INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Yıldızları', 'deniz-yildizlari-semra-dereli-1aak6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toplamaya başladım

Sahil boyunca 

Deniz yıldızlarını.

Topladığım her deniz yıldızı

Dalgalarında savurduğun

Umutlarımdı.', 'Toplamaya başladım Sahil boyunca  Deniz yıldızlarını. Topladığım her deniz yıldızı Dalgalarında savurduğun Umutlarımdı....', ARRAY['Türk Edebiyatı','Şiir','Semra Dereli']::text[], 8.5, '{"poet":"Semra Dereli","poet_slug":"semra-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/deniz-yildizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçan Sevda', 'kacan-sevda-semra-dereli-w5qoj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldırımlar düşürürdüm yüreğine

İsteseydin...

Sevdalardan taçlar takardım saçlarına

Dileseydin...

Yıldızları alıp ellerime; bırakırdım

Yıldızlardan beyaz tenine...

Gitmeseydin, bana bir an görünüp

Yabancı ellere...', 'Yıldırımlar düşürürdüm yüreğine İsteseydin... Sevdalardan taçlar takardım saçlarına Dileseydin... Yıldızları alıp ellerime; bırakırdım Yıldı...', ARRAY['Türk Edebiyatı','Şiir','Semra Dereli']::text[], 8.5, '{"poet":"Semra Dereli","poet_slug":"semra-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kacan-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktan Uzak Dur', 'asktan-uzak-dur-selfet-yilmaz-ws8il', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Müsteri acisindan bakildiginda

Ask cok düsündürücü

ne Son Kullanim Tarihi var

nede bir Garantisi

nede Yan etkileriyle ilgili bir aciklama

nede tespiti mümkün olmayan

Fiyat-Ddger karsiligi

ne kalite Kriterleri

ne geri teslim -nede degistirme hakki

ne Sigortalama olanagi

Ona göre hareket et

Yani ASKA uzatma elini

Aski Satin almaya kalkma', 'Müsteri acisindan bakildiginda Ask cok düsündürücü ne Son Kullanim Tarihi var nede bir Garantisi nede Yan etkileriyle ilgili bir aciklama ne...', ARRAY['Türk Edebiyatı','Şiir','Selfet Yılmaz']::text[], 8.5, '{"poet":"Selfet Yılmaz","poet_slug":"selfet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asktan-uzak-dur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saati Yok Eremi Yok', 'saati-yok-eremi-yok-abdurrahim-karakoc-99jrm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşktan yana söz duyunca,

Ben hep seni düşünürüm.

Uçsuz hayaller boyunca,

Ben hep seni düşünürüm.

Yıldızlar kayar yüceden; 

Renkler sıyrılır geceden; 

Yüreğim sızlar inceden; 

Ben hep seni düşünürüm.

Aklın ucu değer hiçe; 

Yol ararım içten içe.

Kâinat uyur sessizce,

Ben hep seni düşünürüm.

Korkunun bittiği yerde,

Haz duyarım perde perde.

Bir mezar görsem bir yerde,

Ben hep seni düşünürüm.

Zaman hep sonsuza akar

Meyve dökülür, dal kalkar.

Çiçeklere bakar bakar,

Ben hep seni düşünürüm.

Rüzgâr eser ilden ile

Sağlıkta bitmez bu çile.

Vardan öte, Yokta bile

Ben hep seni düşünürüm.

(Dosta Doğru)', 'Aşktan yana söz duyunca, Ben hep seni düşünürüm. Uçsuz hayaller boyunca, Ben hep seni düşünürüm. Yıldızlar kayar yüceden;  Renkler sıyrılır ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-hep-seni-dusunurum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum Yokuşu', 'yoruldum-yokusu-hidir-toraman-ubleb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülerek öleceğim günlere ermek için

mutlu ilan etmek için kalbimi yenibaştan

yenibaştan düşlerimi zamana sunuyorum

Ömrümüzü, fazladan bir günmüş gibi yaşamak

çıplak etin cüretiyle yaşamak sevdiceğim

yaşamak, hangi nehrin tekrara gelmez akışı? 

Hangi nehrin akışı teselli eyler bizi

şimdi kimin derdidir kim bilir yağan yağmur

kim bilir bu ölümlü kalbimizin kaçıncı sevişmesi

Kaç zamandır tez dönerim cevapları veriyorum dünyaya

bilmiyorum hangi aşkın şiddeti alıkoymuş aklımı

kalbim, kaç bin cevaplı sualin karşısında

kaç onulmaz yaranın dermanı bende kalmış

Görülmemiş rüyaların şahidiyim nicedir

nicedir yıldızlarla meşgul gözlerim

yeşil suyu süzülmüş yapraklarla bir

daldan düşen gül sesleri geliyor düşlerimden

düşlerimden geliyor ebedi yalnızlığım

Göğe ermiş dalların yalnızlığı var bende

bende gönlünü bilmez bir ermişlik var

bir çocukluk itirazı kalmıştır yüreğimde

ölüme bir güzellik katmamış gözyaşlarım

hiç kimse gözyaşlarımı hak etmemiştir

Hiç kimse gözyaşlarını hak etmemiştir

bundandır düşlerimiz göklerle meşgul

bunun için boynumuzun yağmurda kanaması

boş göllerin mavisiyle övünmemiz bundandır

Orda hüzün saflarını aralayan çocuklar

arşa revan dallarda kuş sesleri ararken

her metalin külüne yer verdik içimizde

görmedik köküne kötülük sinmiş karanfilleri

gecelerin adamıydı günlerin kahramanı

görmedik parmak boğumları kesik avcılar

beton balık heykelleri ararmış denizlerde

denizin parlattığı kibar yerliler

ılgınlar,aylaklar,kemik zıpkınlar

zağarlar,sazdamlar,yağlı tohumlar

ayazda parlayan demir çapaklar

görmedik altın damarları parıldarken şiirin

yeraltı odalarına sinmiş karaltıları

Oysaki hikayemiz baştan belli sevdiğim

yolların yetmezliğinden söz etmemiz bahane

beyhude sürgün halkın aşkını yaşatma gayretimiz

kimbilir kaç bin körün şaşkınlığı var bizde

kimbilir kaç bin sağır sürgünün aymazlığı var artık

kim gecenin adamıdır kim günün kahramanı

öyle aşkın saflarından çekilmiş müminleriz

öyle kendi yüzlerine hasret gitmiş sürgünler

Göçüyor ateşten sözlerle ördüğümüz kuleler

göçüyor yeni yeni kar tutmaya başlamış yollarımız

yollarımız yürünmeye değer mi bilmem artık

artık bilmem bu dünyadan kendi payıma

gülerek öleceğim bir ölüm düşecek mi

mutlu ilan edecek mi kalbimi kardeşlerim

sabahın seherinde puslu bir dağ başında

bir dostun mezarı hazırlanırken!', 'Gülerek öleceğim günlere ermek için mutlu ilan etmek için kalbimi yenibaştan yenibaştan düşlerimi zamana sunuyorum Ömrümüzü, fazladan bir gü...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Toraman']::text[], 8.5, '{"poet":"Hıdır Toraman","poet_slug":"hidir-toraman","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/yoruldum-yokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Basamak', 'basamak-nurten-altinok-ommx9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu saatlerden nefret ediyorum

Duygu yüklü bulutların

Başıma kangren yağdığı

Şairliğim dört nala yılkı atı

Beynimde eğreti bir bağ

Bir koptu mu 

Kıyamet kopacak! 

Şakaklarımdaki basınç 

Yüreğime eğriliyor

Yüreğim küskün

Dost bakışlara

Yüreğim kırgın 

Dostları basamak yapanlara

Kırgınım

Dost diye bağlandıklarıma

Bu saatlerden nefret ediyorum

İhanet yağıyor

Korkuyorum 

Korkuyorum 

Korkuyorum', 'Bu saatlerden nefret ediyorum Duygu yüklü bulutların Başıma kangren yağdığı Şairliğim dört nala yılkı atı Beynimde eğreti bir bağ Bir koptu ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/basamak-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Taç', 'tac-nurten-altinok-d39rk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kudurmuş hınzır duygulardan

Hasretin son damlasından

Sevginin doruğundan

Bir ben yaptım sana armağan

Şiirlerle süsleyip

Şarkılarla şenlendim

Çılgın benliğimi yüklenip

Sana sunmaya geldim', 'Kudurmuş hınzır duygulardan Hasretin son damlasından Sevginin doruğundan Bir ben yaptım sana armağan Şiirlerle süsleyip Şarkılarla şenlendim...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tac-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '****Bu Gün Güzel Olmalıyım', 'bu-gun-guzel-olmaliyim-nurten-altinok-54tna', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gün güzel olmalıyım

süslenip püslenmeliyim 

Gözlerinde  ben olmalıyım

Çiçek açmalı tenim 

Ellerinde bir ürperti

Bu gün güzel olmalıyım 

Seni sevdiğimi söylerken', 'Bu gün güzel olmalıyım süslenip püslenmeliyim  Gözlerinde  ben olmalıyım Çiçek açmalı tenim  Ellerinde bir ürperti Bu gün güzel olmalıyım  S...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-gun-guzel-olmaliyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şüphe', 'suphe-nurten-altinok-h0ioq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece uyuyamazsın

İçinde ben olacağım kemirgen

Karabasan çiçeklerimle kirpiklerinde gezerken

Parmaklarında dolama olacağım

Kollarım belinde zona 

Bu gece uyuyamazsın

Boşuna kendini zorlama', 'Bu gece uyuyamazsın İçinde ben olacağım kemirgen Karabasan çiçeklerimle kirpiklerinde gezerken Parmaklarında dolama olacağım Kollarım belind...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/suphe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Canım Desen', 'canim-desen-nurten-altinok-betfw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çalsan gönül kapımı

canım  desen 

......................canım

bozbulanık sularda 

.........kanatlı balık olurum 

çorak topraklarında 

................yayla esintisi

bir avuç suda okyanus

martılar yok ki benim memleketimde

kanat kanat bulutlanamam 

güvercin gagasında bir yeşil zeytin dalı

olsam olsam

kırpıp  kırpıp yolları

gözlerine sersem yıldızlardan bir halı

uzaklar erir mi bilemem

daha da mı büyür yangınım

saçlarımda tel tel özlemlerin tutuşur 

kirpiklerimde  bir bestenin ilk notası

çalsan gönül kapımı

canım  desen 

......................canım

parmak uçlarımda göğe uçarım

çatlatıp bulutların ar damarını

dudaklarına konarım', 'çalsan gönül kapımı canım  desen  ......................canım bozbulanık sularda  .........kanatlı balık olurum  çorak topraklarında  .........', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/canim-desen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Armağanı', 'coban-armagani-nail-abbas-sayar-ot5m2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk havalarda

Geliverince aklıma

Üşürsün diye

Seni düşünmüyorum.', 'Soğuk havalarda Geliverince aklıma Üşürsün diye Seni düşünmüyorum....', ARRAY['Türk Edebiyatı','Şiir','Nail Abbas Sayar']::text[], 8.5, '{"poet":"Nail Abbas Sayar","poet_slug":"nail-abbas-sayar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/coban-armagani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Bitti', 'bitti-nurten-altinok-09yoj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bitti 

Virgülleri sıraladım da hep peşi sıra aşkların

Yeni umutlarda 

Yeni pembelerdeydim

Seslerde çoğaldım

Parmaklarda büyülendim 

Bir çift göze kilitlendim

Bitti 

İçimdeki sevgilere sehpa kurdum 

Haydi gelin

İdamı var yüreğimin

İlk tekmeyi kim vuracak', 'Bitti  Virgülleri sıraladım da hep peşi sıra aşkların Yeni umutlarda  Yeni pembelerdeydim Seslerde çoğaldım Parmaklarda büyülendim  Bir çift...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bitti-227-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Seni Sevmekten Korkuyorum', 'seni-sevmekten-korkuyorum-nurten-altinok-oh6pv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelme! 

Alışırım ellerinde yanmaya

Yapamam

Alışırım gözlerinde bakmaya 

 Kaçamam

Alışırım sevginde çoğalmaya 

 Ayrılamam

Seni ben, sensiz yaşamaya

Dayanamam

Gelme! 

Seni sevmekten korkuyorum

İçimdeki benden korkuyorum

Gelme! 

Her alışkanlık bir bıçak oluyor yüreğimde

Çentik çentik yontulduğum ayrılıklarda 

Parmak uçlarımda kanatlarım kırılıyor da

Her ayrılıkta katran karası oluyorum

Her ayrılıkta baştan baştan kara sevda

Gelme! 

Seni sevmekten korkuyorum

İçimdeki benden korkuyorum

Dansa gücüm kalmadı....', 'Gelme!  Alışırım ellerinde yanmaya Yapamam Alışırım gözlerinde bakmaya   Kaçamam Alışırım sevginde çoğalmaya   Ayrılamam Seni ben, sensiz ya...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-sevmekten-korkuyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sevgi Yaşanmalı', 'sevgi-yasanmali-nurten-altinok-l3s1f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', ''''' Uzaklarda aramam çünkü sen içimdesin''

Şarkılar yalan söylüyor... inanma,

Şarkılar eksik... kanma 

Sözlerin tadı tuzu kalmamış... aldanma

Bence,

Bire bir yaşanmalı sevgi

Bire bir...

El ele, göz göze, diz dize... 

Tutabilmelisin ellerini kör güğüm

Bakabilmelisin gözlerine düğüm düğüm 

Sarılabilmelisin ölüm ölüm

Sevişebilmelisin gülüm

Yağmurun toprağa düştüğü ilk damla gibi

Geceler karanlığından utanmalı

Şarkılar yalnızlığından

Sessizlik çiçek açmalı nefes nefes

Saatler çıkarken çığrından

Secdeye durmalı kutsallığınca zaman

Sevgiye boyun eğmeli mutluluktan

Bence,

Bire bir yaşanmalı sevgi

Bire bir

Gözgöze, dizdize, elele...', ''''' Uzaklarda aramam çünkü sen içimdesin'' Şarkılar yalan söylüyor... inanma, Şarkılar eksik... kanma  Sözlerin tadı tuzu kalmamış... aldanma ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevgi-yasanmali-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai', 'rubai-nail-abbas-sayar-gjzo1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ocaklar yansın her dem

Bacada is olmasın.

Gökyüzü mavi kalsın

Ufukta sis olmasın.

Kötülük yansın yıkılsın

Lale gül kesilsin dünya

Herşeyde terhis olsun

Aşkta terhis olmasın...', 'Ocaklar yansın her dem Bacada is olmasın. Gökyüzü mavi kalsın Ufukta sis olmasın. Kötülük yansın yıkılsın Lale gül kesilsin dünya Herşeyde t...', ARRAY['Türk Edebiyatı','Şiir','Nail Abbas Sayar']::text[], 8.5, '{"poet":"Nail Abbas Sayar","poet_slug":"nail-abbas-sayar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/rubai-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Mühür', 'muhur-nurten-altinok-gptje', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşım

Yıllara

Başım

Bana

Kalemim

Kağıda

Yüreğim

Sana

Mühür', 'Yaşım Yıllara Başım Bana Kalemim Kağıda Yüreğim Sana Mühür...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/muhur-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Çivi', 'civi-nurten-altinok-jhy96', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çivi çiviyi söker dedik

sevmeyi bir daha denedik

her şeyi  göze alıp

sevgiliye şarkılar söyledik 

yine uzadı ayrılıkta zaman 

yine yollar girdi araya 

yine gözlere kurbanlar adadık 

yine sözlere mevlütler okuttuk 

en güzel duyguları işledik de inci inci 

bir yürekte sunduk yare ömür gibi

gün geldi 

uçtuk

kumrulara nispet

gün geldi

bataklarda oynadık 

yine uykusuz kaldık 

yine  bittik 

kimi umutlandık

kimi sevindik

çivi çiviyi söker dedik

sevmeyi bir daha denedik

ne çiviymiş be

hala sökemedik', 'çivi çiviyi söker dedik sevmeyi bir daha denedik her şeyi  göze alıp sevgiliye şarkılar söyledik  yine uzadı ayrılıkta zaman  yine yollar gi...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/civi-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Çözemedim', 'cozemedim-nurten-altinok-xgpjz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çözemedim

Çözemiyorum

Hiç iyi şeyler geçmiyor aklımdan

Bir yerde bir hata var ya 

          Bilemiyorum 

                      Bulamıyorum', 'Çözemedim Çözemiyorum Hiç iyi şeyler geçmiyor aklımdan Bir yerde bir hata var ya            Bilemiyorum                        Bulamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cozemedim-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Çok Şey mi İstedim', 'cok-sey-mi-i-stedim-nurten-altinok-c6da7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok şey mi istedim

Alıştırmasaydın

Kabahat sende

Suç bende', 'Çok şey mi istedim Alıştırmasaydın Kabahat sende Suç bende...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cok-sey-mi-istedim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Son Olsun', 'son-olsun-nurten-altinok-vwmeu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tövbeler tövbesi

Yemin edeceğim 

Bir daha kimseyi sevmeyeceğim

Peki ama 

O zaman 

Kimi özleyeceğim', 'Tövbeler tövbesi Yemin edeceğim  Bir daha kimseyi sevmeyeceğim Peki ama  O zaman  Kimi özleyeceğim...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/son-olsun-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-gokhan-demir-qs2c0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben de severim dünyadaki iyi kalpli insanları, 

Anamı, babamı,arkadaşlarımı severim ben

Özelikle de bir arkadaşımı 

Yani sevgilimi yanı aşkımı', 'Ben de severim dünyadaki iyi kalpli insanları,  Anamı, babamı,arkadaşlarımı severim ben Özelikle de bir arkadaşımı  Yani sevgilimi yanı aşkı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Demir']::text[], 8.5, '{"poet":"Gökhan Demir","poet_slug":"gokhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seviyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular', 'sorular-bertolt-brecht-yvki8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne giydiğini yaz bana!

Sıcak tutuyor mu? 

Nasıl uyuduğunu yaz bana!

Yatağın yumuşak mı? 

Nasıl göründüğünü yaz bana! 

Hep aynı mısın? 

Neyi özlediğini yaz bana! 

Kolumu mu? 

Nasılsın, yaz bana! 

Hoş tutuyorlar mı seni? 

Ne bok yiyorlar, yaz bana! 

Cesaretin yetiyor mu? 

Ne yaptığını yaz bana! 

Yaptığın şey iyi mi? 

Neyi düşündüğünü yaz bana! 

Beni mi? 

Elbette sorulardır

sana bütün verebildiğim.

Ve gelen yanıtları kabullenmeliyim,

mecburum buna. 

Yorgunsan, uzatamam sana elimi. 

Ya da açsan, seni besleyemem. 

Sanki yaşamamışım bu dünyada,

hiç yokmuşum. 

Unutmuşum sanki seni.', 'Ne giydiğini yaz bana! Sıcak tutuyor mu?  Nasıl uyuduğunu yaz bana! Yatağın yumuşak mı?  Nasıl göründüğünü yaz bana!  Hep aynı mısın?  Neyi ...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sorular-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıldı', 'nasildi-bertolt-brecht-671fp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-I-

Önce sevinç uyutmadı beni

Sonra üzüntü nöbet tuttu bütün gece.

İkisi de gidince başımdan

Uyudum, ama ah, her Mayıs gecesi

Bir kasım sabahı getirdi ardından.

            -II-

Senin derdin benimdi

Benimki senin

Paylaşamazsam bir sevinci seninle

Yoktu benim de sevincim', '-I- Önce sevinç uyutmadı beni Sonra üzüntü nöbet tuttu bütün gece. İkisi de gidince başımdan Uyudum, ama ah, her Mayıs gecesi Bir kasım saba...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nasildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dersi', 'ask-dersi-bertolt-brecht-43930', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ama kızım, diyorum ki

Biraz istekli olsun sesin:

Ete bürünürse severim ruhu

Ve eti ruh doluysa severim

Azaltamaz masumluk coşkuyu asla

Hem daha güzel doyar insan açken.

Severim erdemin arkası varsa

Ve erdemliyse bir arka.

Tanrı kuğuya bindiğinden beri

Fena olur bazı kızların içi

Zevkle katlansalar da acıya:

Duymak ister Tanrı kuğunun türküsünü', 'Ama kızım, diyorum ki Biraz istekli olsun sesin: Ete bürünürse severim ruhu Ve eti ruh doluysa severim Azaltamaz masumluk coşkuyu asla Hem d...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-dersi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maskulunizma', 'maskulunizma-can-yucel-xwa1g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamak ne güç şeymiş

Kadınlar öğrettiler bana

Başta anam

Hamamda kaynar sular dökerek başımdan... 

Onlar uyandırdılar beni çocukluktan

Erkek olup ......... çıkayım diye. 

Bu öyle bir esatir ki

Hem yesir tuccarı olacaksın, hem yesir... 

Ve vücutlarının akkağıtlarına yazdığım o şiir değil, 

met-cezir... 

Kadınlar doğurdular beni bağıra bağıra

Yine onlar öldürecekler beni aşktan

Bağırta bağırta...', 'Yaşamak ne güç şeymiş Kadınlar öğrettiler bana Başta anam Hamamda kaynar sular dökerek başımdan...  Onlar uyandırdılar beni çocukluktan Erke...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/maskulunizma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazmam Daha Aşk Şiiri', 'yazmam-daha-ask-siiri-cemal-sureya-rc212', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oydu bir bakışta  tanıdım onu

Kuşlar bakımından uçarı

Çocuk tutumuyla beklenmedik

Uzatmış ay aydınlık karanlığıma

Nerden uzatmışsa tenha boynunu

Dünyanın en güzel kadını oydu
..........
..........', 'Oydu bir bakışta  tanıdım onu Kuşlar bakımından uçarı Çocuk tutumuyla beklenmedik Uzatmış ay aydınlık karanlığıma Nerden uzatmışsa tenha boy...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yazmam-daha-ask-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın', 'anlarsin-cahit-kulebi-m8wk1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece habersiz bize gel 

Merdivenler gıcırdamasın 

Öyle yorgunum ki hiç sorma 

Sen halimden anlarsın 

Sabahlara kadar oturup konuşalım 

Kimse duymasın 

Mavi bir gökyüzümüz olsun 

Kanatlarımız dokunarak uçalım 

İnsanlardan buz gibi soğudum 

İşte yalnız sen varsın 

Öyle halsizim ki hiç sorma 

Anlarsın', 'Bir gece habersiz bize gel  Merdivenler gıcırdamasın  Öyle yorgunum ki hiç sorma  Sen halimden anlarsın  Sabahlara kadar oturup konuşalım  K...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi']::text[], 8.5, '{"poet":"Cahit Külebi","poet_slug":"cahit-kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlarsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelleme', 'guzelleme-cahit-kulebi-tjaly', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evinizin önünde dolaşsam

Seni bulamazdım,

Sen gözlerinde bahçeler olan

Şimdi evimdeki karım.

Senin kadar güzel olsun çocuklarım

Gökyüzü bugün ne kadar da çok

Yıldızlarla dolu avuçların', 'Evinizin önünde dolaşsam Seni bulamazdım, Sen gözlerinde bahçeler olan Şimdi evimdeki karım. Senin kadar güzel olsun çocuklarım Gökyüzü bugü...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi']::text[], 8.5, '{"poet":"Cahit Külebi","poet_slug":"cahit-kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/guzelleme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Gelin', 'yeni-gelin-cahit-kulebi-89xz7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin ellerini

Öpmeye kıyamam

Senin yüzüne

Bakmaya kıyamam

Neden kızarıyorsun yeni gelin

Sokakta rastladığım zaman?', 'Senin ellerini Öpmeye kıyamam Senin yüzüne Bakmaya kıyamam Neden kızarıyorsun yeni gelin Sokakta rastladığım zaman?...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi']::text[], 8.5, '{"poet":"Cahit Külebi","poet_slug":"cahit-kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yeni-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gecemi bu Uykusuzluk', 'her-gecemi-bu-uykusuzluk-cahit-sitki-taranci-yne1y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her gece mi bu uykusuzluk!

Hele saatin tıkırtısı! 

Ya karasinek düşünceler! 

Çıldıracağım bu gidişle; 

Yatak değil sanki cehennem. 

Deliksiz bir uykuysa vaadin, 

Günün dolmuş veya dolmamış, 

Gençliğime filan bakmadan, 

Derhal gelebilirsin ölüm; 

Kapı açıktır, lamba sönük.', 'Her gece mi bu uykusuzluk! Hele saatin tıkırtısı!  Ya karasinek düşünceler!  Çıldıracağım bu gidişle;  Yatak değil sanki cehennem.  Deliksiz...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/her-gecemi-bu-uykusuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Ne Yaptın ?', 'anne-ne-yaptin-cahit-sitki-taranci-z9c0n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anne sana kim dedi yavrunu doğurmayı?

Sanki karnında fazla yaramazlık mı ettim? 

Senden istemiyordum ne tacı ne sarayı

Karnında yaşıyordum kafiydi saadetim. 

Bir kere doğurdunsa sonra niçin büyüttün? 

Kundakta beşikte de bir zahmetim mi vardı? 

Koynundan niçin attın yavrunu bütün bütün. 

Bilmiyor muydun ki o yalnızlıktan korkardı? 

Sütünden tatlı mıdır anne sanki bu hayat? 

Bana sorsana anne yaşamak bir hüner mi? 

El aç yalvar gündüze geceye boyun uzat

Bu uğurda bir ömür çürütmeye değer mi? 

Karnında yaşıyordum kafiydi saadetim

Anne istemiyordum ne tacı ne sarayı

Anne karnında fazla yaramazlık mı ettim? 

Anne sana kim dedi yavrunu doğurmayı?', 'Anne sana kim dedi yavrunu doğurmayı? Sanki karnında fazla yaramazlık mı ettim?  Senden istemiyordum ne tacı ne sarayı Karnında yaşıyordum k...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anne-ne-yaptin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paydos', 'paydos-cahit-sitki-taranci-fqk8f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Paydos bundan böyle  çılgınlıklara!

Sert konuşmaya başladı aynalar,

Yetişir koştum aşkın peşi sıra;

Bitirdi beni bu içki, bu kumar. 

Ne saklayayım gaflet ettiğimi,

Elimle batırmışım gençliğimi;

Binip gideceğim en güzel gemi!

Aldığını geri vermez dalgalar. 

Meyhaneler, sabahçı kahveleri,

Cümle eş dost, şair, ressam serseri,

Artık cümbüşte yoksam geceleri

Sanmayın tarafımdan hıyanet var. 

Yaş ilerliyor... Artık geçti bizden;

Kişi ev bark edinmeli vakitken.

Gün gelince biz değil miyiz ölen?

Cenazemiz yerde kalmasın dostlar!', 'Paydos bundan böyle  çılgınlıklara! Sert konuşmaya başladı aynalar, Yetişir koştum aşkın peşi sıra; Bitirdi beni bu içki, bu kumar.  Ne sakl...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/paydos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıkların Ölümü', 'asiklarin-olumu-charles-baudelaire-62l52', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yatağımız olacak ,hafif kokuyla dolu, 

Divanımız olacak ,bir mezar gibi derin; 

Bizim için açılmış, en güzel iklimlerin 

O garip çiçekleri süsleyecek konsolu. 

Son sıcaklıklarını sarfederek hovarda, 

Birer ulu meşale olacak kalplerimiz; 

Çifte ışıklarından gidip gelecek bir iz 

İkimizin ruhunda, o ikiz aynalarda. 

Pembe, lahuti mavi bir akşam saatinde, 

Veda''la dolu, uzun bir hıçkırık halinde 

Yanacak aramızda bir tek şimşeğin feri; 

Nihayet kapıları biraz aralayarak, 

Sadık ve şen bir melek gelip uyandıracak 

Buğulu aynaları ve ölmüş alevleri', 'Yatağımız olacak ,hafif kokuyla dolu,  Divanımız olacak ,bir mezar gibi derin;  Bizim için açılmış, en güzel iklimlerin  O garip çiçekleri s...', ARRAY['Türk Edebiyatı','Şiir','Charles Baudelaire']::text[], 8.5, '{"poet":"Charles Baudelaire","poet_slug":"charles-baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/asiklarin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balkon', 'balkon-charles-baudelaire-s6a34', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatıralar annesi, 

sevgililer sultanı, 

Ey beni şadeden yar, 

ey tapındığım kadın. 

Ocak başında seviştiğimiz 

o zamanı, 

O canım akşamları 

elbette hatırlarsın. 

 Hatıralar annesi, 

sevgililer sultanı. 

O akşamlar 

kömür aleviyle aydınlanan! 

Ya pembe buğulu akşamlar, 

balkonda geçen 

Başım göğsünde, 

ne severdin beni o zaman! 

Ne güzeldir güneşler 

sıcak yaz akşamları! 

Kainat ne derindir, 

kalp ne kudretle çarpar! 

Üstüne eğilirken 

ey aşkımın pınarı, 

Sanırdım ciğerimde 

kanının kokusu var. 

Ne güzeldir güneşler 

sıcak yaz akşamları! 

Kalınlaşan bir duvardı 

aramızda gece. 

Seçerdim o karanlıkta 

göz bebeklerini 

Mestolur, 

mahfolurdum nefesini içtikçe. 

Bulmuştu ayakların 

ellerimde yerini. 

Kalınlaşan bir duvardı 

aramızda gece. 

Bana vergi

o tatlı demleri hatırlamak; 

Yeniden yaşadığım, 

dizlerinin dibinde 

O ''mestinaz'' güzelliğini 

boştur aramak, 

Sevgili vücudundan, 

kalbinden başka yerde, 

Bana vergi 

o tatlı demleri hatırlamak; 

O yeminler, kokular 

sonu gelmez öpüşler, 

Dipsiz bir uçurumdan 

tekrar doğacak mıdır? 

Nasıl yükselirse göğe 

taptaze güneşler. 

Güneşler ki 

en derin denizlerde yıkanır. 

O yeminler, kokular, 

sonu gelmez öpüşler!', 'Hatıralar annesi,  sevgililer sultanı,  Ey beni şadeden yar,  ey tapındığım kadın.  Ocak başında seviştiğimiz  o zamanı,  O canım akşamları ...', ARRAY['Türk Edebiyatı','Şiir','Charles Baudelaire']::text[], 8.5, '{"poet":"Charles Baudelaire","poet_slug":"charles-baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/balkon-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dev Kadın', 'dev-kadin-charles-baudelaire-3l2cu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğa''nın o güçlü ve yaratıcı özünden 

Her gün azman çocuklar boy gösteren çağında, 

Dev bir kadın yayında yaşamak isterdim ben, 

Kösnük bir kedi gibi bir sultan ayağında. 

İsterdim o canla tenin açtığını görmek, 

Geliştiğini ürkünç oyunlarla başıboş; 

Gözlerinde yüzen ıslak sislerde o yürek 

Bilmek isterdim içten bir alev saklar mı, loş; 

Görkemli bedeninde dolaşmak döne döne, 

dev gibi dizlerinin tırmanmak eğilimine, 

Ve dokunan güneşler yazır, sıcak mı sıcak, 

Serdiği zaman onu kırlara yorgun argın, 

atıp göğüslerinin gölgesinde uyumak 

Erinçli bir köy gibi eteğinde bir dağın. 

Tek isteğim şimdi, bir gece 

ulaştık mı zevk saatına, 

Vücudunun saltanatına 

Doğru tırmanmak sinsice, 

Bir yara açıp geniş, derin 

O şaşırakalmış böğrüne, 

Acı vermek için göğsüne, 

Şen tenini incitmek için, 

Ve, ne  estiren tat, değil mi, 

Yavrum! o en güzel, en parlak 

Yeni dudaklardan akıtmak, 

Aşılamak sana zehrimi!', 'Doğa''nın o güçlü ve yaratıcı özünden  Her gün azman çocuklar boy gösteren çağında,  Dev bir kadın yayında yaşamak isterdim ben,  Kösnük bir ...', ARRAY['Türk Edebiyatı','Şiir','Charles Baudelaire']::text[], 8.5, '{"poet":"Charles Baudelaire","poet_slug":"charles-baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dev-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Jane İçin', 'jane-i-cin-charles-bukowski-q8vwg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çimen altında geçen 225 günden sonra

benden daha çok şey biliyor olmalısın.

kanını emip bitireli epey oldu,

artık bir sepette kuru bir çubuksun.

bu işler böyle mi oluyor?

bu odada

aşk saatlerinin

hala gölgeleri var.

bırakıp gittiğinde

aşağı yukarı herşeyi

alıp gittin.

geceleri beni ben olmaya

koymayan kaplanların önünde

diz çöküyorum.

senin sen olman

asla bir daha olmayacak.

kaplanlar beni buldular

ama artık umrumda bile değil.', 'çimen altında geçen 225 günden sonra benden daha çok şey biliyor olmalısın. kanını emip bitireli epey oldu, artık bir sepette kuru bir çubuk...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/jane-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaplan', 'kaplan-charles-bukowski-29cn9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'berbat kavgalar.

ve sonunda,

kadının güzel çiçek desenli kocaman yatağında

huzur içinde uzanmışım,

göbeğim sereserpe başım yanda

abajurun ışığı damla damla

kadın öbür odada

yıkanıyor,

çoğu şey gibi,

bütün bunlar benden uzakta,

küçük radyodan klasik müzik dinliyorum,

kadın yıkanıyor, suyun şırıltısını duyuyorum.', 'berbat kavgalar. ve sonunda, kadının güzel çiçek desenli kocaman yatağında huzur içinde uzanmışım, göbeğim sereserpe başım yanda abajurun ış...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaplan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına', 'i-nadina-cahit-irgat-qa0q8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnadınamı güzelsin

Akşamüstleri,

Demir parmaklıktan gördüğüm deniz?

İnadına mı fiyakan

Yan yan gidişin

Tombul kıçlı gemi?', 'İnadınamı güzelsin Akşamüstleri, Demir parmaklıktan gördüğüm deniz? İnadına mı fiyakan Yan yan gidişin Tombul kıçlı gemi?...', ARRAY['Türk Edebiyatı','Şiir','Cahit Irgat']::text[], 8.5, '{"poet":"Cahit Irgat","poet_slug":"cahit-irgat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/inadina-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perişan', 'perisan-cahit-irgat-wpv1r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinde deniz, gözlerinde gemi

Gözlerinde çırılçıplak çocuklar

Rüzgar esiyor rüzgar, meltemdir

Güzel dünya üzerinde matemdir

Kalbimizin üç köşesi yangın yeri, perişan

Güzel şehir diri diri perişan

Güzel yağmur, çirkin olur yoksul gözünde

İsyan değil, arzudur, şimşek şimşek parlayan

Konuş toprak, konuş meydan

İnsanoğlu her gün daha perişan.', 'Gözlerinde deniz, gözlerinde gemi Gözlerinde çırılçıplak çocuklar Rüzgar esiyor rüzgar, meltemdir Güzel dünya üzerinde matemdir Kalbimizin ü...', ARRAY['Türk Edebiyatı','Şiir','Cahit Irgat']::text[], 8.5, '{"poet":"Cahit Irgat","poet_slug":"cahit-irgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/perisan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düşün İçinde Düş', 'bir-dusun-i-cinde-dus-edgar-allan-poe-o1o5r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Alnına konsun bu öpüş

Ve,şimdi senden ayrılırken,

İtiraf edeyim ki

Günlerimi bir düş

Sayarken yanılmıyorsun; 

Ama, umut gitmişse uzaklara

Bir gece ya da bir gün

Bir görüntüde ya da bir şeyde olmaksızın

Fark eder mi bu yüzden? 

Bütün gördüğümüz ve göründüğümüz

Yalnızca bir düşün içinde bir düş.

Kırılan dalgaların dövdüğü bir kıyının

Haykırışları içinde duruyorum:

Ve altın kum taneleri tutuyorum avucumda

Ne kadar az! Ama nasıl da

Süzülüyorlar parmaklarımın arasından derinlere

Ben ağlarken, ben ağlarken! 

Ah Tanrım! Daha sıkı

Tutamaz mıyım onları? 

Ah Tanrım! Tekini bile kurtaramaz mıyım acımasız dalgadan? 

Bir düşün içinde bir düş mü

Bütün gördüğümüz ve göründüğümüz?', 'Alnına konsun bu öpüş Ve,şimdi senden ayrılırken, İtiraf edeyim ki Günlerimi bir düş Sayarken yanılmıyorsun;  Ama, umut gitmişse uzaklara Bi...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-dusun-icinde-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...''E', 'e-edgar-allan-poe-2u5cd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aldırmıyorum, bu dünyada payımın

-DÜNYADAN AZ BİR HİSSEYLE- 

aşk yılları olmasına unutulan

               bir dakikanın nefretinde.

 ağlamıyorum terkedilmişler güzelim

               BENDEN mutludur diye

ama sen üzülüyorsun diye...

kaderime bir yolcu olan benim!.', 'aldırmıyorum, bu dünyada payımın -DÜNYADAN AZ BİR HİSSEYLE-  aşk yılları olmasına unutulan                bir dakikanın nefretinde.  ağlamıy...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Mutlu Gün', 'en-mutlu-gun-edgar-allan-poe-7q2ud', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En mutlu gün en mutlu saat

Kurumuş körelmiş yüreğimin bildiği,

en büyük umutları gücün ve gururun

Hissettiğim, geçip gitti.

Güç mü dedim? Evet öyle düşünmüştüm

Ama yazık! Çoktan yitip gitti hepsi

Gençliğimin hayalleri-

Ama boşver şimdi.

Ya gurur, ne yapacağım senle şimdi

sakin ol ruhum! 

Belki bir diğer baş devralır

Üzerime döktüğün zehri.

En mutlu gün-en mutlu saat

gözlerimin gördüğü göreceği,

En parlak ışıltısı gücün ve gururun

                                    Hissettiğim:

Ama o zaman çektiğim acıyla

Gücün ve gururun umudunu verselerdi,

Yaşamazdım o parlak saati tekrar

Çünkü onun kanatlarındaydı kara alaşım

Ve çırptıkça-bir öz dökülüyordu

Öldürmeye yeterli

Onu bilen bir ruhu.', 'En mutlu gün en mutlu saat Kurumuş körelmiş yüreğimin bildiği, en büyük umutları gücün ve gururun Hissettiğim, geçip gitti. Güç mü dedim? Ev...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/en-mutlu-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-edgar-allan-poe-f5djg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevilmek mi?-öyleyse bırakma yüreğini

Şimdiki yolundan ayrılmaya.

Olduğun herşeyken şimdi,

Olmadığın şey olma.

Böylece kibarlığın, lütfun,

Aşkın güzelliğin, 

sonsuz bir övgü konusu olacak yeryüzünde,

ve aşk-basit bir görev.', 'Sevilmek mi?-öyleyse bırakma yüreğini Şimdiki yolundan ayrılmaya. Olduğun herşeyken şimdi, Olmadığın şey olma. Böylece kibarlığın, lütfun, A...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isimsiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz', 'giz-fang-vei-teh-ej06x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin yanındayken

Bir şeyler akıyor içimden,

Çağlayanlar gibi...

Tutku mu desem, çoşku mu desem.

Eve dönerken

Bir şeyler sönüyor içimde,

Gün batıyormuş gibi

Hüzün mü desem, korku mu desem.', 'Senin yanındayken Bir şeyler akıyor içimden, Çağlayanlar gibi... Tutku mu desem, çoşku mu desem. Eve dönerken Bir şeyler sönüyor içimde, Gün...', ARRAY['Türk Edebiyatı','Şiir','Fang Vei Teh']::text[], 8.5, '{"poet":"Fang Vei Teh","poet_slug":"fang-vei-teh","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/giz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Şiirim', 'benim-siirim-emre-ozdamar-yge64', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hangi kelimeyle anlatılabilir

Renklere sıgmayan bir güneşin

Issız çölleri sarartan şiiri

Acı ki dokunandır

En çok türküsüdür sessiz çıglıkların

Sabahın gökyüzünü gerdigi okyanuslarda

Bir tutam rüzgar ençok martılar için

Ve çıglık çıglıga ellerimden boşanan

Günlerim gelir aklıma

Bu bitmez bu ıssız bu mavi okyanusta

Zaman açılan bir gemidir hüznün ortalarına

Öyleyse bende bırakıyorum kendimi artık

Bırakıyorum

Ne yapacaksa yapsın yalnızlık', 'Hangi kelimeyle anlatılabilir Renklere sıgmayan bir güneşin Issız çölleri sarartan şiiri Acı ki dokunandır En çok türküsüdür sessiz çıglıkla...', ARRAY['Türk Edebiyatı','Şiir','Emre Özdamar']::text[], 8.5, '{"poet":"Emre Özdamar","poet_slug":"emre-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/benim-siirim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorsun', 'biliyorsun-erol-corlu-q4tpv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açıvermedimi sizin oraların erguvanı

hissetmedinmi kokumu

hani salıvermiştim

Egenin imbat rüzgarlarına

biliyorsun.

Islanıvermedimi yanağın

gözyaşlarımla,

hani bırakıvermiştim yağmuruna

sizin oraların

bunuda biliyorsun

Göremedinmi yıldız bakışlarımı

gecelerinde

sizin oraların,

hani göz kırpmıştım

kayarak

bir kuyruklu yıldız ardı

biliyorsun.

duymadınmı hiç sesimi,

bir sığırcık 

yada kırlangıcın

sesinde idim oysa

pencerene konan,

biliyorsun.

kuru kaldı dudaklarım 

öpmedinmi beni hiç,

hani ben 

rüyalarında idim

sevişmedinmi hiç

aşkla

ay ışığımla,

biliyorsun

biliyorsun

ben sizin denizlerin

yakamozlarında idim,

hissetmedinmi

hiç sevdamı.

taşmadımı hala denizleri

sizin oraların

biliyorsun 

ve

susuyorsun.

(17 Nisan 2000)', 'Açıvermedimi sizin oraların erguvanı hissetmedinmi kokumu hani salıvermiştim Egenin imbat rüzgarlarına biliyorsun. Islanıvermedimi yanağın g...', ARRAY['Türk Edebiyatı','Şiir','Erol Çörlü']::text[], 8.5, '{"poet":"Erol Çörlü","poet_slug":"erol-corlu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/biliyorsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendim', 'kendim-muge-usul-5nink', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir evim olsun herkesten uzakta,

Kendim olayım,

Kendime daha yakın...

Bir düşüm olsun avuçlarımda,

Ellerim olsun,

Kalbime yakın...', 'Bir evim olsun herkesten uzakta, Kendim olayım, Kendime daha yakın... Bir düşüm olsun avuçlarımda, Ellerim olsun, Kalbime yakın......', ARRAY['Türk Edebiyatı','Şiir','Müge Usul']::text[], 8.5, '{"poet":"Müge Usul","poet_slug":"muge-usul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kendim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Gülüşlü Harami Çıkar Dağlar Başına', 'mor-guluslu-harami-cikar-daglar-basina-nurullah-genc-amixx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu gelen kainatın en nadide çiçeği

saplanır delikanlı yüreğine absızın

diken yüzlü atlılar takılar da peşine

mor gülüşlü harami çıkar dağlar başına

önünde hafif kumral perdeler dalgalanır

ona düşen kırmızı elmaların çürüğü

yüreğini umutla koyar sabır taşına

mor gülüşlü harami çıkar dağlar başına', 'bu gelen kainatın en nadide çiçeği saplanır delikanlı yüreğine absızın diken yüzlü atlılar takılar da peşine mor gülüşlü harami çıkar dağlar...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mor-guluslu-harami-cikar-daglar-basina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah Diyeceksin Aşkım', 'eyvah-diyeceksin-askim-zekeriya-cavus-t2hpm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O toz pembe hayallerine

Kadeh kadeh içtiklerine

Bir gün kahrederek eyvah

Eyvah diyeceksin aşkım

Bitmek bilmeyen isteklerine

Solan demet demet güllerine

Ah diyerek eyvah

Eyvah diyeceksin bebeğim

Çektiğin çilelere

Akıp geri gelmeyen günlere

Solup boynunu büken güllere

Ah ah eyvah diyeceksin aşkım

Umutsuz peşinde koştuğun aşkına

Değirmen dervan olan hayatına

Şaşkın şaşkın bakarak 

Ağlayıp küseceksin aşkım

Geleceğe umutla bakan gözlerine

Dermanın dumanda sandığın dertlerine

Hiç gelmeyecek olan mutlu geleceğine

Eyvah eyvah diyeceksin bi tanem

Ak düşen saçlarına

Fermansız kalbine çatan kaşlarına

Aşka susamış dudaklarına

Vay canım diyeceksin erkeğim 

Zamana baygın bakışlarına

Durulan azgın duygularına

Heyhat heyhat hayatıma eyvah

Eyvah diyeceksin hayatım.

Uçup giden emellerine

Doyamadığın sevdiklerine

Doyumsuz zevklerine

Özlüyorum sizleri diyeceksin dostum.

Bedbah olan düşüncelerine

Uyamadığın hayat düzenlerine

Acı dolu gülüşlerine

İnsanım insan diyeceksin kardeşim

Güvendiğin dost ellerine

Gönlünü sarsan meşk depremlerine

Engelleri yıkan aşk sellerine

Yeter artık diyeceksin sevgilim

Acıyla geçen gecen gecelerine

Emek verdiğin gündüzlerine

İçini ürpeten şehvetin seslerine

Merhaba merhaba diyeceksin kadınım.

Güller gibi döktüğün zülüflerine

Ferman yazan kirpiklerine

Duygularını dile getiren kalemlerine

İsyan edeceksin meleğim.', 'O toz pembe hayallerine Kadeh kadeh içtiklerine Bir gün kahrederek eyvah Eyvah diyeceksin aşkım Bitmek bilmeyen isteklerine Solan demet deme...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Çavuş']::text[], 8.5, '{"poet":"Zekeriya Çavuş","poet_slug":"zekeriya-cavus","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/eyvah-diyeceksin-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutkunum', 'tutkunum-ender-cetinkaya-y8z9d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutkunum sana istesem de kopamam

Susamışım sana içmeye kanamam

Öyle sevmişim ki seni anlatamam

Güzel gözlerine bakmaya doyamam

Şarkılar yazsam da ömür boyu sana

Anlatamam hislerimi asla sana

Bir gülüşün dünyaları verir bana

Güzel gözlerine bakmaya doyamam', 'Tutkunum sana istesem de kopamam Susamışım sana içmeye kanamam Öyle sevmişim ki seni anlatamam Güzel gözlerine bakmaya doyamam Şarkılar yazs...', ARRAY['Türk Edebiyatı','Şiir','Ender Çetinkaya']::text[], 8.5, '{"poet":"Ender Çetinkaya","poet_slug":"ender-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tutkunum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-ender-cetinkaya-7kebk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşümde gördüm seni

Öyle güzeldin ki

Uyandığıma pişman oldum

Şikayetim yok ama

Sen hep beni pişman et

Her gece gir düşüme

Gündüzlere düşman et', 'Düşümde gördüm seni Öyle güzeldin ki Uyandığıma pişman oldum Şikayetim yok ama Sen hep beni pişman et Her gece gir düşüme Gündüzlere düşman ...', ARRAY['Türk Edebiyatı','Şiir','Ender Çetinkaya']::text[], 8.5, '{"poet":"Ender Çetinkaya","poet_slug":"ender-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dus-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cebeci İstasyonu ve Sen', 'cebeci-i-stasyonu-ve-sen-yavuz-bulent-bakiler-lk3lb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cebeci İstasyonunda bir akşam üstü

İncecikten bir yağmur yağıyordu yollara

Yeni baştan yaşıyorduk kaderimizi

Sıcak bir kara sevda

Yüreğimizin başında bağdaş kurup oturmuştu;

Acımsı, buruk.

mühürlenmişti ağzımız bir sessizlik içinde

Sessizliği üstümüzden atamıyorduk

Bir saçak altında kararsız, yorgun

Saatlerce duruyorduk

Kimse görmüyordu bizi

Cebeci İstasyonunda bir akşam üstü

Yeni baştan yaşıyorduk kaderimizi

Cebeci İstasyonunda bir akşam üstü

Bir başka türlüydü bu insanlar

Sen bir başka türlüydün

Gözlerin yine öyle bir bilinmez renkteydi

Gözlerin gözlerimde erimekteydi

Bir mermer heykel gibi yanımda duruyordun

Beni bırakma diyordun

Meyhane sarhoşları gibi sırılsıklam

Bir yalnızlık duyuyorduk

Ağlıyordun, ağlıyordun...

Cebeci İstasyonunda bir tren

Nefes nefese soluyordu

Gerilmiş bir keman teli gibiydik

Ankara Kalesi''nde bir eski çalar saat

Bilmem kaça vuruyordu

Bir yağmur yağıyor inceden ince

İçimizdeki binbir düşünce

Harmanlar misali savruluyordu

Islanmış bir ceylan yavrusu gibi

Tiril tiril titriyordun

Gitsek gitsek diyordun.

Yüreğimin atışından deli gönlümce

Sırıl sıklam, paramparça, permeperişan

Türküler söylüyordum

Ağlıyordun, ağlıyordun...

Şimdi, şimdi seni düşünüyorum

Cebeci yollarında rüzgarlar esiyor, serin

Paramparça düşmüş gönül ufkuma

İki yıldız gibi gözlerin

Gel Ey ciğerime saplanan hançer

Gel ey yüreğime oturmuş kurşun

Göçmen kuşlar gibi çok uzaklardan

Gel artık

Ne olursun', 'Cebeci İstasyonunda bir akşam üstü İncecikten bir yağmur yağıyordu yollara Yeni baştan yaşıyorduk kaderimizi Sıcak bir kara sevda Yüreğimizi...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/cebeci-istasyonu-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgünler içindesin', 'surgunler-icindesin-riza-aslan-7f804', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sürgünler içindesin

etrafındaki boşluk düşmanın

benliğin, yabancındır artık

savunduğun ideallerin anlamsız

peşinden koştuğun , sen

sana ait değil

Rıza Aslan

02-05-2001', 'sürgünler içindesin etrafındaki boşluk düşmanın benliğin, yabancındır artık savunduğun ideallerin anlamsız peşinden koştuğun , sen sana ait ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/surgunler-icindesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-murat-dogan-2-kf6a2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşin gözlerini yumduğu andı gönlün yine seni andı

Izdırap mı elemmi gözlerin 

Aşk solmuş bir güldü gönül bahçemde 

Korku gülleri büyüttü aşkı

Sen estirdin kural tanımayan sevda rüzgarlarını

Kavrulan çöllere inat bir damla su akıttın kurumuş yaralara

Sakın bakma gözlerinle gözlerime

Gözlerin hayatı sunsa da bana

Sakın bakma gözlerinle gözlerime

Gözlerin güneş saçsada gözlerime

Sakın bakma gözlerinle gözlerime

Gözlerin hiç tanımadığım ürpertidir bana

Sakın bakma gözlerinle gözlerime

Gözlerin gülü hatırlatsada gözlerime

Sakın bakma gözlerinle gözlerime

Gözlerin yüce dağlar aşırtsada bana

Sakın bakma gözlerinle gözlerime

Gözlerin kara gölgelerine denk gecelerin

Gizemine eş derin okyanusların

Gözlerin sırrımı paylaşan 

Sevgi nameleri fısıldayan ormanların

Ah gözlerin gözlerin

Bir zümrüd-ü ankadır beni ülkemden alan

Ah gözlerin gözlerin

Bir haramidir beni benden çalan.

1990', 'Güneşin gözlerini yumduğu andı gönlün yine seni andı Izdırap mı elemmi gözlerin  Aşk solmuş bir güldü gönül bahçemde  Korku gülleri büyüttü ...', ARRAY['Türk Edebiyatı','Şiir','Murat Doğan 2']::text[], 8.5, '{"poet":"Murat Doğan 2","poet_slug":"murat-dogan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gozlerin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-erol-corlu-3cwza', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşünerek uyumanın

masallarından

daha tatlı olduğunu, 

bilmem ki

nasıl anlatacağım !

Dede''me..

(27.11.1984)', 'Seni düşünerek uyumanın masallarından daha tatlı olduğunu,  bilmem ki nasıl anlatacağım ! Dede''me.. (27.11.1984)...', ARRAY['Türk Edebiyatı','Şiir','Erol Çörlü']::text[], 8.5, '{"poet":"Erol Çörlü","poet_slug":"erol-corlu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/masal-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşe Kzın Hikayesi', 'ayse-kzin-hikayesi-erol-corlu-h7s5j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kız evlatsın

Okumak senin neyine dediler

İlk mektepten sonra,

O da zoraki.

Senki çaresiz

Okumak ne olaki.

Ve öğretilmeye başlandı 

törelerin.

ilkin

kapandı şaçın

Oysa neydiki yaşın,

sonra

el öpmeler

yemekler

örgüler

sövgüler vesaire vesaire....

eloğlu 

saçıyla değil Ayşe kızın

uğraşırken uzayla,

tahta toprak karışımı 

bir damla

tarla arasında geçti

Ayşe kızın çocukluğu..

14''ünde ünlendi

Ayşe Kız..

15''inde bellendi.

16''sında Memed''e verdiler

bilmem kaç koyun ederine.

17''sinde döllendi

18''inde Recep kundakta,

19''unda eksik olmadı

yeni sıpa.

20''sinde 

aldılar Memed''i askere,

arada

dölleyip Kezban''ı döndü.

gurbete düştü Memed

ardı sıra teskere.. 

sonra nemi oldu ?

Ayşe kızın kabusu..

30''una gelmeden 

temizlenmiş diye duydum

en büyük oğlan

Recep tarafından

namusu..

(1984)', 'Kız evlatsın Okumak senin neyine dediler İlk mektepten sonra, O da zoraki. Senki çaresiz Okumak ne olaki. Ve öğretilmeye başlandı  törelerin...', ARRAY['Türk Edebiyatı','Şiir','Erol Çörlü']::text[], 8.5, '{"poet":"Erol Çörlü","poet_slug":"erol-corlu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ayse-kzin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Doğacağız', 'gunese-dogacagiz-ahmet-can-akyol-97faa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürek yüreğe durduk işte

Gülüşümüz koca bir dünya

Hevesimiz sonsuz kadar olmasaydı

Kim yazılabilirdi aşk makamına

Ve kimin şarkısı dahildir aşka

Mor şafaklara durduk yine

Kar beyazı nilüferlere

Soluğumuz kırlardan geçti ki

Ufuklara değiyor sesimiz

Umudumuz doğmamış sevdalara

Biz olacak her mevsim güneşe doğacağız

Sevdikçe düşlerimiz daha çok çoğalacak

Görmüyor musun bizi be hayat

Bak tomurcuklanıyor sevincimiz

Ömrümüz ilkbahar olacak', 'Yürek yüreğe durduk işte Gülüşümüz koca bir dünya Hevesimiz sonsuz kadar olmasaydı Kim yazılabilirdi aşk makamına Ve kimin şarkısı dahildir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gunese-dogacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Görmek,', 'guzel-gormek-sabriye-turkoglu-gsn1h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her güzellin bir çirkin yanı vardır

Her çirkinin bir güzel yanı vardır.

Güzel görenler, güzel düşünürler

Güzel düşünen hayattan lezzet alır

Sabriye TÜRKOĞLU

01.05.2001-10.30', 'Her güzellin bir çirkin yanı vardır Her çirkinin bir güzel yanı vardır. Güzel görenler, güzel düşünürler Güzel düşünen hayattan lezzet alır ...', ARRAY['Türk Edebiyatı','Şiir','Sabriye Türkoğlu']::text[], 8.5, '{"poet":"Sabriye Türkoğlu","poet_slug":"sabriye-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guzel-gormek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizlerde Düştük Kentler Gibi', 'bizlerde-dustuk-kentler-gibi-deger-ulas-turan-kojnu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En son ağlarken bırakmıştık çocukluğumuzu... 

Ağlarken düşmüştü kayıpları bu kentin ve diğer hayallerin 

Arayışlarda bir yokluk saklıydı; Yok olan arayışlardı sanki

İçimizden akıyordu hayat; Dökülüyordu yüzümüzün gülen tarafı. 

Biz şimdilerde bir yokluğu bekliyoruz var olmayışının mucizesinde... 

Bir mucizedir yaşamak bir çocuğun gözlerinde

Ve öpmek dudaklarından sevdiğini bir ağlayışı hatırlatmak gibi... 

Sımsıcak kışlardan koşup da ayazında uçuştuğumuz baharlarıdır

Bu siyahlık kömür karasından başka yalnızlığıdır saklanışların. 

Sus... Ve gece ağlarken annesini unutsun o ölü çocuk.

Biz şimdilerde bir kırık kalbin hatırasını okuyoruz güncel romanlarda... 

Biz şimdi hayatın canına okuyoruz güncel çıkarlarımızda.

Biz artık okumayı bile bilmiyoruz 

Sevmeyi bilmediğimiz gibi

Aşkı yitirenlerin kalesi oldu sözcüklerin en kafiyelisi. 

Nakaratları da kalmadı, zaten hepsi aynıydı.

Aynıydı baştan sona arzularınız Ve arzuladınız öldürmeyi o çocuğu... 

Şimdi çekin gidin hayalleri küllenmiş bu kentten. 

Yıkımları yaşamalı.

Biz mitoloji kadar eskiydik ama onun kadar kalmadık anılarda.

Eksik olan ne varsa bıraktık ve düştük artık bir kenti düşürür gibi. 

Yenilmekten yorulmuştu sevgi, onur ve aşk.

İçinden sızan kan ve hazan... 

Evet, bir hazandı son mevsimleri. 

Ve sonun mevsimsizliğini bile görmüştük.

Ve ben yine bir son söylemiyorum hayallerime.

Çünkü sonu yoktur sevgi için ve sevgiyle olan bir şeyin. 

Yarımlamışlık var hala içimin bilmediğim bir çölünde. 

Bir kadını bıraktım ve kaybettim bir hayatı... 

Şimdi bin kadın gelemiyor örtmeye hatıralarını.

Bir sözcük diyor ve yırtılıyor bütün kayıp fotoğrafların... 

Ellerimde eskittiğim anılarının bir fazlası olmalı

Çoğalması gerek fotoğrafların gibi eskimişse eğer. 

Yenilerini de istemiyorum yalanların eskileriyle boğuşmak bile ölümdü. 

Gerçeğin avcıları ki Şimdi yağmurları kovalıyorlar. 

Buralarda her bahar seller olur ve en az bir insan boğulur gerçeklerde. 

Şimdi ayrılıyorum bu kâğıttan ve bu şarkıyı da böyle bitiriyorum 

Tüm nakaratları ben, tüm ayraçları sen olacaksın. 

Yırtamayacak güncel aşklar hikâyelerini hatıralarımdan. 

Sen yaşayacaksın çocuk, 

Ben yaşadıkça…', 'En son ağlarken bırakmıştık çocukluğumuzu...  Ağlarken düşmüştü kayıpları bu kentin ve diğer hayallerin  Arayışlarda bir yokluk saklıydı; Yo...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bizlerde-dustuk-kentler-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-ulku-tamer-8vumw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu toprakta kalır adın

Tohumların arasında

Yeşilinde tarlaların

Başakların sarısında

Yıllar geçse de aradan

Kopar gelir ırmaklardan

Işır yine kurşunlanan

Dostlarının yarasında

Günü gelir dağa çıkar

Yıldızlardan şiir çeker

Kanımızı siler yıkar

Suların en durusunda

Bir annedir bir kardeştir

Ovalarda bir ateştir

Sırasında hayat verir

Ölüm saçar sırasında

Bayrak olur bize yarın

Rüzgarıyla ilkbaharın

Dalgalanır genç kızların

Gözlerinin karasında', 'Bu toprakta kalır adın Tohumların arasında Yeşilinde tarlaların Başakların sarısında Yıllar geçse de aradan Kopar gelir ırmaklardan Işır yin...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/agit-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demiş', 'demis-asik-ummani-3i0q5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün sevdiğimden bir nağme aldım,

Gözyaşıyla selam yazarım demiş.

Yeniden gönlümü efkâra saldım,

Dem be dem bağrımı ezerim demiş.

Niçin terk eyledin peşimi benim,

Bıraktın sevdaya başımı benim,

Hasiret gözümden yaşımı benim,

Akıtır gün be gün süzerim demiş.

Sarardı çiçeğin güllerin senin,

Daha ulaşamaz ellerin senin,

Nice yıl bekledim yolların senin,

Ah u figan ile gezerim demiş.

Hele benden sonra yaşarsa eğer,

Dağların ardına aşarsa eğer,

ÜMMANİ buraya düşerse eğer,

Ziyaret eylesin mezarım demiş.', 'Bu gün sevdiğimden bir nağme aldım, Gözyaşıyla selam yazarım demiş. Yeniden gönlümü efkâra saldım, Dem be dem bağrımı ezerim demiş. Niçin te...', ARRAY['Türk Edebiyatı','Şiir','Aşık Ümmani']::text[], 8.5, '{"poet":"Aşık Ümmani","poet_slug":"asik-ummani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/demis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-asik-ummani-zk5x8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fikir aynasında bir güzel gördüm,

Yakar iflah etmez beni gözlerin.

Huri melek midir soyunu sordum,

Uğruna yandırır canı gözlerin.

Bu nağmeyi verdiğimden bu yana,

Güllerini derdiğimden bu yana,

Yar yüzünü gördüğümden bu yana,

Süzer damarımdan kanı gözlerin.

Bulunmaz derdime çare yandırır,

Bir günümü yüz bin zara yandırır,

Ölünceye kadar nara yandırır,

Görebilsem değil fani gözlerin.

Yar hasretin ciğerimi dağlıyor,

Gözüm yar gözüne gönül bağlıyor,

Aşığımdır ÜMMANİ CAN ağlıyor,

Görebilir miyim sonu gözlern.', 'Fikir aynasında bir güzel gördüm, Yakar iflah etmez beni gözlerin. Huri melek midir soyunu sordum, Uğruna yandırır canı gözlerin. Bu nağmeyi...', ARRAY['Türk Edebiyatı','Şiir','Aşık Ümmani']::text[], 8.5, '{"poet":"Aşık Ümmani","poet_slug":"asik-ummani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşamalar', 'asamalar-hermann-hesse-223zi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her çağrısında yaşamın hazır olmalı yürek

Yeniden başlamaya eskiyi bırakıp gerilerde,

Kucak açmalı yeni ilişkilere, yeni bağlara

Yaslara bürünmeden, cesaretle ve gözüpek.

Her yeni başlangıçta bir büyü saklı yatar,

Tutar elimizden, kol kanat gerer yaşamamıza', 'Her çağrısında yaşamın hazır olmalı yürek Yeniden başlamaya eskiyi bırakıp gerilerde, Kucak açmalı yeni ilişkilere, yeni bağlara Yaslara bür...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann-hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/asamalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayacağım', 'yasayacagim-nalan-kazazoglu-o1bdi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir vakitte şarkılara ihanet edeceğim

Bir zamanda bitecek güz mevsimleri

Bir vakitte içimdeki sesi boğacağım

Anıların en derin izleriyle

Hırçın dalgalarla boğuşacağım

Demirden elli yaşamın son ayak sesleri yankılanırken kaldırımlarla,

Vazgeçmeyeceğim.

Toparlanıp, uzaklara sürüleceğim.

Bir deniz ülkesinin kar tanesinde,

Ayaklarımın altında ezilen kuru yaprağın gürültüsünde,

Önceki hayatımdan kalmış bir mevsimde,

Firar etmeden ürkek seneler

Başucumda birileri masallar anlatırken

Gökyüzü uzaklaşmadan

Düşlerimi bekçi yollayıp geceye

Uzakta

Adını henüz bilmediğim sıcak bir ülkede

Yaşayacağım..', 'Bir vakitte şarkılara ihanet edeceğim Bir zamanda bitecek güz mevsimleri Bir vakitte içimdeki sesi boğacağım Anıların en derin izleriyle Hır...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğuda', 'doguda-nalan-kazazoglu-4w1e8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çoktan yön verdim gemime

Özlem denilen sinsi büyü güvertede

Uçup gidiyor bedenim

Doğumun,

Doğunun ta kendisine.

Ateşin tam yüreğine diktim gözlerimi

İnatçı yüzünü getirdi oynak alevi

Hava kadar ince yaşam

Yerden göğe haksız bazen

İçimde yağmur yağıyor

Üstüme varma

Başka çağlarla yüklü ruhum

Kalbim doğuda..', 'Çoktan yön verdim gemime Özlem denilen sinsi büyü güvertede Uçup gidiyor bedenim Doğumun, Doğunun ta kendisine. Ateşin tam yüreğine diktim g...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/doguda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Dönüşü', 'i-stanbul-donusu-nalan-kazazoglu-2u1zh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Menzil taşlarını sayıyorum

E-5''te yoldayım

Delidolu şehirden uzaklaşırken

O bildik ağrılı isyanlardayım...', 'Menzil taşlarını sayıyorum E-5''te yoldayım Delidolu şehirden uzaklaşırken O bildik ağrılı isyanlardayım......', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/istanbul-donusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrık Otu', 'ayrik-otu-nalan-kazazoglu-b8jsm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aynını tekrarlar

Bitime kadar

Ömür sürer bazıları,

Dört yapraklı yoncayı arar gizliden....

Aykırı ayrık otları...

Ayak uyduramaz,

Sıkılırlar gidişten..', 'Aynını tekrarlar Bitime kadar Ömür sürer bazıları, Dört yapraklı yoncayı arar gizliden.... Aykırı ayrık otları... Ayak uyduramaz, Sıkılırlar...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayrik-otu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram', 'haram-yesilin-kizi-87v75', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapım dün gece gene 

Üç kez çalındı

Ölüm tarafından

Usul usul ve sessizce

Biliyordum daha zamanım var dı

Ama galiba ^^O^^da

Biliyordu 

Sensizliğin benim için 

Ölüm olduğunu

Aslında bekliyordum

Bende O anın geleceğini ama

İçimi bir korku kapladı 

Hiç tatmadığım duygulara sürükledi

Birden ve amansızca

İşte o an anladım

Seni son defa görmeden

Ölümün bana 

Haram olduğunu', 'Kapım dün gece gene  Üç kez çalındı Ölüm tarafından Usul usul ve sessizce Biliyordum daha zamanım var dı Ama galiba ^^O^^da Biliyordu  Sensi...', ARRAY['Türk Edebiyatı','Şiir','Yeşilin Kızı']::text[], 8.5, '{"poet":"Yeşilin Kızı","poet_slug":"yesilin-kizi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/haram-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Uzaklardan', 'cok-uzaklardan-tugba-tor-hhkpo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok uzaklardan bir gül getirmiştim sana; dudakların gibi kırmızı

Çok uzaklardan bir sevda sunmuştum sana; yaşatırdı bize hayatı', 'Çok uzaklardan bir gül getirmiştim sana; dudakların gibi kırmızı Çok uzaklardan bir sevda sunmuştum sana; yaşatırdı bize hayatı...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Tor']::text[], 8.5, '{"poet":"Tuğba Tor","poet_slug":"tugba-tor","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/cok-uzaklardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Çocukları', 'gunesin-cocuklari-ahmet-i-nce-ewu9c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir sonbahar sabahı

terk etti yaprakları yeşil

uçtu bulutlara doğru

ağaçların kurumuş ciğerleri

koparıldı kalbinden

en güzel çocukları güneşin

kapladı sokakları

karanlığın tamtamları

susturuldu ışığı üretenler

inatçı türkü susmadı

umudun çocukları yürürken yüceliğe

düştü emeğin yüreğinden güller

düşenlerin anısı,sevgimize yazıldı

dökülenler silemez ihanetin pasını

zifiri karanlıkta bile

anacağız düşen gülün hasını

çelik kafes içinde

özgürlük yaralı çiçekti

ışığın çocukları,geçtiler hücrelerden

geçtiler teker teker kanayan gecelerden

şimdi onlar

cadde cadde,bulvar bulvar

birleşiyor yüreğinde güneşin

gülümseyen güzelliğe doğru

koşacaklar durmaksızın

onlar

ışıldayan geleceğidir yurdun

gece sancılı gündüz kaygılı olsa da

aşacaklar tüm barikatlarını karanlığın', 'bir sonbahar sabahı terk etti yaprakları yeşil uçtu bulutlara doğru ağaçların kurumuş ciğerleri koparıldı kalbinden en güzel çocukları güneş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gunesin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Köşe', 'yedi-kose-utku-oguz-cap9k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir köşe seçtim kendime.

Hep yanımda kalacağın,

Ne zaman istersem öpebileceğim,

Hiç yalnız kalmayacağım bir köşe.

-

Bir köşe seçtim kendime.

Karanlıkların aydınlandığı,

Gözümü kapatsam bile,

Aydınlığın hissedildiği bir köşe.

-

Bir köşe seçtim kendime.

Goncaların gül için can attığı,

Güneşin kızıla çaldığı esnada,

Şarap tadındaki gülümsemenle dolu bir köşe.

-

Bir köşe seçtim kendime.

Ankaranın aldatıcı havasına inat,

İtirazsız parmağıma konan kelebeklerle birlikte,

Siyahın gözüme pembe göründüğü bir köşe.

-

Bir köşe seçtim kendime.

İçimdeki çocuk çığlıklarına rağmen,

Sert sorumluluk rüzgarlarını arkama alıp,

Beni kısa yoldan sana getiren bir köşe.

-

Bir köşe seçtim kendime.

Anlamsızlığın bile anlam kazandığı,

Vazgeçilmezin ortasında çırpınırken,

Zevk almak için ellerimi kelepçelediğim bir köşe.

-

Ve bir köşe seçtim şimdi kendime.

Sonların başlangıç olduğunu bilerek,

Yanlızlıktan korkmama rağmen delice,

Korkularımı oyuncak yaparak kollarında,

SENİN YANINDA, SENLE YANLIZ KALABİLECEĞİM BİR KÖŞE....

.', 'Bir köşe seçtim kendime. Hep yanımda kalacağın, Ne zaman istersem öpebileceğim, Hiç yalnız kalmayacağım bir köşe. - Bir köşe seçtim kendime....', ARRAY['Türk Edebiyatı','Şiir','Utku Oğuz']::text[], 8.5, '{"poet":"Utku Oğuz","poet_slug":"utku-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yedi-kose-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansızın Rüyası', 'i-mkansizin-ruyasi-utku-oguz-vz1dt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aslında ilginç sayılır.

Başak sarısının beni böyle düşündürmesi,

Çok uzak görünseler bile,

Yeşilin yüreğimi böylesine çekmesi ilginç sayılır.

-

Aslında ilginç sayılır.

Etrafımdaki altınları toplamak varken,

Gök kuşağının sonundaki hazineyi istemem,

İmkansız olsa dahi,bunu başarma düşüncem ilginç...

-

Aslında ilginç sayılır.

Uykuyu çok sevmeme rağmen,

Gecenin üçünde senin yerine ay ışığını koyup,

Gölgelere dokunmakla yetinebilmem ilginç sayılır.

-

Aslında ilginç sayılır.

Kadife bir dokunuşun beni böylesine yorması,

Sen bilmesen bile,rüyalarımdaki sen,

Ve benim rüyamda bile imkansızı istemem ilginç...

-

Aslında ilginç sayılır.

Sensiz geçirdiğim zamanları hissedememem,

Delice yaşarken hayatı tam ortasında,

Küçük bir gülümsemenle,içimdeki yeni beni bulmam ilginç..

-

Biliyormusun aslında ilginç sayılır...

Sağlam sandığım yüreğimin bir bakışla yıkılması gibi,

İlk defa birisinin haberi olmadan onu sevmem gibi,

Aşkın farklı bir boyutunun daha olduğunu öğrenmem gibi,

HER NE KADAR İMKANSIZ OLSA BİLE,

HER NE KADAR BUNDAN İLK DEFA KORKSAM BİLE,

APTAL BİR CESARETLE SANA KOŞMA KARARIM KADAR İLGİNÇ SAYILIR...

.', 'Aslında ilginç sayılır. Başak sarısının beni böyle düşündürmesi, Çok uzak görünseler bile, Yeşilin yüreğimi böylesine çekmesi ilginç sayılır...', ARRAY['Türk Edebiyatı','Şiir','Utku Oğuz']::text[], 8.5, '{"poet":"Utku Oğuz","poet_slug":"utku-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/imkansizin-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trabzon Kıyıları', 'trabzon-kiyilari-ahmet-i-nce-ypo2b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yosunlu kıyıları öperken dalgalar

martılar balıkları tutuklar

kaygılı gözler, mutlu yüzleri izler

üzüntü neşeyi, çile eğlenceyi gözler

nemlenir bakışları büyük umutların

buzlu bardaklarda mavi düşler ıslanır

özlem ateş içinde

aşk şarkıları yaz havasında yanar

yumuşak yudumların tatlı öpüşlerinde

ıslanır akşam güneşi

ıslanır kızıl gülüşler

denizde ışık eğlentisi

mavi gökte beyaz bulut

bulutun koynunda karanlık

karanlıkta kaybolur kuşlar

rüzgarın saçlarında tuz ve kum kokusu

ıslak avuçlarda martıların çığlığı

yosun kokan yollar özlem dolu

kucaklarken kumsalı ak köpükler

yıkanır kıyının incisi dalyan

yıkanır kızıl sularda ışık yolu

ıslak düşler

esrik gülüşlerden geçer

kız gibi şiirler

şiir gibi kızlar

tuz kokulu kıyılardan geçer

eş yürekler kenetli yürür

şiir gözler, şarkı yüzleri izler

kara gözler tutkundur yeşil göze

kahverengi gözler, suskun bakar

mavi göz, ela gözle çiftleşir

hamsi göz, bütün gözlere vurgun

sevecen gözler sevgi serper şiirlere

hırçın kıyılarında özgürlüğün 

hiç sönmesin yağmuru özleyen ışıklar

ne olur yüce şiir

kurumasın kaynağı güzelliğin

yağdır bereketini emeğin ellerine

susuzluktan ölmesin aşklar

                               Trabzon

                             16.04.1998', 'yosunlu kıyıları öperken dalgalar martılar balıkları tutuklar kaygılı gözler, mutlu yüzleri izler üzüntü neşeyi, çile eğlenceyi gözler nemle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/trabzon-kiyilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kamelyam', 'kamelyam-adem-unal-hjh34', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Serin kavak yelleri esiyordu başımda.. 

Ümit ekmiştim nadasa bıraktığım tüm tarlalara.. 

Alnımdaki teri kurutsam diye 

Bağrımı açtığım rüzgarlar 

Tutam tutam 

saçlarımı götürdüler 

Nasıl anlatsam 

Kurşun sıktılar hayallerimin 

En umulmaz yerinden 

Kamelyam! 

Akşam üstleri horozlar ötmezmiş 

Köy sokaklarında alımlı gezmezmiş köy kızları 

Ay tutulmaya dursun hele bir 

Tüfeği dayarlar uğursuz sayarlar.. 

Hele dur! 

Destursuz girme dediler bu kapılardan... 

Yılaryılı acı ile bağladılar ellerimi, 

Yasak koydular gözlerime, 

Seven göze yasak olur mu demediler, 

Oturmadılar sofralarıma,yemediler.. 

Ateşle korkuttular, 

Zaten yanmışım buram buram, 

Ezikliği yüreğimde tüm sevgilerin... 

Kamelyam! 

Senin için bastığım adımlara 

Mayın döşediler 

Eşkiyalar kesti yollarımı.. 

Sana gelmek için 

Rüyalarımda uçtum geceleri 

Uykularımı böldüm en kuytusunda karanlığın 

Kadermiş,değişmezmiş 

Yılaryılı boşuna aldandım 

Met yapmışlar ikimizi 

Oynuyorlar,oynuyorlar 

Kamelyam! 

Gitti de beni gitti de... 

Tanınmaz insanların balosuna gitti de.. 

Bıkmışlığın ezgisi 

Yalnızlıktan... 

Bir sükutun nabzı damarlarımda, 

Düğüm düğüm içimde.. 

Başka dünyaların çocuğuyuz biz, 

Başka dünyaların çocuğu... 

Kamelyam! 

Çok şeyleri elde etmeye yetmiyor sevgimiz, 

Oraya yaz mektuplarını 

Ararsan, 

Simerenya''ya 

Allah''a ısmarladık... 

Kamelyam! 

Kamelyam!....', 'Serin kavak yelleri esiyordu başımda..  Ümit ekmiştim nadasa bıraktığım tüm tarlalara..  Alnımdaki teri kurutsam diye  Bağrımı açtığım rüzga...', ARRAY['Türk Edebiyatı','Şiir','Adem Ünal']::text[], 8.5, '{"poet":"Adem Ünal","poet_slug":"adem-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/kamelyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Böyle Olsun İstemezdi', 'o-boyle-olsun-i-stemezdi-sabri-tandogan-pja46', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'o böyle olsun istemezdi 

böyle ,umduğu kalmamış gibi kimselerden 

çift uçuşan kuşaların kanatlarındaydı kalbi, 

aşk özlemleri içinde kıvranarak yanarken.... 

o böyle olsun istemezdi 

uzak... çok uzak iklimlerin ardında 

ve ötesinde.. başka mevsimlerin ve maviliklerin 

ve gölgelerin alçaldığı ,o sessiz saatlerde 

yine başlayacakmıydı yalnızlığın  azabı 

yine kanayacakmıydı içindeki yaralar 

yaralar ki azap verir lezzeri kadar aşkın 

yaralar kisızlar sabahlara kadar 

yaralar ki 

ama o böyle olsun istemezdi 

yarım kalmıştı bütün  sevgileri 

bütün sevgilerini sonlara bırakmıştı 

aşk rüyaları görürdü gözü açıkken bile 

içinde kalmıştı bütün  özlemleri 

çekingen,sessiz,mahcup ve saygılı 

ona herkes böyle bakar 

onu herkes böyle tanırdı 

ve onun bütün sevgileri hep...... 

sonralara, yarınlara kamıştı 

vakti henüz gelmedi derdi, 

meyveler daha olgunlaşmamışken dallarda 

ve en güzel çiçekler daha dirilmemişken 

ve hep sonu gelmez nedenlerin yüzünden 

bakışlarıyla bile anlatabilirdi 

bakışlarıyla bile... 

seni senden bile çok... 

diyebilrdi ama olmadı.. 

tadılmamış sevgilerin sonsuz özlemi 

dudaklarında 

ve söylenmemiş şarkıların en güzeli 

kalbinde kaldı... 

en güzel zamanları beklemek lazımdı... 

yaprak engüzel yeşilinde,gökyüzü en güzel mavisindeyken 

bir yağmur sonrası gibi sessiz ve derin 

bir bulut dururken ,bir kuş uçarken 

seni senden bile çok ... demek varken 

o böyle olsun istemezdi ama olmadı 

kalbini dolduran en coşkun duygular 

yine öylece... 

kalbinde kaldı...... 

sessiz ve karanlık gecelerin en güzel bahçesinde 

bembeyaz aşk gülleri derilmeden kaldı... 

o böyle olsun istemezdi ama ... 

söylenmemiş aşkların en güzel şarkıları 

öylece....öyle kahredercesine 

dudaklarında kaldı......', 'o böyle olsun istemezdi  böyle ,umduğu kalmamış gibi kimselerden  çift uçuşan kuşaların kanatlarındaydı kalbi,  aşk özlemleri içinde kıvrana...', ARRAY['Türk Edebiyatı','Şiir','Sabri Tandoğan']::text[], 8.5, '{"poet":"Sabri Tandoğan","poet_slug":"sabri-tandogan","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/o-boyle-olsun-istemezdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gıza Bak Hele', 'giza-bak-hele-cemal-safi-t2tak', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Böyledir kısrağın deli çağları

Çalmadan oynuyo kıza bak hele

Ben yarattım diyo alçak dağları

Kafirin verdiği poza bak hele

Bilmem neyin nesi kimin sıpası

Çözüldü göynümün katmerli pası

Göğüs göğüs değil füze rampası

Şafak mı söküyo yüze bak hele

Ten değil mübarek akrın sıcağı

Koynuna girenin söndü ocağı

Bir kalçayı seyret bir de bacağı

Tornada çekilmiş dize bak hele

Üst yanı Asyalı alt yanı Frenk

Her adım atış bir başka ahenk

Ela mı bela mı bilmem ki ne renk

Şu cellat bakışlı göze bak hele

Dedi ki ''Nasibim senmişsin meğer

On bin kez maşallah demeden eğer; 

Koklarsan solarım, nazarın değer''

Ağzından yel alsın söze bak hele

Dedim ki; ''Ne olur tenhaya gidek,

Gidek de feleği perişan edek''

''Say'' dedi ''o halde saçımı tek tek''

Haspanın ettiği naza bak hele

Görenler altını ıslatmış derler

Yatağı göl etti döktüğüm terler

Yetişin; yanıyo bastığı yerler

Giderken koyduğu ize bak hele', 'Böyledir kısrağın deli çağları Çalmadan oynuyo kıza bak hele Ben yarattım diyo alçak dağları Kafirin verdiği poza bak hele Bilmem neyin nesi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/giza-bak-hele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve...o an! ! !', 've-o-an-mahmut-yildiz-mlqdt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir soğukluk duyarsın da 

Hani donup kalır ya vücudun 

Ve havaya doyamazsın o an 

Etrafın bulutlanır da 

Yağmurlara bel bağlarsın ya 

Ve çaresizliğine yanarsın o an 

Hani yakınlarının sesini duyarsın da 

Onlara sesini duyuramazsın ya 

Ve ayrılık vaktinin geldiği fısıldanır kulağına o an 

Yalnızlık etrafını çepçevre sarar da 

Bir yardım, bir umut ışığı ararsın ya 

Ve gerçek bir yalnızlığın çukurundasın o an 

Hayatın bir film şeridi olur da 

Hani “tüh ulan ne yaptım” dersin ya 

Ve pişmanlığın beş para etmez o an 

Sabah soğuk terlerle kalkar da 

Hani nerede olduğunu bilemez afallarsın ya 

Ve evindeki sıcak yatağındasın o an

Mayıs 2001 - İstanbul', 'Bir soğukluk duyarsın da  Hani donup kalır ya vücudun  Ve havaya doyamazsın o an  Etrafın bulutlanır da  Yağmurlara bel bağlarsın ya  Ve çar...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Yıldız']::text[], 8.5, '{"poet":"Mahmut Yıldız","poet_slug":"mahmut-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ve-o-an-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadığımda...', 'olmadigimda-adil-koruyan-lhlhd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün gelecek, sabah uyandığında,

Ben olmayacağım yanında.

Sana bakan bir çift göz,

Yanaklarını okşayan eller olmayacak.

Sevgi sözcükleri de duymayacaksın.

Bir hüzün kaplayacak içini.

Belki bir kaç damla yaş dökülecek,

Boğazın düğümlenecek, yutkunamayacaksın.

Dudaklarından tek bir sözcük dökülecek,

Eski günlerdeki gibi içten ''canım'' diyeceksin.

Bütün benliğinle haykırarak ağlayacaksın.

Gözüne birlikteliğin bir anısı takılacak,

Anımsayıp, o anı yaşıyor olacaksın.

Ellerin benim ellerin olacak,

Tüm vücudunu saracak.

Yokluğumda beni yaşayacaksın.

Varlığımda yokluk saydığın,

Özlemin ne olduğunu, o zaman anlayacaksın.

Ne yazık, o zaman ben hayatta olmayacağım.

03.05.2001', 'Bir gün gelecek, sabah uyandığında, Ben olmayacağım yanında. Sana bakan bir çift göz, Yanaklarını okşayan eller olmayacak. Sevgi sözcükleri ...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmadigimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan!', 'uyan-mehmet-akif-ersoy-n9o4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baksana kim boynu bükük ağlayan? 

Hakk-ı hayâtın senin ey müslüman! 

Kurtar o bîçâreyi Allâh için,

Artık ölüm uykularından uyan! 

Bunca zamandır uyudun, kanmadın; 

Çekmediğin kalmadı, uslanmadın.

Çiğnediler yurdunu baştan başa,

Sen yine bir kerre kımıldanmadın! 

Ninni değil dinlediğin velvele...

Kükreyerek akmada müstakbele,

Bir ebedî sel ki zamandır adı; 

Haydi katıl sen de o coşkun sele.

Karşı durulmaz, cereyan sîne-çâk...

Varsa duranlar olur elbet helâk.

Dalgaların anlamadan seyrini,

Göz göre girdâba nedir inhimâk? 

Dehşet-i mâzîyi getir yâdına; 

Kimse yetişmez yarın imdâdına.

Merhametin yok diyelim nefsine; 

Merhamet etmez misin evlâdına? 

«Ben onu dünyâya getirdim...» diye,

Kalkışacaksın demek öldürmeye! 

Sevk ediyormuş meğer insanları,

Hakk-ı übüvvet de bu cânîliğe! 

Doğru mudur ye’s ile olmak tebâh? 

Yok mu gelip gayrete bir intibâh? 

Beklediğin subh-i Kıyâmet midir? 

Gün batıyor, sen arıyorsun sabâh! 

Gözleri mâzîye bakan milletin,

Ömrü temâdîsi olur nekbetin.

Karşına müstakbeli dikmiş Hudâ,

Görmeye, lâkin daha yok niyyetin! 

Ey koca Şark, ey ebedî meskenet! 

Sen de kımıldanmaya bir niyyet et.

Korkuyorum, Garb’ın elinden yarın,

Kalmayacak çekmediğin mel’anet.

Hakk-ı hayâtın daha çiğnenmeden,

Kan dökerek almalısın merd isen.

Çünkü bugün ortada hak sâhibi,

Bir kişidir: «Hakkımı vermem! » diyen.

5 Şubat 1330 (18 Şubat 1915)', 'Baksana kim boynu bükük ağlayan?  Hakk-ı hayâtın senin ey müslüman!  Kurtar o bîçâreyi Allâh için, Artık ölüm uykularından uyan!  Bunca zama...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/uyan-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milenyumun Aşk Hİkayesi', 'milenyumun-ask-hi-kayesi-fatih-cunus-nmgb1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen günü ben neyleyim

Sensiz geçen hergün kanadı kırık bir leyleğim

Yokluğuna fazla alıştırma beni

Hemen buluşalım tut ellerimi

Sarılayım yine sımsıkı sana

Hissedelim hep birbirimizi

Sensizliği nasıl anlatayım sana

Anlaman zor biraz galiba

Sensizliği nasıl anlatsam ki

Sen hiç sensiz kalmadın ki

Uzansak birlikte yemyeşil kırlara

Dalsak pespembe rüyalara

Haykıralım aşkımızı tüm dünyaya 

Martılar şahit olsun aşkımıza

Kondurayım dudağına bir aşk busesi

“İşte !” desinler “milenyumun aşk hikayesi !”', 'Sensiz geçen günü ben neyleyim Sensiz geçen hergün kanadı kırık bir leyleğim Yokluğuna fazla alıştırma beni Hemen buluşalım tut ellerimi Sar...', ARRAY['Türk Edebiyatı','Şiir','Fatih Cünüş']::text[], 8.5, '{"poet":"Fatih Cünüş","poet_slug":"fatih-cunus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/milenyumun-ask-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-sadri-alisik-6zq0l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim mezarım deniz kıyısında olmalı

Kıyı kıyı yosun bitmeli

Yeller esmeli, sular akmalı

Kuşlar değil, balıklar su içmeli mermer taşımdan

Başımda düşümde hep bir deniz,

Düüt düüt şirket vapurları, yandan çarklı, pervanesiz..

Benim bütün mirasım İstanbul olmalı.

Kabristanımsa deniz...', 'Benim mezarım deniz kıyısında olmalı Kıyı kıyı yosun bitmeli Yeller esmeli, sular akmalı Kuşlar değil, balıklar su içmeli mermer taşımdan Ba...', ARRAY['Türk Edebiyatı','Şiir','Sadri Alışık']::text[], 8.5, '{"poet":"Sadri Alışık","poet_slug":"sadri-alisik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/istanbul-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-hasan-kaya-corlulu-cu43g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok Sevgili Dostuma;

Çölde kurumuş kalmış kum tanesi üzerine düşen bir yağmur damlası,

Kadife kırmızı,henüz yeni açmış Gonca''ya damlayan çiğ tanesi

Evrenin sonsuzluğunda yalnızlığa mahkum bir yıldıza yarenlik eden Sen.

Aramıza hoşgeldin dostum.

Güler yüzün hiç solmasın

Bulutlanmasın gözlerin

Özlem dolu sevdalardan uzakta.

Zaman çok çabuk geçiyor

Bak

Vakit akşam olmakta.

Unutma;

Hiçbirşey değerli değildir senden

Şairin dediği gibi

Gün eksilmesin pencerenden.

02.05.2001', 'Çok Sevgili Dostuma; Çölde kurumuş kalmış kum tanesi üzerine düşen bir yağmur damlası, Kadife kırmızı,henüz yeni açmış Gonca''ya damlayan çiğ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaya Çorlulu']::text[], 8.5, '{"poet":"Hasan Kaya Çorlulu","poet_slug":"hasan-kaya-corlulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan Şiir', 'yasayan-siir-omer-i-lhan-xd4wu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir en kısa anlarında bile bir ben eder

En durgun gecelerinde gözlerimde

En solgun sabahlarında ellerimde

Bir kaç sayfadan daha çok yaşar

Şiir gidebileceğim kadar uzaklarda

Durumadığım zamanlarda bile ölçülü

Ama gözümün göremeyeceği kadar da

Yakınımda, derinlerimde yaşar

Şiir her zaman her an canlı bir insandır

Bazı anlarda binlerce insan bile

Bir şiiri doldurmaz, yetişemez satırlara

Şiir ölmez ama insan kadar yaşar', 'Şiir en kısa anlarında bile bir ben eder En durgun gecelerinde gözlerimde En solgun sabahlarında ellerimde Bir kaç sayfadan daha çok yaşar Ş...', ARRAY['Türk Edebiyatı','Şiir','Ömer İlhan']::text[], 8.5, '{"poet":"Ömer İlhan","poet_slug":"omer-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasayan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-siverekli-abbas-yilmaz-013wy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni anlatacak sözcüklein tükenişi beni korkutuyor

Sanki...

Misisipi nehri kurumuş

Ağrıdağı hiç yok

Mariona çukurluğu çoktan dolmuş

Ve sözcükler sahnede zavallı figüran rolünde

Biliyorum...

O zaman ne briyantinli saçlaım

Ne papyonların en kapitalisti

Seni geri getirmeyecek

Bunuda biliyorum

Ne garip şey 

Dramatik bir veda sahnesi hayat

Sazımın ince telleri kopar 

Sigaram üşür

Ne kötü şey  sessiz telefon kablolarında aramak seni

Yırtılıyorum galiba

Şarkılar gurur oynatıcı

Caddeler komplo

İnsanlar cinayet

Şimdi med cezir yaşıyor hayatım 

Simanın yokluğu ve sözcüklerin iflası var yüreğimde 

Neden biliyor musun?

Çünkü

Yokluğunun alternatifi ya da rövanşı yok

Onun için yazamıyorum

İşte bu yüzden korkuyorum', 'Seni anlatacak sözcüklein tükenişi beni korkutuyor Sanki... Misisipi nehri kurumuş Ağrıdağı hiç yok Mariona çukurluğu çoktan dolmuş Ve sözcü...', ARRAY['Türk Edebiyatı','Şiir','Siverekli Abbas Yılmaz']::text[], 8.5, '{"poet":"Siverekli Abbas Yılmaz","poet_slug":"siverekli-abbas-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/korkuyorum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giiit!', 'giiit-siverekli-abbas-yilmaz-xy5qh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kusursuzca terk et beni

Öyle acımasız öyle dokunaklı

Adımlarında tükensin herşeyden yoksunluk

Herşeyden mağdur

Kordinatsızca bırak beni

Sokak lambalarının cimri aydınlığında büyüsün  yanlızlığım

Öyle Edison amcasız,öyle yıldızsız,öyle aysız

Git yüzyıllık bir sis bırak arkanda

Buğulansın her şey

Cam,bıçak ve gözlerim

KURŞUN ÇARPSIN Kİ GİT

Öyle mesafesiz,öyle yaklaşımsız

Arada sırada bi namusça dokun bana

Rotasız rüzgar gibi

Negatifçe beni sende;seni bende bırak öyle git

Tanımsızca terk et beni

Öyle adressiz öyle meçhul bir cinayet gibi

Kapısızca bırak beni

Perdelerim üşüsün;cığaram sönsün öyle git

PEYNİR ÇARPSINKİ GİT

Dudakalrında kalsın hep tadılmamış tuzun

Beni takvimsiz 

Beni yarınsız

Kilometrelerce uzat öyle git

Bırak senden pas tutayım

Öyle kirli,öyle traşsız,öyle aç kalayım

Bir kağıt kadar yırtılayım senden,bir cam kadar kırılayım senden

Öyle hesapsız git

Beni böyle yer çekimsiz

Beni Newton amcasız bırak da git

Bir tek yüzüm uğrasın

Senin yüz çekimine

Böyle dokunaksız

Böyle ağırlıksız

Bırak da git

EKMEK ÇARPSIN Kİ GİİİT

Böyle melodi dram niteliğinde

Böyle soğuk

Dönüşümsüz bırak da git

Kendini kaplamsız

Beni içlemsiz işte öylesine bırak da git

Ya dondur beni

Ya da başa sar çocukluğumu

Öyle git

Ve son

KURAN ÇARPSINKİ GİİİT', 'Kusursuzca terk et beni Öyle acımasız öyle dokunaklı Adımlarında tükensin herşeyden yoksunluk Herşeyden mağdur Kordinatsızca bırak beni Soka...', ARRAY['Türk Edebiyatı','Şiir','Siverekli Abbas Yılmaz']::text[], 8.5, '{"poet":"Siverekli Abbas Yılmaz","poet_slug":"siverekli-abbas-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/giiit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen', 'bir-sen-arif-damar-nio6o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günlerce yağmurda,

günlerce karda,

günlerce rüzgar esti

Erzurum''da,Zara''da.

Bir sıcak sen kaldın içimde.

O gün bu gün

dünya bir yana

sen bir yana

Dünyalar senden yana.

                                                    (1954,İstanbul)', 'Günlerce yağmurda, günlerce karda, günlerce rüzgar esti Erzurum''da,Zara''da. Bir sıcak sen kaldın içimde. O gün bu gün dünya bir yana sen bir...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif-damar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmalısın', 'olmalisin-siverekli-abbas-yilmaz-2c06n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşün nasıl ki bir köle efendisine bağlı kalıyorsa

Ve nasıl ki bir rüzgar gideceği yeri keşfediyorsa

Ya da nehir yatağı suyunu sadıkça ulaştırıyorsa

Ve Tanrı güneşi dünyaya nasıl bağışlıyorsa

Öylesin sen de

Senin de tenin tenime değmeli

Beni yorgan gibi sarmalısın

Sabahın güneşi özlercesine

Bana ışık,bana ısı olmalısın

Ve orada terin terime karışmalı 

Beraber cehennemi hak etmeliyiz

Uzun süre orada kalmalı

Sıcaklığın ondan da ağır gelmeli 

Tanrı hayatında ilkkez yanlış yaptığını anlamalı

Bizi oradan da kovmalı...

(y.yeri :siverek/urfa  yayınlıyan:yargıç hasan baran)', 'Düşün nasıl ki bir köle efendisine bağlı kalıyorsa Ve nasıl ki bir rüzgar gideceği yeri keşfediyorsa Ya da nehir yatağı suyunu sadıkça ulaşt...', ARRAY['Türk Edebiyatı','Şiir','Siverekli Abbas Yılmaz']::text[], 8.5, '{"poet":"Siverekli Abbas Yılmaz","poet_slug":"siverekli-abbas-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olmalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalanların Yarınları', 'kalanlarin-yarinlari-jale-demirdogen-6mldo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıl 1999,

Aylardan ağustos

Mevsim cehennem..

Elbette böyle dememişti şair,

Şiirine başlarken..

Fakat o zaman,

Kırkbeşbin öyküyü toprağa gömüp,

En az kırkbeşbin yeni öykü 

İnşa etmemişti henüz deprem!

Hem de kırk beş saniye içinde

Acılara gömülmemişti ülkem

Oysa şimdi;

Mevsim cehennem!

Sonrasında hiç kimse düşünmedi

Kimbilir kaç taksitle ve nice zahmetle alınıp,

Evin mutena bir köşesine konulan eşyanın ardına düşmeyi..

Hiç bir çocuk aramadı

Sevinçten uçarak getirdiği

Pekiyilerle dolu karneyi!

Göz nuru ile işlediği çeyizi için ağlayan

Tek bir gelinlik kız görmedik

Enkazın altı candı çünkü

Ana vardı,baba vardı,evlat vardı..

Enkazın altı yardı!

Aşk kalmıştı betonların altında,

Düş sıkışmıştı kirişlerin arasına

Her şey talandı..

Ve sanki;

Tüm yaşanmışlıklar birer yalandı!

Yapılacak önemli işler vardı ertesi gün

Enkaz altındakiler için..

Fakat ertesi gün olmadı..

Ya kalanların yarınları?

Tutunacakları anıları,

Ve şanslıysalar

Ellerinde birer yırtık fotoğrafla

Her gün yeniden yaşatmak için onları

Asıl ölüm,

Enkazın üstündeydi galiba!', 'Yıl 1999, Aylardan ağustos Mevsim cehennem.. Elbette böyle dememişti şair, Şiirine başlarken.. Fakat o zaman, Kırkbeşbin öyküyü toprağa gömü...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kalanlarin-yarinlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Varmış Bir Yokmuş', 'bir-varmis-bir-yokmus-jale-demirdogen-g0r9x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yirmidört saatin hiç birisinde

Mola vermek yok artık

Gece göze uyku yok!

Şimdi anlamak var sokak lambalarının halinden

Eli kolu bağlı beklemeyi öğrenmek

Sessiz gecede.

Bitmek bilmez kederin saatlerinde,

Çay içmek bir de

Sensiz ,şekersiz,sohbetsiz bardaklardan..

Ve her yakılan sigarada umut söndürmek!

Bir acımak varki derinlerde bir yerde

Sorma gitsin demek var.

Öyle bir acımak ki,

Sorsan da gitmeyecek herhalde.

İlaçlardan medet ummak var şimdi

Bir dakika için bile olsa

Sussun diye düşünce.

Böyle olunurmuş demek var

Ayrılığa düşünce.

Darmadağın bir hal var soframda şimdi.

Bardağımdaki su değil,

Birikmiş gözyaşlarım

Tabağımda tutunduğum hayalin kırıkları,

Günahsa da tövbe deyip çöpe atmak var.

Artık dilimin ucunda

Bir daha söylenmeyecek eski sözler var

Tanıdık,alışıldık sevgiyle sana yolcu.

Artık''''ne var ne yok demek yok ha..

''''Ne var ne yok bir tanem?''''

Bilir misin söylenmedikçe

Çöl olur bu dudaklar.

Yani şimdi ciddi ciddi

Bir anlık bir öfke

Gömdümü seni puslu İzmir sabahına?

Merak edersen şayet,

Ogün bugündür buralarda

Varla yokun arasında,

Yok denecek kadar azım şimdi

Var denecek kadar çok aşkınla!', 'Yirmidört saatin hiç birisinde Mola vermek yok artık Gece göze uyku yok! Şimdi anlamak var sokak lambalarının halinden Eli kolu bağlı beklem...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bir-varmis-bir-yokmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Martı Masalı', 'bir-marti-masali-jale-demirdogen-3fi6z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sırrım vardı benim,

Kimselere demediğim

Bir martı yaşardı kaçak..

En kuytusunda yüreğimimim..

İzin almamıştı benden orada yerleşmek için

Vurdum kilidi üstüne,

Ne su verdim,ne besledim,ölsün diye bekledim!

Gün oldu,

Çok ağladı..

Özgürlüğe yalvardı

Biraz tuhaftı

Git dedim,

Kaldı..

Tek isteği sana doğru uçmaktı

Olmazdı..olmamalıydı

Vurdum kilidi üstüne,

Ölsün diye bekledim!..

Bir gün.

Sana gelirken aleleacele,

Açık unuttuğum kapıdan sızıverip gizlice

Hiç beklemediğim bir anda

Dudaklarımın arasından kanatlandı aniden..

Bir çığlık attı;

Öyle bir çığlıktı ki,

Sen irktün,

Ben utandım..

Yıldızlar ayağımın altında

Birer birer ufalandı

Başımdan aşağı dökülen,

Kaynamış sular değil,

Düpedüz hayatımdı

Ah işte o martı,

Bana ne yaptığını hiç anlamadı.

Çünkü o da dünyadan en güzel şeyin,

Sevilmek olduğunu sandı

Bense hayatımda ilk defa,

Sevmeyi tatmıştım yeni.

Sana hissettiğim aşkta!

Hesapsız kitapsız..hiç karşılıksız

Sevmeyi öğrenmiştim

Bir martı..bir hata..

Seni kaybettim!

Martıya ne mi oldu sonra?

Suçluydu..kızgındım

Bir kurşun sıktım alnının ortasına

Vurdum kilidi üstüne,

Ölsün diye bekledim!

Son bir gayret seslendi

Bir garip baktı yüzüme

''''Tamam dedi..özür dilerim

Bir hataydı kabul..affet ölmek üzereyim

Fakat hemen şimdi söyle..merak ederim..

Madem sevilmek değil,sevmekti istediğin,

Onu kaybettin diye sevemez misin?''''

Sustum cevap veremedim.

Açtım kilitleri

Sardım yaralarını..

Yaşasın diye dua ettim.

Bir sırrım var hala benim,

Kimselere demediğim.

Bir martı yaşıyor hür,

En kuytusunda yüreğimin!', 'Bir sırrım vardı benim, Kimselere demediğim Bir martı yaşardı kaçak.. En kuytusunda yüreğimimim.. İzin almamıştı benden orada yerleşmek için...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/bir-marti-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkum', 'mahkum-jale-demirdogen-mo8g9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pencerelerimin önüne birer gardiyan diktin

Kadife perdelerimden

Uzak duracak artık rüzgar

Bir kereyle yetinmedin

Üç kez üst üste kilitledin

Dostlarım artık bu kapıyı

Tıklatmayacaklar1

Küçücük bir sitem etmişti dilim

Yoktu bende kötü bir niyet,

Savcı sendin,hakim sendin,

Katip sen..

Okundu nihayet,

Cezam,

Sensizliğe müebbed!

Oysa bak denizlere,

Sitem yüklü dalgalarını 

Yüzyıllardır kıyılara vurur durur da hala hür!

Sen şimdi o kıyılara git

Utanma seni bir tek

Gökteki yıldızlar

ve bir balıkçı teknesi görür.

Hoşgörüyü ve büyüklüğünü sevginin

Öğrenmek için güzel yüzünü

O ıslak kumlara bir sür!

Şimdi sor;

Bu evde geçecek mi sensiz bu ömür?

Geçecek gülüm

Geçecek elbet

Sen bilmezsin ben sevmeyi

O kıyılarda dolaşa dolaşa öğrendim

Sen takmış olmasaydın böyle demezdim

Pek yakıştı bileklerime 

Kelepçelerim!', 'Pencerelerimin önüne birer gardiyan diktin Kadife perdelerimden Uzak duracak artık rüzgar Bir kereyle yetinmedin Üç kez üst üste kilitledin ...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mahkum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgan', 'yorgan-jale-demirdogen-wub92', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu defa

Kış uzun sürecek galiba

Bir türlü bitmedi gitti

Havanın değil de aslında,

Bana bu buz gibi acıların ettiği yetti!

Kapadım gözlerimi,

Önce salına salına

Önümden annem geçti

Pişmandıysa da artık,

Dönmek için vakit geç,

Hem de çok geçti!

Babam şöyle bir bakıp sadece gülümsedi

Hiç bilemedim

O gülümseyiş

İçtenmiydi ki..

Sevdalılar birer birer çekti gitti

Şiirler kaldı bana,

Ben şiirlere yar oldum

Yoruldum.

Uzunca bir uykunun tam da sırası şimdi

Çok şey istemiyorum

Bana bir deniz kenar kum

Yalnız bir ağacın dibi,

Başımın altına bir yastık taştan

Bir de yorgan üstüme

Kuştüyü değil topraktan!

Örtünmeliyim;

Öyle çok..

Öyle çok üşüyorum ki!', 'Bu defa Kış uzun sürecek galiba Bir türlü bitmedi gitti Havanın değil de aslında, Bana bu buz gibi acıların ettiği yetti! Kapadım gözlerimi,...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yorgan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığın İki Yüzü', 'karanligin-i-ki-yuzu-jale-demirdogen-iqi0h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevişeceksen

Karanlıkta sevişeceksin

Karanlığın ödü patlar mutluluktan

Sözüme inan!..

Öyle böyle değil ama,

Çok karanlık olacak

Vurmayacak çarşafına bir damla ışık aydan!

Yeterince karanlıksa

Artık unutacaksın seviştiğinin kim olduğunu

O çok sevdiğin yüzü,

Hatırlamayacaksın

Karanlıkta kaybolacak kimliği

Öptüğün dudakların

Soracaksın kendine şaşkın

''''O ezbere bildiğim eller onun mu şimdi..

Onun mu bu soluk..ne fısıldıyor?''''

Derken..

Bu tanıdık yabancıya alışacaksın!

İşte o zaman çıkaracaksın 

En kuytusuna koyduğu sırrı,

Sevdiğinin ruhundan1

Ve işte bundan sonra,

Mutluluğu karanlıkta,

Elinle koymuş gibi bulacak,

Hiç aramayacaksın.

Sevişeceksen,

Karanlıkta sevişeceksin anlayacağın.

Peki ya yalnızsan?

sakın ha karanlıkla sevişmeye kalkmayacaksın!

Yalnızlığın ödü patlar karanlıktan

Tecrübe ile sabittir,

Sözüme inan!', 'Sevişeceksen Karanlıkta sevişeceksin Karanlığın ödü patlar mutluluktan Sözüme inan!.. Öyle böyle değil ama, Çok karanlık olacak Vurmayacak ç...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/karanligin-iki-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-engin-arapoglu-4jmnn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aklım yok!

yola çoktan çıktı,varmış gitmiştir bilinmeze,

ben mukayet olamıyorum aklıma!

ruhum da yok!

bedenimi terketti ruhum,

çıktı ''hayırsız yolculuklar''a!

damarımdan acı veriyorlar,

kirpiklerim dökülüyor ağlamaktan,

dişlerimi kırıyor,tırnaklarımı çekiyorlar!

ayakta duracak halim yok artık!

barınacak bir sığınağım yok!

yer-gök kabül etmiyor beni...

gitti!

ve bitti!

ve bittim!

ve bittim işte!

tükendim,yenildim,

kaybettim işte!

ne yaşadım ne de öldüm,

yok oldum işte!

ara bul beni,

kimim şimdi?

nasılım?

nerdeyim?

sonunda birşey oldum işte,

bir hiçim..!

bu nasıl bir sevda,

bu ne biçim...!', 'aklım yok! yola çoktan çıktı,varmış gitmiştir bilinmeze, ben mukayet olamıyorum aklıma! ruhum da yok! bedenimi terketti ruhum, çıktı ''hayırs...', ARRAY['Türk Edebiyatı','Şiir','Engin Arapoğlu']::text[], 8.5, '{"poet":"Engin Arapoğlu","poet_slug":"engin-arapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hic-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Memleketinde Sen', 'deniz-memleketinde-sen-jale-demirdogen-03fhj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elma kokan şampuanla yıkardım saçlarımı

Ve gurur duyardım

Her gün bir başka şekil verdiğim,

Ve çocuk aklımla seni büyülediğini sandığım saçlarımla..

Sense yosun kokardın..

Yanımdan geçtiğinde,

Yosun ve deniz kokusu asılı kalırdı havada..

Neden bilmem?

Seni ilk kez bir deniz memleketinde

Tanıdığım içindi belki de..

O deniz memleketinin kışı da kara olurdu haa!

Kalın kumaştan dikilmiş,

Uzun siyah paltonla beyaza dönüşürdü sabahlarım..

Buz gibi soğuğu hissetmeme engel,

Vahşi acılarımın üstüne çarpıp da kapıyı,

Bir çıktım mı sokağa,

Kalın uzun siyah paltonla oradaysan eğer;

Acılı bir küçük kız

Mutluydu o gün

O deniz memleketinin otobüs durağında..

Ne şarkılar tutuldu bir dilekle beraber,

Hep senin için hep sana dair,

Ne şiirler yazıldı,

Kaç gece sabaha kavuştu uykusuz yorgun

Ve kaç mevsim yer değiştirdi sessizce bir bilsen..

Sen sadece bir kaç ev ötede

Ve her şeyden habersizken 

O deniz memleketinde..', 'Elma kokan şampuanla yıkardım saçlarımı Ve gurur duyardım Her gün bir başka şekil verdiğim, Ve çocuk aklımla seni büyülediğini sandığım saçl...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/deniz-memleketinde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahlar', 'sabahlar-tugba-tor-jd8uw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O sabah bir başka güzeldi seninle 

Sen vardın ya hayatımda,

Boş ver kimseler arayıp sormasın,

Kapımı kimseler çalmasın

Bir tek sen yeterdin ya bana...

Hatırlıyor musun?

Duygularımın bekareti bozulmuştu seninle o sabah.

Bana her dokunuşunda tüylerimin ürperişini,

Bedenimin alevlenişini...

Hatırlıyor musun?

Sensiz gecelerde göz yaşlarıma sığınışımı,

Yastığıma sarılıp, senli rüyalara dalışımı.

Unutur muyum sanıyorsun,

İçimi gıcıklayan o bakışlarını...

Seninleyken, kadehinden bile kıskanırdım seni.

Dudakların benden başkasına dokunmasın,

Nefesin bir başka nefese karışmasın isterdim.

Yalnızca benim dişiliğim bozmalıydı ruhunun mührünü,

Rüzgar gibi bedenine girip fırtınalar estirmeliydim

Kış ayazında yalnızca bana sokulmalı,

Yaz sıcağında teninde erimeliydim...

şimdi soruyorum da,

Çok mu şey istedim senden terk ettin beni.

Kıyameti yaşattın, ölümü tattırdın gittiğin o sabah.

Sabahlar da benzemez oldu birbirine gidişinle,

Sensiz geçen her sabah bana seni hatırlatıyor.

Şimdi başkalarında bulamiyorum tadını,

Dudaklarım bir başka dudakta seninkileri arıyor,

bedenim dokunuşunu özlüyor

sevişirken su gibi akıp geçen zaman 

Şimdi bir ömür uzuyor,

Sen gittin ya sevgili;

sabahların tadı artık eskisi gibi olmuyor....', 'O sabah bir başka güzeldi seninle  Sen vardın ya hayatımda, Boş ver kimseler arayıp sormasın, Kapımı kimseler çalmasın Bir tek sen yeterdin ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Tor']::text[], 8.5, '{"poet":"Tuğba Tor","poet_slug":"tugba-tor","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sabahlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemide isyan', 'gemide-isyan-murat-berke-lwt0u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzunsoluklu bir savaştan

Kendisini yenmiş

                         Gururlu ve vakur geliyordu

Günlerce At sürmüştü

Elinde yollar vardı derin uçurumlu

Birde atının dizgini 

Atının burnundan çıkan buhar 

Yakıyordu nefesini

Ama olsundu olsun varsındı

Uzun soluklu bir savaştan 

Kendisini yenmiş 

                        Gururlu ve vakur geliyordu', 'Uzunsoluklu bir savaştan Kendisini yenmiş                          Gururlu ve vakur geliyordu Günlerce At sürmüştü Elinde yollar vardı derin...', ARRAY['Türk Edebiyatı','Şiir','Murat Berke']::text[], 8.5, '{"poet":"Murat Berke","poet_slug":"murat-berke","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gemide-isyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Satır Yazı', 'bir-satir-yazi-bahadir-yalcin-ww8e0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kervan yükü acıların yüreğimde

Seni seçtiyse gözlerimin günahı ne

Ateş oldum,buz kestim senin bir sözüne

Dön artık delireceğim bu gidişle.

Gülen yüzüm bilesin en derin yasta

Sığıntı şimdi kalbim bir kaç anıya

Yağmur ol yağ istersen,rüzgar ol es

Bir satır yazı olsanda sen dön bana', 'Kervan yükü acıların yüreğimde Seni seçtiyse gözlerimin günahı ne Ateş oldum,buz kestim senin bir sözüne Dön artık delireceğim bu gidişle. G...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Yalçın']::text[], 8.5, '{"poet":"Bahadır Yalçın","poet_slug":"bahadir-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-satir-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevapsız Kalan Sualler', 'cevapsiz-kalan-sualler-abdurrahim-karakoc-k6bja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürü: duvar beton, otur yer beton 

Tavana bakarsın '' bakma der'' beton 

- Yağmur kokan toprakların nerede? .. 

Ne çiçekler açar, ne kuşlar öter 

Yolların on adım ötede biter 

- Serbest gezen ayakların nerede? .. 

Her günü hasrettir haftanın ayın 

Hani ya bayramın, düğünün, toyun? 

- İlin, yurdun, konakların nerede? .. 

Gönlün gamdan göçer, gama taşınır 

Boş direkler boynu bükük düşünür 

- Dalga dalga bayrakların nerede? .. 

Deprem mi geçirdin, talan mı gördün? 

Kanlı haydutlara haraç mı verdin? 

- Obaların ocakların nerede? .. 

İnancın cezalı, yüreğin tutsak 

Konuşacak yerde çaresiz susmak 

- Dudakların, dudakların nerede? 

(Suları Islatamadım)', 'Yürü: duvar beton, otur yer beton  Tavana bakarsın '' bakma der'' beton  - Yağmur kokan toprakların nerede? ..  Ne çiçekler açar, ne kuşlar öt...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cevapsiz-kalan-sualler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '50. Yıl Hesabı', '50-yil-hesabi-abdurrahim-karakoc-wudot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bağladım nefsimi zincir yulara 

Dünyayı duvara astım; gel de gör. 

Rahatı huzuru attım kenara 

Çileyi bağrıma bastım; gel de gör. 

Yürüdüm sel oldum, durdum göl oldum 

Mazluma, mağdura kıvrak dil oldum 

Zulüm sıcağında serin yel oldum 

Yürekten yüreğe estim; gel de gör. 

Sonu hatırladım, ilki duyunca

Kula kul olmadım ömür boyunca 

Hakkın zehirini içtim doyunca 

Batılın balına kustum; gel de gör. 

Ülfetim olmadı iriler ile 

Ağıla girmedim sürüler ile

Ölümden korkmayan diriler ile 

Selâmı, sabahı kestim; gel de gör. 

Aşk ceylanı emzirince sütünü 

Taşa çalıp, kırdım benlik putunu 

Düşmanımdır inkârcının bütünü 

Allah dostlarıdır dostum; gel de gör. 

Bazı kötülüğü kovdum elimle 

Bazı kötülüğü yerdim dilimle 

Gücüm yetmeyince kendi hâlimle 

Haksıza buğzettim, küstüm; gel de gör. 

Çıkar için lâf davulu çalmadım 

Hiçbir yerden makam, rütbe almadım 

Bildimse söyledim; korkak olmadım 

Bilmediğim yerde sustum; gel de gör.

(Suları Islatamadım)', 'Bağladım nefsimi zincir yulara  Dünyayı duvara astım; gel de gör.  Rahatı huzuru attım kenara  Çileyi bağrıma bastım; gel de gör.  Yürüdüm s...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/50-yil-hesabi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dünya Kimin Dünyası?', 'bu-dunya-kimin-dunyasi-abdurrahim-karakoc-ecp69', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yol üstünde biten çalı

Bu dünya kimin dünyası? 

Ak çiçekli ayva dalı

Bu dünya kimin dünyası? 

Gediklerde esen poyraz,

Yaprakları dalda koymaz

Gözler doysa gönül doymaz

Bu dünya kimin dünyası? 

Her gün eski her gün yeni

Tükenmez gidip geleni

Can evimden vurdu beni

Bu dünya kimin dünyası? 

Kar yağar kaybolur izler

Her nakış bin bir sır gizler

Ufuklara dalan gözler

Bu dünya kimin dünyası? 

Tüm nimetler talan talan..

Hızır bekler darda kalan.

Varı yalan, yoğu yalan

Bu dünya kimin dünyası? 

Toprak basar kucağına

Güneş çeker sıcağına

Atar derdin ocağına...

Bu dünya kimin dünyası? 

(Dosta Doğru)', 'Yol üstünde biten çalı Bu dünya kimin dünyası?  Ak çiçekli ayva dalı Bu dünya kimin dünyası?  Gediklerde esen poyraz, Yaprakları dalda koyma...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-dunya-kimin-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Doğru', 'dosta-dogru-abdurrahim-karakoc-b0p40', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde uzayan her yol 

Çıkar gider dosta doğru 

Nergis, ıtır, menekşe,  gül 

Kokar gider dosta doğru 

Zamanım yoğrulur gamla 

Birleşir sabah akşamla 

Ilık kanım damla damla 

Akar gider dosta doğru 

Gel bende gör, sen gel beni 

Durduramaz engel beni 

Görmediğim bir el beni 

Çeker gider dosta doğru 

Beynim fırın, bağrım tandır 

Yanarım hayli zamandır 

Sevgim bir yavru ceylandır 

Seker gider dosta doğru 

Ne saklarım, ne gizlerim 

Yalnızca Onu özlerim 

Tabutta bile gözlerim 

Bakar gider dosta doğru.

(Dosta Doğru)', 'İçimde uzayan her yol  Çıkar gider dosta doğru  Nergis, ıtır, menekşe,  gül  Kokar gider dosta doğru  Zamanım yoğrulur gamla  Birleşir sabah...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dosta-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gönül', 'ey-gonul-abdurrahim-karakoc-vvmk2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vardığın dergahta post ol, büyürsün

Gördüğün garibe dost ol, büyürsün

Meclise devam et, el sürme mey''e

Girdiğin sohbette mest ol, büyürsün.', 'Vardığın dergahta post ol, büyürsün Gördüğün garibe dost ol, büyürsün Meclise devam et, el sürme mey''e Girdiğin sohbette mest ol, büyürsün....', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ey-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğraf', 'fotograf-abdurrahim-karakoc-4oliy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Resmine baktığım güzel kız, genç kız

Unuttum, Unuttum, Unuttum seni..

Eski bir albümde durursun yalnız

Unuttum, Unuttum, Unuttum seni..

İki harf, bir imza, bir tarih; garip! 

Besbelli üçü de mutsuz, mustarip

Aklımı zorlama karşımda durup

Unuttum, Unuttum, Unuttum seni..

Bilemem aradan geçti kaç sene

Memleketin nere, kimsin, adın ne? 

''Hatırla'' diyerek bakma yüzüme

Unuttum, Unuttum, Unuttum seni..

(Suları Islatamadım)', 'Resmine baktığım güzel kız, genç kız Unuttum, Unuttum, Unuttum seni.. Eski bir albümde durursun yalnız Unuttum, Unuttum, Unuttum seni.. İki ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/fotograf-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi Seninle Tanıdım', 'sevgiyi-seninle-tanidim-unver-genc-k2rx5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni tanımadan önce adını sık sık duyduğum,

Seni tanıyana dek yokluğunun farkına bile varamadığım,

Seni tanıdıktan sonra eksikliğini hissettiğim,

Bu sonsuz sevgiyi bana yaşattığın için

Sana sonsuz teşekkürler...', 'Seni tanımadan önce adını sık sık duyduğum, Seni tanıyana dek yokluğunun farkına bile varamadığım, Seni tanıdıktan sonra eksikliğini hissett...', ARRAY['Türk Edebiyatı','Şiir','Ünver Genç']::text[], 8.5, '{"poet":"Ünver Genç","poet_slug":"unver-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgiyi-seninle-tanidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hudut Taşları', 'hudut-taslari-abdurrahim-karakoc-z0vox', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu bulanık hava,bu toprak, bu su

Beni benden, beni senden ayırır.

Bu sabahsız gece, bu düş, bu uyku

Beni benden, beni senden ayırır.

Doğmadık güneşin aydınlığında

Uzarsa gölgeler dost kılığında

Şüphe keleplenir gönül çığında

Beni benden, beni senden ayırır.

Doğrultmak istesem, kırılır dallar

Sınadım, zamana sığmadı yıllar

Bu dikenli yollar, bu taşlı yollar

Beni benden, beni senden ayırır.

Sevgi bulutundan rahmet damlası

Düşmeden, ayrılık doldurur tası.

Yoğun maddelerin ince mânâsı

Beni benden, beni senden ayırır.

Sen aşka hiç dersin, bense hayata..

Kim bilir, belki de bendedir hata.

Bu dalgalı deniz, bu yanlış rota

Beni benden, beni senden ayırır.

(Dosta Doğru)', 'Bu bulanık hava,bu toprak, bu su Beni benden, beni senden ayırır. Bu sabahsız gece, bu düş, bu uyku Beni benden, beni senden ayırır. Doğmadı...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hudut-taslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-oguzhan-aksoy-ae116', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlatamadım sevgimi, haykıramadım sana,

Belki gözlerinde boğulur, kaybolurum diye

Olmadı,bir türlü duyuramadım sesimi,

İspatlayamadım, belkide aşkımı sana...

Ayrılığınla yıkıldım, hasretinle tutuştum,

Özleminle kan ağladım, sabırsızdı akşamlar,

Anlamsızdı o gün herşey,

Anlamsızdı sözler, acımasızdı gözler,asılsızdı kelimeler...

Mesafelerdi aramıza giren,

Gözlerindi seni böyle delice sevdiren!

Görmek seni her zaman mümkün olsaydı...

Hayalinle ağladım, hayalinle sevindim,hayalinle yaşadım...

Umutsuzca bekledim, ismini haykırdım çığlık çığlık,

Belki bir gün duyarsın diye

Issız bir çölde serabını aradım,

Bir anda olsa seni, görebileyim diye!

Geceye inat yıldızlar karardı o gece,

Bir hüzün veriyordu sanki rüzgar,

Ay bile matemliydi o gece...

Bir kabustu sanki herşey,

Uyanmaktı tek dileğim,

Sevgindi senden tek isteğim!', 'Anlatamadım sevgimi, haykıramadım sana, Belki gözlerinde boğulur, kaybolurum diye Olmadı,bir türlü duyuramadım sesimi, İspatlayamadım, belki...', ARRAY['Türk Edebiyatı','Şiir','Oğuzhan Aksoy']::text[], 8.5, '{"poet":"Oğuzhan Aksoy","poet_slug":"oguzhan-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ozlem-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam ve Ben', 'sevdam-ve-ben-abdurrahim-karakoc-qprtn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey SEVDAM! Nerede kucaklaştık seninle,

Ne zaman dolduk, ne zaman taştık seninle? 

Beklediğimiz sabahları görmeden

Bak... Bak işte mezara yaklaştık seninle.

(Gökçekimi)', 'Ey SEVDAM! Nerede kucaklaştık seninle, Ne zaman dolduk, ne zaman taştık seninle?  Beklediğimiz sabahları görmeden Bak... Bak işte mezara yak...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevdam-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suları Islatamadım', 'sulari-islatamadim-abdurrahim-karakoc-qxzj4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Savaştayım elli yıldır 

Ömrüm geçti boşalt, doldur 

Anlamadım bu ne hâldir 

Bir gün silah çatamadım 

    Suları ıslatamadım. 

Ekin ektim başak yılan 

Kuşandığım kuşak yılan 

Yorgan akrep, döşek yılan 

Bir gün rahat yatamadım 

    Suları ıslatamadım. 

Ne payem oldu, ne sayem 

En doğruya varmak gayem 

Düşüncemdir tek sermayem 

Alan yoktur satamadım 

    Suları ıslatamadım. 

Yolum yokuş, izim ayrı 

Dilim yağsız, sözüm ayrı 

Bedenimden özüm ayrı 

Biri bire katamadım 

    Suları ıslatamadım. 

Talipli yoktur sevgiye 

Anlamadım, neden? Niye? 

Canlar gücenmesin diye 

Can attım, gül atamadım 

    Suları ıslatamadım.

(Suları Islatamadım)', 'Savaştayım elli yıldır  Ömrüm geçti boşalt, doldur  Anlamadım bu ne hâldir  Bir gün silah çatamadım      Suları ıslatamadım.  Ekin ektim baş...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sulari-islatamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvarış', 'yalvaris-abdurrahim-karakoc-x28cd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ya Rab bu hasrete can dayanmıyor; 

Zaman kısa, ben yorgunum, yol uzun.

Her adımda bir engel var, salmıyor,

Zaman kısa, ben yorgunum, yol uzun.

Mümkün mü bu yolda maksuda ermek? 

Mümkün mü sılada dost yüzü görmek? 

Âşıka ar gelir geriye dönmek; 

Zaman kısa, ben yorgunum, yol uzun.

Çekilmez bir şelek vurdun arkama; 

Şaşırdım yollarda kaldım, akşama.

Umudum her zaman bakidir amma,

Zaman kısa, ben yorgunum, yol uzun.

Sevip sevilmemek varsa kaderde,

Hangi doktor ilaç verir bu derde? 

Hastayım, susuzum gurbet illerde; 

Zaman kısa, ben yorgunum, yol uzun.

Ey hanlar hanını halk eden Hancı! 

Bir yudum aşkınla doğdu bu sancı.

Ey fakir ekmeği, Mümin inancı! 

Zaman kısa, ben yorgunum, yol uzun.

(Dosta Doğru)', 'Ya Rab bu hasrete can dayanmıyor;  Zaman kısa, ben yorgunum, yol uzun. Her adımda bir engel var, salmıyor, Zaman kısa, ben yorgunum, yol uzu...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalvaris-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmge Dedim Adına', 'i-mge-dedim-adina-adnan-yucel-4jlun', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son çocukluk da bitmişti ömrümde 

Düşlerim belki kış ölüsü belki yaz 

Kırlara bahar yetmese de içimde 

Yüreğim nar çatlamasıydı sana kadar 

Dilimde sözcüklerin çelik dinerci 

Sesimde ölüm rengine inat aşklar 

Mavilikler yasaklandı gökyüzünde 

Özgürlüğü kuş kanatlarında bekledim 

Doğduğum gün adına ''imge'' dedim 

Sevdim bütün insanları insan yanlarını 

Sen de seveceksin 

Dallarına su yürümüş ağaçlara güleceksin 

Kar yağsa da yaktığn ateşler üstüne 

Ateşi yüreğinle körükleyeceksin 

Kuş sesleri de ertelenebilir güne karşı 

Çiy de düşebilir anıların üstüne 

En güzel ezgileri nehirağzı denizlerde 

Hep kendi sesinle türküleyeceksin 

Hüzün ağaçlarının sevinç açtığını 

Adının sonsuz anlamında göreceksin 

Sevdim soluğunu rüzgar kılan insanları 

Soluğumu soluklarına kattım 

Bir damla uğruna gökyüzünü omuzladım 

Bir çocuk ölümleri ağlattı beni 

Bir de türkülerde kalabalık ihanetler 

Gülüp geçtim yalan iktidarlar görkemine 

Aşk adına sesimi sürdüm namlulara 

En büyük eylemleri söz eyledim 

Doğduğun gün adına ''imge'' dedim 

Sen elbette sen olacaksın biliyorum 

Sesinde yirmibirinci yüzyılı dinliyorum', 'Son çocukluk da bitmişti ömrümde  Düşlerim belki kış ölüsü belki yaz  Kırlara bahar yetmese de içimde  Yüreğim nar çatlamasıydı sana kadar  ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yücel']::text[], 8.5, '{"poet":"Adnan Yücel","poet_slug":"adnan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/imge-dedim-adina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kriz', 'son-kriz-tayfun-yahsi-njza0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen kriz geçirdiğinde

İnegöl köftecisinin camına yapışmıştım

Yemek ne gezer

Turşularını sayıyordum herbir porsiyonun 

Ne çok sevdiğini o an hatırladım, 

Dürüstçe,

Bir tanesini senin için arakladım.

Ve duvarda bir resim vardı

Doğrusu aykırıydı, hiç yakışmıyordu düşündüklerimize

Yine de bir kez daha bakamadan edemedim 

Beynime kazıdığım görüntüsüne.

Sen hastaneye koşturulduğunda,

Bir çingene falıma yapışmıştı.

Elimden akacak ya geleceğim

Öylesine heyacanlı, 

Çizgi çizgiydim, al al ve tombul, damarsız

Kararsız. 

Dürüstçe, çoktan razıydım yalanlarına, 

Ömrümün uzunluğuna, gecenin karanlığına

Yine de hoşlanacağın bir şeyleri

Söylemesini isterdim, ölümün yararına

Sen yoğun bakımdayken ben bir taydım,

Adsız-zamansız bir bozkırda, acemi

Ama ivecen

Koşacağı yönü bilmeyen

Bir taydım

Yürüdükçe genişleyip büyüyen,

Varıldıkça ırayan,

Bu bozkırda yalnızdım.

Sen makinaya bağlandığında

Ben dipsiz kuyulardaydım,

Ve muhtemelen öldüğümde

Oradan kaçacaksın.', 'Sen kriz geçirdiğinde İnegöl köftecisinin camına yapışmıştım Yemek ne gezer Turşularını sayıyordum herbir porsiyonun  Ne çok sevdiğini o an ...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Yahşi']::text[], 8.5, '{"poet":"Tayfun Yahşi","poet_slug":"tayfun-yahsi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/son-kriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülker''in Gözleri', 'ulker-in-gozleri-ahmet-muhip-diranas-m5kfu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahar sabahının karanlığında ıssız 

Gökte diz çökmüş iki titrek ışıklı yıldız 

Olan gözleinize aşıkım, Bayan ülker! 

Mutlu, esen ve hoşken ve 
..........
..........', 'Bir bahar sabahının karanlığında ıssız  Gökte diz çökmüş iki titrek ışıklı yıldız  Olan gözleinize aşıkım, Bayan ülker!  Mutlu, esen ve hoşk...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dıranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dıranas","poet_slug":"ahmet-muhip-diranas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ulker-in-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-sezai-karakoc-ojbko', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğuda bir baba vardi

Batı gelmeden önce

Onun oğullari batıya vardı

Birinci oğul batı kapılarında

Büyük törenlerle karşılandı

Sonra onuruna büyük şölen verdiler

Söylevler söylediler babanın onuruna

Gece olup kuştüyü yastıklar arasında

Oğul masmavi şafağin rüyasında

Bir karaltı yavaşça tüy gibi daldı içeri

Öldürdüler onu ve gömdüler kimsenin bilmediği bir yere

Baba bunu havanın ansızın kabaran gözyaşından anladı

Öcünü alsın diye kardeşini yolladı

                               

İkinci oğul Batı ülkesinde

Gezerken bir ırmak kıyısında

Bir kıza rastladı dağların tazeliginde

Bal arılarının taşıdığı tozlardan

Ayna hamurundan ay yankısından

Samanyolu aydınlığından inci korkusundan 

Gül tütününden doğmuş sanki

Anne doğurmamış da gök doğurmuş onu

Saçlarını güneş destelemiş

Yıllarca peşinden koştu onun

Kavuşamadı ama ona

Batı bir uçurum gibi girdi aralarına

Sonra bir kış günü soğuk bir rüzgâr 

Alıp götürdü onu

Ve ikinci oğulu

Sivri uçurumların ucunda

Buldular onulmaz çılgınlıkların avucunda

Baba yağmurlardan anladı bunu

Yağmur suları aci ve buruktu

İşin künhüne varsın diye

Yolladı üçüncü oğlunu

                                           

Üçüncü oğul Batıda

Çok aç kaldı ezildi yıkıldı

Ama bir iş buldu bir gün bir mağazada

Açlığı gidince kardeşlerini arayacaktı

Fakat batinin büyüsü ağır bastı

İş çoktu kardeşlerini aramaya vakit bulamadı

Sonra büsbütün unuttu onları

Şef oldu buyruğunda birçok kişi

Kravat bağlamasını öğrendi geceleri

Gün geldi mağazası oldu onu parmakla gösterdiler

Patron oldu ama hala uşaktı

Ruhunda uşaklık yuva yapmıştı çünkü

Bir gün bir hemşehrisi onu tanıdı bir gazinoda

Ondan hesap sordu o da

Sırf utançtan babasına

Bir çek gönderdi onunla

Baba bu kağıdın neye yarayacağını bilemedi

Yırttı ve oynasınlar diye köpek yavrularına attı

Bu yüklü çeki

İyice yaşlanmıştı ama

Vazgeçmedi koyduğundan kafasına

Dördüncü oğlunu gönderdi Batıya

                                          

Dördüncü oğul okudu bilgin oldu

Kendi oymak ve ülkesini

Kendi görenek ve ülküsünü

Günü geçmiş bir uygarlığa yordu

Kendisi bulmuştu gerçek uygarlığı

Batı bilginleri bunu kutladı

O da silindi gitti binlercesi gibi

Baba bunu da öğrendi sihirli tabiat diliyle

Kara bir süt akmıştı bir gün evin kutlu koyunundan

                                                         

Beşinci oğul bir şairdi

Babanın git demesine gerek kalmadan

Geldi ve batının ruhunu sezdi

Büyük şiirler tasarladı trajik ve ağır

Batının uçarılığına ve doğunun kaderine dair

Topladı tomarlarını geri dönmek istedi

Çöllerde tekrar ede ede şiirlerini

Kum gibi eridi gitti yollarda

                                                          

Sıra altıncı oğulda

O da daha batı kapılarında görünür görünmez

Alıştırdılar tatlı zehirli sulara

Içkiler içti

Kaldırım taşlarını saymaya kalktı

Ev sokak ayırmadi

Geceyi gündüzle karıştırdı

Kendisi de bir gün karıştı karanlıklara

Baba ölmüştü acısından bu ara

                                                    

Yedinci oğul büyümüştü baka baka ağaçlara

Baharın yazın güzün kışın sırrına ermişti ağaçlarda

Bir alinyazısı gibiydi kuruyan yapraklar onda

Bir de o talihini denemek istedi

Bir şafak vakti Batıya erdi

En büyük Batı kentinin en büyük meydanında

Durdu ve tanrıya yakardı önce

Kendisini değistiremesinler diye

Sonra ansızın ona bir ilham geldi

Ve başladı oymaya olduğu yeri

Başına toplandı ve baktılar Batılılar

O aldırmadı bakışlara

Kazdı durmadan kazdı

Sonra yarı beline kadar girdi çukura

Kalabalık büyümüş çok büyümüştü

O zaman dönüp konuştu :

Batılılar !

Bilmeden

Altı oğlunu yuttuğunuz 

Bir babanın yedinci oğluyum ben

Gömülmek istiyorum buraya hiç değişmeden

Babam öldü acılarından kardeşlerimin

Ruhunu üzmek istemem babamın

Gömün beni değiştirmeden

Doğulu olarak ölmek istiyorum ben

Sizin bir tek ama büyük bir gücünüz var :

Karşınızdakini değistirmek

Beni öldürseniz de çıkmam buradan

Kemiklerim değişecek toz ve toprak olacak belki

Fakat değişmeyecek ruhum

Onu kandırmak için boşuna dil döktüler

Açlıktan dolayı çıkar diye günlerce beklediler

O gün gün eridi ama çıkmadı dayandı

Bu acıdan yer yarıldı gök yarıldı

O nurdan bir sütuna döndü göğe uzandı

Batı bu sütunu ortadan kaldırmaktan aciz kaldı

Hâlâ onu ziyaret ederler şifa bulurlar

En onulmaz yarası olanlar

Ta kalblerinden vurulmuş olanlar

Yüreğinde insanlıktan bir iz tasıyanlar', 'Doğuda bir baba vardi Batı gelmeden önce Onun oğullari batıya vardı Birinci oğul batı kapılarında Büyük törenlerle karşılandı Sonra onuruna ...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":122,"source_url":"https://www.antoloji.com/masal-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-cemal-sureya-95c3h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülün tam ortasında ağlıyorum

Her akşam sokak ortasında öldükçe

Önümü arkamı bilmiyorum

Azaldığını duyup duyup karanlıkta

Beni ayakta tutan gözlerinin

Ellerini alıyorum sa
..........
..........', 'Gülün tam ortasında ağlıyorum Her akşam sokak ortasında öldükçe Önümü arkamı bilmiyorum Azaldığını duyup duyup karanlıkta Beni ayakta tutan ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gul-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garibin Sevmesi', 'garibin-sevmesi-elbeyli-osman-8ut3k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Engeller vardır dağ gibi aşılmaz

Deli Fırattır  yol verip geçilmez

Ferhat ile şirin olsa böyle sevilmez

Garibin sevmesi bir ulu dağa benzer

Bir kere sever sonu topraktır

Sevdiği gül ise o dalında yapraktır

Onu yaşatan yüreğindeki ahlaktır

Garibin sevmesi aşk ile yanmaya benzer

Aranırsa aşkta meşkte bulunur

Uğrunda ağlanır yada gülünür

On defa değil bir defa ölünür

Garibin sevmesi ölmeye benzer', 'Engeller vardır dağ gibi aşılmaz Deli Fırattır  yol verip geçilmez Ferhat ile şirin olsa böyle sevilmez Garibin sevmesi bir ulu dağa benzer ...', ARRAY['Türk Edebiyatı','Şiir','Elbeyli Osman']::text[], 8.5, '{"poet":"Elbeyli Osman","poet_slug":"elbeyli-osman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garibin-sevmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Envanter', 'envanter-ahmet-oktay-sbdss', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok az sey saklamisim yasamimda ; 

ne bir fotograf var ilk asklardan 

ne bir mektup, 

dostlardan bes on tane ; 

sunlari yazmis Stockholm''den 

Demir Özlü 1983''te : 

''rahmetli Çigiltepe''nin oglunu gördüm 

geçenlerde Helsinki''de, 

sürüyorum geçmisin izlerini''. 

Hangi izlerin pesinden gittim ben 

içimde bir mahser beklentisi ? 

Çok az sey biriktirmisim yasamimda ; 

hiçbir andaç yok babamdan, 

verd
..........
..........', 'Çok az sey saklamisim yasamimda ;  ne bir fotograf var ilk asklardan  ne bir mektup,  dostlardan bes on tane ;  sunlari yazmis Stockholm''den...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Oktay']::text[], 8.5, '{"poet":"Ahmet Oktay","poet_slug":"ahmet-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/envanter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeleri Kullanmak', 'golgeleri-kullanmak-ahmet-oktay-jb9zt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte bir ses geçiyor sıkıntıdan 

baksam pencerede yağmur da var, 

hani saçlarını ya da göğsünü 

çok ince bir hüzünle bezeyen. 

Oyuncaklar da var yalnızlıktan 

bir parkta ölümü güzel kılar, 

hani sarmaşıkça uzandığın yatakta 

durmadan aşıladığım sana. 

Hayır yaşamıyor suda o balık, 

bir yanıltı daha çiçek aldığım. 

Herkesin b
..........
..........', 'İşte bir ses geçiyor sıkıntıdan  baksam pencerede yağmur da var,  hani saçlarını ya da göğsünü  çok ince bir hüzünle bezeyen.  Oyuncaklar da...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Oktay']::text[], 8.5, '{"poet":"Ahmet Oktay","poet_slug":"ahmet-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/golgeleri-kullanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-elbeyli-osman-rws2f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şeyler eksik, hissedebiliyorum.

Yerini doldurmak güç

Adını bile bilmiyorum

Sırf o olmadığı için

Bazen ağlamak geliyor içimden

Bazen düşünmekten ağrıyan kafamı

Koparıp atmak

Bazen acılı dertli şarkılar söylemek....

Ama olmuyor....

Dolduramıyorum yerini

Çalışıyor çabalıyorum

Bazen can çekişir gibi çırpınıyorum

Kafam patlıyor düşüncelerden

Bağırmak istiyorum

“Nesin sen”  diye haykırmak

Sonra gözlerim ıslanıyor

Ve ellerimin titrediğini hissediyorum

Bir dost arıyorum

Anlatırsam rahatlarım diye

Ama yok  işte

Kimseyi bulamıyorum

Bulduklarımda beni anlamıyor .. .

Çaresiz dönüyorum kendime

Özümde arıyorum derdimi

Kendi kendime anlatıyorum kendimi

Artık dayanamayıp

Zaman zaman ağlıyorum

Bazen deli oluyor

Bağırıp çağırırken

Abuk sabuk işler yapıyorum

Ama yine olmuyor......

Hala o eksik .. .

Ve hala ismini bile bilmiyorum .. ..

Kolum kanadım kırılıyor

Vazgeçiyorum arayıştan

Sonra bir kalem,

Ve bir kağıt alıyorum elime

Kurt gibi aç bir çocuğun

Anasını emdiği gibi kapanıyorum kağıda

Eksikliği yazıyorum.

Göz yaşlarımı  ,

Çırpınışlarımı ...

Ve ...

Arayışı ....', 'Bir şeyler eksik, hissedebiliyorum. Yerini doldurmak güç Adını bile bilmiyorum Sırf o olmadığı için Bazen ağlamak geliyor içimden Bazen düşü...', ARRAY['Türk Edebiyatı','Şiir','Elbeyli Osman']::text[], 8.5, '{"poet":"Elbeyli Osman","poet_slug":"elbeyli-osman","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/arayis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
