INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-elbeyli-osman-kcsbh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün gelirde gurbet ele gidersem

Sen ağlama ardımdan , ben ağlarım annem

Senin şefkatinden ayrı düşersem

Sen ağıt yakma , ben yakarım annem

Ararda bulamazsan beni evde

Uzun boylunu göremezsen gözlerinle

“Oğlum” deyip saramazsan kucağına

Sen üzülme , ben üzülürüm annem

Hayal edip anarsan benli günleri

Duymak istersen “anam” diyen sesleri

Çok isterde aşamazsan engelleri

Sen isyan etme, ben ederim annem

Hakkı söyledim diye yaktılar beni

Bir küçük bedele sattılar beni

Ne olur ıslatma o güzel gözleri

Sen ağlarsan ben ölürüm annem

Yalan dünya bu gelen geçer

Hakkı bilen hep O yolu seçer

Uzaktan beni güldürmek istersen eğer

Zulmedenlere bakar gibi ,

Anne sevgisiyle onları yakar gibi,

Bir şimşek olup,

Hakkı kafalarına çakar gibi,

Kaldır mübarek elini

“ALLLAHUEKBERRR!”  de annem

Ellerinden öperim annem......', 'Bir gün gelirde gurbet ele gidersem Sen ağlama ardımdan , ben ağlarım annem Senin şefkatinden ayrı düşersem Sen ağıt yakma , ben yakarım ann...', ARRAY['Türk Edebiyatı','Şiir','Elbeyli Osman']::text[], 8.5, '{"poet":"Elbeyli Osman","poet_slug":"elbeyli-osman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/annem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyi Bitirdik', 'her-seyi-bitirdik-ahmet-selcuk-i-lkan-kgyuc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şeyi bitirdik  bir yalan gibi

Bu aşkı yarına götüremedik

Ne günler yaşadık bir roman gibi 

Ne yazık sonunu getiremedik

Önce evet dedik bu hayır neden 

Biz aşkla başladık bu gurur neden 

Ümitler sendendi arzular benden 

Ne yazik sonunu getiremedik

Şimdi sen yolcusun meçhul yollara

Şimdi ben yolcuyum başka kollara 

Ne desek boş artık geçen  yıllara

Ne yazık sonunu getiremedik

Bu aşkı yarına götüremedik

Ahmet Selçuk İLKAN', 'Her şeyi bitirdik  bir yalan gibi Bu aşkı yarına götüremedik Ne günler yaşadık bir roman gibi  Ne yazık sonunu getiremedik Önce evet dedik b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/her-seyi-bitirdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül Olan', 'kul-olan-ahmet-telli-mxa7o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kentte sorular yasaklanmıştır

böyle diyorlar fısıldarcasına ve ürkek

ve diyorlar ki gidip anlatılsın bir kez

çare düünsün tarih denilen bilici

Gidip anlatılsın beklenen yolculara

aşklar küllenmeden ve beynimizi

büsbütün kemirmeden veba

yetişsin durmadan yolu gözlenen

Bu kentin sorusunu yanıtla ey yanılmaz olan

kahret ya da ışıklandır ve de ki:

-Siz ki yangın yıllarından geliyorsunuz

umuda bağlanmak umutsuzluktur ancak

Ve sen ey bilici, de ki:

-Bu masal çok anlatıldı önceleri

çocuklar da susturuldu her defa

karartıldı evlerin bütün ışıkları

-Ve direnmeyi bilmiyorsanız

kül olun savrulun dağlara taşlara

belki hayat yeniden fışkıracaktır o zaman

bu kentin ışıksız varoşlarından

Bir sfenksten söz ediliyor durmadan

yakınmış kahredilmesi', 'Bu kentte sorular yasaklanmıştır böyle diyorlar fısıldarcasına ve ürkek ve diyorlar ki gidip anlatılsın bir kez çare düünsün tarih denilen b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kul-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayalım Atatürk''e', 'aglayalim-ataturk-e-asik-veysel-satiroglu-xalf6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlayalım Atatürk''e

Bütün dünya kan ağladı

Başbuğ olmuştu mülke

Geldi ecel can ağladı

Şüphesiz bu dünya fani

Tanrı''nın aslanı hani

İnsi cinsi cem''i mahluk

Hepsi birden ağladı

Doğu batı cenup şimal

Aman tanrım bu nasıl hal

Atatürk''e erdi zeval

Amir memur altın kürsü

Yas çekip mebsan* ağladı

İskender-i Zülkarneyin

Çalışmadı bunca leğin

Her millet Atatürk deyin

Cemiyet-i akvam ağladı

Atatürk''ün eserleri

Söylenecek bundan geri

Bütün dünyanın her yeri

Ah çekti vatan ağladı

Fabrikalar icat etti

Atalığın ispat etti

Varlığın Türk''e terk etti

Döndü çark devran ağladı

Bu ne kuvvet bu ne kudret

Vardı bunda bir hikmet

Bütün Türkler İnönü İsmet

Gözlerinden kan ağladı

Tren hattı tayyareler

Türkler giydi hep karalar

Semerkand''ı Buhara''lar

İşitti her yan ağladı

Siz sağ olun Türk gençleri

Çalışanlar kalmaz geri

Mareşal Fevzi''nin askerleri

Ordular teğmen ağladı

Zannetme ağlayan gülmez

Aslan yatağı boş kalmaz

Yalınız gidenler gelmez

Felek-el mevt''in elinden

Her gelen insan ağladı

Uzatma Veysel bu sözü

Dayanmaz herkesin özü

Koruyalım yurdumuzu

Dost değil düşman ağladı', 'Ağlayalım Atatürk''e Bütün dünya kan ağladı Başbuğ olmuştu mülke Geldi ecel can ağladı Şüphesiz bu dünya fani Tanrı''nın aslanı hani İnsi cins...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/aglayalim-ataturk-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beserek Dağı', 'beserek-dagi-asik-veysel-satiroglu-q55up', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arzusun çektiğim Beserek Dağı

Elvan elvan çiçeklerin açtı mı? 

Çevre yanın güzellerin otağı,

Bizim eller yaylasına göçtü mü? 

Güney tarafında Kurban Pınarı,

Kalktı mı Mezarlı Boyu''nun karı? 

Garip öter meşeliğin kuşları,

Yavru şahin yuvasından uçtu mu? 

Yeşil atlas giymiş dağlar süslemiş,

Mescit köyü eteğine yaslanmış,

Şeme Dağı, duman olmuş puslanmış,

Sivralan''a nuru rahmet saçtı mı? 

Zaman gelip göçler geri dönerken,

Güzellerin yaylasından inerken,

Dilberler doldurup bade sunarken,

Veysel Şatır, hatırlara düştü mü?', 'Arzusun çektiğim Beserek Dağı Elvan elvan çiçeklerin açtı mı?  Çevre yanın güzellerin otağı, Bizim eller yaylasına göçtü mü?  Güney tarafınd...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beserek-dagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Birlik Kavline Girelim Kardeş', 'gel-birlik-kavline-girelim-kardes-asik-veysel-satiroglu-mlhzp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İtimat edersen benim sözüme

Gel birlik kavline girelim kardaş

Birlik çok tatlıdır, benzer üzüme

İçip şerbetini duralım kardaş.

Son verelim iftiraya bühtana

Kardeşane sevişelim can cana

Elbirlikle çalışalım vatana

Çok okul, fabrika kuralım kardaş.

Yürüyelim Atatürk''ün izine

Boş verelim bozguncular sözüne

Göz atalım şu dünyanın hızına

Yürüyüp hedefe varalım kardaş.

Veysel''in sözleri kanun dışı mı?

Mantığa uymazsa kesin başımı

Bana düşman etmiş vatandaşımı

Sebebi ne ise soralım kardaş.', 'İtimat edersen benim sözüme Gel birlik kavline girelim kardaş Birlik çok tatlıdır, benzer üzüme İçip şerbetini duralım kardaş. Son verelim i...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-birlik-kavline-girelim-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Bana Yakın Yar Bana Uzak', 'hayal-bana-yakin-yar-bana-uzak-asik-veysel-satiroglu-b0jap', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayal bana yakın yar bana uzak 

Sevdası başıma dolanır gitmez 

Aşkına düşeli yar bana uzak 

Yüz bin öğüt versen biri kar etmez

Senin aşkın beni kıldı urusvay 

Düşmüşüm peşinde koşarım hay hay 

Kabul et kapında beni de kul say 

Dost yoluna ölür aşık ar etmez 

Ey beni bu derde giriftar eden 

Eski muhabbeti kaldırdın neden 

Gönül ister kavuşmayı ölmeden 

Gül olmasa bülbül ah u zar etmez

Beni yakan yansın aşkın narına 

Gönül düştü bir zalimin toruna 

Bakmaz mısın bu Veysel''in zarına 

Ah çeker ağlarım yar elim yetmez.', 'Hayal bana yakın yar bana uzak  Sevdası başıma dolanır gitmez  Aşkına düşeli yar bana uzak  Yüz bin öğüt versen biri kar etmez Senin aşkın b...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayal-bana-yakin-yar-bana-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşim', 'kardesim-asik-veysel-satiroglu-dlfh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni hor görme kardeşim

Sen altınsın ben tunç muyum?

Aynı vardan var olmuşuz

Sen gümüşsün ben saç mıyım?

Ne var ise sende bende

Aynı varlık her bedende

Yarın mezara girende

Sen toksun da ben aç mıyım?

Topraktandır cümle beden

Nefsini öldür ölmeden

Böyle emretmiş yaradan

Sen kalemsin ben uç muyum?

Tabiata Veysel aşık

Topraktan olduk, kardaşık.

Aynı yolcuyuz yoldaşık

Sen yolcusun ben bac mıyım', 'Beni hor görme kardeşim Sen altınsın ben tunç muyum? Aynı vardan var olmuşuz Sen gümüşsün ben saç mıyım? Ne var ise sende bende Aynı varlık ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kardesim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar', 'aksamlar-hasan-kaya-corlulu-dyaoa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgili Dostuma,

Rengarenk akşamların hüzünlü bir anında

Tatlı anılarımla ağlamak istiyorum.

Lakin;

Renksiz bu akşam

Gözlerim bir tuhaf

Kupkuru

İçimden ağlıyorum.

1984 Çorlu', 'Sevgili Dostuma, Rengarenk akşamların hüzünlü bir anında Tatlı anılarımla ağlamak istiyorum. Lakin; Renksiz bu akşam Gözlerim bir tuhaf Kupk...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaya Çorlulu']::text[], 8.5, '{"poet":"Hasan Kaya Çorlulu","poet_slug":"hasan-kaya-corlulu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aksamlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acının Duvarı Aşılınca', 'acinin-duvari-asilinca-aziz-nesin-gubzs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendisi çatlamadan 

Toprağı çatlatamaz tohum 

Asmışım sinirini mutsuzluğun 

Ayrımsayamıyorum bile öyle mutsuzum 

Acısını artık duyamıyorum 

Ki kendim öyle bir acı olmuşum 

Nasıl görmezse göz kendini 

Kendimi arıyor bulamıyorum.', 'Kendisi çatlamadan  Toprağı çatlatamaz tohum  Asmışım sinirini mutsuzluğun  Ayrımsayamıyorum bile öyle mutsuzum  Acısını artık duyamıyorum  ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesin']::text[], 8.5, '{"poet":"Aziz Nesin","poet_slug":"aziz-nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/acinin-duvari-asilinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Gelmiş Cihana', 'ask-gelmis-cihana-behcet-necatigil-m8axj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kız kaptırdı gönlünü

Sevdiği oğlan kalpsizin biri

Alay etti güld
..........
..........', 'Kız kaptırdı gönlünü Sevdiği oğlan kalpsizin biri Alay etti güld .......... .............', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-gelmis-cihana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-tuncer-oral-6wc2d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeni umutlarla doğmak varken

Her sabah,

Biz kolay olanı seçtik,

Işıkları söndürdük yatarken.

Oysa,

İkimizde zoru ne çok severdik', 'Yeni umutlarla doğmak varken Her sabah, Biz kolay olanı seçtik, Işıkları söndürdük yatarken. Oysa, İkimizde zoru ne çok severdik...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/umut-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sandalyemde Özgürüm', 'sandalyemde-ozgurum-onur-atasayar-vzoji', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özgürüm tekerlekli sandalyemde

 Umut doluyum

 Yaşamayı seviyorum

 Hayallerim büyük,hayallerim güçlü

 Aramıyorum yaşantımda suçlu(!)

 Özgürlük yaşantımın bir parçası olmuş

 Gidiyorum bazen ufuklara sensiz

 Gözlerin geliyor aklıma

  Özgür değilsin bensiz

  Tekerlekli sandalyemde sınırları aşarım

  Bütün zorlukları aştığım gibi 

  Hiçbir engel bana sınır olamaz

  Ne sandalye,ne masa

 Ah şu merdivenler olmasa

   (25-Aralık-1999)', 'Özgürüm tekerlekli sandalyemde  Umut doluyum  Yaşamayı seviyorum  Hayallerim büyük,hayallerim güçlü  Aramıyorum yaşantımda suçlu(!)  Özgürlü...', ARRAY['Türk Edebiyatı','Şiir','Onur Atasayar']::text[], 8.5, '{"poet":"Onur Atasayar","poet_slug":"onur-atasayar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sandalyemde-ozgurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13-2', '13-2-tahir-ehad-ozar-ctncw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'duygularıma yön veren

üç kadına

anneme

sevgilime

ve tanımadığım halde

aşık olduğum fahişeye

aldığım tüm lanetleri

borç veriyorum', 'duygularıma yön veren üç kadına anneme sevgilime ve tanımadığım halde aşık olduğum fahişeye aldığım tüm lanetleri borç veriyorum...', ARRAY['Türk Edebiyatı','Şiir','Tahir Ehad Ozar']::text[], 8.5, '{"poet":"Tahir Ehad Ozar","poet_slug":"tahir-ehad-ozar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/13-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13-3', '13-3-tahir-ehad-ozar-9483l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'umutlarım kadar karamsar

damarlarımdaki kan gibi 

asice gel

çıkar çıplak bedenindeki elbiseni

rüzgara karşı dur

sesini duyurabilirsen

meydan oku hayata

yık içinde kalan tabuları

kurtul nefes almaktan', 'umutlarım kadar karamsar damarlarımdaki kan gibi  asice gel çıkar çıplak bedenindeki elbiseni rüzgara karşı dur sesini duyurabilirsen meydan...', ARRAY['Türk Edebiyatı','Şiir','Tahir Ehad Ozar']::text[], 8.5, '{"poet":"Tahir Ehad Ozar","poet_slug":"tahir-ehad-ozar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/13-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Gelmez', 'zor-gelmez-adem-i-ris-p1teq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zor gelmez adına sünger çekmek

Büyük acılar bana zor gelmez

Yeniden aşık olmak ne kadar güzel

Eski aşklar gibi zor gelmez

Ben ne acılar çektim

Ne fırtınalarda yoruldum ne ateşlerde eridim

Ben seni sevdim!..

Dünyanın yükü de olsa

Artık bana zor gelmez

Adını duvarlardan silmek kolay

Bir daha yazmak ne de zor

Hani ayrılıktı ateşten kor

Kara talih buysa bana zor gelmez

Ben artık seni kalbime gömdüm

Deseler sanki dünyadan oldun

Ben İÇİMDEKİ SENİ unuttum

Seni unutmak zor gelmez', 'Zor gelmez adına sünger çekmek Büyük acılar bana zor gelmez Yeniden aşık olmak ne kadar güzel Eski aşklar gibi zor gelmez Ben ne acılar çekt...', ARRAY['Türk Edebiyatı','Şiir','Adem İriş']::text[], 8.5, '{"poet":"Adem İriş","poet_slug":"adem-i-ris","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zor-gelmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamburg''a Bu Geliş', 'hamburg-a-bu-gelis-kamil-serdengecti-n3bl8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi  bir esrik zaman rüzgârı

Bulutları aşar da

Dönen bulutları, koşan bulutları

Ve bir taze çam buğularına dolu dolu

Yürekler dolu ikindi yağmurları

Gölgesiz, koyu, gri yeşiller ülkesiydi

Bulutlar ötesi yâd eller,

Zaman aşımlarının

Serin solukları

Biz inerdik bir rüya gibi

Esrik, savruk ve koyu gri

Yağmur tüllerinden renklerce

Alster kıyısından yukarı doğru

Binbir çiçek kokuları

Ve ıslak özveriler ardından

Bir ilk umut gibi

Bağrına Hamburg

Ve o titreşimler iliklerimize

Ilık yaz nefesleri

Kuzey denizlerinden

Sakin zaman dilimleri

Bir ikindi vakti küçük adımlarla

Yürür, yürür giderdik.', 'Şimdi  bir esrik zaman rüzgârı Bulutları aşar da Dönen bulutları, koşan bulutları Ve bir taze çam buğularına dolu dolu Yürekler dolu ikindi ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Serdengeçti']::text[], 8.5, '{"poet":"Kamil Serdengeçti","poet_slug":"kamil-serdengecti","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hamburg-a-bu-gelis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekteki Çürükler', 'yurekteki-curukler-baris-ozkaya-w16c0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürekteki çürükler 

Ağır bir sancı 

Geminin güvertesinden 

Kusulmak istenen 

Yürekteki çürükler 

Belleğin gelgitlerinde 

Genize saplanan 

Leş parçaları 

Yürekteki çürükler 

Ağza vuran 

Acımtrak dalgalar 

Tükürmekle tükenmeyen', 'Yürekteki çürükler  Ağır bir sancı  Geminin güvertesinden  Kusulmak istenen  Yürekteki çürükler  Belleğin gelgitlerinde  Genize saplanan  Le...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yurekteki-curukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-muge-usul-0ru9c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimseyi sevemedim ben,

Her bahar gelişinde çırpınsa da kalbim.

Kimseye söyleyemedim

Sevdiğimi

Onun için sevemedim kimseyi.

Ağlamak yakışmıyor bana,

Gülmek ise tek çare bazen,

Gizlenmek için ardına.

Kimseyi sevemedim korkumdan,

Diyemedim,gelse de dilimin ucuna...', 'Kimseyi sevemedim ben, Her bahar gelişinde çırpınsa da kalbim. Kimseye söyleyemedim Sevdiğimi Onun için sevemedim kimseyi. Ağlamak yakışmıyo...', ARRAY['Türk Edebiyatı','Şiir','Müge Usul']::text[], 8.5, '{"poet":"Müge Usul","poet_slug":"muge-usul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/korku-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk''ün Kudreti', 'turk-un-kudreti-ugur-ozen-kiri5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerimi soksa da kızıl dişli engerek

Gözlerim çakalların gözlerine dikilir.

Bir gün gelir yırtılır göğsümde duran yürek

birgün gelir budunumun bozkırlara çekilir.

O an çalınır gene kara ozanın sazı

uzaklardan duyulur Kültiginin bitiği

Kılıcımı bilerken yalın bozkır ayazı

Ulu bir koca derki titre

öyle titreki taa Altaylar titresin

Türk soyun devam etsin

Türk soyun hiç bitmesin

Ne mutludur sana ki

Türk eri Türk oğlusun

Tanrı seni yüceltsin

Tanrı seni korusun.

                             (Erzurum-Mayıs 2001)', 'Ellerimi soksa da kızıl dişli engerek Gözlerim çakalların gözlerine dikilir. Bir gün gelir yırtılır göğsümde duran yürek birgün gelir budunu...', ARRAY['Türk Edebiyatı','Şiir','Uğur Özen']::text[], 8.5, '{"poet":"Uğur Özen","poet_slug":"ugur-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turk-un-kudreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-oya-erdemci-swl4x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dost sandım sarıldım yalan çıktınız

Ayağıma, elime dolan çıktınız

İki başlı zehirli yılan çıktınız.

Sır verdim sırrımı yele verdiniz

Bilinmez diyarlara ele verdiniz

Kadir kıymet bilmez dile verdiniz

İki başlı zehirli yılan çıktınız.

Bu kadar riyayı nerde buldunuz

Nerde sizin şerefiniz nerde ruhunuz

Ne kadar da ucuzmuş sizin dostluğunuz

İki başlı zehirli yılan çıktınız.

Dost deyip dostuma sarıldım sandım

Kandım ki o güzel yüzlere kandım

Hepsi birer oyundu nasıl aldandım

İki başlı zehirli yılan çıktınız.

Anladım ki dost olmazmış dünyada

Arayışlar boşa,çaba beyhude

Derdimi dökseydim dağlara, taşa

İki başlı zehirli yılan çıktınız.

Dost dilde değil gönülde olur

İnsanlık dağ gibi ardında durur

Elbet bir gün gelir dost da bulunur

İki başlı zehirli yılan çıktınız', 'Dost sandım sarıldım yalan çıktınız Ayağıma, elime dolan çıktınız İki başlı zehirli yılan çıktınız. Sır verdim sırrımı yele verdiniz Bilinme...', ARRAY['Türk Edebiyatı','Şiir','Oya Erdemci']::text[], 8.5, '{"poet":"Oya Erdemci","poet_slug":"oya-erdemci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dost-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladın mı..', 'anladin-mi-oya-erdemci-b61zp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç düşündün mü..

Güler yüzümün  ardına sakladığım beni

Hiç düşündün mü..

Mutsuzluğumu..

Umutsuzluğumu..

Yıkılmışlıklarımı..

Yaşanmamışlıklarımı..

Geç kalmışlıklarımı..

Hiç düşündün mü..

Görebildin mi gönül gözüyle

İçimdeki gerçek beni

Çocukluğunun kırık,dökük hatıraları arasında

Sıkışıp kaldın mı hiç

Sen hiç sevgisiz kaldın mı..

Duygularının coştuğu anlarda

Umutların gözlerinde,

Gülüşlerin dudaklarında donup kaldımı.

Sen hiç..

Anneni gölge sandın mı..

Anneni parayla satın aldın mı..

Sen bilirmisin bunları

Hiç yaşadın mı..

Yıkılmışlıklarını unutabilmek için,

Uzun uzadıya,günlerce uykulara daldın mı..

Sen hiç hayallerinde bir sevgili yaratıp,

Geceleri koynuna aldın mı..

Sen hiç aç,susuz,odunsuz

Hepsi bir yanada..

Sen hiç..

Sevgisiz kaldın mı...

Şimdi neden bu kadar çok gülüyorum..

Anladın mı? 

24.04.2001-İst', 'Hiç düşündün mü.. Güler yüzümün  ardına sakladığım beni Hiç düşündün mü.. Mutsuzluğumu.. Umutsuzluğumu.. Yıkılmışlıklarımı.. Yaşanmamışlıkla...', ARRAY['Türk Edebiyatı','Şiir','Oya Erdemci']::text[], 8.5, '{"poet":"Oya Erdemci","poet_slug":"oya-erdemci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/anladin-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevenden Ayrılmak', 'sevenden-ayrilmak-faruk-aysoy-2pqws', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevenden ayrılmak acıda olsa,

Kalbinden söküp atmak zorda olsa,

Yalnızlığı hissetmek korkunçta olsa,

Unutma yalnız değilsin!!!

Aşkını hiç unutamasanda,

Fikrini hiç değiştiremesende,

Konuşurken yaşadığından dilinde titrese,

Unutma seni seven birileri her zaman var!!!

Korkupda kaçmak kolayda olsa,

Acıyı unutmaya çalışmak daha çok acıtsada,

Yalnızlık canınıda yaksa,

Korkma seninle savaşmaya ve sevmeye hazır birileri hep var!', 'Sevenden ayrılmak acıda olsa, Kalbinden söküp atmak zorda olsa, Yalnızlığı hissetmek korkunçta olsa, Unutma yalnız değilsin!!! Aşkını hiç un...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevenden-ayrilmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyimser Adam...', 'i-yimser-adam-nazim-hikmet-ran-vepaa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocukken sineklerin kanadını koparmadı 

teneke bağlamadı kedilerin kuyruğuna 

kibrit kutularına hapsetmedi ham
..........
..........', 'Çocukken sineklerin kanadını koparmadı  teneke bağlamadı kedilerin kuyruğuna  kibrit kutularına hapsetmedi ham .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/iyimser-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Bir Haber', 'senden-bir-haber-faruk-aysoy-ebgl7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizliğin son aşamasında ,

Korkunun ecele dönüştüğü anda,

Yalnızlığın ölüme seslenişinde,

Senden bir haberle uyandım yeniden...

Kalbim tamamen parçalandığında,

Aklımın uçtuğunu hissettiğimde,

Parmaklarım tutmadığında,

Senin sesinle iyileştim yeniden...

Dudaklarım titremeye başladığında,

Dilim tutulduğunda,

Nefes alamadığımda,

Senin sıvınla,senin hayalinle giderdim susuzluğumu yeniden...

Ve şimdi yeniden geldim dünyaya,

Yeniden hissetmeye başladım aşkı, sevgiyi,

Yeniden anladım yaşamanın değerini 

Seninle yeniden birlikte olup, sana kavuştuğum için....', 'Sensizliğin son aşamasında , Korkunun ecele dönüştüğü anda, Yalnızlığın ölüme seslenişinde, Senden bir haberle uyandım yeniden... Kalbim tam...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-bir-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-faruk-aysoy-szc2r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamandır herşeyi aydınlatan,

Her yolu sonuçlandıran,

Yanlızlığı gideren,

Hiç bir zaman durmayıp hep sabit kalan.

Zamandır insanın içine işleyen,

Korkuları tekrar hatırlatan,

Hiçbir zaman unutulamayan,

Asla kaçılamayan.

Zamandır her bilmeceyi çözen,

Bilinmezleri ortaya çıkaran,

Kişileri tanımanı sağlayan,

Tüm hayatını şekillendiren...', 'Zamandır herşeyi aydınlatan, Her yolu sonuçlandıran, Yanlızlığı gideren, Hiç bir zaman durmayıp hep sabit kalan. Zamandır insanın içine işle...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zaman-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Hİç Aşık Olmadınız ki', 'siz-hi-c-asik-olmadiniz-ki-beril-onbulak-21fbn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siz hiç hayaller ülkesinde dolaştınız mı?

Gördünüz mü Olimpos''ta ki 

peri kızlarını?

Dokundunuz mu bir çiçeğe 

arı gibi?

Sevdiniz mi kendi bedeninizi

çırılçıplak?

Nereden bilirsiniz ki,

Kaf Dağı''nı Anka Kuşu''nu...

Siz hiç çocuk oldunuz mu?

Aşkı da bilmezsiniz siz

Savaşmaktan ve nefretten başka...

Ne gördünüz ki siz?

Siz hiç aşık olmadınız ki...', 'Siz hiç hayaller ülkesinde dolaştınız mı? Gördünüz mü Olimpos''ta ki  peri kızlarını? Dokundunuz mu bir çiçeğe  arı gibi? Sevdiniz mi kendi b...', ARRAY['Türk Edebiyatı','Şiir','Beril Onbulak']::text[], 8.5, '{"poet":"Beril Onbulak","poet_slug":"beril-onbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/siz-hic-asik-olmadiniz-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dede Korkut Masalları', 'dede-korkut-masallari-beril-onbulak-m9kj5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne de garip bir duygu bu sevgi..

Yaklaştıran beni insanlara

Yaklaştırdıkça korkutan 

Sonsuz güven ve sırlar içinde

Yüzen bir hayat adası

İçinde eş,dost,kardeş,bacı...

Ve en sevdiğim

Dede Korkut Masalları', 'Ne de garip bir duygu bu sevgi.. Yaklaştıran beni insanlara Yaklaştırdıkça korkutan  Sonsuz güven ve sırlar içinde Yüzen bir hayat adası İçi...', ARRAY['Türk Edebiyatı','Şiir','Beril Onbulak']::text[], 8.5, '{"poet":"Beril Onbulak","poet_slug":"beril-onbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dede-korkut-masallari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-omer-hayyam-ma40o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ezeli sırları ne sen bilirsin ne de ben

Bu muammayı ne sen okuyabilirsin ne de ben

Perde ardında sen ben dedikodusu var amma...

Perde kalktı mı ne sen kalırsın ne de ben

Ey dünyanın işinden haberi olmayan sen yoksun

Dünya esen yel üstüne kuruldu..

Varlığımız iki yokluk arasındadır

Çevrendekilerde hiçdir sen de bir hiçsin

Medresede söz vardır tekkede de hal

Fakat bu aşk sözden de dışarıdır halden de

İster şeriat müftüsü ol ister şehir vaizi

Aşk mahkemesine gelindi mi dilsiz kesilir

Bugün zevk etmek elindeyken zevkine bak

Yarını düşünmen beyhude bir heves

Bir çok kişiden arda kalanlar

Sana da kalmayacak sen de göçüp gideceksin...', 'Ezeli sırları ne sen bilirsin ne de ben Bu muammayı ne sen okuyabilirsin ne de ben Perde ardında sen ben dedikodusu var amma... Perde kalktı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Yaşanan', 'seninle-yasanan-beril-onbulak-7b3qm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir güneş batımıdır seninle yaşanan

Kıyıdan açılan 

Tan yerinden kopan

Kızıl bir alev masmavi göğü saran

Aşktır seninle yaşanan

Bir müzikal

Melankolik bir aşkı anlatan

Ve sonu ayrılık olmayan

Sevgidir seninle yaşanan

Şiddetli bir fırtına

Ne zaman dineceği belli olmayan

Yaşarken öldüren

Öldürürken dirilten

Tutkudur seninle yaşanan

Renklerin atlı karıncasıdır seninle yaşanan

Dostluktur

Kah gülen ve kah ağlayan

Bana bir ömürdür

Seninle bir dakika bile yaşanan', 'Bir güneş batımıdır seninle yaşanan Kıyıdan açılan  Tan yerinden kopan Kızıl bir alev masmavi göğü saran Aşktır seninle yaşanan Bir müzikal ...', ARRAY['Türk Edebiyatı','Şiir','Beril Onbulak']::text[], 8.5, '{"poet":"Beril Onbulak","poet_slug":"beril-onbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seninle-yasanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-bayram-karaali-rnrd7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İhanetler insan içindir değilmi? dost dediğim ,

Uğruna ; neler verildi bir bilsen,ağlamaklıyım,

Sadaket adınaydı,vefa adınaydı oysa beklentisiz,

İhanet yazmadı nedense ne kitabımda,nede hayatımda..

Anlatmak,vede anlaman belki zordur,

Böyle saf kalabilmiş yüreklerle  arkadaşlığın,

Kolay gelmez belkide anlasanda,

Ama adına dostluk sadakat vefa dedim oysa...

4.Mayıs.2001', 'İhanetler insan içindir değilmi? dost dediğim , Uğruna ; neler verildi bir bilsen,ağlamaklıyım, Sadaket adınaydı,vefa adınaydı oysa beklenti...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ihanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen''e...', 'beklenen-e-muge-usul-5v77h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün gelecek biliyorum,

Beklenen her neyse

Her kimse gelmeyen

Gelecek...

Soracak halimi

Ve ısıtacak içimi

Gülümseyerek...

Beklenen her neyse

Her kimse gelmeyen

Geç de olsa gelecek...', 'Bir gün gelecek biliyorum, Beklenen her neyse Her kimse gelmeyen Gelecek... Soracak halimi Ve ısıtacak içimi Gülümseyerek... Beklenen her ne...', ARRAY['Türk Edebiyatı','Şiir','Müge Usul']::text[], 8.5, '{"poet":"Müge Usul","poet_slug":"muge-usul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beklenen-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuş Sevdalıya Sevgilerle.', 'unutulmus-sevdaliya-sevgilerle-hasan-kaya-corlulu-j1gdt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahar değil...

Sonbaharda zaman

Bir sevda sesi var...çok uzaklardan

Tatlı bir hüzün...Buruk bir sevinç

Acı gülümseme dolu o mahzun dudaklardan.

Gün acı...

Gece acı...

Hayat acı belki sen olmayınca

Aşk güzeldir yalnızken bu sessiz akşamlarda

Bahar bile,

Bahar bile hoş değil inan,

Çünkü sonbaharda zaman

Hüzünlü bir gülüş bir haykırıştır kalan

Acı gülümseme dolu o mahzun dudaklardan

Yavru bir kuş,

Kanadı kırılmış azgın rüzgarlardan

Uçup gidecek...

Gelmeyecek bir daha

Kimbilir ; belki kaçıyor

Umarsız,tükenmiş,yokolmuş ümitsiz bakışlardan

Hüzünlü bir gülüş,bir haykırıştır kalan

Acı gülümseme dolu o mahzun dudaklardan.

Ve

Bir akşam...

Gün henüz kararmışken

Bir kuş uçtu kanadı kırık

Sevgi dolu , aşk dolu sımsıcak yuvamızdan.

Biliyorum...

Bahar değil,

Sonbaharda zaman

Bir sevda sesi var çok uzaklardan

Çorlu; 7 Ekim 1987', 'Bahar değil... Sonbaharda zaman Bir sevda sesi var...çok uzaklardan Tatlı bir hüzün...Buruk bir sevinç Acı gülümseme dolu o mahzun dudaklard...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaya Çorlulu']::text[], 8.5, '{"poet":"Hasan Kaya Çorlulu","poet_slug":"hasan-kaya-corlulu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/unutulmus-sevdaliya-sevgilerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimin Uzağındayım', 'duslerimin-uzagindayim-hakan-yigit-0eywt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman aktıkça bilmediğim denizlerin deltasına

Ben düşlerimin uzağında kalıyorum

Saatime baktığımda uykumun en güzel noktasında

Uyanmaya geç kalıyorum...', 'Zaman aktıkça bilmediğim denizlerin deltasına Ben düşlerimin uzağında kalıyorum Saatime baktığımda uykumun en güzel noktasında Uyanmaya geç ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/duslerimin-uzagindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İskele', 'i-skele-tevfik-mengulluoglu-ha915', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hni bir iskele Vardı limanda 

Koşar adımlarla ilerlerdim

Her yanım deniz.

Hani kiremit çatılı evlerin sokağında 

Ayaklarımın ve yağmurun sesi karışınca 

Bir damla düşerdi 

Kaşlarıma,birden bire...

Sürüklerdi beni sevdamın 

Susayan toprağına usulca...

Hani bir güzel vardı 

Mavilerin dünyasında 

Yüz köpük, gözleri mavi, 

saçları dalga.

Rüzgar hafif hafif okşardı 

Sarılır rüyala... 

Sürüklerdi sonra beni 

sevdamın susayan 

toprağına usulca...', 'Hni bir iskele Vardı limanda  Koşar adımlarla ilerlerdim Her yanım deniz. Hani kiremit çatılı evlerin sokağında  Ayaklarımın ve yağmurun ses...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/iskele-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-erkan-candogan-omuh3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben korkağım.

Gerçekten korkağım...

Çünkü bir gün gideceksin diye,

Çok korkuyorum.

Çünkü bir sabah kalktığımda

Yanımda olmayacaksın diye

Çok korkuyorum...

Beni aslında hiç sevmediğini

söyleyeceksin diye 

Çok korkuyorum

Ve bir gün gittin,

Ve bir gün yoktun.

Ve hepsinden önemlisi,

Beni sevmediğini söyledin.

Korktum, gerçekten korktum...

İzmir 2000', 'Ben korkağım. Gerçekten korkağım... Çünkü bir gün gideceksin diye, Çok korkuyorum. Çünkü bir sabah kalktığımda Yanımda olmayacaksın diye Çok...', ARRAY['Türk Edebiyatı','Şiir','Erkan Candoğan']::text[], 8.5, '{"poet":"Erkan Candoğan","poet_slug":"erkan-candogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korkuyorum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yüzlüm', 'ay-yuzlum-tevfik-mengulluoglu-4bqrt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay parçasından güneş sarısından çalıp resmini yaptım

Gökyüzünün mavisine.

Ardından poyrazın saçlarını okşamasını bekledim ve gözyaşlarının yağmur olmasını.

Dokunmalıydım ama çok uzaktaydın oysa oysa resmini ben çizmiştim gökyüzünün Mavisine..', 'Ay parçasından güneş sarısından çalıp resmini yaptım Gökyüzünün mavisine. Ardından poyrazın saçlarını okşamasını bekledim ve gözyaşlarının y...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ay-yuzlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzleş', 'yuzles-tevfik-mengulluoglu-uyaxw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah uyndığında Aynaya Bakıp kendinle konuşmayı dene önce kendini yargıla sonra yalanlarını.

Ardından bir değil birçok pencereden bak hayata 

Güzelliklerin resmini çiz mas mavi bulutlara, ve sevdiğini söyle bütün çocuklara rengarenk balonlar ver dalgalansın yüzlerinde mutluluk.', 'Bir sabah uyndığında Aynaya Bakıp kendinle konuşmayı dene önce kendini yargıla sonra yalanlarını. Ardından bir değil birçok pencereden bak h...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yuzles-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-emin-ozan-helvacioglu-sh1lx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuksu düşlerimiz yarım kaldı

Bir kısmı güneşte, bir kısmı ayda

İnsanlar pencere gibi, hem gerçek hem değil

Beynimde geceler sonsuzluğa ulaşırken

Bir zamanlar sevdiğimiz saatler hayalden de öte bir şey oldu

Beyaz mı, siyah mı? anlamak çok zor artık

Ne oldu bize? birimiz deli birimiz sürekli değişken

Sesin yabancılaşırken dünlerin gerisinde

Düşlerimde bile normal olamıyorum

Senin istediğin, onların kabul ettiği

Bütün gece düşünmek, yepyeni sorunlar yaratmak

Hiçbir şeyi doğrulamıyor hayal ettiğimiz gibi

Neden uyanamadık biz birlikte sabahları 

İkimiz aynı yerde aynı şeylerle yattığımız halde? 

En güçsüz olduğumuz anı nasıl buldular? 

Tanrılar misali bir gece yarısı ayrıldık

Beklemekle ölmek arası bir şey

Ama ben bekleyeceğim

Çünkü ölürsem seni düşünemem

Bekleyeceğim', 'Çocuksu düşlerimiz yarım kaldı Bir kısmı güneşte, bir kısmı ayda İnsanlar pencere gibi, hem gerçek hem değil Beynimde geceler sonsuzluğa ula...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bekleyecegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Konuşamam Artık', 'ben-konusamam-artik-emin-ozan-helvacioglu-cof5f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Konuşamam artık

Konuşamam

Duvarlar aynalar bile sizden daha yumuşak

Bir skandal korkusu attınız önüme

Biriniz düşlerimi çaldınız

Diğeriniz hayallerimi

Umutlarımı bile kırdınız

Biri de ‘ geçmiş olsun ‘ dedi

Omzumu okşayıp, yüzüme gülüp

‘ Kader ‘ dediler, ‘ boş ver ‘ dediler

‘ Unutursun canım ağlama ‘

Ama unutulan ben oldum

‘ Ağlama canım ağlama ‘

Hiçbir şey anlamadım

Konuşamam artık

Konuşamam

Normal de olamam

Bu haksızlıkta

Lütfen düşlerimi geri verin

Hayallerimi, umutlarımı da

Ben konuşamam artık

Her yerde aptallar, cahiller var

Ben normal olamam

Lütfen dünlerimi geri verin

Ya da tamamen parçalayın beni

Hiçbir atomum nefes almasın

Ben konuşamam artık

Konuşamam', 'Konuşamam artık Konuşamam Duvarlar aynalar bile sizden daha yumuşak Bir skandal korkusu attınız önüme Biriniz düşlerimi çaldınız Diğeriniz h...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-konusamam-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürüklenme', 'suruklenme-resat-serhat-906dm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedenmi sürükleniyorum ardınsıra

Yüzümdeki ifadeyi çaldın sen

Bana tebessümler kaldı

Kahkahalarımı alıp götürdün benden...

(1999 - İstanbul)', 'Nedenmi sürükleniyorum ardınsıra Yüzümdeki ifadeyi çaldın sen Bana tebessümler kaldı Kahkahalarımı alıp götürdün benden... (1999 - İstanbul)...', ARRAY['Türk Edebiyatı','Şiir','Reşat Serhat']::text[], 8.5, '{"poet":"Reşat Serhat","poet_slug":"resat-serhat","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/suruklenme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Anlatamıyorum', 'artik-anlatamiyorum-emin-ozan-helvacioglu-gu5ib', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık anlatamıyorum

Gecenin sunduğu bu garipliği

Huzur mu yoksa tükeniş mi ?

Deli gibi oturduğum bu masa

Bu kırık kül tablası

Artık anlatamıyorum

Biten bir insan, şu sigara

Her gece

Yeni bir kandırmaca

Sanırım sen de aynı şeyi hissediyorsun

Aynada dost bir yabancı

Vicdan azabı ve yanılgı

Artık anlatamıyorum

Dört köşe bir yalnızlık

Ama her şeyi görebiliyorum

Kımıldamadan, gözlerimi açmadan

Bu çamurlu halı, soğuk yastık

Her şeyi hatırlayabiliyorum

Çok geç ve imkansız

Artık anlatamıyorum

Penceredeki şeffaf anlamsızlığı

Ellerimde küçücük hayaller

Kendimi değil sadece seni arıyorum

Uykusuz gecelerde

Artık anlatamıyorum

Hangisi gerçek', 'Artık anlatamıyorum Gecenin sunduğu bu garipliği Huzur mu yoksa tükeniş mi ? Deli gibi oturduğum bu masa Bu kırık kül tablası Artık anlatamı...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/artik-anlatamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey Doğuyor İçime', 'bir-sey-doguyor-i-cime-emin-ozan-helvacioglu-9bzp7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoksa sen mi geri dönüyorsun güzelim ?

Sigara artık zevk vermiyor

Bir şey doğuyor içime

Her zamanki gibi odamda kendimle karanlıkta otururken

Hem korku hem umut var şimdi

Gece çoktan başlamış beklemeden çağrıyı

Hala kollarında düşünüyorum kendimi

Düşle gerçek ortası bir şey

Ve sen bir yabancının karşısında

Bana bakıyorsun sanki benimlesin

Birlikte olmayı hayal ettiğimiz yerde

Sadece sen ve ben aptallardan çok uzak

Bana pamuk gibi dokunan el senin mi güzelim ?

Aynı eski öpüş ve şefkat

Bir şey doğuyor içime

Hayallerle anıları yazarken şiir şiir mektup kağıtlarına

Hiç düşünmemiştim bu kadar ciddi, biz gerçekten neyiz ?

Söylenecek yoksa dinlenecek bir söz mü ?

Duyuyorum hala o şarkıyı mırıldanıyorsun

Koyu perdelerin ardında

Ve ben, korkak-pis, çekiniyorum açmaya

Üstümüze bırakılan örtüleri

Bir şey doğuyor içime

Sen olmalısın güzelim', 'Yoksa sen mi geri dönüyorsun güzelim ? Sigara artık zevk vermiyor Bir şey doğuyor içime Her zamanki gibi odamda kendimle karanlıkta otururke...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-sey-doguyor-icime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut', 'bulut-emin-ozan-helvacioglu-4d3qh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabahlar sabah, öğlenler öğlen

Akşamlar akşam, geceler gece

İnsanlar insan değil

Bulut var güzelim

Zamanın durduğu an

Ne ileri gidiş ne geri dönüş

Olduğun yerde kal, tüken deli gibi

Kahverengi gözleri hatırla

Kaybettiklerini düşün, istersen ağla

O aynı yerlerde veya pencerenin önünde

Gökler gök, yağmurlar yağmur

Rüzgarlar rüzgar, ışıklar ışık

Çocuklar çocuk değil

Bulut var güzelim

Her yerde

Sesler ses, sözler söz

Güçler güç, akıllar akıl

Gerçekler gerçek değil

Bulut var güzelim

Acı bir haksızlık

Neden, niçin, nasıl ve ne kadar ?

Düşün aniden sadece, kaybol değişikliklerde

İçki kokan zayıflığıma gül

Cevaplara soru bul, kır beni yine

Mektuplarda, şiirlerde ve telefonda

Kahverengiler kahverengi, denizler deniz

Şarkılar şarkı, sarhoşluklar sarhoşluk

Çiçekler çiçek değil

Bulut var güzelim 

Her yerde', 'Sabahlar sabah, öğlenler öğlen Akşamlar akşam, geceler gece İnsanlar insan değil Bulut var güzelim Zamanın durduğu an Ne ileri gidiş ne geri...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bulut-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler', 'kelimeler-resat-serhat-vutnh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-I-

kelimeler... 

sunaklarımı taşıyamazlar

kelimeler ki

zaten kendi tatsızdır yaşamak

sırtımda gezindiğini bildiğim el

sıvazlayıcıların mı?

-II-

burada 

sana 

gitgide incelen inciler, 

kelimeler dizdim

ama bilesin ki 

kendi, tatsızdır şarap şişesinin

üzümdür ona tadını veren, 

salkım salkım bağlarından gelip

tad vermek içinse 

inci dizilerini birleştirdiğim

üzümü bağında resmetmem gerek 

ki görülsün mutluluğun resmidir bu

figüran değildir resimde bağ işçileri

mutluluğu işleyen kırmızı, kara...

bir başka resimde 

çeltikten kanayan elleriyle

-III-

bak! 

şimdi kan oldu

tad alınması gerek...

-IV-

biliyorum ki 

çizgilerle yaratılabilinir sözcükler

fakat sözcüklerle yapamadım bu resmi,

yahut vermedi bekledigim tadı ağızlara

-V-

ve şimdi bardakları, kadehleri 

bir kenara bırakıp

resim yapmam gerek.

-VI-

çünki sarhoşluk içilmez

sarhoş olunur

ve 

resmidir artık...

(Ocak 2001 - İstanbul)', '-I- kelimeler...  sunaklarımı taşıyamazlar kelimeler ki zaten kendi tatsızdır yaşamak sırtımda gezindiğini bildiğim el sıvazlayıcıların mı? ...', ARRAY['Türk Edebiyatı','Şiir','Reşat Serhat']::text[], 8.5, '{"poet":"Reşat Serhat","poet_slug":"resat-serhat","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kelimeler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13-4', '13-4-tahir-ehad-ozar-s84sr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'rotasız

bilinç altı yolculuğunda

çok kişilik olup

tek başına oynadığı

rıhtımsız bir yaşam sığınağıydı

yüreğinin şemsiyesiz yağmurlarında

cama yaslanıp da

yansıtılan

köpek tarafındaki altın dişin

yansımasıydı

ve amacın tersine aktığında damlalar

ölü kelebekler

uçmaya devam ediyordu', 'rotasız bilinç altı yolculuğunda çok kişilik olup tek başına oynadığı rıhtımsız bir yaşam sığınağıydı yüreğinin şemsiyesiz yağmurlarında cam...', ARRAY['Türk Edebiyatı','Şiir','Tahir Ehad Ozar']::text[], 8.5, '{"poet":"Tahir Ehad Ozar","poet_slug":"tahir-ehad-ozar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/13-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımı', 'gun-batimi-baris-karabel-ywltk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün batımının ardına yolculuk etmek istiyorum,

Karanlıkların beni boğmadığını hissetmek için...

Aklımda beliren ışığın doğrultusunda

Hayatın anlamını çözebilmek

ve vaar olduğumu hissetmek istiyorum

Duygularımız!

Daima bir adım geride değil,

içimizde olmalı.

Nitelendirilen sahte gerçeklerle

Hayata hiç bir zaman köle olmamalıyız.

Çünki Hayatın acı gerçekleri 

bizi ezmek için beklerken 

aramızdan kurtulanlar sadece 

ama sadece

Sevmeyi bilenler olacaklardır.

Ne güzel değil mi? 

Sevgi sözcüklerinin kelimelere sığdırası

Anlatabiliyormu beni sana

yada anlıyormusun

Bilmiyorum...

Artık sadece kendimden değil

İnsanlardan da emin değilim.

lanet olsun

Sana da...

Bu kocaman dünyayada...', 'Gün batımının ardına yolculuk etmek istiyorum, Karanlıkların beni boğmadığını hissetmek için... Aklımda beliren ışığın doğrultusunda Hayatın...', ARRAY['Türk Edebiyatı','Şiir','Barış Karabel']::text[], 8.5, '{"poet":"Barış Karabel","poet_slug":"baris-karabel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gun-batimi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13-5', '13-5-tahir-ehad-ozar-1fqi2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'birleşimlerin karışım formülleriyle

aleyhe düzenlenen görsel anlaşmalar

kalıplaşmış düzenlerin

fonksiyonları

renkli fotoğraflar misali

kandırır yaraları çiçeksiz büyüyen sular gibi

tatminsiz açıklamalar üzerine

uçurulur kalp görünüşlü

görsel duygulu balonlar', 'birleşimlerin karışım formülleriyle aleyhe düzenlenen görsel anlaşmalar kalıplaşmış düzenlerin fonksiyonları renkli fotoğraflar misali kandı...', ARRAY['Türk Edebiyatı','Şiir','Tahir Ehad Ozar']::text[], 8.5, '{"poet":"Tahir Ehad Ozar","poet_slug":"tahir-ehad-ozar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/13-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak Emek', 'tutsak-emek-ahmet-i-nce-7ddfu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Trabzon’da konakladı kalbim

düşlerim resim yapar şimdi

Tonya’da

yeşil yüzlü bir yayla

koynunda

yaşam sunan buzlu pınarlar

coşku

horon

kemençe

kabına sığmayan 

            nar yanaklı

            ve peştemalli kızlar

bu aşk kadar sıcak kentin

gür

yeşil ormanlarını

başı dumanlı dağlarını

nazlı yar gibi sevdim

hamsiler gibi oynak

ceylanlar gibi kıvrak insanlarını

sımsıcak şiirler gibi sevdim

ekledim sevgimi sevgilerine

istedim ki

Karadeniz özgür olsun

ve 

tutsak emek kurtulsun', 'Trabzon’da konakladı kalbim düşlerim resim yapar şimdi Tonya’da yeşil yüzlü bir yayla koynunda yaşam sunan buzlu pınarlar coşku horon kemenç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tutsak-emek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-umut-erturk-9s315', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne ölüm olmasaydı anlayabilirdim yaşamın tadını,

Ne su olmasaydı toprağın gebe olduğunu,

Ne de sen olmasaydın anlayabilirdim,

Sevginin zulmünü,

Gözyaşının tadını...', 'Ne ölüm olmasaydı anlayabilirdim yaşamın tadını, Ne su olmasaydı toprağın gebe olduğunu, Ne de sen olmasaydın anlayabilirdim, Sevginin zulmü...', ARRAY['Türk Edebiyatı','Şiir','Umut Ertürk']::text[], 8.5, '{"poet":"Umut Ertürk","poet_slug":"umut-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/askim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzda Uçan Şiir', 'sonsuzda-ucan-siir-ahmet-i-nce-qle40', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yitik umutların gözlerinde

ayaklanırken tutkular

akıp gidiyor günlerin kanı

sevginin yeşil kıyılarında

uçuyor esin kuşları

göz kırpıyor imgelere

el değmemiş güzellikler

kesik bir damar gibi derinden

akıyor isteksizlik

doyumsuz duygular denizinde 

ağlamakta sensizlik

yaratıcı emek yolunda

yorgun beklentilerin bitmedi şansı

tükenmedi gelecek

ama yine de 

sığ kıyılarda beklemek değil

engin denizlere açılmak düşer bize

hoşça kal hırçın kıyı 

hoşça kal son okulumuz

zamanın zor noktasında

güzelliğin tam ortasında

ayrılıyor yolumuz

elveda mor ışıkların seviştiği şehir

sarı kızın mavi gözleri elveda

elveda sıcak sözcüklerin çıplak dansı

ve elveda sonsuzda uçan şiir

                             Trabzon

                           01.07.1997', 'yitik umutların gözlerinde ayaklanırken tutkular akıp gidiyor günlerin kanı sevginin yeşil kıyılarında uçuyor esin kuşları göz kırpıyor imge...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sonsuzda-ucan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıların İsyan Olsun', 'acilarin-i-syan-olsun-ahmet-i-nce-i2xar', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'batan güneşin hüznü

öperken kızıl suları

ağaçların saçları kanayacak

menzile varacak her akış

denize koşan ırmak

sapmayacak yolundan

meyveye soyunan çiçek

düşmeyecek dalından

sürüne sürüne üzüntüler

dayansa da kapına

ağlama karanfilim

acıların isyan olsun

özgürlük dağlarda büyür

emek kentlerde yürür

şanlı sevdalarda büyür haziran

nasıl büyümez barışa gebe uğraş

ve nasıl doğmaz batan güneş

güneşin sancısı bitmez

sancılar doğum yapar 

yasaklar zincir kırar

yıkar zulmün engelini

yeni sevda şiirleri

                         Haziran,1983

                             Trabzon', 'batan güneşin hüznü öperken kızıl suları ağaçların saçları kanayacak menzile varacak her akış denize koşan ırmak sapmayacak yolundan meyveye...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/acilarin-isyan-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madenci', 'madenci-oner-fikri-cegev', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş ne doğar ne batar.

Ayıptır bu yüzden

Saate bakılmaz yeraltında.

Gülle çiçekle anılmaz

Domuzdamcı kazmacıdır

Köylerinin adları.

Bırakır tuzunu karanlıkta

Kırılır ışık demetleri,

Gün ışığından geçmişler

Ekmek olmuş dertleri.

                (Ocak 1990)', 'Güneş ne doğar ne batar. Ayıptır bu yüzden Saate bakılmaz yeraltında. Gülle çiçekle anılmaz Domuzdamcı kazmacıdır Köylerinin adları. Bırakır...', ARRAY['Türk Edebiyatı','Şiir','Öner Fikri']::text[], 8.5, '{"poet":"Öner Fikri","poet_slug":"oner-fikri","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/madenci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis Oldu Şarkılar', 'sis-oldu-sarkilar-mevl-na-i-dris-zengin-a38ih', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kağıttan gemiyi bırakıyorum

Bu kağıttan denize

Bakıyorum bakıyorum da bitmiyor

Ne çok çizik atmışız yüreğimize

Dünya ne ki dünya ne ki

Beyaz olan her şey biraz mavi

İstesen de istemesen de

Bakarsın bir el tutmuş elini

Bilemez kimse

Allah dilediği gibi serper çiçeklerini

Ve çakar çivilerini dilediği gibi

Bir can olup öylece kaldığımız an

Bir müzik olup sustuğumuz sesinle söyle bana

Bir çocuğun elleri bırakılır mı hiç bırakılır mı

Sana bakıyorum

Çevirme yüzünü ben yabancı değilim

Seninle bakıyorum bu büyük boşluğa

Sana bakıyorum şarkılara bakıyorum

Sis oldu şarkılar elini arıyorum

Kalbim dünyanın ilk aşığının kalbi gibi

Ve ruhum paramparça

Sis oldu şarkılar elini arıyorum

Bilemez kimse beyaz olan herşey

Bazen bir cümleyi bitiremiyorum

En son ölüm gelir

Yine de erken deriz

Derinlikler için bir yol vardı

Bilmiyorum her şey bitti mi

Bu kağıttan gemiyi bırakıyorum 

Bu kağıttan denize

Sevgilim sevgilim

Böyle yalnız mı gidecektim

Cennetteki evimize', 'Bu kağıttan gemiyi bırakıyorum Bu kağıttan denize Bakıyorum bakıyorum da bitmiyor Ne çok çizik atmışız yüreğimize Dünya ne ki dünya ne ki Be...', ARRAY['Türk Edebiyatı','Şiir','Mevlâna İdris Zengin']::text[], 8.5, '{"poet":"Mevlâna İdris Zengin","poet_slug":"mevl-na-i-dris-zengin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sis-oldu-sarkilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamazsın', 'bulamazsin-osman-yuksel-serdengecti-69q26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kere inkâra düstün mü yavrum,

Kendini aşmaya yol bulamazsın.

Vehimler şüpheler bozar ruhunu,

Seni kaldıracak el bulamazsın...

Elbet dünya döner, bizde döneriz,

Bir müddet parıldar sonra söneriz...

Yükseklerden enginlere ineriz

Halinden anlayan dil bulamazsın.

Ömür akar gider yokluk gölüne

İnsanoğlu dümüş serap çölüne

Hayat benzer bir gecelik geline

Kendin gibi akan sel bulamazsın 

Ektiğin tohumlar bir türlü bitmez

Müşkülü yenmeye bir ömür yetmez

Kuş olsan uçsan da yine kâr etmez

Arasan konacak dal bulamazsın...', 'Bir kere inkâra düstün mü yavrum, Kendini aşmaya yol bulamazsın. Vehimler şüpheler bozar ruhunu, Seni kaldıracak el bulamazsın... Elbet düny...', ARRAY['Türk Edebiyatı','Şiir','Osman Yüksel Serdengeçti']::text[], 8.5, '{"poet":"Osman Yüksel Serdengeçti","poet_slug":"osman-yuksel-serdengecti","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulamazsin-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-muge-usul-o8597', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yolum uzun biliyorum

Ya yalnız olacağım

Ya da sen olacaksın sonuna kadar

Bu yol ya seninle başlayacak

Ve de bitecek

Ya da hiç gidilmeyecek...', 'Yolum uzun biliyorum Ya yalnız olacağım Ya da sen olacaksın sonuna kadar Bu yol ya seninle başlayacak Ve de bitecek Ya da hiç gidilmeyecek.....', ARRAY['Türk Edebiyatı','Şiir','Müge Usul']::text[], 8.5, '{"poet":"Müge Usul","poet_slug":"muge-usul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yol-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umudun Olsun Yeter ki...', 'bir-umudun-olsun-yeter-ki-muge-usul-vfa33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen yaşam sırtını döner sana

Ya da sana sorsak,

Hiç gün yüzünü görmedin ki

Her an hediyedir unutma

Bir umudun olsun yeter ki...

Özledikçe güzel yarınları

Bugün değersiz gelir sana

Sen dünün de kıymetini bilmedin ki!

Yaşıyorsan şu anları

Bir umudun olsun yeter ki...

Bir umudun olsun yeter ki

Bir sebebi olsun her uyanışının.

Derdin mi çok?

Kimin yok ki!

Bir umudun olsun yeter ki...', 'Bazen yaşam sırtını döner sana Ya da sana sorsak, Hiç gün yüzünü görmedin ki Her an hediyedir unutma Bir umudun olsun yeter ki... Özledikçe ...', ARRAY['Türk Edebiyatı','Şiir','Müge Usul']::text[], 8.5, '{"poet":"Müge Usul","poet_slug":"muge-usul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-umudun-olsun-yeter-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak', 'yaprak-muge-usul-qn6m8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tükeniş bu,

Yok oluş...

Bir yaprak olmak istiyorum

Hehangi bir kavak ağacında.

Eğer varsa yeniden doğuş', 'Bir tükeniş bu, Yok oluş... Bir yaprak olmak istiyorum Hehangi bir kavak ağacında. Eğer varsa yeniden doğuş...', ARRAY['Türk Edebiyatı','Şiir','Müge Usul']::text[], 8.5, '{"poet":"Müge Usul","poet_slug":"muge-usul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yaprak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik Türküsü', 'genclik-turkusu-muhsin-i-lyas-subasi-hxu52', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşa, Kaybettiğimiz o yurtların yasını, 

Ulubatlı''yla taşı bayrağımı koşarak.

Kays''a bırak en sıcak Leylâ mâcerâsını, 

Bu delişmen çağında destanlar yazmana bak! 

Târık gibi arkanda gemi külleri kalsın, 

Sen yüksel ki yiğidim, düşmanların alçalsın! ..

Sinan ol, kubbe kubbe süsle gökdünyamızı, 

Bize Mevlâna gibi gönül aşkını anlat.

Yeniden üç kkıtada büyüt coğrafyamızı, 

Gurbetteki hasreti getir sevdamıza kat.: 

Kalmasın ne Asya''da ne de Balkan''da acım, 

Bugün sana dünkünden daha çok muhtacım! ..

Alpaslan ol, Fatih ol, Süleyman ol, Selim ol, 

Yurdumu seccade yap, Yunuslar konaklasın.

İstemeden dağıtan hamiyetli elim ol, 

Yüreğin neşemi de, acımı da saklasın..

Sevinsin öksüzlerim altında kanadının, 

Kızlar kelebek olsun etrafında adının...

Sen de yönel uzaya, çelik uydulara bin, 

Sulhun güvercini ol, diren nötrona karşı.

İster yerden göğe çık, ister gökten yere in, 

Seninle söyleyelim, dinlenecek son marşı! 

Tüm soylu duyguların yıkanırken kanında, 

Arınmalı hırsların, aklınla imanında! ..

Hamâset aksiyondur, geriye dönüş değil! 

Beşbin yıllık tarihin anlatır bunu sana.

Bayrağa saygıya dur, mihrabda Rabb''a eğil, 

Teslim olmasın dünyan, bekledikleri son''a! 

Öncüsü ol çağının, fetihlerinde çoğal, 

Ülkülerin süslesin ufuklarını dal dal!', 'Yaşa, Kaybettiğimiz o yurtların yasını,  Ulubatlı''yla taşı bayrağımı koşarak. Kays''a bırak en sıcak Leylâ mâcerâsını,  Bu delişmen çağında d...', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/genclik-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğduğum Ev', 'dogdugum-ev-muge-usul-9s81c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğduğum bir ev vardı benim

İki katlı, ikinci katında biz

İskele Caddesi üzerinde

Her sabah yürürdüm caddeyi

Giderken liseye

Ve doğduğum eve bakardım

Benim pencereme', 'Doğduğum bir ev vardı benim İki katlı, ikinci katında biz İskele Caddesi üzerinde Her sabah yürürdüm caddeyi Giderken liseye Ve doğduğum eve...', ARRAY['Türk Edebiyatı','Şiir','Müge Usul']::text[], 8.5, '{"poet":"Müge Usul","poet_slug":"muge-usul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dogdugum-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kankalar', 'kankalar-kaan-yardim-aq6y0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ortaköy sahildeyiz...

Kafamızda alkolün verdiği berduşluk,

Beynimizde yorgunluğun, bitkinliğin ve yalnızlığın kafası

Aklımızdaysa hep aynı düşünce,

Hep aynı telaş hareketlerde.

Yağmur damlaları tokatlarken suratımızı

Onbirler geliyor bi an için aklımıza.

Derken gümüş rengi gün doğuyor,

Denizse coşuyor coşuyor

Sanki isyan ediyor yeni günün doğuşuna,

Tıpkı bizim kaldıramadığımız gibi...

Galiba deniz de aşık, galiba onunda kafası güzel...

Beraber çizdiğimiz karükatürler geliyor aklımıza

Biran bir tebessüm suratlarımızda...

Sonra yine aynı muhabbet!

O Gözde''yi sayıklıyor ben malum Hande''yi...

Gözde, Hande... Gözde,Hande...

Sonra kafamı Burkay''a çeviriyorum...

''Kanka be! Ne zaman nasip olucak şurdan atlamak? Ne  zaman ...''

''Yok kanka ben unuttum 

Unuttum sevmeyi.

Sevilmeyi olmasa bile unuttum ,

Unutmayı olmasa bile, görmeyi unuttum,

Görmeyi olmasa bile, ağlamayı,

Ağlamayı olmasa bile, dinlemeyi,

Dinlemeyi de diil galiba, kendimi unuttum.

İçime bişiyler doğuyor kalk gidelim

Sabah oluyor evden beklerler''

Derken bir cani kuşun azizliği

Tam orta yerine sıçıyor saçlarımın

Tam orta yerine kafamın...

En iyi kuş anlatıyor olanları, en iyi o veriyor dersimizi.

Gidiyoruz....

Deniz sakinleşti!

Belli ki bizden rahatsız olmuş budala..

Ulan biz, onla senelerdir tanışırdık, içli dışlıydık!

Vaay be!... O da sölemeye çekiniyomuş,

Biz en iyisi kendimize başka dünya arıyalım kanka, burası Yalan olmuş!......

Hemde kocaman bir yalan...... 

Bizi sevenler, bizim sevdiklerimiz ve aşık olduklarımızda

Onlarda sahteymiş meyer,

Onlarda kahpeymiş, şerefsizmiş,

Onlarda arkadaşlarımızmış meyer...', 'Ortaköy sahildeyiz... Kafamızda alkolün verdiği berduşluk, Beynimizde yorgunluğun, bitkinliğin ve yalnızlığın kafası Aklımızdaysa hep aynı d...', ARRAY['Türk Edebiyatı','Şiir','Kaan Yardım']::text[], 8.5, '{"poet":"Kaan Yardım","poet_slug":"kaan-yardim","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kankalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaptan', 'kaptan-attila-i-lhan-zszsc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eflatun gözlerin olduğunu bilmiyordum

 gece yarısını yaşamaktan yorgunum

 ayazın avucunda unutmuştun ellerini

 önünden geçtiğim halde beni tanımadın

 ben değiştim biliyorum hem sakal bıraktım

 şiirlerim kül rengi kumrular gibi uçuşuyorlar 

 bakır çalığı göklere katiyyen tahammülüm yok

 hele paris’in gökleri aklımı başımdan alıyor

 bana seni senden evvelki poitiers’li kızı

 hatırlatıyor

 ayazın avucunda unutmuştun ellerini

 karanlığın arkasında kıvılcım gözlü orospular

 gölgelerine yaslanmış evliya gibi bekliyorlar

 ışıklar kırmızı yandığı zaman duracaksın

 ben değiştim biliyorum hem sakal bıraktım

 soğuk gözlerinde buğulanmıştı ölsen tanıyamazdın

 hatta ricardo bile hani vatansız ricardo

 burnumun dibinden geçti geçen gün beni tanıyamadı

 oysa au vieux chatalet’de akşam sabah beraberdik

 üçümüz viyana kahvesi ve sıcak rom içerdik 

 üstelik o krapfen severdi güzel olurmuş rivayet

 neden ve nasıl sevdiğini anlayamadım gitti

 yalnızlıktan da kurtulup yalnız kalmak isterim

 montmarte metrosu civarında seni gözden kaybettim

 o zenci yine arkanda mıydı hiç dikkat etmedim

 ağzında yoksul bir ıslık ıslak bir cigara gibi

 sidney bichet’nin caz havalarını çiğneyip tüküren

 o saklasın varsın seni sevdigini biliyorum ben

 yüzünün renginden geliyor bütün üzüntüsü

 bir gazete aldım ama evde okuyacağım

 kahvelerden birine girip bir grog ısmarlasam

 seni öldürmek için çareler tasarlasam

 sükut bembeyaz buz tutsa bıyıklarımda

 ve türküm kaybolsa sessizliğin hırçın türküsü

 ve ben unutulsam yazdığım şiirler

 senin için yazdıklarım herkes için yazdıklarım

 eski padişahlar gibi unutulsa birer birer

 ve ben seni unutsam hiç hatırlamasam 

 ellerim oldum olasıya seni unutsalar

 yarı gecenin içinden bir zenci sütbeyaz bakıyor

 rue lafatette’de dünden bugüne geçiyorum

 eflatun gözlerini bir grog kadehinde unuttum', 'eflatun gözlerin olduğunu bilmiyordum  gece yarısını yaşamaktan yorgunum  ayazın avucunda unutmuştun ellerini  önünden geçtiğim halde beni t...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kaptan-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Şiir', 'yeni-bir-siir-sebahattin-isildak-zimqh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çağla''ya

 yeni bir şiirdi şimdi gökyüzü

 acemi bir şair gibi imgelerim tutuldu

 bulutları seyrettim günlerce

 aysız gecelerde düşledim seni

 yıkık bir aşk masalı sonunda 

 kör olmuş bir yürekle kalmak

 göğsüm ter içinde arar tenini

 ellerim tutuk,yüreğimde tel örgüler

 bir kan deryası gözlerim

 hasretlik türküleri yetmez oldu dağlara

feryatlarım yankılanır derin vadilerde

 tarih tarihde kıvranırken

 med topraklarında yanan kaçıncı isyan ateşiydi bu

 analar ağıt yakar oğullara

 çığlıklar saklanır dağlarda

 doruklarda kaynar Murat suyu

 can katar Fırat ''a eski sümerden beri

 ıssız gecelerde neden sustu nehirler

 kırılmış umutları yazdım denize

 kimsesiz gözlerim yüklüdür yeni sevdalara

 malum olsun dağlara

 gökyüzü şahidimdir

 ateş ,küle küstüğünden beri

 korkutan yüreğimi

 düşlerimin düşsüz kalmasıdır

 hangi rüzgar sesini taşırki bana

 bir gemi daha kalktı bu limandan

 karanlık sulara doğru

 sensizlik sessizliği bastırıyor kaç gecedir

 sanki öleli çok olmuş

 bu gezegeni terk edeli

 yağmur sonrası toprak kokusunda öpmek seni', 'çağla''ya  yeni bir şiirdi şimdi gökyüzü  acemi bir şair gibi imgelerim tutuldu  bulutları seyrettim günlerce  aysız gecelerde düşledim seni ...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Işıldak']::text[], 8.5, '{"poet":"Sebahattin Işıldak","poet_slug":"sebahattin-isildak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yeni-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açlıktan Tokluğa Bakış', 'acliktan-tokluga-bakis-mehmet-caner-sumengen-7n25a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O aç adamın, tok adama bakışıydı

İçimi böylesi acıtan...

Ve 

O tok adamın, 

Aç adama bakmayışıydı

Beni 

Yangınların ortasına atan...', 'O aç adamın, tok adama bakışıydı İçimi böylesi acıtan... Ve  O tok adamın,  Aç adama bakmayışıydı Beni  Yangınların ortasına atan......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/acliktan-tokluga-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmekten Vazgeçenlere', 'donmekten-vazgecenlere-mehmet-caner-sumengen-205et', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dönmekten vazgeçer de uzaklarda yaşarsan

Bahçelerden çiçekler kopartmam senin için.

Verdiğin sözden döner de sevgimden kaçarsan

Yüreğimde umutlar yeşertmem senin için...', 'Dönmekten vazgeçer de uzaklarda yaşarsan Bahçelerden çiçekler kopartmam senin için. Verdiğin sözden döner de sevgimden kaçarsan Yüreğimde um...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/donmekten-vazgecenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Labirent Sevda', 'labirent-sevda-mehmet-caner-sumengen-3y2kw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir labirent bu sevda

Ne başı belli, ne de sonu

Karmakarışık duygular duvarı

Her yanı sarmış

Akıllar firari.

Biz böyle değildik eskiden

Tüm çıkışlarımız

Sevgiye, aşka idi.

Şimdi anlayamıyorum

Var ile yoku ayırt edebilmek

Ya ölmekten geçiyor

Ya da öldürmekten.

Düşlerimin katili dediğim sen

Umutlarımı çalan da sen

Ah elime bir geçsen.

Bir labirent bu sevda

Gittikçe gelinen

Yolları bitmeyen

Kapıları yüzüme kapanmış

Yine de, sonsuza dek içinde koşacağım

Bulmaya yaşayacağım

Bir labirent bu sevda

Arayan ben, aranan sen...', 'Bir labirent bu sevda Ne başı belli, ne de sonu Karmakarışık duygular duvarı Her yanı sarmış Akıllar firari. Biz böyle değildik eskiden Tüm ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/labirent-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-beril-onbulak-8bahi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sen vardın çocuk gibi inandığım

Hiç hesapsız yüreğime kardığım

Bir sen vardın gülerken ağladığım

Yokluğunda hep aradığım

Bir sen vardın mutluluğu yakaladığım

Uğruna ölümlere atladığım

Bir sen vardın

Aşkı koşulsuz yaşadığım

Mecnun''dan daha Mecnun

Bir sen vardın 

Şimdi yoksun yar

Nerdesin?', 'Bir sen vardın çocuk gibi inandığım Hiç hesapsız yüreğime kardığım Bir sen vardın gülerken ağladığım Yokluğunda hep aradığım Bir sen vardın ...', ARRAY['Türk Edebiyatı','Şiir','Beril Onbulak']::text[], 8.5, '{"poet":"Beril Onbulak","poet_slug":"beril-onbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerdesin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niçin', 'nicin-beril-onbulak-ibxhd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi gözler

Yaşla dolu

Ağlıyor için için...

Dertler , kederler

Hep seni bulur

Niçin?', 'Mavi gözler Yaşla dolu Ağlıyor için için... Dertler , kederler Hep seni bulur Niçin?...', ARRAY['Türk Edebiyatı','Şiir','Beril Onbulak']::text[], 8.5, '{"poet":"Beril Onbulak","poet_slug":"beril-onbulak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nicin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liseli Kız', 'liseli-kiz-yavuz-bulent-bakiler-hxdhi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim de bir zamanlar sevdiğim vardı

Beyaz dantel yakalı liseli bir kız.

Bağlarda, bahçelerde, yaylalarda yeşeren

Al karanfiller gibiydi aşkımız...

Gülünce içimde rengârenk güzel,

Güller açılırdı iri.

Hani bilirsiniz ya yıldızsız siyah 

Geceler gibiydi gözleri.

Bir mermer çeşmeden akan su gibi,

Geçip gidiyordu günlerimiz.

Biz bize yaşıyorduk kendi kaderimizi

Bütün yaratılkardan habersiz.

Ve yuvada bekleşen sabırsız, küçük 

Serçeler gibiydik ikimiz.

Gözleri konuşurdu susunca, mahzun:

''Seni seviyorum'' derdi.

Sevdadan, gurbetten, hasretten yana

Sıcak türküler söylerdi...

Üstelik bir ceylan gibi sebepsiz

Ürkek halleri vardı.

Ayrılık deyince oturup sessiz

Çocuklar gibi ağlardı.

Bilmiyorum simdi kaç yıl, kaç mevsim

İçli mektuplar yazdık.

Bazen yan yana yürür, beraber otururduk

Ama konuşamazdık.

Ben görmedim şimdi öyle diyorlar

Büyümüş artık liseli kız, gelin olmuş...

Unuttum her şeyi diyormuş 

Ve her gece rüyâsını nur topu kadar güzel

sarışın çocukları süslüyormuş.

Görsem çocularını şimdi diyorum

Bakamam yüzlerine çaresiz

Bana bakar çocuklar sessiz.

Çocukları gözlerinden tanırım

Biliyorum, hiç birşey bilmezler ama 

Bakamam,  utanırım', 'Benim de bir zamanlar sevdiğim vardı Beyaz dantel yakalı liseli bir kız. Bağlarda, bahçelerde, yaylalarda yeşeren Al karanfiller gibiydi aşk...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/liseli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolumuz İnsana', 'yolumuz-i-nsana-tayfun-talipoglu-a488c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Demem şu ki sevgilim

Demem şu  ki sevgilim

Bir yerinde yaşamın

Birileri

Bittiğini anlatıyorsa durmadan sevdaların

Ve az biraz,

Tutunduğumuz yerinden

Basıyorsa yüreğimize

Direnmek gerek

Direnmek gerek ki hem de nasıl

Hani diyor ya Usta;

“o iyi insanlar,o güzel atlara binip gittiler”

gitmemişler...

gittilerse de dönmüşler

sevdaları zulalarında

konuşacakları günü beklemektedirler', 'Demem şu ki sevgilim Demem şu  ki sevgilim Bir yerinde yaşamın Birileri Bittiğini anlatıyorsa durmadan sevdaların Ve az biraz, Tutunduğumuz ...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Talipoğlu']::text[], 8.5, '{"poet":"Tayfun Talipoğlu","poet_slug":"tayfun-talipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yolumuz-insana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Münzevinin Aynaları', 'munzevinin-aynalari-cahit-koytak-4808m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya olmasaydın, Tanrım,

        Ya olmasaydın! 

İnsanların en hakiri olduğumu düşünüp de

Ruhumu oruçlarla, erdemlerle

         Kırbaçladığımda

Bakışlarımdaki kibri aynada

          Yakaladığım zaman

Utançtan yüzümü avuçlarımla

          Kime kapardım, Tanrım? 

Ya olmasaydın! 

İnsanların en kibirlisi olduğumu düşünüp de

Onurları kırılmışların önünde

          Yere kapandığımda

Varlığım bu küçümen tanrıların ayaklarıyla

          Bir kenara itildiği zaman

Yakınmalarımı, sitemlerimi

          Kime yapardım, Tanrım? 

Ya olmasaydın! 

Harami ininde mürüvvet,

Köle pazarında paye dağıtılırken

''''Bir kenarda kalma''yı marifet,

          Ve unutulmayı marifet bilerek

Beyliği sultanların katında 

           Aramaya çıkıpta sonra

Yarı yoldan dönmeyi başardığım zaman

Sürurumu kime gösterip, kime

           Kurum satardım, Tanrım? 

Ya olmasaydın! 

Sürurla dolup taştığım anlar

Dağları, sır yüklü develer gibi,

Yerinden oynatabileceğimi,

          Yürütebileceğimi

Düşünüp coştuğum ve naralarımla

Yalnızca fareleri ürkütüp,

          Vaşakları, dağ keçilerini...

Sonunda uyuyan aslanı

           Uyandırdığım zaman

Hercai gönlümü can tasasıyla

Kimin yılkısına

           Katardım, Tanrım? 

Ya olmasaydın, Tanrım,

           Ya olmasaydın! 

Yürüdüğüm yollar tükendiğinde

Dostlar yabancıya,

            Sıla gurbete benzediğinde...

Kırbamda su, heybemde azık

Ve türkülerimde...

             Türkülerimde söz bittiğinde; 

İnsanın kıt

Gecenin yıldızsız

İfritlerinse, daim peşimde

(Hem uyanıkken hem de düşümde) 

              Olduğu zaman,

Kimin kapısını omuzlayarak

               Hoyratça açar da, kimin

Aynalarını parçalayarak

Canımı içeri atardım, Tanrım,

               Sen olmasaydın?', 'Ya olmasaydın, Tanrım,         Ya olmasaydın!  İnsanların en hakiri olduğumu düşünüp de Ruhumu oruçlarla, erdemlerle          Kırbaçladığımd...', ARRAY['Türk Edebiyatı','Şiir','Cahit Koytak']::text[], 8.5, '{"poet":"Cahit Koytak","poet_slug":"cahit-koytak","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/munzevinin-aynalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kekeme', 'kekeme-cahit-koytak-h7v2a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ah, ölmek mi, öğrenmek mi,

ebediyen susarak, konuşmayı seninle; 

otların, rüzgarların,

taşların ve yağmurların her telde,

her makamda falsosuz,

gürül gürül konuştukları dili? ...

susmak... susarak unutturmak

boşboğaz sözcüklere,

kekeme mabeyncilere,

gündelik ayinlerin,

aklın öğrettiklerini.

ve şeylere geri vermek,

şeylere... aynalara, yüzlere

bütün bildiklerimizi.', 'ah, ölmek mi, öğrenmek mi, ebediyen susarak, konuşmayı seninle;  otların, rüzgarların, taşların ve yağmurların her telde, her makamda falsos...', ARRAY['Türk Edebiyatı','Şiir','Cahit Koytak']::text[], 8.5, '{"poet":"Cahit Koytak","poet_slug":"cahit-koytak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kekeme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiraz Bahçesi', 'kiraz-bahcesi-betul-dunder-jq1yv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'C.''ye dair...

kiraz bahçelerinden geliyordum

yakamda hınzır çocukların gülümsemeleri

seni sevmekten geliyordum

bir çeşit yalansızından sevda cümleleri

tren yolculuklarında

kiraz bahçelerinin resmi geçitleri

o hınzır çocuklar yok şimdi

seni o denli sevmek yok

tren yolculukları yok

sek sek oynuyorum sanmıştım

önümde çizdiğin kareleri atlarken

geri döndüğümde

tüm eski yollarımı silmiştin

büyümek

kiraz bahçelerinden kaçmakmış

ya ben ne anlamıştım', 'C.''ye dair... kiraz bahçelerinden geliyordum yakamda hınzır çocukların gülümsemeleri seni sevmekten geliyordum bir çeşit yalansızından sevda...', ARRAY['Türk Edebiyatı','Şiir','Betül Dünder']::text[], 8.5, '{"poet":"Betül Dünder","poet_slug":"betul-dunder","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kiraz-bahcesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güçlü Olmalısın Arkadaş', 'guclu-olmalisin-arkadas-unver-genc-j4frl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güçlü olmalısın arkadaş,

Başın dik olmalı.

İçin kan ağlarken bile yüzün şen olmalı

Gözyaşların hüzün gözyaşı değil,

Sevgi gözyaşı olmalı.

Ezilmişlerin ezilmişliğini,

Çaresizlerin çaresizliğini kullananlara inat.

Sevgi nedir bilmeyenlere inat,

Güçlü olmalısın arkadaş...', 'Güçlü olmalısın arkadaş, Başın dik olmalı. İçin kan ağlarken bile yüzün şen olmalı Gözyaşların hüzün gözyaşı değil, Sevgi gözyaşı olmalı. Ez...', ARRAY['Türk Edebiyatı','Şiir','Ünver Genç']::text[], 8.5, '{"poet":"Ünver Genç","poet_slug":"unver-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/guclu-olmalisin-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-ahmet-gungor-wr8tw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölerek sır verecek toprağa ten

Ruha yelken olacaktır bu kefen

Bir gururun kalıyor pes demeyen

O da bugün sana boyun eğdi gönül', 'Ölerek sır verecek toprağa ten Ruha yelken olacaktır bu kefen Bir gururun kalıyor pes demeyen O da bugün sana boyun eğdi gönül...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güngör']::text[], 8.5, '{"poet":"Ahmet Güngör","poet_slug":"ahmet-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gonul-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiremit Uçuran', 'kiremit-ucuran-erhan-guleryuz-1nilv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rutubetliydi küçük oda,küf kokardı.

Soba uzak bir duvarda yanarken soğuk günlerde,

o hep küçük odaya giderdi.

Kiremit uçuran bir kar fırtınasında odaya girdim.

Pencere önündeydi.

Sordum:

''Ne var ki bu odada, küf ve rutubetten başka?''

''Rüzgar''dedi.

''Evlat,rüzgar.

Yalnız buradan güzel duyulur.''

Eliyle camın buğusunu sildi,parmak parmak...

Karlı, karanlıktı sokak.

''Dinle''dedi.

 ''Dinle bak...''', 'Rutubetliydi küçük oda,küf kokardı. Soba uzak bir duvarda yanarken soğuk günlerde, o hep küçük odaya giderdi. Kiremit uçuran bir kar fırtına...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kiremit-ucuran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Vakti Kalkan Kervan', 'seher-vakti-kalkan-kervan-pir-sultan-abdal-2uvmz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seher vakti kalkan kervan,

İniler de zarilenir.

Bir güzele düşen gönül,

Çiçeklenir, korulanır.

Bahçenizde güller biter,

Dalında bülbüller öter.

Engel gelir bir kal katar,

Olan işler gerilenir.

Bülbül geldi kondu dala,

Bülbülden hata yok güle.

Engel bir taş atar göle,

Yüzen ördek yaralanır.

Pir sultan abdal göçelim,

Pir elinden bade içelim.

İnkar olandan kaçalım,

İnkar bir gün parelenir.', 'Seher vakti kalkan kervan, İniler de zarilenir. Bir güzele düşen gönül, Çiçeklenir, korulanır. Bahçenizde güller biter, Dalında bülbüller öt...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seher-vakti-kalkan-kervan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vagon', 'vagon-edip-cangonul-ttq6h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geldi yine kervanı,

                 Katarı,

Gam yükünün.

Grevdeydi işçiler

Boşaltmadılar gam vagonunu

Ben kaldım,

Bir sürü gam.

Bir de vagon,

           yalnız,

sevdası 2 rayın ucunda.

Vagon ağladı halime

Ben sevdasına 

vagonun

Sonsuzluğunda rayların

Vagon bana

Bana sevdanın ettiklerine

Ağlaştık

Hamallar geldi sonra

Para ile tutmuşlar

Totaba yani

Gamı ayrı vagona yüklediler

Bana ceza;

              Biletsiz trene binmekten

Vagon

Yalnız vagon...', 'Geldi yine kervanı,                  Katarı, Gam yükünün. Grevdeydi işçiler Boşaltmadılar gam vagonunu Ben kaldım, Bir sürü gam. Bir de vago...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vagon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzbağ', 'buzbag-edip-cangonul-25yzw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün dağda idik seninle

Acıkmıştık hani

Acıkmıştık, 

kirvem seninle

Bağlardaki kara üzümlere sulandık

           Zil siyahtı

           Zalım bakan gözlerince

Öküzgözlerine dadandık

           Kızıl

           Sarhoş

Bir baktı ki zalım

            Nadan

                Ve hayın

Bulaştırdı kızıllığını

Düştüm

Bir kar tanesi gibi dibine al güneşin

Kar, kızıllaştı

Öküzgözü de

Altında güneşin

Uyandım nice sonra

Öküzgözü asmasının altında

Buzbağıydım artık

             Kızıl

             Sarhoş

Bir gelincik

              Kızıl

Yürekteki  sevda da

Ayrılık bir gelincik kızıllığında

Ölüm buzbağ sarhoşluğunda

Zulüm her zaman ki gibi', 'Bir gün dağda idik seninle Acıkmıştık hani Acıkmıştık,  kirvem seninle Bağlardaki kara üzümlere sulandık            Zil siyahtı            Z...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/buzbag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzbağ, Yürek Ve Hain', 'buzbag-yurek-ve-hain-edip-cangonul-awam5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '3 kişi içiyordu, 

Buzbağ, yürek ve hayın.

yeniden şenlendi çay bardakları, 

yeşil otlar üstünde.

Yürek; 

“ikinizden de çok çektim

hayının zulmünden

senin de şaraplığından”

ve hayın; 

“seni sevmem buzbağ, 

tek sevdiğimdir

bu aptal yürek

yüceltir beni

her kötülüğümde 

Neşelendi bardaklar, 

Doldurdu buzbağ; 

“beni zor anlarsınız” dedi, 

“bilmezsiniz, tanımazsınız”.

“Ama ben, 

sizi iyi tanırım, 

hücrelerinize dek”. 

                 17,05,2000', '3 kişi içiyordu,  Buzbağ, yürek ve hayın. yeniden şenlendi çay bardakları,  yeşil otlar üstünde. Yürek;  “ikinizden de çok çektim hayının zu...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/buzbag-yurek-ve-hain-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesiz', 'sesiz-elif-gultekin-97wi5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün bir garip bakıyorum hayata

Hani bir yaz sabahı uyanıp camdan bakarsında

Güneş tüm güzelliğiyle gülümser ya insana

İşte öyle bir şey bugün yaşamak

Yine de sensiz olmuyor 

Yüzen insanlar görüyorum odamın duvarlarında

Sonsuz... Her yerde insan var ve mutlular

Bir balık görüyorum sonra suda

Ağlıyor...

Dedim ya sensiz olmuyor....', 'Bugün bir garip bakıyorum hayata Hani bir yaz sabahı uyanıp camdan bakarsında Güneş tüm güzelliğiyle gülümser ya insana İşte öyle bir şey bu...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sesiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Pazar İstanbul Ağlıyor Benim Yerime', 'bu-pazar-i-stanbul-agliyor-benim-yerime-fatih-cunus-hnflp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu pazar İstanbul ağlıyor benim yerime

Beni benden daha iyi anlatıyor yağmur tanecikleri

Gökyüzünün kasvetinde duyumsadım yine seni

Bulut oldum, rüzgar oldum geldim yanına

Ve yağmur oldum yağdım delicesine

Hissedebilmek için seni her yağmur zerresinde

Haydi artık dışarı uzat elini

Yakala birkaç yağmur tanesini

Tenini yakından hissedersem

Yağmur tanesi kadar bile duysam sıcaklığını

Diner belki gönlümün yağmurları', 'Bu pazar İstanbul ağlıyor benim yerime Beni benden daha iyi anlatıyor yağmur tanecikleri Gökyüzünün kasvetinde duyumsadım yine seni Bulut ol...', ARRAY['Türk Edebiyatı','Şiir','Fatih Cünüş']::text[], 8.5, '{"poet":"Fatih Cünüş","poet_slug":"fatih-cunus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bu-pazar-istanbul-agliyor-benim-yerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Çocuğu', 'kiz-cocugu-tevfik-mengulluoglu-hu5c3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün Güneş Biraz erken doğar

Ve birden caddeler yıldızlarla Taşar

Gök Gürülder ama bir türlü yağmur Yağmaz

Kiremit çatılı Bir evde bir kız çocuğu Doğar

Bugün havada yarasalara uçma yasağı var

boranlar rüzgarı yararak alçaktan uçar

ve aşağıdan inatla ağlayan bir bebek sesi 

Kiremit çatılı bir evde bir kız çocuğu doğar

Umutlar yıdızlarla kenetlenir bir anda

Buğday tanesi atsan düşmez kızılay meydanına

Dizçöker dağlar menekşemin karşısında

Kiremit çatılı bir evde bir kız çocuğu doğar.', 'Bugün Güneş Biraz erken doğar Ve birden caddeler yıldızlarla Taşar Gök Gürülder ama bir türlü yağmur Yağmaz Kiremit çatılı Bir evde bir kız ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiz-cocugu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarının Sevdası', 'yarinin-sevdasi-tevfik-mengulluoglu-qb3fq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ölümsüz sevdamın sevdalısıyım

Mor dağlardan Toroslara uzanır yarenlerin türküsü

Yüksek tepeden haykırırlar ufuktaki güneşi 

avuçlamak için.

Ben ölümsüz sevdamın sevdalısıyım

Gece konduda bekler bir ana yüreği

fabrika kapısında yoksul bir abla özlemi

özlenir yarenler yarenler her güneş batışında

ben ölümsüz sevdamın sevdalısıyım.', 'Ben ölümsüz sevdamın sevdalısıyım Mor dağlardan Toroslara uzanır yarenlerin türküsü Yüksek tepeden haykırırlar ufuktaki güneşi  avuçlamak iç...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yarinin-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunay', 'dolunay-tevfik-mengulluoglu-kg2ds', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece dolunayla yıldızları izliyorum enson bıraktığın yerden

ve baktıkça gözlerinin maviliğini görüyorum

sokaklarında dolaşmak istiyorum gözlerinin

Gece dolunay

Yağmurla mücdeler gönder gökyüzünden

Rüzgarla gönder dalga dalga saçlarını tane tane

asfaltta yağmurdan kalan aynalarda görüyorum

dalga dalga saçlarının sarılığını

Gece Dolunay

Kıyısından geçmiyor kara bulutlar 

Yinede vuruyor yüzüme yağmur damlacıkları

sokaklar ıslak temiz ama ıssızca

ve ben özlüyorum yine gözlerinin parlaklığını

Gece dolunay

Gözlerinin maviliği kayboluyor

Saçlarının sarılığı ve yıldızlar kayboluyor

Güneş minik bir yara açıyor gökyüzünde

ve ben uyanmak istemiyorum bu rüyadan

kaybolsun istemiyorum dolunay.', 'Bu gece dolunayla yıldızları izliyorum enson bıraktığın yerden ve baktıkça gözlerinin maviliğini görüyorum sokaklarında dolaşmak istiyorum g...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dolunay-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-tevfik-mengulluoglu-c3ml9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevabım olacak derdinde değilim artık 

Günahlarım dizboyu almış başını 

Hatırlıyorum uzak zaman önce dökerken acımasızca

gözlerin gözyaşlarını

yokluğuma bakıpta ağlama

Hep aynı şeyi yapmaktan usanmışsındır

ben nasıl bıktıysam sensiz yaşamaktan

Hangisi senin hangisi benim

kaç banka kartı ne kadar hesapta para

bir apartman veya bir araba

benden bıkmış senden uzak, Benden utanmış bunlar sevgili

ve hayatın ardında hepsi

senide unuttum sevglli

unutmak istemediğim isimsiz bir akşamda

unuttum işte

gücenmezsin sen bilirim

seni hiç unutmak istemedim.', 'Sevabım olacak derdinde değilim artık  Günahlarım dizboyu almış başını  Hatırlıyorum uzak zaman önce dökerken acımasızca gözlerin gözyaşları...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sitem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdama Doğru', 'sevdama-dogru-tevfik-mengulluoglu-qqvlk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben denizim

bazende bulut

Yıldızlardan''da çalarım

Saz çalarım çiçek açarım

Irmak olup oluk oluk akarım

Aktıkça coşarım

size doğru sevdama doğru denize doğru

Bazan bazan taşarım

kucaklarım heryeri

her çiçeği her sevgiyi

size yalnız size varmak için varmadıkça 

gözyaşlarım akar

O zaman olur sizinle kucak kucak bahar

İsterim yıldız gibi yüksekte oluyum

ay oluyum güneş oluyum 

ama size yalnız size sunmak için

bütün güzellikleri.', 'Ben denizim bazende bulut Yıldızlardan''da çalarım Saz çalarım çiçek açarım Irmak olup oluk oluk akarım Aktıkça coşarım size doğru sevdama do...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdama-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudu Vurmasınlar', 'umudu-vurmasinlar-tevfik-mengulluoglu-hom42', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son defa söz veriyorum kendime ağlamayacağıma dair 

ne güzelmiş dört mum ışığında karşılamak yeni yılı

sıcak türküler eşliğinde

yeterki umudu vurmasınlar

Önemli değil yılın başı yada sonu

varsa dört mum ve duruyorsa kızıl karanfiller vazoda

mırıldanıyorsa yaşlı anne sıcak bir türküyü

dur yakala hayatı ucundan 

 umudu vurmasınlar

Üzülme sen tahta masanın ayağı eksik diye

şarap şişeside öyle dursun, köyümüzde ceryan yok ama

dikebiliyorum beş mumu ortasında masanın

Umudu vurmasınlar.

Belki bir mum parası daha geçecekti elime yirmi altı yaşımda  altı mum yakabilmem için, 

umudu vurmasınlar.

Toprakta ilk çatlayan tomurcuk

gözlerini dünyaya açan bebek

sevgi umut karışımlı ilk aşıyı biz yapalım, karanlıktaki ilk mumu biz yakalım onlara yeterki umudu vurmasınlar.', 'Son defa söz veriyorum kendime ağlamayacağıma dair  ne güzelmiş dört mum ışığında karşılamak yeni yılı sıcak türküler eşliğinde yeterki umud...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umudu-vurmasinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-tevfik-mengulluoglu-t2k5s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşı henüz onaltıydı

Sarılmak isterken umuda

alırken kalemi parmakları arasına

kucaklıyamazdı titremeden elleri

Onca çektiğine onca yaşadıklarına

sarılmak belki en iyisiydi yaşadıklarına

belkide avuçlamak en iyisiydi umudu

Hangi limana girmeliydi

Hangisine demir atmalıydı

onca yükle azgın dalgalara göğüs gerebilecekmiydi? 

Yoksa yüzyıl sonra dibinden denizin

çıkarılıp müzesine konacak hayatın.

Uzaklardan usunun çalarken kapısını 

seçebilecekmiydi

ona açılan güzelliklerin yolunu.', 'Yaşı henüz onaltıydı Sarılmak isterken umuda alırken kalemi parmakları arasına kucaklıyamazdı titremeden elleri Onca çektiğine onca yaşadıkl...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocuk-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamın Şehri', 'sevdamin-sehri-tevfik-mengulluoglu-1szky', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidiyorum sevdamın şehrinden

Güneş doğarken.

Gidiyorum sevdamın şehrinden

Güneş batarken...

Sıyrılıp anılardan,uzanırken çıplak gözle

Gördüklerime; 

Yine gözyaşlarım akıyor durmadan.

Vakit vakitlerden oniki eylül,

vakit  vakitlerden bir mayıs

içime haps ederek götürüyorum

uzaklara, kimisinin gitmiş çocuğu, 

kimisinin annesi

vakit vakitlerden cumartesi...

Terrorossa örtüsüyle kaplı,

toroslardan geçiyorum

tüm ağaçlar ve dağlar 

karşımdan geçip gidiyorlar uzaklara.

Arkama baktığımda 

hepsi el sallıyordu,kiminin yüreği buruk,

kiminin şapkası eğik

Tekerleklerin asfalt yolla 

sohbeti esnasında uyanıyorum.

Rüyamda gök kuşağının altından geçerken

Ne güzelmiş Akdenizin tatlı maviliği,

Heryer mavi; sadece ufukta güneş var

Bana el sallıyordu utancından kızarırken

Yoksa rüyamı görüyordum

ama! 

sahiden gözyaşlarım akıyor.', 'Gidiyorum sevdamın şehrinden Güneş doğarken. Gidiyorum sevdamın şehrinden Güneş batarken... Sıyrılıp anılardan,uzanırken çıplak gözle Gördük...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevdamin-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Izdırap', 'izdirap-cuma-kaya-7nlj8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ölümsüz ve erişilmez aşk vardı önce

gözyaşlarıyla yıkandı

sonra sevda hamuru

bir yanılgının inleten ızdırabından

gözyaşları hiç dinmedi

mecnunlar bilir ızdırabı

çolde ceylanlarla söyleşen

gecenin mavi karanlığında

herbir köşesine yıldızların

hıçkırıklarını saklayanlar

en iyi bilenlerdir acıyı

kapılar sürmelenir

panjurlar çekilir

yıldızlar hilalle söyleşir

en deli rüzgarlar

zülüflerini okşar gecenin 

titrek elleriyle

ruhunu bedenine ezdirenler

soğuk gecelerin 

bilmez nicedir çehresi

mecnunlar bilir

kaç saattir geceler

semanın sakinlerinin nazarlarını

uykusuz gecelerin sahipleri bilir

kuşların ve sürme gözlü ceylanların birde

ürkeklik dileneceği yüreğinde

gelgitleri dolaşır zamanın

kanlı dağ zirvelerinde

sıcapa hasret kardelenleri

gönlünün ateşiyle

ısıtacağına inanır aşıklar

ve gözyaşlarıyla beslenir tabiat

azgın çöl kumları üzerinde

kartopu duygularla büyür ümitler

döner gündüzler geceye

inişler yokuşa

açmaz olur ümitle beslenen

sevda çiçekleri

melek kanatlarıyla yağmurlar okşamaz olur

bülbüller küskündür güle

seher vakti ötmez olur

gül yaprağı aşıkın kanıyla

bürünür kızıla.', 'ölümsüz ve erişilmez aşk vardı önce gözyaşlarıyla yıkandı sonra sevda hamuru bir yanılgının inleten ızdırabından gözyaşları hiç dinmedi mecn...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/izdirap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nehirin Gökyüzü', 'nehirin-gokyuzu-hakan-sengorun-dny9d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşen bir ıssızlık

koşan yağmurlar

bulutlar ellerinde sen gülümsediğinde

kendine ait içinden gelen herbir yaşam

rengi soluk çiçekler topladık düşlerde açmış

su rengi bir ölümsün sen hüznü mutluluğundan taşan

kelime ve kelebekler uçup gittiklerinde konacakları yer

onları unutulmaz kılar kısa yaşamlarında sessiz bir yağmur görseler her ağlayışları bir ölüme dönüşür

Nehirin gökyüzü bu çok uzaklarda o burdan

Nehirin elleri bunlar dokundum desem kendime inanmam

çok uzak o buraya gökyüzü var onun bir de sonu olmayan

bir düşü 

her bakışıma değecek bir yüzü...

her ölümde doğacak bir sözü...', 'Düşen bir ıssızlık koşan yağmurlar bulutlar ellerinde sen gülümsediğinde kendine ait içinden gelen herbir yaşam rengi soluk çiçekler topladı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nehirin-gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temenni', 'temenni-cuma-kaya-1ozd7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dilerim yaşadığın müddetçe

mutluluğun her boyutunu tadarsın

ömrün boyunca seni üzecek engeller

önünden eğilerek çekilsin

gül bahçendeki güllerin kokuları hiç dinmesin

çevrene gül kokuları saçasın

ama izin ver gül bahçesinde

senin dikenlerine takılmış

garip bir bülbül yaşasın.', 'dilerim yaşadığın müddetçe mutluluğun her boyutunu tadarsın ömrün boyunca seni üzecek engeller önünden eğilerek çekilsin gül bahçendeki güll...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/temenni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhamet', 'merhamet-cuma-kaya-lkd71', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'merhamet dilenirken insanlardan

ve otururken soğuk kaldırımlarda

kalan bir parça gururundan

kaldırıp yere vurdu elindekileri

boynu bükük,iki damla yaş döküldü

gözlerinden minik kız çocuğunun

kalbindeki son sevgide

uçup gitti nefret rüzgarlarıyla

başını kaldırıpta baktığında yüzüme

içim ürperdi sevgisiz donuk bakışlarıyla

dalıp kaldı gözleri gözlerime

sonra kayboldu sokağın karanlığında

o cılız adımlarıyla

bir daha görmedim onu sokaklarda

ondan bundan merhamet dilenirken

ve kaldırımların gözden uzak bir kuytusunda

hıçkırıklarla ağlarken

farkı neydi acaba diğerlerinden

sebebi neydi bu sonun

merhamet cimriliği yüzünden

mahrum etmek dünyayı sevgisinden bir çocuğun', 'merhamet dilenirken insanlardan ve otururken soğuk kaldırımlarda kalan bir parça gururundan kaldırıp yere vurdu elindekileri boynu bükük,iki...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/merhamet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen', 'beklenen-cuma-kaya-hfdyn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yüzündeki sakal kirli

gözaltlarında torbalar

hayatının ne zor geçtiğini

anlatıyordu anlındaki buruşuklar

her akşam saat beş otuzda

asırlık o çınarın altında

sardığı sigarasının efkarlı dumanında

denizin uzak ufkuna dalıp giderdi

neyi beklerdi kimi beklerdi

gelecek,hep gelecek derdi

söz vermişti elbette gelecekti

o,gelene kadar bekleyecekti

birden ,aniden gülümsedi

biliyordum geldin işte dedi

koşarken takıldı düşüverdi

sonsuzluğa yol alan gemiye oda bindi

suratındaki hiç tatmadığı

bir mutluluk ifadesiydi

beklediği kimdi?

azrail mi?

yoksa,yıllar öncesinden

söz aldığı sevgilisi miydi?', 'yüzündeki sakal kirli gözaltlarında torbalar hayatının ne zor geçtiğini anlatıyordu anlındaki buruşuklar her akşam saat beş otuzda asırlık o...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beklenen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgin', 'sevgin-cuma-kaya-3z4yf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uçtuk

göyüzünde uçtuk

içimizdeki sevgiyi

dünyaya savurduk

özgürdük

martılar gibi alabildiğince

dünya küçüldü

büyüdü aşkımız

sevgimiz büyüdü

çünkü biz

sevginin ellerini tuttuk.', 'uçtuk göyüzünde uçtuk içimizdeki sevgiyi dünyaya savurduk özgürdük martılar gibi alabildiğince dünya küçüldü büyüdü aşkımız sevgimiz büyüdü ...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-cuma-kaya-61r5c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'oturmuşum tek başına

küçük bir havuzun yanıbaşında

yemyeşil çimenlerin ortasında

suyun huzur veren şırıltısında

elimde sigaram seni düşünüyorum

iki sevgli geliyor aklıma

biri sen,diğeride 

seni bekleyen ben

şimdi sende olsaydın yanımda

dalıp gözlerinin içine hayal kursaydım ya

uçup seninle mavi gökyüzüne

engin denizleri beraberce geçseydik ya

sonra tutuşup elele gezseydik kumsalda

her zaman yaptığımız gibi

uzansaydık bulutlara

kırmızı bir gül taksaydım saçlarına

öpüp koklasaydım ya seni

bir kere daha haykırsaydım sevgimi', 'oturmuşum tek başına küçük bir havuzun yanıbaşında yemyeşil çimenlerin ortasında suyun huzur veren şırıltısında elimde sigaram seni düşünüyo...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayal-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-cuma-kaya-tpbk8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uçmak isterdim gökyüzünde kırlangıçlar misali hür

uçsuz bucaksız ovaların üzerinden

haykırmak isterdim yüreğimi yırtarcasına gür

içimdeki sevdanın alevinden

ve özlemime olan özlemimden

bir serçe aşkını dile getiriyor eşine

bir bülbül sevdasını şakıyor gülüne

bir turna süzülüyor gökyüzünden sevgilisine

ve bir aşık özlemini anlatıyor özlemine

oturmuşum karanlık çadırın ortasında

hasretin gözlerimde,sensizlik başucumda

özlemlerim kollarımda,özlemim uzaklarda

günlerim bitmez zaman geçmez buralarda

sen benden uzak oldukça oralarda', 'uçmak isterdim gökyüzünde kırlangıçlar misali hür uçsuz bucaksız ovaların üzerinden haykırmak isterdim yüreğimi yırtarcasına gür içimdeki se...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hasret-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Suskundu', 'her-sey-suskundu-cuma-kaya-9oy4m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'suskundu gece gittiğin akşam

suskundu şehir suskundu rüzgar

gözlerim dolupta yollarına baksam

hasret pınarı durmadan akar

özledim kokunu rüzgara sorsam

ayrılık haberin yüzüme çarpar

durup bir anlık birazcık düşünsem

yüreğim durmadan, her zaman ağlar', 'suskundu gece gittiğin akşam suskundu şehir suskundu rüzgar gözlerim dolupta yollarına baksam hasret pınarı durmadan akar özledim kokunu rüz...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/her-sey-suskundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret-2', 'hasret-2-cuma-kaya-vvnq2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ah sevgilim 

yine bu akşam sensizim

gözlerim nemli yüreğim hüzünlü

yine bu akşam neşesizim

ayrılık akşamları bitmek bilmiyor

sabah olmak bilmiyor sensiz

sensiz günler geçmiyor

gün başlarken yine ümitsiz

yağmurlar dinmiyor

hasret bitmiyor

özlem bitmiyor özlemsiz

yine bu akşam özlemsizim', 'ah sevgilim  yine bu akşam sensizim gözlerim nemli yüreğim hüzünlü yine bu akşam neşesizim ayrılık akşamları bitmek bilmiyor sabah olmak bil...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Acısı', 'ayrilik-acisi-cuma-kaya-yf8co', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'soğuk kaldırımlarında yürürken caddelerin

buğulu gözlerle bakarken ardından

aşkına kurban olduğun sevgilinin

gidişi yıkar gönlünü senin

gözlerin sağa sola bakar boş boş

yüreğin yırtar kendini,haydi duma koş

gözlerinde vuslat gününün hayalleri

kulaklarında bir seda olur hoşmu hoş

ayrılık acısı çekerken yüreğin

durmaz akan yaşları gözlerinin

aradan yıllarda geçse artık

son nefeste de anılır adı sevgilinin', 'soğuk kaldırımlarında yürürken caddelerin buğulu gözlerle bakarken ardından aşkına kurban olduğun sevgilinin gidişi yıkar gönlünü senin gözl...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrilik-acisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşündükçe', 'dusundukce-cuma-kaya-ddifh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şu anda seni düşünüyorum

havada kasvetli benim gibi

kara bulutlar dolaşıyor gökyüzünde

neredeyse boşalacak gözlerim gibi

ıslanmış anılarım

özlemlerimi sel almış

ve kuytu bir köşesinde yanlızlığımın

solmuş mutlu bir resim kalmış', 'şu anda seni düşünüyorum havada kasvetli benim gibi kara bulutlar dolaşıyor gökyüzünde neredeyse boşalacak gözlerim gibi ıslanmış anılarım ö...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dusundukce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlarda Geceler', 'daglarda-geceler-cuma-kaya-8lui1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dağlarda geceler bir soğuk olurki 

sorma

sabaha çıkarmıyım bilmem

koynumda yarimin hayali olmasa

dağlarda geceler bir karanlık olurki 

sorma

sabahı görürmüyüm bilmem

gözümde sevdamın ışığı olmasa

bu dağlarda öyle yanlızım ki

sorma

gün gelirde kavuşurmuyum bilmem

içimdeki umut,özlem olmasa', 'dağlarda geceler bir soğuk olurki  sorma sabaha çıkarmıyım bilmem koynumda yarimin hayali olmasa dağlarda geceler bir karanlık olurki  sorma...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/daglarda-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kadar Uzak Olsamda Senden', 'ne-kadar-uzak-olsamda-senden-cuma-kaya-077zu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben ne kadar uzak olsamda senden

ne kadar acı çeksemde hasretten

dertten yana

özlem alıp götürsede beni uzaklara

yüreğim bir kuş gibi gökyüzünden

süzülüp uçar kollarına

her gece ama her gece koynumda

teninin sıcaklığını hissederim

ve sabah uyandığımda

arar seni o çok sevdiğin gözlerim', 'ben ne kadar uzak olsamda senden ne kadar acı çeksemde hasretten dertten yana özlem alıp götürsede beni uzaklara yüreğim bir kuş gibi gökyüz...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-kadar-uzak-olsamda-senden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-cuma-kaya-56mlt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'artık ay ışığında 

dans etmek istiyorum seninle

kumsalda kolkola yürümek

gözlerindeki huzur veren 

ışıltıyı görmek

sözlerindeki neşeyi

duymak istiyorum

denizin mırıldandığı

aşkımızın şarkısını

dinlemek istiyorum seninle

ve o ılık gecede 

seni öpmek,öpmek

delicesine öpmek

sevmek istiyorum

kumlarda uzanıp yanına 

saçlarını okşamak varya

kokunu hissetmek varya

burnumda tütüyor

gözlerimden gitmiyor

o gece seninle olmak varya

sevdiğim bebeğim

gözümden sakındığım

rüzgardan kıskandığım

varlığımın sebebi

canım sevdiğim', 'artık ay ışığında  dans etmek istiyorum seninle kumsalda kolkola yürümek gözlerindeki huzur veren  ışıltıyı görmek sözlerindeki neşeyi duyma...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/istiyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olmazki Bu Yürek', 'sensiz-olmazki-bu-yurek-cuma-kaya-1v26u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'olmazki

sensiz olmazki bu yürek

yaşanmazki bu hayat

belki tozlu yaolların birinde

belki benim gibi

yanlız kaldırımların

soğuk taşları üzerinde

oturmuş ağlayan birini

görürsen günün birinde

beni hatırla güzelim

yanlızlığın koyu karanlığında

güneşini arayan

seni arayan beni', 'olmazki sensiz olmazki bu yürek yaşanmazki bu hayat belki tozlu yaolların birinde belki benim gibi yanlız kaldırımların soğuk taşları üzerin...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sensiz-olmazki-bu-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat Ne Zaman', 'vuslat-ne-zaman-cuma-kaya-x22e3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yıldızlı gecelerin sabahlarında 

senle uyanmak

en büyük hayalim

o gelecek günün şafağında

güneşle bir doğan

ama güneşle batmayacak olan

mutlu günlerin hasretiyle

yanan yüreğim

ağlayan gözlerim

kavuşmanın sevinciyle

ne zaman gülecek

nereden bileyim', 'yıldızlı gecelerin sabahlarında  senle uyanmak en büyük hayalim o gelecek günün şafağında güneşle bir doğan ama güneşle batmayacak olan mutl...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vuslat-ne-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar', 'hatiralar-cuma-kaya-p56s7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'düşündüm bugün

dalıp sessizliğin

yanlızlığın hüznü içinde

seni düşündüm

kolkola gezdiğimiz kumsalı

sarılıp oturduğumuz

yanlız birbirimizin olduğumuz

o minik cafeyi

hani hep aynı şarkıyı çaldırdığımız

müzik kutusunu

bizim şarkımızı düşündüm

şimdi uzak çok uzak bir hayal gibi

gözleride,yaşanan o mutlu günler

şimdi bütün bunlar

çok uzak geliyor bana

aramızda sıra sıra dağlar var

aşılması zor engeller gibi

çevrem hep karanlık

şsfak bir türlü sökmüyor

ama yinede bir ışık var

o hüzün dolu karanlığın içinde parlayan

bir umutki yüreğimde alev alev yanan

seni istiyor 

hiç durmadan ağlayan 

bu gözler

bu ten,bu yürek,bu can

sadece seni istiyor sevdam', 'düşündüm bugün dalıp sessizliğin yanlızlığın hüznü içinde seni düşündüm kolkola gezdiğimiz kumsalı sarılıp oturduğumuz yanlız birbirimizin o...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hatiralar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahilde', 'sahilde-cuma-kaya-bk6ac', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'güneşin şavkı vurmuş saçlarına 

ışıl ışıl parlıyor

kum tanecikleri çarpıyor yüzüme

dalgalar beyaz bir meltemle oynaşıyor

tatlı bir nağme oluyor kulaklarımızda

sevgiler yağıyor sağnak sağnak

sevgiler uçuşuyor rüzgarda

aşıkların şarkısını söylüyor meltem

bir haziran ayı bu kumsalda

ne aşklar yaşandı bu kumsalda

ne aşıklar gezdi elele

sahile vuran her dalgada

yaşanmış o aşklar gelir dile', 'güneşin şavkı vurmuş saçlarına  ışıl ışıl parlıyor kum tanecikleri çarpıyor yüzüme dalgalar beyaz bir meltemle oynaşıyor tatlı bir nağme olu...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sahilde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak Sesleri', 'ayak-sesleri-bekir-sitki-erdogan-ssutf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her akşam işte böyle  gam gelir bana,

Benden kederli bir adam gelir bana!

Dostum değil gelen, benim garipliğim,

Dostum mu var ki bir selam gelir bana?

Zehr oldu yar elinden içtiğim kadeh

Zemzem de sunsalar, haram gelir bana!

Ağlar gönül o yemyeşil baharlara,

Meltemlerin hayali sam gelir bana!

Hüzzam olup giden o gizli yankılar,

Hala döner, makam makam gelir bana...

Toprak bu ızdırabı örtmez  yarın,

Taş yağsa kubbe kubbe tam gelir bana!..

Dinler elif adım adım bu sesleri,

Her akşam işte böyle gam gelir bana...', 'Her akşam işte böyle  gam gelir bana, Benden kederli bir adam gelir bana! Dostum değil gelen, benim garipliğim, Dostum mu var ki bir selam g...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Erdoğan']::text[], 8.5, '{"poet":"Bekir Sıtkı Erdoğan","poet_slug":"bekir-sitki-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayak-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesellim', 'tesellim-cuma-kaya-qqgxh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yakıyor beni özlemin,yakıyor hasretin

gözlerin özlemim,gülüşün hasretim

ellerin ah o ellerin,huzur veren o tenin

tek tesellisi yanlız gecelerimin

hani gezerdik ya sahilde kolkola

anlatırdık ya sevgimizi kumlara

anlatırdık aşkımızı gökyüzüne

şimdi dalıp gitmişim hayal alemine', 'yakıyor beni özlemin,yakıyor hasretin gözlerin özlemim,gülüşün hasretim ellerin ah o ellerin,huzur veren o tenin tek tesellisi yanlız gecele...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tesellim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-cuma-kaya-9espv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıldızlarla dolu gökyüzüne bakarken

biliyorsun seni düşündüğümü

yokluğunu gönlümde hissettiğimi

her yıldız kayışında

seni dilediğimi biliyorsun', 'yıldızlarla dolu gökyüzüne bakarken biliyorsun seni düşündüğümü yokluğunu gönlümde hissettiğimi her yıldız kayışında seni dilediğimi biliyor...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dilek-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madalyan Olsun', 'madalyan-olsun-cuma-kaya-9c4b2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ya dost

gidiyorsun işte

ayrılık vakti geldi çattı

artık tüm yaşananlar 

birer anı olacak

zihinlerde tatlı bir hatıra 

anımsanacak

gidiyorsun 

kanatlanmış uçuyorsun

mutlusun

mutlu olmak senin hakkın

bunca çileden sonra

mutluluk senin madalyan olsun', 'ya dost gidiyorsun işte ayrılık vakti geldi çattı artık tüm yaşananlar  birer anı olacak zihinlerde tatlı bir hatıra  anımsanacak gidiyorsun...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/madalyan-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdeniz Yürekleri', 'akdeniz-yurekleri-cuma-kaya-9yi1h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gitmek isterdim

masmavi denizin kenarında

güneşin yaktığı

akdeniz kumsallarına

dalıp gökrengi suların derinliğine

çıkmak isterdim kıbrıs açıklarına

güneş kadar sıcak

akdeniz yürekli sevecen insanları

görmek isterdim

bakınca

yüzlerinde esen 

mutluluk meltemlerini

dudaklarındaki tebessümlerini', 'gitmek isterdim masmavi denizin kenarında güneşin yaktığı akdeniz kumsallarına dalıp gökrengi suların derinliğine çıkmak isterdim kıbrıs açı...', ARRAY['Türk Edebiyatı','Şiir','Cuma Kaya']::text[], 8.5, '{"poet":"Cuma Kaya","poet_slug":"cuma-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/akdeniz-yurekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Resim', 'i-ki-resim-baris-ozkaya-jnypd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Resim 1

Daha hiç

okulun yolunu tutmamış

doktora gitmemiş

saksıda bile çiçek yetiştirmemiş

pırıl pırıl ayakkabılar giymemiş

suluboya takımı olmamış

Daha neler neleri olmamış

neler neler yapmamış

küçük ayakkabı boyacısı

küfrederek

ayakkabıların üstüne yapar

onursuz yaşamın resmini

Resim 2

Yıllar sonra

Sabahları öğretmen olur

-kapkara ellerinde bembeyaz tebeşir-

Öğlen doktor

-çatlamış ellerinde neşter-

ya da bahçıvan

-nasırlı ellerinde makas-

Akşam ressam

-boyalı ellerinde fırça-

yıllar öncesinin sokaklarında

ekmek parası diye

ayakkabıların ardında koşturan

küçük boyacıların

hayallerini resmeden', 'Resim 1 Daha hiç okulun yolunu tutmamış doktora gitmemiş saksıda bile çiçek yetiştirmemiş pırıl pırıl ayakkabılar giymemiş suluboya takımı o...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/iki-resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Duvar', 'mavi-duvar-emrah-yurtcu-ff33w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duvarları maviye boyadım

Maviyi çok seversin

Penceremde menekşeler dizili

Sularken şarkı söylersin

Gramafonda eski alaturka

Hoşuna gider bilirim

O yaz evinin içinde denize nazır

Sabaha kadar bekledim seni

Birden dalgalar dedi ki gelmeyeceksin

Birden çıktım viraneden

Koşa koşa indim kumsala

Acı acı sövdüm sonra 

Yüzümü kırbaçlayan rüzgara', 'Duvarları maviye boyadım Maviyi çok seversin Penceremde menekşeler dizili Sularken şarkı söylersin Gramafonda eski alaturka Hoşuna gider bil...', ARRAY['Türk Edebiyatı','Şiir','Emrah Yurtçu']::text[], 8.5, '{"poet":"Emrah Yurtçu","poet_slug":"emrah-yurtcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mavi-duvar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-savas-yildirim-moc3b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokluğun,yokluğun hat safhası

Yokluğun,yokluğun efendisi

Yokluğun,yokluğun ta kendisidir...', 'Yokluğun,yokluğun hat safhası Yokluğun,yokluğun efendisi Yokluğun,yokluğun ta kendisidir......', ARRAY['Türk Edebiyatı','Şiir','Savaş Yıldırım']::text[], 8.5, '{"poet":"Savaş Yıldırım","poet_slug":"savas-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yoklugun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Sayende', 'senin-sayende-i-lhan-gasi-80bb8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sabahta sensiz açtım gözlerimi

Çaresizce resmine bakıp 

Seninle yaşamak istediklerime daldım

Bir anda gerçeğe döndüm sonra

Sensizlik gerçeğine.

Sonra kirpiklerimi kapadım 

Gözlerimden yaşlar aktı

Her zamanki yolundan

Ben sensiz kaç kere kaç gece kaç sene 

Ağladım göz yaşlarım akmaya alışkın

Senin sayende', 'Bu sabahta sensiz açtım gözlerimi Çaresizce resmine bakıp  Seninle yaşamak istediklerime daldım Bir anda gerçeğe döndüm sonra Sensizlik gerç...', ARRAY['Türk Edebiyatı','Şiir','İlhan Gaşi']::text[], 8.5, '{"poet":"İlhan Gaşi","poet_slug":"i-lhan-gasi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/senin-sayende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-aybeniz-kuzeci-n1yht', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sevgi dolu albayrak

gel seninle daglara,taşlara göllere uçalım

o ay yıldızını görseler

gel seninle daglara,taşlara göllere uçalım

sen hep gökyüzündesin

herkesi iyi bilirsin

bir tek sen değil , tanrıda bilir

seni gören sevinçlenir

seni gören duygulanır

seni gören seninle gurur duyar

albayrağım 

şehitlerin örtüsü

toprakların süsü

ben seni Azerbaycan,Tebriz, 

Erbil, Kerkük kalesine

dikmek istiyorum

canım benim ay yıldızlı bayrağım', 'sevgi dolu albayrak gel seninle daglara,taşlara göllere uçalım o ay yıldızını görseler gel seninle daglara,taşlara göllere uçalım sen hep gö...', ARRAY['Türk Edebiyatı','Şiir','Aybeniz Küzeci']::text[], 8.5, '{"poet":"Aybeniz Küzeci","poet_slug":"aybeniz-kuzeci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bayragim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Olsun', 'umudun-olsun-yasemin-korkut-2904w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerindeki yaşlar, sevinçten olsun artık.

Yağmurların yağdığı yerde, çiçekler açsın.

Hasretliği unutsun, mavi puslu gözlerin.

Ayazların yerini, artık baharlar alsın.

Kavuş sevdiğine ve sarıl, sımsıkı sarıl.

Özlemlerin o eski, yırtık resimde kalsın.

Hiçbirşey incitmesin, gülümseyen yüzünü.

Güneşin, daima yolunu aydınlatsın...', 'Gözlerindeki yaşlar, sevinçten olsun artık. Yağmurların yağdığı yerde, çiçekler açsın. Hasretliği unutsun, mavi puslu gözlerin. Ayazların ye...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Korkut']::text[], 8.5, '{"poet":"Yasemin Korkut","poet_slug":"yasemin-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umudun-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşver', 'bosver-bulent-yuksel-cxg8q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruhun satacaksan bedenini birgün

Ve sen ruhunu satacaksan ellere

Kimi eller oksayacaksa bedenini

Kimi bedenler cezbediyorsa ruhunu

Kimi ruhlar, ruhunu arzularsa

Kimi bedenler sarılırsa bedenine

Kimi eller avucundaysa eger

Ruhun da huzurluysa

Bir de mutluysan

Boooşver gerisini', 'Ruhun satacaksan bedenini birgün Ve sen ruhunu satacaksan ellere Kimi eller oksayacaksa bedenini Kimi bedenler cezbediyorsa ruhunu Kimi ruhl...', ARRAY['Türk Edebiyatı','Şiir','Bülent Yüksel']::text[], 8.5, '{"poet":"Bülent Yüksel","poet_slug":"bulent-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bosver-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de...', 'sen-de-yasemin-korkut-rkqq8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin görmez olmuş yalvaran bakışları,

Kulağını tıkamışsın duymaz olmuşsun beni.

Tam lazımken ellerin kanayan yüreğime,

Koyup yaban ellere sen de bıraktın beni.', 'Gözlerin görmez olmuş yalvaran bakışları, Kulağını tıkamışsın duymaz olmuşsun beni. Tam lazımken ellerin kanayan yüreğime, Koyup yaban eller...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Korkut']::text[], 8.5, '{"poet":"Yasemin Korkut","poet_slug":"yasemin-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Olsun', 'gunesin-olsun-huseyin-cebicci-jdoa8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimden akan iki damla

yaş,

Pencerene vuran, 

yağmurun olsun.

Yüzüne hasretim bu boş

şehirde,

Beni bir kez görmek,

tek arzun olsun.

Bir zaman gelecek buluşacağız,

Biriken özlemle sarılacağız,

Gelecek günleri konuşacağız,

Yeter ki güzelim umudun olsun.

Puslu bir sabahta beni anarsan, 

Gözün yaşla değil,

aşkımla dolsun.

Benden tek hatıra o yırtık resim,

Ayazlı gecede güneşin olsun...', 'Gözlerimden akan iki damla yaş, Pencerene vuran,  yağmurun olsun. Yüzüne hasretim bu boş şehirde, Beni bir kez görmek, tek arzun olsun. Bir ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çebiçci']::text[], 8.5, '{"poet":"Hüseyin Çebiçci","poet_slug":"huseyin-cebicci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gunesin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-yasemin-korkut-gcx8a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül bir derya imiş, susamaktan yorulmuş.

Küçücük bir serçeyken, bir kartala vurulmuş.

Serçeyi yemiş yılan,kartalı vurmuş avcı.

Yürek acıyla çarpmış ve derinden bir sancı.

Bu son çırpınışıymış, yüreğin inan bana

Kimse duymamış başka, bana anlattığını.', 'Gönül bir derya imiş, susamaktan yorulmuş. Küçücük bir serçeyken, bir kartala vurulmuş. Serçeyi yemiş yılan,kartalı vurmuş avcı. Yürek acıyl...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Korkut']::text[], 8.5, '{"poet":"Yasemin Korkut","poet_slug":"yasemin-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/masal-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardaki Sevgiliye', 'uzaklardaki-sevgiliye-bilal-degirmendereli-osk14', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Irağına düştüğüm 

Hasretiyle rüzgarları yorduğum sevgili, 

Yastığımın duvarlarındaki pencerenden bakarken gözlerin 

Ben seni düşleyen rüyaların hayalindeyken 

Sahipsiz akşam esintilerinin fısıldadıkları yürek dökümleriyle 

Puslu bir gecenin mahurluğuna inat 

Bir sevda masalı teşkil oluveriyordu, 

Kahverengi bakışlarla zamana bırakıp sonra da unuttuklarımıza koşuyordum 

Yanına her gelişimde söyleyemediklerimle trenleri karartıyordum 

Uzaklardayken daha da yanımdasın 

Seni yaşıyorum bir küçük suretinle 

Anlıyorum 

Kavuşmanın zor olduğu diyarlarda 

Büyümenin daha kolay olduğunu 

Sevdayı yaşamanın 

Önce köklendirip sonra yeşertmenin 

Sensizken mümkün olduğunu 

Nadir yaşanan sadakatin mukaddesiyetini öğretiyorsun 

Habersiz geçen haftaların her anında 

Merhabalar hoşçakallarla birlikte geliyor 

Gözlerimin vuslat yaşadığı zamanlarda 

Yani ayrılırken de buluşurken de hoşçakal diyoruz 

Keşke biraz daha kalabilseydin demek hoşçakal 

Özlemeye devam edecem demek 

Vuslatı düşlemek ve yari beklemek 

Hoşçakal demek 

Aslında 

Seni seviyorum demek 

İç dökümlerin gelir bazen posta kutuma 

Okula başlayan çocuk edasıyla yazına kavuşurum 

Önce sevinç ve gurur 

Sonra sorgulayış, anlayamayış ve hasret 

Resmi geçit yapar yüreğimde 

Hadi hemen cevap ver diyen sesi itip bir kenara 

Süzmeye başlarım zihnimi 

Sırf sana en iyiyi verebilmek adına 

Irağına düştüğüm sevdiğim 

Tek dileğinin anlaşılmak olduğu dünyanda 

Yerimi kazıyorum aşkımızın bahçesine 

Birgün gelirde birileri bir gölge arar diye 

Sana geliyorum ey sevgili 

Döndürme kapından 

Can köşemdeki bir buket hasret namına 

Kavuştur beni zihninin aydınlığına', 'Irağına düştüğüm  Hasretiyle rüzgarları yorduğum sevgili,  Yastığımın duvarlarındaki pencerenden bakarken gözlerin  Ben seni düşleyen rüyala...', ARRAY['Türk Edebiyatı','Şiir','Bilal Değirmendereli']::text[], 8.5, '{"poet":"Bilal Değirmendereli","poet_slug":"bilal-degirmendereli","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/uzaklardaki-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-mehmet-ozyurt-2xdcs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karbeyaz saçlarımın sebebi sensizlik,

Tiryaki olmamın sebebi sensizlik,

Sen yanımda yoksan sevgilim 

İçimdeki hüznün sebebi sensizlik...

Gittiğin günden beri aklımdasın hala,

Nereye baksam nereye gitsem yanımdasın hala,

Sensiz kaldığımdan beri sevgilim

Akan gözyaşlarım yanağımda hala...

Hatırlarmısın bilmem bir gül vermiştin bana

Hala o gülü koklar dururum,

Seni unutmak mümkün değil sevgilim

O güzel resmini öper dururum...', 'Karbeyaz saçlarımın sebebi sensizlik, Tiryaki olmamın sebebi sensizlik, Sen yanımda yoksan sevgilim  İçimdeki hüznün sebebi sensizlik... Git...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özyurt']::text[], 8.5, '{"poet":"Mehmet Özyurt","poet_slug":"mehmet-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlik-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrin Suskun Yazgısı', 'sehrin-suskun-yazgisi-ars-moriendi-khgrt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şehre yanmak vaktidir şimdi,

Yaban sevişlerin getirdiği avuntular adına.

Kayıp kentler yanıyor her defasında,

Fersiz kelimeler caddeleri arşınlıyor,

Yüzlerinde belli belirsiz bir yığın anlam.

Bütün her şey birdenbire susuyor,

Yeryüzüne bir yağmur damlası düşüyor.

Eminönünden yaş-lı bir martı kanatlanıyor.

Güneşin kızıllığına sarılmak sevdasıyla,

Ufkun gerdanına bir çift göz takılıyor.

Geceye boyanıyor üç beş insan,

Avuçlarında bir kentin yanık kokuları.

Bütün her şey birdenbire susuyor,

Şehrin yüreğine düşüyor ızdırap şarkıları,

Bir annenin ağzından bebeği haykırıyor.

Yaşamayı emziriyor dilenci bir çocuk;

Çocuğun cebinde dilendiği hayatı saklı.

Hüzün kokan gözlerinin buğusunda,

Yağmur yüzlü bir annenin elleri okşanıyor.

Ve çocugun avuçlarında

Kırçiçekleri büyüyor rengarenk...

Kütün her şey birdenbire susuyor,

Kentin izbelerine, yaşamlar karışıyor hesapsız.

Yalnızlık aynalarında adamsı yüzler eskitiliyor,

Hayat sancılanıyor çocuk oyunlarında

Ve bir yakarış düşüyor şehrin dualarına...

                                                    (istanbul,2000)', 'Bir şehre yanmak vaktidir şimdi, Yaban sevişlerin getirdiği avuntular adına. Kayıp kentler yanıyor her defasında, Fersiz kelimeler caddeleri...', ARRAY['Türk Edebiyatı','Şiir','Ars Moriendi']::text[], 8.5, '{"poet":"Ars Moriendi","poet_slug":"ars-moriendi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sehrin-suskun-yazgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Şeyler mi?', 'yeni-bir-seyler-mi-mehmet-ozyurt-ievyy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün çekip gitsem buralardan,

Bilmem mutlu olurmuyum?

Gittiğim yeni yerlerde,

Eskiyi unuturmuyum?

Ama unutmalıyım artık,

Yeni birşeyler, yeni sevinçler, yeni hüzünler görmeliyim!

Artık benim için eski değil yeni olmalı,

Yeni sevgililer, yeni günler...

Ama hayır yinede özlerim,

Bana çektirdiği çileyi özlerim,

Geçmiş yıllarda yaşadığım

Tatlı ve hüzünlü günleri özlerim.

Yeni gittiğim yerlerde bulabilirmiyim bunları?

Bulsam da benzer mi eskilere?

Ama artık unutmalıyım onları

Ve onları kalbimin en güzel yerine gömmeliyim

Sevabıyla, günahıyla...', 'Bir gün çekip gitsem buralardan, Bilmem mutlu olurmuyum? Gittiğim yeni yerlerde, Eskiyi unuturmuyum? Ama unutmalıyım artık, Yeni birşeyler, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özyurt']::text[], 8.5, '{"poet":"Mehmet Özyurt","poet_slug":"mehmet-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeni-bir-seyler-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy Beni', 'duy-beni-sadan-cerit-futzv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duybeni...

Rüzgar bırakır avuçlarıma saçlarının kokusunu

Hep seni yazar kalemim mavi yeşil denizlere

Nilüfer açar rüyalarım, penceresiz dört duvarda

Haykırıyorum duyuyormusun? Duy beni.....

Ne rüzgar sarıldı çürümüş yaprak misali bedenime 

Nede denizler keşfetti kaybolmuş ben kıyılarımı

Bir tomurcuk filizlendi karanlıkta güneşi görmeden

Haykırıyorum duyuyormusun? Duy beni

Akıp gitmek gerekli nehir yatağında çağlayarak

Dal dal açmalı, umut umut filizlenmeli bu bahar

İşte ellerim, işte yüreğim, işte baştan aşağı ben

Haykırıyorum duyuyormusun? Duy beni

Tüm dallarımda, bahar tüm goncalarımda sen varsın

Yollarımda koşuşan cocuk, şeytan uçurtmam sensin

Gözlerimde nisan yağmuru, tenimde toprak kokusu

Haykırıyorum duyuyormusun? Duy beni

Duy Beni - Bir Garip Ask Hikayesi', 'Duybeni... Rüzgar bırakır avuçlarıma saçlarının kokusunu Hep seni yazar kalemim mavi yeşil denizlere Nilüfer açar rüyalarım, penceresiz dört...', ARRAY['Türk Edebiyatı','Şiir','Şadan Cerit']::text[], 8.5, '{"poet":"Şadan Cerit","poet_slug":"sadan-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duy-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-mehmet-ozyurt-tv25h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine yalnızlığın soğuk nefesini hissediyorum ensemde,

Günün soğukluğu yetmezmiş gibi.

Ve yine hüzünler çöküyor üstüme

Taşıyamıyacak oluyorum, incecik bacaklarım titriyor!

Nedendir bilinmez yine ğlamak istiyorum

Yağmura nispet edercesine ve

Ve bağırmak istiyorum,

Sanki sesim gök gürültüsü gibi!

Dışarda kopan fırtınaya inat

İçimde koparmak istiyorum birde!...', 'Yine yalnızlığın soğuk nefesini hissediyorum ensemde, Günün soğukluğu yetmezmiş gibi. Ve yine hüzünler çöküyor üstüme Taşıyamıyacak oluyorum...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özyurt']::text[], 8.5, '{"poet":"Mehmet Özyurt","poet_slug":"mehmet-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizlik-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Olmak İstiyorum', 'asik-olmak-i-stiyorum-mehmet-ozyurt-ovsdm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kuş olmak isterdim dünyayı özgürce dolaşmak için;

Ve asice yaşamak için hayatı bir kardelen;

Bir çocuk olmak isterdim dertsiz ve kedersiz,

Her anını doyasıya yaşayan ve mutlu olan;

Ve ölüme hazır olmak isterdim,

Herşeyini yerine getirmiş bir insan;

Öyle bir kitap olmak isterdim ki,

Okundukça okunan ama sonu bir türlü olmayan...

Ve ve aşık olmak isterdim!

Özgürce ve asice yaşanan,

Derdi ve kederi tatlı, mutluluğu eksik olmayan,

Öyle bir aşk isterdim ki

Herşeyiyle yaşanan ve sonu bir türlü olmayan...', 'Bir kuş olmak isterdim dünyayı özgürce dolaşmak için; Ve asice yaşamak için hayatı bir kardelen; Bir çocuk olmak isterdim dertsiz ve kedersi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özyurt']::text[], 8.5, '{"poet":"Mehmet Özyurt","poet_slug":"mehmet-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asik-olmak-istiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sendeyim', 'ben-sendeyim-mehmet-ozyurt-hdlxw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatın sonsuzluğunda ararken sonsuz sevgiyi

Çektiğin çilelere şükret,

Şükret ki, sevginin kıymetini bilesin;

''Seni'' ''sende'' yok et,

Yok etki, bir vücut bulsun sevgi.

''Benliğin'' ötesinde 

Asıl ''sen'' diyebilmektir sevgi.

Sen! Hala ''ben '' diyen mahluk!

Ne cürettir ki yoklukta bulmazsın vücut!

Bilmezmisin ki sevgilinin yeri ordadır.

''Sen'' de! Bırak ''benliği'' bir kenara

Hayatın sonsuzluğunda ulaş sevgi sonsuzluğuna...

''BENİ SEVİYORSAM SEN BAHANESİN!...''', 'Hayatın sonsuzluğunda ararken sonsuz sevgiyi Çektiğin çilelere şükret, Şükret ki, sevginin kıymetini bilesin; ''Seni'' ''sende'' yok et, Yok etk...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özyurt']::text[], 8.5, '{"poet":"Mehmet Özyurt","poet_slug":"mehmet-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-sendeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımsız', 'tanimsiz-siverekli-abbas-yilmaz-cexjl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanımdan geçerken çarpıldım

Yanımda otururken toplandım

Yanımdan giderken çıkarıldım

Yanımda görmeyince bölündüm

Kahretsin pisagor,öklit

En sonunda sıfır kaldım.', 'Yanımdan geçerken çarpıldım Yanımda otururken toplandım Yanımdan giderken çıkarıldım Yanımda görmeyince bölündüm Kahretsin pisagor,öklit En ...', ARRAY['Türk Edebiyatı','Şiir','Siverekli Abbas Yılmaz']::text[], 8.5, '{"poet":"Siverekli Abbas Yılmaz","poet_slug":"siverekli-abbas-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tanimsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum', 'unuttum-i-smail-teker-0hrme', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugünü 1Temmuz farzet

Bilirim, dikenim beni affet

Bunlar da yapmacık dersen

Aynada kendini seyr et', 'Bugünü 1Temmuz farzet Bilirim, dikenim beni affet Bunlar da yapmacık dersen Aynada kendini seyr et...', ARRAY['Türk Edebiyatı','Şiir','İsmail Teker']::text[], 8.5, '{"poet":"İsmail Teker","poet_slug":"i-smail-teker","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/unuttum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selenda', 'selenda-siverekli-abbas-yilmaz-4zmgg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geldiğimde sen de gitmemelisin Selenda 

Hayatın boyanmamış paslı ranzalarında

Hani boyalı umutlar gibi hep olmalısın Selenda

Veresiye bakışlarında bitmeliyim,sen olmalıyım Selenda

Sabrın yüceliği karşısında ışık titremeli

Önünde melul mumlar gibi erimeliyim Selenda

Gelirsem sen de gitmezsen eğer

Ogün bütün köprüler sularla sevişmeli

Veresiye bakışlarında ağlayıp,donmalıyım orada

Göz yaşımı içip intihar etmeli kuşlar

Bir nesil sonu olmalısın Selenda

Ama yine de bu şehirde olmalısın

Eksiksiz olmalısın,eksiksiz yaşamalıyım seni

Mahalledeki çocuklar seni görmeli

Eve yetişmeden sana yetişmeli Selenda

Yani biraz da baktığım her şeyde sen olmalısın Selenda

Kimi seversem sen ,kimden kırılırsam sen 

Gitme Selenda 

Gitme diyemez duvardaki o asılı ipim 

Gidersen eğer 

Kepenklerim çekilir

Bence gitme

Burada kalırsan aforizma yaşar baktığım her şeydeki sen 

Selenda buradadır demeli baktığım mavi yosun

Yorgunum,başımın ağrısı da ordinaryuslük

Bunu bana yapma

Gidersen azraili severim en çok

İpime de sahip çıkarım Selenda', 'Geldiğimde sen de gitmemelisin Selenda  Hayatın boyanmamış paslı ranzalarında Hani boyalı umutlar gibi hep olmalısın Selenda Veresiye bakışl...', ARRAY['Türk Edebiyatı','Şiir','Siverekli Abbas Yılmaz']::text[], 8.5, '{"poet":"Siverekli Abbas Yılmaz","poet_slug":"siverekli-abbas-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/selenda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar', 'dostlar-siverekli-abbas-yilmaz-owwwc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merak edilecek hiçbir şey kalmadı artık dostlar

Onsuz''luk on üzerinde on acı

Ya unutmanın da bi hiyerarşisi olmasaydı

Ya da böyle sadık kalmasaydım duvarımdaki o azrailime

Hayaline putperest gibi taptığım

Üçyüz atmış beş günün ve altı saatin ne değeri olurdu acaba

Herşeyi o''ymuş gibi gördüm dostlar

Hayalinde bile terledim titredim

Gereği yokken üstümü örttüm

Ve hiç hesapta yokken,ben böyle değildim dostlar

Işığımın neden daha sönmediğini

Ve neden pijamalarımı giyip yatmadığımı

Hiyerarşisinin son duraklarına gelmeden

Nereden bile bilirdimki

Ama artık bu piramide de tam uymuyorum dostlar

Ve anladım dostlar

Bu dünyada bu coğrafyada 

Ondan kalan miras yüzümde yoksul renkler taşısa da

Ne kadar keşfedilmemiş gezegeni varsa

Kaybetmeden ve kaybolmadan

O korkunç bilgiye varmadan

Yaşamın onsuz güçlüğünü de anladım dostlar', 'Merak edilecek hiçbir şey kalmadı artık dostlar Onsuz''luk on üzerinde on acı Ya unutmanın da bi hiyerarşisi olmasaydı Ya da böyle sadık kalm...', ARRAY['Türk Edebiyatı','Şiir','Siverekli Abbas Yılmaz']::text[], 8.5, '{"poet":"Siverekli Abbas Yılmaz","poet_slug":"siverekli-abbas-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dostlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senler ve Öteleri', 'senler-ve-oteleri-siverekli-abbas-yilmaz-7v6kv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzun uzun upuzun bir yerdeyim

Noktasızım virgülsüzüm

Koşuyorum sana,koşuyorum ünlemsiz koşuyorum

Arada bir dalıyorum

Kalem oluyorum

Kağıt oluyorum

Kağıtlar birbir sigara içiyor

Kalem yıldızları sayıyor

Kusuyor gökyüzü

Ay soyunuyor

Kırılıyorum kendimce

SEN geliyorsun

Utanıyorum

Başımı yarıyorum

Şehre küsüyorum

sen çıkıyorsun vaz geçiyorum

Uzun uzun  upuzun bir yerdeyim

Gemliyim,töreliyim,yasaklıyım

Urfada balık

Adıyamanda tütün

Hakkaride çoban

Şırnakta gerilla

Diyarbakırda dicle

Siverekte rençber

Ve senlerden vazgeçiyorum

Öteliyim

Vakit tamam

Oralara gidiyorum', 'Uzun uzun upuzun bir yerdeyim Noktasızım virgülsüzüm Koşuyorum sana,koşuyorum ünlemsiz koşuyorum Arada bir dalıyorum Kalem oluyorum Kağıt ol...', ARRAY['Türk Edebiyatı','Şiir','Siverekli Abbas Yılmaz']::text[], 8.5, '{"poet":"Siverekli Abbas Yılmaz","poet_slug":"siverekli-abbas-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/senler-ve-oteleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpüldünüz Efendim', 'opuldunuz-efendim-huseyin-yurttas-ii1cd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buzul günlerinin çözüldüğü mevsimdi

Şiirler gibi akıyordu ırmaklar

Çekildi iğreti yollar ayaklarımızın altından

Saat izmir sularıydı, öpüldünüz efendim

Herkes bir başınaydı, nedense biz ikimizdik

Sokaklar yalın ışıklarla yıkanıyordu

Özlemin kabarmış köpüğü yüreklerimizde

Saat izmir sularıydı, öpüldünüz efendim

Söcükler nereye kaçmışlardı öyle

Neden susmalarla doluydu o uzun yürüyüşümüz

Şehir mi ıssızdı, biz mi kimsesizdik

Saat izmir sularıydı, öpüldünüz efendim

Kanlı yaşantıları tanımıştık, sınanmıştı sevgimiz

Eksik değildi yine de içimizden bulutları

Kendi dallarımızı savurup kıran fırtınaların

Saat izmir sularıydı, öpüldünüz efendim

Kırgındı ömürlerimiz hiçbir şeyi değiştiremediğimizden

İçten içe yaşadığımız pişmanlıklarla

Kaç baharın gülü solmuştu yüreklerimizde

Saat izmir sularıydı, öpüldünüz efendim', 'Buzul günlerinin çözüldüğü mevsimdi Şiirler gibi akıyordu ırmaklar Çekildi iğreti yollar ayaklarımızın altından Saat izmir sularıydı, öpüldü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Yurttaş']::text[], 8.5, '{"poet":"Hüseyin Yurttaş","poet_slug":"huseyin-yurttas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/opuldunuz-efendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Geneller', 'i-lk-geneller-siverekli-abbas-yilmaz-b31da', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ateş,koynunda büyütür yalnızlığı

Işıksız şehirler gibidir görünen herşey

Ve öğrenirsin...

Dışarıdaki nofrost tipi insanlardan 

Sevginin çoğulcu demokrasisini

Öylesine çelişkili

Öylesine sadist

Ve anladımki 

Bir gerillanın haytındadır

Özgürlüğün ağır vebali

Okyanustur yürek

Kudurmuş dalga;

Coşmuş nehirdir ilk çocukluk

Afarozdur herşeye karşı ilk isyan 

İlk jöle

İlk briyantin

Ve evden ilk kaçış', 'Ateş,koynunda büyütür yalnızlığı Işıksız şehirler gibidir görünen herşey Ve öğrenirsin... Dışarıdaki nofrost tipi insanlardan  Sevginin çoğu...', ARRAY['Türk Edebiyatı','Şiir','Siverekli Abbas Yılmaz']::text[], 8.5, '{"poet":"Siverekli Abbas Yılmaz","poet_slug":"siverekli-abbas-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ilk-geneller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-boran-butuner-4mdmz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Büyümek isterdim anne

Cebimde sigara taşımak!,

Ve yakmak

Önce bir nefes çekip 

Ardından ağlamak

Ağbim yapardı bunu

Bende özenirdim

Onun dertli olduğunu nereden bilebilirdim

Şimdi çok iyi anlıyorun anne 

Üflemenin aslında püflemek olduğunu 

Geceye meydan okurcasına gözlerinin

Parıltısının nemden olduğunu

Ve dolduğunu anne dolduğunu

Ciğerime duman yerine sevdanın dolduğunu 

Gitmek istiyorum anne 

Geçmişe rest çekip gitmek

Vatan bildiğim yokluğunda yar gibi özlediğim toprağı 

Ardıma bakmadan terketmek 

Tıpkı onun gibi anne tıpkı onun gibi 

Atılgan ve korkusuz

Yüreğim hariç iz bırakmadan 

Ve düşünmeden kuşkusuz

Ellerim tetikte anne ama tavşan gibi ürkek

Ve ağzımda sigaram yine ağladım titreyerek

Geçmişten çekip geleceğe üflüyorum 

Aşkın sevdanın ve ihanetin bağrına

Ve yine üfleyip püflüyorum 

Ama artık gitmiyor ağırıma', 'Büyümek isterdim anne Cebimde sigara taşımak!, Ve yakmak Önce bir nefes çekip  Ardından ağlamak Ağbim yapardı bunu Bende özenirdim Onun dert...', ARRAY['Türk Edebiyatı','Şiir','Boran Bütüner']::text[], 8.5, '{"poet":"Boran Bütüner","poet_slug":"boran-butuner","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/anne-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasat', 'hasat-boran-butuner-1gpuq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Görmeden sevebilmek 

Ve sevildiğini bilerek ölmek

Umuda yapışıp gülebilmek 

Belkide terkedilmek

İşte sevda bu yarim 

Zor olsa da sevda bu

Kurbanlık koyuna bir avuç tuz 

Sonra da su

Ve kasap ardından ve masat

Nihayet bıçak sevdiğim 

İşte sevda bu kusursuz

Aciz bir taneyken atılırsın suya

Önce su ve güneş sonra ilk çırpınış

Şimdi körpe bir filiz ardından yaldızlı başak

Bakalım caziben nereye kadar koşacak

Hepsi yalan sevdiğim hepsi yalan 

Hepsi yalan bunların ilk aşktan arta kalan

Bir doğru var ki gönlümde

Vazgeçemem ben ondan

İşte orada Azrail(a.s)  elinde orak

Ve nihayet HASAT.', 'Görmeden sevebilmek  Ve sevildiğini bilerek ölmek Umuda yapışıp gülebilmek  Belkide terkedilmek İşte sevda bu yarim  Zor olsa da sevda bu Ku...', ARRAY['Türk Edebiyatı','Şiir','Boran Bütüner']::text[], 8.5, '{"poet":"Boran Bütüner","poet_slug":"boran-butuner","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hasat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Boklarıdır Üşüşür', 'yildiz-boklaridir-ususur-enver-gokce-54vkv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu

Pır pır

Maviş 

Maviş

Yamyaş

Gecede

Yıldız

Boklarıdır.(1)

Üşüşür

Keban 

Toprağının

Üstüne

Gel

Kardaş

Çözüver

Kuşağını

Aç

Kar

Gibi

Bembeyaz

Ekmeğini

Upuzun.

Biraz

Ceviz içi

Az

Kuru

Kaymak

Bir de

Çay

Demliyelim

Kerpeten

Gibi

Tavşan

Kanı

Olsun.

(1)Ateş Böceği', 'Şu Pır pır Maviş  Maviş Yamyaş Gecede Yıldız Boklarıdır.(1) Üşüşür Keban  Toprağının Üstüne Gel Kardaş Çözüver Kuşağını Aç Kar Gibi Bembeyaz...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"enver-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yildiz-boklaridir-ususur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Gül', 'beyaz-gul-umit-yasar-oguzcan-32ovx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni arıyorum kalabalık caddelerde,

tanımadığım insanlar geçiyor, sen yoksun..

perişan hayallerimin basladığı yerde,

sana sesleniyorum, duyuyormusun?

beyaz güller açtı bahçelerde , sevdiğin..

ya o karanfil , baygın kokulu çiçek.

gel  yalnızlık bahçeme beyazlar giyin,

anladımki bu ömür sensiz geçmeyecek.

odamı süsleyen ellerini uzat,

hazzından dile gelsin bastığın halı..

açılsın sevincinden perdeler kat kat..

ışık ve ateş senin için yanmalı..

sonra çevir düğmesini, radyonun

sevdiğin musiki dolsun odama,

dinle şarkısını büyük koronun,

beni düşün! beni düşün aglama..

içimden bir ses diyorki sabret..

sonu gelecek bu yalnızlığın,

bütün aynalar gülecek elbet,

açılacak kapılar ansızın..

yalnız sen varsın beyaz gülüm,

 evde bahçede ve sokakta,

bir eylül akşamı gördüğüm ,

o beyaz hayalsin uzakta..

yakınsın yalnızlık kadar,

uzaksın yakınmış gibi,

sensiz yasadıgım yıllar

bu kadar güzel değildi.

yeter.. gel artık yeter..

karanfiller açtı gel!!

kış bahçesinde , güller

beyaz güller açtı gel..', 'seni arıyorum kalabalık caddelerde, tanımadığım insanlar geçiyor, sen yoksun.. perişan hayallerimin basladığı yerde, sana sesleniyorum, duyu...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beyaz-gul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Yolu', 'sevginin-yolu-halil-karanfiloglu-lyp8b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevgi,bir güneş gibidir.ulaşılmaz

          ısıtır, bazılarını yakar

          tutulmaz, hissedilir

          yaşanmaz, yaşatılır

sevgi,  çiçek gibidir.güzeliktir

            narindir,bakım ister

            naziktır,su ister

            koparilmadan ,koklanmak ister

sevgi ,çoçuk gibidir.şendir

           saftır ,şefkat ister

             kullanılmaz ,beslenir

             anlayış ister.büyümek için zaman ister

sevgi,tabiat gibidir.fonksiyoneldir

          degişkendir. kuralları vardır

           içinde yaşar,yaşatır 

           döner.bazende baş döndürür

 sevgi bir pınar gibidir. akar 

           şeffaftır.saflıgı anlatır

           enerjidir.enerji verir

           kir tutmaz,temizdir', 'sevgi,bir güneş gibidir.ulaşılmaz           ısıtır, bazılarını yakar           tutulmaz, hissedilir           yaşanmaz, yaşatılır sevgi,  çi...', ARRAY['Türk Edebiyatı','Şiir','Halil Karanfiloğlu']::text[], 8.5, '{"poet":"Halil Karanfiloğlu","poet_slug":"halil-karanfiloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevginin-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimde Yatan Ölü', 'kalbimde-yatan-olu-elif-gultekin-u8ee0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbimde ağlıyor bir yıldızı evrenin

Bir yangın daha külleniyor alevler içinden

Kıpır kıpır oluyor gökyüzünün rüzgarı

Uzaklardan kemanın sesi geliyor

Pırıl pırıl ama ağlamaklı

Rüzgarlara soruyorum senin nefesini

Tadını mor sümbüllere

Ne zaman dalıp gitsem

Tenini hissediyorum tenimde

Gelsin diyorum rüzgarlara

Gelsin, bitsin artık bu çile

Sevse de sevmese de gelsin

Bir kere hortlasa mezarından

Bir kere, ah bir kere 

Dokunabilsem kalbimdeki ölüye...

Utanıyorum her gülücüğümde

Her bakışımda sana ağlıyorum

Her sevişimde sana ağlıyorum

Mezarlar diyorum ah mezarlar

Bir bilseniz kara toprakta kim yatar

Bir bilseniz onu

Toprak utanır saklamaktan

Taş utanır beklemekten

Bir görseniz saçlarını 

Dokunmak için bir teline

Vazgeçersiniz dünyadan

Kalbimde bir ölü yatıyor

Ölü aşka ağlıyor gözlerim

Sevdası tükenmemiş bir kelebeğin

Zamanının tükenmesi gibi,

Sana ağlıyor gözlerim ...

Dokunabilmek için gözlerine

Yaşlarımdan sel olsa diyorum

Kara topraktan geçip kalbine inen

Bir türkü olsa hıçkırıklarım

Sevgimi fısıldar kalbine

Kalbimde bir ölü yatıyor

Sevsem de sevmesem de...', 'Kalbimde ağlıyor bir yıldızı evrenin Bir yangın daha külleniyor alevler içinden Kıpır kıpır oluyor gökyüzünün rüzgarı Uzaklardan kemanın ses...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kalbimde-yatan-olu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teyzeden Şiirler 1', 'teyzeden-siirler-1-sair-teyze-wqfdv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerle bakışalım dillerle konuşalım 

Kalplerle birleşelim el ele tutuşalım 

Hiç ayrılmayalım sonsuzluğa koşalım 

Gözlerim ağlar yüreğim yanar, yanar 

Kanlar akar sevgilim, 

Artık beni ne sor ne de ara yüreğimde 

Büyüdü yare, seni suçlamıyorum 

Benim kaderim böyle 

Gözlerim ağlar, ağlar 

Seller akar sevgilim 

Yüreğim yanar, yanar 

Kanlar akar sevgilim', 'Gözlerle bakışalım dillerle konuşalım  Kalplerle birleşelim el ele tutuşalım  Hiç ayrılmayalım sonsuzluğa koşalım  Gözlerim ağlar yüreğim ya...', ARRAY['Türk Edebiyatı','Şiir','Şair Teyze']::text[], 8.5, '{"poet":"Şair Teyze","poet_slug":"sair-teyze","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/teyzeden-siirler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teyzeden Şiirler 2', 'teyzeden-siirler-2-sair-teyze-i35ac', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yavrum terk eti bu alemi ben de geleyim 

Senin olduğun yerde hemen öleyim 

Olmuyor canım olmuyor seniz olmuyor 

Sensiz canım bu hayat geçmiyor 

Seni canım hep arayacağım 

Seni canım kalbimde yaşatacağım 

Bir gün seninle buluşacağım 

Kalbimdeki ateşinle yanıp tutuşacağım 

Olmuyor canım olmuyor 

Sensiz canım bu hayat geçmiyor', 'Yavrum terk eti bu alemi ben de geleyim  Senin olduğun yerde hemen öleyim  Olmuyor canım olmuyor seniz olmuyor  Sensiz canım bu hayat geçmiy...', ARRAY['Türk Edebiyatı','Şiir','Şair Teyze']::text[], 8.5, '{"poet":"Şair Teyze","poet_slug":"sair-teyze","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/teyzeden-siirler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teyzeden Şiirler 3', 'teyzeden-siirler-3-sair-teyze-zb02z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gece sen geldin yine aklıma 

Derinden derine bir nefes aldım 

İçimdeki nefeste yine sen vardın 

Gecelerin derinliklerinde yine sendin 

Beni bırakmayan hep yanımda olan 

O yine sendin geceleri rüyalarımda 

Gündüzleri hayallerimde 

Yine sendin o sendin 

Sen gecenin karanlıkları da beni bırakmayıp 

O karanlık gecelerimi aydınlatan 

Güneşim ayım yıldızım olup 

İçime doğan güneşim 

Bazan da aşkınla yakıp kavuran

Yine sen  o sensin 

Bilir misin   seni ne çok özleyip yandığımı 

Bilseydin derin uykuları bölüp 

Dağları delip gelir miydin 

Biliyor hissediyorum gelirdin sen canım 

O benim yaşadığım sen canım 

Dağları deler yine gelirdin .....', 'Dün gece sen geldin yine aklıma  Derinden derine bir nefes aldım  İçimdeki nefeste yine sen vardın  Gecelerin derinliklerinde yine sendin  B...', ARRAY['Türk Edebiyatı','Şiir','Şair Teyze']::text[], 8.5, '{"poet":"Şair Teyze","poet_slug":"sair-teyze","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/teyzeden-siirler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın', 'yangin-metin-marenbel-xcqi9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kızıl akşamlarda yanan şehirlerle tutuşurdu sandallar

dinmezdi o yangın,

ta ki gece tuttuğu matemin siyahlarına 

bürüründüğü zamana kadar.', 'kızıl akşamlarda yanan şehirlerle tutuşurdu sandallar dinmezdi o yangın, ta ki gece tuttuğu matemin siyahlarına  bürüründüğü zamana kadar....', ARRAY['Türk Edebiyatı','Şiir','Metin Marenbel']::text[], 8.5, '{"poet":"Metin Marenbel","poet_slug":"metin-marenbel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yangin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reyhan 1', 'reyhan-1-mehmet-semih-isik-8d49l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine gece..

Sensiz..

Sessiz bir gece..

Gene yoksun yanımda..

Ağlıyorum..

Niye bomboş herşey..

Niye zevksiz hayat..

Niye gülemiyorum..

Niye boğazımda hep bir düğüm var..

Niye anlamsız herşey..

Niye niye niye..

Yoksa Sen yoksun diye mi..

Yoksa aşığım diye mi..

Yoksa aşkım yanımda değil diye mi..

Evet evet buldum..

Aşkım yanımda değil diye..

Seni sevmek güzel şey..

Seni sevmek huzur veriyor..

Seni sevmek hayat veriyor..

Seni sevmek herşeye farklı bir anlam veriyor..

Seni sevmek zevk veriyor..

Seni sevmek mutluluk veriyor..

Seni sevmek sevgi veriyor..

Ama Ama

Ama

Seni sevmek acıda veriyor..

Seni sevmek dertte veriyor..

Seni sevmek gözyaşı döktürüyor..

Seni sevmek endişe veriyor..

Seni sevmek kıskançlık veriyor..

Seni sevmek bir noktaya saatlerce baktırıveriyor..

Seni sevmek deliler gibi saatlerce boş boş yürümek veriyor..

Seni sevmek saatlerce yatakta tavanı seyrettiriyor..

Seni sevmek uykusuz geceler veriyor..

Seni sevmek .. ah Seni Sevmek..

Şunu merak ediyorum..

Seni sevmek SENi veriyor mu..

Seni sevmek senin sevgini veriyor mu..

Seni sevmek senin mutlu olmanı veriyor mu..

Seni sevmek senin ellerini veriyor mu..

Seni sevmek senin gözlerini veriyor mu..

Seni sevmek senin bakışlarını veriyor mu..

Seni sevmek unutulmamayı veriyor mu..

Seni sevmek senle olmayı veriyor mu..

Seni sevmek senin atmosferine girmeyi veriyor mu ..

Seni sevmek senin KALBİNİ veriyor mu..

Acaba Seni sevmek seninde beni sevmeni veriyor mu..

Muhabbet kuşlarını bilirmisin...

Kafeste öyle tek başına nasılda buruk dururlar..

Dışardan gelen kuş cıvıltıları bile onları nasıl mutlu eder..

Azıcık bir yem onları nasılda doyurur..

Bazen kafeslerinden çıkıp camdan dışarı bakarlar..bilirsin..

Dışardaki diğer özgür kuşlara bakarlar..

Diğer mutlu kuşlara imrenirler..

Ve o sıra hayaller alemine dalarlar..

Kendilerini diğer kuşların yanında görürler..

Hayallerindeki kuşun yanındadırlar o sıra..

Onunla beraber uçuyorlardır o sıra..

Onunla beraber ötüşüyorlardır o sıra..

Daldan dala özgürce uçuşuyorlardır o sıra..

Peki biz seninle ne zaman daldan dala uçacağız..

Ne zaman beraber ötüşeceğiz..

Peki ben hayallerimde dahi olsa ne zaman senin yanında olacağım..

Ne zaman bana şakıyacaksın..

Ne zaman kafesimin yanına geleceksin..

Ne zaman bizim pencereye konacaksın..

Ne zaman.. ne zaman..', 'Yine gece.. Sensiz.. Sessiz bir gece.. Gene yoksun yanımda.. Ağlıyorum.. Niye bomboş herşey.. Niye zevksiz hayat.. Niye gülemiyorum.. Niye b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Semih Işık']::text[], 8.5, '{"poet":"Mehmet Semih Işık","poet_slug":"mehmet-semih-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/reyhan-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Krallar Önde Gider', 'krallar-onde-gider-melon-sapka-ixn5f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'açmıyorsa derininde bir ince kardelen

kanatıyorsa yeni aşklar da seni derinden

usul usul anlatıyorsa bir martı kaptanının

seferinden

bir vurgun bekliyorsan dirilmek için kendinden

aldırma

çek soluğundan bir cigara gülüm

krallar önde gider', 'açmıyorsa derininde bir ince kardelen kanatıyorsa yeni aşklar da seni derinden usul usul anlatıyorsa bir martı kaptanının seferinden bir vur...', ARRAY['Türk Edebiyatı','Şiir','Melon Şapka']::text[], 8.5, '{"poet":"Melon Şapka","poet_slug":"melon-sapka","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/krallar-onde-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Dair', 'gozlerine-dair-aydin-cemal-wvm3l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hiç kimsye benzettirme gözlerini denize

bırak deniz övünsün benzediği için gözlerine.....!', 'hiç kimsye benzettirme gözlerini denize bırak deniz övünsün benzediği için gözlerine.....!...', ARRAY['Türk Edebiyatı','Şiir','Aydın Cemal']::text[], 8.5, '{"poet":"Aydın Cemal","poet_slug":"aydin-cemal","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/gozlerine-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körebe', 'korebe-melon-sapka-m7o8p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'barışmak sevdalara

ayrıkotu tadında

o kadar deli

o kadar ırmak boyu...

delice sevmek

velhasıl

ölüm vurmadan seni gel ...

gel ki birbirimizden habersiz yaşamayalım

gel ki kavuşsun çok uzaktan öykü ellerimiz

gel ki tüm sevdaları kardeş kardeş gözlerimizde seyredelim...

bizler ayrı dünyalarımızda kimsesiz

bizler aynı mekanlarda bertaraf yaşamlarımızla

bizler dağılmış tespih taneleri

bağlanan gözlerimizle

dünyadan bi''haber çocuk düşlerimizle

hep bir yerlere çarptık

hep bir yerlerde ağladık gizli gizli...

yüreğimizdeki çocuklar

sanki körebe oynuyordu

bizlerden habersiz

yüreğin tuhaf gelgitiyle...', 'barışmak sevdalara ayrıkotu tadında o kadar deli o kadar ırmak boyu... delice sevmek velhasıl ölüm vurmadan seni gel ... gel ki birbirimizde...', ARRAY['Türk Edebiyatı','Şiir','Melon Şapka']::text[], 8.5, '{"poet":"Melon Şapka","poet_slug":"melon-sapka","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/korebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurda Sis Düdükleri'' Bölümünden', 'yagmurda-sis-dudukleri-bolumunden-attila-i-lhan-osdus', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmurda Sis Düdükleri

imdat çığlıkları mıdır

              bir felaketi mi duyururlar

                       anlaşılmaz söyledikleri

salkım saçak çökerler karanlığıma

              yalnızlığımı dağıtırlar

                       yağmurda sis düdükleri

camlarda çehreler hayal meyal

              aramızdan müthiş ayrılmışlardır

                       anlaşılmaz niye öldükleri

son nefeslerini tasarladıkça

              insan ısrarla ölümünü yaşıyor

                       yağmurda sis düdükleri

yürekte keder yoğunlaştıkça

              bulutlar buz tozuna yozlaşıyor

                       anlaşılmaz neleri götürdükleri

sabahlar olur bir türlü uyuyamam

              içimde sanki şilepler çarpışıyor

                       yağmurda sis düdükleri', 'Yağmurda Sis Düdükleri imdat çığlıkları mıdır               bir felaketi mi duyururlar                        anlaşılmaz söyledikleri salkım...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yagmurda-sis-dudukleri-bolumunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüm', 'dusum-ozturk-yetis-b9ovp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kim demiş aşk yalandır,

Aşk sana dokunduğum andır.

Yokluğunda düşlerimde kalan,

Gözlerime dalan gülüşün,

O sımsıcak öpüşün,

Düşüm;

Hep sana dönüşüm,

Andır,

Anbe an sende dalandır.', 'Kim demiş aşk yalandır, Aşk sana dokunduğum andır. Yokluğunda düşlerimde kalan, Gözlerime dalan gülüşün, O sımsıcak öpüşün, Düşüm; Hep sana ...', ARRAY['Türk Edebiyatı','Şiir','Öztürk Yetiş']::text[], 8.5, '{"poet":"Öztürk Yetiş","poet_slug":"ozturk-yetis","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Sözler Ki', 'o-sozler-ki-attila-i-lhan-lk9oz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O Sözler Ki

o sözler ki acıdır

       mapusane avlularında

             demirli kırbaçlar gibi şaklar

o sözler ki sırasında

      çiçek açmış bir nar ağacıdır

             dağ ufkuna vuran deniz aydınlığı

                   sırasında gizemli bıçaklar

o sözler ki

      imgelem sonsuzluğunun

             ateşten gülüdürler

kelebek çarpıntılarıyla doğarlar ölürler

o sözler ki kalbimizin üstünde 

      dolu bir tabanca gibi

             ölüp ölesiye taşırız

o sözler ki bir kere çıkmıştır ağzımızdan

      uğrunda asılırız', 'O Sözler Ki o sözler ki acıdır        mapusane avlularında              demirli kırbaçlar gibi şaklar o sözler ki sırasında       çiçek açmı...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-sozler-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süreç', 'surec-nurullah-can-4ovft', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocuktum

Beş yaşındaydım

Tarlada kuş kovala dediler

On yaşındaydım

Oyun çağımda

Koyunların peşine verdiler

Büyüdüm biraz daha

On beş yaşında

Yeni terlemişti bıyıklarım

Sabandaydım sabahtan akşama

Kan davası dediler

Elime tüfek

Belime kurşun verdiler

Irmaklar benden yana değildi

Geçiyordu yanımdan iklimler

Zamanı artık sevmiyordum

Gözlerim düşmanda azıcık ürkek

Yaşamak istiyordum

Ölümü verdiler', 'Çocuktum Beş yaşındaydım Tarlada kuş kovala dediler On yaşındaydım Oyun çağımda Koyunların peşine verdiler Büyüdüm biraz daha On beş yaşında...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Can']::text[], 8.5, '{"poet":"Nurullah Can","poet_slug":"nurullah-can","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/surec-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sile''de Sensiz', 'sile-de-sensiz-mutlu-batur-uc3m1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(Biricigime, Sebnem''e)

Ceviz agacinin altinda,

Puslu bir oglen sonrasi,

Gunun ilk isiklarinda yagmis yagmurun

Toprak kokusuyla dusundum seni

Kulaklarimda, esen ruzgarin oynadigi yapraklarin sesi,

Yuzumde topraktan yukselen nemin serinligi...

Gun boyunca yesil,mavi ve guller

Kimi yani gonca

Kimi acilmis gokyuzune

Sadece dusundum seni..

Senı..

Sevgımı..

Ellerını..

Sile/Mayis 2001', '(Biricigime, Sebnem''e) Ceviz agacinin altinda, Puslu bir oglen sonrasi, Gunun ilk isiklarinda yagmis yagmurun Toprak kokusuyla dusundum seni...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Batur']::text[], 8.5, '{"poet":"Mutlu Batur","poet_slug":"mutlu-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sile-de-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Çizgisi', 'yol-cizgisi-memduh-atalay-g9ne5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güller diyarında bir akşam vakti

Siyah gözlerimden kurşunlar aktı

Bir hançer düşer gecenin ortasına

Sevda kitabını aşıklar yaktı

Sükûtum Kerbela sancılarında

Ölü yüreklere Hüseyin ekti

Ölümden öteye götürdüm aşkı

Karşıma yine yezitler çıktı

Nice değirmenlerde elendim durdum

Ben ağyâr kaldım, değirmen bıktı', 'Güller diyarında bir akşam vakti Siyah gözlerimden kurşunlar aktı Bir hançer düşer gecenin ortasına Sevda kitabını aşıklar yaktı Sükûtum Ker...', ARRAY['Türk Edebiyatı','Şiir','Memduh Atalay']::text[], 8.5, '{"poet":"Memduh Atalay","poet_slug":"memduh-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yol-cizgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-memduh-atalay-14i1q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönülden hayata şavkıyan ışık

Gözüme nur veren nazarın nerde

Aşıklar yüreği meydana saldı

Gül satan, gül tartan pazarın nerde

Yüreğim hizaya gelmez nicedir

Ruha saf tutturan azarın nerde

Yok mu acımızı destan yapacak şair

Sonsuza imza atan yazarın nerde', 'Gönülden hayata şavkıyan ışık Gözüme nur veren nazarın nerde Aşıklar yüreği meydana saldı Gül satan, gül tartan pazarın nerde Yüreğim hizaya...', ARRAY['Türk Edebiyatı','Şiir','Memduh Atalay']::text[], 8.5, '{"poet":"Memduh Atalay","poet_slug":"memduh-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/soru-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-tevfik-mengulluoglu-n93gs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dolaşıyorum yine sahiller boyu

ellerim cebimde

dudaklarımda ıslık

o en sevdiğimiz şarkı

çılgın ırmak misali

anılar deli dolu

bir sel olur boşalır gözlerimden

Martılar bir çığlık atar

uğurlarken vapuru

ve zaman intihar eder

isyan edercesine

Rüzgar melodisini söylüyor

mangal başı kuran balıkçılara

bir eşkiyanın hikayesi

dolanır rakı sofrasında

Gece feneri

yıldızlar kulak kabartır

bende kendimi dinlerim

rüzgarı sırtıma alarak.', 'Dolaşıyorum yine sahiller boyu ellerim cebimde dudaklarımda ıslık o en sevdiğimiz şarkı çılgın ırmak misali anılar deli dolu bir sel olur bo...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anilar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair ve Öteki', 'sair-ve-oteki-memduh-atalay-rhm01', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürek mabet değil, soğuk zindan duvarı

Hissizlikle devirdik bin asırlık çınarı

Sarışın iklimlerden devşirilen korkular

Kuruttu yıllar yılı zemzem akan pınarı

Hasret canda kördüğüm, yüreğim lime lime

Bağlamaz beni ülküsüz aşkın korkuları

İdrakin donuşuna tanık cellat idim

İndi beynime birden şuurun tırpanları

Yürürüm yedinci göğe, ikindi kıyamında

Unutmam hünkârı muhacir yapanları

Zulmün meydanına şair yürek koymalı

Zalime meyleder yumuş oğlanları', 'Yürek mabet değil, soğuk zindan duvarı Hissizlikle devirdik bin asırlık çınarı Sarışın iklimlerden devşirilen korkular Kuruttu yıllar yılı z...', ARRAY['Türk Edebiyatı','Şiir','Memduh Atalay']::text[], 8.5, '{"poet":"Memduh Atalay","poet_slug":"memduh-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sair-ve-oteki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bu Şehir', 'sensiz-bu-sehir-tevfik-mengulluoglu-t24yp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinde durmak istiyorum bu akşam

bana baktığın; ama o gitme diyen bakışlarında

Durmak..

Bir tren''in istasyonundan geçerken bıraktığı

o son çığlık gibi...

yokluğunu bir şiir gibi

yazabilmek

seni zamandan seçerek

sözünde durup seni seviyorum diye bilmek

ve seni yazmak tekrar

Bu şehrin karanlık perdelerine

bir eli cebinde

simit satan çocukları izliyorum şimdi

Buğulu camların arkasından

ve bu şehrin üşüdüğünü farkediyorum

aklıma sen geliyorsun birden

yürüyorum

bavulumda anılarım

olmayan seni düşünüyorum

bir başka istasyonda

bir trenin vagonunda

hayalinle terk edeceğim bu şehri.', 'Gözlerinde durmak istiyorum bu akşam bana baktığın; ama o gitme diyen bakışlarında Durmak.. Bir tren''in istasyonundan geçerken bıraktığı o s...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensiz-bu-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtirazname-i Nazım', 'i-tirazname-i-nazim-nazim-hikmet-ran-qoivy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık bir daha

bir kahkaha

gibi gülmeyecek gözünüzde gözümüz.

Teveccühünüz

mavi bir mücevherdi başımızda.

Başımızdan düşürdük onu
..........
..........', 'Artık bir daha bir kahkaha gibi gülmeyecek gözünüzde gözümüz. Teveccühünüz mavi bir mücevherdi başımızda. Başımızdan düşürdük onu .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/itirazname-i-nazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-tevfik-mengulluoglu-hy736', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı yağıyorsa yağmur

esiyorsa poyraz

ve titriyorsa soğuktan o küçük bedenin

gecenin bir vaktinde

aç pencereni yavrum

savursun rüzgar baba sıcaklığını

menekşeyle çiğ toprak kokusu karışır o zaman

sürüklerdi rüzgar o kara bulutları üstünden

güneş minik bir yara açardı gökyüzünde

yeşerir dünyanda bütün güzellikler

yankılanır özlem dolu ezgiler

işte o zaman ardına kadar aç kapılarını yavrum

uzaklardan savursun rüzgar özlemlerini.', 'Gecenin bir yarısı yağıyorsa yağmur esiyorsa poyraz ve titriyorsa soğuktan o küçük bedenin gecenin bir vaktinde aç pencereni yavrum savursun...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlem-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçeceğim Senden', 'vazgececegim-senden-engin-yavuz-6wqqs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tam unuttum seni derken 

Hatırlatma bana kendini 

Korkutma beni gecelerime girerken 

Artık vazgeçeceğim senden 

Sileceğim seni kalbimden 

Beni bıraktığın yerde beklerken 

Vazgeçeceğim senden 

Düşlerimden, hayallerimden 

Yüzün gözlerimden silinirken

Anılar bile kalmayacak aklımda

Sen ufukta batıp giderken 

Vazgeçeceğim senden...', 'Tam unuttum seni derken  Hatırlatma bana kendini  Korkutma beni gecelerime girerken  Artık vazgeçeceğim senden  Sileceğim seni kalbimden  Be...', ARRAY['Türk Edebiyatı','Şiir','Engin Yavuz']::text[], 8.5, '{"poet":"Engin Yavuz","poet_slug":"engin-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vazgececegim-senden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reyhan 2', 'reyhan-2-mehmet-semih-isik-ezbtd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizlik..

Yığınla insan arasında yalnızlığa benziyor..

Sensizlik..

Bir okyanusta susuzluğa benziyor..

Sensizlik..

Tek kanatlı bir kuşa benziyor..

Hani uçmaya çalışırda..

Hani uçamazya...

İşte bende çırpınıyorum..

Çırpınıyorum..

Ama olmuyor..

Sensiz uçulmuyor..

Gerçi sen varken kanada ne gerek..

Sen insanı en güzel duygulara uçuruyorsun..

Sen insanı yeri geldimi hüzünlendiriyor..

Yeri geldimi sevindiriyor..

Yeri geldimi acı veriyorsun..

İşte sen..

..

Neden SEN ?

Ne var sende..

Yoksa sen Reyhan''mısın..

Ancak Reyhan bu kadar sevilmeye layıktır..

Ancak Reynan uğrunda ağlamaya layıktır..

Eğer sen Reyhan''san neden yanımda değilsin..

Yok Reyhan değilsen neden bu kadar Seviyorum Seni..

..

Bende gülmek istemezmiyim..

Bende güldürmek istemezmiyim..

Ama sen yokken nasıl gülerim..

NasıL güldürürüm..

Neyse nerde kalmıştık..

Sensizlik..

Kızgın kumlar arasında üşümeye benziyor..

Sensizlik..

Bir uçurum kenarında ufka bakmaya benziyor..

Hani ufka baktıkça dahada derinleri görürsün ya..

İşte bende sana baktıkça derinleşiyorum..

Senin derinliklerine daldıkça dalıyorum..

Ve

Ürküyorum..

Sen çok derinsin..

Sen çok şeysin..

Bilmiyorum işte..

Seni seviyorum..

Sadece bunu biliyorum işte..

Sana ne diyeceğim biliyormusun..

Yıldızlara bakarken seni gördüm..

Sende bana bakıyordun..

Bakarken gözünü kırpıyordun..

İşte ben gördüm bunu..

Bana tam bakerken birden kayıverdin..

Sanki kalbimin derinliklerine kaydın..

Senin kayışına diğer yıldızlar çok üzüldüler..

Ama sen bana geliyordun..

Hemde gülerek geliyordun..

Arkandaki yıldızlara bakmadan geliyordun..

Ah o yıldızlar..

Yıllarca seni bana yollamayan yıldızlar..

Nasılda üzülüyorlardı senin bana gelişine..

Bende onlara nispet olsun diye gülüyordum..

Sen bana yaklaştıkça daha da sesli gülüyordum..

Onlarsa bana imrenerek bakıyorlardı..

Arkada kalan yıldızlara;

''Bakın Reyhan şu gülen çocuğa doğru kayıyor.''

Diyorlardı..

Diğer yıldızlarda bana bakıyordu..

Sen bana yaklaştıkça tüm sema sana ve bana kitlenmişti..

Bizim birleşme anımızı tüm kainat izliyordu..

Sen bana yaklaştıkça gözündeki yaşlar yağmur olmaya başlamıştı..

Ne güzeldi senin yağmurların..

Ne güzeldi seni gülüşlerin..

Ne güzeldi senin sevişlerin..

Sende gördüm ben sevgiyi..

Sende gördüm sevilmeyi..

Yahu sen bir okulmusun yoksa..

Hece hece sevgiyi veriyorsun..

Kelime kelime sevmeyi öğretiyorsun..

Cümle cümle aşkı tattırıyorsun..

Ekmeği suyu öğretiyorsun..

Ekmeğin suyun gerçek tadını öğretiyorsun..

Yoksa yoksa sen bir su kaynağımısın..

Kaynağından çoşa çoşa akan bir sumusun..

Kaynadıkça çoşan..

Çoştukça akan..

Aktıkça hayat veren..

Toprağa can veren..

Çiçeklere böceklere renk veren..

Reyhancıkları topraktan fışkırtan..

Gerçekten REYHAN sen nesin..

Ben neden senin ne olduğunu anlamıyorum..

Yoksa sen yokmusun..

Yoksa sen bir hayalmisin..

Hayalsen gerçek olurmusun..

Sende beni severmisin..

Sende beni istermisin..

Sana bir şey diyeceğim..

Ben seni seviyorum biliyormusun..

Sende beni sevecekmisin..

Yoksa sendemi seviyorsun..

Evet evet seviyorsun..

Sevmesem ağlarmısın..

Sevmesen gözlerimin derinine bakarmısın..

Evet evet sende beni seviyorsun..

Uzaktanda olsa seviyorsun..', 'Sensizlik.. Yığınla insan arasında yalnızlığa benziyor.. Sensizlik.. Bir okyanusta susuzluğa benziyor.. Sensizlik.. Tek kanatlı bir kuşa ben...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Semih Işık']::text[], 8.5, '{"poet":"Mehmet Semih Işık","poet_slug":"mehmet-semih-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":105,"source_url":"https://www.antoloji.com/reyhan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Babacım', 'ah-babacim-mehmet-semih-isik-rgcjm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah Babacım

Herkesler güler,eğlenir..

Benimse içimden hep ağlamak gelir..

Oysa baba sen varken böylemiydim..

Bende güler eğlenirdim..

Bir gün orda bir gün burda gezerdim..

Senin ellerini tutar severdim..

Başıma götürür saçlarımda gezdirirdim..

..

Ellerin hala ellerimde sanki..

Sıcaklığı hala benliğimde..

Hiç bir şey senin yerini tutmuyor baba..

Herşeyde seni görüyorum..

Herşeyde seni hissediyorum..

..

Bende gülüyorum baba..

Gülüşmelerimizi düşünüp gülüyorum..

Bende ağlıyorum baba..

Ağlaşmalarımızı düşünüp ağlıyorum..

..

Hatırlıyormusun baba..

Biz seninle gezerdik..

Kırlara giderdik..

Ben çok yaramazlık yapardım..

Sen bana uslu ol kızım derdin..

Ben hep koştururdum..

Sen bana uslu ol kızım derdin..

Ama ben gene koşardım..

Sen bana hep uslu ol derdin..

Ben seni dinlemezdim ama hiç..

Keşke dinleseydim baba seni..

Keşke hiç sözünden çıkmasaydım..

Sen hep uslu ol derdin..

Ama hiç kızmazdın bana..

Hep severdin beni baba..

..

Baba sen varken bana kimse kızmazdı..

Annem bana hiç vurmazdı..

Sen hep severdin beni..

Abim benim istediklerimi alırdı..

..

Baba sen orda üşüyormusun..

Ben burda çok üşüyorum..

Eskiden üşüyünce senin yanına gelirdim..

Şimdi üşüyünce ağlıyorum..

..

Babacım sen ne zaman geri döneceksin..

Halam baban bir daha dönmeyecek dedi..

Bende küstüm halama..

Bir daha gitmeyeceğim onlara..

..

Babacım ben seni çok özledim..

Dizinde oturmayı çok özledim..

Bana canım kızım demeni..

Sarılıp öpmeni..

Kucağına alıp gezdirmeni..

Ya baba..

Ben herşeyini özledim..

..

Babacım ben okulada başladım..

Çok güzel bir sınıfım var..

Öğretmenin ve arkadaşlarım çok iyiler..

Biliyormusun babacım..

Bütün arkadaşlarımın babası var..

En çokda Elif''in babası iyi..

Aynı senin gibi babacım..

Beni bir keresinde kucağına alıp öpmüştü..

Aynı senin gibi..

..

Ya baba..

Sana bir şey soracağım..

Ölmek ne demek..?

Bana baban öldü diyorlar..

Bende gülüyorum..

Ne zaman geleceksin ölmekten..

Keşke gelsen babacım..

Sonra istersen gene gidersin..

Belki benide götürürsün..

Ben çok sıkılıyorum burda..

Kimse gezdirmiyor beni..

Kimse sevmiyor beni..

Kimse öpmüyor beni..

Kimsecikler istemiyor beni babacım..

Ah babacım..Ahh

Bu şiir Yakup K. ye ithaf olunur..', 'Ah Babacım Herkesler güler,eğlenir.. Benimse içimden hep ağlamak gelir.. Oysa baba sen varken böylemiydim.. Bende güler eğlenirdim.. Bir gün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Semih Işık']::text[], 8.5, '{"poet":"Mehmet Semih Işık","poet_slug":"mehmet-semih-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/ah-babacim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Sonra', 'neden-sonra-cahit-sitki-taranci-zpuaf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden sonra farkına varıyorsun

Etrafındaki korkunç ıssızlığın.

Yâr olsun,dost olsun,ne arıyorsun,

adresi belli mi vefasızlığın?

Aşk,dostluk!.. Hepsi dökülür yapraklar!

Çıplak bir ağaç durgun suda aksin.

Yalnızlık dediğin hayatta başlar;

Kabir boyunca devam etmek için.

(Varlık,1 Ocak 1942)', 'Neden sonra farkına varıyorsun Etrafındaki korkunç ıssızlığın. Yâr olsun,dost olsun,ne arıyorsun, adresi belli mi vefasızlığın? Aşk,dostluk!...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neden-sonra-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaline Aşık Oldum', 'hayaline-asik-oldum-zual-erberk-7fzw5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayaline aşık oldum

Ben ona değil onun hayaline,

Bir şarkıda kendimden geçmeye,

Görüşme değil aradaki mesafeye,

Ben ona değil, onun hayaline asik oldum.

Ben ona degil, onsuzlukta avunmaya,

Geceyle dertleşip, gizli gizli ağlamaya,

Anlatmak değil halimi, onu saklamaya,

Ben ona değil, onun hayaline aşık oldum.

Ben ona değil, yalnizligimdaki garipliğe,

Istesem nasil olsa olur düşğüncesine,

Olması değil, olabilme ihtimaline,

Ben ona değil, onun hayaline aşık oldum.', 'Hayaline aşık oldum Ben ona değil onun hayaline, Bir şarkıda kendimden geçmeye, Görüşme değil aradaki mesafeye, Ben ona değil, onun hayaline...', ARRAY['Türk Edebiyatı','Şiir','Zual Erberk']::text[], 8.5, '{"poet":"Zual Erberk","poet_slug":"zual-erberk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayaline-asik-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Geldin', 'sen-geldin-ahmet-yildiz-8ipvb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'neden geldin birden bire

 konu dağıldı

 bir türkü çaldı gözlerin

uçukladı hayat

 ve gülüşlerin birden bire...

ansızın geldin bebeğim

aysız, üstsüz

bütün varlığınla gerçek

sevişler içinde

ve yağmur kadar sarhoş...

fazlaca geldin arkadaş

tarifsiz hecesiz

yutar okyanus bilemeden

yitik bir kalem gibi

ve hesapsız...

içimde uğuldayan bir gece

her gece

sabah doluyor rüzgara

ve sen geldin sonra 

gece gece...

yaban taframa vurdun

çamca kadar mahrem

en insani

alırken kendimi dünyadan

ve tam da geldin...

ey sızı geldin işte

gitmek zamanında

beni haylama artık, tutma

daha fazla yaklaşma

ve sus...', 'neden geldin birden bire  konu dağıldı  bir türkü çaldı gözlerin uçukladı hayat  ve gülüşlerin birden bire... ansızın geldin bebeğim aysız, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yıldız']::text[], 8.5, '{"poet":"Ahmet Yıldız","poet_slug":"ahmet-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-Ş-K', 'a-s-k-mesut-hasturk-vdvjc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ilkyaz kışın düşü

yaparak doğruladı erguvan

aradı her gün''eşim kendini

döküntüsünü toplarken gece

kış-düşü erguvan kaldı 

 sende

 sen de

koynunda terlendi çağrışımlar

gözyerinde dudak yarım

kısa metrajlı bir ömür

fantastik kurgu

ölüm şenliği o''sakar adayı

yok ödülün...den başka

 düş''incem

 düş''incem

sessizliğin çığlıkanası her gecenin

yalnız biri-sarıl sıklam aşık

çalgınca öper sesini

birden kopar tenin

yırtar sessizliği bin yerimden

her çığlığı kovalar getirir im

dinle

dinle', 'ilkyaz kışın düşü yaparak doğruladı erguvan aradı her gün''eşim kendini döküntüsünü toplarken gece kış-düşü erguvan kaldı   sende  sen de koy...', ARRAY['Türk Edebiyatı','Şiir','Mesut Hastürk']::text[], 8.5, '{"poet":"Mesut Hastürk","poet_slug":"mesut-hasturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/a-s-k-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dargınım', 'darginim-i-nci-ozcan-ezh12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dargınım hayata dargınım aşka

Sevmek başka, sevilmek başka

Benim yarim bambaşka

Bir küs bir dargın ne ala

Sevdiğimi sanıp tutuldum aşka

Gönlümü verdim o vefasız yare

Bırakıp gitti beni taa derine

Bu sevgilim sevmek dargınım sana', 'Dargınım hayata dargınım aşka Sevmek başka, sevilmek başka Benim yarim bambaşka Bir küs bir dargın ne ala Sevdiğimi sanıp tutuldum aşka Gönl...', ARRAY['Türk Edebiyatı','Şiir','İnci Özcan']::text[], 8.5, '{"poet":"İnci Özcan","poet_slug":"i-nci-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/darginim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretlik Şarkısı', 'hasretlik-sarkisi-seref-yilmaz-k3ovh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen varsın ya o yeter açılmasın gül derdim

Şimdi çok uzaklarda hasretinle gül derdim

Zaman zaman yüzünde kaybolunca gamzeler

Mehtabı süzer sana bir kez olsun gül derdim

Gitsen gönül kuşuma sultanımı bul derdim

Gelmemi arzu etsen düşünmez kabul derdim

Gönüllere taht kurdun kıskandım elden seni

Hicranlı bir ses duysam âh şu İstanbul derdim', 'Sen varsın ya o yeter açılmasın gül derdim Şimdi çok uzaklarda hasretinle gül derdim Zaman zaman yüzünde kaybolunca gamzeler Mehtabı süzer s...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yılmaz']::text[], 8.5, '{"poet":"Şeref Yılmaz","poet_slug":"seref-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hasretlik-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-sema-akbaba-bc9rq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derinden bir yara var yüreğimde

Tam kabuk bağladı diyorum

Sen kör bir bıçak elinde

İnatla kanatma hevesinde

Daha da azdırıyor,acıtıyorsun her seferinde

Ne ben dur diyorum 

Ne sen vazgeçiyorsun

Bu inat bitecek elbet bir yerde

Bir gün söküp atmak için geleceksin bu yarayı

Ama yaram olmayacak yerinde

Şaşıracaksın

Bakacaksın içme

Göreceksin

Yaradan tek bir iz bile yok yüreğimde

Çünkü yüreğim de yok artık eskiden olduğu yerde...', 'Derinden bir yara var yüreğimde Tam kabuk bağladı diyorum Sen kör bir bıçak elinde İnatla kanatma hevesinde Daha da azdırıyor,acıtıyorsun he...', ARRAY['Türk Edebiyatı','Şiir','Sema Akbaba']::text[], 8.5, '{"poet":"Sema Akbaba","poet_slug":"sema-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gelir Biter', 'bir-gelir-biter-cemal-safi-4grrr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzüne bakınca içim tutuşur,

İçime bir kızıl kor gelir gider.

Geçtiğin sokaklar şavkınla ışır,

Bastığın toprağa nur gelir gider.

Helal-i hoş olsun gurur da naz da

Ne olur tebessüm etsen biraz da?

Gülmezsen gökyüzü aysız kalmaz da,

Yüzün gibi mehtap zor gelir gider.

Tarifin olmuyor ne kadar yazsam,

Ellerim tutmuyor resmini çizsem,

O güzel çehreni görmeyen ressam ,

Bilmez ki dünyaya kör gelir gider.

Yeryüzü hiç afet görmedi sanma,

Ey benim aklımı alan muamma ,

Her türlü felaket mümkündür amma,

Sen gibi kıyamet bir gelir gider.', 'Yüzüne bakınca içim tutuşur, İçime bir kızıl kor gelir gider. Geçtiğin sokaklar şavkınla ışır, Bastığın toprağa nur gelir gider. Helal-i hoş...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gelir-biter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözüm Kesmiyor', 'gozum-kesmiyor-cemal-safi-5bmfz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sessizim ne kadar üzsen de beni

Ağzımı açmaya gözüm kesmiyor

Vurduğun zincirden çözsen de beni

Bırakıp kaçmaya gözüm kesmiyor

Ne olur git deme kalbimi kır da 

Meleyen gönlümü kaptırma kurda

Sıratı geçecek imanım varda 

Aşkından geçmeye gözüm kesmiyor

Ne çıkar sararıp solsa da yüzüm

Gönlümde baharsın gelse de güzüm

Çekilmez olsa da sitemin nazın

Başka yar seçmeye gözüm kesmiyor

Ne olur git deme kalbimi kır da

Meleyen gönlümü kaptırma kurda

Sıratı gececek imanım varda

Aşkından geçmeye gözüm kesmiyor', 'Sessizim ne kadar üzsen de beni Ağzımı açmaya gözüm kesmiyor Vurduğun zincirden çözsen de beni Bırakıp kaçmaya gözüm kesmiyor Ne olur git de...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozum-kesmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin Sözleri', 'sensizligin-sozleri-sema-i-lker-gulcan-jxw73', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sana tutkunum meleğim 

 Sarı saçlarına beyaz tenine

 Ben sana tutkunum sevdiğim

 O deniz gözlerindeki minik bebeğe

 Duvarımdaki resmin acı verir kalbime

 Hazanım hüzün olur düşer yüreğime

 Ne sen yanımdasın nede hayalin

 Sen nerdesin bilmiyorum ama

 Ben hazan gecelerindeyim

 Geceler kurutuyor bedenimi

 Bu ıslak yatakta

 Sıcaklığını hissetmeliyim artık

 Bu karanlık oda da

 Karanlıklar ürkütüyor beni

 Sensizlik ise yıkıyor bedenimi

 Ne olur geri dön bebeğim

 Yüreğim kaldırmıyor bu hasreti', 'Ben sana tutkunum meleğim   Sarı saçlarına beyaz tenine  Ben sana tutkunum sevdiğim  O deniz gözlerindeki minik bebeğe  Duvarımdaki resmin a...', ARRAY['Türk Edebiyatı','Şiir','Sema İlker Gülcan']::text[], 8.5, '{"poet":"Sema İlker Gülcan","poet_slug":"sema-i-lker-gulcan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensizligin-sozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinnet Köprüsü', 'cinnet-koprusu-nazim-tektas-w39jj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Melek mi değerli, şeytan mı cin mi

Köşk mü daha güzel saray mı in mi

Kötülük için mi iyilik için mi

İnsandaki azgın hırsın adı ne

Damak zevk alıyor yediği acı

Dedikodu ballı sohbet umacı

Yürekte perçinli kinin kıskacı

Ağıt içre gülüşlerin tadı ne

Ayak nasır bağlar darlık uğruna

Yokluk kucaklanır varlık uğruna

Adet ölür kof uygarlık uğruna

Ananın yerini alan dadı ne

Baş kesilir kola hayat vermeye

Bin diken beslenir bir gül dermeye

Beyin çarmıh yapar aklı germeye

Bir bilen yok adalet ne kadı ne

Hak mekanı kalpler ifritlere in

Sadece dillerde gezer iman din

Görünürde iyiliğe talibin

Gizli değil gizli yerde yadı ne

Eş kocaya,evlat anaya tuzak

Sözler manasından bir hayli uzak

Yağlı ip boğazına dolansında bak

Dostum diyenleri gör, maksadı ne? 

Bu düzeni kuran biziz bozan biz

Zehroldu çeşmeye su veren deniz

Tepeden tırnağa hurda bedeniz

Sihirbaz ne, büyücü ne, cadı ne', 'Melek mi değerli, şeytan mı cin mi Köşk mü daha güzel saray mı in mi Kötülük için mi iyilik için mi İnsandaki azgın hırsın adı ne Damak zevk...', ARRAY['Türk Edebiyatı','Şiir','Nazım Tektaş']::text[], 8.5, '{"poet":"Nazım Tektaş","poet_slug":"nazim-tektas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cinnet-koprusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimdekiler', 'elimdekiler-arzu-bagriacik-okiz3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu garip dünyada ne için geçiyor ömrümüz? 

İyi bir iş,eş,çocuklar...

Neye ve kime göre? 

Hala anlayabilmiş değilim! 

Yinede gelip geçmekte

Bana sormadan

Cevap almak nezaketinde bulunmadan.

Takmıyorum

Kendiminkini yaşasam da...! 

Gelip yanı başıma boynunu büken yetim,

O buğulu bakışı.

Evladından ayrılan paramparça ana,baba

O yolda dikkat çeken dul.

Borcundan dolayı son eşyasını da

Hacze veren yoksul.

Lüks arabasıyla cana kıyan genç.

Gurbete giden yolcu,

Yolcuyu bekleyen hancı.

Yeni doğan bebek,

Şu an gömülen ceset.

Hastanede koşuşanlar

Kahkahalar atan tımarhanedeki deli.

Zengin,yoksul,yetim,dul,

Ölen,doğan,hasta.

İnsanlar...

Şükrediyorum.

Sıcak bir evim,aşım,işim

Sevdiğim,sevenim.

Hayattan ben daha ne isterim? 

 Ankara', 'Şu garip dünyada ne için geçiyor ömrümüz?  İyi bir iş,eş,çocuklar... Neye ve kime göre?  Hala anlayabilmiş değilim!  Yinede gelip geçmekte B...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/elimdekiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çoktular Ne Kadar Çocuktular', 'ne-coktular-ne-kadar-cocuktular-tayfun-talipoglu-e2r96', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç göze gelmediler 

Gözdesi de olmadılar  kimsenin

Kimse farkına varmadı yalansız gözlerinin

Göz oldu mu yüreklerinin

Hiç anlamadılar

Oysa ne çoktular ne kadar çocuktular

Çözülemedi bakışlarındaki tarifsiz sevdalar

Kim dedi sevgimi

Büyüyünceye kadar cevapsızdılar

Oysa ne çoktular ne kadar çocuktular

Sarıydılar ya da soluk benizli

Çoğunlukla karaya yakın bir esmer

Ve onlar genellikle burunlarını hiç silmezler

Derin iç çekişleri bundandır

Dünyanın kahrından değil

Çünkü umurlarında değil

Onların farkında olmayanlar

Oysa ne çoktular ne kadar çocuktular

Onlar çok ve çocuklar

Büyüyecek adam olacaklar

Önceleri öğretmen, ebe

Sonra doktor olmak isteyecekler

Bildiklerinden değil 

En yakınlarında onları gördüler,

Hep onlar olmak istediler

Çalınmış geleceklerinden habersiz

Yarım yamalak düşlerde eridiler

Oysa ne çoktular ne kadar çocuktular

O güzelim yürekleri 

Delikanlılık edebiyatıyla körelttiler

Okumanın erdeminden

İnsan gibi yaşamanın bilimden geçtiğinden

Haberleri olsun istemediler

Ne kadar parlarsa parlasın

Hep suskun kaldı o gözler

Oysa ne çoktular ne kadar çocuktular

Ahmed Ariften bu yana 

Yolunu gözleyenlerin adı değişti

Hepsi o kadar

Kuşpalazı, boğmaca, karaçiçek, sıtma

Belki azaldı ama

Yeni nedenleriyle yürek enfaktı

Kanser filan hala kapıda

Çaresizlik dağlar aşırmakta

Yer yurt terk edildi

Gurbet artık sıla

Çalansa bildik değil başka bir hava

Kırıldılar farkında olmasanız da

Oysa ne çoktular ne kadar çocuktular

Onlar çok ve çocuklar

Gözlerinden dillerine dökülürse 

Bir gün sorular

Sürdürebilecek miyiz aynı yalanı? 

Yoksa yine susturacak mıyız onları? 

Küçüldü dünya 

Çoğu gitti azı kaldı

Geçici demişlerdi körlüğümüze

Biraz fazla uzadı

Oysa ne çoktular ne kadar çocuktular

Onlar çok ve çocuklar 

Sesiz de kalsalar bizi bağışlamayacaklar

Mazeretlerimize inanmayacaklar

Yaşamımızda görünmedikleri her karenin

Hesabını soracaklar

Hazırlıklı olmak gerek

Çünkü onlar şimdilik 

Çok ve çocuklar', 'Hiç göze gelmediler  Gözdesi de olmadılar  kimsenin Kimse farkına varmadı yalansız gözlerinin Göz oldu mu yüreklerinin Hiç anlamadılar Oysa ...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Talipoğlu']::text[], 8.5, '{"poet":"Tayfun Talipoğlu","poet_slug":"tayfun-talipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/ne-coktular-ne-kadar-cocuktular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırsat', 'firsat-taner-akkan-spoqd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her zaman daim olmuyor aşk,

sonbaharı var, kışı var sevginin

asıl mesele yokuşunu çıkabilmek

tutabilmek onun ellerini  geceleyin

bahar gelecektir sabredersen

sabrettiği gibi güzel bir çiçeğin

sürgünleri de var uçarı gönlün

fırsat ver  yeni bahara değin....

bazen derler Kaf dağının ardında

bazen ummazsın ama yanıbaşında

yaklaşırken uzaklaştığın bir hayal

uzaklaşırken yaklaştığın bir gerçek

nerde başlar aşk  nerde biter?

solarken umudunun ak gülleri

artık gözlerini kalbine  açıver

tüm cevaplar içindedir çünkü

bahar gelecektir sabredersen

sabrettiği gibi güzel bir çiçeğin

sürgünleri de var uçarı gönlün

fırsat ver yeni bahara değin...', 'her zaman daim olmuyor aşk, sonbaharı var, kışı var sevginin asıl mesele yokuşunu çıkabilmek tutabilmek onun ellerini  geceleyin bahar gelec...', ARRAY['Türk Edebiyatı','Şiir','Taner Akkan']::text[], 8.5, '{"poet":"Taner Akkan","poet_slug":"taner-akkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/firsat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-refik-recep-pelit-vw46w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklımda kalan üç sözcük, 

Üçündede sen, 

Önümde yığınla kelimeler, 

Mürekkebimde sen... 

Gözlerim  her gün seni arar, 

Gözyaşlarım yanaklarımda kururlar, 

Yazılmıştır ismin bir buluta, 

imzalarında sen.

İnsanlar çıkış arar sözlerimde, 

Ya okurlar düşüncemi, 

Geçecek birgün der beden dilim, 

Siyahların en karasında ben... 

Çamurdur yürüdüğüm kaldırımlar, 

Ayaklarıma bulaşır balçıklar, 

Beraber koşarız tebessümlerimle, 

Yol ayrımlarında sen... 

Elimde bir demet cümle, 

Beklerim gelmeni mahkum gibi, 

Gözlerim gökyüzünde seni arar, 

Parmak uclarımda sen! 

Kaybolur düşüncelerim beynimde, 

Bir beyaz sayfada üşür cümleler, 

Hayal ederim seni biryerlerde 

Gördüğüm rüyalarda sen... 

Ormanımda bir keklik, 

Karlı dağlarında ben, 

Kardelenler avuçlarımda açar, 

Belki yaşatansın! 

Belki de solduransın sen!', 'Aklımda kalan üç sözcük,  Üçündede sen,  Önümde yığınla kelimeler,  Mürekkebimde sen...  Gözlerim  her gün seni arar,  Gözyaşlarım yanakları...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sen-ve-ben-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Hayal', 'aski-hayal-refik-recep-pelit-y7ztm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yum Gözlerini ilk Önce 

Vazgeç bu kapkara sahte dünyandan 

Varmıyız? yokmuyuz, Damlamıyız ummanmıyız? 

Bir katremiyiz yoksa sonsuz bir deryamı? 

Sır olalım istersen, Yanlız sen ve ben! 

Öyleya sahtelikle gerçeklik arasındyız, 

Düşündünmü hiç, sahtemiyiz diye! 

Yoksa sahte bir dünya içindeki tek gerçekmiyiz? 

Gariplikler vadisinde bir garip çöldeyiz, 

Kapat öyleyse gözlerini birtanem, Kapat! 

Hayalini kur kendi içindeki hayal Şehrinin, 

Görebiliyormusun bakalım, neler istiyorsun 

Burdada seviyormusun seviliyormusun? 

İstiyormusun acıyı aşkları ve sevdayı 

İstiyormusun sözüm ona arkadaşlıkları, 

İsitiyormusun kini, nefreti, 

Neyse bu senin şehrin birtanem

Ve senin hayalin öyleya, 

O zaman kapat gözlerini.', 'Yum Gözlerini ilk Önce  Vazgeç bu kapkara sahte dünyandan  Varmıyız? yokmuyuz, Damlamıyız ummanmıyız?  Bir katremiyiz yoksa sonsuz bir derya...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aski-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Aşk', 'adim-ask-refik-recep-pelit-n5y85', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizleri, bir katre görürsün, 

Adım aşk

Hazanımı bahar bilirsin

Adım aşk

Kanatların varmış gibi uçarsın

Adım aşk

Zerkedip varlığını zayii edersin, 

Adım aşk

Endamı cüsseyi zail edersin, 

Adım aşk

En acı sözlerimi tatlı duyarsın

Adım aşk

Bir damlaya deryaları sığdırırsın

Adım aşk

Dağları uğruma dümdüz edersin

Adım aşk

Bir değil bin kere candan geçersin.

Adım Aşk.

Not: Eşrefoğlu Rumi''nin ''Adı Aşk'' ad lı şiirinden faydalanılarak yazılmıştır.

Asıl adı Abdullah olan Eşrefoğlu Rumi''nin doğum yılı bilinmiyor. Babası Ahmet Eşref''in Mısır''dan geldiği ve bir Mısır''da kalan bir Türk ailesinin çocuğu olduğu sanılıyor. 

Eşrefoğlu Rumi, İznik medreselerinde öğrenim görmüş, öğrenimini bitirdikten sonra da yine İznik''te Çelebi Mehmet medresesinde müderris adayı olmuştur. 

Daha sonra Ankara''ya giderek Hacı Bayram-ı Veli''nin tekkesine girip kendini tasavvufa verdi. Hacı Bayram''ın kızı ile evlendi. Bir süre sonra Hacı Bayram tarafından Hama''ya gönderildi. Orada da tasavvufla uğraştı. Yetiştikten sonra Bursa''ya gelerek bir tekke kurdu ve Eşrefiyye tarikatını yaymaya başladı.1470''te İznik''te öldü

Cihanı hiçe satmaktır adı aşk

Döküp varlığı gitmektir adı aşk

Elinde sükkeri ayruğa sunup

Ağuyu kendi yutmaktır adı aşk

Bela yağmur gibi gökten yağarsa

Başını ona tutmaktır adı aşk

Bu alem sanki oddan bir denizdir

Ana kendini atmaktır adı aşk

Var eşrefoğlu Rumi bil hakikat

Vücudu fani etmektir adı aşk', 'Denizleri, bir katre görürsün,  Adım aşk Hazanımı bahar bilirsin Adım aşk Kanatların varmış gibi uçarsın Adım aşk Zerkedip varlığını zayii e...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/adim-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortaköy', 'ortakoy-refik-recep-pelit-k8p7j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ortaköye indim yine bugün,

Güvercinlere yem veren insanları seyrettim beş dakika

Yürüdüm ,sessizliğimle yanlızlığımla beraber,

Güldüm , bir güvercinin eşine kur yapışına,

Sahile indim , deniz tebessümle baktı yüzüme,

Bir banka oturdum ,

Balık tutan bir amcayı seyrettim,

Söylediği şarkıyı ondan habersiz dinledim ,

Ortak oldum şarkısına,sessizce !

Rüzgarida dinledim , ne kadar samimiydi ,

Bir simit aldım , mis gibi kokan , çıtır çıtır ,

Gözlerim çaycıyı aradı ,

Karşıdan bir vapur geçerken , 

El salladım vapura ,

Gördüm , Bana sallanan elleri de,

Hissettim Belkide,

Belkide Hayal ettim ,

Gülümsedim ,

Onlar beni görmedi , bende onları ,

Ama hesapsızdı gülüşüm,

Pazarlıksızdı Tebessümüm,

Dostluk gibi , Aşk gibi ,Sevgi gibi ,

Onlarınki gibi hesapsız ve içten,', 'Ortaköye indim yine bugün, Güvercinlere yem veren insanları seyrettim beş dakika Yürüdüm ,sessizliğimle yanlızlığımla beraber, Güldüm , bir ...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ortakoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-refik-recep-pelit-ggj4e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Penceresinde bir güzel dışarıda İstanbul

Bulutlar daha bir mavi geçiyor usul usul

Eskiler eskidendi onlar artık bir meçhul

İstanbulluysan eğer onu sevmek ilk koşul

Kadıköy''den Beşiktaş''a kalkar beyaz bir vapur

İnsanlar doluşmuş hepsi birbirinden meşgul

Yemyeşil bir Belgrad,İstinye olmuş pul pul

Eminönü''nde simitciler aç karınlardan mesul

Çamlıca''da aşıklar birbirlerine köle kul

Adalar da faytonlu keyif, zorunlu koşul

Bebek, Balat, Bakırköy, hepside bir şumul

Kumkapıya bir uğra bir masaya geç kurul

Ayasofya''nın minareleri Fatih kadar mağrur

Topkapı''nın surları tarihe meydan okur

Neresinde olursan ol ezan sesi duyulur 

Batan güneş kimi zaman elle bile tutulur

Beyoğlu''nda atılır nağraların en mutlusu

İstiklal''de kanunlar tambur''larla akortlu

Emirgan mis gibidir sanki minyatür Anadolu

İstanbul bile belli ki eski bir İstanbul''lu

Martıları korkusuz tüm kuşlardan da cesur

Gülhane''nin koynunda yanlızlar huzur bulur

Akşam üstü Üsküdar''a iner kıpkızıl bir nur

Arama hiç bulamazsın İstanbul''da bir kusur', 'Penceresinde bir güzel dışarıda İstanbul Bulutlar daha bir mavi geçiyor usul usul Eskiler eskidendi onlar artık bir meçhul İstanbulluysan eğ...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istanbul-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey', 'bir-sey-arzu-bagriacik-1vj7p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün canım her zamankinden daha sıkkın.

Yalnızlık tak dedi artık.

Bunu ne ben anlatabilirim

Ne de sen anlarsın.

Anlayamazsın ki! 

Acaba sen sensiz kalsaydın ne olurdu? 

İşte böyle bir şey.

Ya da 

Ben bensiz kalsaydım

İşte böyle bir şey.

Anlatabildim mi ki? 

Beceremedim.

2001 Ankara', 'Bugün canım her zamankinden daha sıkkın. Yalnızlık tak dedi artık. Bunu ne ben anlatabilirim Ne de sen anlarsın. Anlayamazsın ki!  Acaba sen...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmiş', 'degismis-refik-recep-pelit-q6osb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman hızla geçsede dünya aynı mekanda

Kurban aynı Kurban ,Kurtlar Değişmiş ,

Dişli değişmemiş dönüyor yerli yerinde ,

Kılık kıyafet kisve aynı,yöntemler değişmiş !

Güçlüler ezmekte cümle çelimsiz ve zayıfları ,

Hinler  gaspetmekte cebimizdeki meskukatı ,

Haramiler Çalıp çırpmakta ısrarlı, Cümle tebayı ,

Vatanımın hicranı aynı,Düzenbazı hırsızı değişmiş ,

Kıyılan Canlar daimi kimvurduya gitmekte ,

Kimileri matem içinde ,Kimileri şetaret peşinde,

Güzel yurdumu yaban ellerde Takdime gitmişler,

Mülk ,Servet ve Emval aynı Tüccar değişmiş !

Memleketimin  her taşı göçmüş çile cefa içinde ,

Seçtiğimiz mebbuslar fitne fesat entrika peşinde ,

İtibarı kalmadı memleketimin  bu koskoca alemde

Bu nasıl mizandır ,borç fatura aynı muhasip değişmiş.

10/04/2001', 'Zaman hızla geçsede dünya aynı mekanda Kurban aynı Kurban ,Kurtlar Değişmiş , Dişli değişmemiş dönüyor yerli yerinde , Kılık kıyafet kisve a...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/degismis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Zor', 'cok-zor-arzu-bagriacik-014kz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günleri sayıyorum,geceler bitiyor

Gecelerden gündüzlere ulaşmak

Hele sensiz sabahlamak

Sıcaklığından yoksun,üşümek

Uzaktan hissetmek

Elini attığın yerde boşluk

Çok zor.

Ulaşamıyor ellerim

Bu yük ağır geliyor taşıyamıyorum

İhtiyacım var.

Boğazımda düğüm sesleniyorum.

 Ankara', 'Günleri sayıyorum,geceler bitiyor Gecelerden gündüzlere ulaşmak Hele sensiz sabahlamak Sıcaklığından yoksun,üşümek Uzaktan hissetmek Elini a...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cok-zor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Anlayamadan Ben', 'daha-anlayamadan-ben-arzu-bagriacik-xi80u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün hiç sebepsiz;içim sıkılıyordu.

Biri geldi öl dedi.

Hiç soru sualsiz uydum sözüne

Öldüm öldüm arkadaş

Ve bir daha hiç kalkmamacasına.

Canım nasıl gitti aniden anlayamadım.

Tam yirmi yıl taşımıştım oysa onu ben

Bir rüzgar değildi uçtu gitti

Su değildi aktı geçti

Çiçek değildi kurudu gitti

Kum değildi kumsala karıştı gitti diyeyim.

Ne oldu anlayamadım ama

O gitti benden

Onca yıl taşıyan bana

Sorma zahmetini göstermeden.

09.08.1995 Samsun', 'Bir gün hiç sebepsiz;içim sıkılıyordu. Biri geldi öl dedi. Hiç soru sualsiz uydum sözüne Öldüm öldüm arkadaş Ve bir daha hiç kalkmamacasına....', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daha-anlayamadan-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Arkadaş', 'hey-arkadas-arzu-bagriacik-jbcw3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O sıcacık mekan ve sana,

Aşıp geldim yollardan.

Heyecanım; 

Otobüsün durmasıyla bitti mi sanıyorsun? 

Tüm içtenliğimle ben geldim.

Sana sevgimi,kendimi verdim.

Sar,sarmala,sev dedim.

Ilık nefesinle kayboldum.

Parmağın alnımda çizgi

Kaderimde kayboldum.

2001 Ankara', 'O sıcacık mekan ve sana, Aşıp geldim yollardan. Heyecanım;  Otobüsün durmasıyla bitti mi sanıyorsun?  Tüm içtenliğimle ben geldim. Sana sevg...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hey-arkadas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulağımda Sesin', 'kulagimda-sesin-arzu-bagriacik-l6ev1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerede kaldı her günkü sesin?

Odam loş,elimde sigaram,

Kulağım seste...

Çalmaz oldu telefonun zili.

Teybimde kasetin,

Güzel melodiler,

Kulağımda sesin...

04.03.2001 Konya', 'Nerede kaldı her günkü sesin? Odam loş,elimde sigaram, Kulağım seste... Çalmaz oldu telefonun zili. Teybimde kasetin, Güzel melodiler, Kulağ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kulagimda-sesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığınış', 'siginis-arzu-bagriacik-k20k3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yatağıma uzandım

Saçlarımı duvara yasladığım

Yastığımın üzerine,ellerimle savurdum

Gözlerimi tavana diktim

Bir acıyla irkildim.

Yanaklarımdan süzülen lanet gözyaşlarının 

Tek sebebi;

Oysa açık unuttuğum lambaydı.

Taa gözlerime giriyor; yakıyor,yakıyordu.

30.10.1995 Merzifon', 'Yatağıma uzandım Saçlarımı duvara yasladığım Yastığımın üzerine,ellerimle savurdum Gözlerimi tavana diktim Bir acıyla irkildim. Yanaklarımda...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/siginis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sil Baştan', 'sil-bastan-arzu-bagriacik-d1xuk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tam iki sene hasta yattım

Dört duvar arasında,

Hasta çocuklarla birlikte.

Ne insanlar geldi geçti,

Ben ise hala aynı yerde

Kendimi bilemeden 

Ve şehrin sokaklarını.

Caddeleri unuttum,

Bilardo oynamasını ve hatta tavlayı.

Hastaneden çıkınca kayboldum,

Kendi evimi bulamadım.

Ama şimdi ne güzel,yeni baştan

Yürümek ve sevmeye başlamak insanları,doğayı

Ürkmemek,korkmamak.

09.12.2000 Ankara', 'Tam iki sene hasta yattım Dört duvar arasında, Hasta çocuklarla birlikte. Ne insanlar geldi geçti, Ben ise hala aynı yerde Kendimi bilemeden...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sil-bastan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Uyusam', '1-uyusam-arzu-bagriacik-c6gce', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessizlik içinde kayboluyorum.

Bir ağırlık var gözlerimde,

Uyusam.....

Uyusam; uyanamam diye korkarım.

Soluklarım yavaşlıyor,

Sigaramın dumanı daha kuvvetli yakıyor içimi.

Halsizim...

Duygularım kayıp,hissetmiyorum.

Bomboşum.

Ah bir UYUSAM...', 'Sessizlik içinde kayboluyorum. Bir ağırlık var gözlerimde, Uyusam..... Uyusam; uyanamam diye korkarım. Soluklarım yavaşlıyor, Sigaramın duma...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/1-uyusam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapamam', 'yapamam-arzu-bagriacik-oljp5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı yine

Gözlerim inatla kapanmıyor.

Işık yakıyor canımı.

Susamışım.

Kana kana içmek vardı şimdi.

Camdan dışarı yöneliyorum,

Sessizlik ne hoş huzur.

İşte Kocatepe manzarası

Bakıp resmetmek isterim

Yada sayfalarca anlatmak.

Yapamam; 

Yaşamanın hoşluğu ve huzuru hatırına.

Ankara', 'Gecenin bir yarısı yine Gözlerim inatla kapanmıyor. Işık yakıyor canımı. Susamışım. Kana kana içmek vardı şimdi. Camdan dışarı yöneliyorum, ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yapamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişim', 'degisim-baris-ozkaya-rbhku', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Değişimden kaçılmıyor sevdiğim

         kaçsak,

                        kaçarken değişim

         dursak,

                       durduğumuz yerde değişim.

Hele etkileşiminde 

                                 iki kişinin

         her saniye değişim!

Bakalım seni

         her saniye

                sevebilecek miyim?', 'Değişimden kaçılmıyor sevdiğim          kaçsak,                         kaçarken değişim          dursak,                        durduğumuz ...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/degisim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımı', 'gun-batimi-tevfik-mengulluoglu-36ou5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Alaca karanlık vuruyor bu kentin yamaçlarına

Ve ben oturmuş hâlâ seni bekliyorum.

Gün batımını en iyi izlediğimiz yerden, 

Mızıkasını çalan çocuk aldı sürüsünü

Bir tek ben kaldım bir de gün batımı 

Uzaklardan bir ezginin sesi geliyor kulaklarıma

Bir de yokluğunun sesi

Oysa ben hala bekliyorum.', 'Alaca karanlık vuruyor bu kentin yamaçlarına Ve ben oturmuş hâlâ seni bekliyorum. Gün batımını en iyi izlediğimiz yerden,  Mızıkasını çalan ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gun-batimi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'dusunuyorum-da', 'dusunuyorum-da-mehmet-tas-x9kdy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum da

Nasıl olurdu bir merminin

Yakan sıcaklığını

Şakağında hissetmek..?

Ölümün katılaştıran seğirmelerinde

Süzülüşünü seyretmek

Göz çukurlarına dolan kanın...

Silinip giderken düşünceler

Veda etmeden kimseye

Sessiz ve umarsız 

Çekip gitmek hayattan...

Düşünüyorum da

Nasıl olurdu

Duymadan,görmeden

Arkamdan gelen kalabalığın

Kimi zaman ahlarında bir küfrü

Kimi zaman feryadı hissetmek

Ve çırpınışlarında sevgililerin

Bırakıp gitmek...

Düşünüyorum da

Yaşarken de öyleydin ama

Değer mi ey hayat

Seni böyle anlamsız

Amaçsız

Bir hiç olarak bırakıp gitmek..?', 'Düşünüyorum da Nasıl olurdu bir merminin Yakan sıcaklığını Şakağında hissetmek..? Ölümün katılaştıran seğirmelerinde Süzülüşünü seyretmek Gö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dusunuyorum-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-mehmet-tas-hdm7s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretin adını şiir eyledim

Saldım bulutlara alasın diye

Türküler söyledim seher yeline

Her sabah sesimi duyasın diye



Gün oldu maviye boyadım ayı

Gün oldu kızardı  Ceyhan’ın suyu

Gün oldu içimden kurdum kurguyu

Dualar eyledim gelesin diye...

                       

Çiçek çiçek açtı içimde sevdan

Kavak yeli oldu başımda sevdan

Hayalimde sevdan,düşümde sevdan

Uzattım gönlümü alasın diye...', 'Hasretin adını şiir eyledim Saldım bulutlara alasın diye Türküler söyledim seher yeline Her sabah sesimi duyasın diye Gün oldu maviye boyadı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-icin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolaysa...', 'kolaysa-levent-kayikci-nv8nf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aylarca sevmissin deliler gibi,

Ugruna vermissin her seyini,

Hakettinmiki boyle kahpeligi?

Kolaysa uzulme sen, kolaysa aglama sen!

Dost dedigin vurmus sirtindan,

Yar dedigin etmis seni darma duman,

Yalnizlik ve gurbette diger yandan,

Kolaysa uzulme sen, kolaysa aglama sen!

Kimsenmi var derdin dinlesin,

Yarin nerde sirtin oksasin,

Dostun hani teselli etsin,

Kolaysa uzulme sen, kolaysa aglama sen!

Ingiltere,Kent Mart2000', 'Aylarca sevmissin deliler gibi, Ugruna vermissin her seyini, Hakettinmiki boyle kahpeligi? Kolaysa uzulme sen, kolaysa aglama sen! Dost dedi...', ARRAY['Türk Edebiyatı','Şiir','Levent Kayıkçı']::text[], 8.5, '{"poet":"Levent Kayıkçı","poet_slug":"levent-kayikci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kolaysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Sen Koy', 'adini-sen-koy-levent-kayikci-4dv03', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir nikotin dolu gece daha

Elimde en iyi arkadasim sigara

Aklimda sen, mutlu gunler, gezdigimiz yerler

Bitti artik iste, yerinde esiyor yeller

Ama aklimdan cikmiyorsun ulan cikmiyorsun iste

O kadar adilige, kahpelige ragmen 

Seni dusunuyor, seni seviyor, seni yasiyorum

Goz yaslarimda eslik ediyor ara sira...

Baktigim her yerde, her kosede, her noktada sen varsin

Seviyorum iste,hala seviyorum hemde deliler gibi

Ama bende sende olmayan bisey var gulum:gurur

Artik yollarimiz farkli, dunyalarimiz ayri

Ama su bi gercekki benim hatam buyuk,

Son pismanlik fayda etmiyor

Hata yapan cekiyor acisini

Ah gulum ah; benim en buyuk hatam sensin sen!

Nerden aldim seni hayatima ben?

Ama sunu iyi isit ve belle

Bir gun cok pisman olacaksin 

Kin ve nefretimin siddetiyle pisman bir sekilde gebereceksin!!', 'Bir nikotin dolu gece daha Elimde en iyi arkadasim sigara Aklimda sen, mutlu gunler, gezdigimiz yerler Bitti artik iste, yerinde esiyor yell...', ARRAY['Türk Edebiyatı','Şiir','Levent Kayıkçı']::text[], 8.5, '{"poet":"Levent Kayıkçı","poet_slug":"levent-kayikci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adini-sen-koy-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşime...', 'kardesime-levent-kayikci-gxpz0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatimizin baharinda sevdalanmadikmi deli gibi,

Kazimadikmi sira,kapi ve duvarlara isimlerini

Beraber askin dikenli yollarinda yurumedikmi

Ah be kardesim sen soyle biz bunu hakettikmi?

Soyle kardesim cekinme soyle ami goz yasi doktuk?

Iki liseli icin kendi kendimizi kahrettik

Ne dert istedik, ne sevgi

Muhabbet istedik, bahane ettik sevgiyi

Daha yasimiz kac, ask mesk neyimize?

Yolumuz daha uzun rastlariz nicelerine

Giden gider baskasi gelir yerine

Ana baci kalplerde, salla eli gerisine!', 'Hayatimizin baharinda sevdalanmadikmi deli gibi, Kazimadikmi sira,kapi ve duvarlara isimlerini Beraber askin dikenli yollarinda yurumedikmi ...', ARRAY['Türk Edebiyatı','Şiir','Levent Kayıkçı']::text[], 8.5, '{"poet":"Levent Kayıkçı","poet_slug":"levent-kayikci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kardesime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-aytac-karahan-9r03a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kişi sevdiğiyle olmak ister!. 

Sevdiğinin hâliyle hâllenir... Sevgisi kadarıyla, onunla yaşar!. 

Sevginin ne olduğunu tam olarak bilemediğimiz için, 

çoğunlukla, ''beğeni'' ile ''sevgi''yi birbirine karıştırırız.. 

''Beğeni'' yanında ''sahip olma'' arzusuyla açığa çıkar!. 

Bir nesneden hoşlandığında, beğendiğin şeye sahip olmak ve 

üzerinde tasarruf edebilmek arzusuyla yaşarsın... 

Bu tüm mahlukatta çok yaygın bir duygudur!. 

Kimi, beğendiğini cebine sokar; 

kimi beğendiğine tasma takıp yanında taşıyarak onunla hava atmak 

ister; 

kimi yakalayıp inine sürükler... Her mahlûk yaradılış fıtratına göre, 

beğendiği üzerinde tasarruf etmek ister. 

''Sevmek'' ise bundan çok farklıdır... 

Sevince, yanlızca sevdiğin için yaşamak istersin!. 

Yalnızca yanında olmak, yalnızca onun olmak, 

yalnızca onun zevk aldığıyla zevk alıp, sevmediğinden kaçmak 

istersin! 

Sevdiğin öylesine sarmıştır aklını, fikrini, ruhunu ki, her şey sana, 

onu hatırlatır; yanında iken bile onun içinde olmak istersin!... 

Yakınlık bile uzak gelir sana!... 

Sen kaybolursun, sende; sevdiğin kalır yalnızca, beyninde!.. 

Onun bakışıyla bakar, onun değerlendirmesiyle değerlendirir, 

onun diliyle konuşmaya başlarsın!. Gözün ondan başkasını görmez, 

kulağın ondan başkasını duymaz, 

elin ondan başkasına uzanmaz olur!. 

Her an sana sahip olmasını; varlığının, tasarrufunun her an 

üzerinde olmasını, her an seni kucaklamasını istersin!... 

Bedensel yakınlık bile, korkunç uzaklık gibi gelir sana; 

ve onunla tek bir beden, tek bir ruh, tek bir şuur olmayı dilersin!. 

Sevgi, fıtratın müsait ise, sevdiğinde yok edesiye yakar seni; 

ve gün gelir kaşında-gözünde, yüzünde-dilinde 

sevdiğini görürler de, ''sen o olmuşun'' derler! 

Beğenen sahip olmak ister... 

Seven ise sevdiğinde yok olur; feda eder her şeyi sevdiği uğruna!. 

Bazılarının da sevgi kokusu sürülür üstüne; ''aşığım'' sanır!. 

Ama sevdiği uğruna, fedakarlık etmeye gelince sıra, 

o koku siliniverir üzerinden ''kopamama'' sabunuyla!. 

Parasından kopamaz... Mevkiinden kopamaz... 

Yakınlarından kopamaz... İçinde yaşadığı ortamın 

güzelliklerinden kopamaz... ''Etraf''tan kopamaz!. 

Derken kusurlar belirmeye başlar sevdiğini sandığının üzerinde... 

Eksiklikler görmeye başlar başlar, yetersizlikler görmeye başlar... 

Bunlar önce acıma duygusuna dönüştürür sevgisini; 

uzaktan acıyarak seyretmeye başlar... 

Sonra tatlı bir anıya dönüşür, sevgi sandığı duyguları!. 

Bu tecrübe gösterir ki, onun fıtratında sevgi programı yoktur!.. 

Beğeniyi, sevgi sanmıştır!.. 

Uzaklaşma ondan gelmemiş de, karşısındakinden gelmişse, 

bu defa ''nefret''e döner ''beğeni''; ondan intikam alma duygusu 

gelişir içinde; ve vicdanla intikam dalgaları arasında 

bir o yana bir bu yana sürüklenir durur; terkedilmişliğin, 

uzaklaşmanın, 

layık olmadığını yaşamanın sanısı içinde!.. 

Oysa yanlızca, fıtratında olmayan gerçek sevginin sonuçlarını 

yaşamaktadır!.

Cüzdanı için, güzelliği-yakışıklılığı için, kendisine hoş gelen 

huyları 

için, 

mevkii-koltuğu için, ilmi için beğenmiştir; sevdiğini sanmış; 

sahip olamayınca da arzusuna erişememenin düş kırıklığı içinde 

kopmuş; 

yalnızca çıkarları doğrultusunda yaşamayı tercih etmiştir... 

Seven ise göze almıştır kopmayı... Dışlanmayı... 

Paradan-puldan, namdan nişandan, dosttan akrabadan uzak kalmayı... 

Fıtratından gelir sevgi!. Kulluğu sevmek üzeredir!. 

Onunla, sevmeyi yaşamak istediği için yaratmıştır onu Yaratan... 

O yüzden kopar anadan-babadan; dünyadan paradan! 

Seven, karşılıksız sever!... 

Beğenen karşılığını ister!. 

Benim istediğim gibi yaşarsan seni boğarım sahip olduklarıma, der 

beğenen!..

Onun zaten fıtratında yoktur sevgi, bilmez aşkın ne olduğunu!.. 

Ne üzere yaratılmışsa, odur tüm meşgalesi... Karınca gibi çalışır; 

maymun gibi çiftleşir; aslan gibi yavrularına sahip çıkar... 

Ama pervane gibi sevemez!. Atamaz kendini ateşe!. 

Sevgi sonunda yanmayı getirir!.. Beğeni ise sonunda kaçmayı!. 

Beğenen mahlûkat çoğunluğuna göre, ''sevgi'' delilikten bir türdür!.. 

Anlamazlar onlar, sevdiği uğruna, etraf ne derse desin deyip,her 

şarta 

katlanmayı! 

Ve ''delillik bu'' derler... 

Beğenme bir tür ''hobi''dir!... 

Bazen ömür boyu sürer, bazen bir kaçyıl, bazen bir kaç ay!.. 

Sevgi bir ömür boyudur!... 

Bitmez, tükenmez, bazen durulur, bazen coşar ama hiç gerilemez!.', 'Kişi sevdiğiyle olmak ister!.  Sevdiğinin hâliyle hâllenir... Sevgisi kadarıyla, onunla yaşar!.  Sevginin ne olduğunu tam olarak bilemediğim...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Karahan']::text[], 8.5, '{"poet":"Aytaç Karahan","poet_slug":"aytac-karahan","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/sevmek-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-mustafa-yildizdogan-f3xqe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin için düştüm çöle,

Gönül döndü solmuş güle,

Beni böyle bile bile

Ortalıkta koyma Leyla.

Olan oldu, gülen güldü,

Felek canı sana böldü,

Bu gariban artık öldü,

Yaşıyorum sayma Leyla.

Aşkların aşkı Mevladır

Sevene çile evladır

Gayrı her güzel Leyladır

Bunu benden duyma Leyla.', 'Senin için düştüm çöle, Gönül döndü solmuş güle, Beni böyle bile bile Ortalıkta koyma Leyla. Olan oldu, gülen güldü, Felek canı sana böldü, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/leyla-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Mektupta', 'anlat-mektupta-mustafa-yildizdogan-co0el', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günlerin ayların ne isimleri 

Gönder de hatırlat yok resimleri 

Unuttum unuttum tüm mevsimleri 

Kar nasıl yağardı anlat mektupta 

Arıyı peteği bal özünü de 

Yeşili çimeni  kır sözünü de 

Unuttum unuttum gökyüzünü de 

Kuş nasıl uçardı anlat mektupta 

Kelebek rüzgara kızar mı bazı 

Dal dal öpüp de eder mi nazı 

Unuttum unuttum baharı yazı 

Gül nasıl kokardı anlat mektupta 

Düşümde görürüm bazen anamı 

El açıp yalvarır dua bana mı 

Unuttum unuttum yaşlı babamı 

O nasıl yiğitti anlat mektupta. 

Beklerken hücremde sehpa sıramı 

Bir sızı gelip de yakar şuramı 

Unuttum unuttum yerim bura mı 

Er nasıl yutulur anlat mektupta. 

Anlat anlat çünkü hasretiyim bunların 

Ozan Mustafa''mda özlem yıllarım 

Unuttum unuttum biten yolları 

Son nasıl derler anlat mektupta.', 'Günlerin ayların ne isimleri  Gönder de hatırlat yok resimleri  Unuttum unuttum tüm mevsimleri  Kar nasıl yağardı anlat mektupta  Arıyı pete...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlat-mektupta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Neredesin', 'sen-neredesin-mustafa-yildizdogan-sp8zb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüce dağlar gibi başım karlandı

Yağdım gözlerimden yaşım karlandı

Yemedim içmedim aşım karlandı

Deli divaneyim sen neredesin

Gören deli diyor derdi ne demez

Öyle yalnızım dillerim dönmez

Baykuş bile uğrak vermez tünemez

Yıkık viraneyim sen neredesin

Yıldızdoğan’ını bekletme yeter

Beklemek gönlüme ölümden beter

Kurbanım olayım çektirme yeter

Sana pervaneyim sen neredesin', 'Yüce dağlar gibi başım karlandı Yağdım gözlerimden yaşım karlandı Yemedim içmedim aşım karlandı Deli divaneyim sen neredesin Gören deli diyo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-neredesin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batmışım Ben', 'batmisim-ben-reis-mert-yl5k5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerden çıktı bu rüzgar

Nerden çıktı bu fırtına

Yalvarırım dur artık

Dayanamaz gemim buna

Dalgalar her vurduğunda

Sanki içimden bir parça kopuyor

Bak işte yelkenimide yırttın 

Bitiyorum görüyorsun

Niye hala devam ediyorsun

Sen koca okyanus

Ne istiyorsun fani bedenimden

Batıyorum işte bak sen kazandın

Diğerleri gibi beni de harcadın.', 'Nerden çıktı bu rüzgar Nerden çıktı bu fırtına Yalvarırım dur artık Dayanamaz gemim buna Dalgalar her vurduğunda Sanki içimden bir parça kop...', ARRAY['Türk Edebiyatı','Şiir','Reis Mert']::text[], 8.5, '{"poet":"Reis Mert","poet_slug":"reis-mert","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/batmisim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur!', 'ne-olur-reis-mert-qlwca', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana olan aşkım güzelim

Uçsuz bucaksız bir okyanusta yıkık dökük bir gemi ile giderken görünen bir ada gibi

Adaya yaklaştıkça,

Yeniden hayata dönmenin sevinci içimde

Ama 

Bir yandan da gözlerimde bir korku

Gemim oraya kadar dayanabilecek mi?

Ne olur rüzgar yardım et bana

Ne olur karaya kadar gidebileyim

Ne olur adada kimse olmasın

Ne olur Ne olur!!!!', 'Sana olan aşkım güzelim Uçsuz bucaksız bir okyanusta yıkık dökük bir gemi ile giderken görünen bir ada gibi Adaya yaklaştıkça, Yeniden hayat...', ARRAY['Türk Edebiyatı','Şiir','Reis Mert']::text[], 8.5, '{"poet":"Reis Mert","poet_slug":"reis-mert","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ne-olur-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbakir Türküsü', 'diyarbakir-turkusu-yusuf-hayaloglu-af96q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Diyarbakır ortasinda vurulmuş uzaırım

Ben bu kurşun sesini nerde olsa tanırım

Bu dağlarda gençliğim cayı cayır yanarken

Ay vurur gözyaşına ben gecede kalırım

Üzülme sen, üzülme başını öne eğme

Gün olur kavuşuruz, dert etme Diyarbakır

Yüreğini dağlama, kanlı bezler bağlama

Bu yangın söner birgün, ağlama Diyarbakır

Diyarbakır yolunda toz olmuş dağılırım

Bu hırçın depremlerle sarsılırım kanarım

Arkadaşların yüzü ağır ağır solarken

Gün doğar yaylalara, kahrımdan utanırım

Ey fırtınalı bayır, ey mazlum Diyarbakır

Dağlarında ateşler, alnında kızıl bakır

Çiğdemler solar gibi, anneler yanar gibi

Dizlerine döküldüm, ağlama Diyarbakır', 'Diyarbakır ortasinda vurulmuş uzaırım Ben bu kurşun sesini nerde olsa tanırım Bu dağlarda gençliğim cayı cayır yanarken Ay vurur gözyaşına b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/diyarbakir-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yanma Diye', 'sen-yanma-diye-yusuf-hayaloglu-nztm5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben çürümüş bir asayım

Zindanlara yol eyledi dert beni

Çarmıha gerilmiş bir İsa''yım

Çivilere zapteyledi dert beni

Pir sultanıda gördüm

Darağaca vur eyledi aşk beni

Hacı Bektaş''ı kırda gördüm

Bir ceylana pir eyledi aşk beni

Her yangına, her ataşa

Koz eyledi dert beni

Bu dağlara, bu yollara

Toz eyledi aşk beni

Ben yanarım aşk için

Ben yanarım gül için

Bu ateş sönmesin diye

Ben yanarım kim için

Ben yanarım sen için

Bari sen yanma diye

Ben yıkılmış bir ozanım

Yangınlara kül eyledi dert beni

Kerbela çölünde, bir Hüseyi''nim

Damla suya kul eyledi dert beni

Ben Yunus''u nurda gördüm

Dergahına gül eyledi aşk beni

O mecnu''nu firarda gördüm

Bir Leyla''ya deleyledi aşk beni', 'Ben çürümüş bir asayım Zindanlara yol eyledi dert beni Çarmıha gerilmiş bir İsa''yım Çivilere zapteyledi dert beni Pir sultanıda gördüm Darağ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-yanma-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Deme', 'gel-deme-mehmet-tas-2zlan', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceye bir ninni yayılır birden

Yavaşça yapraklar suları okşar

Serçeler uyurken dal uçlarında

İçimde gecenin hüznü başlar

Bir yağmur örseler karanlıkları

Bir şimşek şavkını sulara serer

Ceyhan ırmağında ruhum ıslanır.



Gel deme...Uyamam çağrına şimdi

Ruhum zindanlarda çile doldurur

Üryan bedenimde sara nöbeti

Yıkar dört yanımı depremler olur

Yorgunum sevdanı taşımaktan  ah

Yollar hasretimi çarmığa gerer

Ceyhan ırmağında hayalin uyur...



Bir yağmur başlar inceden ince

Islak çimenlerde ışıklar oynar

Geceye bir hüzün yayılır birden

Hasret hasret bakar büyün yıldızlar

Parçalar  geceyi sessiz bir çığlık

İçimde hasretin türküsü başlar

Ceyhan  sularında  hasretin büyür...', 'Geceye bir ninni yayılır birden Yavaşça yapraklar suları okşar Serçeler uyurken dal uçlarında İçimde gecenin hüznü başlar Bir yağmur örseler...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gel-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anlatır', 'seni-anlatir-mehmet-tas-3gv61', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni bana sorma ,

Seni sana ben anlatamam...

Seni mehtaba sor geceleri

Suların şavkımasında yıldızlara sor.

Soluk alışında karanlıkların

Bir liman gibi sığındığım

Sokak lambasının aydınlattığı

Kaldırım taşlarına sor...

Seni bana sorma

Sabah rüzgarının serinliğinde

Güne merhaba diyen

Uykuya hasret gözlerin

Mahzun bakışlarına sor...

Dağların sessiz yamaçlarında

Yeni açmış kır çiçeklerine

Bulutların siyim siyim gözyaşlarına

Mesafelerin kahreden hudut taşlarına

Cami avlusunda ki dilencinin kirli avuçlarına

Denizlerin hırçın dalgalarına

Çingenenin umut dolu falına

Boyacı çocuğun bakışlarına sor....

Seni bana sorma;

Gözlerimde şavkıyan ışıltılara

Ruhumda ki fırtınalara

Ve bahara

Ve bahara sor...', 'seni bana sorma , Seni sana ben anlatamam... Seni mehtaba sor geceleri Suların şavkımasında yıldızlara sor. Soluk alışında karanlıkların Bir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-anlatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme İthaf', 'anneme-i-thaf-mehmet-batihan-plxtd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana gelen yol uzak değil,

Belki kolay aşılmaz,

Ve dağdağalı bir yoldur.

Ama uzak değil seni aramak:

Aşkın gözyaşlarıyla 

ıslanmış sineyle seni aramak...

          

Kan damlamış gözlerle, 

 İçimdeki uzayvari  boşlukla,

Veremeden gittiğin sevginle,

Doyasıya ağlamakla,

Kıyasıya özlemekle,

Çatlakları akıtarak  sana uzanmak...

Bir ark gibi...

Dağları sıyıran gözü yaşlı lodosla,

Sana doğru esmek uzak değil...

          

Rüyalarımda geceleri

Ve düşlerimde gündüzleri,

Her dem seninleyim.

Hatırımda kalan son kuşamınla:

Simsiyah fistanın

Ve yeşil yazmanla

Bir nefes kadar yakınsın sanki... 

Uzatıveriyorum ellerimi, uzattığın eline. 

Yazık ulaşamıyorum.

 Yakalaştıkça ırıyorsun.

Susadıkça görüyorum. 

Serap oluyorsun.

Sana ulaşmak zor aydınlık hayatta.

Karanlıkta bulmuşum seni.

            

Mor gölgeler içinde yansıyan bir  ışıksın,

Dağdağalı yolumu aydınlatan,

Buğulu görünümlüsün,

Kavrayamıyorum zifiride. 

Kördüğüm içindesin. 

Çözemeden kayboluyorsun,

Mor ışıklar hızıyla.

Senin diyarın farklı,

Belki ötelerin ötesinde,

Ama uzak değil...

           

Sen nasıl gitmişsen işte...

Bir gün ben de giderim.

Hasret kokan kucağına, 

Soğuk bedenimle gelmem pek yakındır.

Uzak değil, 

Uzak değil anneciğim...', 'Sana gelen yol uzak değil, Belki kolay aşılmaz, Ve dağdağalı bir yoldur. Ama uzak değil seni aramak: Aşkın gözyaşlarıyla  ıslanmış sineyle s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Batıhan']::text[], 8.5, '{"poet":"Mehmet Batıhan","poet_slug":"mehmet-batihan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/anneme-ithaf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim mi?', 'seni-sevdim-mi-engin-yavuz-1g7hn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevdim mi ?

Sevdim !

Hem de çok 

Seni sevmeyi sevdim 

Belki de ; senin uzaklığını sevdim 

Seni sensiz yaşamayı sevdim 

Karanlık gecelerde 

Yalnızlığı...

Uykusuz gecelerde düşlerini sevdim 

Ya sen ?

Beni sevdin mi .......?', 'Seni sevdim mi ? Sevdim ! Hem de çok  Seni sevmeyi sevdim  Belki de ; senin uzaklığını sevdim  Seni sensiz yaşamayı sevdim  Karanlık geceler...', ARRAY['Türk Edebiyatı','Şiir','Engin Yavuz']::text[], 8.5, '{"poet":"Engin Yavuz","poet_slug":"engin-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-sevdim-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Kalıntısı', 'ozgurluk-kalintisi-mehmet-batihan-oe2j4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'öyle biryer düşlemekteyim ki 

kirlerden ve paslardan uzak 

ne bir ayıp işlenir orda ne de yasak 

temizdir insanları kalpten yana 

kurulmaz eşe dosta tuzak

düşünceden yakın 

ama gözlerden öyle uzak

öyle uzak ki 

uzak olduğu kadar güzel,

güzel olduğu kadar özgür,

bak, düşleye düşleye suyun benzi sarardı.

maviliğini yitirmiş gökyüzü

bir solukta güneşi tüketen yiğitler

sersem bakışlı olmuş

ben de mosmor olmuşum uçarı hayallerden

baksana,

içkim zakkumdur sanki 

suyum irindir sanki

ama öyle bir hissim var ki

hayaller deryasında yüzen umut gemisi

yol almakta gece gündüz

beynin en özgür, en çıplak

ve en yasaklı yerinden 

durmaksızın nehir vari yol almakta

derin suların yosun tutmayan kayalarına doğru 

ve midyelerce kuşatılan elmas dağlarına

pek yakın olmasa da 

ötede,

ta ötelerin ötesinde

denizlerin ardında 

özgürlüğün sessiz bekleyişi

ve şair Mehmet’in içindeki 

dalga dalga kavganın en şiddetlisinden kalan

sessiz bir çığlık ile

sevgilisiz bulvarlardan

yükselir şimdi silah sesleri...

                                         

                                                     01.05.1998', 'öyle biryer düşlemekteyim ki  kirlerden ve paslardan uzak  ne bir ayıp işlenir orda ne de yasak  temizdir insanları kalpten yana  kurulmaz e...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Batıhan']::text[], 8.5, '{"poet":"Mehmet Batıhan","poet_slug":"mehmet-batihan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ozgurluk-kalintisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıktır Bu', 'ayriliktir-bu-ercan-buyukkahraman-5na01', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uykusuzum sensız gecelerde

Kararsızım sensız yerlerde

Buradan bır cıkabılsem

Senınle el ele

Ama sen yoksum yanımda

Ben ıse bır boslukta

Nedır bu anlayamıyorum

Bır tek senı sevıyorum

Sen hep aklımdasın 

Nedır bu anlamıyorum

Bır tek sey bılıyorum

Sensızlıktır bu', 'Uykusuzum sensız gecelerde Kararsızım sensız yerlerde Buradan bır cıkabılsem Senınle el ele Ama sen yoksum yanımda Ben ıse bır boslukta Nedı...', ARRAY['Türk Edebiyatı','Şiir','Ercan Büyükkahraman']::text[], 8.5, '{"poet":"Ercan Büyükkahraman","poet_slug":"ercan-buyukkahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayriliktir-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Ağır Yenilgi', 'en-agir-yenilgi-engin-yavuz-hl3bs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bende oluşturduğun 

Depremin farkındamısın 

Bende hiç birşey bırakmadan yıkıp geçen 

Beni benden alıp götüren ve... 

Yine beni benle bırakıp 

Çekip giden 

İşte sen böyle bir felaketsin 

Doğal olan bir şey belki bu senin için 

Ama ben... 

Bende oluşan sevginin farkında bile değilsin 

Çünkü sen senin için yaşıyorsun 

Neden mutluyken mutsuz olmayı istersin 

Benimle mutlu olduğunu söylerken 

Herşeyin bende gizli olduğunu düşünürken çekip gitmek Kolay olan 

Ben zor olanı tercih ettim seni... 

Sonuç belkide yenilgi olacak

Varsın olsun yenilgi almak çokta kötü değil 

Ben zaten yenilgilere alışkınım 

Senden öncede vardı senden sonrada olacak eminim 

Ama en ağır yenilgi bu olsa gerek ! 

Kendime gelecek gücüm kalmadı 

Yoruldum hemde çok 

Mücadele edecek gücüm yok artık 

Bir an mutlu olup 

Hemen ardından mutsuz olmak 

İnan çok kötü 

Neden hayatı yaşamamızı güzel olan şeyleri tatmamızı İstemezsin 

Daha neler yaşayacağımızı sanıyorsun ki 

İnsan elindekilerin kıymetini neden bilmez 

Sen ve ben mutluyken 

Mutsuzluğu umutsuzluğu seçmek ! 

Neyse... 

Herşey senin için güzel olsun 

Sen hakediyorsun bunu 

Ama unutma “sevidiğin kadar sevilirsin” 

Diyende sensin !

Ben buna inanıyorum fakat henüz sevdiğim kadar Sevilemedim 

Sevdiğim kadar beni sevecek olan biri var mı sence 

“Evet mutlaka vardır”  diyeceksin 

Ama ben öyle çok fazla sevende değilim az ve öz severim 

Tıpkı seni sevdiğim gibi...........', 'Sen bende oluşturduğun  Depremin farkındamısın  Bende hiç birşey bırakmadan yıkıp geçen  Beni benden alıp götüren ve...  Yine beni benle bır...', ARRAY['Türk Edebiyatı','Şiir','Engin Yavuz']::text[], 8.5, '{"poet":"Engin Yavuz","poet_slug":"engin-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/en-agir-yenilgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemdir Sana', 'sitemdir-sana-ercan-buyukkahraman-dya98', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sakin bana alinma ama  bunlar sana

Sen ki insani bir boslukta

Yapayalniz birakan degilmisin

Senki o insani kendine asik edip

Kendine kole eden degilmisin

Ama o da birgun farkina varacak bunlarin

Bu yaptiklarini yuzune vuracak yakindir

Ama sen her zamanki pisginliginle

Gulmeyi umursamamayi bilirsin

O gun bugundur 

Bir tek farkla bu gundur

Cunku sen artik gulemeyeceksin

Sana soyledigim o son laf 

Kalbinde bir hancer 

Sana o son bakisim sa icine dert olacak', 'Sakin bana alinma ama  bunlar sana Sen ki insani bir boslukta Yapayalniz birakan degilmisin Senki o insani kendine asik edip Kendine kole ed...', ARRAY['Türk Edebiyatı','Şiir','Ercan Büyükkahraman']::text[], 8.5, '{"poet":"Ercan Büyükkahraman","poet_slug":"ercan-buyukkahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sitemdir-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluta Çizelen Resim', 'buluta-cizelen-resim-i-dris-koylu-birdost-lvh8d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay olurum gecelere

Tütün dalına düşerim

Gün olurum zemheride

Gülün al''ına düşerim

Gül dalında güzeldir

Gün ufuklarda

Can teninde güzeldir

Bıçak kınında

Gül dalında vurulur

Dile gelir dağ-taş

Feryat figanda börtü böcek

Can teninde vurulur

Kınında çıldırır bıçak

Nasıl da dağlar içimi

Nasırlaşan yüreklerde ölüm sessizliği

Oysa neler düşlemiştik

Nelere hasrettik gülüm

Nelere hasretti dünya

Turnalar inecekti su başlarına

Bir ikindi üstü

Gökyüzü konacaktı avuçlarımıza

Mavi ve berrak

Ay saracaktı ovayı

Akasyalar ortasından

Bu bahar patlar demiştik tomurcuk

Dal''la yaprak arasından

Rüzgârda dağıldı düşlerimiz

Ortasında kaldık o puşt ölümün

Yine tan kızıltısında çakal sesleri

Güvercin kanadında kurşun yarası

Uzayan yollar gibi incelir bakışların

Kirpiklerinde titreşir bir yağmur damlası

Hüznün dağlara vurur

Tutuşur çınarlar

Kuzguna mesken oldukça

Yiğidin harman olduğu yerler

Canevimde saklı tuttum sevdanı

Bir de sen yıkma beni

Kaldır kaşlarını yaslan omzuma

Öyküler anlatayım

Umuttan düşten

Yaralı bir kurt öfkesi taşırım

Üşüme

Al, gözlerimdeki ateşten

Susma,

Uçurumlar kapanmasın üstüme

Alacakaranlıktan geceye akan

Düşlere sığmayan türküler gibi

Kuytu köşelerde cânım muhabbet

Anlatıver bir firari öyküsü

Bir başla

Bir başla hele

Gelir gerisi

Umutlanmasın kahpe tuzakları

Kör karanlıklar

Umutlanmasın yüzünde burkulan keder

Yeminim olsun

Gülüşlerinin üstüne düşecek

Pasifik mavisi günler

 İdris Köylü (Birdost)', 'Ay olurum gecelere Tütün dalına düşerim Gün olurum zemheride Gülün al''ına düşerim Gül dalında güzeldir Gün ufuklarda Can teninde güzeldir Bı...', ARRAY['Türk Edebiyatı','Şiir','İdris Köylü (Birdost)']::text[], 8.5, '{"poet":"İdris Köylü (Birdost)","poet_slug":"i-dris-koylu-birdost","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/buluta-cizelen-resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Düşünme', 'hic-dusunme-mehmet-denek-hy8ib', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hiç düşünme uykularını bölme o acımazıs dikenli saatlerde

sanmaki bu acımazıs hasret dolu satlerin bitecegini

bu sevginin kurulu düzenini ne sen boza bilirsin nede ben

ama sen bilemezsin sevginin göbek adını...

bilirmisin sen acıların gömüldügü sevgi yüregini!

aldırma bukurulu düzene sakın düşme acımasız sevginin düşman saatlerine...

çünkü ben yanındayken tek düşman arıyorum sende o da geçip giden kahpe zaman

hayatımın agırlıgını hissediyorum artık ömrümüzden çalıyor

elimi elinden alıyor,napabilirsin söyle!bu düzen kurulu düzen

hadi kalk git bir gün daha geçti şiir misali.....', 'hiç düşünme uykularını bölme o acımazıs dikenli saatlerde sanmaki bu acımazıs hasret dolu satlerin bitecegini bu sevginin kurulu düzenini ne...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Denek']::text[], 8.5, '{"poet":"Mehmet Denek","poet_slug":"mehmet-denek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hic-dusunme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Buldum', 'kendimi-buldum-alperen-karadag-v0k5y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine kağıt kalemle buluştum aylar sonra

Ama bu sefer yanılmayacağım,

Deliler gibi sevilip, sevdiğim bir yürek için...

Satırlarımı, düşüncelerimi sıralıyorum ard arda...

O benim öğretmenim,sınavım,ödevim, 

Vazgeçilemezliğim,yarınım ümidim her şeyim...

Seni tam bulmuşken; 

Kaybetme korkusu içimi kemiriyor

Paramparça oluyor yüreğim.

Gecelerim zindan,düşlerim kabus oluveriyor birdenbire...

Bir gün gelip de seni kaybedeceğim, 

Beni sevmeyeceğin,beni unutacağın korkusu yüzünden...

Ölüyorum bir an

Karamsarlığım dağlıyor bedenimi....

''Seni Seviyorum'' diyerek devam ediyorum şiirime 

Bunu laf olsun diye değil!

Seni gerçekten sevdiğim için söylüyorum 

Ağzımdan öylesine değil!

Yüreğimden,içimden gelerek söylüyorum 

Şimdi, her zaman, ölene dek....

Çünkü seni gerçekten  seviyorum...

Benim vazgeçilmezliğimsin  artık...

Güne başlangıcım,hayatımın anlamı, 

Neşe kaynağım,tutunacağım tek dalımsın.

Seni sevdi şu gönlüm,

Seni gördü şu gözlerim.

Bundan sonrada sen beni unutuncaya kadar 

Gnlüm seni sevecek, 

Gözlerim ise seni arayacak her baktığı yerde... 

Ve sen benden vazgeçtiğin gün,

Senin için atan bu kalp duracak bir daha atmamacasına...

Seni arayan bu gözlerim kapanacak bir daha açılmamacasına...

Çünkü ben o gün ölmüş olacağım!!', 'Yine kağıt kalemle buluştum aylar sonra Ama bu sefer yanılmayacağım, Deliler gibi sevilip, sevdiğim bir yürek için... Satırlarımı, düşüncele...', ARRAY['Türk Edebiyatı','Şiir','Alperen Karadağ']::text[], 8.5, '{"poet":"Alperen Karadağ","poet_slug":"alperen-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kendimi-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haretine Yandığım Gece', 'haretine-yandigim-gece-alperen-karadag-vhfd9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi karanlıklarda yüreğim.

Fırtına öncesi sessizliklerde...

İçimde, bir fırtına koptu kopacak.

İklimler bile birbirine girdi bu gece...

Yağmur muydu bu yağan yaz geceleri gibi sıcak ellerime,

Yoksa göz yaşlarım mı sığmıyor içimdeki sevgi sellerine...

Üç bilinmeyenli denklemler gibi karmakarışık düşüncelerin içinde,

Lodos rüzgarlarına kapılmış bir uçurtma misali sürüklüyorum...

Bir ülkeden, hiç bilmediğim bir başka ülkeye...

Gecemidir beni bu hale getiren,

Duyguların çalkantısına,

Anlamsızlıkları tam ortasına

Bir buruşmuş kağıt gibi savuran....

Yoka ben miyim bu hale gelmek için

Geceye hasret kalan....

Benim saatlerim bu saatler

Gecenin üç beşleri , ayın denize indiği o büyülü saatler...

Ruhumu azat ettiğim,

Kelimelerin ahengiyle, büyüsüyle raks ettiğim,

Hiçbir şeye değişmeyeceğim,

Benim olan, yalnızlığıma eşlik eden saatler...!

Sevdiğime yakınlığım bu zamanlar artar.

Hislerim içime sığmayıp

Kağıda bu zamanlar akar

Mısralar sıralandıkça ardarda...

Benliğimi, sensizliğin girdabı yutar.

Derinlere vardıkça içim yanar,ormanlar yanar,

Yokluğuna ağlamaktan gözlerim yanar...

Az kaldı yarim sana kavuşmaya...

Asker gibi yüzüm şafaklarda,

Bir çizik daha atıyorum adını yazdığım duvara,

Bekle yarim beni

Az kaldı sana kavuşmama....!', 'Şimdi karanlıklarda yüreğim. Fırtına öncesi sessizliklerde... İçimde, bir fırtına koptu kopacak. İklimler bile birbirine girdi bu gece... Ya...', ARRAY['Türk Edebiyatı','Şiir','Alperen Karadağ']::text[], 8.5, '{"poet":"Alperen Karadağ","poet_slug":"alperen-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/haretine-yandigim-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendin Ettin Be Güzelim', 'kendin-ettin-be-guzelim-dragon-goksen-tbxjg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen benim vazgeçilmezindin

Ne zaman ki beni yalnız bıraktın

Güvendiğin insanlardı seni benden ayıranlar

Kendin ettin be güzelim 

Hem kendini hem beni yaktın

Güvendiğin küçük tepecikler 

Şimdi yanında 

Ben ise yüksek dağların zirvesinde

Artık istesende ulaşamazsın bana

Sen ancak küçük tepelere çıkabilirsin

Dağları aşamazsın!!!', 'Sen benim vazgeçilmezindin Ne zaman ki beni yalnız bıraktın Güvendiğin insanlardı seni benden ayıranlar Kendin ettin be güzelim  Hem kendini...', ARRAY['Türk Edebiyatı','Şiir','Dragon Gökşen']::text[], 8.5, '{"poet":"Dragon Gökşen","poet_slug":"dragon-goksen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kendin-ettin-be-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Alıştım', 'sensizlige-alistim-dragon-goksen-w190b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi nerdesin 

Hani hep yanımda olucaktın 

Hani beni yalnız bırakmıyacaktın

Nerdesin gün ışığım

Hayat kaynağım

Hani hep benim kalıcaktın

Yalnızım artık 

Sigara dumanım ve boş içki şişelerimle

Yalnızım anla artık beni

Sök kalbinden...

Yalnız bırak beni git!!

Sana hayat boyu mutlukluklar...', 'Şimdi nerdesin  Hani hep yanımda olucaktın  Hani beni yalnız bırakmıyacaktın Nerdesin gün ışığım Hayat kaynağım Hani hep benim kalıcaktın Ya...', ARRAY['Türk Edebiyatı','Şiir','Dragon Gökşen']::text[], 8.5, '{"poet":"Dragon Gökşen","poet_slug":"dragon-goksen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlige-alistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Moskova''lı İşçilerin 27 Nisan 1935''te Büyük Metroya Sahip Oluşları', 'moskova-li-i-scilerin-27-nisan-1935-te-buyuk-metroya-sahip-oluslari-bertolt-brecht-bomwb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duyduk ki: Seksen bin işçi 

yapmış metroyu, birçoğu günlük işlerinden sonra, 

çoğunlukla geceleri sabahlara dek. 

O yıl boyunca hep delikanlıların ve kızların güle oynaya 

tünellerden çıktıkları görülürmüş 

harca batmış ter içindeki iş giysilerini göstererek gururla. 

Aşılmış bütün engeller- 

yeraltı suları, çok katlı yapıların basıncı, 

dayanıksız büyük toprak yığınları-. 

Süslemek için kaçınılmamış hiçbir çabadan, 

en iyi mermer getirilmiş uzaklardan, en güzel ağaçlar 

işlenmiş özene bezene. 

Güzelim vagonlar adeta çıt çıkarmadan 

kaymaya başlamışlar 

gün gibi aydınlık tünellerde: 

Titiz müşteriler için her şeyin en iyisi. 

Şimdi, demiryolu en üstün planlara uyularak yapıldıktan 

                                                                                        sonra 

sahipleri geldi onu görmeye ve binmeye. 

O insanlardı onlar, onu yapanlardı. 

Binlercesi oradaydı, dolaşıyorlar 

ve inceliyorlardı dev istasyonları. 

Trenlerle büyük kalabalıklar geçiyordu bu ara, 

yüzleri istasyonlara dönük- 

erkekler, kadınlar, çocuklar ve kır sakallılar- 

sevinçten pırıl pırıldı yüzleri, tiyatrodaymışlar gibi, 

çünkü farklı yapılmıştı istasyonların hepsi, 

hepsi başka taştan, başka biçimde; 

ışık da her seferinde geliyordu başka kaynaktan. 

Sevinçli bir itiş kakışla arkaya itiliyordu her trene binen, 

çünkü istasyonlar en iyi 

görülebiliyordu önceki yerlerden. 

Çocuklar yukarı kaldırılıyordu her istasyonda. 

Yolcular her fırsatta dışarı taşıp 

sevinçli bir titizlikle inceliyorlardı bitirilen işi, 

sütunları elliyorlar ve parlaklıklarına bakıyorlardı, 

ayak burunlarını sürtüyorlardı taş döşemeye 

anlamak için taşların düzgünce yerlerine oturup 

                                                                           oturmadığını 

Sonra vagonlara doluşup yeniden 

duvar kaplamalarını inceleyip parmaklarını sürüyorlardı 

                                                                                  camlara. 

Erkekler ve kadınlar işaret ediyorlardı durmadan- 

doğru olup olmadığında biraz duraksayarak- 

çalıştıkları yerleri: 

Ellerinin izini taşıyordu taşlar. 

Her yüz görülebiliyordu açıkça, 

çünkü çok ışık vardı, 

lamba çoktu, gördüğüm herhangi bir demiryolundan 

                                                                        çok daha fazla. 

Tüneller de apaydınlıktı, 

karanlıkta kalmamıştı emeğin bir karışı bile. 

Ve tek bir yıl içinde yapılmıştı tüm bunlar, 

ve dünyada başka hiçbir demiryolu yapımında 

bu kadar çok işçi çalışmamıştı. 

Ve dünyada başka hiçbir demiryolunun bu kadar çok 

                                                                     sahibi olmamıştı 

Çünkü bu yapı harikası, bunca kentte bunca zamandır 

kendinden önceki hiçbir yapının görmediği şeyi gördü: 

Yapının işçileriydi yapının sahipleri. 

Emeğin tüm meyvalarının emek dökenlere düştüğü 

nerede görülmüştü? 

Bir yapıdan, onu yapanların kovulmadıkları 

nerede görülmüştü? 

Onları vagonlarımıza giderken gördüğümüzde, 

kendi eserleri olan vagonlarda, 

hemen anımsadık: 

Klasik yazarların bir vakitler hop oturup hop kalkarak 

önceden gördükleri o büyük tablo buydu.', 'Duyduk ki: Seksen bin işçi  yapmış metroyu, birçoğu günlük işlerinden sonra,  çoğunlukla geceleri sabahlara dek.  O yıl boyunca hep delikanl...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/moskova-li-iscilerin-27-nisan-1935-te-buyuk-metroya-sahip-oluslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerinde Olmak', 'duslerinde-olmak-mehmet-sariyar-vkil5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Var mı böyle sormayın,

Kalmışım dağlardan bir dağ başında,

Yangın, 

Yağmur her yanım,

Çiğdem çiçek kokar düşlerim.

Düşlerinde olmak zor gelir bana,

Bir türkü düşer aklıma,

Ölümüm düşer zor gelir:

''Mezarımı kazın yolun üstüne,

Yar gelip geçtikçe belki bana can gelir''

(12.12.1998)', 'Var mı böyle sormayın, Kalmışım dağlardan bir dağ başında, Yangın,  Yağmur her yanım, Çiğdem çiçek kokar düşlerim. Düşlerinde olmak zor geli...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarıyar']::text[], 8.5, '{"poet":"Mehmet Sarıyar","poet_slug":"mehmet-sariyar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/duslerinde-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-cagri-oluc-hyduz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Denizin tam ortasında demir atıp,

Sevgilimle mavi denize ve mavi gökyüzüne karşı;

Kadeh kaldırıp haykırmak istiyorum.

Denizin tam ortasında demir atıp,

Sevgilimle mavi denize ve mavi gökyüzüne karşı

Dans edip kollarımı açmak istiyorum.', 'Denizin tam ortasında demir atıp, Sevgilimle mavi denize ve mavi gökyüzüne karşı; Kadeh kaldırıp haykırmak istiyorum. Denizin tam ortasında ...', ARRAY['Türk Edebiyatı','Şiir','Çağrı Oluç']::text[], 8.5, '{"poet":"Çağrı Oluç","poet_slug":"cagri-oluc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/deniz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-cagri-oluc-jt885', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle bir sevgilim olsun ki

Öldüğüm vakit o da benimle ölsün

İnansın ki birlikteliğimiz sonuna kadar...', 'Öyle bir sevgilim olsun ki Öldüğüm vakit o da benimle ölsün İnansın ki birlikteliğimiz sonuna kadar......', ARRAY['Türk Edebiyatı','Şiir','Çağrı Oluç']::text[], 8.5, '{"poet":"Çağrı Oluç","poet_slug":"cagri-oluc","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sevgilim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-cagri-oluc-hnjjw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar çok seviyorum seni biliyor musun?

Keşke sana sarılabilseydim...', 'Ne kadar çok seviyorum seni biliyor musun? Keşke sana sarılabilseydim......', ARRAY['Türk Edebiyatı','Şiir','Çağrı Oluç']::text[], 8.5, '{"poet":"Çağrı Oluç","poet_slug":"cagri-oluc","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/keske-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-behiye-koksel-mhj80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen masallardaki dev, 

Kaf dağlarında.

Ben sırma saçlı peri kızı,

Göl kenarında...

Hani bin yılda bir karşılaşır ya insanlar,

Masallarda...

Biz de öyle karşılaşmışız,

Mavi bir akşamda...

Arzular yıldız yıldızmış ellerimizde...

Bin yıl geçmiş aradan,

Unutmamışız...

Ben masallardaki peri kızı,

Sevdalar taşırım sonsuzluklar kadar

Uyuturum arzularımı gecenin kollarında...

Yok, beyaz atlı şehzade değil,

Kınalı kuzunun çobanı da değil,

O yalnız deve sevdalanmışım,

Kaf dağlarında...

Dokunmak ne mümkün, ulaşmak hayal,

Ya fırtına, tufan, ya maça kızı,

Bir esmer cadı keser yolları,

-Belki de sadece kader...-

Gönlüm bel bağlar uzayan yollara,

Bekler de bekler,

Anka kuşundan haber...

Masallarda her şeye gücü yeter insanların,

Kötülere bile,

Belki bir gün bir yerde yeniden karşılaşırız

Binyıl, onbinyıl sonra belki,

Tersine çeviririz dünyayı...

Belki bir gün bir yerde yeniden yaşarız,

Evvel zaman içinde yaşanmış rüyayı...

Hani masallar da hayat gibi, tesadüftür ya,

Binlerce yıllık hasretimi anlarsın,

Anlarsın bir dokunsan alnımın sıcaklığından ,

Kara sevdayı...

Belki hiç tatmadın,

Masallarda bir kere yaşanır sevda,

Sen daha iyisini bilirsin ya,

Devler de bir kere yaşar,

Peri kızları da...

Ben masallardaki peri kızı,

Bir kere yaşamak istiyorum,

Seninle ilk ve son kere,

Eline düşmüşüm de yılların,

Belki de binlerce yıl sonrasını bekliyorum,

Alnımda sıcaklığı kara sevdanın...', 'Sen masallardaki dev,  Kaf dağlarında. Ben sırma saçlı peri kızı, Göl kenarında... Hani bin yılda bir karşılaşır ya insanlar, Masallarda... ...', ARRAY['Türk Edebiyatı','Şiir','Behiye Köksel']::text[], 8.5, '{"poet":"Behiye Köksel","poet_slug":"behiye-koksel","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/masal-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '27', '27-baris-karabel-mftcw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamın verdikleri,

Aldıklarından daha az.

Tatminsizliğimin sorgulandığı

Beyin odacıklarım,

Artık birer birer susmaya başladılar.

Bıktım biliyor musun?

Sensizlikten, seninle olmaktan

Maviden, yeşilden...

Bedenime hükmeden kalbim

Atışlarını yavaşlatmakta 

Gecikmedi

Yaşımın 27 olmasına bakmadan

Mahpus etti bacaklarımı

Hastane koridorlarına...

İstemiyorum yaşamı,

Hak etmiyorum yaşamayı,

Kabullenemiyorum nefes almayı.

Lanet olsun...

Sende yalan, 

Bu kocaman dünyada...', 'Yaşamın verdikleri, Aldıklarından daha az. Tatminsizliğimin sorgulandığı Beyin odacıklarım, Artık birer birer susmaya başladılar. Bıktım bil...', ARRAY['Türk Edebiyatı','Şiir','Barış Karabel']::text[], 8.5, '{"poet":"Barış Karabel","poet_slug":"baris-karabel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-baris-karabel-mdod0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat ne acı...

Bu gün gittiğim yol

Bir başka oldu gözümde.

Anamın gözüne bakamaz oldum

Söyleyemedim ölecekmişim diye

Zor olanın bunu dinlemesi mi? 

Yoksa gittiğim doktorun 

Demesi mi? Anlayamadım.

Yaşayacağım gün olmasını,

Seni görebileceğim saat olmasını,

Dokunabileceğim an olmasını 

Nasıl istiyorum biliyor musun? 

Kaldırıyorum telefonu

Başlıyorum çevirmeye 241.....

3 haneli o kahrolası numarayı 

Çevirdikten  sonra

Felç oluyor gönlüm

Olmuyor be...

Bu sefer gerçekten gidiyorum kuzum

Ama sen...

Sen gene yoksun...

Lanet olsun...

Sende yalan, 

Bu kocaman dünyada...', 'Hayat ne acı... Bu gün gittiğim yol Bir başka oldu gözümde. Anamın gözüne bakamaz oldum Söyleyemedim ölecekmişim diye Zor olanın bunu dinlem...', ARRAY['Türk Edebiyatı','Şiir','Barış Karabel']::text[], 8.5, '{"poet":"Barış Karabel","poet_slug":"baris-karabel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidiyorum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecv-i Sema', 'ecv-i-sema-baris-karabel-9l8da', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutulmak istiyorum

Nefesimin tükendiği anı,

Yalnız yaşamak istiyorum

Allah’a yalvarmak, 

Sitem etmek istiyorum.

Keşke seni görmeden alsaydı

Beni yanında...

Ama hayır!

İyi oldu be. Boş ver...

İyi ki seni almadı benden önce 

Dayanamazdım... 

Lanet olsun...

Sende yalan, 

Bu kocaman dünyada...', 'Unutulmak istiyorum Nefesimin tükendiği anı, Yalnız yaşamak istiyorum Allah’a yalvarmak,  Sitem etmek istiyorum. Keşke seni görmeden alsaydı...', ARRAY['Türk Edebiyatı','Şiir','Barış Karabel']::text[], 8.5, '{"poet":"Barış Karabel","poet_slug":"baris-karabel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ecv-i-sema-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
