INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sergi Sarayı*', 'sergi-sarayi-bayram-tunca-f5ss3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz insanlar, öyle bir sergi sarayındayız ki

Saraydaki tablolar öyle bir güzellikteler ki

Tablodaki renk, motif ve figürler ayrı bir güzellikte

En iyi ressamlar dahi onun güzelliğine hayranlıkta

Hem her ressam,  bu saraydan ilham almıyor mu ki

Aldıkları halde, onların aynılarını yapabiliyorlar mı ki

Saraydaki tabloları seyretmek o kadar doyumsuz ki

Yıllarca seyredenler dahi, doyup da mı gidiyorlar  ki

Tablolar, her an film şeridi gibi değiştirilmiyorlar mı

Bir gündeki olan değişikliği sayalım desek sayılır mı 

Bir yıldaki değişikliğini sayalım desek, güç yeter mi

Değişiklikteki gizemi yazalım desek kalem yeter mi

Saray tablolarının gizemine, kimler hayran olmadı ki

Onun o eşsiz gizemini kimler anlatmaya çalışmadı ki

Nebiler, veliler, şairler, ozanlar, âşıklar...daha kimler

O kadar anlatana rağmen, yine bazıları anlamıyorlar

Bazı basiretsiz seyirciler, göremiyor hakiki ressamı

Halbuki, her bir tablo, çok iyi anlatmakta O ressamı

Bakıyor kimileri bu saraya öküzün trene baktığı gibi

Belki de basiretsizliklerinden, göremiyorlar ressamı

Şair bu hususta muzdarip, ondandır feryad ü figanı

Ey âdemoğlu, gafil olma, bu sarayın ressamını tanı

Nasıl ki her bir tablo bir  ressamın varlığını gösteriyor

Aynen öyle de bu sergi sarayı da o ressamı gösteriyor

Saraya temaşa ederken, mutlaka ressamı görmelisin

Yoksa, ne sarayın, ne de hayatın  hiç olur mu anlamı

Ey Âdemoğlu, sen de bakarlar gibi olma gör ressamı

İyi bak ki iyi göresin, iyi gör ki hayattan lezzet alasın

Zaten gaye-i hayat, bu sarayın ressamını tanımaktır

Gerisi senin benim ve her fani gibi hepsi de yalandır

Tabloları görüp de ressamı görmezsen hayat ziyandır

O tablolar, her an gördüklerimiz, saraysa, bu cihandır

Sarayda görülen her bir tablonun sayısız gizemleri var

Anlatmaya da, ne kalem, ne kelam, ne de ömür yeter

Çünkü her bir tabloda sayısız renk, sayısız figüran, var

Elbette ki bu kadar harika tabloların bir de ressamı var

15.04.2001-15.50', 'Biz insanlar, öyle bir sergi sarayındayız ki Saraydaki tablolar öyle bir güzellikteler ki Tablodaki renk, motif ve figürler ayrı bir güzelli...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sergi-sarayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ateşi-1-', 'ask-atesi-1-bayram-tunca-448ol', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tabipler geldiler yani başıma

Şöyle bir baktılar kalp atışıma

Birisi buz gibi elini koydu alnıma

Öbürü dereceği koydu koynuma

Yine de bilemediler niye yandığıma

Birisi adımı, diğeri de sordu yaşımı

Kalıp kalıp buz koydurdular başıma

Yine de düşüremediler kalp atışımı

Tabip de anlayamadı derdimi bana sordu

Diyemedim düşmandan çok dostlar yordu

Yine diyemedim dostlarımdan çok o yordu

Düşmandan çok dost, dosttan çok o yordu

Ah ah bilmem ki annem beni niye doğurdu

Acep hamurumu çileyle/kahırla mı yoğurdu

İhtimal beni bin bir türlü zorluklarla doğurdu

Şair bu aşka bunca çile değer mi diye sordu

Doldu artık doldu, Bayram''ın ahir ömrü doldu

Şair Bayram aşk çilesiyle saçını sakalını yoldu

Şu hayat, onun için dikenli mi dikenli bir yoldu

Şair bu aşka bu kadar çile değer mi diye sordu

B. TUNCA/20.04.2001-18.30', 'Tabipler geldiler yani başıma Şöyle bir baktılar kalp atışıma Birisi buz gibi elini koydu alnıma Öbürü dereceği koydu koynuma Yine de bileme...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-atesi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Şiir Aşkı+', 'sairin-siir-aski-bayram-tunca-6rprp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her ana çocuğunu nasıl tanırsa

Her peder evladını nasıl tanırsa

Her canlı yavrusunu nasıl tanırsa

Ben de şiirimi tanırım aynen öyle

Tüm şiirler harman edilse yine tanırım

Hatta, heceleri karıştırılsa yine tanırım

Terkipleri değiştirilse, yine de anlarım

Hatta, ters düz edilse, yine de tanırım

Çünkü, onların her biri ayrı birer öyküm

Çünkü, onların her birisi dilimde türküm

Şiirlerimin hecelerini belleğimde süzdüm

Kendimde özümleyip sonra size sundum

Şiir yazmadığımda suyu kesilene benzerim

Bahardaki nutku tutulan bülbüle benzerim

Paylaşmazsam hislerimi, hayattan bezerim

Ogün bugündür aşk ağırlıklı şiirler yazarım

Şiir yazmadığım zaman vasiyetimi yazarım

Kendi mezarımı da kendi ellerimle kazarım

Şiir yazarken Ferhat gibi baş rolde oynarım

Çünkü ben bir günde dört mevsim yaşarım

25.04.2001-11:35

Aşk Ateşten Gömlek', 'Her ana çocuğunu nasıl tanırsa Her peder evladını nasıl tanırsa Her canlı yavrusunu nasıl tanırsa Ben de şiirimi tanırım aynen öyle Tüm şiir...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sairin-siir-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopya Çekme', 'kopya-cekme-bayram-tunca-h6vuw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belki okul da kopya çekmeyi öğrenmişsin

Ama şiirde kopya çekmeyi öğrenmemişsin

Eğer, seni şairler divanına versem asarlar

Sehpada asmasalar da bil ki tefe basarlar

Dikkat et, aldığın o şiir kalbini yakmasın

Görenler sana bir mecnun gibi bakmasın

Onun kelimeleri âşk olup, içine akmasın

O şiirim beni çok yaktı, seni de yakmasın

B. TUNCA/25.04.2001-11.35', 'Belki okul da kopya çekmeyi öğrenmişsin Ama şiirde kopya çekmeyi öğrenmemişsin Eğer, seni şairler divanına versem asarlar Sehpada asmasalar ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kopya-cekme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-arif-nihat-asya-h70a9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çekmece''den Maltepe''den ileri

Gitmemiş Sâdâbâd çelebileri

Alem tepesine Alemdağ derler...

Böyle bilmiş böyle yazmış eserler.

Dağlar var karanlık, dağlar var beyaz.

Korka korka eteğinden öper yaz;

Ağrıdağ, Babadağ, Gâvurdağ, Ilgaz

Kubbelerdir...dolaşır, aşılmaz.

Tendürük''te, Kop''ta Palandöken''de

Kurtların payı var gelip geçende...

Ki alırlar vermek istemesen de!

Dağlar var, tahtından inmeyen sultan

Dağlar var, yapılmış bundan, buluttan...

Dağlar var ki Bingöl, Binboğa, Süphan,

Medetsiz''ler, Mor''lar, Nur''lar, Yıldız''lar;

Karalar, Kızıllar, Bozlar, yağızlar...

Karla dolar ''İmdat'' diyen ağızlar;

Yollar kesen, haraç alan dağlar var.

Bolkarda çamların sakızı damlar...

Ve bir yıldız düşer, tutuşur çamlar...

Bir kızıl şehrâyin olur akşamlar...

Tacı olan, tahtı olan dağlar var.

Tüter Sarıçiçek, burcu burcudur, 

Akşamlar ya mor, ya turuncudur.

Ve kışın dünyanın öbür ucudur...

Sarkarken Cudinin karları dal dal

Bağdaş kuradursun yollara Karhal!

''Ferman padişahın, dağlar bizimdir;''

Dedi yerde bir kurt, gökte bir kartal.

Dönmez misiniz ey yolda kalanlar;

Yolcular, garipler, garip çobanlar;

Allahüekberde tekbir alanlar?

Ovalar, konaklar, yollar aşırı

Birbirini selamlayan dağlar var.

Dağlar var, batının yangınında kor...

Dağlar var; adları Nemrut, Balahor...

Kayışdağ kim, alemdağ kim oluyor?

Lakin ufukları görünce yoksul

Dağ yerine kubbe yapmış İstanbul;

Kurşun şamdanlarda mumlar fildişi...

Ki pırıltıları sularda pul pul.', 'Çekmece''den Maltepe''den ileri Gitmemiş Sâdâbâd çelebileri Alem tepesine Alemdağ derler... Böyle bilmiş böyle yazmış eserler. Dağlar var kara...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/daglar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-tevfik-mengulluoglu-9z7wq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana bunları yanı başına yazacağımı söylememiştim

Küçüğüm.Sensiz bahçenin bir köşesinde, bıraktığın gibi

kalacak karanfiller, her baharın Nisanında, 

gözyaşlarımızla sulayacağız.

Daha bir yeşerecek umutlar küçüğüm.

Bağrındaki ateş donmuş usları eritmeliydi, 

yüreğindeki çoşku sel olup taşmalıydı, sen yatarken

bir tek o ateş saçan gözlerine bakamadım, bakışlarım

titrer oldu.Sen ölmedin hiçbir zaman, şimdi daha bir varsın

Küçüğüm, seni yaşadıkça daha bir yaşatacağız.', 'Sana bunları yanı başına yazacağımı söylememiştim Küçüğüm.Sensiz bahçenin bir köşesinde, bıraktığın gibi kalacak karanfiller, her baharın Ni...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kucugum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırma Saçlı', 'sirma-sacli-tevfik-mengulluoglu-ockpf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sırma saçlı bir güzel geşecekmiş

saçı entarisine uzanmış.

Türkülerle geliyor sesi, bilmem kaçmil öteden

sırma saçlı bir güzel gelecekmiş.

Taç yapmış alnına karanfillerden, 

buram buram kokarmış, 

Karlar kıtırdıyor ayaklarının altında

sesi geliyor bilmem kaçmil öteden.

Sevgi yutarmış, türkü kokarmış

bir yudum sevgi kusmak için

sırma saçlı bir güzel gelecekmiş

Dağları tepeleri aşarak varacakmış, 

güneş yumarken gözlerini sıra sıra dağlara

varıp türküler söyleyecekmiş, sırma saçlı bir güzel.', 'Sırma saçlı bir güzel geşecekmiş saçı entarisine uzanmış. Türkülerle geliyor sesi, bilmem kaçmil öteden sırma saçlı bir güzel gelecekmiş. Ta...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sirma-sacli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık olsa', 'ayrilik-olsa-fuat-colakoglu-p4aip', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sanki bu ayrılığı ben istemişim gibi her derdi çileyi Yüklemişsin sırtıma birde utanmadan herkese gidip ben onu Sevmedim demişsin A kızım sevmedin neden oynadın Benimle bu iş burda bitmez bunu aklına sok unutma seni başkasınla görürsem allahtan çok benden kork 

Ayrılıklarla bezenmiş şu şerefsiz dünyada 

Sende şerefsiz çıkıp acımadan vurdun bana 

Hakaret etmek istiyorum ama sende utanacak yüz yok ki

Söyliyeceğim son bir söz var Yazıklar olsun sana 

Yazıklar olsun sana.', 'Sanki bu ayrılığı ben istemişim gibi her derdi çileyi Yüklemişsin sırtıma birde utanmadan herkese gidip ben onu Sevmedim demişsin A kızım se...', ARRAY['Türk Edebiyatı','Şiir','Fuat Çolakoğlu']::text[], 8.5, '{"poet":"Fuat Çolakoğlu","poet_slug":"fuat-colakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayrilik-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Öykülere', 'yeni-oykulere-tayfun-yahsi-r0twl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdiğimin dingin bir ruhu vardı

Gözü, gönlü, benzersiz sevgisi

Ve ensesinde, belirgin bir beni,

Derinlerden gelen bir sesi vardı sevdiğimin, 

Sezgisi ve incecik bir beli 

Belirsizdi kaç tabutu taşıdığı yüreği,

Şairdi sevdiğim, kelimeleri vardı

Ağzından bir alev topu halinde çıkardı.

Sevdiğim dün öldü. 

Yarın başkasında yaşayacak

Belki bir başka öykü.', 'Sevdiğimin dingin bir ruhu vardı Gözü, gönlü, benzersiz sevgisi Ve ensesinde, belirgin bir beni, Derinlerden gelen bir sesi vardı sevdiğimin...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Yahşi']::text[], 8.5, '{"poet":"Tayfun Yahşi","poet_slug":"tayfun-yahsi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yeni-oykulere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebep Neydi', 'sebep-neydi-fuat-colakoglu-suqww', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İhtiyacım var sana

Ne olur anlasana 

Sen benim tek aşkımsın 

Benden ayrılmasana

Gülüm ben sensizim 

Yüzüne hasretim 

Ayrılma ne olur 

Sensiz kimsesizim 

Aldığım nefestesin 

Her zaman kalbimdesin

Senden asla vazgeçmem 

Dünya ahiret benimsin', 'İhtiyacım var sana Ne olur anlasana  Sen benim tek aşkımsın  Benden ayrılmasana Gülüm ben sensizim  Yüzüne hasretim  Ayrılma ne olur  Sensiz...', ARRAY['Türk Edebiyatı','Şiir','Fuat Çolakoğlu']::text[], 8.5, '{"poet":"Fuat Çolakoğlu","poet_slug":"fuat-colakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sebep-neydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygusalım*', 'duygusalim-bayram-tunca-zt38w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah kestane gözlü, şeftali yanaklı, sevdalım

Aşkından çıra gibi cayır cayır yanmaktayım

O günden beri sana karşı çook duygusalım

Bilmem ki, ne olacak benim bu garip halim

Bunun en güzel ispatı, lisan-ı halim tanıktır

Eğer çile çeken bensem, çektiren o sanıktır

Kalem yazmıyor dil söylemiyor içim yanıktır

Eğer inanmıyorsanız melekler en iyi tanıktır

Yüreğimdeki duygularım, dağı taşı çınlatıyor

Bilmem ki onun kulağını da çınlatıyor mudur

İçime bıraktığı o aşk ateşi, bedenimi yakıyor

Acaba, aynı aşk ateşi onu da yakıyor mudur

Memleketimin rotası, memleketinden geçiyor

Tam memleketinden geçerken içim cız ediyor

Aşkından yüz soluyor, ten kendinden geçiyor

Bak, fazla bekletme, Bayram’ın ömrü geçiyor

25.04.2001-11.35', 'Ah kestane gözlü, şeftali yanaklı, sevdalım Aşkından çıra gibi cayır cayır yanmaktayım O günden beri sana karşı çook duygusalım Bilmem ki, n...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/duygusalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez mi', 'yetmez-mi-bayram-tunca-qgckl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günahkarsam çektirdiklerin yetmez mi

Burada çektiklerim günahıma yetmez mi

Allah affediyor, o sevdiğim affetmez mi

Bu kadar ömre bu kadar çile yetmez mi

B. TUNCA/22.09.2000-16.30', 'Günahkarsam çektirdiklerin yetmez mi Burada çektiklerim günahıma yetmez mi Allah affediyor, o sevdiğim affetmez mi Bu kadar ömre bu kadar çi...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yetmez-mi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilem Yetmez mi?', 'cilem-yetmez-mi-bayram-tunca-i99w3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günahkarsam Çektirdiklerin yetmez mi? 

Burada çektiklerim günahımı yetmez mi? 

Allah af ediyor, O sevdiğim af etmez mi? 

Bu kadar ömre bu kadar çile yetmez mi? 

22.09.2000-16.30', 'Günahkarsam Çektirdiklerin yetmez mi?  Burada çektiklerim günahımı yetmez mi?  Allah af ediyor, O sevdiğim af etmez mi?  Bu kadar ömre bu ka...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cilem-yetmez-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özelliğim', 'ozelligim-bayram-tunca-pnqt6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her bulduğum şeyi yiyemem

Her bulduğum şeyi giyemem

Her dostuma gerçek dosttum diyemem

Her gördüğüm güzele de yâr diyemem

Her zaman bulamayacağım şeyi yemem

Her zaman bulamayacağım şeyi giymem

Her zaman göremeyeceğim güzele bakamam

Her duyduğum dedikoduya, hiç kulak asmam

Faniyim fani olanı istemem

İsterim bir yâr-i baki isterim

Hiç ender hiçim, cenneti cemali beraber isterim

Yoksa, inler durur bastırılmaz içimdeki hislerim

B. TUNCA/20.09.2000-16.35', 'Her bulduğum şeyi yiyemem Her bulduğum şeyi giyemem Her dostuma gerçek dosttum diyemem Her gördüğüm güzele de yâr diyemem Her zaman bulamaya...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozelligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle-1-', 'seninle-1-bayram-tunca-ue6fk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seninle çocukluğumuz aynı

Yoksa gençliğimizde mi aynı olacak

Seninle gözlerimiz aynı

Yoksa, sözlerimizde mi aynı olacak

Seninle doğumumuz aynı

Yoksa, ölümümüzde mi aynı olacak

Seninle kaderimiz aynı

Yoksa, ahretimiz de mi aynı olacak

Olacak olacak her şeyimiz aynı olacak

Dünyamız da ahretimiz de aynı olacak

Sevenler dünya ve ahrette beraber olacak

Mutluluktan üveyikler gibi havada uçacak

B. TUNCA/20.04.2001-16.35', 'Seninle çocukluğumuz aynı Yoksa gençliğimizde mi aynı olacak Seninle gözlerimiz aynı Yoksa, sözlerimizde mi aynı olacak Seninle doğumumuz ay...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seninle-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Ademoğlu-2-*', 'ey-ademoglu-2-bayram-tunca-xsr2a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey âdem, hani seni seven dost çoktu

Baktım, kabirde yanında kimse yoktu

En sadık dostların geldiler kabre kadar

Dememişler miydi her şey kabre kadar

Ey insan, yalnız doğdun, yalnız öldün

Bak her şey yalanmış, sen de gördün

Sanki daha dün doğdun bugün öldün

İtiraf et, tarih tekerrür ediyor gördün

28.04.2001-16.35', 'Ey âdem, hani seni seven dost çoktu Baktım, kabirde yanında kimse yoktu En sadık dostların geldiler kabre kadar Dememişler miydi her şey kab...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ey-ademoglu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bir Bilsen', 'ah-bir-bilsen-bayram-tunca-f3i94', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah bir bilsen, kaç defa yutkundum

Ah bir bilsen, kaç kez dilimi ısırdım

Hep sabrettim o sözü söylememek için

Şeytan ile düşmanın sevinmemesi için

Ama, her insanın da bir dayanma gücü var

Elbette, benim de bir dayanma gücüm var

Sabrım taşarsa benim de bir tek sözüm var

Dikkat et, her insanın dost ve düşmanı var', 'Ah bir bilsen, kaç defa yutkundum Ah bir bilsen, kaç kez dilimi ısırdım Hep sabrettim o sözü söylememek için Şeytan ile düşmanın sevinmemesi...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ah-bir-bilsen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Gel Artık*', 'neredesin-gel-artik-bayram-tunca-q52o7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Defterin arasında, kurumuş bir yaprak buldum

Senin elin değmiştir diye, hep sakladım durdum

Senden kalan bir hatıra olarak koklayıp durdum

Gel artık gel, beklemekten yaprak gibi kurudum

30.04.2001-10.30', 'Defterin arasında, kurumuş bir yaprak buldum Senin elin değmiştir diye, hep sakladım durdum Senden kalan bir hatıra olarak koklayıp durdum G...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/neredesin-gel-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece-2-', 'bu-gece-2-bayram-tunca-c3ca9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece, yine seni rüyada gördüm

O ipeksi saçlarını ellerimle ördüm

Seni başkasından daha çok sevdim

Sevincimden sanki göklere değdim

İpek saçlarını, sazıma tel yapayım

Tatlı sözünü dilime türkü yapayım

Parmağını sazıma mızrap yapayım

Hasret ateşi yaktı ben ne yapayım

Gel artık, sen çal ben oynayayım

Gel artık sen çal ben söyleyeyim

Ya da sen söyle, ben dinleyeyim

Yoksa, bırak  da ney gibi inleyim

B. TUNCA/30.04.2001-10.30', 'Bu gece, yine seni rüyada gördüm O ipeksi saçlarını ellerimle ördüm Seni başkasından daha çok sevdim Sevincimden sanki göklere değdim İpek s...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-gece-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-taskin-sesli-ztatt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni seviyorum

birdaha söyle

seni seviyorum

birdaha

seni seviyorum 

birdaha 

seni seviyorum

ben seni sevgilim

bu şiirim tüm sevenlere', 'seni seviyorum birdaha söyle seni seviyorum birdaha seni seviyorum  birdaha  seni seviyorum ben seni sevgilim bu şiirim tüm sevenlere...', ARRAY['Türk Edebiyatı','Şiir','Taşkın Sesli']::text[], 8.5, '{"poet":"Taşkın Sesli","poet_slug":"taskin-sesli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-seviyorum-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bir Bilseniz*', 'ah-bir-bilseniz-bayram-tunca-eohku', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah bir bilseniz gül diye kaç kez dikene sarıldım

Darılacak kimse bulamadım, kaderime sarıldım

Ah bir bilseniz, üzüntüden kaç parçaya ayrıldım

Derdime çare yokmuş sonunda kefene sarıldım', 'Ah bir bilseniz gül diye kaç kez dikene sarıldım Darılacak kimse bulamadım, kaderime sarıldım Ah bir bilseniz, üzüntüden kaç parçaya ayrıldı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ah-bir-bilseniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-bayram-tunca-upmmz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dertlerimden, dertlerine hiç eğilemedim bir tanem

Çilemden, derdin nedir diye soramadım bir tanem

Bir gün olsun gönlünce eğlendiremedim bir tanem

Seni mesut edemedim, ne olur, beni afet bir tanem

B. TUNCA/07.05.2001-15.50', 'Dertlerimden, dertlerine hiç eğilemedim bir tanem Çilemden, derdin nedir diye soramadım bir tanem Bir gün olsun gönlünce eğlendiremedim bir ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-tanem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki Tektik-1-', 'sanki-tektik-1-bayram-tunca-hlqaa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kayada ötüyor iki keklik

Aşıkların içinde sanki tektik

İçimize sevgi tohumu ektik

Biz iki bedende tek yürektik

Pekmez tarlasına buğday ektik

Tarlada sanki keklik gibi sektik

Aşıkların içinde sanki biz tektik

Sanki şu dünyada ikimiz tektik

B. TUNCA/25.10.2000-16.37', 'Bir kayada ötüyor iki keklik Aşıkların içinde sanki tektik İçimize sevgi tohumu ektik Biz iki bedende tek yürektik Pekmez tarlasına buğday e...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sanki-tektik-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgâr-1-*', 'ruzg-r-1-bayram-tunca-rvks1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu rüzgâr en muazzam bir klima

Çalışınca ne güzel serinler dünya

Hayranım onu icat eden O ustaya

Kimse üretemedi, onun gibi klima

Estikçe rüzgâr, ağaç dalları raks eder

Kokusu harman olup, etrafa akseder

Sallanır dallar, öpüşür yeşil yapraklar

İlham alır şairler, imrenir ona âşıklar

Estikçe rüzgâr, sanki dilleniyor yapraklar

Bu orkestraya eşlik ediyor, bütün canlılar

Hz. Süleyman gibi anlayabilseydim dillerini

O zaman, verirdim tüm dünyalık servetimi

Bak, rüzgârla döllenip, çoğalmakta bitkiler

Elbette, bu güzellikler âdemoğlunu etkiler

Rüzgârla hareket eder, kar beyazı bulutlar

Onlarla oluşur, içimizdeki o güzel umutlar

Bak denizde köpük köpük dalgalar oluşuyor

Martılar semada, âşıklar kıyılarda buluşuyor

Canlıların da zikirlerinden mutluluk oluşuyor

Rüzgarlarla, bilinmez ne hikmetler oluşuyor

Esmese rüzgâr, eser miydi gönüllerde rüzgâr

Esmeseydi rüzgâr, dünyamız olurdu bize dar

Esmeseydi rüzgâr, yağar mıydı yağmurla/kar

Estikçe rüzgâr, yüreğimize mutluluklar dolar

Esmeseydi rüzgâr, hiç hareket olur muydu? 

Hareket olmayan yerde bereket olur muydu? 

Acaba o zaman da hayatın tadı olur muydu? 

Rüzgârla hava temizlenmese yaşanır mıydı? 

07.05.2001-15.50', 'Şu rüzgâr en muazzam bir klima Çalışınca ne güzel serinler dünya Hayranım onu icat eden O ustaya Kimse üretemedi, onun gibi klima Estikçe rü...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ruzgar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine de Anlatamadım*', 'yine-de-anlatamadim-bayram-tunca-1efa1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eller gibi yüzmesini beceremedim şu deryada

Derdime derman bulamadım, şu dâr-ı âlemde

Bir yar sevdim, ondan da bulmadım bir fayda

Duyulsa, yürek dayanmazdı, içimdeki feryada

Meramım için, deste deste kalemler tükettim

Kelimeleri art arda satıra dizip şiirler türettim

Avazım çıktığınca bağırarak gücümü tükettim

Ama yine de anlatamadım, ömrümü tükettim

07.05.2001-16.30', 'Eller gibi yüzmesini beceremedim şu deryada Derdime derman bulamadım, şu dâr-ı âlemde Bir yar sevdim, ondan da bulmadım bir fayda Duyulsa, y...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yine-de-anlatamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulursun*', 'bulursun-bayram-tunca-lrg5n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Defterimi açsan, her sayfada bir şiir  bulursun

Şiirimi okursan, her kelimede ikimizi bulursun

Şiirimi okursan, o günlerin öykülerini bulursun

Seni bu kadar seven bir âşığı nerede bulursun

07.05.2001-16.30', 'Defterimi açsan, her sayfada bir şiir  bulursun Şiirimi okursan, her kelimede ikimizi bulursun Şiirimi okursan, o günlerin öykülerini bulurs...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bulursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Dememişler miydi', 'hani-dememisler-miydi-bayram-tunca-pbbnc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dememişler miydi, ''her koyun kendi bacağından asılır''

İşte gördün, sen de neticede kendi kader ipinle asıldın

Şu fani dünyanın nesine güvenip de krallar gibi kasıldın

Bak her insan gibi sen de neticede kara toprağa basıldın

B.TUNCA/09.05.2001-16.30', 'Dememişler miydi, ''her koyun kendi bacağından asılır'' İşte gördün, sen de neticede kendi kader ipinle asıldın Şu fani dünyanın nesine güveni...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hani-dememisler-miydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylâ''yı Arıyorum*', 'leyl-yi-ariyorum-bayram-tunca-31h49', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah Leyla, katip arzun ben olayım

Arzu ve isteklerini bir bir sorayım

Arzu ve isteklerin için seferber olayım

Gerekirse uğrunda karınca gibi olayım

Yeryüzünde aradım, bulamadım Leyla''yı

Gökyüzünde aradım, bulamadım Leyla''yı

Gece ve gündüz çok yalvardım Mevla''ya

Ya Rab ne olur kavuştur beni o Leyla''ya

Çöllerde mecnun gibi arıyorum Leyla''yı

Dağlarda, Ferhat gibi arıyorum Leyla''yı

Arıyorum Leylâ’yı baktıkça ay’a, güneş’e

Geceleri yıldız misali kayıyorum Leyla''ya

Hani İstanbul, gönlünü martılara vermiş ya

Aynen,  ben de  kaptırdım kendimi Leyla''ya

Gündüzleri, güneş ışığıyla arıyorum Leyla''yı

Geceleri, dolun Ay ışığıyla arıyorum Leyla''yı

Yıllarca  ne çok yalvardım, Leyla için Mevla’ya

Yeryüzü dar geldi, feryadım çıktı ta arşı âlâya

Bilmem ki ne ettim, reva görüldüm bu cezaya

Belki de Mecnun bile dayanamazdı bu cezaya

Denizlerde arıyorum, Leyla''nın o gözlerini

Meltemlerde arıyorum, Leyla''nın kokusuni

Gökte ay’ın nurunda arıyorum, onun cemalini

Güneş’in şualarında arıyorum, onun sevgisini

Bilmem ki nerelerde bulurum onun kendisini

Eğer ki ta fizan’dan alsam Leyla''nın haberini

Kuş olup uçarak, karlı dağları aşarak giderim

Ulaşamasam da, karınca gibi yolunda ölürüm', 'Ah Leyla, katip arzun ben olayım Arzu ve isteklerini bir bir sorayım Arzu ve isteklerin için seferber olayım Gerekirse uğrunda karınca gibi ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/leyla-yi-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sevemezsin', 'sen-sevemezsin-cuneyt-talan-h0qm0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine başladı beynimi kemiren bu düşünceler 

Sen olamazdın sevgimin katili

Olamazdın buaşkın sahibi

Sevgiler,aşklar yakıyorum sizi biir kibrit alevi ile

Bir sevgi böylemi son bulacaktı

Bu kadar basitmiydi ki bir kibrit alevine teslim olacaktı

Yaktım bu sevgiyi ve benim sana olan hasretimi

Bıraktım küllerini gökyüzüne

Bulutlara karışıp yağmur olup yağsın üzerine

Sen sevgiden ne anlarsın

Sen ancak soğuk sevginin elleri ile kalbimi özlemlerimi parçalarsın

Yenilmedim yinede sana

Beni böyle yıkamazsın beni sen anlayamazsın

Ama ben seni iyi tanıdım

Seninle acıları buruk sevdaları yaşadım

Durma vur kalbime acıt ruhumu yık umutlarımı

Benden iyi anlayamazsın pişmanlığımın acısını

Sen bulut olsan yağamazsın

Bir son olsan bitemezsin

Hayattan ölüm kadar zevk alamazsın

Sen sevemezsin..........Sen sevemezsin', 'Yine başladı beynimi kemiren bu düşünceler  Sen olamazdın sevgimin katili Olamazdın buaşkın sahibi Sevgiler,aşklar yakıyorum sizi biir kibri...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Talan']::text[], 8.5, '{"poet":"Cüneyt Talan","poet_slug":"cuneyt-talan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-sevemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizkızı Masalı', 'denizkizi-masali-erol-onur-cehiv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşi getirebilirim sana

Ağlamışsın, ıslak dudakların güneşe muhtaç

İstersen rüzgarları taşırım kollarına

Karlar getiririm uzak dağlardan

Güneşli yağmurlar yağdırırım gökkuşağında

Öpmek istiyorum dudaklarının tuzundan 

Ve adını haykırmak istiyorum tüm evrene

Denizkızı

İstersen okyanusları sereyim ayağına

Buluttan elbiseler yaptırayım yıldızlı

Gökyüzünün mavisiyle aydınlatayım gözlerini

Gezegenlerden taç yapayım saçlarına

Denizkızı

Yeter ki, sen de beni sev

Çok aşksız kaldım denizkızı, çok ağladım

Yeter ki bir gülümse

Yeter ki sen de iste benimle olmayı

Seni Seveceğim Denizkızı

(11 Ekim 1994 10.46 Ankara)', 'Güneşi getirebilirim sana Ağlamışsın, ıslak dudakların güneşe muhtaç İstersen rüzgarları taşırım kollarına Karlar getiririm uzak dağlardan G...', ARRAY['Türk Edebiyatı','Şiir','Erol Onur']::text[], 8.5, '{"poet":"Erol Onur","poet_slug":"erol-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/denizkizi-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğu Yakalamak', 'mutlulugu-yakalamak-erol-onur-xjhus', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün değmeyin keyfime

Öylesine mutluyum ki anlatamam

Ne mi var mutlu olacak?

Düşünsene..

Bak ne güzel yanıyor şehrin ışıkları

Hava öldüresiye soğuk

Öldüresiye güzel...

Biliyor musun boğazım ağrıyor

Ne kadar da iyi şu hastalık

Yalnızım ne kadar güzel

Yalnızım ölesiye

Kimse hatrımı sormaz şimdi

Kimse saati sormaz

Kimse sana benzemez gülünce...

Nergis''deki eski evi hatırlıyorum

Arka pencereden treni seyretmek ne güzel

Terasa çıkmak çiçekleri koklamak

Kısacası yaşamak ne güzel.

(7 Kasım 1994 20.00 Ankara)', 'Bugün değmeyin keyfime Öylesine mutluyum ki anlatamam Ne mi var mutlu olacak? Düşünsene.. Bak ne güzel yanıyor şehrin ışıkları Hava öldüresi...', ARRAY['Türk Edebiyatı','Şiir','Erol Onur']::text[], 8.5, '{"poet":"Erol Onur","poet_slug":"erol-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mutlulugu-yakalamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-ferruh-turgut-i-nal-48xb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlamaya  mecalim  kalmadı  bu  gece

Düşündüklerim  geçiyordu  gözlerimden  hece hece

Takılıp  kaldım  çözülmez  bir  bilmece 

Yetmedi mi  artık  çektiğim  bu  eşsiz  işkence...

Bu  akşam  yine  sensiz  hüzünlerim

Bu  akşam  yine  sensiz,

Ne  olduğunu  bilmediğim  bir girdabın  içindeyim', 'Ağlamaya  mecalim  kalmadı  bu  gece Düşündüklerim  geçiyordu  gözlerimden  hece hece Takılıp  kaldım  çözülmez  bir  bilmece  Yetmedi mi  a...', ARRAY['Türk Edebiyatı','Şiir','Ferruh Turgut İnal']::text[], 8.5, '{"poet":"Ferruh Turgut İnal","poet_slug":"ferruh-turgut-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/huzun-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-ferruh-turgut-i-nal-s92oj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarın  istesem  gelir  misin 

Bana  sevdiğini  söyler  misin 

Bir  ışık  yakar  mısın,bir   göz  kırpar  mısın

Ümitlerim  için...', 'Yarın  istesem  gelir  misin  Bana  sevdiğini  söyler  misin  Bir  ışık  yakar  mısın,bir   göz  kırpar  mısın Ümitlerim  için......', ARRAY['Türk Edebiyatı','Şiir','Ferruh Turgut İnal']::text[], 8.5, '{"poet":"Ferruh Turgut İnal","poet_slug":"ferruh-turgut-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/umit-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martının Çığlıkları', 'martinin-cigliklari-ozge-gul-26uf7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin vardı ilk içimi çeken...

Sen konuştukça derinleşen,

Simsiyah bakışların,

Sence karanlık olan dalışların.

Umutsuzluğun korkuların,

Beni içine çekmekten korktuğun karanlığın,

Soruların, bakışların,

Bırak...

Her şey olacağına varsın.

Düşünmeyelim artık,

Denizin soğukluğunu,

Martının niye çığlık attığını,

Ya da ne bileyim,

Bu aşkın vedasını!

Al beni karanlığına,

Cesaretim var korkma,

Aldanma kararsızlığıma,

Aldırma sen bana,

Üzülmek de güzel,

Yaşanan aşkların sonunda;

Ve anmak belki de,

Gözlerimde yaşlarla,

Ama en güzel hatıralarla,

Yine de güzel

Yeter ki sen hiç bir zaman

Kendini unutma!

Tek başına karanlıklara dalma!..', 'Gözlerin vardı ilk içimi çeken... Sen konuştukça derinleşen, Simsiyah bakışların, Sence karanlık olan dalışların. Umutsuzluğun korkuların, B...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/martinin-cigliklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ozge-gul-fobf0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk!!!

Niye bitersin???

Daha gün doğmadan?

Niye terkedersin

Bu kalbi de... 

Başkalarına gidersin!

Ey Aşk...

Yine sinersin

Gönlümün taa derinliklerine 

Yine beni üzersin

Bir de sevdiğimi

Beni niye dinlemezsin???', 'Aşk!!! Niye bitersin??? Daha gün doğmadan? Niye terkedersin Bu kalbi de...  Başkalarına gidersin! Ey Aşk... Yine sinersin Gönlümün taa derin...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marmara Depremi', 'marmara-depremi-ozan-ezgini-m1s9h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vurdu deprem yaralandı Marmara,

Ağaç ağlar Yaprak ağlar Dal ağlar,

On yedi Ağustos yıl doksan dokuz,

Seher ağlar sabah ağlar yel ağlar.

xxx

Kocaeli Sakarya Gölcük Yalova,

Kan gölüne döndü o zümrüt ova

Değirmen deresi karıştı suya,

Dere ağlar sular ağlar sel ağlar.

xxx

Saraylar villalar kökten söküldü,

Feryadımız gök yüzüne çekildi,

Millet kan ağladı, boynu büküldü

Gelen ağlar gören ağlar el ağlar.

xxx

Mahşere benziyor görünen izler,

Yüreğim yaralı ciğerim sızlar,

Yorgun gözler dalgın çevreyi gözler,

Bağban ağlar bahçe ağlar gül ağlar.

xxx

Fay hattı uzundu çok yeri vurdu,

Ozan EZGİNİ, yim mantığım durdu,

Teselli arayıp sazına sordu,

Perde ağlar mızrap ağlar tel ağlar.

xxx

                                    20/AĞUSTOS/1999

                                         {ANKARA}', 'Vurdu deprem yaralandı Marmara, Ağaç ağlar Yaprak ağlar Dal ağlar, On yedi Ağustos yıl doksan dokuz, Seher ağlar sabah ağlar yel ağlar. xxx ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ezgini']::text[], 8.5, '{"poet":"Ozan Ezgini","poet_slug":"ozan-ezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/marmara-depremi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayamıyorum', 'aglayamiyorum-ozge-gul-elzak', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlayamıyorum...

Bu kadar mı zor bağıramıyorum...

Sesim çıkmıyor azıcık bile

Boş boş bakıyorum

Bir anda oldu her şey

Bir kader miydi geldi gecti?

Nereye sürüklüyor bizi hayat?

Birer kuklaymışız meğer hayat bizi seçti...

Ağlayamıyorum diyorum duymuyor musun?

Tanıyamıyorum seni bu sen misin?

Soracağım çok şey var ama cevabı yok!

Bulduğum zaman  benden onları ister misin?', 'Ağlayamıyorum... Bu kadar mı zor bağıramıyorum... Sesim çıkmıyor azıcık bile Boş boş bakıyorum Bir anda oldu her şey Bir kader miydi geldi g...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglayamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Kaşık', 'sonsuz-kasik-ozge-gul-znio5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk gibi aşığım sana...

Aşk sana aşık,

Ben sana aşık.

Sen aşka aşık,

Ve belki de...

Sen de bana aşık.

Belki de bir kaşık!

Kaçık aşık, aşık kaçık.

Belki de aşk sonsuz kaşık!', 'Aşk gibi aşığım sana... Aşk sana aşık, Ben sana aşık. Sen aşka aşık, Ve belki de... Sen de bana aşık. Belki de bir kaşık! Kaçık aşık, aşık k...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sonsuz-kasik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevap Ver', 'cevap-ver-ozge-gul-3gte5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni unutma diyorsun

Söyle...

Mümkün mü seni unutmak

O iki guzel yılı

Anıları acı ve tatlı...

Hayallerimiz vardı

Unutulmayacak yıkılmayacak hayallerdi onlar

Söyle nasıl unuttuk nasıl yıktık cevap ver

Mümkün mü seni unutmak 

Cevap ver!', 'Beni unutma diyorsun Söyle... Mümkün mü seni unutmak O iki guzel yılı Anıları acı ve tatlı... Hayallerimiz vardı Unutulmayacak yıkılmayacak ...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cevap-ver-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Ayrı', 'o-ayri-yusuf-sabri-bagriacik-v32wu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ah şu ayrı diye nitelediklerimiz var ya, 

		ne oluyorsa onlar için oluyor

		ben bi tanesine kapıldım, o ayrı...

bak etrafına... bak bi kere daha!

gün olacak, o insanlara bakarak ağlayacaksın.

seyredeceğim ağlamanı, uzaktan

hani hep korkarak da olsa seni seyrettiğim yerden

kimse seni görmeye alışık değil, o şekilde

ağla bakalım ağla

görürüm herkesi oralarda, çekinirler,

gelemezler yanına...

bak etrafına... bak bi kere daha!

sinirin gözlerinden kanasın

gücün varsa, kalk yerinden

gel, sök gönlümü içimden 

ağlamalarının içine kat

beni bırak

bırak da seyredeyim ağlamanı, uzaktan

seyredeyim gözlerinden kanayan ihanetlerini

kendimi arayayım içlerin de 

bi kız çocuğunun getirdiği çiçeklere sevin

al ellerine onları, solsunlar

çocuk ağlasın, sen ağla

bu durum da kesindir göz yaşlarım

içime akarlar...

geçiyor akşamlar sessiz

vuruyorum kaldırımlara kendimi

o,

bunu, 

yapmamalıydı diyorum.

bi kız çocuğunun getirdiği çiçeklere sevin

al ellerine onları

göz yaşlarını okut onlara,

ve üzerindeki notu oku!

acıların harflerle yaratılmış itirafını oku

     ''Hani deminden beri karşında oturuyorum ya,

     hani deminden beri ağlamanı seyrediyorum ya,

     bak bakalım bi daha yolun karşısına,

     seni seyrettiğim yere...

     beynimden akan kanları görecek misin?''

aşk da ne eksiğim vardı van gohg dan

tutkularım beni sarı sıcak bi boşluğa götürdü

ve ateşledim belimde ki makineyi şakağıma yaslamış bi vaziyette

oysa, her yol seninle parise çıkacaktı.', 'ah şu ayrı diye nitelediklerimiz var ya,  		ne oluyorsa onlar için oluyor 		ben bi tanesine kapıldım, o ayrı... bak etrafına... bak bi kere ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/o-ayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlumuz Olacaktı', 'oglumuz-olacakti-ozge-gul-31b59', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani kaderdi bizim karsılasmamız

Birbirimiz için yaratılmış olmalıydık

Yaşadıklarımızın hiçbiri boşa değildi

Dünyada sadece ikimiz vardık

Hani bir oğlumuz olacaktı

Adı Ümit Yaşar olacaktı

Küçük ama mutlu evimiz nerde

Söylesene hayallerimiz hangi cehennemde

Çok mu mutluyum sanıyorsun

Ben mi bitirdim? Yanılıyorsun!

Bitti biliyorum ama hazmedemiyorum.

Sen beni çok yanlış tanıyorsun.', 'Hani kaderdi bizim karsılasmamız Birbirimiz için yaratılmış olmalıydık Yaşadıklarımızın hiçbiri boşa değildi Dünyada sadece ikimiz vardık Ha...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oglumuz-olacakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Artık Odalar', 'karanlik-artik-odalar-ozge-gul-s82i7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlık artık odalar

Ses gelmiyor duvarlardan

Ben miydim giden?

Sen miydin beni iten?

Üzesin geliyor beni üzülmedigimi sanıyorsun

Var gel üz beni sınırları zorluyorsun

Ne var ki sınır sonsuza dayanmıs sen farketmiyorsun

İstedigin kadar üz beni çünkü göremiyorsun...

Ben taş olmuşum yüreğim duyulmuyor duyamıyor

Sen hala taş atıyorsun boşuna uğraşma

Bir şey kırılmıyor

Taş taşa ne yapar gözlerim bile tek başına ağlayamıyor

Yüreğimi dışarı çıkartabilirsen çıkart başka türlü olmuyor', 'Karanlık artık odalar Ses gelmiyor duvarlardan Ben miydim giden? Sen miydin beni iten? Üzesin geliyor beni üzülmedigimi sanıyorsun Var gel ü...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karanlik-artik-odalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme', 'uzulme-ozge-gul-vmzq5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni ama hep seni;

Yaşamak, yaşatmak istedimse de içimde;

Başaramadım belki de...

Ama...

Denemek bile bir şey değilmiydi ki?

Ben denedim!

Denemekteyim!

N''olur 

Benim yüzümden;

Sen üzülme!', 'Seni ama hep seni; Yaşamak, yaşatmak istedimse de içimde; Başaramadım belki de... Ama... Denemek bile bir şey değilmiydi ki? Ben denedim! De...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uzulme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamalısın', 'anlamalisin-ozge-gul-o2le1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamalısın...

Yaşadıkça anlamalısın.

Ne kadar sürerse sürsün,

Birlikte olduğumuz sürece farklısın,

Kıramadığım,kızamadığımsın;

Ama belki de en çok kızacağımsın.

Yaşadıkça hatırlayacaksın,

Yaşadıkça anlayacaksın,

Anlamalısın...', 'Anlamalısın... Yaşadıkça anlamalısın. Ne kadar sürerse sürsün, Birlikte olduğumuz sürece farklısın, Kıramadığım,kızamadığımsın; Ama belki de...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anlamalisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaset', 'kaset-ozge-gul-r6a63', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben başka kaset arıyordum

Bu lanet olası kaset nerden çıktı ki?

Kalbimin yumuşamasını istemiyordum.

Bu şarkıları niye yazdınız ki?

Niye götürdünüz beni anılara?

O muhtesem geçen yıllara?

Ne güzel günlermis onlar meğer!

Ne oldu o kusursuz aşkımıza?

Saftı aşkımız tertemiz süt kokardı.

Vapurla geçerdik Kadıköy''e

Kadıköy yalnız ikimizindi.

Biz birbirimizindik... Ne olur artık söyle.

Söyle artık ne oldu aşkımıza?

Sen ve ben vardık, ne oluyor bu insanlara?

Evlenecektik seninle senin olacaktım hani?

Bize mani olan neydi?', 'Ben başka kaset arıyordum Bu lanet olası kaset nerden çıktı ki? Kalbimin yumuşamasını istemiyordum. Bu şarkıları niye yazdınız ki? Niye götü...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaset-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyinle sus', 'herseyinle-sus-ozge-gul-w9emr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sus!

Bir an aydınlık gördün diye konuşma.

Nerede o denizin verdiği huzur?

5 ay içinde bitti.

Daha hiç yaşanmadan...

Hatrımı da sorma bana!

Hal mi bıraktın ki

Hiç konuşma

Gözlerini de çek gözlerimden.

Hatta

Gölgen bile düşmesin üzerime...

Bari şimdi bir iyilik yap da 

Yardım et seni unutmama!

Her şeyinle sus!

Sakın konuşma!', 'Sus! Bir an aydınlık gördün diye konuşma. Nerede o denizin verdiği huzur? 5 ay içinde bitti. Daha hiç yaşanmadan... Hatrımı da sorma bana! H...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/herseyinle-sus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezler', 'bilemezler-ozge-gul-uyndw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gecenin sessizliği de neydi ki?

Onu damı terk etmişler?

Bu yağmur da neyin nesi?

Ona damı dert vermişler?

Duvara sabitledim gözlerimi

Güya buradayım...

Sadece bakıyormuşum

Öyle zannetsinler

Bilseler ki ben neler yaşıyorum!

Bilemezler...', 'Bu gecenin sessizliği de neydi ki? Onu damı terk etmişler? Bu yağmur da neyin nesi? Ona damı dert vermişler? Duvara sabitledim gözlerimi Güy...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bilemezler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Olacak', 'zor-olacak-ozge-gul-cy4u8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle birlikte

Sanki benden de bir parça gidiyor oraya

Ve korkuyorum.

O parçanın hep sende kalmasından

Hiçbir şeyin farkında değilsin ki!

Veya görmemeye çalışıyorsun.

Her şeyi sileceksin ya buradaki...

Geleceğini bile silmişsin!

Ben yanında neyim ki?

Biliyorum unutacağım...

Ama zor olacak.

Her şey çok zor olacak!', 'Seninle birlikte Sanki benden de bir parça gidiyor oraya Ve korkuyorum. O parçanın hep sende kalmasından Hiçbir şeyin farkında değilsin ki! ...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zor-olacak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum Balıkçım', 'seni-seviyorum-balikcim-ozge-gul-yq74c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah sevgilim!

Demek gidiyorsun.

O zeytin gözlerinle

Şimdi sen,

Hangi dağlara bakıyorsun?

Peki ya;

Beni yanında hissediyor musun?

Yolculuğun boyunca

Kendimi gözlerine koydum

Yüreğimi, yüreğine

Fark ediyor musun?

Seni seviyorum balıkçım

Beni düşünüyor musun?', 'Ah sevgilim! Demek gidiyorsun. O zeytin gözlerinle Şimdi sen, Hangi dağlara bakıyorsun? Peki ya; Beni yanında hissediyor musun? Yolculuğun b...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-balikcim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç', 'sen-hic-volkan-koc-zb1ws', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen hiç senliğini yitirdinmi ?

Yada sen hiç başkası için

Başkaları olmaya çalıştın mı ?

Yada senhiç en kalabalıklarda yanlız kaldın mı ?

Kaybolan kendinliğini ararken

En yakın dostun olan sigaranı göz yaşların söndürdü mü ?

Yada sen hiç koşmak danözlemek den  beklemek den 

Ve dinlemek den sesliğin kemanını 

Yada sen hiç aslında sen olan senin öldüğümden 

haberin olmadan yaşadınmı 

   SEN HİÇ', 'Sen hiç senliğini yitirdinmi ? Yada sen hiç başkası için Başkaları olmaya çalıştın mı ? Yada senhiç en kalabalıklarda yanlız kaldın mı ? Kay...', ARRAY['Türk Edebiyatı','Şiir','Volkan Koç']::text[], 8.5, '{"poet":"Volkan Koç","poet_slug":"volkan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-hic-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yolu Olmalı', 'bir-yolu-olmali-ozge-gul-icbsj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir yazmadan önce,

Yaptığım şu karalamaların 

Bir anlamı olmalı...

Her şeyin anlamı olduğu gibi,

Senin anlamının olduğu gibi.

Seni karanlıktan kurtarmanın bir yolu olmalı...

Belki sevginin gücü gibi

Belki de

Aşk gibi...', 'Şiir yazmadan önce, Yaptığım şu karalamaların  Bir anlamı olmalı... Her şeyin anlamı olduğu gibi, Senin anlamının olduğu gibi. Seni karanlık...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-yolu-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğan Çocuğa', 'dogan-cocuga-tevfik-mengulluoglu-jsigo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahın saatleri

güneşin gülümseyişi ve saadeti

önce dağlara sonra bucağına, 

iki yıl önce, yüz yıl önce

Doğan çocuğa

Selam verişi yılların eseri

umuttur, yıldızdır yüreğimden kopan

henüz doğan bir güneş dağların ardından

parlayacak bir yıldız kenardan

gürleyecek bir ses geleceğe koşan

yirmidört saat kıyamete dek, 

şehrimi aydınlatan.

Yeşerdiği saksıdan kokusunu dört bucağa salan, 

gecenin koynunda doğan ama ölmeyen

doğan çocuğa', 'Sabahın saatleri güneşin gülümseyişi ve saadeti önce dağlara sonra bucağına,  iki yıl önce, yüz yıl önce Doğan çocuğa Selam verişi yılların ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dogan-cocuga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dibe Vurmak', 'dibe-vurmak-kivanc-gorkem-vkf3x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'öyle anlar olurki

söyleyeceklerin söylenmez

birikimlerin boşluk olur

boşluklarsa alabildiğine birikir

tutunacak her şeyi yutar

bir arenada yapayalnız hissedersin kendini

iftira,yalan,entrika içinde nefes alamazsın

öyle boğulursunki,kendi doğruların değerlerin 

sana bile anlamsız gelir

öyle boğulursunki savunmak gelmez içinden

öylece bırakmak istersin her şeyi

arenada yalancı dostların ilk terkeder seni

ilk karı bu sefer görürsün güz görmeyen dağında 

yaptığının,geçmişinin,yaşananların 

senin için bile önemi kalmaz

çıkıp gitmek istersin o an gerçekten yalnızsındır

en güvendiğin yaşamın amacı kömür gözler dahi görmez artık seni

ne elinden,ne içinden hiç bi şey gelmez

söylemek istersin çırpınmak açığa vurmak...

yapamazsın

haklı olmak ilk kez gelir sana dokunur

''öyle'' olsa için yanmaz haketmişsindir 

ama ''öyle'' değildir işte

ne yazık kimse inanmaz sana

inanan dostların  ise ne ordadır

nede o an bir şey ifade eder

''herkes'' ve her şey (belki tanrıda) sana karşıyken

içinden zayıf bir ''neden?'' yükselir

''nasıl?'' arkasından gelir

sana o an ne bildiklerinin

ne değerlerin,nede doğruların bir faydası vardır

hayatın adını bilmediğin bir arabesk parçada çoktan anlatılmıştır

gülüp geçtiğin şeyler sensindir şimdi

ne hazindirki gülemezsin bu sefer kendi haline

kendi hakkında öyle şeyler duyarsınki,

etkilenirsin,iyi niyetinden şüphe edersin

parmaklar aşağıyı çoktan göstermiştir

üzülmene fırsatın kalmaz

bu sefer anlamakta zorlanırsın tanrının büyüklüğünü,amacını

inandığın o ilahi adalet bile ne uzaktır şimdi

tanrının gölgesi saydığın gözler bakmak istemez sana

duymak bile istemez çıkartamadığın sesini

aklından bin türlü şey geçer,

üç saniyede kendi anıların seni boğar

gelir her şey seni vurur

üstünden bin kişi geçer

off bile diyemezsin yıkılırken

kaçmazsın atılan taşlardan

yokolmak istersin

kelleni isteyen cellatlara

bu sefer gönüllü uzatırsın başını

elin attığı taştan yaralanmazsında

yarin attığı gül yaralar seni

malesef ilacı yoktur

işte o gül öldürür seni

artık yeni bir anlam kazanmıştır hayat senin için

ne varki sen bu anlamı anlamazsın

anlamak istemezsin

hiç bir şeyde teselli olamayacak kadar uzaktır sana

ne düne dönme imkanı vardır

ne bugünü yaşarsın

hayatı kendine tanımlayamazsın artık

fazla bir amacında kalmamıştır

dünya sensizde dönmeye devam eder 

sen bir önceki durakta çoktan inmişsindir

şiirinde bitmez uzar uzadıkça geceyarıları

ama artık bir nokta koymak istersin

her şeye rağmen sevmeye devam edersin

her şeye rağmen genede onunsundur

ama artık içinden söyleme zamanıdır şarkını

(1/5/2001 0135)', 'öyle anlar olurki söyleyeceklerin söylenmez birikimlerin boşluk olur boşluklarsa alabildiğine birikir tutunacak her şeyi yutar bir arenada y...', ARRAY['Türk Edebiyatı','Şiir','Kıvanç Görkem']::text[], 8.5, '{"poet":"Kıvanç Görkem","poet_slug":"kivanc-gorkem","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/dibe-vurmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kapatamadım İçimde', 'seni-kapatamadim-i-cimde-ozge-gul-5uc7b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülüşün, 

Gülüşünü de özledim.

Gözlerin,

Gözlerini özlediğim gibi.

Telefonu kapattım bir saat önce

Ama seni hala

Kapatamadım içimde.

Nedense canım 

Sadece böyle durmak

Sadece seni düşünmek istiyor.

Evini,

Şu an ne yaptığını.

Nereye baktığını,

Ne düşündüğünü bilmek istiyor.

Sana bir öpücük göndermek

Senin de onu dudaklarında 

Hissetmeni istiyor.

Şu an canım 

Sadece seni istiyor

Aşkım!', 'Gülüşün,  Gülüşünü de özledim. Gözlerin, Gözlerini özlediğim gibi. Telefonu kapattım bir saat önce Ama seni hala Kapatamadım içimde. Nedense...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-kapatamadim-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapamıyorum', 'yapamiyorum-ozge-gul-vo2xx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutacağım diyorum.

Yaramazsın diyorum.

Gitmeyeceğim yanına diyorum.

Ama...

Allah kahretsin!

Bir bakışın,

Bir gülüşün yetiyor.

İşte yine ben...

Koşa koşa sana geliyorum.

Yapamıyorum!', 'Unutacağım diyorum. Yaramazsın diyorum. Gitmeyeceğim yanına diyorum. Ama... Allah kahretsin! Bir bakışın, Bir gülüşün yetiyor. İşte yine ben...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yapamiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-tevfik-mengulluoglu-5spkg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hergün bir avuç korkuyla uyanıyorum

bu senin gitmiş olabileceğinin korkusu yar, 

bu senin unutmuş olabileceğinin korkusu gül.

Çok sürmez sonra ezgi kanatlarında duymaya sesini

anılar depreşir, yürekler durulur

Korkular ertelenir bir başka sabaha

Oysa sen olmayan sen hep aynı yerdesin

yüreğimin derinliklerindesin.

Geçmişten kalan bir alışkanlık belkide 

seni sevmek.

Sokaklarını yokluğunla dolaşırken gecemin

isimsiz sabahlara senin adını koyuyorum şimdi.', 'Hergün bir avuç korkuyla uyanıyorum bu senin gitmiş olabileceğinin korkusu yar,  bu senin unutmuş olabileceğinin korkusu gül. Çok sürmez son...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sevmek-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir Şey', 'baska-bir-sey-ozge-gul-cmtwc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onun...

Oralarda bir yerlerde

Hala yaşadığını 

Benim gibi nefes aldığını

Hatırladım bugün.

Ne kadar unuttum desem de

Bir minik kıvılcım,

Ya da bir anı

Hemen hatırlattı seni bana.

Bir anda bitiriverdim,

Bir anda başlayıverdin.

Yok!

Benimki başka bir şey.

Anlamıyorum kendimi.

Şu anda çıksan karşıma

İnan haykırırdım suratına!

Yok! Benimki başka bir şey

Anlamıyorum...

Ne beni

Ne seni!', 'Onun... Oralarda bir yerlerde Hala yaşadığını  Benim gibi nefes aldığını Hatırladım bugün. Ne kadar unuttum desem de Bir minik kıvılcım, Ya ...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baska-bir-sey-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hiç Sevmedim Desem', 'seni-hic-sevmedim-desem-ozge-gul-w5wdu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni hiç sevmedim desem

Ah! Çok pişman olurdum...

Bir gurur uğruna.

Seni hiç sevmedim desem

Her sabah seni düşünmem

Yalan olurdu o zaman

Ki gerçekler yalan değildir.

Seni hiç sevmedim desem

Gözlerimdeki buğuyu

Nasıl anlatırdım ki sana?

Bana mı inanırdın?

Gözlerime mi?

Seni sevdim...', 'Seni hiç sevmedim desem Ah! Çok pişman olurdum... Bir gurur uğruna. Seni hiç sevmedim desem Her sabah seni düşünmem Yalan olurdu o zaman Ki ...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-hic-sevmedim-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-ozge-gul-2hj4t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Galiba yine seni sevmeye başladım!

Gel artık.

Unutmak da olmadı.

Kendime de kızıyorum.

Gel artık.

Neden bu çekingenlik?', 'Galiba yine seni sevmeye başladım! Gel artık. Unutmak da olmadı. Kendime de kızıyorum. Gel artık. Neden bu çekingenlik?...', ARRAY['Türk Edebiyatı','Şiir','Özge Gül']::text[], 8.5, '{"poet":"Özge Gül","poet_slug":"ozge-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gel-artik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bataklık Menekşesi', 'bataklik-meneksesi-fatih-cunus-tvesz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başım öne eğik geziyordum

Güzel çiçeklerle dolu bir araziydi

Orda dedim hayatımın çiçeği

Koştum, koştum yanına doğru

Kesildi nefesim, ölüyorum sandım

Duraksadım, bir nefes aldım

Taşıyamıyordu güçsüz bedenim beni

Çiçeğin ışıltısı kör etmişti gözlerimi

Adımlarım sıklaştı

Ama o benden uzaklaştı

Koşmaya başladım yeniden 

Uzaklaştığını gördüm ışıltının 

Vardım sonunda yanına çiçeğin

Bataklığın içindeki mor menekşemin

Uzattım elimi ulaşamadım

Onu oradan çıkaramadım

Öldü artık gönlümün neşesi

Adını koydum bataklık menekşesi', 'Başım öne eğik geziyordum Güzel çiçeklerle dolu bir araziydi Orda dedim hayatımın çiçeği Koştum, koştum yanına doğru Kesildi nefesim, ölüyor...', ARRAY['Türk Edebiyatı','Şiir','Fatih Cünüş']::text[], 8.5, '{"poet":"Fatih Cünüş","poet_slug":"fatih-cunus","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bataklik-meneksesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzinsiz Sevdim', 'i-zinsiz-sevdim-fatih-cunus-vftsg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden bahardı

Aylardan nisan

Günlerden ayın üçü

Aldığım risklerin en büyüğü

Belki bir sevgilim olacaktı 

Belki dostluğumuz yıkılacaktı 

Bekledim çöl yağmura nasıl hasretse

Hayaller kurdum, hayaller yıktım

Seni hayallerimde yaşadım

Aşk denen mereti filmlerden bilirdim

Şiirlerde ve öykülerde yaşardım

Aşkın acısını senden öğrendim

Senin suçun değildi güzelim

Ben seni senden izinsiz sevdim', 'Mevsimlerden bahardı Aylardan nisan Günlerden ayın üçü Aldığım risklerin en büyüğü Belki bir sevgilim olacaktı  Belki dostluğumuz yıkılacakt...', ARRAY['Türk Edebiyatı','Şiir','Fatih Cünüş']::text[], 8.5, '{"poet":"Fatih Cünüş","poet_slug":"fatih-cunus","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/izinsiz-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadım', 'unutmadim-mustafa-yildizdogan-yg809', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl çıkarsın aklımdan 

Ruhumdasın unutmadım 

Feryadımda ,eyvahımda 

Ahımdasın unutmadım 

Şiirimsin türküm sensin 

Telaşımsın derdim sensin 

Gözlerimden dökülensin 

Yaşımdasın unutmadım 

Sevdan uykuya salmaz ki 

Geceye derdim sığmaz ki 

Uykular unutturmaz ki 

Düşümdesin unutmadım', 'Nasıl çıkarsın aklımdan  Ruhumdasın unutmadım  Feryadımda ,eyvahımda  Ahımdasın unutmadım  Şiirimsin türküm sensin  Telaşımsın derdim sensin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutmadim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yananı Gör', 'yanani-gor-mustafa-yildizdogan-ohks4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yananı gör yananı gör 

Gör halimi yananı gör 

Ateş ne ki su söndürür 

Gir içime yananı gör 

Yana dursun yana dursun 

Söylen O’ na yana dursun 

Belki bir gün uğrar yolum 

Yönü yoldan yana dursun 

O’ da yansın O’ da yansın 

Ben yanmışken  O''da yansın 

Güvendiğim tüm dağlardan 

Ben çekildim O  dayansın', 'Yananı gör yananı gör  Gör halimi yananı gör  Ateş ne ki su söndürür  Gir içime yananı gör  Yana dursun yana dursun  Söylen O’ na yana dursu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanani-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-mustafa-yildizdogan-ceyxj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur yağmakta,sular akmakta

Esen rüzgarda,düşen yaprakta

Her ne var ise kara toprakta

Bir tek sen varsın gerisi yalan

Bana benden yakın olan sevgili

Her nefes aklımı alan sevgili

Ruhumdan sineme dolan sevgili

Bir tek sen varsın gerisi yalan

Ne gençlik ne varlık ne evlat ne yar

Canımda can gizli cananı arar

Azrail peşimde dünyada ne var

Bir tek sen varsın gerisi yalan', 'Yağmur yağmakta,sular akmakta Esen rüzgarda,düşen yaprakta Her ne var ise kara toprakta Bir tek sen varsın gerisi yalan Bana benden yakın ol...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalan-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Değildik', 'boyle-degildik-mustafa-yildizdogan-kenj5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiyle bakardık,tüm insanlara

Nefret, kin bilmezdik, böyle değildik.

Düşkünü kollardık, kucak açardık.

Garibe gülmezdik, böyle değildik.

 Yalan riya yoktu, sözler senetti.

Selam her kapıyı açan biletti.

Sevgi, saygı vefa aynı niyetti

Dostluğu silmezdik, böyle değildik.

Sabır vardı, şükür vardı, sır vardı,

Edep vardı, haya vardı, ar vardı,

Gönül vardı, sevda vardı, yar vardı,

Sevgiden yılmazdık, böyle değildik.', 'Sevgiyle bakardık,tüm insanlara Nefret, kin bilmezdik, böyle değildik. Düşkünü kollardık, kucak açardık. Garibe gülmezdik, böyle değildik.  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldızdoğan']::text[], 8.5, '{"poet":"Mustafa Yıldızdoğan","poet_slug":"mustafa-yildizdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/boyle-degildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-mehmet-sariyar-i7z1p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha kaç bahar bekler gönlüm bilemiyorum,

Kaç bahar tutar yasını.

Kuş uçumunda oysa ellerin,

Gökyüzü kadar yakın yüreğin,

Hissediyorum.

Ve vardıkça sana, anlıyorum.

Upuzun bir yolun kuşluk vaktindeyim,

Biliyorum.

(03. 08. 1998)', 'Daha kaç bahar bekler gönlüm bilemiyorum, Kaç bahar tutar yasını. Kuş uçumunda oysa ellerin, Gökyüzü kadar yakın yüreğin, Hissediyorum. Ve v...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarıyar']::text[], 8.5, '{"poet":"Mehmet Sarıyar","poet_slug":"mehmet-sariyar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/biliyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adını Hüzün Koydum', 'bir-adini-huzun-koydum-mehmet-sariyar-brili', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğime bir hüzün gibi,

Yüreğime bir karanfil gibi,

Yüreğime bir sevda gibi düşen,

O senin adını yangın koyuyorum.

Tutuşup alevlerinde savrulsa da küllerim.

Acımasız sokaklarında Beyoğlu''nun,

Hayın karanlığında,

Yanlış anlarında anların

Yorgun ışıklarında neonların.

Bir adını hüzün koyuyorum,

Öbürünü hüzün çiçeği karanfil.

Ne sevdalar atlatır bilirim yüreğin,

Ne yağmurlara ket vurur.

Ne fırtınalar ziyaret etmiştir gönül limanını kimbilir? 

Ne kavruk yürekler tanır gözlerin,

Ne adam gibi adamlar bilir.

Merhaba ey güzel insan,

Merhaba hüzün çiçeği karanfil,

Hoş geldin safa geldin dünyama.', 'Yüreğime bir hüzün gibi, Yüreğime bir karanfil gibi, Yüreğime bir sevda gibi düşen, O senin adını yangın koyuyorum. Tutuşup alevlerinde savr...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarıyar']::text[], 8.5, '{"poet":"Mehmet Sarıyar","poet_slug":"mehmet-sariyar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-adini-huzun-koydum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma Şahım', 'sanma-sahim-yavuz-sultan-selim-7iajv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanma şâhım / herkesi sen / sâdıkane / yâr olur

Herkesi sen / dostun mu sandın / belki ol / ağyâr olur

Sadıkâne / belki ol / âlemde bir / serdar olur

Yâr olur / ağyâr olur / serdar olur / didâr olur', 'Sanma şâhım / herkesi sen / sâdıkane / yâr olur Herkesi sen / dostun mu sandın / belki ol / ağyâr olur Sadıkâne / belki ol / âlemde bir / se...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sultan Selim']::text[], 8.5, '{"poet":"Yavuz Sultan Selim","poet_slug":"yavuz-sultan-selim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sanma-sahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Kapıyı', 'ac-kapiyi-necip-fazil-kisakurek-aw1yw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aç kapıyı haber var, 

Ötenin ötesinden.

Dudaklarda şarkılar, 

Kurtuluş bestesinden.

Biz geldik, bilen bilsin.

Gönül gönül girilsin.

İnsanlar devşirilsin,

Sonsuzluk destesinden.', 'Aç kapıyı haber var,  Ötenin ötesinden. Dudaklarda şarkılar,  Kurtuluş bestesinden. Biz geldik, bilen bilsin. Gönül gönül girilsin. İnsanlar...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ac-kapiyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsâf', 'i-ns-f-s-h-i-naksibend-sml7d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsâfa gel, insâfa gel, insâfa

Yazık ömrünü verdin sen isrâfa', 'İnsâfa gel, insâfa gel, insâfa Yazık ömrünü verdin sen isrâfa...', ARRAY['Türk Edebiyatı','Şiir','Şâh-ı Nakşibend']::text[], 8.5, '{"poet":"Şâh-ı Nakşibend","poet_slug":"s-h-i-naksibend","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/insaf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğim', 'gidecegim-tuncer-oral-1m3ru', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yarın burası, 

Sakin ve sessiz olacak. 

Umutlarımı koltuğumun altına alıp 

Gideceğim, habersiz, 

Ardıma bakmayarak... 

Yarın burada, 

Sessizlik yankılanacak 

Ne bir iz ne bir ses geride 

Bütün hüzünlerim, 

Acılarıma eklenip 

Koca bir dağ olacak. 

Ve ben; 

Gideceğim, dağı sırtlayıp 

Arkama bakmayarak... 

3 Mayıs 2001', 'Yarın burası,  Sakin ve sessiz olacak.  Umutlarımı koltuğumun altına alıp  Gideceğim, habersiz,  Ardıma bakmayarak...  Yarın burada,  Sessiz...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gidecegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ne-bileyim', 'ne-bileyim-senol-sonmez-gul-i8q57', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sokaklarda yürürken yalnız,

Ellerimi  uzatıp seni arıyorum,

Yaşarken dünyada umutsuz,

Gözlerimi kapatıp seni arıyorum,

Senin için doğdum ben,

Sensiz kendimi düşünemiyorum,

Her varlığın sonunu,

Seninle beraber görüyorum,

Seni hiç görmesem de, hissetmesem de,

Benimle olmanı birgün diliyorum,

Korkularımın sonunda,

Seninle olacağımı biliyorum,

Ne aşka, ne de birine inandım,

Yalnızlık hissiyle geceleri kayboldum,

Varlığından dolayı, korkularla büyüdüm,

Gel demeden gelme ölüm', 'Sokaklarda yürürken yalnız, Ellerimi  uzatıp seni arıyorum, Yaşarken dünyada umutsuz, Gözlerimi kapatıp seni arıyorum, Senin için doğdum ben...', ARRAY['Türk Edebiyatı','Şiir','Şenol Sönmez Gül']::text[], 8.5, '{"poet":"Şenol Sönmez Gül","poet_slug":"senol-sonmez-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-bileyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derya', 'derya-senol-sonmez-gul-bnwcy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deniz elleriyle rıhtımı yakalar, ağlar,

Ellerim gönlünde bir yer arar gibi,

Rüzgar eser benim gibi; toprak arar,

Yaşadığım her günde arıyorum seni,

Al kalbinin derinliklerine göm beni', 'Deniz elleriyle rıhtımı yakalar, ağlar, Ellerim gönlünde bir yer arar gibi, Rüzgar eser benim gibi; toprak arar, Yaşadığım her günde arıyoru...', ARRAY['Türk Edebiyatı','Şiir','Şenol Sönmez Gül']::text[], 8.5, '{"poet":"Şenol Sönmez Gül","poet_slug":"senol-sonmez-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/derya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabus', 'kabus-senol-sonmez-gul-bmfqj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aklıma,

Düş artık geceleri zihnime giren,

Yırtılıp rüyalarımdan çıkabiliyor musun?

Esir ettin beni sana biliyor musun?

Hayatım var diyordum eskiden

Şimdi bir yokuş yukarı ömrüm,

Tırmanması zor değil,

Çıkıpta inmekten korkuyorum,

Yalnızlığımda boğuşuyorum,

Ne derya ne de dünya,

Bir hayal ben de olan,

Kapalı gözler ardında,

Bir uykuyla var olan,

Rüyadır gördüğüm,

Geceleri boğuştuğum,

Bitirenim,

Mahvedenim', 'aklıma, Düş artık geceleri zihnime giren, Yırtılıp rüyalarımdan çıkabiliyor musun? Esir ettin beni sana biliyor musun? Hayatım var diyordum ...', ARRAY['Türk Edebiyatı','Şiir','Şenol Sönmez Gül']::text[], 8.5, '{"poet":"Şenol Sönmez Gül","poet_slug":"senol-sonmez-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kabus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-senol-sonmez-gul-dp99a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Damla damla gel, yağ,

Fırtına kopmadan,

Rüzgardan önce,

Kimse dokunmadan,

Gözyaşlarımla gel dost ol,

İki ızdırap olun dünyada,

Kalmasın sizden başka,

Izdıraba gebe farklı kişi,

Düşmesin gözlerden sevgi acısı,

Yırtılın bulutlar, dağılın her bir yana,

Her yere sağnak sağnak yağın,

Güneşe bile görünmeden,

İsyan eden seslere verin kulağınızı,

Tercüman olun gönüllere,

Her ağlayan için siz ağlayın,

GÜLMEK sırası gelene kadar,', 'Damla damla gel, yağ, Fırtına kopmadan, Rüzgardan önce, Kimse dokunmadan, Gözyaşlarımla gel dost ol, İki ızdırap olun dünyada, Kalmasın sizd...', ARRAY['Türk Edebiyatı','Şiir','Şenol Sönmez Gül']::text[], 8.5, '{"poet":"Şenol Sönmez Gül","poet_slug":"senol-sonmez-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir Mevsim', 'baska-bir-mevsim-senol-sonmez-gul-r9lj0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonbaharda yapraklar dökülür,

Ağaçlar ayrılır yapraklarından,

Bir deli hüzün başlar,

Bu ayrılığın ardından,

Kışa girer yalın ağaçlar,

Bir soğuk, bir kar derken,

Acılar büsbütün artar,

Ve ölüm gelir severken,

İlkbaharda bir müjde gelir,

Kuşlar fısıldar ağaçlara,

Ağaçlar canlanır gibi olsa da,

Hayat bitmiştir onlara,

Yaz herşeyi getirken,

Ağaçlar ilk yapraklarını arar,

Herkes ilk aşk peşindeyken,

Zavallı ağaçların acısı artar,

Dört mevsimlik bir dünyadır bu,

İlk aşkını unutturur sana,

İsyan edersin her gününde dünyaya,

''Yok mu başka bir mevsim daha''', 'Sonbaharda yapraklar dökülür, Ağaçlar ayrılır yapraklarından, Bir deli hüzün başlar, Bu ayrılığın ardından, Kışa girer yalın ağaçlar, Bir so...', ARRAY['Türk Edebiyatı','Şiir','Şenol Sönmez Gül']::text[], 8.5, '{"poet":"Şenol Sönmez Gül","poet_slug":"senol-sonmez-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baska-bir-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlarda Ölüm', 'bulutlarda-olum-faik-kivanc-5uayw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölümüm sessizce olmalı,

Ama uyurken ölmemeliyim.

Sen sadece haberini almalısın,

Gözlerin dolmalı, ama

Ağlayamamalısın...

Bir yıldız kaybolmalı geceden,

Sen eksikliğini bile 

Anlayamamalısın...

Rüzgarlar kefenim olmalı,

Beni bulutlara gömmelisin...', 'Ölümüm sessizce olmalı, Ama uyurken ölmemeliyim. Sen sadece haberini almalısın, Gözlerin dolmalı, ama Ağlayamamalısın... Bir yıldız kaybolma...', ARRAY['Türk Edebiyatı','Şiir','Faik Kıvanç']::text[], 8.5, '{"poet":"Faik Kıvanç","poet_slug":"faik-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bulutlarda-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-hakan-yigit-k6n3m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir efsaneydi yaşadığımız

Bir rüyaydı birlikte nefes alışımız

Bir hayaldi ulaşılamayan sevgimiz

Bir yalandı bu hayatımız...', 'Bir efsaneydi yaşadığımız Bir rüyaydı birlikte nefes alışımız Bir hayaldi ulaşılamayan sevgimiz Bir yalandı bu hayatımız......', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/efsane-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tazelenen Umutlar', 'tazelenen-umutlar-hakan-yigit-ylh3l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umut dolu umutlarla açıldık engin denizlere

Eli boş gidilmezdi gözü uzaklarda bekleyenlere

Kara göründü diye bir ses gelince kulağıma

Gözyaşımı gönderdim oraya umudumu tazelesin diye...', 'Umut dolu umutlarla açıldık engin denizlere Eli boş gidilmezdi gözü uzaklarda bekleyenlere Kara göründü diye bir ses gelince kulağıma Gözyaş...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tazelenen-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '365', '365-hakan-yigit-e5kxo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir 365 in ardından ''bir'' daha 

Zaman insafsız bir avcı gibi

Beni en derinden vurmaya devam ediyor

Bilerek, isteyerek,yineleyerek

Bitmeyeni yaşatmıyor,bana kanmıyor

366 yapmıyor...', 'Bir 365 in ardından ''bir'' daha  Zaman insafsız bir avcı gibi Beni en derinden vurmaya devam ediyor Bilerek, isteyerek,yineleyerek Bitmeyeni ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/365-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıra Bizde', 'sira-bizde-hakan-yigit-8kyxd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine bir kahkaha at öylesine ya da 

Bir fıkra anlat biz de gülelim ya da 

Bir takla at

Yorulduktan sonra biraz biz bir şeyler söyleyelim...', 'Yine bir kahkaha at öylesine ya da  Bir fıkra anlat biz de gülelim ya da  Bir takla at Yorulduktan sonra biraz biz bir şeyler söyleyelim......', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sira-bizde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güven', 'guven-hakan-yigit-oyn0q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah güven!Elde edilmen çok zor

Kaybetmek ise çok kolay

Her anılışında bambaşka bir olay

Kulağın çınlar patlarcasına!

Arkadaşın kim?Merak esiyorum

Senin de umutların var mı ya da günahların?

Hepsini biz mi yaşamak zorundayız?

Sana güvenmeli miyiz?', 'Ah güven!Elde edilmen çok zor Kaybetmek ise çok kolay Her anılışında bambaşka bir olay Kulağın çınlar patlarcasına! Arkadaşın kim?Merak esiy...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guven-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-aykut-bababalim-90qsu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bunaldığımın ismidir

ankara nın kapalı gözleri

ardı ardına gelen günleri

sevdiğimin resmi bile olmayan 

istanbul hayalleri su-i zanlara mahkum 

arkadaş müsvetteleri', 'bunaldığımın ismidir ankara nın kapalı gözleri ardı ardına gelen günleri sevdiğimin resmi bile olmayan  istanbul hayalleri su-i zanlara mahk...', ARRAY['Türk Edebiyatı','Şiir','Aykut bababalim']::text[], 8.5, '{"poet":"Aykut bababalim","poet_slug":"aykut-bababalim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ankara-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecede', 'gecede-nurettin-ozdemir-8jbad', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bunlar aşkın elleri.. yumuşak

Usulca tutuyor ince bileklerinden,

Ve ölümsüz aşk tek başına koruyor

Tanrısal güzelliği yenilmekten

İşte çaresizliğin sınırı, bunu bil

Orada mesafelere inat büyüyen

Ve bizi çağıran bir başka sıcaklık var.

Ve işte evrenin gücü kolları..unutma!

Soluksuz orman.. gökyüzü ve yıldızlar

Ve dağılan sadece bir görüntüdür

Yalnızlığın insafsız rüzgârında,

Yakan güneş, durgun deniz.. hepsi boş

Ölümsüz ve gerçek olan biziz, yalnız biz.

Seviştikçe aydınlığı çoğalan gecedeyiz.', 'Bunlar aşkın elleri.. yumuşak Usulca tutuyor ince bileklerinden, Ve ölümsüz aşk tek başına koruyor Tanrısal güzelliği yenilmekten İşte çares...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gecede-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Vakit Geçti Yorgunum', 'artik-vakit-gecti-yorgunum-nurettin-ozdemir-r3i7v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep seni bekledim gelmeyen

Çocukluğumda, o altın çağda

O eski masallardan çıkıp ansızın

Kırbacı, sihirli seccadesi ve Keloğlan''la

Göklerin yedi kat güzelliğinden

Hep seni bekledim gelmeyen

Gençliğimde, o hür aynalarda

O cömert çağrısında çeşmelerin

Delikanlı bilekler üstünde

Beyaz gelinliklerle salınıp giden

Hep seni bekledim gelmeyen

Çılgın vuruşunda yüreklerin

Yağmur sonrasında bir sabah

Denizle güneşin kucaklaştığı

İstanbul''un en güzel semtinden

Hep seni bekledim gelmeyen

Yaylalarda, dumanlı doruklarda

Doru taylar üstünde uçarı, kaygısız

Mavzer namlularında sıcak, emin

Ve Köroğlu gibi dağların yücesinden

Hep seni bekledim gelmeyen

Kavgalarda düşman bakışlarında

Soğuk parıltısında bıçakların

Emsalsiz dostluklar uğruna

Yiğit yüreklerle vurulup düşen

Hep seni bekledim gelmeyen

Çocuk seslerinde akşam üstleri

Daracık sokaklarında küçük şehrin

Köşe başlarını döner dönmez

Anne sevgilerine karışıp

Uzak dünyalardan gülümseyen

Hep seni bekledim gelmeyen

Hep seni bekledim gelmeyen

Kavgasız, şarkısız ve umutsuz...

Beklemek hep beklemek, beyhûde, boş

Ne kalbim yitik sevgilerle sarhoş

Ne de mes''ut bakışlarına vurgunum.

Artık vakit geçti yorgunum.', 'Hep seni bekledim gelmeyen Çocukluğumda, o altın çağda O eski masallardan çıkıp ansızın Kırbacı, sihirli seccadesi ve Keloğlan''la Göklerin y...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/artik-vakit-gecti-yorgunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emirganda Gece', 'emirganda-gece-nurettin-ozdemir-6am90', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tılsımlı rûya içinde Boğaz,

Dalların ucuna birikmede haz

Mehtap dökülmeden sulara pul pul

Bir baştan bir başa cânım İstanbul

Dağılmış serpilmiş yamaçlarında

Bir sırrı bölüştük dal uçlarında

Sevda yaprak yaprak avuçlarında

Gezindik bu tenha yollar boyunca

Dinledik suların billûr sesini,

Mermer heykellerin ürpermesini

Duyduk ruhumuzun enginliğinde,

Bu sedef gecenin sahibi nerde? 

Böyle birdenbire başlar içimde

Bir şanlı bestenin son uğultusu; 

Asırlık çeşmenin kurnasında su

Ağlar geçmiş günün mûsikisiyle; 

Kalplerin içinde kalan sesiyle

Söyler bu esrarın ilk hecesini

Gecenin çözülmez bilmecesini

Çözer damla damla ve yudum yudum

Bu sesle tarihi tekrar okudum

Gördüm asırların maverasını; 

Ve eski günlerin hâtırasını

Nefes nefes içim çınarlarından

Tura''larla süslü duvarlarından

Mazi nakış nakış bize gülmede; 

Bir sahil feneri yanıp sönmede.

Düşmede yollara gölgelerimiz.

Bu hulya içinde erir gibiyiz.', 'Bir tılsımlı rûya içinde Boğaz, Dalların ucuna birikmede haz Mehtap dökülmeden sulara pul pul Bir baştan bir başa cânım İstanbul Dağılmış se...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/emirganda-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mermerde Nakış', 'mermerde-nakis-nurettin-ozdemir-bcr4u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mermerde düşünce, ürperme, âhenk;

Yılların bağrında koyulaşan renk.

Yaşıyor sır gibi, canlı ve derin

Mahzun rûyasında âvizelerin.

Bu ıslak taşlara dökülür, güler

Eski hatıralar içinde mermer

Nakışların sessiz mûsikisini

Nakleder bir zaman penceresinden.

Renk, âhenk, ve ışık hendesesinden 

Bir dünya canlanır bir devir başlar.

Hâlâ gülümseyen bu eski taşlar,

Bu muhteşem kapı, bu çılgın sükût

Zamanın çizdiği aşılmaz hudut

Yılların mermere işleyen dili,

Âhenkle, zekânın çağlayan seli

Taşıyor sihrini ebediyete...

Atlılar koşuyor yeni bir fethe

Yeni bir zaferi bekliyor kalbim

Bu ne ulvi koşu sonsuza Rabbim...

Karanlık ufuklar çekildi bir bir

Durgun gözlerimde şâhâne devir

Canlandı bir hayâl inceliğiyle

Düşünmek isterdin. ''İşte vesile''

İşte sana senden kalan hatıra

Ölümsüz hayatı yediyüz yıla

Sığdıran zekânın mermer heykeli

Zamanın o insaf bilmeyen eli

Bu şanlı âbide üstünde her an

Eski yazıların aydınlığından

Gösterir hüznünü ürperişlerin

Sessiz nağmelerle yükselişlerin

En büyük zevkini duyar kalbinde

Esrarlı gecenin maviliğinde

Binlerce senelik saltanatların

Bakiyelerini bekleyen yarın

Bu eşsiz kapıdan nefes almakta.

Yüksek kulelerde şanlı bayraklar

Her an alev alev dalgalanmakta.

Bu kapı üstünde bugün ve yarın

Altın tura''larda geçmiş yılların

Aydın tebessümü sarmakta bizi.

En güzel rûyada sevdiğimizi;

Mermerler içinde görür gibiyiz.

Beni benden alıp götüren bu iz

Bu eski bahçeler, bu coşkun deniz;

Her şeyin başlayıp bittiği mekân

Yağmur sularında eriyen zaman

Bir mûsiki gibi, yeşil dallardan

Ruhlara dökülen, sönen, çırpınan.

Bu çılgın fırtına, bu sonsuz akış.

Oylum oylum âhenk, bu ince nakış

Bu senin ve benim geçtiğimiz yer

Her gece yeniden çıktığım sefer,

Bu kahraman ordu, bu şanlı nefer

Hudut boylarında nöbetleşenler

En yüksek burçlara çekilen bayrak;

Gökte büklüm büklüm ışıklanarak

Bulutlar içinde gülüyor bana,

Zafer müjdeleyen dalgalarına

Fetih yıllarının verdiği huzur

Kalbimde heyecan, gözlerimde nur

Mazi kıvrım kıvrım alnımda gurur

Ak ellere sinen mukaddes uğur

Doğacak günleri bana müjdeler

Üstünde bir dünya taşıyan mermer

Aydın rüyasını tamamlamakta.

Yüksek kulelerde şanlı bayraklar

Gene alev alev dalgalanmakta.

Hüznü, düşüncesi, ürperişiyle

Ve böyle muhteşem gösterişiyle

Beyazıt; bir devri yaşayan mermer

Çınarlar altında gümüş semâver

O çay; o bayraklar, şafaklar gibi

Kâseler içinde en güzel rengi

Bulutlardan bize getiren iksir.

Sonra, fıskiyeler, hûlyalı devir

Sebil, güvercinler, yıkık şadırvan

Kuşların dilinde bir eski zaman

Zümrütten geceler, ışıktan sular

Nedim''ler lâleler, zambak kadınlar

Her mevsim yeniden başlayan bahar

Bozulmuş anladım bu son seferde

Eski sır kalmamış mesafelerde.', 'Mermerde düşünce, ürperme, âhenk; Yılların bağrında koyulaşan renk. Yaşıyor sır gibi, canlı ve derin Mahzun rûyasında âvizelerin. Bu ıslak t...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/mermerde-nakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan I', 'vatan-i-nurettin-ozdemir-0fxcd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vatan,

Antalya''da bir mavi su,

Posof''ta bir çorak tarla,

Gümüşhane''de bir yemyeşil bahçedir.

Vatan,

Sivas yaylasında

Yıldız bakışlariyle aydınlanan 

Ip-ıssız bir gecedir.

Vatan,

Kelkit''te bir kardeş mezarı,

Zonguldak''ta bir maden işçisi,

Rize''de çay toplayan bir gelin

Ve seccâdesinde namaz kılan bir ihtiyar annedir.

Vatan, 

Aydın tebessümüyle Aslıhan

Ve duru bakışlarıyle Emine''dir.

Vatan,

Ceylânpınar''da bir ince ceylân,

Edirne''de bir ince minaredir.

Vatan,

Hudut boylarında dalgalanan

Güzel bayrağımızda

Hare hâredir.

Vatan

Küçük ellerinin avuçladığı

Sâde bir toprak parçası değil çocuğum,

Toprakla büyüyen bir kutsal düşüncedir.', 'Vatan, Antalya''da bir mavi su, Posof''ta bir çorak tarla, Gümüşhane''de bir yemyeşil bahçedir. Vatan, Sivas yaylasında Yıldız bakışlariyle ayd...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/vatan-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüversem', 'oluversem-sabahattin-kudret-aksal-dk9vk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün bir akşam vakti ölüversem

kimseler duymasın kimseler duymasın

bir günbir aksam vakti ölüversem

ve sen o saatlerde uykudasın

telaşa düşmeyin telaşa düşmeyin

böyle vakitsiz çekip gidersem

      sabahattin kudret aksal', 'Bir gün bir akşam vakti ölüversem kimseler duymasın kimseler duymasın bir günbir aksam vakti ölüversem ve sen o saatlerde uykudasın telaşa d...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Kudret Aksal']::text[], 8.5, '{"poet":"Sabahattin Kudret Aksal","poet_slug":"sabahattin-kudret-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/oluversem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-vedat-sumbul-jdm8i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen sustuğunda

Akşamlar depremleniyor...

Yüreğimin fay hatlarında

Kıyametler kopuyor...

Hiçbir masalcı önceden bilemez

Fay hatlarının ne zaman kırılacağını...

Oysa günü gününe,

Saati saatine bellidir,

Yüreğimi sular altında bırakacak deprem...

Sokak köpekleri ve çiçekçi çocuklar tanığımdır,

Her gidişin depremdir bana...', 'Sen sustuğunda Akşamlar depremleniyor... Yüreğimin fay hatlarında Kıyametler kopuyor... Hiçbir masalcı önceden bilemez Fay hatlarının ne zam...', ARRAY['Türk Edebiyatı','Şiir','Vedat Sümbül']::text[], 8.5, '{"poet":"Vedat Sümbül","poet_slug":"vedat-sumbul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/deprem-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meri Kekliğim', 'meri-kekligim-enver-gokce-6odcp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir 

Elde

Çatal

Bir

Elde

Dehre

Dalar

Dikenlerin

Kengerlerin

Peşinde

Kaderimmiş

Söğerim

Oy

Meri

Kekliğim

Yeter

Çektiğim

Dut

Kurusu

Süpürge

Tohumu

Yediğimiz

Ve

Bir

Godik

Arpa

İçin

Sivas

Kapılarından

Geri

Çevrildiğimiz

Günleri

Defledik

Meri Kekliğim

Yeter

Çektiğim

Yol

Paraı

Veremedim

Diye

Şu

Dağları

Bana

Aştırdılar

Şu

Yolları

Bana

Hacizlere

Gitti

Suna

Gibi

Keçim

İneğim

Meri

Kekliğim

Kore

Dağlarında

Tabakam

Kaldı

Mapus

Damlarında

Özgürlüğüm

Hey

Meri

Kekliğim

Yeter

Çektiğin.', 'Bir  Elde Çatal Bir Elde Dehre Dalar Dikenlerin Kengerlerin Peşinde Kaderimmiş Söğerim Oy Meri Kekliğim Yeter Çektiğim Dut Kurusu Süpürge To...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"enver-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/meri-kekligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebiş', 'bebis-selim-omala-xf6d6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başlamıştı yeni bir gün,geceydi odadaki tek kör,

Eşsizdi gözleri,beş buçuğu vuran saatse baş aktör!

Başlamıştı yeni bir gün,bahardı dışarda mevsim,

İlgisizdi geceye,güneşti onun çizdiği resim,

Şarkıydı ve artık,dizelerin ilk harflerindeki isim..!', 'Başlamıştı yeni bir gün,geceydi odadaki tek kör, Eşsizdi gözleri,beş buçuğu vuran saatse baş aktör! Başlamıştı yeni bir gün,bahardı dışarda ...', ARRAY['Türk Edebiyatı','Şiir','Selim Omala']::text[], 8.5, '{"poet":"Selim Omala","poet_slug":"selim-omala","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bebis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk', 'yokluk-suat-akyuz-b14x7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zamanın  karmasık davasında kalbın

gunlerın cekılmez sabahında gozlerın

sana  acı cektirip aglatıyorsa 

sevdanı bosver unut gıtsın...', 'zamanın  karmasık davasında kalbın gunlerın cekılmez sabahında gozlerın sana  acı cektirip aglatıyorsa  sevdanı bosver unut gıtsın......', ARRAY['Türk Edebiyatı','Şiir','Suat Akyüz']::text[], 8.5, '{"poet":"Suat Akyüz","poet_slug":"suat-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yokluk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümle Gelen Yalnızlık', 'olumle-gelen-yalnizlik-oznil-avcioglu-2pfbj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakıyorum etrafa

Hiçbirşey yok

Boş... Bomboş...

Dört dönüyorum çevremde

Dört duvar görüyorum

Haykırıyorum, bağırıyorum

Cevap veren yok.

Yok.. Hiç kimse yok..

Yalnızlığımın hücresindeyim.

Müebbet hapislerde,

Müebbet muhabbetlerde

Kendimle...

Af çıksın diye bekliyorum

Bekliyorum ama çıkmıyor.

Sıkılıyorum, çok sıkılıyorum.

Ebediyen yitirdiğimi hissediyorum dostluklarımı

Beraberinde mutluluklarımı.

Herkes gitti

Bir ben kaldım yalnız.

Annem geliyor yanıma

Konuşuyor, ağlıyor, anlatıyor..

Cevap veriyorum duymuyor

Bağırıyorum duymuyor.

Dostlarıma geliyorlar yanıma

Çiçek veriyorlar bana

Kokluyorum

Kokusunu içime dolduruyorum.

Kapkaranlık bir kuyudayım.

Üzerime toprak döktüler

Başucuma ıhlamur diktiler

Beni yalnızlığa mahkum ettiler.

(06 Mayıs 2000)', 'Bakıyorum etrafa Hiçbirşey yok Boş... Bomboş... Dört dönüyorum çevremde Dört duvar görüyorum Haykırıyorum, bağırıyorum Cevap veren yok. Yok....', ARRAY['Türk Edebiyatı','Şiir','Öznil Avcıoğlu']::text[], 8.5, '{"poet":"Öznil Avcıoğlu","poet_slug":"oznil-avcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/olumle-gelen-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-oznil-avcioglu-vkdq1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duvarlara yazmıştım umutlarımı,

Tavana çizmiştim sevgiyi.

Başucumda 20. sayfasında kaldığım 

Ve asla tamamlayamayacağım kitabım.

Tavan şimdi yok;

Üst kattaki komşunun bebeğiyle yanyanayım

O hayata gözlerini daha açamadan kapamış.

Umutlarımı yazdığım duvarlar,

Meğer gerçekten kağıttanmış.

Geriye kala kala bir tek

Okunmamış kitabım kalmış:

''Sevgili Arsız Ölüm''!!!

(30 Ağustos 1999)', 'Duvarlara yazmıştım umutlarımı, Tavana çizmiştim sevgiyi. Başucumda 20. sayfasında kaldığım  Ve asla tamamlayamayacağım kitabım. Tavan şimdi...', ARRAY['Türk Edebiyatı','Şiir','Öznil Avcıoğlu']::text[], 8.5, '{"poet":"Öznil Avcıoğlu","poet_slug":"oznil-avcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deprem-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakıncasız', 'sakincasiz-metin-eloglu-w1hgh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kuş tüyüne değip de

berelenmeden

Bir güz yelinde örselenmeden hiç

Çayırın acı yeşillerine uğramaksızın

Hırpalanmadan günışığında

Papatya kokularıyla ırgalanmadan

Sen yine orda mısın demeden

Sen hala

Sen hala gel demeden

Geliyorum ben sana', 'Bir kuş tüyüne değip de berelenmeden Bir güz yelinde örselenmeden hiç Çayırın acı yeşillerine uğramaksızın Hırpalanmadan günışığında Papatya...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin-eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sakincasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Özlem', 'gozlerine-ozlem-gokhan-yuksel-8xar3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerini ne zaman saymaya kalksam

hep bir eksik kalır hiç doyamam.

Tamamlayamam gözlerini gözlerimde.

Masamda sen yoksun ya

masamda yok

gözlerimle tamamlayamadım ya seni

hayallerimde yok.

Oysa ben bilirdim seni bir güzel tamamlamayı

eksik ve yalnız saatlerime

ama gözlerin yok...

Gözlerin

Balım

Bebeğim

Sen yoksun ya

O çok sevdiğim gecelerim de yok

sen yoksun ya

o çok sevdiğim gülüşün de yok

özledim seni

özledim kucaklayışımı seni

bütün yıldızlarını toplasam evrenin;

sığmayan kollarımda.

Seni seviyorum demek

sen hayatsın demek

hayatımsın demek

ruhumsun, amacımsın demek

ben yalnız saatlerimde

kuru bir ekmek yerim ya doymak için

senin yokluğun;

aç kalmışım demek

ben seni öyle sevmişim ki;

yokluğun cehennem demek...

ki ben cehennemden korkmadım hiç

senin yokluğun kadar.', 'Gözlerini ne zaman saymaya kalksam hep bir eksik kalır hiç doyamam. Tamamlayamam gözlerini gözlerimde. Masamda sen yoksun ya masamda yok göz...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Yüksel']::text[], 8.5, '{"poet":"Gökhan Yüksel","poet_slug":"gokhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gozlerine-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Zaman Aşığı', 'eski-zaman-asigi-oktay-rifat-0f0u4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben eski zaman aşığıyım

Sevda çeker düşünürüm ağlarım

Bazen tilki kadar kurnaz bazen akılsız

Bazen çocuk gibiyim bacak kadarım

Herkes aşık olur sevdalanır

Bir yolu var gönül çekmenin de

Benimki sevda değil ateşten gömlek

Bir kor düşmüş ışıl ışıl yanar içimde

Ama ben eski zaman aşığıyım

Sevmek kadar katlanmak da gelir elimden

Gece hayalimde gündüz fikrimde

Ela gözlü o yar çıkmaz gönülden', 'Ben eski zaman aşığıyım Sevda çeker düşünürüm ağlarım Bazen tilki kadar kurnaz bazen akılsız Bazen çocuk gibiyim bacak kadarım Herkes aşık o...', ARRAY['Türk Edebiyatı','Şiir','Oktay Rifat']::text[], 8.5, '{"poet":"Oktay Rifat","poet_slug":"oktay-rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eski-zaman-asigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıpları Oynuyor Hayat', 'kayiplari-oynuyor-hayat-deger-ulas-turan-niv7l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocuktu, anıları vardı hiç gülmediği... 

Ve zaman kanatıyordu, her gördüğünde düşlerini. 

Öyle masum ağlıyordu ki.. 

Düşsem yanaklarından, bir gül bahçesi, 

Dokunsam dudaklarına, çırpınan bir deniz oluyordu. 

Bir gün diyordu o

Mevsimine açamadan, 

Tazeliğinde saklıyordu kirlenmişliğini. 

Alkol mevsimlerinde hep hazanı oynuyordu... 

Yağmurları içtiği vakit karamsar gözlerinde, 

Karlar çoktan erimiş oluyordu. 

Hani, diyorum kim ağlatıyordu? 

Ellerinde kardelen tazeliğinde taşıyan bu çocuğu... 

Gökyüzü giyinmişti geceleri üstüne 

Ve yıldızlarla süslemişti soluk kalbini.

Bir yıldız diyordu

Ve orda buluyordu her şeyini. 

Bilir mi ki kapılarının da bir gün yıldız doldurulacağını. 

Ve kaçışan insanların bir sığınak güvenliğinde,

Kanayan şarkılarına sığınışını anlayabilir miydi? 

Yitirirken kendini, hep yeniden buluyordu cinnetini. 

Hayat, kafiyelerini toplamakta ve bir nakarat oluşmakta, 

Hep aynı kafiyeden sonra bir daha söylenmekte, 

İnsanların aynılığı gibi. 

Bir şarkı söylüyorsun ya; hep yeni sözlerin eklendiği 

Ve bir keman bestesi oluyor şimdi hayallerin. 

Şimdi, dudakların kanamıyor ve ellerin üşümüyor. 

Ve yollara düşmüyor hayallerin. 

Kendinle yalnızlığında, bir kitap gibisin 

Her sayfasında yeniden yeniden okunası. 

Sessizliğimse, bu şarkıların nakaratı olsun. 

Sen, öyle serin 

öyle şirin bak ki, 

Kendisinden utansın gecedeki yıldızlar. 

Sus ve dinle sessizliğin ağır ve aksak melodisini, 

Bak! Nasılda yıldız dolu...', 'Çocuktu, anıları vardı hiç gülmediği...  Ve zaman kanatıyordu, her gördüğünde düşlerini.  Öyle masum ağlıyordu ki..  Düşsem yanaklarından, b...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kayiplari-oynuyor-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakılıp Yırtılıyor', 'yakilip-yirtiliyor-deger-ulas-turan-64dzg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sözcük mü, dokunacak şimdi hayallerine? 

Sadece bir irkinti, yani duygularımız. 

Ve ölümsüzlüğünü vuruyor bir aşk, 

Aşklarına bir sözcük sığdıranlar, 

Geceler dolusu yıldız bırakanlar, 

Neredeydiler şimdi? 

Yalnızlık diyorum, orada bıraktık ya, 

Şimdi her şeyi, gözlerinde bırakıp... 

Yorumunu, duygularından alıyorum. 

Arının balını, Çiçeklerin özünden topladığından. 

Bir pusuda buluyorum kendimi. 

Arkasından koştuğum özlemlerinin; 

Kalleşliğinden kaçanların, 

Sığınağında buluyorum kendimi. 

Bir şarkı düşüyor şimdilerde dilime. 

Ve birden açıyorum gözlerimi, 

Kollarımda sayfalarımı görüyorum. 

Bakmıyorum bile ne olduklarına, 

Sadece yakıyorum.', 'Bir sözcük mü, dokunacak şimdi hayallerine?  Sadece bir irkinti, yani duygularımız.  Ve ölümsüzlüğünü vuruyor bir aşk,  Aşklarına bir sözcük...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yakilip-yirtiliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yine Yolculuğum', 'ben-yine-yolculugum-deger-ulas-turan-8vvhw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evet, dostlar gidiyorum bu şehirden

Aynı hayallerin küllendiği, başka bir şehre. 

Yazınsamaya, belki de bir hikâye bırakmaya, 

Ama unutamadığım bir tat kalıyor, dişlerim arasında. 

Renklerini anımsamıyorum acıların, 

Sadece yokluklarında kaybolmuş bir sessizlik 

Ve bu sessizliği okuyup susuyorum. 

Her susuşumda biraz siz kalıyorum, biraz öfke. 

Yinede aşkı bulursanız beni unutmayın, 

Bilemem bir aşkın kekre tadını, 

Ama hikâyesini çok iyi çıkarırım.', 'Evet, dostlar gidiyorum bu şehirden Aynı hayallerin küllendiği, başka bir şehre.  Yazınsamaya, belki de bir hikâye bırakmaya,  Ama unutamadı...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ben-yine-yolculugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahuzardayım Şimdi', 'ahuzardayim-simdi-deger-ulas-turan-mt4pt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerindeyim, öpülesiye

Bir çiçek gibi narin. 

Ve bir gül kokusu, tenimden geçiyor, 

Her bakışında. 

Geceyi siyaha, 

Tenini, kızıla boyalı saçlarında bıraktım kızımın. 

Cümle, gece olunca, 

Tutunmak istiyor bir dala. 

Uçuşamıyor, 

Gün kadar özgür, 

Bir kuş misali ürkek. 

Sessizliğimi alıp da koynuma, 

Gecelerde kayboluşum olur. 

Duvar olur, 

Her karanlığa bakışında suretim. 

Aynalarda geceleri, 

Bakışımla, suretin yalan olur. 

Sözlerim kalır dudaklarımda, 

Çıldırasıya çırpınan bir balık olur. 

Denizine kavuşamayan, 

Can olur. 

Ama şimdi ahuzardayım 

Ellerim alevinde, 

Tutuşur sonra, ne kalır. 

Değerlerini yitirirken sevdalar, 

Gözlerinde, bir acı renk kalır. 

Ve ben ki gözlerimle tutmuştum ellerinden, 

Geride iki çocuk, 

Birde aşk kalır. 

(Annem İçin)', 'Ellerindeyim, öpülesiye Bir çiçek gibi narin.  Ve bir gül kokusu, tenimden geçiyor,  Her bakışında.  Geceyi siyaha,  Tenini, kızıla boyalı s...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ahuzardayim-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi Rüzgar', 'asi-ruzgar-dragon-goksen-lru7r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey! asi rüzgar sen misin beni batıracak

Ne istersin ki benden 

Alacağını aldın zaten 

Ben ne fırtınalar gördüm ki

Senin rüzgarından sert ve asi

Onlarla başa çıkmasını bildim

Ne yapacaksın benim dostlarımla, arkadaşlarımla

Beni içerden mi batıracaksın 

Rüzgarın yetmedi dimi

Ama beni seven beni sayan yine benim yanımdadır

Bana inanmayan senin söylediklerinle hareket eden

Zaten benim arkadaşım değildir

Bir gün güvenmenin ne kadar önemli olduğunu anlarsan

O gün çok geç olmasın

Beni yalnız bırakırsan eline ne geçecek

Beni hala tanımıyorsun 

Beni seven böle seviyor zaten

Arkadaşlarımın yanında senden öncede vardım senden sonrada olacağım

Yalan olmuş hayatın 

Kaldı mı hayatında dürüstlük

Beni neden kaybettiğini sakın unutma

Bari benden sonrakilerle mutlu ol!!!', 'Ey! asi rüzgar sen misin beni batıracak Ne istersin ki benden  Alacağını aldın zaten  Ben ne fırtınalar gördüm ki Senin rüzgarından sert ve ...', ARRAY['Türk Edebiyatı','Şiir','Dragon Gökşen']::text[], 8.5, '{"poet":"Dragon Gökşen","poet_slug":"dragon-goksen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/asi-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hata', 'hata-mehmet-batihan-8jmbp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hatayı başkalarından yakalamak isterler,

hardal tanesi kadar ufak olsa bile,

işte böyle aşağılık kimseler, görmezler hatayı,

kendilerinde kocaman karpuz olsa bile.', 'hatayı başkalarından yakalamak isterler, hardal tanesi kadar ufak olsa bile, işte böyle aşağılık kimseler, görmezler hatayı, kendilerinde ko...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Batıhan']::text[], 8.5, '{"poet":"Mehmet Batıhan","poet_slug":"mehmet-batihan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hata-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aynadır', 'bir-aynadir-mahmut-shabistari-ly54q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bil ki bir aynadır dünya baştan sona.

Yüz güneş ışır her bir atomunda.

Yüz okyanus oluşur.

Parçalarsan bir damla suyu.

Baktığında bir kum tanesine.

Bir adamı görebilirsin

Bakarsan ayrıntılarına 

Fil gibi görünür sivrisinek

Nil''e benzer yağmur damlası

Bakarsan niteliklerine

İçinde yüzlerce harman taşır

Tek tahıl tanesi

Yerleşir bir damlanın özüne dünya

Bir yaşam okyanusu

Sivrisineğin kanadında

Bir cennet barınır gözünde insanın

Pek küçükse de özü tohumun

Burda durur iki dünyanın tanrısı', 'Bil ki bir aynadır dünya baştan sona. Yüz güneş ışır her bir atomunda. Yüz okyanus oluşur. Parçalarsan bir damla suyu. Baktığında bir kum ta...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Shabistari']::text[], 8.5, '{"poet":"Mahmut Shabistari","poet_slug":"mahmut-shabistari","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-aynadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Sofrası', 'sevgi-sofrasi-taner-akkan-2895u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçmek gerek üstünden bulutların 

görmek için gökyüzünü  masmavi.

kapatmak gerek gözlerini bazen,

duyabilmek için şarkısını baharın.

geçti nice yeni baharlar önceleri,

hesabını tutamazsın eski yılların.

mısralar ekleniyor mutluluk şiirine,

hayatı yaşamaktan böyle kaçamazsın.

küçük sevgi kırıntıları kuşlara göre,

ben sevgi sofrasında ziyafete oturmuşum.

yağmur ondan korkanlara çilesin,

bardaktan boşansın oysa benim üstüme...', 'Geçmek gerek üstünden bulutların  görmek için gökyüzünü  masmavi. kapatmak gerek gözlerini bazen, duyabilmek için şarkısını baharın. geçti n...', ARRAY['Türk Edebiyatı','Şiir','Taner Akkan']::text[], 8.5, '{"poet":"Taner Akkan","poet_slug":"taner-akkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgi-sofrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Tomurcuk', 'uc-tomurcuk-hamit-ketizmen-bdvih', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Esir olmuşum hayatın acılarına

İçimden koparıp atmak istesem bile

Yüreğime yapışmış çıkaramıyorum

        Bir sızı akıyor damarlarımdan

Bir sel gibi alıp götürüyor kendimden

Çocokluğumuzu yaşıyorum çocuklarımızda

Sen ve ben olduğu gibi.

    Bak ben ağlıyor muyum sen de ağlama 

hadi sil gözyaşlarını sil be gülüm

solmuş sararan üç gül idiysek

düşün ki yeni doğacak yarının güneşini kucaklarcasına

üç tomurcuk güller bekliyor.

    bizler geçmişin acılarını yüreğimize süpürmüşüz

sonra, sonra gülüm damla damla

şerbet niyetine içip yüreğimizde saklamışız

    geride kalan yarının güneşini bekleyen 

tomurcuklara hediye etmişiz

    onlar ki umutla bekledigimiz güneşi

sımsıkı sararak bizi biz edenler ve beklediğimiz tomurcuklar

üç gül olarak açmış olacaklar.

     ve biz onları göremeyecegiz,

onları koklayıp sevemeyeceğiz.

varsın bizler sevmeyelim be gülüm

    onlar ki açtıkları zaman ....

..bizi duyacaklar..

     .... bizi görecekler..

           .... kısacası onlar bizi çok özleyecekler.



                 08.05.2001', 'Esir olmuşum hayatın acılarına İçimden koparıp atmak istesem bile Yüreğime yapışmış çıkaramıyorum         Bir sızı akıyor damarlarımdan Bir ...', ARRAY['Türk Edebiyatı','Şiir','Hamit Ketizmen']::text[], 8.5, '{"poet":"Hamit Ketizmen","poet_slug":"hamit-ketizmen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uc-tomurcuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Sırası', 'olmek-sirasi-hamit-ketizmen-13k7h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'üzülme sen gardaş

gülmek sırası bizde

at içinden kötü korkuyu

mutlak güleceğiz elbette

ağlamakla sızlamakla çekilmez bu dünya

inanki gardaş gülmek sırası bizde

varsın acılar dayansın kapımıza 

    biz ki ağlıyorsak bu dünyada 

inan ki gardaş gülmek sırası bizde

    sen ol üzülme

bak yaşıyorlar geleceğimizi

ben ki gardaş herzaman yaşıyorum 

senin gibi

kim gülmüş ki biz de gülelim

inan ki gardaş ölmek sırası bizde', 'üzülme sen gardaş gülmek sırası bizde at içinden kötü korkuyu mutlak güleceğiz elbette ağlamakla sızlamakla çekilmez bu dünya inanki gardaş ...', ARRAY['Türk Edebiyatı','Şiir','Hamit Ketizmen']::text[], 8.5, '{"poet":"Hamit Ketizmen","poet_slug":"hamit-ketizmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olmek-sirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-ferruh-turgut-i-nal-k4iut', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şey  küçük  bir  tesadüf 

Yapılan  küçük  bir  gaf

Söylenen  bir  merhaba  birkaç  laf

Ve  atıldık  girift  bir  olaya  saf saf

İstemeden  kırdığım  kalpler  bini  aştı

Her şeyin  başı  küçük  bir  yanlış  anlayıştı

Söylenen  bir  merhabaydı  doldu   taştı

Talihsiz   başıma  bin  türlü  dertler  açtı

Sevdim de  açılamadım, anlatamadım korkaklığımdan

Kurtulamadım  başıma  bela  olan  kaygılarımdan

Bıktım  yaptığım  aptalca  davranışlarımdan

Ne  vazgeçebildim  canımdan  ne  de  cananımdan

Asıl  depremi ben  şimdi  yaşıyorum

Ruhumun  derinliklerine  yeni yeni faylar açıyorum', 'Her şey  küçük  bir  tesadüf  Yapılan  küçük  bir  gaf Söylenen  bir  merhaba  birkaç  laf Ve  atıldık  girift  bir  olaya  saf saf İstemede...', ARRAY['Türk Edebiyatı','Şiir','Ferruh Turgut İnal']::text[], 8.5, '{"poet":"Ferruh Turgut İnal","poet_slug":"ferruh-turgut-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/merhaba-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamıyorum', 'bulamiyorum-ozan-ezgini-kfpff', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık gecenin derinliğinde

Gördüğüm rüyayı yoramıyorum

Yıkıldı gönlümün binası viran

Ne kadar uğraşsam öremiyorum.

Duygularım birbirine karıştı 

Kötü kader hep benimle yarıştı

Garip başım her çileye alıştı 

Kör talih zincirin kıramıyorum.

Yüküm elmas değil mücevher değil

Alacak müşterim eyledi seyir

Yıllar yıla eder tesellim devir

Giden kervanımı göremiyorum.

Ozan EZGİNİ ,yim gönlüm yaralı.

Üst üste yığıldı dertler sıralı,

Ciğer param parça bahtım karalı.

Sağlık haberimi veremiyorum..

Ankara', 'Karanlık gecenin derinliğinde Gördüğüm rüyayı yoramıyorum Yıkıldı gönlümün binası viran Ne kadar uğraşsam öremiyorum. Duygularım birbirine k...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ezgini']::text[], 8.5, '{"poet":"Ozan Ezgini","poet_slug":"ozan-ezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bulamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ötesi', 'sen-ve-otesi-sitki-dursel-ejtk6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlık Tanrı ya mahsus

Göç eden kuşlara değil

Sırası gelip yeşeren dallara

Kabuğu içinde vuslat sayan

Kelebek larvalarına hiç değil

kısa olsada ömürleri

Ne sen ne ben

çizemeyiz kaderimizi

Sana ceza yaşamaksa

bir ömür boyu 

cevizlerin ve çimenlerin içinde

Bil ki banada cezadır 

büyük kentlerin insanı ürküten

korkulu titrek ve kederli 

gurbet geceleri

Ve artık sıyrılmışız kendimizden

fıtratımıza dönmüşüzdür

Ne sen beni umarsın artık

Ne de ben seni hayal ederim

Ve bir gülün kokusunda

aklıma sadece peygamber gelir

Sana yetecek ne sevda kaldı

ne de huzur

Yazılmışsa kaderde 

Mecnun leylasını

Kerem Aslısını

muhakkak bulur', 'Yalnızlık Tanrı ya mahsus Göç eden kuşlara değil Sırası gelip yeşeren dallara Kabuğu içinde vuslat sayan Kelebek larvalarına hiç değil kısa ...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Dürsel']::text[], 8.5, '{"poet":"Sıtkı Dürsel","poet_slug":"sitki-dursel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-ve-otesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giremedim Sarayıma', 'giremedim-sarayima-ozan-ezgini-ozjcq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Fukara eyledi bu talih beni

Duramadım sarayımda ben benim

Hem gece hem gündüz figan eğledim

Giremedim sarayıma ben benim.

Sevda rüzgârıydım yârin yelinden

Kötü kader hep çevirdi yolumdan

Dedim tutam nazlı yarin elinden

Giremedim sarayıma ben benim.

Talihim değişmez hem de kaderim

Ben saklandım beni buldu nedeyim

Eyyubun sabrı yok figan ederim

Giremedim sarayıma ben benim.

EZGİNİ;yim mecnun oldum gezerim.

Öttü sarı sazım telle söyledim

Gönül yaylasında yarla eğlendim

Giremedim sarayıma ben benim

Ankara.', 'Fukara eyledi bu talih beni Duramadım sarayımda ben benim Hem gece hem gündüz figan eğledim Giremedim sarayıma ben benim. Sevda rüzgârıydım ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ezgini']::text[], 8.5, '{"poet":"Ozan Ezgini","poet_slug":"ozan-ezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/giremedim-sarayima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülden İbret AL', 'gulden-i-bret-al-ozan-ezgini-6mupj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana nasihatım divana gönül

Leyla;dan Mecnun;dan, çölden ibret al.

Düşersen sevdaya sende yanarsın

Aslı;dan Kerem;den külden ibret al.

Deli gönlüm bir sevdaya bulaştı

Yıllar yılı ardın sıra dolaştı

Gemi gibi iskeleye ulaştı

Emeğim boşamı yoldan ibret al.

Ozan EZGİNI;yim fidandım daldım,

Güldürmedi felek gam ile doldum,

Daha yeşermeden sarardım soldum,

Laleden, sümbülden, gülden ibret al.

Ankara', 'Sana nasihatım divana gönül Leyla;dan Mecnun;dan, çölden ibret al. Düşersen sevdaya sende yanarsın Aslı;dan Kerem;den külden ibret al. Deli ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ezgini']::text[], 8.5, '{"poet":"Ozan Ezgini","poet_slug":"ozan-ezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gulden-ibret-al-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-ozan-ezgini-0amh9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşamdan akşama kara giymeyi

Ben sizden öğrendim karalı dağlar

Her esen rüzgara göğüs germeyi

Ben sizden öğrendim sıralı dağlar.

Çiğdemle çiçekle yeşille kaplı

Sarı çiçek giymiş yüzü mehraplı

Eksilmez üstünden hep duman kaplı

Ben sizden öğrendim pareyi dağlar

Çok özledim ta zirvene çıkmayı

Yükseğinden bizim ele bakmaya

Bazen dertli dertli ağıt yakmayı

Ben sizden öğrendim yaralı dağlar.

EZGİNİ yim güle gönül vermeyi

Çeşit çeşit çiçeklerin dermeyi

Her mevsimde ayrı renge girmeyi

Ben sizden öğrendim aralı dağlar.

Ankara.', 'Akşamdan akşama kara giymeyi Ben sizden öğrendim karalı dağlar Her esen rüzgara göğüs germeyi Ben sizden öğrendim sıralı dağlar. Çiğdemle çi...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ezgini']::text[], 8.5, '{"poet":"Ozan Ezgini","poet_slug":"ozan-ezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/daglar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Değil', 'sahte-degil-turgut-yuca-stjod', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirim kolay değil yürümek 

Sahte uçurumlarda

Sahte olduğunu bile bile

Düşmemek için dikkatlice;

Sahte düşlerde görünmek

Bilirim oda kolay değil,

Yalan bir dünyada 

Amaçsızca görünmek

Aldığım nefesler sahte değil;

Biliyorum; yalnız o değil

Peki sen biliyormusun?

Ben de sahte değilim...', 'Bilirim kolay değil yürümek  Sahte uçurumlarda Sahte olduğunu bile bile Düşmemek için dikkatlice; Sahte düşlerde görünmek Bilirim oda kolay ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sahte-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avusturalya Mektubu', 'avusturalya-mektubu-ozan-ezgini-18bqq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'EZGİNİ,Yedi yıldır hasret kaldım kuzuma

Bir mektup gönderde bakam yazına

Ayrılık hasreti vardır kuzumda

Türkiye`den sonsuz sevgiler oğul.

Yeter oğul yandım hasret narına

İsterim kuş olam gelem yanına

Canım feda olsun gül cemaline

Türkiye den sonsuz sevgiler oğul.

Hasret kaldım gözlerine, yüzüne

Bağlar gazel döktü ömrüm gözünde

Hayran kaldım kelamına sözüne

Türkiye den sonsuz sevgiler oğul.

Zalim Avustralya bağladı seni

Güzel bu vatanım cennet her yeri

Dilerim dokunmaz sana sam yeli

Türkiye den sonsuz sevgiler oğul.

Mevsim temmuz ayı havalar sıcak

Selamlar dolusu sar kucak kucak

Güzel mektup Avustralya ya varacak

Türkiye den sonsuz sevgiler oğul.

Ozan EZGİNİ nin gönül dağında

Hasretlik gülleri açtı bağında

Ne cefalar çekti gençlik çağında

Türkiye den sonsuz sevgiler oğul.

Ankara', 'EZGİNİ,Yedi yıldır hasret kaldım kuzuma Bir mektup gönderde bakam yazına Ayrılık hasreti vardır kuzumda Türkiye`den sonsuz sevgiler oğul. Ye...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ezgini']::text[], 8.5, '{"poet":"Ozan Ezgini","poet_slug":"ozan-ezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/avusturalya-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Feda', 'canim-feda-ozan-ezgini-0gy8q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tabiatla insan iç içe yaşar

Hoşgörü yolunu açalım dostlar

Dürüst olmayanlar yolundan şaşar

Hoşgörü yolunu açalım dostlar.

xxx

Sevgi pınarında sular durulur

Cahil insan birbirine kırılır

Ermiyor aklımız mantık yorulur

Hoşgörü yolunu açalım dostlar.

xxx

Birlikte yaşarız hep kardeş bacı

Bizleri yaşatır sevginin gücü

Cömerttir tabiat verir ilacı

Hoşgörü yolunu açalım dostlar.

xxx

Canım feda olsun mert oğlu merde

Hal ehli dost için geçerim serde

EZGİNİ der nifak sormayın ferde

Hoşgörü yolunu açalım dostlar.

xxx

Ankara.', 'Tabiatla insan iç içe yaşar Hoşgörü yolunu açalım dostlar Dürüst olmayanlar yolundan şaşar Hoşgörü yolunu açalım dostlar. xxx Sevgi pınarınd...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ezgini']::text[], 8.5, '{"poet":"Ozan Ezgini","poet_slug":"ozan-ezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/canim-feda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Figan Bana Düştü Zar Bana ,Düştü', 'figan-bana-dustu-zar-bana-dustu-ozan-ezgini-6lwsz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vatan özlemiyle her gün yanarken,

Hasret bana düştü nar bana düştü,

Anlayan yok gurbet elde hallerim,

Figan bana düştü zar bana düştü.

xxx

Sıla özlemiyle yandı dillerim,

Kambur felek ters düşürdü yollarım,

Has bahçede soldu açan güllerim,

Diken bana düştü har bana düştü.

xxx

Hasret yığın yığın dertler sıralı,

Yıllar beni böyle koydu yaralı,

Karlı dağ misali başım pareli,

Dolu bana düştü kar bana düştü.

xxx

Şad olup gülmedim her gün yastayım,

Sıla hasretiyle bur da hastayım,

EZGİNİ; yim gönül yapan ustayım,

Bina bana düştü şar bana düştü.

xxx

08/05/1999

Ankara', 'Vatan özlemiyle her gün yanarken, Hasret bana düştü nar bana düştü, Anlayan yok gurbet elde hallerim, Figan bana düştü zar bana düştü. xxx S...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ezgini']::text[], 8.5, '{"poet":"Ozan Ezgini","poet_slug":"ozan-ezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/figan-bana-dustu-zar-bana-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün...', 'gulusun-turgut-yuca-rsnxa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülüşün...

O ağlamaklı,

O sırıl, o sıklam;

O iç eğriten gülüşün.

Nasıl olduğunu biliyormusun?

Gözlerin nasıl güler ıslanırken sen,

Her çığlığında kahkahanın,

Bir kez daha ağlayışın.

İçime doldurduğun kuşkuyla 

Nasıl sevinirsin biliyormusun?

Evlerin önünde oynayan çocuklar gibi,

Sesin yankılanıyor kulaklarımda.

Gülüşün seni tarif ediyor kulaklarıma,

Bir kez daha ıslanıyor görüntü,

Bulanıklaşıyor artık

Silindiğin akşam sefalarında;

Soldu rengin karanlığında

Gülüşün renk vermiyor artık;

Gökyüzü daha pastel 

Acılarım daha parlak artık

Gülüşün...

Artık çınlamıyor kulaklarımda

Sesin cezbetmiyor sesimi

Kalan bir avuç kül;

Yakmıyor artık içimi...', 'Gülüşün... O ağlamaklı, O sırıl, o sıklam; O iç eğriten gülüşün. Nasıl olduğunu biliyormusun? Gözlerin nasıl güler ıslanırken sen, Her çığlı...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gulusun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halk Ozanları', 'halk-ozanlari-ozan-ezgini-bczt6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ozan demek şair demek saz demek

Yaşar gönüllerde halk ozanları

Gönül birleştirir rûz-i mahşerde

Yaşar gönüllerde halk ozanları

xxx

Mertliği savunur namerde dönmez

Hayine uyupta vatanı bölmez

Ozan sevdalıdır kibirli olmaz

Yaşar gönüllerde halk ozanları

xxx

Birliğe çağırır sohbette sözde

Söyler geleneğin milletçe özde

Anlatır sevgiyi türküde sazda

Yaşar gönüllerde halk ozanları

xxx

Birimiz bin olduk toplandık burda

Gönül kovanından bal yaptık yurda

Lezzeti dağıttık perdede, telde

Yaşar gönüllerde halk ozanları

xxx

Arayıp sevgiyi huzuru bulan

Halkının önüne kılavuz olan

Ozan EZGİNİ;yim eylemen yalan

Yaşar gönüllerde halk ozanları.

Ankara.', 'Ozan demek şair demek saz demek Yaşar gönüllerde halk ozanları Gönül birleştirir rûz-i mahşerde Yaşar gönüllerde halk ozanları xxx Mertliği ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ezgini']::text[], 8.5, '{"poet":"Ozan Ezgini","poet_slug":"ozan-ezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/halk-ozanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buyur Usta', 'buyur-usta-i-brahim-sadri-04jky', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oğlum, onüç-ondört anahtarı ver 

Al usta 

Oğlum, yat motorun altına 

Nesi var bir bakıver 

Olur usta 

Oğlum, iyi sık civatayı 

Sonra sahibi neder? 

Sıkıyorum usta 

Bileğim yettiğince 

Yüreğim yettiğince 

Sıkıyorum işte 

Oğlum, terlemişsin 

Akmasın terin motora 

Motor pas yapar sonra 

Olur mu be usta 

Ter pas yapar mı 

Gözyaşı pas yapar mı? 

Oğlum ne diyorsun bak işine 

Bakıyorum usta 

Yalnız ellerim 

Ellerim çatlamış be usta 

Ellerim acı içinde 

Yüreğim var ellerimde 

Yüreğim yanıyor usta 

Kan ter içinde. 

Hem usta 

Sen hiç misket oynadın mı sokakata? 

Sen hiç okula gittin mi okula? 

Okul nasıl bir şey be usta 

Öğretmen nasıl biri? 

Usta sahi 

Orda da motor baktırırlar mı ki? 

Orda da söverler mi çocuklara be usta? 

Orda da döverler mi? 

Oğlum bak işine ! 

kızdırma beni. 

Olur usta . 

ha usta, 

Senin anan da saçlarını okşar mıydı? 

Sana ağlar mıydı gecenin al yalazında? 

Sahi usta sen hiç ağladın mı bir sabah 

Cansız düşende anan 

Yavaşca gözlerinin önünde?! 

Oğlum bak işine ! 

Attırma tepemi 

gir motorun altına 

Usta dur kızma! 

Bak giriyorum motorun altına 

Dünyanın altına 

Giriyorum usta giriyorum 

Desteğe gerek yok usta 

Desteğe gerek yok 

Ben oraya yüreğimi koyuyorum 

İnan taşır be usta', 'Oğlum, onüç-ondört anahtarı ver  Al usta  Oğlum, yat motorun altına  Nesi var bir bakıver  Olur usta  Oğlum, iyi sık civatayı  Sonra sahibi ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadri']::text[], 8.5, '{"poet":"İbrahim Sadri","poet_slug":"i-brahim-sadri","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/buyur-usta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Değilim', 'yalniz-degilim-ali-osman-yilmaz-c8uke', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırakıp giderken düşünme beni

Gönlümde sızın var yalnız değilim

Sensizlikten korkmam eskisi gibi

Kalbimde hüznün var yalnız değilim

Dünyama izinsiz dönme bir daha

Arzulamam seni girme rüyama

Sensiz güneş yine doğar sabaha

Tenimde izin var yalnız değilim

Kokumu özleme gördüğün gülde

Bir resmim bir anım kalmasın sende

Silinmeyen bir iz bıraktın bende

Alnımda yazın var yalnız değilim', 'Bırakıp giderken düşünme beni Gönlümde sızın var yalnız değilim Sensizlikten korkmam eskisi gibi Kalbimde hüznün var yalnız değilim Dünyama ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalniz-degilim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Baksam Ki Gelmişsin', 'bir-gun-baksam-ki-gelmissin-yavuz-bulent-bakiler-i5kox', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün baksam ki gelmişsin.. 

Bir güvercin gibi yorgun uzaklardan yar. 

Gözlerinde bir bitmez,bir tükenmez güzellik 

Saçlarında ilkbahar.. 

Bir gün baksam ki gelmişsin... 

Gülüşünde taze serin bir rüzgar 

Ellerin yine eskisi kadar güzel 

Çiçek açmış dokunduğun bütün kapılar... 

Bir gün baksam ki gelmişsin... 

Hasretin içimde sonsuzluk kadar. 

Şaşırmış kalmışım birdenbire çaresiz. 

Dökülmüş yüreğime gökyüzünden yıldızlar. 

Bir gün baksam ki gelmişsin.. 

Ne yüzünde bir gölge, ne dilinde sitem var. 

Tozlu pabuçlarını gözlerime sürmüşüm 

Benim olmuş dünyalar...', 'Bir gün baksam ki gelmişsin..  Bir güvercin gibi yorgun uzaklardan yar.  Gözlerinde bir bitmez,bir tükenmez güzellik  Saçlarında ilkbahar.. ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-baksam-ki-gelmissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibritçi Kız', 'kibritci-kiz-filiz-beduk-uc1rv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendine çıkar bu sokak 

ağır bir taş gibidir ağzında yalnızlık

çarpar ve düşer zaman

kanadı kırılarak

Kuytusuna eski bir evin

küçük bir kız düşer masallardan

yüreği titrek  kibrit yalımlarında annesiyle buluşan

Yüksek ökçesiyle salınan sarışın bir şiirdir şimdi gökyüzü

saçları akasyalı akşamın sularında

Beni saymazsan kimse bilmez burada 

temmuz saatlerini karlı akşamların

gelinlik badem ağaçlarını

arsız duruşlarını kozalakların

Beni saymazsan,kimse tanımaz beni

gözleri hep yıldızlara dönük 

bu kimsesiz sokakta....', 'Kendine çıkar bu sokak  ağır bir taş gibidir ağzında yalnızlık çarpar ve düşer zaman kanadı kırılarak Kuytusuna eski bir evin küçük bir kız ...', ARRAY['Türk Edebiyatı','Şiir','Filiz Bedük']::text[], 8.5, '{"poet":"Filiz Bedük","poet_slug":"filiz-beduk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kibritci-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-tolga-baydar-4co9g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elveda demek kolay olmadı inan

Gönlümde derin bir acı ile gidiyorum

Canım sevgilim birtanem ruhum

Sana ben derdimi anlatamıyorum

Çok çabaladım idare ettim olmadı

Ton üstüne ton bindi yüreğim kaldıramadı

Her nefes alışımda içime dolan sevgin

Ayrılık rüzgarı estiğinde engel olamadı

Seni sevdim ta içten derinden

Fasıllar okudum sana nefesimden

Bir gül bahçesinde bile yürürken

Almamıştım o zevki senden aldığım zevkten

Ne oldu da sonumuz böyle oldu

Suçlu aramak yakışmaz zaten olan oldu

Her günüm her saatim her anım seninle

Ruhum tarumar bedenim bitap oldu

Mutluluk diliyorum sana ömründe

Aşk ile geçen o günleri dizin dibinde

Umarım unutmazsın benimle geçen günleri

Senden kalan bir parça her zaman yüreğimde....', 'Elveda demek kolay olmadı inan Gönlümde derin bir acı ile gidiyorum Canım sevgilim birtanem ruhum Sana ben derdimi anlatamıyorum Çok çabalad...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elveda-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lal Masalımın Lal Kahramanına', 'lal-masalimin-lal-kahramanina-ayse-asuman-karaca-qsmu4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerinin yeşilinde

nehirlerin buğusuyla dans ettiğim

küçük çocuk...

yıka yıka öğreneceksin

yıkılmayı...

ve çook büyüdüğünde anlayacaksın

aradığın şeyin

aslında uzun zaman önce

yitirdiğin şey olduğunu...

hayat bu kadar acımasız işte...

gözlerinin yeşilinde

çığlık çığlığa yağan yağmurda ıslandığım

küçük çocuk...

gerçekleri görmemek için

gözerleri kapatmak  yetmiyor kimi zaman...

yüreğin bir mandalın arasında

sıkışıyor gibi hissettiğinde

çocuk kalbindeki dayanılmaz acıya

göğüs gerebilecek misin acaba? 

gerçekten büyüdüğünde

bu korkunç acılar bizi büyüttüğünde

ne olacak diye düşündün mü hiç? 

geri dönmek istemenin o karşı konulmaz kokusu...

kokladıkça baştan çıkacaksın

yüreğindeki yaradan her gün

daha fazla kan akacak...

gözlerinin yeşilinde

umarsızca İstanbul''u yaşadığım

küçük çocuk...

artık İstanbul yok benim için

balkonumdan görünen deniz mavi değil

dünyanın en büyük tanker kazasına

sahne oluyor bu şehir

her bakışımda beni farklı

dünyalara götüren Galata Kule''sinden

atlamak istiyorum şimdi

ayaklarımın dibindeki o karanlık boşluğa...

Zamana bu kadar çabuk mu yenildik çocuk? 

Gözlerinin yeşilinde

Uçmayı öğrendiğim

küçük çocuk...

kül rengi kanatlarımın altından

gördüğüm rengarenk dünyaya ne oldu? 

her yer neden karanlık çocuk? 

yaşadığım sabahı olan bir gece mi? 

yoksa yüreğimin gözleri mi kör oldu? 

gözlerimi kapatıyorum bazen

gelse diyorum...

yıkıntıların arasından bir çocuk yüzü

''merhaba'' dese...

tutsa elimden çekip çıkarsa

kaldırsa bu enkazı üzerimden...

acaba o gücü bulabilir miyim kendimde çocuk? 

yeniden seninle bir dünya kurabilir miyim? 

sen benim yüreğimi bilmezsin çocuk...

sana ''canımsın '' dedim inanmadın

oysa şimdi çürüyor etlerim...

gözlerinin yeşilinde

zamanı unuttuğum

küçük çocuk...

şimdi bütün kulağım tik taklarda...

burnuma sürdüğün traş köpüğü kadar

çabuk tükendik çocuk

mutluluklar bu kadar uçucuymuş meğer

ve acılarım civa kadar yoğun

kanımın dibine çöktüler şimdiden...

gözlerinin yeşilinde

benliğimi bulduğum

küçük çocuk...

dünyam seninle anlam kazanmıştı

oysa şimdi yitirişler içinde

herşey

ANLAMSIZ...', 'gözlerinin yeşilinde nehirlerin buğusuyla dans ettiğim küçük çocuk... yıka yıka öğreneceksin yıkılmayı... ve çook büyüdüğünde anlayacaksın a...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Asuman Karaca']::text[], 8.5, '{"poet":"Ayşe Asuman Karaca","poet_slug":"ayse-asuman-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/lal-masalimin-lal-kahramanina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ayse-asuman-karaca-v6o2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen...

İçimde her daim kanayan bir yara

ve gözlerin

meydanlara ekilen japon menekşelerinden

daha güzel bir çiçek

çocuk saflığında izliyor dünyayı

gülünce sadece dudaklarından değil

gözlerinden okunuyor tebessümler

ve ben isterim ki

bir kere öpeyim o gözlerden

Alnının sol tarafında mevzilenmiş

bir damar...

kanın içinden nasıl delice aktığını

bile görebiliyorum sanki

hayallerimde

ki bu bile yasak bazen bize

ellerim alnının sol tarafında dolanıyor

ezberlemek istiyor parmak uçlarım

her, herbir kıvrmını

ve artık sen, benim damarlarımda akıyorsun

naklediliyorsun bir hücremden diğer hücreme

Her türkü söylenişinde bu memlekette

halay çeken kalabalığın içinde

ellerini arıyor ellerim

sıcaklığınla tepeden tırnağa titremek

Sen...

evet herkesi seven sen...

bu kadar zor mu

beni sevmek?', 'Sen... İçimde her daim kanayan bir yara ve gözlerin meydanlara ekilen japon menekşelerinden daha güzel bir çiçek çocuk saflığında izliyor dü...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Asuman Karaca']::text[], 8.5, '{"poet":"Ayşe Asuman Karaca","poet_slug":"ayse-asuman-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sen-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-ayse-asuman-karaca-k5t3b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüm...

Tatlı bir düş..

Serseri bir kurşunu arzuluyorsa da bedenim

Ben ölüme gidecek kadar korkak değilim

Yenilmedim göreceksiniz

Bu keder öldüremez beni

Ben

Çıldırasıya mutluyken ölmek isterim', 'Ölüm... Tatlı bir düş.. Serseri bir kurşunu arzuluyorsa da bedenim Ben ölüme gidecek kadar korkak değilim Yenilmedim göreceksiniz Bu keder ö...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Asuman Karaca']::text[], 8.5, '{"poet":"Ayşe Asuman Karaca","poet_slug":"ayse-asuman-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '160 Karakter', '160-karakter-reis-mert-q33ga', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kucak dolusu yağmurlar versem sana 

adına yakışır mevsimde nisan kadar çok sevsem

gökkuşakları vaaddetsem gözlerimde

ellerimde toprağın kabul eden yanı

fikrinde güneş sıcağı

ben seni bekliyorum 

tanımadığım seslerde çöl rüzgarı.

hes...', 'kucak dolusu yağmurlar versem sana  adına yakışır mevsimde nisan kadar çok sevsem gökkuşakları vaaddetsem gözlerimde ellerimde toprağın kabu...', ARRAY['Türk Edebiyatı','Şiir','Reis Mert']::text[], 8.5, '{"poet":"Reis Mert","poet_slug":"reis-mert","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/160-karakter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
