INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bu Şehir Yetim Kalır', 'sensiz-bu-sehir-yetim-kalir-mustafa-yildiz-2-dldjm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sensiz

bu şehir yetim kalır

leylekler yuva yapmaz bacaya

çaylar dem tutmaz

kızlar kına yakmaz ellerine

sensiz

mesai başlamaz 8.30''da

bahar gelmez dağlara

ajanslar haber geçmez

şeker yemez çocuklar

sensiz 

bu şehir yetim kalır

anlıyormusun', 'sensiz bu şehir yetim kalır leylekler yuva yapmaz bacaya çaylar dem tutmaz kızlar kına yakmaz ellerine sensiz mesai başlamaz 8.30''da bahar g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız 2']::text[], 8.5, '{"poet":"Mustafa Yıldız 2","poet_slug":"mustafa-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sensiz-bu-sehir-yetim-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Ey Sevgili', 'sevgili-ey-sevgili-mustafa-yildiz-2-immkz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Alemlere rahmet olan efendimize...''

duy beni sana geldim

sevgili

ey sevgili

ruzigar-ı seher ile

bu kutlu mekana geldim

sevgili

ey sevgili

terkettim ben ki beni

ve dahi ins-ü cinni

sevdan ile ey sevgili

belde-i aşiyan''a geldim

sevgili

ey sevgili

duy beni sana geldim

bıraktım her bir şeyi

yürüdüm yalın ayak

mecnun görse acırdı

gör ki ne hale geldim

sevgili

ey sevgili

duy beni sana geldim

ne dünüm kaldı benim

ne yarınım var şimdi

sildim attım zamanı

sevgili ey sevgili

mebde-i an''a geldim

duy beni sana geldim

terk edip ırmakları

bir sonsuz ummana geldim

sevgili

ey sevgili', '''Alemlere rahmet olan efendimize...'' duy beni sana geldim sevgili ey sevgili ruzigar-ı seher ile bu kutlu mekana geldim sevgili ey sevgili t...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız 2']::text[], 8.5, '{"poet":"Mustafa Yıldız 2","poet_slug":"mustafa-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevgili-ey-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzinsiz Ölüm', 'i-zinsiz-olum-mustafa-yildiz-2-fp3vx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biliyorum

izinsiz öldüm

özür dilerim

tüm devlet büyüklerinden', 'biliyorum izinsiz öldüm özür dilerim tüm devlet büyüklerinden...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız 2']::text[], 8.5, '{"poet":"Mustafa Yıldız 2","poet_slug":"mustafa-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/izinsiz-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbrahim''in Elleri', 'i-brahim-in-elleri-mustafa-yildiz-2-belqq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ibrahim

ödünç istiyorum senden

put kıran ellerini', 'ibrahim ödünç istiyorum senden put kıran ellerini...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız 2']::text[], 8.5, '{"poet":"Mustafa Yıldız 2","poet_slug":"mustafa-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ibrahim-in-elleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halepçe', 'halepce-mustafa-yildiz-2-1u5rq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'payımıza direnmek düştü yine

ve ölmek yeniden

kimyasal ölümler kuşandık

doğmamış bebeler adına

bilinsin için dostum

bilmesi için dünyanın

ölüm

bir bildiri okumak kadar doğal

bir söylev kadar etkileyicidir

günün orta vaktinde

halepçe''de

şimdi

hasret bir bebe çığlığıdır

ölüm bir çöl rüzgarı

alan götüren uzaklara

yakılan ağıtları

ve sarsan saraylarını zulmün

waşington''da

telaviv''de

bağdat''ta', 'payımıza direnmek düştü yine ve ölmek yeniden kimyasal ölümler kuşandık doğmamış bebeler adına bilinsin için dostum bilmesi için dünyanın öl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız 2']::text[], 8.5, '{"poet":"Mustafa Yıldız 2","poet_slug":"mustafa-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/halepce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü', 'dogum-gunu-guvenc-gonlugenc-uatgl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anneciğim,

Hatırlarmısın

Sünnet Düğünümde sana ne sordum?

''Anneciğim,

Ben ne zaman doğdum?''

''Canım Oğlum,

Sen Harman Ayında doğdun.

Sonuncu çocuğum oldun.

Herneyse geçmişi unut,

Gelecekte umut.

Bugün sünnet oldun,

Yarın adam olacaksın.

Günlerden bir gün

Tatlı sözlü, güler yüzlü,

Bilgili, görgülü,

Ağırbaşlı, uzun saçlı,

Pamuk elli, ince belli

Bir kız bulacaksın.

Benim seni sevdiğim gibi

Sende onu seveceksin.

O zaman yeniden doğacaksın.'' 

Anneciğim,

Bugün, Ben çok mutluyum.

Çünkü, Ben yeniden doğdum.

Söylediğin gibi bir kız buldum.

Senin beni sevdiğin gibi

Bende onu seviyorum.

Sen bana ninniler söylerdin,

Ben ona şarkılar söylüyorum,

Sen bana meyveler verirdin,

Ben ona çiçekler veriyorum.

Anneciğim.

Bugün, Ben çok mutluyum.

Çünkü, Ben yeniden doğdum.

Seni sayacak, seni sevecek,

Sana torunlar verecek bir kız buldum.', 'Anneciğim, Hatırlarmısın Sünnet Düğünümde sana ne sordum? ''Anneciğim, Ben ne zaman doğdum?'' ''Canım Oğlum, Sen Harman Ayında doğdun. Sonuncu ...', ARRAY['Türk Edebiyatı','Şiir','Güvenç Gönlügenç']::text[], 8.5, '{"poet":"Güvenç Gönlügenç","poet_slug":"guvenc-gonlugenc","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dogum-gunu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Bir Tavla Oyunu', 'yasam-bir-tavla-oyunu-guvenc-gonlugenc-02tnh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşam bir tavla oyunu!

Bilirsen oynamasını,

Olursan şanslı,

Açıksa kapılar

Kazanırsın çifter çifter.

Bilsende oynamasını,

Olsanda şanslı,

Kapalıysa kapılar

Sayarsın aynı yerde.

Bilmezsen oynamasını,

Olmazsan şanslı,

Açık yada kapalıysa kapılar

Kaybedersin çifter çifter.

Yaşam bir tavla oyunu!

Bazen düşeşler dübeşler

Peşpeşe gelir,

Meydan senindir.

Çalda oyna.

Kazanırsın düyekle,

Kaybedersin dubarayla.

İyi öğren oynamasını.

Kapattırma kapıları.

Birazda cesur ol.

Bol şanslar!', 'Yaşam bir tavla oyunu! Bilirsen oynamasını, Olursan şanslı, Açıksa kapılar Kazanırsın çifter çifter. Bilsende oynamasını, Olsanda şanslı, Ka...', ARRAY['Türk Edebiyatı','Şiir','Güvenç Gönlügenç']::text[], 8.5, '{"poet":"Güvenç Gönlügenç","poet_slug":"guvenc-gonlugenc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yasam-bir-tavla-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekten mi?', 'gercekten-mi-guvenc-gonlugenc-20qio', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çizerim resim,

Değilim ressam.

Yazarım şiir,

Olduğumdan şair.', 'Çizerim resim, Değilim ressam. Yazarım şiir, Olduğumdan şair....', ARRAY['Türk Edebiyatı','Şiir','Güvenç Gönlügenç']::text[], 8.5, '{"poet":"Güvenç Gönlügenç","poet_slug":"guvenc-gonlugenc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gercekten-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekçinin Kızı', 'cicekcinin-kizi-guvenc-gonlugenc-qedvq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiçek gibi çiçekçinin kızı

Uçuyor sevincinden.

Çünkü,

Kimse çiçek vermemiş

Çiçekçinin kızına

Benden başka.', 'Çiçek gibi çiçekçinin kızı Uçuyor sevincinden. Çünkü, Kimse çiçek vermemiş Çiçekçinin kızına Benden başka....', ARRAY['Türk Edebiyatı','Şiir','Güvenç Gönlügenç']::text[], 8.5, '{"poet":"Güvenç Gönlügenç","poet_slug":"guvenc-gonlugenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cicekcinin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Doruğunda Dua', 'mutluluk-dorugunda-dua-guvenc-gonlugenc-fe2a2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Heyecanlı bir tırmanıştan sonra,

Dorukta iki sevgili

Ak bayrak çekmişler

En kutsal duygu sevgiye.

Gidilemez mutluluktan daha ileriye

Ve birlikte dua ediyorlar;

Bütün sevenler

Bizim gibi mutlu olsun diye.', 'Heyecanlı bir tırmanıştan sonra, Dorukta iki sevgili Ak bayrak çekmişler En kutsal duygu sevgiye. Gidilemez mutluluktan daha ileriye Ve birl...', ARRAY['Türk Edebiyatı','Şiir','Güvenç Gönlügenç']::text[], 8.5, '{"poet":"Güvenç Gönlügenç","poet_slug":"guvenc-gonlugenc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mutluluk-dorugunda-dua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın Yalnız Kaldığını', 'anlarsin-yalniz-kaldigini-selcuk-akcay-h2mey', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Söylenilmek istenen sebepsizliğe dökülünce,

Ölesiye sevgiler tüketilince,

Değerin yıldızlardan, yere serilince,

Anlarsın aslında yalnız kaldığını.

Önceleri bu sözler manasız gelir,

Esas sevgiyi arayınca yalnızlık belirir.

Ne zamanki duygular yere serilir,

Anlarsın aslında yalnız kaldığını.

Sevgi denilen o koskoca deniz,

Herkesi yüzeyde barındırmaz bedelsiz.

Sevdiğin seni terkederse nedensiz, 

Anlarsın aslında yalnız kaldığını.

Deli gönül, sevdiğin kalırsa sessiz, 

Sorunca bu haline derse sebepsiz,

İçine bir korku düşerse yersiz,

Anlarsın aslında yalnız kaldığını.', 'Söylenilmek istenen sebepsizliğe dökülünce, Ölesiye sevgiler tüketilince, Değerin yıldızlardan, yere serilince, Anlarsın aslında yalnız kald...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlarsin-yalniz-kaldigini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz yalnızlık kokar', 'sensiz-yalnizlik-kokar-selcuk-akcay-i595l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi sensiz yalnızlık kokar sokaklar

Uğramadığım mekanlardan biri artık onlar

Sensizliğin acısı içimi yaktığından beri

Gecelerce sabahladığım o sokaklar

Yalnızlığın büyüsü  hapsetmiş sevinçleri

Sanki bırakmış ebedi kederi

Sebepsiz çekip gittiğinden beri

Sensiz yalnızlık kokar sokaklar

Toprak rengi gözlerinmiş meğer

Onca hüznü sevince çeviren

Kaybolunca o gamzeli gülüşün

Belkide sebebidir üstüme çöken hüznün

                                         17.04.2001', 'Şimdi sensiz yalnızlık kokar sokaklar Uğramadığım mekanlardan biri artık onlar Sensizliğin acısı içimi yaktığından beri Gecelerce sabahladığ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sensiz-yalnizlik-kokar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçtim Sabahın Bütün Susuzluğunu', 'i-ctim-sabahin-butun-susuzlugunu-selcuk-akcay-txlvs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçtim sabahın bütün susuzluğunu,

Bülbüller ağlar halime ben gülüyorum.

Hissediyorum içten içe kuruduğumu,

Sanki sen varsın yanımda,hayal görüyorum.

Seni gördüm gece rüyamda,

Uyanınca anladım rüya olduğunu.

Bir sevinç oluştu hüzün dolu odamda,

Anladım sevginin ne demek olduğunu.

Gerçek sandım; boş yatakta dolaştı ellerim,

Bir boşluk hissettim, sinsice,

Çöl fırtınaları ile kurumuş bedenim

Ve ruhum sana yöneldi gizlice.

İçtim sabahın bütün susuzluğunu,

Penceremden seni gözledim.

Rüyalardaki yüz sildi umutsuzluğumu,

Ben sevdiğim o beyaz yüzü özledim.', 'İçtim sabahın bütün susuzluğunu, Bülbüller ağlar halime ben gülüyorum. Hissediyorum içten içe kuruduğumu, Sanki sen varsın yanımda,hayal gör...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ictim-sabahin-butun-susuzlugunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar yükselir', 'umutlar-yukselir-selcuk-akcay-0dzri', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umutlar yükselir

Umutlar yükseliyor göklerin maviliğinde,

Kuru bir bakış doğa sadeliğinde,

Yeşilleniyor yine gönlümün bahçelerinde,

Yeşilleniyor;güneş pareliğinde.', 'Umutlar yükselir Umutlar yükseliyor göklerin maviliğinde, Kuru bir bakış doğa sadeliğinde, Yeşilleniyor yine gönlümün bahçelerinde, Yeşillen...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/umutlar-yukselir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar I', 'aksamlar-i-selcuk-akcay-cm7yn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşam oldu,yine ızdırap.

Terk ediyor yeryüzünü güneşin ışıkları.

Dolduruverdi her yanı mehtap;

Büyülüyor yeryüzünde bütün aşıkları.

Boyun eğdi yeşiller karanlığın hezimetine,

İnsanlar yitirdi gölgelerini.

Kimi bakmaz gölgesinin esaretine,

Akşam kaplamış fikirlerini.', 'Akşam oldu,yine ızdırap. Terk ediyor yeryüzünü güneşin ışıkları. Dolduruverdi her yanı mehtap; Büyülüyor yeryüzünde bütün aşıkları. Boyun eğ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aksamlar-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...', 'sen-selcuk-akcay-vgpat', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O gamzeli gülüşün eksilmesin yüzünden,

Baharın cıvıltısı gitmesin gönlünden.

Sessizliğe boğulmuş bu yaz akşamları,

Durmadan yankılansın, o berrrak sesinden.

Yıldızlar bezesin kapkara saçlarını,

Gözlerin hep korusun hayat ışıltısını,

Üzüntüden kahrolduğum bu yaz akşamları, 

Güzel yüzün atsın içimdeki hüzün kırıntısını

Ellerin çiçeklere hayat versin, 

Ağaçları sallasın ılık nefesin.

Kuşlar cıvıldasın ipek saçlarında, 

Mevsimler seninle yaşansın.', 'O gamzeli gülüşün eksilmesin yüzünden, Baharın cıvıltısı gitmesin gönlünden. Sessizliğe boğulmuş bu yaz akşamları, Durmadan yankılansın, o b...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar II', 'aksamlar-ii-selcuk-akcay-bjwzi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamlar sıkıcı bir bulut gibidir;

Yağdırır keder damlalarını.

Akşamlar susuz bir çöl gibidir;

Viran eyler bütün yolcularını.

Üzerine çökünce akşam sisi,

Kapanıverir insanın gönül gözü,

Öyle sis ki söyletmez hiçbir sözü,

Dizer boğazına tıkayıverir.

Karanlık çökünce meydanlara,

Dağılır akşam gözler, semalara,

Dert üstüne dert yığar aşıklara,

Akşamın sesi bütün ağızları kapayıverir.', 'Akşamlar sıkıcı bir bulut gibidir; Yağdırır keder damlalarını. Akşamlar susuz bir çöl gibidir; Viran eyler bütün yolcularını. Üzerine çökünc...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksamlar-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Özlem', 'bir-baska-ozlem-selcuk-akcay-wlypu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oysa ne kadar isterdim beni sevmeni

Benle olup. Bende bütünleşmeni

Sevgisiz bir çocukken yalnızlığımda

Bakışlarınla beni yüreklendirmeni

Mutluluğun yalnızlığa terkedildiği akşamlarda

Sıcacık sohbetini arar gözlerim

Elbet gelirsin diye birgün, sevgimi anlarda

Senin yolunda durur, beklerim.

Oysaki ne kadar isterdim, beni bilmeni

Yalnız beni sevip beni düşünmeni

En umutsuz anlarımda

Karşıma çıkıp gülüvermeni.', 'Oysa ne kadar isterdim beni sevmeni Benle olup. Bende bütünleşmeni Sevgisiz bir çocukken yalnızlığımda Bakışlarınla beni yüreklendirmeni Mut...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Akçay']::text[], 8.5, '{"poet":"Selçuk Akçay","poet_slug":"selcuk-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-baska-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğa', 'dostluga-adil-koruyan-6d2d5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadehler dolu, kırmızı, sarı, beyaz,

İçme günüdür bugün, hiç fark etmez.

Güzel günler, geçmiş yaşanacak, 

Anılar tazelenecek, bir şişe yetmez.

Sevdiğin gün batımında başlayacak,

Sevdiğim sabah güneşinde son bulacak.

Gece boyunca dostluğa kalkacak eller,

Her yudumda sevginin yerini dostluk alacak. 

Günün ilk ışıklarında, sona yaklaşıldığında,

Bir şiir yankılanacak kulaklarında,

“Taş duvarlar biliyor, bir sen bilmiyorsun”

Dostluğa diyeceksin son kez, sevgi sarhoşluğunda.

26.05.2001', 'Kadehler dolu, kırmızı, sarı, beyaz, İçme günüdür bugün, hiç fark etmez. Güzel günler, geçmiş yaşanacak,  Anılar tazelenecek, bir şişe yetme...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dostluga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhasebe', 'muhasebe-bahaettin-karakoc-hod8j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Has bahçeyi sardı dikenle ayrık,

Ağa da, kâhya da başına buyruk.

Mukaddes ülküler ölü yatarken,

Herkesin koştuğu hep yağlı kuyruk! ...', 'Has bahçeyi sardı dikenle ayrık, Ağa da, kâhya da başına buyruk. Mukaddes ülküler ölü yatarken, Herkesin koştuğu hep yağlı kuyruk! ......', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/muhasebe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analar Ağlamasın', 'analar-aglamasin-nurten-altinok-cdstg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ankara Diyarbakır seferini yaparken şehit düşen 34 erimizin anısına

Analar ağlamasın da kimler ağlasın 

Davullu zurnalı

Asker uğurlama alaylarında

En büyük asker bizim asker

asker gidecek geri gelecek 

Nasılda çöküvermişti gözlerinden 

Bir kor ateş 

Ta bağrının ortasına 

Kor alev 

Yangın 

Acı feryatlar gibiydi 

Suskun 

Son defa sarılırken boynuna: 

- Aman ha oğul 

Sakın üşütme 

Sırtın açık kalmasın 

Ayağın yalın - 

Fısıldayıvermişti kulağına 

Sarılıvermişti sımsıcak 

Kucak dolusu 

Genizlerine kadar çektiği hala 

Dünkü bebeğinin kokusu 

Mis kokusu 

İçi titredi 

Avuçları terledi 

Yiğidim dedi 

Canım dedi 

Dudaklarından dökülen dua 

Vatan içindi 

Yapma anam dedi 

Üzme kendini 

Gider gelirim 

Vatan borcu 

Şunun şurası ne ki 

Sen değil miydin şarkılarında çoğu zaman 

Asker yolu beklediğin 

Günü güne eklediğin 

Sen değil miydin 

Vatan borcu can borcu dediğin 

Sen değil miydin ta ninnilerimde 

Asker oğlum diye sevdiğin 

Hudut kapılarını sen öğretmedin mi bana 

Sen öğretmedin mi bana 

Şehit düşecek kadar bu vatanı sevmeyi 

Bilirim hasret yakıyor içini 

Resimler gönderirim anam 

Selama durmuş askerin 

Çakı gibi 

Gururla duvarına asacağın 

Bağrına basacağın 

Gider gelirim tasalanma ana 

Kader bu ya 

Gazi olursam vatan uğruna 

Şehit düşersem 

Akarsa canım toprağa 

Sakın ağlama 

Hakkını helal et ana 

Helal et 

Gövdemi siper ettim 

Geçit vermem ne haine ne düşmana 

Anam 

Nöbetteyim şimdi kışlamda 

Nöbetteyim bir dağ başında 

Nöbetteyim bir sınır kapısında 

Nöbetteyim bir denizin kıyısında 

Bir bulutun buğusunda 

Gövdemi siper ettim 

Mayın tarlalarında 

Geçit yok düşmana 

Rahat uyu diye sen 

Rahat ol diye ana 

Anam 

Son mektupta kendimi postaladım sana 

Terhis oldu oğlun baksana 

Terhis oldum anam

Geliyorum

Geliyorum 

Boynuna sarılmaya 

Bir tas sıcacık çorbana kaşık sallamaya 

Sen bir çorbayla kalmazsın bilmez miyim 

Yorma be anam kendini 

Bu kadar yorma 

Bak

Babama söyle 

İki kadeh bir şeyler hazırlasın 

Şöyle oturup karşı karşıya 

Karşılıklı 

Erkek erkeğe 

Erkekçe 

Ne güzel olur değil mi be anam

İlk defa bir şeyler içeriz 

Asker oğlun şerefine

Bir de sigara yakarım değil mi anam

Yakarım yaa

Neden olmasın

Bir de türkü patlatırım vallah

Şöyle gurbet üstüne

Askerlik üstüne

Sevda üstüne

of! of! 

Yandım be anam

Haber sal kardeşler yeğenler de gelsin 

Anam 

Haber sal 

Nazlım da gelsin / çok özledim

Bu gün kalabalık olmalı evimiz 

Bu gün çok kalabalık anam 

Özlemlerimle düştüm yollara 

Özlemlerimi yükledim de demir kanatlara 

Geliyorum

Uçuyorum

Uçuyorum anam

Son mektupta kendimi postaladım sana 

Çivilenmiş bir tabutta 

Bedenim 

Özlemlerim 

Söyleyemediğim şarkılarımla 

Çivilediler beni ana 

Sonra al bir bayrağa sardılar 

Allı pullu bir yazma almıştım sana 

Her saçını bağladığında 

Her özlem çöktüğünde bağrına 

Silersin diye gözyaşını bir ucuyla 

Bugün onu bağla saçına ana 

Kusura bakma 

Nerden bilirdim ben olacağımı 

Yamana ilk düşecek acı damla 

Ağlama anam 

Anam ağlama 

Özlemlerim bulutlara takıldı 

Ellerim yıldızlara 

Yüreğim 

Ah 

Yüreğim 

Yüreğim rüzgarlara 

Haber Sal 

Kardeşler yeğenler de gelsin 

Haber Sal 

Nazlım da gelsin 

Elinde bahar çiçekleri 

Bu gün kalabalık olmalı evimiz 

Bu gün çok kalabalık anam 

Özlemlerimle düştüm yollara 

Özlemlerimi yükledim de demir kanatlara 

Taşımadılar be anam 

Anam 

Taşıyamadılar 

Bulutlar kıskandı 

Analar ağlamasında kimler ağlasın 

Ağlama desem 

Ağlamaz mısın 

Anam 

Canım anam 

Ağlama! 

Analar ağlamasın! ..', 'Ankara Diyarbakır seferini yaparken şehit düşen 34 erimizin anısına Analar ağlamasın da kimler ağlasın  Davullu zurnalı Asker uğurlama alayl...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":156,"source_url":"https://www.antoloji.com/analar-aglamasin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılın İlk Karı Yağıyor...', 'yilin-i-lk-kari-yagiyor-yasar-gunacgun-kzyoc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yılın ilk karı yapıyor

dışarıdayım...

düşünüyorum da kaçıncı aşk bu sersefil yaşadığım...

mızrakları saplı durur sırtımda...

yalan değil onüçünde sevdalandığım...', 'yılın ilk karı yapıyor dışarıdayım... düşünüyorum da kaçıncı aşk bu sersefil yaşadığım... mızrakları saplı durur sırtımda... yalan değil onü...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Günaçgün']::text[], 8.5, '{"poet":"Yaşar Günaçgün","poet_slug":"yasar-gunacgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yilin-ilk-kari-yagiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hatırlayacağım Yine (2)', 'seni-hatirlayacagim-yine-2-emin-ozan-helvacioglu-pik56', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne garip! ömrümün sonuna kadar

Sensizliğe mahkum edildim

Hem de en güvendiğim insan tarafından

Oysa sabahları erkenden uyandığımda

Seni yanıbaşımda görmek ne güzel olurdu

Şimdi ise dünün yarınla birleştiği yerde

Seni hatırlayacağım yine

Dudaklarında şarkıların en güzelini

Gece yarısından sonra açan çiçek gibi', 'Ne garip! ömrümün sonuna kadar Sensizliğe mahkum edildim Hem de en güvendiğim insan tarafından Oysa sabahları erkenden uyandığımda Seni yanı...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-hatirlayacagim-yine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hatırlayacağım Yine (1)', 'seni-hatirlayacagim-yine-1-emin-ozan-helvacioglu-mllxr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece yarısından sonra gizlice eve döndüğümde

Seni hatırlayacağım yine

Upuzun geceleri yapayalnız yaşamak zorunda olduğumu

Her gün beni yeniden kıran

Asla tükenmeyen korkunç gücünü', 'Gece yarısından sonra gizlice eve döndüğümde Seni hatırlayacağım yine Upuzun geceleri yapayalnız yaşamak zorunda olduğumu Her gün beni yenid...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-hatirlayacagim-yine-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Senin Olmayı Düşlerdim', 'yalniz-senin-olmayi-duslerdim-emin-ozan-helvacioglu-bjzyj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başım göğsünde ellerinin arasında

Yalnız senin olmayı düşlerdim

Çekerdim çocuksu kokunu ciğerlerime

Garip sessizliğine aşık olurdum yeniden

Çizerdim yarınlarımızı düşler içinden

Sen gerçektin ve unuturdum herşeyi

Başım göğsünde ellerinin arasında

Yalnız senin olmayı düşlerdim

Bir şey olurdu o an, ikimizde de aynı sıkıntı

O büyük kapıyı açacak anahtarın sesini işitirdim

Sanki akşam olurdu merdivenlerde erken erken

Sen içeri girmeliydin ve özlerdim delice isyanımızı

Başım göğsünde ellerinin arasında

Yalnız senin olmayı düşlerdim

Asla bilemezdim arkamızdan kapanan şeyin geleceğimiz olduğunu

Gözlerim boş, yüreğim, beynim boş

Anımsamamaya çalışırdım boşlukları

Sen içerde ağlardın ve korkardım ben aydınlıktan

Başım göğsünde ellerinin arasında

Yalnız senin olmayı düşlerdim', 'Başım göğsünde ellerinin arasında Yalnız senin olmayı düşlerdim Çekerdim çocuksu kokunu ciğerlerime Garip sessizliğine aşık olurdum yeniden ...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalniz-senin-olmayi-duslerdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız', 'yalniz-emin-ozan-helvacioglu-zwlbf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bıkmadım inan seni umutsuzca beklemekten

Sana ulaşan yollarda zaman öldürmekten

Bütün gün, bütün gece

Biliyorum bebek iyi biliyorum sen de biliyorsun

Sen yalnızsın

Ben yalnız', 'Bıkmadım inan seni umutsuzca beklemekten Sana ulaşan yollarda zaman öldürmekten Bütün gün, bütün gece Biliyorum bebek iyi biliyorum sen de b...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalniz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odanda', 'odanda-emin-ozan-helvacioglu-bw42d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece yarısı odandaki ışık ne ?

Pencerede kıpırtısız duruyorsun

Şiirler boşuna mı yazıldı ?

Her zamanki gibi ağlıyorsun

Karanlık, herkesin rahat rahat uyuduğu

Renk renk düşler kurduğu

Saatler yıllara dönüşüyor

Yapayalnız odanda

Hala neyi bekliyorsun ?

Sanki içerde de yağmur var

Duvarlarda geçmişten kalan birkaç anı

Aynadaki insan normal değil ki

Güvenip ellerini uzatasın

Ama yine de onun için ağlıyorsun

Dönüp dururken geniş yatağında

Sözler boşuna mı verildi ?

Düşünmeden, anlamadan, ama insanca

Birlikte önce isyanı öğrendik

Sonra haksızlığı

Onların bilemediği, göremediği, duyamadığı

Yitik bir eşya gibiyiz şimdi

Ben sokakta

Sen odanda

Çok uzak', 'Gece yarısı odandaki ışık ne ? Pencerede kıpırtısız duruyorsun Şiirler boşuna mı yazıldı ? Her zamanki gibi ağlıyorsun Karanlık, herkesin ra...', ARRAY['Türk Edebiyatı','Şiir','Emin Ozan Helvacıoğlu']::text[], 8.5, '{"poet":"Emin Ozan Helvacıoğlu","poet_slug":"emin-ozan-helvacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/odanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-yildiray-aydin-y03vd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün hayatın sonu oldugu gibi;

 Sevgininde sonu olacaktır

Ama  benim sevgim 

 Sana sadece dünya için degil 

Ahiret için olacak ...', 'Bir gün hayatın sonu oldugu gibi;  Sevgininde sonu olacaktır Ama  benim sevgim   Sana sadece dünya için degil  Ahiret için olacak ......', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Aydın']::text[], 8.5, '{"poet":"Yıldıray Aydın","poet_slug":"yildiray-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevmek-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Güneşimsin', 'yaz-gunesimsin-yildiray-aydin-kw7fk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazın güneş ısıtırya 

  insanı işte bende öyle sevmiştim 

seni güneşten kıskanıyorum   

  çünkü seni benden çok daha iyi ısıtıyor 

yıllar  sevipte terk eden olmadıgından seni daha çok 

arzuluyorum 

 çünkü yıllar geçici sevgilim seni denizin dalgalaraına ben zetiyorum çünkü onlar kadar hırçınsın sana 

 bir gül vermek istemem çünkü onlar solar ama 

sana kalbimi veriyorum çünkü o unutmaz:', 'Yazın güneş ısıtırya    insanı işte bende öyle sevmiştim  seni güneşten kıskanıyorum      çünkü seni benden çok daha iyi ısıtıyor  yıllar  s...', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Aydın']::text[], 8.5, '{"poet":"Yıldıray Aydın","poet_slug":"yildiray-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yaz-gunesimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebep', 'sebep-bahaettin-karakoc-0tmxz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dilime sen verdin gül ezgisini,

Bir gönül üzdümse sebebi sensin! ...

Seninle aşmışım dur çizgisini,

Töreyi bozdumsa sebebi sensin! ...

Ufuk ufuk uçtum daldım derine,

Sen öğrettin çoban kimdir, sürü ne? 

Daha yaklaşmadan konak yerine,

Göçümü çözdümse sebebi sensin! ...

Bir renk cümbüşüyle sular ışıdı,

Düş bahçeme kuşlar bahar taşıdı,

Kurbanlık koç güldü, bıçak üşüdü,

Hep esrik gezdimse sebebi sensin! ...

Kimi deli diye güler arkamdan,

Kimi suçlu diye tutar yakamdan,

Eller değil,aklım korkar şakamdan,

Kendime kızdımsa sebebi sensin! ...

Düşmanımın yarasını sardımsa,

Muhabbeti sofra sofra serdimse,

Her güzele hemen gönül verdimse,

Petekler süzdümse sebebi sensin! ...

Dostun sitemleri deler bağrımı,

Sağır gökler yutar yanık çağrımı,

Uzun yıllar gizledimse ağrımı,

Ve şimdi yazdımsa sebebi sensin! ...

Beklerim özüme mihman olasın,

Her selâmın canevimi sulasın.

Bende sabır tükeniyor bilesin,

İçmeden sızdımsa sebebi sensin! ...', 'Dilime sen verdin gül ezgisini, Bir gönül üzdümse sebebi sensin! ... Seninle aşmışım dur çizgisini, Töreyi bozdumsa sebebi sensin! ... Ufuk ...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sebep-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağma', 'yagma-bahaettin-karakoc-mia4n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu şaşkın dünyada yer-gök alçaldı,

Bir yağma başladı  çalanlar çaldı.

Kefenmiş, rütbeymiş, makammış derken; 

Ne ehliyet kaldı, ne mezar kaldı...', 'Şu şaşkın dünyada yer-gök alçaldı, Bir yağma başladı  çalanlar çaldı. Kefenmiş, rütbeymiş, makammış derken;  Ne ehliyet kaldı, ne mezar kald...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yagma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Kalmış', 'kime-kalmis-bahaettin-karakoc-g4789', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Er veya geç bütün tavanlar çöker,

Taban çökmez ama her yükü çeker.

Hesap görülmeden defter kapanmaz,

Elbet bir gün biri çıkını döker.', 'Er veya geç bütün tavanlar çöker, Taban çökmez ama her yükü çeker. Hesap görülmeden defter kapanmaz, Elbet bir gün biri çıkını döker....', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kime-kalmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Ağızdan Bir Ses Çıkar', 'her-agizdan-bir-ses-cikar-bahaettin-karakoc-luyck', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi koru diyor,kimi çal diyor;

Kimi yürü diyor kimi kal diyor.

Kimi Hakk rızası  güder oruçlu;

Kimi nefsin iti,''aman yal'' diyor.', 'Kimi koru diyor,kimi çal diyor; Kimi yürü diyor kimi kal diyor. Kimi Hakk rızası  güder oruçlu; Kimi nefsin iti,''aman yal'' diyor....', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/her-agizdan-bir-ses-cikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mukaddes Sır', 'mukaddes-sir-bahaettin-karakoc-y934g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Âşık güler, aynalarda gül açar; 

Kıraçlar yeşerir, gök ışık saçar.

Muhabbet yağmuru düşmeyen yerde, 

Ne bir ceylan meler, ne bir kuş uçar...', 'Âşık güler, aynalarda gül açar;  Kıraçlar yeşerir, gök ışık saçar. Muhabbet yağmuru düşmeyen yerde,  Ne bir ceylan meler, ne bir kuş uçar......', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mukaddes-sir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozulmuş', 'bozulmus-ozan-arif-b7g1c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'On bir yıl sonra gördüm yurdumu

Toprağı bozulmuş,taşı bozulmuş

Açamadım kimselere derdimi

Halkın yüzde yetmişbeşi bozulmuş

Edirne''den Van''a Van''dan Mersin''e

Muğla''sından başla yürü Kars''ına

Kapılmayan yoktur para hırsına

İzmir''i ,Konya''sı Muş''u bozulmuş

Haramı helali incele de bak

Ya aptal diyorlar ya avanak

Haram dolu haram tencere tabak

Ekmeği bozulmuş,aşı bozulmuş

İyi varsa alınmasın sözüme

İyi miyi görünmedi gözüme

Bakarak kararmış üzüm üzüme

Kurunun yanında yaşı bozulmuş

Köprünün altından çok sular akmış

İyiler yerine lükse bırakmış

Sevdalar fuhuşa sekse bırakmış

Gönüllerin artık düşü bozulmuş.

Bir kahveye kırk yıl hatır yok şimdi

Ne kırk yıl kırk saniye çok şimdi

Hatıra gönüle karın tok şimdi

Gaddar olmayanın işi bozulmuş

Vatan vatan tabii vatan  vatan da

Esrar satan da var,karı satan da

Çıkıyorlar akşam güneş batanda

Erkekler değişmiş,dişi bozulmuş.

Vatan için millet için döğüşmüş,

Mana için maddeyle boğuşmuş

İnsanlarda bile ölçü değişmiş

Bozulmaz dediğim kişi bozulmuş.

Baştakiler ne yaparsa elbette

Aynısını yapacaktır millette

Ah Arif ah,vatanımız cennet de

Velakin balığın başı bozulmuş.', 'On bir yıl sonra gördüm yurdumu Toprağı bozulmuş,taşı bozulmuş Açamadım kimselere derdimi Halkın yüzde yetmişbeşi bozulmuş Edirne''den Van''a ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bozulmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertleşme', 'dertlesme-abdurrahim-karakoc-gq1o6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sırtımıza cümle derdi, belâyı

Sizin için aldık; sizden  ne haber? 

Senelerce uykuları rüyayı

Sizin için böldük; sizden ne haber? 

''Nemize ne, aman bırak'' demedik

Otuz alıp onbeş verek demedik

Hava kışlı, yollar ırak demedik

Sizin için geldik; sizden ne haber? 

Aşk ile doldurduk gönül tasını

Tavuğunuz ölse çektik yasını

Zalimlere karşı cenk havasını

Sizin için çaldık; sizden ne haber? 

Durup da ''bize ne'' demedik bir gün

Korkmadık, yılmadık, düşmedik yorgun

Sıra sıra hapis, kitlece sürgün

Sizin için olduk; sizden ne haber? 

İçkiye, kadına, rütbeye, şana

Tenezzül etmedik, malûm cihana

Bunların cümlesi kalsın bir yana

Sizin için öldük; sizden ne haber? 

(Kan Yazısı)', 'Sırtımıza cümle derdi, belâyı Sizin için aldık; sizden  ne haber?  Senelerce uykuları rüyayı Sizin için böldük; sizden ne haber?  ''Nemize ne...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dertlesme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Yüz', 'karanlik-yuz-orhan-tahsin-pebe6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzaklarda...

Güneş kadar uzaklarda...

Yıllar sonra kağıt kalem bu kadar mutlu!

Deprem korkusuna rağmen.

Birbirine kavuşmanın sevinci içinde

ve donuk bir yüz

Kendisine şefkatle bakan kağıda inat.

Asırlarca yaşamışcasına,

Asice ,kararlı ve korkusuz.

Geceye direnen karanlık bir yüz.

Adeta deliyor karanlıkları

Bir taraflardan ışık mı sızıyor ne?

Her gün doğan güneşe inat.', 'Uzaklarda... Güneş kadar uzaklarda... Yıllar sonra kağıt kalem bu kadar mutlu! Deprem korkusuna rağmen. Birbirine kavuşmanın sevinci içinde ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tahsin']::text[], 8.5, '{"poet":"Orhan Tahsin","poet_slug":"orhan-tahsin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karanlik-yuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarpık Çağ', 'carpik-cag-abdurrahim-karakoc-rd6bg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğru mu, yanlış mı karar sizlerin

Biz aklın durduğu çağda yaşadık

''Ben dinsizim! '' diyen beyinsizlerin

Din dersi verdiği çağda yaşadık.

Çabuk pişsin diye zorbanın aşı

Ayıran olmadı kurudan yaşı

Keçinin kaplana her adım başı

Kırk tuzak kurduğu çağda yaşadık.

Baylar çalım sattı, bayanlar etin 

Ar duvarı çürük, darbeler çetin.

Modern putçuluğun, şirkin, zilletin

Kemale erdiği çağda yaşadık.

Bazen kör kilitler vuruldu dile

Bazen armağanlar kazandı hile

Homo''nun,komo''nun, deyyusun bile

İtibar gördüğü çağda yaşadık.

Yabancısı olduk ilin, obanın

Müdür ekmeğini çaldı çobanın

Resmi dairede devlet babanın

İpe un serdiği çağda yaşadık.

Önümüz çileydi, arkamız cefa

Bir gün semtimize basmadı sefa

Mürşidin, müridin günde beş defa

Günaha girdiği çağda yaşadık.

Kimi hak adalet gördü düşünde

Kimi devlet kuşu buldu başında

Vatanseverlerin vatan dışında

Hasretlik sürdüğü çağda yaşadık.

Göz yumup izine düştük batı''nın

Tuttuk kuyruğundan haçlı atının

Pamuk yumağının, tüyün, tütünün

Nice baş yardığı çağda yaşadık.

Neler yıkmadık ki son olsun diye

Harcadık günleri gün olsun diye

Asker kaçağının şan olsun diye

Askeri vurduğu çağda yaşadık.

Dilendik, savurduk Doları, Markı

Döndükçe aşındı düzenin çarkı

Şalvarı, kasketi, gömleği, börkü 

İhtiras sardığı çağda yaşadık.

Kimi vurgun vurdu döndü köşeyi

Kimi yalamakla doydu şişeyi

Kiminin ateşi, külü, maşayı

Ekmeğe dürdüğü çağda yaşadık.

Kılavuzluk yaptı körü beylerin

Seçimde sağılan sürü, beylerin

Morgtaki ölüden diri beylerin

Hâl-hatır sorduğu çağda yaşadık.

Atladık bir çağdan bir diğerine

Çıktık zirvelere, daldık derine

''Çağdaş bayanlar''ın cins beylerine

Çuvallar ördüğü çağda yaşadık.

Biri yola çıkmaz dayı bulmadan

Biri balık avlar suyu bulmadan

Birinin haftayı, ay''ı bulmadan

Milyarlar derdiği çağda yaşadık.

Baş örtüsü yasak,Türk olmak günah 

Sabır ver, sabır ver ey gadir Allah! 

Bulaşık basının her gün, her sabah

İslâm''ı Yerdiği çağda yaşadık.

Zorbaya rüşvettir ''nurol-çok yaşa''

Mâbutlar, kıbleler değişti hâşâ

İnsanın kâğıda, demire, taşa

Secdeye vardığı çağda yaşadık.

Görün hâlimizi biz insanların

Tutsağı olmuşuz suizanların

Her zaman her yerde müslümanların

Müslüman kırdığı çağda yaşadık.', 'Doğru mu, yanlış mı karar sizlerin Biz aklın durduğu çağda yaşadık ''Ben dinsizim! '' diyen beyinsizlerin Din dersi verdiği çağda yaşadık. Çab...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/carpik-cag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vitrin', 'vitrin-abdurrahim-karakoc-ztu0o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seçimle iş başına gelen yöneticiler

Palavra sıka sıka geçirir beş seneyi,

Zamanın vitrininde tükense de sevgiler

Dolaylı menfaatler doldurur boş seneyi.

(Gök çekimi)', 'Seçimle iş başına gelen yöneticiler Palavra sıka sıka geçirir beş seneyi, Zamanın vitrininde tükense de sevgiler Dolaylı menfaatler doldurur...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/vitrin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynanın İki Yüzü', 'aynanin-i-ki-yuzu-abdurrahim-karakoc-5gxr3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir, zirvede habire şiştikçe şişene bak

Bir, tabanda her adım yıkılıp düşene bak

Bir, ülke yansa bile yan gelip yatanlara

Bir, yangın söndürmeye çarıksız koşana bak.', 'Bir, zirvede habire şiştikçe şişene bak Bir, tabanda her adım yıkılıp düşene bak Bir, ülke yansa bile yan gelip yatanlara Bir, yangın söndür...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aynanin-iki-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keyfiyet', 'keyfiyet-abdurrahim-karakoc-im2zj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göl, göl oldu anaların gözyaşı

Kan selinde akıyoruz eyi mi? 

Ateş sardı Malatya’yı, Maraş’ı

Kendimizi yakıyoruz eyi mi? 

Bağlandı yolumuz, yolaklarımız

Zincire vuruldu bileklerimiz

Küfür ile doldu kulaklarımız

Dişimizi sıkıyoruz eyi mi? 

Koçyiğitler kör kurşunla devrilir

Kazancımız nahak yere savrulur

Dilekçemiz Ankara''dan çevrilir

Her belâyı çekiyoruz eyi mi? 

Azığı, çarığı ardıca astık

Bulutlar yorgandır, kayalar yastık

Görkemli başlardan umudu kestik

Uzaklara bakıyoruz eyi mi? 

Adalet istedik, zulüm sundular

Hayat hakkı dedik, ölüm sundular

Sabrımıza bakıp korkak sandılar

İkrah ettik, bıkıyoruz eyi mi? 

Bölücü beyinler baykuş yuvası

Pis koku neşreden suyu, havası

Duru gönlümüzde millet davası

Sevgi gülü ekiyoruz eyi mi? 

Yıllar yılı bir halaskâr bekledik

Günü güne, ayı aya ekledik

Sırtımıza umutları yükledik

Doruklara çıkıyoruz eyi mi? 

(Suları Islatamadım)', 'Göl, göl oldu anaların gözyaşı Kan selinde akıyoruz eyi mi?  Ateş sardı Malatya’yı, Maraş’ı Kendimizi yakıyoruz eyi mi?  Bağlandı yolumuz, y...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/keyfiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-abdurrahim-karakoc-8xqg7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben deliden çok kurnazdan korkarım

Cahilden ziyade yobazdan korkarım

Bedenimdeki hastalıklardan değil,

Adalete düşen marazdan korkarım.', 'Ben deliden çok kurnazdan korkarım Cahilden ziyade yobazdan korkarım Bedenimdeki hastalıklardan değil, Adalete düşen marazdan korkarım....', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/korku-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Gerçekler', 'garip-gercekler-abdurrahim-karakoc-o1df5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir tarafta her devrin sultanları durur

Bir tarafta kaderin kurbanları durur

Ne kurban kesiciler biter dünyamızda

Ne de kesilen kurban kanları durur.', 'Bir tarafta her devrin sultanları durur Bir tarafta kaderin kurbanları durur Ne kurban kesiciler biter dünyamızda Ne de kesilen kurban kanla...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/garip-gercekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erbabiye', 'erbabiye-abdurrahim-karakoc-ytd8k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Liderimiz uzaylı,silahımız ok bizim

Hilede, iftirada üstümüze yok bizim.

Bal,sirke,soğan,şeker,et,süt,nane,sarımsak; 

Katar çorba yaparız,hünerimiz çok bizim.

(Gökçekimi)', 'Liderimiz uzaylı,silahımız ok bizim Hilede, iftirada üstümüze yok bizim. Bal,sirke,soğan,şeker,et,süt,nane,sarımsak;  Katar çorba yaparız,hü...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/erbabiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölülere İhtar', 'olulere-i-htar-abdurrahim-karakoc-6g5im', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey eski ölüler kalkın mezardan

Dünyayı bir daha görün de gidin.

O günler mi berbat yoksa bugün mü

Biz değil...siz karar verin de gidin.', 'Ey eski ölüler kalkın mezardan Dünyayı bir daha görün de gidin. O günler mi berbat yoksa bugün mü Biz değil...siz karar verin de gidin....', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olulere-ihtar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Öldürdüm Ben', 'ask-oldurdum-ben-hakan-ege-prtop', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk öldürdüm ben,

Kan çekiyor, hergün öldürdüğüm yere gidiyorum

Feriha orada ben orada cesedin başında

Ölüm yüzünde bembeyaz, yaşasaydı diyorum

Feriha zalim, , içi ağlarken aldırmaz

Bunu bana yaptırdı, bu yüzden, 

Pişmanlık ve acı

Gözbebeklerinden bile kaçmış onun

Bu bembeyaz cesedi tanıdığı

Aşk öldürdüm ben,

Kendimi de terkettim

Temmeuz-1998', 'Aşk öldürdüm ben, Kan çekiyor, hergün öldürdüğüm yere gidiyorum Feriha orada ben orada cesedin başında Ölüm yüzünde bembeyaz, yaşasaydı diyo...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ege']::text[], 8.5, '{"poet":"Hakan Ege","poet_slug":"hakan-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-oldurdum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılmalar', 'kirilmalar-hakan-ege-vghx9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıyılarına vurdum usulca

Ayışığı dökülmüştü üstüne

Cesaretim

Gözlerinin ışıklarını yıkamaktı

Yağmurdan kalan sularla

Med-cezirlerimde

Sana uzakken en çoktun

Benimdin

Çizgileri dudaklarının yollarıydı

Gözlerinden bana gelenlerin

Dokunurdun bedenime küçük damlalarla

Sana koşmalarım senin

Senine getirirdi beni

Duvarlarından aşağı akarken köpüklü sularım

-Kırılan hırçın özlemlerimdir bu-

Bir durgun şaşkınlıkla akardı gerilere

Sana giderdim

Senden uzaklara benim senine

Sen seni görmedin bu yüzden

bu kırılmalarda', 'Kıyılarına vurdum usulca Ayışığı dökülmüştü üstüne Cesaretim Gözlerinin ışıklarını yıkamaktı Yağmurdan kalan sularla Med-cezirlerimde Sana u...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ege']::text[], 8.5, '{"poet":"Hakan Ege","poet_slug":"hakan-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirilmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Kaymaları', 'zaman-kaymalari-hakan-ege-3tacy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir damla düşer, saten gece yırtılır,

                          rengi dökülür, lacivert olursun..

bugün dün mü, yarın mı,

babamın babasıyım, yada oğlumun çocuğu

buzullarda çözülürken gençliğim

böyle uzun değildir de kaymalar bazen

küçük bedenine sıkışır

bir el olur göğsünün üstünde

nefesi alkol fırtınalı yüzüne

çarpan, kusturacak öpmeler...

bir pervane böceği gibi kendi

etrafında dönmeler...

uçuşan şeyler senden,

 kopan çınarlar köklerinden, Topkapıda bir yerde

girdaplara düşüyorlar bazen içe bazen dışa

dönen girdaplara

geliyor veya gidiyorlar

yuvarlak genişleyen zelzelelerle

böyle dönüp durmazda kaymalar bazen

hüzünle çekilmiş Gitane dumanı gibi acı

büyür büyür

için senden büyük olur

çözülür çizgiler

zaman kaymaları

bir avuç su olursun

ay boğulur.

Temmuz-2000', 'bir damla düşer, saten gece yırtılır,                           rengi dökülür, lacivert olursun.. bugün dün mü, yarın mı, babamın babasıyım,...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ege']::text[], 8.5, '{"poet":"Hakan Ege","poet_slug":"hakan-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/zaman-kaymalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos Monologları', 'agustos-monologlari-isil-canitez-61hih', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğim kumral aşklara gebe

Dilimde yıpranmış bir ıslık

Gözlerim yolun sonunu görüyor yine

Kumral aşklar kumral hüzünlere gebe

Karanlık yüreklerin dibi tutar yıldızsız gecelerde

Gözyaşları nehir olur akar,istemdışı

Yağmur sesleri gelir kulaklara uzaktan

Yağan yağmur değil gecedir aslında

Umutların nadasa bırakıldığı mevsimdir gece.

Merdivenler kırık dökük,

Merdivenler daracık, çatlak

Her çatlakta başka bir rüya saklanıyor

Ebe;yalnızlık.

Zamanın esiri Ağustos

Çay bahçelerinde çekirdek çıtlanıyor

Manolyalar sükunetle baharı bekliyor

Takalarda deniz türküleri...

Küçük bir fener tüm dünyaları aydınlatıyor.', 'Yüreğim kumral aşklara gebe Dilimde yıpranmış bir ıslık Gözlerim yolun sonunu görüyor yine Kumral aşklar kumral hüzünlere gebe Karanlık yüre...', ARRAY['Türk Edebiyatı','Şiir','Işıl Canıtez']::text[], 8.5, '{"poet":"Işıl Canıtez","poet_slug":"isil-canitez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/agustos-monologlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Boğulmasından Sana Ne Deme', 'ay-bogulmasindan-sana-ne-deme-hakan-ege-i9e59', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana bak adam,

Bana bir içki ver birde Edirne peyniri bir tabağa

-Beyim duymadınız herhalde ay boğuldu dün gece

Ha siktir ya

Ay mı istedik senden

-Bilmem ben, ay boğuldu deyip herkes gitti

bırak babacım ya, rakıya buz koy yeter

biz kendi ayımızı resmederiz içine

beyaz gecemizin.', 'Bana bak adam, Bana bir içki ver birde Edirne peyniri bir tabağa -Beyim duymadınız herhalde ay boğuldu dün gece Ha siktir ya Ay mı istedik s...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ege']::text[], 8.5, '{"poet":"Hakan Ege","poet_slug":"hakan-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ay-bogulmasindan-sana-ne-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir Misin', 'bilir-misin-umit-yasar-oguzcan-cjf61', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tam sınırdan kaçarken vurulmak nedir bilir misin? 

Nöbetçiler ha gördü, ha görecek

Parmaklarının ucu dikenli tellere değdi değecek...

Ama... Bir adım daha atamazsın.

Uzanıp tutamazsın; 

Göz pınarlarında donup kalır hayallerin

Planların, kaçışın, kurtuluşun

Ve deler sevgi dolu yüreğini

Sevgi bilmeyen bir kurşun.

Bir okyanus da boğulmak nedir bilir misin? 

Batan bir gemiye el sallayamamak, 

Oturup ağlayamamak, 

Birkaç kulaç ötedeki

Bir tahta parçasını tutamamak, 

Nedir bilir misin? 

Sevmek nedir bilir misin? 

Bir şeyler tutuşur yüreğinde kıpır kıpır

Bütün benliğini sarar, ısıtır.

Her gülüşte yeniden doğarsın

Ve bin kere ölürsün her iç çekişte

Nasıl anlatsam bilmem ki.

Yani ''sevmek'' işte.

Duymak nedir bilir misin? 

Duymak, ama anlatamamak

Çemberini kıramamak kelimelerin.

Tam dilinin ucuna gelmişken söyleyememek

''Seviyorum'' diyememek

Yani ölümü yaşamak nedir bilir misin?', 'Tam sınırdan kaçarken vurulmak nedir bilir misin?  Nöbetçiler ha gördü, ha görecek Parmaklarının ucu dikenli tellere değdi değecek... Ama......', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bilir-misin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Lambaları Boyu Göz Yaşların Var', 'sokak-lambalari-boyu-goz-yaslarin-var-eray-bilge-1xnfd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uçaklar geçiyor

özgür...

adımlar sıklaşır

nefeslerini duyarsın

dolu dizgin bir gidiş halinde

hep boşluksun, günlerin geçer

sonbaharda kanar yaprakları içinin

uzatıversen 

vurulur biri bir köşede

o köşe ki kırmızı ile siyah kadar benzer

birinin içini atmasına

dolmasına boşlukla

sokak lambaları boyu göz yaşların var

merdivenler dolusu umudun 

“ başın sonun var ” derken birileri

pencere açılası bir kavga başlar

asılını bulur anlam

anlam, masa örtüleri fistolar

anlam, ölümde kalmak yaşayarak

anlam, sıkı bir şarkı dinlemek

gülmek, uzaklardaki gün

gülmek, akşam keyifleri

yani

dakikalık geçici

ne eskisi gibi gerçek

ne gelecek gibi yalan

22.09.1997', 'uçaklar geçiyor özgür... adımlar sıklaşır nefeslerini duyarsın dolu dizgin bir gidiş halinde hep boşluksun, günlerin geçer sonbaharda kanar ...', ARRAY['Türk Edebiyatı','Şiir','Eray Bilge']::text[], 8.5, '{"poet":"Eray Bilge","poet_slug":"eray-bilge","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sokak-lambalari-boyu-goz-yaslarin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerende Başlar Hayat', 'nerende-baslar-hayat-eray-bilge-trklg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nerende başlar hayat

canın nerende

var mısın yok olamamanın eş anlamında

antin kuntin kuruntular içinde

sen de yok olmalar gibi misin bunca var içinde

sahi komşuları olmalı adamın

varda ve yokta

yoklamak ve varlamak için belki 

yoksa anlamı be ki 

baksana, görmüyor musun ne kadar da üst düzey

entelektüel ve kibirli ihtiyaçlarımız var...

tuvaletlerden vazgeçer misin 

ya saatlerden

ya, ben yokum bu kadar benden, desem

vazgeçer misin

boşuna mı bunca çaba

ki değil biliyorum

dikine çizgilerimi yatıştırdım hep bak

senin de dikine çizgilerin var mıydı bir zamanlar

nasıl yatıştırılacağını bilmediğin...

11.01.2000', 'nerende başlar hayat canın nerende var mısın yok olamamanın eş anlamında antin kuntin kuruntular içinde sen de yok olmalar gibi misin bunca ...', ARRAY['Türk Edebiyatı','Şiir','Eray Bilge']::text[], 8.5, '{"poet":"Eray Bilge","poet_slug":"eray-bilge","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nerende-baslar-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mücahede', 'mucahede-okkes-yuksek-tsd5x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ruhum cenk meydanı, düşmanlar şedit, 

kalbimde şeytanın kılıç izleri, 

itminan; ufukta bir nurlu geçit, 

beni bağlar nefsin kelepçeleri.

şüpheler beynimde zehirli kıymık, 

vesvese ateşi kalbimi yakar, 

vicdan; hep doğruyu haykıran çığlık, 

sönmez ışığını yoluma tutar.', 'ruhum cenk meydanı, düşmanlar şedit,  kalbimde şeytanın kılıç izleri,  itminan; ufukta bir nurlu geçit,  beni bağlar nefsin kelepçeleri. şüp...', ARRAY['Türk Edebiyatı','Şiir','Ökkeş Yüksek']::text[], 8.5, '{"poet":"Ökkeş Yüksek","poet_slug":"okkes-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mucahede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rumuzu Nevhayat', 'rumuzu-nevhayat-mehmet-calik-xdi7n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bakışların değil 

kelimelerin gücenikliğinde konakladım 

ilk yazdı,erguvan çiçekleri açmıştı yalnızlığım 

çil çil yıldızlar ışımıştı alnımda 

yıllar sonra bir daha öpülesi olmuştu. 

sesinden değil 

hüznün mızıkasında tanıdım 

ağlamıştın önce 

sarmalayıp kelimelere gücenikliğini 

bana gelmiştin 

gözlerini hiç görmedim 

hüznün lekesiz maviydi 

yuvadan düşmüş kuş yavrusuydun 

çıplak elle dokunamazdım 

yalnız değildin 

kokunda yoktu 

incinmiş sevdanla geldin 

hayatı konuşacaktık 

hani şu yeni olacak olanı 

sen kuralları koydun 

ben kavramları 

saçlarında değil 

telaşların dalgasında gördüm 

minik bir deniz kabuğunun 

okyanusa özlemini 

kendi avuçlarımla başlattım 

akdenizde itakilere yolculuğunu 

severiz ya arabeski 

hayat bizi kurban ettiyi 

hiç acaba demedik 

hayatı bizmi kurban verdik 

yalnızdım 

kutupsuz penguen kadar 

aşkla 

hep yarına bağladım hayatı 

çözemedim 

şimdi 

kanıyorum 

dilime batıyor kelimeler 

unuttum 

bu hayatın hangi adı? 

siz bilmiyorsunuz 

dudak değmemiş türkülerim 

susuyorlar şimdi 

cinnetlik aşermelerle 

aşklar geçerken şölenle 

nadas kokuyor yüreğim 

al bir duvakla 

örtünüp dölsüzlüğümü 

yaşama topallıyorum 

bir umudu 

tacizliyerek tenhada 

çığlıklar atarızya 

tutunacak dal kalmadı diye 

işte ben 

hep o dallarda takılı kaldım 

hadi bir düş bul bana 

içinde bir tutamlık dal olmasın 

bir düş getir bana 

arkasında yarın olmasın 

tapınaklar 

düşlerimizle paslandı 

adına umut dedim 

yarına iteledim hayatı 

bir beden küçüldüm her yıl 

bir beden büyüdü dünya 

ben cüce kaldım 

hayat bakir 

eşeleyecek külüm olmadı 

naftalin sürüyorum yıllardır 

içimdeki mızıkcı çocuğa 

yetişkinler gelmesin kokusuna 

bekliyorum ''godo'' yu 

çekelim 

hayatlarımıza tutulan alkışları 

uzat ellerini 

''küçük prens''le baharlandıralım 

hadi 

bir oyun daha oynayalım 

bu kez aklımızı aldatalım 

şimdi sen 

nasıl düşlersem öylesin 

tıpkı hayat gibi 

inadına mavi 

darasız gökyüzü gibi 

gecedir 

ay ışığını hovarda yapan 

düşerim 

yıldızlarda firar kaldı.', 'bakışların değil  kelimelerin gücenikliğinde konakladım  ilk yazdı,erguvan çiçekleri açmıştı yalnızlığım  çil çil yıldızlar ışımıştı alnımda...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çalık']::text[], 8.5, '{"poet":"Mehmet Çalık","poet_slug":"mehmet-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/rumuzu-nevhayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum...', 'usuyorum-sah-ali-yasar-w19qc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Farzet ki fırtınada kalmışım 

Tipiye tutulmuşum dağ başında

Saçlarım ak appak

Ayaklarım puç

Kök salmış kulaklarımda uğultular!..

Al beni, dost beni

Al yüreğine ısıt beni!..

Farzet ki rüzgar kesmiş soluğumu

Don atmış kanıma gecenin ayazı

Ellerim mosmor

Gözlerim kaskatı

Kandil gibi sarkmış dudaklarımda arzular!..

Al beni, yar beni

Al yüreğine sar beni!..', 'Farzet ki fırtınada kalmışım  Tipiye tutulmuşum dağ başında Saçlarım ak appak Ayaklarım puç Kök salmış kulaklarımda uğultular!.. Al beni, do...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/usuyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berrak', 'berrak-mehmet-emin-asik-j329l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göz yaşım seninle hiç dinmez oldu,

Sular seller gibi akıyor Berrak.

Korkarım ki aşkın gözü kör oldu,

Yeşil gözler beni görmüyor Berrak.

Teselli ararım meyhanelerde,

Sersefil olurum viran yerlerde,

Aşk için söylenen bahanelerde,

Hep sen çıkıyorsun karşıma Berrak.

Mahruk bakışınla ufkumu deldin,

Mor dağları kızıl çöle çevirdin.

Aşkınla garibi şereflendirdin,

Her falda yollarım sanadır Berrak.

Manasız olsada seni sevişim,

İmkansız olsada benim oluşun,

Söz dinlemez gönlüm artık sen düşün,

Kalp gözüm elleri görmüyor Berrak.

Ben kendimi şair olmaz sanırdım,

Kemal-i aşkına nasıl kapıldım?

Nerde hata yaptım,nerde yanıldım?

Arasamda sensiz bulamam Berrak.

Aşkın kemalinden sihir umarken,

Doluya tutuldum rahmet ararken,

Hekimler derdime çare sunarken,

Tek ilacım sendin bilmedin Berrak.', 'Göz yaşım seninle hiç dinmez oldu, Sular seller gibi akıyor Berrak. Korkarım ki aşkın gözü kör oldu, Yeşil gözler beni görmüyor Berrak. Tese...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Aşık']::text[], 8.5, '{"poet":"Mehmet Emin Aşık","poet_slug":"mehmet-emin-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/berrak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sudan Ucuz...', 'sudan-ucuz-sah-ali-yasar-cdy8p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir Kutlu Sefere Gitti Yiğitler

Sevgiler Uğruna,

Sevgileri Geride Bırakarak...

Yaşlar Döküldü Arkalarından

Ağıtlar Yakıldı,

Onlar Sevildiklerinden Habersiz

Titrettiler Zamanı...

Ne Ağustos Sıcağından Korktular,

Ne Zemheri Soğuğundan,

Ne de Çil Yavrusu

Sudan Ucuz İnsanlardan...

Gün Oldu, Kınından Çıktı Öfkeleri

O Dağ Benim, Bu Dağ Senin

Kıyasıya Çarpıştılar,

Gün Oldu, İbişek Atıp Aralarında

Ölümü Paylaştılar...

Bir Kutlu Sefere Gitti Yiğitler

Sevgiler Uğruna,

Sevgileri Geride Bırakarak...

Yaşlar Döküldü Arkalarından

Ağıtlar Yakıldı,

Onlar Sevildiklerinden Habersiz

Titrettiler Zamanı...

Duvarlar Örüldü Önlerine

Cellatlar Sürüldü,

Sinmediler, Sindiremediler

Bükülmedi Bilekleri,

Hesaplar Görüldü Günlerine

Defterler Bürüldü,

Sönmediler, Söndüremediler

Dağ Gibiydi Yürekleri...

Yarınları Pahasına

Yarınları Savundular,

Göz Koymayıp Dahasına

Olanıyla Avundular...', 'Bir Kutlu Sefere Gitti Yiğitler Sevgiler Uğruna, Sevgileri Geride Bırakarak... Yaşlar Döküldü Arkalarından Ağıtlar Yakıldı, Onlar Sevildikle...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sudan-ucuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırdılar Beni', 'kirdilar-beni-mehmet-emin-asik-eam86', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hislerim şiir olup geldi dilime,

Anlatamıyor seni hiç bir kelime,

Aşkın en güzelini yaşadım diye,

Zalimler deryasında boğdular beni.

Mehtap sönük kalırdı senin yanında,

Beni her gün vurdular viran bir handa.

Yıldızlar ağlamıştı bakıp halime,

Güneş bile kıskanıp eritti beni.

Niye kıskanırlar anlamıyorum,

Bir bilmece oldun çözemiyorum,

Aşkın deryasında yüzemiyorum,

Kollarımı kırıp vurdular beni.

Kaç kere ağlamıştım seni anarak,

Her gün irkildim çığlığını duyarak,

Rüyalarda aşkın dibine dalarak,

Hayalimde yaşattım yücelttim seni.

Bahtı kara bir garip olmuşsun AŞIK,

Herkesle dostidin herkesle barışık.

Gaflet uykusunda şeytanla yarışıp,

Hep beraber oldular kırdılar beni.', 'Hislerim şiir olup geldi dilime, Anlatamıyor seni hiç bir kelime, Aşkın en güzelini yaşadım diye, Zalimler deryasında boğdular beni. Mehtap ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Aşık']::text[], 8.5, '{"poet":"Mehmet Emin Aşık","poet_slug":"mehmet-emin-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirdilar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ben Nasıl Sevmem', 'seni-ben-nasil-sevmem-tekin-gonenc-1sc09', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hani bir çocuğun sımsıkı sarılıp 

bir bebeği öpüp koklaması var ya 

o’sun işte sen 

ben seni nasıl sevmem 

kimileri gövde sanıp karanlığı 

darmadağın sığınırken içine 

sen aralayıp gözyaşlarını 

gülüşünü serpiyorsun üstlerine 

vakitsiz birer ölüm sanki geceler 

bir bakımlık ay düşüyor herkesin payına 

ve hiç dönüp de soran olmuyor 

eklenen hangi düşler bir sonraki sabaha 

bildik bir nehrin sularına kendini bırakıp da 

gidilecek başka denizler arıyorsun ya 

o’sun işte sen 

seni ben nasıl sevmem', 'hani bir çocuğun sımsıkı sarılıp  bir bebeği öpüp koklaması var ya  o’sun işte sen  ben seni nasıl sevmem  kimileri gövde sanıp karanlığı  d...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-ben-nasil-sevmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak...', 'yasamak-sah-ali-yasar-hr8nt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir başkaldırıdır şimdi yaşamak

Haksızlığa ve eşitsizliğe

Hüznün eşiğinde...

Acı bir tebessüm incitir gururu

Bir adım dönüştür geriye

Adım başı aramak şuuru...

Sevgiye inat

Sevgiliye inat

Ayrılıktır yaşamak

Gecenin soysuzluğunu

Gecenin koynunda tatmak

Dağlar direnmek

Dağlar yaşamak

Yaşamak bir ömür savaşmak!..

Ağlayan çocuğu susturan emzik

Benim de dokunduğum tetik

Nar çiçeği şafaklarda beyaz iz yaşamak...

Yaşamak hesap sorma vakti

Yeni bir zafere varma vakti

Yürekler serpmek yüreksizlere

Dokunmak dolu dolu gözlere

Gece rengi türkülerde eritmek zamanı

Bol nefes çekmek özgürlükten

Yaşamanın en güzel yanı!..', 'Bir başkaldırıdır şimdi yaşamak Haksızlığa ve eşitsizliğe Hüznün eşiğinde... Acı bir tebessüm incitir gururu Bir adım dönüştür geriye Adım b...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yasamak-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle olmak vardı...', 'seninle-olmak-vardi-sah-ali-yasar-ffa9w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi seninle olmak vardı gülüm

Seninle demlemek zamanı,

Geçen günlerin inadına

Seninle yaşamak bugünü, yarını...

Başkaldırmak bakışlarımla kör bir vakit,

Bin hınç ile sarılmak boğazına çaresizliğin

Boğmak,

Parçalamak

''Cızz'' etmeden yüreğim...

Ve bütün engellere rağmen

Döküp ortaya ne varsa,

Ne varsa yakmak sensizliğe ait...

Çekip aralamak zaman perdesini

Umutların gözlerinden yol geçirmek,

Bir adıma indirmek mesafeleri

Son bir şansımı denemek

Önümde ateşten barikat,

Arkamda kulak asmadığım ''dur'' ihtarı.

Soluk soluğa koşmak sana

Beni sana getirmek...

Şimdi seninle olmak vardı gülüm...', 'Şimdi seninle olmak vardı gülüm Seninle demlemek zamanı, Geçen günlerin inadına Seninle yaşamak bugünü, yarını... Başkaldırmak bakışlarımla ...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seninle-olmak-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Ayrımları', 'yol-ayrimlari-tekin-gonenc-lpen4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'göz gözü görmeyecek kadar mıydı

yol ayrımları

söylenecek ne varsa

alıp gittin

sesindi

hiç yorulmadı

tırmandı durdu ıslığıma

bir deste başıboş anahtar

giderayak elime tutuşturduğun

hangi kapına varsam

taş

duvar

geri dönmelerine sakladım kendimi

keşke bir gün

tık kapı

ansızın sen', 'göz gözü görmeyecek kadar mıydı yol ayrımları söylenecek ne varsa alıp gittin sesindi hiç yorulmadı tırmandı durdu ıslığıma bir deste başıbo...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yol-ayrimlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceksin', 'geleceksin-betul-kondu-twq0p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selamlar 

Ey insanoğlu

Selamlar

Seni bekliyoruz

Sadece seni

Bekliyoruz 

Sabırlıyız

Biliyoruz ki geleceksin bu yere

Sabırlıyız 

Sabırlı olacağız

Bazen bazıları,

Ortaya atlayıp haykırsada

Aldırma 

Sabırlıyız

Selamlar

Ey insanoğlu

Bekliyoruz

Geleceksin

Umudumuz hiç ama hiç bitmeyecek

Bekliyoruz

Biliyororuz

Geleceksin

İçimizden kalbimizden bir

Ses sadece bir ses bize öyle diyor

Geleceksin...', 'Selamlar  Ey insanoğlu Selamlar Seni bekliyoruz Sadece seni Bekliyoruz  Sabırlıyız Biliyoruz ki geleceksin bu yere Sabırlıyız  Sabırlı olaca...', ARRAY['Türk Edebiyatı','Şiir','Betül Kondu']::text[], 8.5, '{"poet":"Betül Kondu","poet_slug":"betul-kondu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/geleceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyorum', 'yasiyorum-sair-yagmuryurekli-xnc3d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yine seni yaşıyoum

gecenin bu vaktinde 

yarım kalmış duygularım

parçalanmış bir sevdam

dudağımda sigaram 

radyoda o sevdiğin şarkı 

ve ben...

seni arıyoruz o eski anılarda

bekliyoruz gelmeni

ama sen gelemezsin çünkü

sen dönüşü olmayan uzak 

diyardasın... sevgili...', 'yine seni yaşıyoum gecenin bu vaktinde  yarım kalmış duygularım parçalanmış bir sevdam dudağımda sigaram  radyoda o sevdiğin şarkı  ve ben.....', ARRAY['Türk Edebiyatı','Şiir','Şair Yağmuryürekli']::text[], 8.5, '{"poet":"Şair Yağmuryürekli","poet_slug":"sair-yagmuryurekli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ateşim Yanarım', 'bir-atesim-yanarim-umit-yasar-oguzcan-k2eop', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ateşim yanarım külüm yok dumanım yok

Sen yoksan mekanım belli değil zamanım yok

Fırtınalar içinde beni yalnız bırakma 

Benim senden başka sığınacak limanım yok', 'Bir ateşim yanarım külüm yok dumanım yok Sen yoksan mekanım belli değil zamanım yok Fırtınalar içinde beni yalnız bırakma  Benim senden başk...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-atesim-yanarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömer Haybo''nun Son Günleri', 'omer-haybo-nun-son-gunleri-attila-i-lhan-49sy4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bıçak ısırmasın ömer haybo

dişleri çıtır çıtır çelik

yanılıp beyoğlu''na çıkmasın

topraklüle sokağını tutmasın

bütün şaraplarölü kırmızı

bütün kadınlar çabuk

hiçbiri durduğu yerde durmuyor

ömerhaybo''nun gözü hiçbirini tutmuyor

haydut ömer haybo

her gün onsekiz sularında acı siyah beyaz 

ondokuz ellibir de bir alman gemisini limandan çıkarıyor

yirmibir buçukta alkazar sineması''nda kötü seyirci

yarından sonra beklediğim ömer haybo

gelmeyecek ömer haybo

lionel hapton''a tutulmuş cazdan anlamaz

polis romanları yazıyor acaba neden yazıyor

parmak uçlarında bronz kuruşların madeni kirliliği

birkaç kere öldü ömer haybo

korsan ömer haybo

hangi şehirde olsa sabhları yabancı

boğulmuş geceler mahallesini bir türlü bulamıyor

hangi otobüse binmesi lazım bilemiyor yanılıyor

herkesin gittiği yer onun gitmeyeceği

terazi burcunun kötümser çocuğu 

namuslu bıyıkları kirli siyah

ah ömer haybo', 'Bir bıçak ısırmasın ömer haybo dişleri çıtır çıtır çelik yanılıp beyoğlu''na çıkmasın topraklüle sokağını tutmasın bütün şaraplarölü kırmızı ...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/omer-haybo-nun-son-gunleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler Ağlamaklı', 'geceler-aglamakli-fatih-alptekin-0jzyy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin koynundayım yine

Zifirde adın saklı

Yanar ansız gidişine

Geceler ağlamaklı.

Derin kuytulardan.

Uzanacak mı elin ?

Gülüşüne hasret kalmış

Ağlamaklı gecelerim.

Üşüyorum sensizlikte.

Tutan yok ellerimi

Yak bir kibrit yüreğime

Isıt gecelerimi.

Şarkılar söylüyorlar

Sensiz şimdi rüzgarlar

Kimseler de bilmiyor

Geceler nasıl ağlar.

Ay da pek karanlık

Çehresinde bir buğu

Ne yıldızlar aydınlık

Ne de geceler mutlu.

Biliyorum gelmezsin.

İş olsun benimkisi.

Benim tutsak gönlümden

Geçmez başka birisi', 'Gecenin koynundayım yine Zifirde adın saklı Yanar ansız gidişine Geceler ağlamaklı. Derin kuytulardan. Uzanacak mı elin ? Gülüşüne hasret ka...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/geceler-aglamakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-fatih-alptekin-xwmgl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu akşam yine çalmadı telefonum.

Bilemezsin bir tanem çok yorgunum.

Sabah oldu yolunu gözledim.

Kapıl bir sehere çok özledim.

Bir hikayem olsun benimde,

Sonunda elini tuttuğum

Sarılıp boynuna acıları unuttuğum.

Tutun bir rüzgara çok özledim.

Bilsen, nasıl da yorgun gözlerim.

Şafak söküyor işte,

hadi artık ufukta görünsene.

Tutup elimden beni de ,

Bir rüzgar gibi götürsene.

Dön demeye yetmiyor gücüm,

Şiir oldum, türkü oldum, kul oldum.

Yol oldum serildim yine,

Gel artık bedenimi çiğnesene.

Seni beklerim her seher,

Her yağmur akşamında.

Mecsim bahar oldu yol gözledim.

Gel artık karçiçeğim çok özledim.', 'Bu akşam yine çalmadı telefonum. Bilemezsin bir tanem çok yorgunum. Sabah oldu yolunu gözledim. Kapıl bir sehere çok özledim. Bir hikayem ol...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozledim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağların Kızı', 'daglarin-kizi-fatih-alptekin-j8o5e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Derin bir acı, ince bir sızı.

Taktın mı nişanı dağlarınkızı ?

Göçtün mü sende sıcak dağlara ?

Bıktın mı benden gönül hırsızı ?

Kurduğun hayallere ayaz mı vurdu ?

Büyülendin mi sen ömrümün yazı ?

Üşüştümü üstüne kuşları kurdu ?

Bir havlinde mi yok gelmeye bazı ?

Gezdiğin dağlara avcılar çıkmış

Attıkları saçma yüreğimdedir.

Ceylanımı kör olası bir avcı almış.

Gittiğin yollar üzerimdedir.

Bir daha konmaz mı bu dağa kuşlar ?

Bir maral geçmez mi derelerimden ?

İnip çıktığın patika yollar,

Dağ benim, benim üzerimdedir.

Ağlar mı deme koskoca tepe

İçerimde yanar nice volkanlar.

Ceylana vurulur kalır öylece.

Bizlere yakışmaz çokca sevdalar.

Gözlerin her seher gelir karşıma.

Bulutlar yetişir hep imdadıma.

İzleri kalmıştır karçiçeklerinin.

Tazelenmez ki, kırlarım benim', 'Derin bir acı, ince bir sızı. Taktın mı nişanı dağlarınkızı ? Göçtün mü sende sıcak dağlara ? Bıktın mı benden gönül hırsızı ? Kurduğun haya...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/daglarin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Olmak Vardı', 'cocuk-olmak-vardi-fatih-alptekin-s0g8t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İmkansızdı kolumuza kelepçe

Aşkın kendisiydi kendimiz

Yoktu elemli bir günümüz

Mutluyduk çocukken biz.

Adam olalım dedik,

Büyüdükte dünyaya.

Oysa nerden bilirdik.

En iyi adamın çocuk olduğunu', 'İmkansızdı kolumuza kelepçe Aşkın kendisiydi kendimiz Yoktu elemli bir günümüz Mutluyduk çocukken biz. Adam olalım dedik, Büyüdükte dünyaya....', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cocuk-olmak-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölemiyorum', 'olemiyorum-fatih-alptekin-nktrc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kasvet ve hüzün vardı gökte,

O gün bugündür gülemiyorum

Elveda yazılır mı böyle sevene

Sen yaşarken dünyada, ölemiyorum.

Dindi yaz yağmuru gibiydi,

Bir daha yağarmı bilemiyorum.

Kesildi türküler, kuşların sesi.

Sen yaşarken dünyada ölemiyorum

Müebbet cezandır bu hüzün bana 

Senden başkasını sevemiyorum. 

beklesede geceler beni bıçakla 

Sen yaşaken dünya da ölemiyorum. 

Saçlarımda izlerin var hala senin. 

Namluyu şakağıma koyamıyorum. 

Kalbimse hala kaldığın yerin 

Hançeri sineme vuramıyorum. 

Haklısın suçluyum hatamdı sevmek 

Ben suç işlemeden duramıyorum 

Bana ders oldu, çekipte gitmek. 

Senin gibi taş kalpli olamıyorum.', 'Kasvet ve hüzün vardı gökte, O gün bugündür gülemiyorum Elveda yazılır mı böyle sevene Sen yaşarken dünyada, ölemiyorum. Dindi yaz yağmuru g...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancısın', 'yalancisin-fatih-alptekin-k1qlz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne çetin bilmecesin anlayamadım 

Gün gibi hep doğup batacak mısın ? 

Aklımda yüzlerce soru bıraktın 

Anladım sevgilim sen yalancısın 

Girme rüyalarıma artık istemem. 

Al bu gözlerin sende kalsın 

Bu nasıl sevgidir hiç bilemem 

Anladım sevgilim sen yalancısın 

Uzak bir diyarda kur yuvanı. 

Gelmesin soluğun, rüzgarın bile. 

Yaktın gittinçocuksu umutlarımı 

Anladım sevgilim sen yalancısın 

Girmesin yuvana hiç bir dem neşe 

Yorganın, ayağından hep kısa kalsın 

Ne yazık ki benzetirdim seni güneşe 

Anladım sevgilim sen yalancısın. 

Artık söylenecek ne kaldı bende. 

Sukutun dolandı çileye, derde 

Gün gibi aşikar bir vefasızsın 

Anladım sevgilim sen yalancısın', 'Ne çetin bilmecesin anlayamadım  Gün gibi hep doğup batacak mısın ?  Aklımda yüzlerce soru bıraktın  Anladım sevgilim sen yalancısın  Girme ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalancisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yak..!', 'yak-fatih-alptekin-7k74p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzünde  ki çizgiler niçin 

Sırlı camlarda kendine bak. 

Bu yılda mutluluk isterse için 

Elinde ağlayan resmimide yak 

Derin çukurlar var yüzünde. 

Ağlamaktan mı, gülmekten midir ? 

Bir burukluk varsa içinde. 

Bir kibritte anılara yak. 

Kahroldu kader, yıkamadı seni. 

Kahraman oldun mutlu musun ? 

Yaşlardan kalan ela gözleri 

Gün gelirde avutur musun ?', 'Yüzünde  ki çizgiler niçin  Sırlı camlarda kendine bak.  Bu yılda mutluluk isterse için  Elinde ağlayan resmimide yak  Derin çukurlar var yü...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bu Rüzgarlar', 'ah-bu-ruzgarlar-fatih-alptekin-sirlq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yok kalemimde olmasa hiç kimsem. 

Aklıma düştüğün anlar koşarım ona. 

Nasıl bırakılırsın sen,bir bilsem. 

Bir daha yazmam seni sayfalara. 

Issız oluyor sensiz geceler, 

Bir gölge çıkıyor her kuytudan. 

Korkuyorum, bulamamaktan seni 

Uyanmak istemiyorum uykudan. 

Yadele gidecekmişsin söylediler. 

Ah bu rüzgarlar, halimi hiç bilmediler. 

Kalmadı özümde, sözümde 

Kör olası rüzgarlar bitirdiler. 

Mutluymuşsun öyle dedi biri. 

Bilemezsin nasıl dağıttı beni. 

Düşmüş resimlerim elinden 

Hiç anmıyormuşsun ismimi.', 'Yok kalemimde olmasa hiç kimsem.  Aklıma düştüğün anlar koşarım ona.  Nasıl bırakılırsın sen,bir bilsem.  Bir daha yazmam seni sayfalara.  I...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-bu-ruzgarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bensiz Kalmış', 'bensiz-kalmis-fatih-alptekin-1eo09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Parmağında yabancı iz 

O ellerin bensiz kalmış 

Sınırsızca yaşardık biz 

Hayallerin bensiz kalmış 

Masanda ki kağıtlarda 

Yalancı fal bensiz kalmış 

Hoş çizgiler yanağında 

Gülüşlerin bensiz kalmış. 

Kulağında sesimde yok 

Telefonlar bensiz kalmış 

Gözlerinde izimde yok 

Gözyaşların bensiz kalmış. 

Yüreğinde başka bir his 

Dudakların bensiz kalmış 

Dinlerken ağlardık biz 

Şarkıların bensiz kalmış. 

Saçında ki kimin eli 

Avutmuşlar eller seni 

Söz vermiştin nerde hani ? 

Yalanların bensiz kalmış', 'Parmağında yabancı iz  O ellerin bensiz kalmış  Sınırsızca yaşardık biz  Hayallerin bensiz kalmış  Masanda ki kağıtlarda  Yalancı fal bensiz...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bensiz-kalmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci', 'dilenci-fatih-alptekin-zxhed', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dilenci, 

Adım dilenci kalsın her dem. 

Her dem dileneceğim bil ki 

Görür mü gözlerin bilemem 

Senin vefan bu kadar mı ki ? 

Ellerim açık semaya doğru. 

Kirli ellerime bakar mısın ki ? 

Beklerim hep geçtiğin yolu 

Bu serseriyi anar mısın ki ? 

Güzel bir anım kaldı mı sende ? 

Verdiğim gülü unuttun mu ki ? 

Büsbütün silinip gittim mi bende ? 

O ela gözleri kuruttun mu ki ?', 'Dilenci,  Adım dilenci kalsın her dem.  Her dem dileneceğim bil ki  Görür mü gözlerin bilemem  Senin vefan bu kadar mı ki ?  Ellerim açık se...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dilenci-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri', 'serseri-fatih-korkut-1xray', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dün yine karasularımdaydın

yine bırakmadı peşimi gözlerin

tam tutuverecekken ellerini

kenetleniverdi ellerim

tam sevdiğimi söyleyecekken 

yine tutuldu dilim

yine masumdun 

eskisi gibi

yine kaldım tek başıma 

çaresiz ve serseri...', 'dün yine karasularımdaydın yine bırakmadı peşimi gözlerin tam tutuverecekken ellerini kenetleniverdi ellerim tam sevdiğimi söyleyecekken  yi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Korkut']::text[], 8.5, '{"poet":"Fatih Korkut","poet_slug":"fatih-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/serseri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Hariç', 'senden-haric-fatih-korkut-5es5a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hayat denen bu yolda

bulamadım bir liman

gözlerin hariç

budamışlar hayatımın en güzel dallarını 

sen hariç

kalmamış sevdiğim diyebileceğim bir güzel

sen hariç

yanan kalbimin külleri arasında bir gül açtırdım

senden hariç...', 'hayat denen bu yolda bulamadım bir liman gözlerin hariç budamışlar hayatımın en güzel dallarını  sen hariç kalmamış sevdiğim diyebileceğim b...', ARRAY['Türk Edebiyatı','Şiir','Fatih Korkut']::text[], 8.5, '{"poet":"Fatih Korkut","poet_slug":"fatih-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/senden-haric-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzelmez', 'duzelmez-ozan-arif-pu5nk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kör olan vicdanlar bakın da görün

Bakmayınca bu memleket düzelmez!

Şu çıban yarılıp içinden irin;

Akmayınca bu memleket düzelmez!

Kapanmalı bu milletin yarası

Ne kavganın,ne döğüşün sırası,

Evde huzur,yurtta dirlik çırası,

Yakmayınca bu memleket düzelmez!

Olmamalı Türk''ün Türk''ten şüphesi

Yol olmalı aşk dağının tepesi

Her kulağa birer sevgi küpesi

Takmayınca bu memleket düzelmez!

Beşeriyet kanununun çatlağı

Yurdu yaptı vurguncunun otlağı

Yetimin hakkını yiyen gırtlağı

Sıkmayınça bu memleket düzelmez!

Vallahi susamış arıyor vatan,

Yeni bur kumandan,yepyeni bir han;

Ben diyeyim Fatih,sen de Alparslan,

Çıkyanıca bu memleket düzelmez!

Koy desinler falan fikrin ozanı

Ozan Arif sen bırakma ezanı

Bismillah deyip de köhne düzeni

Yıkmayınca bu memleket düzelmez!', 'Kör olan vicdanlar bakın da görün Bakmayınca bu memleket düzelmez! Şu çıban yarılıp içinden irin; Akmayınca bu memleket düzelmez! Kapanmalı ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/duzelmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Anlatayım', 'kime-anlatayim-ozan-arif-gshsx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vatanımın gözünde yaş

Yurdu kime anlatalım?

Biz eylülde donduk gardaş,

Mardı kime anlatalım?

Şimdi yoktur suyu soran

Bizden makbul testi kıran

Milyonlara geldi boran

Ferdi kime anlatalım?

Yaptığı ne neler dedi

Ahbap oldu fare kedi

Sürüleri köpek yedi

Kurdu kime anlatalım?

Bu dert fazla devletlere

Biz dayandık bu dertlere

Fırsat geçti namerdlere

Merdi kime anlatalım

Arif kaçtı ağız tadı

Adalet mi bunun adı

Anamızı alan kadı

Derdi kime anlatalım?', 'Vatanımın gözünde yaş Yurdu kime anlatalım? Biz eylülde donduk gardaş, Mardı kime anlatalım? Şimdi yoktur suyu soran Bizden makbul testi kır...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kime-anlatayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şemdinli''den Telefon', 'semdinli-den-telefon-ozan-arif-wsulc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aloo...Angara  mı?Gonuşun susman!

Zor benim oraya erişmem begim.

Burası Şemdinli...Ben Çopur Osman,

Şart oldu sizinle görüşmem begim.

Neden mi aradım,hele bah şuna!

Yoksa sesim getmedi mi hoşuna?

Bize silah dağıtmayın boşuna,

Anarşistle filan vuruşmam begim.

Bir kere vuruştum aldım payımı

Hapiste geçirdim otuz ayımı

Şimdi tekrar gazıp gendi guyumu

Zindanda çürüyüp buruşmam begim.

Aloo..Dur gapatma dökem içimi

Sattım savdım davarımı geçimi

Ürüşvetle zor gurtardım gıçımı

Üç ay evvel bitti duruşmam begim.

Silah diye zırtımıza bindiniz

Şimdi niye dağıtmaya döndünüz

Ula bizi siz eşşek mi sandınız?

Ben daha o işe girişmem begim.

Hem köylüler ne yapacak silahı

Bu yolla mı bilacağız felahı

Hani gardaş gavgasıydı bu yahu

Ben öyle lafınan yarışmam begim.

Gardaşı mardaşı artık bırahıp

Bu gavga neymiş anlayın bahıp

Yerinizde olsam kürsüye çıhıp

Beşlik simit gibi gırışmam begim.

Gayrı benim külahıma anlatın

Enayisi biz miyiz be milletin

Cendermesi polisi var devletin

Dövletin işine garışmam begim.

Gedip de Arifi dinleyin bir de

Dünkü garışanlar şimdi bah nerde

Türkeş babo dört senedir içerde

Küsmüşem vallahi barışmam begim.', 'Aloo...Angara  mı?Gonuşun susman! Zor benim oraya erişmem begim. Burası Şemdinli...Ben Çopur Osman, Şart oldu sizinle görüşmem begim. Neden ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/semdinli-den-telefon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlığından Değil', 'varligindan-degil-riza-aslan-hrr64', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hiç birşeyin,

varlığından veya 

yokluğundan değil

tüm bu yaşananlar

kayıplar bir birikim,

-yılların getirdiği-

kayıplar yitik birer kent,

içinde nice umutlar,

nice sahipsiz yarın

aslında ;hiçbir şeyin

bitişi değil bu bitiş

kayıptı zaten var olması istenen.

hiç olmamıştı

olmakla olmamak arasındaki

o ince çizgi

kayıplar bir birikim sadece

gözlenilen

var olduğu düşünülen

hiç bir son

bu güne ait değil

Rıza Aslan

27-05-2001

Karacan Dersanesi 

Ankara', 'hiç birşeyin, varlığından veya  yokluğundan değil tüm bu yaşananlar kayıplar bir birikim, -yılların getirdiği- kayıplar yitik birer kent, iç...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/varligindan-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Mektup', 'aska-mektup-fatih-karacelik-oc4mp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İpeksi bir buğu gibi uçuşuyorken,

Hasretin damarlarımda;

Gözpınarlarımda alevlenir,

Tılsımlı o pak hayalin.

Bir turnanın kanatlanışında

Dilegelen demir ikonlar gibi...

Halbuki özlemindir,

Şimşekleri kahkahaya boğan;

Ve dalgaların iniltisi...

Ve yakamozun hüznü...

Müebbete mahkum duygularım

Firariler gibi dağlarda.

Dağlarda ateş yüklü eşkiyalar...

Eşkiyada hazan yemiş umutlar...

Masumun kanına girmiş umutlar...

Halbuki özlemindir,

Asiliğimin şahdamarı;

Ve öfkemin cansuyu...

Ve hırsımın nefesi...

...Ve ''ah''lar uzar gider

İçerimdeki yıldızlara dek.

Aynaların ürkek izdüşümünde

Gölgelerin ruhu canlanır.

Çağların dağdağasındaysa

Alevlenir sevdamın Kafdağı.

Halbuki özlemindir,

Kızılığı veren güneşe;

Ve mavinin dayanılmazlığı...

Ve yıdızların yalnızlığı...

Çığlıklar kopar semadan,

Beynimi saran silüetine eş.

Şahdamarımda kaybolunca adın

Mercanlar sarar dört yanım.

Sonra acıyla kurtulurum

Dünden, bugünden, yarından...

Halbuki özlemindir,

Hayatımda açan tüm çiçekler;

Ve onların renkleri...

Ve onların duyguları...

Efsunlu rüzgarlarımın ozanı...

Bir tufan olup yüreğimde,

Yak mazien kalan ne varsa.

Sonra imbiğinden damlat sevdanı,

Süz altın duygularımı yarınlarıma.

Ne olur tut beni,

Sensizliğin eşiğindeyim.

Ötesi çöl, ötesi deniz, ötesi...

Halbuki özlemindir,

Yeşerten yoluna ekili yıldızları;

Ve kuraklığın buzlu vahası...

Ve yağmurların kuru çağıltısı...', 'İpeksi bir buğu gibi uçuşuyorken, Hasretin damarlarımda; Gözpınarlarımda alevlenir, Tılsımlı o pak hayalin. Bir turnanın kanatlanışında Dile...', ARRAY['Türk Edebiyatı','Şiir','Fatih Karaçelik']::text[], 8.5, '{"poet":"Fatih Karaçelik","poet_slug":"fatih-karacelik","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/aska-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Cinnet...', 'yuregim-cinnet-sah-ali-yasar-1rvq5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitmek mi Zordur, Kalmak mı

Giden mi Ağlar, Kalan mı

Nedense O gün İkimiz de Ağladık...

Mavi Bereliler Gelmişti Sizi Almaya

Sekiz Neoplan Hazır Bekliyordu.

İstanbul''a Kar Yağıyordu Lapa Lapa

Bizi, İnadına Ter Basıyordu...

O Gün Solmuş Bir Yaprağın Marazı Vardı Yüzlerimizde

Cam Cilası Gözlerimizde Buğulu Hüzün Vardı...

Dünya Ne Kadar Büyük

Oysa Zaman Ne Kadar Dardı...

Tutsak da Elimizi Bırakmasak da,

Sarmaşıklar Gibi Yedi Koldan Sarılsak da,

Darılsak da Kadere

Alınıp Kırılsak da,

Yolcu Yolunda Gerek

Ayrılık Aşikardı...

Siz Jandarmasıydınız Kartal Yuvası Karakolların,

Biz İç Güvenlik Timiydik

Geçit Vermez Dağların...

O Gün Son Kez El Salladım Sana,

Arkandan Mırıldandım Yüreğim Cinnet...

Heyy Arkadaş! Sağol

Yurdumuzun Dağlarında Görüşürüz Elbet...

(15/02/1998-Tuzla)', 'Gitmek mi Zordur, Kalmak mı Giden mi Ağlar, Kalan mı Nedense O gün İkimiz de Ağladık... Mavi Bereliler Gelmişti Sizi Almaya Sekiz Neoplan Ha...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yuregim-cinnet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Hasret...', 'sevgiye-hasret-sah-ali-yasar-twsc2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki Kiprik Arası Kadar Yakınım Sana,

Uzanıp Tut Ellerimi Ne Olur

Keşmi Keş Yalnızlığın Ortasında...

Eğil de Kulak Ver Yüreğimin Sesine,

Gevşesin Yüz Hatlarımdaki Gerginlik

Gökyüzü Maviliğinde Kaybolsun Bakışlarım

Arzularım Karışsın Nefesine,

Özlem Dolu Her Temasında...', 'İki Kiprik Arası Kadar Yakınım Sana, Uzanıp Tut Ellerimi Ne Olur Keşmi Keş Yalnızlığın Ortasında... Eğil de Kulak Ver Yüreğimin Sesine, Gevş...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgiye-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlar olunca...', 'yarinlar-olunca-sah-ali-yasar-aqxvb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gök arınır bulutlardan

Yeni bir güne hazırlanır...

Söker kararmışlığını üzerinden

Döker içinde ne varsa başına illet

Bardaktan boşalırcasına fırtınalı

Toprağın özüne dolarcasına bereket

Yağan yağmurlarla yıkanır...

Aralar perdesini sis mağduru ufuklar

Bir bayram arifesinde

Çocuk neşesinde

Mavi entarilerle kuşanır...

Göz kamaştıran görkemliğiyle

Ötelerden görünür güneş

Çözer buzdan bedenleri

Bertaraf gönüllere uzanır...

Yarınlar olunca... 

Mevsimler bahar olur 

Baharlar bayram...

Dağlar silkinir kalkar yatağından 

Sırtlar omzuna ormanları 

Aşılmaz kale gibi dikilir doruklara

Gölgesi ülkemin sınırlarına dayanır...

Isınır akarsular

Köz düşer topraklara

Açar tomurcuklar kozalarını yeşil yeşil

Sürüngenler kış uykularından uyanır...

Yarınlar olunca...

Canlanır...

Can pazarı meydanlar canlanır...

Bir isyan çıkar zulmün saltanatına 

Bir direniş başlar kan revan 

Yer gök zangır zangır sallanır...

Şad olur Fatihlerin ruhu

Şahlanır mavzer yürek Türk Ordusu

Şanına yakışır zaferler kazanır...

Yarınlar olunca...

Aşınır taş duvar

Demir kapı

Benliğine mahpus fikir, özüyle barışır...

Ulaşır mahzene yıldızlardan mahyalar

Karanlığa müebbet gözler kamaşır...

Yıkılır esaretin dar kalıp hayalleri

Küf tutmuş düşler

Ay ışığına karışır...

Yarınlar olunca...

Zaman mahcuptur

İnsanlar mahcup... 

Hayal edilemeyen gün yaşanır...

Halaylar kurulur tutkulu halka

Davullar vurulur yabana fiyaka

Elemden değil bu sefer

Sevinçten gözyaşları boşanır...

Açılır hilâl hilâl burkulmuş kollar

Alınları öpülesi yiğitler

Düğün dernek karşılanır...

Yarınlar olunca...

Öksüz büyümez bebeler 

Gelin kızlar karalar takmaz...

Analar ağlamaz hiç 

Ağlamaz...

Yarınlar Olunca... 

Solmuş bayrağım 

Şehidimin kanlarıyla boyanır...

Bayrak namus 

Bayrak şeref 

Dikilir zirvelere

Mehmedimin Elleriyle 

Beklediği rüzgâr eser o zaman 

Dalgalanır 

Dalgalanır 

Dalgalanır...

Yarınlar olunca... 

Sevgilerimiz öğretilir çocuklara 

Sonra Türkülerimiz 

Mavi geceler dillere dolanır...

Belki bir nebze dokunur da hani

Al iner yanaklara

Boncuk gözler buğulanır...

Yarınlar olunca... 

Böyledir can kurban sevdamız

Başlayabilmek için iman

Yaşayabilmek için zaman

Anlayabilmek için de insan gibi insan...

Yarınlarda anlayacaklar bizi

Yarınlar olunca...', 'Gök arınır bulutlardan Yeni bir güne hazırlanır... Söker kararmışlığını üzerinden Döker içinde ne varsa başına illet Bardaktan boşalırcasına...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/yarinlar-olunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünceler', 'dusunceler-orhan-yuksel-xwdxc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün biterken,

karanlıkla birlikte gelir düşünceler.

dalgaların kıyılara bıraktığı deniz yıldızları gibi,

gecenin sonunda can çekişerek ölürler.

Yalnızlık,

alışılagelmiş, müzmin bir hastalık.

Küçük bir akvaryumda ben

okyanusu özleyen bir çaresiz balık.

Hayat sandığımız bir rüya alemi belki

-tıpkı Caldero''nun dediği gibi-

ve yok saydığımız herşey var, 

varlarda yoksa

gönül istediğinde yaşatacak bir yar 

olmasa da

her zaman yardan atan bir yar var

inandığımız herşey bir sanı aslında

sanılarda yanılgılara yol açar

var 

      yok,

             yok 

                     var…', 'Gün biterken, karanlıkla birlikte gelir düşünceler. dalgaların kıyılara bıraktığı deniz yıldızları gibi, gecenin sonunda can çekişerek ölürl...', ARRAY['Türk Edebiyatı','Şiir','Orhan Yüksel']::text[], 8.5, '{"poet":"Orhan Yüksel","poet_slug":"orhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dusunceler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Defa Gülümsedi Güneş Gözlerine', 'bir-defa-gulumsedi-gunes-gozlerine-orhan-yuksel-xyau4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzel bir insan olacaktın oysa…

Yüreğinde sevgi, gözlerinde pırıltı

          hiç eksik olmayacaktı.

Birlikte çok şeyler yapacaktık.

Gökyüzünü seyredecektik mesela

                    yıldızları, dolunayı, güneşin batışını

                    bıkmadan gülümseyen çiçekleri…

Bazı akşamlar, deniz kıyısına gidip

martıları izleyecektik, gökyüzünde uçuşan

ve taş sektirecektik suyun üzerinde…

Bir gün gelecek okula başlayacaktın

başında kırmızı kurdele,

gözlerinde büyümüş olmanın sevinci

                              olduğu halde.

Düşünceler belirecekti kafanda

          yaşama dair…

oturup konuşacaktık tüm bunları

paylaşacaktık düşüncelerimizi de

                    sevgileri paylaştığımız gibi.

Sonra bir gün ortada hiç neden yokken

Terk edip gidecektin belki

Ben ardından gözyaşı dökerken

Belki sende ağlayacaktın belli etmeden

Keşke böyle olsaydı!

Keşke!

Güneş ancak bir defa doğdu üzerine.

Keşke terk edip gitseydin

Keşke o günden sonra hiç görmeseydim seni

ancak her gün aynı güneşi, havayı,

aynı gökyüzünü paylaştığımızı bilseydim.

Bir defa gülümsedi güneş gözlerine 

ve sen kanatlanıp ayrıldın aramızdan

saçlarına kırmızı bir kurdele takamadan…

(6/12/1996)-ANKARA', 'Güzel bir insan olacaktın oysa… Yüreğinde sevgi, gözlerinde pırıltı           hiç eksik olmayacaktı. Birlikte çok şeyler yapacaktık. Gökyüzü...', ARRAY['Türk Edebiyatı','Şiir','Orhan Yüksel']::text[], 8.5, '{"poet":"Orhan Yüksel","poet_slug":"orhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-defa-gulumsedi-gunes-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak Vakti', 'aglamak-vakti-fatih-cinar-mtgn2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güngelir sevgilim beni ararsın

ararsın yanında bulamazsın

birdaha geri dönmem beni anlarsın

işte sen sevgilim ozaman ağla

üstüne bir çiçek koklamadım diye

resmini yırtıpta yakmadım diye

kırdın sen kalbimi hiç yoktan yere

işte sen sevgilim sen şimdi ağla

ben yine bulurum bir kafa dengi

sen kendi derdine oturup ağla

sonunda yalnız kaldın

bak bir başına

işte sen sevgilim sen şimdi ağla

müzik:fatih çınar', 'güngelir sevgilim beni ararsın ararsın yanında bulamazsın birdaha geri dönmem beni anlarsın işte sen sevgilim ozaman ağla üstüne bir çiçek k...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aglamak-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-fatih-cinar-bezt5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'birdaha görememektir

insanı deli eden

insan ağlar yaşadığını bilmeden

bir kaybediş öyküsüdür

gözlerinden süzülen

ölümdür ağlamaktır onun adı

yas tutmaktır

ona elveda derken', 'birdaha görememektir insanı deli eden insan ağlar yaşadığını bilmeden bir kaybediş öyküsüdür gözlerinden süzülen ölümdür ağlamaktır onun adı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/elveda-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Aşkın Var', 'senin-askin-var-fatih-cinar-8ou3f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'unuttum diyemem

dağlar gücenir

hala o yüce dağlarda

senin yolun var

uzak diyarlarda sevdam söylenir

benimse kalbimde senin aşkın var

arada kibirden engel olsada

mutlu yaşıyormusun

eller koynunda

beni bir ömür aramasandsa

güzel sesini duyamasamda

bilki kulaklarımda senin aşkın var

bazen elimde duman duman

yanan sigara

bazen gözyaşı damla damla

senden uzakta

o senli günlerden bana hatıra

hala gözlerimde senin aşkın var', 'unuttum diyemem dağlar gücenir hala o yüce dağlarda senin yolun var uzak diyarlarda sevdam söylenir benimse kalbimde senin aşkın var arada k...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/senin-askin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-fatih-cinar-sj0ty', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nasılsın ey koca şehir

yükü ağır beli bükülmüş 

yaşlı şehir

yalnızlığımın şehri

mutlulukları yutan

sevgileri unutturan

derdi bana tattıran

bunamış köhne şehir

lanet olsun sana

ey koca ankara!', 'nasılsın ey koca şehir yükü ağır beli bükülmüş  yaşlı şehir yalnızlığımın şehri mutlulukları yutan sevgileri unutturan derdi bana tattıran b...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ankara-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-arif-atalay-zfc90', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zaman en büyük dert,

zaman en büyük ilaç; 

zaman insanlara değil 

insanlar zamana muhtaç...', 'zaman en büyük dert, zaman en büyük ilaç;  zaman insanlara değil  insanlar zamana muhtaç......', ARRAY['Türk Edebiyatı','Şiir','Arif Atalay']::text[], 8.5, '{"poet":"Arif Atalay","poet_slug":"arif-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Şiir', 'ey-siir-sahbaz-hulusi-ljjod', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey şiir

Kanunlar önünde

Eşit olan insanlara inat

İnsanlara inat

Sen suç işle

Kanattığın yarayı

Saracak

Ne bir bez

Ne bir merhem bulunsun

Ceza kitaplarında

İşlediğin suça dair

Bir kanıta da

Rastlanmasın

Dağların çekemediği

Bir yükü

Sen yüklen

Ey şiir', 'Ey şiir Kanunlar önünde Eşit olan insanlara inat İnsanlara inat Sen suç işle Kanattığın yarayı Saracak Ne bir bez Ne bir merhem bulunsun Cez...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ey-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-sahbaz-hulusi-vvbcy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mecnun'' u çöllerden geri çağırın

Paylaşalım yalnızlığımı

Leyla'' nın gözlerini hayal edip

Ağlayıp durmasın öyle

Çöl ortalarında aşıklık taslamasın

Kararlılığını dumanlar arasına katılıp

Leyla'' yı yüreğinde pişirsin de göreyim

Leyla'' ya gelince onada sözümüz var

Leyla çekebilir mi benim kahrımı

Leyla tamamlayabilir mi beni

Leyla bana savaş açabilir mi

Çadırını acımla örmeyince

Kuştüyü yataklarda beklemesin öyle

Güzelliğini aynalara söylesin

Fildişi taraklara söylesin

Böbürlenmesin öyle

Biz ayı ve güneşi satın aldık', 'Mecnun'' u çöllerden geri çağırın Paylaşalım yalnızlığımı Leyla'' nın gözlerini hayal edip Ağlayıp durmasın öyle Çöl ortalarında aşıklık tasla...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/leyla-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeyince', 'olmeyince-fatih-alptekin-1flvq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim ıssız sevdalarım vardı,

Bilinmedik ,hesapsız.

Sen girdin kalbime, çaldın

Ver sevdalarımı hırsız.

Benim gülüşlerim vardı,

Şimdi ise ağlayışım.

Ben mutluluğumu istiyorum.

Al bu hüzün senin, senden almışım.

Çek git denmiyor artık bilirsin,

Ancak benide götür diyebilirim.

Papatya falımda ise,

Ölsem mi, kalsam mı hesabı.

Ölmeyince ölünmüyor bilirsin.', 'Benim ıssız sevdalarım vardı, Bilinmedik ,hesapsız. Sen girdin kalbime, çaldın Ver sevdalarımı hırsız. Benim gülüşlerim vardı, Şimdi ise ağl...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmeyince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Gurbette', 'soz-gurbette-sahbaz-hulusi-40wje', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben seni neden bekledim

Neden bu kadar nazı

Neden bu kadar azarı işittim

Beş dolar avucumun içinde

İşte hayat şimdi yandı ve bitti

Gözlerin avucumun içinde

Bir Polonya yosması gibi

Özgürlüğün güzelliğin

Sarı saçların mihriban türkün

Türbanın şeyhin plasiyerliğin

Antilop çarşıların ve kombinezonun

Avucumun içindeKorkma nazar almazsın

Kahve falın

Medyumların muskacıların

Yasin okuyucuların

Cevşen asanların

Mum yakanların

Yıldızname bakanların

Rüya yorumcuların

Avucumun içinde

Bursa kapalı çarşı

Gelinliğin esvabın

Bindiğn araba

Hacı babanın sakalı

Türbe ve cami ziyareti

Dağıtacak zekatı

Avucumun içinde

Öldürdüğün bir kişinin

Özrüyle yaşaman

Tövbe kapısında durman

Adağın göz nurun

Fidyen kredi kefaletin

Mazlumun ahı

Ve köle azatlığın

Avucumun içinde

İçinin kükreyen ırmakları

Sevgin nefretin

Gurbette olan ve gurbette kalan sözün

Yapma çiçeğin

İhanet ve küfrün

Göçebe kuşların

Semerkant Buhara

Ve ağaran saçlar

Avucumun içinde

Avucumun içinde', 'Ben seni neden bekledim Neden bu kadar nazı Neden bu kadar azarı işittim Beş dolar avucumun içinde İşte hayat şimdi yandı ve bitti Gözlerin ...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/soz-gurbette-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Elma', 'yarim-elma-sahbaz-hulusi-elp74', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göz yaşları

Susuz derelere akar

Kurumuş göllerde toplanır

Irmağından kimse faydalanmaz

Açlığı kayıptı

Hiçbir ilanla

Ve ödülle

Doyma tatma

Kavuşma bulunma

Umudu yoktu

Bekliyordu ama

Gelecek bir yolcusu yoktu

Belediği kundakladığı

Emzirdiği büyüttüğüü

Özlemi vardı yalnızBekarların beklediği

Naylon kızlar çıkmıştı

Bunun naylonunun

Hiçbir anlamı yoktu

Bir iç kanama gibiydi

Dindirilmesi sağması

Pıhtılaşması olanağı yoktu

Sanki hemofili idi

Sistem kilitlenmişti

Evlatlık ve Zeyd yoktu artık

İki özlem iki ayrı dünya

Elmanın yarısı yoktu

Münafığı yoktu

Emini olsun

Bacası dumanı

Konuğu ikramı

Alanı satanı

Hudeybiyesi Kubaysı

Seveni bekleyeni

Ağlayanı arayanı bulanı

Sevdası yoktu sabrı olsun

Yarım bir elma

Kaç peygamber

Bu uğurda dua yapmıştı

Adak adamıştı

Yahya aramıştı

Yaşayanı öleni duası

Amini yoktu bunun

Yarım bir elma

Hiç tamamlanmadı

Gözyaşları bir dua mıydı

Bir isyanmıydı

Gıdası ateş olan

Semender balığı mıydı', 'Göz yaşları Susuz derelere akar Kurumuş göllerde toplanır Irmağından kimse faydalanmaz Açlığı kayıptı Hiçbir ilanla Ve ödülle Doyma tatma Ka...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yarim-elma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rumeli Türküsü', 'rumeli-turkusu-sahbaz-hulusi-4465n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bıraktım seni

Asılı bir tavanda 

Bir bebe beşiği olarak

Baltamı kütüğünde bıraktım

Dağladım yüreğimi bıraktım geride

Tunayı bıraktım

Asma bahçelerini

Göğermeden erikleri

İncirleri daha olmadan

Mayalanmadan sütler bakraçlarda

Dövülmeden mutunlarada ayranlar

Kaymağımı, özümü

Peteğimden balımı ayırdılar

Çarığımdan, poturumdan, fesimden,

Fistanımdan, fitamdan, feracemden,

Üç dallı eteğimden ayırdılar

Bir daha görmemek üzere

Dönmemek üzere 

Ayrıldım sevgilimdenÇanakkale'' de ve Yemen'' de

Ben dövüştümse de

Rüştiye mektebini okudumsa da

Manastırda

İstanbul hayaliyle yandım

Eminönü'' nden Karaköy'' e geçerken

Hayretler içinde kaldım

Sultanahmet meydanında 

Turist namıyla benle konuştular 

Hala Erzincan'' da olan Fahriye Abla'' yla

Maraş'' lı Şeyhoğlu arasındaki ilgiyi kuramadım

Arktan su sularken

Kaç öküzü patlattı

Sabanın savurduğu toprak

İnebahtı, Preveze, Barbaros

Uruç Reis ve Cezayir

Korsanlarının eline geçti şimdi

Eyvah 

Bağrında kaç gül açtı

Kahpe Gırnata''nın

Altın Kadeh

Meftunum güle

Ole ole 

Şala ve ala

Kahpesine zil takıp oynamasına

Bitmeyen gece başladığında

Lale açmasını niye beklersin

Göğsünde 

Serin selviler altında, mezar taşlarındaki

İbareyi ve ifadeyi değiştirdikleri halde

Çanakkale geçilmezse

Kime hala bu vize

Miracını mı kutluyorsun Efendimizin

Yoksa doğumunu mu

Regaib gecesi ne anlam taşır

Taleal Bedru Okuyarak

Ayın doğuşunu kime farkettirmeye çalışıyorsun

Selimiye'' nin minaresini

Mahyasını, 

Taşların direncini,

Sinan'' ın fendini,

Keserini,

Malasını,

Kellesini,

Kim uçurdu Şehzade Mustafa'' nın

Rızk ve ekonomiyi

Riski ve ticareti

Dolunayı inkar etmeyi

Gülü soldurmayı

Teammüden kim azmettirdi sana

Öküzler ağladı

Saban ağladı bu topraklarda

Makedonya yasa bulandı

Konavalı

Atını gerisi geriye sürerek

Terk etmek zorunda kaldı

Doğduğu toprakları

Geleceğine ağladı dağlar taşlar

Kağıthane deresi bekliyordu onları

Altın tepsi, Sağmalcılar, Paşabahçe 

Zeytinburnu, Avcılar bekliyordu onları

Yozgat, Çorum, Samsun bekliyordu

Söke ve pamuk tarlaları

Çır çır makineleri, 

Forbes Meyan fabrikası

Orhangazi, Bursa bekliyordu onları

Kavun, karpuz 

Eriği, inciri, narı parayla alıyorduk

Ve hasrettik Doyra'' nın balık etine

Kızlarımız burçak tarlasında gelin olamıyordu

Alişimin kaşları çatıldı

Debreli Hasan

Eşkiyalığa tövbe etse de

Kimse özrünü kabul etmedi

Halbuki Atçalı Kel Mehmet gibi

Hademe-i Devlet diye para da bastırmamıştı

Tuna aksa ne olur

Akmasa ne olur artık

Şimdi soydaştım

Karacaali'' den getirdiğim lastik yemeniler

On senedir giyiyorum

Huzurum kaçtı

Tren raydan çıktı

Yitirdik tüm değerlerimizi

Onur üzerine hiçbir söylem 

Söyleyemez oldum

Türkülerim ağladı sahipsizlikten

Üsküp ağladı, Gevgili ağladı

Yahudi tüccarlarına taş çıkartan

Kırcaali'' li ağladı

Vardar ovası ağladı

Urba, fıta, peşkir ağladı

Gelberi ağladı

Orman ve ağaç ağladı

Paleler ağladı

Yorgi ağladı

Kirletilmek korkusuyla

Tuvaletler ağladı

Maşatlıklar 

Kristo ağladı

Bağlar 

Erişilmez ve ulaşılmaz bir örnekle

Dallarına asılan ücretlerini

Anıt bir efsane olarak

Saklamak üzere 

İçin için ağladı

Köprüler ve medreseler

Duvarlar ve taşlar

Kelime-i tevhid'' li sancaklar

Hutbeler ve dualar

Akıncı beyi ağladı

Elifba

Mızraklı ilmihal

Enver-ül Aşıkin

Niyaz-i Mısır'' ı

Nur'' ül Arabi

Efendi Baba

Süleyman Hilmi

Terketmek zorunda kaldıkları için

Secde edilmiş toprakları 

Hüngür hüngür ağladı

Cami duvarı

Musalla taşı

Musallat olacaklar diye ağladı

Ertuğrul ve Osmanbey

Gaziorhan, Şehzade Süleyman,

Rumeliye geçiren sal

Bakıp bakıp akıbetine ağladı

Boşnak ağladı

Pomak ağladı

Arnavut ağladı

Türk ağladı

Çingeneler

Atlar ve taligalar ağladı

Ocak ve kazan,

Küpler, ambarlar,

Çömlek ağladı

Yel olup savrulmaktan

Abdülhamit Han'' a sahip çıkmamaktan

Bir intizar ile savrula savrula

Saman ve çöp ağladı

Cephanemiz,

Silahımız,

Rızk aletimiz,

Çapamız ve kazmamızdı

Ve Menderes ırmağı su kaynağımızdı

Her yıl birkaç can alırdı

Menderes akar akar

Boz bulanık akar

Menderes yüzünden 

Kaç ana ağlardı geride

Bilinmez

Menderes akar 

Şeker şerbeti yapılmak için

Ve üç beş damla sirke

Veya ulaşıklı biberle içilmek için

Gazlı bidonlara konulur 

Menderes'' in suyu

Pamuk tarlalarının dibinden

Mile bulanmış bir şekilde

Tarlalara vura vura 

Çarpa çarpa akar

Savuca köyünden

Sabah beşte

Bir traktör römorku dolusu

Kadın - erkek

Pamuk tarlalarına koşar

Güneş doğmamıştır

Anneler yanlarındaki

Çocuklarının dizisinide 

Çapalamak zorundadır

Yevmiye ver amele

Satılmış bir beden

Belim koptu anne diyen çocuklar

Ve güneşin tepede

Ağır ağır yükselmesi

Kızgın toprak

Yılgın insanlar

Hafta başında

Çarşamba'' da

Ücret dağıtır dayıbaşılar

Perşembe birinci günümüzdür

İş başında 

Ne Cuma selası ne ezan sesi

Yalnız Menderes'' in sesi

Ve akması

Kala kalırız muhacirliğimizle

Menderesler gibi

Mahzun ve ağlamaklı

Ben size ne yaptım der gibi

Asılırız zamana

Kefen gibi elbiselerimizle

Paydos,  boynumuzdaki ipi

Gevşeten bir iskemle gibiydi

Söke,

Forbes Meyan Fabrikası,

Harç tenekeleri,

Malamız, küreğimiz

Ayrılmaz bir parçamızdı

Köprü üzeri 

İş bulma kurumumuzdu

Bir genel müdürün karşısında

Durur gibi duruyorduk

Çiftlik sahiplerinin karşısında

Velinimetmizdi onlar

Saygıda kusur affedilmezdi

Sanki sur üflenmiş

Kaçacak yerler arayan

Sığınmak için kuytular

Ağlamak için duvar dipleri

Pamuk tarlalarında 

Cibinlik içinde yatar

Sabah vakti kırağı düşerdi yüreğimize

Çocuklarımız 

Ve parasız yatılı okullar

On iki yaşında başlayan 

Bir askerlikti sanki

Depremler 

Yüksek seviyedeydi içimizde

Su satmak 

Turşu sarmak

Daha ileride

Seslen ne olur duyarım

Kulağım sende

Araya kim koydu bu telleri

Kim gözetliyor beni

Toprağımdan beni ayıran kim

Kurusun elleri

Ebu Leheb gibi', 'Bıraktım seni Asılı bir tavanda  Bir bebe beşiği olarak Baltamı kütüğünde bıraktım Dağladım yüreğimi bıraktım geride Tunayı bıraktım Asma ba...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":247,"source_url":"https://www.antoloji.com/rumeli-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-bora-alagoz-i13ol', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'samuray kılıcı kadar keskin

acılardan türedim ben

en güzel baharlar

gözyaşlarımla yeşertir çiçeklerini...', 'samuray kılıcı kadar keskin acılardan türedim ben en güzel baharlar gözyaşlarımla yeşertir çiçeklerini......', ARRAY['Türk Edebiyatı','Şiir','Bora Alagöz']::text[], 8.5, '{"poet":"Bora Alagöz","poet_slug":"bora-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ben-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın Güzeldir', 'kadin-guzeldir-nurullah-can-z9igk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beyaz bir kadındır sabah.İpekli elbise giyer

Bahçesini sularken incecik şarkılar söyler

Elleri güzeldir yüzük takar.Eladır gözleri

Kocasını uyandırır terlik tutar süt taşırır

En çok sabun kokan saçlarını severim ben onun

Aynalım derim hep ona şiir atarım balkonuna

Sarışındır öğle vakitleri kısa eteklidir

Şıpıtık giyer tango dinler gözleri hareli

Sokakta eski sevgilileriyle karşılaşınca

dudaklarını ıslatır.Güzeldir ayak bilekleri

Halhal takar mektup yazar ağır kokular sürünür

Hiç çocuğu olmamıştır.Yastığında dul sıcaklığı

Akşamüstleri esmer bir kadındır.Hüzünlü

şarkılara banzerler.Eski fotoğraflarına bakar

Çay demler sedire uzanır fasıl dinlerler

Kulakları güzeldir küpe takar reçel kaynatır

Tekir kedileri vardır.Çocuklarını erken yatırıp

gece deniz gibi kabarır erkeklerini yorarlar

Şairler ayak parmaklarının ucunda yürürler

Gece olur.Ay çıkar.Kadınlardan korkarlar', 'Beyaz bir kadındır sabah.İpekli elbise giyer Bahçesini sularken incecik şarkılar söyler Elleri güzeldir yüzük takar.Eladır gözleri Kocasını ...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Can']::text[], 8.5, '{"poet":"Nurullah Can","poet_slug":"nurullah-can","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kadin-guzeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlılık Şiirleri', 'yaslilik-siirleri-nurullah-can-l5yjy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah,yatakta

Odamda solgun bir gün ışığı 

Uyanmak istemiyorum dünyaya

Uyumak sonsuz saatlerin yalnızlığına

Sonra bir ilaç bir ilaç daha

Kuşluk vakti,bahçe

Yaşlılık ne zor şeymiş diye mırıldanıyorum

Acıyla gülümsüyor yorgun bakkal

Gazeteyi okuyorum ölümler ölümler

Öğle,Bahariye

Martılar çığlık çığlığa defne yaprakları

Ben bir köşedeyim kitaplarım sessiz

Uğulduyor yüreciğimin tapınakları

Bir aziz olmalıydım ben ya da bir derviş

İkindi,sokaklarda

Eve dönüyoruz bütün kuşkuları terk edip

Sorsalar haykırırdım diyor peygamberliğimi

Ben odamı düşünüyorum o Babil bahçelerini

Akşam,ev

Korkak bir şairim ben. Ova rüzgarlarında

üşüyüp şiirlerini erzak torbasında unutan

bir zavallı. Mahzun eşyalar gibi yalnız

Unutulmuş kasaba yolları gibi ıssız

Gece yarısı,tavanda depresyon böceği

Uyusam yine bir rüya görsem

Uyansam o sonsuz Arkadya çayırlarında

Elimde serseri bir kargıyla koşsam

Takılsam yine çılgın rüzgarlarıma', 'Sabah,yatakta Odamda solgun bir gün ışığı  Uyanmak istemiyorum dünyaya Uyumak sonsuz saatlerin yalnızlığına Sonra bir ilaç bir ilaç daha Kuş...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Can']::text[], 8.5, '{"poet":"Nurullah Can","poet_slug":"nurullah-can","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yaslilik-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fetih', 'fetih-okkes-yuksek-yx6br', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sene bindörtyüz elli üç, bir bahar sabahı, 

Bir genç vardı atının üstünde pür sevdalı, 

Müjdelemişti peygamber bir fetih olacak, 

Dikilmeliydi Bizans''ın surlarına sancak, 

Peygamberin ismini surlara dokumuştu, 

Gece dualarda, gündüz cephede coşmuştu, 

Ya ben, ya Bizans diyordu geri dönmek olmaz, 

Can, baş koymuştu bu yola azmi asla yılmaz, 

İşte o gün, o sabah dualar gerçekleşti, 

Şanlı hilal Bizans''ın surlarına dikildi, 

Ey şanlı Fatih, ey büyük insan kalplerdesin, 

Bayraklaşan şahsınla her daim ellerdesin.', 'Sene bindörtyüz elli üç, bir bahar sabahı,  Bir genç vardı atının üstünde pür sevdalı,  Müjdelemişti peygamber bir fetih olacak,  Dikilmeliy...', ARRAY['Türk Edebiyatı','Şiir','Ökkeş Yüksek']::text[], 8.5, '{"poet":"Ökkeş Yüksek","poet_slug":"okkes-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fetih-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nef''i Yolumdan Çekil', 'nef-i-yolumdan-cekil-sahbaz-hulusi-3k64f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nef'' i çekil yolumdan

Ben bir şair değil

Deliyim

Hayatı

Horosan'' ın köpekleriyle

Harlem'' in gangsterleriyle

Paris'' in züppeleriyle

Paylaşarak geçirdim

Gönlüm kayda değer

Bir titreşime sahip değil

Nef''i çekil yolumdan

Katilinin katili benim

Katilinin muradı benim

Benimle uğraşamazsın

Çekil yolumdan

Münafıklığıma sebep olma

Vebal alırsın

Benimle yürüyemezsin

Yolda kalırsınCariyeler o cariye değil

Kime şiir yazacaksın

Nef''i çekil yolumdan

Etekler şimdi yırtmaçlı

Mucize olamaz artık sözün

Tutiler suni yemle beslenmekte', 'Nef'' i çekil yolumdan Ben bir şair değil Deliyim Hayatı Horosan'' ın köpekleriyle Harlem'' in gangsterleriyle Paris'' in züppeleriyle Paylaşara...', ARRAY['Türk Edebiyatı','Şiir','Şahbaz Hulusi']::text[], 8.5, '{"poet":"Şahbaz Hulusi","poet_slug":"sahbaz-hulusi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nef-i-yolumdan-cekil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-hakan-hallac-4jbgv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalnızlık  gibisi varmı bufani dünyada 

         yaşamın anlamsız tadına varılır

         gecenin gündüzün belli olmadığı

         mapushane gibidir yalnızlık

      

      o yüzdendir ki benim için,

      HAYAT BİR GÜL BAHÇESİ DEĞİL;

      DİKEN TARLASIDIR....', 'yalnızlık  gibisi varmı bufani dünyada           yaşamın anlamsız tadına varılır          gecenin gündüzün belli olmadığı          mapushane...', ARRAY['Türk Edebiyatı','Şiir','Hakan Hallaç']::text[], 8.5, '{"poet":"Hakan Hallaç","poet_slug":"hakan-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalnizlik-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Sonu Şiiri', 'gece-sonu-siiri-halil-kosem-dee3t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bozkırda çiçeklenmiş

Eğreti, yosma, dişi

Ay altında salınan badem ağaçları

Gidip gelen göçebe kervanlara

Ve dağ köylerinin çıplaklığına

Yazılıdır yazgınız gece sonlarında...

Kuyubaşı çıkrığı

İmbiklerde ağıtlarla toplanır kovanız

İçi geceye bulanmış denizdir

			Şimdi

İşbaşı yapan şiirde', 'Bozkırda çiçeklenmiş Eğreti, yosma, dişi Ay altında salınan badem ağaçları Gidip gelen göçebe kervanlara Ve dağ köylerinin çıplaklığına Yazı...', ARRAY['Türk Edebiyatı','Şiir','Halil Kösem']::text[], 8.5, '{"poet":"Halil Kösem","poet_slug":"halil-kosem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gece-sonu-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Kafa', 'ah-kafa-ozan-arif-r7xbc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu dünyada zevk sefa

Bir devran sürmek varmış.

Ulan kafa ah kafa,

Bugünü görmek varmış.

Vatan dedim,yurt dedim,

Vatandan sürgün yedim

Tek doğru ben mi idim

İpe un sermek varmış.

Hey gidi aptal hey hey

Bak yaşıyor paşa bey

Neyimiş de yolsuz köy

Köprüsüz ırmak varmış.

Bu işler nene bırak

Kel başa şimşir tarak

Ot gibi yaşayarak

Murada ermek varmış.

Şu ömrüm bile bile

Baştan sona hep çile

Rüşvet ile torpile

Kafayı yormak varmış

Bugünleri bilip de 

Türkiye''de kalıp da

Bir yolunu bulup da

Anap''a girmek varmış.

Kaç tane ozan gelmiş,

Çoğu aç sefil ölmüş

Ozanlık iş değilmiş

Bu sazı kırmak varmış.

Eloğlu davul çaldı

Başbakan kızı aldı

Ben saz çaldım ne oldu

Davula vurmak varmış.

Ozan Arif kes burda

Günaha girme bir de

Biliyorsun mahşerde

Hesap da vermek varmış.', 'Bu dünyada zevk sefa Bir devran sürmek varmış. Ulan kafa ah kafa, Bugünü görmek varmış. Vatan dedim,yurt dedim, Vatandan sürgün yedim Tek do...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ah-kafa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İş İşten Geçer', 'i-s-i-sten-gecer-ozan-arif-brbzk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İbret al gardaşım az kulak ver de

Ar''ım dersin amma iş işten geçer.

Kızıl afat girer ise bu yurda

Zorum dersin amma iş işten geçer

Üzülerek söylüyorum saz ile,

Bu sözlerim kafanıza yazıla,

Mavi,yeşil,beyaz döner kızıla,

Sarım dersin amma iş işten geçer.

Tarlana tohumu mecbur ekersin

Ak alnından emek teri dökersin

Hasatı el yapar boynun bükersin

Darım dersin amma iş işten geçer.

Dersin ki benim de bir törem vardı

Davul zurnam ile kanım kaynardı

Erzurum''da dadaşlarım oynardı

Bar''ım dersin amma iş işten geçer.

Varlığını göster gardaşım önce

Destek ol hemşehrim ülkücü gence

Kızıl balyoz kuş beynine inince

Varım dersin amma iş işten geçer.

Arifim sözümü yayın bucağa

İnciri dikerler senin ocağa

Her gece verirler başka kucağa

Karım dersin amma iş işten geçer.', 'İbret al gardaşım az kulak ver de Ar''ım dersin amma iş işten geçer. Kızıl afat girer ise bu yurda Zorum dersin amma iş işten geçer Üzülerek ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/is-isten-gecer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sütyolu', 'sutyolu-suleyman-sahra-erok6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'küçük bir kızım henüz onüç

sizin beni ağlatmanız pek güç

geceyi kısaltırım kışın bile usluyum hem

uyuyun efendim ben hiç rüya görmem

gündüzü doldururum elim hamarat

vakitsiz özlemem annemi olun rahat

hep gülün hep oynaşın ne aç kalırım ne çıplak

her yerde bulunur bir kaç yaprak terkedilmiş başak

küçük bir kızım söylenmem böyle kendimle gülünç

başkadından öğrenmek pek güç

ıslanmasın diye devletim yıkamam içimin çamaşırlarını

kirlenmem yine de çünkü hiç bakmam kapıdan dışarı

getirdikçe kahya güzel erzağı donatırım sofranızı

işim var iştahım doygun siz çoğaltın varlığınızı

hanım kız süslenirken çatlayan aynaları

siler süpürürüm gözüme dikerim parçaları

konuklar yakınlar gelenler kalanlar ne de çok hamfendi

aman üzülmeyin yetişir yetiştiririm beceririm ayak altından çekilmeyi

konuş büyüdün de artık bana kalfa

yoksa dönemem köyüm çok uzakta

öldüğünde küçükbey okul yolunda

karar verdim yol yok yola çıkmaktan başka

yerleştiğimde annemin rahmine yürünecek bir yol vardı

çıktığımda yeryüzüne beni yürüten bir meme vardı

sizinki ne o bile bitti de burdayım sütün beni getirdiği yerde

gidersem gücenmeyin bulmalıyım çağırıyor kaynak nerde

boynumu boğdum doğurdum göğsümü

yok yok görmüyorum arkamı önümü

çağırmıyorum kimseyi saçlarımdan çekip vursun duvara başımı

kanımla kirletmesin terimle temizlediğim duvarı

utanır saklarım çingeneler terkederse kırları

eğri ve de büğrü ıslak ya da kurak kim bulacak yolları

döneceksen geriye duvarı silen yol damarda akmalı

hayretiniz yetmiyor şüpheniz yoruluyor bu bendeki sabra

şaşmayın siz unuttukça hayattasınız ben yolcuyum andıkça

gevezeliğimden değil bu sözler seslerin yolculuğundan

bellediğim sözcüklerin yeşerme zamanından

küçük bir kızım henüz onüç

sizin beni anlamanız pek mi güç', 'küçük bir kızım henüz onüç sizin beni ağlatmanız pek güç geceyi kısaltırım kışın bile usluyum hem uyuyun efendim ben hiç rüya görmem gündüzü...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sahra']::text[], 8.5, '{"poet":"Süleyman Sahra","poet_slug":"suleyman-sahra","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sutyolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C-5', 'c-5-ozan-arif-j5suu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hakim bey...Hakim bey.. bütün dünyamı,

Yıkarak yaptılar benim sorgumu.

C-5 denen yere gözleri bağlı,

Tıkarak yaptılar benim sorgumu.

Savcının ağzından şu okunanlar

Benim suçum değil hep yalan bunlar!..

Dövdüler hakim bey,ağzımdan kanlar,

Akarak yaptılar benim sorgumu.

Düştüm ki bir sürü moskof piçine

Biri de demedi bunun suçu ne?

Tabancayı ta ağzımın içine

Sokarak yaptılar benim sorgumu.

Döve döve işettiler altıma

Bayıldıkça sarıldılar hortuma

Islatıp ıslatıp tekrar sırtıma

Çıkarak yaptılar benim sorgumu

Kimi vurdu,kimi baktı seyrime

Cop izleri oluk oldu böğrüme,

Sigaranın ateşiyle bağrıma

Çökerek yaptılar benim sorgumu.

Kimi şarap içti,kimisi rakı,

Karma karış oldu her türlü koku.

Döverek pisletip ağzıma boku

Dökerek yaptılar benim sorgumu.

Jileti vurdular ileri geri

Dilim dilim oldu yarıldı deri

Yarılan yere tuzu biberi

Ekerek yaptılar benim sorgumu.

Tırnağım söküldü kelpeten ile

C-5 ler konuşsa gelse de dile

Su diye yalvardım,hep güle güle

Bakarak yaptılar benim sorgumu.

Şişe ile zorladılar gıçımı

Tuzlu su verdiler yaktı içimi

Derisinden kopanaca saçımı,

Çekerek yaptılar benim sorgumu.

Allahsız-kitapsız sekiz on ayı,

Suçsuzum dedikçe vurdu sopayı,

Burnuma soktular tornavidayı

Bükerek yaptılar benim sorgumu.

Biri bu Soyer''de domuzun dölü!..

Sesinden tanıdım değilim deli.

Tenasül uzvuma ceryanlı teli

Takarak yaptılar benim sorgumu.

Hakim bey,erkeklik kalmadı daha

Ölem diye çok yalvardım  Allah''a.

Avuç içlerimden tutup çarmıha

Çakarak yaptılar benim sorgumu.

Babamı almaya eve gittiler

Anama avradıma neler ettiler

Çocuğum boğazından tuttular

Sıkarak yaptılar benim sorgumu.

Yavrumu görünce çıldırdım dedim(!)

Ne derseniz kabul saldırdım dedim.

Atatürk''ü bile öldürdüm dedim

Yakarak yaptılar benim sorgumu.

Ozan Arif anlatamaz kaygımı

Yitirdim kanuna olan saygımı

Velhasıl ''devlete güven'' duygumu

Sökerek yaptılar benim sorgumu.', 'Hakim bey...Hakim bey.. bütün dünyamı, Yıkarak yaptılar benim sorgumu. C-5 denen yere gözleri bağlı, Tıkarak yaptılar benim sorgumu. Savcını...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/c-5-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat', 'anlat-ozan-arif-lxvi2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dile gel be Anadolu''m dile gel,

Dile gel bugünü dünü de anlat.

Kimse beni dinlemiyor hele gel,

Hele gel istersen bunu da anlat.

Anlat,çünkü ben anlatsam can sıkar

Muş çalışır İstanbul yer,Muş bakar.

İzmir mamur Bursa şenmiş ne çıkar

Yozgat''ı  Bitlis''i,Van''ı da anlat.

Sen anlat,bulunur elbet bir duyan

Yerli kırem beğenmezken şu bayan

Ağustos ayında orak sallayan

Sıcaktan kavrulan teni de anlat.

Hep sustun harama helal denirken

Bağrında öksüzün hakkı yenirken

Küfür kara kara filizlenirken

Yüreğe gömülen dini de anlat.

Sen vatansın susma, söyle adını,

Çeken bilir her acının tadını.

Üstünde yaşayan karabudunu,

Budun''dan habersiz han''ı da anlat.

Yaraların eskimedi çok yeni

Kan gölüyken biliyorum ben seni

Kurşunların ıslak çaldığı dünü

Dün''lerin yediği gün''ü de anlat.

Ne günü unut sen ne de geceyi

Unutmaktan ateş sardı bacayı

Kanlı katil yetiştiren hocayı

İlimi,irfanı,feni de anlat.

Bir selden kurtuldun kim idi bendin

Bendi de bilirsin seli de kendin

Hangi yöne sürüklenmek istendin

Gelecek öğrensin yönü de anlat.

Tarih bazan inkar eder gerçeği.

Birliğine kim sapladı bıçağı?

Su ile beslenmez huzur çiçeği

Çiçeği besleyen kanı da anlat.

Şu ananın gözündeki yaşa bak!

Şu mezarın başındaki taşa bak!

Ne yazıyor doğumuna yaşa bak!

Uğrunda verilen canı da anlat.

Tekme vuran çok olurmuş düşküne

Arif miydi bomba koyan köşküne?

Suçlu isem susma Allah aşkına,

Beni de beni de...beni de anlat.', 'Dile gel be Anadolu''m dile gel, Dile gel bugünü dünü de anlat. Kimse beni dinlemiyor hele gel, Hele gel istersen bunu da anlat. Anlat,çünkü ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/anlat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılmışım', 'yanilmisim-adil-koruyan-tqf2t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çölde yolunu kaybetmiş mecnun misali

Savrulurken fırtınalar önünde.

Aşka susamışlığın ateşi ile yanmış,

Kum taneciklerini su sanıp, aldanmışım.

Güneşin yakıcı ışıklarıyla kavrulmuş,

Çatlayan dudaklarımla adını anarken,

Suya susamışlığın özleminden

Acıyı mutluluk sanıp, aldanmışım.

Çöl ortasında düşler dünyası yaratmış,

Hayalinle acıyı ve mutluluğu birlikte yaşarken;

''İnan'' deyişindeki gizemli sesle uyanmış,

Gördüğüm bir serapmış, yanılmışım.

24.05.2001', 'Çölde yolunu kaybetmiş mecnun misali Savrulurken fırtınalar önünde. Aşka susamışlığın ateşi ile yanmış, Kum taneciklerini su sanıp, aldanmış...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanilmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoşum', 'sarhosum-fatih-alptekin-gz9dc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarhoşum yine, başım dumanlı.

Anılar depreşir durur içimde.

Kadehlerde senin ismin mi saklı

Saatler şerefe vurur her gece.

Müptela yüreğim dayanmaz buna.

Karanlık odamda bir yerdesin sen.

Çekipte gidemezsin çok uzaklara.

Derin delhizlerimde yaşarsın sen.

Bıçak nakış işler fikrime benim.

Ektiğin hüzünleri biçerim ben.

Bende kalmış güzel sözlerin senin.

Her gece yolunu beklerim ben.

Pek zamansız oldu gidişin,

Apar topar çıkıverdim içinden.

Nerde kaldı deli gibi sevişin ?

Vurdun hançerini gidiverdin sen.', 'Sarhoşum yine, başım dumanlı. Anılar depreşir durur içimde. Kadehlerde senin ismin mi saklı Saatler şerefe vurur her gece. Müptela yüreğim d...', ARRAY['Türk Edebiyatı','Şiir','Fatih Alptekin']::text[], 8.5, '{"poet":"Fatih Alptekin","poet_slug":"fatih-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sarhosum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekten', 'gercekten-adil-koruyan-khbpm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Gerçekten beni seviyorsan'' la başlayan,

Ve ''mutlu olmamı istiyorsan'' la süren,

Bir not alırsan eğer, uzaklardan gelen;

O an, şüphe edildiğini anlarsın sevginden

Oysa, daha dün, sevgi doruklarında gezerken,

Ve sevginin gerçekliliğinden şüphe etmezken,

Nasıl olur da ''Gerçekten'' diye sorabilirsin?

Bir düşün, anımsayacaksın, geçmişte sana söylenenleri,

Sevgiden dostluğa giden yolu, yüceliğini sevginin.

Bir kez daha düşün, sana hiç yalan söylenip söylenmediğini.

O zaman anlayacaksın, ne olduğunu gerçek sevginin.

25.05.2001', '''Gerçekten beni seviyorsan'' la başlayan, Ve ''mutlu olmamı istiyorsan'' la süren, Bir not alırsan eğer, uzaklardan gelen; O an, şüphe edildiği...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gercekten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Deme', 'don-deme-fuat-colakoglu-e46rq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tanıdığım eski insan sen değilsin 

Gurbet elde görmeyeli çok değişmişsin 

Burda sen benim halimi nerden bilesin 

Dön deme dönmem artık bunu bilesin 

Acı tatlı günlerimiz geçti seninle 

Unuttum artık seni de sevgileride

Beni görüp utanma sakın günün birinde 

Dön deme dönmem artık sahte sevgilere', 'Tanıdığım eski insan sen değilsin  Gurbet elde görmeyeli çok değişmişsin  Burda sen benim halimi nerden bilesin  Dön deme dönmem artık bunu ...', ARRAY['Türk Edebiyatı','Şiir','Fuat Çolakoğlu']::text[], 8.5, '{"poet":"Fuat Çolakoğlu","poet_slug":"fuat-colakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/don-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-omer-hayyam-9j87u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir muhabbethanedir şol dergah hikmetini bil,

                     Bade ile mus eyke, dostun kıymetini bil,

                     Fazla işretten kaçın, ahengi bozma sakın,

                     Ehl-i-dil olmak gerek, cehlin zilletini bil! 

                     Caniden farkın olmaz, bozarsan meclis-i mey!

                     Paran ile övünme, burda herkes paşa bey,

                     Meclis-i muhabbette olmıya uzak yakın

                     Bu kubbenin işreti ibadetle aynı şey.

                     Caniden farkın olmaz, bozarsan mecls-i mey!                                                                            

                  

                     Şarap içti mi, dilenci sultanlaşır;

                     Tilki çıkar deliğinden, aslanlaşır;

                     Yaşlı başlı adam delikanlaşır;

                     Delikanlı yaşça basca olgunlaşır. 

                                                                                       

                     Günahlarım çok olmasına çoktur benim,

                     Ama dinsizler gibi umutsuz değilim:

                     Cennet cehennem umrumda değilse de

                     Ötede hem şarap olacak, hem de sevgili. 

                                                                                         

                     Derdin avucundan şarap içmedikçe

                     Bir yudum su içmiş değilim gönlümce;

                     Kimsenin tuzuna da ekmek banmadım

                     Ciğerimi kebap edip yemedikçe.. 

                                                                                           		

                     Hergün şarap çümbüşüne dalanların da

                     Her gece mihrap önünde kalanların da

                     Islanmayanı yok, yağmur altında hepsi:

                     Bir uyanık var, ötekiler hep uykuda. 

                                                                                        

                     Unutma, amansız feleğin çarkındasın;

                     Şarap iç, çünkü ateşten bir dünyadasın;

                     Madem ki yerin önünde sonunda toprak

                     Farzet ki üstünde değilsin altındasın.                                                                                            

                     Sevgiliyle sabah içmedeyiz, saki;

                     Biz Nasuh tövbesi bilmeyiz, saki;

                     Yeter okuduğun Nuh hikayesi

                     Hemen dolsun huzur kasemiz,saki. 

                                                                                              

                     Madem aman vermiyor ecel, saki,

                     Kadeh boş kalmasın, aman gel, saki;

                     Şu üç beş günlük dünyada gam yemek

                     Bizim gönlümüzce iş değil, saki.                                                                                        

                     Şarap sonsuz hayat kaynağıdır, iç;

                     Gençlik sevincinin pınarıdır, iç;

                     Gamı yakar eritir ateş gibi,

                     Sağlık sularında şifalıdır, iç. 

                                                                                             

                     Açılmışken nasılsa mutluluk gülün

                     Niçin elinde kadeh yok böyle bir gün?

                     Şarap iç, can düşmanındır geçen zaman:

                     bir daha bu fırsatı bulman ne mümkün? 

                                                                                              

                     Kim yüreğini uydurduysa aklına

                     Bir anını yitirmedi bu dünyada;

                     Ya Tanrı uğruna ekmek verdi candan

                     Ya rahatını aradı buldu şarapta.', 'Bir muhabbethanedir şol dergah hikmetini bil,                      Bade ile mus eyke, dostun kıymetini bil,                      Fazla işret...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/hosgeldin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-aziz-akgun-5hhyo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kolay değil ayrılık bu

kolay olsaydı adı ''ayrılık'' olur muydu?

gül kokulu yarim

''elveda'' en beteri sözlerin

daha da beteri

gördüm

giderken ıslaktı gözlerin', 'kolay değil ayrılık bu kolay olsaydı adı ''ayrılık'' olur muydu? gül kokulu yarim ''elveda'' en beteri sözlerin daha da beteri gördüm giderken ı...', ARRAY['Türk Edebiyatı','Şiir','Aziz Akgün']::text[], 8.5, '{"poet":"Aziz Akgün","poet_slug":"aziz-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/elveda-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Oyunu', 'gecenin-oyunu-hikmet-tugrul-tekeli-whnzm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamansız uyanırım rüyalarımdan

               En çok beraber olduğumuz zamanlardan

               Oysa seni nasıl görürüm 

               Sensiz nasıl yaşarım

               Çok görme bana bu zamanları

               Uyandırma beni

               Sadece benim olan zamanlardan

               Ben,seni sensiz yaşıyorum

               Bedenim burda ama ruhsuz yaşıyorum

               En mutlu zamanlarım bile kederli

               Ve ben senin için ağlıyorum

               Bir yüregim var ama sende

               Gözlerim hep yolda 

               Bir umut var işte şuramda

               Bu hıçkırıkları duymasanda...

               Gündüzüm ve gecelerim yok artık 

               Düşüncelerim karıştı birbirine 

               Bir ikilem var

               Birisi senle olmak 

               Ya da bu dünyada olmamak.', 'Zamansız uyanırım rüyalarımdan                En çok beraber olduğumuz zamanlardan                Oysa seni nasıl görürüm                 Se...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecenin-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakitler Susuyordu Sen Gibi', 'vakitler-susuyordu-sen-gibi-deger-ulas-turan-uusaw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu vakitleri takıp arkana, 

Ne de sessiz gelirdin... 

Çalındığında kapım, 

Ne komik olurdum her açışımda. 

Bir gün yine sensizliğini 

Vakitlere soruyordum. 

Ama vakitler susuyordu, sen gibi. 

Karanlık yüzünde saatler, 

Aydınlık gülüşünde sen. 

Yok artık, çalınan kapılarda gülüşlerin. 

Ve karanlıklarda kaldı kapılarım.

Ne de olsa vakitlerindedir dedim, 

Gelir yine sessizce, ben uyurken. 

Ama vakitler susuyordu, sen gibi. 

Şarkıları işgal ediyordu, 

Bu boşluklarında odamın. 

Dinlenilen yalnızlık ezgileriyle bir olduğumuz.. 

Boş durmayan odamda, 

Hep bir doluluk ve sen. 

Ama vakitler susuyordu, sen gibi... 

Bir bardak çay içtiğin oluyordu, 

Demliğimde bir sevinç. 

İçilmeyen vakitler hep sıkılıyordu. 

Onunda içi dolu, hiç bitmiyordu, 

Bu vakitlerde.

Ama vakitler susuyordu, sen gibi. 

Gelmenizi bekledim dün yine 

Odamda aynı ezgiler 

Bardağın ve susuşumla. 

Ve birden gelişini hissettim, o vakitlerin. 

Eksik olanı sendin, sen yoktun, 

Vakitlerden sonraya kalmazdın hiç. 

Ama vakitler susuyordu, sen gibi. 

Ve anladım ki vakitsiz kaldığını. 

Anladım artık, yeni bir arkadaşın vardı. 

Adını duymuştum, 

Sonsuzluk diyorlardı. 

Ben inanmadım, 

Gözyaşlarım inanmadı. 

Çığlıklarım dolduruyordu artık odamı. 

Ama vakitler susuyordu, sen gibi.', 'Bu vakitleri takıp arkana,  Ne de sessiz gelirdin...  Çalındığında kapım,  Ne komik olurdum her açışımda.  Bir gün yine sensizliğini  Vakitl...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/vakitler-susuyordu-sen-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vesselam', 'vesselam-ozan-arif-s5c37', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben böyle bilmezdim bu bizim yurdu

Bambaşka bir hali varmış vesselam!

Vay anam vay,nelerini doyurdu

Bol kaymağı balı varmış vesselam!

Başa geçen doğru dürüst olmadı

De ki bana şu geldi de çalmadı

Testisini doldurmayan kalmadı

Kurumayan gölü varmış vesselam!

Kimi geldi sunta ile götürdü

Kimi geldi çanta ile götürdü

Her biri bir avantayla götürdü

Gani para,pulu varmış vesselam!

Mayısına Eylülüne Mart''ına

Güvendik de dindi mi ki fırtına

İçten dıştan hep bindiler sırtına

Bükülmeyen beli  varmış vesselam!

Bırak dünü bugün bile seyret be

Yıkmak için ediyorlar gayret be

Daha hala gık demedi hayret be

Bıçak açmaz dili varmış vesselam!

Benim aklım benim fikrim yetmedi

Bu memleket nasıl hala batmadı

Gelen yedi,giden yedi bitmedi

Tükenmeyen malı varmış vesselam!

Ozan Arif  şunu söyle sen bir de

Hiç mi sahip çıkan yoktur bu yurda

Var var ama,o da işte içerde

Tek talihsiz kulu varmış vesselam.', 'Ben böyle bilmezdim bu bizim yurdu Bambaşka bir hali varmış vesselam! Vay anam vay,nelerini doyurdu Bol kaymağı balı varmış vesselam! Başa g...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vesselam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Görürsün', 'bak-gorursun-ozan-arif-fodjg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Böyle gitmez hep bu devran

Döner gardaş bak görürsün

Boş mangalda kül savuran

Siner gardaş bak görürsün.

Gürültüsü çoktur boşun

Eti yenmez her cins kuşun

Eylüldeki sular kışın

Donar gardaş bak görürsün.

Öz yerine geçmez kabuk

Ok olur mu eğri çubuk?

Yalancının mumu çabuk

Söner gardaş bak görürsün.

İster cık de,ister he de

Neler gördük bu dünyada

Ata binen merkebe de

Biner gardaş bak görürsün.

Pilavdan döner mi kaşık

Hep bu işler keşik keşik

Bize de o yeşil ışık,

Yanar gardaş bak görürsün.

Karga korkar havasından

Kartal geçmez davasından

Karga,kartal yuvasından

İner gardaş bak görürsün.

Hani nerde firavunlar

Nemrut varmış bir zamanlar

Arif der ki inananlar

Yener gardaş bak görürsün.', 'Böyle gitmez hep bu devran Döner gardaş bak görürsün Boş mangalda kül savuran Siner gardaş bak görürsün. Gürültüsü çoktur boşun Eti yenmez h...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bak-gorursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrışım', 'cagrisim-deger-ulas-turan-qvgbk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sarmalanmış bir papirüs yaprağında, 

Yazılarımın gülüşmeleri. 

Ey bu yaraların çaresinde arandığım 

Ve bu zamanların, kirletilmemiş hayaller. 

İnce, çok ince bir denizyıldızı gece. 

Niye hep beklentilerinde? 

Ne bu şiirler çıkar enginlerinden, 

Ne akşam vakitlerine kilitlenmiş, kırlangıç sürüleri. 

İşte akıyor yeniden, yengecin kıskacında hayat. 

Ne ne akrep durduruyor, ne 

Ne yelkovan sarıyor, 

Kırık dökük zaman sarkacını. 

Yeniden tik! ; ve yine tak!', 'Sarmalanmış bir papirüs yaprağında,  Yazılarımın gülüşmeleri.  Ey bu yaraların çaresinde arandığım  Ve bu zamanların, kirletilmemiş hayaller...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cagrisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Sancısı', 'sevda-sancisi-hikmet-tugrul-tekeli-8lfgv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yakındır dediler

             Yürek acısının ,sevda sancısının sonu

             Yakındır 

             Bitermiş dediler

             Anlayamadım

             Bu nasıl bitmekmiş,ben

             Dayanamadım

             Alışırsın dediler

             Nasıl alışırım sensizliğe

             O dayanılmaz sessizliğe 

             Nasıl yaşarım sensiz 

             Yakarım,yıkarım,kıyarım canımada

             Ben sensiz yaşayamam

             Hayır ben buna dayanamam

             Yetti artık canıma 

             Bir bilsen neler geldi başıma 

             Sen olmadan yaşanmazki bir başına 

             Bundan sonra vursamda o akılsız başıma 

             Geri gelmiyor, giden dönmüyor

             O kahrolası zaman sensiz geçmek bilmiyor

             Nasıl olacak bilmem ama 

             Hayalini silmek mümkün olmuyor.', 'Yakındır dediler              Yürek acısının ,sevda sancısının sonu              Yakındır               Bitermiş dediler              Anlaya...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevda-sancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyrederken', 'seyrederken-deger-ulas-turan-kcuf8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki hayali başıboş sevgilerinde, 

iki insanı sarmaş dolaş yüreklerinde 

Ve yaz getiren sevdalarıyla bir Haziran akşamında. 

Deniz yine tuzlu ve, 

Dalgalarında çırpınan martı sesleri 

Kıyılarda yosuna sarılmış bir sandal 

Öyle bir sandal işte.. 

Kıştan geçmiş de, bir bahar eskitmiş yüreğinde. 

Ne gelen yaza hazır, 

Ne geçmiş sonbaharı özlüyor.

Adımlarım uyku getiriyor 

Seyirlerim yalnızlık… 

Kumsalda yeni doğan bir gün 

Ve martıların sabah şarkıları…

İyi seyirler yalnız çocuk.', 'İki hayali başıboş sevgilerinde,  iki insanı sarmaş dolaş yüreklerinde  Ve yaz getiren sevdalarıyla bir Haziran akşamında.  Deniz yine tuzlu...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seyrederken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Es''lerimiz', 'es-lerimiz-deger-ulas-turan-f545r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi duyulur mu oralardan, 

Söylediğimiz şarkıların nakarat es''leri. 

Ve anlar mı her es geldiğinde, 

Bir aşkın es geçildiğini. 

Siz söylerdiniz küçük hanım, 

Suskunluğum aşkımdan.

Her susuş bir es değil, 

Ciğerlerimize yeniden çektiğimiz, 

Bir hayat belki, bir nefes. 

İşte şimdi her şeye yeniden bir es… 

Ellerinde kırık saplı bir karanfil. 

Ve karşıma hep ağlayarak yeniden 

Sevda sanarak gelişlerin yeniden. 

Acıtmışlar ey sevgili yüreğini, 

Seni kim saracak? 

Şimdi kim susacak? 

Her yakarışında bir sevdaya.. 

Kim gözlerin olacak ağlarken, 

Şimdi ne yapmalı, 

O durmadan sömürülen hayatçıklara. 

Haydi, sarıl şimdilik, 

Unutalım kendimizi.', 'Şimdi duyulur mu oralardan,  Söylediğimiz şarkıların nakarat es''leri.  Ve anlar mı her es geldiğinde,  Bir aşkın es geçildiğini.  Siz söyler...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/es-lerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şarkı Sana', 'bu-sarki-sana-yank-i-van-umt8n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerindir    ruhumun    nazenin     yaprakları

Ruhumun   lalesidir     gözlerinle  solmayan

Nazenin     gözlerinle  rüyamın     çiçeğisin

Yaprakları  solmayan  çiçeğisin   kalbimin

Sensin    hülyalarıma   demirleyen  şehrayin

Hülyalarıma   yağdırır   hicranı       kirpiklerin

Demirleyen  hicranı      anlamadı  gözlerin

Şehrayin      kirpiklerin,  gözlerin  ağlamadı

Riyakar     gülüşümle  gizledim    hüznümü

Gülüşümle  bilmedin   geceye      isyanımı

Gizledim     geceye     feryadımı    vermedim

Hüznümü,    isyanımı    vermedim  gündüzlere

Aşığınım,    bahçeme   gelmezmisin  sultanım

Bahçeme     ekiyorum     adına      güllerimi

Gelmezmisin adına     vurulmuştur   soldurtma

Sultanım     güllerimi    soldurtma     hasretinle

Gurbetin    çektirmedi    acısını     İstanbul

Çektirmedi   semtlerde   kaybetmek   yüreğini

Acısını      kaybetmek    saçlarıma   koymadı

İstanbul     yüreğini         koymadı    ellerime

Ümidimin    sudaki    ebrusudur  renklerin

Sudaki        hayaline   dalıyor      bakışlarım

Ebrusudur,   dalıyor     intizarın     hançeri

Renklerin    bakışlarım,  hançeri   gözyaşlarım

Lalezarın    nadide       çiçeğine    meftunum

Nadide      şarkıların    söylediği    mecnunum

Çiçeğine    söylediği    sevgilidir   muradım

Meftunum,  mecnunum,  muradım  yollarında', 'Ellerindir    ruhumun    nazenin     yaprakları Ruhumun   lalesidir     gözlerinle  solmayan Nazenin     gözlerinle  rüyamın     çiçeğisin Y...', ARRAY['Türk Edebiyatı','Şiir','Yank İvan']::text[], 8.5, '{"poet":"Yank İvan","poet_slug":"yank-i-van","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bu-sarki-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaksın', 'uzaksin-nurgun-salli-jd7wz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İmakansızı başarmak istercesine.

Ve birden yıldızlar kaybolur yağmurlar başlar...

Bir yağmur damlasını isterim öylesine,

Hiç kaybetmeden avucumun içinde tutmak.

Seni hissederim gecenin karanlığında

Sesini duyar, sana yaklaşmak istediğimde

Hayalini kurarım küçük bir tebessümle..

Ve seni yanımda hissettiğim an

Aslında ne kadar uzakta olduğun gelir aklıma.

Sonra hafiften akmaya başlar içime

Yağmur damlaları bir sel olur.

Cesaretimi toplayıp sana gelebilsem

Ve sesini duyduğumda

Sana olan hislerimi anlatabilsem

Dilimin ucuna kadar gelip

Fakat boğzıma düğümlenen,

Söylebilsem eğer o iki kelimeyi

Belki bir yanıt bulabilirdim sorularıma.

Karanlık çöker üstüme 

Gecenin verdiği bir hüzün olasa gerek

Bana olan uzaklığın

Yıldızları tutmak gibi seninle olmak.

Zaman ilerledikçe

Uykularımı kaçıran bu sessizlik

Bırakır kendini çaresizliğe

Ve akar yağmur damlaları...

Sevgi bu mu acaba

Sevgiliyi özlemek acı çekmek

Hayallere dalıp gerçekleri unutmak.

Akıp gecer saatler....

Yeni birgünü işaret eder takvim

Gün yavaş yavaş ağarır

Pencerenin aralığından

Ve işte yeni hayaller yeni umutlar

Bitmeyen Soru işaretleri

Sonunu göremediğim çözemediğim problemler

Bir damla içime akan,

Bir hayal içimi yakan,

Yağmur damlaları beni uyutmayan

Sevgi damlaları gibi...

Yıldızlar kadar uzaksın

Belkide bir çiçek kadar yakın

Ama önemli olan seni bulmak değil mi

Seni tutamıyorum

Çünkü içimde engeller var

Çünkü sen bana çok uzaksın çok.....

                                 28/03/2001', 'İmakansızı başarmak istercesine. Ve birden yıldızlar kaybolur yağmurlar başlar... Bir yağmur damlasını isterim öylesine, Hiç kaybetmeden avu...', ARRAY['Türk Edebiyatı','Şiir','Nurgün Şallı']::text[], 8.5, '{"poet":"Nurgün Şallı","poet_slug":"nurgun-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/uzaksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşa', 'yasa-sair-mahoni-xhhs9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşa,

Yaşadıkça sev,

Sevdikçe hayal kur,

Hayal kurdukça umut et,

Umutlar tükenmedikçe yaşam sona ermez...', 'Yaşa, Yaşadıkça sev, Sevdikçe hayal kur, Hayal kurdukça umut et, Umutlar tükenmedikçe yaşam sona ermez......', ARRAY['Türk Edebiyatı','Şiir','Şair Mahoni']::text[], 8.5, '{"poet":"Şair Mahoni","poet_slug":"sair-mahoni","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yasa-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıçak', 'bicak-haydar-ergulen-bk05q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kadın, gözlerinin eski gürültüsünü

göçebe, ırmağını gezdiriyor, suçortakları gibi,

gövde arayan bıçak, yarasıyla buluşuyor,

bağışlıyor yoksul sevişme taklitlerini

kalbimizin gam yükünden geçilmediği yalan,

yaralarımızı gösterecek kadar seviştiğimiz de.', 'kadın, gözlerinin eski gürültüsünü göçebe, ırmağını gezdiriyor, suçortakları gibi, gövde arayan bıçak, yarasıyla buluşuyor, bağışlıyor yoksu...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bicak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen mi O mu?', 'sen-mi-o-mu-cerkez-i-smail-10o6c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senden sonra binlercesini gördüm...

Ama senin gözlerin,

Senin dudakların,

Senin burnun,

Senin ayakların,

Senin saçın,

Senin ellerin,

Senin tenin,

Kısaca senin vücudun,

Senin herşeyin,

Sadece birisinde vardı,

Ben ikinize de aşığım;

Sana ve rüyalarıma giren hayaline...', 'Senden sonra binlercesini gördüm... Ama senin gözlerin, Senin dudakların, Senin burnun, Senin ayakların, Senin saçın, Senin ellerin, Senin t...', ARRAY['Türk Edebiyatı','Şiir','Çerkez İsmail']::text[], 8.5, '{"poet":"Çerkez İsmail","poet_slug":"cerkez-i-smail","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-mi-o-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarimden Ayrı Ölürsem', 'yarimden-ayri-olursem-i-lhami-karagul-4s0bx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarimden ayrı ölürsem mezartasıma, 

Ne gün gördü neden güldü yazsınlar.

Uğrayan olursa okur başımda, 

Bu dünya yı zindan bildi yazsınlar.

Ne yaptıysa olmadı, 

Sustu olmadı soyledi olmadı.

ZEYNEP adlı bir yar için, 

Sarardı soldu kurudu yazsınlar.

İşte bu garibin kendi dilinden tarifi

Esirgemeyin bir yasini serif-i

Sevdigi için 

Genç yaşta kara toprağa karıştı yazsınlar', 'Yarimden ayrı ölürsem mezartasıma,  Ne gün gördü neden güldü yazsınlar. Uğrayan olursa okur başımda,  Bu dünya yı zindan bildi yazsınlar. Ne...', ARRAY['Türk Edebiyatı','Şiir','İlhami Karagül']::text[], 8.5, '{"poet":"İlhami Karagül","poet_slug":"i-lhami-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yarimden-ayri-olursem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-menderes-atmaca-5tiin', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kardelen çiçeğini bilmezsin canım

Daha küçücüksün çünkü

Daha on sekizindesin

Sizin nesil bilmez o mağrur çiçeği

Karları arasından nasıl çıktığını

Nasıl itinayla yaşadığını

Bilmezsin ama sende bir Kardelensin

Kardelen kadar temiz

Kardelen kadar onurlu

Kardelen kadar güzelsin

Çoğu çiçek koparılır mutlaka

Ya koklanır atılır

Ya sevgiliye verilir

Bilmez koparan çiçeğin halinden

Yararlanır güzelliğinden

Atılan çiçek solar

Kaderine ağlar çiçek

Son anlarını pişman yaşar

Kader Kardeleni farklı kılar

Dağların yücesinde yaşar

Kaç kişi çıkabilir dağların tepesine

Kaç kişi göze alır karı, borayı

Ulaşamazlar ona koparamazlar

Koklayıp bir kenara atamazlar

Herkes göremez onu

Herkes bilemez kokusunu

Kokusu dostlarını sarar

Yan yana yaşarlar

Kimseyle paylaşamazlar onu

Karlar,dağlar, taşlar

Yücelerin çiçeğidir kardelen

Sen ise gönlümün çiçeği

Yalnız kalbim bilir değerini

Yalnız kalbim görür güzelliğini

Sen gönlümün çiçeği

Sen ömrümüm kardelen çiçeği', 'Kardelen çiçeğini bilmezsin canım Daha küçücüksün çünkü Daha on sekizindesin Sizin nesil bilmez o mağrur çiçeği Karları arasından nasıl çıkt...', ARRAY['Türk Edebiyatı','Şiir','Menderes Atmaca']::text[], 8.5, '{"poet":"Menderes Atmaca","poet_slug":"menderes-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kardelen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yansımalar', 'yansimalar-menderes-atmaca-smy44', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Resimlerde gördüm seni yıllar yılı

Kimileri renkli, kimileri siyah beyaz

İlkin bir Hint fakiri idin Hindistan sıcağında

Dalmış oturuyordun bir ağaç altında

Düşünceler birikmişti kirli saçlarına

Söylemek istediğin ama söyleyemediğin,

Öylece kabullendiğin bir söz duruyordu dudaklarında

Üstünde bilmem kaç yıllık bir giysi

Beyaz sakalların karış karış yayılmıştı suratına

Sonra bir Kızılderili kadını oluverdin başka bir fotoğrafta

Siyah,beyaz bir fotoğraf bu, yaşadığın yaşam gibi

Elinde uzun saplı bir balta,

Kan damlıyordu ucundan

Çevrende onlarca ölü

Belki de savaştaydın

Bir can pazarındaydın

Korku yoktu gözlerinde

Ölümüne kararlıydın

Sonuna kadar savaşacaktın

Boyun eğmeyecektin soluk benizlere

Toprağını koruyacaktın

İki Japon kadınından biri sendin yine

Renkli bir takvim yaprağındaydın

Saçların itinayla toplanmış

Üç çubuk toka ile bağlanmış

Yüzün beyazlar içinde

Dudakların kıpkırmızı

Tekrar dirilmişsin gibi bir yere bakıyordun, göremedim

Kederin yüzüne yansımıştı

Boşlukta sallanmak gibi

Bir başka fotoğrafta çıktın karşıma

Bir hayli değişiktin

Bir Latin ülkesinde dans ediyordun

Kendinden geçmiştin

Yarı çıplaktın

Üzerinde bir sütyen birde don

Eğlencelere dalmıştın

Etrafında onlarca dans eden

Hepsinin gözü üstünde

Şehvet akıyordu gözlerinden

Esmer değildin üstelik, şaşırttın

Sarıya boyanmıştı saçların', 'Resimlerde gördüm seni yıllar yılı Kimileri renkli, kimileri siyah beyaz İlkin bir Hint fakiri idin Hindistan sıcağında Dalmış oturuyordun b...', ARRAY['Türk Edebiyatı','Şiir','Menderes Atmaca']::text[], 8.5, '{"poet":"Menderes Atmaca","poet_slug":"menderes-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yansimalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Kalan', 'senden-kalan-menderes-atmaca-sic8n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu  yalnızlık  senin  eserin

Senin  eserin şu garip  duruşum

Dünyaya mat  bakışım  senden miras

Senin eserin böyle suspus  oluşum

Bilmem ki  kaçıncı günüm,kaçıncı gecem

Sensiz  geçen öcü  bir  zaman  içindeyim

Bilebildiğim karanlık  oluşum  bir  gece gibi

Bilmem  kaç bin defa arşınladığım yoldayım

Bir ben kaldım içinde  yürüyen

Bir  ben  yapayalnız,

Bir ben suskun.

Tarifsiz  kederliyim.

En  son kervan  yıllar önce geçti buralardan

Su içiyordum,son anda fark ettim

Arkasından  bağırdım  yetişemedim

İçinde  sen vardın

Beni  göremedin

Hüzünlüydü  gözlerin

Farkıma  varamadın

Yürüyerek  gelemem  sana

Çok  yoruldum  bir tanem

Seni  kaçırmanın verdiği azap  boğuyor  beni

Hüznüm  geceden  büyük

Her  yanım  kanıyor

Gözlerim  ufukta

Ne  gelen  var,ne giden

Tüm evler boş birer anıt

Sona kalmışım  ben

Bir  ışık  yolu  ötede  sen

Diz  çöktüm  yolun  ortasında

Elimde  bir  sigara

Uzat kollarını bulunduğun  yerden

Bitsin içimdeki  yaygara', 'Bu  yalnızlık  senin  eserin Senin  eserin şu garip  duruşum Dünyaya mat  bakışım  senden miras Senin eserin böyle suspus  oluşum Bilmem ki ...', ARRAY['Türk Edebiyatı','Şiir','Menderes Atmaca']::text[], 8.5, '{"poet":"Menderes Atmaca","poet_slug":"menderes-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/senden-kalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bİr Kesit', 'bi-r-kesit-menderes-atmaca-tq5cm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uğradı  dükkana

Çıktığında  bir  sigara  vardı elinde

Onaltısındaydı  daha

Uzun  saçları gözlerini kapıyordu

Yere bakıyordu yüzü

Sanki altmışlık bir nene

Yorgun yorgun yürüyordu

Bir duvarın  önünde durdu

Saklanmıştım,beni  görmüyordu

Açtı paketi  bir sigara aldı

Yan  cebinden bir çakmak çıkardı

Derin bir nefes çekti

Sanki kırk yıllık  tiryaki

Saatlerce kaldı duvar  önünde

Bakanlara aldırmadı

Önünde birkaç çakıl  taşı

Kendince bir  oyun  oynadı

Daldı birden

Habersiz  geçen  çocukluğunu hatırladı

Gözlerinden yaşlar  süzüldü

Hıçkıra hıçkıra  ağladı

Uyandı..kaldırdı başını

Üç beş  haylaz top  oynuyordu

Sildi  gözyaşlarını

Ayağa kalktı

Yürümeye  başladı

Pantolonları toz  içinde

Yürek  karalar  içinde', 'Uğradı  dükkana Çıktığında  bir  sigara  vardı elinde Onaltısındaydı  daha Uzun  saçları gözlerini kapıyordu Yere bakıyordu yüzü Sanki altmı...', ARRAY['Türk Edebiyatı','Şiir','Menderes Atmaca']::text[], 8.5, '{"poet":"Menderes Atmaca","poet_slug":"menderes-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-kesit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Üzerine', 'ayrilik-uzerine-menderes-atmaca-ji0kv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'El  vurduğun  eşyalara  dokunmadım önceleri

Hatırlamak  istemedim  seni

Ama  hiç  ağlamadım senden  sonra

Hiç kötü  hissetmedim  kendimi yokluğunda.

Yine  deniz kıyılarında  geçti günlerim

Yine güzel  kızlara takıldı gözlerim

Dönekliğine kafa yormadım

Yanlış  bir yoldaydım

Ayrılığa  sevindim.

Özgürüm  şimdi

Özgür  bir  şahin  gibi kalbim...

Hayalini bile  sildim

Çok  sevinçliyim

Teşekkür  ederim', 'El  vurduğun  eşyalara  dokunmadım önceleri Hatırlamak  istemedim  seni Ama  hiç  ağlamadım senden  sonra Hiç kötü  hissetmedim  kendimi yok...', ARRAY['Türk Edebiyatı','Şiir','Menderes Atmaca']::text[], 8.5, '{"poet":"Menderes Atmaca","poet_slug":"menderes-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrilik-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Apansız', 'apansiz-menderes-atmaca-866x3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şekerini kaptırmış çocuklar  gibiyiz

Koca bir çocuğa kaptırmışız üstelik

Şaşkınız...

Dalgın  bir  anımızda  çaldırmışız

Canımız  istiyor,canımız ağlıyor

Ama alamıyoruz bize ait  olanı

Yapabildiğimiz  kızmak sadece

Ağlamak  kanlı yaşlar eşliğinde

Ve yutkunmak,

Boğulacak  gibi  çaresizce', 'Şekerini kaptırmış çocuklar  gibiyiz Koca bir çocuğa kaptırmışız üstelik Şaşkınız... Dalgın  bir  anımızda  çaldırmışız Canımız  istiyor,can...', ARRAY['Türk Edebiyatı','Şiir','Menderes Atmaca']::text[], 8.5, '{"poet":"Menderes Atmaca","poet_slug":"menderes-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/apansiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yeminler Ettim', 'ne-yeminler-ettim-sair-bombaci-9i2me', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeminler ettim,

İnandığım tüm devrimci değerler üstüne.

Yeminler ettim,

Bir daha asla geri dönmemek üzere.

Ağladım,

Sabahlara kadar, bana bıraktığın bir resme bakarak.

Ağladım,

Beraber izlediğimiz son filmin mutlu aşıklarını düşünerek.

Kahroldum,

Sana, kızılı insanı yakan bir demet gül veremediğim için,

Kahroldum,

Sensiz geçen günlerde, sana koşmadığım için.

Umutlandım,

Gece camıma vuran ay ışığında yüzün belirdiğinde.

Umutlandım,

Sabah uyanır uyanmaz kendi ellerinle çizip bana verdiğin resmi gördüğümde.

Sevindim,

En azından hayalin ve benden hiç gitmeyecek sevgine sahip olduğum için.

Sevindim,

O erişilmez ve bir o kadar saf aşkı bana yaşattığın için.

Ne yeminler bozdum,

Güya bir daha gözlerine bakmayacaktım.

Ne yeminler bozdum,

Bende ki de saflık, durabilir miyim ki hiç seni düşünmeden?', 'Yeminler ettim, İnandığım tüm devrimci değerler üstüne. Yeminler ettim, Bir daha asla geri dönmemek üzere. Ağladım, Sabahlara kadar, bana bı...', ARRAY['Türk Edebiyatı','Şiir','Şair Bombacı']::text[], 8.5, '{"poet":"Şair Bombacı","poet_slug":"sair-bombaci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-yeminler-ettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmasaydı Güneş', 'dogmasaydi-gunes-sair-bombaci-e25ao', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyanırım yine her gün olduğu gibi

Umutsuz,sensiz bir sabaha

Yüzümü bile yıkamadan

Yüzün belirir zihnimde

O bakışların gelir aklıma

Zaptedemez kendimi ağlarım

Haykırırım keşke olmasaydı sabah

Keşke doğmasaydı güneş benim için diye

Susar yüreğim ve tekrar tekrar söyler bunları her sabah

Ama yine de her sabah sana ulaşabilmem için bir umut doğuyor

Gözlerin,ellerin ve sesin çağırıyor beni sana

Bilirsin karşı koyamam bunlara 

Sonu ölüm de olsa hayır diyemem sana

Eğer ki olmayacaksam yanında

Haykırırım keşke olmasaydı sabah

Keşke doğmasaydı güneş benim için diye', 'Uyanırım yine her gün olduğu gibi Umutsuz,sensiz bir sabaha Yüzümü bile yıkamadan Yüzün belirir zihnimde O bakışların gelir aklıma Zaptedeme...', ARRAY['Türk Edebiyatı','Şiir','Şair Bombacı']::text[], 8.5, '{"poet":"Şair Bombacı","poet_slug":"sair-bombaci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dogmasaydi-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D-III', 'd-iii-arif-nihat-asya-68eb0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yatırırken bu sedef kakmalı şimşir beşiğe 

Neyle kundakladılar Hazret-i Mevlânâ''yı?

Perdelerden taşırıp neyleri çığlık çığlık

Neyle kundakladılar Hazret-i Mevlânâ''yı.

Bir, ipekten ve köpükten yaratılmış yumuşak

Tüyle kundakladılar Hazret-i Mevlânâ''yı.

Kıyılardan, ovalardan dererek inciyle,

Çiyle kundakladılar Hazret-i Mevlânâ''yı.

Gece, mehtâbı elekten geçirip kirpikler

Ayla kundakladılar Hazret-i Mevlânâ''yı.

Mesnevî''sinde bir altın lüleden nûr akıtıp

Öyle kundakladılar Hazret-i Mevlânâ''yı.

''Bu yürek durmayacaktır'' dediler.. esmâdan

''Hay''la kundakladılar Hazret-i Mevlânâ''yı.

Sakalar doldurarak kırbaların Kevser''den

Meyle kundakladılar Hazret-i Mevlânâ''yı.

Ve açıp ağzını Nîsan Tası''nın Besmele''ler

Suyla kundakladılar Hazret-i Mevlânâ''yı.

Rûhlardan, kokulardan, durulardan duru bir

Şeyle kundakladılar Hazret-i Mevlânâ''yı.

Ulu Tûbâ''ların altında gönüller, eller

Böyle kundakladılar Hazret-i Mevlânâ''yı.', 'Yatırırken bu sedef kakmalı şimşir beşiğe  Neyle kundakladılar Hazret-i Mevlânâ''yı? Perdelerden taşırıp neyleri çığlık çığlık Neyle kundakla...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/d-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Bahar', 'gecen-bahar-mustafa-necati-karaer-6kst0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine getirdiğin yeşil bir sis

Bahar, of bahar.

Ellerim bilekten kesilmiş,

Ben sizi tutamam artık

Dallar, of dallar.

Upuzun telgraf direklerine

Kuşlar konar, kuşlar kalkar.

Bir daha gelmeyecek günlerin akşamında

Unuttuğum şarkılar sendedir

Rüzgâr, of rüzgâr.

Ne ebemkuşağının tutuncusu,

Ne akşam eve geç kalma korkusu;

Şimdi kulaklarımda o derenin yalnız sesi var,

Bir de karanlıklar boyunca saçların

Uzar, of uzar.

Mevsimler eskir, yollar kısalır,

Zamanla güzelleşir hâtıralar;

İlk sevgim, ilk şiirim, ilk kederim,

Ben eski gözlerimi isterim

Yıllar, of yıllar.

Her şey öylesine başkalaşmış

Masmavi olsa da gökyüzü,

Bu eller bile benim ellerim değil;

Bir daha sevmek ihtimali olmasa

Var, of var.', 'Yine getirdiğin yeşil bir sis Bahar, of bahar. Ellerim bilekten kesilmiş, Ben sizi tutamam artık Dallar, of dallar. Upuzun telgraf direkleri...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Necati Karaer']::text[], 8.5, '{"poet":"Mustafa Necati Karaer","poet_slug":"mustafa-necati-karaer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gecen-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulmün Türküsü...', 'zulmun-turkusu-sah-ali-yasar-3g1zj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boynumuzda sübyan kavgaların vebali

Koynumuzda üryan sevdaların cemali

Baba yadigarı çalar saat misali

Gün ışımaz yarınlara kurdular bizi

Gün ortasında alenen vurdular bizi!..

Köreldi sevgiler, öfkeyi bilediler

Ak alnımızı al kanlara belediler

İnce ince dokudular, sık elediler

Tel örgü kasnaklarda savurdular bizi

Gün ortasında alenen vurdular bizi!..

Telef oldu mağdur gözlerimizin rengi

Örselendi türkülerimizin ahengi

Derimize yapışan aç sülükler gibi

Kanlarımızı emdiler, sordular bizi

Gün ortasında alenen vurdular bizi!..

Yaktılar yüreğimizi kor eylediler

Yıktılar bileğimizi hor eylediler

İnsan gibi yaşamayı zor eylediler

Acıyla, gözyaşıyla yoğurdular bizi

Gün ortasında alenen vurdular bizi!..

Dost kervanımızı bastılar yaka paça

Zulmü yaşattılar ağzımızı açtıkça

Ansızın, topyekun saldırdılar alçakça

Deh ettiler süngü dipçik, yordular bizi

Gün ortasında alenen vurdular bizi!..

Ak güvercinler salsak sehpalardan hergün

Mahrum kalsak sevdalardan, dağılsak sürgün

Bilmezler mi ki sel olur çağlarız birgün

Garip akıllarınca susturdular bizi

Gün ortasında alenen vurdular bizi!..

(16/11/1996-Ümraniye)', 'Boynumuzda sübyan kavgaların vebali Koynumuzda üryan sevdaların cemali Baba yadigarı çalar saat misali Gün ışımaz yarınlara kurdular bizi Gü...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/zulmun-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzum', 'arzum-ferhat-i-ricam-lza2y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damarlarımda Arzuzun

Alev Alev Dolaşan 

Bel Bağladığım Umutsun

Düşlerimde Tutuşan

Herşeyimsin Yoluna Öldüğüm

Sevgilimsin

Düşlerimde Gördüğüm', 'Damarlarımda Arzuzun Alev Alev Dolaşan  Bel Bağladığım Umutsun Düşlerimde Tutuşan Herşeyimsin Yoluna Öldüğüm Sevgilimsin Düşlerimde Gördüğüm...', ARRAY['Türk Edebiyatı','Şiir','Ferhat İriçam']::text[], 8.5, '{"poet":"Ferhat İriçam","poet_slug":"ferhat-i-ricam","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/arzum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parça Tesirli Melodram', 'parca-tesirli-melodram-kucuk-i-skender-hurh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'senin yaşın aşka tutmuyor hiç gelme

bükülmüş dudaklarına bükülmüş sözler büyük kaçar

on santim daha uzasan başın göğe çarpacak

göğsün diyordum göğsünden sözediyordum / sen

sen ölmeden beş dakika önce düştün

mandallarından savrulup uçan beyaz bir gömlek gibi

havada uçarken ölüp savrulan beyaz bir kelebek gibi

hay aksi dengesini kaybeden bir cambaz gibi

virajı alamayıp şarampole yurvarlanan arabalar gibi

aklıma ilk gelecek bir şey gibi

düştün

düşüşün bir rüyaydı

düşüşün yarım kalacak bir rüyaydı gecelerden bir gece

gecelerden bir gece aşkın üstüne yürüdün

delikanlı bir yanın vardır karanlıkta

şöyle sert, şöyle naif, şöyle öfkeli!

senin yaşın aşka tutmuyorum çocuğum, hiç gelme

açıkta kalırsın

aşk insanı acıktırır

aşk insanı bir ölüme susatırsa aşk diye anılır

senin mahallende aşk masallara giremez

masala giren aşk çıkamaz o mahallelerde!

masalların aşkına, benim aşkıma, Allah aşkına

senin yaşın aşka tutmuyor sevgilim, lütfen gelme

bana ayak bastığın gün

aşk herhangi bir gün olarak katılır haftaya

salı ile çarşamba arasında bir yere

aşk, her koşulda eğlenceli; aşk, istedi mi sereserpe!

yüzünde derin mi derin, kuşkulu, canavar bir gülümse

yırtarsın, kapatırsın, vurur deviremezsin

sevgilim

sen bu aşkta dolap çeviremezsin!

açıkta kalırsın

aşk insanı acıktırır

aşk insanı bir ölüme susatıyorsa aşk diye anılır!

yüzünde derin mi derin, kopkoyu, yapış yapış bir gülümseme

senin yaşın aşka tutmuyor sevgilim

lütfen gelme!', 'senin yaşın aşka tutmuyor hiç gelme bükülmüş dudaklarına bükülmüş sözler büyük kaçar on santim daha uzasan başın göğe çarpacak göğsün diyord...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/parca-tesirli-melodram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Tanem!!!', 'ben-tanem-turgut-erdogan-n85sm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzyıllar mı oldu sana iki kelam yazmayalı yoksa asırlar mı oldu bilemiyorum. Burada zaman kavramını yitirdim artık. Ne günler umurumda nede aylar ve yıllar. Kendimi bırakmışım zaman mevhumunun kollarına. Nereye götürürse gidiyor, ne işkence münasip görürse çekiyorum artık. Çünkü hiçbir şey koymuyor sensizlik kadar.

Dedim ya zaman kavramını yitirdim. Ne kadar süre geçti bilmiyorum beni buraya kapattıklarından beri. Küçücük bir oda dört metreye üç metre güya. Oysa dışarıdaki koca dünyanın yanında buğday tanesi kadar kalıyor. Burası küf kokuyor, burası nem kokuyor, burası sensizlik kokuyor ben’tanem. 

Hücrede benden başka 2 kişi daha var.Biri Necmettin dede. Bir kaza eseri oğlunu vurmuş kırk yedi yaşında. Otuz yıl vermişler on iki yıl evvel. Daha geride koskoca on sekiz senesi var. Diğeri ise Emin isminde 19 yaşında bir genç. Kan davası yüzünden üç kişiyi öldürmüş. Önce idam vermiş hakim sonra müebbet olmuş cezası. Ben mi? Benim dört duvar arasında olmama gerek yok aslında. Ben her yanı açık, püfür püfür boğaz esintisi olan bir kırda olsam da yine mahkumum. Ben yüreğimden kelepçeliyim sana ve aşkıma. Suçumsa çok büyük aslında seni sevmek, sana bağlanmak, sana tapmak, sana KADINIM demek, senin ADAMIN olmak.

	Hücrenin küçük bir penceresi var dört parmaklıklı. Son zamanlarda nemden ve rüzgardan pas tutmaya başladı sensiz her günde törpülenen ömrüme inat. Hücre penceresine bir serçe dadandı ben’tanem. Ve ben onunla dertleşiyorum, seni soruyorum ona, şimdi nerede neler yapıyor, beni düşünüyor mu beni soruyor mu sana diyorum. Kimse anlamıyor benden başka onun dilini. Bana her gün senden haberler getiriyor. Bense sadece yemeklerden arttırdığım birkaç parça ekmek kırıntısı. Görüyorsun değil mi adaletsizliğini dünyanın. Birkaç ekmek kırıntısına karşılık dünyaya bedel birkaç havadis. Ama sanırım yanılıyorum o birkaç ekmek kırıntısı da onun için çok önemli sanırım.

	Sıkıyor burası beni, boğuluyorum. Her ne kadar bir süredir sıkıntımı hafifletmek için sana şiirler, mektuplar yazıp bildiğim en son adresine göndersem de ne kadarının eline ulaştığı bilemiyorum.

	Belki senden uzaklaştığımı, belki de senden sıkılıp seni terk ettiğimi sanıyorsun. Oysa bilmiyorsun ki! Beni aldıklarında güzel saatlerin verdiği rehavetle düş bahçelerinde çiçekler deriyordun sen. Ben ise gözlerim açık, sigaramın dumanında seninle ilgili gelecek düşleri kurarken apansız yakalandım kaçınılmaz gerçeğe. Oysa bilmeliydim beni sana, seni bana yar etmeyeceklerini, oysa bilmeliydim seni benden uzaklara fırlatıp, beni senden habersiz dört duvara atacaklarını.

	Şimdi insanlık kim bilir kaçıncı baharda ve biz kaçıncı hazandayız bilmiyorum. Birlikte sarmaş dolaş olduğumuz tepelerde papatyalar yine açıyor mu her bahar? El ele gezdiğimiz o parkta ağaçlar yine yapraklarını savuruyor mu kış rüzgarlarında?

	Bu beton yığını arasında senden uzak kalıyor olmak, elini tutamamak, sesini duyamamak, gözlerimi kapatıp saçlarının nilüfer kokusunu ciğerlerime çekememek, bal dudaklarından öpememek ve uzun gecelerimde seninle bakkal rafında yıllanmış bir köpek öldüren şarabı bile içememek yüreğime saplanmış paslı bir hançer gibi.

	Ama tüm uzaklığına, tüm yokluğuna rağmen yüzünün her ayrıntısını hatırlıyorum. Geceleri küçük penceremden gözlerine bakar gibi bakıyorum parlayan yıldızlara. Arada bir mazgalın aralığından esen meltem saçlarının nilüfer kokusunu getiriyor bana.

	Bir gün bu esaretten kurtulacağım biliyorum, sayılı gün çabuk geçer derler. Bir gün ben de eşyalarımı toplamaya başlayacağım gelen bir haberle. Sensiz kurduğum senli anılarımı ve sana yazdığım mektuplarımı tahta bir bavula koyup ardına kadar açılan ağır demir kapıdan dışarıya adım atacağım. Özgürlüğü koklayacağım ve sana koşacağım. Biliyorum sen beni bekliyor olacaksın ve zamanın tüm acımasızlığına rağmen her zamanki melek güzelliğini koruyacaksın. Merak etme seni çekip alacağım “sensizlik” dediğin esaretinden.

	El ele tutuşup gideceğiz bu kötü anılar yaşadığımız diyarlardan. Belki bir dağ köyü olacak gittiğimiz yer, ırgatlık yapacağız. Belki küçük ama şirin bir balıkçı kasabasında ekmek kavgası yapacağız. Benim mahpusluğumun, senin bensizliğinin acısını çıkartmak istercesine bir günü bin yıl niyetine yaşarız.

	İşte ben gücümü bu küçük mutluluklardan, umutlardan alıyorum. Hep seninleyim, hep seni yaşıyorum. Yaşadığımız mahpusluğa rağmen seni seviyorum Ben’tanem...

Alanya, Nisan-2001', 'Yüzyıllar mı oldu sana iki kelam yazmayalı yoksa asırlar mı oldu bilemiyorum. Burada zaman kavramını yitirdim artık. Ne günler umurumda nede...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-tanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tezat', 'tezat-turgut-erdogan-etje8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gitmeyi seviyordun,

Ben ''gitme'' diye yalvarmayı.

Senin kalmanı istediğim kadar,

Sen, sevmiyordun ki kalmayı

Alanya, 19 Mayıs 2001', 'Sen gitmeyi seviyordun, Ben ''gitme'' diye yalvarmayı. Senin kalmanı istediğim kadar, Sen, sevmiyordun ki kalmayı Alanya, 19 Mayıs 2001...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tezat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Adı Yok...', 'sevginin-adi-yok-sah-ali-yasar-f6mnr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyor musun anne şimdi ne haldeyim?

Mekân sessiz, zaman sessiz, ben sessiz

Bir yaprak bile kımıldamıyor yüreğimde...

Yer yerinden oynamış gibi

Tepe taklak dünya sanki

Şeklini şemalini yitirmiş her madde...

Kaç zamandır arkamdan kapılar sürgülü

Perdeler örtülü, duvarlar örülü

Yaşamak marifet istiyor anne

Ölüm kol geziyor üzerimde!..

Kurtulmak istiyorum bu kıskaçtan

Varmak sonra düşlerimde birikmiş özlemlere

Ağız tadıyla yaşamak istiyorum

Yeter artık Anne, yeter!

Yüzbin kere yeter!

Dışarıda hayat

Dışarıda hareket var, biliyorum!..

Geceden bu yana yağan

Karlar büyülüyor gözlerimi

Kendimi kaybediyorum beyazda

Tutsaklığımı unutuyorum bir an

Pencereme çarpan karın

Bir lapa sesi yankılanıyor kulaklarımda

Bana fısıldıyor sanki

Beni çağırıyor yanına

“Gel” diyor, “çık dışarı gel!”

Hırçınlaşıyorum doludizgin

Gitmek istiyor canım

Koşup yanlarına varmak istiyor

Yolak yok!..

Ellerim sarılıyor buğulu pencereye

Bir kâğıt parçası gibi yırtmak

Parçalamak istiyor camları

İmkân yok!..

Çaresizlik balyoz oluyor

İniyor üzerime!..

Oysa çıkıp dışarı

Bütün yağan karları

Avuçlayıp tutmak istiyorum

Gözlerime yağsın

Kirpiklerime yağsın

Bahtıma yağsın Anne

Yerler soğuk, karlar üşümesin

Sokaklarda kartopu oynayan çocuklar da

Ne olur kızmasınlar bana

Onları da el üstünde tutacağım, söz!..

Zemin kaygan, çocuklar düşmesin!..

Gör şimdi neredesin?

Ne yapar, ne edersin?

Haberim yok!..

Ben ise malumun

Dört duvarın arasındayım

Kaderimle baş başayım

Sevginin adı yok!..

Yapıştı boğazıma kahrolası yalnızlık

Ha bire sıkıyor Anne, sıkıyor!

Beni boğmak istiyor

Çaresi yok!

Ne yapsam kâr etmiyor!..

Kaç gece uykumu böldü iğreti kâbuslar

Tüm korkaklığımla bağırdım da

Kimseler duymadı

Duyanlar da oralı olmadı

Oysa sen duysan sesimi

Yalınayak koşup gelirsin

Biliyorum benim için

Düşünmeden ölürsün

Ancak neylersin ki

Sesim gitmez ta oralara

Buralar illet, buralar şirret

Buralar çok, çok uzak senden

Buralar apayrı bir yermiş işte!..

Düşünüyorum da

O çok sevdiğin oğlunu şimdi görsen tanır mısın?

Ayırt edebilir misin diğer çocukların arasında?

Bulup boynuna sarılır mısın?

O özünle büyüttüğün çiçeğin

Şimdi soldu, kurudu Anne

O avucunla tutup okşadığın çehrem

Şimdi darmadağın

Başım oyuk, kerme kerme kan

Saçlarım düğüm düğüm

Gözlerimin altında derin mor halkalar

Dişlerimin hepsi bir dağda

Tıraşım uzadı epeydir

Rengi de çekildi yüzümün

Bitkinim Anne, yorgunum

Kırk yılın yükü var sanki sırtımda!..

Hepsinden kötüsü, hepsinden beteri

Ağzımı açacak gücüm yok, konuşamıyorum

Ne kötü şeymiş konuşamamak!

Mesela “Anne” diyememek

“Ekmek” diyememek

Sessizlik ne kötüymüş

Oysa emeklerken sökmüştüm konuşmayı

Dilimin ilk döndüğü sendin

Görüyorsun ya şimdi onu da beceremiyorum

İsmini uzaklara çağıramıyorum

Her seslenişte sana ulaşamıyorum!..

Bağışla beni güzel Annem

Senden bir şey kapamadım

Sana yakışanı yapamadım

Erken teslim oldum

Tez kabullendim her şeyi

Sana mahcubum!..

(1991-Buca/İzmir)', 'Biliyor musun anne şimdi ne haldeyim? Mekân sessiz, zaman sessiz, ben sessiz Bir yaprak bile kımıldamıyor yüreğimde... Yer yerinden oynamış ...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":106,"source_url":"https://www.antoloji.com/sevginin-adi-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin', 'yemin-mustafa-gokgoz-t8xg2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne işi var ki gönlümün 

Senin olmadığın yerde

Yazık ki gitti ömrümün,

Yarısı verdiğin derde

Ömür boyu peşindeyim 

Gittiğin yol yolum olsun   

Seni terk edersem eğer 

Darağacı sonum olsun

Sensin benim tek hasretim

Hayalin gözümde perde

Yaratandan  tek dileğim,

Sensin benim seherlerde

Bu aşkın çilesi benim

Mutluluğu senin olsun

Ölürüm gidersen eğer

Allah’ıma yemin olsun', 'Ne işi var ki gönlümün  Senin olmadığın yerde Yazık ki gitti ömrümün, Yarısı verdiğin derde Ömür boyu peşindeyim  Gittiğin yol yolum olsun  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökgöz']::text[], 8.5, '{"poet":"Mustafa Gökgöz","poet_slug":"mustafa-gokgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yemin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığımın Adısın...', 'yalnizligimin-adisin-sah-ali-yasar-ca86l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mektuplarım, umutlarım, aşklarım

Yalnızlığın deminde yaşarken bir güruh paylaşım...

Kurşunların altında yıldızlara gülümseyebilmek

Ay ışığında görebilmek seni

Yakamozlar içinde gözlerini seçebilmek

Yüreğim kibrit alevi karanlığın

Parmaslayarak tutabilmek elini

Kanıksayarak sevebilmek!..', 'Mektuplarım, umutlarım, aşklarım Yalnızlığın deminde yaşarken bir güruh paylaşım... Kurşunların altında yıldızlara gülümseyebilmek Ay ışığın...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizligimin-adisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş...', 'serzenis-sah-ali-yasar-7vdqy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaralı dağ ceylanı ürkekliğinde ellerin

