INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım Ben', 'aglarim-ben-ahmet-unal-cam-3qlhg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Garib bir kasvet basar da

   Beni benden alır ya

   Kalırım tek başıma

   Ağlarım ben bahtıma', 'Garib bir kasvet basar da    Beni benden alır ya    Kalırım tek başıma    Ağlarım ben bahtıma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aglarim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-ahmet-unal-cam-2ip49', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağları yıkacak gücüm vardı

...elim kolum kalkmıyor.

Haykırınca titretecek sesim vardı

...sesimi kulaklarım duymuyor.

Kahkahamdan durulmazdı

...gözyaşlarım durmuyor.

Yıktı beni hasretin

...bil bende öldüm; 

  kapanırken gözlerin.

''Aşk'' derdine düştüm, beteri varmış

Seni sevmekten beteri, sensiz kalmakmış', 'Dağları yıkacak gücüm vardı ...elim kolum kalkmıyor. Haykırınca titretecek sesim vardı ...sesimi kulaklarım duymuyor. Kahkahamdan durulmazdı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık', 'asik-ahmet-unal-cam-xjn6f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiçek suladım, yağmurlu havada,

Çaya tuz ektim, aşa şeker koydum,

Palto giydim, güneş beni yakarken.

Hay Allah! . ben yine mi aşık oldum?', 'Çiçek suladım, yağmurlu havada, Çaya tuz ektim, aşa şeker koydum, Palto giydim, güneş beni yakarken. Hay Allah! . ben yine mi aşık oldum?...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İçin Dua', 'ask-i-cin-dua-ahmet-unal-cam-tkb7d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Allahım! ..sen bilirsin

Bana ya sabır ver,

        ya da onu.

Olmuyor ki başka türlü

    bu aşkı

.

.

.

"Yıllar sonra not:

Allah sabır verdi."', 'Allahım! ..sen bilirsin Bana ya sabır ver,         ya da onu. Olmuyor ki başka türlü     bu aşkı . . . "Yıllar sonra not: Allah sabır verdi....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-icin-dua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Özdedir', 'ask-ozdedir-selim-tuncbilek-g75d9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün bir ucuna konsa 

Sen Bir ucuna dünyanın 

İçinde çığlığı duyar gibiyim,

Aşk evreni sarmış...

İki Uçtadır.

Uç ki,

Ak bir kavak yaprağı,

olur bedeninde 

Titrer konar dalına gözlerin

Rengini bulduğu demdir,

Ol vakit sevda,

İki Gözdedir...

Özdedir,

Şimdi, kavuran ateş dağları

Delen Ferhat özdedir.

Görse Şirin bir yürek

Bin yürek dağlar,

Uçar, her dem,

Merhem...

Bir çift sözdedir.', 'Gün bir ucuna konsa  Sen Bir ucuna dünyanın  İçinde çığlığı duyar gibiyim, Aşk evreni sarmış... İki Uçtadır. Uç ki, Ak bir kavak yaprağı, ol...', ARRAY['Türk Edebiyatı','Şiir','Selim Tunçbilek']::text[], 8.5, '{"poet":"Selim Tunçbilek","poet_slug":"selim-tuncbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-ozdedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Attın Başımı Sevdalara', 'attin-basimi-sevdalara-ahmet-unal-cam-snriu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bahar günü

  attın başımı sevdalara

  çekip gittin

  erişilmez yollara

Koştum peşinden,

Çıkmaz sokaklar

  kesti yolumu.

Döneyim dedim

  aşılmaz duvar ördü yüreğim.

Çaresizliğin sınırlarındayım

  hayalin yol gösteriyor

  yolların sonu uçurum

Tam ''kurtuldum'' derken

  tekrar tekrar düşüyorum

...sevdana', 'Bir bahar günü   attın başımı sevdalara   çekip gittin   erişilmez yollara Koştum peşinden, Çıkmaz sokaklar   kesti yolumu. Döneyim dedim   ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/attin-basimi-sevdalara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışlarda Veda', 'bakislarda-veda-ahmet-unal-cam-07wk3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülümseyişin müjdesi sandım baharın

Umutlandım, mutluluğa hazırlandım.

Sözlerin oldu başlangıcı

Gönlümdeki depremin, fırtınanın.

Yepyeni binalar yıkıldı

Tüm güzelliklerin yerinde enkaz.

Bahar geliyor, derken yine kış

Bahardan geçtim gelmiyor yaz,

Ve, gözlerinde hayırsız bakış.', 'Gülümseyişin müjdesi sandım baharın Umutlandım, mutluluğa hazırlandım. Sözlerin oldu başlangıcı Gönlümdeki depremin, fırtınanın. Yepyeni bin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bakislarda-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bencil', 'bencil-ahmet-unal-cam-v8ax1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey Afrikalılar !..

Ey aç insanlar !..

   yoksul insanlar !..

Alın şu şiiri,

   yarım ekmeğimi de.

Ben ekmeksiz umut yiyorum.

Size yarım ekmek arası şiir kaldı.

Umutsuz olduğu için kusura bakmayın

   affedin bencilliğimi,

Umutların hepsi bende kaldı.', 'Ey Afrikalılar !.. Ey aç insanlar !..    yoksul insanlar !.. Alın şu şiiri,    yarım ekmeğimi de. Ben ekmeksiz umut yiyorum. Size yarım ekme...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bencil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Eski Ben Değilim', 'ben-eski-ben-degilim-ahmet-unal-cam-zumz6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben, buz misali sevdalarda, kayan oldum,

Herkese yabancı, kendime ayan oldum.

Gülüşlerim yüzümü terketti, hoş görün,

Biten bir dert üstüne, bin dert sayan oldum.

Zor gelirdi gurbet, gurbette kalan oldum,

Bağ idim, bahçeydim, şimdi ben talan oldum.

Eski ben değilim, düştüm aşk deryasına,

Yalan bilmez iken, şimdi ben yalan oldum.', 'Ben, buz misali sevdalarda, kayan oldum, Herkese yabancı, kendime ayan oldum. Gülüşlerim yüzümü terketti, hoş görün, Biten bir dert üstüne, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-eski-ben-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Yerime', 'benim-yerime-ahmet-unal-cam-4fvhx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dostlarım !..

  Benim yerime bakın ağaçlara

  Benim yerime göz kırpın yıldızlara

    her gece

  Benim yerime şarkı söyleyin

    karanlıklara.

  Ve sonra

  Benim yerime ''-Merhaba''deyin

    sabaha.

  Gücüm tükendi benim,

    bir gönülde hapisim,

    hasretim ışıklara...', 'Dostlarım !..   Benim yerime bakın ağaçlara   Benim yerime göz kırpın yıldızlara     her gece   Benim yerime şarkı söyleyin     karanlıklara...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-yerime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misin ?', 'bilir-misin-ahmet-unal-cam-ek9m8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilir misin ki ?

Sana şu satırları

Herkes uyurken yazıyorum.

Bölmüşsün uykumu yine ;

Seni düşünüyorum ,

Ne kadar istemesem de !..

Bilir misin ki ?

Ümitlerim sen olmuş ;

Geçmişsin karşıma,

Olmayacak dua gibi

Gülüyorsun...

Bakıp gözlerime.

Ve,

Bilir misin ki ne kadar acı;

Bunun hiç olmayacağını bilmek,

Hayalinle bile gülememek.', 'Bilir misin ki ? Sana şu satırları Herkes uyurken yazıyorum. Bölmüşsün uykumu yine ; Seni düşünüyorum , Ne kadar istemesem de !.. Bilir misi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilir-misin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil ki !', 'bil-ki-ahmet-unal-cam-pi7fj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biter sandığım nice şey

  devam ediyor sensiz de

Yalnız nefes alışım değil

  gülümseyişlerim de.', 'Biter sandığım nice şey   devam ediyor sensiz de Yalnız nefes alışım değil   gülümseyişlerim de....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bil-ki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akşamdı', 'bir-aksamdi-ahmet-unal-cam-kteyp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeni umutlar büyüttüm içimde,kış günü

Umutlar ki; taşıdı yüzüme gülücüğü.

Güzeldi sevdiğim, nazlıydı sevdiceğim,

Kasvetli bir akşamdı, Ah.. duydum öldüğünü.', 'Yeni umutlar büyüttüm içimde,kış günü Umutlar ki; taşıdı yüzüme gülücüğü. Güzeldi sevdiğim, nazlıydı sevdiceğim, Kasvetli bir akşamdı, Ah.. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-aksamdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Barış Yılı - Bir Kış Günü', 'bir-baris-yili-bir-kis-gunu-ahmet-unal-cam-16yq1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Türkiyem ve terör)

Yüreklerde sevgi eksikti

Bir serseri kurşun daha sekti,

Bir çocuk daha öldü.

Kar üstüne kan düştü,

...sonra da çocuk.

Ümit tükenmiş, gözler kaygılı

Kimsenin haberi yok ama

  bir barış yılı.

Duvarlarda yazılar, pankartlar

...kimi bombalı

Ne yapmalı...ne yapmalı?

Kar üstüne kan düştü,

...sonra da çocuk.

Herhangi bir kış günüydü,

Bir çocuk daha öldü.

Hava soğuk, hava soğuk !..

Tüm yürekler üşüdü...', '(Türkiyem ve terör) Yüreklerde sevgi eksikti Bir serseri kurşun daha sekti, Bir çocuk daha öldü. Kar üstüne kan düştü, ...sonra da çocuk. Üm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-baris-yili-bir-kis-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Demet Hüzün', 'bir-demet-huzun-ahmet-unal-cam-cabv4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak;

Bulutlar geziyor gökte,

Rüzğarlar esiyor.

Ben acı çeksem de

Hayat devam ediyor.

Sonu olmayacak gidişin

Sevinçlerimin, gülüşlerimin.

Biliyorum, yansa da kalbim şimdi

Unutacağım,d aha öncekiler gibi.

Her alev söner, köz de kalmaz,

Unutanlar elbet unutulur,aranmaz.

Dönersen, arama maziyi,

Bil kî; nehirler yukarı akmaz.', 'Bak; Bulutlar geziyor gökte, Rüzğarlar esiyor. Ben acı çeksem de Hayat devam ediyor. Sonu olmayacak gidişin Sevinçlerimin, gülüşlerimin. Bil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-demet-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paris Üzerine Bilmeceler', 'paris-uzerine-bilmeceler-nazim-hikmet-ran-y9bwj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hangi şehir şaraba benzer? 

Paris.

lk bardağı içersin

buruktur, 

ikincide dumanı vurur başına, 

üçüncüde mümkünü yok masadan kalkmanın

Garson bir şişe daha getir! 

Ve artik  nerde olsan, nereye gitsen

Parisin ayyaşısın iki gözüm

Hangi şehir

kırk yagmurlarda  bile güzeldir? 

Paris...

Hikmetin oglu hangi şe
..........
..........', 'Hangi şehir şaraba benzer?  Paris. lk bardağı içersin buruktur,  ikincide dumanı vurur başına,  üçüncüde mümkünü yok masadan kalkmanın Garso...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/paris-uzerine-bilmeceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düş Gördüm', 'bir-dus-gordum-ahmet-unal-cam-n8fnu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vücud gönle dar idi

Etrafım gülzâr idi

Mutlu idim, baktım

Yanımdaki yâr idi', 'Vücud gönle dar idi Etrafım gülzâr idi Mutlu idim, baktım Yanımdaki yâr idi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-dus-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hüzün İkliminde', 'bir-huzun-i-kliminde-ahmet-unal-cam-uta66', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir hüzün ikliminde   

Çiçek açmış yüreğim.  

Korkularım dağ gibi  

Bırakmıyor güleyim.', 'Bir hüzün ikliminde    Çiçek açmış yüreğim.   Korkularım dağ gibi   Bırakmıyor güleyim....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-huzun-ikliminde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah Uyanamadım ki', 'bir-sabah-uyanamadim-ki-ahmet-unal-cam-dw3c0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sabah uyanamadım kî; ölmüşüm.

Yüzüme gülen

  arkamdan daha çok gülen

Sahte yüzler

  sahte hüzünler takmış.

Bir sabah uyanamadım kî;

  herşey bitmiş.

Para-pul gözümde değil.

Sonra,sanki biri seslendi

''-Zengin olmak ister misin?''

Eski hırsla şöyle bir kıpırdadım

Baktım kî kefene ;

''-Yan cebime koy'' bile diyemedim.', 'Bir sabah uyanamadım kî; ölmüşüm. Yüzüme gülen   arkamdan daha çok gülen Sahte yüzler   sahte hüzünler takmış. Bir sabah uyanamadım kî;   he...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-sabah-uyanamadim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şair Bin Hayat Yaşar', 'bir-sair-bin-hayat-yasar-ahmet-unal-cam-r0jz3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vatanı kurtardım bir gün,

 Bir gün uçtum kaf dağına.

 Herkese sarıldım bir gün

 Bir gün kaçtım yalnızlığa.

 Güneşe uzandım bir gün

 Bir gün düştüm karanlığa.

    Yaşamadıklarım da

    Şiir olur bende.

 Ağladım,

       gözyaşımı yazdım.

 Düşündüm,

       hüzünleri yazdım.

 Dört yanıma baktım

       dertleri yazdım.

    Kaçamadıklarım da

    Şiir olur bende.

 Kaç kez olmuştur

       güneşli havada ıslanmışım.

 Kaç kez olmuştur

       kıpırdamadan koşmuşum

 Kaç kez,kaç kez

       sevdiğimle elele gezmişim

    Yapamadıklarım da

    Şiir olur bende', 'Vatanı kurtardım bir gün,  Bir gün uçtum kaf dağına.  Herkese sarıldım bir gün  Bir gün kaçtım yalnızlığa.  Güneşe uzandım bir gün  Bir gün ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-sair-bin-hayat-yasar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yaz', 'bir-siir-yaz-ahmet-unal-cam-2dpr1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni düşün ve

Bir şiir yaz bu gece.

Umut olsun içinde

  geleceğe dair.

Kavuşmak olsun,

Ve...

Mutlu gülüşler olsun

  dizelerinde

Sonra bu gülüşleri

Takın yüzüne

Beni gördükçe

Gözyaşlarını sakla

Hüzünlerini göm,

  sonsuz çukurlara.

Kalbinde yer aç

Yeni mutluluklara.

Bana güven,

Beni düşün,

Bitsin hüzün,

Gülsün yüzün.', 'Beni düşün ve Bir şiir yaz bu gece. Umut olsun içinde   geleceğe dair. Kavuşmak olsun, Ve... Mutlu gülüşler olsun   dizelerinde Sonra bu gül...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-siir-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaprakta Seyahat', 'bir-yaprakta-seyahat-ahmet-unal-cam-id4k1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece yarısı, tam onikide

Evimin balkonunda

  gönlümün yalnızlığındayım.

Gecenin anlaşılmaz uğultusu

  ve rüzğarın fısıltısı

  kulaklarımda.

Gözlerim ufukları kolaçan ediyor.

Yüreğimin tik-takları

  saatleri geçiyor.

Gece yarısı, tam onikide

Gözlerim çekiyor beni ufuklara.

Bir yıldız kayıyor,

  bir yaprak uçuyor rüzğarda.

Gözlerim takılı kalıyor yaprağa,

Gözlerim gidiyor,gidiyor yaprakla,

  ben kalıyorum yalnızlığımla..

  *        *        *

Sincan-Fatih arası, yaprak uçuşu

  kaç saat!. sormayın, bilmiyorum

Ama Sincan garındayız.

Biletimiz yok, kaçak biniyoruz trene

  söylemeyin biletçiye.

İstanbul''a gidiyormuş trenimiz.

Bir köşede titremekte yaprağım,

  gözlerim üstünde.

Bir çocuk uzanıyor, aldı-alacak...

Yeni bir rüzğarla kaçıyoruz,

Biletçi arkamızdan dalgın bakıyor.

İlk kaçak yolculuğumuzun heyacanı

  gözlerimde.

Biletçi gidiyor...

Biz savruluyoruz vagonda,

  oradan oraya...

  *        *        *

Bir istasyonda duruyor tren,

  hala trendeyiz.

Yaprakla gözlerim süzülerek iniyor,

Genç bir kızın okuduğu mektup üzerine

Bir damla ayrılıyor,kızın gözlerinden

Düşüyor gözlerime,gözlerim nemleniyor.

''Elveda''yı okuyorum,

  kız mektubu buruşturup atmadan önce

Yaprağı alıyor,yüzüne yaklaştırıyor,

Bir an gözgöze geliyoruz,

  ...gözlerimi kaçıramıyorum.

  *        *        *

Tren hareket ediyor,

Ne olduğunu anlamadan atıveriyor kız

  yaprağı ve gözlerimi pencereden.

Korkunç bir savruluş,peşpeşe takla,

Yerdeki su birikintilerine

  düşmekten korkarak

  zor atıyoruz kendimizi kenara.

Bir kaç sarhoş oturmuş şarkı söylüyor,

Bir köpek havlıyor uzaktan,susuyorlar.

Biri kalkmak isterken düşüyor,

  biri sızıyor,

  diğeri,bacası tüten bir eve bakıyor,

  ...ağlamaklı.

Bir tren geçiyor yine,

Yine savruluyoruz,

  rüzğarın kollarında uzaklara...

Bir pencere önüne konuyoruz,

İçerden çocuk ağlaması duyuluyor,

  ve bir ninni...

  gözlerim ağırlaşıyor...

Ezanlar başlıyor,dalga dalga,

Ayaklarım yanımda değil,

              ...toplayamıyorum.

Güzel bir bahar günü başlıyor,

Derin bir nefes çekmek istiyorum,

                  ...çekemiyorum.

  *         *       *

Gün ışıyor yavaş yavaş,

İşe gidenler telaşlı.

Yoldan alımlı bir kız geçiyor,

Gözlerim kızda kalıyor,

Yaprak bir kuşun gagasında

                 uzaklaşıyor...

Kız bir kaç mektubu zarfa

                  yerleştiriyor.

Zarfa bakarken,içine düşüyor

                        gözlerim.

Bir posta kutusunda kalakalıyorum.

  *         *        *

Kapım iki defa çalıyor,açıyorum,

Postacı,gülerek uzatıyor mektubumu.

Hayli kalın bir zarfı merakla

                      açıyorum.

İade edilmiş mektuplarımın arasında

Gözlerimi buluyorum,...ağlamış.

Anlaşılan okumuş veda satırlarını..

  *         *        *

Gözlerimi kuruluyorum,

  ''Üzülme''diyorum,

         ...üzülüyorum.

Saat kaç,günlerden ne !..

         ...bilmiyorum.', 'Gece yarısı, tam onikide Evimin balkonunda   gönlümün yalnızlığındayım. Gecenin anlaşılmaz uğultusu   ve rüzğarın fısıltısı   kulaklarımda. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/bir-yaprakta-seyahat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharda Ayrılık', 'baharda-ayrilik-ahmet-unal-cam-7qoya', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hava güzel, çiçekler güzel

Herkes şen, gülüp oynuyor

Ölmek için..

Yanlış zaman seçtin,

Ey !.. ümidim...', 'Hava güzel, çiçekler güzel Herkes şen, gülüp oynuyor Ölmek için.. Yanlış zaman seçtin, Ey !.. ümidim......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/baharda-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
