INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Altında', 'gunes-altinda-ahmet-ceylan-2-9qb77', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara kız kara yazar yazıyı,

Yazdırma alnına enayice kara yazıyı,

Gözlükler beni değil seni aldatır,

Mutku günler gelecektedir,

Çektirme onlara satır.

Geçici hislerine kurban olma,

Sonradan acı çekerek saçını yolma,

Yürüdüğün okul yolunda yorulma,

Hiçbir engele takılma ,enayi olma.

Gönül oyunundan önce ekmek parası,

Aç adamın olmaz karısı,

Kafada bilgi cepte varsa parası,

Hiçbir zaman ağlamaz insanın anası.

Her kötülüğün başı cehalettir,

Cehalet ise sefalettir.

Akıl ve irade namussuzluğa bektir,

Bugünden yarınını düşünmeyen eşşektir.

Uzun etme baba Ahmet,

Gelsin bu destanın sonu;

Anlayan kendiliğinden bulursa doğru yolu,

Güçlenir yücelir,bükülmez kolu.', 'Kara kız kara yazar yazıyı, Yazdırma alnına enayice kara yazıyı, Gözlükler beni değil seni aldatır, Mutku günler gelecektedir, Çektirme onla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ceylan 2']::text[], 8.5, '{"poet":"Ahmet Ceylan 2","poet_slug":"ahmet-ceylan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gunes-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havalar Pusluydu', 'havalar-pusluydu-metehan-selcuk-1ku26', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Havalar pusluydu

İnceden inceye yağmur yağıyordu

Gün ağarmış

Bak akşam olmuştu

Etrafımı sislerde sarmıştı

Ama sen yoktun yanımda

Tutunacak kimsede yoktu

İçimde bir korku vardı

Puslu havalar zaten beni

Hep korkuturdu

Ufakken, küçücükken

Böyle puslu havalarda

Anneciğimin

Kucağına sarılırdım, yapışır bırakmazdım

Ama şimdi

Anneciğimde yok

Şimdi ben ne yaparım

Kime sarılırım, kime tutunurum

Bir sen vardın

Ama şimdi neden yoksun

Bıktın mı benden hemen

Arıyorum şimdi seni

Daha fazla

Hasretine dayanamıyorum

Ya sen gel

Yada puslu havalar gitsin

Söyle de

Benim saçlarımı kim okşar

Ellerimden kim tutar

Sensiz korkarım bilirsin

Böyle akşamlarda

Dön artık bekleyemeyeceğim

Ey sevgili, duy artık sesimi', 'Havalar pusluydu İnceden inceye yağmur yağıyordu Gün ağarmış Bak akşam olmuştu Etrafımı sislerde sarmıştı Ama sen yoktun yanımda Tutunacak k...', ARRAY['Türk Edebiyatı','Şiir','Metehan Selçuk']::text[], 8.5, '{"poet":"Metehan Selçuk","poet_slug":"metehan-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/havalar-pusluydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar Çiceğim', 'nar-cicegim-metehan-selcuk-rllya', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Atalar diyarım

Canım, ciğerim, toprağım

Nasılda gelmişti ayrılık vaktimiz 

Ben istiyor muyum zannediyorsun

Hiç bu kadar üzüntü vermemiştin bana

Şimdi söyle, neden üzüyorsun beni 

Seninle aynı havayı, suyu, toprağı 

Börtüyü böceği  paylaşmadık mı

Bana ekmeğini, aşını, suyunu vermedin mi

Oysa ki ben nasıl sevmişim

Kader ayırıyorsa bizi

Elden ne gelir söyle nar çiçeğim

Buraya kadarmış yolculuğumuz 

Bilmiyor musun

Her yolculuğun bir sonu vardır

İşte bizim yolumuz 

Burada buracıkta ayrılıyor

Havada uçan kartalım, şahin bakışlım

Senden ayrılmak kolay mı zannediyorsun

Bilmelisin ki bende istemiyorum

Ama elden ne gelir

Kader işte

Her şeyi bırakıp gitmek 

Hele dostları terk etmek kolay mı

Söyle nar çiçeğim, mor menekşem

Niçin göz yaşları döküyorsun

Nar çiçeğim, mor menekşem

Bir gün çıkagelirim

Sanma ki unuturum seni

Ben nasıl unuturum seni

Nar çiçeğim 

Ağacını, yeşilini, denizini

İçtenliğini, toprak kokunu nasıl unuturum

Söyle nar çiçeğim

Seninle beraber yiyip içmedik mi 

Sevinçlerimizi üzüntülerimizi

Paylaşmadık mı

Söyle nar çiçeğim 

Unutur muyum zannediyorsun

Vefasız  mı çıkacak diye korkuyorsun yoksa

Ağlama ne olursun ağlama

Nar çiçeğim mor menekşem

Dökme göz yaşlarını

Sana kıyamam bilirsin

Bak bende ağlarım

İçim yanıyor nar çiçeğim  içim

Yoksa,

Göz yaşlarımız Kara denize sığmaz

Irmak olup taşar

Sil göz yaşlarını

Nar çiçeğim hadi sil

Vurulmuşum sana nar çiçeğim vurulmuş

Hadi, kucaklaşalım artık

Yaklaşıyor veda zamanımız

Kaderimizde bur da

Bu otogarda ayrılmak varmış

Ayrılık acıymış insanı çok kötü yakarmış

İnsan yaşayınca anlarmış

Bak üzüyorsun beni

Niçin nazlanıyorsun

Nar çiçeğim, mor menekşem

Beni dertlere koyuyorsun

Hadi üzülme sen, rahat ol,ferah tut kalbini

Sana uçan martıların, esen rüzgarların önünde 

Söz veriyorum, nar çiçeğim

Ucan kartalım, şahin bakışlım

Mor menekşem

Ama bil ki 

Bir gün geleceğim

Acını dertlerini süpürmek için

Hasretini dindirmek için

Geleceğim nar çiçeğim gelecek

Hadi ayrılalım artık 

Nasıl olsa

Kalplerimiz bir atmayacak mı

Bırak beni gideyim

Ne olur, yalvarıyorum

Şimdi gidiyorum, ne olur üzülme

Ağlama sakın, yas tutma arkamdan

Bir sabah döneceğim, bir sabah

Yeşilini denizini

Kucaklamak için

Nar çiçeğim', 'Atalar diyarım Canım, ciğerim, toprağım Nasılda gelmişti ayrılık vaktimiz  Ben istiyor muyum zannediyorsun Hiç bu kadar üzüntü vermemiştin b...', ARRAY['Türk Edebiyatı','Şiir','Metehan Selçuk']::text[], 8.5, '{"poet":"Metehan Selçuk","poet_slug":"metehan-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/nar-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-baris-ozkaya-2yjaw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne ucuz şeydir

    birileri uğruna gözyaşı dökerken

                                              şu balonlar

Ne pahalı şeydir

    birileri teker teker patlatırken

                                              şu balonlar

Bir partide

          patlattılar

             çocukların hayallerini

                           süsleyen balonları', 'Ne ucuz şeydir     birileri uğruna gözyaşı dökerken                                               şu balonlar Ne pahalı şeydir     birileri ...', ARRAY['Türk Edebiyatı','Şiir','Barış Özkaya']::text[], 8.5, '{"poet":"Barış Özkaya","poet_slug":"baris-ozkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/celiski-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalap Okulu', 'calap-okulu-yunus-emre-6e7ka', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söylememek harcısı söylemeğin hasıdır

Söylemeğin harcısı gönüllerin pasıdır

Gönüllerin pasını gel sileyim der isen

Şol sözü söylegil kim sözün hülasasıdır

Kul''il hak-dedi Çalap sözü doğru diyene

Bu gün yalan söyleyen erte utanasıdır

Cümle yaratılmışa bir göz ile bakmayan

Şer''in evliyasıysa hakıykatte asidir

Şeriat haberini şerh ile aydam işit

Şeriat bir gemidir hakıykat deryasıdır

Ol geminin tahtası her nice muhkem ise

Deniz merci kat olsa tahta uşanasıdır

Bundan içeri haber işit aydayım ey yar

Hakiykatin kafiri şer''in evliyasıdır

Biz talip-ilimleriz aşk kitabın okuruz

Çalap müderris bize aşk hod medresesidir

Evliya safa-nazar edeli günden beri

Hasıl oldu yunus''a her ne kim veyasıdır.', 'Söylememek harcısı söylemeğin hasıdır Söylemeğin harcısı gönüllerin pasıdır Gönüllerin pasını gel sileyim der isen Şol sözü söylegil kim söz...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/calap-okulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayalar', 'unutmayalar-yunus-emre-wdkhp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arifler ortasında sofilik satmayalar,

İhlas ile aşka riyayı katmayalar.

Ya bildiğini eyit, ya bir bilirden işit,

Teslimlik ucunu tut sözü uzatmayalar.

Kur’an kelamım dedi, gönlüne evim dedi,

Gönül ev ıssın bilmez, âdemden tutmayalar.

Gönül sındı bulundu, hem Hakk’a yakın idi,

Yine dikerim diye, bütünü yırtmayalar.

Mumlu baldır şeriat, tortusuz yağdır tarikat,

Dost için balı yağa, pes niçin katmayalar.

Arif can verir duymaz, yalancı mala kıymaz,

Yalan ile gerçeği beraber tutmayalar.

Kıymetin duyar isen, neye değer iş bu dem,

Erenlerin manasın almaza satmayalar.

Miskin Adem yanıldı, Uçmak''ta buğday yedi,

İşi Hak’tan bilenler şeytandan tutmayalar.

Şirin hulklar eylegil, tatlı sözler söylegil,

Sohbetlerde Yunus’u hergiz unutmayalar.', 'Arifler ortasında sofilik satmayalar, İhlas ile aşka riyayı katmayalar. Ya bildiğini eyit, ya bir bilirden işit, Teslimlik ucunu tut sözü uz...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutmayalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan', 'vatan-yusuf-aslan-zxbrq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Otuz beş bin askerle,

Batı cephesindeyken,

Savaştık hepimiz mertçe,

Yıllarca...Senelerce...

DİYARBAKIR/ŞEHİTLİK

                                                                01.05.2000', 'Otuz beş bin askerle, Batı cephesindeyken, Savaştık hepimiz mertçe, Yıllarca...Senelerce... DİYARBAKIR/ŞEHİTLİK                             ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Aslan']::text[], 8.5, '{"poet":"Yusuf Aslan","poet_slug":"yusuf-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/vatan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''ın Beni', 'ask-in-beni-yunus-emre-xc3g0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözüm seni görmek için elim sana ermek için

Bu gün canım yolda kodum yarın seni bulmak için

Bu gün canım yolda koyam yarın ivazın veresin

Arz eyleme uçmağını hiç arzum yok uçmak için

Benim uçmak neme gerek hergiz gönlüm ona bakmaz

İşbu benim zarılığım değildürür bir bağ için

Uçmak uçmağım dediğin mü''minleri yeltediğin

Vardır ola bir kaç huri arzum yoktur koçmak için

Bunda dahi verdin bize ol huriyi çiftü helal

Ondan geçti arzum tamam arzum sana ermek için

Sufilere ver sen onu bana seni gerek seni

Haşa ben terkedem seni şol bir evle çardak için

Yunus hasretdürür sana hasretini göster ona

İşin zulüm değil ise dad eylegil istedi çün.', 'Gözüm seni görmek için elim sana ermek için Bu gün canım yolda kodum yarın seni bulmak için Bu gün canım yolda koyam yarın ivazın veresin Ar...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-in-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Egeli', 'egeli-murat-gulen-urj0v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kadehimdeki  şarap  ne kadar günahımsa

sende o kadar günahımsın .

Beyaz  boyalı , begonyalı  evler gibi Egeli ,

sen benim  meltem rüzgarımsın.

Denizimsin,

Tuzumsun,

Aşkımsın .

Sen  Egeli ;  Sevdalımsın .', 'Kadehimdeki  şarap  ne kadar günahımsa sende o kadar günahımsın . Beyaz  boyalı , begonyalı  evler gibi Egeli , sen benim  meltem rüzgarımsı...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülen']::text[], 8.5, '{"poet":"Murat Gülen","poet_slug":"murat-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/egeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalsaydın', 'kalsaydin-gulay-dere-cky5k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalsaydın

Beni anlardın

Kalsaydın

Sönerdi içimi yakan bu ateş

Kalsaydın

Gitmek istemeyecektin bir daha

Kalsaydın...

Hep kalsaydın diyorum

Gitmeseydin uzaklara

Beni bir ıssız çölün ortasında

Bırakıp gitmeseydin

Belki bir gün pişman olup

Döneceksin geri

Fakat o gün

Bütün kapılarım kapalı olacak sana

Onca dökülen gözyaşlarımın yerine

O zaman sen ağlayacak

Sen yalvaracak

Ve sen öleceksin', 'Kalsaydın Beni anlardın Kalsaydın Sönerdi içimi yakan bu ateş Kalsaydın Gitmek istemeyecektin bir daha Kalsaydın... Hep kalsaydın diyorum Gi...', ARRAY['Türk Edebiyatı','Şiir','Gülay Dere']::text[], 8.5, '{"poet":"Gülay Dere","poet_slug":"gulay-dere","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kalsaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-hasan-canpolat-sqxw2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giden geri gelmezse de,

Üzülme, dik tut basini!

Hayat devam eder.

Anilarla yasamayi bil!

Uzaklara dalman anlamsiz.

Asmakta olsa da kaf daglarini güneş,

Umutlar kaybolmasin karanlıklarda,

Aglayan gözlerinde tut!

Biliyorum kizil elma misali,

Sen yaklastikca uzaklasirlar.

Bilsen de yetismeyecegini,

Olabilecegini var say!

Kos, ilerle, git, gidebildigin kadar!

Bakarsin yeniden bir umut dogar.', 'Giden geri gelmezse de, Üzülme, dik tut basini! Hayat devam eder. Anilarla yasamayi bil! Uzaklara dalman anlamsiz. Asmakta olsa da kaf dagla...', ARRAY['Türk Edebiyatı','Şiir','Hasan Canpolat']::text[], 8.5, '{"poet":"Hasan Canpolat","poet_slug":"hasan-canpolat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nasihat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimim?', 'kimim-zuhal-camci-26kar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben,

Çölde susuz bir gül

Değil;

Ben,

Denizde bir dalga

Değil;

Ben,

Ormanda herhangi bir ağaç

Değil;

Ben,

Gökteki samanyolu yıldızı

Değil;

Ben,

Dertlerini kimseyle paylaşamayan

Bir akıl hastası

Olabilir.', 'Ben, Çölde susuz bir gül Değil; Ben, Denizde bir dalga Değil; Ben, Ormanda herhangi bir ağaç Değil; Ben, Gökteki samanyolu yıldızı Değil; Be...', ARRAY['Türk Edebiyatı','Şiir','Zühal Çamcı']::text[], 8.5, '{"poet":"Zühal Çamcı","poet_slug":"zuhal-camci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ayrılık', 'bu-ayrilik-adem-aydin-hwjha', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu ayrılık

bağrımda bir kızgın ateş

gönlümü dağladı yaktı...

yaz ile açarken güneş

bu ayrılık nerden çıktı.

sevişmenin vakti derken

hicran için vakit varken

deli gibi severiken

bu ayrılık nerden çıktı

şu hasreti koy kenara

vazgeçince beni ara

sevişmeye geldi sıra

bu ayrılık nerden çıktı', 'Bu ayrılık bağrımda bir kızgın ateş gönlümü dağladı yaktı... yaz ile açarken güneş bu ayrılık nerden çıktı. sevişmenin vakti derken hicran i...', ARRAY['Türk Edebiyatı','Şiir','Adem Aydın']::text[], 8.5, '{"poet":"Adem Aydın","poet_slug":"adem-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutun Sözlere', 'tutun-sozlere-unal-bulut-928vi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gelecek ne olur bilmesem bile

Temennim devam etsin bu silsile

Satırlarımdasın ne hacet dile

Silmem seni olsanda binbir çile

Bana sensizlik getirdiği sürece

Peceli tatar mahiyetinde zaman

Uykusuz kaldiğim her yıldızsız gece

Zihnimi yakar, dizlerimde uyuman

Meşgul ettiğim zihinler gibi halim

Aklıma gelişinle manidar dilim

Nerdesin? Seni sayıklıyorum hala

Perişan olmama dakikalar kala

Unuttum derken büyük yalan söyledim

Her yalanımla metanetimi eledim

Kendini dahi tanıyamaz ki dünya

Belirsiz bu halimle bensiz kalsa ya

Bizden olmayanlara sizdenim demem

Bu topraklara küsüpte kin güdemem

Mesafeleri yok yere düşman etti

Yinede seni özlemeyi öğretti

Biz boşta yaşamadık aslında

Bir dilek sordular giriş kapısında

Ne kaldı geri, geçmişimi de eledim

Senle yaşlanıp, ölmeyi diledim…', 'Gelecek ne olur bilmesem bile Temennim devam etsin bu silsile Satırlarımdasın ne hacet dile Silmem seni olsanda binbir çile Bana sensizlik g...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tutun-sozlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Benim', 'canim-benim-adem-aydin-eh058', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben seni yürekten sevip sayarken

kimlerin sözüne aldandın canım

gördüğüm rüyayı hayra yorarken

sen beni bilmemki ne sandın canım.

canım benim güzel sevgili yarim

sayende artık yok hiç mecalim

senin ile görür iken gözlerim

bir kere yüzüme bakmadın canım', 'ben seni yürekten sevip sayarken kimlerin sözüne aldandın canım gördüğüm rüyayı hayra yorarken sen beni bilmemki ne sandın canım. canım beni...', ARRAY['Türk Edebiyatı','Şiir','Adem Aydın']::text[], 8.5, '{"poet":"Adem Aydın","poet_slug":"adem-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/canim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuzluk', 'susuzluk-unal-bulut-9as01', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beşere hakim canavarı bir damlada yen,

Can çekişirken içime doluver susuzluk,

Çöle aşıksa herhangi birimiz derinden,

Al, önce sarıl sonra yâr oluver susuzluk...

İlk önce renksiz gözlerim alındı,

Sonra karanlık  önümden çalındı,

O an tüm alem ışıksız bir handı,

Daraldık şu alemi ger susuzluk...', 'Beşere hakim canavarı bir damlada yen, Can çekişirken içime doluver susuzluk, Çöle aşıksa herhangi birimiz derinden, Al, önce sarıl sonra yâ...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/susuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Geçti', 'yillar-gecti-adem-aydin-94vnt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben gönlümün sultanını

bulamadan yıllar geçti

bir güzele kollarımı

dolamadan yıllar geçti

kimi huysuz kimi boysuz

diye diye kaldım yarsız

bir gönüle girip hırsız 

olamadan yıllar geçti', 'ben gönlümün sultanını bulamadan yıllar geçti bir güzele kollarımı dolamadan yıllar geçti kimi huysuz kimi boysuz diye diye kaldım yarsız bi...', ARRAY['Türk Edebiyatı','Şiir','Adem Aydın']::text[], 8.5, '{"poet":"Adem Aydın","poet_slug":"adem-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yillar-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasta Hoca', 'hasta-hoca-unal-bulut-si0gp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sefil, aynı kelimeye denk bir talebe,

Yoğuran eller, sefalete  çalar galebe,

Öldüren günahlarIn en başında cehalet,

Düşün hocam, bizleri ondan uzak hayal et,

Bu, iklimi solmuş, kış misali memlekette,

Benliğim etrafı görmesin diye bir pakette,

Tutan olmayınca uçar diye korkuyorum,

Olmasaydın, olası geçmişten ürküyorum...

Vefadan uzak çöl aşkları yaşıyor gönlüm,

YazIklar olsun ki benim gibi soldu gülüm,

Gülüm, bir gülen yüzüm birde önümde saygım, 

Öğreten üstad, öğrenmedim işte bu ayıbım...

Beni ve ben gibileri, her daim üzsünler,

Arkadan gelenler bu izleri elbet siler,

Tekrar gelecek misin? Sen, unutulmaz adam,

Gün doğdukça, seni üzmesinler HASTA hocam...', 'Bir sefil, aynı kelimeye denk bir talebe, Yoğuran eller, sefalete  çalar galebe, Öldüren günahlarIn en başında cehalet, Düşün hocam, bizleri...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasta-hoca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'istanbul', 'istanbul-adem-aydin-7wv54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'derler ki bu dünyanın inci sensin..

istanbul ben seni hiç sevmiyorum

bilmem ki  kaç gönüllerden geçersin 

istanbul ben seni hiç sevmiyorum.

bilseydi fatih seni kuşatırmıydı..?

görseydi bu halini yaşatırmıydı..?

beni de yuttun ya sırasımıydı....

istanbul ben seni hiç sevmiyorum.

havanda suyunda zehir zemberek

neyleyim sana muhtaç etmişse felek.

senden ayrılmak kurtulmak demek

istanbul ben seni hiç sevmiyorum', 'derler ki bu dünyanın inci sensin.. istanbul ben seni hiç sevmiyorum bilmem ki  kaç gönüllerden geçersin  istanbul ben seni hiç sevmiyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Adem Aydın']::text[], 8.5, '{"poet":"Adem Aydın","poet_slug":"adem-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istanbul-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran', 'haziran-bayram-karaali-4cfwg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haziran’a   bir el verdim  sımsıcak,

Beklemedim oysa  bunaltacağını nedense,

Elini sallıyor  Temmuz ; gel gel diyor,

Sevdaları,acıları,hüzünleriyle  seninim ...

Bir yağmur damlası düştü önüme,Haziran’da,

Kar tanesi  diye  elimi uzattım  tutacaktım.

Ellerimde eridi , yok olup buharlaştı akşam da,

Meyhaneler  dar geldi, içkiler tatsız,

Oysa;içmeye karar vermiştim yıkılasıya,

Kafam nede karıştı yahu,yüreğim sensiz,

Yağmurlarımı özledim sırılsıklam,

Ellerim cebimde,küskün,yalnız  ve sessiz..

Gecem bunaltıcı,gündüzüm karamsar,

Hüznü severim ya; sevdiğim,kadınım,

Ben Temmuz''lar da nedense mahvoldum,

Gelsinmi,gelmesinmi? Ben öylesine kararsız...', 'Haziran’a   bir el verdim  sımsıcak, Beklemedim oysa  bunaltacağını nedense, Elini sallıyor  Temmuz ; gel gel diyor, Sevdaları,acıları,hüzün...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haziran-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim', 'kim-ahmet-tufan-senturk-ywda8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu dünyaya gelen kim

Gel diyen kim, git diyen kim?

Alan benim, satan benim

Al diyen kim, sat diyen kim?

Şölen eyledim kendimi

Kendim biçtim kefenimi

Topraktan nazik tenimi

Var eden kim, yok eden kim?

Bakardım ama kördüm ben

Dostu dostuma sordum ben

Hakkı mânada gördüm ben

Görünen kimdir, gören kim?

Düşeni tutup kaldırdım

Ağlayanları güldürdüm

Cümle boşları doldurdum

Dolduran kimdir, dolan kim?

Ne yükseğe ne engine

Tufan coşup taştın yine

Anlat kendini kendine

Sen kimsin aradığın kim?', 'Şu dünyaya gelen kim Gel diyen kim, git diyen kim? Alan benim, satan benim Al diyen kim, sat diyen kim? Şölen eyledim kendimi Kendim biçtim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tufan Şentürk']::text[], 8.5, '{"poet":"Ahmet Tufan Şentürk","poet_slug":"ahmet-tufan-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Köyüm', 'ah-koyum-mehmet-feyat-tyi8x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuru ekmek soğan ile 

Ben köyümde mutlu idim

Yoktu yalan yoktu hile

Ben köyümde hile

Üç beş tavuk,iki koyun

Eğmezdim zalime boyun

Ey gözü doymazlar duyun

Ben köyümde mutlu idim

Şehre geldim azgınlaştım

Hırsız arsızla anlaştım

Güya böyle çağdaşlaştım

Ben köyümde mutlu idim

Kürsü kururdık tandıra

Yanardı gaz yağlı çıra

Hergün giderdim ahıra

Ben köyümde mutlu idim

Gün geçtikçe artar acım

Nerde şimdi anam bacım

Yazık namerde muhtacım

Ben köyümde mutlu idim

Ellerimizde hep nasır

Altımızda tek çul hasır

Kerpiç evler sanki kasır

Ben köyümde mutlu idim

Karasaban bir umuttu

Büyük şehir bizi yuttu

Bilmem kimin ahı tuttu

Ben köyümde mutlu idim

Ne sütüm var yoğurdum

Viran oldu yerim yordum

Düşündüm kendime sordum

Ben köyümde mutlu idim

Bizler çoban ve rençberdik

İyi kötü bir şey yerdik

Kader böyle boyun eğdik

Ben köyümde mutlu idim', 'Kuru ekmek soğan ile  Ben köyümde mutlu idim Yoktu yalan yoktu hile Ben köyümde hile Üç beş tavuk,iki koyun Eğmezdim zalime boyun Ey gözü do...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Feyat']::text[], 8.5, '{"poet":"Mehmet Feyat","poet_slug":"mehmet-feyat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ah-koyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harranlı Müneccim', 'harranli-muneccim-cahit-koytak-jipfp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sonunda yağmur yağacak,

hem öyle bir yağmur ki

yapılmayan işlerin,

ödenmeyen borçların,

tutulmayan sözlerin

mazereti olacak .

ve kefareti, uğruna bir tazenin

kalkıp yollara düşmeyi

ve kaderle güreşmeyi bu yaşta

göze alamamanın...

öyle bir yağmur ki, aylarca

belki yıllarca yağacak;

senatoyu su basacak,

sarayı, kiliseyi ...

ve patriğin külahını

snodun çamurlu tortuları üstünde

yüzdürecek kadar

yükselecek sular;

yağlı takkelerini yüzdürecek kadar

çerçöple birlikte,

kavgayı kızıştıran ruhanilerin;

ve takma başı üstündeki

takma perçemini

biçare imparatorun.

elmas sertliğinde yağacak,

sabır inceliğinde...

ve yasaları eritecek yağmur,

töreleri - o yıkılmaz sanılan

kaleleri, kurumları falan...

yer gibi sağlam, gök gibi her yerde

diyerek şanını yücelttikleri

ama kanını emdikleri,

kökünü kemirdikleri

köhne devleti...

öyle bir yağmur ki...

allakbullak edecek piyasaları,

dinleri, sanatları, ülküleri;

maskaraların suratlarına sürdükleri

boyalı pudra gibi eritip akıtacak,

pudra şekeri gibi...

dilleri, üslupları, retorikleri.

ve siz ey, süslü seremonilerin,

sadakat gösterilerinin,

ödüllerin, nişanların altında

yamalı ciğerlerini,

tahta cambaz bacaklarını

gizlemeye çalışan

yeteneksiz saray şairleri!

o yağmur yağınca,

o büyük yağmur,

teranelerinize can katmak için

cıvıltılarına kulak kabarttığınız,

tahsisat-ı mestureden ödenekli

ilham perileriniz,

ilham fareleriniz

yuvalarından dışarı vuracak,

halkın yatağının, yastığının altından,

gardıroplarından fahişelerin,

akla gelen her kuburdan,

hatta ayak yollarından muhaliflerin;

hem de leşlerinin kuyrukları

sizin burunlarınıza

dolanmış olarak!

o yağmur yağınca,

o büyük yağmur,

kemerli, revnaklı hayalhanelerinde

arp çalan, neşide söyleyen,

iskambil falı açan

ve tatlı ürpermeleri içinde

ölümlü ihsasların

aşk oyunlarıyla oyalanan

zarif ruhlarını çürütecek rutubet

ve rakik vicdanlarını

suskun entelektüellerin.

ve yıkayacak o büyük yağmur,

silip temizleyecek

noktasına, virgülüne kadar,

halkın belleğine balçıkla sıvadıkları

bulanık satırlarını,

görece lekelerini şöhretimin;

o göçebe serazen güzeliyle yaşanan

küçük, masum macerayla ilgili...

bunları ben söylüyorum;

en uzak yıldızlara,

ziclere, atlaslara bakarak...

ben, El Harizmi''nin gözde tilmizi,

-öyle olduğu için de

Bağdat''ta tutunamayan,

Roma''da anlaşılmayan,

ve Bizans''ta, elli yaşında

tam yıldızı parlayacakken

adı ikon kırıcıya

ve kart hovardaya çıkartılan-

ben, yıldızbilimci, şair,

Harranlı Leon:

ben, matematikçi, mimar, ressam;

rum ateşinin mucidi;

hendesede hace-i hacegân;

yedi dilde konuşan,

üçünde yazan-bozan;

gizli ilimlerde,

bahusus maraz-ı kalpte

ve inkisar-ı aşk ve muhabbette uzman;

diline hâzık hekim,

eline mahir cerrah;

tarid-i cin ve sihir,

ilahiri ilahiri ilahir...', 'sonunda yağmur yağacak, hem öyle bir yağmur ki yapılmayan işlerin, ödenmeyen borçların, tutulmayan sözlerin mazereti olacak . ve kefareti, u...', ARRAY['Türk Edebiyatı','Şiir','Cahit Koytak']::text[], 8.5, '{"poet":"Cahit Koytak","poet_slug":"cahit-koytak","theme":"Türk Şiiri","is_hero":false,"total_lines":107,"source_url":"https://www.antoloji.com/harranli-muneccim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Kalmak', 'gec-kalmak-nurol-banabak-xp1w3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir yazarım

Yazının icadından önce

Ben bir şairim

Şiirin icadından önce

Ama dostlar, ama dostlar, aman dostlar

Ben bir insanım

İnsanın icadından çoook sonra', 'Ben bir yazarım Yazının icadından önce Ben bir şairim Şiirin icadından önce Ama dostlar, ama dostlar, aman dostlar Ben bir insanım İnsanın i...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gec-kalmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz''e özlem', 'deniz-e-ozlem-murat-gulen-47t6s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Damla olmak istedim  deniz''e, 

bütüne  karışmak için.

Yelken olmak istedim üstünde.

Özgürce gezmek için.

Balık olmak istedim  denizde, 

her yerini görmek için.

Dalga olmak istedim.

Köpük köpük bembeyaz  olmak.

Kıyılara  varmak.

O Yüce hali, 

masmavi.

Bazen  sakin, bazen deli.

Deniz olmak istedim, 

denizi çok özledim…', 'Damla olmak istedim  deniz''e,  bütüne  karışmak için. Yelken olmak istedim üstünde. Özgürce gezmek için. Balık olmak istedim  denizde,  her ...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülen']::text[], 8.5, '{"poet":"Murat Gülen","poet_slug":"murat-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deniz-e-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum Ölürse', 'dostum-olurse-murat-gulen-jxvk8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açtım ellerimi  iki yana.

Sevgiden  yana.

Dünyalar benim olsa ne yazar.

Dostlarım  giderse azar azar, 

kahrımdan vururum başımı, 

ağlayarak sorarım.

Çok mu gördün Tanrım? 

Aldın,  arkadaşımı.

Gözlerim dolu dolu, aklım mazide.

Andıkça  dostumu, saf yüreğimde.

Ah, dostum dedikçe, 

ıssız çölde bir serap gibi.

Sevgi dediğin azar azar.

Ha var ha yok gibi.

Bir  yudum  suya  verdim koca bir serveti.

Yoksa öksüz  gelin gibi

her  yerim ziynet olsa ne yazar.', 'Açtım ellerimi  iki yana. Sevgiden  yana. Dünyalar benim olsa ne yazar. Dostlarım  giderse azar azar,  kahrımdan vururum başımı,  ağlayarak ...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülen']::text[], 8.5, '{"poet":"Murat Gülen","poet_slug":"murat-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dostum-olurse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırat''a Sesleniş', 'firat-a-seslenis-mehmet-feyat-g05oy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fırat coşkun ve deli, Fırat azgın serseri,

Ne kadar zulüm yıkım varsa onun eseri

Boynunda kemend mi var akıyorsun pespaye

Başıboş mu kalmlışsın, ne hedef var,ne gaye

Ben sana sevdalıyım, bilmezsin asırlardır

Sana anlatacağım yığınca derdim vardır

Senden şikayetim var, akarsın deli dolu

Senden vefa bekliyor bu mahzun Anadolu

Neden kendinde değil,sarhoş geçer her demin

Seninle anlaşmıştık,hem kavil hem de yemin

Tersine akıtmalı, seni durdurup baştan

Mahrum etmeli seni, hem sudan hem de aştan

Biz görmezken gün yüzü, senin yüzün parıldar

Sana dar gelmelidir, sığdığın yatağın dar

Anlatsam dinler misin, belki saatler boyu

Gece uzar gün uzak, karanlıklar kopkoyu

Sana anlatmam lazım iknaya mecburum ben

Yıllardır ezilmişim, mazlumum mağdurum ben

Köyümüz yerle yeksan şehirde varoştayım

Bana zindan bu halim, sanki bir koğuştayım

Geçmiyor gayri zaman, sen sınırlar aşarken

Senin umurunda mı, biz perişan yaşarken

Ey Fırat! sen gamsız, sen çilesiz şeysin

Biz esir, biz biçare bize Fırat neylesin

Ama yürek bu işte,doldu mu taşar böyle

Haksız mıyım ey Fırat, şimdi doğruyu söyle

Bize umut vermeli, bize can katmalısın

Vardığın her sınırda bunu anlatmalısın

Senin adın dillerde, benim dilim ellerde

Kim bilir yadımızı koydun hangi ellerde

Haykırışım feryadım belki de beyhudedir

Çektiğim çile, azap bu yürekte ukdedir

Lügatları devirdim tarif için halimi

Ben sustum, sen çağladın güçlendirdik zalimi

Ne benim feryatlarım, ne çağlayışın

Ya benim çilem yalan, ya senin ağlayışın

Sana vasıl olmanın bir yolu vardır amma

Sen o büyük cüssenle bir sırsın, bir muamma

Ben sana haykırmaya, davete mecbur muyum?

Lal olsun benim dilim, kurusun benim huyum

Hiç aklına gelmez mi, yadına düşmez miyiz?

Böyle perişan, mahzun kalacak bir biz miyiz?

Yeter artık bu halin, beni çıldırtıyorsun,

Bana korku türleri dersleri veriyorsun.

Sana taş mı diyeyim, zaten sen taş yiyorsun,

Ben karalar bağlarken, sen taşa bağla yosun.

Karanlık çöktü demin, yakamozlar belirdi,

Bu dertle nice mecnun nice bin kez delirdi.

Sana zulmü anlattım, suskunluğum bozarak,

Sana name yolladım, göz yaşımla yazarak.

Hiç karalar bağlamaz,anlamaz mısın yası,

Sele kapıldı gitti, milyonların hülyası.

Ah Fırat, zalim Fırat kar eridi bahardır,

Seni bekleyen nice kurak topraklar vardır.

Nasip olur mu bir gün kavuşmak bir tenhada,

Vuslatımız belki de artık öbür dünyada.

Özlüyoruz gün be gün, şırıltını sesini

Kime söylemektesin ağıtını ninnini?

Bize söyle, bizi duy, bize doğru ak biraz,

Nerde bahar mevsimi, nerde açar ak kiraz.

Durdurmaz sanıyordum ne duvar, ne set seni,

Yıldıramaz duyordum ne kin, ne haset seni.

Yatağına sığmayan bir er bilirdim seni

Tutmayan dizlerime bir fer bilirdim seni.

Artık ağlamalıyım söndü gözümün feri

Kaybetmek üzereyim sağ olan tek neferi

Dua ettim Rabbime birleştir gönlümüzü,

Ya bizi burda öldür, ya güldür yüzümüzü.

Gel artık zalim Fırat kollarını aç bana,

Ova, nehir, dereler yıllar var ki aç sana.

Yetmez mi bağırdığım bunca zaman, bunca gün,

Benim feryatlarımdan sen alınma, sen öğün.

Ümidim var bu zulüm sürmez ki haşra kadar,

Bize bir selam yolla, olsa da katre kadar.

Sen ummanı özlersin, dökülürsün taşarsın,

Kim bilir hangi ilden ne öyküler yaşarsın.

Sen beni bir başıma böyle bırak kimsesiz,

Sen deli-dolu Fırat, ben öksüz, garip, sessiz.', 'Fırat coşkun ve deli, Fırat azgın serseri, Ne kadar zulüm yıkım varsa onun eseri Boynunda kemend mi var akıyorsun pespaye Başıboş mu kalmlış...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Feyat']::text[], 8.5, '{"poet":"Mehmet Feyat","poet_slug":"mehmet-feyat","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/firat-a-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biçare Yarim Biçare Yüreğim', 'bicare-yarim-bicare-yuregim-abluka-gunerhan-78qow', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kavrulmuş yüreğim 

Çatlamış dudağım 

Bu mahşer  sıcağında 

Bir yudum sevgine hasret

İster yüreğim elbette

Senide sevgini de

Ama...

Bu bir nafile haykırıştır

Sana ve sevgine olan 

Özlem çığlığı olsa bile 

Olsa bile yarim 

Bilir ki gönlüm 

Elbette sevmek ister yüreğim

Ama...

Acı veriyor hep bana 

Bu sevmeler  sevilmeler

Riyakar yare böyle tutunmalar

Tatlı uykumdan 

Kabusla uyanmak gibi

Hüzne boğuyor hep beni

Bu sevmeler sevilmeler

Biçare yüreğin 

Kovulmuş gönül dergahından

Yapma gülücükler

Sararmış koynunda güller

Sevmesini bilemedin 

Bilemedin yar

Geçiyor günler geçiyor 

Geliyor hicran 

Geliyor yar

Ve şimdi sevgili yarim

Mevsim sonbahar 

Kopuyor yapraklar

Birer birer', 'Kavrulmuş yüreğim  Çatlamış dudağım  Bu mahşer  sıcağında  Bir yudum sevgine hasret İster yüreğim elbette Senide sevgini de Ama... Bu bir na...', ARRAY['Türk Edebiyatı','Şiir','Abluka Günerhan']::text[], 8.5, '{"poet":"Abluka Günerhan","poet_slug":"abluka-gunerhan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bicare-yarim-bicare-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz Destanı', 'temmuz-destani-zeki-ergin-wgziv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'en güzel şiirlerimi yazmalıyım

    sevgi kardeşlik barış ve özgürlükten yana

    pınarlarından içmeliyim

    çam kokulu suları

    kana kana içmeliyim  korkusuzca

-1-

bir ses yaladı şafağı

güvercin güvecin  uçuverdi denizaşırı

dost düşman sustu

bu sıra bir zeytin dalı kopardı

Lefkoşe yolunda Sıvaslı Mehmet

uzattı Giritli  Dimitroya

aldığı cevap

bir şarjör dolusu kurşundu

durur mu artık Adanalı ahmet

iki adım arayla yatıyor şimdi

boyluboyunca iki ceset

oysa yaşamak istiyordu

Baflı Ayşe Lefkeli Yorgo

Magosalı ali Limasollu Despina

hepsini de en çok

yavuklusunu öpemeden ölmek

elinden su içemeden ölmek 

kahrediyordu

bir ses yaladı şafağı

güvercin güvercin uçuverdi denizaşırı

dost düşman sustu

zorbalara karşı

çağdışı insanlara karşı

namlular

günlerce ölüm  kustu

-2-

dün baharlar bahar

bayramlar bayram değildi

yaşanılır gibi değildi

bu eller özce

insanca yaşanılır gibi değildi

-3-

bir türküyü sindiriyoruz hücrelerimize

sevgiden barıştan özgürlükten yana 

adı temmuz türküsü

yaşıyoruz yüzyıllarca

yaşıyoruz halklarca

duyunca Zeüs indi

binlerce yıllık tahtından

olimpos dar geldi

irkildi sevincinden

düştü asası ansızın elinden

-4-

20.yüzyıl Neronları 

şaşkınlığınız  öfkeniz kadar

bizim sevgi dolu yüreğimiz

ırmaklardan denizlere kadar

kim barbar kim  gaddar

yakın isterseniz yeni romalar

gün 24 saat uygarlık sağdığımız

kitapları yakın isterseniz

ne yapsanız kurumaz bizim ırmağımız

bu tarihin akışıdır

bu bir senfoni

bu dünyaya bilimin akışıdır

-5-

bu bir temmuz türküsüdür

bu türküyle ballandı

bir gecede Girne bağları

aynı tastan içiyoruz şarabını

Afroditin elinden

şimdi Yorgo zeybek oynuyor

Mehmet sirtaki

-6-

ve ötelerde

zincirlerini kırmaya  çalışıyor

Gazzeli Abdullah

Santiyagolu Salvador

_çağ şubat1975 sayı:4

_sevgiliye isyan yt:haz04', 'en güzel şiirlerimi yazmalıyım     sevgi kardeşlik barış ve özgürlükten yana     pınarlarından içmeliyim     çam kokulu suları     kana kana...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/temmuz-destani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınırında Bir Yaşam', 'sinirinda-bir-yasam-riza-aslan-l1tps', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sınırında bir yaşam

yaşamaya çalıştığın

ucunda bekleyip

karar veremediğin

atlamak kurtulmak,

veya bekleyip kaybolmak.

anlık bir karar

hesapsız yarınsız

pişmanlık olmayan

karar veremediğin

atlamak kurtulmak

veya bekleyip kaybolmak

25-03-2001', 'sınırında bir yaşam yaşamaya çalıştığın ucunda bekleyip karar veremediğin atlamak kurtulmak, veya bekleyip kaybolmak. anlık bir karar hesaps...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sinirinda-bir-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum Seni', 'bekliyorum-seni-umit-kara-be77m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğimde hiç bitmeyen bir umutla

Beklemeden gidenlerin dönmesini

Mavi ufuklarda bekliyorum seni

İstikbalime güvenmemek değil

Geleceğimde sen varsın

Gerçek bir özlemle bekliyorum seni

Yalnız korkmuyorum sanma sakın

Bir heyula sardı gecelerimi

Ayrılığın korkusunda bekliyorum seni

Bir umut ekspresiyle ağır ağır

Hemen dön geçmeden kara tren

Gözüm yollarda bekliyorum seni

Gözümden uzaksın göremiyorum seni

Ama gönlüme yakın ol

Gönülden bekliyorum seni

Sağnak sağnak yağıyor yağmur

Bekleme yağmurun dinmesini

Sular durulmadan bekliyorum seni

Henüz acın dinmedi gönlümde

Yanıyor acın hala içimde

Ağıtlar bitmeden bekliyorum seni

Gündüz kavuşmadı geceye

Güneşin batmasını bekleme

Karanlık basmadan bekliyorum seni

Bir mazlum ceylan gibi bekleme dağlarda

Av olursun bilinmez avcıya

Vurulmadan kalbinden bekliyorum seni

Dönmeden kurt kelebeğe

Rüzgar yaprağı dökmeden yere

Gitme bu bilinmez son sefere

Yollara düşmeden bekliyorum seni', 'Yüreğimde hiç bitmeyen bir umutla Beklemeden gidenlerin dönmesini Mavi ufuklarda bekliyorum seni İstikbalime güvenmemek değil Geleceğimde se...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kara']::text[], 8.5, '{"poet":"Ümit Kara","poet_slug":"umit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bekliyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek İsterim', 'olmek-i-sterim-umit-kara-6ruh1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir nur aktı kalbime ılgıt ılgıt

Bu gece ilahi alemden

Fikrime güneş doğdu Medineden

Ateşi aşk yaksa yüreğimi

Ebu cehilin yardığı kalbim

İpil ipil akıtsa kanını toprağa

Kanla ulaşılmış bir sevdaya kavuşmadan

Karanlığın girdabında boğulmadan aciz aklım

Yokluğun çilesinde kırılmadan gönlüm

Sensizliğin acısından vurgun yemeden kalbim

Cehennemin ateşinde yanmadan bedenim

İslamın hakimiyeti kaybolmadan dünyadan

Kafirin okuna sinem hedef olmadan

Kelime-i şehadeti dilim okumadan

Girmeden bedenim toprağa

Görmeden kara günleri cehaleti

Cahil Kureyşi Ebu Lehebi hübeli

Kopmadan kıyamet yüreğimde

Taşlar sağnak gibi yağmadan semadan

Peygamberin izinden ayrılmadan

Gören köre artık perde açılmadan

İyiler kötüyü kötüler iyiyi korumadan

Hiç aldırmadan kaderin böylesine

Kaderim neyse işte o zaman

Al canımı rabbim sana kavuşayım

İşte o ecel her an...', 'Bir nur aktı kalbime ılgıt ılgıt Bu gece ilahi alemden Fikrime güneş doğdu Medineden Ateşi aşk yaksa yüreğimi Ebu cehilin yardığı kalbim İpi...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kara']::text[], 8.5, '{"poet":"Ümit Kara","poet_slug":"umit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olmek-isterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık Şiir', 'satilik-siir-umit-yasar-oguzcan-egqfs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sersemin biriyim

Oturmuş senin için aşk şiirleri yazıyorum

Ellerinin beyazlığından

Gözlerinin güzelliğinden bahsediyorum

Oysa sen

Bir ettir, kemiktir tutturmuşsun

Gözün dünyayı görmüyor

Al bu şiirimi götür sat

Bir ekmek

Yarım kilo pirzola al

otur zıkkımlan', 'Ben sersemin biriyim Oturmuş senin için aşk şiirleri yazıyorum Ellerinin beyazlığından Gözlerinin güzelliğinden bahsediyorum Oysa sen Bir et...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/satilik-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran', 'haziran-necati-cumali-m37b4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin saçların, gülen gözlerin,

Haziran günleri gibi aklıma gelir:

Daha ağaçların gölgeleri serindir

Kaçıp gidemem

Gömülmüşüm sararan kitaplar arasına

Arka odalarında evin

Gölgeler düşer çinili tabaklara

Hasır sepetlerde mavi ibrişimler

Solar önünde pencerelerin

Bir dakika rahat yok senden

Elim bir kibrit çöpüne değmesin

Saatte, kapıda aklım fikrim

Duvarda su buharının aksinden

Dışarda sağır bir akasyadan başka

Kalmadı semtime uğrayan kimsem

Kalbinden daha hafif basma entarin

Tek, benim halim olsun sana tasa

Olsun artık ne olacaksa! 

Yanımda saçlarını, eteklerini uçuran

Şu rüzgar çıksa da bir serinlesem

Gömülmüşüm sararan kitaplar arasına

Yetti bu sıkıntı bu sınav derdi

Çekilmez oldu artık bu hava

Bir yerimden ayrılacak kuvveti bulsam

Yüreğim öyle feraha kavuşacak ki...', 'Senin saçların, gülen gözlerin, Haziran günleri gibi aklıma gelir: Daha ağaçların gölgeleri serindir Kaçıp gidemem Gömülmüşüm sararan kitapl...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumalı']::text[], 8.5, '{"poet":"Necati Cumalı","poet_slug":"necati-cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/haziran-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyor', 'korkuyor-william-shakespeare-6gddt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanların çoğu kaybetmekten korktuğu için, sevmekten korkuyor. 

Sevilmekten korkuyor, kendisini sevilmeye layık görmediği için.

Düşünmekten korkuyor, sorumluluk getireceği için. 

Konuşmaktan korkuyor, eleştirilmekten korktuğu için.

Duygularını ifade etmekten korkuyor, reddedilmekten korktuğu için. 

Yaşlanmaktan korkuyor, gençliğinin kıymetini bilmediği için. 

Unutulmaktan korkuyor, dünyaya iyi birşey vermedigi için. 

Ve ölmekten korkuyor aslında yaşamayı bilmediği için.', 'İnsanların çoğu kaybetmekten korktuğu için, sevmekten korkuyor.  Sevilmekten korkuyor, kendisini sevilmeye layık görmediği için. Düşünmekten...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korkuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamet', 'kiyamet-yunus-emre-glloo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anmazmısın sen şol günü cümle alem uryan ola

Ne ata oğula baka ne kardaştan derman ola

Dağlar yerinden ayrıla heybetinden gök yarıla

Yıldızın bendi kırıla yere düşe perran ola

Malik tamuya çağıra zebaniler saf saf dura

Korkusundan yer yarıla titreyü ben hayran ola

Malik eder hey hey tamu kıyameti gördün ya''ni

Asileri getireler gire sende perran ola

Zebaniler yetip tuta getüre tamuya ata

Derü yanup sökük tuta dün gün işin efgan ola

Yunüs senin ki bu sözün kan yaşıla doldu gözün

Ol hazrete tuta yüzün yine derman andan ola', 'Anmazmısın sen şol günü cümle alem uryan ola Ne ata oğula baka ne kardaştan derman ola Dağlar yerinden ayrıla heybetinden gök yarıla Yıldızı...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiyamet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Kendi Kanını', 'asik-kendi-kanini-yunus-emre-12gfo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Helal kıldı ma''şuka aşık kendi kanını

Ma''şuk nakşından okur aşk eri Kur''anını

Yardan ayrı olunca asılıp ölmek yeğdir

Aşık kendi bırakır boynuna urganını

Gitmez aşık gözünden hergiz ma''şuk hayali

Nitekim zilha verir Yusuf''un nişanını

Dirlik budur aşıka ma''şuk yolunda öle

Sorarlar ise aydam aşıkın burhanını

Belkıys ile Süleyman aşka düştü bir zaman

İsteyip bulmadılar bu derdin dermanını

Gökteki Harut Marut aşk için indi yere

Zühre yüzün görecek unuttu Rahman''ını

Güzaf görmen siz aşkı kime oğradı ise

Sultanı iltir baştan yitirir hanmanını

Ferhat bu aşk yolunda başın külünge tuttu

Hüsrev Şirin derdinden dosta verdi canını

Leyli''yle Mecnun işi acebdür ( ür ) bu halka

Abdürrezzak terk etti aşk için imanını

Zemane vefaları cefa gelir yunüs''a

Bir doğru yer bulucak fidi kılar canını', 'Helal kıldı ma''şuka aşık kendi kanını Ma''şuk nakşından okur aşk eri Kur''anını Yardan ayrı olunca asılıp ölmek yeğdir Aşık kendi bırakır boyn...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asik-kendi-kanini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çift Boncuk', 'bir-cift-boncuk-mehmet-toprak-gonen-vayug', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülümsüyor davet edercesine gizemine

Gülümsüyor bir çift boncuk içine saklanmış ışık

İzin verme hiçbir dünyasal boşluğun ışığını söndürmesine

İzin verme sönmesine hayır

Yazıktır tanrısal esrarla kuşatılmış güzelliğine', 'Gülümsüyor davet edercesine gizemine Gülümsüyor bir çift boncuk içine saklanmış ışık İzin verme hiçbir dünyasal boşluğun ışığını söndürmesin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Toprak Gönen']::text[], 8.5, '{"poet":"Mehmet Toprak Gönen","poet_slug":"mehmet-toprak-gonen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-cift-boncuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelgit', 'gelgit-suna-aydin-jxenp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelgitlerle yaşıyorum...

Bir dakika önce herşey sular altındayken bir dakika sonra,

Sular çekiliyor uzun, ıssız bir kumsalda yalnız başıma kalıyorum.

Ve sonra yine aynı kısır döngü tekrar ediyor.

Bazen sular o kadar derinleşiyor ki; kendimi bırakmak, açılmak,

Sahili, insanları, tüm hayatımı unutmak,

Arkama bakmadan yüzmek istiyorum.

Ama tam o sırada sular tekrar çekiliyor ve

Ben yine karaya vuruyorum. O ıssız, yalnız karaya...', 'Gelgitlerle yaşıyorum... Bir dakika önce herşey sular altındayken bir dakika sonra, Sular çekiliyor uzun, ıssız bir kumsalda yalnız başıma k...', ARRAY['Türk Edebiyatı','Şiir','Suna Aydın']::text[], 8.5, '{"poet":"Suna Aydın","poet_slug":"suna-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gelgit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahta Sandalyeler', 'tahta-sandalyeler-yasin-bozkurt-oquir', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve günün birinde çıkageldi ki, 

en kaybettiğim anlardan biriydi,

korktum biran çünki tanımıyordum 

                                 o duyguyu

daha önce hiç tatmamıştım...

Birden mavi çıkageldi,

gözlerim ferine yeniden kavuştu,

ve yeni bir gonca açtı düşlerimde.

Ne kadar geride kalmış olsada,

yinede en az senin kadar yakındı,

özlem duyuyordum...

Biryerlerde bırakıyorum ümitlerimi şimdi,

Bu zamansız ve mekansız alemde,

kendimden kaçıyorum.

Bir nokta kadar küçük hayallerim,

Koca kağıtta bir nokta ama,

içinde koca bir alem saklanıyor...

Bak neleri eritiyor o küçük nokta 

                                      içinde,

Ve eleri gizlemiş,

yaşamak her anda her boşluğunda 

                               zamanın..

Bir kuş kanat çırpıyordu serin,

dingin maviliğin üstünde,

sen koşuyordun, ben sabırsızlanıyordum,

Neden şimdi bu engeller,

Tamda yırtıp atmışım,yırtıp atmışız

                                     derken,

En çözülmez sırları ve zorlayıp,

aşıp karşısında güldüğümüz zorlukları.

Yeşil bir çimenasılıydı ve damlıyordu çardaktan,

Evin her tarafı da dökülmüştü,

penceresiz camsız hatta kapısının yerinde 

kuru bir yel gezinip duruyordu.

odalarıda eski püskü, kırık dökük,

sedirler ve tahta sandalyeler vardı.

Birkaç kedi yavrusu gezniyordu,

bir o yana bir bu yana,

yaşanmış anılar geziniyordu....', 'Ve günün birinde çıkageldi ki,  en kaybettiğim anlardan biriydi, korktum biran çünki tanımıyordum                                   o duyguy...', ARRAY['Türk Edebiyatı','Şiir','Yasin Bozkurt']::text[], 8.5, '{"poet":"Yasin Bozkurt","poet_slug":"yasin-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/tahta-sandalyeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısır Döngü', 'kisir-dongu-kursat-aksu-atdvg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saat bilmem kaç olmuş, 

Ben yine yalnızım. 

Gün sabahı bulmuş, 

Ben yine bekliyorum. 

Güneş karşıya vurmuş, 

Ben yine ağlıyorum. 

Ay yerini almış, 

Ben yine arıyorum. 

Yıldızlar kendini bulmuş, 

Ben yine korkuyorum. 

Zaman durmuyor, 

Ben yine yoruluyorum. 

Fakat günlerden sonra.., 

Zaman yerimi alıyor 

Ben YOK oluyorum...', 'Saat bilmem kaç olmuş,  Ben yine yalnızım.  Gün sabahı bulmuş,  Ben yine bekliyorum.  Güneş karşıya vurmuş,  Ben yine ağlıyorum.  Ay yerini ...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Aksu']::text[], 8.5, '{"poet":"Kürşat Aksu","poet_slug":"kursat-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kisir-dongu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeynep', 'zeynep-tarik-selek-kjxc2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman olurda birgün seninle

El ele dolaşmak sahillerde 

Yıldızların ışığında dans etmek 

Nehirlerin akışını izlemek 

Elbet birgün olu diye düşlüyorum 

Papatya tarlalarında seni düşlüyorum', 'Zaman olurda birgün seninle El ele dolaşmak sahillerde  Yıldızların ışığında dans etmek  Nehirlerin akışını izlemek  Elbet birgün olu diye d...', ARRAY['Türk Edebiyatı','Şiir','Tarık Selek']::text[], 8.5, '{"poet":"Tarık Selek","poet_slug":"tarik-selek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zeynep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zannettiğim', 'zannettigim-cem-yasar-d3dgb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözyaşı gibi gideceğim

buralardan

kalbinin üstünden kayarak.

kalbindeki yokuşta

sağlı sollu dizilmiş

yeşil yapraklı ulu ağaçlar 

uğurlayacak beni.

rüzgar esecek.

yapraklar hışırdayacak.

Dolmabahçe''nin önünden

bir vapur geçecek.

Haydarpaşa’da Ankara’dan gelen

bir tren düdüğü duyulacak.

bir bebek ağlayacak.

çok sevdiğin bir şeyi hatırlayacaksın.

çok sevdiğim seni hatırlayacağım.

gözyaşı gibi gideceğim

buralardan

kalbinin üstünden kayarak.

yokuş sallanacak.

yapraklar uğuldayacak.

kalbin yaslanacak.

zamana yenik düşeceğim.

tabi ki sende

yine uğurlayanlar olacak beni

sen de uğurlayacaksın 

muhakkak birilerini

ne Dolmabahçe’de vapur,

ne Haydarpaşa’da Ankara’dan gelen tren,

ne de bir bebek çığlığı olacak.

sevdiğin bir şeyi hatırlayacaksın,

sevdiğim seni hatırlayacağım.

rüzgar beni üşütecek

sen titreyeceksin. 

gözyaşı gibi gideceğim 

buralardan

kalbinin üstünden kayarak...', 'Gözyaşı gibi gideceğim buralardan kalbinin üstünden kayarak. kalbindeki yokuşta sağlı sollu dizilmiş yeşil yapraklı ulu ağaçlar  uğurlayacak...', ARRAY['Türk Edebiyatı','Şiir','Cem Yaşar']::text[], 8.5, '{"poet":"Cem Yaşar","poet_slug":"cem-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/zannettigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Giderken...', 'o-giderken-yavuz-dogan-vtgts', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Faili belli

         Mağduru meçhul

                  Lirik bir ağıttı yaşadığımız...

                                Bir destan değil….

Şimdi kim sever böyle kim bekler yollarımda

Böyle terkedip gitmek kolay mı sanıyorsun

Kim koklar saçlarını kim uyur kollarımda

Beni kahredip gitmek kolay mı sanıyorsun

Nereye gider şimdi terkedilmiş öpüşler

Kimlere rüya olur yarım kalan bu düşler

Yüreğimi yırtıp ta delerken  son gülüşler

Maziyi silip gitmek kolay mı sanıyorsun

Sonra kimler öpecek yaş dolu gözlerini

Söyle kim dinleyecek aşk dolu sözlerini

Yüreğimden söküp te mazinin izlerini

Beni mahfedip gitmek kolay mı sanıyorsun

Ardından matem tutmak

Hasrete hasret katmak

Anıları unutmak

Kolay mı sanıyorsun

Yolunu gözlemeyi

Kokunu özlemeyi

Bitti artık demeyi

Kolay mı sanıyorsun', 'Faili belli          Mağduru meçhul                   Lirik bir ağıttı yaşadığımız...                                 Bir destan değil…. Şim...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Doğan']::text[], 8.5, '{"poet":"Yavuz Doğan","poet_slug":"yavuz-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlı', 'delikanli-necmi-yildirim-m7akz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yırtılsa da yürek vurgunda,

Çıkacak su yüzüde,

Sağ ya da değil.

Yıkılsa da kocagenç gururundan,

Yürüyecek yine,

Ezik ya da değil.

Ve bu beden

Ayrılmadıkça ruhundan,

Hiç bir acı en büyük acı olmayacak...

(1992 Ankara)', 'Yırtılsa da yürek vurgunda, Çıkacak su yüzüde, Sağ ya da değil. Yıkılsa da kocagenç gururundan, Yürüyecek yine, Ezik ya da değil. Ve bu bede...', ARRAY['Türk Edebiyatı','Şiir','Necmi Yıldırım']::text[], 8.5, '{"poet":"Necmi Yıldırım","poet_slug":"necmi-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/delikanli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanın Resmi', 'vatanin-resmi-omer-avsar-7zhb2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazmak gelmiyor içimden

Halkim böylesine ezilirken

Niye bizim kaderimiz bu olsun

El oglu rahat hayatlari sürerken

Durmadan geliyor zam her sey ates pahasi

insanlarin agzinda bitmeyen umut duasi

öylesine buluyorlar bir lokma ekmek parasi

çiftçisinden emeklisine ayri bir yürek sizisi

Büyükler götürüyor vatan diye halkin gelecegini

polis dövüyor dur diyen memuru isciyi ögrencisini

herkez sinmis ve ezilmis duyuramiyorlar seslerini

geçiriyorlar bir daha gelmeyecek o güzel günlerini

umudu kesmek iyi degildir

ey allahim sen milletimi sevindir

bizi yönetenlere vicdan yerlestir

belki düzelir her sey kimbilir

            27/02/2001', 'Yazmak gelmiyor içimden Halkim böylesine ezilirken Niye bizim kaderimiz bu olsun El oglu rahat hayatlari sürerken Durmadan geliyor zam her s...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vatanin-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Nedir ki', 'hayat-nedir-ki-omer-avsar-q60p0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'beyni zorlar bu gel gitler

bir yanda bitmez didismeler

öte tarafda sicacik gülüsler

gerçekmi sahtemi bakan yüzler

oyun gibi geliyor bu dünya

iyilerle kötüler hep bir arada

anlamadan bitiyor hayat sonunda

bosuna ugras göremedikden sonra

ne için bunca zamandir yasananlar

fayda vermez beyhude aglamalar

dogruysan önemli degil hayatlar

nasil olsa perdeyi sensiz kapatacaklar', 'beyni zorlar bu gel gitler bir yanda bitmez didismeler öte tarafda sicacik gülüsler gerçekmi sahtemi bakan yüzler oyun gibi geliyor bu dünya...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-nedir-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ki!...', 'ki-hakki-yildirim-lbe04', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ecelim yakaladı beni bakışlarında;

Guzel gözlerine bakamam ki!...

Ben ağlarım suzulen gozyaşlarında,

Sen ağlama gozyaşına kıyamam ki!...

Uzakta bir bulut gibisin,sonsuz mavinin ustunde,

Yıldızlar gibisin;gecenin susunde,

Oturmus bakıyorsun,Ay''ın ustunde,

Uzatsam da ellerimi sana dokunamam ki!...', 'Ecelim yakaladı beni bakışlarında; Guzel gözlerine bakamam ki!... Ben ağlarım suzulen gozyaşlarında, Sen ağlama gozyaşına kıyamam ki!... Uza...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Yıldırım']::text[], 8.5, '{"poet":"Hakkı Yıldırım","poet_slug":"hakki-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Olmaz', 'haberin-olmaz-yavuz-dogan-ry8i0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gece ansızın rüyana girip

Bir ömür yaşarım haberin olmaz

Seninle bir güne bir ömür verip

Sevdana koşarım haberin olmaz

Yağmurum; güneşin ardından gelen

Ferhat''ım uğruna dağları delen

Belki bir mendilim yaşını silen

Derdine düşerim haberin olmaz

Bir şarkı olurum senin dilinde

Dikensiz bir gülüm belki elinde

Belki bir yağmurum bahar yelinde

Saçını okşarım haberin olmaz', 'Bir gece ansızın rüyana girip Bir ömür yaşarım haberin olmaz Seninle bir güne bir ömür verip Sevdana koşarım haberin olmaz Yağmurum; güneşin...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Doğan']::text[], 8.5, '{"poet":"Yavuz Doğan","poet_slug":"yavuz-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haberin-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek ve Ben', 'kelebek-ve-ben-ahmet-unal-cam-oregd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kelebek döner durur

  başımın üzerinde

Ne gelir,konar ellerime

          güvenipte

Ne gider uzaklara

          terkedipte.

 *       *       *

-Döneceksin,döneceksin

Terkedip gideceksin,sonunda

Bir ışığa kanıp ta.

Bilmeyeceksin;ışıkta ateş var

Geç olacak öğrendiğinde,ateş yakar.

 *       *       *

Gel,kelebek gel !..

Yüreğimdeki şefkat,ellerimdeyken

Ben dost,sen ışık ararken.

Sızlatma yüreğimi

Yakma kendini.

Beni mahzun etme

Dönüp dönüpte,gitme

Sen de terketme...', 'Bir kelebek döner durur   başımın üzerinde Ne gelir,konar ellerime           güvenipte Ne gider uzaklara           terkedipte.  *       *   ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kelebek-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Bilmedi', 'kimse-bilmedi-ahmet-unal-cam-poa7s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimizle küstük

   gözlerimizle barıştık

 Dilimiz yorgun

   kelimeler tükenmiş.

 Halay çektik,

   kalabalığa karıştık

 Bir an baktım ,

   elin elime değmiş.', 'Gözlerimizle küstük    gözlerimizle barıştık  Dilimiz yorgun    kelimeler tükenmiş.  Halay çektik,    kalabalığa karıştık  Bir an baktım ,  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kimse-bilmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-ahmet-unal-cam-bqq76', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep birşeylerin korkusu içimde

Her an bitecek gibi birşeyler

Yarım kalıverecek sanki tebessümler

Dudağıma konuverecek hüzün

Gidivereceksin gibi baharla,güzün.', 'Hep birşeylerin korkusu içimde Her an bitecek gibi birşeyler Yarım kalıverecek sanki tebessümler Dudağıma konuverecek hüzün Gidivereceksin g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/korkuyorum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşu', 'kosu-ahmet-unal-cam-4xmrs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuk bana gülümsedi,

Çıkarıp bir şeker verdim.

''-Kaç lira ?'' dedi

''-Yanaktan bir öpücük.''dedim.

   ödedi.

Koşan çocuklara takıldı gözü,

Boynu bükük fısıdadı;

   ''-koşalım mı?''

Gülümsedim''-Koşalım.''dedim.

Kucağıma aldım,

   koştum...koştum...

Koltuk değnekleri

   bizi bekledi...', 'Çocuk bana gülümsedi, Çıkarıp bir şeker verdim. ''-Kaç lira ?'' dedi ''-Yanaktan bir öpücük.''dedim.    ödedi. Koşan çocuklara takıldı gözü, Boy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kosu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maskeliler', 'maskeliler-ahmet-unal-cam-ousho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutsuzlara gülen maskeler dağıttım.

Herkes,''-Ne kadar neşelisin.''dedi.

Kimse anlamadı,

Bende de maske olduğunu...', 'Mutsuzlara gülen maskeler dağıttım. Herkes,''-Ne kadar neşelisin.''dedi. Kimse anlamadı, Bende de maske olduğunu......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/maskeliler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Sevgiliye', 'mechul-sevgiliye-ahmet-unal-cam-0zx3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bilmezsin

Şarkılarda seni dinlerim

Açtığım kapılarda

    seni ararım

      geçtiğim yollarda

         tozunu

      çiçeklerde dallarda

         kokunu

         ararım...

   *   *   *   *   *

Olmadığını bile bile

Eve dönüşlerimde

    her köşeye bakarım

Yine saklanmışsın diye

    ararım,ararım...

Yıllar var kî hep aynı sahne

Sen kaçarsın,ben hep ebe...

   *   *   *   *   *

''Elma'' dedim,''Erik'' dedim

Muz,şeftali,börülce...

Ne göründün,ne bir ses verdin

Yoruldum,tükendim pes artık

Çay içirdim

Hadi ! çık,gelsene...', 'Sen bilmezsin Şarkılarda seni dinlerim Açtığım kapılarda     seni ararım       geçtiğim yollarda          tozunu       çiçeklerde dallarda  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mechul-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sobe', 'sobe-ahmet-unal-cam-i7st8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutluluk !..               

   kaçma artık,           

 Sağım-solum           

   sobe !..', 'Mutluluk !..                   kaçma artık,             Sağım-solum               sobe !.....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sobe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Bu Halin', 'nedir-bu-halin-ahmet-unal-cam-vajtd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaldır başını aslanım,dik yürü

Gül bakayım,

Ne o öyle günlerdir halin

Bir ağlamadığın kaldı.

Sakın,sakın ağlama...

Şimdi üzüntüden kahroluşun

Sonradan pişmanlığa dönüşür,

''-Değer miydi o gözyaşına''dersin.

İnan,inan ki ismini bile unutursun.

Sen neler gördün be !..

Ne sevdalara katlandın.

Hele dayan,az kaldı ;

Bir gün bakacaksın ki

Onu düşünmeden bir saatin geçmiş

Şaşıracaksın.

Başka bir gün gelecek,

Birisi adını anacak yanında

''-Hiçte yabancı gelmiyor ismi,

Ama hatırlayamadım,kimdi ?''

Diyeceksin,sonra hatırlayacaksın

Onu ve bu günleri.

Kimse sebebini sormasın diye

Gizlice gülümseyeceksin...', 'Kaldır başını aslanım,dik yürü Gül bakayım, Ne o öyle günlerdir halin Bir ağlamadığın kaldı. Sakın,sakın ağlama... Şimdi üzüntüden kahroluşu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nedir-bu-halin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadar Zor ki', 'o-kadar-zor-ki-suna-say-68b3r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O kadar zor ki;

Bu kadar yakın ve bu kadar uzak olmak...

Elini uzattığında dokunabilecekken,

Araya görünmez duvarlar çekmek.

Fırtınada ona doğru savrulurken ve bütün benliğinle koşmak isterken,

Gücün tükenene kadar karşı koymak ve...

Sanki bir akşamüstü ılık bir meltem eşliğinde kumların üzerinde, 

Dalga seslerini dinlermişcesine dingin görünmeye çalışmak...

İmkansızlıklar arasında bir umut beklemek,

Çıkış yolu olmadığını bile bile boşluğa doğru koşmak

Yorulmak, tükenmek, bitmek ve,

Her gün, her dakika aynı acıyı tekrar yaşamak...

En kötüsü ise hiçbir şeyden emin olamamak,

Bilememek, sürekli soru işaretleriyle yaşamak.

Gözlerim, gözlerini yakaladığında gördüğüm sıcaklık,

Gözlerini kaçırdığı zaman ki utanç ve suçluluk,

Geçmiş özlemin mi, yoksa macera arayışının emaresi mi bilememek...', 'O kadar zor ki; Bu kadar yakın ve bu kadar uzak olmak... Elini uzattığında dokunabilecekken, Araya görünmez duvarlar çekmek. Fırtınada ona d...', ARRAY['Türk Edebiyatı','Şiir','Suna Say']::text[], 8.5, '{"poet":"Suna Say","poet_slug":"suna-say","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-kadar-zor-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Çare', 'son-care-dilek-demir-51fcc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benimle olabildiğin kadar varsin

Beklemiyorum daha fazlasini

Ama bende mutlu olmak istiyorum

Son çarem….

Seninle, seni sensiz yaşayabilmek olur

Marifettir hayatlari birleştirebilmek

Iki canin, bir bütün olmasiyidi hayalimdeki

Birlikte mutlu olmak istiyorum

Son çarem…..

Umutlari, hayalleri geride birakmak olur

Bana vermek istediğin kadar verebilirsin

Paylaşmakti sadece benim icin önemli olan

Mutlu olmak istiyorum

Son carem…..

Sensiz yaşamayi ögrenmek olur.

Amaclar, hayaller düsünceler farklidir

Hiçbir zaman küçümseyip ayiplama

Kendimle mutlu olmak istiyorum

Son care….

Mutluluğu kendimde bulmak olur

Kapali kutu içinde sevği çoktur

Sevği birlikte yaşanmali, saklamamali

Mutluluğu yaşamak istiyorum

Son carem…..

Belkide sensiz yaşamak olur.', 'Sen benimle olabildiğin kadar varsin Beklemiyorum daha fazlasini Ama bende mutlu olmak istiyorum Son çarem…. Seninle, seni sensiz yaşayabilm...', ARRAY['Türk Edebiyatı','Şiir','Dilek Demir']::text[], 8.5, '{"poet":"Dilek Demir","poet_slug":"dilek-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/son-care-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Kalacak Geriye', 'neler-kalacak-geriye-ahmet-unal-cam-444ro', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey güzel gözlü kız

Duydum ;

Çok övünürmüşsün

     güzelliğinle.

Doğru ;

Güzelsin bence de.

Ama esas olan

Kişiliğin yaptıkların.

Düşün ;

O güzel gözlerden,

         vücuttan,

Neler kalacak geriye ?

Bir kaç kemik sadece.

Gerisi böceklere yem,

     çiçeklere gübre.', 'Ey güzel gözlü kız Duydum ; Çok övünürmüşsün      güzelliğinle. Doğru ; Güzelsin bence de. Ama esas olan Kişiliğin yaptıkların. Düşün ; O gü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/neler-kalacak-geriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-ahmet-unal-cam-0y3kn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağaçlar yeşil,gök maviydi

Tazelenmişti umutlarım

Gözlerin,gözlerime çarpınca

İçim ürperir,seninle dolu

         düşler kurardım.

Sayende umutlarım yeşerdi,kök saldı

Senin bakışlarında da bir şeyler vardı.

Sevgi sandım sana yöneldim,oysa o gün...

O gün,kolunda başka biri vardı...', 'Ağaçlar yeşil,gök maviydi Tazelenmişti umutlarım Gözlerin,gözlerime çarpınca İçim ürperir,seninle dolu          düşler kurardım. Sayende umu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/o-gun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olan Oldu', 'olan-oldu-ahmet-unal-cam-hupky', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir goncayla bahar geçti

Bak yine gün,gün yaz oldu

Tebessümler başlar iken

Gönle şimdi hüzün doldu

Olan oldu,olan oldu 

Bahçeler hep viran oldu

Olan oldu,olan oldu       

Gönle şimdi hüzün doldu

                           (Nakarat)              

Mevsim yazdır,vakit akşam

vakit geçmez,günü saysam

İster idim mutlu olsam

Mutlulukta hayal oldu.

Rüzğarlar serin esiyor

Uzaktan yâr,yâr geliyor

neyleyim kî ,neyleyim kî

Bir gülüşü çok görüyor.

Yıldızlar gölge etmez kî

Viran yerde kuş ötmez kî

Yâre binbir sitem ettim

Kâr etmez kî,Kâr etmez kî', 'Bir goncayla bahar geçti Bak yine gün,gün yaz oldu Tebessümler başlar iken Gönle şimdi hüzün doldu Olan oldu,olan oldu  Bahçeler hep viran o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olan-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onunla', 'onunla-ahmet-unal-cam-ypzuv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onunla...

Havadan sudan konuşup,bir parkta yürümek

Üşüdüğünü gizleyip,ona ceketini vermek

Bir sıcak bakışla ısınmak

Gülüşlerinde,bulmak istediğini aramak

...ve bir gün

Sevginin karşılıksızlığını anlamak

Bir yaz günü aynı parkta ağlamak...', 'Onunla... Havadan sudan konuşup,bir parkta yürümek Üşüdüğünü gizleyip,ona ceketini vermek Bir sıcak bakışla ısınmak Gülüşlerinde,bulmak iste...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/onunla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otobüste', 'otobuste-ahmet-unal-cam-zv9us', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Otobüsümüz düzgün yollarda,

Sevda yolu engebeli.

Dalgın bakışlı güzel,

  ellerin yanında

Bilmiyor ki sevgimi,

  ne demeli !.', 'Otobüsümüz düzgün yollarda, Sevda yolu engebeli. Dalgın bakışlı güzel,   ellerin yanında Bilmiyor ki sevgimi,   ne demeli !....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otobuste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrendim', 'ogrendim-ahmet-unal-cam-vu9bp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidişin yıkmaz beni

Hayata gülerek

  bakmayı öğrendim ,

Eller bana gülmeden önce.

Senden sonra da

  gülümseyeceğim,

  mutluymuş gibi...', 'Gidişin yıkmaz beni Hayata gülerek   bakmayı öğrendim , Eller bana gülmeden önce. Senden sonra da   gülümseyeceğim,   mutluymuş gibi......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ogrendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Düşündüm', 'olumu-dusundum-ahmet-unal-cam-72xw3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Yaralı bir terörist)

Ölümü düşündüm

Şu bahar gününde

  fidanlara can gelirken.

Kanaryamı hatırladım

  elimde can verirken.

Ölümü düşündüm,

Kavak yellerim eserken.

Yaşamak böyle güzelken.

Ölüm''ü düşündüm

Cesedim sürükleniyor

  bir savaş meydanında

  düşmanlarım bir yanda

  dostlarım bir yanda ;

 ''Biz kazandık!.'' diyorlar

  Kaybeden ben''im...

Ölümü düşündüm,

Sevda dolu yüreğimde,

24 yaşımın gençliğinde.

Umutlarım nerede ?

Yarınlarım nerede ?

Hatıra kaldı umutlardan

Üç kurşun göğsümde.

Hazır değilim ölmeye,

Niyetliyim ;

  güzel günler görmeye

Niyetliyim ;

  sevmeye-sevilmeye.

Niyetliyim ;

 ''Yaşadım.''demeye.

Bana yaşanacak

  günler bırakın,

Çekin kurşunları

  yüreğimden çıkarın.

Penceremden bahar

  görülüyor,

parkta çocuklar

  oynuyor.

Kimse bilmiyor,

  ...kimse bilmiyor;

Yaşamayı çok seven biri

  ...burda ölüyor.

Çocuk olmak istiyorum anne,

Bütün nefretlerden azade.

Bana bir selam getir anne,

Bana bin selam getir anne;

Tüm sevgilerden.

Bana bir umut getir anne,

Bana bin umut getir anne;

Yaşanacak günlerden.', '(Yaralı bir terörist) Ölümü düşündüm Şu bahar gününde   fidanlara can gelirken. Kanaryamı hatırladım   elimde can verirken. Ölümü düşündüm, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/olumu-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce', 'once-ahmet-unal-cam-icn95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acı tebessümlere kanıp ta

Beni mutlu sananlar için

Gülmek isterdim doyasıya

İçim kan ağlamadan önce.

Çağlar yıkılırken içimde,

Ayağa kalktığımı sananlar için

Uzanmak isterdim göğe

Boşluğa düşmeden önce.

Beni dertsiz bilip te

Derdini dökenler için

Derman olmak isterdim

Verem olmadan önce.

Elini ellerime koyup ta

Dostça sevenler için

Kalbimi vermek isterdim

Bir hayırsız almadan önce.', 'Acı tebessümlere kanıp ta Beni mutlu sananlar için Gülmek isterdim doyasıya İçim kan ağlamadan önce. Çağlar yıkılırken içimde, Ayağa kalktığ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/once-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemle', 'ozlemle-ahmet-unal-cam-2vbqd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensizliği

 vedalaşırken değil

 eve dönünce anladım.

Her açtığım kapıda ümitle

 gülen yüzünü aradım.

Bu seninle ilk ayrılışımız,

Dilerim son olur

  hayat arkadaşım.', 'Sensizliği  vedalaşırken değil  eve dönünce anladım. Her açtığım kapıda ümitle  gülen yüzünü aradım. Bu seninle ilk ayrılışımız, Dilerim son...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlemle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Romantiklikten Anlayan Kalmadı', 'romantiklikten-anlayan-kalmadi-ahmet-unal-cam-frbsg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzğar feryadımı,

 Deniz gözyaşımı,

 Yare götürsün''dedim.

 Münasabetsizin biri;

''Posta çok mu pahalı?''

                dedi.', 'Rüzğar feryadımı,  Deniz gözyaşımı,  Yare götürsün''dedim.  Münasabetsizin biri; ''Posta çok mu pahalı?''                 dedi....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/romantiklikten-anlayan-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-ahmet-unal-cam-1nyib', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün olup uçmuşum,

  kanatlarında kuşların.

Gün olup konmuşum,

   ortasına ufukların.

Bir de baktım vurulmuşum

  takılmışım ağına aşkının

  çırpınıp durmuşum.

      *        *

Ne kuşum,ne de yıldız

  göklerdeki.

Ben bir damla sevgi

  kalplerdeki.

Ne çare unutulmuşum

Haberin yok ama

Kalbine oturmuşum

Orda yalnızlığı bulmuşum.

Öyle bir konuşmuşum...

Ne o beni duymuş

Ne ben onu duymuşum

Sonunda susmuşum,

Uyanmış...

Yine sensiz olmuşum.', 'Gün olup uçmuşum,   kanatlarında kuşların. Gün olup konmuşum,    ortasına ufukların. Bir de baktım vurulmuşum   takılmışım ağına aşkının   ç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruya-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçmece Bu İnsanlar Seçmece', 'secmece-bu-i-nsanlar-secmece-ahmet-unal-cam-9st1k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi toplarla,tüfeklerle öldürülür,

Kimi takma kalplerle yaşatılır,

Kimi milyonluk perhizle,sporla

      sağlıklı yaşam peşinde

Kimi kollarımdan ince belleriyle

      Afrika''da ölmekte.', 'Kimi toplarla,tüfeklerle öldürülür, Kimi takma kalplerle yaşatılır, Kimi milyonluk perhizle,sporla       sağlıklı yaşam peşinde Kimi kolları...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/secmece-bu-insanlar-secmece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Versem', 'selam-versem-ahmet-unal-cam-zumso', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün

 yürürken Kızılayda

 güneşe baktım,kuşlara

 gelip geçenlere baktım.

Sonra

 selam verdim

  içten bir gülümseyişle

 yıllardır yüzlerine taktıkları

 çirkin asıklık düşecek diye.

Almadılar da selamımı

 bir kuş aldı

 gülerek,çoşkuyla', 'Bir gün  yürürken Kızılayda  güneşe baktım,kuşlara  gelip geçenlere baktım. Sonra  selam verdim   içten bir gülümseyişle  yıllardır yüzlerin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/selam-versem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ahmet-unal-cam-bqxwt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Sen'' diye

Şiirler yazdığım,övdüğüm

Hiçbiriniz değilsiniz.

Belki de hepinizsiniz

         güzeller !..

Hepinizden bir parçayı

         seviyorum

Sevgimin erişilmezliği,

  sonun,hep mutsuzluk olması

  hep bu yüzden.

Hepiniz varsınız,

''Sen'' yoksun...', '''Sen'' diye Şiirler yazdığım,övdüğüm Hiçbiriniz değilsiniz. Belki de hepinizsiniz          güzeller !.. Hepinizden bir parçayı          seviy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-ahmet-unal-cam-u49zt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yerlerde yine

Çocuklar gülecek,ağlayacak

İnsanlar koşuşturacak,yaşayacak

Güneş doğacak,güneş batacak

Rüzğarlar esecek,yağmurlar yağacak.

Tahta kapımız yine gıcırdayacak

Ellerim akşamları yine üşüyecek.

Fakat sen...sen artık

Bunları duymayacaksın,görmeyeceksin.

Akşamları ellerinle ellerimi ısıtmayacaksın

...bazıları senin için ''öldü''diyor,

Onlar hangimizin öldüğünü bilmiyor...', 'Bir yerlerde yine Çocuklar gülecek,ağlayacak İnsanlar koşuşturacak,yaşayacak Güneş doğacak,güneş batacak Rüzğarlar esecek,yağmurlar yağacak....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-sonra-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Uzaklarda', 'senden-uzaklarda-ahmet-unal-cam-s7l16', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulutsuz akşamlarda

Bir yağmur yağar gözlerimden,

Düşer ;

    gözlerim ufuklara,

    gözyaşım yerlere...

    ta... içimden.

Hüzün fırtınası başlar.

Peşpeşe şimşekler çakar,

    düşer yıldırımlar.

Düşer yıldırımlar,

    paramparça olur gönlüm.

Düşünürüm ;

    sen gittin,ben öldüm.', 'Bulutsuz akşamlarda Bir yağmur yağar gözlerimden, Düşer ;     gözlerim ufuklara,     gözyaşım yerlere...     ta... içimden. Hüzün fırtınası ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senden-uzaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Giderken', 'sen-giderken-ahmet-unal-cam-kvp02', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'El sallayışlardaki hüzünü

   öğrendim artık

   sen giderken

Biliyorum şimdi

   tren sesi

   neden ağlatır insanı

Öğrendim ayrılığı

Öğrendim acıyı

   sen giderken

Sen giderken

   çaresizliği öğrendim

   öğrendim akşamları

   ve öğrendim insan

   niçin bakar ufuklara

   ağlamaklı.

Sen giderken

   geldi hüzün

Sen giderken

   geldi dert

   geldi acılar

Ayrılığı öğrendim ;

Yamanmış...', 'El sallayışlardaki hüzünü    öğrendim artık    sen giderken Biliyorum şimdi    tren sesi    neden ağlatır insanı Öğrendim ayrılığı Öğrendim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-giderken-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gülümsersin', 'sen-gulumsersin-ahmet-unal-cam-maz5v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen

Bunalırım;hep dert,hep kahır.

Ne olacak bu halim derim,

Aralanır düşlerim ;

Sen gülümsersin.

Bir tren çalar düdüğünü

İçim kavrulur

Bir kuş penceremden uçar-gider

Yalnızlık doluşur odama.

Tam pes edecekken

Bir köşeden

Sen gülümsersin.', 'Bazen Bunalırım;hep dert,hep kahır. Ne olacak bu halim derim, Aralanır düşlerim ; Sen gülümsersin. Bir tren çalar düdüğünü İçim kavrulur Bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-gulumsersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Olsun', 'gunesin-olsun-cesar-fleischler-zdd6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşin olsun gönlünde 

Kar bile yağsa 

Ya da fırtına olsa. 

Gök bulutlarla 

Dünya kavgayla dolsa 

Güneşin olsun gönlünde 

O zaman gelsin ne gelirse 

Doldurur ışıklarla 

En karanlık gününü 

Bir şarkın olsun gönlünde 

Sevinçli ezgilerle 

Seni günlük tasalar boğsa bile 

Bir şarkın olsun dudaklarında 

O zaman gelsin ne gelirse 

Yardım eder atlatmaya 

En yalnız gününü 

Başkaları içinde bir diyeceğin olsun 

Tasada ve bunalımda 

Ve seni mutlu edecek her şeyi 

Söyle onlara da 

Bir şarkın olsun dudaklarında 

Yitirme sakın cesaretini 

Güneşin olsun gönlünde 

Ve her şey iyi olacak', 'Güneşin olsun gönlünde  Kar bile yağsa  Ya da fırtına olsa.  Gök bulutlarla  Dünya kavgayla dolsa  Güneşin olsun gönlünde  O zaman gelsin ne...', ARRAY['Türk Edebiyatı','Şiir','Cesar Fleischler']::text[], 8.5, '{"poet":"Cesar Fleischler","poet_slug":"cesar-fleischler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gunesin-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aramak', 'seni-aramak-ahmet-unal-cam-xp3s4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gün,her an

   dalıp dalıp geliyorum sana

Tam uzanmış tutacakken

   kaçırıyorsun ellerini.

Her gün,her an

   dalıp dalıp geliyorum sana

Çöllerde buluyorum bazen,

   bırakıp gidiyorsun beni,

   aç-susuz yine düşüyorum peşine.

Bir deniz kenarında arıyorum seni,

   kumsallarda buluyorum

          ayak izlerini.

   sen siliyor,kaçıyorsun yine.

   rüzğarlara tutunup geliyorum,

                  yetişemiyorum.

Bir köye varıyorum,

   akşam üstü,

   yorgun argın.

Seni soruyorum

  ''-Henüz gitti'' diyorlar

Tekrar koşuyorum

   ayaklarım parça parça,

   kanıyor.

Bir dağ kulübesinde

          duyuyorum kokunu,

Kar başlamış,fırtınası bir yandan.

Seni bulamamanın korkusu,

   yüreğimde çırpınırken,

   atıyorum kendimi içeri,

   bağırıyorum ismini...ses yok.

Şöminede sönmekte bir ateş,

Bir pencere çarpıp duruyor pervaza,

   koşup bakıyorum;

Pencerenin önünde

          ayak izlerin yine,

Yine benden uzağa götürmüş seni.

Koşarak çıkıyorum dışarı,

İzlerini takip ede ede

   bir uçuruma varıyorum.

Sen geçmişsindir diye,

          geçmek istiyorum

          ...başaramıyorum

   kayıyor ayaklarım,ellerim

   düşüyorum...düşüyorum...

Düşüyorum;ismini haykırarak.

Uçurumun dibinde görüyorum seni,

   kavuştuğuma sevinemeden

          ...ölüyorum.', 'Her gün,her an    dalıp dalıp geliyorum sana Tam uzanmış tutacakken    kaçırıyorsun ellerini. Her gün,her an    dalıp dalıp geliyorum sana Ç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/seni-aramak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serap Oldu', 'serap-oldu-ahmet-unal-cam-nk26k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düştüm derde

Halim bîtap oldu

Evim yurdum harap oldu

''Yârim,yârim''dediğim

Bende iken serap oldu.', 'Düştüm derde Halim bîtap oldu Evim yurdum harap oldu ''Yârim,yârim''dediğim Bende iken serap oldu....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/serap-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(Bosna Şiirleri) Sobe', 'bosna-siirleri-sobe-ahmet-unal-cam-7llgm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bosna''da,kurşunlar çocukları

  sırtından ''Sobe''liyor...', 'Bosna''da,kurşunlar çocukları   sırtından ''Sobe''liyor......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bosna-siirleri-sobe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Hüznü', 'sonbahar-huznu-ahmet-unal-cam-hvxjf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birşeyler var bu akşamlarda,

Birşeyler var bu sabahlarda,

Birşeyler var sonbaharlarda,

    tutsan tutulmaz

    kovsan gitmez.

  yüreğimi ezen birşeyler var.

Birşeyler var,

    dilimi dolaştıran,

    elimi tutan,

    boğazımı sıkan.

  ağlamak zor,

  gülmek imkansız.

Birşeyler var,

  rüzgar başka esiyor.

Birşeyler,

  güneş başka batıyor.

Var var,birşeyler var,

  herkes biliyor,

    söyleyemiyor.', 'Birşeyler var bu akşamlarda, Birşeyler var bu sabahlarda, Birşeyler var sonbaharlarda,     tutsan tutulmaz     kovsan gitmez.   yüreğimi eze...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sonbahar-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Değil', 'son-degil-ahmet-unal-cam-kd1j2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çalışı son olmayacak

  kapımı mutsuzluğun

Her ayrılıkta

  bulur beni

Ne kadar kaçmak istesem

  kırarcasına çalar kapımı

Mutlaka gelir yanıbaşıma

  sımsıkı sarar beni', 'Çalışı son olmayacak   kapımı mutsuzluğun Her ayrılıkta   bulur beni Ne kadar kaçmak istesem   kırarcasına çalar kapımı Mutlaka gelir yanıba...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-degil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürpriz', 'surpriz-ahmet-unal-cam-fw6f3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Depremler,seller olmadı,

Çakmadı şimşekler,şatafatlı.

Sabah yine güneş doğdu,

Gidişin sürpriz oldu...', 'Depremler,seller olmadı, Çakmadı şimşekler,şatafatlı. Sabah yine güneş doğdu, Gidişin sürpriz oldu......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/surpriz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-ahmet-unal-cam-y1w34', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şair,duygu denizinden bir avuç alır,

Yollar geçer,dağlar aşar çöldekine ulaştırır.

Şair sonbaharda ağaçları çiçekli görebilir,

Gözlerini kapatıp,satırlarda bir ömür yaşayabilir.

Şair,duyguları yoğurur,yazar satır satır

Şair doğar,yaşar,ölür  adı yadiğar kalır.', 'Şair,duygu denizinden bir avuç alır, Yollar geçer,dağlar aşar çöldekine ulaştırır. Şair sonbaharda ağaçları çiçekli görebilir, Gözlerini kap...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirsiz Bir Akşam', 'siirsiz-bir-aksam-ahmet-unal-cam-cd17v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne gökte ay gülümsüyor

Ne deniz kokusu havada.

Ne de hasretin içimi yakıyor.

İşte şiirsiz bir akşam daha.', 'Ne gökte ay gülümsüyor Ne deniz kokusu havada. Ne de hasretin içimi yakıyor. İşte şiirsiz bir akşam daha....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siirsiz-bir-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş Dediğin', 'arkadas-dedigin-nurgun-salli-zx8xu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen gökyüzündeki bir yıldızsın,

Karanlık gecemi aydınlatan.

Hep yanımdaydın içindeki sevgiyle,

Kimsenin göremediği gözyaşlarımı,

Ve anlam veremediklerini gördün içimde.

İşte senin gibi olmalı arkadaş dediğin.

Kimi zaman ben anlattım,

Sen dinledin...

Bazen sen anlattın,

Dinleyen bendim.

Öyle bir temel attık ki,

Bitmeyen bir dostluk gelişti,

Sen gibi olmalı arkadaş dediğin.

Sevecen dilin, o tatlı yüzün,

Hatırlamıyorum, hiç tartışmadık.

Çünkü saygı vardı bizde,

Anlayış ve sevgi vardı temelde,

Biliyorum ki çok uzaklara da gitsen, 

Sen hep benim yanımdasın,

Senin gibi olmalı arkadaş dediğin.

Nasıl da anlarsın dumanlı düşüncelerimi,

Başımda esen kavak yellerini,

Sen benim gibisin, bensin.

Bir kelimemden çözersin herşeyimi,

Daha ne isteyebilirim ki,

Şu dostluk kervanından,

Sen benim herşeyimsin,

Tek dostum, canımsın.

Seval gibi olmalı arkadaş dediğin.

(Seval''e sevgilerle)', 'Bazen gökyüzündeki bir yıldızsın, Karanlık gecemi aydınlatan. Hep yanımdaydın içindeki sevgiyle, Kimsenin göremediği gözyaşlarımı, Ve anlam ...', ARRAY['Türk Edebiyatı','Şiir','Nurgün Şallı']::text[], 8.5, '{"poet":"Nurgün Şallı","poet_slug":"nurgun-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/arkadas-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Aykırı Bir Çocuk', 'i-ki-aykiri-bir-cocuk-onder-karadag-gr996', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İki aykırı bir çocuktuk

sen ölümden korkuyordun

bense ayrılıklardan

Hiçleştik korkularda.

Sen avuçladın baharı

Kırağı vurdu dallarına.

		

Ben dinginliğinde, günün

Karlar tozdu saç’aklarımda.

Sen güzel bir çok çocuk,

bense  deli bir az ihtiyar

Çoklaştık  acılarda.', 'İki aykırı bir çocuktuk sen ölümden korkuyordun bense ayrılıklardan Hiçleştik korkularda. Sen avuçladın baharı Kırağı vurdu dallarına. 		 Be...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iki-aykiri-bir-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-deral-gasgar-nfkt4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zaman akıp gidiyor

sen yoksun

ben varım yalnız

başım dumanlı 

yıkık yorgun çaresiz

dün gece 

sen belirdin

ay ışığında 

yıldızlar göz kırptı gece boyunca

tan yeri ağarmadan önce

uyandım

yalnızdım

sonra sahilde  martılar

şehir bomboş

ve hamallar yanıbaşım da

gülümsüyordu ortadaki zayıf olanı

ben gülümseyemedim

çünkü

sen yoktun 

ve

ben yalnızdım.

25 mart 2000 Yenibosna/İstanbul', 'zaman akıp gidiyor sen yoksun ben varım yalnız başım dumanlı  yıkık yorgun çaresiz dün gece  sen belirdin ay ışığında  yıldızlar göz kırptı ...', ARRAY['Türk Edebiyatı','Şiir','Deral Gasgar']::text[], 8.5, '{"poet":"Deral Gasgar","poet_slug":"deral-gasgar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizlik-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-sair-kyo-vrvho', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yoklugunda kediler büyüttüm,

Karıncalar besledim , toprağı sevdim,

Boyumu aştı,inan,sarmaşıklar.

Sevmeli karşılık beklemeksizin,derdin

Kuşca,çiçekçe,böcekçe;yürekten

Kelebek olmalı ruhun;uçmalı.

Bozmalı çirkinliklerin yuvalarını

Sarı paptyalar tomurcuklandı bahcede,

Sorma,ah görsen ne denli şirin!

Sana benzeyecekler,eminim,büyüdükçe.

İkimiz için gez,gör,araştır,öğren

İyi bak kendine,düşünme beni

Çalışıyorum işte 

Gelecek güzel günler için.

Sınsuz gelmeden yola çık emi?

Uçur önün sıra bir ak güvercin

Bana yeni yeni öyküler getir...', 'Yoklugunda kediler büyüttüm, Karıncalar besledim , toprağı sevdim, Boyumu aştı,inan,sarmaşıklar. Sevmeli karşılık beklemeksizin,derdin Kuşca...', ARRAY['Türk Edebiyatı','Şiir','Şair Kyo']::text[], 8.5, '{"poet":"Şair Kyo","poet_slug":"sair-kyo","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mektup-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgünüm Leyla', 'uzgunum-leyla-sair-kyo-kwz57', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben o bildigin mecnun

Değilim! 

Üzğünüm! 

zamanı aşıp gelecek, sana

Mecnun ben degilim 

Ve sende üzgünsün

Çünkü sende o leyla değilsin

Aradığım sen degilsin

ben yokun yoklugunda olanı, arıyorum! 

O sen degilsin!', 'Ben o bildigin mecnun Değilim!  Üzğünüm!  zamanı aşıp gelecek, sana Mecnun ben degilim  Ve sende üzgünsün Çünkü sende o leyla değilsin Aradı...', ARRAY['Türk Edebiyatı','Şiir','Şair Kyo']::text[], 8.5, '{"poet":"Şair Kyo","poet_slug":"sair-kyo","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uzgunum-leyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-deral-baran-26ybw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'günaydın,

oysa yeni başlamıştı 

kayıtlar

sorgucularım sıramı beklemeden 

yureğimin titrekliğini anlamışlardı

ne zaman elimi sol göğsüme atsam

sen vardın

oda karanlık bir dehlize açılıyordu 

sorgucular beni

bende seni bekliyordum

umutsuzca

ne vakit suçsuzluğumu

anlayacaklardı

ben loş bir lambanın altındayım

sol göğsümde sen

insan olmanın cezası 

bu olmamalıydı diye düşünüyorum

düşünde ben mi vardım bilinmez

kayıtlar yeni başlamıştı

sırada ben yoktum

sırada sen yoktun

sıralar ikiye ayrılmıştı

biz ve onlar

kimbilir kaç kere yanyana çarpışmıştık

cephenin ön safında

aslında hepimiz birdik

bizi biz ve onlar diye ayırmışlardı

sogucular sıra mı beklemeden

karar vermişlerdi

ve kayıtlara şöyle bir not düşülmüş

bizde böyle bir kayıt yok', 'günaydın, oysa yeni başlamıştı  kayıtlar sorgucularım sıramı beklemeden  yureğimin titrekliğini anlamışlardı ne zaman elimi sol göğsüme atsa...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gunaydin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-deral-baran-2cf94', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ansız gidişlerin

ne yürek dayanır

ne hüzünlü bir bakış

bir el sallamak isterim ardından

ve kayboluşun

dudaklarımdan dökülemeden

yüreğime akan anlamsız bir temessüm

ayın doğuşu 

ve ansızın kayboluşu

geride bıraktığın

örselenmiş 

bir yürek

yalnız bir hayat

masada bir bardak su

yüreğimdeki fırtınaların koptuğu an

ansızın gidişlerin

ve benim yalnızlığım

paylaştığım kitaplar

mum ışığında

geçen zamanlar

gidişlerin 

bakmayışın

gözlerindeki anlamsız bakışın

arkana bakmadan sessizce gidişin

geride bırakdığına aldırmayışın

dudaklarındaki titreyiş

kısacık bir bekleyiş

ve

bilinmeyene yeniden kayboluş', 'ansız gidişlerin ne yürek dayanır ne hüzünlü bir bakış bir el sallamak isterim ardından ve kayboluşun dudaklarımdan dökülemeden yüreğime aka...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/huzun-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamer''e', 'tamer-e-deral-baran-jgaqr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susmak ne kadar kolay

Ne kadar acıdır gerçekler

Yalnız sen varsın 

Ön cephede

Olsun ,ya dilin olmasaydı

Ya yürümeseydin zalimlerin üstüne

Kimbilir kaç madalya aldın

Susarken geçen zamanı

Onurları vardı

Başları dikti

Sevdalıydılar delicesine

Bırakıp gitmek mi?

Asla!

Bana sorarsan yiğit

Sen kazanacan

Bu mücadeleyi

Meydanda leş kargaları

Gölge oyunu var

Şişirilmiş bedenler

Ortalıkta gezerler

Sen kazanacan ey dost

Bunda şüphe bekleme

30 Nisan 1999-

Sefaköy-ist', 'Susmak ne kadar kolay Ne kadar acıdır gerçekler Yalnız sen varsın  Ön cephede Olsun ,ya dilin olmasaydı Ya yürümeseydin zalimlerin üstüne Ki...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tamer-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-deral-baran-xmjue', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çocuk var içimde 

Yüreği hızla çarpar

Suskun bakışları var

Elinden değil yar!

Bazen ağlar...

Bir çocuk var içimde

Deli dolu bir adam

Sevda türküleri var

Tüter her yanı yanar

Hep yalnız 

Hep gaddar

Hep seni seni anar

Yüreğinin en pak yerinde

Sevdamsın eylül akaşamlarında

Bir sigara dumanında

Bazen göz yaşlarımda bir damla

İnan hep seni anar

Hep seni sorar

Sevdam çağlayanlar gibidir

Deli dolu o adam

Dedim ya gaddar mı gaddar

Yine de o çocuk bir sevda büyüttü

Gönül yamçlarında 

Ne senin gücün yeter

Zalimin zulmü

Büyüyüp yeşerecek 

İnan benim bir tanem

Ah birde konuşsa

Daha güzel olacak

Sefaköy-İSTANBUL

30 Nisan 1999', 'Bir çocuk var içimde  Yüreği hızla çarpar Suskun bakışları var Elinden değil yar! Bazen ağlar... Bir çocuk var içimde Deli dolu bir adam Sev...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevdam-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim', 'benim-deral-baran-s6bks', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benim 

kapıda kaldım

herzaman ki gibi

ne zaman sana dönsem

yüreğim burkulur

kapıda kalırım

elim hep sana açık

yüreğim tetikte 

sana gelirim

hep sana

gece gündüz fark etmez

benim görevim bu

sana gelmek

ama

hep kapıda kalırım

ve

bir gün kapı açık

yüreğim ürkek ceylanlar gibi

sana geldim

ve 

kapı açık

ama 

sen yoksun

25 mart 2000 Yenibosna/İstanbul', 'benim  kapıda kaldım herzaman ki gibi ne zaman sana dönsem yüreğim burkulur kapıda kalırım elim hep sana açık yüreğim tetikte  sana gelirim ...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığı', 'ay-isigi-deral-baran-f51zs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yine bana yaslan ay ışığında

başın göğsümde nefes al

elini ellerimle kenetle

öylece duralım

şafak sökene dek

İst.', 'yine bana yaslan ay ışığında başın göğsümde nefes al elini ellerimle kenetle öylece duralım şafak sökene dek İst....', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ay-isigi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-deral-baran-9ywbe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşün

Kurşun gibi bir bulut üzerinde dolaşıyor

gece boyunca.

düşün.

ayaklarında tonlarca ağırlıkta

gümüş kelepçeler.

düşün.

bütün yeryüzü kaygan bir buz parçası.

düşün.

ben uykuya tutsak bir halde

düşün.

yongunluk büker boynumu.

düşün.

sokaklar açları oynuyor

uzun metrajlı bir filmde

düşün.

genç bir adamı.

sadece bir somun alacak kadar

filmdeki rolü.

düşün.

başrol yaşam çizgisini

ve..

düşün...

düşünebildiğin kadar

insanlık tarihini.

25.04.2001

İst', 'Düşün Kurşun gibi bir bulut üzerinde dolaşıyor gece boyunca. düşün. ayaklarında tonlarca ağırlıkta gümüş kelepçeler. düşün. bütün yeryüzü ka...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dusun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam', 'adam-murat-akgoz-xg86e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adam var...

Yanarcasına 

Kelime oyunları 

Oynuyor.

Su içmeyecek biliyorum...', 'Adam var... Yanarcasına  Kelime oyunları  Oynuyor. Su içmeyecek biliyorum......', ARRAY['Türk Edebiyatı','Şiir','Murat Akgöz']::text[], 8.5, '{"poet":"Murat Akgöz","poet_slug":"murat-akgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/adam-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunalma', 'bunalma-murat-akgoz-xt5c0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız kalmış bir parça düş...

Adımlarıyla ıslak,

Yürüyor 

İkiçeşmelikten aşağıya.

Güneşten mi 

Bilmiyorum ama cayır cayır...

Basmaneye geldiğinde,

O da tükenmişliği sezdi galiba.

Sanki yol bitmiyor.

Yol boyunca tükenmişlik...', 'Yalnız kalmış bir parça düş... Adımlarıyla ıslak, Yürüyor  İkiçeşmelikten aşağıya. Güneşten mi  Bilmiyorum ama cayır cayır... Basmaneye geld...', ARRAY['Türk Edebiyatı','Şiir','Murat Akgöz']::text[], 8.5, '{"poet":"Murat Akgöz","poet_slug":"murat-akgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bunalma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-deral-baran-64jpf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana şiir seçiyorum

usulca 

gerdanına 

asarak.

biraz uzun

ve

devrik kullanırım

cümleleri,

ki;

sarsın tüm bedenini

ben gibi.

13 nisan 2001 

İst', 'Sana şiir seçiyorum usulca  gerdanına  asarak. biraz uzun ve devrik kullanırım cümleleri, ki; sarsın tüm bedenini ben gibi. 13 nisan 2001  İ...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimelerin Yetişemediği Yerde Boğulan Çocuk', 'kelimelerin-yetisemedigi-yerde-bogulan-cocuk-murat-akgoz-3y5xy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen!

Gözlerinde 

Hangi denizi saklıyorsun çocuk?

Ağlayamıyorsun yine...

Sen de Kızkulesi''ndesin.

Kendi martına bakıyorsun.

O martı ki; 

Seni Kızkulesi''ne taşıyandı.

Şimdi dönüp bakmıyor bile... 

O seni hala kanadında sanıyor.

Sense yüzme bilmeden 

Düşmüşsün gözlerindeki denize...

Kelimelerin yetişemediği yerdesin çocuk! 

Korkma, 

Birgün boğulmayı da öğrenirsin...', 'Sen! Gözlerinde  Hangi denizi saklıyorsun çocuk? Ağlayamıyorsun yine... Sen de Kızkulesi''ndesin. Kendi martına bakıyorsun. O martı ki;  Seni...', ARRAY['Türk Edebiyatı','Şiir','Murat Akgöz']::text[], 8.5, '{"poet":"Murat Akgöz","poet_slug":"murat-akgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kelimelerin-yetisemedigi-yerde-bogulan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-deral-baran-nct0q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor İstanbul''a

ıslandı tüm şehir

sessizce.

insanlar sığınacak yer aradı

duvar diplerinde.

gemiler heyecanla

son yolcularını

beklerken,

kimse farkında değildi.

ben vardım

sen vardın

martılar vardı orta yerde.

İstanbul''a yağmur yağıyordu

sessizce..

13 nisan 2001

İst', 'Yağmur yağıyor İstanbul''a ıslandı tüm şehir sessizce. insanlar sığınacak yer aradı duvar diplerinde. gemiler heyecanla son yolcularını bekle...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir', 'i-zmir-bahadir-bangi-r4ff6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kordon''da gezmek 

Nedir bilirmisin? 

Karşıyaka''da sevmek

Nedir bilir misin? 

Yamanlar'' da  hava almak

Sokaklarda top oynamak

Nedir bilir misin

Sevgilinle pasaporta gidip güneşe bakmak

Karataşta bisiklete binmek

Nedir bilir misin

Menemende ovalarda gezerken erik toplamak

Karşıyakada çarşıda gezerken alışveriş yapmak

Nedir bilir misin? 

Bilemezsin.... Çünkü İzmir''li değilsin...', 'Kordon''da gezmek  Nedir bilirmisin?  Karşıyaka''da sevmek Nedir bilir misin?  Yamanlar'' da  hava almak Sokaklarda top oynamak Nedir bilir mis...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Bangı']::text[], 8.5, '{"poet":"Bahadır Bangı","poet_slug":"bahadir-bangi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/izmir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-bora-zihni-iwyxd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gündüzden kalan son ışıklardan sonra 

Gel sevgilim.

Tutuşmay hazır yatağımıza,

Aşka susayan,

Hasretle bekleyen geceye,

Gecemize gel sevgilim.', 'Gündüzden kalan son ışıklardan sonra  Gel sevgilim. Tutuşmay hazır yatağımıza, Aşka susayan, Hasretle bekleyen geceye, Gecemize gel sevgilim...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/davet-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-bora-zihni-mihf3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir hüzünle doluyorsun içime.

Uçuyorsun serçe gibi avucumun içerisinden.

Ardından bakıyorum kanat çırpıp

Başka daldaki yuvana konuşuna.

Sonra, sonrası boş kalan eller,

Gökyüzüne ağlayan gözler,hasret ve hüzün.

Bir hüzünle doluyorsun içime

Gözlerini her  son görüşümden sonra.', 'Bir hüzünle doluyorsun içime. Uçuyorsun serçe gibi avucumun içerisinden. Ardından bakıyorum kanat çırpıp Başka daldaki yuvana konuşuna. Sonr...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/huzun-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret Ediyorum Kendimden', 'nefret-ediyorum-kendimden-fevzi-dursun-icdr1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanları üzdüğüm! ! ! ! 

                      Hele de 

                      beni sevenleri 

                      üzdüğüm

Doğunca annemin

çiğ sütünü emdiğim için! ! ! 

               Bazen doğaya, çiçeklere, 

               Kır çiçeklerine rağmen, 

               sinirli olduğum 

               ve insanları kırdığım, 

               başkalarına göre, 

               bireysel düşündüğüm için, 

               Nadirde olsa küçük yalanları, 

               Söyleyebilmiş olduğum için, 

Bunca kötülüğe rağmen, 

nefes aldığım için! ! ! 

               En önemlisi de, 

                ne olursa olsun, 

                insanları sevmekten! ! 

               Kendimi alıkoyamadığım için.         

Ama yinede, 

Her zaman

Üzülenin ben olduğum için', 'İnsanları üzdüğüm! ! ! !                        Hele de                        beni sevenleri                        üzdüğüm Doğunca annemin...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Dursun']::text[], 8.5, '{"poet":"Fevzi Dursun","poet_slug":"fevzi-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nefret-ediyorum-kendimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamı Anlamak', 'yasami-anlamak-fevzi-dursun-1a491', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acıya, 

Korku Ve Kokuya

Rağmen Yaşamak! 

Can Çekişirken

Hiç Ölmemeyi

Kurmak, Gibidir Yaşamak! 

Binlerce İnsana

İnat Yalnızlığı

Hissedebilmektir. 

Yaşamak! ! .', 'Acıya,  Korku Ve Kokuya Rağmen Yaşamak!  Can Çekişirken Hiç Ölmemeyi Kurmak, Gibidir Yaşamak!  Binlerce İnsana İnat Yalnızlığı Hissedebilmek...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Dursun']::text[], 8.5, '{"poet":"Fevzi Dursun","poet_slug":"fevzi-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasami-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen Diyorum ki...', 'bazen-diyorum-ki-muge-usul-vmukd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen diyorum

Gitmeli buralardan

Alıp başını

Neresi olursa farketmez

Zaten mekan değil önemli olan

Zaman da hükümsüz kalır

Kuş uçmaz kervan geçmez

Deniz,güneş,hava yeter

Bir de çiçekler olmalı

Dalında arkadaşlık etmeli bana

Geceleri de akşam sefaları

Kaynağından içmeliyim suyu

Buz gibi,doyasıya,kana kana

Bazen diyorum

Gitmeli oralara

Gitmeli ama...', 'Bazen diyorum Gitmeli buralardan Alıp başını Neresi olursa farketmez Zaten mekan değil önemli olan Zaman da hükümsüz kalır Kuş uçmaz kervan ...', ARRAY['Türk Edebiyatı','Şiir','Müge Usul']::text[], 8.5, '{"poet":"Müge Usul","poet_slug":"muge-usul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bazen-diyorum-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskız', 'eskiz-gamze-ozer-yq1hu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her düş

Bir yontudur

Kendi göğüne çizdiğin

At ölülerisiniz hepiniz

Denize dökülen küçük ırmaklarında 

Gecenin', 'Her düş Bir yontudur Kendi göğüne çizdiğin At ölülerisiniz hepiniz Denize dökülen küçük ırmaklarında  Gecenin...', ARRAY['Türk Edebiyatı','Şiir','Gamze Özer']::text[], 8.5, '{"poet":"Gamze Özer","poet_slug":"gamze-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/eskiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağ(ı)rışım', 'cag-i-risim-gamze-ozer-4u9o6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arşe

Küstüğü bestenin sırrını çaldı

Ve 

Virtüözün usul parmakları

Kanadı birden

Ki gümüştendi güzün ıslığı

Çokuluslu bir hıçkırık düş/erken geceye

Suçu

Tırnağının buğusunda sakladın

Ve

Kabus sokağının barok kokusu

Bomboş bir tuvalden selamladı

Katafalkın üzerinde ölüce kalan

Arşenin yazgısını

Ki gümüştendi

Ki gümüş tendi güzün ıslığı

Sonunu bilmediğimiz masalların 

                                     uykusunda büyüdük

Sonunu bilmediğimiz hayatların 

                                                   karanlığına', 'Arşe Küstüğü bestenin sırrını çaldı Ve  Virtüözün usul parmakları Kanadı birden Ki gümüştendi güzün ıslığı Çokuluslu bir hıçkırık düş/erken ...', ARRAY['Türk Edebiyatı','Şiir','Gamze Özer']::text[], 8.5, '{"poet":"Gamze Özer","poet_slug":"gamze-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cag-i-risim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamlı Bir Cuma İçin Sessiz Bir Solo', 'gamli-bir-cuma-i-cin-sessiz-bir-solo-gamze-ozer-xben9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akrep yelkovanı sokar

Durur zaman 

Durur saat

Durur an

              Yaşam!

Si minör bir acı

Sadece son notayı bilen 

                      bestecileriz biz

İstersek

Yalnızca istersek

               gideriz

Karakutun sende kaldı

Bir sonraki şarkın sende kaldı

Elinin öylece durduğu

                       gövdenin son kanadında

Son notaya ters yönde çırpınan küçücük

                                                      kocaman kanatlarında

İçinden yükselen tik-taklarında

Kalbinde kesilen tik-taklarında

Sözü asla yazılamayacak 

                  bir müzik kaldı

Vokalden backvokale geçişin

                                     -ki sana hiç yakışmadı

Siyahı sezişin

Siyahı içişin

Mavi pelerine gidişin

Mavi pelerinden düşüşün

                            -paralel zamanlı yoculukların

Soğuk, acımasız fotoğrafları

Bu

Bu fotoğraf senin

Gamlı bir Cuma için sessiz bir solo

Si minör bir acı

Sadece son notayı bilen

                                 yorumcularız biz

İstersek

Yalnızca istersek gideriz

İstenirse

İstenirse

Gider miyiz?', 'Akrep yelkovanı sokar Durur zaman  Durur saat Durur an               Yaşam! Si minör bir acı Sadece son notayı bilen                        ...', ARRAY['Türk Edebiyatı','Şiir','Gamze Özer']::text[], 8.5, '{"poet":"Gamze Özer","poet_slug":"gamze-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gamli-bir-cuma-icin-sessiz-bir-solo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Adam', 'ayni-adam-gamze-ozer-9a0ok', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu kentte

Takvimler

Hep aynı adamın yüzüyle 

                              eskir

Doğruysa da

Yanlışsa da

Uzakta

Mevsimler

Hep aynı temmuzu 

                çağırır

Olsa da olmasa da', 'Bu kentte Takvimler Hep aynı adamın yüzüyle                                eskir Doğruysa da Yanlışsa da Uzakta Mevsimler Hep aynı temmuzu  ...', ARRAY['Türk Edebiyatı','Şiir','Gamze Özer']::text[], 8.5, '{"poet":"Gamze Özer","poet_slug":"gamze-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayni-adam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumuz Arabesk', 'ruhumuz-arabesk-omer-avsar-qlgcr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sanki oyun oynuyoruz hayatta

rolümüz piyonmu olmak acaba

olurmu hiç bunca acidan sonra

sah vezir dururken öte tarafda

gülmeyi çabuk unutuyoruz

yipranmayi çok seviyoruz

karamsarligi biz yaratiyoruz

yinede bildigimizden sasmiyoruz

hep ezecekmiyiz daha iyi görenleri

okumazsak bilemeyiz gerçekleri

ufku açmazsak kaliriz her daim geri

sanmayinki bizden ibaret dünya dedikleri', 'sanki oyun oynuyoruz hayatta rolümüz piyonmu olmak acaba olurmu hiç bunca acidan sonra sah vezir dururken öte tarafda gülmeyi çabuk unutuyor...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruhumuz-arabesk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atlar...', 'atlar-omer-avsar-9m3zv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sahlandi kisrak durmak bilmiyor

menzile varmak için dört nala kosuyor

oyunmus gibi rüzgarla yarisiyor

atalarimin dostu selam olsun sana

dogudan batiya sen getirdin

kahramanlara yarenlik ettin

ecdadimin sözlerinde senin ismin

atalarimin dostu selam olsun sana

kar kis demeden bozkirlarda kostun

bizimle beraber sende çostun

gazilere hep dayanak oldun

atalarimin dostu selam olsun sana', 'sahlandi kisrak durmak bilmiyor menzile varmak için dört nala kosuyor oyunmus gibi rüzgarla yarisiyor atalarimin dostu selam olsun sana dogu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/atlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıktım Dertlerinizden', 'biktim-dertlerinizden-omer-avsar-p5xrh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu aksam vurup kafayi yatacagim erkenden

yastiga gömülüp oh çekecegim derinlerden

her allahin günü dert tantana dinlemekden

zaman ayiramaz oldum kendi kendimden

ben dert babasi olmak istemedimki

her önüme gelene anlat demedimki

sizin dermaniniz nasil olayimki

daha kendime çare bulamadimki

düsünceleriniz kapladi her tarafimi

kiramadiniz sonu gelmez inadimi

çepe çevre sardiniz dört bir yanimi

henüz unutturamadiniz kendi kavgami', 'bu aksam vurup kafayi yatacagim erkenden yastiga gömülüp oh çekecegim derinlerden her allahin günü dert tantana dinlemekden zaman ayiramaz o...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biktim-dertlerinizden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce', 'dusunce-mehmet-i-smail-iynhc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bele gecelerin olmaz evezi,

Toprağı düşünce,daşı düşünce

Derede çayların boğular sesi

Eriyip gözümün yaşı düşünce

Ezizim gurbetten esen yelem ben', 'Bele gecelerin olmaz evezi, Toprağı düşünce,daşı düşünce Derede çayların boğular sesi Eriyip gözümün yaşı düşünce Ezizim gurbetten esen yele...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İsmail']::text[], 8.5, '{"poet":"Mehmet İsmail","poet_slug":"mehmet-i-smail","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dusunce-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstekler', 'i-stekler-hakan-yigit-agcnt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendimi anlatabilmeyi ne kadar çok isterdim

Ya da yeniden doğmayı

Var olmayanı yaratmak isterdim

Ya da olanı yaşamayı

Yağmurun beni sırılsıklam etmesini isterdim

Ya da bir yağmur damlası olmayı

Geri dönmesi beklenen gemilere el sallamayı

Ya da o geminin kaptanı olmayı isterdim

Gözyaşlarını biraz olsun dindirmek isterdim

Ya da gözyaşını silen bir mendil olmayı

Hak ettiğim gibi bir sevgi isterdim

Ya da hak edilen olmayı

Bastığım topraktan hiç ayrılmamayı

Ya da kimseleri ayırmamayı

Hasreti bizden ayırmayı isterdim

Yapmacık gülüşlere gülmeyi isterdim

Ya da yapmacık gülebilmeyi

Acı,gerçek ve yalanı birbirinden ayırmayı isterdim

Ya da üçünden biri olmayı

Sonu olmayan akarsunun yanında uzanıp sesini dinlemek

O köprüden geçenlere sorular sormayı ben gerçekten isterdim', 'Kendimi anlatabilmeyi ne kadar çok isterdim Ya da yeniden doğmayı Var olmayanı yaratmak isterdim Ya da olanı yaşamayı Yağmurun beni sırılsık...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/istekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-hakan-yigit-mnk6e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tek arayan ben değilmişim bunu fark ettim

Donık yüzlerin yanına park ettim

Kapı çalınıp bir demet çiçek geldi elime

Ben ise içinden soluk bir gül seçtim', 'Tek arayan ben değilmişim bunu fark ettim Donık yüzlerin yanına park ettim Kapı çalınıp bir demet çiçek geldi elime Ben ise içinden soluk bi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gul-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayattan', 'hayattan-hakan-yigit-u7isp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir avuç toprağı yeni alevlenen ateşin üzerine attık 

Rüzgarla birlikte baş döndüren şişelere haber attık

Düğümlenmiş ipi çözüp içini tek tek boşalttık

Sanma bir şey aldık hayattan ne de ona bir şey kattık', 'Bir avuç toprağı yeni alevlenen ateşin üzerine attık  Rüzgarla birlikte baş döndüren şişelere haber attık Düğümlenmiş ipi çözüp içini tek te...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayattan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dreaming', 'dreaming-hakan-yigit-7ojc2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dilediğim aşkların hayali de olsa olur yanımda

Rahat bir nefes almak için korkuların tuzağında

Elimde kalem istemiyorum bu sefer

Akşam güneşi kendi kendini anlatsın

Madem gözüm gönlüm onun uzağında

Ilık bir rüzgar beklesem atsa beni semaya

Nereye gittiğimi bilerek kanat çırpsam

Görsem o hayali hiç olmazsa bir anlığına', 'Dilediğim aşkların hayali de olsa olur yanımda Rahat bir nefes almak için korkuların tuzağında Elimde kalem istemiyorum bu sefer Akşam güneş...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dreaming-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun', 'suskun-semsettin-akcay-kznj1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece yarısı başladı

                                      SUSKUN,

Kulağımda binlerce yıllık ezgiler

Önümde yeni kağıt

Ve içimde sırasını bekleyen binlerce sözcük,

Yıl 1987 temmuzun beşi

Gecenin kokusu burnumda

Yarı ot, yarı ağaç, yarı hanımeli

Ve sen birtanem, KIRÇİÇEĞİM

Yüreğimin üst köşesine çöreklenmiş bir sızı

Ne kıvrandıran, ne mutlu eden...

Sensizliğim bile yarım 

Her nefes ayrı bir koku

Her nefeste san biraz daha ulaşıyorum.

Delicesine çekiyorum havayı ciğerlerime

Penceremdeki tül delik delik

Her bir delik büyüyor

Bir dünya oluyor gecenin karanlığında

Uzakta bir sokak lambası

Dibini zor aydınlatıyor

                                   benim gibi

Bir ışık perdede dansediyor bir süre

Bir araba geçiyor yoldan

Kalbim müziğe ritim tutmuş

Neden diyorum, neden bu ayrılık

Kendimde bir kısırdöngü

Birtürlü bulamıyorum çözümü

Güvenemediğim sen mi? yoksa ben mi?

Biliyorum çözdüğüm an

Ödül.....

        Sen.....', 'Bir gece yarısı başladı                                       SUSKUN, Kulağımda binlerce yıllık ezgiler Önümde yeni kağıt Ve içimde sırasını...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Akçay']::text[], 8.5, '{"poet":"Şemsettin Akçay","poet_slug":"semsettin-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/suskun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garipçe', 'garipce-semsettin-akcay-vzcpe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir özlem.....bin özlem olduğu an,

Bir kalp.....bin olacaksa,

Bir ömür.....bir kalpsiz kalırsa,

Tırpanını sallayacak ölüm,

Bin özlemli bir kalbe

(Ankara, 1987)', 'Bir özlem.....bin özlem olduğu an, Bir kalp.....bin olacaksa, Bir ömür.....bir kalpsiz kalırsa, Tırpanını sallayacak ölüm, Bin özlemli bir k...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Akçay']::text[], 8.5, '{"poet":"Şemsettin Akçay","poet_slug":"semsettin-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/garipce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüme Dair', 'gonlume-dair-yaren-gurler-ounts', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğim yanmıyordu, fikrim ilkesiz

            Derdim yoktu, kalbim yaresiz

            Şimdi senin elinden ruhum çaresiz

            Nadas toprağa tohum ekilir mi gönül?

   Tam da sevmeyi unutuyorken;

   Akıttığım göz yaşımı kurutuyorken,

   Ruhumda yeni bir ben yaratıyorken,

   Pişmiş aşa su katılır mı gönül?

         

              Hazır değilken yeniden sevmeye,

              Vefasız bir hasretin ardına düşmeye,

              Bir nefes kalmışken yeniden bitmeye,

              Olmamış başak biçilir mi gönül?

  

    Saadet güneş gibi, erişilmez, ulaşılmaz.

    Hasretine acısına asla alışılmaz.

    Kapanmışım ben içime, öyle ki anlaşılmaz.

    Işıksız limana gemi yanaşır mı gönül?

               Her an bir hayali düşünemem ben,

               Bir an gülüp bir an üzülemem,

               Bundan gayrı sevsem de sevilemem,

               Çıkmış candan umut beklenir mi gönül?

    Onun her halinde bir meşalesi var,

    Gülüşünde huzur efsanesi

    Benimse atim karanlık, ufkum dar

    Ateş baruta yar olur mu gönül?

              Benim sevmeye mecalim kalmamış,

              Anlaşılan senin gözün daha doymamış,

              Hala umudun var güllerin solmamış,

              Öyle olsun, yeniden sevelim be gönül.', 'Yüreğim yanmıyordu, fikrim ilkesiz             Derdim yoktu, kalbim yaresiz             Şimdi senin elinden ruhum çaresiz             Nadas ...', ARRAY['Türk Edebiyatı','Şiir','Yaren Gürler']::text[], 8.5, '{"poet":"Yaren Gürler","poet_slug":"yaren-gurler","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gonlume-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih', 'tarih-nurol-banabak-1grx1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tarafımdan silinmiştir/nb', 'tarafımdan silinmiştir/nb...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/tarih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayamıyorum', 'aglayamiyorum-fikret-tasbek-ibsdv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlayamıyorum artık

Gözyaşlarım hükmediyor benliğimin sesine

Selvi boyları düşlerim

Yarım kalmış tarihimin

Enson izleri şimdi

Ey İstanbul, sende bensiz kalmış

Bir dudak izi

Bende, sende özlemlerinin yittiği

Bir gece gizemi saklı

Dokunuyorum ufkunun parmak uçlarına

Kahpece örülüyor dağlar

Ağularsa son demini almıl

Gidiyor esrik bir rüzgarın ardı sıra

Sigaram, gözlüğüm, kitabım baş ucumda

Lanet doğuruyorum

Acıları katık ederek yaşama

Ne su

Ne ekmek

Ne de hava gerek

İnsan da olmamak gerek

Dünyanın buyruğu yaşamak ise eğer

Buyruğa boyun eğmeden yaşayabilmek

Ağlayamıyorum,

Ağlayamıyorum artık....', 'Ağlayamıyorum artık Gözyaşlarım hükmediyor benliğimin sesine Selvi boyları düşlerim Yarım kalmış tarihimin Enson izleri şimdi Ey İstanbul, s...', ARRAY['Türk Edebiyatı','Şiir','Fikret Taşbek']::text[], 8.5, '{"poet":"Fikret Taşbek","poet_slug":"fikret-tasbek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aglayamiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Sana Ne Demeli', 'i-stanbul-sana-ne-demeli-omer-avsar-bw1dn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'modadan günesin batisini seyretmek

üsküdar kiyisindan camileri görmek

eminönünde kuslarin dansini izlemek

yada besiktasda oturup bir çay içmek

beyoglunun nostalji kokan havasi

çamlicanin doyumsuz manzarasi

eyüpün o tarihi sokaklari

taksimin bitmez kalabaliklari

istanbul tüm sehirlerin tanriçasi

güzelligiyle dünyanin harikasi

herkezin imrendigi altin parçasi

nankörlük edemem yokki senden baskasi

essiz sehrim sana doyum olmuyor

inan anlatmaya benim gücüm yetmiyor

tarifsiz büyüklügün herkezi sasirtiyor

bir kez görenin yüregi askla baglaniyor', 'modadan günesin batisini seyretmek üsküdar kiyisindan camileri görmek eminönünde kuslarin dansini izlemek yada besiktasda oturup bir çay içm...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-sana-ne-demeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediye Olsun Şiirlere', 'hediye-olsun-siirlere-omer-avsar-15p7q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kelimelerde sakli yalnizligim

hecelerde benim dert ortagim

her seyimi sinirsizca paylastigim

siir satirlari hediyedir yazdiklarim

mutlulugu hüznü size anlattim

hayatima belkide anlam kattim

bir gün olsun aklimdan çikarmadim

bütün siirler benim ilk göz agrim

bir sürü sitemime dayandiniz

çogu zaman bana katlandiniz

beni en iyi sizler anlattiniz

kuru bir tesekküre çoktan hak kazandiniz', 'kelimelerde sakli yalnizligim hecelerde benim dert ortagim her seyimi sinirsizca paylastigim siir satirlari hediyedir yazdiklarim mutlulugu ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hediye-olsun-siirlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bidenem', 'bidenem-erdal-canbulat-dykrh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlümü bir volkana çevirdin bidenem

Aşkın pare pare yakar kavurur beni 

Ömrümü bir balkona çevirdin bidenem

Aşkın pare pare asar savurur beni 

xxx

Karlı dağım bir virana çevirdin bidenem

Aşkın pare pare biçer devirir beni .

Gençlik çağım bir limana çevirdin bidenem

Aşkın pare pare çeker getirir beni 

 Hollanda - Amsterdam', 'Gönlümü bir volkana çevirdin bidenem Aşkın pare pare yakar kavurur beni  Ömrümü bir balkona çevirdin bidenem Aşkın pare pare asar savurur be...', ARRAY['Türk Edebiyatı','Şiir','Erdal Canbulat']::text[], 8.5, '{"poet":"Erdal Canbulat","poet_slug":"erdal-canbulat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bidenem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Damlaları', 'yagmur-damlalari-nurgun-salli-8c2ma', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğun nasıl bir ızdırap,

Kanayan yüreğimde.

Gecelerim nasıl da donuk, sensizliğimde,

Karamsarlıklar diz boyu, yoksun yanımda.

Olsan da anlamazsın duygularımı,

İçimdeki yağmur damlalarını...

Kumsaldaki izleri dalgalar silse de,

Yüreğimdeki izleri sen silemezsin,

Bırakıp gitsem de seni,

Yine seninleyim aslında.

Anlatsam da sana olan sevgimi,

Anlayamazsın içimdeki yağmur damlalarını.

Tutamadığım yıldızlardan birisin artık,

Senden nefret ettiğimi söylese de dilim,

Seni unuttum derken bile özlüyorsam,

Yıkılan gururumla sana yalvarıyorsam,

Gözlerimle anlatmak istesem de,

Anlayamazsın içimdeki yağmur damlalarını.

Buğulu bir gecenin ardından,

Sabahın nasıl geldiğini anlayamadıysam,

Ve hala bir damla saklıyorsam gözlerimde,

Bir kuytuya düşmüşse yüreğim,

Çaresizliğimi anlatmak istesem de,

Anlayamazsın içimdeki yağmur damlalarını.

Hüzünlü bakışlarımdan,

Yüreğimdeki o derin sevginden,

Sana olan bağlılığımdan,

Gözlerinin içinde kayboluşumdan,

Sana olan sevgi selimi anlatsam,

Anlayamazsın içimdeki yağmur damlalarını.', 'Yokluğun nasıl bir ızdırap, Kanayan yüreğimde. Gecelerim nasıl da donuk, sensizliğimde, Karamsarlıklar diz boyu, yoksun yanımda. Olsan da an...', ARRAY['Türk Edebiyatı','Şiir','Nurgün Şallı']::text[], 8.5, '{"poet":"Nurgün Şallı","poet_slug":"nurgun-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yagmur-damlalari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopamamak', 'kopamamak-bulent-yuksel-njqi5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne birlikte olabilirsiniz bazen,

     ne de kopabilirsiniz.

Ne sen onu anlayabilirsin,

     ne de o seni anlayabilir.

Ne sen onu kaybetmek istersin,

     ne de o seni kaybetmek ister.

Ortak buluştuğunuz tek noktanız

     kopamamaktır birbirinizden.

İçinizi kemiren, küçük fakat

     rahatsız edici bir kemirgen gibi,

Hem sevgi hem de ihtirasla

     beslersiniz bu kemirgeni.

Ne beraber olabilirsiniz,

Ne de kopabilirsiniz birbirinizde.', 'Ne birlikte olabilirsiniz bazen,      ne de kopabilirsiniz. Ne sen onu anlayabilirsin,      ne de o seni anlayabilir. Ne sen onu kaybetmek i...', ARRAY['Türk Edebiyatı','Şiir','Bülent Yüksel']::text[], 8.5, '{"poet":"Bülent Yüksel","poet_slug":"bulent-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kopamamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çirkin İstanbul', 'cirkin-i-stanbul-ardan-okay-t2bip', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yabancı gibisin

Bu akşam İstanbul

Gözlerimde değil

Kulağımda dans edersin anlamsız

Bir dert gibisin

Bu akşam İstanbul

Sarhoş ceketi gibi fırlatıvermişsin beni

Ter kokulu yataklara da

Gençliğimi umursamazsın

Denizin fahişe mi fahişe bu akşam

Mehtap eğilmiş tüm şehvetiyle

Öper öper de

Kıskançlığıma aldırmazsın

l6 yaşın dudakları güler, güler de

Kahrolurum da çaresizliğime

Hiç acımazsın

Dalların uykusuz İstanbul

Rüzgarın tembel mi tembel

Fenerlerin kavrulmuş yanmaktan

Dert döker kaldırımlara

Makyajlı gecelerinde

İnsanların çileli İstanbul

Karhane dudağına benzer verdiklerin

Duygusuzca avuttum zannedersin

Oysa ki,

Verdiğin sade acı

Her güzelliğin yalancı

Kadehlerin kahır tortusu

Mübarek şehir değil

Sosyete orospusu.

Ağustos l966', 'Bir yabancı gibisin Bu akşam İstanbul Gözlerimde değil Kulağımda dans edersin anlamsız Bir dert gibisin Bu akşam İstanbul Sarhoş ceketi gibi...', ARRAY['Türk Edebiyatı','Şiir','Ardan Okay']::text[], 8.5, '{"poet":"Ardan Okay","poet_slug":"ardan-okay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cirkin-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakla Beni', 'sakla-beni-nurol-banabak-8zxjk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni gözlerinde saklama

Ağlarsın düşerim

Beni yüreğinde saklama

Küsersin düşerim

Beni rahminde sakla

Doğur doğayım', 'Beni gözlerinde saklama Ağlarsın düşerim Beni yüreğinde saklama Küsersin düşerim Beni rahminde sakla Doğur doğayım...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sakla-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meltem', 'meltem-i-sa-seker-vi1yh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vuslata ermezsem ederim sitem.

Sensiz an-ı seyyâleyi ne edem?

Cemâlin görmek bu denli zor mâdem,

Üfle nefesinden bana bir meltem.

Ferhat,Mecnun dostumdur,Yunus dedem.

Gözlerim yolunu sevgilim her dem.

Ey kaşları kalem lebleri bâdem,

Yandırma sev beni dolmadan vâdem.', 'Vuslata ermezsem ederim sitem. Sensiz an-ı seyyâleyi ne edem? Cemâlin görmek bu denli zor mâdem, Üfle nefesinden bana bir meltem. Ferhat,Mec...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/meltem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-serdar-akcimen-kw7hz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevmek istiyorum,

Kalbim durana kadar

Peşinden koşmak istiyorum,

Dizlerim çürüyene kadar.

Seninle konuşmak istiyorum,

Dilim tutulana kadar.

Seni öpmek istiyorum,

Dudaklarım kuruyana kadar.

Seninle çıkmak istiyorum,

Kalbim durana kadar.

Cevabını bekliyorum,

Taaaa ki, ölene kadar!!!', 'Seni sevmek istiyorum, Kalbim durana kadar Peşinden koşmak istiyorum, Dizlerim çürüyene kadar. Seninle konuşmak istiyorum, Dilim tutulana ka...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçimen']::text[], 8.5, '{"poet":"Serdar Akçimen","poet_slug":"serdar-akcimen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istiyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyim', 'herseyim-faruk-aysoy-ebisd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlıkta yeni doğan bir ışık,

Aklımda beliren bir kıvılcım,

Ruhuma yapışan bir heyecan,

Kalbimde oluşan koca bir sevgisin.

Yalnızlığın ötesindeki ses,

Karamsarlığı önleyen mükemmellik,

Hissedilen tüm güzellikler,

Yeniden doğan dünyanın en büyük aşkısın.

Sadece benim için beliren,

Benim gönlümde gelişen,

Yeniden bana aşkı tattıran,

Hayatıma giren en yüce ve güzel varlıksın

Sen herşeysin; herşeyimsin...', 'Karanlıkta yeni doğan bir ışık, Aklımda beliren bir kıvılcım, Ruhuma yapışan bir heyecan, Kalbimde oluşan koca bir sevgisin. Yalnızlığın öte...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/herseyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık Düşler', 'satilik-dusler-tuba-sarlak-2gcxb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'satılık düşlerim olmadı benim hiç

karanlığında bile yüreğimin

uzaktanda olsa hep

ışığı oldu düşlerimin

gölgesinde onun olduğu gaz lambam

küçük sevmedi yüreğim hiç

her ne kadar saklasada gözlerini

bir tek ondan gizleyemedi

işte sırf bu yüzden

böylesi sevdiği için

müebbet bir ceza aldı

öyle bir zamanda gitti ki 

düğümlendim sanki...', 'satılık düşlerim olmadı benim hiç karanlığında bile yüreğimin uzaktanda olsa hep ışığı oldu düşlerimin gölgesinde onun olduğu gaz lambam küç...', ARRAY['Türk Edebiyatı','Şiir','Tuba Şarlak']::text[], 8.5, '{"poet":"Tuba Şarlak","poet_slug":"tuba-sarlak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/satilik-dusler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusu', 'pusu-atilla-bekdemir-y88gw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnmez şiirlerin doruklardan

yamaçların söz dinlemez

ve bir çığ düşer

en bakir ufkuna bakışlarının

kaldırımlar taşıyamaz yükünü

yüreği doruklarda asılı kalanların

menzil uzar

silah geri teper

ulaşamaz düşman

hep pusuda bekler

pusu kaderidir

Yüreği doruklarda asılı kalanların

ve

başkaldırının izleri

iniyorken dağlardan

kentlerin karanlık sokaklarına

rüyalarının içinde yitirirken herşey anlamını

kelimeler de pusu''ya saplanır bazen

o zaman kısalır menzil

patlar silah

Yorulmuş ayaklarınla

baka kalırsın gidenlerin ardından

bebeler büyütürsün

Yabancı gözlerin hapsinde

rüyaların

başkalarının yaşamında

karışırken dudağında umut mechule

kundaklanır sevdan

kazanır pusu

Yüreği dağlarda gezenlerin

kaderidir pusu', 'İnmez şiirlerin doruklardan yamaçların söz dinlemez ve bir çığ düşer en bakir ufkuna bakışlarının kaldırımlar taşıyamaz yükünü yüreği dorukl...', ARRAY['Türk Edebiyatı','Şiir','Atilla Bekdemir']::text[], 8.5, '{"poet":"Atilla Bekdemir","poet_slug":"atilla-bekdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/pusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kraliçe', 'kralice-poet-of-the-darkness-6ph0q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aydınlık ve karanlık diye

İkiye ayırmıştım yüzünü

İki ayrı yüz

İki ayrı insandın benim için...

Aydınlığınla kandırır

Karanlığınla beni yakardın

Ellerimi tutar gibi yapardın ya hani

Sonra da arkanı dönerdin hep...

Ne yapacağımı bilmezdim

Yüzünü görmeyince

Çevirirdim bedenini

Yüzün yüzüme deysin diye

Sense bir adım daha

Kaçardın benden

Kovalamamı istiyordun belki de

Dizlerimin üstüne çökmemi

Ve seni sevdiğimi

Söylememi bekliyordun

Kim bilir elin elime deyer

Felaketim olurdu belki de

Ama sen Kraliçe

Sen ki gözlerinle insanları

Ölüme gönderen

Sen ki pençelerinle kalpleri

Yerinden sökendin

Ama gör müyor musun

Gözlerimin ötesini

Sen yakardın

Sen yıkardın ya hep

Bu beden sana ait değil

Kraliçe!

Ve şimdi masumların

Ruhunu kusmanın zamanı

Çek zincirleri ellerine

Haykır, yalvar...

Şimdi gözlerin gözlerimde

Erned lezülgiğin

Erned temaniysumin

Nes adecse rib siçnih...

Ben gölgeyi takip edenim

Ben gerçekteki sahteliğim

Ve sen Kraliçe

Sen benim gözlerimdeki

Karanlığın sesisin...

Öl artık Kraliçe!

Öl artık!....', 'Aydınlık ve karanlık diye İkiye ayırmıştım yüzünü İki ayrı yüz İki ayrı insandın benim için... Aydınlığınla kandırır Karanlığınla beni yakar...', ARRAY['Türk Edebiyatı','Şiir','Poet Of The Darkness']::text[], 8.5, '{"poet":"Poet Of The Darkness","poet_slug":"poet-of-the-darkness","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/kralice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı YOk Bu Şiirin', 'adi-yok-bu-siirin-sair-gokhan-5auqd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Martı çığlıkları var üzerimde

Haykırışları, bağırışları

Göz yaslarıyla bir martı çığlığı.

Derin denizlerde belki

Belki de halkalı çöplüğünde

Ama kanatlarının ucunda özgürlüğü taşıyan,

Çığlıklar , naralar atan

''Özgürüm , özgürüm iste! ''

Bir martı çığlığı sardı içimi

Çok uzaklarda olsam da İstanbul’dan

Bir martı gördüğümde andıran

Boğazın serin suyunu

Avlanan balıkçıları , belki Eminönü''nü

Ama daha çok Taksimi yalnızlığı unutmak

Sevgiden yana çaresizliğimi paylaşmak için

Tüm sırlarımı anlattığım Taksimi

Unutabilir miyim?!

Bir martı çığlığı sardı ruhumu

Ama bu kez değil, bu sefer olamaz

Martı gitsin içimden! Ne olur!

Bıraksın artık!

Kendi kanatlarım var benim görmüyor musunuz!

Görmüyor musunuz ha!

Bırakın uçabilirim ne olur baba kırma kanatlarımı yine!

Ne olur!!!

Ama kanatlarım olmasa da yanına gidebilirim!

Sevdiğimi görebilirim...

Ruhumda var kanatlarımdan ziyade,

Ruhumla sevdiğimin kalbine girebilir,

O sıcacık nefesi olabilirim içinde!

Olabilir miyim? izin verir misin sevdiğim?', 'Martı çığlıkları var üzerimde Haykırışları, bağırışları Göz yaslarıyla bir martı çığlığı. Derin denizlerde belki Belki de halkalı çöplüğünde...', ARRAY['Türk Edebiyatı','Şiir','Şair Gökhan']::text[], 8.5, '{"poet":"Şair Gökhan","poet_slug":"sair-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/adi-yok-bu-siirin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bir Daha Ummak', 'seni-bir-daha-ummak-semih-sergen-38y9r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen şimdi yoksun o kadar

Ayak diremen boşuna

Sana kaç kere söyledim yalnızım diye

Birde ürkek ürkek dolanma yaban geyikler gibi

Sevişmeye izin yok yasak aşklara paydos

Kapadım kilitledim

Özgürlükle aramıza koskoca bir duvar ördüm

Koskoca bir küfürüm şimdi

Bir üfledim söndürdüm güneşi

Darmadağın ettim çopur suratını ayın

Mutluyum şaşkına çevirdim gezegenleri

Seni inkar ediyorum

Seni duvara çiviledim

Seni yaktım

Seni şehrin en kalabalık meydanında seni

Bir kurtulabilsem sensizliğimden

Çekse gitse bu yıkıntı

Bir daha hiç gelmese

Hiç tanımasa bu sokaklar ayak seslerimi

Guçsüzüm biliyorum tükenmişim

Hadi bütün ışıklarını söndür

Sana yalan söyledim', 'Sen şimdi yoksun o kadar Ayak diremen boşuna Sana kaç kere söyledim yalnızım diye Birde ürkek ürkek dolanma yaban geyikler gibi Sevişmeye iz...', ARRAY['Türk Edebiyatı','Şiir','Semih Sergen']::text[], 8.5, '{"poet":"Semih Sergen","poet_slug":"semih-sergen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-bir-daha-ummak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimdeki', 'hayalimdeki-sair-gokay-52pr3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay ışığında gözlerin parlıyor

Uzun sarı saçların

Gece rüzgarıyla havalarda uçuşuyor

Evet sensin o hayalimdeki sensin

Kumsaldaki izlerin beni sana getirecek

Ay ışığında parlayan gözlerin 

Bana yol gösterecek

Evet sensin o hayalimdeki sensin

Bir ilkbahar gecesi olacak

Gökteki ay gülümseyip parlayacak

Rüzgar hafif ve serince esecek

Ve ben sana bir gül uzatacağım

Tıpkı hayalimdeki gibi

Bekle bekle beni sevgilim

Yollarım uzaksada gelecegim

Bekle bir ilkbahar gecesini 

Tıpkı hayalimdeki gibi geleceğim', 'Ay ışığında gözlerin parlıyor Uzun sarı saçların Gece rüzgarıyla havalarda uçuşuyor Evet sensin o hayalimdeki sensin Kumsaldaki izlerin beni...', ARRAY['Türk Edebiyatı','Şiir','Şair Gökay']::text[], 8.5, '{"poet":"Şair Gökay","poet_slug":"sair-gokay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayalimdeki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktır Bu', 'asktir-bu-sair-gokay-lpavz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgiye susamıştım

Sulayı verdin beni

Bedenimi sarmıştın 

Kalbimi çaldın benim

Sevsem mi bilmiyorum

Sevmesemde diyorum

Ama aşktır bu inan

Önüne geçmek olmaz

Sevenler diyarından 

Geliyorum ben inan

Sevsende sevmesende 

Seviyorum ben inan

Aşkın yalanı olmaz 

Sulanan çiçek solmaz

İşte aşktır bu inan 

Önüne geçmek olmaz', 'Sevgiye susamıştım Sulayı verdin beni Bedenimi sarmıştın  Kalbimi çaldın benim Sevsem mi bilmiyorum Sevmesemde diyorum Ama aşktır bu inan Ön...', ARRAY['Türk Edebiyatı','Şiir','Şair Gökay']::text[], 8.5, '{"poet":"Şair Gökay","poet_slug":"sair-gokay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asktir-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kelime', 'i-ki-kelime-sair-gokay-kqcj6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özgür olmak istiyorsun,

Belki de!

Uçmak, bir kuş gibi

Bulutlarda süzülmek.

Ve sonra yalnızlık

Gün gibi aşikar

Daralıyor, sıkılıyorsun.

Uçuyorsun alabildiğince

Kollarıma konuyorsun

O an bir buse konduruyorum dudaklarına.

Önce gözlerini kapatıyorsun

Sonra şöyle bir dönüp arkana 

Kaybolan yıllarına 

Belki acıdıgın 

Belki özlemini çektiğin 

Anılarına bakıyorsun.

Ayaklarınla yere basmak istiyorsun,

Yeni doğan çocuklar gibi bocalıyorsun önce

Sonra dimdik ayakta 

Bakışlar gururlu

Hafif bir tebessümle bakıyorsun bana 

Dudaklarında iki kelime 

Şelaleden dökülen sular gibi boşalıyor

Seni Seviyorum...', 'Özgür olmak istiyorsun, Belki de! Uçmak, bir kuş gibi Bulutlarda süzülmek. Ve sonra yalnızlık Gün gibi aşikar Daralıyor, sıkılıyorsun. Uçuyo...', ARRAY['Türk Edebiyatı','Şiir','Şair Gökay']::text[], 8.5, '{"poet":"Şair Gökay","poet_slug":"sair-gokay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iki-kelime-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakan Şimşektir', 'cakan-simsektir-sair-gokay-mef6v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çakan şimşektir gözlerimizde kalan

Parıltısıyla gözlerimizi kamaştıran

İlk aşk yağmurumuzun habercisi

Çakan şimşektir gözlerimizde kalan

Çakan şimşektir gözlerimizde kalan

Değdiği kayalıkları toz duman eden

Odur aşkımızın anılarınıda silen

Göremediğimiz sonsuz beyazlığa iten

Çakan şimşektir gözlerimizde kalan

Kalbimize giden yolu bağlayan

Odur bizi birbirimizden ayıran

Çakan şimşektir gözlerimizde kalan', 'Çakan şimşektir gözlerimizde kalan Parıltısıyla gözlerimizi kamaştıran İlk aşk yağmurumuzun habercisi Çakan şimşektir gözlerimizde kalan Çak...', ARRAY['Türk Edebiyatı','Şiir','Şair Gökay']::text[], 8.5, '{"poet":"Şair Gökay","poet_slug":"sair-gokay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cakan-simsektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firardayım', 'firardayim-cengiz-yazici-nq7l5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakma bana,benden adam olmaz.Ben bir eşkiyayım.

Öz vatanımdan sürülmüşüm.Artık başka diyarlardayım.

Dağılır sandığım dağılmayan.Duman duman efkarlardayım,

Suçlu ben değilim.Suçum bağlanmaksa ben artık firarlardayım.

Dönüşüm yok.Ben dönüşü olmayan zorlu yollardayım,

Olamam sende,olsamda,ben şimdi başka kollardayım.

Karda sanmayın sakın beni,vallahi billahi zarardayım,

Suçlu ben değilim işte anla.Ben benden firardayım.

Aramasın gözlerin sakın beni.Ben yokum çok uzaklardayım,

Arayıp arayıp bulamadığım,gençliğimi çalan yıllardayım.

Avare avare dolaşıp,kah burda,kah orda,kah yıldızlardayım,

Dedim ya bitanem,dedim ya canım.Ben artık... 

AKLIMDA FİRARDAYIM....', 'Bakma bana,benden adam olmaz.Ben bir eşkiyayım. Öz vatanımdan sürülmüşüm.Artık başka diyarlardayım. Dağılır sandığım dağılmayan.Duman duman ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/firardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Çalan', 'kara-calan-cengiz-yazici-14ezb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hey!sen.Kalbimi yaralayan.

Sana dedim.Alnıma kara çalan.

Duymuyormusun beni?çıngıraklı yılan.

Duymazsın tabi,senin hayatın yalan.

Rastladığımda ikinci bahardaydı ömrüm.

Kral değildim ama bir kraldan özgürdüm.

Tam unuttum derken onu rüyamda gördüm.

Görsem ne çıkarki kara topraklara gömdüm.

Seni kalbimin en derinlerine hapsettim.

Ordasın artık,ordan asla çıkamayacaksın.

Ben şimdi,sensiz Günlerime hasretim,

Sense,yaşadığını zanneden bir ölü olacaksın.

Var git deli gönlüm başka sevdalar bul.

Bulduğun sevdalarda olmasın sakın para pul.

Harman olsun sevdaların onlarla savrul,

Savrulduğun sevdalarda sevdanka mutlu ol...', 'Hey!sen.Kalbimi yaralayan. Sana dedim.Alnıma kara çalan. Duymuyormusun beni?çıngıraklı yılan. Duymazsın tabi,senin hayatın yalan. Rastladığı...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kara-calan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir''den Bir Haber Bekliyorum.', 'i-zmir-den-bir-haber-bekliyorum-cengiz-yazici-86lcx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üstüme hafiften yağan,yağmurmu ne?

Oturmuş kafa çekiyorum.Yağmursa bana ne.

Dudaklarımda külü uzamış,Bafra cigaram,

Kaldırım taşı,sandalyem.pazar kasasından masam.

Pet şişeden,kadeh yapmışım kendime,

Toz kondurmam billah,yarım elmadan mezeme.

Birazdan Cırcırböceğim çalar benim,

İzmir''den bana haberler verir.Cep telim.

Yağmur sanki inat,sadece bana yağıyor,

Bulutlar kapamış,yıldızımı.Gözlerim arıyor.

Cırcır da o na inat,çalmıyor işte çalmıyor,

Gözlerim beyhude boşlukta,yoksun.Ağlıyor.

Hep sen vardın.Dar günlerimin dar anlarında,

Minnet,hafif kalır.Yazdıklarımın yanında

Şimdi sıra ben de olsun artık.Sıra bana gelmeli.

Yorgun kalbim,Seni artık sarmalı,sevmeli öpmeli...', 'Üstüme hafiften yağan,yağmurmu ne? Oturmuş kafa çekiyorum.Yağmursa bana ne. Dudaklarımda külü uzamış,Bafra cigaram, Kaldırım taşı,sandalyem....', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/izmir-den-bir-haber-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahpenin Şehri', 'kahpenin-sehri-sadan-cerit-lg7ia', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün olsun diyorum,

Bir gün olsun yakamoz seyrederken 

Ağlatmadan rakımı içirtmeyecek misin

İşte yine başlıyor 

Aynı müzik, aynı nakarat, aynı koro

Hep bir ağızdan söylüyorlar şarkımı

- “Nereden Sevdim O Zalim Kadını “

Sana ne diyeyim İstanbul kahpenin şehri

Sokakların aynı, çirkefin aynı, ayrılıkların aynı

Kahpenin Şehri - BirGaripAskHikayesi', 'Bir gün olsun diyorum, Bir gün olsun yakamoz seyrederken  Ağlatmadan rakımı içirtmeyecek misin İşte yine başlıyor  Aynı müzik, aynı nakarat,...', ARRAY['Türk Edebiyatı','Şiir','Şadan Cerit']::text[], 8.5, '{"poet":"Şadan Cerit","poet_slug":"sadan-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kahpenin-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melankoli', 'melankoli-ataol-behramoglu-p1kxa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey sokaklarında yıllarca avare dolaştığım 

İçinde ilk aşkımı yaşadığım küçük şehir. 

Umutsuz akşamlarımda sesini duyduğum lir 

Sihrinde ilk acıyı tattığım .

Ey sarhoş akşamlarımın biricik tesellisi 

İlk şiirlerimdeki biricik dert ortağım fener 

Soğuk kış geceleri ısındığım kalorifer 

Gitgide uzaklaşan tren sesi .

ey en masum arzularımı gizleyen oda 

Yıldızlarla dost eden küçük pencere 

Her akşam gönlümün dilediği yere 

Götüren sihirli araba .

Ey en içli en yanık türkülerimi duymayan 

rüzgarı saçlarımı dağıtan sokak 

Ve ey saçı ak gönlü ak 

Anneciğim pencerede ağlayan .

Ah biliyorum güç gelecek sizlere 

Ama artık gitmek geliyor içimden 

Bir sabah masmavi bir bulutun peşinden 

Dönüşü olmayan yerlere...', 'Ey sokaklarında yıllarca avare dolaştığım  İçinde ilk aşkımı yaşadığım küçük şehir.  Umutsuz akşamlarımda sesini duyduğum lir  Sihrinde ilk ...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/melankoli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-selim-sen-xt3i8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I

Ellerin geniş, yüzün kalabalık değildir senin

Nasıl bileceksin kaldırım taşının kabuk bağladığını

Bir çiftçinin ellerine dokununca bozkır olamamışsın

Bu yüzden sokakta yürürken avuçlarını ısıtamazsın

Ağıt nasıl yakılır, nasıl kına vurulur bilemeden yaşamışsın

Öyle ki nehirler bazen bir denize dökülmek için akmazlar

Dostun elinden zehir içilirse gök nasıl soğur görememişsin

Farkında değilsin giyinik bakıyorsun çıplak uçan güvercinlere

Sen böyle sevemezsin

Ama dünya çok daha geniş, sen böyle sevemezsin

Daracık, daracık, daracık yüreğin vardır senin

II

Bir muhacir,  yüzünü niçin nadasa bırakır bilememişsin

Acı çekmek, kendine dal bulamayan bir yapraktır

Öpüşlerini unutmak için, bütün dudak izlerini silmişsin

Türküler söyleyerek yasaklı yollarda yürümemişsin

Bir beden yanarsa neler sulanır görememişsin

Yağmurun utandığı ve bulutların buruştuğu da olur

Aşk, üşümekten korkan bir kelimeyi sıcak tutmaktır

Saçak diplerinde bağdaş kurup alnını serinletemezsin

Sen böyle sevemezsin

Ama dünya çok daha insaflı, sen böyle sevemezsin

Küçücük, küçücük, küçücük merhametin vardır senin

III

Grevlerde halay tutan işçileri kucaklamamışsın

Efendilere fırlatılacak aksi sözlerin yoktur senin

Açların, asılanların hesabını bir beyaz gülle tutamazsın

Darağaçları bengi yapraklar açsa ne olur, bilememişsin

Karların üstünde yanan bir dağ ateşiyle ısınmamışsın

Sana zor geliyor, söylediklerin donar diye üşümemek

Ayın altında hafif uyuyan bir eşkiya olmak istememişsin

İstek dışı bir bakışla namludan kelebekler uçurttamazsın

Sen böyle sevemezsin

Ama dünya çok daha aydınlık, sen böyle sevemezsin

Işımayan, ışımayan, ışımayan gözlerin vardır senin

IV

İsyan eden bir köleye derinden hiç bakmamışsın

Söyle, acıktığı zaman hangi canlı merhametli olur

Özgürlük, katılmak mıdır yoksa seyirci olmak mı

Söyle, eşit olunmadan bir arada hiç yaşanır mı

Kervanlara yol gösteren kuyulardan su içmemişsin

Ama korkmazsın ve uykunu avucunda saklamazsın

Yıldızlara bakarsın örtünmek için bir sözcük bulursun

Bir dilek tutunca niçin terlemiyorsun hiç söylemezsin

Sen böyle sevemezsin

Ama dünya çok daha ferahtır, sen böyle sevemezsin

Açılmayan, açılmayan, açılmayan bir için vardır senin

V

Yüzünü dağlardan sarkan bir ışık demetiyle ısıtmamışsın

Mevzide unutulmuş bir bakışı kendine konuk edemezsin

Köy yollarında sıkışıp kalmış bir damla serinlik midir

Bir gökdelenin çatısında kimin ayak izleri var bilememişsin Farklıyı yücelten ve benzeri bozanları tanımamışsın

Kendine ağız bulamayan bir sesi göğsünde tutamamışsın

Sessizlik topraksız bırakılmış bir tohum gibi şiddettir

Bulutlar çekilince gökyüzü nasıl mayi konuşur  duyamamışsın

Sen böyle sevemezsin

Ama dünya çok daha mütevazidir, sen böyle sevemezsin

Küçümseyen, küçümseyen, küçümseyen yüzlerin vardır senin

Sen böyle sevemezsin', 'I Ellerin geniş, yüzün kalabalık değildir senin Nasıl bileceksin kaldırım taşının kabuk bağladığını Bir çiftçinin ellerine dokununca bozkır ...', ARRAY['Türk Edebiyatı','Şiir','Selim Şen']::text[], 8.5, '{"poet":"Selim Şen","poet_slug":"selim-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/sevgi-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Gemi', 'son-gemi-sair-kambocyali-grgox', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün, gideceğim çok uzaklara 

Senden habersiz, sen olmadan

Orada, yenibir aşk ,yenibir sevgili bulacagım

Çıldırtan aşkını unutmak 

Seni birdaha hatırlamamak için 

Ve yıllar sonra bulndugum ülkeden bir mektup gelecek

Bu mektubu ,belki kocan, belki çocukların açacak

İçinden çıkan resmime, kim bu ihtiyar diye soracaklar

Sen cevap veremeyeceksin

Ama içinden onun resmi diyeceksin

Bilemem nekadar sonra  yolun düşecek bulundugum ülkeye

Koşacaksın rıhtımdaki meyhaneye ,nasıl nerede bulurum diye

Gösterecekler mezarlıgın yolunu 

Diyecekler çok içmekten öldü geçenlerde

İnan hep seni andı son nefesinde

Ve daha sonra mezarımı bulacaksın, belirsiz bir tümsek

Yağmur yagıyor, haydi git artık diyecekler 

Sen bu sözlere aldırış etmeyeceksin

Saatlerce kalacaksın ölmüş sevgiliyle

Ölüler konuşa bilse, haydi git diyecegim

Evvelden diyordum ayrı yollarımız

Şimdi ise ayrı dünyalarımız 

Evet herşey kaldı mazide 

Koş sende yer ayırt meçhule giden bu

                           SON GEMİDE', 'Birgün, gideceğim çok uzaklara  Senden habersiz, sen olmadan Orada, yenibir aşk ,yenibir sevgili bulacagım Çıldırtan aşkını unutmak  Seni bi...', ARRAY['Türk Edebiyatı','Şiir','Şair Kamboçyalı']::text[], 8.5, '{"poet":"Şair Kamboçyalı","poet_slug":"sair-kambocyali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/son-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem Öldü', 'annem-oldu-mehmet-calik-lx8yh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sevgilim

doldur memelerini ağzıma

ömürlük bir konak aç sıcaklığında

kucaksız kaldı çocukluğum...

artık o gün

kara haberin

gideceği bir adresim yok.', 'sevgilim doldur memelerini ağzıma ömürlük bir konak aç sıcaklığında kucaksız kaldı çocukluğum... artık o gün kara haberin gideceği bir adres...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çalık']::text[], 8.5, '{"poet":"Mehmet Çalık","poet_slug":"mehmet-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/annem-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanan', 'yasanan-ahmet-telli-rt2ai', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir süredir kuşlar da yok

Kentin bulanık göğünde 

Dumanlı bir uğultu

Uzayıp dururken sokaklarda

Ürküttü bütün kuşları da

Öfkeyi kollayarak sakin

Kalabilmenin zamanıdır

Biliriz ki bizimledir doğanın

Ve sevdanın gülümseyen sevinci

Ve onlar sahip çıkacaktır bize

Biz ki acılarla olgunlaştık

Biliriz kederi, kahrı ve zulmü

Aşkı ve hicranı da biliriz

Nice onmaz denilen yarayı

Acılarla sargılamadık mı

Ve ölesiye bağlıyızdır

Sevdamızı paylaşan

Uzak ve yakın dostlara

Ki ahde vefa denilen şey

Bizimle girmiştir kitaplara

Ama neler getireceğini yarının

Ve neler alacağını bizden

Hesaplamanın zamanıdır

Bel bağlayamayız çünkü

Feleğin ve zalimin insafına', 'Bir süredir kuşlar da yok Kentin bulanık göğünde  Dumanlı bir uğultu Uzayıp dururken sokaklarda Ürküttü bütün kuşları da Öfkeyi kollayarak s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yasanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilime', 'sevgilime-baris-tekin-0wx7z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Merhaba aşkım sana bu mektubu yazıp yazmamak konusunda inan cok düşündüm.

Bu  benim ilk ve son mektubum yazmayı sevmiyorum ve sevmeyeceyim.

neyse konuya gelelim

Özden seni çok seviyorum hemde benim bile tahmin edemeyeceyim kadar çok  herşey biranda oldu 

 Senin yakamı düzeltmen cana yakın davranışların ve daha birçok şey biranda beni sana bağladı.

Belkide cüzdanımın sende kalması ve senin alkol aldığın zaman herşeyi unutup bir çocuk gibi oluşun bana en çok yardımı olan bir kaç şeydi

AMA bunların hepsi beni korkutuyor sana olan sevgimin büyüklüğü altında ben eziliyorum 

Hayatım boyunca gerçek sevgiyi aradım aslında seni aradaım

Tamam ebruyuda seviyordum ama bu tam anlamıyla bir sevgi deyildi sadece vicdan azabı ve belkide biraz suçluluk duygusu 

O olaydan sonra hep kaçtım inasanlardan ve kendimden utandım dört sene bir yabani gibi yaşadım 

Ama sen  benim karşıma çıktın ve dört senede hisetmediyim bütün güzelikleri hisettirdin 

YA BİRBÜN SENDE ONUN GİBİ BENİ TERKEDİP GİDERSEN ! 

Sence ben buna dayana bilirmiyim yada nereye kadar dayanırım .

(sevgilini ölümle kaybetmekmi. yoksa o yaşarken o senin nefes aldığın havayı solurken onu kaybetmekimi insana dayanılmaz gelir ). Bence o yaşarken kaybetmek

Ben bunu istemiyorum  inan bunu kaldıramam 

Biliyorum sende büyük acılar çektin artık birşeylerden kurtulmak kaçmak istiyorsun biraz üzüntüleri kenara atıp mutlu olmak istiyorsun .

Ve bunu eminolki hak ediyorsun bende aynı şeyleri istiyorum ama olmuyor ben seni severken bile acı çekiyorum

Ben ne kadar büyük bir suç işledimki bunları yaşıyorum 

---------------ŞİMDİ SANA SORUYORUM .----------------------------

   Benimlemisin ?

   Beni gerçekten seviyormusun ?

   Ölüm olmadan benden ayrılırmısın ?

   Ve benim sevgimin büyüklüğüne inanıyormusun ?

------------------------------------------------------------------------

 Ben seninleyim seni çok seviyorum senden ölüm olmadan ayrılamam ve senin beni sevdiğine inanıyorum.

------------------Barış Tekin------------------------

Bir damla göz yaşı olmak isterdim.

Gözlerinde doğup.

Yanaklarından süzülerek.

Dudaklarında ÖLMEK için.

Seni seviyorum BEBEĞİM', 'Merhaba aşkım sana bu mektubu yazıp yazmamak konusunda inan cok düşündüm. Bu  benim ilk ve son mektubum yazmayı sevmiyorum ve sevmeyeceyim. ...', ARRAY['Türk Edebiyatı','Şiir','Barış Tekin']::text[], 8.5, '{"poet":"Barış Tekin","poet_slug":"baris-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevgilime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Geceler Kurşun', 'geceler-kursun-nurten-altinok-cuy78', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecelerin kurşun sağnağında

Korumasız

Sarmaş dolaş yaşadın mı hiç yalnızlığı

Bir şamar yüzünde dost eli

Umutların aynalarda kırıldığı

Geceler hüzün ebesi

Kan emici sülük misali

Kırçıl saçlarda öfke geceler

Göz altında mor halkaların belgesi

Geceler

Günahların sis perdesi

Geceler... ah geceler, ah', 'Gecelerin kurşun sağnağında Korumasız Sarmaş dolaş yaşadın mı hiç yalnızlığı Bir şamar yüzünde dost eli Umutların aynalarda kırıldığı Gecele...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geceler-kursun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Sevda Güç Değil', 'boyle-sevda-guc-degil-nurten-altinok-f261c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykusuz geceler

Yağmur yağıyor', 'Uykusuz geceler Yağmur yağıyor...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/boyle-sevda-guc-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gidiyor musun', 'gidiyor-musun-nurten-altinok-z68af', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyor musun

Ellerim açık kıbleye dönük dualarımda... kal

Gidiyor musun

Sıcaklığını kundakladığım sabah ezanlarında... kal

Gidiyor musun

Sensizliğin asılı bir gerdanlık gibi boynumda... kal 

Gidiyor musun 

Peşin sıra sürüklediğin umutlar 

Ayaklar altında

Dön de bir bak

Dön de bir bak

Sır duvarları nasıl yükseliyor yeni baştan ve

Karanlığın iki eli nasıl boynumda

Boğdu boğacak

Kocam gözlerimde korkular çaresiz

Titreyen ellerimde yüreğim

Kapım ağlıyor 

Çalınmayan

Yanmayan ışığım

Soframda aşım

Söyleyemediğim lafım

İçim ağlıyor 

İçim

Dön de bir bak

Gidiyor musun

Beni böyle bırakıp tek başıma

Gidiyor musun

Sevinçlerimi unufak eleyip

Gidebiliyor musun?', 'Gidiyor musun Ellerim açık kıbleye dönük dualarımda... kal Gidiyor musun Sıcaklığını kundakladığım sabah ezanlarında... kal Gidiyor musun Se...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gidiyor-musun-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yalnız Geceler', 'yalniz-geceler-nurten-altinok-wedi0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine yalnız geceleri oynuyorum kaderimle baş başa

Yine sessizliği / parçalarcasına / bu kaçıncı

Yine sen-siz-liği.. ah! tutamadığım

Paylaşmanın acısı  birde / kıskanıyor muyum yoksa

Dokunamadığım ellerin kimin avuçlarında

Bana ne? 

İçim içimi yiyor oysa

Bakamadığım gözlerin kimlere ayna

Kırılası diyorum parça parça

Gönlüm el vermiyor

Hadi gel

Hadi çık gel

Bu ileti

Bir davet değil

Üç güne

Beş güne

Yaşanmamışlara 

Yaşanacaklara

Yaşamın çatal ayrımında / kim bilir / dualar doğrultusunda

Zaman oyunu bizden yana kullanır belki

Amorti gibi sığındığımız mutluluk

Hadi gel

Bir çığlığa boğulmuşum

Suskunluğum alabora

Sabahlara sürgün gözlerimde

Kör olmuşum

Bulutlar ağlıyor bak yıldız kaymalarında

Hadi gel', 'Yine yalnız geceleri oynuyorum kaderimle baş başa Yine sessizliği / parçalarcasına / bu kaçıncı Yine sen-siz-liği.. ah! tutamadığım Paylaşma...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yalniz-geceler-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf Sevgi', 'saf-sevgi-ferit-ozcan-wcy7m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'cgül gönderiyorum

beyaz saflığın kırmızı ise

sevginin simgesi olduğu için', 'cgül gönderiyorum beyaz saflığın kırmızı ise sevginin simgesi olduğu için...', ARRAY['Türk Edebiyatı','Şiir','Ferit Özcan']::text[], 8.5, '{"poet":"Ferit Özcan","poet_slug":"ferit-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/saf-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sSonrası', 'ssonrasi-ferit-ozcan-kkjs7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'senden sonraki yaşamım

konusunu bilmediğim

fakat isimleri

hoşuma gittiği için

aldığım kitaplar gibi', 'senden sonraki yaşamım konusunu bilmediğim fakat isimleri hoşuma gittiği için aldığım kitaplar gibi...', ARRAY['Türk Edebiyatı','Şiir','Ferit Özcan']::text[], 8.5, '{"poet":"Ferit Özcan","poet_slug":"ferit-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ssonrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sensiz', 'hep-sensiz-ferit-ozcan-0llg9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni seviyordum

ve seni sevdiğimi sana söylerken

hep yanlış zamanlar seçiyordum

ismini bilmediğim filmler seyrederken

aşık oluyordum gözlerine

sözlerini bilmediğim şarkılar dinlerken

okşuyordum saçlarını

ve ben seni

hep sensiz seviyordum

bilmediğim sokaklarda geziniyordum

tesadüfler kolluyordum

hayatımın en olanaksız anlarından

her insan sana benziyordu

her kadın senden birşey almıştı

ve nedense karşıma çıkan 

hiçbir kadın sen olmuyordun

ben seni

hep sensiz seviyordum

biliyordum beni sevmiyordun

belkide hiçbir zaman sevmeyecektin

bense umutlarımı

yüreğimin en kuytusunda yeşertip

gözyaşlarımla suluyordum

ben seni

hep sensiz seviyordum', 'seni seviyordum ve seni sevdiğimi sana söylerken hep yanlış zamanlar seçiyordum ismini bilmediğim filmler seyrederken aşık oluyordum gözleri...', ARRAY['Türk Edebiyatı','Şiir','Ferit Özcan']::text[], 8.5, '{"poet":"Ferit Özcan","poet_slug":"ferit-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hep-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstümdeki Çardak', 'ustumdeki-cardak-caglar-yazici-gji61', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üstümdeki çardak görebildiðim tek þey,

Sadece yatyyorum burda.

Umarym seni hep özleyeceðimi anlarsyn

Ve umarym beni hep özlersin.

Ve umarym uyuduðunda hep bu zamanlary hatyrlarsyn

Ama ben sen yokken uyuyamyyorum

Sakyn uykuya dalan yorgun gözlerimi açma,

Onlar bana birlikte geçirdiðimiz zamanlary hatyrlatyyor

Sakyn açma gözlerini,

Onlar bana seni hatytrlatyyor..', 'Üstümdeki çardak görebildiðim tek þey, Sadece yatyyorum burda. Umarym seni hep özleyeceðimi anlarsyn Ve umarym beni hep özlersin. Ve umarym ...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Yazıcı']::text[], 8.5, '{"poet":"Cağlar Yazıcı","poet_slug":"caglar-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ustumdeki-cardak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Öyle', 'i-ste-oyle-erhan-baglarli-myo6q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülümün dikenine eller değmesin

Benden başkasına yüzü gülmesin

Gülüm sevda kokar

Kimse bilmesin

Kıymetini ben bilirim

Eller ne bilsin

Gülüm narin güldür

Yılda bir açar

Yüzü sevda saçar

Kalbi gül açar

Birgün gurbet elde 

Kalırsam naçar

Gülümün bahçesine 

Bülbül girmesin

Kıymetini ben bilrim

Eller ne bilsin

Gülüm bu son sözüm

Yalnız sanadır

Yalvarışım Yaradan''a duadır

Benimki sevda değil karasevdadır

Gülüm kıymetini bileni sen bil

Vazgeçilmezin olayım 

Hem sev hem sevil

(Beypazarı,13/06/2001)', 'Gülümün dikenine eller değmesin Benden başkasına yüzü gülmesin Gülüm sevda kokar Kimse bilmesin Kıymetini ben bilirim Eller ne bilsin Gülüm ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Bağlarlı']::text[], 8.5, '{"poet":"Erhan Bağlarlı","poet_slug":"erhan-baglarli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iste-oyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kız Beni Deli etti', 'bir-kiz-beni-deli-etti-nurol-banabak-zoqfy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tarafımdan silinip kaldırılmıştır / nb', 'tarafımdan silinip kaldırılmıştır / nb...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/bir-kiz-beni-deli-etti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim', 'duslerim-yildirim-yildirim-iqnjj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevda gördüm düşümde,

Düş buya, uyandım hep seni öpüşümde.

Yeniden daldım  rüyalara,düşümdeki gülüşünle; 

Ve sen ağlıyordun, aşkın için her ölüşümde.

İnci mi ne gözlerinden çağlayan! 

Bir kuru düşmüdür  beni sana bağlayan? 

Bir düşmüdür, kor ateşler gibi beni dağlayan

Düşlerim mi yoksa sen misin düşlerimde bana ağlayan.

Ağlama ağlama düşümdeki sevdam dayanamam,

Sen ağlarsan beyaz kefenden gayrısına boyanamam

Ağlama ağlama düşümdeki sevdam dayanamam.', 'Bir sevda gördüm düşümde, Düş buya, uyandım hep seni öpüşümde. Yeniden daldım  rüyalara,düşümdeki gülüşünle;  Ve sen ağlıyordun, aşkın için ...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Yıldırım']::text[], 8.5, '{"poet":"Yıldırım Yıldırım","poet_slug":"yildirim-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/duslerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar İçinden', 'anilar-i-cinden-sabahattin-yalkin-i94gb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tren Haydarpaşa''ya yaklaştıkça

Bütün İstanbul beni karşılıyacakmış sanki

Yüreğim ağzımda

Şimdi nerde çatık kaşlı Fikriye ?

Yamru yumru ara sokakların birinde

Aksaraydan yokuş yukarı Fatih''e çıkarken !

Laf attıkça nasıl da yumuşardı

Hele mahalleden uzaklaştıkça.

Ya Şehremini''li Zünnire 

Az mı bekletmişti beni söz verip de

Bildik yüzlere dönen tramvay durağında.

Çok oldu Kasımpaşa''lı Turan''ı görmeyeli

Odun sobalı küçük evlerinde

Hep sabahlardık sınav geceleri.

.............................................

.............................................

Sağlığı nasıl acaba ?

Satın alabildi mi kira evini.

İki kızı olmuştu sevimli mi sevimli,

Ya sen nasılsın sigara tiryakisi Nimet yengesi ?

Haydarpaşa bekleme boş yere

Ne yer, ne gök

Geldiğim gibi gidiyorum işte.....', 'Tren Haydarpaşa''ya yaklaştıkça Bütün İstanbul beni karşılıyacakmış sanki Yüreğim ağzımda Şimdi nerde çatık kaşlı Fikriye ? Yamru yumru ara s...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Yalkın']::text[], 8.5, '{"poet":"Sabahattin Yalkın","poet_slug":"sabahattin-yalkin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anilar-icinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Bitti', 'bahar-bitti-bayram-karaali-62fwx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baharım bitti; yaz başladı elini , verirmisin?

Ben baharları seninle yaşadım,yaz senindir,

Gönlüme hançer koymadım yıllarca  baharca,

Yazı sorma bana;kelime oyunu  dermisin?...

Temmuz; aşkımın adı oldu bilirsin  canım,

Alyanslarımızda yazanla özdeş vede kardeş,

Tarihler hatırlatır ya;nede sensiz ve bensiz,

Bir kadehimle sonsuz aşkına davet  seninim...

Ellerim ilk gün kadar terli,yüreğim uçuşmada,

Çeyrek asır oldu  ve ben heyecanlamadayım,

Haziran’ı bir ben bilirim,birde Temmuz   ayını,

Yüreğime yazdım,bir sen oldun orada  seninleyim...

16.Haziran.2001

 Bayram Karaalii', 'Baharım bitti; yaz başladı elini , verirmisin? Ben baharları seninle yaşadım,yaz senindir, Gönlüme hançer koymadım yıllarca  baharca, Yazı s...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bahar-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Aşk', 'bitmeyen-ask-bayram-karaali-2rhc5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece saat  24:00  bitmez bu gece  duyuyormusun?

Aşkımı anlatmak zordur benim için,seninle sonsuz,

Ellerini ver elime canımm.. uykum yine yok ,

Ve sen yine üzgün,çaresiz,umutsuz  yalnızsın.

Ve ben kıydım bu aşka;acımasız,edepsizce,

Ellerini esirgemedin benden,gözlerin hüzünlü,

Ağlarken bile,başını koynumdan esirgemedin,

Utandım  ben senden canım... baktığımda gözlerine..

16.Haziran.2001', 'Gece saat  24:00  bitmez bu gece  duyuyormusun? Aşkımı anlatmak zordur benim için,seninle sonsuz, Ellerini ver elime canımm.. uykum yine yok...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bitmeyen-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangimiz', 'hangimiz-esin-ruzgar-hdxbl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangimiz vardikki Hayatin tadina

Hangimiz bir Ömrü yikipta gectik

Neleri harcadik Sevda ugruna

Hangimiz Sevdadan cayipta gittik

Hangimiz Kalbinin Sesine uydu

Hangimiz Aklinla hareket etti

Hangimiz Askini aciga vurdu

Hangimiz Hisleri cigneyip gecti

Hayatin Selinde kim sürüklendi

Kimlere Mutluluk Günesi dogru

Kimlere umarsiz Dertler yüklendi

Seneler Kimleri neyi eskitti', 'Hangimiz vardikki Hayatin tadina Hangimiz bir Ömrü yikipta gectik Neleri harcadik Sevda ugruna Hangimiz Sevdadan cayipta gittik Hangimiz Kal...', ARRAY['Türk Edebiyatı','Şiir','Esin Rüzgar']::text[], 8.5, '{"poet":"Esin Rüzgar","poet_slug":"esin-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hangimiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-esin-ruzgar-9n29j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Prangalara vurulmus deli Yüregim

Caresizlik icinde kivranir durur

Acliga susuzluga dayanirimda

Hasretlik beni Can evimden vurur

Yüregim sevdali Bedenim Tutsak

Hangi tarafa baksam ne yapsam yasak

Benligimi aydinlatan isik gibisin

Sen uzakta degilsin yüregimdesin

Damarlarimda dolasan Cansuyum sensin

Cicekler Topraga,Yagmur Buluta

Yüregim Sevdama ,ben sana Tutsak', 'Prangalara vurulmus deli Yüregim Caresizlik icinde kivranir durur Acliga susuzluga dayanirimda Hasretlik beni Can evimden vurur Yüregim sevd...', ARRAY['Türk Edebiyatı','Şiir','Esin Rüzgar']::text[], 8.5, '{"poet":"Esin Rüzgar","poet_slug":"esin-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tutsak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-esin-ruzgar-azmbz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbime Sevdani saldinda gittin

Özlemler icinde koydunda gittin

Sensiz ben yarimim hep aklimdasin

Bir Sevda Masali oldunda gittin

Nerdesin kac Gündür sensiz olmuyor

Günlerim gecmiyor icim yaniyor

Sensizlik acisi hic cekilmiyor

Kara kara Sevdaya saldinda gittin

Yolunu gözlerim hergün ümitle

Her Dakika Hatiran zaten benimle

Zamanin kavrami kalmaz seninle

Sen benim Kalbimi caldinda gittin

Melekler Sesimi duyursun sana

Dilerim beni gör sende Rüyanda

Isterdim olmani yanibasimda

Yasama Sebebim oldunda gittin

Uzaktan uzaga bagladin beni

Nasilda sevdirdin bana kendini

Dilek tut deseler dilerdim seni

Hayalin Gözümde vardinda gittin', 'Kalbime Sevdani saldinda gittin Özlemler icinde koydunda gittin Sensiz ben yarimim hep aklimdasin Bir Sevda Masali oldunda gittin Nerdesin k...', ARRAY['Türk Edebiyatı','Şiir','Esin Rüzgar']::text[], 8.5, '{"poet":"Esin Rüzgar","poet_slug":"esin-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gittin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemim Sana', 'sitemim-sana-esin-ruzgar-c8ect', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Askin ile Gurbet ellerde kaldim

Bu ne bana bu ne bana bu Nazin

Careleri Türkülerde aradim

Burdan sana yetismiyorki Sözüm

Herkes kostu ben daha atmadan Adim

Bilmemki calmayi bende calsam Sazim

Kalbime bile gecmezken Sözüm

Seni Rüyalarda,Sarkilarda aradim

Hayatimda bir Sayfa iken 

Simdi bir Roman oldun

Ben deli divane iken

Sen kosmadan yoruldun

Zaman zaman aklimda 

Sen bir Bulmaca oldun

Oturdum cözmeye ama 

basaramadim

Dilimden Özlem Sarkilari hic düsmez oldu

Bazende söylerken Gözlerim doldu

Hani Askin sonsuza giden yoldu

Sen oldugun yerden bile kipirdamadin

Güllerden bir Demet yapayim dedim

Ben artik keyfime bakayim dedim

Dikenler sivriymis acidi Elim

Senden baska Gül koklayamadim', 'Askin ile Gurbet ellerde kaldim Bu ne bana bu ne bana bu Nazin Careleri Türkülerde aradim Burdan sana yetismiyorki Sözüm Herkes kostu ben da...', ARRAY['Türk Edebiyatı','Şiir','Esin Rüzgar']::text[], 8.5, '{"poet":"Esin Rüzgar","poet_slug":"esin-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sitemim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kalbimdesin', 'sen-kalbimdesin-esin-ruzgar-iwb4y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürekten gelir hani Duygular

Satirlara dökmek istersin

Zaman gelir canin önemi kalmaz

Ama Yardan vazgecemezsin

En büyük Düsmanin Sana Yüregin olur

Firtinalar koparir engelleyemezsin

Ilk kez tatmisindir bu Duyguyu 

Zaman zaman isyan edenlerdensin

Gözyasin birikip icine akar

Belkide en fazla aglayanlardansin

Güldügün anlarda olacak elbette

Sonucta sende bir Insansin

Istemezsin Yare actigin Gözlerin

Yari görmeden kapansin

Sakin Kadere sitem edeyim deme

Birakta Felek utansin

Hani farkinda olmadanbazen

Düsünceye dalarsin

Dertlerin Denizinde 

Bogulacan sanirsin

Kivrandikca daha cok batar 

bir türlü kurtulamazsin

Careyi Hayallerde Umutlarda ararsin

Yanlizlarin yanlizi Sen

Bende hep var olansin

Sen herseyden vazgectigim anda

Tek geriye kalansin', 'Yürekten gelir hani Duygular Satirlara dökmek istersin Zaman gelir canin önemi kalmaz Ama Yardan vazgecemezsin En büyük Düsmanin Sana Yüregi...', ARRAY['Türk Edebiyatı','Şiir','Esin Rüzgar']::text[], 8.5, '{"poet":"Esin Rüzgar","poet_slug":"esin-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-kalbimdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Dedigin', 'sevgi-dedigin-esin-ruzgar-eom8f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kolayca kurulmaz Dostluk dedigin

Dostluk hem Özveri hem Yürek ister

Canim cicimle olmaz Sohbet herzaman

Dostlukta Dertleri paylasmak ister

Her zaman gülmeyi bekleyemezsin

Bazende birlikte aglamak ister

Sokakta bulunmaz Sevgi dedigin

Önce bir Gönülü kazanmak ister

Kolaymi sanirsin Kalbe girmeyi

Elbette her Insan sevilmek ister', 'Kolayca kurulmaz Dostluk dedigin Dostluk hem Özveri hem Yürek ister Canim cicimle olmaz Sohbet herzaman Dostlukta Dertleri paylasmak ister H...', ARRAY['Türk Edebiyatı','Şiir','Esin Rüzgar']::text[], 8.5, '{"poet":"Esin Rüzgar","poet_slug":"esin-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgi-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heves', 'heves-esin-ruzgar-nvj01', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hevestir deyip gecme

Gün gelir yanilirsin

Onsuz yasanmadigini

Cok gec iken anlarsin

O baskasini bulur

Seni cabuk unutur

Olanlar sana olur

Kendini aldatirsin

Unutayim istersin

Ondan vazgecemezsin

Onu her gördügünde

Kalbinden vurulursun', 'Hevestir deyip gecme Gün gelir yanilirsin Onsuz yasanmadigini Cok gec iken anlarsin O baskasini bulur Seni cabuk unutur Olanlar sana olur Ke...', ARRAY['Türk Edebiyatı','Şiir','Esin Rüzgar']::text[], 8.5, '{"poet":"Esin Rüzgar","poet_slug":"esin-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/heves-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katil', 'katil-arif-nihat-asya-2ut0u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen de  bilirsin ki, iki  kurşunla; 

Bana  kolay  kolay  gelmezdi  ölüm.

İstedim ki  sana  ''kaatil''  desinler:

Bunun''çin  öldüm.', 'Sen de  bilirsin ki, iki  kurşunla;  Bana  kolay  kolay  gelmezdi  ölüm. İstedim ki  sana  ''kaatil''  desinler: Bunun''çin  öldüm....', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/katil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Gözlerin', 'ah-gozlerin-esin-ruzgar-mioce', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah o Gözlerin varya

Senin en güzel tarafin

O güzel Gözlerin varya

Senin en büyük Silahin

Zaman zaman sitem dolu

Cogu zaman Sevgi dolu

Hüzünlüyken dolu dolu

Olur gider Bakislarin

O Karagözlerin varya

Karanliklar kadar derin

Yildizli Geceler gibi

Sevdigim senin Gözlerin

Bir Damla Gözyasi kayar

Gözlerinden güzel Yarin

Bugulanir dalar gider

Uzaklara derin derin

Bazen bir Sarki söylerler

Müziksiz Sözsüz bir Sarki

Dile getirirler sanki

Sendeki Siiri Aski

Evet Gözler Sarki söyler

Siir okur,aglar,güler

Ama Gözleri hic bir zaman

Asla yalan söylemezler', 'Ah o Gözlerin varya Senin en güzel tarafin O güzel Gözlerin varya Senin en büyük Silahin Zaman zaman sitem dolu Cogu zaman Sevgi dolu Hüzünl...', ARRAY['Türk Edebiyatı','Şiir','Esin Rüzgar']::text[], 8.5, '{"poet":"Esin Rüzgar","poet_slug":"esin-ruzgar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ah-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpmek', 'opmek-arif-nihat-asya-7kyh3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanaklar  öpmedesin, öptürüp  yanaklarını; 

Böyle  geçsin  bu  günlerin  varsın.

Sen  ey  çocuk! Öpülüp  öpmenin  ne  olduğunu; 

Dudaklarında  dudaklar  duyunca  anlarsın!', 'Yanaklar  öpmedesin, öptürüp  yanaklarını;  Böyle  geçsin  bu  günlerin  varsın. Sen  ey  çocuk! Öpülüp  öpmenin  ne  olduğunu;  Dudaklarınd...', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/opmek-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Yedi Haziran', 'on-yedi-haziran-nurol-banabak-nsmx0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tarafımdan silinip kaldırılmıştır./nb', 'tarafımdan silinip kaldırılmıştır./nb...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/on-yedi-haziran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi', 'geceyi-muhtalip-turkmen-b256q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceyi yırtabilsem

Boğabilsem 

Karanlığı ellerimle

Buluttan kanatlarım olsa

Açabilsem ufkunuza

Her birinizin

Ve dostluk

Ve sevgi

Ve barış 

Ve özgürlük

Ve ................

Ve ................

Ve aşk yağdırabisem yüreklerinize.', 'Geceyi yırtabilsem Boğabilsem  Karanlığı ellerimle Buluttan kanatlarım olsa Açabilsem ufkunuza Her birinizin Ve dostluk Ve sevgi Ve barış  V...', ARRAY['Türk Edebiyatı','Şiir','Muhtalip Türkmen']::text[], 8.5, '{"poet":"Muhtalip Türkmen","poet_slug":"muhtalip-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geceyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızları', 'yildizlari-muhtalip-turkmen-e8k9q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızları tutmalı

Yıldızları diyorum,

Birer birer almalı gökyüzünden,

Işıklarını, Aşkın imbiğinden geçirmeli.

Damla damla,

Ve sonra,

Barış katmalı,

Sevgi katmalı,

Özgürlük eklemeli yüreğimizden,

Daha sonra diyorum,

Bir merdiven yapmalı

Bütün bunlardan

Ve ulaşmalı güneşe

Toplamalı,altın sarısı saçlarını,

Bir sevgilinin saçlarını toplar gibi

Öpmeli,koklamalı,

Ve sonra

Savurmalı bir anda 

Tüm karanlıkların üstüne  kcaklar dolusu', 'Yıldızları tutmalı Yıldızları diyorum, Birer birer almalı gökyüzünden, Işıklarını, Aşkın imbiğinden geçirmeli. Damla damla, Ve sonra, Barış ...', ARRAY['Türk Edebiyatı','Şiir','Muhtalip Türkmen']::text[], 8.5, '{"poet":"Muhtalip Türkmen","poet_slug":"muhtalip-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yildizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Ettin Neler', 'neler-ettin-neler-bayram-tunca-7v5cb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ettin/ettin mükâfatı çoktan hak ettin

Yaşattığın az aşkla saçlarımı ak ettin

Çektirdiğin çileyle canıma tak ettirdin

Çile çektirmede sanki dünyada tektin

Ettiklerin beni deli divaneye döndürdü

Gözyaşlarım değirmen taşını döndürdü

Senin gibileri ne aile ocakları söndürdü

Senin gibileri yârini toprağa gömdürdü

Gözyaşlarım, yanar dağları söndürürdü

Ağıtlarım duyanı Mecnun''a döndürürdü

O zehirin en güçlü yiğidi bile öldürürdü

Bir başkası olsaydı inan seni öldürürdü

Yoldurdun yoldurdun, saç/baş yoldurdun

Soldurdun soldurdun, benzimi soldurdun

Azıcık çileli aşkla ahir ömrümü doldurdun

Bir tomurcuk gülken, örseleyip soldurdun

Daha genç yaşta deli gömleğini giydirdin

Genç yaşta boynumu öksüz gibi eğdirdin

Feryadı figanımı, taa arş-ı âlâya değdirdin

Kırdın kolumu kanadımı ta yere değdirdin

Hak ettin/hak ettin, en iyi ödülü hak ettin

Mükâfatını bulamadım, O’na havale ettim

Madem başta sevdin niye sonra terk ettin

Terk etmekle, öldürmekten de beter ettin

Gözyaşlarımla sineme kurşun döktürttün

Yıllarca, sen bana sayısız kök söktürttün

Saçlarımı daha güz gelmeden döktürttün

En son şair yapıp, içimi böyle döktürttün

Akan gözyaşımla, sinemde kurşun erittirdin

Aylar-yıllarca çok kefensiz gömlek giydirttin

Hayatımda kaç kez öldürüp öldürüp dirilttin

Her şeye rağmen yine de kendini sevdirttin

19.06.2001-11:35', 'Ettin/ettin mükâfatı çoktan hak ettin Yaşattığın az aşkla saçlarımı ak ettin Çektirdiğin çileyle canıma tak ettirdin Çile çektirmede sanki d...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/neler-ettin-neler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babalar Günü*', 'babalar-gunu-bayram-tunca-r6a6a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah bak yine bugün babalar günü

Babası olana en iyi bayram günü

Öksüz ve yetim olana hüzün günü

Bugün kimine yaz kimine kış günü

Bugün, kiminin bahar, kiminin güz günü

Kimi babanın düğün, kimininse acı günü

Babası olanların, neşe ve mutluluk günü

Şair gibi yetim olanların da kederli günü

Ben de isterdim, babama bir hediye almak

Babam deyip, elini öpüp, boynuna sarılmak

Ne edem, kaderde varmış babayla ayrılmak

Ne edeyim, kaderimmiş bugün yetim olmak

Ne edem kaderde varmış, acıyla yoğrulmak

Hayat mücadelesinde varmış çok yorulmak

Hayat nedir ki iki nefes arasındaki yaşamak

Hem şaire yakışmaz ki daha fazla bağırmak

Hem, her şeyi veren de  alan da O değil mi

Hem mülk O’nundur, istediğini yapamaz mı

Elbette yapar, ve yapıyor, kim ne diyebilir ki

Şair Bayram da, kader mahkumu değil mi ki

Babası olanlar, babasının kıymetini bilsinler

İnan ki babasının bir dediğini iki etmesinler 

Hediye yerine sıcak bir buse versinler yeter

Babacığım, evimizin direğisin desinler yeter

Yoksa, hayatta babasızlık ölümden de beter

Ölmeseydi peder, olur muydum böyle heder

Baba olsam da aklımdan hiç çıkmıyor peder

Her baba, evladına kızsa bile onu çok sever

Sevmeselerdi, verebilirler miydi ömürlerini

Sevmeselerdi, verebilirler miydi servetlerini

Onlar aileleri için verirler bütün servetlerini

Onlar, yüreklerinde gizlerler aile sevgilerini

Bütün babaların, babalar günü kutlu olsun

Babaların mutluluğuyla evler neşeyle dolsun

Bu evlerin her biri cennet bahçesi gibi olsun

O an ülkemizde her gün babalar günü olsun

16.06.2001-17.35', 'Ah bak yine bugün babalar günü Babası olana en iyi bayram günü Öksüz ve yetim olana hüzün günü Bugün kimine yaz kimine kış günü Bugün, kimin...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/babalar-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükendi', 'tukendi-bayram-tunca-6hor5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaza yaza defterinin sayfaları tükendi

Yaza yaza kelimelerin heceleri tükendi

Yaza yaza parmağının dermanı tükendi

Yaza yaza kaleminin mürekkebi tükendi

Sensiz yatağı, yorganı, yolu hep dikendi

Bağırmaktan sesi kısılıp, nefesi tükendi

Hasretle, ağlaya ağlaya gözyaşı tükendi

Bekleye bekleye de şairin ömrü tükendi

Yollarına baka baka gözünün feri tükendi

Hasretinden, ter döke döke terleri tükendi

Senin için dünyayı dolaşıp serveti tükendi

Servet nedir ki; beklemekten ömrü tükendi

Hülyalarında konuk etti seni hep yıllarca

Hasretin mesken oldu, gönlünde yıllarca

Şair Bayram beklemektedir, seni yıllarca

Yine de niyeti beklemektir ömrü boyunca

Ne zaman bitse vuslat, sevinir dünyalarca

Bil ki o hep hasretten yandı ömür boyunca

İnanki biter onun hasreti sana kavuşunca

Şair Bayram ne çekilmezleri çekti yıllarca

Hasretten önce gençliği, sonra ömrü tükendi

Önce hayali, sonra da ümitleri bir bir tükendi

Sensiz hayat, sanki ona her an batan dikendi

Başkasını bilmem ama o gerçek çile çekendi

B. TUNCA/12.06.2001-16.45', 'Yaza yaza defterinin sayfaları tükendi Yaza yaza kelimelerin heceleri tükendi Yaza yaza parmağının dermanı tükendi Yaza yaza kaleminin mürek...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tukendi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem (Adana Ceyhan)', 'deprem-adana-ceyhan-bayram-tunca-mt2pg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylardan haziran, günlerden cumartesiydi

Hava da sanki cehennem sıcağı gibi sıcaktı

Bir uğultuyla dolu yağıyor gibi patırtı koptu

Korkudan sanki bütün insanların ödü koptu

O gün insanlar, sağa/sola kaçacak deniyordu

O gün, aynen öyle oldu, sanki kıyamet koptu

Ana, baba, çocuk, sevenler birbirinden koptu

İnsanlar, canı canânı bırakacak kadar korktu

Şair der; ‘büyük musibetler hep umuma gelir’

Geldiğinde masum cani ayırt etmeyerek gelir

Zengin-fakiri, genç-ihtiyarı, kayırmadan gelir

İmtihan sırrı bozulmasın diye hep böyle gelir

Deprem bu kez de Adana ve çevresini salladı

Hiç de zengin misin, fakir misin diye sormadı

Hiç kimseyi istisna edip, ayrı kefeye koymadı

Yüzlerce insanın canını aldı, yine de doymadı

O gün sanki, burada küçük kıyamet kopmuştu

Bütün herkes, sağa sola kaçışmaya çalışıyordu

Ambulanslar siren, arabalar da korna çalıyordu

Deprem şokunu atlatabilen akrabasını arıyordu

Yollar trafikten kilitlenmiş, insan yaya gidiyordu

Adem, kaldırımdan ziyade, cadde de yürüyordu

Feryad-ü figan eden, matemli havayı artırıyordu

Kesildi elektrik/telefon, hiçbir yerle irtibat yoktu

İlk defa ben de kendi erkekliğimden şüphe ettim

Çünkü ben de ilk defa böyle bir deprem yaşadım

O dükkandan çıkar çıkmaz, insan seline kapıldım

İstemeyerek de olsa, eşim çocuğumdan ayrıldım

Adanalı günlerce endişeyle yatıp, korkuyla kalktı

Bazı insanlar artçı depremlerde kendini yere attı

Yüzlercesi yaralanıp, aylarca da hastanede yattı

Adana depremi, bazı insanlar için kara bir bahttı

Deprem bu sefer de Adana ve ilçelerini seçmişti

Adana depreminin şiddeti, ''6.02'' kuvvetine eşti

Ölenlerin sayısı “146” yaralıların sayısı bini geçti

Adana Ceyhan depremi işte böylece tarihe geçti

Şair Bayram der; bu depremden bari ibret alına

Milletçe bu hususta verilen sözlere sadık kalına

Çürük yapılaşmayla kıymayalım insanın canına

Aksi halde hiç yakışır mı Türk Milletinin şanına

B.TUNCA/15.05.2000', 'Aylardan haziran, günlerden cumartesiydi Hava da sanki cehennem sıcağı gibi sıcaktı Bir uğultuyla dolu yağıyor gibi patırtı koptu Korkudan s...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/deprem-adana-ceyhan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Defa', 'i-lk-defa-selami-simsek-1szzp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece sırlarla dolu sanki

Yanliz kaldım seni özledim

Hayret...

Uzaktan sevmeyi isterdim halbuki

İlk defa yanimda olmani istedim

Bu gece sırlarla dolu sanki

Ask mızrağının saplandığı kalbim

Durmuyor yerinde, düşlüyor afaki

İlk defa gönül yarami sarmanı istedim

Bu gece sırlarla dolu sanki

Hülyalar aralaniyor görüyor gözlerim

Adim atsam tutacağım belki

İlk defa ellerimi tutmani istedim

Bu gece sırlarla dolu sanki

Bogazda düğümlenir sevda şiirlerim

Kafeste mahkum kuşlar gibi

İlk defa beni dinlemeni istedim', 'Bu gece sırlarla dolu sanki Yanliz kaldım seni özledim Hayret... Uzaktan sevmeyi isterdim halbuki İlk defa yanimda olmani istedim Bu gece sı...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ilk-defa-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-selami-simsek-58mwo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani nerde kaldı nerde anılar

Söyleyin yaşanmadı mı yoksa o anlar

Gönlüm hala o yılların iklimine hüşyar

Keşke yanımda olsaydın sevgili yar

Kalbimin gül bahcesi o mutlu yıllar

Ruhumun derinliğinde  taptaze yaşar

Hayat mı bana, yoksa ben mi ona dar

Keske yanımda olsaydın sevgili yar

Heyhat iste yine, yine mevsim sonbahar

Benim gibi sanki ağaçlarda ağlar

Gözlerimden yaş değil sanki anılar akar

Keske yanimda olsaydın sevgili yar

Sürer mi dersin akasyam bu sonsuza kadar

Ümit yok mu gelmez mi acaba bahar

Belki bize de  rahmet olur yağmurlar

Tasalanma akasyam bak orada umutlar

Ulaşacak mutlaka sana güneşten ışınlar

Bana da sürayya kokulu o sevgili yar...', 'Hani nerde kaldı nerde anılar Söyleyin yaşanmadı mı yoksa o anlar Gönlüm hala o yılların iklimine hüşyar Keşke yanımda olsaydın sevgili yar ...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anilar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Yanlızlığı', 'bayram-yanlizligi-selami-simsek-021wn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün herkese şenlik bayram

Her yerde düğün seyran

Güneş, mavi gök

Sonra ay ve yıldızlar

Bunlardı sadece hatırı mı soran

 

Merhaba dedi bay alman

Yokmu size bugün bayram

Var dedim dün size bugün bize

Tebrikleştik öyle hayran hayran

 

Sabah oldu dedim telefon açam

Bir, iki, on, öğlen akşam...

Beyinde sorumluluk, kalpte hasret

Ey yanliz ruh! Nafile kendini yorman...', 'Bugün herkese şenlik bayram Her yerde düğün seyran Güneş, mavi gök Sonra ay ve yıldızlar Bunlardı sadece hatırı mı soran   Merhaba dedi bay ...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bayram-yanlizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sembol Aşk', 'sembol-ask-selami-simsek-6zza5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yine gecelerle başbaşayım

bu gece farklı ama, bir başkayım

umutlar soluk, hayaller yıkık

sanki bu gece yastayım

saat gecenin üçü oldu

üçüncü küllüğümde doldu

uyku tutmadı gözlerimi

hüznüm bu şiir oldu

oysaki! oysaki!

ne güzel başlamıştı bu şarkı

güneşin denize göz kırpması

yıllar varki ışık yüzü görmemiş

yakamozların sevinç dansı

senelerdir yagmura hasret kalmış

toprağın damlalarla kucaklaşması

işte yıllardır aradağım şey

gönlümü dolduran 

ruhumu umutlandıran

hayallerime kanat olan

aradağım şey, işte bu şey

yine mi sen sahte şafak

neden bana bu düşmanlığın

bu kaçıncı aldatışın

farkındamısın vediğin acının

yoksa bana sembol aşk da mı yasak!

heyhat! yine yanıldım

yıllar öncesi gibi

kursagımda kaldı umutlarım

yagmurkızı öldü sanki

şarkım sana ne oldu aniden

neden hüzünlendin birden

halbuki ne neşeli başlamıştın

yoksa seninde mi var sembol aşkın

anlıyorum seni şarkım

sende benim gibi yıkıldın

ama boş ver hayat devam ediyor

gör bak farklı olacak yarın...

stuttgart  12.02.2001', 'yine gecelerle başbaşayım bu gece farklı ama, bir başkayım umutlar soluk, hayaller yıkık sanki bu gece yastayım saat gecenin üçü oldu üçüncü...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sembol-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-selami-simsek-vbn8w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gittin...

Bir elveda demeden

Gittin...

Arkana bile bakmadan

Hic anlamadın halimi

Susukunluğumun nedenini

Hic anlamadın...

Ayrılışın hançerledi kalbimi

Annenin yavrusunu kaybedişi gibi

Bende seni kaybettim

Yaşamıyorum sanki o andan beri

Biliyorum sevmemeliydim belki

Gönül vermemeliydim ötelere bu kadar

Yüksekte tutmamalıydım özlemlerimi 

Ruhum uzaklarda süreyyada seni arar

Duygularım ne yapsın dünya cok dar

 

Hani umutsuz sevgiler vardırya

Gülün bülbüle, bülbülün güle aşkı gibi

Benim askımda işte öyle sanki

Işınları ulaşır yüreğimin ortasına 

O cok uzakta ama, 

Kucaklayamam bedenini

Tıpkı bülbülün gülü kucaklayamadığı gibi

İşte sen o ışık hüzmesiydin sevgilimin

Gercek oldu sanki hayallerim

Yagmurla birlikte gelip gönlümü aydınlatan

Yüreğime taht kuran

Ayağıma fer, ruhuma kanat olan

Seninle avundum bir zaman

Ne olduysa birden o an

Umutlarım soldu, kalbimde hüsran

Firdevs kokulum başka yamaçlarda, vay aman!

 

Neler oluyor sana

Kayıyor gibisin baska diyarlara

Süreyyadan gelen sen değilmisin yoksa

Umutlarim kaldı yine yarınlara

 

Yine yıkıldı hayallerim

Boynu bükük kaldı ümitlerim

Belkide ben istedim, sen hisssettin

Bir elvada demeden

Sırtını dönüp çekip gittin

 

Sensiz geceler şimdi bir virane gibi

Gel yeniden güneşim ol

Bir daha üzmem seni

Gel yeniden damlalar halinde 

Gir sineme gizemli emanet ol !

27.02.2001', 'Gittin... Bir elveda demeden Gittin... Arkana bile bakmadan Hic anlamadın halimi Susukunluğumun nedenini Hic anlamadın... Ayrılışın hançerle...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gittin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Söz Vermiştik', 'hani-soz-vermistik-selami-simsek-zs6c6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani söz vermiştik

Ayrılmayacaktık sonsuza kadar

Yırtılsa da gökkubbe

Çöksede yerküre

Emr-i Hak gelene kadar

 

Hani söz vermiştik

Karıncalar yaprağı taşırken

Biz de dünyayı taşıyacaktık

Elele verip sözleşmiştik

Tüm dertlere göğüs gererek

Tarlamıza ümit ekecektik

Hiç üşenmeden

Hiç yeter demeyerek

 

Hani söz vermiştik

Zirvelere çikacaktık

Sarp yokuş dinlemeyerek

Karları eritecektik

Damarlarımızdaki sevgiyi üfleyerek

 

Evimizi orada kuracak

Etrafını saracaktık

Tüm haşarat ve kötülüğe set

Cennet atmosferine denk

Güller yetiştirecektik rengarenk

Gönlümüzde olduğu gibi

Bahçemizde de bir ahenk

Hülyalar alemine nispet

 

Hani söz vermiştik

Yağmurla ilk biz kucaklaşacaktık

Damla damla hissederek

Hatta sayacaktık

Kac damlayla öpüştük 

Kendimizden geçerek

 

Sonra gözlerimizi kapatıp

Ay çiçeğine özenerek

Güneşi bekleyecektik

Gülümsediğinde yüzümüze nur parcası

Acacaktık göz kapağımızı

Selam verecektik güneşe

Sevinç gözyaşlarımızı dökerek

 

 Hele gökkuşağı çıktığında

Ona ilk biz dokunacaktık

İlk biz sevişecektik onunla

Renklerine bürünerek

Ben mavi, sen sarı

Ben yeşil, sen kırmızı

Hayallerimiz pembe olacaktı

Rüyalar ülkesine yelken açacaktık

Kanatlarımızı sonuna kadar gererek

 

Ya simdi !!

Sen orada sürayyanın yanında

Ben ise yapayanlız, dünyada

Hayatın karşı konulmaz mücadele arenasında

Her seye dayanırım ama

Sensizliğe varya asla!!

Tek sevincim seninle geçirdiğim

Bitmesini istemediğim saniyelerim

Bu sadece düşlerde de olsa!

05.04.2001 Stuttgart', 'Hani söz vermiştik Ayrılmayacaktık sonsuza kadar Yırtılsa da gökkubbe Çöksede yerküre Emr-i Hak gelene kadar   Hani söz vermiştik Karıncalar...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/hani-soz-vermistik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumdan Bir Sayfa', 'cocuklugumdan-bir-sayfa-selami-simsek-dn4nj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocukluğumu hatırladım birden

Yaşadım sanki o günleri yeniden

Saf, duru, tertemiz günlerdi

Tıpkı su gibi mineralden

 

Kırlara koşardık her pazar

Bahar geldiğinde

Çiçekler toplardık

Hediye etmek için annemize

Yemlik arardık samanda iğne gibi

Çayırların içinde

Bulduğumuzda sevinir

Bir güzel yerdik afiyetle

 

Sonra aramızda takım kurar

Top oynardık ölesiye

Ne goller atardım

Ne kafa ne röveşata golleri öyle

Halbuki hiç düşünmemişim

Topu gönderirken kaleye

Asıl golleri ben yiyecekmişim

Son bir kaç hüzünlü yıl içinde

 

Bir paşa oğlu Hüseyin vardı

Boyu en az bir doksan kadardı

Nedense hep rakip olurduk oyunda

Top geldiğinde bana

Bitiverirdi hemen yanı başımda

Başımı kaldırdığımda

Sanki kavak ağacı vardı karşımda

Yine de çalımlardım onu

Yüzde doksan oranında

Çalımlardım çalımlamasına ama

Arkadan çelme takar

İndirirdi beni çayıra

Basım yerde, ayaklarım havada

Unutamam o toprakları

Kokusu hala burnumda

 

Her molekülünü gözüme sürme çektiğim toprağım

Atalarımın, dadaşımın kanıyla yıkanmış toprağım

Doğarken nikâhlandığım ölümümde kundağım

İnanıyorum ki senden geliyordu

O saflık o duruluk o haya

Hayatımın bu altın çağında

 

Neyse; gelelim yine çocukluk günlerimize

Akşam olup eve döndüğümüzde

Otururduk hemen televizyon başına

Uyuklardık kesin, filmin tam ortasında

 

Ertesi gün pazartesi,

Okulda ders bası

Heyecan sarardı hepimizi

Önce merasim olurdu

Okurduk hep bir ağızdan istiklal marsımızı

Sonra sınıflara girer

Beklerdik öğretmenimizi

Geldiğinde ayağı kalkar

Söylerdik o tuhaf andımızı

 

Ben en çok matematiği severdim

Çünkü en çok o dersi bilirdim

Bir problem yazıldığında tahtaya

Durmaz kendiliğinden kalkardı elim

 

Ahlak dersini hiç sevmezdim

Fark ederdi bunu tabi öğretmenim

Nedense çok sıkıcı gelirdi bu ders bana

Belki de annemin karnında öğrendiğim için

Hatta küfür atmasını bile beceremezdim

Gerçi şimdi de halen atamam ya! 

 

Böyle devam ederdi okul bir hafta boyunca

İste geldi çattı bugün cuma

Defter kitabı attığımızda odamıza

Kendimizi bir solukta atardık sokağa

Hemen iki kale kurar taşlarla

Başlardık top oynamaya

 

Akşam olduğunda herkeste bir sızı 

Anneler çağırıyor yemek zamanı

Otururduk hep beraber sofra başına

İçerdik çorbalarımızı öyle hızlı hızlı

Sonra çaylarımızı yudumlar

Annemizin gözünün içine baka baka

Kaçardık tekrar buluşma noktasına

Saklambaç oynardık o gece doyasıya

Eve geç gelir, sıradan geçilirdik dayağa

Sabah olduğunda

Uykumun en tatlı anında

Bir ses!  abimin sesi. 

Çavuş sesi gibi

Hey SELAMİ! ! ! ! 

Kalk artık ayağa! 

Bir sürü iş var dükkanda

Çaresiz kalkardım

Çünkü dayak var işin ucunda 

O gün hep çalışır

Katkıda bulunurdum nafakamıza

  

İşte çocukluğumdan bir sayfa

Simdi dönüp bakıyorum da arkaya

Hüzünlenip ahh çekiyorum

Keşke diyorum 

Hep çocuk kalsaydım, hep çocuk! 

Büyümeseydim keşke

Böyle kahpe hayatla tanışacağıma

Ne işin vardı sanki senin Almanya''da! ! ! 

12.04.2001 Stuttgart', 'Çocukluğumu hatırladım birden Yaşadım sanki o günleri yeniden Saf, duru, tertemiz günlerdi Tıpkı su gibi mineralden   Kırlara koşardık her p...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/cocuklugumdan-bir-sayfa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Duyguları', 'gurbet-duygulari-selami-simsek-wah5x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gurbette dert yüklüdür kapalı akşamlar

Yağmur değil sanki kurşun bırakır bulutlar

Girer bedene saplanır kalp merceğine

Gerçekler ütopya, hayaller gerçek olurlar

Gurbette hazan vaktidir geceler

Herkes yareniyle, çocuklarıyla beraber

Yanlızlık sadece Allah’a göre 

Sahipliler neşe içinde sahipsizler iç çeker

Gurbette düş kırıklığıdır sabahlar

Yalanmıydı? az önce yaşananlar

Yavrular, ana, baba vede yar

Hani nerde?

Aldanış zaten garibe göre

Sende aldatmışsın ne gam! hain rüyalar !

Gurbette duygu fukarasıdır güneşsiz günler

İki lokma ekmeğe çalışır kurumuş bedenler

Vuslat yoksa hele gün bitiminde

Yorgunluk katman katman, batmanlara eşdeger

Gurbette deli doludur duygular

Mantıga değil hislere ayarlılar

Her şey karmakarışık, her şey iç içe

Ömür kötürüm, dünya kördüğüm, hayat cefakar

Gurbette sıradandır kendi kendine gülmeler

Hayalde tugrul ve efşan, elde resimler

Hani nerede? bahar kokan, yüz çizen

Nerede? saçları okşayıp çeken minicik eller

Gurbette daha da hüzünlü çalar şarkılar

Mızrak saza değil kalp teline hüşyar

Anılar tüllenir, hasret buğulanır gözlerde

Nağmeler kırık, sözler yıkık, gönül sitemkar

Gurbette arkadaş gönül yapıcıdır canan kadar

Açar evini, verir neyi varsa vereceği, sineye ümit saçar

Hele seksen santimlik masa sohbetlerinde

Doyumsuz dostluk türküsü, ruhlar sevgi soluklar...

27.04.2001 Stuttgart', 'Gurbette dert yüklüdür kapalı akşamlar Yağmur değil sanki kurşun bırakır bulutlar Girer bedene saplanır kalp merceğine Gerçekler ütopya, hay...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gurbet-duygulari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Sevdam', 'sakli-sevdam-selami-simsek-30av0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen şimdi varsın ya

Dünya manasız, yaşam sıradan

Sen gönlüme doldun ya

Boşalır damarımdan  mavisiz kan 

...

Sen canıma can oldun ya

Ruhumda düğün bayram

Sen damarımda kan oldun ya

Bedenimde cümbüş seyran

........

Sen ufuktan doğdun ya 

Sinemde sonsuz bir heyecan

Her yerimi  kapladın ya

Korku ve endişe tekrar batmandan

....

Sen bahçede çiçek açtınya

Bulutlar ak, yagmurlar daha saydam

Sen güneşe göz kırptınya

O şimdi daha berrak, daha yakmayan

....

Sen notalı selam verdinya

Kus nağmeli şarkılardan

Sen bir gülsün ya

Bülbüle kanat olur hoş sedan

...

Sen bir gizemsin ya

Baska kimse yok anlayan

Sende kimsin bilmiyorsun ya

Sen benim saklı sevdam

14.05.2001 Stuttgart', 'Sen şimdi varsın ya Dünya manasız, yaşam sıradan Sen gönlüme doldun ya Boşalır damarımdan  mavisiz kan  ... Sen canıma can oldun ya Ruhumda ...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sakli-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-akin-kir-4cwqq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşka dair bir şiir süzülür dudaklarımdan.

Büyük bir sevda vardır içinde.

Bir damla yaş düşer ardından, 

Ruhunu kaplayan hüzünle.

Öyle bir aşk ki bu, yalnızlığımı dolduran, 

Dayanamam kesinlikle sensizliğe.

Hissetmek için birşeyler varlığından, 

Yastığıma sarılırım her gece.

Aşka dair bir şiir süzüldü dudaklarımdan

Ve sen vardın içinde.

Şimdi ağlıyorum yokluğundan, 

Sana kavuşacağımı bilsemde', 'Aşka dair bir şiir süzülür dudaklarımdan. Büyük bir sevda vardır içinde. Bir damla yaş düşer ardından,  Ruhunu kaplayan hüzünle. Öyle bir aş...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aska-dair-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-selami-simsek-sp48h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söyle bana be gece

Neden kaciyorsun gizlice

Bak senin  ay gibi  bir arkadaşin var

Ne olur götür benide belirsizliğine

Seviyorum seni be gece

Adını sayıklıyorum hece hece

Al götür beni de gizlice

Yanlızlık kanatsız bir serçe

Ufuklarda belirdin yine gizlice

Yüreğime doğdun gene sessizce

Dökülür gözyasim seni görünce 

Üzülme! Yağmur siler gizlice

Sahi nerde kaldin be gece

Avunuyorum seninle kendimce

Dalarim sen diye düşlerime

Mazi olduğunu bile bile

15.11.2000 Stuttgart', 'Söyle bana be gece Neden kaciyorsun gizlice Bak senin  ay gibi  bir arkadaşin var Ne olur götür benide belirsizliğine Seviyorum seni be gece...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gece-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Arzum', 'son-arzum-nilgun-pakyildiz-i18qa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman kapısını açsam evimin,

Boyumu aşan bembeyaz karlar.

Buz gibi geçti bütün gecelerim.

İçimde dört mevsim fırtınalı kışlar.

Ne zaman yüzümü güneşe dönsem,

Yanıbaşımda esen sert bir rüzgar.

Geçti ömrüm hazan ile neyleyim.

Yaşadığım yarımyamalak bir bahar.

Ne zaman tülünü açsam,gönül penceremin,

Bin yıl ötede görünür,yeşil bir bahar.

Son arzum,yeşermektir bir mevsim.

Bin nazla olsa da,içime süzül yar.', 'Ne zaman kapısını açsam evimin, Boyumu aşan bembeyaz karlar. Buz gibi geçti bütün gecelerim. İçimde dört mevsim fırtınalı kışlar. Ne zaman y...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Pakyıldız']::text[], 8.5, '{"poet":"Nilgün Pakyıldız","poet_slug":"nilgun-pakyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-arzum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülker Yıldızının Armağanı', 'ulker-yildizinin-armagani-selami-simsek-m6vm3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşin doğuşu sanki bana selam verişin

Sinemi coşturur o canım deyişlerin

Ruhumu kaplar o tatlı muhabbetin

Bana armağanısın o gizemli ülkerin

Gök mavisine benzer o sürmeli gözlerin

Bülbül ötüşü gibidir o tatlı sözlerin

Kalbimde bir baskadir senin yerin

Adını kazıdım tam ortasına yüreğimin

Deniz dalgalı o kadife saçların

Ufukları süzen o masum bakışların

Gönlüme akıttığın o gizli gözyaşların

Meltemli duydular estirir ruhumda, tanımadığım

Misk-i amber gibidir kokun

Ruhuma ferahlık verir her soluğun

Bedenime farklı bir haz veririr dokunuşun

Varlık içinde yokluk  gibidir yokluğun

19.12.2000 Stuttgart', 'Güneşin doğuşu sanki bana selam verişin Sinemi coşturur o canım deyişlerin Ruhumu kaplar o tatlı muhabbetin Bana armağanısın o gizemli ülker...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ulker-yildizinin-armagani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Dağlar', 'mor-daglar-nilgun-pakyildiz-3w12o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alamam gözlerimi,

Şu karşı ki dağdan.

Bir hayal,bir pus,

Gözükmüyor dumandan.

Rüzgarınla haber sal,

Gülümse bir uzaktan.

Kulağımda boz at''ın 

Nal sesleri var.

O mor çiçekli dağdan,

Bir beklediğim var.

Şuursuzca eser,

Hırçın rüzgar doruklardan.

Günışığı zirveden

Göğe yükseldiği zaman,

Kasvetli bir karartı iner,

Yavaş yavaş akşamdan.

İçimde bir yiğidin,

Ahh sesleri var.

O mor çiçekli dağdan

Bir beklediğim var.', 'Alamam gözlerimi, Şu karşı ki dağdan. Bir hayal,bir pus, Gözükmüyor dumandan. Rüzgarınla haber sal, Gülümse bir uzaktan. Kulağımda boz at''ın...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Pakyıldız']::text[], 8.5, '{"poet":"Nilgün Pakyıldız","poet_slug":"nilgun-pakyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mor-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Hasretindeyim', 'sevmek-hasretindeyim-nilgun-pakyildiz-91u5n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eriyen bir gümüş gibi, 

Akıyor gözümde zaman.

Ve o zamanın akışında,

Hapsolunmuşluğun içindeyim.

Yemin ederim, 

Bir çıkabilsem kabuğumdan,

Yaratılmış ne varsa 

Doyasıya severim.

Bir dünya ki,

Elimi uzatsam sanki benim.

Ve bir dünya ki,

Öylesine de bana uzak.

Özlemle seyre dalar,

Sadece nazar ederim.

Karalara tutsak yüreğim,

Sökmez ki hiç şafak.

Hayatın cilvesine boyun eğip,

Yorgun düşürüldüm.

Ve bir hayat ki,

Gözlerimde erişilmeyenim.

Her yanımı saran hüzünlerle,

Karanlığa gömülüyüm.

Bir sefa bulsam,

Bin yıl kölesi olurum sevginin.

Gönlümde sevgi yağmurları,

Dönüşüyor sellere.

İçim dışım dolu,

Ben sevmeye gebeyim.

Ruhumdaki sevdayla,

Vurgunum,sümbüllere güllere.

Cümle alemin rengini, 

Sevmek hasretindeyim.', 'Eriyen bir gümüş gibi,  Akıyor gözümde zaman. Ve o zamanın akışında, Hapsolunmuşluğun içindeyim. Yemin ederim,  Bir çıkabilsem kabuğumdan, Y...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Pakyıldız']::text[], 8.5, '{"poet":"Nilgün Pakyıldız","poet_slug":"nilgun-pakyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevmek-hasretindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek', 'bir-tek-faruk-aysoy-kibtl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep seni düşündüm gecelerin içinde,

Seni hayal ettim ışıkların kapanışında,

Seni istedim kapının ardında,

Bir tek seni.

Sadece sana tutuldum senelerce,

Sana hayran kaldım bir ömür boyunca,

Sana sevgi besledim ölümsüzce,

Bir tek sana.

Şimdi düşünüyorum karanlığın içinde,

Senin çok uzağında ama içinde,

Ve biliyorum hata yaptım ömrüm boyunca,

Bir tek senin hakkında...', 'Hep seni düşündüm gecelerin içinde, Seni hayal ettim ışıkların kapanışında, Seni istedim kapının ardında, Bir tek seni. Sadece sana tutuldum...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-tek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Kalmışız', 'gec-kalmisiz-sair-cano-lx0ml', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün gelecek

çocuklar;

denizin mavisini göremeyecekler,

sevemeyecekler pullarını balıkların,

yeşili ağaçlarda bulamayacaklar,

Gün gelecek

anlayacağız ki Geç Kalmışız.

                                                               01.12.1997', 'Gün gelecek çocuklar; denizin mavisini göremeyecekler, sevemeyecekler pullarını balıkların, yeşili ağaçlarda bulamayacaklar, Gün gelecek anl...', ARRAY['Türk Edebiyatı','Şiir','Şair Cano']::text[], 8.5, '{"poet":"Şair Cano","poet_slug":"sair-cano","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gec-kalmisiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce Yağmur Vardı', 'once-yagmur-vardi-tuncay-alkan-jskuw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Önce yağmur vardı;

Seni yağmurların aldığını biliyordum

Ama durmadan seni aradım,adını bağırdım;duymadın...

Beni benden başka kimse duymadı.

Yağmurun altında akşam oluyordu,

Yağmur yağmasa akşam olmayacaktı,

Belki bunların hiçbirisi olmayacaktı.

Şiirden ayrılan bir dize gibi kalktın gittin

Bir dizesi eksik şiir gibi kalktın gittin.

Yağmur ve akşam

Bağırdığımı duymadın ama bağırdığımı biliyordun.

Elini aradım,elin yoktu.

İşte böyle yağmurlu bir akşamdı

Bir yaz günü açılsaydı kapılar

Yağmur yağmasaydı,seni yağmurlar almasaydı

Koşacaktım sana

İhtimal ben kapıyı vurmadan açacaktın,

Elimi bulacaktın,

Yağmur yağmasaydı,seni yağmurlar almasaydı.

Kimbilir ellerin nasıl dururdu?

Seni yağmurların aldığı bir akşamdı;

Sen yoktun...

Sözlerini bulamadığım bir şarkının müziği vardı

Küçük,eski bir yara izi gibi...

Tüfeklerin dönüp baktığı bir şarkının müziği vardı

Sen yoktun...

Ben kaderimi ellerinden tuttum

Yağmur yağmasa akşam olmayacaktı,

Belki bunların hiçbirisi olmayacaktı.

Yağmurda bütün ışıklar sönüyordu,

Bir karanlık yürüyordu,

Yıldızlar dahil herkes ölmüştü,

Ve tek tek ölüyordu ışıklar.

Sen yoktun ama ellerin ellerimde uyuyordu,

Sen yoktun ama gözlerin başka söylüyordu,

Yıldızlar dahil tüm ışıklar ölüyordu.

Seni yağmurların aldığı bir akşamdı

Bu şehirde akşam oluyordu

Geceye dönüyordu yağmur

Sen yoktun...

Belki yağmura karıştın 

Ne asılanların arasında adın,

Ne yağmurda kokun...

Olsa duyardım,gecenin yüzüne vururdu

Olsaydın duyardım,

Kalbim durudu.

Kimselere soramadım seni,yoktun

Yamur da yoktu.

Ben kaderimi ellerinden tuttum

Yanımda sen yoktun.

Uyumuyordum...Uyuyamıyordum...

Sande uyumuyorsun,biliyorum

Çünkü yoktun,yağmurlar yoktu.

Belki sen yoktun,belki yağmur.

Kaç kez kendi kendime konuştum

Kalbimi alıp tüfeklerin patladığı yere koydum.

Çünkü sen de yoktun,yağmur da yoktu

Dalgalar kadar yakın

Dalgalar kadar uzaktın bana

Seni tenimde yürüyen bulutlar gibi,

Seni özgürlük,

Seni kurtuluş gibi düşünüyordum.

Karda kalmış serçe gibi üşüyordum

Yanımda sen yoktun

Seni kimlere sormalıydı?

Seni tınısına yenilgi düşürmeyen çığlıklara sormalıydı.

Nereden geldiği bilinmez bir uğultu

Düşlerimin iz düşümünü karıştırıyordu.

Seni yağmurların aldığı bir akşamdı.

Yapayalnız yürüyordum,

Sonra yürüdüğümüzü anımsadım

Ama şimdi sen yoktun.

Sen hiç yokmuş gibi susuyordun

Kalbimin kuytuları titredide

Geçmedi senden tek bir haber.

Seni yağmurların aldığı bir akşamdı,

Sokaklara sığamadım,

Sokaklarda sen yoktun,

Ben kaderimi ellerinden tuttum.

Bağırsam duyan olmazdı.

Duvarlarda yüzün kalmış,

Gidip gördüm,kimseler görmedi.

Elimi yüzünde gezdiriyordum.

Yağmurlar yağmazdı bu akşam böyle,

Günlerdir yüzümün ıslaklığını yağmura sordum

Sen yoktun,belki yağmur...

Ben kaderimi ellerinden tuttum 

Nerdesin?

Yoruldu kalbim aramaktan seni,

Tüketiyordum yolları,kendimi,

Nerdesin?

Seni yağmurların aldığı bir akşamdı

Kalbimin haritaları karıştı 

Birbirine çıkmıyordu yollar

Ne izin vardı yırtılan gecede,

Ne kaderimde tutunacak bir dal.

Gözümü açıyordum

Çünkü sadece yakamozlar aklımı çeliyordu

Sen yoktun...

Seni yağmurların aldığı bir akşamdı

Ben kaderimi ellerinden tuttum 

Ağladım!...', 'Önce yağmur vardı; Seni yağmurların aldığını biliyordum Ama durmadan seni aradım,adını bağırdım;duymadın... Beni benden başka kimse duymadı....', ARRAY['Türk Edebiyatı','Şiir','Tuncay Alkan']::text[], 8.5, '{"poet":"Tuncay Alkan","poet_slug":"tuncay-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/once-yagmur-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hele Bir Yol Sefa Geldin Desene', 'hele-bir-yol-sefa-geldin-desene-pir-sultan-abdal-18w28', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Böle midir sizin ilin töresi

Hele bir yol safa geldin, desene

Geçer bu güzellik sana da kalmaz

Hele bir yol safa geldin, desene

Öl dediğin yerde ölürüm , derdin

Kal dediğin yerde kalırım, derdin

Her derdine derman olurum, derdin

Hele bir yol safa geldin, desene

Sarardı gül benzim ayvaya döndü

Hakk''ı söyledikçe müşkülüm kandı

Ayrılık ateşi sinemi deldi

Hele bir yol safa geldin, desene

Yatarım Muhammed, kalkarım Ali

Gittiğimiz on''ki İmam yolu

Pirim Hünkâr Hacı Bektaş Veli

Hele bir yol safa geldin, desene

Kırmızı güller solmaz mı sandın

Pir Sultan Abdal''ı gelmez mi sandın

Bir safa geldin de demez mi sandın

Hele bir yol safa geldin, desene', 'Böle midir sizin ilin töresi Hele bir yol safa geldin, desene Geçer bu güzellik sana da kalmaz Hele bir yol safa geldin, desene Öl dediğin y...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hele-bir-yol-sefa-geldin-desene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dervişlik', 'dervislik-yunus-emre-291gz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tehî görmen kimseyi hiç kimsene boş değil

Eksiklik ile nazar erenlere hoş değil

Gönlünü derviş eyle dost ile biliş eyle

Aşk ile eri şol manâda derviş içi boş değil

Derviş bilir dervişi Hak yoluna durmuşu

Dervişler hümâ kuşu çaylak u baykuş değil

Dervişlik aslı cândan geçti iki cihândan

Haber verir sultandan bellidir yad kuş değil

Ey Yunus Hakk’ı bilen söylemez hergiz yalan

İkilik ile gelen doğru yol bulmuş değil', 'Tehî görmen kimseyi hiç kimsene boş değil Eksiklik ile nazar erenlere hoş değil Gönlünü derviş eyle dost ile biliş eyle Aşk ile eri şol manâ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dervislik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman', 'ne-zaman-ozgur-cakmakci-1tfnv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hava kötü, sen yine yoksun

Ah, na zaman düzelecek bu hava.', 'Hava kötü, sen yine yoksun Ah, na zaman düzelecek bu hava....', ARRAY['Türk Edebiyatı','Şiir','Özgür Çakmakçı']::text[], 8.5, '{"poet":"Özgür Çakmakçı","poet_slug":"ozgur-cakmakci","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ne-zaman-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Bitmez', 'umut-bitmez-bayram-karaali-5cmd7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve sen kızgın; huysuz,kaşın kalkmada yinede,

Ama ben yine  aşağılarda uçmada kanatsız,

Elimi uzatırken yine yalnız,nehirlerim  sessiz,

Kürek çekmeyi bırak  kulaçsız  vede çaresiz.

Bak gördünmü,kafiye yaptım, istememiştim oysa; 

Elinin sıcaklığı   serin bir  gün batmasında yakınımda,

Kızgınlıklarını  anlamadımki; ben  aşkımı anlatmada,

Kırağılarımı  erittim yağmura sığınmalarımda..

17.Haziran.2001', 'Ve sen kızgın; huysuz,kaşın kalkmada yinede, Ama ben yine  aşağılarda uçmada kanatsız, Elimi uzatırken yine yalnız,nehirlerim  sessiz, Kürek...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umut-bitmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerini İstiyorum', 'ellerini-i-stiyorum-bayram-karaali-cme6a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerini  istiyorum canım.. uzat bana,

Hazanımda sen varsan ; baharım seninle oldu,

Al götür yüreğimi nereye  istersen  senindir,

Sokakları şaşırtmadan al götür  beni  oraya,

Sevmenin acı yanı budur ya; teslim olmadayım,

Biz aşkı,sevdayı vede doyasıya sevmeyi,

Beraber öğrenmedikmi? katıksız  açlığımızla,

Gel  bana canım.. Sana  yalvarmadayım...

Kuşkulanmalarının;  tipileri,boranları,fırtınaları,

Yüreğimdeki;bunaltan sıcakları vede  selleriyle,

Alıp katmasın önüne  götürmesin,felaketleriyle,

Anla  canım..ben , seninle ama;  yalnız  seninle....

17.Haziran.2001

Bayram Karaali', 'Ellerini  istiyorum canım.. uzat bana, Hazanımda sen varsan ; baharım seninle oldu, Al götür yüreğimi nereye  istersen  senindir, Sokakları ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ellerini-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-sebahattin-kulaksiz-01ebj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'baban,dediler ey babam!

anladım ama sana konduramadım.

bir ulu çınardın gözümde

dallarına benzerdi kolların

offff!!!!

kollarını özledim babam!

çok zamandır sarılmadın...

bir ulu çınara benzerdin ya,

biz yaprak mıydık,kuş muyduk üstünde

-tam üç çocuk-

bir de bedenine sarılan sarmaşık-ANNEM!-

o toprakta uzanır artık.

var mı haberin?

birlikte misiniz yine?

inan babam,çok sevindim...

bizi sorma babam!

hani kuştuk,yapraktık ya

acı rüzgarlara kapılıp savrulduk...

zemheri ayazı sardı dört bir yanımızı,

üşüdük,kavrulduk.

konacak dallar ararız boyuna...

ya senin köklerin duruyor mu yerinde hala?

dönüp gelsek dilimizde dua,

elimizde testi testi sularla

döksek toprağının üstüne...

söyle!!!

büyürmüsün yeniden?

yeniden konar mıyız dallarına?..

baban,dediler ey babam!

anladım ama sana kondduramadım.

iki kapısı vardı evimizin,

sen hep giriş kapısındaydın.

hiç görmedim çıktığını.

çocukluk işte! uyuyakalırdım

düşlerine dalardım akşam getireceklerinin:

ilk çıkan kirazlar,oyuncaklar,akide şekerleri...

biz sende yaşadık herşeyin ilkini!:

saygıyı büyüklüğünde,

doğruyu korkunda,

sevgiyi merhametinde tanıdık.

offff!!!!!!

çok özledim ellerini.

hani okşarken başımı,saçlarım hep uzardı yaa,

hani ben hep küçülürdüm yaa,

bak sen gittin gideli

saçlarım kısaldı,

ben büyüdüm babam!

sen gittin gideli

bir selamını almadım,

bir kısacık mektup yazmdın bana,

telefon da etmedin üstelik.

hiç mi düşünmezsin beni?

öksürdüğümde bile başıma dikilişin yalanmış demek

alacağın olsun!!!

zamanın mı yok,

paran mı kalmadı acep,

çok mu harçlık istedik senden

kalem,kağıt,pul alacak?

yoksa postacı mı bulamadın?

anlat babam, haydi anlat!...

yoksa gittiğin yer çok mu rahat?

var mı içecek suyun?

yenecek ekmeğin?

sıcacık mı odan?

yok mu hiç eksiğin?

dualar mı istersin,

hayır mı beklesin benden,boşuna!

benim kendime yok hayrım.

ne abdest alırım,ne kılarım namaz

tutulmamış oruçlarım da var daha.

her ne kadar iyi insan olarak bilinsem de

saymakla tükenmez günahlarım...

ben artık eyy babam!!!

düşen bir yaprak,

uçan bir kuşum,

göçer bir kuş!

bir gün yanına gelirim muhakkak...

BEKLER MİSİN?', 'baban,dediler ey babam! anladım ama sana konduramadım. bir ulu çınardın gözümde dallarına benzerdi kolların offff!!!! kollarını özledim baba...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Kulaksız']::text[], 8.5, '{"poet":"Sebahattin Kulaksız","poet_slug":"sebahattin-kulaksiz","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/babam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koş', 'kos-ethem-vayvayli-onb0l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'koş

ayaklarından kayboluş duyuldun

nar dallarından çiçekler aşır

ez hepsini incirler altında

yağmur görmemiş dudaklarınla', 'koş ayaklarından kayboluş duyuldun nar dallarından çiçekler aşır ez hepsini incirler altında yağmur görmemiş dudaklarınla...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizci', 'denizci-murat-ereren-jtrpk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok konuşup, çok şey anlatır denizci

Bir bildiğine bin ekler ; bir şişe içki ile !

Kimse bilmez derdini 

Gülerken yada ağlarken görmemiştir kimse Onu

Hatırlamamak için ayyaştır belki,

Belki de ayyaş olduğu için hatırlamaz.

Her kadına sevgilisi gibi sarılır

Sadece bunu bilir denizci, aşkı tanımaz.

Alışmıştır ; bilir bıraktığı yerde

Kimse beklemez Onu

Yine de içi sızlamıştır belki

	Kim bilir ?

Bir eş aramaz , 

Arasa da bulamaz

Kimse eş olmaz ; eşsizdir denizci.

İsimleri de hatırlamaz ;

ne “sokaktaki kadının”

ne “bardaki adamın”

Çabuk unutur unutanlarını, umutlanmaz

Bilir ki;

Geçmeyen zaman geçer,

Ya denizde

ya pis bir barda

ya da adsız bir kadının koynunda 

ölecektir

ölmüştür belki de!

Bir anı bile olmamıştır ; çoğu zaman

Adı kitaplara geçmeyecektir

Kimse beklemez Onu 

Yine de içi sızlamıştır belki

	Kim bilir ?', 'Çok konuşup, çok şey anlatır denizci Bir bildiğine bin ekler ; bir şişe içki ile ! Kimse bilmez derdini  Gülerken yada ağlarken görmemiştir ...', ARRAY['Türk Edebiyatı','Şiir','Murat Ereren']::text[], 8.5, '{"poet":"Murat Ereren","poet_slug":"murat-ereren","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/denizci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Böceği', 'ates-bocegi-murat-ereren-6lpev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hâlâ fark etmemiş olmalı insanoğlu

Kör karanlıkta, 

Uzakta

Belli belirsiz parlayan 

Ateşböceğini...

	dolu dolu mutlu olmak için.', 'Hâlâ fark etmemiş olmalı insanoğlu Kör karanlıkta,  Uzakta Belli belirsiz parlayan  Ateşböceğini... 	dolu dolu mutlu olmak için....', ARRAY['Türk Edebiyatı','Şiir','Murat Ereren']::text[], 8.5, '{"poet":"Murat Ereren","poet_slug":"murat-ereren","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ates-bocegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreği Alev Saltanat', 'yuregi-alev-saltanat-ethem-vayvayli-pgxtc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hadi bırak ceylanlara

Saçlarından yıldız gibi aksın

Aksın erisin içinde kalyon ve deniz

İnsin dökülsün ırmaklara yıldız

Ah belgin umutlarımda ağaran çiçek

Kanı sıcak, yüreği alev saltanat

Sonsuz kurtuluşun bir bahar dediği

O bahar bu olsa gerek...

Ellerin..ellerin ki bir soyluluk

Ellerinde yurdumun tohumları

Analık ve kadınlıkla içiçe bir koruluk

Ah eli elimdeki çocuk

Beyaz kelebek yandı alevde

22.08.2000

22:33', 'Hadi bırak ceylanlara Saçlarından yıldız gibi aksın Aksın erisin içinde kalyon ve deniz İnsin dökülsün ırmaklara yıldız Ah belgin umutlarımd...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuregi-alev-saltanat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye İşte', 'hikaye-i-ste-murat-ereren-bsejp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sığamadım bedenime

Haykırmak istedim !...

Sadece yüreği ile bağırınca  insan

hiç sesi kısılır mı?

Kısıldı işte !

Dayanamadım 

Hıçkırarak ağlamak istedim 

Bir damla yok !

“mutluluktandır” diye avuttum kendimi

göz yaşı biter mi hiç ?

Bitti işte ! 

-ya gidersen- leri düşündüm

sadece bir an,

belki ‘an’ dan bile kısa !

Ölmek istedim

İsteyince ölür mü insan ?

Öldüm işte !', 'Sığamadım bedenime Haykırmak istedim !... Sadece yüreği ile bağırınca  insan hiç sesi kısılır mı? Kısıldı işte ! Dayanamadım  Hıçkırarak ağl...', ARRAY['Türk Edebiyatı','Şiir','Murat Ereren']::text[], 8.5, '{"poet":"Murat Ereren","poet_slug":"murat-ereren","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hikaye-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-murat-bagis-dxq8h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce ağlamayı öğrendim

Pencere önlerinde zamanı adımlamayı

İflah etmez hastane koğuşlarında

İsyanı öğrendim

Gecenin gönüllere çizdiği koyu renklere

Çizgi çizgi ayrılığı işledim

Sensiz saatlerime

Yılların darbelerine kalkan oldu düşlerim

Zehirlerden arıtıp

Bir ömür yüklediğim bedenim

Küskün şimdi hayata

Bir çift ağıtla yürüyorum acılara

Ayaklarına kapanıyorum umudun

Hastane köşelerinde 

Yaşama dileniyorum

Ölüm dağıtıyor beton yürekler

Hedef oluyorum

Hayatın acımasız darbelerine

Üzgünüm...

Ümitsizim...

Kıskacında boğuluyorum dikenli hülyaların

Oysa güneşin boyun eydiği bir sevdayla

Açılmıştım zamana

Damla damla eridi saniyeler

Adım adım yürüdüm kararmış sayfalara', 'Önce ağlamayı öğrendim Pencere önlerinde zamanı adımlamayı İflah etmez hastane koğuşlarında İsyanı öğrendim Gecenin gönüllere çizdiği koyu r...', ARRAY['Türk Edebiyatı','Şiir','Murat Bağış']::text[], 8.5, '{"poet":"Murat Bağış","poet_slug":"murat-bagis","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevdam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-murat-bagis-wzg5a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamak nedir?

Bir tebessüm bir umut

Bir acı gözyaşı

Nefesi kesilen ömür

Ve ardından dökülen

Sonbahar yaprakları

Ve elveda

Beyaz elleriyle enseme sessizce dokunan

Bir bitiş noktasıdır ÖLÜM...', 'Yaşamak nedir? Bir tebessüm bir umut Bir acı gözyaşı Nefesi kesilen ömür Ve ardından dökülen Sonbahar yaprakları Ve elveda Beyaz elleriyle e...', ARRAY['Türk Edebiyatı','Şiir','Murat Bağış']::text[], 8.5, '{"poet":"Murat Bağış","poet_slug":"murat-bagis","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutkular Alev Olur', 'tutkular-alev-olur-murat-bagis-g5wms', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adını anıyorum bütün bulutlar dağılıyor

Sonra sen geliyorsun gözlerimin önüne

Bir sessizlik sarıyor odamın dört duvarını

Bir şiir yazıyorum sevdaya dair

Adını anıyorum bütün bulutlar dağılıyor

Yanlızlık zehir gibi sarıyor dört yanımı

Almamak için senden kara haberi

Kaçıyorum geceden ve gözlerine yakalanıyorum

Acıya düşüyorum Güneşi ağlatıyor feryadım

Ey gönül bahçemin nazlı çiçeği, yaban gülüm

Bu hicran şiiri senin için biliyorsun

Elveda sana, gözlerine, o can bakışlarına

Tutkular alev olur, süzülür, küle döner.', 'Adını anıyorum bütün bulutlar dağılıyor Sonra sen geliyorsun gözlerimin önüne Bir sessizlik sarıyor odamın dört duvarını Bir şiir yazıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Murat Bağış']::text[], 8.5, '{"poet":"Murat Bağış","poet_slug":"murat-bagis","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tutkular-alev-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bölüşür müsün', 'bolusur-musun-tevfik-karinca-ev8pk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bölüşürmüsün benimle mutluluk dediğini

Yaz akşamları gönlüne serin esen rüzgarları

Açlığımda sofranı

Yokluğunda yalnızlığımı bölüşürmüsün

Bölüşürmüsün benimle

Önüne eğik başını kaldırıp

Hiç öpülmemiş dudaklarını

ve önünde uzanan yaşamı 

bölüşürmüsün

Ben ki kahramanım

Hiç olmamış gerçeklerde

Zararım kendime 

Kendime ihanetim 

Bölüşürmüsün benimle

Acıları umutları

Ve mutluluk dediğini', 'Bölüşürmüsün benimle mutluluk dediğini Yaz akşamları gönlüne serin esen rüzgarları Açlığımda sofranı Yokluğunda yalnızlığımı bölüşürmüsün Bö...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bolusur-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Uykuda Şehir', '1-uykuda-sehir-arzu-bagriacik-ge96v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehir soğuk esintilerde

Kuşlar henüz derin uykuda.

Sinek bile yok,

İki ayaklılar rüyalarda.

Minik bir elden simit alabilmenin

Coşkusu içimde...

2001 Kütahya', 'Şehir soğuk esintilerde Kuşlar henüz derin uykuda. Sinek bile yok, İki ayaklılar rüyalarda. Minik bir elden simit alabilmenin Coşkusu içimde...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/1-uykuda-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Gelsen', 'bize-gelsen-sadun-koprulu-swn43', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yar saçını yan eder 

Bakışı bin kan eder 

Doğru yari sevenler 

Canını kurban eder 

Dağ başından kar gelsin 

Dost evinden bar gelsin 

Yıllar oldu sevmişem 

İstediğim yar gelsin 

Naz ederem, naz geçmez 

Söz ederem, söz geçmez 

Güzeli seven gönlüm 

Ölsem bile vazgeçmez 

Yar başın koy diz üste 

Seni sevdim söz üste 

Bizim eve gelsen kız 

Bırakıram göz üste 

Ruhumsan canımda kız 

Gezirsen kanımda kız 

Seni bir gün unutmam

Yaşa hep yanımda kız', 'Yar saçını yan eder  Bakışı bin kan eder  Doğru yari sevenler  Canını kurban eder  Dağ başından kar gelsin  Dost evinden bar gelsin  Yıllar ...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bize-gelsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-sadun-koprulu-jisvq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel kız, melek misin 

Tek bana, dilek misin 

Gönül bahçemde gezen 

Nazlı kelebek misin 

Gel yar, nerdesin nerde 

Gönüldesin gönülde 

Gülüyorsun alayla 

Saçıldın güneşle, ayla 

Süslü daha güzelsin 

Kırmızı kurdaleyle 

Gel yar, nerdesin nerde 

Gönüldesin gönülde 

Uykuda kalmıştık, dön 

Gel gözümde yerini bul 

Kucaklaş gel kavuşak 

Dünyamız olsun düğün 

Gel yar, nerdesin nerde 

Gönüldesin gönülde', 'Güzel kız, melek misin  Tek bana, dilek misin  Gönül bahçemde gezen  Nazlı kelebek misin  Gel yar, nerdesin nerde  Gönüldesin gönülde  Gülüy...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nerdesin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-sadun-koprulu-6ra1w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İkimizin derdi  bitmez 

Sana canım veriyorum 

Her yanımda seni buldum 

Senden umut diliyorum 

Bakışınla gülüyorum 

Ölsem bile seviyorum 

Aylar oldu, yıllar oldu 

Her gelenden soruyorum 

Tek yaşarsın, gözlerimde 

Bir sen varsın, sözlerimde 

Uyku nedir, bilmez oldum 

Gece gündüz, izlerimde 

Varım yokum, canım sensin 

Gündüz gecem, anım sensın 

Düşündükçe, derdim bitmez 

Ölsem bile kanım sensın 

Çilem bitmez, mutluluk yok 

Bıktım artık dertlerden çok 

Yalan bakış, aldatıyor 

Sinem dolu dağlarla ok 

Yar, gönlüm vurgun sana 

Bekliyorum yana yana 

Nolur birgün yüzün görem 

Yalvarırım kana kana 

İç duygumda sevgimde sen 

Kanımda sen, içimde sen 

Dört baharla canlanırsın 

Heran başka biçimde sen 

Akar durmaz yaşım sensin 

Dost, yoldaşım, eşim sensin 

Başkasını gözüm görmez 

İlk, sonbahar, kışım sensin', 'İkimizin derdi  bitmez  Sana canım veriyorum  Her yanımda seni buldum  Senden umut diliyorum  Bakışınla gülüyorum  Ölsem bile seviyorum  Ayl...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sensiz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümüz', 'gonlumuz-sadun-koprulu-bfpyl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kuşlar bizimle kanatlı 

Hayat senle güzel mutlu 

Gönlümüzde umut dolu 

Günlerimiz baldan tatlı 

Gönlünle gönlüme tokun 

Sensin bana benden yakın 

Gönlümde hep evin vardır 

Benden başka tutma sakın 

Gözlerimde ılık yaş sen 

Gönlüme tek güzel eş sen 

Bu dünyama ışık veren 

Yeni doğan şen güneş sen 

Sevgine sevgi  katamam 

Kız  bırakıp hiç atamam 

Can gönlümü, parçasalar 

Unutamam, unutamam 

Geçen günler bir düş gibi 

Anlarımız gülüş gibi 

Gel barışak kucaklaşak 

Küçük gönlümüz kuş gibi', 'Kuşlar bizimle kanatlı  Hayat senle güzel mutlu  Gönlümüzde umut dolu  Günlerimiz baldan tatlı  Gönlünle gönlüme tokun  Sensin bana benden y...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonlumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-sadun-koprulu-g6z4r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün seninleydim, akşam 

Al yazma vardı başında 

Senle güzel hoş yasam 

Umudum çatma kaşında 

Sazlar çalındı inceden 

Gönül sevmişti önceden 

Bal akar, yaşlanır, titrer 

Dudaklar yonca yoncadan 

Bülbül gibi güle konduk 

Şirin şirin söze kandık 

İkimizde candan sevip 

Aşk uğrunda yıllarca yandık 

Sen olmasan yüzüm gülmez 

Senden başka gönül sevmez 

Gece gündüz seninleyim 

Sen olmasan hayat olmaz', 'Bir gün seninleydim, akşam  Al yazma vardı başında  Senle güzel hoş yasam  Umudum çatma kaşında  Sazlar çalındı inceden  Gönül sevmişti önce...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.Bütün Renkler', 'a-butun-renkler-sadun-koprulu-ra9cr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel yar gönlümü yormuş 

Güle güle karşı durmuş 

Sümbül saçının teline 

Akşamın güneşi vurmuş 

Yar bahçenin gülün derde 

Canlanırsın her bir yerde 

Can vermeden can alırsın 

Her karşıma çıkışın birde 

Bütün renkler yar gözünde 

Balda akar bal sözünde 

Umutlarla gülümseme 

İyimserlik yar yüzünde 

Yar yüzünde bütün bahar 

Bakışında umutlar var 

Süt mavisi gözleriyle 

Bana verir hayatı yar', 'Güzel yar gönlümü yormuş  Güle güle karşı durmuş  Sümbül saçının teline  Akşamın güneşi vurmuş  Yar bahçenin gülün derde  Canlanırsın her bi...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/a-butun-renkler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Güzelsin', 'sen-guzelsin-sadun-koprulu-tfwyd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaratılmışsın balla 

Çok güzel sirinsin yar 

Saçların tıl tıl salla 

Çok güzel, şirinsin yar 

Tek türküsün dilimde 

Bir sen varsın iliğimde 

Hep yaşarsın gönlümde 

Çok güzel, şirinsin yar 

Bahçemde sen birtek gül 

Açıl saçıl içten gül 

Sen ki dünyamda güzel 

Çok güzel şirinsin yar 

Yar yolunda gül, çiçek 

Çok güzeldi sanki melek 

Senden güzel, yok demek 

Çok güzel, sirinsin yar', 'Yaratılmışsın balla  Çok güzel sirinsin yar  Saçların tıl tıl salla  Çok güzel, şirinsin yar  Tek türküsün dilimde  Bir sen varsın iliğimde ...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-guzelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Tatlı', 'tatli-tatli-sadun-koprulu-0opfx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne güzelsin tatlı tatlı 

Şirin, güzel beni yakma 

Gözün bahar, saçın bulut 

Ne bakarsın tatlı tatlı 

Bak gözüme süzül, görüş 

Al gönlümü, içten soruş 

Gel  benimle doğru seviş 

Ne yakarsın, tatlı tatlı 

Konuş doyum, bal dilinden 

Aşk şarabın, ver elinden 

Sarılaydım, gül belinden 

Ne kokarsın tatlı tatlı 

Damarımda, al kan güzel 

Düşme  duygumdan, yan güzel 

Sular gibi canlan güzel 

Ne akarsın, tatlı tatlı', 'Ne güzelsin tatlı tatlı  Şirin, güzel beni yakma  Gözün bahar, saçın bulut  Ne bakarsın tatlı tatlı  Bak gözüme süzül, görüş  Al gönlümü, iç...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tatli-tatli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tat Verir', 'tat-verir-sadun-koprulu-nqh8b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoksun alsam gül sümbülün 

Yaprak sarar, dal tat verir 

Gönlün çalsam, o güzelin 

Bel dolasan, kol tat verir 

Ay yüzünde gül açmıştı 

Dudağından bal saçmıştı 

Yanağına hal göçnıstı 

Gülüsüne hal tat verir 

Bahar, seyran, gülşen sensin 

Bahçe, bağla, bostan sensin 

Şeker, şerbet, canan sensin 

Ağzın, içsem, dil tat verir 

Karşı baksa selam söyler 

Ağzın açmaz, kelam söyler 

Güzel yarı alem söyler 

Nazlı koşar, yol tat verir 

Tek güzelim yaşat canı 

Sever isen aşkın tanı 

Gel gönlüne dost et beni 

Girsem pembe, al tat verir', 'Yoksun alsam gül sümbülün  Yaprak sarar, dal tat verir  Gönlün çalsam, o güzelin  Bel dolasan, kol tat verir  Ay yüzünde gül açmıştı  Dudağı...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tat-verir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem', 'i-stemem-sadun-koprulu-m8vdp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdiğim, tek eşim olsa 

Başkasını, dal istemem 

Can gönülden, aşkın yaysa 

Yad bağından, gül istemem 

Çok güzeldir, kuşla öter 

Işık olur, aydan beter 

Al dudağı, bal, bal satar 

Arı veren, bal istemem', 'Sevdiğim, tek eşim olsa  Başkasını, dal istemem  Can gönülden, aşkın yaysa  Yad bağından, gül istemem  Çok güzeldir, kuşla öter  Işık olur, ...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/istemem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık Olsun', 'yazik-olsun-sadun-koprulu-22l1v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yada verdin şirin canın 

Tez unuttun, sen cananın 

Yazık olsun, yar canıma 

Aşkın çekti yıllar senin 

Sen, bülbülün gülü gibi 

Sevenlerin dili gibi 

Sen yar, beni tez unuttun 

Ettin deli, deli gibi 

Canıma dert katan idin 

Sen gönlümde yatan idin 

Beni bir gün görmeseydin 

Yar gönlünü, atan idin 

Gülden aldın nazik cismin 

Dillerde idi tatlı ismin 

Seni bir gün görmeseydim 

Karşılardım güzel resmin', 'Yada verdin şirin canın  Tez unuttun, sen cananın  Yazık olsun, yar canıma  Aşkın çekti yıllar senin  Sen, bülbülün gülü gibi  Sevenlerin di...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yazik-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimiz Büyüyecek', 'sevgimiz-buyuyecek-sadun-koprulu-uv9df', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ümit yaymış ışığın 

Sen aşkım, çok büyüksün 

Bu aşkta tek tutsağın 

Taşınacak yüküsün 

Deniz coşan gözünden 

Temiz yağmur inecek 

Ölmez yaşar duygumuz 

Sevgimiz büyüyecek', 'Ümit yaymış ışığın  Sen aşkım, çok büyüksün  Bu aşkta tek tutsağın  Taşınacak yüküsün  Deniz coşan gözünden  Temiz yağmur inecek  Ölmez yaşa...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgimiz-buyuyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Atmalı', 'nasil-atmali-sadun-koprulu-g3p1w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarin bağında yattım 

Yadları baştan attım 

Ayrılık duyan günden 

Bin türlü dert çıkarttım 

Yanağı al şeftali 

Nar dudağı tutmalı 

Kız sana gönül verdim 

Sevip nasıl atmalı 

Gel güzel beni ara 

Çıkalım hoş bahara 

Can verip tez ölmeden 

Kavuşsaydık diyara 

Gözün kaldır tez güzel 

İnci, yakut duz güzel 

Gel gönlümde yaşa sen 

İster isen göz güzel', 'Yarin bağında yattım  Yadları baştan attım  Ayrılık duyan günden  Bin türlü dert çıkarttım  Yanağı al şeftali  Nar dudağı tutmalı  Kız sana ...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-atmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşat Bakalım', 'yasat-bakalim-abluka-gunerhan-94g2v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hadi...

Yaşat bakalım

Yaşa bakalım 

Al eline kemanını 

İşle ruhuma

Yaşarken geceyi

Bütün tükenmişliğiyle

Penceremden yatağıma düş

Ay ışığım ol

Ya da mavi gecemde

Bir yıldız

Yeter ki benim ol

Yeter ki yaşat beni', 'Hadi... Yaşat bakalım Yaşa bakalım  Al eline kemanını  İşle ruhuma Yaşarken geceyi Bütün tükenmişliğiyle Penceremden yatağıma düş Ay ışığım ...', ARRAY['Türk Edebiyatı','Şiir','Abluka Günerhan']::text[], 8.5, '{"poet":"Abluka Günerhan","poet_slug":"abluka-gunerhan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasat-bakalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biziz Türküler', 'biziz-turkuler-sadun-koprulu-5fl7p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökte doğmuş şen ayımız 

Biziz yiğit Türkler kardeş 

Atalardan pek, soyumuz 

Biziz yiğit Türkler kardeş 

Tarih yazmış şan adımız 

Dağı deler feryadımız 

Korkuyor düşman, yadımız 

Biziz yiğit Türkler kardeş 

Utku doludur kavğamız 

Düşman titredir naramız 

Toprak sever balamız 

Biziz yiğit Türkler kardeş 

Düşman gözün oyarız 

Canımız yurda dayarız 

Bayrağı kana boyarız 

Biziz yiğit Türkler kardeş 

Korkmadan çıkak yola 

Sesimizden cihan dola 

Verelim gönül gönüle 

Biziz yiğit Türkler kardeş 

Kavuşur birlik yolunda 

Türkün marşı Türk dilinde 

Biz şirin Kerkük elinde 

Biziz yiğit Türkler kardeş 

Toprağımda başka hayat 

Yurdun sever bizim millet 

Yatanları kardeş uyat 

Biziz yiğit Türkler kardeş', 'Gökte doğmuş şen ayımız  Biziz yiğit Türkler kardeş  Atalardan pek, soyumuz  Biziz yiğit Türkler kardeş  Tarih yazmış şan adımız  Dağı deler...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/biziz-turkuler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-sadun-koprulu-gtjey', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Konuş benim şirin annem 

Özgürlük can yuvasıdır 

Özgürlükle millet üstün 

Birleşmenin süresidir 

Özgürlükte aldık varlık 

Hayatta çok çektik darlık 

Özgürlükte yüksek birlik 

Gönlümüzün çaresidir 

Özgürlük var okullarda 

Sevgi sevinç gönüllerde 

Hem kızlar hem oğullarda 

Özgürlüğün meyvesidir 

Özgürlük gör ilkbahardır 

Kan verenler bahtiyardır 

Dünyada bak neler vardır 

Özgürlük yol görmesidir 

Özgürlük can damarıdır 

Bilenlerin tek yarıdır 

Geleceğin bal varıdır 

Er millete vermesidir 

Özgürlük mert Türkün yolu 

Özgürlük millet temeli 

Doğa, deniz, gök bilmeli 

Bu ses tutsaklık sesidir 

Özgürlükte var hidayet 

Mutlu güzel olur hayat 

Özgürlükte vardır lezzet 

Özgürlük anne yuvasıdır', 'Konuş benim şirin annem  Özgürlük can yuvasıdır  Özgürlükle millet üstün  Birleşmenin süresidir  Özgürlükte aldık varlık  Hayatta çok çektik...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ozgurluk-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Türkiyem', 'can-turkiyem-sadun-koprulu-3j88f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Can Türkiyem güneş rengin açanda 

Bahar koksun her bir yana saçanda 

Sevenlerin gönül derdin açanda 

Çok sevinem İstanbul’u görende 

Toprağını öpüp yüzüm sürende 

Can Türkiyem temiz Türkçe dilim var 

Çok güvenir hiç darılmam dalım var 

Sensiz bana ayrılık var ölüm var 

Canım kurban bayrağa can verene 

Çokça selam Türkiye’mi sevene 

Can Türkiyem binbir renkli güllerin 

Millet güler esende hoş yellerin 

Sevgi coşar süslendikçe yolların 

Bak canlanır oynayanda sümbüller 

Gün doğmadan türkü söyler bülbüller 

Can Türkiyem sende bahar olunca 

Her bir yanın gül karanfil dolunca 

Bütün dünya Türkleri de gülünce 

Uçan kuşlar dalımıza konaydı 

Ümit veren mutlu günler döneydi 

Can Türkiyem yiğit yeri meydandı 

Kıratıyla koşan kılınç kalkandı 

Savaşan er toprağına dayandı 

Göz aç bir bak Türkler nerde, söz orda 

Toprak nerde, bayrak nerde, biz orda', 'Can Türkiyem güneş rengin açanda  Bahar koksun her bir yana saçanda  Sevenlerin gönül derdin açanda  Çok sevinem İstanbul’u görende  Toprağı...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/can-turkiyem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karabağ', 'karabag-sadun-koprulu-jgh5o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bu toprağın eriyim 

Türküm nasıl tez eriyim 

Azeriyim, Türkmenim ben 

Geçmişle gelişti varım 

Tarih Atamdan söz açar 

Yolumuzda güller açar 

Hep dünya bizi konuşur 

Güneşimiz heran saçar 

Kımız sütün içmekteyiz 

Karabağı seçmekteyiz 

Şeyh Şamil’in gölgesinde 

Yaramızı dikmekteyiz 

Haydi koşun Azer kardeş 

Düşmanlara salak ateş 

Döndürelim yerlerimiz 

Hiç korkmadan yapak savaş 

Dert özlemden uzaklaşak 

Duyğumuz bir yakınlaşak 

Söyleyelim Turan marşın 

Karabağ’da kucaklaşak 

Toprağa  binlerce can 

Sizinledir bütün Türkmen 

Uğrunuzda ölürüz biz 

Azerbeycan, Azerbeycan 

Şehit diye öleceğiz 

Dağ taşlardan geleceğiz 

Öz toprak öz yurdumuzda 

Türk sevgisin bulacağız 

Karabağda Çeçen ile 

Birgün olur güleceğiz 

El kaldırıp bütün Türk’e 

Mutlu hayat dileyeceğiz 

Kerkük’ümde çocukların 

Yaşlarını sileceğiz 

Her bir yerde Türkler için 

Canımıza kıyacağız 

Azizim sözümde var 

Tarihte izimde var 

Azerbeycan sevgisi 

Gönlümde, gözümde var', 'Ben bu toprağın eriyim  Türküm nasıl tez eriyim  Azeriyim, Türkmenim ben  Geçmişle gelişti varım  Tarih Atamdan söz açar  Yolumuzda güller a...', ARRAY['Türk Edebiyatı','Şiir','Sadun Köprülü']::text[], 8.5, '{"poet":"Sadun Köprülü","poet_slug":"sadun-koprulu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/karabag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ut Ameris Ama', 'ut-ameris-ama-afsar-timucin-chmq7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkı kimi açık açık yaşadı

Kimi de düşündü sessiz sessiz

Birileri de kitaplar yazdı

Yazmasa daha iyiydi çünkü bir yüzü

Canavarlar kadar korkunçtur aşkın

Onu rahat odalarda çay içerken

Ona buna anlatanlara bakma

Aşk her zaman üçüncü kişilere kapalı

Aşk her zaman yedi kat yerin altı

Cehennemin dibinde kor çeşmesi

Değdiği yeri yakması o yüzden

Gücü bitti mi soğur buz keser

Sokağa atsan kimse almaz

Aşktan başka ne beklenir ki aşktan

Bazı çok güzel aşklar da var

Dersin bunu benim için biçmişler

Benim kapım öyle şeye kapalı

Ben kanımdan canımdan veririm

Kimi aşkın koltuğuna kurulur

Leblebi çekirdek yer

Kimi de benim gibi

Gece gündüz dolaşır sokakları', 'Aşkı kimi açık açık yaşadı Kimi de düşündü sessiz sessiz Birileri de kitaplar yazdı Yazmasa daha iyiydi çünkü bir yüzü Canavarlar kadar kork...', ARRAY['Türk Edebiyatı','Şiir','Afşar Timuçin']::text[], 8.5, '{"poet":"Afşar Timuçin","poet_slug":"afsar-timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ut-ameris-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaller Diyarından Bir Menekşe', 'hayaller-diyarindan-bir-menekse-sinem-cengiz-p7fdv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şelaledir, akıp gidiyor içimde

İyiliklerime iyilik katacak yenilikler arıyorum

Eskiler ise boynumda bir kolye

Dünya mı benim çevremde,ben mi onun etrafında dönüyorum

Bir hasrettir,yakıyor beni her nefeste

Ölümle yüzyüze geliyorum

''elveda'' dediğim anda hayata

Mutluluklarımda ölüyorum

Dünya mı benim çevremde,ben mi onun etrafında dönüyorum

Bir dünyadır,atıyor beni sürekli içinden

Pembe olanından isteniyorum

Tos pembe dünyadan

Yeşil yaprağı seviyorum belki de

Kahverengi toprağı

Ya da mavi göğü, gülen tabloları

Kabuslarımdan amiyane bir kafeste yaşıyorum

Dünya mı benim çevremde, ben mi onun etrafında dönüyorum

Bir rüyadır,uyutuyor beni her gece

Arıtıyor üzüntülerimden

Hatta bazen eser aklmıyor hüzünlerimden

Ama artık kısalıyor tatlı hayaller

Harcıalem oluyor günden güne

Uyanıyorum artık rüyalardan

Daha doğrusu dalamıyorum

Önümden koşan derin uykulara yetişemiyorum

Falsolu bir hayata yöneldi adımlarım

Iskarta bir labirente giriyorum

Herkes gibi

Bu yüksek duvarlara aşık herkes gibi

Oysa arkamdaki cansız bedenler şad iken

Kemlerini satmışlar bana,benacı çekiyorum

Dünya mı benim çevremde, ben mi onun etrafında dönüyorum

Bir neşeli muhabbettir, hâlâ sürüyor kulaklarımda dilimde

Sıcak sözler usumda,bildiğim,tanıdığım,her diyarda

Hayatım dışında

Duymuyor beni kimse,anlamıyor bu yeni banal yerde

Susuyorum

Ne geldiyse susmaktan geldi başıma

Ama konuşamıyorum

Sanki biri gizlice alıyor ağzımdan kelimeleri

Ama konuşamıyorum

Bir gün dolu dolu söyleyebilmek için susuyorum

Şaşkın bir haldeyim

Dünya mı benim çevremde,ben mi onun etrafında dönüyorum

Bir hayattır,içiyor beni sürekli kadeh kadeh

Sevgimi çalıyor benden

Sonra da damla damla göklerden yere düşüyorum

Ayağım bastığı anda yeryüzüne

Yönümü şaşırıyorum

Bir anda duruyorum

Göremiyorum ilk anda yeşili,maviyi

Daha soluk,çok daha soluk bu sefer

Mutluluklarımı sadece küçük bir noktayla bitirip gamlı defteri-

min sayfalarına başlıyorum

Hicran benim, ben hayatın peşinden koşuyorum

Gerçek hayatın...

Şimdi her gece gökyüzüne baktığımda kendi kendime soru-

yorum

Dünya mı benim çevremde, ben mi onun etrafında dönüyorum

İşte o anda biri mutluluk sıkıştırıyor yüreğime

Şimdiye kadar hep ben dünyanın çevresinde döndüm

Ama bir gün karşılığında o benim etrafımda dönecek

Tekrar soruyorum

Dünya mı benim çevremde,ben mi onun etrafında dönüyorum

Ve o anda susuyorum...

Ne var ki derin uykuların yolunu tutmuşum

Bir gün onlara yetişeceğimi biliyorum...', 'Bir şelaledir, akıp gidiyor içimde İyiliklerime iyilik katacak yenilikler arıyorum Eskiler ise boynumda bir kolye Dünya mı benim çevremde,be...', ARRAY['Türk Edebiyatı','Şiir','Sinem Cengiz']::text[], 8.5, '{"poet":"Sinem Cengiz","poet_slug":"sinem-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/hayaller-diyarindan-bir-menekse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbim', 'rabbim-nazim-tektas-781ao', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önümde uzanan sonsuz engine

Ruhumu kuş gibi sal yüce Rabbim

Fani bedenimi süründür, yine

Benliğimi benden al yüce Rabbim

İçimden uzak et öfkeni kini

Tattırma geçici dünya zevkini

Göster bana gördüğümün fevkini

Nefsimi yerlere çal yüce Rabbim

Sırtım hasret kalsın çula kilime

Gönlüm hasret kalsın güzel ilime

Sevdiğim tatlardan verme dilime

Arıların olsun bal, yüce Rabbim

Kul eyleme cehle tacı da olsa

Meftun et gerçeğe acıda olsa

Adı Ana - Baba Bacı da olsa

Açmasın önümde fal yüce Rabbim

Şükür kapısını ardına dek aç

Kanaat suyundan ver bakraç bakraç

Tevekkül nurunu yüreğime saç

Cezbetmesin beni, mal yüce Rabbim

Dünya dünyacıya süslenedursun

Bülbüller güllere seslenedursun

Nazım biraz daha uslanadursun

Sonra doğsun, hal yüce Rabbim', 'Önümde uzanan sonsuz engine Ruhumu kuş gibi sal yüce Rabbim Fani bedenimi süründür, yine Benliğimi benden al yüce Rabbim İçimden uzak et öfk...', ARRAY['Türk Edebiyatı','Şiir','Nazım Tektaş']::text[], 8.5, '{"poet":"Nazım Tektaş","poet_slug":"nazim-tektas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/rabbim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep O ,Düşünde', 'hep-o-dusunde-nazim-tektas-5jyu8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birgün bu yollardan sessiz sedasız

Geçip gideceğim eller üsünde

Elim dilim bağlı duracak bağsız

Ruhum kuş olacak yeller üstünde 

O zaman hatıra gelirmi eş dost?

Sevdiklerim hıçkırır mı gülermi?

Pay edilip benden kalan eski post

Birileri çıkıp iyoldu der mi?

Toprak sıcak kollarına salar mı?

Tepermi bilemem, bilemem Rabbim

Seninle vuslattan derin haz var mı?

Başka birşey asla dilemem Rabbim', 'Birgün bu yollardan sessiz sedasız Geçip gideceğim eller üsünde Elim dilim bağlı duracak bağsız Ruhum kuş olacak yeller üstünde  O zaman hat...', ARRAY['Türk Edebiyatı','Şiir','Nazım Tektaş']::text[], 8.5, '{"poet":"Nazım Tektaş","poet_slug":"nazim-tektas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hep-o-dusunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Duygu ki', 'bir-duygu-ki-nazim-tektas-7fbrl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uykum, rüyam, hayalim, havam suyum dediğim

Bir duygu var içimde adını bilmediğim

Bazan surlarda Fatih, bazan dergahta çile

Bazan denizde balık konuşur yunus ile

Bazan mimar başın harç taşır kürek kürek

Bazan bütün milletin derdine çarpan yürek

Baza yetime ana, esirlere hürriyet

Mevlevilerde sema, mü''min gönülde niyet

Bir duyguki uzanır sonsuza doğru son hız

Amamnın gözlerinde parıldar yıldız yıldız

Ne zaman ben ben olsam çağırıyor derinden

Varlığım bir çığ gibi yuvarlanıp yerinden

Düşüyor en dik dağdan en derin bir çukura

Bin parça oluyorum her parçamda bin yara

Bazan hıçkırık olur boğazıma kırk düğüm

Bazan başımda balyoz beynime iner güm güm

Bir duygu ki içimde, içinde kaybolurum

Ve aklımda ne varsa hepsi de ben olurum', 'Uykum, rüyam, hayalim, havam suyum dediğim Bir duygu var içimde adını bilmediğim Bazan surlarda Fatih, bazan dergahta çile Bazan denizde bal...', ARRAY['Türk Edebiyatı','Şiir','Nazım Tektaş']::text[], 8.5, '{"poet":"Nazım Tektaş","poet_slug":"nazim-tektas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-duygu-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açsın!..', 'acsin-sair-kyo-xi5k2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'selam uzaklardan gelen yolcu selam

belki pek hüzünlüsün

belki pek sıkılgan

hepimiz degilmiyiz ademin soyundan 

darılma bunlara 

sıkılma onlardan

anlarız biz biz olanın halinden 

açsın!

bizim gibi;

sevgiye,doyumsuz dostluga bizde açız

yüreklerdeki bi sıcak muhabbete

sevmeyi bilenlere

dostlugun degerini bilenlere

bizde açız 

anlarız senin halinden

anlarız da aglarız 

dostluk,insanlık vardı

öldü dediler 

geçen gün 

yalan insanın içindeki ölürmü....', 'selam uzaklardan gelen yolcu selam belki pek hüzünlüsün belki pek sıkılgan hepimiz degilmiyiz ademin soyundan  darılma bunlara  sıkılma onla...', ARRAY['Türk Edebiyatı','Şiir','Şair Kyo']::text[], 8.5, '{"poet":"Şair Kyo","poet_slug":"sair-kyo","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/acsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Baştan Başlamak İstiyorum', 'en-bastan-baslamak-i-stiyorum-kamil-ucbas-qxjfo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En baştan Başlayarak

Yaşamak istiyorum;

En karmaşık, en baştan çıkarıcı,

En gizemliyi!

En fırtınalısını seçip...

En baştan başlayarak

Sevmek istiyorum;

Sonunda ışık olmasa da...

Mademki, yüreğinde bir dişi şölvalye var.

Sev bakalım diyorum.

Ama kimseyle paylaşmadan!

Sev sevebildiğin kadar...

En baştan başlayarak

En önde olmak istiyorum;

Utanç duşmadan,

Dik ve onurlu.

Öndekileri teker teker

safdışı ederek...

En baştan başlayarak

Fark edilmek istiyorum;

Sırdan değil, can dostu gibi,

İyi gün dostu değil,

En fırtınalısı,

En sınırsızı,

En dürüstçesi,

Her neyse...

En baştan başlayarak

Koklamak istiyorum;

Sulamayınca solan,

Kalbimin kanında açan son gülü.

Kırılgan bir çiçek gibi, korumak,

Derleyip toparlamak istiyorum...

En baştan başlayarak

Haykırmak istiyorum;

Sevdiğimin beni sevdiğine inanarak

Soluk soluğa koşup!

Coşkumuzu çığlık atarak ilan edebilseydik.

Kaçmanın sarhoşluğu yerine,

Sevincin coşkusunu yaşasaydık...

En baştan başlayarak

Beni anlamanı istiyorum.

Kanadı kırık bir yürekle sevmektense,

Sensiz olma istiyorum.

Benimki, çivi çiviyi söker yöntemi!

Sensiz nasıl yaşanacağını öğrenip,

Aradan çekilmek istiyorum.

En baştan başlayarak

Duymak istiyorum...

Ve...

Bana ilk kez,

Bana

Anlatmanı istiyorum...

En baştan başlayarak yazmak istiyorum.

Aklıma sen geliyorsun,

İçli sevda şiirleri doğuyor içimden.

Sana hasretim bir çığ gibi artıyor.

Meğer sana ne kadar bağlıymışım...

Yüreğimde, gözümde, şahdamarımdasın...

Yüzüm mahçup, gözlerim dolu,

Yüreğim sancılı...

Sana yazmak,

Yarım kalmış öpücüğe benzer bir şey...

Her düşündüğümü,

Her istediğimi yazmak,

Meğer ne kadar zormuş.

Yüreğim bir volkan gibi kaynıyor,

Nedense boşalamıyorum....

Yine de şiirlerim seninle başlıyor.

Ve...

Ancak sana yazabiliyorum.

Bir sen bir de benden başka,

Kimsecikler bilmemeli,

duymamalı, okumamalı...

Yüreğimde, gözümde, aklımdasın.

Sevmenin gücüyle çarpıştığımız an,

Ben galip geliyorum.

Duygularla çarpıştığımız an ise,

Sonsuza kadar yenilen benim.

Yenilmez şövalyem,

Haklısın diyemiyorsun.

Öyle ipe sapa gelmez, 

Öyle münasebetsiz,

Öylesine ölçüsüz seven bir yüreğim var.

Tüm güzellikler, tüm içtenlik,

Sınır tanımaz yüreğimde değil mi?

Bu duygulardan küçücük bir şey eksilirse,

Ben bomboş kalırım...

En baştan başlayarak

Ceylan gözlerine benzer gözlerinin,

Sonsuz ufuklara açılan beyazlığında,

Sevgimi resme dönüştürmek isterim.

Zaman zaman, yaşamakla,

Düşünmek arasında,

Kavga etmek için kuvvet aldığım,

O dost gözlerinin,

O dost beyazlığında,

İnsanların eşit olduğu dünyayı düşlerim...

Gökyüzünün lacivertimsi karanlığında,

Bana yol gösteren,

Ceylan gözlerine benzer gözlerin,

İki yıldız parlaklığında...

Havai fişeğin,

Kapkara gökyüzünde yarattığı,

Renk fınarını düşünür;

Yüreğimde patlayan fişeğin coşkusuyla,

Sevgiyi düşlerim...

Resim denince aklıma,

Olabildiğince renkli palet gelir.

Bir rüyalar ülkesi;

Üzerinde kuşların ötüştüğü,

Kelebeklerin uçuştuğu,

Kirinden, pasından arınmış

Tertemiz bir ülke gelir...

O ceylan gözlerine benzer

Gözlerinin okyanusunda...

En baştan fırçamı alırım elime,

Beyaz tuvalden önce...

Benden kaçamadığın

Hesaplaşmayı göze alabildiğin,

Lacivert yatak odanı aydınlatan,

O gizemli mumdan çıkan,

Alev gelir aklıma...

Tuvalime;

Alev kırmızısıyla

Mercan kırmızısını,

Gül kırmızısıyla,

Çingene pembesini,

Yerleştirmek gelir...

Ege''nin büyüleyici gecelerine benzer,

İri gözlerin gelir aklıma.

Işık tutkunu olduğun,

İçtenliğin gelir...

Renkleri karıştırıyorum...

Çivit mavisiyle, buz mavisi,

Gül pembesiyle, zümrüt yeşili,

Turuncuyla, kan kırmızısı renkler,

Ölümsüz güzelliğine dönüşüyor.

Renk pınarı kadar duru saflığın geliyor aklıma...

Dantel gibi örülmüş,

Ege kıyılarından,

Kır kahvelerinden,

Daracık sokaklarından,

Ve...

Senden yaratılmış

Sevgi yumağı aklıma gelir...

En baştan düşündüğüm rengi

Bir defasında sürmek isterim...

Önce suluboya gelir aklıma.

Çünkü; suluboya yaşam gibi

Düzeltme kabul etmez.

Yaşamdaki akıcılığı kolayca yakalar,

Senin gibi hissettirmeden,

Değerleri yerine koyar benim gibi...

Lacivert odanın,

Lacivert duvarında palyaçolar görüyorum...

Kadın, erkek, çocuk palyaçolar...

Gerçek duygu ve düşüncesi olan insanlar...

Hepimiz de palyaço değil miyiz?

Bu kez de aklıma,

Hiç çıkarmadığın masken gelir...

Uzakta, çok uzaklarda...

Tahta bacaklı, küpeli kulaklı,

Tek gözü kapalı, dişsiz korsanlar gülümsüyordu.

Ve deniz can dost gibiydi,

Cıvıl cıvıl havasıyla...

Ya bir sihirbazın,

Ya bir ressamın fırçası,

Ya da başka bir alem oluvermişti...

O ceylan gözlerine benzer gözlerinin

Sonsuz beyazlığından,

Bir saflık

Bir içtenlik,

Sıcaklık yayılıverir

Tuvalime...

Renkleri bildik gibi gelen,

Ama bilmediğimiz...

Artık her şey yerli yerindedir.

Sanatın doğasında,

Yüreğinde olgudur bu duygu...

Hemen şimdi, vakit geçirmeden

Kaybolanları geri getirmek üzere,

Kapat artık gözlerini...

Beklediğimiz an geldi,

Yolculuk gökkuşağına...

Dünyada haksızlık varsa,

Kimse temiz olamaz...

Ey, kasırgaların kardeşi fırtınalar,

Güzeller güzeli gökkubbe,

Yüreğimin zenginliği deniz!

Ey, öteki gezegenlerin halkları!

İçinizde kim en günahsızsa,

O duysun çığlıklarımı...

En baştan başlayarak

Yaşamla oynaşmak istiyorum.

Öylesine sessiz, öylesine güzel,

Bir tomurcuk açtı...

Yüreğimin derinliğinde,

Bir fısıltı gibi...

Oysa yıllardır,

Sarmaşık gibi, yüreğimi

Kocaman bir yengeç dolamıştı.

Tomurcukla sevincim yeşerdi,

Neşelendim, yeniden gülümsedim

Yaşamla oynaşırken,

Soluk soluğa, tam zamanında,

Ne önce, ne de sonra...

Sevgisiz insanları,

Acımasız davranışları geride bıraktım.

Yaraları bereleri onardım.

Kabalığı, hoyratlığı aştım.

Her şeyi gönlümde okşadım.

Ve tomurcuklar...

Yaşama sevincimin tomurcukları

Açmaya başladı.

Hem gizemini çözmeye başladım,

Hem de...

Soluk alıp vermek üzere,

Açmanın tadını yaşadım

Tomurcuklarla...

Hep alçak sesle düşünüyordum:

Hep böyle tomurcuk kalacak değil ya?

Diyordum...

Sen en güzel çiçekleri açmalısın,

Tomurcuk diyordum...

Tomurcuk öylesine sessiz,

Öylesine güzel, öylesine içten ki,

Gökyüzünün aydınlığından

Başka bir şey görmemişti...

Açtığında bak, göreceksin!

Yer, gök nasıl birbirine karışacaktı!

Bir gün korktuğum başıma geldi...

Tomurcuk çiçek olacağını haykırdı!

İçimdeki susuzluğumun ortasında,

Çiçek gibi açmaya devam ederken,

Benim çiçeğim derken,

Yüreğimde bir anda beliriveren,

Eşsiz güzellik birden,

Gözümün önünden kayboluverdi...

Ve...

Bir gün, bir gül yolumu kesti.

Dikenli tele takılmış.

Şipşak fotoğrafı vardır ya hani,

Onlardan biri gibi...

Sonuçta kayda değer bir şey yok.

Aşk acısını toprağa gömeceğim.

Bereketli tohumlar gibi gömeceğim.

Sevmek güzel de, yitirmek çok acı...

Yüreğimdeki yengecin şenlendiğini,

Duyar gibi oluyor musunuz?', 'En baştan Başlayarak Yaşamak istiyorum; En karmaşık, en baştan çıkarıcı, En gizemliyi! En fırtınalısını seçip... En baştan başlayarak Sevmek...', ARRAY['Türk Edebiyatı','Şiir','Kamil Üçbaş']::text[], 8.5, '{"poet":"Kamil Üçbaş","poet_slug":"kamil-ucbas","theme":"Türk Şiiri","is_hero":false,"total_lines":249,"source_url":"https://www.antoloji.com/en-bastan-baslamak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadığımız', 'anlayamadigimiz-nurgun-salli-a07iq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar ne seni çözebildi

Ne de bitmeyen sevgimizi

Haklıydın hata benimdi

Bencildim bilmiyordum

Belki de bir bağlılıktı bu

Belki de alışkanlıktı anlayamadığımız.

Üstüme çöken karanlığı,

Silkindikce içimdeki acıları

Farkında olmadan üzdüm seni

Meğer ne çok seviyormuşsun 

Nasıl da inat etmişsin bu sevgide

Affet çözemedim duygularını

Neydi bizi birleştiren

Belki de sevgiydi anlayamadığımız

Bak işte yine karşındayım

Seninleyim, doyasıya sev beni

Sımsıkı sarıl bırakma

Artık pes etmek yok

Şimdi içindeki sevginle al intikamını

Hazırım sevgini hissetmeye

Korkmuyorum inan, belki de

Yıldızların parlaklığıydı anlayamadığımız.', 'Yıllar ne seni çözebildi Ne de bitmeyen sevgimizi Haklıydın hata benimdi Bencildim bilmiyordum Belki de bir bağlılıktı bu Belki de alışkanlı...', ARRAY['Türk Edebiyatı','Şiir','Nurgün Şallı']::text[], 8.5, '{"poet":"Nurgün Şallı","poet_slug":"nurgun-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anlayamadigimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimizdeki Çaresizlik', 'i-cimizdeki-caresizlik-nurgun-salli-wwsdg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimden gelen en yoğun duygularla

Sana Sesleniyorum,

Haykırıyorum tüm dünyaya.

Duygularım alt-üst olmuş

Kalbim taşıyamayacak kadar yorulmuş

Nereye kadar gider

Bu karanlık düşünceler bilmem

Bir gün pes edecek yürek.

İlk defa korkuyorum

Sana sevgimi haykırmaktan

İlk defa yenik düşüyorum

Bitmeyen bu aşkta

Ve dönüp dolaşıp sende yoğunlaşan

Senden başkasını düşünmeyen

Sevgimle haykırıyorum.

Düşüncelerim bulanık

Çaresiz kalmış mantığım

Kestiremiyorum artık inan

Ne zaman biter bu 

Yılan hikayesine dönüşen aşk

Bilinmeyene ilerleyen bu sevgi

Ne sen benden

Ne de ben senden vazgeçemedik

Nedir o zaman içimizdeki çaresizlik

Ve kabul edemeklerimiz....', 'İçimden gelen en yoğun duygularla Sana Sesleniyorum, Haykırıyorum tüm dünyaya. Duygularım alt-üst olmuş Kalbim taşıyamayacak kadar yorulmuş ...', ARRAY['Türk Edebiyatı','Şiir','Nurgün Şallı']::text[], 8.5, '{"poet":"Nurgün Şallı","poet_slug":"nurgun-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/icimizdeki-caresizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adı Olmalı', 'bir-adi-olmali-nurgun-salli-wi7x0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duygularım karmakarışık

Zifiri karanlığın içinde

Üşüyorum bu sıcak gecede

Nedenini bilmediğim

Ve bir türlü cevap bulamadığım

Sorularımın içinde kayboldum.

Gözlerin uzakta bir deniz sanki

Boğuluyorum düşündükçe....

Ne zaman kalsam sabah nöbetlerine 

Sebepsizce seni bulurum gecelerimde

İçimde anlam veremediğim 

Hatta ismini koyamadığım hisler

Getirir beni sana

Bir ben kalmalıyım diyorum

Bir adı olmalı anlamsızlıkların.

Çözümünü bulamadığım sevgimin

Ve ulaşamadığım sevginin

Anlamı neydi acaba

Seviyor muydum seni çıkmazlıklarda

Yoksa bir alışkanlık mıydın

Zaman dedim sadece zaman

Ama sana göre bu sevginin

Bir adı olmalıydı.....

Oysa ben bu sevginin anlamını

Bilmiyordum.

Bana göre yaşananlar bir anı olarak

Sadece bir adı kalmalıydı....', 'Duygularım karmakarışık Zifiri karanlığın içinde Üşüyorum bu sıcak gecede Nedenini bilmediğim Ve bir türlü cevap bulamadığım Sorularımın içi...', ARRAY['Türk Edebiyatı','Şiir','Nurgün Şallı']::text[], 8.5, '{"poet":"Nurgün Şallı","poet_slug":"nurgun-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-adi-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm', 'kara-gozlum-nurgun-salli-qu1jf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman bir çok şeyi alıp götürmüş benden,

Sevginin değerini bilememişim yazık,

Meğer ne çok alışmışım sana,

Gururuma yenilmek üzereyim sayende.

Bu deli kızı uslandırdın sonunda,

Mutlu musun kara gözlüm.

Yaşadıklarımız ve yaşanacaklar,

Nasıl da gözümün önünde duruyor,

O masum bakışın, sevginin haykırışın

Bir gün gelir de seni üzersem,

Affet, bu sevgi seline bağışla,

Üzülme kara gözlüm.

Kirpiklerinde sakladığın,

O bir damla yaşı tut ne olur,

Bir daha ağlama dayanamam

Sadece sevdiğini söyle yeter.

Olaki bir gün nankörlük edersem sevgine

Beni affet kara gözlüm.

Farkında değildim inan,

Beni böylesine sevdiğinin,

Yoksa hiç kırar mıydım seni,

Atar mıydım o derin gecelerin içine.

Gökyüzündeki tüm yıldızlar seninle olsun,

Yeter ki beni hep böyle sev kara gözlüm.', 'Zaman bir çok şeyi alıp götürmüş benden, Sevginin değerini bilememişim yazık, Meğer ne çok alışmışım sana, Gururuma yenilmek üzereyim sayend...', ARRAY['Türk Edebiyatı','Şiir','Nurgün Şallı']::text[], 8.5, '{"poet":"Nurgün Şallı","poet_slug":"nurgun-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kara-gozlum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-sebahattin-altan-n3yrb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'senin ellerinle tutsam dost elini sıcacık ve karşılıksız

senin gülüşünle gülem masum  ve yapmacıksız

ırkın dinin dilin önemli değil

kuzeyden güneyden,dogudan batıdan

belkide bir çingenenin kucağından

senin gözlerinle baksam bebeğim

hiç büyümeden...', 'senin ellerinle tutsam dost elini sıcacık ve karşılıksız senin gülüşünle gülem masum  ve yapmacıksız ırkın dinin dilin önemli değil kuzeyden...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Altan']::text[], 8.5, '{"poet":"Sebahattin Altan","poet_slug":"sebahattin-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bebegim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-sebahattin-altan-8rp13', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sağdaki evden bir çocuk çığlığı yükseliyor

ağlama be bebeğim ağlayacak daha o kadar yılların olacakki

soldan loş bir ışık yırtıyor karanlığı

ask mı sevgi mi yoksa yılların yorgunluğumu bilinmez

köşedeki parkta iki çocuk uyuyor

ilgisizliktenmi sevgisizlikten mi acaba

karşıda hep aynı taksici olmayan müşterilerini bekler durur

kafasında bin bir hesap olmasınistiyor hiç sabah

bütün pislikler pusuda günün agarmasını bekliyor haince

hanımeli kokuları gittikçe yogunlaşıyor 

genzimi yakıyor artık

tıpkı yaşam gibi.....', 'sağdaki evden bir çocuk çığlığı yükseliyor ağlama be bebeğim ağlayacak daha o kadar yılların olacakki soldan loş bir ışık yırtıyor karanlığı...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Altan']::text[], 8.5, '{"poet":"Sebahattin Altan","poet_slug":"sebahattin-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasam-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Sitem', 'sevgiliye-sitem-sebahattin-altan-tz3c6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bak yine çakıyor balıkçı feneri

sanki giden gemilere göz kırpan bir sevgili

seni düşünmekte anlamsız artık geceleri

ardına kadar açık bırak pencereni

dağıtsın rüzgar kokumu anılarımı,

alıp götürsün bir dağ başına bir deniz kenarına bir ovaya

çiçek tohumları gibi

kuşlar gelsin böcekler gelsin

özgürlüğümü alıp özgürlüğüyle birleştirsin

yeni bir dünya yaratsın kendince

senin yapmadığın gibi....', 'bak yine çakıyor balıkçı feneri sanki giden gemilere göz kırpan bir sevgili seni düşünmekte anlamsız artık geceleri ardına kadar açık bırak ...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Altan']::text[], 8.5, '{"poet":"Sebahattin Altan","poet_slug":"sebahattin-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgiliye-sitem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönülatma Gönül Beni Derde', 'gonulatma-gonul-beni-derde-adem-aydin-zc4xj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aşk insana büyük bela 

atma gönül beni derde

yüreğimde sızlar hala 

atma gönül beni derde

ayrılığa dayanmak zor

hasret yanan alevli kor

neler çektim gel bana sor

atma gönül beni derde

nede güzel yaşıyorsun

ne gam keder taşıyorsun

bak haddini aşıyorsun

atma gönül beni derde', 'aşk insana büyük bela  atma gönül beni derde yüreğimde sızlar hala  atma gönül beni derde ayrılığa dayanmak zor hasret yanan alevli kor nele...', ARRAY['Türk Edebiyatı','Şiir','Adem Aydın']::text[], 8.5, '{"poet":"Adem Aydın","poet_slug":"adem-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonulatma-gonul-beni-derde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eleni', 'eleni-sebahattin-altan-213r3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'rum mu yoksa bilmem ermenimi

biraz tombul biraz iri

biraz uçuk biraz deli

raksına uygun göbeği

her akşam ugrama buraya arkadaş

bu akşam neşeli...', 'rum mu yoksa bilmem ermenimi biraz tombul biraz iri biraz uçuk biraz deli raksına uygun göbeği her akşam ugrama buraya arkadaş bu akşam neşe...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Altan']::text[], 8.5, '{"poet":"Sebahattin Altan","poet_slug":"sebahattin-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/eleni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık', 'ciglik-emre-ozdamar-2s4ur', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suskunluğum ardında çığlığım uyur 

Hüznümün ardında saklı kelimelerim

Dile geliyor senden ayrı kalınca 

Seninle başlıyor bitirdiklerim', 'Suskunluğum ardında çığlığım uyur  Hüznümün ardında saklı kelimelerim Dile geliyor senden ayrı kalınca  Seninle başlıyor bitirdiklerim...', ARRAY['Türk Edebiyatı','Şiir','Emre Özdamar']::text[], 8.5, '{"poet":"Emre Özdamar","poet_slug":"emre-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ciglik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmak', 'olmak-sebahattin-altan-7779i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'damaktaki tad

olabilirmisin

petekteki bal

ağaçtaki meyvalı dal

yanaktaki al

olabilirmisin

kırmızıyla sarıyı

incitmeden karıncayı

dostunu düşmanını

tanıyabilirmisin...', 'damaktaki tad olabilirmisin petekteki bal ağaçtaki meyvalı dal yanaktaki al olabilirmisin kırmızıyla sarıyı incitmeden karıncayı dostunu düş...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Altan']::text[], 8.5, '{"poet":"Sebahattin Altan","poet_slug":"sebahattin-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Yolunda', 'koy-yolunda-adem-aydin-o9qrv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu akşam beni teselli etmez bir şey

bir meçhule sürüklenir gibiyim sanki

şişeler ne çare neylesin artık mey,

yaşamak içimden gelmiyor inanki', 'bu akşam beni teselli etmez bir şey bir meçhule sürüklenir gibiyim sanki şişeler ne çare neylesin artık mey, yaşamak içimden gelmiyor inanki...', ARRAY['Türk Edebiyatı','Şiir','Adem Aydın']::text[], 8.5, '{"poet":"Adem Aydın","poet_slug":"adem-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/koy-yolunda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum', 'oglum-adem-aydin-kt7bc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne yapsam ne etsem hep senin için

bu akşamda elim boş darılma oğlum

bilirim çocuksun gidiyor için

pahalı şeylere sarılma oğlum

şu fakir babanın yoktur günahı

almak istemezmi sana dünyayı

hayra yor gördüğün her rüyayı

her mahsun bakışa vurulma oğlum', 'ne yapsam ne etsem hep senin için bu akşamda elim boş darılma oğlum bilirim çocuksun gidiyor için pahalı şeylere sarılma oğlum şu fakir baba...', ARRAY['Türk Edebiyatı','Şiir','Adem Aydın']::text[], 8.5, '{"poet":"Adem Aydın","poet_slug":"adem-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oglum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba', 'acaba-ahu-caglar-a49xd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'herkesin amacı, düşünceleri,

istekleri farklıdır

benzemez kimse kimseye

her nekadar benzetsek de 

acaba uzaklarda

yada aramızda

varmıdır başka bir BEN daha?', 'herkesin amacı, düşünceleri, istekleri farklıdır benzemez kimse kimseye her nekadar benzetsek de  acaba uzaklarda yada aramızda varmıdır baş...', ARRAY['Türk Edebiyatı','Şiir','Ahu Çağlar']::text[], 8.5, '{"poet":"Ahu Çağlar","poet_slug":"ahu-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/acaba-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kışın Bestesi', 'kisin-bestesi-tuce-kongul-vexmq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dudaklarımda morardı

                  sonbahar...

                    Soğudu

            Caddeler, sokaklar...

                    Dondu

            Gözlerdeki pırıltılar...

                      Aşk

            Çıkardı hançerini

                    Titredi

           Tenleri ayrılık kokanlar

                       Kış

           Bütün kapılarını açtı....', 'Dudaklarımda morardı                   sonbahar...                     Soğudu             Caddeler, sokaklar...                     Dondu   ...', ARRAY['Türk Edebiyatı','Şiir','Tuçe Köngül']::text[], 8.5, '{"poet":"Tuçe Köngül","poet_slug":"tuce-kongul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kisin-bestesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Sözcüklerin Şehri', 'kayip-sozcuklerin-sehri-tuce-kongul-368eh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonsuzluğu mırıldanmakla kaldım

Solan şehrin hayalinde

Kısalmış bir hikayenin

Kayıp sözcüklerinde

Sahipsiz bir yere vardım...

Kapının ardında tanıdık bir şehir

Kapının ardında tanıdık bir tını

Sen misin söyleyen o eski şarkıyı? 

Sokaklarda adım adım yürüyen rüzgar

Gecesinde kayan, yiten yıldızlar

Sözcükleri kayıp bir şehrin

Hayalinin solduğu yere kadar...', 'Sonsuzluğu mırıldanmakla kaldım Solan şehrin hayalinde Kısalmış bir hikayenin Kayıp sözcüklerinde Sahipsiz bir yere vardım... Kapının ardınd...', ARRAY['Türk Edebiyatı','Şiir','Tuçe Köngül']::text[], 8.5, '{"poet":"Tuçe Köngül","poet_slug":"tuce-kongul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kayip-sozcuklerin-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-murat-bozdemir-ltda2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç özlemedim o zamanlar seni hiç aklıma gelmedin

Belki seni özleyecek zamanım olmadı 

Belkide zaman seni özleyecek fırsatı ermedi bana...', 'Hiç özlemedim o zamanlar seni hiç aklıma gelmedin Belki seni özleyecek zamanım olmadı  Belkide zaman seni özleyecek fırsatı ermedi bana......', ARRAY['Türk Edebiyatı','Şiir','Murat Bozdemir']::text[], 8.5, '{"poet":"Murat Bozdemir","poet_slug":"murat-bozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ozlem-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemler', 'ozlemler-murat-bozdemir-sd8pt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç özlemedim o zamanlar seni hiç aklıma gelmedin.

Belki seni özleyecek zamanım olmadı,

Belkide zaman seni özleyecek fırsatı vermedi bana...', 'Hiç özlemedim o zamanlar seni hiç aklıma gelmedin. Belki seni özleyecek zamanım olmadı, Belkide zaman seni özleyecek fırsatı vermedi bana......', ARRAY['Türk Edebiyatı','Şiir','Murat Bozdemir']::text[], 8.5, '{"poet":"Murat Bozdemir","poet_slug":"murat-bozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ozlemler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnternette muhabbet üzerine', 'i-nternette-muhabbet-uzerine-burak-atabey-vsd9o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vakit dolmuş,sular çekilmiş 

Kayığımla yaklaşıyorum o iskeleye yine

Her akşam denizkızının peşine

Dolanıp durmak oğlum senin neyine

Hey gidi budala çocuk hey

Yeryüzünde bakamazken kimse gözlerine

Gözlerinden ziyade yüreğinin derinliklerine

Senin ne işin var hayallerin peşine

Uyan artık uyan,dön kendine

Oğlum burak haydi yürü git işine', 'Vakit dolmuş,sular çekilmiş  Kayığımla yaklaşıyorum o iskeleye yine Her akşam denizkızının peşine Dolanıp durmak oğlum senin neyine Hey gidi...', ARRAY['Türk Edebiyatı','Şiir','Burak Atabey']::text[], 8.5, '{"poet":"Burak Atabey","poet_slug":"burak-atabey","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/internette-muhabbet-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazilere', 'gazilere-burak-atabey-kwwtp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ülkü nedir bilir misin dostum

Parmaklarını açıp bağırmak mı sence

Arkadaşların,tanıdıkların hoşlansın diye

Yoksa insan ayırmak mı kafana göre

Bilir misin dostum o bıçkın delikanlıları 

Davul zurna ile cepheye oğurlananları 

Mevzi emri hücuma dönünce hayatı kararanları

Çoluk çocuk yolumu gözler diye sakınanları

Bir taraftan tüfek kurarken saklanacak yer arayanları

İşte o gün anlarsın dostum ülkünün ne işe yaradığını

Atalarını,dedelerini görürsün yanında korkakların yerine

Çekersin Ayyıldız resmini iki gözüne

İşte meydan işte düşman , hepsi yerli yerine

Selam olsun bu millet için acımayana kendine

Yazıklar olsun bunca emeğe ihanet edene', 'Ülkü nedir bilir misin dostum Parmaklarını açıp bağırmak mı sence Arkadaşların,tanıdıkların hoşlansın diye Yoksa insan ayırmak mı kafana gör...', ARRAY['Türk Edebiyatı','Şiir','Burak Atabey']::text[], 8.5, '{"poet":"Burak Atabey","poet_slug":"burak-atabey","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gazilere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nafile', 'nafile-sair-baksencik-rq2qu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamanın bahçesinde koskocaman bir deniz,

Üzerinde ilerliyor yorgun argın gemimiz,

Kıyıda bir gül var;

Bir kız kadar güzel, bir çocuk gibi temiz.

Gemi gitmeye, yol bitmeye

İnsan ölmeye mahkum.

Biz gülü almışız almamışız;

Sevmişiz seyretmişiz

Ne fayda!', 'Zamanın bahçesinde koskocaman bir deniz, Üzerinde ilerliyor yorgun argın gemimiz, Kıyıda bir gül var; Bir kız kadar güzel, bir çocuk gibi te...', ARRAY['Türk Edebiyatı','Şiir','Şair Baksencik']::text[], 8.5, '{"poet":"Şair Baksencik","poet_slug":"sair-baksencik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nafile-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükürler Olsun', 'sukurler-olsun-burak-atabey-lpp4s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey meleklerin kalbini kırmaktan zevk aldığını sanan

Ey şeytanların aferinlerinden medet uman

Kaldır başını da bir bak bakalım etrafına

Hani,nerede kendine örnek aldıkların

Tüm dünyayı titretemiş zalimler,kendini tanrı ilan edenler

Bir topal sivrisineğe mağlup olanlar,nerede

Nefsine zor gelir ama cevabını sorarsan eğer

Kıyametin kopmasını beklemekteler

Çünkü o güne dek kabir azabı çekmekteler

Ne mutlu kalplere kudretle değil de sevgiyle hükmedenlere

Ne mutlu seni de beni de yaratan Allah''a şükredebilenlere

En zalimleri bile tövbe edebilsin diye ertesi sabaha

Kavuşturan Rabbime şükürler olsun binlerce kere', 'Ey meleklerin kalbini kırmaktan zevk aldığını sanan Ey şeytanların aferinlerinden medet uman Kaldır başını da bir bak bakalım etrafına Hani,...', ARRAY['Türk Edebiyatı','Şiir','Burak Atabey']::text[], 8.5, '{"poet":"Burak Atabey","poet_slug":"burak-atabey","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sukurler-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostumun Mirasıdır Bana', 'dostumun-mirasidir-bana-burak-atabey-5t80p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğduğun anda sana verileni kaybetmediysen 

Hala sahipsen o ışığa az ya da çok

Bil ki mahkumdur karanlıklar

Etrafından dağılmaya, er ya da geç

Kimileri katılır sana bu yolda mahçup gözlerle

Kimileri de uzaklaşır senden kaçabildiğince

Dostum sen  yeter ki sen ışığını söndürme

Ömrünün nihayetinde o ilahi nur

Seni almaya gelene dek

Yoksa sen de katılırsın onlara

Umutsuzlukla yaşanabileceğini sananlara

Karanlıklarda dolaşıp kaçarak ışıktan

Sonunu bulamayan o zavallılara', 'Doğduğun anda sana verileni kaybetmediysen  Hala sahipsen o ışığa az ya da çok Bil ki mahkumdur karanlıklar Etrafından dağılmaya, er ya da g...', ARRAY['Türk Edebiyatı','Şiir','Burak Atabey']::text[], 8.5, '{"poet":"Burak Atabey","poet_slug":"burak-atabey","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dostumun-mirasidir-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Cam', 'kirik-cam-baris-demir-h9ibf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle bir gidişin vardıki ben ağlarken

Ardına bile bakmadan

Hayatıma kıyarcasına kıydın yaşananlara

Acımasızca...

Gittin bir cellat edasıyla

Yittim...

Umutlara aldırış bile etmedin

Paramparça ettin artık hayatımı, oysa

Sana adanmıştı.

Dağıldı etimi parçalayarak, kan revan içinde.

Sen bile toplayamazsın artık sana adanmışlığımı

Toplasan bile

Kırık cam misali...', 'Öyle bir gidişin vardıki ben ağlarken Ardına bile bakmadan Hayatıma kıyarcasına kıydın yaşananlara Acımasızca... Gittin bir cellat edasıyla ...', ARRAY['Türk Edebiyatı','Şiir','Barış Demir']::text[], 8.5, '{"poet":"Barış Demir","poet_slug":"baris-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirik-cam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baykuş', 'baykus-burak-atabey-hed7t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendi dertlerimi unutmuşken

Dost bildiklerime moral vereyim diye

Sordum kendime oğlum böyle nereye

Dedi kendim bana dinle a keriz

Böyle giderse mezara kadar yalnız gezeriz

Çık dışarı dolaş,bir hava al hele

Daldan dala kon , çiçekten çiçeğe

Lakin sen ne bir arısın ne de bir kuş

Olsa olsa ömrü boyu yalnız ötmüş bir baykuş

Öt bakalım sanki bülbüldü sesin

Kimbilir belki bir bün sen de gülersin', 'Kendi dertlerimi unutmuşken Dost bildiklerime moral vereyim diye Sordum kendime oğlum böyle nereye Dedi kendim bana dinle a keriz Böyle gide...', ARRAY['Türk Edebiyatı','Şiir','Burak Atabey']::text[], 8.5, '{"poet":"Burak Atabey","poet_slug":"burak-atabey","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/baykus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usandık', 'usandik-nazim-tektas-3mor8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeşil çimen mavi su çıplakların harası

Edepden urbalılar örenlerden usandık

Hazarda halimizi soran bilen olmadı

Seferde can simidi görenlerden usandık

Toprak kan isteyende nefer olduk ön safta

Sırça saraylarında ürenlerden usandık

Bir kutsi sıfat ile ruhumuzu donatıp

Bizi ateş hattına sürenlerden usandık

Coğrafya vatan oldu asırlık azmimizle

Düşmana bahşiş gibi verenlerden usandık

En ulvi hislerimiz bulandı kahrımızdan

Asabımız yay oldu gerenlerden usandık

Keder, kıvanç, tasada, kaderde bir bütünüz

Deyip sonra ipe un serenlerden usandık

Alayı vala ile birbirini methedip

Gıyabında bolca yerenlerden usandık

Palavraya gelince mangalda kül koymayan

Sahte kahramanlardan, erenlerden usandık

Biz zaten ikbal için gelmemiştik cihana

İkbal defterimizi dürenlerden usandık

Öldük, dünya onlara kalsın diye, ne çare

Mezarlarımızdan gül derenlerden usandık', 'Yeşil çimen mavi su çıplakların harası Edepden urbalılar örenlerden usandık Hazarda halimizi soran bilen olmadı Seferde can simidi görenlerd...', ARRAY['Türk Edebiyatı','Şiir','Nazım Tektaş']::text[], 8.5, '{"poet":"Nazım Tektaş","poet_slug":"nazim-tektas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/usandik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Islanmak', 'seninle-islanmak-gulcihan-atalay-z1yyd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kopan bir tel gibi

Kalbimden

Kopup gidersen uzaklara

Rüzgarlara bırak kendini

Ayışığında ıslık çalarak

Yürü karlı bir gecede

Yaşlı ırmağın rehberliğinde

Geçerek geniş ovaları

Karanlık bir ormana gir

Şarkı söyleyen dallara şaşarak…

Yarenlik et  dağbaşlarında

Kavalını ağlatan yalnız çobanla

Ateşler yak, yüreğimi de yakarak

Uğultulu bir davettir uzaklardan

Sevdalarını al gel diye çağıran

Utanma, istiyorsan ağla 

Gecelerin koynu kurutur gözyaşlarını

Seni bir çocuk gibi kollarında saklayarak…

Düşen bir yaş gibi

Gözlerimden

Düşersen bir gün kederli göğsüme

Bırak

Kuruyan dere yatağı

Nasıl şenlenirse baharda

Şenlensin göğsüm seninle ıslanarak…', 'Kopan bir tel gibi Kalbimden Kopup gidersen uzaklara Rüzgarlara bırak kendini Ayışığında ıslık çalarak Yürü karlı bir gecede Yaşlı ırmağın r...', ARRAY['Türk Edebiyatı','Şiir','Gülcihan Atalay']::text[], 8.5, '{"poet":"Gülcihan Atalay","poet_slug":"gulcihan-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seninle-islanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-selcuk-yilmaz-0ykz4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arzın derinliklerinde yüreğe düşen 

Kor bir ateş mi desem. 

Yoksa fısıltılarla söylenmiş

sözcükler midir aşk..

Ya da seni bana sürekli hatırlatan

O vazgeçilmezliğin mi?

Sonsuzluk rüzgarlarının

O pembe yanaklara  vuran 

Meltemsi ılık yansıması mı?

Bazı kereler hayalini göndüğüm, 

Bir peri kızı gibi zihnime yansıyan,

İmgelerle dolu o şiirselliğin mi?

Ya da bir serap gibi,

Tıpkı   gözde bir sultanın

Yeşil gözlerinin parıltısında,

Hülyalarla dolu bir gecenin

Sema aleminde ki 

Suzidilara bir fasıl mıdır aşk;

Ama yalnızlığın sarhoş ettiği,

Mehtabın yakamoza

Yakamozun da mehtaba bir

Raksımıdır aşk, aşk, aşk ...........SY   18.6.2001 İzmir', 'Arzın derinliklerinde yüreğe düşen  Kor bir ateş mi desem.  Yoksa fısıltılarla söylenmiş sözcükler midir aşk.. Ya da seni bana sürekli hatır...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yılmaz']::text[], 8.5, '{"poet":"Selçuk Yılmaz","poet_slug":"selcuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamız', 'sevdamiz-huseyin-cakmak-0amhb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün

Gelecekte bir gün

Ülkeme güneş doğarsa

Ufuklar ağarıp

Gece utanırsa karanlığından

İşte o gün benim bayramımdır

sancaklar açıp yeni ufuklara doğru

doldurup yelkenleri

esen çağın rüzgarıyla

sürüklenmek değil

azgın denizlerde

acımasız dalgalara karşı

kürek çekmek 

sevdamız

boşa değil

(15.07.99-Ankara=', 'Bir gün Gelecekte bir gün Ülkeme güneş doğarsa Ufuklar ağarıp Gece utanırsa karanlığından İşte o gün benim bayramımdır sancaklar açıp yeni u...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çakmak']::text[], 8.5, '{"poet":"Hüseyin Çakmak","poet_slug":"huseyin-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdamiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostiş', 'akrostis-huseyin-cakmak-73yys', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel gözlüm

Ürkek ceylanım

Lüle lüle saçlarını 

Sarıp koklamak

Ellerini avuçlarıma alıp

Ruhuma katabilmek için

En uzun gecenin

Nihayetinde kalbime gömdüm seni

Ve 

Esrik bakışlarıyla

Umut dolu bir yumurcak

Mışıl mışıl uyuyorken

Uyandı birden

Ta kalbimdeki hasretim.

Umudu şafağımdı.

Siz 

En değerlisi

Ve 

İçtenisiniz sevgililerin

Yorgun gözlerimin

Oralarda kapandığı ve

Ruhumun derinliklerinde

Umarsızca açan yediveren güllerinin

Mistik kokular saçtığı baharımdasınız

(28.05.95-Ankara)', 'Güzel gözlüm Ürkek ceylanım Lüle lüle saçlarını  Sarıp koklamak Ellerini avuçlarıma alıp Ruhuma katabilmek için En uzun gecenin Nihayetinde ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çakmak']::text[], 8.5, '{"poet":"Hüseyin Çakmak","poet_slug":"huseyin-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkolsun Akşamüstü', 'askolsun-aksamustu-ferhan-sensoy-aame8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşkolsun akşamüstü

akşamüstü aşk küstü

nur bir boşluktur şimdi

zor bir boşluktur akşam

kırdı saydam kafesi

uçtu gitti can kuşu

mor bir boşluktur şimdi

şol gönlümün yoldaşı', 'aşkolsun akşamüstü akşamüstü aşk küstü nur bir boşluktur şimdi zor bir boşluktur akşam kırdı saydam kafesi uçtu gitti can kuşu mor bir boşlu...', ARRAY['Türk Edebiyatı','Şiir','Ferhan Şensoy']::text[], 8.5, '{"poet":"Ferhan Şensoy","poet_slug":"ferhan-sensoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askolsun-aksamustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen', 'beklenen-huseyin-cakmak-0wjr2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdam

Sızlar yüreğimde

Canımdan can koparırcasına

Ayrılık acısı duyumsarım

Dalar gözlerim

Bir akşam vakti

Ufukta ararım

Bekleneni

Sabırla 

Ve bin bir özlemle...

(17.08.99-Ankara)', 'Sevdam Sızlar yüreğimde Canımdan can koparırcasına Ayrılık acısı duyumsarım Dalar gözlerim Bir akşam vakti Ufukta ararım Bekleneni Sabırla  ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çakmak']::text[], 8.5, '{"poet":"Hüseyin Çakmak","poet_slug":"huseyin-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beklenen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutabilecek misin', 'unutabilecek-misin-i-rem-demirbas-v5lte', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bile seni unuttum sandım,

Sahte gülücükler saçtım.

Gece olunca da boş yere,

Yollarını gözleyip, 

Pencerede sabahladım.

Kaç gün oldu saymıyorum,

Her gün bir öncekinden beter,

Seni görmek için ölürken,

Olur da karşılaşırız diye, 

Başımı yerden kaldırmıyorum.

Karşılaşsak ne olacak ki?

Geri gelecek mi mutluluğumuz,

Unutacak mıyız geçmişi,

Söylenenleri, kavgalarımızı...

Geri gelmeyecekse mutluluğumuz,

Tekrar beni başının tacı yapmayacaksan,

Ben de yüzüne bakamayacaksam,

Ne anlamı var ki boynu bükük görüşmenin?

Ne kadar zor sensiz yaşamak,

Alışmışım sana yıllardır,

Sensiz hiç bir şey yapamıyorum,

Elim kolum bağlı, anılarınla yaşıyor,

Beni unutman için dualar ediyorum.

Unutabilecek misin zamanla?

Ben unutamam seni,

Ne verdiğin mutluluğu,

Ne de kalp kırıklıklarımı.

Her şeye rağmen iyi ki tanımışım seni,

Ne mutlu bana, sevmişim, sevilmişim...

Bundan böyle çok mutlu ol,

Ne miden ağrısın, ne kalbin,

Unut sana çektirdiğim acıları,

Bul kendine göre bir güzel,

Çocukların olsun boyunca,

Adları şimdiden belli nasıl olsa,

Buğra ve Dilara....', 'Ben bile seni unuttum sandım, Sahte gülücükler saçtım. Gece olunca da boş yere, Yollarını gözleyip,  Pencerede sabahladım. Kaç gün oldu saym...', ARRAY['Türk Edebiyatı','Şiir','İrem Demirbaş']::text[], 8.5, '{"poet":"İrem Demirbaş","poet_slug":"i-rem-demirbas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/unutabilecek-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Dostlar', 'yalanci-dostlar-huseyin-cakmak-badqj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne dostlar gördüm ben

Dost gülücüklü

Yılansı

Hiçbiri yıldırmadı

Aldırmadım

Senin sözlerine

Gücendiğim 

Kadar

(13.05.96-Ankara)', 'Ne dostlar gördüm ben Dost gülücüklü Yılansı Hiçbiri yıldırmadı Aldırmadım Senin sözlerine Gücendiğim  Kadar (13.05.96-Ankara)...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çakmak']::text[], 8.5, '{"poet":"Hüseyin Çakmak","poet_slug":"huseyin-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalanci-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gri Aşk', 'gri-ask-bulent-yuksel-nrtwm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıcaklık, mutluluk, sevgi, 

heyecan, iyimserlik, güven, 

zerafet, umut, fedakarlık, 

beyazdır...

Soğukluk, mutsuzluk, 

riyakarlık, kötümserlik, kin, 

öfke, ihtiras, intikam, 

siyahtır...

Grı her ikisidir... 

Aşk grıdir...', 'Sıcaklık, mutluluk, sevgi,  heyecan, iyimserlik, güven,  zerafet, umut, fedakarlık,  beyazdır... Soğukluk, mutsuzluk,  riyakarlık, kötümserl...', ARRAY['Türk Edebiyatı','Şiir','Bülent Yüksel']::text[], 8.5, '{"poet":"Bülent Yüksel","poet_slug":"bulent-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gri-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derviş Yunus', 'dervis-yunus-yunus-emre-rlwwo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tabtuk dergahından feyizler alan, 

Yanan Yunus idi,o derviş Yunus... 

Gönlünü derya,ummanlara salan, 

Dalan Yunus idi,o derviş Yunus... 

*** 

Gezer idi; iki Arşı alayı, 

Sevgi ile yoğururdu mayayı, 

Barış, Hoşgörü bir edip davayı, 

Bulan Yunus idi,O derviş Yunus 

*** 

Yetmiş üçe hep, bir nazar eyleyen, 

Herdem Hakkı hakikatı söyleyen , 

Aşk elinden kendin heder eyleyen, 

Kanan Yunus idi, o dervişYunus ... 

*** 

O bilmezdi kin ile kem hiddeti, 

Diler idi;Kahhar Haktan mededi, 

Şu fani dünyaya mehil vermedi, 

Canan Yunus idi,O derviş Yunus. 

*** 

Aşık Çağlari 

Amsterdam - Hollanda', 'Tabtuk dergahından feyizler alan,  Yanan Yunus idi,o derviş Yunus...  Gönlünü derya,ummanlara salan,  Dalan Yunus idi,o derviş Yunus...  ***...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dervis-yunus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzin Ver', 'i-zin-ver-murat-gencer-09sw0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bitmez susuzluğum bilmezmisin sana

Bırak öpeyim a$kımı doya doya

Bende yanıyorum istanbul’larda sana

İzin ver ne olur kor dudaklarıma

(İstanbu - 19/06/2001)', 'Bitmez susuzluğum bilmezmisin sana Bırak öpeyim a$kımı doya doya Bende yanıyorum istanbul’larda sana İzin ver ne olur kor dudaklarıma (İstan...', ARRAY['Türk Edebiyatı','Şiir','Murat Gençer']::text[], 8.5, '{"poet":"Murat Gençer","poet_slug":"murat-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/izin-ver-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-umit-kara-rftox', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'MEKTUP

Bir duygu seli ile hatırladım anıları

Göz yaşımı mürekkep yaptıp yazdım yazıları

İlmek ilmek düğümledim sana bu satırları

Mektup yazdım ah ile sana yolladım

Yüreğimi satırlara döktüm

Mektup bile ağladı halime

Bir zadegan gibi hiç ağlamadım

Hiç bakmadım halime

Sadece mektup yazdım

Anlattım sana bütün kahrı ile

Yazdım yazıları sana yolladım

Sensiz yaşadığım yılları

Çektiğim onca kahrı onca çileyi

Umudumun doğmayan güneşini

Gözlerimdeki ayrılık şebnemini

İçimde biriken hasret sancısını

Bir zarfa koydum sana yolladım

Bıraktığın güzel anıları

Aklımda kalmış bir kaç sözümü

Kalemimdetasvir olmuş yüzümü

Ayrılıktan viran düşmüş yüreğimin

Satırlara yansıyan özünü

Mektup yaptım sana yolladım

Giderken unuttuğun anıları

Belki bizim olacak yarınları

Aklımdaki karışık soruları

İçten bir name ile yazdım

Mektup yaptım sana yolladım

Beraber yürüdüğümüz yolları

Geçirdiğimiz güzel senli yılları

Birlikte söylediğimiz şarkıları

Arkadaşların selamlarını

Mektup yaptım zarfa koydum

Sana yolladım...

            ÜMİT KARA', 'MEKTUP Bir duygu seli ile hatırladım anıları Göz yaşımı mürekkep yaptıp yazdım yazıları İlmek ilmek düğümledim sana bu satırları Mektup yazd...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kara']::text[], 8.5, '{"poet":"Ümit Kara","poet_slug":"umit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mektup-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabayı Bılenlere', 'arabayi-bilenlere-erdal-canbulat-sue19', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönlünde yer yoksa bana güzelim; 

Farketmez ben ayakta da giderim.

Karayollarinda degil,senin kollarinda öleyim.

Rampalarin ustasiyim,gözlerinin hastasiyim.

Asiksan vur saza, söförsen bas gaza.

Sana taptigim kadar paraya tapsaydim milyarder, 

Allaha tapsaydim peygamber olurdum.

Sen gökyüzünde dogan günes, ben yollarda çilekes.

Yollar gidisime, kizlar durusuma hasta.

Gönlünde yer yoksa bana güzelim; 

Farketmez ben ayakta da giderim.', 'Gönlünde yer yoksa bana güzelim;  Farketmez ben ayakta da giderim. Karayollarinda degil,senin kollarinda öleyim. Rampalarin ustasiyim,gözler...', ARRAY['Türk Edebiyatı','Şiir','Erdal Canbulat']::text[], 8.5, '{"poet":"Erdal Canbulat","poet_slug":"erdal-canbulat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/arabayi-bilenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Samurak Ushuri', 'kayip-samurak-ushuri-cem-erbay-of06l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlık,karanlıkla beslenirken ruhum, kılıcımın ışığı

Yardı bu anın durgunluğunu, ben kayıp samurayım.

Ustam yok tek başına aramaktayım Tanrımı ve yolumu

Bu kılıçla aç insanların ekmeğini paylaştırdım.

Kara ejderler çevrelemiş her yeri

Hırs ve açgözlülük her yerde

Ustalar cok uzakta 

Yaşlı resimlerine bakarken

Huzur ve sevgi gormez oldum o yüzlerde

Yazık bu dünyaya aşkı unuttuk romanlarda,filmlerde

Savaşlar ve ölümler yok etti dünyayın güzelliklerini

Hep mi böyle hayır çünkü kayıp samuraylar kanatlı melekler gibi,

Başucunuzda olabilir kötülüğe direnen son kaleler gibi.

Bu siir bulamadığım ve aradığım sevgiliminde dikkatini çekecek.

Henüz tanımadığım o kadına ,sevgimle gösterecegim hayatın en büyük

Güzelliğini ,Şövalyelerde yapardi aynisini yazardi aşklarına

Aynı şiirleri .

Kılıcımla ben varım kanser hastasının göz yaşında,sokaktaki itilmiş çocuklarla , tüm acı çekenlerin yaninda ,afrikada ,asyada tüm kıtalar ve denizin dibinde,kesfedilmemiş gezegenlerde.

Adım Ushuri Tanaka Japonya’da , ama ben hepiniz kardeşi kayıp samurayım isimsiz anın beni tüm uçan kuşların kanadında.', 'Yalnızlık,karanlıkla beslenirken ruhum, kılıcımın ışığı Yardı bu anın durgunluğunu, ben kayıp samurayım. Ustam yok tek başına aramaktayım Ta...', ARRAY['Türk Edebiyatı','Şiir','Cem Erbay']::text[], 8.5, '{"poet":"Cem Erbay","poet_slug":"cem-erbay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kayip-samurak-ushuri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağırayım Mevlam Seni', 'cagirayim-mevlam-seni-yunus-emre-nw9n8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağlar ile taşlar ile

Çağırayım Mevlâm seni

Seherlerde kuşlar ile

Çağırayım Mevlâm seni

Sular dibinde mâhiyle

Sahralarda âhû ile

Abdal olup yâhû ile

Çağırayım Mevlâm seni

Gök yüzünde İsâ ile

Tûr dağında Mûsâ ile

Elimdeki asâ ile

Çağırayım Mevlâm seni

Derdi öküş Eyyûb ile

Gözü yaşlı Ya’kûb ile

Ol Muhammed mahbûb ile

Çağırayım Mevlâm seni

Hamd ü şükrullah ile,

Vasf-ı Kulhüvallah ile

Daima zikrullah ile,

Çağırayım Mevlam seni 

Bilmişim dünya halini

Terk ettim kıyl ü kâlini

Baş açık ayak yalını

Çağırayım Mevlâm seni

Yûnus okur diller ile

Ol kumru bülbüller ile

Hakkı seven kullar ile

Çağırayım Mevlâm seni', 'Dağlar ile taşlar ile Çağırayım Mevlâm seni Seherlerde kuşlar ile Çağırayım Mevlâm seni Sular dibinde mâhiyle Sahralarda âhû ile Abdal olup ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cagirayim-mevlam-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Gibi', 'benim-gibi-sebahattin-altan-5ckew', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hiç büyülü koku çektinmi içine tenin gibi

varmı güzelim tatlı ve hoş senin gibi

hayatta bazen boğar insanı ölüm gibi

tutunacak bir dost bir dal bir ışık ararsın benim gibi

yaşam kısa çabuk geçip gider zaman

geriye bakarsın her sey toz duman

bir gün uçup gideceğiz  bu dünyadan

yaşama hasret doğaya tutkun sana sevdalımıısn benim gibi

tüm emegimiz iyi bir yaşam için

neler yapıp neler çekiyoruz kimin için

solan çiçekler gibi her şeyi arayacağız bir gün

suya hasret sevgiye hasret sana sevdalımısın benim gibi', 'hiç büyülü koku çektinmi içine tenin gibi varmı güzelim tatlı ve hoş senin gibi hayatta bazen boğar insanı ölüm gibi tutunacak bir dost bir ...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Altan']::text[], 8.5, '{"poet":"Sebahattin Altan","poet_slug":"sebahattin-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Osman', 'osman-sebahattin-altan-cjpe8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uzun yaşamından çok şey geçmiş başından

yıllara direnmiş yorgun bedeni

tüm güçlüğe alışmış taki sevdiğini kaybedeli

karısına hasret sevgiye hasret kalmış eşi öleli

altmışından sonra yemiş hayattan darbeyi

buruşturulup atılmış bir  kağıt gibi sokaklarda şimdi

oğlumu gelinimi bilinmez sebebi

bir park köşesi bir naylon altı olmuş artık evi

anılarıda geçmez olmuş gözünden incinmemek için

bir sabah naylonu kaldırmış parktaki çoçuklar

osman kaskatı uçup gitmiş sevdiğine eşine bu dünyadan

yüzünde tatlı bir gülüş öç alır gibi.....', 'uzun yaşamından çok şey geçmiş başından yıllara direnmiş yorgun bedeni tüm güçlüğe alışmış taki sevdiğini kaybedeli karısına hasret sevgiye ...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Altan']::text[], 8.5, '{"poet":"Sebahattin Altan","poet_slug":"sebahattin-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/osman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Sonbahar', 'mevsim-sonbahar-selen-noyan-kohc0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün kapıma geleceksin

Ama nafile bulamayacaksın

Beni ararken bir ses duyucaksın

Bu saatte ezan okunurmu diyeceksin

Bu ezan değil sela diyecekler

Kimin selası diye soracaksın

Birgün bırakıp gittiğin sevgilinin diyecekler

Üzülüp ağlayacaksın

Üstüme koyacak bir gül arayacaksın

Ama nafile bulamıyacaksın

Çünkü   mevsim SONBAHAR', 'Bir gün kapıma geleceksin Ama nafile bulamayacaksın Beni ararken bir ses duyucaksın Bu saatte ezan okunurmu diyeceksin Bu ezan değil sela di...', ARRAY['Türk Edebiyatı','Şiir','Selen Noyan']::text[], 8.5, '{"poet":"Selen Noyan","poet_slug":"selen-noyan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mevsim-sonbahar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık Olur Vatana', 'yazik-olur-vatana-ozan-arif-za23i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Meydan sizin...Onun bunun sözünü,

Duyarsanız yazık olur vatana.

Kuru lafla memleketin gözünü

Boyarsanız yazık olur vatana.

Eğilin milletten yükselen sese

Mavi boncuk dağıtmayın herkese

Hoşgörü bezinden takım elbise

Giyerseniz yazık olur vatana.

Bilinmeli Mataracı sürüsü

Ötmemeli Yahya''ların borusu

Aç beklerken memleketin yarısı

Doyarsanız yazık olur vatana.

Atatürk maskesi,hayran firenge

Bak şimdi de girdi Kemalist renge

Her devrin köpeği şu pezevenge

Uyarsanız yazık olur vatana.

Hatırını gütmen bilmem ne beyin

Herkesin suçunu yüzüne deyin

Şimal rüzgarına dikkat eyleyin

Buyarsanız yazık olur vatana.

Düşman olup milli birlik çağrıma

Koministler yara açtı böğrüme

Siz de süngünüzü benim bağrıma

Dayarsanız yazık olur vatana.

Beşik yapıp kollarımı dizimi

Ben büyüttüm ''ordu'' adlı kuzumu

Ben büyüttüm diye benim gözümü

Oyarsanız yazık olur vatana.

Dörtbin şehit verdik yurda hediye

Düşünün bir defa acaba niye?

Koministle beni aynı kefeye

Koyarsanız yazık olur vatana.

Arif hazır size destan yazmaya

Söz verdiniz ihaneti bozmaya

Söz verdiniz kominizmi ezmeye

Cayarsanız yazık olur vatana.', 'Meydan sizin...Onun bunun sözünü, Duyarsanız yazık olur vatana. Kuru lafla memleketin gözünü Boyarsanız yazık olur vatana. Eğilin milletten ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yazik-olur-vatana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Değil', 'yalan-degil-ozan-arif-hkgih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vah zavallı Türkiye''m!

Soluyor yalan değil.

Başa geçen onu yem

Biliyor yalan değil.

Ne yol aldık ne menzil

Bugün dünden de rezil

Halkın karnı yine zil

Çalıyor yalan değil.

Kuran kurmuş ağını

Uzatmış ayağını

Bal tutup parmağını

Yalıyor yalan değil.

Zengin zengindir bre

Sırtı gelir mi yere?

Olan yine fakire

Oluyor yalan değil.

Torpil ile masalar

Rüşvet ile keseler

Vurgun ile kasalar

Doluyor yalan değil.

Bir yer biri bakar

Kıyamet ondan kopar

Felaket apar topar

Geliyor yalan değil.

Devlet baba nerdesin?

Ozan Arif neylesin?

Babalık vasfın kesin

Ölüyor yalan değil.', 'Vah zavallı Türkiye''m! Soluyor yalan değil. Başa geçen onu yem Biliyor yalan değil. Ne yol aldık ne menzil Bugün dünden de rezil Halkın karn...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yalan-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babo !..', 'babo-ozan-arif-mk92i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben köylü vatandaşım,

Kim benim dostum babo?

Bu ne hırs bun ne hışım?

Sesimi gıstım babo.

Kiminiz bana güler

Kiminiz aptaldır der

Baştaki efendiler

Ben size küstüm babo.

Damarda kanım kurban

Şerefim şanım kurban

Devlete canım kurban

Sizedir kastım babo...

Ne oruç ne söfür,

Din iman sizde sıfır

Ağzıma geldi küfür

Yine de sustum babo...

Seçimde reye-meye

Geldiniz bizim köye

Ben sizi adam diye

Bağrıma bastım babo...

İstemem sevmeyin lo..

Baştan da savmayın lo..

Kapıdan kovmayın lo...

Toz diye üstüm babo...

İşime zor dediniz

Ürüşvet istediniz

Ben ektim siz yediniz

Soyuldu postum babo...

Devletin malı sizin

Kaymağı balı sizin

Küpünüz dolu sizin

Boş benim testim babo...

Yapılan ne bak hele

Patlarsın güle güle

Köyümde yok yok ula

Büstüm var büstüm babo...

Anarşist çıktı bir de

Onlarla girdim derde

Üstelik hapislerde

Az mı kan kustum babo?', 'Ben köylü vatandaşım, Kim benim dostum babo? Bu ne hırs bun ne hışım? Sesimi gıstım babo. Kiminiz bana güler Kiminiz aptaldır der Baştaki ef...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/babo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Sabahı', 'bayram-sabahi-turgay-ulusoy-vdcz7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine bir bayram sabahı,

Bir çocuk gördüm,

Sokakta.

O kadar mahzun bakışlı,

Ve o kadar da ürkek.

Taa burdan hissediyorum,

Çarpıyordu yüreği.

Hani kanadı kırık bir kuş,

Yüreği  gibi.

Kimsesiz garip,

Sırtında boyacı sandığı,

Yırtık,

Eski ve kirli elbise,

Ayağında bir terlik,

Ya çorabından fırlayan,

Parmağa ne demeli.

Bir çocuk gördüm,

Bayram sabahı.

Elinden tutup götürmek,

İsterdim lunaparka.

Doyasıya binseydi atlı karıncaya.

Elinde elma şekeri,

Bir elinde de bir oyuncak.

Ayağında delik olmayan çorabıyla,

Bir de gıcır gıcır bot.

Görmek isterdim,

Üzüm karası gözlerindeki,

Pırıltıyı,

O sımsıcak gülüşü.

Ah keşke,

İsterdim.

Hayatımda olmasaydı,

Ah keşke', 'Yine bir bayram sabahı, Bir çocuk gördüm, Sokakta. O kadar mahzun bakışlı, Ve o kadar da ürkek. Taa burdan hissediyorum, Çarpıyordu yüreği. ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bayram-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-turgay-ulusoy-lrtm4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilirim bebekleri,

En az sizlerinde bildiği kadar.

Saf ve temiz,

Gülün üstündeki bir çiğ damlası kadar.

Ne kadarda parlak,

Gözlerindeki ışık,

İnsanın yüreğini ısıtan,

Hani kalırsında bir dağ yamacında,

Yaşama sevinci verirler insana,

Karşılıksız.

Gülüşleri çıkarsız,

Sevgileri.

Ya! Dokunuşlarına ne demeli,

Sanki bir su damlasını severcesine.

O kadar nazik,

O kadarda nazlı.

Ama kirlenecekler onlarda,

Bizler gibi büyüyecekler.

Büyüdükçe öğrenecekler,

Kirlenmenin ve hayatın,

Tüm çirkinliklerini,

Ve onlarda öğrenecekler,

Aynı bizler gibi.', 'Bilirim bebekleri, En az sizlerinde bildiği kadar. Saf ve temiz, Gülün üstündeki bir çiğ damlası kadar. Ne kadarda parlak, Gözlerindeki ışık...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bebek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-turgay-ulusoy-pjt9i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalında çiçekler solarda bir gün,

Yağmaz olup ta yağmurlar,

Tomurcuk olup ta meyve vermezse ağaçlar,

Sende beni hatırla unutma sevdiğim.

Doğmak isteyip de doğmazsa güneş,

Gece olup ta çıkmazsa yıldızlar,

Şarkı olup ta aşkımız söylenmezse dillerde,

Sende beni hatırla unutma sevdiğim.', 'Dalında çiçekler solarda bir gün, Yağmaz olup ta yağmurlar, Tomurcuk olup ta meyve vermezse ağaçlar, Sende beni hatırla unutma sevdiğim. Doğ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beni-hatirla-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-turgay-ulusoy-2vpqg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resmini koydum da yine onüme,

Uzun uzun dertleştik seninle bu akşam.

Mutlu yarınlardan konuşup özlerken,

Hasret olup birbirimize aktık bu akşam.

Bakıp ta bana gülümsüyormuşcasına,

O kadar saf ve güzeldin bu akşam.

İkimizde hasretmişiz ki aşka,

Mutluluğa koştuk seninle bu akşam.', 'Resmini koydum da yine onüme, Uzun uzun dertleştik seninle bu akşam. Mutlu yarınlardan konuşup özlerken, Hasret olup birbirimize aktık bu ak...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-aksam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırpınış', 'cirpinis-turgay-ulusoy-fjqxk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuru bir yaprak isyan ediyordu kaderine,

Rüzgar önüne katmış sürüklerken.

Koparılmıştı dalından hasretti sevdiğine,

İki damla yaş süzülüyordu,

Sessizce gözlerinden.

Feryat figan içinde savrulurken,

El uzatmış yardım dileniyordu.

Bilmiyordu ki kimseden kimseye fayda yokken,

Yazısına boyun eğmiş,

Sonunu bekliyordu.', 'Kuru bir yaprak isyan ediyordu kaderine, Rüzgar önüne katmış sürüklerken. Koparılmıştı dalından hasretti sevdiğine, İki damla yaş süzülüyord...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cirpinis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur', 'dur-turgay-ulusoy-jxsrf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dur gitme sevgili dur,

Ne olur bir şans daha.

Farzet ki,

Bir idam mahkumu,

Yaşanacak neyi kalmış ki, 

Kalan üç,beş dakikası.

Dinle birde beni benden,

Rüyalarımı,hayallerimi ve,

Özlemlerimi.

Sana olan susuzluğu mu.

Farzet ki bir rüya,

Uyandırma,

Bırak.

Rüyalarımda sarayım seni,

Başımı dizlerine koyup,

Sevda şiirleri sunayım sana.

Bırak.

Gözlerim değsin gözlerine,

Nefesim nefesine,

Ellerim ellerime.

Okşasın tomurcuk bir gülü okşarcasına.

Kavuşsun sana bedenim,

Dalgaların sahile kavuşurcasına.

Aksın sana tüm benliğim,

Irmakların denize akarcasına.

Dur gitme sevgili dur,

Bir şans daha.', 'Dur gitme sevgili dur, Ne olur bir şans daha. Farzet ki, Bir idam mahkumu, Yaşanacak neyi kalmış ki,  Kalan üç,beş dakikası. Dinle birde ben...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ertelenmeli', 'ertelenmeli-turgay-ulusoy-h0grd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ertelenmemeli,

Mutluluklar yarına.

Dünlerde bu günler kadar yarındı,

Bir dahaki sefer olmamalı asla.

Ve taşınmamalı,

Geçmişten geleceğe,

Yaşanmış pişmanlıklar.

Zaman bu zaman ya yaşıyorsun,

Yada kaçıyorsun hayattan.

Sarmış gibi her yanını,

Akşamların karanlık pusu,

Kaplamış ruhunu derinden derine,

Sonu görünmeyen yollarda,

Yürümek ve dibi karanlık,

Sularda yüzmek gibi.

Artık bu gün gün değil,

Bizler tükendik.

Anılarda kalan sadece mutluluklar.

Ne umutlar tükettik,

Bir hayal uğruna.

Farzet ki bir rüyaydı,

Tüm bu yaşananlar.

Belki yine erteleyeceğiz,

Hiç ders almamışcasına.

Ve biliyoruz ki,

Asla olmayacak yarınlar.', 'Ertelenmemeli, Mutluluklar yarına. Dünlerde bu günler kadar yarındı, Bir dahaki sefer olmamalı asla. Ve taşınmamalı, Geçmişten geleceğe, Yaş...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ertelenmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-turgay-ulusoy-bhhdj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine gece ve yine soğuk,

Issız,hüzün dolu karanlık.

Elimle  tutmak isterdim,

Gökte ki yıldızları,

Paylaşsınlar yalnızlığı mı.

Uzakta yanan,

Çoban ateşini isterdim,

Yanım da,

Isıtsın içimi diye.

Denizlerdeki yakamozların,

Işıltısını isterdim.

Yüreğimi aydınlatsın diye.

Çok mu şey istedim ki,

Hayattan ben.

Sadece,

Ertelenmesin mutluluklar,

Yarını olmayan yarınlara.

Geç kalmazmıyız ki,

Bir dahaki sefere.', 'Yine gece ve yine soğuk, Issız,hüzün dolu karanlık. Elimle  tutmak isterdim, Gökte ki yıldızları, Paylaşsınlar yalnızlığı mı. Uzakta yanan, ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gece-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemi', 'gemi-turgay-ulusoy-omp2m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ufukta görünen gemi,

Şişirmiş yelkenlerini yosun kokulu,

Rüzgarlarla.

Nasılda yanaşıyor rıhtıma,

Özen gösteriyor incitmemeye,

Sanki rıhtım bir sevgili.

Dalgın,mahzun seyrediyorum,

Seni bana mı getirdi ne.

Yoksa,

Beni senden mi alacak ne.

İniyor yolcular birer,ikişer,

Hepsi ne kadarda mutlu,

Ve ne kadar da çoşku lu.

Kavuşuyor rıhtımdakiler ve,

Gemiden inenler.

Kimisi sevdiğini bekliyor,

Kimi dostunu kimide eşini.

Kimse kalmadı artık rıhtımda,

Gemi yalnız,ama bir o kadarda mutlu,

Kavuşturdu sevenleri sevdiklerine,

Görevini yerine getirmiş insanlar kadarda,

Huzurlu.

Ve ben yalnız o kadarda mutsuz,

Gözlerim bir başka gemiyi arıyor,

Gözlerim kapalı,

Hayal ediyorum rıhtıma yanaşan gemiyi,

Ve gemiden inenleri.

Bir öncekiler ne kadarda mutluydu,

Gözleri ne kadarda ışıltılı.

Ve gemi öttürüyor acı acı düdüğünü,

Ağır,ağır rıhtımdan ayrılırken,

Gemi yalnız ama mutlu.

Ve ben yalnız.', 'Ufukta görünen gemi, Şişirmiş yelkenlerini yosun kokulu, Rüzgarlarla. Nasılda yanaşıyor rıhtıma, Özen gösteriyor incitmemeye, Sanki rıhtım b...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gemi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelim', 'guzelim-turgay-ulusoy-h9pto', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Giderken yaktığın ateş,

Dönünce söner mi zannedersin.

Sönmez bir tanem sönmez.

Öyle bir yara ki,

Hiçbir tabib derman bulmaz.

Unutulur mu sanırsın,

Yaşananlar.

Her anım da sen varsın,

İçtiğim sigara da,

Soluduğum hava da,

Gözlerimin baktığı her yer de,

Sen varsın güzelim.

Ya o gözlerini,

Ilık nefesini,

Teninin kokusunu,dudaklarının sıcaklığı nı,

Unutulur mu sanırsın.

Unutmam güzelim,

İnan ki unutmam.', 'Giderken yaktığın ateş, Dönünce söner mi zannedersin. Sönmez bir tanem sönmez. Öyle bir yara ki, Hiçbir tabib derman bulmaz. Unutulur mu san...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guzelim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-turgay-ulusoy-kizlg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdiğim,

Sende benim gibi hasret kalıpta sevgiye,

Uğruna adaklar diktin mi hiç?

İçindeki hasret dökülüp de çoşku ya,

Sevdiğine ırmak olup ta aktın mı hiç.

Eller birleşip,dudaklar kavuşunca,

Sarılıp sevdiğine ılık ılık aktın mı hiç?

Engelleri aşıp ona kavuşmak isteyip de,

Ferhat olup dağları deldin mi hiç.', 'Sevdiğim, Sende benim gibi hasret kalıpta sevgiye, Uğruna adaklar diktin mi hiç? İçindeki hasret dökülüp de çoşku ya, Sevdiğine ırmak olup t...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hasret-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Değişti', 'her-sey-degisti-turgay-ulusoy-zoiy8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şey değişti hayatımda,

Güneş bir farklı doğuyor,

Batışı bir farklı.

Yağmurların yağışı bile değişti,

Eskisi gibi çıkmıyor artık,

Parlak değil ebem kuşağı.

Tarihler değişti takvimde,

Ardı ardına.

Saçlarımın aklarına nazire,

Yaparcasına.

 Nefes alışım.yürüyüşüm,

Hani çok sevdiğin bakışlarım bile.

Ama her şey.

İskeleye yanaşan balıkçı motorları bile,

Eskisi gibi gelmiyor peşlerinden,

Martılar.

Balık yüklü değil artık ağlar.

Evet değişti her şey,

Ama ben asla.', 'Her şey değişti hayatımda, Güneş bir farklı doğuyor, Batışı bir farklı. Yağmurların yağışı bile değişti, Eskisi gibi çıkmıyor artık, Parlak ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Ulusoy']::text[], 8.5, '{"poet":"Turgay Ulusoy","poet_slug":"turgay-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/her-sey-degisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ak sayfa', 'ak-sayfa-huseyin-cakmak-jxi7k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay yok bu gece

Küstü mü yoksa

Neden aydınlatmıyor 

Geceyi 

Oysa 

Alaca aydınlatsa ortalığı

Açsa güzelliklerin üstünü

Kötülüğe dokunmadan

Salsa ışıklarını bir hüzme

Delip karanlığı.

Aydınlatsa ki

Zifiri karanlık  puslu gecede

Defterinin ak sayfalarını

Nasıl karalamışlar 

Ülkemin

Görsünler...

(05.12.00-Ankara)', 'Ay yok bu gece Küstü mü yoksa Neden aydınlatmıyor  Geceyi  Oysa  Alaca aydınlatsa ortalığı Açsa güzelliklerin üstünü Kötülüğe dokunmadan Sal...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çakmak']::text[], 8.5, '{"poet":"Hüseyin Çakmak","poet_slug":"huseyin-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ak-sayfa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-huseyin-cakmak-qhab0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey

Kokuşmuş yürek

Taş kesmiş

Vicdan

Örümcek bağlamış beyin

Duy artık 

Beni 

Sen beni yok edemezsin

Çünkü ben

Sevdayım...

Hasretim... 

Kavgayım...

Özgürlük savaşçısıyım.

Çünkü ben..

Senin aklının almadığı

Kalbinin duymadığı

Vicdanının anlayamadığı

Bir ütopyayım

Çünkü

 Ben bir

İNSANIM

(08.04.01-Ankara)', 'Ey Kokuşmuş yürek Taş kesmiş Vicdan Örümcek bağlamış beyin Duy artık  Beni  Sen beni yok edemezsin Çünkü ben Sevdayım... Hasretim...  Kavgay...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çakmak']::text[], 8.5, '{"poet":"Hüseyin Çakmak","poet_slug":"huseyin-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyor musun', 'biliyor-musun-huseyin-cakmak-vo9rj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne düşünüyorum biliyor musun

Yağmurun ellerinden tutup

Sevgiyi kucaklamayı

Rüzgarın kanatlarında

Yıldızlara  takılıp

Güneşin gözlerinden öpmeyi

İşte böyle ulaşılmaz dır 

İsteklerim

Sevdalar yaşarım yürek isteyen

Dostluklar kurarım

Paylaşımları olan

Çıkarlara değişilmeyen

Arkadaşlıklar...

Yani zordur bu hayatı

 Benle yaşamak arkadaş.

.

(17.06.01-Ankara)', 'Ne düşünüyorum biliyor musun Yağmurun ellerinden tutup Sevgiyi kucaklamayı Rüzgarın kanatlarında Yıldızlara  takılıp Güneşin gözlerinden öpm...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çakmak']::text[], 8.5, '{"poet":"Hüseyin Çakmak","poet_slug":"huseyin-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biliyor-musun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben 2', 'ben-2-huseyin-cakmak-el36z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Kim geldi 

-Ben 

-Hoş geldin Ben

 Ama sen hiç gitmedin ki

 Her yerde sen yok musun

 Ben 

 Ben-cil

 Ben-im

 Ben-zer

 Ben-cillik

 Ben,ben,ben,ben

 Keşke sen gitseydin de Ben

 O 

 Onlar

 Biz

 Bizler

 Binler olsaydık.

          (18.04.1997-Ankara)', '-Kim geldi  -Ben  -Hoş geldin Ben  Ama sen hiç gitmedin ki  Her yerde sen yok musun  Ben   Ben-cil  Ben-im  Ben-zer  Ben-cillik  Ben,ben,ben...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çakmak']::text[], 8.5, '{"poet":"Hüseyin Çakmak","poet_slug":"huseyin-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-ali-kinik-yj1xp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir zemheri günü dirilir kardelen

Coşar türkü türkü yorulur kardelen

Kader ise eğer o da boyun eğer

Hoyrat eller değer vurulur kardelen

Yıllık bir görüşte ilk ve son gülüşte

Bir günlük bir düşte görülür kardelen

Kutsal bir toprağı öper gül dudağı

Sararır   yaprağı ölür kardelen

Zemheride olsun sonsuzlukta buluşmak

İhanet olmasın baharla sevdamızda

Kardelen vakitsizliği desinler

Akşam  ayaz ve beyaz yalnızlıkla örtülsün sevdalarım

Güle güle KARDELEN güle güle', 'Bir zemheri günü dirilir kardelen Coşar türkü türkü yorulur kardelen Kader ise eğer o da boyun eğer Hoyrat eller değer vurulur kardelen Yıll...', ARRAY['Türk Edebiyatı','Şiir','Ali Kınık']::text[], 8.5, '{"poet":"Ali Kınık","poet_slug":"ali-kinik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kardelen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünde Böyle Geçti', 'bugunde-boyle-gecti-selami-simsek-27bjv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugünde böyle gecti

Ne arayan var ne soran

Biz nasıl düştük buraya 

Kim di burayı hayra yoran 



Bugünde böyle gecti

Yine dert bulutu, yine boran 

Kuşattı her yöremizi 

Hem önden hem arkadan



Bugünde böyle gecti

Yine kahır, yine isyan 

Melekler çekip gitti

Şeytana kaldı  meydan 



Bugünde böyle gecti

Zulme karşı yine çıkmadı haykıran 

Bir yiğit seda esmedi 

Yıllar varki bizim semalardan 



Bugünde böyle gecti

Bir yanda gülen insan

Öbür yanda ağlayan 

Vicdanlarda sam yeli

Ruhlarda hafakan

17.06.2001 Stuttgart', 'Bugünde böyle gecti Ne arayan var ne soran Biz nasıl düştük buraya  Kim di burayı hayra yoran  Bugünde böyle gecti Yine dert bulutu, yine bo...', ARRAY['Türk Edebiyatı','Şiir','Selami Şimşek']::text[], 8.5, '{"poet":"Selami Şimşek","poet_slug":"selami-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bugunde-boyle-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalansiz Bir Dunya İstiyorum', 'yalansiz-bir-dunya-i-stiyorum-emrullah-erdinc-cxfjg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalansiz bir dunya istiyorum

Yalansiz bir dunya istiyorum sevmek ve sevilmek  icin

Durust bir arkadaslik istiyorum

Riyasiz  hiylekarsiz arkadaslik istiyorum sevmek ve sevilmek  icin 

Karsiliksiz menfaat beklemeden sevmek  ve sevilmek istiyorum 

Insanca sevmek insanca sevilmek istiyorum 

Istiyorum be arkadas gercek bir sevgi istiyorum iste 

Hilesiz yalansiz gercek bir sevgi istiyorum 

Sevmek ve sevilmek  istiyorum  arkadasim 

Ama ben herkezi seviyorum hic  karsilik beklemeden  arkadasim', 'Yalansiz bir dunya istiyorum Yalansiz bir dunya istiyorum sevmek ve sevilmek  icin Durust bir arkadaslik istiyorum Riyasiz  hiylekarsiz arka...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalansiz-bir-dunya-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünki', 'dusunki-cevahir-evren-08yby', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'düşün ki; başında paralansın yalnızlığın, 

ve bir baykuş kadar derine dalsın 

gözlerin...

an gelir bulgular olsun yatağında

uyanınca hep orda kalsın

bırak hayatın saatini

sana anlamsızlığı anlatsın...', 'düşün ki; başında paralansın yalnızlığın,  ve bir baykuş kadar derine dalsın  gözlerin... an gelir bulgular olsun yatağında uyanınca hep ord...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dusunki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbakır', 'diyarbakir-cevahir-evren-gm6m0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kaldırınca kaldırımlar 

ve pusudaysa gece lambaları

yalnızsa küçük oğlan 

ve adını bilmiyorsa anasının

sıcak tarlasıda ırgatıysa ağasının

neylesin diyarbakır...

koşarak geldim evimin bahçesine 

evimin diyorum anamın babamın 

kaldığı yere,

kimseler yoktu ses veren yoktu...

korkuyordum oracıkta

kimseler yoktu anlatabildiğim,

ben yalnız kalmıştım diyarbakır ne yapsın...

sevdalım vardı on beşimde 

çocuklarıyla geçti, tanıdı mı bilmem

tanısa ne yapsın...

yalvardım tanrıya hayata 

bir bebek sesiydi beni kabuğumdan alan

ağlıyor mu gülüyor mu belli değil

anası çoktan gitmiş babası zaten ölmüş

ben kendime mi yanayım...', 'kaldırınca kaldırımlar  ve pusudaysa gece lambaları yalnızsa küçük oğlan  ve adını bilmiyorsa anasının sıcak tarlasıda ırgatıysa ağasının ne...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/diyarbakir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem', 'kalem-cevahir-evren-k475k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kağıt parçası için mi

yaratıldı kalem?

yoksa kalem hep vardı da 

kağıt mı kalem için yaratıldı?

elimde bir kalem yazmaya başlasam 

kesin sana aşığım,

bıraksam gitsem oracıktan 

bunu sen bilmeyeceksin

elimde bir kalem

her yere yazıyorum 

seni beni herkesi

sen de biliyorsun simdi

ben sana aşığım

bırakıp gitsem de nafile artık...

bir kağıt parçası için mi yaratıldı kalem,

yoksa ben kalemsiz mi yazdım her yere 

sana aşık olduğumu...', 'bir kağıt parçası için mi yaratıldı kalem? yoksa kalem hep vardı da  kağıt mı kalem için yaratıldı? elimde bir kalem yazmaya başlasam  kesin...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-abacan-askisev-senkal-34xy2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinde masmavi bir pırıltı,

Yanaklarında küçük gamzeler var.

Dudaklarında sıcak bir tebessüm,

Saçlarında yumuşak dalgalar...

Kalbinde hep mutlu olma isteği,

Aklında belki başka biri! 

Ellerin ellerimde sımsıkı,

Hayalinde tatlı düşler var...

Üzerinde kolsuz, renkli bir tişört,

Boynunda hediyem olan kolye.

Çıplak ayaklarında ince kumlar,

Bacaklarında tuzlu sular var...

Kumsalda ılık, hafif bir rüzgar,

Engin denizde sakin dalgalar.

Yukarda bulutlar ve mavi gök,

Yanımda  biricik sevgilim var...

Bugün bile hayalimde o günler,

Kulaklarımda çınlar tatlı sesin.

İçimde hala o ilk hevesim,

Ve kalbimde bıraktığın iz var...

Artık yanında ben değil yabancılar,

Seni çok seven arkadaşların var.

Benim ise saçımda çoğalmış aklar,

Teselli bulduğum bir kadehim var...

Yıllar geçti de, bugün olduysam ihtiyar,

Sonunda rahat edeceğim bir yer var! 

Sana bırakacağım yegane yadigar,

Eski hatıralar ve soğuk bir mezar...', 'Gözlerinde masmavi bir pırıltı, Yanaklarında küçük gamzeler var. Dudaklarında sıcak bir tebessüm, Saçlarında yumuşak dalgalar... Kalbinde he...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevgilim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün İstediği', 'gonlumun-i-stedigi-abacan-askisev-senkal-xo33y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevgi ki, asla azalmamış,

Bİr heves ki, hiç tadılmamış,

Bir rüya ki, sabah uyanılmamış...

Bir sevgili ki, teni okşanmamış,

Bir gonca gül ki, hiç solmamış,

Bir buse ki, izi kaybolmamış...

Bir mutluluk ki, kanılmamış,

Bir anı ki, tekrar yaşanmamış,

Bir şiir ki, başkasına yazılmamış...

Bir insan ki, hiç bozulmamış,

Bir eski dost ki, unutulmamış,

Bir coşkun kalp ki, hiç kırmamış...

Bir çığlık ki, hiç susmamış,

Bir uzak diyar ki,ulaşılmamış,

Bir deniz ki, suyu durulmamış...

Öyle bir gün ki, hiç doğmamış,

Öyle bir dünya ki, hiç olmamış,

Şu kırgın gönlümün istediği,

Özlediği ne de çok şey varmış! ...', 'Bir sevgi ki, asla azalmamış, Bİr heves ki, hiç tadılmamış, Bir rüya ki, sabah uyanılmamış... Bir sevgili ki, teni okşanmamış, Bir gonca gül...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gonlumun-istedigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Yelkenli', 'kucuk-yelkenli-abacan-askisev-senkal-jhpul', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaklarda gezen küçük yelkenli; 

Dalgaların üzeride salınır hevesli.

Kıpırdayan denizin içinde,

Bir yol arar kendi kendine...

Bazen rüzgarlarla yarışır,

Bazen yapayalnız gezer.

Gün batarken süzgün olur,

Yorgun ve yalnız kalır! 

Kararan gökyüzüne meydan okur,

Bir gayretle sallanıp durur.

Karanlıklar çökmeden ufka,

Son bir kere görünür bana...

O, küçük ama mağrur yelkenli,

Rüyalarımdaki hayalin gibi! 

Zaman zaman hatırlatır seni,

Seni ve seninle geçen günleri...

Hatıralardaki mutluluk gibi,

Yavaşça kaybolur küçük yelkenli!', 'Uzaklarda gezen küçük yelkenli;  Dalgaların üzeride salınır hevesli. Kıpırdayan denizin içinde, Bir yol arar kendi kendine... Bazen rüzgarla...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kucuk-yelkenli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Kelimelerden Büyük', 'butun-kelimelerden-buyuk-nemir-enver-xdnw0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülayşem!

Defterimde dans ediyor

Binlerce kelime...

Yakıyorlar sayfa kenarlarını:

Biri

Sarı elbiseli...

Bir diğeri

Kırmızı...

Ben bu dünyâda

Yalnız değilim

Âilem:

Bir demet beyit...

***

Ben:

Bir seyyâr aşk şairiyim

Bütün balkonlar

Tanırlar beni.

Tanır beni bütün güzeller.

Hiçbir divitin aklından geçmeyen

Aşk için kelimelerim var...

***

Güneşin

Pencerelerini

Tek tek ben açtım; ve

Oraya ben demir attım...

Birbiri ardına denizler aştım...

Dalga diplerini kazıdım, ve

İstiridye kabuklarında

Daha önce hiç söylenmemiş,

Fırça ucuna hiç ilişmemiş

Bir aşk kelimesi 

Aradım.

Hediye edeceğim:

-yeşil bir ay gibi-

Gülayşem’in gözlerine!...

***

Gülayşem!

Bu defterde bulacaksın

Binlerce kelime.

Kimisi beyâz,

Kimisi kırmızı...

Bazıları mâvi,

Bazıları sarı

Ama... Sen ey yeşil ay’ım

Bütün kelimelerden daha güzelsin...

Bütün kelimelerden 

Çok daha büyük!.

Mecidiyeköy, 04.06.01', 'Gülayşem! Defterimde dans ediyor Binlerce kelime... Yakıyorlar sayfa kenarlarını: Biri Sarı elbiseli... Bir diğeri Kırmızı... Ben bu dünyâda...', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/butun-kelimelerden-buyuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sisler Sokağı', 'sisler-sokagi-nemir-enver-un6zx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sisler Sokağı

“saçmalama”

Sisler sokağı! Yürüyorum seni

İçimde bir burukluk,

Kalbimde ağrılar var...

İçinde eski bir ev

İçimde karanlıklar...

Birden yağmur bastırsa...

Sisler hemen dağılsa...

Saatlerce bekledim...

O karanlık gecede...

Gökyüzü el çırpınca,

Her taraf aydınlansa...

Belki bir gölge görür...

Yalazlanan ateşi,

Az, biraz küllendirir...

Bir türlü göremedim:

Aradığım gölgeyi!.

Yirmi yıl geçti bugün

Şimşek her çaktığında

Yine arar gözlerim:

Yalazlanan ateşi,

Söndürecek bir gölge!!...

Mecidiyeköy, 09.05.01', 'Sisler Sokağı “saçmalama” Sisler sokağı! Yürüyorum seni İçimde bir burukluk, Kalbimde ağrılar var... İçinde eski bir ev İçimde karanlıklar.....', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sisler-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri Kızlarının Türküsü', 'peri-kizlarinin-turkusu-nemir-enver-nuouw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Peri Kızlarının Türküsü

Duygularımızı yağmur ıslattı

Ay ise içinde kandîller yaktı

Çingene kâfileleri: Yolunuzu şiirlerimizle bulun,

Sehere doğru yürüyün,

Yarına doğru yürüyün!!

Biz peri kızlarıyız.... Gözümüze uyku girmez,

Karanlıkta, 

Tepelerde dolaşırız veya mezarlıklarda koşarız,

Her yolcuya âşık olur,

Gençlik ve aşk şarkıları dinletiriz.

İnsânlardan.... Genç bir kız konarsa

Mezar yalnızlığı veya çukur karanlığı

Onu sıkarsa

Türkülerimiz, toprağı deler ve ona varır:

“çıplaksan eğer,

elbiselerini ağaçtaki örümcekler örecekler

her bir ipine, ayrı bir nağme koyacaklar.

kader izin verinceye;

ölüler hesâp günü mahşere çıkıncaya kadar, uyumalısın.

vefâlı sevgilinin, yüzü gülüyor,

bir başkasını bulmuş.

doğrusu, onun tâze vücûdunda seni görmüş

kirpikleriyle gözleri: yüreğine od, 

gözüne uykusuzluk düşürmüş,

seni onda görmüş, seni arzulamış...... 

keşke bekleseymiş!!....

Gülayşem!!....”

			***

Çocuğa, ışık kelebekler göndeririz

Ağaç karanlığında, kanat çırpsınlar,

Âşık gözümüzde vedâyı görür

Tren düdük çalar, yelken çırpınır.

Şâir şiir yazarsa, onun oluruz

Dumân gönderir, 

En güzel beyti, ona biz hâzırlarız......

Türkü söylemeye başlarız:

“sinbad’ın gemileri denizde kayıp oldu

bir adaya geldi, deniz kabukları fısıldaşıyordu:

ay kraliçeye aşık oldu

sarayın tepesinden hiç ayrılmaz oldu”.

Şâir ağlıyordu:”beni ülkesine götürün

çünkü onu seviyorum

çünkü ay benim! diyordu”

Ve delirdi.... Ve intihâr etti.

			***

Ve ay’ı içimize çekeriz 

Seher olana kadar

Mezarlıklarda koşarız

Şâirleri şaşırtırız

Ve herkesi yanıltırız!!....

Mecidiyeköy,  08.05.01', 'Peri Kızlarının Türküsü Duygularımızı yağmur ıslattı Ay ise içinde kandîller yaktı Çingene kâfileleri: Yolunuzu şiirlerimizle bulun, Sehere ...', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/peri-kizlarinin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulmet Ormanı İçinde', 'zulmet-ormani-i-cinde-nemir-enver-de3z5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zulmet Ormanı İçinde

      dördüncümüz ölmeden....

      hep yaşayacağız....

Gözlerimin orman cehennemi korları

Yakıyorlar zulmetin ormanını

Düşünceler: -çalmak için uykumu-

Açıyorlar gâyıb âleminin kapılarını.

Ölçüyorum yerin derinliğini,

Topluyorum lahit kemiklerini.

Ürkütücü.... Ürkütücü bir dişbileme

Çıktı karşıma

-yangın alevleri arasında yanan bir kandîl-

Hüzünlü kafatasım içinde el sallıyor:

İlâhların duygumuzla, dalga geçmesi....

***

Tek başıma yatağımdan gözlerim

Seçiyor uzakları;

Gece canavar olmuş, elinde hançer,

Saplıyor gözlerime

-yıldızlar ve seher-

Gece: Recim taşlarının inât domuzu

Zulmün hançeri, kalbimde yatan konuk....

Görüyorum Kerkük’ü: Ay, kale’ye inmiş, boyuyor

-hüzün dolu ışığı- 

Beli bükük toprağı....

***

Ve hüzünle yanıyor gözleri:

Ölmek ellerinden gelmeyen dostların....

-durduğu yerden seyrediyorlar

eriyip yok olan ağaçlıkları-

Uykusuzluk ülkesinin gözleri....

Düşünceler savaşının verdiği azâp.......

“erken değil miydi bütün bunlara?”

Gözleri -bir gemi- deliyorlar karanlıkları.

Hangi tarlaları düşlüyorlar? Hangi ırmağı?

Lahitten dikilecek: Dördüncü dostu!

(Bağırıyor Mesih:

Bir ölü buldum!

-taşı yerinden oynattıktan sonra-

Bir yatan var burada,

Kaldıracağız,

Haydi gel Nemir!....)

***

Yetmez mi ey İlâh!

Türkü gâyesidir: Hayâtın.

Hayâtımı isle nasıl boyarsın?

Birleşmez parçalara ayırdın beni

-su yüzünde parçalanmış gemi-.

Üstümü ört!

Uyumak istiyorum ben

Babamın, mezarı yanı başına

Mezarlık karanlığının arka yerine.

Merhamet kurşunun:

Nerede İlâh!....

İstanbul (E-5),  30.05.01', 'Zulmet Ormanı İçinde       dördüncümüz ölmeden....       hep yaşayacağız.... Gözlerimin orman cehennemi korları Yakıyorlar zulmetin ormanını...', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/zulmet-ormani-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin', 'sesin-nemir-enver-ahb02', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adetâ içti sesini,

Kalbi titredi, oynadı yerinden.

Sesin: Yanan bir gül, doğdu içinde....

Sesin: Alevli bir turunç var yankısında....

Sesin: Kayan bir yıldızı seyreder gibi,

		İçindeki koku!

			Onunla sanki, sarhoş oldu rûhu,....

Tütün dumânından diktiği orman....

		Serâp ormanı oldu, 

Karşısında sesinin büyüsü.

Ve titrek sesin: Yeşil palmiye dalı;

		Islanmış; hayâ, meltem ve yağmurdan....

Titrerken 

Yatağında ve -aşkın ve pişmanlık kalıntıları olmasa-

Gecenin ardında cân çekişirken

Duydu sesini

Sevgisini seninle doyuramayan, her iki yakada bekleyen,

Gölgesi için, denizin ağzı sulanan, gemi.

Şifâ onda, odur kaptan ve odur kader.

Şarkıcı onda

-ama intihâr ediyor çektiği dertten!-

Sesin, o’nu konuştu o’na,

Kerkük’te can çekişen bahardan,

Gariplerin ağlama seslerinden. Ve okaliptüste 

Sarı karanlığın şikâyet yankısından

Ve dönemecin arkasında uluyan 

Çakal seslerinden. Ve “nerede çocuklarım??!” Diye 

Haykıran anne sesinden. Çağırıyor:

		(Göktürk.... Gökçen!)

			Ne dönen var.... Ne bakan!....

***

Zamân ve mesâfe Gülayşem,

Titrek sesinde:

	Kaybolanın geri gelmesi....

	Mesih’in Şâm’a inmesi....

	Ve Allah’ın evet demesi....

		Hepsi elinde....

Sanki çalıyor kapını....

Açıyorsun....

Ve saklıyor gölgeler gölgenizi!....

Ve saklıyor gölgeler gölgenizi!....

Mecidiyeköy,  04.06.01', 'Adetâ içti sesini, Kalbi titredi, oynadı yerinden. Sesin: Yanan bir gül, doğdu içinde.... Sesin: Alevli bir turunç var yankısında.... Sesin:...', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sesin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmin', 'i-smin-nemir-enver-v5tky', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İsmin

-gülayşem-

İsmin dilimde... Yağmur ağlaması,

Kokunun göçü... Ayrılık tarlası.

Kesim kuyruğunda bekleyen kuzu...

Uçmağa hâzır bir yavru kırlangıç.

Duygularıma boşalan... Rûhuma 

Akan çağlayan.... Ve esen fırtına.

Asmanın soluk alışı... Kaybolur

Güldüğümde: Sarışın bir mutluluk.

Islak ve tüylü, çabuk geçen parfüm...

Her dönemeç, her sokak, her uğrakta.

Kirpiğin kırpışması... Allah koymuş 

İçine: İki damla, berrâk zümrüt.

Türkülerin sürüsü... Konuk gelmiş 

Evime... Dün yitirdiğim yurdumda.

İsmin... 

Sinir uçlarımda şarap koşması...

Damar bükümümde... Hazz sürünmesi.

İsmin... 

Yüreğimde... Yeşil bir tarla... Geçen 

Bir nisân... Yeşiller doğurmuş bahar.

Su yüzüne ermiş yaprak, 

Ortasında açmış çiçek...

Yedi harfli, hangi sazın telleri...

Bir Budistlin: Tapınak nağmeleri.

Yedi tane harf... Işıktan da şeffâf...

Daha güzel: Kokusundan, çiçeğin.

***

İsmin... 

Nasıl bir âleme, çağırır beni...

Yolunu gösterir, bana ilhâmın!.

Mecidiyeköy,  29.05.01', 'İsmin -gülayşem- İsmin dilimde... Yağmur ağlaması, Kokunun göçü... Ayrılık tarlası. Kesim kuyruğunda bekleyen kuzu... Uçmağa hâzır bir yavru...', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ismin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Tanımında Tamamlanmamış Bir Şiir', 'askin-taniminda-tamamlanmamis-bir-siir-nemir-enver-0km0u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(I)

...Aşk hakkında;

Deneyimlerimi yazmağa karâr verdiğimde...

Çok düşündüm...

İtirâflarımın ne fâydası olacak diye?

Benden önce insânlar, aşkı çok yazdılar...

Eskiler, mağara duvarlarına;

Porselen ve çinilere kazıdılar aşkı...

Hindistan’da fildişine,

Mısır’da papirüs yaprağına,

Çin’de pirinç tanesine çizdiler onu...

Kurbanlar... Adaklar, ona sundular...

***

Aşk hakkında;

Görüşlerimi yaymağa karâr verdiğimde...

Çok tereddüt ettim...

Ben, ne bir kâhinim,

Ne de öğrenci yetiştirmeği denemiş biri.

Ne de çiçeklerin, 

-kokularını- 

İzâh etmek mecbûriyetinde olduklarına inanan biri...

Ne yazacağım Gülayşem?

Bu bir tek benim deneyimim...

Ve bir tek beni ilgilendirir...

Bir tek beni siler târîhten...

Tek beni parçalayacak olan kılıç...

-ölmekle de, benim huzûr dolacak olan...-

(II)

Denizine açıldığım zamân Gülayşem...

Deniz harîtasına göz atmamıştım,

Ve yanımda ne bir şişme bot,

Ne de bir cân simidi vardı...

Ben sadece ateşine yürüdüm -bir budist gibi-

Ve ben seçtim geleceğimi...

En büyük eğlencem: Güneşin üstüne adresimi,

Tebeşirle yazmaktı...

Ve ellerinin üstünde bir köprü kurmaktı....

(III)

Sana âşık olduğumda...

Bahçemizdeki kırmızı kirazların

Yuvarlak birer kora dönüştüğünü fark ettim...

Çocukların oltasından korkup kaçan balıkların

Sahillerimize tohum atmak için,

Milyonlarla geldiklerini gördüm...

Ve okaliptüslerin daha da yükseldiğini...

Ve hayâtın daha da genişlediğini...

Ve Allah’ın:

Nihâyet yer yüzüne döndüğünü gördüm...

(IV)

Sana âşık olduğumda...

Yaz aylarının, her sene onlarca kez

Geldiğini gördüm...

Tarlamızdaki buğdayın her gün onlarca kez

Büyüdüğünü gördüm...

Şehrimizden kaçan ay’ın ise:

Bir ev, bir de yatak kiralamağa 

Geldiğini gördüm...

Ve şeker ve anasonlu rakının...

Aşktan çok hoşlandığını gördüm...

(V)

Sana âşık olduğumda...

-gülayşem-

Evrendeki çocuk gülüşleri,

Daha tatlı oldu...

Ekmeğin tadı, daha güzel oldu...

Karın yağması, bir başka beyâz oldu...

Sokaktaki kara kedilerin miyavlaması, daha çekici oldu...

Beyoğlu’nda avuçların birleşmesi, daha sevgi dolu oldu...

Lokantada peçetelere çizdiğimiz şekiller, daha güzel oldu...

Ve... Süzme kahve,

Ve sigara içmek...

Ve Cumartesi akşamı tiyatroya gitmek, daha güzel oldu...

Hafta sonu tatilinden üzerimizde kalan kum...

Ve yazın göçünden sonra sırtındaki bronz renk,

Çok daha güzel oldu...

Ve üzerinde yattığımız...

Ve üzerinde uzanıp... 

Saatlerce gevezelik ettiğimiz dergiler,

Hâtıralar ufkunda: Birer kuş oluverdi....

(VI)

Sana âşık olduğumda Gülayşem:

Gözlerin için tebrikler aldım

Ve bütün ananas ağaçlarını bağışladılar bana...

Güneşin üstünde binlerce dönüm yer hediye ettiler,

Gökyüzünün anahtarını bana verdiler...

Madalyalar taktılar...

İpekler giydirdiler.

(VII)

Aşkımı yazmağı denediğimde...

Çok azâp çektim...

Ben suların altındayım

Ve suyun basıncını nasıl hissettiğimi, ancak

Yüzyıllar boyu okyanusun dibinde kaybolanlar anlar!...

(VIII)

Aşkın hakkında ne yazabilirim Gülayşem?

Hâfızamda kalan tek hâtıra:

Bir sabâh uyandığımda,

Kendimi bir prens olmuş görmemdi!....

Mecidiyeköy, 28.05.01', '(I) ...Aşk hakkında; Deneyimlerimi yazmağa karâr verdiğimde... Çok düşündüm... İtirâflarımın ne fâydası olacak diye? Benden önce insânlar, a...', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/askin-taniminda-tamamlanmamis-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler', 'kelimeler-nemir-enver-4bcmm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kelimeler

Fısıldıyorum kulaklarına:

-dans ettiğimizde-

Kelimelere benzemeyen...

Kelimeler!.

Tutuyorum

Kollarının altından

Ekiyorum

Bulutların tekine

Yemyeşil yağıyor

Atkuyruğu yağmurlar 

Gözlerinde!...

Alıyor beni...

Etekleri gülkurusu

Bir akşama!...

Ben

Bir çocuk gibi kalıyorum

Ellerinde!...

Beni

Bir tüy gibi götürüyor

Esintiler!...

***

Ellerimle...

Götürüyorum ona

Yedi tâne ay...

Bir de,

Bir demet türkü...

Ona bir güneş 

Hediye ediyorum,

Bir yaz,

Bir de kırlangıç sürüsü

Hediye ediyorum...

O’na

En kıymetli mücevherim olduğunu,

Söylüyorum.

Binlerce yıldız

Değerinde olduğunu 

Söylüyorum.

Hazîne olduğunu...

Ve gördüğüm en güzel tablo olduğunu

Söylüyorum...

***

O’na

Başını döndürecek

Sözler söylüyorum...

Pisti ve adımlarını 

Unutturuyorum...

Târîhini

Unutturacak 

Kelimeler söylüyorum...

Birkaç sâniye içinde

O’na

Kadın olduğunu hâtırlatıyorum...

Birkaç sâniye içinde

Başka bir kadın olduğunu 

Öğretiyorum...

***

O’nun için kalbimde

Bir sarây yapıyorum:

Tapusunu oracıkta

Eline veriyorum...

Ama o, dönüyor...

Kalbimi ve kelimelerimi alıp 

Geri gidiyor... Masasına.

Ben ise kalakalıyorum...

Hiçbir şey,

Düşlerimden başka!...

Hiçbir şey:

Kalmıyor elimde!...

Mecidiyeköy, 05.06.01', 'Kelimeler Fısıldıyorum kulaklarına: -dans ettiğimizde- Kelimelere benzemeyen... Kelimeler!. Tutuyorum Kollarının altından Ekiyorum Bulutları...', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/kelimeler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennemde Çöven', 'cehennemde-coven-nemir-enver-7yzxx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kardeşim Celâl’e

Cehennemde Çöven

Dönüp durdum

-kalbimdeki ağrıdan-

Gözü bağlı, taştan bir boğanın döndüğü gibi.... 

Hiç kızabilir miyim?

İnsanlar yürüyorlar zirveye

Benim ayaklarım -eyvâh- yürümekten aciz 

Yatağım: Zindânımdır, tâbûtumdur ve acılar diyârına, 

Adem âlemine sürgünüm!!

Bir gün gelecek diye 

Bekliyorum....

Birkaç ay,

Veya birkaç sıkıcı yıl,

Yada birkaç asır sonra!!

Yürüyeceğim...... Ayaklarımın üstünde....

Sağ elimde bir çöven

Bir mi?.... Hayır iki çöven

Koltukların altında.... 

Yardım ediyorlar:

Ağrılarla yorulmuş vücûda:

Duvarlarında, kan lekeleri harâbe!!

Yürüyeceğim...... Ayaklarımın üstünde yürüyeceğim!!....

Mezara giderse bu yol;

Karanlık ve bin bir ağızlı kurtçuk

Önümde uzanıyor dünyânın bir ucunda.... Bir sunak veya

Karanlık bir vâdi, yada yüksek bir dağda

Koşarak veya sürünerek ona doğru gider,

Yolun sonunu bulur ve kara kapılarını çalarım

Zebânîye bağırırım:

Neden kapıların kapalı??......

Çağır cehennem şeytanlarını....

Erimiş vücûdu parçalasınlar,

Çıplak yaraları kamçılasınlar....

Kartallarını gönder, gözlerimi oysunlar ve kalbimi söksünler....

Burada komşum derdime gülmez......

Veya kapımın önünden, 

Gece yarısı:

((işte felçlinin evi, artık ne yiyeceği var ne de içeceği

yarın iki kızıyla karısını ve doğacak oğlunu, atacaklar sokağa....

ödemezse birikmiş kirâsını))......

Bağırarak bir fahişe geçmez!!....

Ört beni!!....

Acılarım karşısında Gülayşem: Açık tut kapılarını.

Yem istiyor vücûdumu: Cehennemin ateşi,

Cehennem zebânîsi!!...... 

İstanbul,  04.05.01', 'Kardeşim Celâl’e Cehennemde Çöven Dönüp durdum -kalbimdeki ağrıdan- Gözü bağlı, taştan bir boğanın döndüğü gibi....  Hiç kızabilir miyim? İn...', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/cehennemde-coven-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Şarkısı', 'yagmur-sarkisi-nemir-enver-mda01', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'بسم الله

Yağmur Şarkısı

Gözlerin seher vakti, iki zeytin ormanı,

Veya Ay’ın kaçtığı, fırtınada iskele.

Gözlerinin gülüşü, cân verir Mesih gibi, 

Yada taşı misâli, rahmet ve hayât verir.

Gözlerinde

Dans ediyor ışıklar, nehirde bir ay gibi

Güne vedâya gelen, boğazdaki martının,

		Kanat çırpması gibi...

Sanki derinliklerinde, parıldayan bir yıldız,

Aniden kayboluyor, 

Soğuk bir hüznün sisleri,

Yutuyorlar onları...

Gözleri Gülayşem’in, şafakta birer deniz

Akşamın, elleriyle üzerini örttüğü.

Onda kış sıcaklığı ve güzün ürpertisi

İçlerinde ölüm, doğum, karanlık ve ziyâ;

Uyanıyor rûhumda, ağlama titreyişi,

Ve semâları kucaklayan, vahşî bir neşe,

Ay’dan ürktüğü zamân, bir çocuk sessizliği!

Sanki bulut kuşağı: İçiyor susuzluğu

Damla damla eriyor ve yağdırıyor yağmur.....

Asmalar ülkesinde, kıkırdıyor çocuklar:

Yağmur şarkısı...

Gıdıkladı ağaçlarda, kuşların sessizliği...

Yağmur...

Yağmur...

Yağmur...

Akşam esnemeğe başladı, bulutlar hâlâ

Ağır gözyaşlarını dökmekteler...

Sanki dalmadan önce bir çocuk sayıklıyor:

-bir yıl önce; 

uyanıp annesini bulamayınca, sorduğunda;

“yarından sonra” dönecek,

muhakkak dönecek, dediler!-

Arkadaşları, aralarında fısıldaştılar:

O, orada

Tepenin kenarında, 

Ölüm uykusuna dalmış,

	Toprak yiyor ve yağmur içiyor dediler;

Sanki hüzünlü bir balıkçı, topluyor ağlarını

Ve okuyor sulara ve kadere lanetler

Ve ayın battığı yerde dağıtıyor şarkılar.

Yağmur...

Yağmur...

Nasıl bir hüzün yayar, bilir misin yağmur?

Ve yağınca nasıl ağlar oluklar?

Ve garîp, nasıl hisseder kimsesizliğini?

Hiç bitmeyecek -dökülen kan!

	ve karnı aç olanlar gibi,

aşk gibi, çocuk gibi, ölüm gibidir- Yağmur!...

Gözlerin tavâf ettiriyor, yanında yağmur

Boğaz dalgaları arasında, şimşekler siliyorlar

Kalbimin sâhilini, yıldız ve deniz kabuğu,

Sanki doğmağa çalışıyor

Gece ise üstüne, kandan çarşaf seriyor.

Boğaza bağırıyorum: “hey! boğaz,

inci ve mercan vereceksin bana!”

Bir inleme gibi

Geri gelir yankı:

“hey! boğaz, mercan vereceksin bana!”

Duyar gibiyim Anadolu’yu -biriktiriyor şimşekleri-

Ova ve dağlarda. Ve topluyor yıldırımı...

Hasan emmi, tâm düşlerken bereket bulduğunu

Esen kara rüzgâr,

Bırakmaz vâdide, Yörük’ten eser.

Duyar gibiyim kavakları, içiyorlar yağmur

Duyuyorum inleyen köyleri

Boğazdaki fırtına ve şimşekleri

Küreklerle, boğazlamağa çalışan göçmenleri

Söylüyorlar şarkılarını:

Yağmur...

Yağmur...

Yağmur...

Ve Anadolu’da kıtlık

Hasât günü, savuruyor ürünü

Doyuracak karga ve kuzgunu.

Tarlalarda dolaşan değirmen taşları 

-etrâfını sarmış

memetler ve ahmetler- Öğütecek ambarları

Yağmur...

Yağmur...

Yağmur...

Göç gecesinde, ne çok döküldü: Gözyaşı

Ve sonra -ağladık diye ayıplanmamak için-

Kandırmağa çalıştık: Bunlar yaş değil, yağmur...

Yağmur...

Yağmur...

Biz henüz ufak birer çocukken, gökyüzünde

Toplanırdı bulutlar -kış aylarında-

Ve yağardı yağmur,

Ve her sene, nemli toprak göğerdiğinde 

-hissederdik açlık-

Hiçbir yıl geçmez Anadolu’da, olmadan açlık.

Yağmur...

Yağmur...

Yağmur...

Yağmurun her damlasında

Kırmızı veya sarı çiçek yapraklarında

Aç ve çıplakların, her damla gözyaşında

Esir Türkmen’in dökülen her damla kanında

Hayât veren, genç yarının dünyâsında,

Yeni bir ümit gülümsemesi... Veya

Bir bebeğin ağzında yara olmuş anne memesi!...

Yağmur...

Yağmur...

Yağmur...

Yeşerecek Anadolu... 

Yağarsa yağmur...

Mecidiyeköy,  11.06.01', 'بسم الله Yağmur Şarkısı Gözlerin seher vakti, iki zeytin ormanı, Veya Ay’ın kaçtığı, fırtınada iskele. Gözlerinin gülüşü, cân verir Mesih gi...', ARRAY['Türk Edebiyatı','Şiir','Nemir Enver']::text[], 8.5, '{"poet":"Nemir Enver","poet_slug":"nemir-enver","theme":"Türk Şiiri","is_hero":false,"total_lines":111,"source_url":"https://www.antoloji.com/yagmur-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmadın', 'i-nanmadin-ahmet-selcuk-i-lkan-pphqf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğinin  çöllerine,

Nehir oldum inanmadın.

Saçlarının tellerine,

Esir oldum inanmadın.

İnanmadın ne yapayım,

Sensizlikmiş senden payım.

Allah''mısın ki tapayım,

Sevdim seni inanmadın.

Diz çökerken dağlar bana,

Şimdi, şimdi taşlar ağlar bana.

Hayatımda bir tek sana,

Yenik düştüm inanmadın.

Sen kavgamın tek galibi,

Sen gönlümün tek sahibi.

Sana uysal çocuk gibi,

Teslim oldum inanmadın.

İnanmadın ne yapayım,

Sensizlikmiş senden payım.

Tanrı mısın ki tapayım,

Sevdim seni inanmadın.

Yere serdim onurumu,

Hiçe saydım gururumu.

Kucakladım umudumu,

Koştum sana inanmadın.

Yasak koydum şu gönlüme,

Ne geçtiki ah elime.

Bağlanmak mı ne kelime,

Öldüm sana inanmadın.

İnanmadın ne yapayım,

Sensizlikmiş senden payım.

Allah mısın ki tapayım,

Sevdim seni inanmadın.

Koştum sana inanmadın.

Öldüm sana inanmadın.', 'Yüreğinin  çöllerine, Nehir oldum inanmadın. Saçlarının tellerine, Esir oldum inanmadın. İnanmadın ne yapayım, Sensizlikmiş senden payım. Al...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/inanmadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-gurol-genc-pel-van-fvwdt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'birden gece olucak gunlerden bir gun

ay yeryuzune yaklasıcak

sinsi ısıkları sarıcak butun dunyayı

puslu havada insanlar ne oldugunu

anlamaycak ve bi ısık vurucak yeryuzunun bi kısmına

oyle kuvvetli olucakki

gozleri kamasacak bakan toplulukların

kimi tanrının bir lutfu

kimi ise bir cezalandırması diye dusunucek

sende bakıcaksın pencerenin bir kenarından

gokyuzune usul usul

garipsiceksin olan olayları ve hayretle

izlemeye baslıyacaksın 

bir an ısıgın kuvvetlendigini goruceksin

oyle parlak olucakki kimse bakamıyacak

tek sen farkedeceksin ne icin oldugunu

bir bagrıs duyucaksın o an icin

cok sert cok isyankar ve yurekten gelen

bir haykırıs olucak

icinde bir an bir sızı hissedeceksin

ta yureginin akan nehirlerinde

yavas yavas kaybolmaya baslıyacak 

yayılan ısık bir an

gokyuzunde kaybolmak uzereyken bir den

bir pırıltı goreceksin

kayan bir yıldız olucak

ve tam ısıgın vurdugu yere dusucek

o kadar hızlı inecekki hayretle bakıcaksın

sanki bir kez daha olmek istermis gibi

ve oan bir bosluk hissedeceksin yureginde

dusuncelerini alıp goturen bir bosluk

bir den bi sıcaklık olucak odanın icinde

teninde hissedeceksin 

ve tuylerin urperecek titreyeceksin

yanagında ufak bir ıslaklık olucak bir anda

tanıdık bir ıslaklık ama anlamıyacaksın

uzatacaksın ellerini bosluk gelicek

pencerenin camı bir an esen bir ruzgarla acılıcak

acelesi olan ruzgar alıcak hissettigin sıcaklıgı 

bir anda ve ıslaklıgı

hic bir sey yapamıyacaksın

agır agır penceren kapanıcak ve birden gunes

dogucak

yeni bir gune baslıcaksın

ama yanlız olmayarak hep o sıcaklıgı arayarak

yakalayıp kaybetmis oldugun 

sıcaklıgı....', 'birden gece olucak gunlerden bir gun ay yeryuzune yaklasıcak sinsi ısıkları sarıcak butun dunyayı puslu havada insanlar ne oldugunu anlamayc...', ARRAY['Türk Edebiyatı','Şiir','Gürol Genç Pel Van']::text[], 8.5, '{"poet":"Gürol Genç Pel Van","poet_slug":"gurol-genc-pel-van","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gece-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-gurol-genc-pel-van-63o8o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her zamanki gibi gene yavaş yavaş

is donüşü bi akşam üstüydü rastladığım

hafif kararmış hafif puslu

siniyordu ortalığa hükmeder gibi

bir o kadar ateşli bir o kadar isyankar 

hayatamıydı öfkesi yoksa insanlaramı

diye durup düşündüm bir an 

ve başladım tekrar yürümeye 

ayak izlerimde dahi sıcaklığı vardı sanki

alacalığın usul usul dokunuyordu

durmadan yaklaşır gibiydim 

erişilmezlere dogru emin adımlarla

kasmalımıydım kendimi yoksa rahatmı

olmalıydım hayata bakarken diye

düşünüp durdum kendi kendime

ve geldim her zamanki gibi

otobüs durağına yaklaştım

insanların menfaatçi ve alaycı bakışları 

arasında ezilir gibiydim bir an sanki

katıldım bende topluluğun arasına 

sessizce girdim kimse farketmesin diye

etrafa göz atmaya başladım göz uçlarımla

süzüyordum insanları 

kimi maaşından kimi ise

dün buluştuğu kızdan bahsediyordu 

ama kimse söylemiyordu

dun burada olanları ne çabuk unutmuştu insanlar

yola doğru çevirdim yüzümü ve baktım

hala dün gibi duruyordu fren izleri

isyan ediyordu bakışlarım belkide küsüyordu

sanki ordan kalkacakmış gibi görüyordum

kendi içimdeki hülyaları bir an

ama ne bir hareket nede bir ses vardı 

ortalıkta gündelik muhabbetlerden başka 

ve otobüs gelmişti tekrar ertesi gün gorüşene 

kadar elveda dedim sana o an 

ve bindim otobüse 

bir sonraki yarını sevinçle bekleyerek..', 'her zamanki gibi gene yavaş yavaş is donüşü bi akşam üstüydü rastladığım hafif kararmış hafif puslu siniyordu ortalığa hükmeder gibi bir o k...', ARRAY['Türk Edebiyatı','Şiir','Gürol Genç Pel Van']::text[], 8.5, '{"poet":"Gürol Genç Pel Van","poet_slug":"gurol-genc-pel-van","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/o-gun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamayadığım Hayallerim', 'yasamayadigim-hayallerim-gurol-genc-pel-van-gzhnn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'alacakaranlıkta olsun ölümüm

ne acizliğim nede çagresizliğim görünsün

belki bi parça sen belki bi parça nefret

bırakın süzülsün süzüldüğü yere kadar

demeliyim akan göz yaşlarıma

derken 

tutulan hoca gelmeli 

açmalımıyım ellerimi yoksa isyanmı etmeliyim

duaların arkasından diye

sormalıyım

ama çekip gitmeli hoca dahi

ıssız kalmalıyım dalıp hatıralara

son kez düşünmeliyim seni

son görevimi yaptığımı sanmalıyım

düşünücek o kadar şey varken

son anımda bile seni hissetmeliyim

kapı gıcırdamalı ve alıp gitmeliler 

umutlarımı bir anda

bırakın bile dememe fırsat vermeden

ve gözlerde sabağın ilk aydınlığı olmalı

bağırmalı umutlarımı alan adam

toplansın iki üç dost bir ikide yabancı diye

gün doğmadan kurulsun dar agacı 

arkalarından ben bağırmalıyım 

avazım çıktığı kadar

son kez hayata isyan ederek

beni hayallerimin bittiği yerde asın diye..

Hayallerimi alıp giden insana.....', 'alacakaranlıkta olsun ölümüm ne acizliğim nede çagresizliğim görünsün belki bi parça sen belki bi parça nefret bırakın süzülsün süzüldüğü ye...', ARRAY['Türk Edebiyatı','Şiir','Gürol Genç Pel Van']::text[], 8.5, '{"poet":"Gürol Genç Pel Van","poet_slug":"gurol-genc-pel-van","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yasamayadigim-hayallerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-gurol-genc-pel-van-2fxld', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün öldüğümü duyacaksın 

ağlayacaksın 

taze bir bahar sabahı kapanacak gözlerim 

köşe başından bir tabut çıkacak 

basını onune egeceksin bir suclu gibi 

son pismanlıklar olucak hic dokunamadıgım 

dudaklarında

ve bir ufak mısra gibi mırıldanacaksın

derken, 

ilk adımı atacaksın toprağıma 

ağlamak gelecek içinden 

zor tutacaksın kendini 

düşüneceksin yapılan hataları 

beraber olduğumuz günler gelecek aklına 

titreyerek karşımda 

sarılmak isteyeceksin 

fakat bir an hocanın sesi 

kaybedecek hayalini 

dönüp bakacaksın yaş toprağa 

insanların, 

yavaş yavaş kaybolduğunu göreceksin 

yanlız kalacaksın mezarımda 

küçücük toprak taneciklerinden

uzaklaşacaksın ağır ağır 

her sabah ziyaret edeceksin mezarımı 

2 gül fidanı dikeceksin mezarımın iki başına 

biri beyaz biri kırmızı 

iki bülbül ötecek baş ucumda 

birbirlerine gulup ilân-ı aşk edecekler 

bizim yerimize 

aradan günler,aylar geçecek 

yavaş yavaş azalacak ziyaretler 

guller yaprak dokumune giricek

sonbahar esintileri baslayacak aramızda

bir sabah 

yanında sevgilinle geleceksin 

ona birşeyler söyleyeceksin 

mezarımın başında 

sen başını kapatacaksın ve dua edeceksin 

mezarcıya para verip mezarıma bakmasını söyleyeceksin 

birkaç gün o gelip sulayacak zamanla 

bülbüllerim ötmeyecek 

güllerim açmayacak 

ve benim zavallı bu ruhum 

mezarımın perişanlığını görünce 

son defa haykıracak 

elvada gülüm 

ELVEDA.......', 'Birgün öldüğümü duyacaksın  ağlayacaksın  taze bir bahar sabahı kapanacak gözlerim  köşe başından bir tabut çıkacak  basını onune egeceksin ...', ARRAY['Türk Edebiyatı','Şiir','Gürol Genç Pel Van']::text[], 8.5, '{"poet":"Gürol Genç Pel Van","poet_slug":"gurol-genc-pel-van","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gulum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'mehmetcik', 'mehmetcik-mustafa-bilik-fnw5v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ğüneydoğuda bir karakolda

Hasret dolu bir gecede

Demeden gündüz gece

Vatanı için yine nöbette

xxx

Uzak düşmüş anasıyla

Kurban önce Allah''a, sonra vatana

Elde silahla gözde yaşla

Gözü gibi bakar bayrağa

xxx

Türk askeridir başı diktir

Vatan bekçisidir mehmetçiktir

Der her şey ,vatan içindir

Ataları, abileri hep şehittir.

xxx

Gökteki yıldızlar kadar

Hasret dolu yüreğinde

Gözü menzilde eli tetikte

Yari yine aklında yüreğinde

xxx

Matarasındaki bir damla sudur

Çantasındaki ekmek kurudur

Der bu vatan borcudur

Şehitlerin hesabı sorulur.

xxx

Mustafa Bilik

[email protected]', 'Ğüneydoğuda bir karakolda Hasret dolu bir gecede Demeden gündüz gece Vatanı için yine nöbette xxx Uzak düşmüş anasıyla Kurban önce Allah''a, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilik']::text[], 8.5, '{"poet":"Mustafa Bilik","poet_slug":"mustafa-bilik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mehmetcik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Sevgili', 'beklenen-sevgili-sinan-aydinli-xj11v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeter artık uzat ellerini

Çek çıkar beni bu karanlıklardan!

Ayışığı gibi süzül bir geceyarısı

Odamın camından içeri.

Duvarlarda dans et

Yastığıma konup gözbebeklerimi okşa

Ruhuma yerleş.

Unuttur bana bildiğim tüm isimleri.

Dilime sadece

Senin ismini söylemeyi öğret.

Dudaklarımdan kayıp ellerimi tut.

Sonra da al götür beni

Henüz yazılamış şiirlerde,

Hiç bir dudağın söylemediği 

Sözlerde gizli olan sevdamızın olduğu yere.

Çek çıkar beni bu karanlıkşardan

Ruhum bedenimden çıkmadan...

                                ( 27-05-2001)

                                    (SÇL için)', 'Yeter artık uzat ellerini Çek çıkar beni bu karanlıklardan! Ayışığı gibi süzül bir geceyarısı Odamın camından içeri. Duvarlarda dans et Yast...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydınlı']::text[], 8.5, '{"poet":"Sinan Aydınlı","poet_slug":"sinan-aydinli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beklenen-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz İnsanlar', 'siz-i-nsanlar-dogan-kaya-trnwy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siz insanlar zaten yoktunuz 

Gölgelerinizin ayak izleriydi kaldırımlardaki

Gülüşleriniz yoktu, yoktu o şen kahkahalarınız

Evleriniz yoktu , yoktu arabalarınız.

Çünkü siz yoktunuz sokaklarda

O gezinen gölgelerinizdi

Sabahın ilk ışıklarıyla beliren

Sadece uzayıp, kısalan belirsiz karanlıklardınız,

Beni heryerde takip eden karanlıklar

Güneş battımı siz de yok olurdunuz.

Çünkü o zaman her yer karanlıktı

Siz korkardınız karanlıktan.

Siz korkardınız kendinizden.

Siz insanlar zaten yoktunuz

Kulaklarımda ki  o anlamsız fısıltılar

Sizlere ait degildi

Yoktunuz yanımda, yoktunuz karşımda

Siz yoktunuz!

Paramparça birer hatıraydınız 

Beynimin ıssız bir köşesine gizlenmiş,

Apansız beynimi istila eden bir virüstünüz.

Yok edilemeyen bir virüs.

Siz insanlar zaten yoktunuz, yoktunuz.

Hiç bir zaman da olmadınız!', 'Siz insanlar zaten yoktunuz  Gölgelerinizin ayak izleriydi kaldırımlardaki Gülüşleriniz yoktu, yoktu o şen kahkahalarınız Evleriniz yoktu , ...', ARRAY['Türk Edebiyatı','Şiir','Doğan Kaya']::text[], 8.5, '{"poet":"Doğan Kaya","poet_slug":"dogan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/siz-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-dogan-kaya-90922', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Susmak istiyorum konuşmamak,

O manasız sesleri çıkarmamak.

Sağır olmak istiyorum

Kulaklarımda yalnızca sessizliğin ıslığı olsun.

Duymamak ve konuşmamak.

Bir bebek gibi manasızca etrafa bakınmak,

Ağlayabilmek korkusuzca

Utanmamak...', 'Susmak istiyorum konuşmamak, O manasız sesleri çıkarmamak. Sağır olmak istiyorum Kulaklarımda yalnızca sessizliğin ıslığı olsun. Duymamak ve...', ARRAY['Türk Edebiyatı','Şiir','Doğan Kaya']::text[], 8.5, '{"poet":"Doğan Kaya","poet_slug":"dogan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bebek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk', 'ey-ask-abluka-gunerhan-gjcft', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben  sana yandım yanalı

Ey aşk

Döner dururum  devri alemde

Alemin derdi derdimden öte

Gönlüme fermansın

Fermansın diye ...

Alır beni 

Götürürsün  bilinmeze

Bak yine saldın 

Şu yaralı gönlü tarifsiz kederlere 

Ey aşk

Şu alemde  dert mi  yok ki?

Gelir beni sen bulursun

Seher yeli esende sen 

Gündüzümde gecemde sen', 'Ben  sana yandım yanalı Ey aşk Döner dururum  devri alemde Alemin derdi derdimden öte Gönlüme fermansın Fermansın diye ... Alır beni  Götürü...', ARRAY['Türk Edebiyatı','Şiir','Abluka Günerhan']::text[], 8.5, '{"poet":"Abluka Günerhan","poet_slug":"abluka-gunerhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ey-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Zaman', 'o-zaman-aydin-deniz-sk67w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dönecektin güzel gözlüm, dön emi

Gözlerim yollarda beklerim seni

Sensiz rüyalardan  uyandır beni

Yıldızlar uykuya yattığı zaman

Sensiz perişanım, bak gönül kaç yama

Pembe bir kızıllık vuruyor  cama

Bekliyorum seni bu kimsesiz odama

Gecenin gündüzü yuttuğu zaman.

O güzel gülüşün gözümden gitmez

Seni anlatmaya şiirler yetmez

Bir kere yaktın, bu ateş sönmez

Denizler yağmura döndüğü zaman.', 'Dönecektin güzel gözlüm, dön emi Gözlerim yollarda beklerim seni Sensiz rüyalardan  uyandır beni Yıldızlar uykuya yattığı zaman Sensiz periş...', ARRAY['Türk Edebiyatı','Şiir','Aydın Deniz']::text[], 8.5, '{"poet":"Aydın Deniz","poet_slug":"aydin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkeden', 'terkeden-selcuk-ozturk-sgh90', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Giden değil,

Asıl kalandır terkeden.

Giden de;

Bunun için gitmiştir zaten....', 'Giden değil, Asıl kalandır terkeden. Giden de; Bunun için gitmiştir zaten.......', ARRAY['Türk Edebiyatı','Şiir','Selçuk Öztürk']::text[], 8.5, '{"poet":"Selçuk Öztürk","poet_slug":"selcuk-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/terkeden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun', 'olsun-koray-palazoglu-n3vbp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yasadigim yerde cam agaclari olsun

Bir nefeste bin hayale dalayim

Denizin kokusunu alayim arada bir

Hayalin bini bir para olsun', 'Yasadigim yerde cam agaclari olsun Bir nefeste bin hayale dalayim Denizin kokusunu alayim arada bir Hayalin bini bir para olsun...', ARRAY['Türk Edebiyatı','Şiir','Koray Palazoğlu']::text[], 8.5, '{"poet":"Koray Palazoğlu","poet_slug":"koray-palazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tereke', 'tereke-cahit-kulebi-vhdim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha ben ölmeden paylaşın

Sabrım zamanım karımın olsun

İşte boş cüzdanım cebimde

Oğullarıma kalsın.

Dostlara bıraktım türküleri,

Gözlerimi delikanlılara.

Hayallerim hepsine yeter,

Bolca dağıtılsın kızlara.

Gövdemi şölen ettim böceklere,

Mezarıma milyonlarca dolsun.

Özgürlüğü duyardı saçlarım

Bütün şairlere selam olsun.', 'Daha ben ölmeden paylaşın Sabrım zamanım karımın olsun İşte boş cüzdanım cebimde Oğullarıma kalsın. Dostlara bıraktım türküleri, Gözlerimi d...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi']::text[], 8.5, '{"poet":"Cahit Külebi","poet_slug":"cahit-kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tereke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açık', 'acik-cahit-kulebi-e599f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz hep açık konuştuk.

Gökyüzünden maviydi sözlerimiz.

Sığ bataklarda değildik, kuşlar gibiydik,

Uçarıydık. Gözlerimizde

Şavkıyan parıltılar gibiydik.

Biz iyiye iyi, güzele güzel dedik.

Masallardan çekerdik mısraları, tülbent gibi.

Yalnız, şiirlerde yalan söylemezdik,

Umutlarımızda, hayallerimizde de yalancı değildik.

Biz buğday tarlalarında buğday,

Ağu yeşili bahçelerde ot,

Trenlerde düdük sesiydik.

Yıldızlara çobandık, değirmenlere su,

Bozkırlara bulut gölgesiydik.

Seller aktı gitti. Biz kaldık.

Bulutlar uçtu gökyüzünden.

Rüzgarlar darmadağın etti.

Ne bahçesinden hayır var, ne güzünden.

Akıl da bulutlar gibi çekip gitti.

Nerden bilirdik, çalışmaktan

Kocayacağını sevgililerin,

Yaşamanın güzelliği kadar

Hoyratlığını, bezginliğini...

Biz kaldık, koyup gitti bahar, 

Her şeyi nerden bilirdik.', 'Biz hep açık konuştuk. Gökyüzünden maviydi sözlerimiz. Sığ bataklarda değildik, kuşlar gibiydik, Uçarıydık. Gözlerimizde Şavkıyan parıltılar...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi']::text[], 8.5, '{"poet":"Cahit Külebi","poet_slug":"cahit-kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/acik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acının Omuzlanışı', 'acinin-omuzlanisi-i-smet-ozel-yzm9h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Edip Cansever için

Kadını bir gürültüye sapladılar.

Evler tıkırtıydı, tıkırtıydı, tıkırtı

kahkahamın düşürdüğü çiçekleri bulamadılar

fırtınalı bir geceydi çünkü bulamadılar

bombalar, bö sesleri, savaş alaborası...

Yaşamak bir tıkırtıydı, aldırmadılar.

Çocukların düşlerinde bir Markut

bir kurbağa zıplıyor yaşamamızdan

hergün zıplıyor, hergün eksiliyor, hergün

Markuuuut! Torbanı sarkıt.

Her doğal güzelliğin bir ucunda aptallık

öbür ucunda o kambersiz geçen düğün.

Kadın. Kadını bir dilime katık ettiler

Markuuuut! Torbanı sarkıt.

Siz büyüyün kan kuşları siz büyüyün

güzün gelişi bir öğürtüdür korkmayın

korkmayın ölüm bir başka ağzıdır yarasaların.

Aşınmış eşikler, aşınmış yaygaralar

aslan gibi bir kocası var mıydı bu kadının?

Gömleğimi zorlayan kuş sesleri.', 'Edip Cansever için Kadını bir gürültüye sapladılar. Evler tıkırtıydı, tıkırtıydı, tıkırtı kahkahamın düşürdüğü çiçekleri bulamadılar fırtına...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/acinin-omuzlanisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çocuk Tanıdım', 'bir-cocuk-tanidim-hikmet-tugrul-tekeli-95cpl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlık gökyüzünde dolaşan

     Hep derinlere dalan

     Sessiz,içten herkesten uzakta ağlayan.

     Yaralı bir kuştu gökyüzünde 

     Taşıyamayacağı ve hep ağır gelen bir yüreği vardı

     Sevmekten,sevilmekten,acı çekmekten korkardı

     Sessiz,içten herkesten uzakta ağlardı.

     Bir çocuk tanıdım

     Yalnızlıktı tek dostu

     Tüm yaşamı boyunca kıvrandı durdu

     Duymadı kimse haykırışlarını

     Anlamak istemedi yalvaran bakışlarını

     Çaresizdi,kimsesizdi,yalnızdı

     Sessiz,içten herkesten uzakta ağlardı.

     Bir çocuk tanıdım

     Masmavi denizin pırıltılarına aldanan

     Uçan martılarda kendini bulan

     Vurgun yemiş gibi kıyılara vuran

     Bir çocuk tanıdım 

     Kaderi miydi bilinmez 

     Sessiz,içten herkesten uzakta ağlardı.', 'Karanlık gökyüzünde dolaşan      Hep derinlere dalan      Sessiz,içten herkesten uzakta ağlayan.      Yaralı bir kuştu gökyüzünde       Taşı...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-cocuk-tanidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğrama Bana', 'ugrama-bana-hikmet-tugrul-tekeli-nrn3j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uğrama bana gecenin karanlığında 

       Uğrama güneşin sıcağında kavrulmuş toprağıma 

       Uğrama girma hayallerime istesende

       Uğrama bana,bırak beni kendi çaresizliğimle

       Bekliyorsam seni aynı yerde

       Üşüyorsam yağmurlu gecelerde

       Titriyorsa ellerim,çarpıyorsa o kırılgan yüreğim

       Uğrama bana,bırak beni kendi çaresizliğimle

       Ağlıyorsam hüzünbaz şarkıları dinlerken

       Kaçıyorsam senden seni özlerken

       Korkuyorsam yalnızlığın dayanılmaz zindanında

       Uğrama bana,bırak beni kendi çaresizliğimle

       Uğruna uslanmaz çocuklar gibi ağladığım

       Yalnızlığımı örtbas ediyorsa sahte gülüşüm

       Senden uzaklarda aşksızlıktan ölsemde

       Uğrama bana,bırak beni kendi çaresizliğimle

                                                            

NOT:Mustafa İcat ve Mustafa Bayır''a katkılarında dolayı teşekürler', 'Uğrama bana gecenin karanlığında         Uğrama güneşin sıcağında kavrulmuş toprağıma         Uğrama girma hayallerime istesende        Uğra...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ugrama-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge Oyunu', 'golge-oyunu-orhan-polat-syy3q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gölgeyle sevda oyunu;

Bir kulaç atarak yandaki masaya,

Gölgeyi düşürmek istedim,

Masadaki kızla aşka,

Gönlü yuvarladım üstüne,

Peşinden bedeni...

Sevdim ben diyebilmek için,

Hep aykırı sevdalara kapıldım,

Koştum aykırılıkta aşka düştüm,

Bir taşla...

İki kuş gölgesinde uzandım,

Yarınların yanıbaşına,

Gölgeme yasladım bedeni,

Aşka baktım gölgeden,

Sonra oynadım aşkla en güzel oyunu,

Güneşsiz bir havada oynadığım oyna

Dedim ki: ” gölge oyunu “....

(20 haziran 2001

 ankara)', 'Gölgeyle sevda oyunu; Bir kulaç atarak yandaki masaya, Gölgeyi düşürmek istedim, Masadaki kızla aşka, Gönlü yuvarladım üstüne, Peşinden bede...', ARRAY['Türk Edebiyatı','Şiir','Orhan Polat']::text[], 8.5, '{"poet":"Orhan Polat","poet_slug":"orhan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/golge-oyunu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heddeden Geçmiş Nezaket', 'heddeden-gecmis-nezaket-nedim-qp3t8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haddeden geçmiş nezâket yâl ü bâl olmuş sana 

Mey süzülmüş şîşeden ruhsar-ı âl olmuş sana 

Bûy-i gül taktîr olunmuş nâzın işlenmiş ucu 

Biri olmuş hoy birisi dest-mâl olmuş sana 

Sihr ü efsûn ile dolmuşdur derûnun ey kalem 

Zülfü Hârut’un demek mümkin ki nâl olmuş sana 

Şöyle gird olmuş Firengistân birikmiş bir yere 

Sonra gelmiş gûşe-i ebrûda hâl olmuş sana 

Ol büt-i tersâ sana mey nûş eder misin demiş 

El-amân ey dil ne müşkil-ter suâl olmuş sana 

Sen ne câmın mestisin âyâ kimin hayrânısın 

Kendin aldırdın gönül n’oldun ne hal olmuş sana 

Leblerin mecrûh olur dendân-ı sîn-i bûseden 

Lâ’lin öptürmek bu hâletle muhâl olmuş sana 

Yok bu şehr içre senin vasfettiğin dilber Nedîm 

Bir perî-sûret görünmüş bir hayâl olmuş sana', 'Haddeden geçmiş nezâket yâl ü bâl olmuş sana  Mey süzülmüş şîşeden ruhsar-ı âl olmuş sana  Bûy-i gül taktîr olunmuş nâzın işlenmiş ucu  Biri...', ARRAY['Türk Edebiyatı','Şiir','Nedim']::text[], 8.5, '{"poet":"Nedim","poet_slug":"nedim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/heddeden-gecmis-nezaket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmadı', 'unutulmadi-hikmet-tugrul-tekeli-flmkd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'M.İcat''a

       Yüreğimde açtığın yara kapanmadı

       Yokluğunda çekmediğim azap kalmadı

       O kadar bekledim gelen,giden olmadı

       Söyle yar verdiğin süre hala dolmadı mı? 

       Sensiz ne yapar bu cansız beden

       Ne yapayım sevmişim sen istemeden

       Hatırla birde söz verdiğin 

       Söyle yar verdiğin süre hala dolmadı mı? 

       Benliğimi kurban ettim uğruna 

       Vazgeçtim herşeyden,kul,köle oldum yoluna 

       Hadi dön bir bak halime 

       Söyle yar verdiğin süre hala dolmadı mı? 

       Sensizlik zindanına hapsettin bedenimi

       Hasretin gölgesinde büyüttün yüreğimi

       Kuruttun nazlı çiçeğimi,unuttun

       Söyle yar verdiğin süre hala dolmadı mı? 

       Şimdi isyan ediyorum zamana,kaderime

       Ufacık bir ümidi çok gören sevdiğime 

       Yaşadığım sürece tek dileğimdi

       Unutulmadı yaklaştıkça artan güzelliğin

       Söyle yar verdiğin süre hala dolmadı mı?', 'M.İcat''a        Yüreğimde açtığın yara kapanmadı        Yokluğunda çekmediğim azap kalmadı        O kadar bekledim gelen,giden olmadı       ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/unutulmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dem Vakti Gecti', 'dem-vakti-gecti-koray-palazoglu-d3v48', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani daha muhabbet edecektik

Ben sana demedim mi...

Cayi demle ben geliyorum diye

Bak bugun de gec kaldik', 'Hani daha muhabbet edecektik Ben sana demedim mi... Cayi demle ben geliyorum diye Bak bugun de gec kaldik...', ARRAY['Türk Edebiyatı','Şiir','Koray Palazoğlu']::text[], 8.5, '{"poet":"Koray Palazoğlu","poet_slug":"koray-palazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dem-vakti-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahramanlık Türküsü', 'kahramanlik-turkusu-niyazi-yildirim-gencosmanoglu-psf3l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gazi alperenler işe koyulun

Gayrı söze vakit az verilmeli

Bidevi atlara rüzgarca soluk

Ve yıldırımlarca hız verilmeli

Şanlı kitap önderimiz kılındı

İman sancak gönderimiz kılındı

İklim-i Rum,minderiniz kılındı

Ol mindere kavi diz verilmeli.

Barak Baba,Sarı Saltuk orada,

Hacı Bektaş Veli,Taptuk orada,

Bir mübarek vatan yaptık orada,

Ki,bir can dilerse bin verilmeli.

Töre,nizam,yol ve yordam her kula

Usul,erkan,edep,erdem her kula,

Yirmidört saatte her dem her kula,

Allah ın buyruğu uz verilmeli.

İnatla girmeyin soy sop faslına

Kurtsa kurt itse it döner aslına

Rum ülkelerinde Oğuz nesline 

Peygamber kavlince öz verilmeli.

İçinde olanlar bir nebze iman

Gönlünü mazluma eder süt liman

Halkı ayırmadan kafir müslüman

Açsa aş,açıksa bez verilmeli.

Bu kılıçlar iller fethi içindir.

Bu kitaplar diller fethi içindir.

Türküler gönüller fethi içindir.

Cümle ozanlara saz verilmeli.

Kartal yuvasıdır Söğüt te burçlar,

Devletin zırhıdır sınırda uçlar,

Gazi Osmanlara zağlı kılıçlar

Yunus Emrelere söz verilmeli...', 'Gazi alperenler işe koyulun Gayrı söze vakit az verilmeli Bidevi atlara rüzgarca soluk Ve yıldırımlarca hız verilmeli Şanlı kitap önderimiz ...', ARRAY['Türk Edebiyatı','Şiir','Niyazi Yıldırım Gençosmanoğlu']::text[], 8.5, '{"poet":"Niyazi Yıldırım Gençosmanoğlu","poet_slug":"niyazi-yildirim-gencosmanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kahramanlik-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başı Boş', 'basi-bos-abdi-kadir-birinci-klmi5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolaşıyorum

Başı boş nâhoş

Yanağımda bir çiğ damlası yaş

Düşüyor düşüyor düşüyor...

İçimde bir sızı,

Zaman zaman zevk veriyor

Fûzûli misali...', 'Dolaşıyorum Başı boş nâhoş Yanağımda bir çiğ damlası yaş Düşüyor düşüyor düşüyor... İçimde bir sızı, Zaman zaman zevk veriyor Fûzûli misali....', ARRAY['Türk Edebiyatı','Şiir','Abdi Kadir Birinci']::text[], 8.5, '{"poet":"Abdi Kadir Birinci","poet_slug":"abdi-kadir-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/basi-bos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Denizlerin Çocuğu', 'biz-denizlerin-cocugu-abdi-kadir-birinci-ak2c1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dolu dizgin koştuk dört mevsim

Fırtınalarla harabe şehrin

Özgür sahillerine.

Evvel şarkılara sessizce göçüp giderken,

Biz denizlerin çocuğu,

Virane yılların uğultularını yakaladık

Ayak izlerimiz de

Ve zaman,

Siliniverdi belleğimizden...', 'Dolu dizgin koştuk dört mevsim Fırtınalarla harabe şehrin Özgür sahillerine. Evvel şarkılara sessizce göçüp giderken, Biz denizlerin çocuğu,...', ARRAY['Türk Edebiyatı','Şiir','Abdi Kadir Birinci']::text[], 8.5, '{"poet":"Abdi Kadir Birinci","poet_slug":"abdi-kadir-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/biz-denizlerin-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-abdi-kadir-birinci-wfbmy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tüm benliğinle gel

Olanca gücünle

Korkmadan

Haykırarak gel.

Ve açık yüreklilikle

Söyle,

Ben kimim?', 'Tüm benliğinle gel Olanca gücünle Korkmadan Haykırarak gel. Ve açık yüreklilikle Söyle, Ben kimim?...', ARRAY['Türk Edebiyatı','Şiir','Abdi Kadir Birinci']::text[], 8.5, '{"poet":"Abdi Kadir Birinci","poet_slug":"abdi-kadir-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gel-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oniki Kasım Düzce', 'oniki-kasim-duzce-abdi-kadir-birinci-gpmis', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve aklımda geldiğim diyar

Uzaktan acı bir selam.



Kar taneleri tozak vuruyor

Beyaz üstü beyaz

İnleyenler sustu tümden

Korku, soğuk, umut

Karıştı-yekpare



Uzaklardan sıcak yerden

Koca enseli adamlar gelir

Kar taneleri savrulan yamaçlara

Bir tokat gibi 

Utanmadan!



Sızlamak yasak

Telkinler hep birden-tek

Sevinç, soğuk, umut

Karıştı-yekpare



Bir çocuk

Gocuk yırtık

Yüzler donuk

Bilmem ne umduk!



Kadere baktım doğru

Suçlu-aramadım

Yalnız, aksayan vardı yinede

Bilinmeyen bir denklem

Aradım ve çözüm

Şimdi umut, sevinç

Beraber  gelmeli

Güzel bir çocukla

Aydın bir günde

Işık dolu

Onca yıl

Akıp gitmeli...', 'Ve aklımda geldiğim diyar Uzaktan acı bir selam. Kar taneleri tozak vuruyor Beyaz üstü beyaz İnleyenler sustu tümden Korku, soğuk, umut Karı...', ARRAY['Türk Edebiyatı','Şiir','Abdi Kadir Birinci']::text[], 8.5, '{"poet":"Abdi Kadir Birinci","poet_slug":"abdi-kadir-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/oniki-kasim-duzce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onyedi Ağustos Marmara', 'onyedi-agustos-marmara-abdi-kadir-birinci-cwrpb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kat kat evler tünemiş

Taş üstüne taş

Her biri ayrı bir can

Farklı bir kader

Bilmece-ağlamaca

Baktığında hepsi bir

Ya kapı aralanıp içeri girdiğinde

İşte can, işte dünya

Teker teker

Can ruh, dünya alem,

Oluvermekte...



Kat kat evler tünemiş

Kız–oğlan, kadın-erkek

Yaşlısı genci yok

Hepsi bir ayrısı gayrısı yok...



Canlar kan, taş, toprak

Yek olmuş.

Ne ağlayan ne gülen kalmış

Duvarlardan bir akis bir resim

Sanki yalan...

Geri kalan; eskiden gelen bir talan.', 'Kat kat evler tünemiş Taş üstüne taş Her biri ayrı bir can Farklı bir kader Bilmece-ağlamaca Baktığında hepsi bir Ya kapı aralanıp içeri gir...', ARRAY['Türk Edebiyatı','Şiir','Abdi Kadir Birinci']::text[], 8.5, '{"poet":"Abdi Kadir Birinci","poet_slug":"abdi-kadir-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/onyedi-agustos-marmara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Üşümeler İçinde', 'uzak-usumeler-i-cinde-abdi-kadir-birinci-fluxx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzak üşümeler içinde

Yeşeren tohum taneleri

Baharla yaz arası

İki büklüm- bir gece bir gündüz.

Işığa uzanan el

yürüyen merdivende koşan çocuk

yüzüme yansıyan parıltı

aklımı alıp kaçan kız...

Uzamadı boyum

Kök su ya varasıya.

Alındığım dere kurumadı

Salındığım orman yanarsa diye.

Akla tırpan vurmada

Yarışa yokum

Su ile ateşe

Kandığım noktada.

Öyleyse,beynime aradığım çare

Son duraksa

Kıramadığım ruhuma

Akıttığım sır neydi?', 'Uzak üşümeler içinde Yeşeren tohum taneleri Baharla yaz arası İki büklüm- bir gece bir gündüz. Işığa uzanan el yürüyen merdivende koşan çocu...', ARRAY['Türk Edebiyatı','Şiir','Abdi Kadir Birinci']::text[], 8.5, '{"poet":"Abdi Kadir Birinci","poet_slug":"abdi-kadir-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzak-usumeler-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız', 'yalniz-binay-donmez-fxt5l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sahile vuran dalgalar gibi

umudun seni sürüklemesini beklersin.

yakamoz acıtır yüreğini

bir sensindir, bir de sen

ıssız,sakin ve aldırışsız.

gözlerini kapatır o ilk anı hayal edersin

tutkulu ve deli...', 'sahile vuran dalgalar gibi umudun seni sürüklemesini beklersin. yakamoz acıtır yüreğini bir sensindir, bir de sen ıssız,sakin ve aldırışsız....', ARRAY['Türk Edebiyatı','Şiir','Binay Dönmez']::text[], 8.5, '{"poet":"Binay Dönmez","poet_slug":"binay-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalniz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba', 'acaba-omer-avsar-j4rga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sebebsiz hayat hayatmidir

bir seyler istemek uzakmidir

sevdayi yesertmek serapmidir

gönlü susturmak harammidir

insanlarda farki görür müyüz

diken batmasada üzülür müyüz

bosuna yasayip ölür müyüz

kafesdeki kus gibi özgür müyüz', 'sebebsiz hayat hayatmidir bir seyler istemek uzakmidir sevdayi yesertmek serapmidir gönlü susturmak harammidir insanlarda farki görür müyüz ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/acaba-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunaldım', 'bunaldim-omer-avsar-03l7f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kirilmis kalbim parçalaniyor dört bir tarafa

kafesdeki kus kadar mahsunum buralarda

öfkem kabardi artik sabrimla yanyana

bilmeden yürüyorum çikmaz yollarda

içimde SIKINTI var günden güne büyüyen

cana sine gülemedim belkide bu yüzden

ugursuz bir parmak var talihimi engelleyen

çare bulamiyorum bilmem neden

daraldim bunaldim artik yoruldum

kendi kendime kalamaz oldum

anlamak için anliyani aradim durdum

sans küsmüs bir kere bosa benim umudum', 'kirilmis kalbim parçalaniyor dört bir tarafa kafesdeki kus kadar mahsunum buralarda öfkem kabardi artik sabrimla yanyana bilmeden yürüyorum ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bunaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyorsak eğer', 'yasiyorsak-eger-omer-avsar-4b6iy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'biktim bitmez yalanlardan

sonu gelmeyen ihtiraslardan

vazgeçtim sevdalardan

korkum sadece insanlardan

kalbim acilarla dolu

geldi artik ömrün sonu

biterken hayat yolu

nasihatim var ademoglu

yasadigin kar kalir sanma

derdine ortak olan yoksa

paranin gücüne aldanma

sevenden çok sevmiyenin varsa', 'biktim bitmez yalanlardan sonu gelmeyen ihtiraslardan vazgeçtim sevdalardan korkum sadece insanlardan kalbim acilarla dolu geldi artik ömrün...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasiyorsak-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır Nereye Kadar', 'sabir-nereye-kadar-omer-avsar-g49ph', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gökyüzü sahittir dualarima

umudu bekledim gözüm kapida

kirginim artik yarinlara

gülmedi kader vuslat sonbahara

sabirla beklemistim yillarca

hakkim degilmiydi yasamak rahatça

sagligim yerinde çok sükür amma

birde kismetim olsaydi su dünyada

her seyi olursa SIKILIRMIS insan

denemedikki bilelim hiç yasamadan

hele o firsati versin verecek olan

bizde anliyalim toprak olmadan', 'gökyüzü sahittir dualarima umudu bekledim gözüm kapida kirginim artik yarinlara gülmedi kader vuslat sonbahara sabirla beklemistim yillarca ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sabir-nereye-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-omer-avsar-81x2u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kirilma yavrum sen sakin dünyaya

elbet bulunur dogru güçde olsa

devam et güzeli durmaksizin aramaya

hiç degilse çabaladim dersin en sonunda

yasamayi iste gönül gözünle

degeri ver samimi sözlerinle

kötü bulur cezasini hiç düsünme

bilki allah her zaman seninle

baskasi yapiyormu diye sorgulama

kibir atesinde sende kavrulma

verdigim nasihatlerden asla sasma

en nihayet duacim olursun sakin unutma', 'kirilma yavrum sen sakin dünyaya elbet bulunur dogru güçde olsa devam et güzeli durmaksizin aramaya hiç degilse çabaladim dersin en sonunda ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ogut-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk''e Saygılarımla', 'ataturk-e-saygilarimla-omer-avsar-t8ep1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'paramparça memleketi toplayan kimdir

öndere bakin öndere mustafa kemaldir

elbette yardim eden kendi milletidir

dikkat edin bu toprak bagimsiz türkiyedir

düsün bir kez olmasaydi

düsman çevirmis her bir tarafi

padisah dersen önemsemez halkini

güvendi milletine aldi bayragi

sana ne kadar tesekkür etsem az

senin sevgin gönüllere sigmaz

geçmis gelecek yaptigini yapamaz

sagol atam budur içimizdeki niyaz', 'paramparça memleketi toplayan kimdir öndere bakin öndere mustafa kemaldir elbette yardim eden kendi milletidir dikkat edin bu toprak bagimsi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ataturk-e-saygilarimla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'görünen Manzara', 'gorunen-manzara-omer-avsar-0q3d4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'acimasiz hissiz zavalli bir serüven

nereden tutarsan sapir sapir dökülen

yiyicileri durmaksizin üreten

düzen bozuk kardesim düzen

dürüst kalmayi kimse beceremiyor

çalmayan insana enayi deniyor

rüsveti en tabi hakki zannediyor

oysaki günden güne eriyip bitiyor

adaleti mumla arar olduk

ahlakli insanlari geçmisde bulduk

yanlis nerede diye hep baskalarina sorduk

fetbazlik etmeden kazanmayi çoktan unuttuk

dogruluk deyince herkez basliyor sallamaya

dinleyen katiliyor bu yalan kervanina

bilmesen inanirsin edilen bunca laflara

ama hesap günü gelince yüzün olmaz konusmaya', 'acimasiz hissiz zavalli bir serüven nereden tutarsan sapir sapir dökülen yiyicileri durmaksizin üreten düzen bozuk kardesim düzen dürüst kal...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gorunen-manzara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Öyküsü', 'umudun-oykusu-omer-avsar-lxchv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gün açacak ülkemde aydinligin beyaz gülleri

bir gün dönecek ülkemin kara talihi

belki görecegiz belkide olacagiz fani

ama bilinki bu düzen degismeli

yetimin mali serefsizin olmus sakizi

namuslu yasamaya çalisanin durumu içler acisi

yönetenler dersen hepsinin gözü kapali

sustukça sira sana gelir unutma bu lafi

iscisi ögrencisi memuru köylüsü

hepsi elele verecek bitecek zalimin sömürüsü

o güzel ve mutlu günün öyküsü

geç olmadan gelecek bu ATATÜRK gençlerinin sözü

                          06.10.1998', 'bir gün açacak ülkemde aydinligin beyaz gülleri bir gün dönecek ülkemin kara talihi belki görecegiz belkide olacagiz fani ama bilinki bu düz...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umudun-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bir Meleksin', 'sen-bir-meleksin-cengiz-yazici-6ir6a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '. Sen varsın aklımda, hayallerimde birtek sen. 

Elimde değil, yaşayamam ben seni düşünmesem. 

Nasılki muhtaçsa, ağaçlar yaşam için toprağa, 

Ben de sana işte, nefes gibi bir nebze soluğa. 

İçimde kopan fırtınaları bir sen bilirsin, 

Ruhumda, gönlümde, kalbimde çok derinlerdesin, 

Mısralara sığar mı ki yazılacak bu kelimeler, 

En son sendedir sende biter bu dizeler. 

Lugatlarda var mı acaba bu sevdanın manası, 

Esası yoktur başka yerde aransın asıl anlamı .

Karabasandır sensiz geçen anlar zamanlar, 

Senin anladığın gibi söyle beni kim anlar .

İsmim cismim benliğim sensin artık benim ,

Namert olsun unutan namert olsun kardeşim....', '. Sen varsın aklımda, hayallerimde birtek sen.  Elimde değil, yaşayamam ben seni düşünmesem.  Nasılki muhtaçsa, ağaçlar yaşam için toprağa, ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-bir-meleksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkını Helal Et.', 'askini-helal-et-cengiz-yazici-qldaf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben seni çocukça sevdim;aksi olamazdı elbet.

Sen demiştin.Güzel günler yakın biraz sabret.

Bekledim,bekliyorum,bekleyeceğimde.Ya hasret,

Her şey bitsin istersen.Gel hakkını helal et.

Bırak benim masum çocuksu aşkım bende kalsın,

Dün vardın,bugün varsın.yarında olacaksın,

Sen bir gülsün.Lakin başkasında açacaksın,

Herşey bitsin istersen.Gel hakkını helal et.

Sen bendeydin,bense çoktan benden geçmiştim,

Onca güzel vardı.Yüz güzelden seni seçmiştim,

Ekmeğimdin sanki aşımdın,nimet gibi sevmiştim

Herşey bitsin istersen.Gel hakkını helal et.

Gelmez artık,gelmeyecek güzel dediğin günler,

Açmayacak artık,aşkımın anlamı kadife güller,

Günemi inat,gülemi acep,ötmez oldu bülbüller,

Herşey bitsin istersen.Gel sen hakkını,hakkını.HAKKINI ve AŞKINI helal et..................', 'Ben seni çocukça sevdim;aksi olamazdı elbet. Sen demiştin.Güzel günler yakın biraz sabret. Bekledim,bekliyorum,bekleyeceğimde.Ya hasret, Her...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askini-helal-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Sömürüsü', 'duygu-somurusu-cevahir-evren-fkb98', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevdiğimi söylüyorum

duygu sömürüsü

sevmiyorsu diye 

duygu sömürüsü

anlatamıyorum

duygu sömürüsü

anlamıyorsun diye

duygu sömürüsü

gidiyorum buralardan

duygu sömürüsü

gitme dedin diye

duygu sömürüsü...

nerde, ne zaman ve ne şekilde

kim, kime, kimin için

ağlasam duygu sömürüsü

gülsem duygu sömürüsü

bilmesem duygu sömürüsü

sen diye diye

duygu sö-mü-rü-sü...', 'sevdiğimi söylüyorum duygu sömürüsü sevmiyorsu diye  duygu sömürüsü anlatamıyorum duygu sömürüsü anlamıyorsun diye duygu sömürüsü gidiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/duygu-somurusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gelir', 'dun-gelir-cevahir-evren-ngu2m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dün gelir açılır kapılar boylarında

vardığın su şehri akmaz olur diyarına

bırak o da anlatsın gurbet elde 

sen de dinle o anlatsın diye

gitsin bir rüzgar kıyılarına 

varsın da gelsin

uzak bir kuş olsun gökyüzünde

gözden kaybolunca

uçsun gitsin...', 'dün gelir açılır kapılar boylarında vardığın su şehri akmaz olur diyarına bırak o da anlatsın gurbet elde  sen de dinle o anlatsın diye gits...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dun-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bileceksin', 'bileceksin-eren-erimer-p0x4z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'vapurdan atılan simitlere 

dalan martılara bak göreceksin

o bir tanesi zayıf, acizse

sana nasıl koştuğumu bileceksin

görüş gününde bir mahkuma bak

daldığında gözleri gökyüzüne

yokluğun yağarken üstüme bir sağnak

seni nasıl özlediğimi bileceksin

uzuvlarını kaybetmiş bir gaziye bak

çırpınırken bir şeyler yapmaya

yaşamaksa yaşadığı ağar aksak

ne kadar yarım olduğumu bileceksin

korkularının en büyüğünü düşün bir gün

içimdeki Allah korkusunu anla diye

gazete ilanlarında gözün takıldığı gün

seni ne çok sevdiğimi bileceksin', 'vapurdan atılan simitlere  dalan martılara bak göreceksin o bir tanesi zayıf, acizse sana nasıl koştuğumu bileceksin görüş gününde bir mahku...', ARRAY['Türk Edebiyatı','Şiir','Eren Erimer']::text[], 8.5, '{"poet":"Eren Erimer","poet_slug":"eren-erimer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bileceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-cevat-aydin-5l38z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dokuz ay karnında taşımışsın beni,

Bıkmadan, yorulmadan, usanmadan.

Bana vermişsin kalbinin en değerli köşesini,

Çekinmeden, yılmadan, gözünü kırpmadan.

Sonra çocuk olup büyütmüşsün beni,

Her şeyimle sen ilgilenmişsin,

Elim ayağım olmuşsun yani.

En hırçın halimle bile,

Avutmaya çalışmışsın beni.

Ninniler söylemişsin,

Uyutmaya çalışmışsın beni.

Sonra delikanlı olmuşum, büyümüşüm,

Bu sefer nasihatler vermişsin.

Adam olmak için sığınacağım,

Tek kapı senmişsin.

Bilemedim değerini anam,

Dertliyim yine gurbet ellerde sensiz.

Kanayıp duruyor bağrımda yaram,

Ben ki senin hayatının çilelere boğdum,

Affet beni ne olursun, affet beni anam.

Sanki çile çektirmek için mi doğdum,

Uzat  bedenini bedenime saram.

Unutma ki sensiz ben bir hiç oluyorum,

Yine de kalbimin tahtına seni koyuyorum.

Affet beni anam, hakkını helal et.

Affına sığındım ne olur kabul et.

Ne olursa olsun dualarını eksik etme,

Ne olursa olsun benim için de dua et.', 'Dokuz ay karnında taşımışsın beni, Bıkmadan, yorulmadan, usanmadan. Bana vermişsin kalbinin en değerli köşesini, Çekinmeden, yılmadan, gözün...', ARRAY['Türk Edebiyatı','Şiir','Cevat Aydın']::text[], 8.5, '{"poet":"Cevat Aydın","poet_slug":"cevat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/anam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçtur Sensizlik', 'suctur-sensizlik-yaren-gurler-lqlwr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç eder toplasam acımla sevdamı?

Üzerime hasretimi eklesem kaç eder ki?

Ya ağladığım yağmurlar,

Yalvardığım tanrılar,

Yumrukladığım duvarlar?

Kaç eder ki bensiz bu dünya?

Yahut sensiz ben kaç eder?

Suç eder gözlerine dokunmak.

Sensiz sevişmek neyler ki nefse?

Sensiz ağlamak ne ki, gülmek ne?

Yaşamak ne ki, ölmek ne?', 'Kaç eder toplasam acımla sevdamı? Üzerime hasretimi eklesem kaç eder ki? Ya ağladığım yağmurlar, Yalvardığım tanrılar, Yumrukladığım duvarla...', ARRAY['Türk Edebiyatı','Şiir','Yaren Gürler']::text[], 8.5, '{"poet":"Yaren Gürler","poet_slug":"yaren-gurler","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/suctur-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Terk', 'aski-terk-refik-recep-pelit-sts7n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayalettiğim bulut ufukta kaybolup gider 

Rüyalarım Her akşam beni böyle terk eder, 

Gönülden kovuldumu o lezzetli sezgiler,   

Gözümdeki ışık, kulağımdaki ses gider 

İstikamet kaybolur fani olur bu ömür, 

Ne geri dönebilirim ne de  ileri giderim

Azap çeken benim! derinlerdeki yüreğim

Gül solar bülbül susar, doruklardan renk gider, 

Güneş doğmaz olur, karanlık sarar beni, 

Üşüyen ruhum yanlız, fevkindeki ten değil, 

Belki sabah olur, seherler küskün değil,  

Gece uyur, yıldız söner, gökyüzünden fer gider!', 'Hayalettiğim bulut ufukta kaybolup gider  Rüyalarım Her akşam beni böyle terk eder,  Gönülden kovuldumu o lezzetli sezgiler,    Gözümdeki ış...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aski-terk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-erhan-tigli-dmnd8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SENİ DÜŞÜNÜYORUM

Seni düşünüyorum

Göle iniyor bir ceylan

Sefere çıkıyor her bakışında

Yepyeni bir kervan

Seni düşünüyorum

Doğuyor içimde

Yemyeşil bir orman

Gülüşünle yazıyorum

Kötünün, çirkinin katline ferman

Seni düşünüyorum

Duruyor zaman

Çilenin rüzgarı

Yaman esiyor yaman

Dinlemiyor aman

Ama seni düşünmenin gücü

Oluyor yaralı gönlüme derman

Seni düşünüyorum

Gökkuşağına dönüşüyor dünyam.

Erhan TIĞLI', 'SENİ DÜŞÜNÜYORUM Seni düşünüyorum Göle iniyor bir ceylan Sefere çıkıyor her bakışında Yepyeni bir kervan Seni düşünüyorum Doğuyor içimde Yem...', ARRAY['Türk Edebiyatı','Şiir','Erhan Tığlı']::text[], 8.5, '{"poet":"Erhan Tığlı","poet_slug":"erhan-tigli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-dusunuyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünme Kulesi', 'dusunme-kulesi-duygu-yalcin-7njco', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşlerim var dedim

Çalmaya kalktılar

Sevgilerim var dedim

Yakmaya kalktılar

Tükendim,bırakın dedim

Durdurmaya çalıştılar

Ne istiyorsunuz dedim

Özgürlüğünü diye haykırdılar

Hadi!Şimdi gelin yanıma

Düşünme Çocukları Kulesinin en tepesine

Yetişemezsiniz ki

Uzanamazsınız ki

Uzatmam ki elimi sizin gibilere

Paylaşmam ki hayatımı sizin gibi cahillerle

Hadi şimdi gelin alın düşlerimi

Yakın sevgimi,esir edin,durdurun beni

Yapamazsınız ki...

Düşlerimi çalamazsınız

Sevgimi yakamazsınız

Artık beni durduramazsınız ki...

haziran 2001', 'Düşlerim var dedim Çalmaya kalktılar Sevgilerim var dedim Yakmaya kalktılar Tükendim,bırakın dedim Durdurmaya çalıştılar Ne istiyorsunuz ded...', ARRAY['Türk Edebiyatı','Şiir','Duygu Yalçın']::text[], 8.5, '{"poet":"Duygu Yalçın","poet_slug":"duygu-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dusunme-kulesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matematik Hayatlar', 'matematik-hayatlar-duygu-yalcin-3jtmw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatımın cosinüs 30`undayım

Logaritmanın sonu integralin başındayım

Karmaşık sayılarla içiçeyim

Üç bilinmeyenli denklemler halt etmiş 

Ben çözülmeyen tam bilinmeyenli denklemim

Doğal sayıları geçtim

Rasyonelleri boşverdim

Geldim hayatın analitik çemberdeki yerine

Ben neredeyim bu çemberde?

Birinci,ikinci,üçünçü bölge?

Hayır,ben tam orjindeyim...

Çarpanlarıma ayrılmam

Fonksiyonumu aldırmam

Başka kümelerle kesişmem

Parabol hayatlar yaşamam

Dedim ya

Ben hayatımın cosinüs 30`undayım

Logaritmanın sonu,integralin başında...

haziran/2001', 'Hayatımın cosinüs 30`undayım Logaritmanın sonu integralin başındayım Karmaşık sayılarla içiçeyim Üç bilinmeyenli denklemler halt etmiş  Ben ...', ARRAY['Türk Edebiyatı','Şiir','Duygu Yalçın']::text[], 8.5, '{"poet":"Duygu Yalçın","poet_slug":"duygu-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/matematik-hayatlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibiyim', 'gibiyim-cevat-aydin-5b4nl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşil gözüm can özüm,

Gönül közüm verdiğim sözüm,

Beni yürekten yakan vefasız,

Gelmediğin an hayata küstüm.

Yollara düştüm mecnuna döndüm,

Bir mum gibi eriyip söndüm,

Dostun bağında bir gonca güldüm, 

Sararıp  soldum,hazan gördüm. 

Kerem olup aşkın narına yandım,

Çeke çeke hasretine kandım.

Uzaklardan bir ses duydum,

Sesime ses veren nazlı yar sandım.

Ferhat oldum dağları deldim,

Bu canı yoluna serdim,

Bir zamanlar deli rüzgar gibi eserdim,

Şimdi rüzgarda kırık dal gibiyim.

Senin için yaşadım, senin için öldüm,

Senin için yazdım, senin için şairim.

Nice derdi içime atıp gömdüm,

Şimdi omuzlarda taşınan sal gibiyim.

Bir zamanlar elin elimden ayrılmazdı,

Gözün gözüme değdiği anda utanırdı.

Ayrılmazdık hiçbir yerde, hep beraberdik,

Şimdi uzaklardan bakan el gibiyim.

Rüzgarda kırık bir dal,

İşte o benim, şöyle bir düşün ve dal.

Ben çile çekeyim sen mutlu kal,

Derbedere dönmüş perişan gibiyim.', 'Yeşil gözüm can özüm, Gönül közüm verdiğim sözüm, Beni yürekten yakan vefasız, Gelmediğin an hayata küstüm. Yollara düştüm mecnuna döndüm, B...', ARRAY['Türk Edebiyatı','Şiir','Cevat Aydın']::text[], 8.5, '{"poet":"Cevat Aydın","poet_slug":"cevat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gibiyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram', 'haram-cevat-aydin-ncgmn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdalar yalan oldu,

Yerini zevk-i sefa aldı.

Yiğitler öldü,yok oldu,

Yerini namertler aldı.

Şiirler yazıyorum senin için,

Bir an oluyor isyan ediyorum,

Bir an geliyor kırık bir dal gibi,

Boynumu eğip ağlıyorum.

Göz yaşlarım da sana fedadır,

Bu can sana kurban,sana hebadır,

Senden başkası bana haramdır,

Sensiz yaşamak da bana cefadır.

Vuslat da haram,

Sevmek de haramdır.

Bağrımda merhemsiz yaram,

Tabipler de bana haramdır.', 'Sevdalar yalan oldu, Yerini zevk-i sefa aldı. Yiğitler öldü,yok oldu, Yerini namertler aldı. Şiirler yazıyorum senin için, Bir an oluyor isy...', ARRAY['Türk Edebiyatı','Şiir','Cevat Aydın']::text[], 8.5, '{"poet":"Cevat Aydın","poet_slug":"cevat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haram-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemancı', 'kemanci-cevat-aydin-6ycrh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir acı,

Beynimde bin bir düşünce,

Dertli birşeyler çal kemancı,

Sarhoş olmak istiyorum delicesine.

İntihar mı etsem,

İsyan mı bilmem.

Dertli çal be kemancı,

Artık bu hayatı çekemem.

Neden kader gülmüyor bize,

Neden neden be kemancı,

Neden yüce dağlar yol vermez bize,

Neden hayat hep bize veriyor acı.

Toprağa ölmeden girerim be,

Girelim ne olacak sanki,

Sevdiklerim mutlu olsun,

Kabirde de mutlu olurum inan ki.', 'Yüreğimde bir acı, Beynimde bin bir düşünce, Dertli birşeyler çal kemancı, Sarhoş olmak istiyorum delicesine. İntihar mı etsem, İsyan mı bil...', ARRAY['Türk Edebiyatı','Şiir','Cevat Aydın']::text[], 8.5, '{"poet":"Cevat Aydın","poet_slug":"cevat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kemanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisandan Önce', 'nisandan-once-asli-donmez-u7s14', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günler geçer önümden

Günler geçer ve gülümser

Tutup çekemem kolundan

Günleri geri getiremem

Günler geçer önümden

Günler geçer ve gülümser

Konuşsam

Ah bir konuşabilsem

                                    (1997)', 'Günler geçer önümden Günler geçer ve gülümser Tutup çekemem kolundan Günleri geri getiremem Günler geçer önümden Günler geçer ve gülümser Ko...', ARRAY['Türk Edebiyatı','Şiir','Aslı Dönmez']::text[], 8.5, '{"poet":"Aslı Dönmez","poet_slug":"asli-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nisandan-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-baver-beser-452mk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yokken; sararıyor benzim, çürüyor bedenim.

Yitiriyorum umutlarımı, geleceğimi.

Kaygılarım dev bir canavar oluyor...

Çocukluğuma dönüyorum korkuyor ve yaşlanıyorum.

Beklentilerim kırgınlığım oluyor hayata dair.

Ne yağmurda dolaşıyorum ne de dolunayı seyrediyorum.

Tüm kapılarımı hayatın yüzüne kapadım.

Çıkışı olduğunu bildiğim ama arayamadığım

Çıkmaz sokaklarla dolu, ihtiyar bir şehirdeyim.

Kapatma vakti göz perdelerini bu şehre.

Ve son sözlerim olduğunu bildiğim cümleler,

dudaklarımdan süzülürken; 

Kendime ağıtlar yakıyorum...

İçimde sönmekte olan bir ateş,ölen bir ben var.

Belki bir yağmurla yüzüne, bir çiçekle ellerine dokunurum.

Belki de mavi gözlü bebeğin olurum...

Bir gün...', 'Sen yokken; sararıyor benzim, çürüyor bedenim. Yitiriyorum umutlarımı, geleceğimi. Kaygılarım dev bir canavar oluyor... Çocukluğuma dönüyoru...', ARRAY['Türk Edebiyatı','Şiir','Baver Beşer']::text[], 8.5, '{"poet":"Baver Beşer","poet_slug":"baver-beser","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-gun-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyamız', 'ruyamiz-cahit-sitki-taranci-funuw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir havuz kenarında yan yana oturmuşuz;

Bu su bizim gölgemiz,biziz şeffaf ve temiz.

Su sesine uyarak bir şarkı tutturmuşuz,

Açılan güller gibi suda gönüllerimiz.

Ne vakitten beridir burada oturmuşuz?

Dünden, hatta bugünden bile yok haberimiz.

Yaşamanın en güzel noktasında durmuşuz,

Bir huzur ahengine dalmış gönüllerimiz.

Uyanabilir miyiz sanki böyle rüyadan?

Asırlar kadar uzun,müphem ve tatlı bir an,

Biz o kadar sarhoşuz, o kadar sarhoşuz biz!

İşte gözlerimizde bu suyun derinliği,

İçimizdedir işte bu suyun serinliği;

Biz o kadar, o kadar birbirimiziniz.', 'Bir havuz kenarında yan yana oturmuşuz; Bu su bizim gölgemiz,biziz şeffaf ve temiz. Su sesine uyarak bir şarkı tutturmuşuz, Açılan güller gi...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ruyamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşem', 'aysem-asik-sefai-i08c4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimi annaya ,bellaya ,kimi mariyaya kimide kızıl saçlı nataşaya yazdı oysa ben bir Türk yiğidiyim Türk'' e 

sevdalı olduğum için Ayşem sana yazıyorum... 

        Ben seni kongoda ölen sevgilisini İstanbul''da arayan teksaslı bir dişi gibi değil,aşk eşittir burjuva güzellerini diskoteklerde arayan zübbeler gibi değil,hele kafalarındaki kirli duyguları nataşa adlı rus kızında sembolleştiririp kızıl ruble arayanlar gibi aramıyorum Ayşem... 

        Ben seni; belki bir ana ceylanın vurulmuş yavrusuna su aradığı gibi... Belki bir Anadolu delikanlısının kaçırmak için güzel Zeynep''ini gecenin alaca karanlığında aradığı gibi arıyorum Ayşem... 

        Ama muhakkak bütün iyilikleri bütün güzellikleri bütün özlemleri sende bulacağımı bilerek engin denizin kudurmuş dalgaları gibi önümdeki tüm engelleri aşarak yüce ALLAH''IN izniyle seni arıyorum Ayşem... 

        Seni kaybettiğim dünyalarda bulmak istiyorum. O dünya; HZ.FATİH'' in kılıcının altın kapması Estergon dönüşünün gönülleri yakması veyahut Tuna''nın bir Itri bestesinde musiki gibi çağlayıp akması olabilir geçtiğim 

yıllardaki parlak aynalar geleceğimi aydınlatır benim bir elim geleceğin MİLLİYETÇİ TÜRKİYE sinde ise YAVUZ ''un beyaz atının yelesindedir öbür elim... 

        Seni kaybettiğim ve şimdi aramaya çıktığım dünyalarda Ayşem; ne meyhane tezgahları ardında mum gibi 

yanıp sönen kızlarımın gözlerinin karası, ne yoksulluktan ve fakirlikten ölen yiğitlerimin verdiği yürek yarası, nede başı kabak; yalın ayak dolaşan insanımın ciğerlerini hilton gecelerin de içkilerine meze yapıp yiyen kahpelerin ağız kavgası var... 

            Seni kaybettiğim ve şimdi aramaya çıktığım dünyalarda; bir KURAN,bir KILIÇ ve bir BOZKURT üçünün ördüğü koca bir dünya koskoca bir tarih var Ayşem... 

        Tut ki seni karanlığın ta ötesinde bir yere hapsetsinler ömründe güneşi hiç görmeyeceksin; ama ben o güneşi yanıma aldım seni kurtarmaya geliyorum Ayşem... 

        Ne sezar, ne hitler, ne posbıyıklı stalin, nede faresuratlı mao; çözemez, çözemez, çözemez senin derdini Ayşem... 

        Senin derdini; batılılık delisi sömürge aydınları robert koleji mezunu özgürlük budalaları ve kafalarını çirkin kapitalistlere satmış deve kuşlarıda çözemez... 

Senin derdini Ayşem; senin gibi konuşan, senin gibi düşünen, senin gibi yaşayan, velhasıl kelam bizler ÜLKÜCÜLER çözeriz senin derdini... 

        Anamın anlattığına göre Koca Türk Dünyası''nın küçük bir köyünde doğmuşum senin için doktor yada ilaç 

ekmek yada su ne ise benim için MİLLİ DEVLET, KIZIL ELMA ÜLKÜSÜ odur... 

        Sen benim için; Kırım'' lı Bike, Azerbaycan'' lı Aybala, Yerköy'' lü Fadime hepiniz bizim için birsiniz. Çünkü 

bizim kanunumuzda akvaryumlu meyhanelerde sevgilinin kömür karası gözlerine şiir yazmak yok biz çoktan erittik ÜLKÜ denen nazlı gelinin duvağında sülün gibi kızların göz bebeğini Ayşem... 

        Bizim kanunumuzda geri bıraktırılmış insanımızı, esir milyonlarca soydaşımızı tutsaklıktan kurtarmak için,bu geri kalmışlığa son vermek için birlikte mücadele etmek var... 

        Bu; ne benim sana ağlayarak, nede dizlerine kapanarak bir yalvarışımdır... 

        Bu; parmakları çelikten, yürekleri Estergon demirinden, yüz binlerce, milyonlarca MÜSLÜMAN TÜRK ÜLKÜCÜSÜ ''NÜN sana durdurulmaz emridir... 

        Kendine dön, kendine dön Ayşem...', 'Kimi annaya ,bellaya ,kimi mariyaya kimide kızıl saçlı nataşaya yazdı oysa ben bir Türk yiğidiyim Türk'' e  sevdalı olduğum için Ayşem sana y...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aysem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-murat-gencer-azilh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün daha çizdim takvimimden

Sana bir gün daha yaklaştım,

Yağmur yağıyor dışarıda gözlerinden akan yaş misali

Daha da güzeli onların mutluluk gözyaşları oluşu

Sana Seni nasıl sevdiğimi anlatamıyorum bile

Hani derler ya;gerçek sevgi budur diye

Asıl gerçek sevgi benim sevgim işte

Ve sana bir kez daha söylüyorum

Seni Seviyorum…', 'Bir gün daha çizdim takvimimden Sana bir gün daha yaklaştım, Yağmur yağıyor dışarıda gözlerinden akan yaş misali Daha da güzeli onların mutl...', ARRAY['Türk Edebiyatı','Şiir','Murat Gençer']::text[], 8.5, '{"poet":"Murat Gençer","poet_slug":"murat-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-seviyorum-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkım Değilmi', 'hakkim-degilmi-murat-gencer-pv2b2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hakkım değilmi gözlerine bakmak doya doya

Seni seviyorum diyemesende dediğini bilmek

Yalnızken seninle konuşmak, gülmek belkide ağlamak

Hakkım değilmi hergün gözlerine bakıp 

Seni Seviyorum demek', 'Hakkım değilmi gözlerine bakmak doya doya Seni seviyorum diyemesende dediğini bilmek Yalnızken seninle konuşmak, gülmek belkide ağlamak Hakk...', ARRAY['Türk Edebiyatı','Şiir','Murat Gençer']::text[], 8.5, '{"poet":"Murat Gençer","poet_slug":"murat-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hakkim-degilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tohdur Beğ', 'tohdur-beg-abdurrahim-karakoc-m0h9v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Avrat yeğin sayrı, benim karnım aç,

Keyf için gelmedik bura tohdur beğ.

Fukara harcından yaz da bir ilaç,

Olsun derdimize çare tohdur beğ.

Tama vatandaşık, gardaşık tama...

Bunca pahılm’olur adam adama? 

Geldik ta sabahtan, kaldık akşama,

Yarına mümkün mü sıra tohdur beğ? 

Yedi baş horanta yıkık hânede..

Tüm kazancım bini bulmaz senede; 

Yüz pangunut helâl olsun gene de; 

Ben nereyim, beşyüz nere tohdur beğ? 

Tek kaşıkla çorba içer dördümüz..

Kul başından ırak ola derdimiz.

Senden, benden esker ister ordumuz.

Candan da mı yeğdir para tohdur beğ? 

Dert-belâ tebelleş oldu başıma,

Her gece tahsildar girer düşüme...

Beni mahcup etme can yoldaşıma,

Erkeklik öldü mü bre tohdur beğ? 

Büyük oğlan esker, öteki çırak,

Han için param yok, oteli bırak...

Mevsim kış, yollar sarp, köy hayli ırak; 

Bir değil, beş değil yara tohdur beğ.

Memur gelir karşılarsın köşeden,

Zengin gelir kırılırsın neşeden.

Öte kaçma bizim garip Eşe’den,

Bakıp boynundaki kire tohdur beğ.

Hemi Müslümanım, insanım hemi; 

Hâlimi arzettim darılma e mi? 

İçinde mangır yok, gördün kesemi; 

Bir de ceplerimi ara tohdur beğ.

Daha sayayım mı? Noksan mı daha? 

Yalvara yalvara tükendim aha..

Bu yüzle mi çıkacaksın ALLAH’a? 

Vallahi yanarsın nara tohdur beğ.

(Vur Emri)', 'Avrat yeğin sayrı, benim karnım aç, Keyf için gelmedik bura tohdur beğ. Fukara harcından yaz da bir ilaç, Olsun derdimize çare tohdur beğ. T...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/tohdur-beg-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sönmeyen Ateş', 'sonmeyen-ates-sair-gokay-rs4sw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'S abahın olmasına az bir vakit var,

Ö ylesine bir sıkıntı beynimi kemiriyorki!

N e olduğunu bir türlü bilmediğim bir sıkıntı.

M ıhlanmış duyguların eziyetiyle

E n derin bir boşlukta, kayıtsızca 

Y ok olmanın verdiği bir telaş, bir sükut

E hemniyetsizce atılan adımlar ve izler,

N eticesiz görünen bu sorular ve ben.

A ğlamak isteyen gözlerim ağlayamaz bi çare

T ek bir damla göz yaşı dökmek bile nafile

E saret altında kalmış beyhude,

Ş aşkın şaşkın gezerken alemlerde,

İ mtiyazsızca yaşanan geçmişin bedeli mi bu?

N ağme nağme yerleşen hücrelerime.

I slak bir zemin üzerinde 

Z annedildiğinden daha sıcak bir alev,

D okundukça en derinliklerde hissedilen.

I zdırabın her nevisini yaşatan gün be gün,

R aksettiren hayatın cilveli yokuşlarında

A dını kalbime kazıdım bu ateşin közleriyle

B eyhude silemezler sensin nedeni

I zdırabın her nevisini yaşatan gün be gün', 'S abahın olmasına az bir vakit var, Ö ylesine bir sıkıntı beynimi kemiriyorki! N e olduğunu bir türlü bilmediğim bir sıkıntı. M ıhlanmış duy...', ARRAY['Türk Edebiyatı','Şiir','Şair Gökay']::text[], 8.5, '{"poet":"Şair Gökay","poet_slug":"sair-gokay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sonmeyen-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülcan', 'gulcan-murat-gencer-nf93e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül görünce 

Can denince 

Aklıma geliyorsun

Tüylerim diken diken oluyor... 

Aşk denince 

Yar duyunca 

Aklıma geliyorsun 

Yüreğim kıpır kıpır oluyor... 

Gün doğunca 

Ay gülünce 

Aklıma geliyorsun 

Tekrar tekrar aşık oluyorum sana...', 'Gül görünce  Can denince  Aklıma geliyorsun Tüylerim diken diken oluyor...  Aşk denince  Yar duyunca  Aklıma geliyorsun  Yüreğim kıpır kıpır...', ARRAY['Türk Edebiyatı','Şiir','Murat Gençer']::text[], 8.5, '{"poet":"Murat Gençer","poet_slug":"murat-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulcan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alperenler Otağı', 'alperenler-otagi-yaman-turk-2i0no', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İzlerimiz şehitlerin izleri, 

Sözlerimiz yiğitlerin sözleri, 

Tanıyanlar tanır elbet bizleri, 

Devlet uğruna kan verenleriz 

Yeşil Ilgaz''lı Alperenleriz 

Dilimizde tekbirler Bismillah, 

Elimizde sabrımız, tek silah, 

Geliyoruz, geliyoruz inşallah, 

Vatan uğruna can verenleriz 

Yeşil Ilgaz''lı Alperenleriz 

Yeminimiz var sönmeyiz, 

Külleniriz, lakin sönmeyiz, 

Ölümleri öldürür, ölmeyiz, 

Erlik uğruna şan verenleriz 

Yeşil Ilgaz''lı Alperenleriz 

Genç Ozanım ışık saçan hâleyiz, 

Ay-yıldızlı albayrakta laleyiz, 

 Türkiye'' de aşılmayan kaleyiz, 

Ülkü uğruna can verenleriz 

Yeşil Ilgaz''lı Alperenleriz', 'İzlerimiz şehitlerin izleri,  Sözlerimiz yiğitlerin sözleri,  Tanıyanlar tanır elbet bizleri,  Devlet uğruna kan verenleriz  Yeşil Ilgaz''lı ...', ARRAY['Türk Edebiyatı','Şiir','Yaman Türk']::text[], 8.5, '{"poet":"Yaman Türk","poet_slug":"yaman-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alperenler-otagi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Andımız Turan''a', 'andimiz-turan-a-yaman-turk-qu1ga', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbimizde bu Ülkü 

Dilimizde bu türkü 

Yürüyoruz el ele 

Allah korusun Türk''ü 

Altaylardan Tuna''ya 

Kerkük''ten Buhara''ya 

El açtık Turan için 

Çıktık Tanrı Dağı''na 

Börteçine Asena 

Yol gösteriyor bana 

Önde Türkmen Başbuğu 

Yürüyoruz Turan''a 

Ülkücüyüz güçlüyüz, 

Albayrakta üçlüyüz, 

Andımız Turan''a dek, 

Yürümüzsek suçluyuz..', 'Kalbimizde bu Ülkü  Dilimizde bu türkü  Yürüyoruz el ele  Allah korusun Türk''ü  Altaylardan Tuna''ya  Kerkük''ten Buhara''ya  El açtık Turan iç...', ARRAY['Türk Edebiyatı','Şiir','Yaman Türk']::text[], 8.5, '{"poet":"Yaman Türk","poet_slug":"yaman-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/andimiz-turan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerin Türküsü', 'askerin-turkusu-yaman-turk-agxud', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tendürek''in karlı kara kışında 

Bir elinde silah bere başında 

Vatanını bekler sınır taşında 

Askere uzanan eller kırılsın 

Ne Ermeni PKK ne de başkası 

Durduramaz engeller yoktur şakası 

Kükrer ise titretir yerleri arşı 

Askere uzanan eller kırılsın 

Ezân-ı Muhammedî dinmez diyen 

Albayrak gökyüzünden inmez diyen 

Şehadet şerbetin gülerek içen 

Askere uzanan eller kırılsın 

Genç Ozanım ne desen hakkı ödenmez, 

Mehmetçik nöbette iken bu bayrak inmez, 

Vuruşur, vurulur gözyaşın dinmez, 

Askere uzanan eller kırılsın...', 'Tendürek''in karlı kara kışında  Bir elinde silah bere başında  Vatanını bekler sınır taşında  Askere uzanan eller kırılsın  Ne Ermeni PKK ne...', ARRAY['Türk Edebiyatı','Şiir','Yaman Türk']::text[], 8.5, '{"poet":"Yaman Türk","poet_slug":"yaman-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askerin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Sefai Hocama', 'asik-sefai-hocama-yaman-turk-6es3b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hele kulak ver Sefaî Hocam 

Davaya bağlı özü sende gördüm 

Çatal yürekler konuşsun ne gam 

Mert kelam, yiğit sözü sende gördüm 

Aşk kütüğüne vurmuşsun nacak, 

Geziyorsun köy, kent, bucak bucak 

İki çift laf etsen biri ocak, 

Ocağı, ataşı, közü sende gördüm.. 

''Emmoğlu, Allah razı olsun'' 

Aşk bağına giden yolsun 

Gönlüne feyz, muhabbet dolsun, 

Sohbeti, zevki, hazzı sende gördüm 

Bazen bağlaman karalar bağlar, 

Kerkük''le yas tutar, Kırım''la ağlar, 

Geçit vermese de demir dağlar, 

Yol gösteren izi sende gördüm 

Sözle anlatılmazsın sezdim ben, 

Gayrısını yazmaktan bezdim ben, 

Seninle diyar diyar gezdim ben, 

Dört mevsim yazı sende gördüm.. 

Genç Ozanım dile gelmiş çok mu ? 

Sazın sadak, türkülerin ok mu ? 

Hele o Ayşem şiirin yok mu ?

Mızrapı, teli, sazı sende gördüm', 'Hele kulak ver Sefaî Hocam  Davaya bağlı özü sende gördüm  Çatal yürekler konuşsun ne gam  Mert kelam, yiğit sözü sende gördüm  Aşk kütüğüne...', ARRAY['Türk Edebiyatı','Şiir','Yaman Türk']::text[], 8.5, '{"poet":"Yaman Türk","poet_slug":"yaman-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asik-sefai-hocama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-tacettin-simsek-k8zqy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dost istediğin anda çağır aynaları

Dilsiz ve soğuk

kör ve sağır aynaları

Benzerleri yoktur hani

sır saklamada

Sır ver ve güven

Sonra da

kır aynaları', 'Dost istediğin anda çağır aynaları Dilsiz ve soğuk kör ve sağır aynaları Benzerleri yoktur hani sır saklamada Sır ver ve güven Sonra da kır ...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aynalar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyükler Bilir', 'boyukler-bilir-abdurrahim-karakoc-tppqx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalan-dolan ile devran sürmeyi 

Biz ne bilek beğim, böyükler bilir. 

Milletin başına çorap örmeyi 

Biz ne bilek beğim, böyükler bilir. 

Rüşvet vermek, rüşvet almak nasıl şey 

Hazineden para çalmak nasıl şey 

Terlemeden zengin olmak nasıl şey 

Biz ne bilek beğim, böyükler bilir. 

Erken palazlanıp erken ötmeyi 

Değirmenler kurup baş öğütmeyi 

Hele meydan meydan adam gütmeyi 

Biz ne bilek beğim, böyükler bilir. 

Anlamayız kopya nedir, asıl ne 

Perde, sahne, solo, koro, fasıl ne 

Üçkağıtta erkân nedir, usul ne 

Biz ne bilek beğim, böyükler bilir. 

Viski, votka çekip keyif çatmayı 

Dansöz kucağında stres atmayı 

Milleti bölmeyi, vatan satmayı 

Biz ne bilek beğim, böyükler bilir. 

Kaç tür hokkabazlık, kâhinlik varsa 

Kaç şeytanlık varsa, kaç cinlik varsa 

Dünyada ne hile, ne hinlik varsa 

Biz ne bilek beğim, böyükler bilir. 

Namussuzluk yapın derler... Yaparız 

El uzatır öpün derler... Öperiz 

Put gösterir tapın derler... Taparız 

Biz ne bilek beğim, böyükler bilir. 

Seyrettikçe ana-baba filmini 

Hissederiz baskısını, zulmünü 

Lisansüstü maskaralık ilmini 

Biz ne bilek beğim, böyükler bilir. 

Âdettir gerekmez mâluma ilâm 

Taklide günaydın, asıla selâm 

Ne ki hınzırlık var hâsılıkelâm 

Biz ne bilek beğim, böyükler bilir.

10.12.1991

(Akıl Karaya Vurdu)', 'Yalan-dolan ile devran sürmeyi  Biz ne bilek beğim, böyükler bilir.  Milletin başına çorap örmeyi  Biz ne bilek beğim, böyükler bilir.  Rüşv...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/boyukler-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylülce', 'eylulce-tacettin-simsek-whv96', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben

Belki çocuktum

Ezik ve iyimserdim üstelik

Çıkarsız gülümserdim

Büsbütün pazarlıksız

İkinci yüzlerine uzaktım insanların

Gündelik telâşlara sıvanmamıştım daha

Ve henüz erkendi ağlamak için

Gördüm anne

Bu kentin kan tüküren bulvarları

Kuşkular emzirir çocuklarına

Bir yemin kopacak kadar incelir

Toy bakışlar boşalır korumasız evlerden

Çağa vurgun oğullar kızlar gider

Çağa kurban oğullar kızlar gelir

Acılıyım

Dokunsanız ağlarım belki

Bir yerlerde beter huylu adamlar

Kül savurur göğüs tahtam üstüne

Beri yanda ıtır soylu sevgilim

Gül dizer gönül haritam üstüne

Beni ölümlerle eğitir ustam

Ben türküler yakarım aziz ustam üstüne

Arasöz

     Aşkların

     ve acıların büyük olduğu yerde

     rumuz daima güldür

     Ve zaman

     muzdarip elifli bir eylüldür

Sevin anne

Benimle övün anne

Ben bir gül kavgasının şahidiyim

Çağa uyumsuz olmalı gözlerim

Bana has bir yalnızlığım olmalı

Dipnot

     Yine eylüldür

     Bizim semte yeni bir eylül yağar

     Ellerine tutunurum annemin

     Beş vaktime gül yağar', 'Ben Belki çocuktum Ezik ve iyimserdim üstelik Çıkarsız gülümserdim Büsbütün pazarlıksız İkinci yüzlerine uzaktım insanların Gündelik telâşla...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/eylulce-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-tacettin-simsek-av0zg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Onlar

kelebek soylu çiçekler miydi

Rüzgârlara savrulmuş etekler miydi

Ben onları on bin senedir bekliyorum

Onlar

beni

on bir sene

bekler miydi', 'Onlar kelebek soylu çiçekler miydi Rüzgârlara savrulmuş etekler miydi Ben onları on bin senedir bekliyorum Onlar beni on bir sene bekler miy...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beklemek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Dostu 2', 'allah-dostu-2-necip-fazil-kisakurek-zy7fn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allah dostu odur ki, nefsine tek pay biçmez; 

Kırk yıl bir ekşi ayran özler de onu içmez.', 'Allah dostu odur ki, nefsine tek pay biçmez;  Kırk yıl bir ekşi ayran özler de onu içmez....', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/allah-dostu-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atlar', 'atlar-tacettin-simsek-4kd5d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Atlar bilirim

soylu kanatlar bilirim

Atlarla bir örnek

ne hayatlar bilirim

Atlar bilirim

kuş gibi

atlar bilirim düş

Rüzgârları kıskandıran atlar bilirim', 'Atlar bilirim soylu kanatlar bilirim Atlarla bir örnek ne hayatlar bilirim Atlar bilirim kuş gibi atlar bilirim düş Rüzgârları kıskandıran a...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/atlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalan', 'kalan-nil-duman-q5i23', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birşey kaldı gecelerden birinde

senden

Öncesinde bilinmemiş bişey,

Silinmez bir ses gibi giden..

Kelimelerden büyük kelimelerin içinde,

Birşey kaldı senden

Yaşamalar'' ın arasında kaçamaklı.

Veriliş rengi başka,alınış rengi başka..

Söylemeye vakit kalmadan 

Dudakların altına bırakılmış bişey.

Karanlıkların tam ortasında kırmızı bir nokta..

Gözlerce pırıl pırıl ellerce saklı.

Birşey kaldı bir denizin kıyısında senden,

Bakışlarla yüklü,söylemelerle sessiz...

Seninle dolu,seninle sensiz bir şey..

Aradıkca bulunmamış yıllar yılı,

Bulundukca aramaklı.', 'Birşey kaldı gecelerden birinde senden Öncesinde bilinmemiş bişey, Silinmez bir ses gibi giden.. Kelimelerden büyük kelimelerin içinde, Birş...', ARRAY['Türk Edebiyatı','Şiir','Nil Duman']::text[], 8.5, '{"poet":"Nil Duman","poet_slug":"nil-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hilal Sancağında Bozkurt Töresi', 'hilal-sancaginda-bozkurt-toresi-asik-sefai-higoq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehâdet ile düşerken minareler toprağa, 

Tekbir ile omuz verip kaldırdık gökyüzüne birer birer. 

Ne yardan geçtik, ne serden geçtik. 

Törede ne varsa inandık hak ölçülerine, 

Vurduk kıstasa kırdık zincirleri 

Cuma gecelerinin Yasin''leriyle sohbet eyledik. 

Gidenlerin, şehitlerin ardından. 

Ağladık düşmana göstermeden 

Kayaların yosun tutan taraflarında, 

Hıçkırıklarımızı rüzgara vermedik ki 

Yadeller, namerdler duyup da sevinmesin diye. 

Bir gün pusatlandık sevda mavzerini 

Yaşayamadık, sevdalarımızdan vazgeçtik. 

Doyasıya seyredemedik yarin hilâl kaşını, 

Gözlerine bakmaktan çekindik belki de. 

Lakin zifiri zindan odalarda karanlığı yaşarken, 

Ak kılı çekip aldık, ak sütün içinden. 

Derdimizi açtık kara gecelere, nemli duvarlara, 

Ak duvarlara anlattık derdimizi 

Garibim duvarlar öyle dinlediler bizi. 

Niye sustular onu da bilemedik. 

Sonra döndük kara gecelere , ak duvarlara 

Üzüldük derdimizle üzüldü diye. 

Bir gün bir seher vaktinde, 

“Es-selatü hayrün min’en nevm” derken ezanlar” 

Sevdaların kutsaliyetine el kaldırdık. 

Af diledik âlemlerin Rabbinden. 

Minberlerde dinledik, sevdaların en yücesini. 

Cami duvarlarında satıldık, 

Ucuzlar, soysuzlar tarafından 

Hilâl gecelerinin töreleriyle avunduk her zaman. 

Destur alırken Hoca Ahmet Yesevî’den, 

Alparslan’a Sarı Saltuk, Kayı’dan Osman Gazi, 

Şeyh Edebali, Fatih Sultan Mehmed Han Hazretlerine, 

Akşemseddin’in kutsaliyetini düşünüp durduk her zaman. 

Âleme nizam dedik, yaren tuttuk kendimize, 

Niceleri yol dostu olmuş bize, 

Sonra yine biz kaldık bu Allah’ın davasında, 

Bu imân davasında, bu vatan, bu bayrak davasında, 

Sonra yine biz kaldık sevdiklerimizle beraber. 

Senelerce dert sofrasından bal yedik ekmeksiz. 

Eğilmedik, kırıldık defalarca, 

Allah’ın davasıdır dedik ve diyet istemedik. 

Erkekçe öldük, yiğitçesine öldük, 

İpe giderken satmadık sevdiklerimizi 

Kaldırdık Hilâl Sancağını, yaşadık Bozkurt Töresini', 'Şehâdet ile düşerken minareler toprağa,  Tekbir ile omuz verip kaldırdık gökyüzüne birer birer.  Ne yardan geçtik, ne serden geçtik.  Törede...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/hilal-sancaginda-bozkurt-toresi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlüm', 'deli-gonlum-harun-kesik-hfp1v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geze geze dolaştım ben dünyayı

Kalan bir sevgim vardı yoksa rüyamı

Çeke çeke çeke ben bir sevdayı

Uslanmaz deli gönlüm bir deryamı', 'Geze geze dolaştım ben dünyayı Kalan bir sevgim vardı yoksa rüyamı Çeke çeke çeke ben bir sevdayı Uslanmaz deli gönlüm bir deryamı...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/deli-gonlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Defterim''den', 'gonul-defterim-den-harun-kesik-s4nad', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geze geze dolaştım ben dünyayı

Kalan bir sevgim vardı yoksa rüyamı

Çeke çeke çeke ben bir sevdayı

Uslanmaz deli gönlüm bir deryamı

Söyleyemem ben sevdiğimi sunayı

Nerelerde şimdi o sonbahar ayı

Çektiysek çektiysek serseri belayı

Katlanırız bu yazgıya doya doya

Arsızım arsızım ben bir vicdansızım

Tek hedefim sevmekti ben zararsızım

Bilirim ben seni sen kalp hırsızısın 

Bilirim bilirim ben seni sen aşıksın', 'Geze geze dolaştım ben dünyayı Kalan bir sevgim vardı yoksa rüyamı Çeke çeke çeke ben bir sevdayı Uslanmaz deli gönlüm bir deryamı Söyleyeme...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-defterim-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Haberi', 'olum-haberi-i-brahim-akca-aot83', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'D.''in aziz ruhuna Fatihalarla

Kim benden iyi bilir bu ölüm haberlerini

Aniden gelirler böyle ölüm gibi

Teklifsiz bir dostdurlar sanki

Feryat, hıçkırıklar, ağlamalar

Niyeydi nasıldı derken geçer günler

Ne ölümün yakınlığıyla verilen takva sözleri kalır

Ne içinde yüzülen elem ve hüzünler

Herşey unutulur yine

Eskisi gibi devam eder hayat 

Gözyaşlarına ve ölüme inat

Bilinmez

Ama Sünnetullahtır değişmez

Bazen erken tecelli eder ism-i rahim 

Tamam denilir anlaşıldı senin bu imtihanı vereceğin

Terkedebilirsin şu mihnethaneyi

Ve duyulur felah cümlesi

‚Udhuli fi cenneti’*

Burada bizler ardından ağlarken

Bizler yaşayan ölüler

Onlar orada güler 

Onlar yaşamayan ölümsüzler

Yüzleri nur saçar, gözleri nur devşirir

Ellerinden tutarlar doğmamış çocuklarının

Gezdirirler onları emsalsiz bahçelerde, cennet saraylarında

Sevinçlidir gözler, mutmain yürekler

İki parmak misali Resul’e komşu, Resul’le beraber

Köln, Saat:1.20/Pazar/13.5.01

(*Ayet: ‚Sen kadın/müennes kişi, gir cennetime’)', 'D.''in aziz ruhuna Fatihalarla Kim benden iyi bilir bu ölüm haberlerini Aniden gelirler böyle ölüm gibi Teklifsiz bir dostdurlar sanki Feryat...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Akça']::text[], 8.5, '{"poet":"İbrahim Akça","poet_slug":"i-brahim-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/olum-haberi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-harun-kesik-fec0g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçme burdan yalnız sandal

Hüzün dolu insanlar

Geç geç geçme bizim sokaktan 

Hasret dolu uçan kuşlarrrr 

Çekip giden vefasızlar

Hasret çeken sılasızlar

Ölüp giden günahsızlar 

Haydi sılayaaaa', 'Geçme burdan yalnız sandal Hüzün dolu insanlar Geç geç geçme bizim sokaktan  Hasret dolu uçan kuşlarrrr  Çekip giden vefasızlar Hasret çeken...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlik-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hedef', 'hedef-abdurrahim-karakoc-1t66p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '- Oğlum Türk-İslâm ile Enderhan''a -

Çıktık Ötüken''den günün birinde,

Yıkandık Mekke''nin tevhid nurunda.

Hem dünde, bugünde, hemi yarında

İslâmlık Miraçtır, Ülkü sancaktır

Bu mübarek yoldan dönen alçaktır.

Yürüdük ''Nizam-ı Âlem'' uğruna

Doğduk güneş gibi küfrün bağrına

Batılın elleri düştü böğrüne

İslâmlık rahmettir, Ülkü sancaktır

Bu mübarek yoldan dönen alçaktır.

Hep karaya kara, aka ak dedik

Korkaktan, millete fayda yok dedik

Hayat mücadele, ölüm hak dedik

İslâmlık cihaddır, Ülkü sancaktır

Bu mübarek yoldan dönen alçaktır.

Biz dava uğruna serden geçmişiz

Anadan, babadan, yârdan geçmişiz

İman denizine yelken açmışız

İslâmlık hedeftir, Ülkü sancaktır

Bu mübarek yoldan dönen alçaktır.

Engeller yıldırmaz Müslüman Türk''ü

Şüphesiz, inandık; söz verdik çünkü...

Kıyamete kadar yaşar bu ülkü! 

İslâmlık sevdadır, Ülkü sancaktır

Bu mübarek yoldan dönen alçaktır.

(Kan Yazısı)', '- Oğlum Türk-İslâm ile Enderhan''a - Çıktık Ötüken''den günün birinde, Yıkandık Mekke''nin tevhid nurunda. Hem dünde, bugünde, hemi yarında İsl...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hedef-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan Şiir', 'aglayan-siir-harun-kesik-jpnmw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul da gezen yalnız martı

Tüter bizim bacanın dumanı,hasreti

Memleketimin her köşesine gider mi ?

Alır mı haberimi uçan telli turna 

Haykırsam ulaşırmı sesim sılaya ?

İstanbul dan taa Sakarya  ya

Söyler mi sevdiğini dağlar ?

Usulca bizim oralı Memmet Ağa''ya

Düşünsem hisseder mi kuzular ?

Söyler mi öleceğim zamanı azrailim

Bazan ağlar mı bulutlarda yalnızken ?

Söyler mi derdini martılara 

Hiç durur mu dereler şelaler sebepsiz

Hiç olur mu bir çocuk annesiz

Deniz de dalga bitmez 

Kesik Harun da dert', 'İstanbul da gezen yalnız martı Tüter bizim bacanın dumanı,hasreti Memleketimin her köşesine gider mi ? Alır mı haberimi uçan telli turna  Ha...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglayan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Göre', 'bize-gore-abdurrahim-karakoc-g6f1x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beşyüz itten kaçan kurda

Kurt diyenler halt eylemiş.

Şehit verilmeyen yurda

Yurt diyenler halteylemiş.

Birlik ister bizden olan

Kör olsun milleti bölen

Siyasette yalan-dolan

Şart diyenler halteylemiş.

Yazıklar olsun ismine

Gider yan verir hasmına

Vatandaşın bir kısmına 

Kürt diyenler halteylemiş.

Ülkü bizim baş tacımız; 

Şeker, bal olur acımız.

Çilemizdir ilacımız

Dert diyenler halteylemiş.

Hamdolsun alnımız aktır; 

Zalimden korkumuz yoktur

Hakikatin yönü tektir

Dört diyenler halteylemiş

Danışsınlar canlarına

Kalmayacak yanlarına

Marksizmin hayranlarına

Mert diyenler halteylemiş.

Rahmet yağar ilik ilik

Aşk suyunu içer çelik

Ön niyettir ülkücülük

Art diyenler halteylemiş.

(Kan Yazısı)', 'Beşyüz itten kaçan kurda Kurt diyenler halt eylemiş. Şehit verilmeyen yurda Yurt diyenler halteylemiş. Birlik ister bizden olan Kör olsun mi...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bize-gore-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebeb-i Aşk', 'sebeb-i-ask-i-sa-seker-ihwzh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gece yarısı dinlerken bilmem ney sesi

Aylardan hazirandı ,günlerden   pazartesi

Yine tüllendi  ufkumda  hayaller  prensesi

Şu ruhumu okşayan  bilmem ki onun nesi

Gözleri  bendeydi ve dudağı  mütebessim

Bu muydu hep hayallerimi süsleyen resim?

Sular  dindi  ve  artık   fırtına   oldu   nesim

Endişeliyim  birgün bitecek diye hevesim

Sorma sakın ''nedendir bana bu ah-u zarın''

Korkuyorum diline  düşmekten şu ağyârın

Kalpler tatmin olacak mı? bilsem ah yarın

Ey  aşkı  yaratan!  menbaı  sensin pınarın', 'Bir gece yarısı dinlerken bilmem ney sesi Aylardan hazirandı ,günlerden   pazartesi Yine tüllendi  ufkumda  hayaller  prensesi Şu ruhumu okş...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sebeb-i-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meydan', 'meydan-niyazi-yildirim-gencosmanoglu-tav5j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu yeryüzü er meydanı

Gönül sevmez her meydanı

Yüreksize yorgan döşek,

Koç yiğite ver meydanı.

Başbuğlar tuğ kaldıranda,

Atlar dizgin dolduranda,

Malazgirt''te, Çaldıran''da

Sakarya''da gör meydanı.

Kaytan bıyık bura bura

Gakkoş, Dadaş sıra sıra

Elaziz''de Çay''da Çıra,

Erzurum''da bar meydanı.

Ey içi boş, dışı süslü! 

Eli kirli, yüzü paslı! 

Yetişsin Asım''ın nesli

Etsin sana dar meydanı! 

Geldiği gün kutlu çağrı

Bas, titresin yerin bağrı.

Doğu''dan batıya doğru

Bir yay gibi ger meydanı.

Ben Türk''üm! De, dur sözünde,

Yürü Bozkurt''un izinde

Kalmasın şu yer yüzünde

Şerirlere şer meydanı.

Tanrı Kut Mete Çağı''ndan,

Son Peygamber kucağından,

Hacı Bektaş ocağından,

Açık bize sır meydanı.

Hayaller kalınca güdük

Açıldı surlarda gedik...

Mehter sustu, öttü düdük,

Rezil oldu er meydanı! 

Yer yüzünde kalsan da tek

Eğme boyun, öpme etek! 

Çin seddinden, Nemçe''ye dek

Yeni baştan sar meydanı.

Bak neler var dünlerinde

Acı, tatlı günlerinde...

Dumlupınar önlerinde

Mehmetçik''ten sor meydanı.

Sancaklar kalmasın aysız,

Boz Oklar Üç Oklar yaysız

Soyunu bilmeyen soysuz

Düşmanına kor meydanı.

Ayrılık can paresidir,

Sıla, gurbet çaresidir,

Ahi Evran töresidir.

Yarenlerle yar meydanı.

Dön ardına bir bak hele

Hatırına neler gele...

Dar boğazda Çanakkale,

Tarihin en zor meydanı! 

Git danış büyük ceddine,

Sor doğuda Çin seddine,

Girmek kimlerin haddine

Sen açmazsan bir meydanı! 

Çabuk söner şişirdiğin

Soya çeker devşirdiğin...

Kırk Bismillahla girdiğin

Meydan, şimdi kir meydanı.

İtibar olmazsa ere

Düşmana kim göğüs gere? 

Kör döğüşü olan yere

Derler elbet kör meydanı! 

Uyanınca Türk''ün özü,

Gerçekleşir Tanrı sözü...

Olur bir gun şu yer yüzü,

İnsanlığın hür meydanı!', 'Şu yeryüzü er meydanı Gönül sevmez her meydanı Yüreksize yorgan döşek, Koç yiğite ver meydanı. Başbuğlar tuğ kaldıranda, Atlar dizgin doldur...', ARRAY['Türk Edebiyatı','Şiir','Niyazi Yıldırım Gençosmanoğlu']::text[], 8.5, '{"poet":"Niyazi Yıldırım Gençosmanoğlu","poet_slug":"niyazi-yildirim-gencosmanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/meydan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-niyazi-yildirim-gencosmanoglu-gw1tf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Burada baş sağlığı, orada gözler aydın;

Íki ayrı dünyada iki ayrı tören var.

TANRI katından gelen bir yüce buyruk üzre, 

Aramızdan ansızın çadırını deren var. 

Orada ecdat ruhu sadümanlık içinde 

Burada tamu içre gönüllerde boran var.

Eksilmiş bir yanımız; çarpılmış gibiyiz hep

TANRI korusun sanki, Bozkurtluğa kıran var. 

Yukardan gök mü bastı; altta yer mi çöktü ne?

Kimsede ağız dil yok; gözleriyle soran var.

Buradan uğurlarken onu binlerce Bozkurt

Orada karşılayan binlerce Alp-Erenler var.

O gün Tanrıdağı''nda tan ağardığı çağda, 

Dediler Oğuz Han''ın otağına giren var.

Töredir; konan göçer, doğan gün batar elbet

Tanrı zeval vermesin; devlet, din ve KUR''AN var.', 'Burada baş sağlığı, orada gözler aydın; Íki ayrı dünyada iki ayrı tören var. TANRI katından gelen bir yüce buyruk üzre,  Aramızdan ansızın ç...', ARRAY['Türk Edebiyatı','Şiir','Niyazi Yıldırım Gençosmanoğlu']::text[], 8.5, '{"poet":"Niyazi Yıldırım Gençosmanoğlu","poet_slug":"niyazi-yildirim-gencosmanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ardindan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Malazgirt Marşı', 'malazgirt-marsi-niyazi-yildirim-gencosmanoglu-iycm8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aylardan Ağustos, günlerden Cuma 

Gün doğmadan evvel iklîm-i Rum''a 

Bozkurtlar ordusu geçti hücuma 

Yeni bir şevk ile gürledi gökler 

Ya Allah...Bismillah... Allahuekber 

Önde yalın kılıç Türkmen Başbuğu 

Ardında Oğuz''un ellibin tuğu 

Andırır Altay''dan kopan bir çığı 

Budur, Peygamberin övdüğü Türkler... 

Ya Allah...Bismillah... Allahuekber 

Türk, Ulu Tanrı''nın soylu gözdesi 

Malazgirt Bizans''ın Türk''e secdesi 

Bu ses insanlığa Hakk''ın müjdesi 

Bu seste birleşir bütün yürekler... 

Ya Allah...Bismillah... Allahuekber!.. 

Nağramızdır bu gün gök gürültüsü, 

Kanımızdır bugün yerin örtüsü 

Gazi atlarımın nal parıltısı 

Kılıçlarımızdır çakan şimşekler... 

Ya Allah...Bismillah... Allahuekber!.. 

Yiğitler kan döker, bayrak solmaya, 

Anadolu başlar, vatan olmaya... 

Kızılelma''ya hey... Kızılelma''ya!!! 

En güzel marşını vurmadan mehter 

Ya Allah...Bismillah... Allahuekber', 'Aylardan Ağustos, günlerden Cuma  Gün doğmadan evvel iklîm-i Rum''a  Bozkurtlar ordusu geçti hücuma  Yeni bir şevk ile gürledi gökler  Ya All...', ARRAY['Türk Edebiyatı','Şiir','Niyazi Yıldırım Gençosmanoğlu']::text[], 8.5, '{"poet":"Niyazi Yıldırım Gençosmanoğlu","poet_slug":"niyazi-yildirim-gencosmanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/malazgirt-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Bir Gece', 'yine-bir-gece-akin-kir-7l3yk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşye yine bir gece

Ve ben yine ağlıyorum.

Ama bu sefer seni düşünerek...

Biliyorum ki oradasın,

Biliyorum ki sen de benim gibisin,

Benim düşündüklerimi düşünüyorsun.

En önemlisi, sen de beni seviyorsun.

Ağlıyorum çünkü mutluyum,

Çünkü seni hissediyorum yanımda.

Benimle oturmuş, aynı güneşi bekliyorsun.

Aynı gecedeyiz, aynı karanlıktayız.

Karanlığı bozacak güneşin peşindeyiz.

Güneşin sıcaklığı dolacak içimize,

İçimizdeki aşkı daha da yakacak.

Daha çok seveceğim seni

Ve bileceğim ki sen de beni daha çok seviyorsun', 'İşye yine bir gece Ve ben yine ağlıyorum. Ama bu sefer seni düşünerek... Biliyorum ki oradasın, Biliyorum ki sen de benim gibisin, Benim düş...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mamak''ta', 'mamak-ta-niyazi-yildirim-gencosmanoglu-6j0on', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oğullar işkencede... Analar ağlamakta.

Körpe yüreklere kan...

Gencecik rüyâlara gözyaşı damlamakta.

Demokrasi... Hak... Hukuk... karasevdâlıları...

Şuracıkta.. Mamak''ta

Vicdanları çürüten feryâdı duymamakta.

Demek bazılarının hak, hukuk anlayışı

Bazılarını insan yerine koymamakta! ..

Meğer ne faziletler varmış ta bilmezmişiz

Millî mukaddesatâ saygılı olmamakta (!) 

Vatan hainlerinin bile doldu çilesi; 

Vatanı sevenlerin çilesi dolmamakta...', 'Oğullar işkencede... Analar ağlamakta. Körpe yüreklere kan... Gencecik rüyâlara gözyaşı damlamakta. Demokrasi... Hak... Hukuk... karasevdâlı...', ARRAY['Türk Edebiyatı','Şiir','Niyazi Yıldırım Gençosmanoğlu']::text[], 8.5, '{"poet":"Niyazi Yıldırım Gençosmanoğlu","poet_slug":"niyazi-yildirim-gencosmanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mamak-ta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altın Destan', 'altin-destan-ziya-gokalp-s3y7k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I

Sürüden koyunlar hep takım takım

Ayrılmış, sürüde kalmamış bakım; 

Asmanın üzümü dağılmış; salkım

Olmak ister, fakat bağban nerede? 

Gideyim, arayım: çoban nerede? 

II

Yüce dağlar çökmüş, belleri kalmış,

Coşkun ırmakların selleri kalmış,

Hanlar yok meydanda, illeri kalmış,

Düşenler çok ama, kalkan nerede? 

Gideyim arayım: Hakan nerede? 

III

Türk yurdu uykuda ey düşman sakın! 

Uyuyan ülkeye yapılmaz akın.

Tan yeri ağardı, yiğitler kalkın.

Bakın yurd ne halde, vatan nerede? 

Gideyim arayım: yatan nerede? 

IV

Herkesin gözünde vatan öz yurdu,

Çitlerin yağısı, derenin kurdu,

Yad iller, Turan''da hanlıklar kurdu,

Turan''dan yadları koğan nerede? 

Gideyim arayım: ogan nerede?', 'I Sürüden koyunlar hep takım takım Ayrılmış, sürüde kalmamış bakım;  Asmanın üzümü dağılmış; salkım Olmak ister, fakat bağban nerede?  Gidey...', ARRAY['Türk Edebiyatı','Şiir','Ziya Gökalp']::text[], 8.5, '{"poet":"Ziya Gökalp","poet_slug":"ziya-gokalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/altin-destan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-akin-kir-s2rrw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin ayazı vurduğumda bedenime, 

Tek bir isteğim olur Allah''tan.

Yanımda olmanı dilerim.

Ama gelemezsin.

Ben de hayal ederim seni.

Hayaline sarılırım sıkı sıkı, 

Isındığımı hissederim.

Daha sıkı sarılırım.

Benimserim hayalini, 

Sabaha kadar bırakmam.

Sonra uyanma vakti gelir.

Gözlerimi açtığımda, 

Seni görürüm karşımda.

Bu sefer sana sarılırım

Ve seni daha çok hissederim.

Kulağına bir söz fısıldarım, 

''Seni seviyorum'' derim.', 'Gecenin ayazı vurduğumda bedenime,  Tek bir isteğim olur Allah''tan. Yanımda olmanı dilerim. Ama gelemezsin. Ben de hayal ederim seni. Hayali...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayal-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Hiçbir Yagmur Islatamaz Beni', 'artik-hicbir-yagmur-islatamaz-beni-emre-ozdamar-dmp8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kelimeler  yetmiyor

Suskun bakışlarından süzülen

bir akşam üstü oluyor heryer

Bir yerlerim yanıyor ve

sen yoksun

Gözlerin yok ve

artık hiçbir yagmur ıslatamaz beni

Şimdi solgun

bir sonbaharı kuşanıyor mevsimler

Ben hasreti kuşanıyorum

Damla damla birşeyler çoğalıyor içimde

kelimeler yetmiyor

konuşamıyorum

Ve sen sevgili sen

yüzünde sonsuz bir gülümsemeyle

ellerinde kır çiçekleri kelebekler

geçiyorsun  ruhumun ıssız yerlerinden

vuruyorsun   kıyılarıma

dalga dalga

savuruyorsun küllerimi', 'Kelimeler  yetmiyor Suskun bakışlarından süzülen bir akşam üstü oluyor heryer Bir yerlerim yanıyor ve sen yoksun Gözlerin yok ve artık hiçbi...', ARRAY['Türk Edebiyatı','Şiir','Emre Özdamar']::text[], 8.5, '{"poet":"Emre Özdamar","poet_slug":"emre-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/artik-hicbir-yagmur-islatamaz-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Göreceksin', 'ne-goreceksin-akin-kir-ildp2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günler, aylar, yıllar geçecek,

Bir an gözlerin dolacak

Ve durup geçmişi düşüneceksin.

Peki ne göreceksin orada?

Güzel günlerin yaşandığı,

Hoş bir anı mı?

Yoksa,

Sonsuza doğru ilerleyen bir aşkın,

Acemi heyecanlarına sahip

O, ilk günler mi?', 'Günler, aylar, yıllar geçecek, Bir an gözlerin dolacak Ve durup geçmişi düşüneceksin. Peki ne göreceksin orada? Güzel günlerin yaşandığı, Ho...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-goreceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinipte Söylenemeyen', 'bilinipte-soylenemeyen-emre-ozdamar-lbep1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'derin olan birşey var

hayatımda

içinde boğulup çıkamadığım

kimselere anlatamadığım

saklı olan bir yanı var

görüntülerin

göze gelmeyen

bilinipte söylenemeyen

ağlayan bir yaı var

gündüzün

yıldızları bekleyen

ve geceye sezdirmeden

karanlığı besleyen

titreyen bakışları var

yıldızların

yüreğime dokunan

sönseler bile

unutulmayan', 'derin olan birşey var hayatımda içinde boğulup çıkamadığım kimselere anlatamadığım saklı olan bir yanı var görüntülerin göze gelmeyen bilini...', ARRAY['Türk Edebiyatı','Şiir','Emre Özdamar']::text[], 8.5, '{"poet":"Emre Özdamar","poet_slug":"emre-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bilinipte-soylenemeyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosunlu Gözlerindir Yıldırımlar Düşüren Tan yerine.', 'yosunlu-gozlerindir-yildirimlar-dusuren-tan-yerine-sair-zehre-tt1df', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ruhum mahkumudur yosunlu gözlerinin.

Bürünürken gecenin siyah kefenine.

Yemyeşil şimşekler boşalır üzerime.

Sen bir kuşun kanadında düş gibi.

Devasa sevdalar büyütüp ikliminde.

İstila rüzgarı salıyorsun içime.

Tutuşturur hasretin alev alev kanımı.

İlkbaharlar örer çiçeklerden tacını.

Esrarlı ülkenin tahtında sultan olan

Mağrur bakıyorsun aynalardan yüzüme.

Yapayalnız kalmış öksüz çocuklar gibi.

Çaresizce uğruna dökülür gözyaşım.

Ve sinen..ebedi istiratgahıdır ölümsüz aşıkların.', 'Ruhum mahkumudur yosunlu gözlerinin. Bürünürken gecenin siyah kefenine. Yemyeşil şimşekler boşalır üzerime. Sen bir kuşun kanadında düş gibi...', ARRAY['Türk Edebiyatı','Şiir','Şair Zehre']::text[], 8.5, '{"poet":"Şair Zehre","poet_slug":"sair-zehre","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yosunlu-gozlerindir-yildirimlar-dusuren-tan-yerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbinde Hüzün', 'kalbinde-huzun-sair-zehre-hl7sf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbinden vurdu mu seni de hüzün.

Seninde bahçende üryan  mı güller.

Sensiz günler  bir bir sararıp solar.

En güzel çağımda karanlık düşler.

Mehtabı alıver omuzlarına

Umudu bağladım dudaklarına.

Ömrümün senli her bir anında.

Seninle yaşamak ve ölmek güzel', 'Kalbinden vurdu mu seni de hüzün. Seninde bahçende üryan  mı güller. Sensiz günler  bir bir sararıp solar. En güzel çağımda karanlık düşler....', ARRAY['Türk Edebiyatı','Şiir','Şair Zehre']::text[], 8.5, '{"poet":"Şair Zehre","poet_slug":"sair-zehre","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalbinde-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarımda Bulut', 'saclarimda-bulut-sair-zehre-g2vaq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üzerime çöker sis,saçlarıma düşer bulut

Hani büyülü zaman ,yüreğinde saklar umut

Ben ki dağları aşıp rüzgarla yarışacaktım

Hani binip dalgalara,ummana karışacaktım

Ben bir ebedi aşık yeryüzü cehenneminde

Sürurum dudaklarında,cennetim ellerinde

Söyle hatırında mı hüzünlü gözlerim

Her gece sessizce iner düşlerime suretin

Rüyadır bütün çektiğim,yalnızlığın kalbinde

Bilirim teselli yok,bu kapkara sensizlikte

Hasretinle geçirdiğim her bir anım intihar

Şimdi yalnız kederi terennüm ediyor bahar...', 'Üzerime çöker sis,saçlarıma düşer bulut Hani büyülü zaman ,yüreğinde saklar umut Ben ki dağları aşıp rüzgarla yarışacaktım Hani binip dalgal...', ARRAY['Türk Edebiyatı','Şiir','Şair Zehre']::text[], 8.5, '{"poet":"Şair Zehre","poet_slug":"sair-zehre","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saclarimda-bulut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda Üşürüm', 'yoklugunda-usurum-sair-zehre-bl04f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zerrin    pırıltılı    yağmurlar yağar  şimdi 

sağanak  sağanak . 

 üzerime

imbat eser  kordon boyu

eylül   ikindilerinde

ve yokluğun

sedef bir hançer  göğsüme

saplanan

bakamam  aynalara

ölürüm

varlığında.

nasıl yandıysam sana

yokluğunda ..

üşürüm...', 'Zerrin    pırıltılı    yağmurlar yağar  şimdi  sağanak  sağanak .   üzerime imbat eser  kordon boyu eylül   ikindilerinde ve yokluğun sedef ...', ARRAY['Türk Edebiyatı','Şiir','Şair Zehre']::text[], 8.5, '{"poet":"Şair Zehre","poet_slug":"sair-zehre","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yoklugunda-usurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu Gezisi', 'anadolu-gezisi-abdurrahim-karakoc-0hv55', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ter kokuyordu Çukurova tarlaları, 

Irgat Türküleri duyuluyordu uzaktan; 

Ekin biçiyordu yalın ayaklı köy kızları 

Elleri kabarıyordu oraktan. 

   Gökbelen dağlarına yağmur yağıyordu;                                 

   Yetimler mahallesinde bir çocuk ağlıyordu. 

Kan kokuyordu doğunun çimenli yaylaları; 

Silah sesleri geliyordu Şırnak''tan. 

Oğulsuz koymuşlardı ak saçlı anaları; 

Tütünler tedirgin olmuştu ocaktan. 

   Cilo dağlarında kamalaklar üşüyordu;                                   

   Garipler köyünde bir gelin düşünüyordu.

Yosun kokuyordu Karadeniz''in mavnaları; 

Oynak havalar döküyordu parmaktan. 

Buz gibi bir soğuk  biçiyordu baharı; 

Dal boylu gençler gidiyordu bıçaktan. 

   Ilgaz dağlarında kurtlar uluyordu. 

   Bekârlar kahvesinde bir adam uyuyordu. 

Şehvet kokuyordu Ege''nin bereketli ovaları; 

Körpe bedenler soyuluyordu ahlâktan. 

Tedirgin etmişlerdi bizim havaları; 

Yadırgı sesler geliyor plâktan. 

   Çatalkaya dağında kartallar dönüyordu; 

   Bir nesil yaşıyor, bir tarih ölüyordu.

Vur Emri', 'Ter kokuyordu Çukurova tarlaları,  Irgat Türküleri duyuluyordu uzaktan;  Ekin biçiyordu yalın ayaklı köy kızları  Elleri kabarıyordu oraktan...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anadolu-gezisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlik', 'birlik-abdurrahim-karakoc-tmiyv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmeyen öğrensin, duymayan duysun! 

Kardeşiz, tek vücut, tek bir milletiz. 

Bölücü sapıklar aklına koysun 

Kardeşiz, tek vücut, tek bir milletiz. 

Dünün insan yiyen kanlı çarkı yok! 

Yüzlerde gam, gönüllerde korku yok... 

Çerkezi yok, Kürdü yoktur, Türkü yok... 

Kardeşiz, tek vücut, tek bir milletiz. 

Allah bir, vatan bir, bayrak bir beden 

Yanlış yola sapmayalım bilmeden! 

Doğu, batı diye ayirmak neden? 

Kardeşiz, tek vücut, tek bir milletiz. 

Yırtılıp atılmaz tarih sepete! 

Birlik olduk camide ve cephede; 

Kore''de, Kıbrıs''ta, Kocatepe''de 

Kardeşiz, tek vücut, tek bir milletiz. 

Nineler, dedeler, masum bebekler, 

Bizlerden Huzurlu Türkiye bekler; 

Tutuşsun el-ele kızlar erkekler: 

Kardeşiz, tek vücut, tek bir milletiz. 

Kalacak adımız, kaldığı gibi, 

Âleme velvele saldığı gibi 

Tıpkı Sakarya''da olduğu gibi 

Kardeşiz, tek vücut, tek bir milletiz. 

Ne zulmü severiz, ne kinimiz var! 

Hayrı emreyleyen hak dinimiz var; 

Dağlar, çağlar boyu yeminimiz var: 

Kardeşiz, tek vücut, tek bir milletiz.

(Suları Islatamadım)', 'Bilmeyen öğrensin, duymayan duysun!  Kardeşiz, tek vücut, tek bir milletiz.  Bölücü sapıklar aklına koysun  Kardeşiz, tek vücut, tek bir mil...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/birlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-abdurrahim-karakoc-f6lai', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çelik testereyle kestim suları

Yıkadım duvara astım suları..

   Düşümde düşüme girdim dün gece.

Buluta yaslandım ışığı tuttum.

Seni hatırladım, seni unutdum..

   Kendimi kendime sordum dün gece.

Topladım yolları eyledim yumak

Musalladan gayri görmedim durak...

   Durmadan düşünüp durdum dün gece.

Toprağı boyadım otlar ağladı

Oturdum kalkmadım atlar ağladı..

   Tuttum yorgunluğu yordum dün gece.

Dertler gecikince gidip yokladım

Yırtık bohçalarda umut sakladım..

   Kırgınlık bağını kırdım dün gece.

Şişelerde mahkûm çiçek kokusu

Yağdı yüreğime renk renk korkusu..

   Yok yere yokluğu vurdum dün gece.

Ay doğdu, gölgeler çöktü üstüme

Hicran alev alev aktı üstüme..

   Gözümü yollarda gördüm dün gece.

Aydınlığa koştum karanlık çıktı

Her sevgi, her vefa bir anlık çıktı..

   Güç-belâ ben bana vardım dün gece.

Dosta şiir yazdım ''hatıra'' dedim

Belki bir dost gele otura dedim..

   Gönlümü toprağa serdim dün gece

(Beşinci Mevsim)', 'Çelik testereyle kestim suları Yıkadım duvara astım suları..    Düşümde düşüme girdim dün gece. Buluta yaslandım ışığı tuttum. Seni hatırlad...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dun-gece-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köroğlu''na Mektup', 'koroglu-na-mektup-abdurrahim-karakoc-4v4tp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benden selâm olsun Koç Köroğlu’na

Şimdi devir başka, zaman değişti. 

Karga konar kır atların beline

Arpa bulunmuyor, saman değişti. 

Gayri ne Kenan var, ne Demircoğlu

Tarihe karıştı, Ayvaz’la Hoylu 

Herkes Bolu Beyi, her taraf Bolu

Yiğitlik kalmadı, insan değişti. 

Sır tutmuyor suya giden testiler

Kılınçları müzelere astılar

Çamlıbel’in çamlarını kestiler 

Dağlar çıplak kaldı, orman değişti. 

Kale yoktur, ok atılmaz burçlardan

İnsanoğlu yüksek uçar kuşlardan

Boz tavşanlar haraç alır kurtlardan

Erlik başkalaştı, meydan değişti. 

Ninnocular çadır kurdu düzlere

“Avare mu” sedef oldu sazlara

Benzerimiz hiç kalmadı sizlere

Caz müziği çıktı, makam değişti.

Kervan geçmez, uçurdular hanları

Hile satar asrın bezirgânları 

Banka kurup biriktirdik kanları 

Dertler yenilendi, derman değişti. 

Günden güne küçülüyor Arzımız

Şimdi ise Aya gitmek arzumuz

Feza elbisesi diker terzimiz

Gökleri fethettik, mekân değişti.

Tat bozuldu, küp kokutur turşular 

Haydutlara yatak oldu çarşılar 

Şişkin cüzdan bin belâyı karşılar 

Boynuzlar gürz oldu, kalkan değişti.

(Vur Emri)', 'Benden selâm olsun Koç Köroğlu’na Şimdi devir başka, zaman değişti.  Karga konar kır atların beline Arpa bulunmuyor, saman değişti.  Gayri n...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/koroglu-na-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-abdurrahim-karakoc-qdmza', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül tezgahında şiir dokudum

İplik iplik nakışında sen varsın.

Aşk yolunun kanununu okudum

Madde madde yokuşunda sen varsın.

Fikir vadisinden bir ırmak geçer

Eğilir serviler, suyundan içer

Bağrında ay doğar, zambaklar açar

Sessiz sessiz akışında sen varsın.

Öz suyusun hayat denen şişenin

Nedenisin keder ile neşenin

Sevda cephesinde şehit düşenin

Donuk donuk bakışında sen varsın.

Hep senin renginde görünür bahar

Yaprakta yeşilin, gülde kokun var

Yama yama kalbimdeki yaralar

Sıra sıra dikişinde sen varsın.

Gidip de yorulma çok uzaklara

Sen, ''sen''i gel benim içimde ara...

Umut güneşimin mor bulutlara

Girip girip çıkışında sen varsın.

(Dosta Doğru)', 'Gönül tezgahında şiir dokudum İplik iplik nakışında sen varsın. Aşk yolunun kanununu okudum Madde madde yokuşunda sen varsın. Fikir vadisind...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-varsin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın Ya Sen', 'sen-varsin-ya-sen-hayrettin-tarhan-wn9bs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen varsın ya sen;

Saçlarımda ak gözlerimde umutsun.

Bazen gökte bembeyaz bir bulutsun.

Sen varsın ya sen;       

Dudaklarımda bir şarkı, kulaklarımda yankısın.

Yağmur ile, üzerime çöken bir karanlıksın.

Sen varsın ya sen;

Avuçlarıma dolan bir mutluluk yumağısın.

Ellerimi açsam bir anda kaçar mısın?

Sen varsın ya sen;

Gözlerimde bir pınar, aktıkça akan... 

Kalbimde huzursun, coştukça coşan...

Sen varsın ya sen;

Rüzgârımsın, estikçe esen beni sürükleyen. 

Susamış aşka yüreğim bir umut bekliyorum senden. 

Sen varsın ya sen;

Çözemediğim bir bilmecesin beynimde.

Ama ben halâ, delicesine sevmede.

Çıktın karşıma neden böyle aniden

Seni mi bekledim acaba yıllarca neden?

Sen varsın işte bütün benliğimde sen. 

Ne olur unut deme, isteme bunu benden.', 'Sen varsın ya sen; Saçlarımda ak gözlerimde umutsun. Bazen gökte bembeyaz bir bulutsun. Sen varsın ya sen;        Dudaklarımda bir şarkı, ku...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-varsin-ya-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zayıfım Sanma', 'zayifim-sanma-abdurrahim-karakoc-avrco', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya Allah,deyince yedi zinciri

Kıracak güçtesin, zayıfım sanma.

Fikir koşusunda çok dingişleri

Yoracak güçtesin, zayıfım sanma.

İlmi azık eyle,sabırı silâh; 

Gittiğin Hak yoldur,yardımcın Allah; 

Kırk geceden sonra kırk milyon sabah

Görecek güçtesin, zayıfım sanma.

Sevda kelep kelep, kin deste deste; 

Eller tetikdedir, kulaklar seste; 

En uzak menzile iki nefeste

Varacak güçtesin, zayıfım sanma.

Günahkar ne orman, ne balta, ne sap; 

Akıl yor.. müşkülü halletmez âsap; 

Mazlumlar adına zalimden hesap

Soracak güçtesin, zayıfım sanma.

Kötülük beklenmez yiğitten, mertten

Milletim sizinle kurtulur dertten; 

Haini, zalimi mübarek yurttan

Sürecek güçtesin, zayıfım sanma.

Vaktiken çadır kuraşk diyarına; 

Her şeyin sahibi sensin yarına; 

Yumruğu TÜRKLÜĞÜN düşmanlarına

Vuracak güçtesin, zayıfım sanma.

(Kan Yazısı)', 'Ya Allah,deyince yedi zinciri Kıracak güçtesin, zayıfım sanma. Fikir koşusunda çok dingişleri Yoracak güçtesin, zayıfım sanma. İlmi azık eyl...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zayifim-sanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmak İstemiyorum', 'unutulmak-i-stemiyorum-hayrettin-tarhan-viwbr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok zor olsa da sevmen beni; unutma yeter ki.

Unutman şart olsa da unutulmak istemiyorum.

Yaşanmamıştır böyle bir aşk dünyada inan ki.

Unutman şart olsa da unutulmak istemiyorum.

Sus, söyleme, hatırlatma, ayrılığı bana ne olursun.

Ben sevmedim hiç; Sevemem senin gibi diyorsun.

Unutmam mümkün mü, nasıl sevdiğimi biliyorsun.

Unutman şart olsa da unutulmak istemiyorum.

Gün gelip de mahrum kalırsam hareli gözlerinden

Sen hiç bir şey hatırlamasan da aşk bestesinden

Unutmam, unutamam içsem de ayrılık badesinden

Unutman şart olsa da unutulmak istemiyorum.

Alın yazım bu benim; Bu kaderi ben yazmadım.

Sevdim gönülden ölesiye, hiç pişmanlık duymadım.

Kızgın çölde gördüğüm serabı gerçek sanmadım.

Unutman şart olsa da unutulmak istemiyorum.

Zor bir şey değil ki, bu istediğim senden.

Bundan sonra bir değil, bin gönüle de girsen, sen.

Hatırla, yinede beni bir tek pembe karanfilden

Unutman şart olsa da unutulmak istemiyorum.', 'Çok zor olsa da sevmen beni; unutma yeter ki. Unutman şart olsa da unutulmak istemiyorum. Yaşanmamıştır böyle bir aşk dünyada inan ki. Unutm...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutulmak-istemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güney İlleri', 'guney-i-lleri-abdurrahim-karakoc-7dmz7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gök mavi, dağlar ak, ovalar yeşil.. 

Dört mevsim bahardır güney illeri 

Çiğ düşmüş çiçekte gün ışıl ışıl.. 

Bir sarı, bir mordur güney illeri 

Yollar kıvrım kıvrım iner yokuştan

Köpüklü suları dökülür taştan 

Kuşları çiçekten, çiçeği kuştan 

Seçilmeyen yerdir güney illeri. 

Dağılır yaylanın boz dumanları 

Eğilir yıldızlar öper çamları 

Bir başka âlemdir yaz akşamları 

Cennet ile birdir güney illeri. 

Baharda haz duyar nar çiçeklenir 

Arı sesi çan sesine eklenir 

Tüm güzellik Toroslarda renklenir 

Oylum oylum kardır güney illeri. 

Motor sesleriyle uyanır sabah 

Kekik kokusuna boyanır sabah 

Özene-bezene yaratmış Allah, 

Ne geniş, ne dardır güney illeri. 

Ordadır ozanın gönül bolluğu 

Sevgi sıcak sıcak, aşk buğu buğu.. 

Gerçek yiğitlerin harman olduğu 

Eşsiz bir diyardır güney illeri.', 'Gök mavi, dağlar ak, ovalar yeşil..  Dört mevsim bahardır güney illeri  Çiğ düşmüş çiçekte gün ışıl ışıl..  Bir sarı, bir mordur güney iller...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guney-illeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SiTEMiM VAR', 'sitemim-var-omer-avsar-dggwg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu savasda hep benmi kahrolacagim

aci üstüne tütünmü basacagim

haykirmak isterken yine susacagim

yalanci dünya sana kanmayacagim

nice bayramlar yalniz geldi

gözyaslarim bana dostluk etti

içim kan aglarken yüzüm gülmedi

ömrümün yarisini çaldida gitti

sitemlerim sana degil yaratana

mutsuzluk yazmis alin yazima

heves kalmadi yarinlarima

biraktim kendimi dipsiz kuyularda', 'bu savasda hep benmi kahrolacagim aci üstüne tütünmü basacagim haykirmak isterken yine susacagim yalanci dünya sana kanmayacagim nice bayram...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sitemim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-abdurrahim-karakoc-38lhx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bunca yıldır bir hiçliğe 

Gittim, sana geliyorum...

Yeter artık döne döne

Bittim, sana geliyorum...

Durdum ve düşündüm demin

Baktım bu yol daha emin

Ayrılmamaya bin yemin

Ettim, sana geliyorum...

Gözüm yaşlı gönlüm garip

Yalvarayım dedim varıp

Benliği benden çıkarıp

Attım, sana geliyorum...

Aşk tokmağı değdi örse

Durmam gayrı dünya dursa

Dünden kalma neyim varsa

Sattım, sana geliyorum...

Bıraktım öfkeyi kini

Oldum bir rahmet ekini

Seni sevmenin zevkini

Tattım. sana geliyorum...

(Dosta Doğru)', 'Bunca yıldır bir hiçliğe  Gittim, sana geliyorum... Yeter artık döne döne Bittim, sana geliyorum... Durdum ve düşündüm demin Baktım bu yol d...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/donus-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğim', 'gelecegim-abdurrahim-karakoc-pejae', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar yirmi olsa da, otuz olsa da

Yollar kar, çamur olsa da, buz olsa da

Bedenim yorgun, aç ve susuz olsa da

Bir gün yalın ayak, terli gömlekle

- Gelirim, beni bekle

Belki yakında olur, belki de uzak

Sırtımda hatıralar, saçlarımda ak

Gün, tarih bilemiyorum amma, muhakkak

Bitmeyen bir azim, sabır ve emekle

- Gelirim, beni bekle

Unutmam mümkün değil, unutur sanma

''Gelmez'' diyen olursa sakın inanma

Umutlarını kaybetme ha zamanla

Geç kaldı diyerek gam çekme

- Gelirim, beni bekle

Sıcak bir yaz akşamında olabilir

Sarı bir güz akşamında olabilir

Kışın beyaz akşamında olabilir

Ellerimde bir top mavi çiçekle

- Gelirim, beni bekle

Cümle köprüleri sel alsa da tek, tek

Söz vermişim bir kere engel ne demek

Başı karlı, kara dağlardan geçerek

Azığım bir tas su, bir dürüm ekmekle

- Gelirim, beni bekle

Vermese de kaybolan gençliğimizi

Ayıran bir gün kavuşturacak bizi

Ve içimde sevgilerin en temizi

Seninle dolu, arı-duru bir yürekle

- Gelirim, beni bekle.

(Dosta Doğru)', 'Yıllar yirmi olsa da, otuz olsa da Yollar kar, çamur olsa da, buz olsa da Bedenim yorgun, aç ve susuz olsa da Bir gün yalın ayak, terli göml...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gelecegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genelge', 'genelge-abdurrahim-karakoc-e8afs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dar zamanda düşmanların altına

At olanlar safımıza gelmesin

Garibanın, fukaranın sırtına

Bit olanlar safımıza gelmesin

Ağırlık, irilik ölçüsün bırak

Tartıya vurulmaz beyinle, yürek

Bu ülkede iman gerek, ruh gerek

Et olanlar safımıza gelmesin.

Öte dursun işkembeden atanı

Lâzım değil kaçan ile yatanı

Menfaate rüşvet verip vatanı

Fit olanlar safımıza gelmesin

Sapıklar her yerde atsa da çamur

Gerçek mayasına kuvuştu hamur

Adam istiyoruz dört başı mamur

İt olanlar safımıza gelmesin.

Gönül bahçesinde korku gezeni

Asla kabul etmez ülkü düzeni

Sevdası, sabırı, aklı, izanı

Kıt olanlar safımıza gelmesin.

Biz zulüm ayında güneş çağıyız

Hira''dan feyzalan Tanrıdağ''ıyız

Biz meyve bahçesi, üzüm bağıyız

Ot olanlar safımıza gelmesin.

Parolamız her zamanda, her yerde:

Ölmek var da baş eğmek yok namerde

Bu imana, bu ülküye, bu derde

Yad olanlar safımıza gelmesin.

(Kan Yazısı)', 'Dar zamanda düşmanların altına At olanlar safımıza gelmesin Garibanın, fukaranın sırtına Bit olanlar safımıza gelmesin Ağırlık, irilik ölçüs...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/genelge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümdeki Gurbet', 'gonlumdeki-gurbet-abdurrahim-karakoc-8p2y8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dost ülkeler duman duman önümde

Dağların alnında gurbet yazılı.

Göv göcekler firez oldu gönlümde

Çamların dalında gurbet yazılı.

Ilgıt ılgıt yeller eser ovadan

Kuşlar hep tedirgin kalkar yuvadan

Özümüz gövünür yanık havadan

Sazların telinde gurbet yazılı.

Gene yanar oldu bağrımın başı

Nasıl söner bu sevginin ateşi? 

Oğuzlar soyunun savaş yoldaşı

Atların nalında gurbet yazılı.

Bin canım olsa da yurt için versem

Ufka nakış nakış kanımı sersem

Kalk gardaş sılaya gidelim desem

ÖTÜKEN yolunda gurbet yazılı.

Dosta Doğru', 'Dost ülkeler duman duman önümde Dağların alnında gurbet yazılı. Göv göcekler firez oldu gönlümde Çamların dalında gurbet yazılı. Ilgıt ılgıt...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonlumdeki-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farklı İnsanlar', 'farkli-i-nsanlar-omer-avsar-5dwkq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kimisi var olduguyla yetinen

kimisi var bu kadar yetmez diyen

kimisi var varligiyla kahreden

kimisi var etrafa güven veren

kimisi var geçmisi inkar eden

kimisi var gelecegi görmeyen

kimisi var sürekli böbürlenen

kimisi var sevgiyi hissetmeyen

kimisi var erdemi ilke edinen

kimisi var namusunu kirletmeyen

kimisi var çikari için ezmeyen

kimisi var bunlarla ilgilenmeyen

kimisi var canlilari hor gören

kimisi var dogayi incitmeyen

kimisi var sanatkar olabilen

kimisi var yetim hakkini yiyen

kimisi var akillanmayan

kimisi var dersler çikaran

kimisi var yazilanlardan olmayan

kimisi var hepsi benimdir sanan', 'kimisi var olduguyla yetinen kimisi var bu kadar yetmez diyen kimisi var varligiyla kahreden kimisi var etrafa güven veren kimisi var geçmis...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/farkli-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fetva', 'fetva-abdurrahim-karakoc-bnkxd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Türküler var başı belden aşağı

Çalmayan radyonun pili cennetlik.

Kâfir meyve inmez daldan aşağı

Yoksulun yaktığı çalı cennetlik.

Boşunadır dünyamıza geldiği

Aha yaşadığı, aha öldüğü...

Korkak müslümanın namaz kıldığı

Camiyi taşlayan deli cennetlik.

Kara günde çözülmesin kuşağın

Kara toprak olsun uyku döşeğin

Cihadda yük çeken uyuz eşeğin

Semeri cennetlik, çulu cennetlik.

Tez vururlar harpte önde gideni

Kaçanlar kurtarır canı, bedeni.

Şimdilik kördüğüm kalsın nedeni

Diri b... yedi, ölü cennetlik.

''Bana ne''yi akıllılık sananın

Başı var da, beyni yoktur; İnanın! 

Beş-on sene cehennemde yananın

Dumanı cennetlik, külü cennetlik.

''Karışma boşver''i eylemiş sanat

''Dava gereksiz'' der, ''herşey menfaat''

Böyle bir babayı vurursa evlat,

Tüfeği cennetlik, eli cennetlik.

Sevabı, günahı ayırmış Rabb''im

Ölçüdür gözlerim, tartıdır aklım

Yalana riyaya, dayanmaz sabrım

Haksıza sövenin dili cennetlik.

(Vur Emri)', 'Türküler var başı belden aşağı Çalmayan radyonun pili cennetlik. Kâfir meyve inmez daldan aşağı Yoksulun yaktığı çalı cennetlik. Boşunadır d...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/fetva-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinin Biri(sultanım)', 'i-kinin-biri-sultanim-abdurrahim-karakoc-3fzwq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Can özümden besmeleyi çekende

Dil yanmazsa ben yanarım sultanım.

Hak uğruna bir sefere çıkanda

Yol yanmazsa ben yanarım sultanım.

Arzuhâlim ulaşırsa divana

Korkarım ki taban değer tavana

Çiçeğimden zerre girse kovana

Bal yanmazsa ben yanarım sultanım.

Göz utanır gönül dostu görünce

Can tutuşur candan selâm verince

Bülbül olup bir bahçeye girince

Gül yanmazsa ben yanarım sultanım.

Aşıklık içimde doğduğu zaman

Taş yanar gözyaşım yağdığı zaman

Mızrabım sazıma değdiği zaman

Tel yanmazsa ben yanarım sultanım.

Üzülmedim erkenine geçine

Akıl yordum herşeyine, hiçine

Söküp yüreğimi atsam içine

Göl yanmazsa ben yanarım sultanım.

Alev alev ruhta, canda bu ateş

Bakmakla görülmez bende bu ateş

Bırakılsa hangi günde bu ateş

Yıl yanmazsa ben yanarım sultanım.

Dosta mektup yazma vakti gelirse

Yazar, postalarım kısmet olursa

Mektubumun mahiyetin bilirse

Pul yanmazsa ben yanarım sultanım.

(Dosta Doğru)', 'Can özümden besmeleyi çekende Dil yanmazsa ben yanarım sultanım. Hak uğruna bir sefere çıkanda Yol yanmazsa ben yanarım sultanım. Arzuhâlim ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sultanim-ikinin-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesit', 'kesit-abdurrahim-karakoc-hvvbe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim, yollarda serili kilim

Yüreğim, denizde bir garip balık

Yaralı kekliktir ağzımda dilim

Ben, kendi türkümü anlamam artık.

Dağa kaçmış ceylan güldeki koku

Şahin umutlarım inmez havadan...

En rahat yatakta uyumaz korku

Su doldurur, kan içerim kovadan.

Aydınlık, noktadır derin kuyuda

Sabahsız geceler ömrümü aşar...

Girse kuğularım boğulur suda

Çile bende doğar, dert bende yaşar.

(Dosta Doğru)', 'Gözlerim, yollarda serili kilim Yüreğim, denizde bir garip balık Yaralı kekliktir ağzımda dilim Ben, kendi türkümü anlamam artık. Dağa kaçmı...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kesit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milletvekili Marşı', 'milletvekili-marsi-abdurrahim-karakoc-z3zoc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sormayın kim olduğumu

Ben bilmem, liderim bilir

Varlığımı yokluğumu

Ben bilmem, liderim bilir...

Gözlerim hep ona bakar

Kaldır der, ellerim kalkar

Gül, menekşe nasıl kokar? 

Ben bilmem, liderim bilir...

Ne içip, ne yiyeceğim? 

Sırtıma ne giyeceğim? 

Nerede ne diyeceğim? 

Ben bilmem, liderim bilir...

İçimdeki riyaları

Süreceğim boyaları

Göreceğim rüyaları

Ben bilmem, liderim bilir...

Sıkı tutarım aramı

Ye derse, yerim haramı

Süt beyaz, kömür kara mı? 

Ben bilmem, liderim bilir...

Enim nasıl, boyum nasıl? 

Fikrim nasıl, huyum nasıl? 

Kullanacak oyum nasıl? 

Ben bilmem, liderim bilir...

Hasta mıyım, sıhhatta mı? 

Sadakatım ifratta mı? 

Otuz gün ay mı, hafta mı? 

Ben bilmem, liderim bilir...

Hicap nedir, örtü nedir? 

Kurt-kuş, böcek-börtü nedir? 

İyi nedir, kötü nedir? 

Ben bilmem, liderim bilir...

Hürmetim tamdır zatına

Minder olurum altına

Uyarım talimatına

Ben bilmem, liderim bilir...

Teslim ettim irademi

Böyle yürür benim gemi

Varsa beynimi, midemi

Ben bilmem, liderim bilir...

(Parmak İzi)', 'Sormayın kim olduğumu Ben bilmem, liderim bilir Varlığımı yokluğumu Ben bilmem, liderim bilir... Gözlerim hep ona bakar Kaldır der, ellerim ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/milletvekili-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemiler Hakkında', 'gemiler-hakkinda-omer-avsar-ye4fo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gemiler yanasiyor yavas yavas rihtima

bazilari açilmis gidiyor iz biraka biraka

ne bekliyor onlari sakin deniz yada firtina

ne olursa olsun allah yardimcilari ola

ben olsam SIKILIRDIM dört bir taraf derya

uzun bir yolculuk olacak belkide aylarca

firsat buldukça oturup düsünürler kara kara

sevdiklerinden uzak ne yapiyorlar acaba

iste yine yanasti gemi limana

bir telas geldi içindeki çalisanlara

yabanci sehir taninmadik insanlara

merhaba diyor gemi sessiz ve usulca

                      21.01.2000', 'gemiler yanasiyor yavas yavas rihtima bazilari açilmis gidiyor iz biraka biraka ne bekliyor onlari sakin deniz yada firtina ne olursa olsun ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gemiler-hakkinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöbetçinin Vukuatı', 'nobetcinin-vukuati-abdurrahim-karakoc-892fh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzbaşım, garajda nöbet tutarken

Hatırıma sıla düştü bu gece.

Güngören''in horozları öterken

Gönül kalktı yola düştü bu gece.

İçinde dışında yoktur yalanı

Anlatayım dur başıma geleni

Bir yâr için düşüncemin olanı

Sapanca''da göle düştü bu gece.

Bozhöyük''e vardım Güllü kadına

Fal açtırdım Ülker''imin adına

Gelin olmuş bak şu işin tadına

Bizim kısmet ele düştü bu gece.

Kırk yıl geçse unutamam bu günü

Olmuş bitmiş sevdiğimin düğünü

Hep çözülmüş sırrımızın düğümü 

Maceramız dile düştü bu gece.

Kalbime ateşten vurdular yama

Perişan bir hâlde döndüm kıtama

Karakoç bildiğin KARAKOÇ ama,

Bilmediğin hâle düştü bu gece.', 'Yüzbaşım, garajda nöbet tutarken Hatırıma sıla düştü bu gece. Güngören''in horozları öterken Gönül kalktı yola düştü bu gece. İçinde dışında ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nobetcinin-vukuati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Postacı', 'postaci-abdurrahim-karakoc-ock37', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eylen bir haber ver, acele gitme

Sevgilimden mektup var mı postacı? 

Yok deyip de beni perişan etme

Sevgilimden mektup var mı postacı? 

Tel çekmiştim giden ayın üçüne

Cevap gelmez korku düştü içime

Karıştır çantayı, bir bak içine

Sevgilimden mektup var mı postacı? 

Uykumu dağıtan korkulu düşler

Gün biter, her gece yeniden başlar

Bir ''evet'' dünyayı bana bağışlar

Sevgilimden mektup var mı postacı? 

Hiç haber çıkmadı geçti on pazar

Beklerim.. saatler yıl kara uzar

Zarfının üstünde KARAKOÇ yazar

Sevgilimden mektup var mı postacı? 

(Dosta Doğru)', 'Eylen bir haber ver, acele gitme Sevgilimden mektup var mı postacı?  Yok deyip de beni perişan etme Sevgilimden mektup var mı postacı?  Tel ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/postaci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sergi', 'sergi-abdurrahim-karakoc-609xy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zümrüt bahçe, altın saray

Girdim amma beğenmedim.

Ortasında elmas bir ay

Gördüm amma beğenmedim.

Hak diye döndüm yönümü

Boynuma taktım ölümü

İstediler ak gönlümü

Verdim amma beğenmedim.

Çile çektim sünnet diye

Kınadılar cinnet diye

Çağırdılar cennet diye

Vardım amma beğenmedim.

Kalbim tarla, sevgim başak

Tahammülü yaptım kuşak

Dost yoluna candan döşek

Serdim amma beğenmedim.

Beyde makam, beyde para

Garibanda türlü yara

İnsanlığı insanlara

Sordum amma beğenmedim

Başlar hep beyine muhtaç

Mideler dolu, gözler aç

Her çıbana üç-beş ilaç

Sürdüm amma beğenmedim.

Gelen olmadı çağrıma

Ellerim düştü böğrüme

Var gücümle öz bağrıma

Vurdum amma beğenmedim.

(Kan Yazısı)', 'Zümrüt bahçe, altın saray Girdim amma beğenmedim. Ortasında elmas bir ay Gördüm amma beğenmedim. Hak diye döndüm yönümü Boynuma taktım ölümü...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sergi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taksim', 'taksim-abdurrahim-karakoc-v5v34', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana Mevlana’yı, Yunus’u verin 

Mecnun’u, Leyla’yı size bıraktım. 

Kırk yıldır susuzum, bir tas su verin 

Irmağı, deryayı size bıraktım. 

Talipli değilim şöhrete, şana

Makamı, rütbeyi yük etmem cana 

Dostluk, sevgi, şefkat yetişir bana 

Dövüşü, kavgayı size bıraktım. 

Zaman yoktur ekip, biçip, sürmeme 

Ham topraktan haram mahsul dermeme 

Bir tek gönül kâfi gelir girmeme 

Konağı, sarayı size bıraktım. 

Çokta değil, hakta buldum huzuru

İstediğim alın teri, göz nuru 

Benliği, kibiri, iğrenç gururu 

Faizi, bankayı size bıraktım. 

Hiçbiriniz telaş etmesin boşa 

Doyacak gözünüz toprağa, taşa… 

Beni inancımla koyun baş başa... 

Topyekûn dünyayı size bıraktım.

(Suları Islatamadım)', 'Bana Mevlana’yı, Yunus’u verin  Mecnun’u, Leyla’yı size bıraktım.  Kırk yıldır susuzum, bir tas su verin  Irmağı, deryayı size bıraktım.  Ta...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/taksim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlân', 'i-l-n-abdurrahim-karakoc-3uf34', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne diyorsa İSLÂM DİNİ

Uyacağız suç olsa da.

Gerçeği örten kefeni

Soyacağız suç olsa da.

Alnımız ak, yüzümüz ak

İslâm olan olmaz korkak

Bâtıla bâtıl, hakka hak

Diyeceğiz suç olsa da.

Çiçeklenir sevda serde

Cihad, düğün olur merde

Nur-u Kur''an''ı her yerde

Yayacağız suç olsa da.

Baba, ana, bacı, gardaş

Ehl-i küfre açtık savaş.

İslâmlık yoluna can, baş

Koyacağız suç olsa da.

Cihad bize bayram, düğün

Ta doğuştan haşre değin

Her an Zikrullah gömleğin

Giyeceğiz suç olsa da.

Mânâ doldurmuş iç''leri

Gam mı maddenin suçları..

Dine ''Taş'' atan piçleri

Sayacağız suç olsa da.

(Vur Emri)', 'Ne diyorsa İSLÂM DİNİ Uyacağız suç olsa da. Gerçeği örten kefeni Soyacağız suç olsa da. Alnımız ak, yüzümüz ak İslâm olan olmaz korkak Bâtıl...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ilan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Topraktaki Sevince', 'topraktaki-sevince-abdurrahim-karakoc-y2ykx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al elmalar yeşil dalı eğince

Yaprakların ucu yere değince

Bak o zaman topraktaki sevince.

Hava bulutlanıp gök gürleyince

Bir yağmur başlar ya inceden ince

Bak o zaman topraktaki sevince.

Sevdalılar al kefeni giyince

Kara yerler seni beni yiyince

Bak o zaman topraktaki sevince.

(Dosta Doğru)', 'Al elmalar yeşil dalı eğince Yaprakların ucu yere değince Bak o zaman topraktaki sevince. Hava bulutlanıp gök gürleyince Bir yağmur başlar y...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/topraktaki-sevince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sonra', 've-sonra-abdurrahim-karakoc-4n9z2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kurudu sevgiler gönül tasında

Her mevsim bir başka aldattı bizi.

Renkler başkalaştı gün ortasında

Koyu bir karanlık öptü denizi.

Daraldı her sabah geniş ufuklar

Aşkımızı gölgeledi bulutlar

Yaprak yaprak daldan düştü umutlar

Tüketti takvimler gençliğimizi.

Seneler yalancı çıktı düş gibi

Tüm yazlar üşüttü kara kış gibi

Mermere işlenmiş bir nakış gibi

Dağıldı yüzlerce yokluğun izi.

Önce ''Gerçek'' dedik ve sonra ''Neden''

Bekledik bir daha gelmedi giden

Uyandık en güzel düşü görmeden

Aynalardan sorduk birbirimizi.

(Vur Emri)', 'Kurudu sevgiler gönül tasında Her mevsim bir başka aldattı bizi. Renkler başkalaştı gün ortasında Koyu bir karanlık öptü denizi. Daraldı her...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ve-sonra-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-omer-avsar-brj6e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kendimi kaybettim bilinmez diyarlarda

kavusmayi bekliyorum çok uzaklarda

umudu silmeden bekliyorum sabirla

özlemi yaziyorum bitmez satirlarda

o büyük günde bir gün mutlaka gelecek

bir sabah uyandigimda her sey degisecek

yorgun düsmüs yüregim bir baska sevecek

karsimda anam bana tatli tatli gülecek

aksam gene pür nese sofraya oturacagiz

geleniyle gideniyle yasami paylasacagiz

zaman yine akip gidecek ayrilmayacagiz

bu güzellikleri bir ömür boyu yasayacagiz

disarda insanlar bildigim gibi konusacak

ne yana gitsem derdimi herkez anliyacak

eski dostlarim birer birer ortaya çikacak

biraktigim yerden hayat tekrar baslayacak

                     23.03.2000', 'kendimi kaybettim bilinmez diyarlarda kavusmayi bekliyorum çok uzaklarda umudu silmeden bekliyorum sabirla özlemi yaziyorum bitmez satirlard...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozlem-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkürler', 'tesekkurler-muharrem-guney-gqp9z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine bir mayıs sabahı uyandık hayata,

Acısıyla,tatlısıyla ama her anı seninle olan.

Sana sormustum:”Ne istersin?” 

Sen de her zaman ki gibi “Gereği yok.” demiştin.

Sonra aklıma geldi orta okulda yazdığım şiir sana.

Oradaki dizeler saf bir cocuğun kalemindendi.

Bugünküler ise bir yetişkinden günahıyla sevabıyla senin eserin olan.

İnsan yıllar geçtikçe farklı bakıyor hayata ve sana 

Şu an seni sorsalar bana “Sabır taşım” derim.

“Çeneme katlanan” derim.

“Sevinçlerimi sıkıntılarımı paylaşan” derim.

Bakma seni kızdırdığıma, 

Bazen bunalttığıma,

Hepsi sevgimdendir sakın darılma.

Sana insan daha çok bağlanıyor,

Ayrılık vakti yaklaştıkça.

Senin değerini anlıyor.

Ben senin hakkını nasıl öderim.

Her ne kadar sana olan sevgimi yetmese de anlatmaya.

Bu küçük şiiri kabul et annelik hakkına.', 'Yine bir mayıs sabahı uyandık hayata, Acısıyla,tatlısıyla ama her anı seninle olan. Sana sormustum:”Ne istersin?”  Sen de her zaman ki gibi ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Güney']::text[], 8.5, '{"poet":"Muharrem Güney","poet_slug":"muharrem-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tesekkurler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kaldı ?', 'ne-kaldi-harun-kesik-ausi4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar geçti,bitti

Yaşananlar ve yaşayanlar

Geriye kalan ne vardı ?

Mutluluk,hüzün ve anılar

Ne zaman bitecekti

Mutluluk ve hüzün yok olacak

Anılar ebediyet 

Nesilden nesile varolacak

İnsan bazan ağlar

Dökülür gözlerinden boncuk boncuk

Akaar gider bazen yağmur olur

Sevinç gözyşaları ise;

Yağmur olur tekrar döner

Hüzün gözyaşları ise;

Bulutların üstünde kalır 

Akar gider bir ömür boyu', 'Yıllar geçti,bitti Yaşananlar ve yaşayanlar Geriye kalan ne vardı ? Mutluluk,hüzün ve anılar Ne zaman bitecekti Mutluluk ve hüzün yok olacak...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-kaldi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka sevdalar Yeni Hayatlar', 'baska-sevdalar-yeni-hayatlar-yildirim-yildirim-2hc3f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hilalin yıldızı aldığı gibi bağrına, 

Ateşin kızıl alevi kaptığı gibi harına, 

Maşukun baktığı gibi aşkına, 

Ecelim olsada yaptığım her şey, 

O hilal kaşların altındaki bakışların uğruna.

Amaç veya hedef ben içindeki sen olma düşüncesi, 

Izdıraptan başka birşey değil; bu aşkın  her gün sürüncemesi, 

Anlamadım neden bu ayrılık, sanki sırrın kapalı penceresi, 

işte, hayat yeniden başlıyor; sahne iki oyunun birinci perdesi!', 'Hilalin yıldızı aldığı gibi bağrına,  Ateşin kızıl alevi kaptığı gibi harına,  Maşukun baktığı gibi aşkına,  Ecelim olsada yaptığım her şey,...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Yıldırım']::text[], 8.5, '{"poet":"Yıldırım Yıldırım","poet_slug":"yildirim-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/baska-sevdalar-yeni-hayatlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yük', 'yuk-yildirim-yildirim-zahhu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Omuzlarımda taşıyamayacağım kadar yük,

Ağırlığınca ağır, manaca büyük.

Bir nefesin vucuddaki dolaşımı kadar kısa,

Menfaatsiz, seni yaşatacak kadar büyük.

Yükün ıstılahtaki manası,

Taşınırsa eğer olacaktır her kulun felahı,

Ne alet ister ne edevat yüreğin yeter.

Taşıyamamışsan şayet cesedine okunmayacak sela yeter.', 'Omuzlarımda taşıyamayacağım kadar yük, Ağırlığınca ağır, manaca büyük. Bir nefesin vucuddaki dolaşımı kadar kısa, Menfaatsiz, seni yaşatacak...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Yıldırım']::text[], 8.5, '{"poet":"Yıldırım Yıldırım","poet_slug":"yildirim-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehadetin Şehidi', 'sehadetin-sehidi-yildirim-yildirim-y11sw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıcak yorganıma sarılmış yatarken, 

Serseri kursunlar yağıyordu kardeşime, 

Adım adım basamaklardan çıkamayınca giremem düşüne, 

Duy ey şehit kuruldu cennet o mübarek gülüşüne! ! ! 

Bakın bakın heybetle ayakta durusuna, 

İki cihan yıkılıyor kılıçla vurusuna, 

Ölmüş diyerek melekler sürme çekmiş kaşına, 

Dur! ölü değil onlar bak nur yağmış saçlarına!', 'Sıcak yorganıma sarılmış yatarken,  Serseri kursunlar yağıyordu kardeşime,  Adım adım basamaklardan çıkamayınca giremem düşüne,  Duy ey şehi...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Yıldırım']::text[], 8.5, '{"poet":"Yıldırım Yıldırım","poet_slug":"yildirim-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sehadetin-sehidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Kadar', 'sonsuza-kadar-harun-kesik-pfdvz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir umut parlıyor gözlerimde

Bakıyorum aydolana mısralara

Şairim gelirr gözlerim yolda

Ağlarım gelmez gece aydolana

Dünya''nın kuralı 

Severken ölmek gidipte dönmemek

Var var kainatın her mısrasında

Ölmekte,dönmekte sevmekte

Ağlarsam akmaz gözlerimden

Gözyaşları bazan mısra olur

Bazan gözlerimde bir tutam yaş

Dökülür gönül bahçemin dallarına

Ağlayan şair geride kalmaz

Döker dertlerini mısralara

Gamı,kederi zoru ölümü 

Bazan bir yıldız gibi kayar gökyüzünden

Dünyada kavak yelleri durduğunda

Güneş dünyaya yüzünü somurttuğunda

Bütün dünya yalansız olduğunda 

Bende varolmayacağım', 'Bir umut parlıyor gözlerimde Bakıyorum aydolana mısralara Şairim gelirr gözlerim yolda Ağlarım gelmez gece aydolana Dünya''nın kuralı  Severk...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sonsuza-kadar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaratana', 'yaratana-i-lyas-duran-4rmo5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vardır her insanda biraz sitem Yaratan''a.

Benim sitemim biraz sana, biraz da Yaratan''a,

Ama yine de;

İnsan nasıl şükretmez ki, seni Yaratan''a?', 'Vardır her insanda biraz sitem Yaratan''a. Benim sitemim biraz sana, biraz da Yaratan''a, Ama yine de; İnsan nasıl şükretmez ki, seni Yaratan''...', ARRAY['Türk Edebiyatı','Şiir','İlyas Duran']::text[], 8.5, '{"poet":"İlyas Duran","poet_slug":"i-lyas-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yaratana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıra', 'hatira-nurullah-aydin-q818k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidişinin 147 nci gecesi

Gözlerimi diktim köşedeki sokak lambasına

Işığın altından geçmeni bekliyorum

Pencereden içeri giren yağmur damlaları

Gözlerimden süzülen yaşlara karışıyor

Mum ışığının aydınlattığı resmine bakıyorum

Ne kadarda özlemişim seni bir bilsen

Ellerinin dokunduğu her eşya

Gümüş çerçevede duran resmimiz

Ve o çok sevdiğin mavi hırkam

Her gece seni getiriyor bana

Hep sensiz geliyorsun yanıma,

Kara bulutlar çökmüş şimdi o güzel hatıralara

Herşey bir mazi olmuş artık

Gelmeyeceğini bile bile baktığım her kapı sesinde

Umutlarımın tükendiğini hissediyorum

Ve gidişinin 147 nci gecesine rağmen

Seni hala hatıralarla seviyorum.', 'Gidişinin 147 nci gecesi Gözlerimi diktim köşedeki sokak lambasına Işığın altından geçmeni bekliyorum Pencereden içeri giren yağmur damlalar...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hatira-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-nurullah-aydin-mm5i4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dostum, çok zaman oldu ayrılalı

Hasretin yaşadıklarımdan sonra dayanılmaz oldu

Şimdi boyut değiştirme zamanı;

Burada yalnızım dostum

Ne uçurtmamız telli arabamız

Ne de misketimiz su tabancamız var

Bahçesinden meyva kopardığımız evlerde yok

İnsanlar bile değişti dostum

Değil 8-9 sokak ötesi

Aynı binadaki insanlar bile merhaba demiyor

Yüzlerin hepsi sahte

İlişkiler çıkarlara bağlı burda dostum

Aşkları hiç sorma

Anlatamam sana

Sonra üzülürsün sende

Senin gibi dostlarda yok artık

Bekle beni birgün mutlaka geleceğim yanına...!!', 'Dostum, çok zaman oldu ayrılalı Hasretin yaşadıklarımdan sonra dayanılmaz oldu Şimdi boyut değiştirme zamanı; Burada yalnızım dostum Ne uçur...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dostum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-nurullah-aydin-6wlrm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İhaneti gördüm aşkta

Aşk diye gördüğüm yeşil gözlerde

Yalanı duydum aşkta 

Aşk diye duyduğum kırmızı dudaklarında

Mutsuzluğu yaşadım aşkta

Aşk diye yaşadığım sahte sarılışlarda

    Gördüm

        Duydum

            Yaşadım

Ve sordum kendime bir gece vakti

Gerçek aşk nerede....?', 'İhaneti gördüm aşkta Aşk diye gördüğüm yeşil gözlerde Yalanı duydum aşkta  Aşk diye duyduğum kırmızı dudaklarında Mutsuzluğu yaşadım aşkta A...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya İhanet', 'sevdaya-i-hanet-nurullah-aydin-gemaw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senki dağlarda bir kır çiceği

Sileceğim aklımdan seninle geçen her geceyi

Anmayacak dilim adını

Söylemeyecek dilim şarkımızı

Bir anı saklayacağım içimde bir yerlerde

İçinde hiç sen olmayan

Döneceksin belki yağmurlu bir günde

Gözlerinde umut, saçların ıslak

Titreyen ellerini uzatacaksın 

Vicdan azabı çekmişcesine

Tek bir sözüm olacak sana içtenlikle

Görmeseydi gözlerim

Tutmasaydı ellerim

Sevmeseydi seni yüreğim

Nerden bileydim seninde ihaneti sevdiğini.....', 'Senki dağlarda bir kır çiceği Sileceğim aklımdan seninle geçen her geceyi Anmayacak dilim adını Söylemeyecek dilim şarkımızı Bir anı saklaya...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevdaya-ihanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-nurullah-aydin-u6knl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece o kadar yalnizdim ki 

Karanligin yalnizligini aradim gecede 

Düsüncelerin girdap olup bogazima sarildigini hissettim 

Ne düsündügümü bilmiyorum 

Cevapsiz binlerce soru isareti var kafamda 

Ve çözemedigim bazi bilmeceler 

Dün gece yalnizligi aradim gecede 

Bir irmak düsü gördüm orman içinde 

Inceden inceye sessiz akiyordu 

Bir ceylan gördüm yürürken hayallerimin içinde 

Ürkek ürkek kaçiyordu 

Dün gece seni gördüm çok gariptin 

Hani hatirlarsin ya 

Günes isiklari vurunca pencereden 

Kafesteki kusun civiltilariyla uyanirdik 

Renkli sabahlara, güleryüzlü ve hayata dost, kendimizle dost 

Hele günes batmaya yüz tuttugunda balkona serilmis bir sedirin 

Üzerinde bosalan bira kadehleri 

Inan o an mutlulugu yakalardik oltayla balik yakalar gibi 

Simdi bu dar çikmazlarda mutlulugun adresini unuttuk 

Özgürlügün özlemiyle çarpan çatal yüregimiz 

Artik kendi kendimize düsmaniz 

Eger mutlulugun türküsünü bir agizdan söylemesek bile 

Bir gün ayriligin o adaletsiz kavsagina vardigimizda 

Mutlulugun resmini çizecegiz.', 'Dün gece o kadar yalnizdim ki  Karanligin yalnizligini aradim gecede  Düsüncelerin girdap olup bogazima sarildigini hissettim  Ne düsündügüm...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mutluluk-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmali mi ?', 'olmali-mi-nurullah-aydin-glf61', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep boyle olmali 

Sevgi alcak, ihanet yuce olmali

Birileri canini verirken sevdigi icin 

Birileri umursamamali

Sevdigini soyleyen diller yalanci

Yollarina bakan gozler sahte olmali

Mutlulugun hayalini kurdugunda

Senin icin kipir kipirken

O ise seni yipratmanin planini yapmali

Iste guzelim tam senin dedigin gibi

Sevdalar hain olmali.....', 'Hep boyle olmali  Sevgi alcak, ihanet yuce olmali Birileri canini verirken sevdigi icin  Birileri umursamamali Sevdigini soyleyen diller yal...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olmali-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlığa....', 'aydinliga-nurullah-aydin-ydbw3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Issız bir gecenin zifiri karanlığında

Dertlerim yoldaş olmuş yüreğime

Ellerim prangada, gözlerim firari

Duygularım karmaşık, zihnimde bir sürü soru işareti

Sen diye bir güzel çıkıverdi ansızın

Çevirdi beni karanlık yolumdan

Şimdi mutluyum, yüzüm aydınlığa dönük

Gözlerim ışıl ışıl, yüreğim umutlu

Artık tüm düşüncelerim sensin

Özlem duyabildiğim, dokunabildiğim, sevebildiğim

Gökten inmiş iki yıldız gibi asılı duran ışıltılı gözlerin 

Beni yarınıma, hayallerime, sana bağlayabildiğim', 'Issız bir gecenin zifiri karanlığında Dertlerim yoldaş olmuş yüreğime Ellerim prangada, gözlerim firari Duygularım karmaşık, zihnimde bir sü...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aydinliga-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye Dair', 'geceye-dair-nurullah-aydin-ialzi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanki hiç doğmayacakmış gibi güneşi bekleyip 

Uzayan saatlerde özleminle yanarken 

Karanlığın sessizliğini bozan rüzgarın uğultusunda 

Aradım yine, 

Dün gece o güzelim ellerini 

Ulaşamadım bir türlü güzelliğine, 

Çünkü yoktun sen 

Artık hiç olmayacaktın 

Bir umut rüzgarıyla ektiğim sevgi tohumlarını 

Hain bir rüzgar alıp götürmüştü 

Mutlu günlerin hayaliyle yaşarken

Kaybetmiştim seni ıssız bir gecede 

Artık bende sessizim 

Yüreğim alabildiğine buruk, alabildiğine suskun', 'Sanki hiç doğmayacakmış gibi güneşi bekleyip  Uzayan saatlerde özleminle yanarken  Karanlığın sessizliğini bozan rüzgarın uğultusunda  Aradı...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/geceye-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-nurullah-aydin-q0gme', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Keşke hep çocuk kalsaydım diyorum bazen 

Hiç büyümeseydim

Hiç anlamasaydım 

Büyüklerin derdini, koşuşturmacasını

Benim en büyük kazancım çikolata paketi olmalıydı

Ya da bir külah dondurma,

Sevgiyi bilmeseydim anne sevgisinden başka', 'Keşke hep çocuk kalsaydım diyorum bazen  Hiç büyümeseydim Hiç anlamasaydım  Büyüklerin derdini, koşuşturmacasını Benim en büyük kazancım çik...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ozlem-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede', 'nerede-nurullah-aydin-fqg3n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerde bizim gençlik yıllarımız dostum

Bir parça sosisliyi bölüştüğümüz istasyonlar

Bahçesinden çiçek kopardığımız okullar

Nerde ha dostum nerde o günler

Parayı düşünmediğimiz

Kızları özlemediğimiz o günlerimiz nerde

Kaybolduk şimdi bu derin dehlizlerde

Ya mumu uzat bana

Ya da elimi bırak gömüleyim karanlıklarda', 'Nerde bizim gençlik yıllarımız dostum Bir parça sosisliyi bölüştüğümüz istasyonlar Bahçesinden çiçek kopardığımız okullar Nerde ha dostum ne...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nerede-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece Seni Düşündüm', 'dun-gece-seni-dusundum-nurullah-aydin-3pu0l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum gece ansızın

Dilimden hazin bir şarkı dökülüyor

Gecenin belirsiz büyülü gülüşüne akıyordu

Aynaya bakıyorum

Sensizlik ne denli değiştirmiş beni

Yırtılıyor kalbimin içten damarları

Kan gözeneklerine dönmüş gözlerim

Seni düşünüyorum gece ansızın

Sigara dumanında kaybolmuş tüm hayallerim

Bir sistabakası çökmüş o o güneşli ve açık şafaklara

Güller kurumuş saksılarda

Leylak ve zambak kokan sabahların sam yellerini

Ayrılıklar ve sonu gelmeyen özlem dolu geceler almış

Dün gece seni düşündüm yine ansızın

Sol gözümde bir damla yaş

Kirpiklerimden süzülüp yanağıma aktı

Belki ağlıyordum ama köşe bucak saklandım

Kimse ağladığımı duymasın diye

Dün gece seni düşündüm ansızın

Akıllı olmaktan uzak, delicesine

Seviyorum seni ölürcesine...', 'Seni düşünüyorum gece ansızın Dilimden hazin bir şarkı dökülüyor Gecenin belirsiz büyülü gülüşüne akıyordu Aynaya bakıyorum Sensizlik ne den...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dun-gece-seni-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Öyküsü', 'askin-oykusu-nurullah-aydin-aoha9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani bana sarılırken ağlardın ya içten içe

 Hani sadece seninim derdin ya

 Mutlu bir yuvanın hayaline imza atmıştık

 Yalnız bizim olacak dünyanın özlemini taşımıştık

 Gözlerim kimseyi görmüyordu

 Kulaklarımda sadece senin sesin

 Ve kalbimde yalnızca senin sevgin yüklüydü

 O kadar mutluydum ki Allahım uçuyordum

 Ve aşk hainliğini gösterdi bir gece ansızın

 Uzayan tartışmalar, bir de aile baskısı

 Galip geliverdi sevda denen yalan düşe

 Ayrılmalıyız dedi,

 Ne kadar da kolay söyleyiverdi

 Sanki karşımdaki sevdiğim insan değil

 Hiç tanımadığım, ellerinden tutmadığım

 Boynuna bir kez olsun sarılmadığım birisiydi

 Bir anda dünyam yıkıldı zannettim

 Boğazımda düğümlenen bir hıçkırık

 Ve kalbimde yerinden çıkarmışcasına bir çarpıntı

 Uzanıverdi titreyen ellerim sigara paketine

 İçime çektiğim her nefeste sanki ihaneti tadarmışcasına

 Gecelerde buluyordum yalnızlığımı

 Artık her şey yavan geliyordu bana

 Çekip gitmeliydim bu şehirden

 Bu şehir koparmıştı beni çok sevdiğim birinden', 'Hani bana sarılırken ağlardın ya içten içe  Hani sadece seninim derdin ya  Mutlu bir yuvanın hayaline imza atmıştık  Yalnız bizim olacak dün...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/askin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerilerde', 'gerilerde-nurullah-aydin-g044q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamansiz geçtim sevda tünellerinden 

Elimde ne bir fener ne de pusula 

Yol göstereninmi var deli gönül 

Uzadikça uzadin bir türlü çikar yolu bulamadin 

Simdi karanliklar ülkesindesin 

Yok, öyle hemen kestirip unutmak 

Kara sevdalar içerisindesin 

Sonumuz ya mutluluk, ya da kara toprak 

Hiç yanmamisti gönlüm böyle köz misali 

Nereden gördüm o yesil yesil bakan gözlerini 

Simdi istesemde geri getiremem seni 

Bilinmezlerdesin, düsündünmü hiç kederimi 

Yarim kaldi simdi sevdalar 

Ya o bahçede kosusacak çocuklar, neredeler 

Hepsi bir mazi oldu ayriligin pençesinde 

Tekrar yasanirmi saniyorsun, artik hersey çok gerilerde….', 'Zamansiz geçtim sevda tünellerinden  Elimde ne bir fener ne de pusula  Yol göstereninmi var deli gönül  Uzadikça uzadin bir türlü çikar yolu...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gerilerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevince', 'sevince-nurullah-aydin-l343k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevince içten, çılgınca sevmeli 

Özlediğinde içine sığmamalı yüreğin 

Değer vermeli insan sevdiğine 

Hiçbir set durmamalı önünde 

Coşup akmalı sevdiğinin gönlüne 

İki kelimeyle özetlememeli sevgiyi 

Bazen sıcak bir sarılış 

Bazen içli bir gözyaşı 

Fazlasıyla anlatır içindeki duyguyu 

Değilmi ki aslolan mutlu olabilmek 

O zaman yol ver sevdaya aşkı yaşasın..', 'Sevince içten, çılgınca sevmeli  Özlediğinde içine sığmamalı yüreğin  Değer vermeli insan sevdiğine  Hiçbir set durmamalı önünde  Coşup akma...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevince-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-cevat-aydin-w0hht', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılmak kolaysa,

İşte sana ayrılık yolu.

Yüreğin dayanırsa,

İşte sana aşkın sonu.

Aşk hatırlanmaksa,

Her an aklımdasın.

Aşk unutulmamaksa,

Ölene dek unutulmayacaksın.

Ben ne acılar çektim,

Dayandım heyhat....

İşte sana iki yol;

Biri ayrılık biri vuslat.', 'Ayrılmak kolaysa, İşte sana ayrılık yolu. Yüreğin dayanırsa, İşte sana aşkın sonu. Aşk hatırlanmaksa, Her an aklımdasın. Aşk unutulmamaksa, ...', ARRAY['Türk Edebiyatı','Şiir','Cevat Aydın']::text[], 8.5, '{"poet":"Cevat Aydın","poet_slug":"cevat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yol-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece ve Gökyüzü', 'gece-ve-gokyuzu-nurullah-aydin-h14xg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Istasyonda kara trenin gelmesini bekleyen yolcular gibi 

Gözlerimi gecenin karanlığında ışıl ışıl 

Uzayıp giden raylara dikiyorum 

Kimi zaman da yıldızları bekliyorum gecede 

Yürüyorum sahilde kimsecikler yok 

Etrafta sadece ben ve ayak seslerim var 

Birde dalgaların senden haber getirdigi fısıltılar 

Ansızın dolunay oluyor yüreğim yıldızlara karışıyorum 

Gökyüzünden asağıda olup bitenleri seyrediyorum 

Yeryüzü ne kadarda yalın geliyor 

Özgürlüğü hissedince kanatsız bir şekilde 

Yıldızlar bile küsüyor bazen insanlara 

Niçin bu kargaşa, bu oyun diye 

Evet, gece güzeli hayat bir oyun 

Bu oyunda çok güzel roller var 

Yıldızlar müsaade isteyerek tek tek ayrılıyorlar 

Sabahın ilk ışıklarıyla gökyüzünden 

Onlardan bir tanesinin karanlıkta kaymasını istiyorum 

Dönerken yaşadığım hayatın içerisine 

Eski bir dost olduğumdan kırmıyorlar beni 

Birisi ışıl ışıl sessizce aşağılara iniyor 

İşte o zaman duygularımı karıştırıp tutuyorum dileğimi 

Senin yanımda olmanı diliyorum hep

Ve ertesi gün, ertesi gece böyle geçip gidiyor günler 

Teşekkürler gece, teşekkürler gökyüzü...', 'Istasyonda kara trenin gelmesini bekleyen yolcular gibi  Gözlerimi gecenin karanlığında ışıl ışıl  Uzayıp giden raylara dikiyorum  Kimi zama...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gece-ve-gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Kırılırsan', 'ya-kirilirsan-nurullah-aydin-1vmt6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte bir gece daha 

Uzun uzadıya bir gece 

Ne kadar uzak olsak da 

Sıcaklığını hissedebiliyorum içimde 

Seni alip götüren o hain yollara sitem ediyorum 

Bazende seviyorum onlari 

Seni getiriyorlar bana 

Mutluluğun tarifini çiziyoruz kimi zaman 

Birden bire rüzgar çıkıyor kuvvetlice 

Sevgi, ümit ne varsa alip götürüyor 

Yetiştirmeye çalistigim ümitlerimi 

Savuruyor dört bir tarafa 

Sonra yine rüzgarı bekliyorum sessizce 

Hep bir kısır döngü içerisinde 

Duyguların dalgasina katıştırıyorum kendimi 

Bazen sözler tıkanıveriyor boğazıma 

Söyleyemiyorum ya kırılırsan diye...', 'İşte bir gece daha  Uzun uzadıya bir gece  Ne kadar uzak olsak da  Sıcaklığını hissedebiliyorum içimde  Seni alip götüren o hain yollara sit...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ya-kirilirsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecdad', 'ecdad-nurullah-aydin-spx7u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aman dileme kimseden gardaş

Başın dik göğsün serhat dolu olsun

Senin ataların hiç kimseye eğilmedi

Bir gün el etek öpmedi ufak menfaatler için

Er kişiye yakışmaz böyle lakayit tavırlar

Düşün ecdadını, nice hükümdarları ağlattılar

Onlar ki vatan bellediler her karış toprağı

Kanlarıyla suladılar kıymetini bilmediğimiz bu vatanı

Gökten ayla yıldızı indirdiler

Nede güzel yakıştı ortasına şehitlerin kanı

Yürekleri coşkuluydu, gemileri yürüttüler karadan,

Mohaçda derbeder ettiler küffarı

Tunadan geçtiler bir akşam üstü

Öğün ecdadınla, bu hayat sana onların emaneti', 'Aman dileme kimseden gardaş Başın dik göğsün serhat dolu olsun Senin ataların hiç kimseye eğilmedi Bir gün el etek öpmedi ufak menfaatler iç...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ecdad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para Hırsı', 'para-hirsi-cevat-aydin-ihjvi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya değil eski dünya,

Emilen ak süte karışmış kara.

İnsanlarda bir hırs ki adı; para

Kul oldu kimileri para denilen mel''una.

Yeri geldi canımızı canımıza kattık,

Çok dert çektik derdi derde katık yaptık.

Kimisi oldu vatanımızı bile sattık,

Eremedik refaha yoksulluktan usandık.

Bizi bir birimize düşürdüler,

Kapıldık para hırsına.

Kardeşi kardeşe vurdurdular,

Kahrolası para uğruna.', 'Dünya değil eski dünya, Emilen ak süte karışmış kara. İnsanlarda bir hırs ki adı; para Kul oldu kimileri para denilen mel''una. Yeri geldi ca...', ARRAY['Türk Edebiyatı','Şiir','Cevat Aydın']::text[], 8.5, '{"poet":"Cevat Aydın","poet_slug":"cevat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/para-hirsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temenni', 'temenni-nurullah-aydin-1qaei', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdalar ray olsun, 

sende mutluluk treni, 

her tünele girdiğinde 

yolunu aydınlatan 

birde aşkın

olsun yanıbaşında......', 'Sevdalar ray olsun,  sende mutluluk treni,  her tünele girdiğinde  yolunu aydınlatan  birde aşkın olsun yanıbaşında.........', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/temenni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostuma', 'dostuma-nurullah-aydin-pzixx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne çok şeyi paylaştık seninle,

Kimi gün güldük, kimi zaman ağladık

Gözyaşlarımız birlikte aktı 

Kahkahalarımız çınladı ortalıklarda

O zamanlar paramız yoktu belki ama

Mutluyduk dostum

Hatırlıyormusun okuldan çıktığımızda

İstasyona gidip tren beklediğimiz günleri

Bazı günler arıza yapardı da 

Saatlerce yürürdük hani

Birlikte dolaşır, cebimizdeki parayı paylaşırdık

Sonraları sevdalanmaya yüz tuttu gönlümüz

Aşık olduğumuz kızları anlatırdık birbirimize

Sen başka bir türlü överdin sevdiğini

Her lafından biri onun ismiyle doluydu

Sahilde oturup ağlamıştık beraberce

Sevdiğin kız için gecenin bir yarısında

Ne kadar üzülmüştüm dostum sana,

Daha sonraları alışmıştık ayrılıklara

Her defasında sevmeyelim derdik

Ne zaman bir sıkıntımız olsa

Ya ben gelirdim yanına, ya da sen

Canımızı dişimize takıp 

Herşeyin üstesinden gelmeye çalışırdık

Herşeyden önemlisi dostum

Bizim aramızdaki bağ çok farklıydı.

Hayatım boyunca karşılaştığım insanlar arasında

Dosdoğru dost denebilecek bir sen çıktın yalansızca

Bir şiir yazmayı denedim sana içinde sen olan

Dostluğumuzu unutturmayacak bir hatıra diye

Her yalnızlık hayaline daldığın gecelerde

Cebinden çıkarıp okuyunca beni duyabilesin diye………', 'Ne çok şeyi paylaştık seninle, Kimi gün güldük, kimi zaman ağladık Gözyaşlarımız birlikte aktı  Kahkahalarımız çınladı ortalıklarda O zamanl...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dostuma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-nurullah-aydin-eqab3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün doğmadan henüz geceye

Işıl ışıldı gökte yıldızlar

Sen düştün birden aklima

Düşlerle yoğruldum karanlığın içinde

Artık daha iyi görebiliyordum herşeyi

Ne dönüşün belliydi bana sabahın ilk ışıklarıyla

Ne de gerçekten sevebileceğin….!!', 'Gün doğmadan henüz geceye Işıl ışıldı gökte yıldızlar Sen düştün birden aklima Düşlerle yoğruldum karanlığın içinde Artık daha iyi görebiliy...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gece-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Sevdalandım..?', 'nasil-sevdalandim-nurullah-aydin-s4q4q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdim inanamayacağın kadar seni esmer kız

Gönlümü yitirdim bir tatlı gülüşünde	

Gözlerim görmez oldu senden başka hiç kimseyi

Sarmadı kollarım bir başkasını	

Senle varoldum yeniden	

Seninle duydum tüm mutluluğu	

	

Gidişin hüsranım oldu bir gece yarısı	

Gözlerimde hep bir umut seni bekledim	

Özlemin sardı tüm benligimi	

O hain bitip tükenmek bilmeyen saatlerde	

Gelmeyecektin biliyordum	

Ama ya yüreğim, o bunu biliyormuydu ?	

	

İhaneti tatmış buruk bir yürek	

Küskün bakan yaşlı gözler	

Birde sigara paketine uzanan şu eller	

Hepsi senin eserin	

Sen bunu hiçbir zaman bilemesende…….', 'Sevdim inanamayacağın kadar seni esmer kız Gönlümü yitirdim bir tatlı gülüşünde	 Gözlerim görmez oldu senden başka hiç kimseyi Sarmadı kolla...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nasil-sevdalandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran', 'haziran-i-brahim-sadri-zd5yw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mektubun geldi arkadaşım

haziran da geldi

şimdi sen, denizi de yazmışsındır

beni beter edeceksin ya

martılarını ve simidini istanbul''un

göz nurum

suyun çiçeğe, çimene yürüdüğü bir mevsimde

bana umudu yazmana ne hacet

hadi biraz

şehrin şarkısından ve arkadaşlardan bahset

mektubun geldi arkadaşım

haziran da geldi

gönderdiğin gibi duruyorum burada

hiç ağlama

ağlamak yakışmıyor haziranda adama

iyi yanları da yok değil ama

bak erken kalkıyorum mesela

gökyüzüne bakabiliyorum arada sırada

arada sırada koymuyor değil

koyuyor hasretlik onca kahrıyla 

ama arada

hadi çocuklardan bahset

herkes iyi diye bir yalan yaz mesela

pazar günleri onları güneşe çıkar

ellerinden tut götür uzak bir limana

sevgili karıma da bir gül diziyorum boncuktan

mahsus selam ediyorum bütün arkadaşlara

mektubun geldi arkadaşım 

haziran da geldi

kimin aklına gelirdi ki

aşkın ve sevdanın hatrına

bir menekşe büyüteceğim iki ranza arasında

sonra türküler öğreneceğim

zulümün, ayrılığın ve turnaların adına

gönderdiğin kitapları da okuyorum

elin değerse ve zor değilse

biraz çimen, taze bir gül yaprağı

karımın sesinden, çocuklarımın gülüşünden de koy

bir daha ki mektuba

arkadaşların yüreğini de unutma

mektubun geldi arkadaşım 

haziran da geldi

yağmur da yağıyor mu

ıslanıyor musunuz eskisi gibi

eskisi gibi anıyor musunuz arkadaşınızı

hiç unutmadığım adlarınızı

adımın yanına yazıyor musunuz

bu pazar açık görüş var

çocuklarımı, karımı ve arkadaşlarımı istiyorum

konuşuruz ordan burdan

elleriniz elime, yüreğiniz yüreğime dokunur

tamam, biraz da ağlarız

ağlarız işte n''olur

mapusluk mevsiminde o kadar olur

mektubun geldi arkadaşım

haziran da geldi', 'mektubun geldi arkadaşım haziran da geldi şimdi sen, denizi de yazmışsındır beni beter edeceksin ya martılarını ve simidini istanbul''un göz ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadri']::text[], 8.5, '{"poet":"İbrahim Sadri","poet_slug":"i-brahim-sadri","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/haziran-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kır çiçeği olmalıydım', 'bir-kir-cicegi-olmaliydim-hasan-sutay-iraz1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben dağbaşlarında unutulmuş

bir kır çiçeği olmalıydım

Kuşlarla, böceklerle haşır-neşir olmuş

Mevsimi geldiğinde solmuş..

Kem gözlerden ırakta

yaşamak

Göz açıp kapamak da olsa

Neyin varsa bırak da

Bir kır çiçeği ol

Dağbaşlarında unutulmuş...

Esen rüzgar

Senden bir rayiha alıp

Götürsün şehirlere

Burada bir lahza kalıp

atılma yerlere...

Varsın şarkını kuşlar söyleyip

Şiirini rüzgar yazsın

Sararıp solsan da

Artık unutulmazsın', 'Ben dağbaşlarında unutulmuş bir kır çiçeği olmalıydım Kuşlarla, böceklerle haşır-neşir olmuş Mevsimi geldiğinde solmuş.. Kem gözlerden ırakt...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sutay']::text[], 8.5, '{"poet":"Hasan Sutay","poet_slug":"hasan-sutay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-kir-cicegi-olmaliydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte O Benim', 'i-ste-o-benim-huseyin-anilan-oqmge', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç unutmam ilk tanışmamızı sizinle, 

Ben yirmi bir, siz altı yaşına yeni basmıştınız.

Ana sınıfı denilen yerde buluştuk sizinle, 

Ben ilk öğretmenliğe, siz ilk öğrenciliğe başladınız.

Üç ay, beş ay derken, koskoca yıl geçiverdi oyunla, 

Siz artık birinci sınıftınız, bense birinci sınıf öğretmeni

A’yı B’yi, Biri, İkiyi derken

Geçiverdi beş yıl durup dinlenmeden

Siz büyüdünüz, altıncı sınıftınız, 

İşte burada beni biraz yanlış tanıdınız

Sizin deyişinizle Müzikçi, Bedenci ya da Fenci idim

Ama branşım değişse de ben hep öğretmendim

Eski, tarihi bir binaydı lise denilen yer, 

Tatlı bir telaş, bir heyecan vardı yer yer, 

Ben kazandırmanın, siz ise kazanmanın derdindeydiniz

İşte sonunda başardık, artık hepimiz üniversiteliyiz.

Yıllar çok çabuk savurmuştu hepimizi

Sizler Hukuk’ta, Tıp’ta,  Eğitim’desiniz, 

Bense anfide yapıyorum artık derslerimi

Bilseniz ne çok seviyorum sizleri

İnanın değişen nedir? Bilmiyorum! 

Yıllar mı çabuk geçti, yoksa ben mi yaşlandım? 

Daha dün gibiydi ilk tanışmamız

Neden bu kadar acele davrandınız? 

Nasıl unutursunuz beni yaşlansam da

Ben her zaman, her yerde sizinle değil miydim? 

Adım, ünvanım, memleketim değişse de

Ben hep öğretmeniniz değil miydim? 

		Eskişehir  15.11.1999', 'Hiç unutmam ilk tanışmamızı sizinle,  Ben yirmi bir, siz altı yaşına yeni basmıştınız. Ana sınıfı denilen yerde buluştuk sizinle,  Ben ilk ö...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Anılan']::text[], 8.5, '{"poet":"Hüseyin Anılan","poet_slug":"huseyin-anilan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iste-o-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış Manço''ya Ağıt', 'baris-manco-ya-agit-omer-salman-ztmh1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bembeyaz bir mâtem çöktü dağlara

O büyük hoş sedâ çekildi bugün

Yetim gibi baktım ''''dağlar dağlara''''

Bağrıma bir hançer sokuldu bugün

Hayat; gamsız, dertsiz, kedersiz olmaz

Açtım ellerimi eyledim niyaz.

Gün bir şubat ''''hava ayaz mı ayaz''''

Soğuktan buz kesen akıldı bugün.

''''Kara haber'''' taşı atıldı bana

Hayâl kuşu uçtu mâziden yana

Bir titreme girdi bu tatlı cana

''''Adam olmuş'''' biri yıkıldı bugün.

O kültürümüzün bir eseriydi

O ''''gülünce güller açan'''' biriydi

O yirmi dört saat önce diriydi

Gönlümden bir parça yok oldu bugün.

Onun sevenleri güzel görürdü

''''Dere tepe'''' demez, durmaz yürürdü

Bize ahlâk, edep, bilgi verirdi 

''''Yediden yetmişe'''' üzüldü bugün.

Sanatçı geçinen bak sanatına

Ömür boyu bindi edep atına

Bakma yüce Rabb’im taksirâtına

Azrâil ulu bir can aldı bugün.

Onunla tutuldu ''''karasevdâya'''' 

Mini mini kardeş ülke Japonya

O coşku seliyle yıkıldı dünya

O konser aklıma takıldı bugün

''''Kısacık bir çizgi ömür'''' az gelir

Ölümden Manço’ya bil ki haz gelir

Ardından duâlar ve niyaz gelir

O ''''yedi iklime'''' ün saldı bugün



Elden bir şey gelmez yüce buyruğa

Mübârek nâşını sarın bayrağa

''''Allayıp pullayıp'''' verin toprağa

Dünyamızdan kopan bir güldü bugün

Gördüm göz yaşlarım kırmızı bir tel

Gelmesin cismine rûhuna halel

''''Dünyayı'''' tabuta sığdırdı ecel

Sonsuzluğa uçan bülbüldü bugün

Gitti elden eyvâh bir eşini bul 

Cennet köşklerinden birine kurul

''''Moda seksen bir bin üç yüz İstanbul''''

Bu adrese hücum edildi bugün.

Allah sabır versin güzel eşine 

Hasret kaldık onun bir gülüşüne 

Bir millet yas tuttu onun peşine

Kızıl gözler ile bakıldı bugün

''''Seke seke çaydan öteye geçti''''

''''Hendeği atladı'''' dünyadan geçti

Kendine yepyeni bir yuva seçti

Bir âbide yere dikildi bugün

Şimdi mahzun kalan karlı dağ olsun

''''Barış Çelebi''''nin alnı ağ olsun

Derim bütün dünya başın sağ olsun

Manço’muz toprağa verildi bugün

Yirmi yıllık dosttu yandı ciğerim

Merhameti bol’a duâ ederim

Ağla durma ağla Âşık Ömer’im

Koskoca bir dünya yıkıldı bugün

1-3.ŞUBAT.1999 KÜTAHYA', 'Bembeyaz bir mâtem çöktü dağlara O büyük hoş sedâ çekildi bugün Yetim gibi baktım ''''dağlar dağlara'''' Bağrıma bir hançer sokuldu bugün Hayat;...', ARRAY['Türk Edebiyatı','Şiir','Ömer Salman']::text[], 8.5, '{"poet":"Ömer Salman","poet_slug":"omer-salman","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/baris-manco-ya-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KOŞMA', 'kosma-omer-salman-cs3k5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözü kara ettin ey kara gözlüm

Bana mahzun mahzun baktın da gittin

Ay mısın güneş mi ey melek yüzlüm?

Gözümden yaş olup aktın da gittin

Yolun düzü varken eğrisi niye 

Ağladım,adını ah diye diye

Derler ki bu hâle düştün ne diye

Aklıma bin şüphe soktun da gittin

Gerçekten insana ağlar anası 

En güzel hâllerdir için aynası

Bakışın acaba neydi mânâsı?

Cânânım canımı sıktın da gittin

Siyah gözlerini görmez olaydım

Bakışını hayra yormaz olaydım

Şu gönlümü sana vermez olaydım

Aldın emâneti yaktın da gittin

Arada deniz var,arada dağlar

Gemiler hâlime ah edip ağlar

Nasıl hayattayım şaşıyor sağlar

Zor ile gönlümden çıktın da gittin

Duydukça türküyü 

Ah’la göğü siyah eden bülbülüm

Yön gösterir yüzün yol olmuş gönlüm

Yolları peşine taktın da gittin

Kalmamış ümidi tutar yolunu

Terk edip de gitmiş İstanbul’unu 

Kale gibi Âşık Ömer kulunu

Vîrân ettin yaktın yıktın da gittin', 'Gözü kara ettin ey kara gözlüm Bana mahzun mahzun baktın da gittin Ay mısın güneş mi ey melek yüzlüm? Gözümden yaş olup aktın da gittin Yolu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Salman']::text[], 8.5, '{"poet":"Ömer Salman","poet_slug":"omer-salman","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kosma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımızın Duası', 'askimizin-duasi-orhan-gencebay-6lez5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyam gözlerinde ağlıyor gibi

Her damla aşkımıza bir dua gibi

Dünyam gözlerinde ağlıyor gibi

Her damla aşkımızı bağlıyor gibi

Kaderim bile seni benden çok sevdi,sevdi

Derdinde mutluluk var aşk seni bana verdi

Yarınlar bak ufukta aşkımıza gel gel diyor

Kucak açmış hep ümitler bizi bekliyor

Sensiz ölecektim inan kahrımdan

Bir ses bekle dedi çok uzaklardan

Yaşamak çok hüzünlü sessiz bir şarkı gibi

Çek derdi ızdırabı,aşkıma hep yıllardan', 'Dünyam gözlerinde ağlıyor gibi Her damla aşkımıza bir dua gibi Dünyam gözlerinde ağlıyor gibi Her damla aşkımızı bağlıyor gibi Kaderim bile ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askimizin-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğan Bir Pişman', 'dogan-bir-pisman-orhan-gencebay-mxk8p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğan bir pişman,doğmayan iki

Doğuştan felekle düşmanım sanki

Herkeste bir kalp sevgiye muhtaç

Sevenler bir ise,sevmeyen iki

Bu ne aşktır yarabbim öldürdü beni

Ne kendisi güldü,ne de güldürdü beni

Dertlerim dermansızdır yaram çok derin

Yıllardır çekiyorum bitmedi dertlerim', 'Doğan bir pişman,doğmayan iki Doğuştan felekle düşmanım sanki Herkeste bir kalp sevgiye muhtaç Sevenler bir ise,sevmeyen iki Bu ne aşktır ya...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dogan-bir-pisman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayırsız Oğul', 'hayirsiz-ogul-tacettin-simsek-lr9kj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dönmez mi o 

hülyası sınırsız oğlun

Berduş tabiat

hayli sabırsız oğlun

Söyler misin anne

hiç şaşırmaz mıydın

Birgün çıkagelseydi

hayırsız oğlun', 'Dönmez mi o  hülyası sınırsız oğlun Berduş tabiat hayli sabırsız oğlun Söyler misin anne hiç şaşırmaz mıydın Birgün çıkagelseydi hayırsız oğ...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayirsiz-ogul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savunma', 'savunma-tacettin-simsek-dhxad', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel kınama beni cânım efendim

Böyle gurbetlerle sınama beni

Dünbir aşkı kabullenmekti şiir

Bugün bir aşkı inkâr

Duyarsın

Alıcı kuşlara karşı bir akşam

Hâki gölgeler ağzından ismimiz

Güvercin diye çıkar

Tut ki biz de yetim-i akranız

Bizim de bahtımızla kavgamız var

Gel kınama beni cânım efendim

Böyle gurbetlerle sınama beni

İster ciğerpârem ol

İster tanıma beni

Korkuyu söylemek de insancadır

Neylesem ne söylesem

Kundakta bir yediveren gülüm var

Namlular uzanır uykularına

Penceremin pervazında ölüm var

Tükenmek üzre bir tahammülüm var

Gel kınama beni

cânım efendim

Böyle gurbetlerle

sınama

beni', 'Gel kınama beni cânım efendim Böyle gurbetlerle sınama beni Dünbir aşkı kabullenmekti şiir Bugün bir aşkı inkâr Duyarsın Alıcı kuşlara karşı...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/savunma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunay Dört Parça', 'dolunay-dort-parca-tacettin-simsek-w0m5f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Altın dökülüp göklerin elmas tasına

Binlerce ışık doldu

zaman bohçasına

Birgün dediler

dörde bölünmüş dolunay

Bildim ki

güneş baktı

ayın aynasına', 'Altın dökülüp göklerin elmas tasına Binlerce ışık doldu zaman bohçasına Birgün dediler dörde bölünmüş dolunay Bildim ki güneş baktı ayın ayn...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dolunay-dort-parca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İftarlık', 'i-ftarlik-tacettin-simsek-e1qz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yokluktadır aslında

bütün varlığımız

Sevgiyle kurulmuş

sabır uygarlığımız

Gel sevgili dostum

çıkalım dağ başına

Yağmur suyu olsun yine

iftarlığımız', 'Yokluktadır aslında bütün varlığımız Sevgiyle kurulmuş sabır uygarlığımız Gel sevgili dostum çıkalım dağ başına Yağmur suyu olsun yine iftar...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iftarlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çarşamba', 'bir-carsamba-feride-sayili-u0lvm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir Çarşamba günü randevulaştık,

Tuttu ellerimi öyle bakıştık,

Hal hatır biraz fısıldaştık,

Ellerimi elinden usulca çektim,

Hem utandım,hem sıkıldım.

Böyle terbiyesizlik olmaz deyip ona karardım.

Yalvardı yakardı biraz zorladı,

Üzerimde bir kilot bir de sütyenim vardı,

Kalktı usulca yatağa gitti,

Bana da gelmemi işaret etti,

Dikildim ayakta biraz düşündüm,

Ortalıkta o halimle artık üşüdüm,

Birkaç adım atınca yatağa eriştim.

Rüyamda da olsa gizlice seviştim.', 'Bir Çarşamba günü randevulaştık, Tuttu ellerimi öyle bakıştık, Hal hatır biraz fısıldaştık, Ellerimi elinden usulca çektim, Hem utandım,hem ...', ARRAY['Türk Edebiyatı','Şiir','Feride Sayılı']::text[], 8.5, '{"poet":"Feride Sayılı","poet_slug":"feride-sayili","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-carsamba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiş', 'gidis-nurullah-aydin-jhupy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çekip gittin ya hayatımdan

Sanki bir boşluk çöktü içime

Eskisi gibi değildim

İçimden birşeyleri de alıp götürmüştün

Ne gecenin, ne de denizin tadı var artık

Sahilde söylediğimiz şarkılar bile yabancı bize

Öyle alışmıştımki sana

Yalnızlık çok ağır geldi yüreğime

Bir rakı kadehinde yahut bir sigara dumanında

Aradım yalnızlığımı,

Kaç kere denedim seni unutabilmeyi

Meğer her yudumda, her nefesde seni çekmişim içime

Farkına bile varamadan sevdamın bittiğinin

Yalnızlığımın tek sırdaşı şimdi geceler

Dalıp giderken karanlıkta yıldızların ışıltısına

Bir seni düşünüyorum bir de kendimi

Ve şairin sözü düşüyor dilimden sabahın ilk ışıklarıyla

Güzelliğin beş para etmez, bu bendeki sevdan olmasa……

Haziran/2001', 'Çekip gittin ya hayatımdan Sanki bir boşluk çöktü içime Eskisi gibi değildim İçimden birşeyleri de alıp götürmüştün Ne gecenin, ne de denizi...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gidis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarmısın', 'anlarmisin-cumhur-yerlikaya-23c46', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni 

Ve 

Bitmeyen hisleri 

Anlayabilirmisin? 

Yoksa 

Zormu 

Gelir? 

Bense 

Seni 

Anlamak 

İstiyorum... 

Sevmek 

Çokmu 

Kolay? 

Yoksa 

Yoksa... 

Ben seni 

Sevebilirmiyim? 

Beni 

Ve 

Benliğimi 

Anlayabilirmisin? 

İstermisin?', 'Beni  Ve  Bitmeyen hisleri  Anlayabilirmisin?  Yoksa  Zormu  Gelir?  Bense  Seni  Anlamak  İstiyorum...  Sevmek  Çokmu  Kolay?  Yoksa  Yoksa...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Yerlikaya']::text[], 8.5, '{"poet":"Cumhur Yerlikaya","poet_slug":"cumhur-yerlikaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anlarmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rücu', 'rucu-cemal-safi-z1nna', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen benim gözümde bir kifayettin.

İlk değil alçağı yüksek görüşüm.

Sanma ki sen bana ihanet ettin; 

O, senin aslına rücu edişin.

kahrını çektiysem vardır bir neden

sendin bu duyguyu bende üreten

kim kimi kullanmış şöyle bir düşün

o senin aslına rücu edişin

ilk defa başımı vurmadım taşa

yanıla yıkıla geldim bu yaşa

sanma ki sen beni aldattın haşa! 

çoktandır başladı bende bitişin

o senin aslına rücu edişin', 'Sen benim gözümde bir kifayettin. İlk değil alçağı yüksek görüşüm. Sanma ki sen bana ihanet ettin;  O, senin aslına rücu edişin. kahrını çek...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/rucu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanın Aşkına', 'vatanin-askina-fatih-cinar-6y0ym', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'toprağın bağrında 

sıra dağlar gibi duranlar

tarih tekerrür ediyor

uyanın ey gaflet uykusunda uyuyanlar

bir gün olur eski hakanlar dirilir

çıkarın kınından kılıcı sizde paşalar

yine anadolular alınıp yine canlar verilir

yiğit türk yine namerdi önüne katıp koşar

güngelir yine birçok yurt alırız avrupada

akıtırız namerdin damla damla kanını

çekilirde kılıçlar yeniden kosovada

parçalar yerle bir ederiz bizanslının haçını

yine ufka açılır limandan şanlı gemilerimiz

yüce türk vatanı yaparlar karadenizin içini

makmında gülerek bugün oturanlarımız

inşallah bir gün rezil ederler avrupanın piçini

alırız bizde elimize zamanla amerikanın yakasını

boğazlar önünde yine kopar bir fırtına

askerimiz bozar havalı ingilizin cakasını

yunanın bedenini döndürürüz kalbura

ey türk gençleri iyi öğrenin dersinizi

türk genci aklıyla düşmana saldırandır

vazifemiz çiğnetmemek vatanı

istiklali ulusu koruyup kollamaktır

fatih sultan uyanıp yine tekbir alırda

söndürürüz kafirin kilisedeki mumunu

genç osman iptida alıp bağdat kapısına varırda

çiğneriz ayağımızla fransızı rumunu

yarın alparslan dirilip bize emir verince

anadoluyu tekrar dört baştan aşarız

boynumuz kıldan ince koparırız hepsini

cennetin enüst katında peygamberle yaşarız', 'toprağın bağrında  sıra dağlar gibi duranlar tarih tekerrür ediyor uyanın ey gaflet uykusunda uyuyanlar bir gün olur eski hakanlar dirilir ç...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/vatanin-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahlarım', 'gunahlarim-sair-gokay-e2drx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yıldız daha kayıyor

Uzaklardaki mor dağların ardına.

Bir meşale yanıp yanıp sönüyor

Feleğin çarkı yine kimin boynunda.

Bir hançer gibi saplanıyor bakışları.

Bir elinde cennet gülünden bir demet,

Bir elinde cehennem ateşi

Gidip geliyor ona doğru elleri...', 'Bir yıldız daha kayıyor Uzaklardaki mor dağların ardına. Bir meşale yanıp yanıp sönüyor Feleğin çarkı yine kimin boynunda. Bir hançer gibi s...', ARRAY['Türk Edebiyatı','Şiir','Şair Gökay']::text[], 8.5, '{"poet":"Şair Gökay","poet_slug":"sair-gokay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunahlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Organ Nakli Gibi Sevmiştim Seni', 'bir-organ-nakli-gibi-sevmistim-seni-kucuk-i-skender-zqh00', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir organ nakli gibi sevmiştim seni; 

Çürük gözlerine bağışlanan ellerim, 

Yırtık dudaklarına bağışlanan şiirlerim.. 

Darmadağın kadınların,darmadağın ettiği erkekler gibi 

Sevmiştim seni... 

Çok eskitilmiş bir aşkın hatırlanması, 

Sevgilinin resmi karşısında çocuksu bir iç kanaması 

Aslında işin açıkçası; 

Rüzgarın fırtınaya dönüşmesi gibi 

Hayatına yönelik bombalı bir saldırı gibi 

Geriye çekilirken herkesi öldürmek gibi 

Sevmiştim seni... 

Ruhum kan kaybederken nasıl tutarım seni şimdi deniz gibi, 

Neticesi olmayan herhangi bir sebep gibi 

Ortalık yerde durup dururken 

Sevmiştim seni... 

Atlara kalırsa çoktan kaybettik savaşı, 

Mızraklar kırıldı,kalkanlar delindi,ganimetler paylaşıldı. 

Kasaba meydanında birbirini dövmekten 

Yorulan iki kovboy gibi, 

Bir tabancanın namlusuyla tetiğiyle, 

Kendisinden farklı, 

Kendisinden ayrı, 

Bir silahın şarjöründe tanışan iki soğuk mermi gibi, 

Aynı bedene sıkılan iki el kurşun gibi, 

Katille kurban arasında o birkaç saniyelik telaşla 

Sevmiştim Seni...', 'Bir organ nakli gibi sevmiştim seni;  Çürük gözlerine bağışlanan ellerim,  Yırtık dudaklarına bağışlanan şiirlerim..  Darmadağın kadınların,...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-organ-nakli-gibi-sevmistim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben İçeri Düştüğümden Beri', 'ben-i-ceri-dustugumden-beri-nazim-hikmet-ran-3ampi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben içeri düştüğümden beri güneşin etrafında on kere döndü dünya

Ona sorarsanız: ’Lafı bile edilemez, mikroskopik bi zaman...’

Bana sorarsanız: ‘On senesi ömrümün...’

Bir kurşun kallemim vardı, ben içeri düştüğüm sene 

Bir haftada yaza yaza tükeniverdi

Ona sorarsanız: ’Bütün bi hayat...’

Bana sorarsanız: ‘Adam sende bi hafta...’

Katillikten yatan Osman; ben içeri düştüğümden beri 

Yedibuçuğu doldurup çıktı.

Dolaştı dışarda bi vakit, 

Sonra kaçakçılıktan tekrar düştü içeri, altı ayı doldurup çıktı tekrar.

Dün mektubu geldi; evlenmiş, bi çocuğu olacakmış bah
..........
..........', 'Ben içeri düştüğümden beri güneşin etrafında on kere döndü dünya Ona sorarsanız: ’Lafı bile edilemez, mikroskopik bi zaman...’ Bana sorarsan...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-iceri-dustugumden-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-nurullah-can-phhu7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece birden uyandım

Yanım yörem masmavi

Mavi sularda yıkandım

Seyrettim sevdim kendimi

Artık ben de sevsem ömür boyu

Sevgi sunağında yüzsem

Çılgınca koşsam denize doğru

Mavi bir çevren kesilsem', 'Dün gece birden uyandım Yanım yörem masmavi Mavi sularda yıkandım Seyrettim sevdim kendimi Artık ben de sevsem ömür boyu Sevgi sunağında yüz...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Can']::text[], 8.5, '{"poet":"Nurullah Can","poet_slug":"nurullah-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlem-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsküdar Çeşmesi', 'uskudar-cesmesi-nurullah-can-cy37p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben dalgındım o gün ışık vardı yüzümde

Çok eski bir sevda şiirinde

Şairin unuttuğu bir dizeydim.Soyadım:Hüzün

Martıların sesini sanki ilk kez duyuyordum

Adlarını bilmediğim çiçekleri topluyordum

Kedi yavrularını öpüyor durup durup gülüyordum

Ben dalgındım o gün dünya nedir bilmiyordum

Orda Üsküdar Çeşmesi’nin yanında

Yüzüme ışık vuruyordu dalgındım o gün

Kaçamak bakışlarla süzüyordu beni

Eli elime değmişti.Ilık bir rüzgar esmişti

Bunlar göz değildi artık dudak değildi

Gün geceye dönüyor hep sevdiğimi söylüyordum

O gün dalgındım ben kadın nedir bilmiyordum

Dalgındım ne çok şey konuştuk o gün

Çocukluğumuzu evlerimizi memleketi

Güzel günler düşledik.Kırdılar bizi diyordu

Şiirlerden resimlerden şarkılardan söz ettik

Aşk nedir bilmiyordum o gün dalgındım

Yürümek kuşları seyretmek böyle şeyler

Işık çekiliyordu yüzümden yoksuldum

Çarşılarda vapurlarda tren yollarında

Nedense solgun bir gülümseme oluyordu

Sonra gökyüzünde bir bulut üstünde

Kahkahalar atarak gidiyordu Hezarfen Çelebi

Ben bir yıldız tutmuştum o bir sigara yakmıştı

İçimden Köprü’ye asılmak geliyordu

Sevişmekten yorulmuştuk.İstanbul bize yakışmıştı

O gün dalgındım ben şiirlerimi okuyordum

Sevmezdim soneleri.Haralardan kopan

Kösnük atlar gibi çılgınca koşsunlar

Yorulunca mavi göllerde dinlensinler isterdim

Yıldızlar bastırmıştı şiir nedir bilmezdim

Dalgındım o gece terketti beni

Daha çok sevdim Sadullah Ağa’yı

Gün ağarıyordu.Her şey daha güzeldi.Dediler:

Serinmiş Elhamra Sarayları’nın avluları

Geceleri uzunmuş ağlatırmış şairleri

Sen de öylesin', 'Ben dalgındım o gün ışık vardı yüzümde Çok eski bir sevda şiirinde Şairin unuttuğu bir dizeydim.Soyadım:Hüzün Martıların sesini sanki ilk ke...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Can']::text[], 8.5, '{"poet":"Nurullah Can","poet_slug":"nurullah-can","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/uskudar-cesmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-faruk-aysoy-7o9q0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu akşam geziyorum İstanbul''da,

Karanlıklar içinde Laleli''de,

Bir ses duydum, çocuk sesi,

Beyoğlu''nda ise eğlence sınırsızca,

En son hatırladığımsa bir ışık,

Bir araba farı... Sonrası ise karanlık

Taa ki gözümü açıncaya kadar hastanede,

İlk söylediğimse, ilk sayıkladığımsa senin adın,

Yani ne kadar gezsemde, ölümden dönsemde,

Unutamadığım adın, senin adın: ''Gönül Sesi''...', 'Bu akşam geziyorum İstanbul''da, Karanlıklar içinde Laleli''de, Bir ses duydum, çocuk sesi, Beyoğlu''nda ise eğlence sınırsızca, En son hatırla...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yegane Umudum', 'yegane-umudum-faruk-aysoy-upija', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaderin sonsuzluğunda,

Yaşamın sonbaharında,

Karanlığın son ışığında,

Sen benim yegane umudumsun.

Aşkın yenilmezliğinde,

Hırsın kurnazlığında,

Güzelliğin gücünde,

Sen benim yegane umudumsun.

Zamanın akılalmazlığında,

Aklımın her köşesinde,

Kalbimin en derinlerinde,

Sen benim yegane umudumsun...', 'Kaderin sonsuzluğunda, Yaşamın sonbaharında, Karanlığın son ışığında, Sen benim yegane umudumsun. Aşkın yenilmezliğinde, Hırsın kurnazlığınd...', ARRAY['Türk Edebiyatı','Şiir','Faruk Aysoy']::text[], 8.5, '{"poet":"Faruk Aysoy","poet_slug":"faruk-aysoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yegane-umudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk', 'dostluk-oguz-atalay-ec7o9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim dostluğum dağlar,

Benim dostluğum denizler,

Benim dostluğum yürekler dolusudur.

Dünya yıkılsa gelse ayağa

Yıldızlar sönse düşse dünyaya

Bu dostluk asla bitmez unutma...', 'Benim dostluğum dağlar, Benim dostluğum denizler, Benim dostluğum yürekler dolusudur. Dünya yıkılsa gelse ayağa Yıldızlar sönse düşse dünyay...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Atalay']::text[], 8.5, '{"poet":"Oğuz Atalay","poet_slug":"oguz-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dostluk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-hayrettin-tarhan-devp0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hadi gel artık;

Uzakları yakın eyle.

Avuç dolusu deniz kokuları getir,

İçinde senin kokunda olsun.

Martı çığlıklarını getir,

Sevgimizi taşısın bütün gemiler.

Deniz kızlarının çığlıkları içinde,

Birde senin sesin olsun.

Hadi gel artık;

Bitsin bu hasret.

Uzat ellerini ak denizden,

Avuçlarında demet demet, 

Portakal çiçekleri olsun.

Hadi gel artık;

Bak yıldızlara her gece,

Yalnızlığımı sor onlara.

Yıldızlar şarkılar söylesin,

O şarkıların hepsi bizim olsun.', 'Hadi gel artık; Uzakları yakın eyle. Avuç dolusu deniz kokuları getir, İçinde senin kokunda olsun. Martı çığlıklarını getir, Sevgimizi taşıs...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-artik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erciyes', 'erciyes-arif-atalay-5nmog', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey erciyes neden bakıyorsun bana tepeden

                 Ben zaten yaralıyım yürekten, 

                 Sen anlamazmısın garibin halinden? 

                  Derdime ortak olmaz mı senden? 

                 Anlıyorum yalnızlık senin de derdin, 

                 Bu yüzden dumanlıdır hep başın senin, 

                 Dağıt artık şu dumanı bitsin kederin, 

                 Başı dumanlı garip erciyes! 

                  

                 Yücelerde gezersin hep böyle 

                 Alçaklarda gözün neden söyle? 

                 Kaptırmışsın gönlünü bir güzele

                 Dağıt şu dumanı, dağıt ERCİYES! ! !', 'Ey erciyes neden bakıyorsun bana tepeden                  Ben zaten yaralıyım yürekten,                   Sen anlamazmısın garibin halinden?...', ARRAY['Türk Edebiyatı','Şiir','Arif Atalay']::text[], 8.5, '{"poet":"Arif Atalay","poet_slug":"arif-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/erciyes-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum Düşler', 'masum-dusler-mahmut-kuru-kw26v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'rüyalarda yüzme arzusu tüm bedenimde

zorlu yokuşlarında tırmanmak düşlerin

en kutsal duygu adına her şey

hepsi sevgi adına masumca iffetli

senin için delice fedakarlıklar yaşamdan

boş mutluluklara bir rest benimkisi

masum küçük bir kızsın 

kandırılmaya alışık

bu diyarların yabancısı

saf düşlerine katıldım istemeden 

bir parçası oldum aniden oyunun

vazgeçilmez bir oyun başlamıştı

artık dönüşü olmayan

deli bir yaşamın sakinleri olduk

hayaldi belki her şey

ama gerçek bir sevginin üstünde

biz gerçektik

sevgimiz de 

buna aşk diyemedik bir süre

korktuk, biz korkutulmuştuk mutluluk yolunda

geçmişimiz vardı engebeli

bir çırpıda silinemeyecek kadar yüklü

masum küçük bir kız vardı

ve hayalleri

biz kahramanları olduk bu düşün

susamışlığımız sürüklemişti bu yola

çıkmaz bir sokakta ilerliyorduk

her şey hayaldi belki ama

masumca hayalleri seviyorduk

küçük kızı da

korkmuştuk bir kere hayattan

çektiklerimiz yeterdi gerçeklerden

ağlamayı bile unutmuştuk

kahkahaların örttüğü gözlerimiz suskundu

uzunca zamanlar boyu

sahte bir yaşamın bize sundukları

kötüydü çirkindi her şey

yorulmuştuk, dinlenmeliydik artık

küçük kız çıktı karşımıza

ve masumca düşleri

hiç düşünmeden atladık denize

sırılsıklam olduk ıslandık

düş yağmurlarında

ama sevdik işte

bu oyunu

uzunca bir zaman oynadık yorulmadan

her şey hayaldi belki

küçük masum bir kızın

ama biz gerçektik

sevgimiz de

aşk diyemedik, korkuyorduk 

aşık olmaktan, tadı acıydı

hatırladığımız zamanlardan kalma

unutmak istedik hep kaçtık ondan

bizde bıraktığı kötü izlerden

ama o masum kız çıktı karşımıza

ve düşleri

bize aşkı tekrar gösterdi

kaçılamayacak kadar yakın olan

acısından bile lezzet alınan

aşkı düşlerde öğretti

küçük kız bir düş kurmuştu

ben prens oldum çöllerde

güller mesaj taşıdı ötelerden

her şey hayaldi belki ama

küçük kız gerçekti

güller de

mesafeler bile yok olmuştu

ayrıydık uzak şehirlerden

ayrılmamıştık aslında hiçbir zaman

yanyana konuştuk geceler boyu

elele durduk bazen sıcaklığı hissettik

sustuğumuzda bile konuştuk durmadan

düşlerden bir köprü kurduk

ayrı yaşamlara 

biz mi konuştuk düşlerimiz mi

belki her şey bir hayaldi

ama aşkımız gerçekti

küçük kız gibi...

22.06.2001-Dilovası', 'rüyalarda yüzme arzusu tüm bedenimde zorlu yokuşlarında tırmanmak düşlerin en kutsal duygu adına her şey hepsi sevgi adına masumca iffetli s...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/masum-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Mevsim', 'kac-mevsim-mevlut-serttas-0vw53', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmem kaç mevsim geçti

Sen olmadan

Kaç gece ağladım

Sana sımsıkı sarılmadan

Kışın üşüyen ellerimi 

Senin sıcak hayalinle ısıttım

Kimbilir kaç gece...

Kaç gece yıldızlara bakıp fal tuttum

Her yattığımda senin adını sayıkladım

Kaç gece seni sevdiğim için

Kendimle gurur duydum

Bilmem kaç mevsim geldi geçti

Sen olmadan

Ayları, günleri, saatleri saydım

Sensiz söyledim şarkıları

Sensiz başladım yeni bir güne

Sensi nefes alabildim

Kimbilir kaç gece...', 'Bilmem kaç mevsim geçti Sen olmadan Kaç gece ağladım Sana sımsıkı sarılmadan Kışın üşüyen ellerimi  Senin sıcak hayalinle ısıttım Kimbilir k...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Serttaş']::text[], 8.5, '{"poet":"Mevlüt Serttaş","poet_slug":"mevlut-serttas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kac-mevsim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozlu Kelimeler', 'tozlu-kelimeler-mehmet-calik-16r0b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dün gece

yıllar önce

tavan arasına kaldırdığım

kelimelerin tozunu aldım

oldukca yıllanmışlardı

iki kelimeyi

el ele tutturup 

bir cümle kurdum da

diyecek insan bulamadım', 'dün gece yıllar önce tavan arasına kaldırdığım kelimelerin tozunu aldım oldukca yıllanmışlardı iki kelimeyi el ele tutturup  bir cümle kurdu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çalık']::text[], 8.5, '{"poet":"Mehmet Çalık","poet_slug":"mehmet-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tozlu-kelimeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok', 'adi-yok-asli-atabay-zgbnf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çoktan uzaklaştım bıraktım

bir yerlerde

unuttum seni aşk hatırlat

kendini bana

sesimde yok saydığım tenimde

biraz yalan oysa kaygısızdım

her an

aşk hatırlat kendini bana

farkında değilim sanma

anımsarım ışığını

Zor da olsa lakin duvarlarım

sanırım

altında kalırım

aşk gözlerine bakamıyorum

hatırlat kendini bana

göremediklerim kime ait bulamıyorum

bana ait bir çift boşlukla kalıyorum

kapasam da tüm kapıları sana

aşk

kapı yok çırılçıplak

kalıyorum

görünmez duvarlar bulup

yaslanmak istiyorum

ama içimde duvar yok

yıkılıyorum

ey aşk hatırlat kendini bana

çağırıyor musun

geliyorum

biliyor musun değişiyorum.', 'Çoktan uzaklaştım bıraktım bir yerlerde unuttum seni aşk hatırlat kendini bana sesimde yok saydığım tenimde biraz yalan oysa kaygısızdım her...', ARRAY['Türk Edebiyatı','Şiir','Aslı Atabay']::text[], 8.5, '{"poet":"Aslı Atabay","poet_slug":"asli-atabay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/adi-yok-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ne Biçim Devran?', 'bu-ne-bicim-devran-ozan-arif-k916b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu ne biçim devran,bu ne biçim iş?

Her gelen bir hava atmaya kalktı.

Hele bunlar hepten sıfır hiçimiş;

Peşrevsiz makamsız ötmeye kalktı.

Biri Erzurum''da hacı kesildi!

İzmir''de zamane pici kesildi.

Hepsi bana bilmem neci kesildi

Putun gölgesinde yatmaya kalktı.

Aha işte gördünüz mü arıyı?

Hele hele yanındaki karıyı

Eski çoban bırakınca sürüyü

Köpeklek zağarlar gütmeye kalktı.

Ne imişte ekonomi mimarı!

Adam sırf et yok gardaşım damarı

Tam ağzına vuracaksın şamarı

Fakiri kenara itmeye kalktı.

Bu sanmıştık gelenlerin düzgünü

Meğer herif azgınların azgını

Tüysüz tüysüz yetimlerin rızgını

Lop diye yemeye,yutmaya kalktı.

Ne yaptı bir yere çivi mi çaktı?

Yoksa bir zincire halka mı taktı?

Köprüden başladı barajdan çıktı

Memleketi toptan satmaya kalktı.

İz değil bunların gittiği izler

Arif der Allah''a havale bizler

Avradını idareden acizler

Devleti idare etmeye kalktı.', 'Bu ne biçim devran,bu ne biçim iş? Her gelen bir hava atmaya kalktı. Hele bunlar hepten sıfır hiçimiş; Peşrevsiz makamsız ötmeye kalktı. Bir...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bu-ne-bicim-devran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidebilmek Rüyası', 'gidebilmek-ruyasi-orhan-balta-xijh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çekip gidecegim bir gün buralardan 

geride herkesi herseyi bırakarak. 

gözyaslarımı saklayacagım içime akacak.. 

yüregimde saplı acın gibi. 

Bir küçük sahil kasabasında.. 

bahçesinde salkım sögütlerin oldugu. 

tek göz odalı evimde, 

küçük bir insan gibi yaşayacagım.. 

kocaman yüregime ragmen. 

Sevmelerim olmayacak..sevişmelerimde.. 

ama seni düsünmekten asla vazgeçmeyecegim!! 

Sabahları erkenden balıga çıkarım.. 

eskimiş agaç teknemin gidebildigi yerlere. 

oltalarımı saldıgımda Denize.. 

aksam neler yasayacagımı hayal ederim, 

(belkide yine sen gelir oturursun baş köşeme) 

Bir iki dostum gelir..hem balık yemeye.. 

iki kadeh rakıda rakidaki sohbette buluşmaya.. 

anoson kokulu dudaklarımdan.. 

hazin bir ayrılık türküsü dinlemeye 

(iste gidiyorum çesmi siyahim...) 

yada.. 

denizde kaçırdıgım okocaman balığın hikayesine. 

hele sıkıstırırlarsa.. 

o kocaman gözlü,dalgalı saçlı yüreğime hançer gibi saplanan bakışlı.. 

güzel kızın bana bakışlarını yakaladığımdaki.. 

yere tökezleyip düştüğüme gülmeye. 

sonra geç vakitler.. 

artık herkes kalkıp gitmeli kendi dünyasına, 

beni bıraksala benimde gidecek yerim var ama.. 

hayır..hayır..ben en doğrusu... 

YÜREĞİN..saydıgım tek göz odama gireyim.. 

Seninle başbaşa kalmanın hazzında.. 

sensiz... 

sesinsiz..', 'Çekip gidecegim bir gün buralardan  geride herkesi herseyi bırakarak.  gözyaslarımı saklayacagım içime akacak..  yüregimde saplı acın gibi. ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gidebilmek-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyumak İstiyorum', 'uyumak-i-stiyorum-orhan-balta-zefsd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyumak istiyorum..

seni düşünmekten yoruldum artık..

morfin yemiş hasta gibiyim..

bedenim uyuşuk..beynim ayakta..

karanlığa gömüyorum kendimi

yüreğim ışık ışık..

uyumak istiyorum..

seni düşünmekten yoruldum artık..

areneda yaralı bir gladyatör gibiyim..

kanım akmıyor ..

ama canımın yandığını hissediyorum..

uyumak istiyorum..

seni düşünmekten yoruldum artık.

cudi dağında bir mağarada,kaçak gibiyim

en ufak bir seste her yanım ayakta.

kimse yok etrafımda biliyorum..

bir kalabalık üstüme geliyor..

uyumak istiyorum..

seni düşünmekten yoruldum artık..

göğsümde kanat sesleri..gözlerimde işveli bir lacivert..

her yanımda sen..herşeyimde sen..

ölmek istemiyorum..

seni sevmekten mutluyum artık.', 'Uyumak istiyorum.. seni düşünmekten yoruldum artık.. morfin yemiş hasta gibiyim.. bedenim uyuşuk..beynim ayakta.. karanlığa gömüyorum kendim...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/uyumak-istiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Yağdığında Ben', 'kar-yagdiginda-ben-orhan-balta-r8wvl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kar yağdığında ben  dağbaşlarını severim..

esen rüzgarda sen olursun..

alır seni bana getirir

sana sarılmanın hazzını yaşarım..

seninleyimdir.

kar yağdığında ben sokakları severim

her pislik yok olur.

her yanda bembeyaz papatyalar açar

çiçek çiçek kokan yine sen olursun

gülümseyen yüzünle.

kar yağdığında ben yaylaları severim

üşüyen elerimdir..yüreğim sıcacık

sevginle doludur.

kar yağdığında ben ağaçları severim..

bir gelin edasıyla tacı başında

bana gelişini anımsatır.

kar yağdığında ben....

 ocak başlarını sevmem

değdiğinde ateş..yakar canımı sensizliğim olur...

ölürüm....

kar yağdığında ben kendimden nefret ederim..

sıcak bir odada kendi hayallerimde kalmaktan..! ! ! ! ! !', 'kar yağdığında ben  dağbaşlarını severim.. esen rüzgarda sen olursun.. alır seni bana getirir sana sarılmanın hazzını yaşarım.. seninleyimdi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kar-yagdiginda-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-orhan-balta-n8xvw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman sunuldu yaşam bize.. 

avuçlarımizda çiçek gibi. 

ve ne zaman yaşadıklarımız.. 

yaşamak istediklerimizdi. 

Kah bir bulut olduk gökyüzünde ap ak.. 

kah bir bulutta yagmur damlası..ıp ıslak.. 

bazen yaprak olduk ulu bır çınarın dallarında.. 

yıllar sarartı rengimizi.. solduk.. 

rüzgar savurdu..döküldük.. 

kuru bir gazel olduk....yandık.. 

belkide.... yarin mangalında.. 

ama sevdalarımız taze kaldı eskimedi.. 

antik bir acı gibi yüreğimizde.', 'Ne zaman sunuldu yaşam bize..  avuçlarımizda çiçek gibi.  ve ne zaman yaşadıklarımız..  yaşamak istediklerimizdi.  Kah bir bulut olduk gökyü...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasam-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşasın Cumhuriyet', 'yasasin-cumhuriyet-ozan-arif-tycwt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Altmışbirinci yılı

Yaşasın Cumhuriyet

Biz de çalak kavalı

Yaşasın Cumhuriyet

Altmışbir yıl övdüğüm

Davulunu dövdüğüm

Hay gözünü sevdiğim

Yaşasın Cumhuriyet! 

Çok şükür dipdiriyiz

Kim demiş ki geriyiz? 

Yamyamdan ileriyiz

Yaşasın Cumhuriyet! 

Kulaklarım duymasın

Duyup ele uymasın

Varsın karnım doymasın

Yaşasın Cumhuriyet! 

Yoksa bir suyum yoktur

Başka da neyim yoktur

Heykelsiz köyüm yoktur

Yaşasın Cumhuriyet! 

Köyde herşey şahane

Enerji yok, bahane

Tezek var ya daha ne

Yaşasın Cumhuriyet! 

Ne ararsan ara bol

Ceryan yoksa çıra bol

Su mu yoktur bira bol

Yaşasın Cumhuriyet! 

Meyhane, kerhane bar,

Gidene camii de var.

Biz laik''iz o kadar

Yaşasın cumhuriyet! 

Bu devir neşe devri,

Ye, iç, yat, yaşa devri

Sultan yok paşa devri

Yaşasın Cumhuriyet! 

Azerbaycan yetimmiş

Batı Trakya kimmiş? 

O işler eskidenmiş

Yaşasın Cumhuriyet! 

Kerkük Musul şu anda

Boğulsun varsın kanda

Sulh var yurtta cihanda

Yaşasın Cumhuriyet! 

Ya bu terör kargaşa

Canım gardaş gardaşa

Kapılmayın telaşa

Yaşasın cumhuriyet! 

Arif be artık yetsin

Bu destan burda bitsin

Allah bizi affetsin

Yaşasın cumhuriyet!', 'Altmışbirinci yılı Yaşasın Cumhuriyet Biz de çalak kavalı Yaşasın Cumhuriyet Altmışbir yıl övdüğüm Davulunu dövdüğüm Hay gözünü sevdiğim Yaş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yasasin-cumhuriyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Felsefesi ve Sen', 'askin-felsefesi-ve-sen-i-sa-seker-i7vca', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tarih bana seni hatırlatır günün her anında,

Zamanım hayâl kütüphânende geçer arşiv sayfalarında.

Coğrafyayla bulurum nerede olduğunu,elimde pusula

Haydi şu karadeniz ikliminle yanaklarımı bir sula

Derdimi sosyoloğa açamam öyle herkesin ortasında.

Psikoloji yer bulamaz ona hastalıklar haritasında.

Sahi seninle ilk tanışmamız fizik bölümündeydi değil mi?

Hani o güzel gözlerinden yansıyan ışınlar hoşuma gitmişti.

Senle aramızdaki kimyayı hâlâ çözebilmiş değilim.

Şimdilik biyolojiyle de işimizin olmasını istamem

Keşke matematikten kalsak yalnız sen ,ben

Galiba şu kullandığım Türkçede de hayır yok,

Bana aşkın felsefesi lâzım, bir de filozof.', 'Tarih bana seni hatırlatır günün her anında, Zamanım hayâl kütüphânende geçer arşiv sayfalarında. Coğrafyayla bulurum nerede olduğunu,elimde...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askin-felsefesi-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sevdaydı', 'bir-sevdaydi-orhan-balta-595hk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevdaydı hasretin

küçük bir gülüş..sevdalı bir öpüştü vuslatın

yaramaz bir çocuktu bakışların

kocaman dı sevişmelerin gülüm..

kaprisin kinin nefretin olmadı,

belki tanımıyordun onları,

tanıştırılmamıştın bire bir.

yüreğinde sevda, gönlünde umut,

gözlerinde şafak bekledin.

kara gecenin koynunda ellerinde düş çiçeği,

sevdayı özledin.

varsın karanlık kalleş olsun..

umutlar salkım saçak.

sevdaya giden yolu bulmalısın bilmelisin ..ceylanım

uzun kavgalar sonunda gelir 

özlenen günlerimiz,

kimbilir belki dağlarımızın,

mavi bir deniz gibi dalgalanan ormanında,

kuşlar kadar özgür türküler söyleriz,

belkide...

yüksek ağaçlar üzerinden göz kırpan güneşe bakıp..

sessiz kalırız..gülüm...

derinmavimden seher yeline', 'Bir sevdaydı hasretin küçük bir gülüş..sevdalı bir öpüştü vuslatın yaramaz bir çocuktu bakışların kocaman dı sevişmelerin gülüm.. kaprisin k...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-sevdaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sol Elim', 'sol-elim-orhan-veli-kanik-ai04x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarhoş oldum da

Seni hatırladım yine;

Sol elim,

Acemi elim,

Zavallı elim!', 'Sarhoş oldum da Seni hatırladım yine; Sol elim, Acemi elim, Zavallı elim!...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sol-elim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılcık', 'kizilcik-orhan-veli-kanik-54td7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk yemişini bu sene verdi

Kızılcık

Üç tane;

Bir daha seneye beş tane verir

Ömür çok,

Bekleriz;

Ne çıkar?', 'İlk yemişini bu sene verdi Kızılcık Üç tane; Bir daha seneye beş tane verir Ömür çok, Bekleriz; Ne çıkar?...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kizilcik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-orhan-veli-kanik-03cq6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bardak boşalır bencileyin dolmayı bilmez

Benzim gibi yaprak sararıp solmayı bilmez

Hiçbir şey canımca feda olmayı bilmez

Canım senin uğrunda feda olmak içindir!', 'Bardak boşalır bencileyin dolmayı bilmez Benzim gibi yaprak sararıp solmayı bilmez Hiçbir şey canımca feda olmayı bilmez Canım senin uğrunda...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sarki-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyarlık', 'i-htiyarlik-orhan-veli-kanik-uesa9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim, bardağın, sürahinin,

Önümüzdesin; rengin uçmuş,

Bu; eski, sevdiğim bir duruş

Elin, içinde benimkinin.

İçelim! Madem ömrümüz hoş

Geçmiş, tatmamışız ayrılık; 

Madem ne bardağımız kırık,

Madem ne sürahimiz boş.

Bir gün ikimizden birimiz

İçmek veya doldurmak için

Burada olmayabiliriz.', 'Benim, bardağın, sürahinin, Önümüzdesin; rengin uçmuş, Bu; eski, sevdiğim bir duruş Elin, içinde benimkinin. İçelim! Madem ömrümüz hoş Geçmi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ihtiyarlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ölüm', 'olum-cevahir-evren-7jwa8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bugün kuzenimi kaybettim

nerelerdedir şimdi

cennet var mı, yoksa 

toprak ana ona sahip çıkıyor mu?

dört harf iki hece

ölüm...

onu daha şimdiden çok özlüyorum

belki de sonsuza kadar hiç bu kadar özlemeyceğim,

bugün kuzeni mi kaybettim

onu bulamıyorum...', 'bugün kuzenimi kaybettim nerelerdedir şimdi cennet var mı, yoksa  toprak ana ona sahip çıkıyor mu? dört harf iki hece ölüm... onu daha şimdi...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-halil-i-brahim-guncan-bsz55', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben düşündüm bulamadım yollarım,

Ne olur çıkar yol bul Yüce Tanrım.

Elim açık havadadır kollarım,

Bu garip sana bak kul Yüce Tanrım.

Bana ümit veren senin kudretin,

Günahım ne, niye bana hiddetin,

Yetsin gayrı bize de ver rahmetin,

Rahmetin bu kadar bol Yüce Tanrım.

Garip kaldım, hiç kimseler bilmiyor,

Zalim kader bana neden gülmüyor,

Derdime kimseler derman olmuyor,

Derdimin dermanı ol Yüce Tanrım.

Uzak kaldım yardan, yurttan, sıladan,

Biliyorum sensin bizi yaradan 

Bütün ümidimi yitirdiğim an,

Bekliyom imdada gel Yüce Tanrım.', 'Ben düşündüm bulamadım yollarım, Ne olur çıkar yol bul Yüce Tanrım. Elim açık havadadır kollarım, Bu garip sana bak kul Yüce Tanrım. Bana üm...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Güncan']::text[], 8.5, '{"poet":"Halil İbrahim Güncan","poet_slug":"halil-i-brahim-guncan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dua-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm 2', 'olum-2-halil-i-brahim-guncan-eq8gv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne dahi, ne filozof, ne de başka biri,

Böyle yazmış bu yazıyı yaradan.

Çırpınırız deryada bir karınca gibi,

Bir gün daha yaşamak için fazladan.

	Çalar bir gün Azrail kapımızı,

	Diyerek “davet var gaipten”,

	Gözyaşlarına aldırmadan alır canımızı,

	Kim kurtulmuş ki ölümden.

Bir ıslak öpücük dudaklarında,

Soğuk musalla taşından.

Mezarcılar bir çukurun başında,

Yorulmuş ekmek savaşından.

	Uğraşma açılmaz çürümüş dudakların,

	Dünyalılar duymaz sesini.

	Dindiremez arşa çıksa feryadın,

	Ölümün öfkesini.', 'Ne dahi, ne filozof, ne de başka biri, Böyle yazmış bu yazıyı yaradan. Çırpınırız deryada bir karınca gibi, Bir gün daha yaşamak için fazlad...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Güncan']::text[], 8.5, '{"poet":"Halil İbrahim Güncan","poet_slug":"halil-i-brahim-guncan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz''e Doğru', 'karadeniz-e-dogru-halil-i-brahim-guncan-xxkf5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sonbahar akşamı başladı yolculuğum,

Yeşiller bir bir sararıp soluyordu.

Merakla beklediğim Abana yolu,

Tekerler döndükçe kısalıyordu.

	Geceyle sessizlik çöktü her yere,

	Sağımız sıradağ solumuz dere,

	Güneş yükselirken mavi göklere,

	Yorulmuş yolcular sahile iniyordu.

Kavuştum nihayet Karadeniz’e,

Hasretle yandığım soluk benize,

Bu rüzgar, bu koku, bu sesler bize,

Esir Türk illerinden dert getiriyordu.

	Gittikçe küçüldü kumda adımlar,

	Ancak Türk olanlar bu halden anlar,

	Beyaz umutlarla gelen martılar,

	Düş kırıklığıyla uzaklaşıyordu.

Ben böyle ufukta gözleri bağlı,

Kalplerde bu hasret yıllardır dağlı,

Düğüm düğüm gırtlağımda bir ağrı,

Yaşlar yanaklardan süzülüyordu.

	Gözümde canlandı Hanlar Giraylar,

	Nerde Tuna, nerde İdil, Volgalar,

	Hasretle gürleyen coşan dalgalar,

	Boynunu büküyor kahroluyordu.

Kırım, Kırım kırılsın bu zincirler,

Akmescitte ötmüyor bak bülbüller,

Sibirya da dillenen tüm bebekler,

Sivastopol marşını heceliyordu.

	Cemiloğlu, Cengiz Dağcı, Aytmatof,

	Ne bitmez çileymiş, of Allah’ım of,

	Ettiğin yanına kalır mı Moskof,

	Şamil’in erleri diriliyordu.', 'Bir sonbahar akşamı başladı yolculuğum, Yeşiller bir bir sararıp soluyordu. Merakla beklediğim Abana yolu, Tekerler döndükçe kısalıyordu. 	G...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Güncan']::text[], 8.5, '{"poet":"Halil İbrahim Güncan","poet_slug":"halil-i-brahim-guncan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/karadeniz-e-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Tasası', 'yalnizligin-tasasi-halil-i-brahim-guncan-lw7f5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tak tak ayak sesleri kaldırımlar üstünde,

Yollara sarılmışım yılan gibi giderim.

Tanıyamazsın beni yeniden gördüğünde,

Mor çukurlar dibinde feri solmuş gözlerim.

	Ararım sokaklarda kaybettiğim yılları,

	Sıcak pencerelerden ışıklar gülümserken,

	Sımsıkı kucaklarken karanlığın kolları,

	Başlasın yalnızlığım eller eve giderken.

Minarelerde ezan sesleri yankılanır,

Aralık pencereden bir çocuk ağlaması,

Adımlarım yavaşlar gözlerim dumanlanır,

Titretir yüreğimi yalnızlığın tasası.', 'Tak tak ayak sesleri kaldırımlar üstünde, Yollara sarılmışım yılan gibi giderim. Tanıyamazsın beni yeniden gördüğünde, Mor çukurlar dibinde ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Güncan']::text[], 8.5, '{"poet":"Halil İbrahim Güncan","poet_slug":"halil-i-brahim-guncan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizligin-tasasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aheste Aheste Ölüm', 'aheste-aheste-olum-gokhan-ulker-zykn1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İdamı bekleyen bir suçluyum…

Son isteğimin sorulmasını bekliyorum,

Son sözümün ne olacağını merak ediyorum…

Son saatlerimi yaşıyorum…ahestee aheste… 

İdamı bekleyen bir suçluyum…

Son isteğimin sorulmasını bekliyorum,

Son sözümün ne olacağını merak ediyorum…

Son saatlerimi yaşıyorum…ahestee aheste… 

Ölümün nedemek olduğunu şimdi daha iyi anlıyorum…

Karanlık karanlık karanlık…

Korkma karanlıktan be adam ,ölümden korktuğun kadar…

Ne karanlıklar gördük biz …hepsi geçti….aheste aheste….

Dudaklarımda donuk bir sızı,

Ellerimdeki kansız damarlar,

Gözlerim titrek bir kıvılcım

Kalbim bir ateş topu…

Artık düşünecek tek şey war…

Gideceğim yer gerçekten karanlıkmı?

Yoksa iğrenç kuşlarmı uçuşuyo…

Gerçek güneş doğuyormu?

Sanane be adam!

Ordada kalıcı değilsin

Her yolun bir sonu wardır…

Bu Dünyadakininde bu sandalyeymiş işte…

Ordakininde bir başka nesne…

Hayat budur işte!

Kalır bir kerestenin eline.

Yalvaramazsında yaşat beni diye

Dinleyen olmaz seni…

Devam eder işine …aheste aheste……..

Enjekte eder vücuduna zehiri

İşte en can alıcı kısmı budur hayatın…

Onca yıl çürüttün kendin için

Geçer o çürümüş mazi, gözünden

Aheste aheste…

Bumudur özgürlükdersin içinden ilk beş dakika

Bumudur yaşama özgürlüğü…

Bağıramazsın gururuna yadiripte…çırpınamazsın…

Ölümün soğuk nefesi suratını serinletmeye başlar ,aheste aheste….

Geçersin ikinci beş dakikaya…son beş dakika dersin kendi kendine…

Elinde olmadan…reflexlerin kudurmaya başlar…tutamazsın bu çılgın vücudu…

Kaparsın gözlerini…bir el sallamak istersin…son defa dünyaya….

Ya sallarsın ,ya sallıyamazsın…

İşte budur hayat……geçeeer aheste ahestee…!!!', 'İdamı bekleyen bir suçluyum… Son isteğimin sorulmasını bekliyorum, Son sözümün ne olacağını merak ediyorum… Son saatlerimi yaşıyorum…ahestee...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Ülker']::text[], 8.5, '{"poet":"Gökhan Ülker","poet_slug":"gokhan-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/aheste-aheste-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanımız', 'sultanimiz-halil-i-brahim-guncan-c0ucq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alemlere rahmetsin sen,

Ya Muhammed Mustafa.(SAV)

Arş-ı âlâdadır rütben,

Ya Muhammed Mustafa.(SAV)

Sen, sohbet-i Kur’an’sın Sen,

Sen, rahmet-i Rahmansın Sen,

Biçareye dermansın Sen,

Ya Muhammed Mustafa.(SAV)

Yoktur dünyada bir eşi,

İki cihanın güneşi,

Kalplerimizde  ateşi,

Ya Muhammed Mustafa.(SAV)

Sana layık olamadık,

Sünnetinde kalamadık,

Biz yolunda ölemedik,

Ya Muhammed Mustafa.(SAV)

Aynı dünyadaki gibi,

Ahret de bırakma bizi,

Derman eyle derdimizi,

Ya Muhammed Mustafa.(SAV)

Biz günahkar, bîçareyiz,

Ahir zaman, avareyiz,

Aşkın ile divaneyiz,

Ya Muhammed Mustafa.(SAV)

Ezanlarda, selâmızda,

Zikirlerde, duamızda,

Mühür ol sen alnımızda,

Ya Muhammed Mustafa.(SAV)', 'Alemlere rahmetsin sen, Ya Muhammed Mustafa.(SAV) Arş-ı âlâdadır rütben, Ya Muhammed Mustafa.(SAV) Sen, sohbet-i Kur’an’sın Sen, Sen, rahmet...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Güncan']::text[], 8.5, '{"poet":"Halil İbrahim Güncan","poet_slug":"halil-i-brahim-guncan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sultanimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Öğretmenim', 'sevgili-ogretmenim-halil-i-brahim-guncan-cir59', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neler öğrettin bana,

Sevgili öğretmenim.

Ne yapsam azdır sana,

Sevgili öğretmenim.

	A, B, C’yle başlattın,

	Hayatıma renk kattın,

	Dünyamı aydınlattın,

	Sevgili öğretmenim.

Dün Zühal’din, İnci’ydin,

Bugün Ebru’dur ismin,

Bana bir dünya verdin,

Sevgili öğretmenim.

	Günaydın diyen sesin,

	Sımsıcaktır nefesin,

	Destansın, efsanesin,

	Sevgili öğretmenim.', 'Neler öğrettin bana, Sevgili öğretmenim. Ne yapsam azdır sana, Sevgili öğretmenim. 	A, B, C’yle başlattın, 	Hayatıma renk kattın, 	Dünyamı a...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Güncan']::text[], 8.5, '{"poet":"Halil İbrahim Güncan","poet_slug":"halil-i-brahim-guncan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgili-ogretmenim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih 17 Ağustos 1999', 'tarih-17-agustos-1999-gokhan-ulker-g1m20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tarih 17 ağustos 1999…

Sıcak bir günde, kavruluyordu sanki insanlar,

Bırakmışlardı kendilerini bazıları,

Yazın bencilliğine, güzelliklerine…

Güzel bir gündü her halikarda.

Bütün insanlar,güle oynaya…

Ewet güle oynaya…nerden bilinebilirki bu facia?

Yıkıcak geçicekti bazı mekanlardan…

Yavaş yavaş güneş batıyordu…

Günün tüm güzelliklerini arksaına alarak.

Birden hızlandı…Sanki bir acelesi wardı!!!

Kim bilir?belki en büyük suçu işliyordu…

Güneşde battı artık…

Ortam gitgide hazırlanıyordu!

Çekildi yerli halk evlerine,

Kimileri ise bilinmezlere…

Eh artık!yatma vakti gelmişti bazıları için…

Diğerleri için bilinmezliğe devam!

Bi kaç saat sonra olucakları bilmeden,

Geçiriyorlardı zamanlarını, aheste aheste….

Evet ortam iyice kızışmıştı…

Artık tek bir şey kalmıştı!

Saatin …vaktin yaklaşması…

Yelkovan süzülüyoru aheste aheste…

Milyonlara acımadan…

Bir dakika kalmıştı…

Kimileri yataklarında son haraketlerini,

Kimileri son sözlerini,

Kimileri duygularını açmayı …

Belkide son kez göz kapaklarını kapamayı düşünüyorlardı ki…

İşte tam o sırada…tam o sırada ,

Hayat ve ölüm arasındaki ince çizgiden ,sınırdan ,

Hangi tarafa geçmek istediklerini şaşırdılar bazıları…

Hayatlarındaki en önemli karardı bu…

Ve verdikleri kararlar, herşeyin geride kalmasını ,

Yada bu dünyada hala var olduklarını gösterecekti!

Ama onlar daha hazır değildi…

Son bir şans istediler!!!

Ama ,ama ,olmadı…

Onların herzaman için bu dünyadan göçmeye hazır olmaları gerekirdi.

Ve tek suçlarıda buydu!!!', 'Tarih 17 ağustos 1999… Sıcak bir günde, kavruluyordu sanki insanlar, Bırakmışlardı kendilerini bazıları, Yazın bencilliğine, güzelliklerine…...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Ülker']::text[], 8.5, '{"poet":"Gökhan Ülker","poet_slug":"gokhan-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/tarih-17-agustos-1999-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ondokuz Mayıs (19 Mayıs)', 'ondokuz-mayis-19-mayis-halil-i-brahim-guncan-ar066', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seksen dokuz yıl evvel,

Türklüğün içi yandı.

Birleşti yedi düvel,

Ankara’ya dayandı.

Saldırdı kahpe Yunan,

Anadolu uyandı.	

O, öyle bir zor zaman,

Öyle zor bir zamandı.

Ne top vardı, ne tüfek,

Cephanemiz al kandı.

Kadın, çocuk, er, erkek,

Atasına inandı.

Samsun’da doğan güneş,

Ta İzmir’e uzandı.

Bu harp kıyamete eş,

Meydanlar toz dumandı.

Minarelerde Ezan,

Dualar çağlayandı.

Yüreğimizde iman,

Allah Rahim Rahmandı.

Mehmetçik cephelerde,

Eşsiz bir kahramandı.

19 Mayıs bize,

Gençlere armağandı.', 'Seksen dokuz yıl evvel, Türklüğün içi yandı. Birleşti yedi düvel, Ankara’ya dayandı. Saldırdı kahpe Yunan, Anadolu uyandı.	 O, öyle bir zor ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Güncan']::text[], 8.5, '{"poet":"Halil İbrahim Güncan","poet_slug":"halil-i-brahim-guncan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ondokuz-mayis-19-mayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup 1', 'mektup-1-halil-i-brahim-guncan-z4w8a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özleminle atan kalbimde ateş,

Keremin misali yanar sevdiğim.

Her an hayalinle gerçeğine eş,

Yaşarır gözlerin dolar sevdiğim.

	Günlerim aylarım geçiyor sensiz,

	Ellerim yetişmez, dizler dermansız,

	Çalsam kapınızı bir gün apansız,

	Gurbet aramızda duvar sevdiğim.

Dicle kenarında ararım seni,

Çağlayan sulara sorarım seni,

Kaplamış ruhumu İzmir özlemi,

Gözlerim dalar da dalar sevdiğim.

	Sağ oldukça bugünler de geçecek,

	Ayrılık hasretlik hepsi bitecek,

	Gülecek bahtımız elbet gülecek,

	Bizimdir en güzel yıllar sevdiğim.', 'Özleminle atan kalbimde ateş, Keremin misali yanar sevdiğim. Her an hayalinle gerçeğine eş, Yaşarır gözlerin dolar sevdiğim. 	Günlerim aylar...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Güncan']::text[], 8.5, '{"poet":"Halil İbrahim Güncan","poet_slug":"halil-i-brahim-guncan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mektup-1-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-halil-i-brahim-guncan-zeh1l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her nefes sigaramda düşüncemde sen varsın,

Karanlıklar içinden ismimi fısıldarsın.

Karlı dağlar ardında sensiz deli gibiyim,

Beni çöllere salan dertlerin sahibiyim.

Sabrın sonu selamet deseler inanamam,

Sensiz geçecek ömre ölürüm dayanamam.

Her günüm bir yıl gibi uzar gider geceler,

Hep rüyamda sen varsın, karmaşık düşünceler

,

Gündüz gözüm saatte, şimdi nerdesin diye,

Seninle  gezer aklım, sokakta, işte, evde.

Bu geceyse rüyamda yatmıştın, uyuyordun,

O pembe yanağına bir öpücük kondurdum.

Uyandım bir baktım ki kimse yoktu yanımda,

Busenin sıcaklığı duruyor dudağımda.

Öyle bir ağladım ki tan yeri ağarırken,

Sen çayını yudumlar, yıkanır, taranırken.

Kalktım bir ceset gibi giyindim işe gittim,

Mutlu günlere hasret Allah’a dua ettim.

Aşkımız hiç bitmesin yıllar geçse aradan,

Korusun esirgesin seni Yüce Yaradan.', 'Her nefes sigaramda düşüncemde sen varsın, Karanlıklar içinden ismimi fısıldarsın. Karlı dağlar ardında sensiz deli gibiyim, Beni çöllere sa...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Güncan']::text[], 8.5, '{"poet":"Halil İbrahim Güncan","poet_slug":"halil-i-brahim-guncan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mektup-441-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An', 'an-hakan-sengorun-04g9b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korkunun anlamı belkide  sahte bir anın bedeli

Sıradan bir yaşam sıradan bir ölüme varmadan

Baktığım ana sahibim gözlerinde

Gülüşünden tanıyabilirim mutluluğunu

Gözlerindeki şiiri okuyabilirim gece siyahını akıtırken zamana

Çok derine bakmıştım hiç bilmedin bunu

Ruhunu paylaştım belki birazını çaldım gözlerinden

Gözyaşlarım hüznümü somutlaştırırken gidişinin ardından

Ne kadar kaçtıysam o kadar büyüdün

Sokaklar korkardı hüzünlü yürüyüşlerden

Zamana çıkan en uzun yolu seçerdim hep

Şehre düşerdi yine yanlızlığım

Sokaklar ağlardı hep bir gidişin ardındaki sıra

Yinede söylemezdi papatyalar her baharda 

Ilık bir rüzgarla sallanırlar 

Bir bahar hayali demiştim adına

Gerçekti itiraf edemezken ben kendime

Yırtılırdı sokaklar sende bilmiyordun derinliğini

Ne yapılabilirdiki şimdiyi alıp gitmiştin

Elimde geçmişle kalakalmıştım 

Fakat geçmiş geçmemişti geçmiyorduda 

Geçip gitmesine izin verdim sonunda

Aşk bir andı 

derin bir an

her bahar tekrar açıp solan...', 'Korkunun anlamı belkide  sahte bir anın bedeli Sıradan bir yaşam sıradan bir ölüme varmadan Baktığım ana sahibim gözlerinde Gülüşünden tanıy...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/an-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rütbe', 'rutbe-necip-fazil-kisakurek-ybkdv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşünün, ben ne büyük bir rütbeye tutkuluyum,

Çünkü O''nun kulunun kölesinin kuluyum.', 'Düşünün, ben ne büyük bir rütbeye tutkuluyum, Çünkü O''nun kulunun kölesinin kuluyum....', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/rutbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuntu', 'avuntu-abdi-kadir-birinci-leq92', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gölgesinde oturduğum çınar

Önünden geçen kızları ağırlayan şu pınar

Zamana akıp giden düşünce yelinde

Ne güzel avutuyor beni.', 'Gölgesinde oturduğum çınar Önünden geçen kızları ağırlayan şu pınar Zamana akıp giden düşünce yelinde Ne güzel avutuyor beni....', ARRAY['Türk Edebiyatı','Şiir','Abdi Kadir Birinci']::text[], 8.5, '{"poet":"Abdi Kadir Birinci","poet_slug":"abdi-kadir-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/avuntu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavanozdaki Aşk', 'kavanozdaki-ask-kaan-guven-g3rdo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kavanozlar... Hemen hemen hepsi bakkaldan alınmış tahinlerin bitmesi sayesinde raflara girmişti.Hepsi aynı boyda,hepsi aynı şekilde... İçlerinde nohut,şehriye,baharat birde annemin yaptığı reçeller...

                                Kavanozdaki Aşk

     Aşklarım vardı cam kavanozlarda sakladığım

     İçine su kaçmasın diye ağzını sıkıca kapattığım

     Zarar gelmesini istemediğim

     Aşklarım cebimdeki soluk renkli sinema biletleri gibiydi

     Ne kadar soluk olsalarda atmaya kıyamadığım

     Her elime alışımda bir sahnesini hatırladığım

     Aşk, kaybedilmiş bir duyguydu benim için

     Tıpkı defterimin arasındaki şiirler gibi...

      Kayıp...

    

     Aşklarım vardı kavanozlarda sakladığım

     Yastığımın altında duran

     Bir ayrılık serüveninin son sayfasında kaybolan

     Yolculuk bitiminde bulunamayan

     Şimdi onu tekrar aramaya karar verdim

     Cadde cadde,

     Sokak sokak,

     Şehir şehir,

     Bana yoldaş olmaya ne dersin ?

                  

                                                              Nisan / 2000', 'Kavanozlar... Hemen hemen hepsi bakkaldan alınmış tahinlerin bitmesi sayesinde raflara girmişti.Hepsi aynı boyda,hepsi aynı şekilde... İçler...', ARRAY['Türk Edebiyatı','Şiir','Kaan Güven']::text[], 8.5, '{"poet":"Kaan Güven","poet_slug":"kaan-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kavanozdaki-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Sana Çıkar', 'her-sey-sana-cikar-mahmut-kuru-r71ap', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen,sen,ah sen

Bende tutuşturduğun yürek yangını,

söndürmeyen yağmurlara özenir

kelimelerle sürdürdüğüm mücadelem

sonuçsuz kalır belki

ama karşılıksız cümlelere çıkar yokuşlarım

sana çıkar yolun sonunda

tüm kelimeler

tüm cümleler

Sen,sen,ah sen

Doymaz bir sevgiyle yıkanırsın

kelimeler sana yetmez

cümleler tırmanamaz yokuşlarına

ancak bakışlarım var sana sunacak

tükenmez umutlar dayanağım

her şey sana çıkar sonunda

tüm bakışlar

tüm umutlar

Sen,sen,ah sen

duyduğum ufak bir gülüşüne

yaslanırım günlerce

acılar,sevgilere döner

sevsen de sevmesen de beni

ihtimaller yeter bana

her seçim sana çıkar sonunda

tüm acılar,sevgiler

tüm ihtimaller...

		21.06.2001-Tavşancıl', 'Sen,sen,ah sen Bende tutuşturduğun yürek yangını, söndürmeyen yağmurlara özenir kelimelerle sürdürdüğüm mücadelem sonuçsuz kalır belki ama k...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/her-sey-sana-cikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımında Yolculuk', 'gun-batiminda-yolculuk-mahmut-kuru-0l80r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün batımlarına uzanan akşamlarda

Sesleri dinlerim sahillerde

Sesini ararım sensiz kalabalıklarda

Sesin sesim olduğundan beri

Konuşmaktan çekinirim

Kelimelerini tüketmek korkusu

Sana ait kelimeleri

Kullandığım cümlelerde ama özenle

yüreklice bir sevişle

Severim sana ait olan her şeyi

Kelimeleri,sevdaya özgü

Gözlerle konuşmayı öğrendiğimden beri

Gönül nağmeleri yakarım

gözlere bakarım,

ağızlardan çıkanlar

uzak düşer bana

Her şey yakınlaşır,

Sen yakın olursun bana 	

Sen olurum zamanla

Gün batımlarında sen ben yok

Seninle bakarız ufuklara

sahillerde elele yol alırız

gün batımlarına,

sen olmasan da yanımda,

ben varım ya yeter

ikimizin varlığına...

		20.06.2001-Tavşancıl', 'Gün batımlarına uzanan akşamlarda Sesleri dinlerim sahillerde Sesini ararım sensiz kalabalıklarda Sesin sesim olduğundan beri Konuşmaktan çe...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gun-batiminda-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğultu', 'ugultu-mahmut-kuru-jfmqq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uykularım sırtını dönmüş

yüz vermiyor artık bana

gündüzsüz geceler özlüyorum

Şehrin üstünü kaplayan kin bulutu

fırsatını bulup beynime üşüşmüş

leş görmüş sırtlanlar gibi

arta kalan gecelerimi kemiriyorlar

Molasız karabasanlar istila ediyor

darmadağın uykularda 

yine de hayra yoruyorum 

olan biteni

bağrıma basıyorum yalancı şahitlerimi

şehvetini kusmaya and içen bedenimi

fahişe sokaklara vuruyorum

alaca karanlık kuşağından kalma

Nefes alamıyorum karmaşadan

boğucu gürültüyü bastırmakla meşgulüm

gücümün yettiğince haykırarak

kimse beni duymuyor 

aldırış etmiyorlar varlığıma

sığınacak sahte gölgelere sokuluyorum

kendi gölgeme bile sözüm geçmiyor

düşmanlarıma bekçilik ediyor

Yarınlarım yok benim

geçmişe borcum çok birikti

haciz koymuşlar yarınıma

bense tüm bunlara inat

geceden arttırdığım

gündüzleri yaşıyorum.

		19 Haziran 2001-Dilovası', 'Uykularım sırtını dönmüş yüz vermiyor artık bana gündüzsüz geceler özlüyorum Şehrin üstünü kaplayan kin bulutu fırsatını bulup beynime üşüşm...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ugultu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akasya Ağacı', 'akasya-agaci-mahmut-kuru-t45us', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir akasya ağacıyım,çam ormanında,

Dallarım iğdiş edilmiş,yapraklarım perişan

Fazlayım,istenmediğimin farkındayım

Gönlümün aradığı esenlik yok hiçbir yerde

Yüreğim öfke dalgalarıyla boğuşur günlerce,

Demir atacak sakin limanlar aradığım

Öksüz bir akasyayım çam ormanında

Pişmanlıkları özler oldum dar vakitlerde

Gündüzler fazlalık,geceler zaten bitmiş

Rüyalara ulaşamıyorum,ışık uzak

Düşlerde bile istenmiyorum,fazlayım

Çam ormanında öksüz bir akasya

Gemiler arasında bir sandal,dalgalarla boğuşan

Sardalyaların içinde istavrit balığı

Oltalar düşman bana,ölüm uzak

Kırgın bir akasya, çam ormanında

İçtiğim çay düşmanlıklar peşinde

Dudaklarımda bıraktığı acı lezzet

Bir tek dostum sigaram,öksürükler arasında

Dumanlarıyla şarkılar söyler bana

Yalnızlığıma yalnızlıklar katar 

Sadece gülleri özlüyorum çöllerde

Güller bana uzak

Fazlayım çam ormanında

Perişan bir akasya ağacı

İstenmiyorum hiçbir yerde,dostum yok

Fazlayım,farkındayım

Güzel yüzlere kırgınım

Bana bakmayan gözlerin sahibi güzel yüzler

Bir tek dostum sigara

Dumanları ölüm mangası

Ölüm bana yakın...

Ben bir akasya ağacıyım,çam ormanında,

Dallarım iğdiş edilmiş,yapraklarım perişan.

				16 Haziran 2001-Eskihisar', 'Ben bir akasya ağacıyım,çam ormanında, Dallarım iğdiş edilmiş,yapraklarım perişan Fazlayım,istenmediğimin farkındayım Gönlümün aradığı esenl...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/akasya-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Gözlerim', 'yeter-gozlerim-mahmut-kuru-vyykb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Bildiğim değişen aşığa''

Gözlerim

gözlerim hain

yalan yüzler peşinde

yanıltma yarışlarında galip

sürükler peşinden ihanet çemberlerine

alışılmadık gözler arar

kaybolacak sahipsiz gözler

götürdüğü son hep boşluğa

uykusuz gecelere dayanır

ihanet çemberlerine...

Yeter gözlerim sus artık

ışığa götür beni

kurtar karanlıklardan

derin uykusuzluklardan

Ağıtlar arama şarkılarda

Baktığın hayat benim değil

Yeter çıkardığın

İhanet çemberlerine...

Gözlerim

hain gözlerim

huzurdur aradığım

sonsuzluk ülkelerinde

Bildiğim değişen aşklardır

suskun duvarlarda gözlediğim

yeter, yeter artık çıkardığın 

İhanet çemberlerine...

Gel gözlerim

Barışalım artık senle

günahlara koşalım dilersen

huzur veren günahlara

Aşıkları gözleyelim sokak başlarında

derin uykulara batalım

hiç uyanılmayan

umuda koşalım,düşlere

Ve bildiğimiz değişen aşığın

Gelip bizi çıkarmasını bekleyelim

İhanet çemberlerine...

14.06.2001-Gebze', '''Bildiğim değişen aşığa'' Gözlerim gözlerim hain yalan yüzler peşinde yanıltma yarışlarında galip sürükler peşinden ihanet çemberlerine alışı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yeter-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-mahmut-kuru-suxkm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecelerim parıltılı sessizlik,

Şafağa az kala,

Derin uykuların anlamsız acısı yüreğimde,

Lüzumsuz afların geçici rahatlığı.

Olgun kelimelerin peşine düştüm,

Kolayca elde edilemeyen,

Şekillenecek topraklar,sulanacak tarlalar,

Kuraklığın bilinmezinde,

Gelişimi gözler sabırla...

Kalpler var ihanet için tutuşan,

Gözlerinden tanıdığım kalpler,

Kölelik engel özgürlüğe,

Tüm aynalar düşmanım,

Tanınmamak adına savaşım,

İçerden kuşatan bir kahpelik,

Aynaların saydamlığı...

		13.06.2001-Gebze', 'Gecelerim parıltılı sessizlik, Şafağa az kala, Derin uykuların anlamsız acısı yüreğimde, Lüzumsuz afların geçici rahatlığı. Olgun kelimeleri...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aynalar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yabancı Gibi', 'i-ki-yabanci-gibi-mahmut-kuru-mh8i0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Korkularını sevdim,korktuklarını,

Cesaretini ardından,

Med-cezirlerine kapıldım...''

...

Biz farklı şehirlerden ''iki yabancı'' gibi

Korktuk birbirimizden

Yol yakınken dönmeliydik kendi karanlıklarımıza,

Ama dönmedik,ışığa kenetlendik yolun sonundaki

Korkularımızı yendik,korktuklarımızı da.

Yola koyulmuştuk bir kere,dönüşü yok artık

İnatçıydık,sonunu görebilmeliydik filmin,

Dinleyebilmeliydik şarkının bitişini,

''İki yabancı'' gibi...

İhanetlerle çevrili bir yolda yürüyorduk

Kolay değildi,korkuyorduk ama

Cesurduk aynı zamanda hayat karşısında

Biz ihanetleri yaşayarak yenmeyi öğrenmiştik,

Bazen yol dar geldi bize,paylaşamadık ışığı

Bu ışık fazla dedin ikimize,

Ama bilmediğin bir şey vardı sevdiğim,

İkimizle vardı ışık,birimiz yüz çevirse yoldan

Karanlıkta kalıyorduk, üşüyorduk

Sensiz bensiz herşey bir hiçti,karanlıktı...

Evet ikimiz birlikte yürümeliydik bu yolda

O zaman çölde olsak bile koklardık gülleri

Işığı paylaşarak,''iki yabancı'' gibi,

Ama dönmemeliyiz asla,anlaşılmaz bulsak bile birbirimizi

Çünkü biz ışığa kenetlendik,

Ardımız karanlık...

				12.06.2001-Gebze', '''Korkularını sevdim,korktuklarını, Cesaretini ardından, Med-cezirlerine kapıldım...'' ... Biz farklı şehirlerden ''iki yabancı'' gibi Korktuk b...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/iki-yabanci-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımında Kurutulan Goncalar', 'gun-batiminda-kurutulan-goncalar-mahmut-kuru-xwmpr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Gül olmamış tüm goncalara''

Bir günbatımında yine sürüklendim kıyılara

Deniz kıyısında,eskimiş bir balıkçı kahvesinde 

Masamın üstünde kurumuş gül goncası,

Gül olmadan koparılmış dalından,

Kendini bülbüle sunmak için hazırlanırken,

Bir kitabın tozlu sayfaları arasına terkedilmiş yapayalnız,

Günlerce hapis kalmış orada,

Yalnızlığını kelimelerle hasbihal ederek unutmuş

Unutulmuş olduğunu bile unutmuş durduğu yerde...

Bugün karıştırırken tozlu sayfalarını kitapların

Ona rastladım,avucumun içine aldım,okşadım kuruyan yanlarını

Kokladım,öptüm,bağrıma bastım onu

Annesiz kalmış bir bebeğin hüznü vardı yüzünde,

Kendimi gördüm onda,kendimi kokladım aslında

Açamadan kurutulan gonca oldum onunla,

Kuruyan yanlarını okşadım,ağladım çaresizliğine

Eskiden ben de yaşardım gül bahçesinde

Bütün goncalar gibi açılmayı beklerdim,

Bülbülü hayal ederdim her gonca gibi,

Bir gün açacaktım,sunacaktım güzelliklerimi özgürce

Yanıma gelecek,dalıma konacak,bana şarkılar söyleyecekti 

Belki de aşık olacaktı renklerime

Birlikte şarkılar söyleyecektik o zaman 

Baharı doyasıya yaşayacaktık birlikte

Ama olmadı işte...

Şimdi bir balıkçı kahvesindeyiz

Eskimiş bir balıkçı kahvesi.

Tozlu bir masanın üstünde,o ve ben

Goncayız ikimiz de

Açmadan kurutulan birer gonca...

Gül olmak istedik,ama tozlu sayfalarda yer bulduk kendimize

O ve ben şimdi birlikte bakıyoruz günbatımına

Güneş yine veda etmeye hazırlanıyordu bugünkü yolculuğuna,

Uzaktan göz kırptı ikimize,tazeledi tükenmiş umutları

İkimiz de aşklarımızı kaybetmiştik,

Bülbül artık ona hiç şarkılar söylemeyecekti,

Ben o iri gözlere hiç bakamayacaktım artık,

O bülbülünü kaybetmişti,ben gözlerimi günbatımlarında

Onu aldım avucumun içine, okşadım,ağladım çaresizliğime

Gözyaşlarımı akıttım kuruyan yanlarına...

Birlikte yalnızlıklarımızı unutmalıydık

O bana rastlamıştı,ben ona

Artık birlikte aramalıydık güzellikleri,

Acılarımızı ortak etmeliydik yarınlarımıza

Birlikte günbatımlarına veda etmeliydik

Tozlu sayfalara karışmalı

Kelimelerle hasbihal etmeli

Ve unutmalıydık yalnızlıkları

Ben ona bir bülbül olmalı,dalına konmalıydım

Seçilmiş şarkılar bulmalı,fısıldamalıydım kulağına

Belki zamanla aşık olurdum solmuş renklerine,

O bana kaybettiğim gözlerimi verir,doyasıya bakardı bana

Belki kuruyan yanlarımız canlanırdı zamanla...

Eskimiş bir balıkçı kahvesinde,

Tozlu bir masanın üstünde,

Kurutulduğumuz günbatımına veda ettik mutlulukla,

Yeni günbatımlarına sözleştik güneşle,

Sımsıkı sarıldık kaybolan düşlerimize,

Umutlarımızı yarınlara bırakarak,

Döndük tozlu sayfalarımıza 

Tozlu hayatlarımıza...

09.06.2001/Tavşancıl-Gebze', '''Gül olmamış tüm goncalara'' Bir günbatımında yine sürüklendim kıyılara Deniz kıyısında,eskimiş bir balıkçı kahvesinde  Masamın üstünde kurum...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/gun-batiminda-kurutulan-goncalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Durdurdum', 'zamani-durdurdum-mahmut-kuru-arbps', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Farklı bir güne kavuştum bugün

Güneş üşütmüyor,

Bulutlar ağlamıyordu eskisi gibi

Yollardan ağır bir ezilmişlik kokusu yayılıyordu etrafa

Çiçekler güzelliklerinden utanırcasına renklerini eskitmişti

Kuşlar cıvıltılarını geçmişte unutmuşlardı

Herşey farklı olmaya çabalıyordu sanki

Hırçın deniz bile uslu bir çocuk olmuştu

Fırtına öncesi sessizliği andıran,

Tanıdık bir tedirginlik yaşanıyordu çevremde

Birden seni gördüm karşımda!..

Sorular gelmenle yanıtlarını bulmuştu

Bütün ihtişamınla işte yanımdaydın

Zamanı durdurdum,

Bu an sonsuza dek sürmeliydi

Hiç bitmemeliydi...

Sen gelmenle güzelim,

Güneşe ışığını,

Bulutlara yasını verdin

Çiçeklere rengini,

Kuşlara sesini,

Bana kaybolan neşemi

Geri verdin.

Geri verdin tüm yitirilenleri...

07.06.2001-GEBZE', 'Farklı bir güne kavuştum bugün Güneş üşütmüyor, Bulutlar ağlamıyordu eskisi gibi Yollardan ağır bir ezilmişlik kokusu yayılıyordu etrafa Çiç...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zamani-durdurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin İçin', 'gozlerin-i-cin-gokhan-yalcinkaya-ppjaw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık Dünyaya Güneş olurum, 

Yalnızsan yanına bir eş olurum, 

İstersen alnına ateş olurum ,

Yakarım Dünyayı gözlerin için.', 'Karanlık Dünyaya Güneş olurum,  Yalnızsan yanına bir eş olurum,  İstersen alnına ateş olurum , Yakarım Dünyayı gözlerin için....', ARRAY['Türk Edebiyatı','Şiir','Gökhan Yalçınkaya']::text[], 8.5, '{"poet":"Gökhan Yalçınkaya","poet_slug":"gokhan-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozlerin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımında Yetim Kalmış Bİr Gül', 'gun-batiminda-yetim-kalmis-bi-r-gul-mahmut-kuru-47p1p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Elton John''a ve sana''

Bu akşamüstü yine oturdum evimin önünde

Güneş veda etmeye hazırlanıyordu ufuktan bugünkü yolculuğuna

Durdum,derin bir nefes çektim akşamın sessizliğinden

Üşümüş bir bardak çay eşlik ediyordu yalnızlığıma

Elton John dostça şarkılar armağan ediyordu gün batımına

Sen düştün aklıma,içim huzurla doldu

ilk defa yokluğundan lezzet aldım doyumsuzca

Yüreğim acımadı sensizlikten,ruhum kanamadı

Gözlerimi kapadım bir an,seni hayal ettim

Bir melek oldun,süzülerek geldin ve gülümsedin bana

Karşımda durdun,bahçemdeki çiçeklerin arasında dolaştın

Tek tek hepsini okşadın,kokladın birer birer

Elton John hala şarkılarını söylüyordu gün batımına

Güneş veda edecekti bugünkü yolculuğuna

Sen hala bahçemdeydin,gözlerim kapalı

Rüzgar saçlarını dalgalandırıyordu hafifçe

Yanıma geldin,gözlerimiz kenetlendi birbirine

Elimi uzattım,yüzüne dokunmak istedim

Saçlarını okşadım,parmaklarımla taradım tel tel

Sen yüzüme baktın,gözlerimin içine

Gülümsedin içtenlikle,yüzüme dokundun

Saçlarımı okşadın sıcacık ellerinle

Elimi tuttun çiçeklere götürdün beni

Eğildin,ikimize bakan yetim bir gülü kopardın

Gülü kokladın ve bana uzattın

Sersemledim gülün kokusundan,gözlerim kapalı

Birden ayaklarım yerden kesildi hafifledim

Birlikte göğe doğru yükselmeye başladık

Gün batımına baktık beraber,ufka yöneldik

Elton John''un şarkıları gökte yankılanıyordu

Güneş ufuktan son bir kez daha baktı

Gözlerini yumdu, veda etti bize ve bugünkü yolculuğuna

Elton John şarkılarını artık günbatımına değil bize söylüyordu

Gökyüzünde bir bulutun üstüne uzandık

Yumuşacıktı,pamuk dolu bir çuval gibiydi

Elele semaya baktık bir süre,bana döndün

Yüzüme dokundun,dudaklarımda gezdirdin parmaklarını

Ruhum bedenimden boşalmış hafiflemişti

Ayağa kalktım aşağıya bahçeme baktım

Kendimi gördüm çiçeklerin arasında,gözlerim kapalı

Elton John duyulmuyordu artık şarkıları tükenmişti

Artık gitme vaktiydi sana döndüm

Yüzüne baktım,dudaklarına dokundum

Doyasıya öptüm,ellerimi gezdirdim yüzünde

Sen sadece gülümsedin ve el salladın bana

Gözlerimi açtım,bahçede çiçeklerin arasında uzanmıştım

Seni aradım,elimde yetim kalmış bir gül

Elton John da susmuştu artık,duyulmuyordu şarkıları

Ve sadece gülümsedim hatırana

Gün batımlarından miras kaldı düşlerim

Düşlerde yolculuğu sende öğrendim

Kaybolmuş düşleri bekledim gün batımlarında

Bahçemde çiçeklerin arasında yetim kalmış bir gül

Bizim yetim gülümüz...

03.06.2001 Gebze', '''Elton John''a ve sana'' Bu akşamüstü yine oturdum evimin önünde Güneş veda etmeye hazırlanıyordu ufuktan bugünkü yolculuğuna Durdum,derin bir...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/gun-batiminda-yetim-kalmis-bir-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfi', 'karanfi-hayrettin-tarhan-96pzt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık aşkım köhne bir yol

Bir çıkmaz sokak

Biliyorum artık bu duygulara, 

Bir daha güneş doğmayacak.

Artık kavuşmak hayal,

Anılar bile bir bir yıkılmakta

Unutulanlar perişan, sevenlerin sonu 

Hep hüsran olmakta.

Benim için yaz bitti, 

Bahar son buldu, işte kabir.

Geldi çattı hazan;

İşte aşk için en uygun tabir.

Soldu karanfiller, unuttu seni, 

Deseler de, yanlış bunlar.

Ömrümce yaşayacaksın kalbimde,

Hayalimde hatıralar.', 'Artık aşkım köhne bir yol Bir çıkmaz sokak Biliyorum artık bu duygulara,  Bir daha güneş doğmayacak. Artık kavuşmak hayal, Anılar bile bir b...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanfi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okyanus Kadar Geniş Yüreğim', 'okyanus-kadar-genis-yuregim-mahmut-kuru-dpdw8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Okyanus kadar geniş bir yüreğim var benim

Gemiler demir atar limanlarımda

Balık avlar kıyılarımda balıkçılar

Bazen hırçınlaşır,köpürürüm dalga dalga

Kimi sakinleşir,yatarım derin uykulara

Bir gece yıldızların elinden tutarım

Dansederim sabahlara kadar yorulmadan

Diğer gece güneşe küserim, aldırmam batışına

Bir gün bulutlara göz kırparım 

Üstümde salına salına gezinirler

Başka gün hüzünleşirim,acılarım tazelenir

Gözyaşlarıyla ortaklık ederler kederime

İşte ben okyanus kadar geniş yüreğimle

Sevda gemilerini gözler limanlarım

Balıklar kıyılarımda katillerini bekler

Hırçın olsam da özlerim sessizliği

Sakinleşsem de sonra, dinmez hiç öfkelerim

Dansetsem de yıldızlarla ihaneti kollarım

Güneşe küserim belki aldırmam batışına

Ama ufukta en mahrem sırlarımı paylaşırım onunla.

Ve yüreğim genişler, aslında yürekler okyanuslara benzerler

Ve okyanuslar bir gün yüreklere dönerler.

01.06.2001 Gebze', 'Okyanus kadar geniş bir yüreğim var benim Gemiler demir atar limanlarımda Balık avlar kıyılarımda balıkçılar Bazen hırçınlaşır,köpürürüm dal...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/okyanus-kadar-genis-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solgun Bİr Ağacın Yapraklları Gibi', 'solgun-bi-r-agacin-yaprakllari-gibi-mahmut-kuru-9eq50', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Minik serçe''ye''

Görmemeliyim seni,yok olmamalıyım gözlerinde

Hayır,yoksun işte,gözlerin kapalı dünyama

Soluk almalı,beynimi kemiren sensizlik düşüncesi 

Uçmalı artık ruhum rahat rüzgarların esintisiyle

Yelken açmalıyız birlikte dingin limanlara

Hırçın olmamalı dalgalarımız beden denizinde

Sen yoksun yanımda,yok olmalısın belki de

Rahat kalmalı içimdeki martı,

Sonsuzluğa uçmalı,sensiz yarınlara

Şarkılarım seni söylememeli,

Şiirlerim seni anlatmamalı artık

Uçmalıyım yokluklara,sensiz ufuklara

Batmalısın güneş gibi ama doğmamalısın artık

Karanlıklara alışmalı gözlerim

Bırak gece olsun bütün günler,

Takvimler hep kışta kalsın,dökülmesin

Solgun bir ağacın yaprakları gibi,

Biliyorum yorgunsun,yorulmuşsun bu savaşta

Yine yenilmekten korkuyorsun,kaçıyorsun ihanetten

Farkındayım,dinlenmelisin sessiz okyanuslarda...

Ve ben,gecelerin ihanet kokan yalnızlıklarında,

Devamlı ufuklara bakacağım,

Doğmanı ve her yeri aydınlatmanı bekleyeceğim,

Benim için yanmanı özleyeceğim sabırla...

İşte o zaman minik serçe

Gecelerim tekrar gündüz olacak,kışlarım yaz

Takvim yaprakları düşmeye başlayacak

Solgun bir ağacın yaprakları gibi,

Ve o zaman , işte o zaman

Bir martı olup kanat çırpacağım

Seninle birlikte mutlu yarınlara...

29.05.2001 Gebze', '''Minik serçe''ye'' Görmemeliyim seni,yok olmamalıyım gözlerinde Hayır,yoksun işte,gözlerin kapalı dünyama Soluk almalı,beynimi kemiren sensizl...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/solgun-bir-agacin-yaprakllari-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Defa', 'son-defa-mahmut-kuru-ko481', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derinlerde bir şeyler arıyorum bir fısıltı belki

Coşmuş yüreklerden rüzgarın kopartıp getirdiği

Batmayan bir yaz güneşinde kapımın önünde bekliyorum sevdiğimi

Gelmez biliyorum ama yine de bekliyorum onu

Hiç olmazsa fısıltısı gelir diye kokluyorum esen rüzgarı

Yanan sokak lambalarında gözlerine bakıyorum

Onu arıyorum her köşe başında

Bir gülüşü,nazlı nazlı bir salınışı bile yeter biliyorum

Ama nafile gözlerim yenik düşüyor bu savaşta

Artık hiçbir şey duymuyorum

Ne bir fısıltı ne bir koku uzak diyarlardan

Bak yıldızlar yine göz kırpıyorlar bana

Bulutlar salına salına geziyorlar gökyüzünde

Ay ortaya çıkmak için zaman sayıyor

Ve ben yine yatıyorum o ağacın altında

Olan biteni umarsızca izliyorum sadece

İnsanlar yanımdan geçiyorlar bana değmeden

Belki son sürüşlerini yapıyor yolda arabalar

Sanatçılar son bestelerini söylüyorlar

Güneş son defa batıyor ufuktan

Ay son defa doğuyor batıdan

Herşey herkes son defa yapıyor yapacağını

Ben de herşeye ve herkese son defa bakıyorum

Gözlerim son defa kapanacak hayata artık

Son defa kokunu duydum çünkü

Son defa sesini işittim

Ve son defa gözlerine baktım sokak lambalarında

Rüzgarın getirdiği esenliği son defa avuçladım

Son defa yıldızlara göz kırptım,bulutlara el salladım

Gözlerimi son defa yumdum hayata ve sana...

                     24.05.2001   Gebze', 'Derinlerde bir şeyler arıyorum bir fısıltı belki Coşmuş yüreklerden rüzgarın kopartıp getirdiği Batmayan bir yaz güneşinde kapımın önünde be...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/son-defa-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değilsin', 'sen-degilsin-mahmut-kuru-n3rh3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Resmine bakarak çizdiğim

Yüzüne bakarak daldığım

Dudağına bakarak öptüğüm

Saçlarına bakarak okşadığım

Gözlerine bakarak kaybolduğum

Ellerine bakarak tuttuğum

Vücuduna bakarak sardığım

Sen değilsin

Aslında sevgilim sen

Yanımda olmasan da yanıbaşımda duransın

Sana söyleyemesem de biricik aşkım

Masamdaki vazomda asılı kalan bir demet gülsün

İçtiğim çayda şekerim

Şarkı dinlerken kulağım,kitap okurken gözümsün

Yazdığım şiirlerde kalemi tutan elim

Ağladığımda gözümden akan iki damla gözyaşımsın

Güldüğümde dudağımda beliren tebessüm.

                   20.05.2001--Gebze', 'Resmine bakarak çizdiğim Yüzüne bakarak daldığım Dudağına bakarak öptüğüm Saçlarına bakarak okşadığım Gözlerine bakarak kaybolduğum Ellerine...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-degilsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bİtmeyen Gecelere Yanarım', 'hic-bi-tmeyen-gecelere-yanarim-mahmut-kuru-u6s4r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalabalıklar bastırıyor çığlığımı

Yıldızlar göz kırpıyor dağınık akşamlarda

Bir köpek bozuyor gecemin sessizliğini

Ama ben aldırmadan yürüyorum şehirleri sayarak

Ben bir adamım başka biri

Sokakların efendisi,bir abide belki

Molalarımı kavşaklarda alarak

İlerliyorum,bu gece başka biliyorum

Bir müjdesi var tanrının hissediyorum

Yıldızlar düşecek kaldırımlarıma

Önüm karanlık arkam gece

Tutunarak bir ışığa ilerliyorum yeniden

İlerliyorum aydınlığa kavuşana dek.

Korkunun esiriyim yalnız akşamlarda

Bitimsiz heyecanlar yaşarım ardı ardına

Karanlığı yudumlarım bir ömür boyu

Hiç bitmeyen gecelere uyanırım

Ve doyasıya günah işlerim 

Sonra göğe yönelirim,kaybolurum içinde

Af dileme sarhoşluğunu yaşarım

Bir dolu ezan dinlerim saba makamında

Doludizgin ağlarım ve af diler ellerim

Secdeye vararak hıçkırıklarla...

16 Mayıs 2001-Gebze', 'Kalabalıklar bastırıyor çığlığımı Yıldızlar göz kırpıyor dağınık akşamlarda Bir köpek bozuyor gecemin sessizliğini Ama ben aldırmadan yürüyo...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hic-bitmeyen-gecelere-yanarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O İri Gözlerin', 'o-i-ri-gozlerin-mahmut-kuru-vc8gb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bomboş şehirlerin loş sokaklarında 

Gözlerin kılavuzum oldu

O iri gözlerin....

Issız gecelerde buldum kendimi

Labirentlerin ortasında

Ama hep gözlerin vardı önümde

O iri gözlerin....

Kayıp mabetlerde tapındım

Sahte ilahların önünde diz çöktüm

Ama her zaman yürüdüm yorulmadım

Çünkü gözlerin vardı önümde

O iri gözlerin....

Aldandım aldatıldım kimi duraklarda

Çöl fırtınalarında güller sığınağım oldu

Bazen ıslandım sessiz yağmurlarda

Ama gözlerini hiç kaybetmedim

Onlar hep kılavuzum oldu

O iri gözlerin....

                         15 Mayıs 2001-Gebze', 'Bomboş şehirlerin loş sokaklarında  Gözlerin kılavuzum oldu O iri gözlerin.... Issız gecelerde buldum kendimi Labirentlerin ortasında Ama he...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/o-iri-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dermisin', 'dermisin-mahmut-kuru-ssoo3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu üstüme doğan güneş mi yoksa sen misin

Yüzüme meltem misali durmadan esen misin

Önünde eğilsem sana aşığım desem

Atılıp kollarıma ben de sana,ben de sana der misin

Şu üstüme yağan yağmur mu yoksa sen misin

Gökte bulut misali durmadan gezen misin

Yoluna güller sersem seni seviyorum desem

Bakıp gözlerime ben de seni,ben de seni der misin

Şu üstüme parlayan yıldız mı yoksa sen misin

Geceleri rüyama durmadan giren misin

Gözlerinde kaybolsam senden vazgeçemem desem

Tutup ellerimden ben de senden,ben de senden der misin

14 Mayıs 2001-Gebze', 'Şu üstüme doğan güneş mi yoksa sen misin Yüzüme meltem misali durmadan esen misin Önünde eğilsem sana aşığım desem Atılıp kollarıma ben de s...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dermisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Beri', 'senden-beri-mahmut-kuru-w3xsg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''biricik güzelime''

Ben seni sevdiğimden beri güzelim

Güneşi sevmez oldum

Yağmuru özledim,koyu bulutların

Dans edercesine gökte tur atmasını

İçindekileri boşaltmasını bekledim durdum.

Ben seni sevdiğimden beri güzelim

Baharı sevmez oldum

Kışı özledim,insanı ürperten

Uzun kış gecelerinde fırtınaların

Çılgınca esmesini bekledim durdum.

Ben seni sevdiğimden beri güzelim

Gündüzü sevmez oldum

Geceyi özledim,gizli günahlar işlenen

Şehvetin bedenden çıldırırcasına çıktığı

Anların gelmesini bekledim durdum.

Ben seni sevdiğimden beri güzelim

Şehirleri sevmez oldum,

Eski kasabaları özledim,eskimiş aşklar yaşanan

Hala birbirlerine papatyalar veren sevgililerin

Gezdiği yerleri bekledim durdum.

Ben seni sevdiğimden beri güzelim

Edirne''yi sevmez oldum

SENİ özledim,içinde kimselerin yaşamadığı

Başka başka şehirleri özledim

Ve sadece SENİ bekledim durdum.

                   10 Mayıs 2001-Edirne', '''biricik güzelime'' Ben seni sevdiğimden beri güzelim Güneşi sevmez oldum Yağmuru özledim,koyu bulutların Dans edercesine gökte tur atmasını ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/senden-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz', 'guz-erdem-demirkol-7ltk2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülden güzeldi gül yüzleri

Güze dönmüş gülşen gülüşleri

Gülzâr içinde gülmek eskidenmiş

Şimdi ağlamak vakti gelmiş

Sarkıyor geceye saatin sarkacı

Sarıp sarmalamış güz yaprakları toprağı

Şimdi ölmek zamanı

Sararmış solmuş güze güldük

Şimdi kışa girmek sırası

(01.06.2001-İçerenköy-İst.-saat:03.10)', 'Gülden güzeldi gül yüzleri Güze dönmüş gülşen gülüşleri Gülzâr içinde gülmek eskidenmiş Şimdi ağlamak vakti gelmiş Sarkıyor geceye saatin sa...', ARRAY['Türk Edebiyatı','Şiir','Erdem Demirkol']::text[], 8.5, '{"poet":"Erdem Demirkol","poet_slug":"erdem-demirkol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Zamanları', 'hasret-zamanlari-erdem-demirkol-vm4tv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün sana aşık oluşumun bilmem kaçıncı günü?

Ve bilmem kaçıncı saati şimdi?

Milattan sonra mıydı, yoksa önce mi?

Yoksa milat, aşık olmam mıydı gözyaşlarına?

Gözyaşlarım, kum saatinin kum taneleri.

Aşk, sessiz ve sürekli akışında gizli.

Zaman kadar düzenli,

Aşk kadar, senin kadar gizemli.

Bilmem kaçıncı dakikası sana aşık oluşumun?

Her nedense savruldum saçlarınla,

Vuruldum yalancı bakışlarına.

Yalancı olan sevgi miydi, mestane gözlerin mi bilmem?

Yoksa gerçekler miydi yalan olan?

Güzel yüzünden arta kalan,

Hayalin kadar yalan.

Bilmem kaçıncı saniyesi sana aşık oluşumun?

Kalbimin kaçıncı haykırışı seni?

Kaçıncı duyuşum kapıda sesini?

İşte yine gelmeyişin,

Hayalkırıklığının hangi saniyesi?

Bilmem kaçıncı salisesi sana aşık oluşumun?

Ve alışamadığım yokluğunun?

Ne zamandır hasretim karbeyaz tenine.

Yokluğunda geçen saliseler kadar,

Akıttığım gözyaşları kadar,

Sana olan sevgim kadar çok hasretim sana.

Vuslat, bir dua kadar uzak,

Ölüm kadar yakın bana,

Şimdi sessizce ağladığım mezarının başında.

(26.02.2001-Esatpaşa-İst.-saat:04.00)', 'Bugün sana aşık oluşumun bilmem kaçıncı günü? Ve bilmem kaçıncı saati şimdi? Milattan sonra mıydı, yoksa önce mi? Yoksa milat, aşık olmam mı...', ARRAY['Türk Edebiyatı','Şiir','Erdem Demirkol']::text[], 8.5, '{"poet":"Erdem Demirkol","poet_slug":"erdem-demirkol","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hasret-zamanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Freknas', 'kayip-freknas-sema-gulser-keser-kxhq1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün bitti acı bir gülümsemeyle,

    Sen yine yüklendin yılları gidiyorsun bilinmeze.

    Dışlanmış bir sevda sarsıyor asi yüreğimi

    Şiirin dalları kırılıyor suskunluğunda

    Buna rağmen gidiyorsun pervasızca...

    Oysa seni çiçek gülüşlerlerde sevmişti yorgun bedenim

    Bilirdim vefasız olanın kahrı çekilmez

    Yine de sevdim umarsızca

     Bitmeyen yarışmış yaşam,hükmü kalmazmış sevginin

     Sevgi biter,hoşçakal trenleri kalkarmış son duraktan

     Amansız rüzgarla devrilirmiş çınar

     Geçmişten kalan bir avuç şiir serpilirmiş umuda

     Ve en son söz söylenirmiş ''anla beni''

     Gül diken ellerimde gül diken olurmuş

      Boşunadır saydıklarım biliyorum

      Yüreğim kaybetti yine o suskun frekansta...

  13-06-2001', 'Gün bitti acı bir gülümsemeyle,     Sen yine yüklendin yılları gidiyorsun bilinmeze.     Dışlanmış bir sevda sarsıyor asi yüreğimi     Şiiri...', ARRAY['Türk Edebiyatı','Şiir','Sema Gülser Keser']::text[], 8.5, '{"poet":"Sema Gülser Keser","poet_slug":"sema-gulser-keser","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kayip-freknas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-deli-doktor-1vbi3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana karşı duygularım

Güneş kadar sıcak

Bulutlar kadar beyaz

Gökyüzü kadar sonsuz...', 'Sana karşı duygularım Güneş kadar sıcak Bulutlar kadar beyaz Gökyüzü kadar sonsuz......', ARRAY['Türk Edebiyatı','Şiir','Deli Doktor']::text[], 8.5, '{"poet":"Deli Doktor","poet_slug":"deli-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gulum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş', 'ates-deli-doktor-9300y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonsuzlukta sönmeyen ateşin 

beni yakarken;

   Sonsuz yanan ateş beni bekliyor

sensizlikte...', 'Sonsuzlukta sönmeyen ateşin  beni yakarken;    Sonsuz yanan ateş beni bekliyor sensizlikte......', ARRAY['Türk Edebiyatı','Şiir','Deli Doktor']::text[], 8.5, '{"poet":"Deli Doktor","poet_slug":"deli-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ates-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hala Seviyorum', 'seni-hala-seviyorum-deli-doktor-gx0yh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Seni seviyorum'' sözü bir anlam kazanmıştı,seni sevince

 Beni kendimle başbaşa,sensiz bir sessizlikte bıraktığında

 Kahretsin! SENİ HALA SEVİYORDUM...', '''Seni seviyorum'' sözü bir anlam kazanmıştı,seni sevince  Beni kendimle başbaşa,sensiz bir sessizlikte bıraktığında  Kahretsin! SENİ HALA SEV...', ARRAY['Türk Edebiyatı','Şiir','Deli Doktor']::text[], 8.5, '{"poet":"Deli Doktor","poet_slug":"deli-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/seni-hala-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bir Yaz Gecesi', 'sensiz-bir-yaz-gecesi-semih-semin-wpeas', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ege''de bir koyda 

Gülümseyen bir dolunayda

Akşamdan kalan bir yaz gecesinde

Herşey yerli yerinde 

Ama yine de sensizlik

Bunca güzellikler içinde

Kimsenin kimseye söyleyemediği

Bir felaket haberi gibi

Hüküm sürmekte', 'Ege''de bir koyda  Gülümseyen bir dolunayda Akşamdan kalan bir yaz gecesinde Herşey yerli yerinde  Ama yine de sensizlik Bunca güzellikler iç...', ARRAY['Türk Edebiyatı','Şiir','Semih Semin']::text[], 8.5, '{"poet":"Semih Semin","poet_slug":"semih-semin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensiz-bir-yaz-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortayaş Duyarlılığı', 'ortayas-duyarliligi-kemal-gunduzalp-ein6r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Küçük Sevi  Sözleri'' İçin Kötü Bir Başlangıç 

Otuz beş yaşında olmak herhangi bir yaş gibi

biraz ilkel bir hüzün katıyor yaşamına insanın

ölüme doğru gitmesi gibi merdivenlerin hani.

''Artık günde bir şiir yaratılmaz'' diyorum, ''gençlik 

rüzgarlarının yedeğinde'', sessizce mırıldanarak.

Benim bir kentim de olmadı, bir ilk kent yani

yirmi yaşımda birdenbire ikinci kentte yaşadım. 

Ümit Sineması''nda kaç köylü çocuk vardı ilk Eylül''de? 

Şimdi ben: Dünyaya anakentten bakmanın burukluğuyla

Bir filim afişi gibi yapıştırabilirsiniz yüreğimi duvarlara

herkes baksın bana, sesimi duysun anlık duyarlıklarla

hâlâ  siyah-beyaz bir afiş gibiyim, boğulmuş çığlığım

renklerimi isterim, yasak bayraklar gibi sallansın diye

ç o c u k l a r ı n   e l l e r i n d e! .. 

Son mevsim, omuzlarımda ağrıyan yanım, sevgilim

yaşım seni sevmek için hiçbir zaman geçkin olmadı ki, 

nedense görmediğim bir denizin kıyısını özlüyorum

seni andıkça. Yıllar var ki, uzak bir sudur yalnızca

deniz ve işte o yüzden boğulma korkusu duymuyorum

ancak senin derinliklerinde boğulabilirim bir zaman

ortayaşa girerken de reddediyorum aydın intiharlarını! 

Çocukken yazdığım mektuplara benzesin isterdim hep

o bir türlü sesini bulamadığını sandığım kötü şiirlerim

yani bana biraz beni anlatsınlar gibi bir şeydir bu duygu

seni ya da senin gibi birini; ne çok severdim o zaman...

Herkesin bir kadını vardır belki de, her zaman sevdiği

benimse, yurdundan sürülmüş çocuklar gibi birçok

s e v g i l i m   v a r! ..

Galiba seni özlemek de birini özlemek gibi bir duygu: 

ortayaşımdan mı kuşkulansam yoksa kendimden mi? 

Yoksa her gece başımı yastığa koyduğumda az ötede

aynada büyüleyici bir görüntü gibi karşımda duran 

ve bir türlü ellerimle dokunamadığım senin sevginden mi? 

Bir nota: Müziğin abecesi ve benim aşk diyerek

Eyvahlarla çürüttüğüm eski şarkıları yaşatacak dilin!

Lal bir çağın bakışlarında dondu sesim, ben artık

Otuz beş yaşımı da yaşarım seninle ve yine sensiz.', '''Küçük Sevi  Sözleri'' İçin Kötü Bir Başlangıç  Otuz beş yaşında olmak herhangi bir yaş gibi biraz ilkel bir hüzün katıyor yaşamına insanın ö...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ortayas-duyarliligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anama', 'anama-edip-cangonul-dyogd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana nasıl şiir yazmalı

Nasıl yazılır “aney gurban”

Nasıl öpülür elin

               Nobran olmadan

Dizinde ölmek var

Yüzümde yüzün

             Türkü söylemek

“asker ağam gelse yaralarım eyi olur

gülüşün nasıl anam

nasıl yakıştırdık biz sana ağlamayı

yaz-bahar dururken

nasıl kışa çevirdik ömrünü

bir mevsim mi olmalıydı ömrün

               çileli hem

bir gün mü olmalıydı

               gün görmeden

ufak birimleri gibi ömrün

oy ömrüm

oy anam', 'Sana nasıl şiir yazmalı Nasıl yazılır “aney gurban” Nasıl öpülür elin                Nobran olmadan Dizinde ölmek var Yüzümde yüzün         ...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Oldu!', 'i-ste-oldu-kemal-gunduzalp-cr9wl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I.

Pencerelerden her gece baktığım da yalan olmuştur artık

Giderken sorulur sanmıştım: Özleyeceğim kim kaldı bu kentte? 

Sorulmadı ve ben alıp başımı gittim, özleyeceğim biri olsun diye.

Çok önceden söylemiştim bunu, demek böyle oluyormuş gitmek:

Bırakacağım bu kara kenti, ardımda gözüyaşlı kimse olmayacak! 

İşte oldu! Gidiyorum, ne sevinç ne üzüntü: Ara yerdeyim...

Özleyeceğim biri olacaksa o da sen olursun, hep sen oldun.

Bu son gelişimdi: Sanki ölecekmişim de kimseler duymayacak! 

Seni yitiriyormuşum gibi ağır duygular var içimde.

Haydi bana son kez olsun ‘seni seviyorum’ gibi bir yalan söyle:

- Seni seviyorum, ben de seni özleyeceğim hep bu kara kentte.

Ne acı bir duygudur bu, çekip giderken hiç kimse: ''Dur! 

Kal burada...'' demedi. Durup dururken demez mi insan:

- Gitme, kal... Hiç olmazsa bu akşamı çoğalt benimle! 

II.

Küçük kaçamaklar da bitti, aşk da yok: Belki hiç olmadı

Küçük ihanetlerin güzelliği ya da nedensizliği gibi bir şey:

“Yani bilmiyorum işte” gibi duyarsız ve inceliksiz sözler.

Yani yitiriyormuşum gibi artık bütün güzellikleri de...

Ben sevdim biliyor musun? Ölümü de, sensizliği de, bu kenti de.

Şimdi gecikilmiş bir intiharı yaşama denemesidir kalan hayat...

Haydi orda kal! 

                        Haydi ben gideyim artık.

                                                              Haydi sevgi.

                                                                                  Haydi paydos.

Haydi elveda yalnızlık duygusu, elveda ey bitmeyen ince hüzünler! 

Sancı... Sancı: Yalnızca sancıyor yüreğim derin bir yaradan! 

Bir son söz olsun haykırabilsem ağlayarak yeniden...

İşte oldu: Gidiyorum bu kara kentten, hoşça kal sevgili!', 'I. Pencerelerden her gece baktığım da yalan olmuştur artık Giderken sorulur sanmıştım: Özleyeceğim kim kaldı bu kentte?  Sorulmadı ve ben al...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/iste-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Başlangıçlar İçin', 'kotu-baslangiclar-i-cin-kemal-gunduzalp-ole0i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öksürüklerle büyüyor yüzümde hüznün kibarlığı

budanmış ve yaprak açmayan bir ağaç gibiyim

sanki ömrüm sele gitmiş ben de kum ve çakıl

uzamış sakallarımı kestim yeni bir sabah için

ikindiye uzar, gün ve yorgun akşamüstleri 

terbiyesiz bir yağmur başlar, gökyüzü savaşır

şimşekler arasında ıslanır koşuşan sokak itleri

ben umarsızlığıma dönerim, kapılar kapanınca.

Yüzü eskimiş ve kirli bir yorgan çekerim başıma

bir kenarda yıkanmamış, kokan kirli çoraplarım

sandalyeye asılmış buruşuk bir pantolonda

bacak  izleri: Müzik! Bir bu eksikti burada! ..

Zamansızlık yaşanır bellekte; anlar, anılar

sararmış fotoğrafların solgun renklerinde

yüzüm kül: Zayıf ve rengi uçmuş oracıkta

yine geldiler kaçtığım ve yitirdiklerim... ya sen? 

Yalnızlığımı da yaşayamıyorum bu sokakta

içimde hep kirletilmemiş bir güzellik olacak,

kızların teni ve taşıdıkları çiçekler gibi sevgiyle.

Annem uyanır gömütünden ve bana seslenir! 

Uykusuzum oysa, gidemem, uyumak ve düşlerce

beni bırak, özgürlüğü buldum yüreğimde:

Yitirilecek bir şeyin olmaması ne kötü artık

beklentilerin de bittiği bir yerdir orası./Yitik! 

Gidiyorum, yolculukların gizli gözyaşlarıyla

kimsesizlik en ağır yük gibi biner omzuma

biraz ekmek bırak oraya, biraz sevgi, biraz düş

kartopu da oynayacağım çocuklarla... zil! 

Artık gidiyorum, yalnızlığımla ve kimsesiz

yeni duygular için yaşamak isterdim oysa.', 'Öksürüklerle büyüyor yüzümde hüznün kibarlığı budanmış ve yaprak açmayan bir ağaç gibiyim sanki ömrüm sele gitmiş ben de kum ve çakıl uzamış...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kotu-baslangiclar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastasın Sen', 'hastasin-sen-asli-donmez-i47wg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaç bin sene oldu ,

Lokman bilem torpak oldu

Derler derd-i efkar sarar her yanı

Sararsa beni sarar ellere nesi

Cumartesi bazarında

Derler bi yiğit yatar

Sabah namazıyla kalkar

Salası verilene dek terini satar

dört yanda seher yelleri 

yara ulaşın der bozkır türküleri 

yar dediğin ne ola ki 

devlet büyükleri hep mason olduktan sonra

Neytsek neylesek zahir

Gayri uzatmak sözü

Çek tilili var get gardaş

Hastasın sen...

                         (1998)', 'Kaç bin sene oldu , Lokman bilem torpak oldu Derler derd-i efkar sarar her yanı Sararsa beni sarar ellere nesi Cumartesi bazarında Derler bi...', ARRAY['Türk Edebiyatı','Şiir','Aslı Dönmez']::text[], 8.5, '{"poet":"Aslı Dönmez","poet_slug":"asli-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hastasin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Bir Alışkanlık Gibidir Aşklar da', 'kotu-bir-aliskanlik-gibidir-asklar-da-kemal-gunduzalp-mzrva', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uçurumların kıyısında yürümek de kötü bir alışkanlıktır

derin saç diplerinde bit yavrusu gibi yuvalanmak da...

Bir kıyının en güzel ve mavi yanı, gözlerinin gülümsemesidir

bir ben bilirim şimdi bunu, bir de yürek yanar yine ben

teninin boşluklarında ay ölür, ben çıkarım günışığına...

Gözlerini bana boşalt! Eskilerden bir ben kaldım bir de

günboyu yıldırımlar düşüren yağmur kuşlarının kanatları.

Aydınlığının sonuyum, boğulmadığım tek denizin suyusun

saçmasapan bir samanlık öyküsüdür hep anlattığım

altımda gökyüzü mavisi, üstümde yağmur bulutları.

Rengine vuruldum o dağların, bir de yeşil otların

gözlerimi bağışladım bir koyağın derin diplerinde

esirgenmiş ne varsa yalanım olsun uçurumlarına.

Ne aşk isterim artık, ne sonluluğunu sevgisizliklerin

ölümün yanına koyun, altı üstü bir insanım ben de.

Nedense ağlamaklı bir yüzüm var her akşamüstü, anla bunu

sen gidiyorsun, kalıyorum yol boyunda bir ben bir de ben.

Yalnızlığın boyutlarına sürülüyorum, bir de taşranın...

Kimsesiz, ben nasıl çoğullaşırım yokluğunda bilemem

sesini duyabilsem, yaşamak renklenecek dudaklarında.

Beklediğim ne kaldı: Bir gülümseme, bir tatlı bakış

kahkahanın kösnüllüğünde yitip gitmelerim bir de.

Bitti: Bir filmin son sahnesini çekiyorum kamerasız

doldurma tek karesi olmasın, olmasın istedim ama

son sözcüğünü yakıştıramadım senin güzelliğine.

Ne deniz, ne derya: Gözünde aşkın kör rengi

yaşlı bir balıkçıyım ben suların sığlığında

yitirecek bir kuzum bile yok: Yine ağlıyorum

sesin yok, sevda da... ne kaldı daha geride

gecenin son şarkısını fısıldıyorum sessizliğime.', 'Uçurumların kıyısında yürümek de kötü bir alışkanlıktır derin saç diplerinde bit yavrusu gibi yuvalanmak da... Bir kıyının en güzel ve mavi ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kotu-bir-aliskanlik-gibidir-asklar-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Akan Bir Irmak', 'kendine-akan-bir-irmak-kemal-gunduzalp-ja4z1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendine susamış bir ırmaktı belki de

durgun vadilerden süzülerek akan

öte yanda sessiz bir çöl/ben vahası! 

Birden bütün giysilerini soyunmuş

bir ilkyaz göğü, bulut ve yağmur! 

Gözyaşları bile yoktu yorgun ve uykusuz

yeni bir intihar denemesinde yanılmış

çıplak bir ilkyaz göğünde kaldı gözlerim

bir kedi küçücük ve bir ciğeri vuruyor

yerden yere: Ah, bu kötü bir aşk, biliyorum.

Bilinmeyen biriyim oysa adım halkın arasında

geceboyu çalan bir telefon zilinde kulağım

eskimiş bir düşü göremem ki, artık yaşlıyım

kendine dönük yüzüm yorulmuştur ve aşk

yok! Hayır, bir ilkyaz göğü o yağmur sonrası.

Aylar var ki, kendine küskün ve yalnızdır:

Sıcak bir tene dokunamamıştır elleri

uzamış sakallarında ak telleri yokluyor

yalancı pezevenklerin dünyası değil mi bu? 

Ben yokum, ben yokum, söylüyorum işte...

Ağzı kapalı bir kuyu ve uçurumdu kendisi

bense çocuk elleriyle çizilmiş bir dağ resmi

ve kendine doğru akan bir ırmaktı denizsiz

göl kıyısında intiharı deneyen iki yolcu

bu da geçer, bu da yalan ey ilkyaz göğü!', 'Kendine susamış bir ırmaktı belki de durgun vadilerden süzülerek akan öte yanda sessiz bir çöl/ben vahası!  Birden bütün giysilerini soyunmu...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kendine-akan-bir-irmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncelikler Yoksunu', 'i-ncelikler-yoksunu-kemal-gunduzalp-h43ql', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İncelikli sözlerle sarsmak isterdim insanları

bir tek kadını olsun yeter! Dinerdi sancılar.

Tutup saçlarından ‘ağlama’ demeyi sevgiyle

duyarlı bir noktasına vurmuş gibi öpüvermek

ürpertilerle, nedensizmiş gibi suskunluğundan

tam da pembeliğe varan yüzünün kanlanışı:

- Ah, bırak beni, dayanamam bunca inceliğe! ..

Gençliğimi sayıklamalarla anıp geçti o da

kadınsı güzelliği ve incecik elleriyle

merak ve kuşku: Sevdanın uzak ve eski ulakları

unuttuğum bir şarkıydı çoktandır o filim

sokulup yanına adını bile soramadım,

ölümcül bir hastalık olacak yanıbaşımda:

- Ah, bedenim uzun yolculukların telâşında! 

Göz koyacak bir güzellik olsa, bir aşk belirtisi

bu kenti tüketemedim henüz, biraz durgun

sisli bir akşam alacasında geçiverecekmişim

sokağın başında liseli duyarlıklar durağı.

Üşümüştüm, ellerim buz gibi ceplerimde

durup durup ağlamaklı yüzünün görüntüsü:

- Ah, her gece baktığım sararmış fotoğraf tadında! 

Alıp başını gideceksin, çocuklar ve ben yine

tanıdık bir yolculuğun bekleme salonunda

bırakılmış, uzun sevgisizliklerde uyuyakalacağız.

Dilim sürçecek sözcükleri seçerken, mavilikleri-

özledik, sıcağı. Üstelik gidecek bir yerim de yok! 

Hep terkedilmiş kimsesiz yavru masalındayım:

- Ah, inceliklerden yoksun kırkbeşyaşım, şiirsizliğim! 

Belki bir ırmakta yüzeriz, kanımız ısınır

belki bir uçurum olur geride kalan yaşam! 

Atlarım: Düşebilsem, kolların açılsın isterim.

Adımı sormuş, kimliğimi: Bir bedenim kaldı

bir işkence de sen uygula, direnirim yine

acı çekmenin son kentini de bitirelim haydi:

- Ah, başımı alıp gider miyim yeniden, bilemem!', 'İncelikli sözlerle sarsmak isterdim insanları bir tek kadını olsun yeter! Dinerdi sancılar. Tutup saçlarından ‘ağlama’ demeyi sevgiyle duyar...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/incelikler-yoksunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ergenekon''dan Çıkış', 'ergenekon-dan-cikis-ali-kinik-a9oub', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kurt görün bu gece, rüyanız parçalansın

Bir kutsal ışık görün, riyanız parçalansın

Bir bozkurt pençesiyle mayanız parçalansın

Beni görün bu gece, bir kurt görün, bir beni

Bize artık susmak yok, bir kurt vurun, bir beni...

Elin ekmeğiyle yaşayan kurt kahrolsun

Boynunda tasma izi taşıyan kurt kahrolsun

Kar yağmış dağlarına, üşüyen kurt kahrolsun

Kahrolsun kurt postunu giyen yalancı kuzu

Dağıtanlar kahrolsun, kurt sesli ordumuzu

Ne düşlerimiz vardı, bir karayel savurdu

Deli taylarımızı hain oklar devirdi

Yoksa, hata yaptık da, Tanrı mı yüz çevirdi

Ey kurt soylu milletim, ey Tanrı''nın kırbacı!

Bu düzene kanmayın, andolsun ki yalancı!

Kaç kere kuşatıldım, dara düştü umudum

Bayrak gibi devrildi, yere düştü umudum

Tanrı''ya dua ettim, kurtlar gibi uludum

Dedim, bu hüsran artık sonuncu olsun, en son

Dayanacak sabrım yok, yüreğim Ergenekon

Hani, Çinli katuna kanan Kağan, vardı ya?

Hani, şehzadeleri bir bir boğan, vardı ya?

Ve tek kalıp, sütünü kurtla sağan, vardı ya?

Bu destanda ben kimim, siz kimsiniz, a beyler?

O susuş neler saklar, bu feryat neler söyler?

Bir gün, yerin üstüne gece örtüldüğünde

Binlerce tutsak bozkurt ipten kurtulduğunda

Mahşeri çığlıklarla gökler yırtıldığında

Bu, bizim dönüşümüz, destanımız olacak

Doğmamış çocuklara, şerefimiz kalacak

Ey, öz çocukların boynunu sıkan düzen!

Hak kırbacıyla halkın canını yakan düzen

Devşirme dervişlere tekke bırakan düzen

Her hesabın bir tersi, her zulmün süresi var

Bir tilki hükmü varsa, bir de kurt töresi var

bir Bozkurt Töresi var', 'Bir kurt görün bu gece, rüyanız parçalansın Bir kutsal ışık görün, riyanız parçalansın Bir bozkurt pençesiyle mayanız parçalansın Beni görün...', ARRAY['Türk Edebiyatı','Şiir','Ali Kınık']::text[], 8.5, '{"poet":"Ali Kınık","poet_slug":"ali-kinik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ergenekon-dan-cikis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanadı Kırık Kartal', 'kanadi-kirik-kartal-ali-kinik-y1pke', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ustam, sen şairsin, yıkılmak olmaz.

Bu hesap bitmeden çekilmek olmaz.

Yorgun yapraklarca dökülmek olmaz.

Haydi ustam, haydi doğrul, kurbanım.

Kalk ki bir ak kartal daldan süzüle,

Şiir burcumuza kona saz ile,

Sen de “yıldızları yandır söz ile”                                               Haydi ustam, haydi doğrul, kurbanım.

Alevlerle göğe savrulsun küller,

Doğsun “beyaz günler ve beyaz güller”

“Ordulaşsın ümitlerle emeller”

Haydi ustam, haydi doğrul, kurbanım.

Bir dünya ki o ilk sürgünden beri,

Ağır olmuş ustaların yükleri,

“Aktarıp toprağı, yırtıp gökleri”

Haydi ustam, haydi doğrul, kurbanım.

Sen ki, ta burçlara çıkan şairsin,

Sen ki, yağmurları yakan şairsin,

Sen ki, sarp dağları yıkan şairsin.

Haydi ustam, haydi doğrul, kurbanım.

Dünya kahpe, ama küsme ne olur,

Kılavuzum, ses ver, susma ne olur,

Gel Türk’ün sesini kısma ne olur!

Haydi ustam, haydi doğrul, kurbanım.

Ustam sensiz ben vallahi yarımım.

Bu kabusu çözemiyor yorumum.

Sen anlarsın kahır üzre durumum,

Haydi ustam, haydi doğrul, kurbanım.

Ustam hadi iki al tay seçelim,

Çiçekli dağlara bayrak açalım,

Tanrı Dağları’nda kımız içelim.

Haydi ustam, haydi doğrul, kurbanım.

Hem şairsin, hem ülkücü, hem adam,

Hem ustamsın, hem yoldaşım, hem atam,

Ben kimim ki, seni sözle anlatam,

Haydi ustam, haydi doğrul, kurbanım', 'Ustam, sen şairsin, yıkılmak olmaz. Bu hesap bitmeden çekilmek olmaz. Yorgun yapraklarca dökülmek olmaz. Haydi ustam, haydi doğrul, kurbanım...', ARRAY['Türk Edebiyatı','Şiir','Ali Kınık']::text[], 8.5, '{"poet":"Ali Kınık","poet_slug":"ali-kinik","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kanadi-kirik-kartal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turan Duası', 'turan-duasi-ali-kinik-plzwb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni, acundan yüce tek ''var'' saymışım Tanrı''m

Göğe değen başımı, yere eğmişim Tanrı''m

Ve gönlümde yanına çiçek koymuşum Tanrı''m

Bu sevgiyi sen verdin, bu da benim nazımdır

Korkak kullarca değil, erkekçe niyazımdır 

Ey Tanrı''m, yüce Tanrı''m

Kat, gücü güce Tanrı''m

Bölük bölük bölündük

Sonumuz nice Tanrı''m 

Sensin derdi yaratan, derman olan yine sen

Sensin Türk''ü yaratan, ayrı kılan yine sen

Yüce dağlar birleşir, eğer ki sen ''ol'' desen

Dilersen kes hakkımı ekmeğimden, suyumdan

Bu birlik, varlık demek esirgeme soyumdan 

Kapına durdum Tanrı''m

Yere diz vurdum Tanrı''m

Çek şu kızıl perdeyi

Bir olsun yurdum Tanrı''m 

Tanrı''m, şerefim için, namusum, dinim için

Şerefsize bilenen şerefli kinim için

''Ben'' dedim ya, andolsun, sanma ki benim için

Ahlaksız çarklar için, saklanmaz farklar için

Şu çakal insancıklar, şu bozkurt Türkler için 

Açtım elimi Tanrı''m

Çözdüm dilimi Tanrı''m

Kabul et bu duamı

Arz-ı halimi Tanrı''m 

Bir gece, ağlar gibi kurtlar uludu dağdan

Gözlerime kan değdi, dokuz yaralı tuğdan

Bir türkü, bir de ağıt kopardım eski çağdan

Türküm umudum olsun, ağıdım yaram olsun

Türküsüz ve ağıtsız gün bana haram olsun 

Bu acı beter Tanrı''m

Sanmam ki biter Tanrı''m

Belki benden artar da

Neslime yeter Tanrı''m 

Bizi zulme bileyen bu kutlu güç senindir

Haklı ve yiğit kılan terefli taç senindir

Türk olmaksa suçumuz, bu soylu suç senindir

Sanma ki bu sorgudur, sen Tanrı''sın, ben kulum

Sen sabırda zenginsin, bense işte yoksulum 

Dört yanım soru, Tanrı''m

Hepsi en zoru Tanrı''m

Soruların zorundan

Soyumu koru Tanrı''m 

Sen Tanrı değil misin, adını yargılatma

Sana Tanrı deyince, dinimi sorgulatma

Ya adam et bunları, ya beraber yaşatma

Kanı bozuk olanlar ''Türk''üm'' diyemesinler

Ve Türk''ün dik başını yere eğemesinler 

Gökçek Tanrı''m, gök Tanrı''m

Sevgisi büyük Tanrı''m

İti kurda baş kılma

Bu ne ağır yük Tanrı''m 

Şimdi beni ezenler, demek soyumu bilmez

Bozgunun ardındaki mutlak toyumu bilmez

Demek beni bilir de, deli huyumu bilmez

Çin''de kırkbir çeriyle ihtilal yapan kimdi? 

Peki o uslanmaz kan hangi bedende şimdi? 

Şükür ki bende, Tanrı''m

''Niçin''i, sende Tanrı''m

Bugünü de kutlu kıl

Gözlerim dünde Tanrı''m 

Türkiye benim yurdum, canım kurban bu yurda

Fakat bir dağ az gelir mayası hür bozkurda

Kıralım şu zenciri artık ferman buyur da

Sınırları bozalım, yeni baştan çizelim

Kendi toprağımızda hesapsızca gezelim 

Bir ferman buyur Tanrı''m

Dünyaya duyur Tanrı''m

Türk''ü Türk''e kavuştur

Var beni ayır Tanrı''m

Çünkü o gün her ölen

Sadece uyur Tanrı''m', 'Seni, acundan yüce tek ''var'' saymışım Tanrı''m Göğe değen başımı, yere eğmişim Tanrı''m Ve gönlümde yanına çiçek koymuşum Tanrı''m Bu sevgiyi s...', ARRAY['Türk Edebiyatı','Şiir','Ali Kınık']::text[], 8.5, '{"poet":"Ali Kınık","poet_slug":"ali-kinik","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/turan-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İçin', 'benim-i-cin-alisan-satilmis-d2z89', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yakana bir gül tak benim için 

Rengi kırmızı olsun

Kanamalarım yüreğinin üstünde tutuşsun

Buyur etmelerin kadar kaçışlarına da 

Bir davetiye... Gel diyen 

Gözlerini kapat benim için 

Düşlerine gireyim o an

Çölden buzula... Bir şarkı  mırıldan

Yoksunluğunda muzdarip halimi anla

Sensizlik neymiş ...Beni yaşa da öğren!

Aceleci telaşlarını bir yana bırak 

Uzaklara taşıma hasretimi...

Yakınına sal soluklanmalarını...

İç ağrısı eksilmelerin çoğalışında 

Kökü sende boy verişlerin celladı olma', 'Yakana bir gül tak benim için  Rengi kırmızı olsun Kanamalarım yüreğinin üstünde tutuşsun Buyur etmelerin kadar kaçışlarına da  Bir davetiye...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benim-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dostluk Destanı', 'bir-dostluk-destani-muharrem-guney-mqtzy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün bana bir sitem ettin.

“Kimlere şiir yazdın?” dedin.

Dedin:”Bir ben mi eksiktim?”

Bilmezsin ne zordur sığdırmak seni birkaç satıra.

Belki de bir kağıda.

Dile kolay ulaştık yirmi yıla.

Acısıyla,tatlısıyla,

Dostluk adına,

Ne çok şey sığdırdık bu yirmi yıla.

Son dönemleri geçti belki acıyla.

Kolay mıydı ki dayanmak ayrılığa.

Cehennem diyordun Allah’ın Çorumun’a.

Sanki cennetim mi diyecektim;sensiz Ankara’ya.

Hayatımızın dönemeçlerine beraber imza attık.

İlk aşkımızı birbirimizle paylaştık.

Acı çektik ağladık.

Sevindik paylaştık.

İlk birayı beraber paylaştık.

İlk sarhoşluğu beraber yaşadık.

İçsek de sarhoştuk içmesek de.

İçmiştik bir kere dostluğun şarabından.

Bir kere içmeyegörsün insan

Bu doyumsuz şaraptan,

Müptelası olur ilk andan.

Şimdi pek sık beraber olamasak da,

Bilirim ki sen hep yanıbaşımda.

Hatırlasana sen Ankara’da,

Benim yanımda,

Ama kahretsin Çorum’da,

Teselli hep bu oyunda.

Sen bir saplantı kafamda.

Mutlu olamam insanlarda

Seni aradığımda.

Geçer mi derim.

Geçer dersin.

Biter mi derim.

Biter dersin.

Peki buna inanır mısın?

Karanlık bir gecede bir ışık yakar mısın? 

Bu umutla gecelerce,günlerce yanar mısın?

Ben bir martı senden uzakta.

Beklerim seni yalnızlık limanında.

Bulurum avuntuyu kavuşmanın umudunda.

Bazen bir ses der:”Vur kendini şişelerin buğusuna.”

Razı gelmem böylesi zayıflığa.

Sevgi için,dostluk için değer acılara.

Sevginin bedelini bu acıyla ödemek,

Hasretin ateşini şiirle söndürmek,

İşte tüm bunlar vefa sınavını geçmek demek.

Ve bu gece yine imza attım bir ilke.

Dostuma yazdığım ilk şiire.

Belki de hayatımın en zor işine.

Sığdırmak seni dizelere.

Uzun lafın kısası,

Anlatamam senin dostun olmayı.

İnşallah oluruz yine hep birlikte.

Birlikte ecelde bile.

Belki yanyana bir döşekte,

Belki iki serseri kurşun ile.', 'Bugün bana bir sitem ettin. “Kimlere şiir yazdın?” dedin. Dedin:”Bir ben mi eksiktim?” Bilmezsin ne zordur sığdırmak seni birkaç satıra. Bel...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Güney']::text[], 8.5, '{"poet":"Muharrem Güney","poet_slug":"muharrem-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/bir-dostluk-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Bunları Bir Deliye Anlattım', 'butun-bunlari-bir-deliye-anlattim-alisan-satilmis-mpz8j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soy adlarıyla zamana kaydedilen

Sesime esmer yalnızlıklar düşerken

Çılgın melodiler eşliğinde bir cümbüşü andırır

Şimdi yaşadığımız şehirler...

İlk kez girdiğimiz sokak...Ölüm sessizliği

Yabansı türküler söyler

Hatıralarımız kadar yaşlanmış

Biz kavilleşmiş güvercinlere mi bırakmıştık

Gözlerimizle konuşmayı...

Onlardan gayrı anlayan yok gibidir dilimizden

Oysa...Sen!Ben!Biz!O...

Böyle akitleşmemiştik...Dönersek eğer

Kavgadan tehirli günleri hep birlikte yaşayacaktık

Muradı görülmemiş olsa da dünlerin!

Hangi gölgelenmiş surat yazdı?

Ya da kim ne adına söyledi?

''Siz'' yıldızname...Falına...

Gecenin en zifiri

Karanlık yerinde asılı kaldınız diye

Döndük işte döndük..Neden inanmıyorsunuz!

Yüzlerimiz mi benzemiyor dünkü bize

Lal masalları bir başka resmettiyse hüznümüzü

Fotoğraflarımızda sızmıyor değil ya

''Asılmış arkadaşlarımızın'' -Nerdesin dostum- diyen

Tek kare çerçevelerin içine...

Gidişimiz...Dönüşümüz bir ayrıntının

...Ayrılığında göç serüveni...

Sürgünler yazdı ara kesiti yitik tarihe

Çocuklar büyümemişti o zamanlar

Bahçemizdeki ağaçlar kurumamıştı henüz

Kiremit damlı evlere hala kuşlar konardı

Her bahar salkım saçak uzayıp giderdi sarmaşıklar

Dalından kopmuş solgun yapraklar...Ölüm düşü...

Kayıp günleri çağırmazdı

İmzasına bile sahip çıkmaya vakit bulamayan

Düş gölgesi mevsimler  gibi..

Bütün bunları bir deliye anlattım

''''Ya öyle mi?'''' dedi..Biz böyle mi akitleşmiştik

Dönersek emanete bırakılmış gençlik aşklarımızla 

Giderken son sözümüzü söylemeye fırsat bulamadığımız

Çokça yakışır acıların gün dönümü vakitlerinde

Bakışlarla konuşmayı....', 'Soy adlarıyla zamana kaydedilen Sesime esmer yalnızlıklar düşerken Çılgın melodiler eşliğinde bir cümbüşü andırır Şimdi yaşadığımız şehirler...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/butun-bunlari-bir-deliye-anlattim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığıyım', 'asigiyim-ozan-arif-35sic', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siz sormayın bana aşkı

Ben bu yurdun aşığıyım

Kalleş dosttan gözüm yıldı

Düşman merdin aşığıyım

Biri dişli bir çarktır

Aynı millet aynı ırktır

Alevi Türk,sünni Türktür

Çerkez Kürdün aşığıyım.

Bu dünyanın kıymetine

Aldanmayın servetine

Aç kalsa da devletine

Bağlı ferdin aşığıyım

Yolcusu var kızıl yolun

Farkı benden şudur onun:

O Leninin O Maonun,

Ben Bozkurtun aşığıyım.

Arif dönmüş bir bülbüle

O aşıktır bağda güle

Ülkücülük dertse bile

Ben bu derdin aşığıyım.', 'Siz sormayın bana aşkı Ben bu yurdun aşığıyım Kalleş dosttan gözüm yıldı Düşman merdin aşığıyım Biri dişli bir çarktır Aynı millet aynı ırkt...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asigiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kastamonu Bizim İl.', 'kastamonu-bizim-i-l-cengiz-yazici-bhomv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kastamonu bizim il.

Çalış.Oku,onu bil.

Kuzeyi,Karadeniz,

Ne yamandır görseniz.

Batı yönde Zonguldak,

Dağı kara,yüzü ak.

Güney yönde,Çankırı,

Ovaları sapsarı.

Doğumuzda Sinop var,

Gemilere kol açar.

Çorum''lada komşuyuz,

Her işte uyuşuruz.

İnebolu ilçesi,

Yolcu eder herkesi.

Küre,Cide,Abana.

Atlırmı hiç yabana?

Devrekani,Azdavay,

Ver elini bay Daday.

Tosya pirinç yurdudur,

Araç,yayla kurdudur.

Kargı ırmak boyunda,

Pirinç büyür suyunda.

Taşköprü,zengin ülke,

Urgan sarar her yüke.

Yaşasın Kastamonu,

Kalbinde yaşat onu.', 'Kastamonu bizim il. Çalış.Oku,onu bil. Kuzeyi,Karadeniz, Ne yamandır görseniz. Batı yönde Zonguldak, Dağı kara,yüzü ak. Güney yönde,Çankırı,...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kastamonu-bizim-il-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Ateşi...', 'sevda-atesi-yagmur-adam-0raax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ateşi sevdim

Yaktıkça beni kendimden geçtim

Geceler boyu sensizliği içtim

Ben kıvılcımı değil ateşi seçtim

Benim sevdam ateş oldu 

Ateş yüreğime doldu 

Yüreğimin ateşinde

Cehennem ateşi soldu

Yüreğimin ateşi söndü

Ateş birden suya döndü

Aslında gördüğüm bir düştü 

Sevdam elimden düştü', 'Ben ateşi sevdim Yaktıkça beni kendimden geçtim Geceler boyu sensizliği içtim Ben kıvılcımı değil ateşi seçtim Benim sevdam ateş oldu  Ateş ...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Adam']::text[], 8.5, '{"poet":"Yağmur Adam","poet_slug":"yagmur-adam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevda-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl Düşleri', 'col-dusleri-mahmut-kuru-epv0r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen var mısın gerçekten

yoksa hayal oyunu mu 

oynadığımız birlikte

Seni düşünüyorum ansızın

bir yüz çiziyorum kumların üstüne

iki güzel göz çöle bakan

Baştan yaratıyorum durmadan bedenini

Uzanıyorum yanına incitmeden

yakıştırmaya çalışıyorum

Bu sen misin,gerçekten var mısın

yoksa çizdiklerim

senin düşlerine mi çıkıyor?

Çölde bir yatakta uzanıp

tanrıçalara giden yola bakarız

çöl tanrıçası, belki

rüzgarlarıyla savurur düşlerimizi

hepsi ayrı bir yana düşer

ayrı bir düşe sahiplilk eder

çöl gülleri de eşlik eder

o acımasız güzel kadının

yorulmayan atlarla yolculuğuna

Bilirsin atlara kanatlar takardık

uçururduk onları da

yanlarına düşlerimizi katarak.

Sonunda hep hüzünlere çıkardı

çöl tanrıçası gözükmezdi bize

meleklerini elçi yapardı yerine

Onlar dikenleri ayıklanmış

güller sunarlardı düşlerimize

dikensiz olmalıydı herşey 

çölde sen ve ben

Zorlu çöl yolculukları

bizim içindi,düşler olmadan

geçemezdik asla,

Hatırlar mısın bir keresinde

bir ateş yakmıştık çölde

oturup seyrediyorduk yanışımızı

köz köz

Birden atlar çıkmıştı hani kanatlıydı

ateşin çevresinde döndüler durmadan

hepsi birbirine iple bağlıydılar

kopmayan sağlam bir ip

Üstümüze güller yağıyordu.

Of,sen gerçekten var mısın

beynim zonklamalarla hemhal

yoksa her şey bir hayal mi

bir gün düşlerimizden çıkıp

gelecek misin yanıma

birlikte günbatımlarına çıkacak mıyız

yoksa hepsi bir hayal mi

sen yoksun aslında

seni ben baştan yarattım

sana bir yüz çizdim

iki güzel göz çöllerde

Yalnızlığıma arkadaş...

		24.06.2001-Dilovası', 'Sen var mısın gerçekten yoksa hayal oyunu mu  oynadığımız birlikte Seni düşünüyorum ansızın bir yüz çiziyorum kumların üstüne iki güzel göz ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/col-dusleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Teğet Geçti Kar Boran', 'yuregime-teget-gecti-kar-boran-asli-atabay-8g3fk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuşatılmış sözcükte içinde barınamayan  bir anlam ele avuca 

sığmaz haşarı düşte senden ve biraz benden arta kalan . Ayrık 

otum, kuşkonmaz baharımdan alabildiğine uzağa gittin.

İçimin sınır ihlali !  sana, yaban gülümsemene , pervasız

aşksız harabeme  son gidişim  son gelişim kendime  ...

Ki buluşamadığımız buluşturamadığımız nice şeyin arasından

ılık bir esinti gelse de sen beni anlayamadığından gittin yoksa

sevemediğinden değil !

Sevdin bilirim sessiz çoğunluk  yüreğin   suretime sarılırken 

kar kış bahar geçerdi, geçerdi de duymazdın 

Birer birer terk ettik odaları teker teker gittik. önce dışımız 

karıştı sonra sen baktığın aynada göremedin beni. itiraf 

edemeden. nedir itiraf dediğin   korkaklığın kayda değer darlığı . 

sen gittin alabildiğine uzağa...

Yüreğime teğet geçti kar boran .   gitiğin uzak benim

yakınımdan daha bi çare olmasaydı  olmasaydı gereksiz 

tekrarların çalıntı şarkı çaresizliğinde yada sevmemiş  olsaydın

gülüşüme ilintili hüznümü .Bırakırdım suretimde ne var ne yoksa 

istediğin .

pervasız aşksız harabem !       sen yüklenirken günahı sevabı

bana ıssız limanlara demir atmak kaldı .

20 haziran 2001', 'Kuşatılmış sözcükte içinde barınamayan  bir anlam ele avuca  sığmaz haşarı düşte senden ve biraz benden arta kalan . Ayrık  otum, kuşkonmaz ...', ARRAY['Türk Edebiyatı','Şiir','Aslı Atabay']::text[], 8.5, '{"poet":"Aslı Atabay","poet_slug":"asli-atabay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yuregime-teget-gecti-kar-boran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın VArdığı O Yer', 'askin-vardigi-o-yer-asli-atabay-il8ot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir güne başlamak senle hesapsız kitapsız bir öncesi silinmiş taze bir 

sayfayla

şaşırmadan önceden seçilmemiş cümlelerle.

kimsesiz kalmış gibiyim .

kendimce biriktirdiklerim yetmiyor.

yetinmelerim daha sessiz oldu.

oysa kızılca kıyamet kopsa içimde farketmezdin.

Sen görürmüydün? Görsen de  yoksun.

baktığım hiçbir yer yok.

Yeni değil aşkın uzaktan seslenişi.

o çağrı en az bana olduğu kadar sana da yakın.

ne derdin sen

herşey oraya varır

AŞKA.

ama seslendiği ben değilim.

Küçümserdin küçümserdik birlikte uzun vadeli planları

kendi yalnızlığımızın tanıklığını küçümserdik

senin hep geçerli sebeplerin vardı

geçerlilik çoktan almıştı seni benden

uzun zaman önceydi unuttum bütün o sebepleri

Artık saklıyorum nicedir attıklarımı belki de kendimi

biriktirmedeyim.

Dost yüzlere daha dikkatli bakıyorum

unutmadan geçiyorum sözleri.

gülümseyişinin zihnime kazılı olduğu bölüm var ya özenle saklıyorum 

orayı.

Arada bir tazeliyorum gülüşünü.

bu aralar sık hatırlamam seni özlediğimden mi bilmem.

ben zaten  çok beklediğini zannettiğim o gün seni aramayışımın nedenini de

hala bilemem.

Herşey oraya varır derdin ya .AŞK çoktandır buraya varmıyor.

Galiba ben burdan sıkıldım .

aşkın vardığı oraya gitmeli . 

herşey hazır

Hem karışmasın diye kolilerin üstüne adları da yazılı.

gelse tanır mısın

sahi sen hala aşkın vardığı orda mısın?

				22 Haziran 2001', 'bir güne başlamak senle hesapsız kitapsız bir öncesi silinmiş taze bir  sayfayla şaşırmadan önceden seçilmemiş cümlelerle. kimsesiz kalmış g...', ARRAY['Türk Edebiyatı','Şiir','Aslı Atabay']::text[], 8.5, '{"poet":"Aslı Atabay","poet_slug":"asli-atabay","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/askin-vardigi-o-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-asli-atabay-q7lgv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaf dağının tepesindeki üç boynuzlu üç gözlü dev içimin sabır taşı.

kaç düş kurdum doğduğum sabahtan beri .

sahici masalım olsun istedim 

bilmezdim masalın sahicisi  sahibini görmezmiş.

Doğduğum sabahtan beri kaç düşüm yalnız uyandı sayamadım. 

ya sen ordaki sükunetin aşkı var yaptığını zanneden 

güzümün peri masalı

gel de görelim

uçan halı

hem seni hem beni içine alır mı?

boşver beni istersen

kifayetsiz bir masal anlatıcısının

kime hayrı dokunur

güzel uyuyan birkaç çocuktan başka

sen olur da

birden

yalnız

sabah

aklına düşersem

alır mıydı ikimizi

uçan halı

vazgeçmeden kendimizden

gözümün peri masalı

o sabah gel

uyanmadan düşüm sensiz!

		2001', 'Kaf dağının tepesindeki üç boynuzlu üç gözlü dev içimin sabır taşı. kaç düş kurdum doğduğum sabahtan beri . sahici masalım olsun istedim  bi...', ARRAY['Türk Edebiyatı','Şiir','Aslı Atabay']::text[], 8.5, '{"poet":"Aslı Atabay","poet_slug":"asli-atabay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensiz-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-yuksel-i-lhan-3k9rj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne bir sıcak el, saçlarımı okşayacak

Ne bir ses, bana sevgiden söz edecek

Nede ılık bir nefes...

Bu soğuk ve yalnız gecemi yokedecek

Bir tek ben ve gölgem yine...

Yeni bir güne merhaba diyecek.', 'Ne bir sıcak el, saçlarımı okşayacak Ne bir ses, bana sevgiden söz edecek Nede ılık bir nefes... Bu soğuk ve yalnız gecemi yokedecek Bir tek...', ARRAY['Türk Edebiyatı','Şiir','Yüksel İlhan']::text[], 8.5, '{"poet":"Yüksel İlhan","poet_slug":"yuksel-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/merhaba-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-i-brahim-yavuz-bildik-vv1zj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umutsuz bekleyiş geç vakte kadar,

Bilmem kaç gün sürer, daha ne kadar?

Geleceğim diye söz de vermiştin...

Bilmem kaç gün sürer, daha ne kadar?

Hep seni gelecek sanacak mıyım?

Gelsen bile sana kanacak mıyım?

Ömür boyu böyle yanacak mıyım?...

Bilmem kaç gün sürer, daha ne kadar?

Bunca bekletende olur mu vefâ?

Güldüğümü sanma! Bir gün, bir defa.

Kul''a çektirilmez, çektiğim cefâ.

Bilmem kaç gün sürer, daha ne kadar?

Gönlümdeki maya tutarsa eğer,

Hoşgörün, dumanım tüterse eğer,

Beklerim, bir ömür yeterse eğer...

Bilmem kaç gün sürer, daha ne kadar?', 'Umutsuz bekleyiş geç vakte kadar, Bilmem kaç gün sürer, daha ne kadar? Geleceğim diye söz de vermiştin... Bilmem kaç gün sürer, daha ne kada...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekleyis-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başımın Yeli', 'basimin-yeli-unal-bulut-zcl96', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklediğim rüzgar yala gökleri,

Seni dirilten bir ummandı eski,

Eski gitmişse yarala gökleri...

Her eve bekçi versek olacak bu,

Kapılara zil taktıkta ne oldu,

Gönül bekçisiz, sokak hırsız doldu...

Yol ayrımı kalbe ve beyne gidiş,

Sadece, karmaşaya hizmet bu iş...

Uşak aciz, efendiyle dişe diş,

Girilmemiş kabirlerin ölüsü,

Sen gündüzün ahı, gecenin süsü,

Burda acıların parlak yüzlüsü...

Siyah bacalar birer emir eri,

Asılık şu yelin başımdır yeri,

Başlar kaçmışsa karala gökleri', 'Beklediğim rüzgar yala gökleri, Seni dirilten bir ummandı eski, Eski gitmişse yarala gökleri... Her eve bekçi versek olacak bu, Kapılara zil...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/basimin-yeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat ve Şehir', 'hayat-ve-sehir-unal-bulut-dljwo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aldanmışlar ayağa kalkıp dikilse karşıma,

Onlar fazla, ben tek, olsun öylede tur atarım,

Buyursunlar katılmak isteyenler yarışıma,

Yük mü ağırmış? Çekilin altına ben yatarım.

Cefalar ortasında kıvranıp ağlasam her an

Kim duyabilir? ne kadar uzağa gider sesim ?

Derdim anlaşılır mı? Bulunur mu beni soran ?

Ben küçük lekeyim kağıtta, hayatsa resim

En uçurum noktasında elsiz kaldım hayatın

Dört kenarı eşit olmayan kare gibi bir şey

Faturası bana kesildi sahipsiz rahatın,

Ödemeyse sonraya kaldı, anlam yoksunu herşey

        Galiba tekrar ülke değiştiriyor bu şehir

        Hainler değil şehri ikiye bölen, bir nehir

        Kaçar, peşini bırakmaz, karartan kara gölge

        Takip edemezler yaşadıkları ayrı bölge

İller değişip adresler karışır mı acaba ?

Gidenlerden haber yok postacılar mı izinde ?

Korkuyorum bu halle boşa gidecek tüm çaba

Ağlıyor olacağız başlangıçların dizinde

Lâtif rüzgarlardan sonra işte burası orta

Hayat ve şehir, kabulleri yerinde ziyaret

Misafirperver hayat, yatıya yer olmaz orda

Şehrinse bağrı açık burda da kalan yok hayret

Ne ışıklar tanıdm, karartI ardında kuyruk

Ne kuyruklar gördüm, âmâ milyonların önünde

Orta yerde hiçe sayılmış ahlâk, tarih, uyruk

Cesaret yerine korku her aslanın gönlünde

        Ölümü yakındır acılar içinde adalet

        Sakarlar kol geziyor, hepsinin hali sefalet

        Parçalanmış vazoya çare etmez hiçbir alet

        Sağduyuya kulak ver, kendini arayan millet

Rahimane bir tavırla yanıma yaklaşınca

Yerle bir olunca sağlam dediğimiz surlar

Son defa görebildiğim karartı aklaşınca

Paklaşınca her yan, aşikar olacak kusurlar

Şişe dibinde kaldı kimi, kimiyse tepede

Sen zirve mahkumusun sinemezsin bir köşeye

Tükenmiş olanlar var, tırmanıştalar yinede

Unutma ki zemin cam, düzlük yok kimseye

Uyuyanlar uyanıyor niyhayet yavaş yavaş

Biraz geç kalmış zili çalanlar hala uykuda

Üstüne bir felaket gelmeli yada savaş

Kadir bilmeyenlere az buluyorum bunuda

        Vurulan tek ben değilim kollarında arkamdan

        Ne farkım kaldı bundan sonra adi bir korkaktan

        Sonum ya bir mızraktan olacaktı yada oktan

        Farkı anladığımdaysa olan olmuştu çoktan.

                                                                19/10/1998', 'Aldanmışlar ayağa kalkıp dikilse karşıma, Onlar fazla, ben tek, olsun öylede tur atarım, Buyursunlar katılmak isteyenler yarışıma, Yük mü ağ...', ARRAY['Türk Edebiyatı','Şiir','Ünal Bulut']::text[], 8.5, '{"poet":"Ünal Bulut","poet_slug":"unal-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/hayat-ve-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben''den Çektim', 'ben-den-cektim-i-brahim-yavuz-bildik-531jw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben''den çektim ne çektiysem

ne el 

ne dil

bel de değil kuşkusuz

ne çektiysem ben''den çektim

gökyüzü kadar doldum

bir damla yağamadım

beşiz hamile gönülle

yarım piç doğamadım

neresindeyim yaşamın

kaplumbağa telâşıyla 

neresinde doyumun

geceleri yıdız yıldız bezedim

gecenin rengini tutturamadım

gönül tuvalinde fırça ettim kalemi

hecenin rengini tutturamadım

aksın istedim dizeler

koksun istedim duygular

gönen tavında toprak gibi

çapalayıp vuran ben

çabalayıp duran ben

ben''den çektim ne çektiysem

yüzünün yan duvarında 

tablo gibi duran Ben!', 'ben''den çektim ne çektiysem ne el  ne dil bel de değil kuşkusuz ne çektiysem ben''den çektim gökyüzü kadar doldum bir damla yağamadım beşiz h...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-den-cektim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-alisan-satilmis-9kfn2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağladın mı? Hayır. Niye?

Çünkü kimse yoktu...

O, bir çocuktu...

Kimler (?) kimin demeleriyle büyür ya da alçalır

Hiç anlamayacak kadar / Küçücük!                                             

Kendince edilen... kendin yakışır küfürlere 

Aldırmazdı büyükler

Elbet büyüklüğün şanından değildi 

Bu hal...

Çocukça şeylerin bir anlam taşımadığından (dı)

Bilinirdi ki (Anlam) masal gelirdi. 

Bu yaşta olanlara / dahası isminin esrik destanında 

Kürşad''dı onun adı

Sırf şövalyelik ruhundan saldırdı yel değirmenlerine

Akıl, fikir, izan yerli yerine oturunca

Bir de başında kavak yelleri...Eksik kalınca 

Kaybolup giderdi tüm duyguları

O zaman büyümüş olurdu ''çocuk'' 

Ulu orta laflar etmenin neye bedel 

..Geldiğini de bilirdi

Ve öğrenirdi meledikçe...

Sürüde bir baş olmaktansa

Çoban köpeği olmanın (kimlere) yakıştığını

Ne diyelim iftiracılar (?) dünyanın 

En alçak çukurlarıdır

O, bir çocuktu... Kimler kimlerin demeleriyle büyür

Ya da alçalır. Hiç anlamayacak kadar küçücük

Küçüğü büyükten ayıran eksik yanıdır

Eksik tamamlanınca adam olur adam ÇOCUK!

Cüceydi -devleşti- 

Sonra kocaman gölgesinden

Korkmaya başladı

Ödlekti yüreklendi

Zamanla yiğitliği altında ezilip kaldı

Tek yüzlüydü, iki yüzlü oldu

Gün geldi biçare yitirdi kendi

Yüzünü

Onun için hayat bir oyundu

Yıllar geçti oyun içinde oyuncak oldu.', 'Ağladın mı? Hayır. Niye? Çünkü kimse yoktu... O, bir çocuktu... Kimler (?) kimin demeleriyle büyür ya da alçalır Hiç anlamayacak kadar / Küç...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/cocuk-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekler Tutulan', 'dilekler-tutulan-alisan-satilmis-nqhns', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün salmış beni ''azatlığın'' kelamına

Dar kapılardan geçmişim

Söylemek kavlinden söylenmişim (de )

Mişlere davetiye bilinmemişim her ne halse

Ki sıratı bilen yollar yürümüşüm 

Hükmü sakıt kalmış tevellütlerin

..Bir başın alığında

Mevsimler içre mevsimler büyütmüşüm

Adı sonbahar olan

Güz talanı yaprak

O yana bu yana savrulan

Kökü toprakta bir ağaç kalmışım

Bozkır yalnızlığı kurumuş

Efsunlu gelecekler büyüten

Her yüreğe açık kapı dilekler tutulan', 'Gün salmış beni ''azatlığın'' kelamına Dar kapılardan geçmişim Söylemek kavlinden söylenmişim (de ) Mişlere davetiye bilinmemişim her ne halse...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dilekler-tutulan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevgili', 'ey-sevgili-alisan-satilmis-hp5r2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey sevgili...

Gidişin mecburiyetin koynuna girdiğinde

Buz kesmiş duyguların soysuz yalnızlığında

Şehir gibi çürüdüm / Bir hoyrat sancı kaldım

Ahlarım kadar ''vahh''ların muhasebesini de yaptım 

Kurumuş çiçeklerin dal ucu kadar

Soğumuş bir ceset gibi

Her akşam hüzün donuk bakış kaldım

Düş gölgesi...İçimin sancıları

Acıtılmış yanlarıma hançer gibi saplanırken 

Her gece

Ölümü haklı çıkaran uykuda

İntihar kaygılarının perdesi kapandıkça

Salgın bir hasretin kötürüm duyuşunda

Delişmen bir vuslatın susuşunda sen kaldım 

Ey sevgili...

Murat almamış mevsimlerin göç serüvenlerinde

Mülteci dramı...

Tomurcuğu koparılmış gül dikeni

Kan revan yürüyüşlerde / Gece karanlığına', 'Ey sevgili... Gidişin mecburiyetin koynuna girdiğinde Buz kesmiş duyguların soysuz yalnızlığında Şehir gibi çürüdüm / Bir hoyrat sancı kaldı...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-sevgili-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-abacan-askisev-senkal-64d2w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutluluk, herkesle olmak değil; 

En zor anında yanında olacak,

Güçlüklere seninle karşı koyacak,

Gerçek dostlar bulabilmektir.

Mutluluk, sadece gülmek değil; 

Herşeyi gönülden duyabilmektir.

Sevginin güzelliğini görebilmek,

Hayattan daima zevk alabilmektir.

Mutluluk, yalnızca almak değil; 

Daha çoğunu verebilmektir.

Menfaat düşünmeyip kendine,

Karşılık beklemeden sevebilmektir.

Gerçek mutluluk ve onun sırrı; 

Kahkahalarda, övgülerde değil,

Huzurla yaşanan dolu bir günde,

Zor hissedilen bir tebessümdedir! 

En güzel mutluluk aslında,

Mutlu olabilmeyi bilmek ve

''''Mutluyum'''' diyebilmektir...', 'Mutluluk, herkesle olmak değil;  En zor anında yanında olacak, Güçlüklere seninle karşı koyacak, Gerçek dostlar bulabilmektir. Mutluluk, sad...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mutluluk-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Affet', 'sen-beni-affet-abacan-askisev-senkal-ovy90', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vazgeçtim, kaybettim herşeyimi,

Tükettim, yıprattım benliğimi,

Özledim, öldürdüm geçmişimi,

Ben seni affedemem, sen beni affet!

Çalıştım çabaladım yapamadım,

Ağladım, haykırdım unutamadım,

Seni sevmelere zaten doyamadım,

Ben seni affedemem, sen beni affet!

Hüzünlendim, dağladım yüreğimi,

Hep aradım, bulamadım sevgiliyi,

Uzandım sana, tutamadım ellerini,

Ben seni affedemem, sen beni affet!

Seni hiç kimselere soramadım,

Çok kızdım, sana kıyamadım,

Affetmek istedim ama yapamadım,

Ben seni affedemem, sen beni affet!', 'Vazgeçtim, kaybettim herşeyimi, Tükettim, yıprattım benliğimi, Özledim, öldürdüm geçmişimi, Ben seni affedemem, sen beni affet! Çalıştım çab...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-beni-affet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğimi Hatırlarım', 'sensizligimi-hatirlarim-abacan-askisev-senkal-zkpgi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur pencereme her vurduğunda,

Sokaklar karanlık olduğunda,

Geceleyin gözümü her yumduğumda,

Sensizliğimi hatırlarım...

Her sağanak yağmur sonrasında,

Simsiyah göklere baktığımda,

Toprağın kokusunu duyduğumda,

Sensizliğimi hatırlarım...

Gece yapayalnız kaldığımda,

Titreyerek her uyandığımda,

Kimi zaman korktuğumda,

Sensizliğimi hatırlarım...

Efkarlanıp sessizce ağladığımda,

Tekrar kalbim her kırıldığında,

Sokulacak birini aradığımda,

Sensizliğimi hatırlarım...

Her uzun günün sonrasında,

Böyle mahzun olduğumda,

Bir şeylere özlem duyduğumda,

Sensizliğimi hatırlarım...', 'Yağmur pencereme her vurduğunda, Sokaklar karanlık olduğunda, Geceleyin gözümü her yumduğumda, Sensizliğimi hatırlarım... Her sağanak yağmur...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensizligimi-hatirlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yüzlü Sevgiliye', 'huzun-yuzlu-sevgiliye-abacan-askisev-senkal-2na4q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tek dün vardı!...

Bugün yaşanmadı,

Yarın olmayacak!

Ayrılmadan önce 

Son hatırladıklarım:

Tatlı bir buse,

Sıcak bir tebessüm

Ve titreyen dudakların olacak...

Islak yollarda çamurlu izler,

Yağmur pek çok şeyi gizler,

Kalbimde yoğunlaşır hisler,

Aklımda hep o son halin...

Ellerinde renk renk çiçekler,

Arkanda küçük bahçeli evler,

Zirvesi bulutlu, yüksek tepeler,

Aklımda hep o son resmin...

Solgun dudaklarında pembe güller,

Hüzünlü yüzünde geçmişten izler,

Buğulanan gözlerinde keder,

Aklımda hep o hayalin...', 'Bir tek dün vardı!... Bugün yaşanmadı, Yarın olmayacak! Ayrılmadan önce  Son hatırladıklarım: Tatlı bir buse, Sıcak bir tebessüm Ve titreyen...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/huzun-yuzlu-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay Be...', 'vay-be-i-brahim-yavuz-bildik-k3bf6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'saklambaç oynuyorum özlemlerimle

yazık

her defasında ben ebe

mutluluk başka limanlara demirli

ama ben

baştan göçebe

geceler çiseliyor

aydınlık döşüne yaşamın

vay be!

gülüşlere gizlendim

ama

sobe!

biliyormusun dostum

babası belirsiz

bu zifiri piç gece 

çok şükür sadece

şiire gebe

heeyt be!...

                    19 06 2001

                      ankara', 'saklambaç oynuyorum özlemlerimle yazık her defasında ben ebe mutluluk başka limanlara demirli ama ben baştan göçebe geceler çiseliyor aydınl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vay-be-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-i-brahim-yavuz-bildik-df8e3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdânın semâsından nice yıldızlar kaydı,

Gözattım,gökyüzüne;tüm izlerin ordaydı.

Rengârenk yaprakların gözbebeği yemyeşil,

Bütün yapraklardaki o gizli sır,sevdâydı...

01.nisan 2001

 Ankara', 'Sevdânın semâsından nice yıldızlar kaydı, Gözattım,gökyüzüne;tüm izlerin ordaydı. Rengârenk yaprakların gözbebeği yemyeşil, Bütün yapraklard...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sir-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tren Ve Zaman', 'tren-ve-zaman-i-brahim-yavuz-bildik-4l0jz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şairin 13 yaşında yaşadığı bir tren yolculuğunun öyküsü

eski trenler

bir dura bir kalkaydı

sabit hızla giderlerdi

durak aralarında

ama ömür sürerdi 

iki gece üç günler

yollar boyu su doldururdum

boğazımda düğümler

çoğu zaman haşlanmış bir tavuk olurdu azığım

canım anam

yürek tandırında pişirdiği birkaç kete

ve yolcu etmenin tutuşumuyla

buharlaşan gözlerinde haşladığı

sarısı büyük köy yumurtaları

sıktıkça boğazımı...

her istasyonda su doldururdum

musluksuz göz pınarlarıma

daha âşk kalesine varmadan

Aşkale''de özlerdim

ışkın ve çaşır kokuların

buharlı trenin günlerlik yollarında

tünel ağizlarınca gürleşirdi

terlemeye yüztutmuş bıyıklarım

isini unutamadığım

ama ismini hatırlayamadığım istasyonlarda

kaptığım halde su sırasını

treni kaçırdığımı düşlerdim bazen

ve özgüvenim yetişirdi imdadıma

koşardım keseyoldan

üstelik...birkaç soluk beklerdim treni

bir sonraki istasyonda bin hızla

çocukluk işte..

ama inançlı olmaktı en güzeli

ya ekspresdi ya postaydı ya karma..

eski trenler

sabit hızla giderlerdi 

durak aralarında

bilmiyorum

tadı aynı mı hâlâ

onüç yaşımın gece yarılarındayken

kuşetli vagonun koridorunda

uyku mahmuru ter tomurcuklarımı

yalarken sabah ayazı pencereden

rengi şafağı andıran

ve kaçıncı trene aşlandığını bilmeden 

içtiğim kıtlama çayın

bazen

kuşetli bileti alır

yer bulamazdım üçüncü mevkide

kompartmana girmeden gösterir

kurulurdum baş köşeye

sayesinde sazımın

bazen

zorla tıkışabildiğim

kırık camlı vagon girişinde

Ilıca''ya varabildiğimi anımsarım

kuşluk vakti

tam da farz olmuşken soğuğa teslim olmak

hâlâ özlerim o günkü

geri dönme kararlılığımı

umurumda değildi

bu bahaneyle abimin ve dayıoğlunun

Erzurum''da yaşayacakları

gençliklerinin ilkleri

olsundu

onlar yaşasınlardı ilklerinde..

bense yol alıyordum geleceğime

iliklerimde...

hâlâ şaşarım

onlarca tünelden

günlerce geçmiş trende

ne de çabuk kirlenirdi

abimin üç numara beyaz naylon gömleğinin yakası

bense

kol ağızlarının kirine gizlemiştim

beklentilerimin aydınlığını

satır aralarında...

eski trenler

bir dura bir kalkaydı

sabit hızla giderlerdi

durak aralarında

trenler ivme kazandı

her istasyondan kalkıp

her durakta durmuyorlar artık

gidenler gitti

yapılacak hiçbir şey yok

ilk trene binmekten gayrı...', 'şairin 13 yaşında yaşadığı bir tren yolculuğunun öyküsü eski trenler bir dura bir kalkaydı sabit hızla giderlerdi durak aralarında ama ömür ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/tren-ve-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su''ya', 'su-ya-ahmet-sahin-soner-iimh7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamanı zamansız yaşamak

Su berraklığında

Gizli saklı bir umudun pençesinde yaşamak

Hani yıldızsız bir gece bir sis boğuntusunda

Gizli saklı bir boyuttan diğer boyuta geçiş sanallığında

Ve sende saklanmış bir su serinliğinde

Zamanı karanlığa bölerken

Rüzgarlara savrulurcasına yaşamak

Ne olduğunu bilmeden

Bir şekil çizmeden karanlığın düşüne

Senli bir izdüşüm zamanında

Sisli puslu bir karanlık gecede

Belli belirsiz çizerken yüzünü kara kalemlerle

Saçlarına yıldızlar çizerken

İsmini bilmediğimiz bir suya

Hasret şiirleri döktüm yüreğimden

Adı senden,

Dizesi sudan...

Mısrası benden,

Yüreğimden...', 'Zamanı zamansız yaşamak Su berraklığında Gizli saklı bir umudun pençesinde yaşamak Hani yıldızsız bir gece bir sis boğuntusunda Gizli saklı ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/su-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı:', 'adi-faruk-yapicigil-tgxio', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bİr kız sevdim

Adı: Meral!

Gözlerinde gördüğüm,

Herşey sanki hayal!', 'Bİr kız sevdim Adı: Meral! Gözlerinde gördüğüm, Herşey sanki hayal!...', ARRAY['Türk Edebiyatı','Şiir','Faruk Yapıcıgil']::text[], 8.5, '{"poet":"Faruk Yapıcıgil","poet_slug":"faruk-yapicigil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş... Yüzün...', 'gunes-yuzun-faruk-yapicigil-t6da9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş gibi parlıyordu yüzün;

Gecesinde, rüyama girdiğin günün!', 'Güneş gibi parlıyordu yüzün; Gecesinde, rüyama girdiğin günün!...', ARRAY['Türk Edebiyatı','Şiir','Faruk Yapıcıgil']::text[], 8.5, '{"poet":"Faruk Yapıcıgil","poet_slug":"faruk-yapicigil","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/gunes-yuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-sair-evindar-3mymu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni her düşündüğümde 

Ruhumda bir gül yeşeriyor sanki.

Senden önce bir çöl idim

Şimdi ise gül bahçesi', 'Seni her düşündüğümde  Ruhumda bir gül yeşeriyor sanki. Senden önce bir çöl idim Şimdi ise gül bahçesi...', ARRAY['Türk Edebiyatı','Şiir','Şair Evindar']::text[], 8.5, '{"poet":"Şair Evindar","poet_slug":"sair-evindar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-dusunmek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-bulent-isik-l8okl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kabarır gönlümde dermansız acı

Başıma ne dertler açar gözlerin

Tam ben olacakken başının tacı

Vefasız elleri seçer gözlerin.

Boynum kıldan ince öldür istersen

Yalnız sen dermansın bu derde bir sen

Peşinden koşarken kazara görsen

Ürkek bir martıdır uçar gözlerin.

Ne güzel bir işim evim var ama

Bir gece görülmez dönmek yuvama

Yıllardır yağmursuz çorak ovama

Verimsiz tohumlar saçar gözlerin.

Hedefim sevgindir çark edilemez

Vuslatım gözlerin terk edilemez

Ömrüm şarap oldu fark edilemez

Kadehten gizlice içer gözlerin.

Kışı da hatırla dalma bahara

Gitmeye mecburuz öbür diyara

Ne kadar bağırsam: ''Bir yuva ara''

Kulak vermeyip de kaçar gözlerin.

Ne dermanım kaldı ne gözümde fer

Gönül bu taş değil,bir umut ister

Var mı benden aşık? İnanmam göster

Cevabı veremez naçar gözlerin

Cevabı veremez naçar gözlerin.', 'Kabarır gönlümde dermansız acı Başıma ne dertler açar gözlerin Tam ben olacakken başının tacı Vefasız elleri seçer gözlerin. Boynum kıldan i...', ARRAY['Türk Edebiyatı','Şiir','Bülent Işık']::text[], 8.5, '{"poet":"Bülent Işık","poet_slug":"bulent-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gozlerin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yarısı Notları', 'gece-yarisi-notlari-melisa-gurpinar-5ftbc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben ondört yaşımdaydım ilk şiirlerimi yazdığımda

ve ilk aşık olduğumda bisiklete binen bir oğlana

- ama ondört yaşında hiç aşk şiiri yazmamış olmamı

aşkı anlamadan hiç konuşmayan bir sağduyuya mı bağlamalı -

sonra okulda bir ablaya aşık olacaktım

sonra saçları oluklu mukavva gibi dalgalı yaşlı bir memura

sonra -inanmaycaksın belki- sinemada yer gösteren bir

adama

sonra bir kaleciye

hey tanrım sonra bir deniz subayının ellerine

bir lise öğrencisinin uzun kiprikli gözlerine

ve gözlüklü bir keman öğretmenine

artık aşkı bir mirasyedi gibi harcayacaktım

hiç inanmadan duygu kaynağının bir gün kuruyacağına

ve kimbilir kaç yaşımda olacaktım

aşkın

ancak bedensel bir bütünleşme söz konusu olduğunda

onu gözelleştiren bir çaba olduğunu

şöyle bir düşünmeğe başladığımda

girişilmesi güç ve zorlu bir çaba olduğunu onun da

sen bir ozan kızısın

çok büyük tarihi aşklardan

ve sabun köpüğü gibi çocukluk günlerinden yaratılmadın

dünyanın bütün acılarını kollarında uyutan bir kadınsa

senin anan

artık kimselere aşık olamaz

olsa da can eriği yemiş gibi olur ancak....

ben onsekiz yaşında da hiç olmadım

kayak yaptığımı anımsamıyorum

yüzme havuzuna girdiğimi ve berbere gittiğimi de

dünyanın doğusuna doğru ilerledikçe

çoğalır hiçbir yaşa gelmeden ölenler

ve neden öldüğünü bilmeden ölenler yemen''de

altmış yaşında da olamaz kimse

kırkbeş yaşında da tam tamına

ben artık neyi yazıyorsam

onu yazdığım yaşta duracağım

karar verdim yalnız oralarda yaşayacağım

sen bir ozan kızısın

durmadan yaşlanan

ve ağlamaktan başka silahı olmayan

bir kadının değil

hırçın bir hesap uzmanı da değil vergi dairesinde

çok güler yüzlü bir bayan banka şefi de değil senin anan

devetabanlarıyla dolu bir odada müşteri ağırlayan

sapho''yu tanımamış olabilirim nazım hikmet''i

bir ozanım ama

ne faulkner''ı ne nietszche''yi saymakla biter mi

tanımamış olabilirim sözün gelişi

yunus emre gibi dağ başında kimseyi

atlı karınca mı keten helvası mı kiralık sandal mı

aksak timur ya da taptuk emre''mi diye sorabilirim

bunların anlamı

hiçbir okulu bitirmedim

hiçbir dili sevmedim ana dilimden başka

ben biraz çerkezim biraz arnavut biraz giritli

kendi esintilerimle başbaşa kalınca bazen tanımıyorum hiç

kimseleri

bilirim üzümü şarabı ve sirkeyi

-birbirinden elde edilen acı ve tatlı herşeyi-

reçellik incirlerin üstündeki kahverengi çilleri

kuzu etiyle rezene otu pişirmeği

dedemin biri beşyüz yıldanberi ıstanbul''da yaşarmış

söylentilere bakılırsa

ben gidip onu da görmedim

tanımak da istemiyorum aslında ''sülalemi''

hiç kitap da okumadım -var mı ötesi-.....', 'ben ondört yaşımdaydım ilk şiirlerimi yazdığımda ve ilk aşık olduğumda bisiklete binen bir oğlana - ama ondört yaşında hiç aşk şiiri yazmamı...', ARRAY['Türk Edebiyatı','Şiir','Melisa Gürpınar']::text[], 8.5, '{"poet":"Melisa Gürpınar","poet_slug":"melisa-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/gece-yarisi-notlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yarısı Notları (II)', 'gece-yarisi-notlari-ii-melisa-gurpinar-w8pii', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'nasıl anlatmalı sana bilmem

-birşeyi herkes gibi anlatmak da istemem-

bir tamburu sarsmış gibi yayılmalı sesin tınısı

ve yeni titreşimler eklemeli dinleyenin yüreğine

şimdi sana yaşam bir bayrak yarışıdır desem

yaşamın bir süreklilik konusu olduğunu bilirsin -herkes bilir-

salt yaşama güdüsünden başka şeyleri de

bayrak yapınca eline

kızım seçme sorunu çıkıyor işte o zaman insanın önüne

ozanlığı mı yürüteceksin benden öte

yalnızca üremeği mi

çiftçiliği mi

-hiç aklına gelmeyen bir işi mi-

yenikapı''da tekir ağlarını onaran ve hep yas tutan

kara başörtülü ermeni kadınlar gibi

gerçek anlamda bir ilericiliği mi yoksa

çağın ötesine kapıp götüreceksin

doğru bildiğin bir yöne de gereksinim duyacaksın tabii

-benim bildiğim yönü ne yapacaksın

kimse kimseyi çekmemeli zorla bir yöne

üstelik sen sorumlu değilsin ananın edimlerinden de-

yok yok sana varoluşu filan anlatamam -bilsem de anlatamam-

eğer zamanın kalırsa terziye git

kaynananı ağırla eline su dök

otel lobisinde otur arkadaşlarınla paran çoksa

bir kez olsun çay iç çin porseleninden yapılmış bir fincanla

istersen resim sergilerine de git

ilkçağı arala

shakespeare''e gidersen -hatırı kalmasın- saroş

marlowe''a da uğra

-kimse kim- tanımasan da uğra

hiç eyüp sultan camiine gitmedin mi

bahçesindeki sayısız evliyanın üzerine paçavra bağlanmış

mezar taşlarına bakıp karışık şeyler düşünmedin mi -onun gibi-

kızım senin anan kermes düzenleyen

saçları platin renginde

elli yaşlarında yüzü çok boyalı bir kadın değil

gündelikçi bir kadın da değil her gece bel ağrısından yakınan

ve elleri yıkanmaktan yara olmuş temizlik hastası

çocuksuz bir kadın da değil

söylüyorum ya binlerce kezdir

bir ozan

tam anladın sanıyorum

sonra öyle bir bakıyorsun ki yüzüme

yıkılıyor birbiri üstüne yığılı duran düşünceden

kuleler içimde

senin anan nefret eden bir ozan

insanların gözlerindeki hiç anlamamış bakışlardan

ve yaşamı büyük bir gizlilik içinde geçen

bir sürü karışık işi hep birlikte yapan insanlardan

ister istemez yalana ve ikiyüzlülüğe bulaşanlardan

yani güvenilmez olanlardan

insanlık adına nefret eden bir ozan senin anan

yaşam açık olmalı

kırlara bakan perdesi açık bir pencere gibi

aydınlık olmalı

başkalarının elinde rehin kalmış gibi

düşünsene nasıl yaşanır hesabı verilmemiş bir yaşam

diyelim ki çok bilinen bir örnek olsa bile

sevgilinin biri odada biri sofada biri sokakta

ve biri sur dışındayken

tümünün sigarası nasıl yakılır bir anda

telefondakine ne yapılır örneğin -bir vodvir midir yaşam-

karışık hesap sonuçta hep yanlış çıkar kızım

ve sayısız konuda olabilir karışıklık

önemli ve önemsiz de olabilir....', 'nasıl anlatmalı sana bilmem -birşeyi herkes gibi anlatmak da istemem- bir tamburu sarsmış gibi yayılmalı sesin tınısı ve yeni titreşimler ek...', ARRAY['Türk Edebiyatı','Şiir','Melisa Gürpınar']::text[], 8.5, '{"poet":"Melisa Gürpınar","poet_slug":"melisa-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/gece-yarisi-notlari-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yare', 'yare-ulas-balkir-cb9ig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dudaklarının aleviyle 

Kavrulurken yüreğimin gölgesi,

Direngen yürekli yarim,

Gözlerin unutturuyor mahpusluğu....', 'Dudaklarının aleviyle  Kavrulurken yüreğimin gölgesi, Direngen yürekli yarim, Gözlerin unutturuyor mahpusluğu.......', ARRAY['Türk Edebiyatı','Şiir','Ulaş Balkır']::text[], 8.5, '{"poet":"Ulaş Balkır","poet_slug":"ulas-balkir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peki Sen !', 'peki-sen-asli-sekeroglu-lhh9g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzünün karanlık sessizliği

Çöktü üzerime bu gece

Bir ben miyim ağlayan bu şehirde

Bana eşlik eden gözler de var mı !

Bulutlar geçiyor sıra sıra

Sanki bir yere yetişmek için koşturuyorlar

Bir ben miyim elinde kalemi olan bu gece

Bana eşlik eden dizeler var mı başka yerlerde !

Ay bu gece de ağlamaklı

Baksanıza saklanmış bulutların arkasına

Bende saklanıyorum annemden

Bir perde arkasında ...

Ahh ayı gördüm

Kara bulutlar önünden geçtikçe

Saklanmış gözyaşlarının döküldüğünü hissediyorum

Bulutlar ne kadar da hızlı geçiyor.

Her zaman şaşkın olan ay

Bu gece benim gibi gökyüzünü seyrediyor

Onun da kara bulutlar geçiyor önünden

Benim de, bunu okuyan senin de ...

O hala parlak

Peki ben

Peki sen

O hala gökyüzünde

Peki ben

Peki sen

O hala güzel

Peki ben

Peki sen !', 'Gökyüzünün karanlık sessizliği Çöktü üzerime bu gece Bir ben miyim ağlayan bu şehirde Bana eşlik eden gözler de var mı ! Bulutlar geçiyor sı...', ARRAY['Türk Edebiyatı','Şiir','Aslı Şekeroğlu']::text[], 8.5, '{"poet":"Aslı Şekeroğlu","poet_slug":"asli-sekeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/peki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim !', 'o-benim-asli-sekeroglu-k75c5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hala kulaklarımda sesini duyuyorum

Beni sevdiğini söylüyorsun

Ama büyü bozuldu

Sen çöle düştün

Serap mı gördüğünü zannediyorsun

O benim !', 'Hala kulaklarımda sesini duyuyorum Beni sevdiğini söylüyorsun Ama büyü bozuldu Sen çöle düştün Serap mı gördüğünü zannediyorsun O benim !...', ARRAY['Türk Edebiyatı','Şiir','Aslı Şekeroğlu']::text[], 8.5, '{"poet":"Aslı Şekeroğlu","poet_slug":"asli-sekeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/o-benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-ulas-balkir-dsxpo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umudun ve sevginin

 gül goncası misali

 yeşerdiği günler boyu

 kirpiklerine doluşmuş

 gözyaşları kadar

 yakın olmak sana

 doyasıya tatmak seni

 sevişmek saatler boyu...

95', 'Umudun ve sevginin  gül goncası misali  yeşerdiği günler boyu  kirpiklerine doluşmuş  gözyaşları kadar  yakın olmak sana  doyasıya tatmak se...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Balkır']::text[], 8.5, '{"poet":"Ulaş Balkır","poet_slug":"ulas-balkir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aska-dair-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemname', 'sitemname-ulas-balkir-3pybe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tenine dokunamadığım

 teriyle üşüyemediğim

 kimseyle paylaşamadığım

 içimden atamadığım

 sen unutamadığım

 öpmeye kıyamadığım

 sevmeye doyamadığım

 saçlarını okşayamadığım

 birlikte sabahlayamadığım

 sesiyle ısınamadığım

 başına dönemediğim

 kapısını çalamadığım

 su başında göremediğim

 elinden su içemediğim

 gözlerine bakamadığım

 elini tutamadığım

 doyasıya öpemediğim

 sen aşkıyla yandığım....

 98', 'tenine dokunamadığım  teriyle üşüyemediğim  kimseyle paylaşamadığım  içimden atamadığım  sen unutamadığım  öpmeye kıyamadığım  sevmeye doyam...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Balkır']::text[], 8.5, '{"poet":"Ulaş Balkır","poet_slug":"ulas-balkir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sitemname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Öpmek', 'gunesi-opmek-cem-veysel-gul-lzbsv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göğe uzanmak,

Uzanıp senin için çiçek toplamak

Yada güneşi öpmek,

Bulutları okşamak,

Dalında çiçek okşar gibi.

Sevebilmek en ateşli yerinde.

En hızlısını yaşamalı,

Şimşekler çakmalı yüreğinde,

Yada en şiddetli yağmurlarda,

Sırılsıklam aşık olmalı,

Baştan ayağa kadar.

Sevgi ekmeli saçlarına,

Yada gökkuşağı altında,

Sevişebilmeli en olmadık yerinde.

Hayatın köklerine uzanabilmeli yani.

(istanbul,31.04.2001)', 'Göğe uzanmak, Uzanıp senin için çiçek toplamak Yada güneşi öpmek, Bulutları okşamak, Dalında çiçek okşar gibi. Sevebilmek en ateşli yerinde....', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunesi-opmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmek İstediklerim Var Uzaklarda', 'gormek-i-stediklerim-var-uzaklarda-nihal-kose-isik-xsuyt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutlu bir gündür dilenen

ve özlenen

Ümittir dilenen

Nefesinle soluduğun bu havada

Yüzüne vuran rüzgar

al al yapar yanaklarını

Yeni bitmiş çimleri görürsün

nemli toprak üstünde

Yeşil yemyeşil uzanan ve toprağı saran...

Ve incitmemek için çiçeği

nazikçe yürürsün

parmaklarının üstüne basarak

Nefes bile alamadığın yerden 

uzaklardasındır şimdi

Büyük ağaçların derinliklerine ilişir

gözlerin sonsuz

ve üstteki dağlara

sipsivri uzanan

Biraz sisli ve puslu

uzanasın gelir oraya

Daha dersin daha yürümeliyim

Görmek istediklerim var

Morl lale ve pembe papatya

Bembeyaz bir dağ

Daha dersin daha 

Görmek istediklerim var uzaklarda

07.01.1999', 'Mutlu bir gündür dilenen ve özlenen Ümittir dilenen Nefesinle soluduğun bu havada Yüzüne vuran rüzgar al al yapar yanaklarını Yeni bitmiş çi...', ARRAY['Türk Edebiyatı','Şiir','Nihal Köse Işık']::text[], 8.5, '{"poet":"Nihal Köse Işık","poet_slug":"nihal-kose-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gormek-istediklerim-var-uzaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğurlama', 'ugurlama-ozan-durmaz-dokxf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'UĞURLAMA

Hava ağır,bunaltıcı sıcak

Yağmur damlaları ıslatıyor,

Yeni ölmüş birinin kefenini

Ve ağırlaşıyor daha da koku

Hızlanıyor yağmur

Ve damlalar tutuyor toprağın elinden

Ferahlıyor yeni yeni hava

Naaşın başındaki insanların,

Solukları hızlanıyor

Sanki ölen içinde nefes alıyorlar.

Yaşlı kadın dayanamıyor daha fazla

Tam düşecekken toparlanıyor...

Küçük çocuk arkadaşını kovalıyor,

hemen arka tarafta.

Ve bekçisi mezarlığın;

Eski sevdiğini düşünüyor,

Elinde votka şişesi.

Sonra en güzel çiçekçisi geliyor oraların

En güzel güller,en güzel karanfiller

Rengarenk serpiliyor mezara,

Geç kalınmış mutlak!..

Niye ölmeden önce verilmez bunca çiçekte,

Sevilen yitirilince verilir?

İşte insanlarda,

Bunun için ağlıyor.

Yağmur hafiflliyor,ince ince artık.

Kuşlar daldan dala gidiyor konuyor

Ve şakıyorlar...

Soğuk günlerin acısını çıkarır gibi...

Ve bir kozadan çıkıyor,

Yeşil üstüne sarı benekli kanadı olan kelebek.

Biri giderken,

Diğeri merhaba diyor!

Ve dağılıyor yavaş yavaş kalabalık

Gece çöküyor önce,

Güneş doğuyor sonra.

Dün ağlayan yaşlı kadın,

Bugün çiçekleri suluyor umarsızca...

Küçük çocuk okula gidiyor,

Arkasındaki arkadaşından kaçarak...

Mezarlık bekçisi ise

Elini tutuyor falcı kadının

Diğer elinde votka şişesi...

Ve güzide çiçekçisi mahallenin,

En güzel kıyafetleri üstünde,

Yeni siparişleri hazırlıyor.

Kuşlar;renkli kanatlı kelebeği kovalıyor.

Yağmur bastırıyor bir anda,

İnce ince yağıyor...

Her birinin,

Her birimizin yüreğine

İnce ince yağıyor yağmur

Her gün yeniden,yeniden yağıyor...

Yağmur her gün birini uğurluyor.', 'UĞURLAMA Hava ağır,bunaltıcı sıcak Yağmur damlaları ıslatıyor, Yeni ölmüş birinin kefenini Ve ağırlaşıyor daha da koku Hızlanıyor yağmur Ve ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ugurlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgara Karşı Uçmak', 'ruzgara-karsi-ucmak-nihal-kose-isik-tr8g3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçinden geldiği gibi yaşanmalıdır hayat

Sorgusuzca, kaygısızca, sualsiz

Bilmelisin bir kuş konuşamaz hiç

Ama göremediklerini görür 

ve atar kalbi 

bazen ürkek bazen hızlı

Yaşayamamaktan korkar bir tek

ve erişememekden sevdiklerine

Hayranlıkla izlemelisin onu

Timsalidir özgürlüğün, uçmanın

Dengenin ve narince yaşamanın

Ve herkes kuş olmak ister 

Bir gün bile olsa

Rüzgara karşı uçmak

Dağların üstünden geçmek

Küçük insanları yukarıdan seyretmek

Ve yeni diyarlar gezmek...

07.01.1999', 'İçinden geldiği gibi yaşanmalıdır hayat Sorgusuzca, kaygısızca, sualsiz Bilmelisin bir kuş konuşamaz hiç Ama göremediklerini görür  ve atar ...', ARRAY['Türk Edebiyatı','Şiir','Nihal Köse Işık']::text[], 8.5, '{"poet":"Nihal Köse Işık","poet_slug":"nihal-kose-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruzgara-karsi-ucmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek', 'bir-tek-aziz-akgun-t58se', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne kin duyarım geceye

ne de özlerim sabahı

sadece bir ses kulaklarımda 

kardeşimin son ahı', 'ne kin duyarım geceye ne de özlerim sabahı sadece bir ses kulaklarımda  kardeşimin son ahı...', ARRAY['Türk Edebiyatı','Şiir','Aziz Akgün']::text[], 8.5, '{"poet":"Aziz Akgün","poet_slug":"aziz-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-tek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey Var', 'bir-sey-var-aziz-akgun-y3rlg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Menekşe''ye Şiirler) 

ellerini ver bana

ellerini sevdiğim

bir şey var dudağımda 

sana söyleyemediğim', '(Menekşe''ye Şiirler)  ellerini ver bana ellerini sevdiğim bir şey var dudağımda  sana söyleyemediğim...', ARRAY['Türk Edebiyatı','Şiir','Aziz Akgün']::text[], 8.5, '{"poet":"Aziz Akgün","poet_slug":"aziz-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-sey-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyada', 'dunyada-cevat-aydin-i4bmg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Harap olmuş bitap olmuş dünyada,

Okunmuş anlaşılmamış kitap olmuş dünyada.

Sevmiş aşık olup yanmış,

Karşılık görüp murat almamış,

Mecnun gibi dolaşmış dünyada.

Doyamadan çocukluğuna,

Büyük yükler taşımış omzunda.

Kıymet bilmemiş kalp kırmış,

Vurup çıkmış dağlara.

Zindanlara atılmış,

Sürgünlere katılmış,

İtilmiş kakılmış,

Kul olmuş dünyada.

Her mutluluğa darılmış,

Hep kaybetmiş kazanamamış,

İyilik edip yaranamamış,

Tövbe edip arınamamış,

Günahkâr olmuş dünyada.

Bülbül gibi feryat etmiş,

Feleğin bin bir sillesini yemiş,

Gül olup solmuşuz dünyada,

Kadir bilmezlere kul olup,

Anlamsız ölmüşüz dünyada.', 'Harap olmuş bitap olmuş dünyada, Okunmuş anlaşılmamış kitap olmuş dünyada. Sevmiş aşık olup yanmış, Karşılık görüp murat almamış, Mecnun gib...', ARRAY['Türk Edebiyatı','Şiir','Cevat Aydın']::text[], 8.5, '{"poet":"Cevat Aydın","poet_slug":"cevat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Oldum', 'asik-oldum-nurol-banabak-o3s9u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimden bir kuyrukluyıldız geçiyor.

Işıldıyorum!

Ben buna;

Aşık olmak diyorum!

Yüreğim akvaryum.

Canım, su.

İçinde yüzüyorsun!

Ben buna;

Aşık olmak diyorum!

Ölüm sek içilse de gülüm

Seninle vız geliyor!

Ben sana 

aşık oldum, diyorum!', 'İçimden bir kuyrukluyıldız geçiyor. Işıldıyorum! Ben buna; Aşık olmak diyorum! Yüreğim akvaryum. Canım, su. İçinde yüzüyorsun! Ben buna; Aşı...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asik-oldum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeli', 'sevmeli-cem-veysel-gul-z5m45', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan sevecekse yaşamalı,

Evrendeki her şeyi.

Yağmurdan sonra,

Yaprakta kalan son damla gibi,

Sevmeli güneşi.

İnsanları sevebilmeli,

Hatta verebilmeli canını,

Amaç sevgiyse güzellikse.

Güller bile açar sevgi için,

Çiçekler bile koku saçar bunun için.

Güzelliğe kıymamalı,

Yok etmemeli aşkı sevdayı,

Hatta emek harcamalı aşk için.

Canla bedenle sevmeli ömür boyu.

Bal yaparmı arı sevmese sevilmese.

Kötülere anlatmalı.

Ölüm neylediki söz neyler dememeli.

Bir kuş kanadında,

Gülücükler götürmeli onlara.

Sevmeyi öğretmeli,

Yani sevmeli.

Aşık olunmalı,

Ve sevecekse yaşamalı insan,

Hemde çokça yaşamalı..

(31.01.2001.19.45.istanbul)', 'İnsan sevecekse yaşamalı, Evrendeki her şeyi. Yağmurdan sonra, Yaprakta kalan son damla gibi, Sevmeli güneşi. İnsanları sevebilmeli, Hatta v...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Yüzü', 'askin-yuzu-cem-veysel-gul-qsxa8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzü aşkın yüzü oluncaya dek sevecekmiyiz.

Ben burada sen orada, 

Aç kollarını sevdiceğim, 

Uzanabilirsin belki yıldızlara, 

Belki uzak kalır yıldızlar tutamazsın, 

Kimisi parlak kimisi sönük, 

Ufukta yere yakın olsa bile, 

Senle benim gibi yani, 

Her biri diğerine çok uzak.

İçlerinden biri bir gün kayar belki, 

İşte o yıldız ben olurum, 

Sana doğru gelirim.

Yada sen tutuşup yanarsın, 

Rüzgarında yardımı ile, 

Bana doğru uçar küllerin.

Ben kollarımı açmış olacağım o zaman, 

Yani seni bekleyeceğim, 

Yada sen kucaklayacaksın göğü, 

Gökteki beni.

Yer yüzümü yoksa gökyüzümü, 

Aşkın yüzü olacak bilmem ama, 

Ben yer yüzü aşkın yüzü oluncaya dek yanacağım, 

Her gece sevgilim, 

Her gece tepende olacağım, 

Senin dünyanı aydınlatacağım, 

Umutlarına ışık olacağım, 

Yani seni gözetleyeceğim, 

Usul usul yanacağım sevdanla, 

Taki sana kavuşuncaya dek.

İşte o zaman, 

Kollarını aç ve beni bekle, 

Yıldızlarla geleceğim, 

Bekle sevdiceğim, 

İşte o zaman aşkın yüzü olacak her yer.

Bekle beni sevdiceğim, 

Aşkın yüzünü bekle.

(16.03.2001.istanbul.02.20)', 'Gökyüzü aşkın yüzü oluncaya dek sevecekmiyiz. Ben burada sen orada,  Aç kollarını sevdiceğim,  Uzanabilirsin belki yıldızlara,  Belki uzak k...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/askin-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göğe Sesleniş', 'goge-seslenis-cem-veysel-gul-sir5c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haykırmak istiyorum gökyüzüne, 

Sesimi duyan yıldız çıkarmı.

Bir öpücük kondursam çobanyıldızına, 

Yarime ulaştırırmı acaba.

Ay''a yalvarsam aydınlatırmı yarimin gönlünü, 

Sıcaklığımı, sevdamı ulaştırırmı acaba.

Göğe sesleniyorum gökteki varlıklara, 

Sesimi ulaştırın, sevdamı yansıtın, 

O''na sevdiğimi, hasretimi söyleyin.

Uçun kuşlar uçun yarime doğru, 

Yüreğimin acısını götürün yarime, 

Alın beni kanatlarınızın arasına, 

Uçalım yarimi bekletmeyelim, 

Aşkıma şahit olun hepiniz, 

Gökyüzünde halay tutun düğünümüzde.

Nikah şahidimiz olun martılar, serçeler, 

Hep bir ağızdan söyleyelim bu türküyü.

Evet diyelim hep bir ağızdan, 

Evet seviyoruz diyelim.

(istanbul,05.05.2001.01.30)', 'Haykırmak istiyorum gökyüzüne,  Sesimi duyan yıldız çıkarmı. Bir öpücük kondursam çobanyıldızına,  Yarime ulaştırırmı acaba. Ay''a yalvarsam ...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/goge-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-fidan-aykut-hewjz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoruldum; anlaşılmamaktan,

Sevdiklerimi, sevenlerimi ''dost'' yapmaya çalışmaktan,

Yüreğime kulak tıkayıp mantıklı olmaya çalışmaktan,

Haksız ithamlarla yaralanmaktan.

Yoruldum; sevgime hak ettiği değeri bulamamaktan,

Güzel bildiğim insanları bir bir hayatımdan çıkarmaktan,

Sevdiğim gibi sevilmeyip, sevmeyi isteyipte sevememekten,

İncinmekten, yalnızlıktan, gözyaşlarından....

Yoruldum;

Dostluk limanımda huzur bulamayan okyanusun beni bilmeden yaralamasından,

Camdan bir vazo olan yüreğimin, her defasında parmaklarımın arasından kayıp tuzla buz olmasından,

Dipsiz bir sevgi kuyusu bulduğunu zanneden sevgi çiçeğimin, umutsuzca solmasından,

Yoruldum....

28.5.2001/ İstanbul', 'Yoruldum; anlaşılmamaktan, Sevdiklerimi, sevenlerimi ''dost'' yapmaya çalışmaktan, Yüreğime kulak tıkayıp mantıklı olmaya çalışmaktan, Haksız ...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yoruldum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Armağanı', 'coban-armagani-tacettin-simsek-o0xhw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bir koca kentin

o deniz gözlü kızı

Hem belki de en zengini

en kaygısızı

Varken babanın onca sakız fabrikası

Mümkün mü

getirmek sana

bir çam sakızı', 'Sen bir koca kentin o deniz gözlü kızı Hem belki de en zengini en kaygısızı Varken babanın onca sakız fabrikası Mümkün mü getirmek sana bir ...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/coban-armagani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Ve Ay', 'gunes-ve-ay-cem-veysel-gul-5z8ct', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşmi ay'' a aşık, 

 Yoksa ay''mı güneş''e bilinmez.

 Benmi ay''ım senmi güneş''sin belli değil, 

 Yada benmi sana aşığım, 

 Senmi bana belli değil.

 Ay''la güneş her an.

 Birbirlerini kovalar giderler.

 Her an sıcaklıklarını hissederler.

 Ne zaman ayrıldıkları bilinmez, 

 Ama onlar birbirlerini seviyor.

 Kavuşacakları günü beklerler, 

 Her an her saniye.

 Belki sen ay''sın bende güneş, 

 Belki kavuşuruz.

 Bir gün benim sıcaklığım yakacak seni, 

 Yada senin ışığın çekecek, 

 Beni sana bilinmez.

(17.02.2001, istanbul,02.25)', 'Güneşmi ay'' a aşık,   Yoksa ay''mı güneş''e bilinmez.  Benmi ay''ım senmi güneş''sin belli değil,   Yada benmi sana aşığım,   Senmi bana belli d...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gunes-ve-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun Yanımda', 'yoksun-yanimda-fidan-aykut-mmhss', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamla ölümün,

Var oluşla yok oluşun,

Bitişle başlangıcın,

Ve suyla toprağın kenetlendiği o anda,

Meğer ne çok ihtiyacım varmış O güven dolu kucağa.

Yazık ki yoksun yanımda.

17.08.2001/ İstanbul (Deprem günü)', 'Yaşamla ölümün, Var oluşla yok oluşun, Bitişle başlangıcın, Ve suyla toprağın kenetlendiği o anda, Meğer ne çok ihtiyacım varmış O güven dol...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yoksun-yanimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı İstanbul Olan Sevda', 'adi-i-stanbul-olan-sevda-tacettin-simsek-2tlh8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya bize zengin görünür

yoksul olur

Dağlar bile

sevdamıza

birgün kul olur

Aşk ülküsü ardında gül uygarlığını

Bin yılda kurarsın

adı İstanbul olur', 'Dünya bize zengin görünür yoksul olur Dağlar bile sevdamıza birgün kul olur Aşk ülküsü ardında gül uygarlığını Bin yılda kurarsın adı İstanb...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/adi-istanbul-olan-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimle', 'sevgimle-fidan-aykut-eg4a1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ülkenin öbür ucunda da olsam,

Hissederim gözlerindeki hüznü,

Yüreğindeki acıyı,

Sevgimle, sevginle sar yaralarını...

11.09.2001/ Mersin', 'Ülkenin öbür ucunda da olsam, Hissederim gözlerindeki hüznü, Yüreğindeki acıyı, Sevgimle, sevginle sar yaralarını... 11.09.2001/ Mersin...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Adı Gül', 'askin-adi-gul-tacettin-simsek-x88ih', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söyler misiniz

en diri gül nerde açar

Bir gül

uyuyan bir göze

bin perde açar

Zannım bu ki

gül sadece toprakta değil

Kalbin uyanık gezdiği her yerde açar', 'Söyler misiniz en diri gül nerde açar Bir gül uyuyan bir göze bin perde açar Zannım bu ki gül sadece toprakta değil Kalbin uyanık gezdiği he...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askin-adi-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı', 'sizi-fidan-aykut-um57a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün ağaçlar bir bir soyunuyor.

Yazık üşüyecek hepsinin dalları.

Bütün yaprakları veda etmiş olsada, gövdenin sızısı;

Aşamaz yüreğimin sızısını.

10.11.1999/ İstanbul', 'Bütün ağaçlar bir bir soyunuyor. Yazık üşüyecek hepsinin dalları. Bütün yaprakları veda etmiş olsada, gövdenin sızısı; Aşamaz yüreğimin sızı...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sizi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-tacettin-simsek-85cp0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda ekeyim

gül dikeyim yollarına

Kaç yıl daha

hasret çekeyim yollarına

Etrafımı

gül yüzlü çocuklar sarsın

Binlerce oyuncak dökeyim

yollarına', 'Sevda ekeyim gül dikeyim yollarına Kaç yıl daha hasret çekeyim yollarına Etrafımı gül yüzlü çocuklar sarsın Binlerce oyuncak dökeyim yolları...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cagri-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Ağlıyor II', 'i-stanbul-agliyor-ii-fidan-aykut-gx2lf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul ağlıyor;

Sevdaları tüketmiş ayrılıkların üzerine,

Yeni doğan güneşe veda eden ayın üzerine,

Uyuyan bebeğine siper olan ananın üzerine,

Tomurcuk gülün, sararan yaprağın üzerine,

Toprakta yatanların geride kalanların üzerine,

İstanbul ağlıyor,

İnsan olan insanın üzerine...

25.09.2001/ İstanbul', 'İstanbul ağlıyor; Sevdaları tüketmiş ayrılıkların üzerine, Yeni doğan güneşe veda eden ayın üzerine, Uyuyan bebeğine siper olan ananın üzeri...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/istanbul-agliyor-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Künye', 'kunye-tacettin-simsek-5jvw2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve künyem dağ başlarında okunur

Zülfüyâre dokundukça ellerim

Ellerim tebeşir tozu ellerim

Eskimiş kara tahtalar üzre

Tut ki bir eskimez yazı ellerim

Ve künyem dağ başlarında okunur

Yad elim tetik düşürür yadıma

Yaman çeker söz mülküne yar beni

Söyle kim tarih düşürür bahtıma

Ve söyle kim kılar bahtiyar beni

Ve künyem dağ başlarında okunur

Bir kara kurşun değer kardeşime

Acıları harmanlayan kül/hani

Ey ölüm ey sevgili

Gözlerin çözer bendeki külhanı

Ve künyem dağ başlarında okunur

Ben bir ölü kentin ortasındayım

Lügatimde deli sözler dolaşır

Bir yağız atlıdır söz şimden geri

Terkisinde ince bir yürek taşır', 'Ve künyem dağ başlarında okunur Zülfüyâre dokundukça ellerim Ellerim tebeşir tozu ellerim Eskimiş kara tahtalar üzre Tut ki bir eskimez yazı...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kunye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Safâ Geldin', 'saf-geldin-tacettin-simsek-9lyi0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Safâ geldin evime tenha vakit

Be hey mübarek hüzün

Boyun borcum

Gönül harcım

Şiir burcum

Merhaba

Kandır beni yeniden

Hırka kasidesine döndür beni

Giydirip kuşatıp bir ikindiyi

Adına and içilen zamanlardan geçirip

Akşamlardan geçirip

Utandır beni

Doğru sabahlara uyandır beni

Âsiyim böyle biraz

Çağımla kalmadı alış verişim

Sınırlı avunmalar

Onurlu savunmalar kurmadayım

Cür''et bu ya

Bir de sözün gezginiyim üstelik

Olmazlara gönül yormaktır işim

Safâ geldin evime tenha vakit

Be hey mübarek hüzün

Boyun borcum

Gönül harcım

Şiir burcum

Merhaba', 'Safâ geldin evime tenha vakit Be hey mübarek hüzün Boyun borcum Gönül harcım Şiir burcum Merhaba Kandır beni yeniden Hırka kasidesine döndür...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/safa-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diri Bir Sevda Temi', 'diri-bir-sevda-temi-tacettin-simsek-3xtq2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1. Karşılama

Siz

Sormaya çekindiğimiz

Gizli geçmiş zamanlardan geldiniz 

Yâr üstüne

Köhne bir diyar üstüne

Unutulmuş bir mevsim getirdiniz

Kürsü yalnızlıkları

Tebeşir sitemleri arasında

Şehirler derledik gözlerinizden

Siz

Gizli geçmiş zamanlardan geldiniz

Siz çağa gücenmeniz

Ve çağı yenmenizle güzeldiniz

Ben

Kıyımlar içinde

Deyişler umarken duyuşlarıma

Ve mısralar adarken ölümlere

Geldiniz

Ölü toprağı serpilmiş şi’rime

Diri bir sevda temi eklediniz

Sesime belki hışım

Nefesime çağrışım

Canıma can meltemi eklediniz

Siz

Tozlu geçmiş zamanlardan geldiniz

Siz çağa direnmeniz

Ve çağı yenmenizle güzeldiniz

2. Uğurlama

Biz

Rengi uçuk beyaz

Yakın yer yıldızları

Kırpılmış kırpılmış da

Kapkara bir boşluğa serpilmişiz

Oysa siz

Karanlık bahçemizin sabâ meltemiydiniz

Bilmezdim böyle zamansız

Apansız

Gider miydiniz

Siz

Ardınızda

Kırılan geçmiş zamanlar bırakıp

Sırra kadem gittiniz

Ki olmadığınız her şehir tenha

Ve öylesine sessiz

Ses/siz

Bir çığlıkla bölünmüş rüyâ gibi gittiniz

Bozkır bakışlarımıza bengisu

Bir parça ümittiniz

Say ki yine eylüldür

Yüreğimin bağbozumudur artık

Cümle düşler yorumsuz kaldı yine

Cümle gülüşler yarım

Ahh böylesi ayrılık yoktu gündemimizde

Yoktu ama gittiniz

Yetim bıraktınız mısralarımı

Siteme elbette elvermez içim

Ama nasıl gittiniz

Nasıl gidebildiniz', '1. Karşılama Siz Sormaya çekindiğimiz Gizli geçmiş zamanlardan geldiniz  Yâr üstüne Köhne bir diyar üstüne Unutulmuş bir mevsim getirdiniz K...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/diri-bir-sevda-temi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Itırcan', 'itircan-tacettin-simsek-ueg0v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akşamlar

Bilirsin Itırcan

Önce bize gelir akşamlar

Acıları kuşanırız yeniden

Donar dudaklarımızda selâmlar

Gece ay dağıtırken perçemini

Bir kavis çizer ufkuma ellerin

Ürkek ışıklarla gelirsin bana

Denenmiş

ayrılıklarla

gelirsin

Akşamlar

Bilirsin Itırcan

Önce bize gelir akşamlar 

Kesilir damarlarımızdan biri

Çağın avuçlarına gül damlar

Bir bir uzaklaşır cennetlerimiz

Ve sonra elif meltemi gözlerin

Muhalif mevsimler getirir bana

Ölümler getirir

Yarım kalmış

tebessümler getirir

Akşamlar

Bilirsin Itırcan

Önce bize gelir akşamlar 

Yaşar yine eşref saatlerini

Kuytularda gül cellâdı adamlar

Gitgide eksilir yakınlıklar

Ve gitgide uzar matemlerimiz

Söz çeliği zincirler tutar bizi

Her adımda büyür sitemlerimiz

Erir gidersin

Hülyânı

yellere

verir

gidersin', 'Akşamlar Bilirsin Itırcan Önce bize gelir akşamlar Acıları kuşanırız yeniden Donar dudaklarımızda selâmlar Gece ay dağıtırken perçemini Bir ...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/itircan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Züleyhâ’ya Müstezad', 'zuleyh-ya-mustezad-tacettin-simsek-tfbyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '‘Bizi cehennemle korkutma vâiz’

Ateşle denenmişiz ömürlerce

Ateşle sınanmışız

Biz semender gönüllüleri aşkın

Önümüzde kaknus efsaneleri

Küflü zindanlar

Ardımızda kahkaha yangınları

Züleyhâ yangınları

Züleyhâ

züley

zül

Gül dediğin başka ne ki

Gündüz düşlerimizden

Yüzümüz hep dalgalı denizler

Gözlerimizde mecaz bulutları

Elif cüzümüz kenan kuyusunda

Yürüdükçe tarihçemiz kandı

Yol boyu yüzyıl boyu

Darağaçlarında hep Züleyhâ

Züleyhâ

züley

zül', '‘Bizi cehennemle korkutma vâiz’ Ateşle denenmişiz ömürlerce Ateşle sınanmışız Biz semender gönüllüleri aşkın Önümüzde kaknus efsaneleri Küfl...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zuleyha-ya-mustezad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Günlük Misafir', 'uc-gunluk-misafir-tacettin-simsek-4o2li', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O gün bir yaşlı köşkün vuruldu penceresi

Gelen kim diye sordu ince bir kadın sesi

Gelenler bir müjdeli haberin hamalıydı

Bir bohça bıraktılar hediye olmalıydı

Bir çiçekti armağan doldurdu kucakları

''Gül'' dedirtti adına kan rengi dudakları

O köşkün sakinleri güle öyle ki düşkün

Üç gündür en nazenin misafiriydi köşkün

Güldü mevsimler boyu gülecekti hesapta

Gülmüyor ağlıyordu yattığı gümüş kapta

Her hıçkırık silerken çizgisini sözlerin

Harcandı damla damla sermayesi gözlerin

Yerini beğenmedi demek ki dedi herkes

Her ağızda ayrı söz her ağızda ayrı ses

Artık ağlamıyordu o nazlı gül solmuştu

Sanki başka diyarın sevdalısı olmuştu

Son gün bir kalabalık geldi ''çiçeği verin''

Ayrılık azabını tattılar derin derin

Kavuşmadan ayrılık ölümden daha zordu

Mahzun kadın çaresiz ''götürmeyin'' diyordu

''Ağlamak çare değil sebep yok hiddet için

''Sizde emanetti bu kısa bir müddet için

''Anlayana üç günden farklı değil üç sene

''Götürmeliyiz artık çiçeği sahibine''

Son uykuya yatmıştı duymadan ilk haberi

Bu ihtiyar dünyanın gencecik misafiri

Belki de şakacıktan doğdu o nurlu çocuk

Dünyayı beğenmeyip giden gururlu çocuk', 'O gün bir yaşlı köşkün vuruldu penceresi Gelen kim diye sordu ince bir kadın sesi Gelenler bir müjdeli haberin hamalıydı Bir bohça bıraktıla...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Şimşek']::text[], 8.5, '{"poet":"Tacettin Şimşek","poet_slug":"tacettin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uc-gunluk-misafir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstop', 'i-stop-i-rfan-cebeci-vjojg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir top attım havaya 

Güneşe gülercesine

İstop!

Sıra sende.

Tünel kurdum dünyaya

Korkuyu yenercesine

İstop!

Sıra sende.

Masal kattım rüyaya

Devleri dövercesine

İstop!

Sıra sende.

Demir attım karaya

Gemiyi sürercesine

İstop!

Sıra sende.', 'Bir top attım havaya  Güneşe gülercesine İstop! Sıra sende. Tünel kurdum dünyaya Korkuyu yenercesine İstop! Sıra sende. Masal kattım rüyaya ...', ARRAY['Türk Edebiyatı','Şiir','İrfan Cebeci']::text[], 8.5, '{"poet":"İrfan Cebeci","poet_slug":"i-rfan-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istop-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-i-rfan-cebeci-ofl8t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şehir beni boğuyor  ilmik ilmik

Yağmur tutsak buluta, eve kapandım

Fotoğraflar çerçevemde tastamam

Geçmişe bakmaktan ne kadar usandım

Rüzgar kapımı çalıyor heryer ıssız

Hayalinle başbaşa , eve kapandım

Hatıralar bende kaldı tastamam

Sensiz yaşamaktan ne  kadar usandım

Yine aşksız geçiyor sevda mevsimi

Yüreğimde fırtına, eve kapandım

Ellerimde bir gül kaldı tastamam

Aşksız şarkılardan ne kadar usandım', 'Bu şehir beni boğuyor  ilmik ilmik Yağmur tutsak buluta, eve kapandım Fotoğraflar çerçevemde tastamam Geçmişe bakmaktan ne kadar usandım Rüz...', ARRAY['Türk Edebiyatı','Şiir','İrfan Cebeci']::text[], 8.5, '{"poet":"İrfan Cebeci","poet_slug":"i-rfan-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlik-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
