INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vedalar Da Güzeldir', 'vedalar-da-guzeldir-ahmet-beltekin-qrd3t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Değişmem  denizlerin  mavisine, gözlerinin  rengini,

Kaybolup  gitse  de  sevdamız  bu  gönül  selinde...

Yağmur  kokusu  başlar, saçlarının  her  telinde,

Dolarken  gözlerim, bir  türküde  bulutlar  gibi...

Eylül  bir  kuş  uykusu  kadar  hafif  gözlerinde,

Yanaklarından  süzülse  de  yaşlar  bir  gölge  gibi...

Siyahın  koyusuna  çizdim  de  yalnızlığımın  rengini,

Biliyorum, vedalar  da  güzeldir, senin  gözlerinde', 'Değişmem  denizlerin  mavisine, gözlerinin  rengini, Kaybolup  gitse  de  sevdamız  bu  gönül  selinde... Yağmur  kokusu  başlar, saçlarının...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vedalar-da-guzeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mumun Heybeti Değildir', 'mumun-heybeti-degildir-melon-sapka-wiv6u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mumun heybeti değildir 

