INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-i-lhan-berk-wistb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar ilk başında belli

Gökyüzünü çocukları büyütmüş

Denizle kuşlarla evlerle var

Dünyaya aşk diye hürlük diye

En yavuz  gerçek tohumlar ekmiş

