INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenaze İnsanlar', 'cenaze-i-nsanlar-yalcin-ergir-2ilfr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dedikoducudurlar

Sizin haberiniz yokken

Sizin ağzınızdan yalan konuşurlar

İnandırırlar da

Tesadüfen tanırsınız

Dibinizdeki ''Cenaze İnsan''ı

Titizdirler

Ve de korkunc egoist

Hiç kimsenin kendilerini sevmediğini çok iyi bilirler

Ama zaten herkes aptal değil midir? 

Her şeyi sorarlar

Hakkınızdaki her şeyi bilmek isterler

Ve asla unutmazlar

O fırsat bir daha ele geçmeyecekse

Sizi, sizin yanınızda satarlar

Sattıkları gidince de, onu size satarlar

Alıngandırlar

Bir o kadar da tedbirli

Ya az önce küsmüş

Ya da küsmek üzerelerdir

Küsme nedeni yaratmada

Ve işleri düşünce barışmada

İnanılmaz yaratıcıdırlar

Hep vardırlar

Yanınızda “en son kalan”dırlar

Hep görürler, görünmezler

Suçluluk duyarsınız

Yanlarında rahat olmaktan

Uyanık ve akıllıdırlar

Bulduklarını paylaşmazlar

İşi bitince yok ederler

Haindirler

Kuralları sapına kadar uygular

Kolunuza girivermezler

Şarkı da soylemezler

Anlamayacağınız

Acayip müzikler dinlerler

Hiç yok olmazlar

Karanlıkta karşınıza çıkan

Kara bir gölge gibidirler

Tüccardırlar

Karlarını çok iyi bilirler

Döver gibi sevişir

Eşlerini, eski sevgililerini

Müthiş kıskanırlar

Sizi de korkunç kıskanırlar

Kendisine bağımlı hale getirmek

Kendinize güveninizi yitirmeniz için

Hiçbir fedakarlıktan kaçınmazlar

Sizinle ilgili herşey alay konusudur

Sizin yaptığınız herşey hatalıdır

Ve siz, aslında bir aptalsınızdır

Cenazenizi ilk omuzlayacak

Toprağı mezarınıza ilk atacak

Dostlarınıza ''ilgisizlik'' suçlamalarında bulunurken

Arkanızdan ''en iyi dostumdu'' diye ağlarken de

''İyi oldu, pezevenk'' diye düşüneceklerdir

Onlar “Cenaze İnsanlar”dır

Onlar yaşamınızdan eksik değildirler

Kimi zaman yan komşu

Kimi zaman arkadaşınız

Kimi zaman sevgilinizdirler', 'Dedikoducudurlar Sizin haberiniz yokken Sizin ağzınızdan yalan konuşurlar İnandırırlar da Tesadüfen tanırsınız Dibinizdeki ''Cenaze İnsan''ı T...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergir']::text[], 8.5, '{"poet":"Yalçın Ergir","poet_slug":"yalcin-ergir","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/cenaze-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Anlatır Bir Resim', 'neler-anlatir-bir-resim-yalcin-ergir-8a3o4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne anlatır; neler anlatır,10 mart 1947 de, Konya''da

okul bahçesinde çekilmiş siyah beyaz bir resim? 

Gencecik bir öğretmen; 

elleri belinde, omuzlarında Cumhuriyet; 

kanat açmış beyaz yakaların bedenlerini eğitmekte

Fırtına beklemekte; 1950 ler ve sonrası beklemekte 

üç sıra dizilmiş yürekleri, okul duvarının dışında

ve gencecik bir öğretmen bağırmakta; 

''bir, iki, bir, iki...''

555 K beklemekte okul kapısının hemen ardında

Ahmet Tarık Tekçe gülümsemekte dut ağacının altında

Radyo da; ''Millet Partisi''nin amblemi kartaldır...''

motosiklet sürmekte bir delikanlı, Şarkışla yollarında, 

eşekler yemekte samandan bir otomobili, yan sokakta

Kırık bir T cetveli, kırık bir gözlük durmakta bir başka okul yolunda

Elinde altın kalem, gözlüğü sağlam bir adam konuşmakta

köşeyi dönünce karşına çıkan ekranda, 

minicik bir telefon çalmakta uzakta, çok uzaklarda

yılların ardında, aynı topraklarda; başka, bambaşka diyarlarda

Önce sevgi, sonra beş parmağın izi beklemekte terli yanakları

Ankara''dan gelecek abiler, özlemler beklemekte taş istasyonlarda

Konya''da, bedenlerin de eğitildiği bir okulun bahçesinde çekilmiş 

üzerinden ömürler geçmiş siyah beyaz bir resim elimde 

Gencecik bir öğretmen bağırmakta

bahçenin içindeki beyaz yakalara, açılmış kanatlara

elleri belinde, omuzlarında Cumhuriyet; 

''bir, iki, bir, iki...''

Neler anlatır eski bir resim, nemli gözlere

bir gece vakti, loş bir ışık altında; 

resimdeki öğretmen, annen ise...', 'Ne anlatır; neler anlatır,10 mart 1947 de, Konya''da okul bahçesinde çekilmiş siyah beyaz bir resim?  Gencecik bir öğretmen;  elleri belinde,...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergir']::text[], 8.5, '{"poet":"Yalçın Ergir","poet_slug":"yalcin-ergir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/neler-anlatir-bir-resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümek', 'buyumek-yalcin-ergir-qhyi5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gün bile görmeden yapamayacağın sevdiklerini; 

bir ömür boyu görmesen de olması mıdır; 

büyümek?', 'bir gün bile görmeden yapamayacağın sevdiklerini;  bir ömür boyu görmesen de olması mıdır;  büyümek?...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergir']::text[], 8.5, '{"poet":"Yalçın Ergir","poet_slug":"yalcin-ergir","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/buyumek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zülüf Dökülünce Yüze', 'zuluf-dokulunce-yuze-yalcin-ergir-61ks6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık Kolej’den mezundum.

Okul kapısında makasla saçımı kesecek kimse de kalmamıştı. Saçlarımı omuzuma değil; belime kadar uzatabilirdim. Zaten duvarımdaki posterlerin içine atlamamak için kendimi zor tutuyordum.

Hacettepe Üniversitesi yıllarım başladı. Artık odanın, adanın dışındaydım. Yaşıtlarım sanki koca adamlardı. Çoğu dar gelirli ailelerin, binbir güçlükle Türkiye’nin dört bir şehrinden, kasabasından, köyünden oralara gelebilmiş çocuklarıydı. Çıkartılmış bir kavganın çekiçleri; çivileriydiler.

 Bir de beraberlerinde getirdikleri kültürleri vardı. Yaz gelince yazlığına değil; “köyüne giden” arkadaşlarım olmaya başlamıştı. Herkesle, ama herkesle ön yargısız arkadaştım. Şehrin her semtinde, her öğrenci yurdunda, her kahvesinde sevdiklerim, sevildiklerim vardı. Orhan Gencebay da büyük adamdı. Saz çalan bir arkadaşı dinlemek; Rod Stewart’ı dinlemek kadar zevk veriyordu. Erzurum’daki gençlik kampına giden Halil’in anlattıkları; bir damla suyu paylaşmaları da çok güzeldi; bira kamyonuyla Marmaris’e gitmek de.

 Ve zaman, içimdeki orman yangınını; bütün kültürleri tanıyabilme arzumu hiç söndüremedi. Özellikle üzerinde yaşadığım canım ülkenin mozaiğini; 

bunu yerinde, yaşayanından “öğrenebilme aşkı”mı.

Bir de “aşkını öğrenebilme”yi

güneş altında kavrulmuşun

ensesi çorak toprak gibi çatlamışın

yol vermez dağın ardındakinin

mavi donlu, gök gözlünün

boynu bükük, benzi soluğun aşkını

Öğrenebilmeyi; 

bozkırın tezenesinin; kendi sazından, kendi sözünden

al yanaklı, zülfü yüze dökük yarinden ayrı düşmüşün

sadık yari kara toprak olanın aşkını

** ** **

Aşklar vardı

Aşklar var

Aşklar hep olacak

Zülüfler yüze dökülüyordu

Zülüfler yüze dökülüyor

Zülüfler hep yüze dökülecek

Zaman bitene dek...

** ** **

Bir yer sofrasında, bir bayram namazında, bir damat traşında, bir kına gecesinde, bir köy kahvesinde, bir çeşmede, ekinde, bir römorkun tepesinde, bir harman yerinde görüşebilmek; 

kucaklaşabilmek dileğimle..', 'Artık Kolej’den mezundum. Okul kapısında makasla saçımı kesecek kimse de kalmamıştı. Saçlarımı omuzuma değil; belime kadar uzatabilirdim. Za...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergir']::text[], 8.5, '{"poet":"Yalçın Ergir","poet_slug":"yalcin-ergir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/zuluf-dokulunce-yuze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaman` da', 'karaman-da-yunus-emre-em458', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karaman da varlık dolu, Nurlanmıştır güzel yolu, 

Aşıklar Yunus’un oğlu, Karaman da, Larende de... 

*** 

Karaman da sağlık düzen, Görsün Aşıkların gezen, 

İlim yollarında özen, Karaman da Larende de... 

*** 

Karaman da çok Erenler, Mevlanayla hay dönerler, 

Kültür sanatı severler, Karaman da Larende de... 

*** 

Karaman’ın çok güzeli, Sazları okur gazeli, 

Sadıklar gelmiş ezeli, Karaman da Larende de 

*** 

Karaman da Yunus Hocam, Mehmet Beyim Lisan Amcam, 

Mevlevi der gülüm goncam, Karaman da Larende de... 

*** 

Aşık Mevlevi hep ağlar, Yunus un yolunda çağlar, 

Ne güzeldir bahçe bağlar, Karaman da Larende de. 

*** 

Aşık Mevlevi 

Kaydeden: Erdal Canbulat - [email protected]', 'Karaman da varlık dolu, Nurlanmıştır güzel yolu,  Aşıklar Yunus’un oğlu, Karaman da, Larende de...  ***  Karaman da sağlık düzen, Görsün Aşı...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karaman-da-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-melih-cevdet-anday-sjlcr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocukluğunu düşünüyorum Emilia

Deniz boyundaki ıssız yolu sabahleyin

Hani saçların, atkın uçuşurdu rüzgarda

Kokusunu duyuyorum bembeyaz gömleğinin

Seni kucağıma alıyorum Emilia

Ben büyüttüm seni, ben yetiştirdim

Bugüne bu sevdaya

Toprağım ekmeğim kitabım şiirim

Sen ne varsa iyiden doğrudan yana

Gözümün nuru, başımın tacı, efendim', 'Çocukluğunu düşünüyorum Emilia Deniz boyundaki ıssız yolu sabahleyin Hani saçların, atkın uçuşurdu rüzgarda Kokusunu duyuyorum bembeyaz göml...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih-cevdet-anday","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-dusunuyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım Ben ve Mersin', 'askim-ben-ve-mersin-mustafa-ozbek-9cyfi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tuz kokusunu bilir misin? 

Hiç oturdunmu rüzgarında sahilin? 

Aklında varmı anısı adada ki tesisin? 

Aşkım ben ve Mersin.

Senin kadar taze ve temiz baharı

Yavaş yürü ki üzerine sinsin.

Öyle bir kentki değmeli kavgaları

Aşkım ben ve Mersin.

Tuz ve yakamozdu değiştiren kaderimizi, 

Kıskanılacak kadar da sevilebilirsin, 

Onda buımuştuk aslında kendimizi, 

Aşkım ben ve Mersin.

(Mersin,1998)', 'Tuz kokusunu bilir misin?  Hiç oturdunmu rüzgarında sahilin?  Aklında varmı anısı adada ki tesisin?  Aşkım ben ve Mersin. Senin kadar taze v...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özbek']::text[], 8.5, '{"poet":"Mustafa Özbek","poet_slug":"mustafa-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askim-ben-ve-mersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İstanbul Hatırası', 'bir-i-stanbul-hatirasi-mahmut-kuru-74hbu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''gül kokan kadınıma''

kan mı gözyaşı mı dökülen ardımızdan acele acele

gitmeden bir kaç kelam bırakmadı mı ozan

anlaşılır yarınlar icad edilmedi daha

beklemek zor gidilen yol uzak bilirim aşkı

bilirim çekilen çileyi güz akşamlarında

kadın bu sever mi önüne ilk çıkan şairi

hem de günah çıkartmak eminönü rıhtımında 

palas pandıras çıkılan aksaray yokuşlarında

her düş teklifsiz sevişmelere gebe

kadın o kadın değişmedi hala istekli şiire

dertleri bir bir katlayıp mendil misali

yuvarlamak beyazıttan kuşbakışı ayasofyaya

ayasofya ki bir kadın asırlardır tapılan

kiliseye cami katıp hadım etmek derdi

vurulan zincirler ona değil kadına itaatsizlik

tapın dilediğince her yer kadın olmuş 

cennet kokulu kadınlar sarmış ibadetleri

nasılsa ilahlar olimpostan kovuldu

mitolojik kavgalar esrarengiz anlaşmalar yapıldı

atinada bayram bugün sirtaki molası barlarda

konstantinapolis istanbula kavuştu 

tarihçiler üzgün fethedilmedi daha laleli

kadın kokuyor çamlıca, kızkulesi hapis denizde

iran sefareti işgal edilmiş sol açıktan

şahlar padişahlar ve krallar kaçıyor ülkemden

hayat bir kadının peşinden sürükleniyor

tapılacak kadınını arıyor istanbul

kadınsa bakir bir şiir arıyor 

bağrı açık surların dibine uzanmış

gökten düşecek bir ozan bekliyor

bilirim aşkı acıdır, kana susamış

kan kusar göz yaşını saklar bebeklerinde

o kadını bir ben tanıdım isyan günlerinden

şah mat deyişini beni her gördüğünde

yıkılmış viraneye dönmüş içtenliğimle

aşkımla yalın duyarsız alay edişini

bilmezdi beklediği şairin kadın koktuğunu

olimpos yok artık terketti sahte ilahlar

boş tapınmalardan vazgeç ozanlar yok

istanbul kadın kokmaz artık satıldı vaftizlerde

gel kollarıma bir şiir yazalım birlikte

kaçalım bu şehirden çölde buluşalım

kadın kokalım bulduğumuz güllerde

düşlerde aşkı yoklayalım kan kokan

acı kokan gerekçesiz kadınlar bulalım

sen benim gül kokan kadınımsın

yüreğim senin dokunaklı nağmelerine açık

tuşlarım son besteni çalman için bekliyor 

hadi dokun bana bak herşey değişecek

yalnızlıklar sonsuza kadar tükenecek.

		30.07.2001-Dilovası', '''gül kokan kadınıma'' kan mı gözyaşı mı dökülen ardımızdan acele acele gitmeden bir kaç kelam bırakmadı mı ozan anlaşılır yarınlar icad edilm...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/bir-istanbul-hatirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-aysin-ulug-2fn2z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gece kimin ellerine düşer bu gece

gece kimin tenine ayışığı damlatır

kime sabahın ışıklarını...

ve gece bir çiğ gibi düşerken düşlere

geceme pencere aç

yanımda bulayım seni

gece biter güne karışır bedenler

bırak güneş dönsün yüzünü sevdaya

sevda bir cam parçası akıllarda...', 'gece kimin ellerine düşer bu gece gece kimin tenine ayışığı damlatır kime sabahın ışıklarını... ve gece bir çiğ gibi düşerken düşlere geceme...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gece-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalperest', 'hayalperest-aysin-ulug-ncdtr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayışığında vahşi bir sevişme

tenin tenime düşen bir gölge

duygularını kime satmış bilinmez; gece

hayallerime yağmur yağıyor

sen düşüyorsun sesime

Belki bir tek öpüş

belki bir tat tanımadığın

yolunu yitirmiş eski aşıklar

koca bir tren gibi

uçsuz bucaksız yolculuklarım

Ayışığına takılıyor gözlerim

yolumu ne kadar bulurum; aydınlatır

tenine düşen son damla gözyaşım

demirleşmiş duygularına saplanır kalır

Yalnızlık kaderidir hayalperestlerin

çünkü her hayal bir yalana adanır.', 'Ayışığında vahşi bir sevişme tenin tenime düşen bir gölge duygularını kime satmış bilinmez; gece hayallerime yağmur yağıyor sen düşüyorsun s...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayalperest-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kahve Fincanı', 'bir-kahve-fincani-aysin-ulug-gfxn2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'farkında mısın 

bulamadım o gezegeni

bulduğumu sandım

yanıldım

üstüne üstlük acı çektim

yaşadığım hayat acılarımın hep üzerini örtüyor

keşke sadece aşkın ardından ağlasaydım

canım yanıyor

bir sürü yangın üstüste

matematik bile yetmez bendekileri hesaplamaya

bilançom kaydı

ruhum bedenim sözlerim dengesizliğe gömüldü

artık korkuyorum

kendim için gerçekten korkuyorum

gelecek ilk defa karanlık

karanlıklar aydınlığın işareti mi bilmiyorum artık

bir kahve fincanı kaldı ellerimde

başka da bir şey yok artık', 'farkında mısın  bulamadım o gezegeni bulduğumu sandım yanıldım üstüne üstlük acı çektim yaşadığım hayat acılarımın hep üzerini örtüyor keşke...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-kahve-fincani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılmışsın Çocuk', 'kirilmissin-cocuk-aysin-ulug-wamhv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kırılmışsın çocuk

ellerine batmış dünyanın kırıkları

tenine düşmüş acıların gölgesi

sevdalanmışsın zamansız

yakalanmış amansız bir hastalığa

yalnız kalmışssın karanlıklarda

kırılmışsın

gel tut elimi

desem diyemem

bir parkta

bankta yalnız başına-ma oturuyorken

öyle aniden aşka tutulmak

gel sev desen-m

derim der misin gelir misin

bilmiyorum

yaydan fırlamış ok yüreğim

temizler mi kırıklarını

kanamış yaralarını hayatın-m

silinir mi izler

ne olursa olsun unutmalı

temizlemi silmeli pençe izlerini

kazınmış derin anıları

temize çekmeli geçmişi

unutmalı ne var ne yok

sil baştan yeniden başlamalı 

yenilenmeli

taze bir aşkın kollarında unutmalı

zaman durmalı

başka çaresi yok

yok inan...', 'kırılmışsın çocuk ellerine batmış dünyanın kırıkları tenine düşmüş acıların gölgesi sevdalanmışsın zamansız yakalanmış amansız bir hastalığa...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kirilmissin-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şirler Bile', 'sirler-bile-yavuz-sultan-selim-ouuuv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merdüm-i dideme bilmem ne füsun etti felek

Giryemi füzun eşkımı hun etti felek

Şirler pençe-i kahrımda olurken lerzan

Beni bir gözleri ahuya zebun etti felek', 'Merdüm-i dideme bilmem ne füsun etti felek Giryemi füzun eşkımı hun etti felek Şirler pençe-i kahrımda olurken lerzan Beni bir gözleri ahuya...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sultan Selim']::text[], 8.5, '{"poet":"Yavuz Sultan Selim","poet_slug":"yavuz-sultan-selim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sirler-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldan-ma', 'aldan-ma-aysin-ulug-o9qzz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gün gibi geçiyor gözlerin

gözlerin Ankara bozkırının elasında

bir bahar günü

gözlerin yaza çalmış bir sarı bu defa

yaşadığım her ana yayılıyor sesin

uzun bir yolun sonunda 

bulduğum sımsıcak bir ev

yüreğin

çocukluğum gençliğim bir bir önümde yine

ilk aşk ilk öpüş ilk heyacan

ilk kaçış sevgiliye

ilk yakalanış sağanaklara

aklıma su birikintilerinde zıplayan

o deli kız geliyor

sanki Ankara ayazında ellerine sığınmış

ellerim

denizi ıssız çöl Ankara'' nın sanırlar

sarı başakların rengidir aldanırlar

gökyüzü kızıla çalar tan vakti 

yüreğimin evinde hep o keman çalar

şimdi burda bir İstanbul güncesinde

hem de bu kadar bonkör bir şehirde

neden bunca Ankara özlemi anlamazlar

yokluk değeri arttırır

çokluk sevgileri aldatır aldanırlar

aldanmamak için bozkırlara sarılara

ıslanmamak için sağanaklarda

titrememek için ellerinde

aldatmalı aldanmalı yine

son defa.', 'gün gibi geçiyor gözlerin gözlerin Ankara bozkırının elasında bir bahar günü gözlerin yaza çalmış bir sarı bu defa yaşadığım her ana yayılıy...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aldan-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Günü', 'sevgi-gunu-cem-veysel-gul-3u1ek', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocuk öptü kızı dudaklarından, 

Ona yüreğindeki sıcaklığı, 

Dudaklarından sevgi olarak yansıttı.

Sarıldı, sarmaladı, sevdi, sevişti.

Birlikte geleceğe uzandılar, 

Bugün sevgi gününde.

Bir martı kanat çırptı denize, 

Uzun süre kanatlarıyla sevdi dalgaları, 

Okşadı ve kondu bir serseri dalgaya, 

Geleceği bölüştü, paylaştılar birlikte.

Bir kelebek havalandı, 

Çiçekten çiçeğe dolaştı, 

Kondu daldan dala, 

Kanat vurdu, koklaştı, öpüştü, 

Özlerinden faydalandı, uçtu sonsuzluğa onlarla.

Bir zenci sarıldı beyaz kıza, 

Sarıldı, öpüştü, koklaştılar, 

Sıcaklıklarını, sevgilerini belirttiler, 

Bugün sevgi gününde.

Dostluk, kardeşlik, kucaklaşma gününde, 

Yaşamı payşlaşma.varolma günü yani, 

Bugün ortak geleceği kurma günü.

Bugün sevgi günü.

29.07.2001, istanbul

saat: 18,20', 'Çocuk öptü kızı dudaklarından,  Ona yüreğindeki sıcaklığı,  Dudaklarından sevgi olarak yansıttı. Sarıldı, sarmaladı, sevdi, sevişti. Birlikt...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgi-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlak Denge', 'mutlak-denge-i-sa-seker-3fdgo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alisveristeyken terazi kollarinda

Terazi burcudakilerin sahsinda, 

Istisnalar kaideyi bozmadiginda.

Düz yolda pek hatirlanmasa da

Her an akilda uçurum kenarinda.

Katbettigimiz anlar vardir onu: 

Keçiyi yardan uçuran sanki ot mu? 

Dengenin yoklugudur bulduran sonu.

Duygular da dengesizlesir bazen: 

Kalp akla agir basarken, 

Istemek ihtirasa dönüsürken

Ve birileri bizim için ''vazgeçilmez''ken

Ama mutlak denge anlik degildir.

Istikrar ancak dengenin dengidir.

Kalbinin tiktaklarinin kesilmesi, 

Dengeyi sagladiginin resmidir.', 'Alisveristeyken terazi kollarinda Terazi burcudakilerin sahsinda,  Istisnalar kaideyi bozmadiginda. Düz yolda pek hatirlanmasa da Her an aki...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutlak-denge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Uzakta', 'senden-uzakta-nurgun-salli-fl6gz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz uzak bir uzak bir şehirde

Özleminle beraberim

Gecelerim ise bir  başka

Bodrumda

Sensiz nefes almak gibi

Hasret denizinde yüzmek gibi

Anlamı yok Sanki

Gökyüzündeki yıldızların

İçimde bir burukluk 

Göremediğim sana dair

Ve aradaki kilometrelere

Bir damla gözyaşı gibi

Senden uzakta olmak

Duymadıgım sesinle yankınır

Bangır bangır müzik sesleri

Sevgin bir ruh sanki

Hep içimde benimle yatar

Sadece seni ister

Eğlencenin tadı özleme

Özlem ise bir denize dönüştü

Burada senden uzakta

Herşey farklı inan

Çekilmeyecek kadar özgürlük

Katlanamayacak kadar özlem 

Senden uzakta', 'Sensiz uzak bir uzak bir şehirde Özleminle beraberim Gecelerim ise bir  başka Bodrumda Sensiz nefes almak gibi Hasret denizinde yüzmek gibi ...', ARRAY['Türk Edebiyatı','Şiir','Nurgün Şallı']::text[], 8.5, '{"poet":"Nurgün Şallı","poet_slug":"nurgun-salli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/senden-uzakta-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiire Devam', 'siire-devam-i-sa-seker-rgwx2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Değerli şiir amca: 

Bir itirafım var sana.

Şu meslek-i aşkta 

Sizi biraz kullandımda.

Kafiye, redif kardeşlerim: 

Sizleri de suçuma alet ettim.

Can yoldaşım hece veznim: 

Yüzüne bakacak halde değilim.

Affet beni şairlerin üstadı! 

Şiirleri kullanmam bir hataydı, 

Daha şimdi adın aklımdaydı, 

Fuzuli düşünme okudun o adı.

Ne yapayım ama mecburdum, 

Bu dilbere aniden vuruldum.

Vurma sırası bana gelince

Haliyle size başvurdum.

Bu şiirin hazırlanmasında, 

Emeği geçen ilham peribacalarıma, 

Teşekkür ederim ama veda asla

İhtiyaç zaruridir her an bu yarla.', 'Değerli şiir amca:  Bir itirafım var sana. Şu meslek-i aşkta  Sizi biraz kullandımda. Kafiye, redif kardeşlerim:  Sizleri de suçuma alet ett...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siire-devam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRBENİN ÇOBANLARIA', 'turbeni-n-cobanlaria-ziya-sahin-asik-ziya-39tod', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben türbenin çobanlarını sevdim, 

Ayağında gardaşlar lastiği, 

Gözleri ışıl, ışıl, çakmak, çakmak.

Omuzunda heybesi, 

Içinde kömbesi, 

Sırtında hiç çıkarmadığı

Rengi solmuş göynek, 

En çok havas ettiği

Tarhana çorbası içmek.

Çocuktan çoban olur mu, 

Demeyin...

Daha yedi yaşında

Korkmaz mı? 

Kayalardan düşmez mi? 

Başına bir hal gelmez mi? 

Demeyin...

O da güttüğü körpe kuzular gibi büyür, 

Ardıç kuşu gibi uçar, 

Çoban aldatan kuşu gibi saklanır, 

Koyaklara iner.

Kayalardan yağmur suyu içer, 

Kevenlerin üstün de kelebek pişirir, 

Bahar da çiğdemler toplar.

Süt kesiği kokar, 

Kuzular gibi büyük.

Kuzular gibi tor toraşık, 

Üstü ıslak çer çerpeşik.

Amma velakin adam olur, 

Yiğit olur, mert olur.

Emmi der, dayı der.

El öpmeyi, 

Hatır sormayı, 

Gönül almayı, 

Kaval çalmayı, 

Büyüdükçe dağların dilini öğrenir.

Ben türbenin çobanlarını sevdim, 

Eli öpülesi çobanları.

Onlar, körpınarın başın da

Çökelek dürümü yer.

Geceleri keçcenin arasında 

Daş ağıl da yatarlar.

Gökteki yıldızları sayarlar.

Ün lüküs otomobili, 

Boz eşşeğin sıpasıdır.

Ben türbenin çobanlarını sevdim.

O çobanlar bana, 

Çocukluğumu hatırlatır, 

Anamı hatırlatır, 

Gurbetteki dayılarımı hatırlatır.

Dedim ya, ben Türbenin çobanlarını sevdim.

Çorabının biri tevir, biri bir tevir...

Elmacık kemikleri yanmış, 

Sevgiye, saygıya hürmete kanmış, 

Dağlar kadar yüce, 

Yaylalar kadar temiz, 

Siz Türbenin çobanları, 

Sizi hasretle öperiz.', 'Ben türbenin çobanlarını sevdim,  Ayağında gardaşlar lastiği,  Gözleri ışıl, ışıl, çakmak, çakmak. Omuzunda heybesi,  Içinde kömbesi,  Sırtı...', ARRAY['Türk Edebiyatı','Şiir','Ziya Şahin Aşık Ziya']::text[], 8.5, '{"poet":"Ziya Şahin Aşık Ziya","poet_slug":"ziya-sahin-asik-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/turbenin-cobanlaria-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emmiler 1', 'emmiler-1-ziya-sahin-asik-ziya-ebvl7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vakit akşam oldu, gece başlıyor, 

İçime bir firkat çöker emmiler.

Gurbet beni döne, döne daşlıyor, 

Yüreğime hasret eker emmiler.

Gözümde tüterdi dereler, bağlar, 

Bahar gelse çiçek döşese dağlar, 

Kaya pınarının suları çağlar, 

Başına kuşları çeker emmiler.

Kaç yıl oldu, ayrı düştüm sıladan, 

Anadan, bacıdan, gardaştan, dosttan, 

Salına salına insem Toros’dan, 

Beni gören köylüm ne der emmiler.

Akşam dip odaya bağdaş kurulur, 

Ocağa bir kazan yemek vurulur, 

Bir misafir gelse köye duyulur, 

Duymuyor geleni nefer emmiler.', 'Vakit akşam oldu, gece başlıyor,  İçime bir firkat çöker emmiler. Gurbet beni döne, döne daşlıyor,  Yüreğime hasret eker emmiler. Gözümde tü...', ARRAY['Türk Edebiyatı','Şiir','Ziya Şahin Aşık Ziya']::text[], 8.5, '{"poet":"Ziya Şahin Aşık Ziya","poet_slug":"ziya-sahin-asik-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emmiler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emmiler-2', 'emmiler-2-ziya-sahin-asik-ziya-weeb9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öksüz çam önünde akan körpınar, 

Sularında inci, mercanlar yanar.

Keklikler suyunu içmeye konar, 

Kekliğim nazlıca öttü emmiler.

Daş ağılar, sürün gelip yazmaz mı, 

Armutlu kaya da kuzgun  uçmaz mı, 

Keltepe üstünden güneş batmaz mı.

Gönlüme bir hüzün çöktü emmiler.

Duz  daşına  gelir’mola kuzular, 

Yarelerim göz göz oldu sızılar

Bodur kalmış yörepteki mazılar, 

Yeşil yaprağını  döktü emmiler.

Ezine de Köşker dağı ezine, 

O dağlarda Sultan gelin süzüne, 

Anam duyar ise vurur dizine, 

Ayrılık belimi büktü emmiler.', 'Öksüz çam önünde akan körpınar,  Sularında inci, mercanlar yanar. Keklikler suyunu içmeye konar,  Kekliğim nazlıca öttü emmiler. Daş ağılar,...', ARRAY['Türk Edebiyatı','Şiir','Ziya Şahin Aşık Ziya']::text[], 8.5, '{"poet":"Ziya Şahin Aşık Ziya","poet_slug":"ziya-sahin-asik-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emmiler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emmiler-3', 'emmiler-3-ziya-sahin-asik-ziya-ulp1u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Babam tırpanını almış çekiçler, 

Anam kirkit vurur kilim nakışlar, 

Bir gün olur ağam beni bağışlar, 

Ataya kim küslük güder emmiler.

Kalkıp sapa gitmek için gecelen, 

Ay ışığı vurur damdan, peceden.

Azığımız gelir sonra niceden, 

Taplah gözlerimde tüter emmiler.

Elma döleğin de ekin biçerdik, 

Yolaşandan gelip sapı çekerdik, 

Hatloluktan derman sura inerdik, 

Dizimdeki derman biter emmiler.

Kuzayca da burçak yoldum ağladım, 

Belkavak da ata torba bağladım.

Garip tepesinde yürek dağladım, 

Gasavetim bana yeter emmiler.', 'Babam tırpanını almış çekiçler,  Anam kirkit vurur kilim nakışlar,  Bir gün olur ağam beni bağışlar,  Ataya kim küslük güder emmiler. Kalkıp...', ARRAY['Türk Edebiyatı','Şiir','Ziya Şahin Aşık Ziya']::text[], 8.5, '{"poet":"Ziya Şahin Aşık Ziya","poet_slug":"ziya-sahin-asik-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emmiler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EMMİLER-4', 'emmi-ler-4-ziya-sahin-asik-ziya-hy8po', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüyamda da gördüm karışık halde, 

Beni bu ellerden alın emmiler.

Samanlık duvarı yıkılmış yerde, 

Kuşlarınan haber salın emmiler.

Baba dede yurdum virane olmuş, 

Tarlamız calbayla, ayrıkla dolmuş.

Bakın konaklarım hele nic’olmuş, 

Baykuşlara mesken malım emmiler.

Daşoluk da ayram içtim oturdum, 

Yüreğimi karlı dağa götürdüm.

Gardaşımı yadellerde yitirdim, 

Acaba nic’olur halım emmiler.

Kazım emmim der mi kağnıyı kurun, 

Irgadı toplayıp tarlaya vurun.

Türbeliler Derviş dayımı sorun, 

Kalmadı tutacak dalım emmiler.

Horlavuktan çıktım ben ağır ağır, 

Görünce eyledim bir sürü kahır, 

Radi emmi evini etmişler ahır, 

Kalkmadı kanadım kolum emmiler.', 'Rüyamda da gördüm karışık halde,  Beni bu ellerden alın emmiler. Samanlık duvarı yıkılmış yerde,  Kuşlarınan haber salın emmiler. Baba dede ...', ARRAY['Türk Edebiyatı','Şiir','Ziya Şahin Aşık Ziya']::text[], 8.5, '{"poet":"Ziya Şahin Aşık Ziya","poet_slug":"ziya-sahin-asik-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/emmiler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emimler-5', 'emimler-5-ziya-sahin-asik-ziya-igr0b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül yüzlüm ellere gelin oldu mu, 

Sararıp da acep benzi soldu mu? 

Dizlerine vurup saçın yoldu mu, 

Ona hakkım helal olsun emmiler.

Eline bayramlık kınası yaksın, 

Beline oyalı yağlığı taksın, 

Evine yurduna çok iyi baksın, 

Geçimin de huzur bulsun emmiler.

Şahancaydım amma yetmiyor gücüm, 

Gözlerim görmüyor ağardı saçım, 

Gardaşlarım uzak gelemez bacım, 

Geleninen haber salsın emmiler.

Yaman olur gurbet elin hasreti, 

Anam benden kınalı kız isterdi.

Mürüvvet görmedi yokmuş kısmeti, 

Evlatları ona yansın emmiler.', 'Gül yüzlüm ellere gelin oldu mu,  Sararıp da acep benzi soldu mu?  Dizlerine vurup saçın yoldu mu,  Ona hakkım helal olsun emmiler. Eline ba...', ARRAY['Türk Edebiyatı','Şiir','Ziya Şahin Aşık Ziya']::text[], 8.5, '{"poet":"Ziya Şahin Aşık Ziya","poet_slug":"ziya-sahin-asik-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emimler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emmiler-6', 'emmiler-6-ziya-sahin-asik-ziya-tuibg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Avşar düğününde çeksem mendili, 

Kendimi yerlere vursam emmiler.

Davranıp belime silah sıkarak, 

Seğmenin önünde dursam emmiler.

O düğüne varsam şabe çaldırsam, 

Kirmen gibi dönüp halay kaldırsam.

Azığıma kömbe alıp sardırsam, 

Yaylalara çadır kursam emmiler.

Yüreğime şimdi bir sızı düştü, 

Gözlerim doldu da çağladı çoştu, 

Pusucuk arkası her zaman kıştı, 

Koyaklarda çiğdem dersem emmiler.

Aşık ziyam daha neyi söyleyim, 

Melikgazi ben her zaman böyleyim.

Yavrumu alıcı kuşa vermeyin, 

Teberiğimi de bir görsem emmiler.', 'Avşar düğününde çeksem mendili,  Kendimi yerlere vursam emmiler. Davranıp belime silah sıkarak,  Seğmenin önünde dursam emmiler. O düğüne va...', ARRAY['Türk Edebiyatı','Şiir','Ziya Şahin Aşık Ziya']::text[], 8.5, '{"poet":"Ziya Şahin Aşık Ziya","poet_slug":"ziya-sahin-asik-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emmiler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim Olmasan', 'sevgilim-olmasan-i-sa-seker-08og5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baban olsam döverim seni dizimi dövmeden, 

Annen olsam eksik etmem süpürgeyi elinden, 

Ablan olsam kıskanırım seni güzelliğinden, 

Ağabeyin olsam kurtulamaz başım dertten, 

Sevgilim olmasan yazmazdım bu şiiri ben.', 'Baban olsam döverim seni dizimi dövmeden,  Annen olsam eksik etmem süpürgeyi elinden,  Ablan olsam kıskanırım seni güzelliğinden,  Ağabeyin ...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgilim-olmasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Anneler Aynıdır', 'butun-anneler-aynidir-i-sa-seker-0dlpg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben yatarken pencereyi kapatır, üşütürüm diye, 

Betona otursam zorla verir altıma bir iskemle, 

Tıka basa yemek yesem doymam onun gözünde

Çocuğum olunca anlarmışım, söylediğine göre.

Sizin anneniz de aynı değil mi sanki söylesenize.', 'Ben yatarken pencereyi kapatır, üşütürüm diye,  Betona otursam zorla verir altıma bir iskemle,  Tıka basa yemek yesem doymam onun gözünde Ço...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/butun-anneler-aynidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kağanlığa Doğru', 'kaganliga-dogru-huseyin-nihal-atsiz-33zqi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çekildi mi kılıçlar 

Türk''ün gönlü hoşlanır

Kağanlığı kurmaya 

Yeni baştan başlanır

Gözler ayda güneşte

İlteriş Kağan başta 

Yazlar geçer savaşta 

Ötüken''de kışlanır

İçelim kımızları 

Yosma Gök Türk kızları 

Esritirken bizleri

Yavuzlar yavaşlanır', 'Çekildi mi kılıçlar  Türk''ün gönlü hoşlanır Kağanlığı kurmaya  Yeni baştan başlanır Gözler ayda güneşte İlteriş Kağan başta  Yazlar geçer sa...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaganliga-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Zeybek 1', 'sari-zeybek-1-huseyin-nihal-atsiz-kz318', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu dağların meşeleri karanlık

Etekleri olur çayır, çimenlik

''Sarı Zeybek şu dağlara yaslanır

Yağmur yağar, pusatları ıslanır''

Sarı Zeybek şu dağların eridir 

Dağlar onun bütün varı yoğudur

Kendi sarı, bindiği at dorudur

Attan inip şu dağlara yaslanır

Gözü dalar, bakışları ıslanır

Sarı Zeybek dağdan dağa taşınır

Taşınır da yüce dağlar aşınır

Mola verip Gökçen kızı düşünür 

Efe dağdan köye doğru seslenir

Yosma Gökçen sesi duyar süslenir.', 'Şu dağların meşeleri karanlık Etekleri olur çayır, çimenlik ''Sarı Zeybek şu dağlara yaslanır Yağmur yağar, pusatları ıslanır'' Sarı Zeybek şu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sari-zeybek-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-esra-erdogan-k19v4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir aci dolasiyor icimde

bir yangin var korlastikca yanan

bir bicak sapli yüregimin en derinliklerinde

bir yara var iyilestikce kanayan

bir AYRILIK var beni bitiren tükeden

yalnizligimi avuclayabilsem 

atardim akarsulara

Caresizligime dokunabilsem

Birakirdim onu arkami dönmeden

Ayriligimin sebebini görebilsem

Bu kadar aci cekmezdim

Ve zamani geri cevirebilsem

Sevmezdim seni böyle...', 'Bir aci dolasiyor icimde bir yangin var korlastikca yanan bir bicak sapli yüregimin en derinliklerinde bir yara var iyilestikce kanayan bir ...', ARRAY['Türk Edebiyatı','Şiir','Esra Erdoğan']::text[], 8.5, '{"poet":"Esra Erdoğan","poet_slug":"esra-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayrilik-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Zeybek 1 (devamı)', 'sari-zeybek-1-devami-huseyin-nihal-atsiz-uvj4w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmesin mi Sarı Zeybek  Gökçen''i? 

Yüzü melek, saçı ipek Gökçen''i

Bütün Aydın İlinde tek Gökçen''i

Kız sevmeyen erin gönlü paslanır

Paslanır da imil imil yaslanır

Padişahın kulağına varırsa 

Tutun diye devlet emir verirse

Üç yüz atlı, beş yüz yaya yürürse 

Ölen ölür, anaları yaslanır', 'Sevmesin mi Sarı Zeybek  Gökçen''i?  Yüzü melek, saçı ipek Gökçen''i Bütün Aydın İlinde tek Gökçen''i Kız sevmeyen erin gönlü paslanır Paslanır...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sari-zeybek-1-devami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevda', 'kara-sevda-vedat-akin-zcx4e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir buluttur kara sevdan döner durur başımda, 

Döker aşk taneciklerini, yüreğime yalnızlıklarda, 

Umut doludur yüreğim, seni her gördüğümde, 

O kara sevdan her zaman yüreğimde….

Bir umut dolar gönlüme, seninle birlikte olduğum zaman, 

Dolar içimdeki kadehe bir aşk şarabı, sen gülümsediğin zaman, 

Arar gözlerim senin izini her zaman, 

Sevinç çığlıkları dolar gönlüme, seni bulduğum zaman…', 'Bir buluttur kara sevdan döner durur başımda,  Döker aşk taneciklerini, yüreğime yalnızlıklarda,  Umut doludur yüreğim, seni her gördüğümde,...', ARRAY['Türk Edebiyatı','Şiir','Vedat Akın']::text[], 8.5, '{"poet":"Vedat Akın","poet_slug":"vedat-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kara-sevda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen & Sen', 'sen-sen-vedat-akin-16sar', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinlediğim şarkılar da hep sen, 

Yazdığım şiirler de hep sen, 

Her gördüğüm insanda yine sen, 

Bütün varlığım da, kalbimde sen, 

HEP SEN OLACAKSIN

Sen bütün benliğimdesin, 

Sen gördüğüm rüyamdasın, 

Sen hissettiğim her duygudasın, 

Sen, sen her şeyimdesin, 

HEP SEN OLACAKSIN

Sen yarınımdasın, 

Sen bugünümdesin, 

Sen dünümdesin, 

Sen yaşadığım her anımdasın, 

HEP SEN OLACAKSIN

Seni unutamam, 

Seni yaşamadan yapamam, 

Seni düşünmeden günüm geçmez, 

Sen olmadığın zaman benim hayatım devam etmez, 

 SEN OLACAKSIN

Sen ruhumun derinliklerinde, 

Sen kalbimin en güzel yerinde, 

Sen bedenimin her parçasında, 

Sen benim her zaman içimdesin, 

HEP SEN OLACAKSIN

Sen benim en mutlu anımsın, 

Sen benim neşe kaynağımsın, 

Sen benim alın yazımsın, 

Sen benim hayatımsın, 

HEP SEN OLACAKSIN', 'Dinlediğim şarkılar da hep sen,  Yazdığım şiirler de hep sen,  Her gördüğüm insanda yine sen,  Bütün varlığım da, kalbimde sen,  HEP SEN OLA...', ARRAY['Türk Edebiyatı','Şiir','Vedat Akın']::text[], 8.5, '{"poet":"Vedat Akın","poet_slug":"vedat-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delicesine', 'delicesine-vedat-akin-ig3lt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş açar gönlüme görünce seni, 

Fırtınalar kopar içimde duyunca sesini, 

Bakınca gözlerine düşer içime bir aşk ateşi, 

Ruhum bedenimden ayrılır hissedince seni, 

İşte o zaman yaşarım delicesine seni…

Dokununca sana yüreğim titrer, 

İncinirsin, kırılırsın diye, 

Kalbim değişik atmaya başlar, 

Sarınca kollarım seni, 

Geçerim kendimden yanımda isen eğer, 

Hayatım son bulur sen yoksan eğer…', 'Güneş açar gönlüme görünce seni,  Fırtınalar kopar içimde duyunca sesini,  Bakınca gözlerine düşer içime bir aşk ateşi,  Ruhum bedenimden ay...', ARRAY['Türk Edebiyatı','Şiir','Vedat Akın']::text[], 8.5, '{"poet":"Vedat Akın","poet_slug":"vedat-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/delicesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girdap', 'girdap-vedat-akin-ru4jp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatı yaşamak zor, 

Korkular tünemiş içimize, 

Her gün arıyoruz  bir ümit diye, 

Belki sevdiğimizi, belki de geçmişimizi…

Umutsuzluk örmüş ağlarını, 

Kadere boyun eğmişiz hep, 

Beklemişiz hep, 

Belki döner mi? diye, 

Yanlış yapıyoruz yanlış, 

Sevgi birdenbire gelir apansızın, 

Belki bir nefretle, belki de yaşadığımızı anlayınca yine, 

Her zaman gülebilmeyi

Ve

Her şeyi sevebilmeyi öğrenmeliyiz belki de…', 'Hayatı yaşamak zor,  Korkular tünemiş içimize,  Her gün arıyoruz  bir ümit diye,  Belki sevdiğimizi, belki de geçmişimizi… Umutsuzluk örmüş ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Akın']::text[], 8.5, '{"poet":"Vedat Akın","poet_slug":"vedat-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/girdap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Zeybek 2', 'sari-zeybek-2-huseyin-nihal-atsiz-mpfhf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Candarmalar genç efeyi sardılar

Kırk ölümden beğendiğin sordular

Kızanları bir bir yere serdiler

Sarı Zeybek kara sürmez şanına 

Erlik için kıyar kendi canına 

Nasıl olsa uçar da can kalır ten 

Bir ah tuttu şu dağları derinden 

Srı Zeybek vuruldu üç yerinden

''Yazık olsun Telli Doru Şanına 

Eğil de bak mor cepkenin kanına''

Sarı Zeybek gün batarken vuruldu 

Nabızları yavaş yavaş duruldu

Gözlerine kara perde gerildi

Yiğit başı düşüp kaldı yanına 

Bakmaz oldu mor cepkenin kanına

Sarı Zeybek öldü sanma Diridir, 

O, dağların yine eşsiz eridir, 

Bütün kızlar artık onun yarıdır

Vurulmuştur hepsi onun ününe 

Can atarlar şimdi gerdek gününe

Sarı Zeybek şimdi artık masaldır, 

Sanma yıllr şerefini azaltır

Yiğitlerin dillerinde meseldir

Er kişiler kıyar da öz canına 

Bir damlacık leke sürmez şanına....

                                                     1940', 'Candarmalar genç efeyi sardılar Kırk ölümden beğendiğin sordular Kızanları bir bir yere serdiler Sarı Zeybek kara sürmez şanına  Erlik için ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sari-zeybek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-vedat-akin-s1f0m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllardan sonra seni tanıdım, 

Yıllardır sanki hep seni aradım, 

Seni gördüm aşkınla yandım, 

Artık bu kalp seni seviyor.

Yalnızlığa boyun eğmişim bir garip gibi, 

Hiç kimsem yok çevrem de bir yar gibi, 

Seni arıyorum bir MECNUN gibi, 

Neredesin  LEYLA

Seni seviyor bu FERHAT, 

Sensiz olamıyor bu gönlüm rahat, 

Kan ağlıyor yüreğim heyhat, 

Neredesin  ŞİRİN

Seni arıyorum KEREM gibi, gözlerim boşluğa dalmış, 

Seni istiyorum kafam karmakarışık, 

Sensiz olamıyorum, beynim de hep hayalin, 

Neredesin ASLI

İster LEYLA ol, ister ŞİRİN, 

İstersen de ASLI ol gerekirse, 

İster çölde, ister dağlar da, 

Bana bir ateş, bir ışık yak, 

Gönlüm bulacaktır bir gün seni elbet, 

Seni seviyorum güzelim…', 'Yıllardan sonra seni tanıdım,  Yıllardır sanki hep seni aradım,  Seni gördüm aşkınla yandım,  Artık bu kalp seni seviyor. Yalnızlığa boyun e...', ARRAY['Türk Edebiyatı','Şiir','Vedat Akın']::text[], 8.5, '{"poet":"Vedat Akın","poet_slug":"vedat-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-seviyorum-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-vedat-akin-brf0r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızım sensiz bu dünya da

Ne arayanım var ne bir soranım, 

Sırtlanmışım yalnızlığı tüm ağırlığı ile, 

Taşıyorum yıllarca ayaklarım titreyerek…

Bir başına bomboş bir dünya da, 

Konuşanım yok ki paylaşayım derdimi, 

Seviyorum delicesine seni, 

Seveceğim ölünceye kadar seni…

Gittiğinden beri hayatım anlamsız, 

Kelimeler kifayetini kaybetti cümleler manasız, 

Beynim durdu düşüncelerimde hep sen, 

Sensiz yapayalnız kaldım  ben…

Aşığım ben sana gözlerim dolu, 

Seviyorum seni ağlayarak, 

Anlatamıyorum sana aşkımı, 

Çünkü sen seviyorsun.......!', 'Yalnızım sensiz bu dünya da Ne arayanım var ne bir soranım,  Sırtlanmışım yalnızlığı tüm ağırlığı ile,  Taşıyorum yıllarca ayaklarım titreye...', ARRAY['Türk Edebiyatı','Şiir','Vedat Akın']::text[], 8.5, '{"poet":"Vedat Akın","poet_slug":"vedat-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizlik-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-vedat-akin-petog', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir umuttu benimkisi, 

Bir ışık, bir şua gibi, 

Çok gördüler güzelim, 

Bir umudu bile çok gördüler…

Bir değil iki değil kaç oldu sayısını hatırlayamadığım, 

Hep benim umutlarım mı? Yok olacak, 

Ben mi hep umutsuzluk ve mutsuzluğu yaşayacağım, 

Hep mutsuz kalacağım….

Evet çok gördüler bir umudu bile çok gördüler, 

Bir sevinci ve mutluluğu çok gördüler, 

Bir sevinç çığlığını ve haykırışını çok gördüler, 

Çok görenlerin gözü kör olsun…

Yaşamak zorlaşır bir umudun yoksa hayata bağlayan, 

Hep umutların çalınıyorsa çok zor gelir insana yaşamak, 

Hayatın dengesi mi bu, yoksa dengesizliğimi, 

Bilmiyorum ama çok mutsuzum bu hayatta….

Umudunu yitirme dediler, 

Ama bir umudu bana çok gördüler, 

Takma kafana gelir geçer dediler, 

Bir umut bile kalmamış bu hayatta, 

Gelip geçecek, bir umudum bile….', 'Bir umuttu benimkisi,  Bir ışık, bir şua gibi,  Çok gördüler güzelim,  Bir umudu bile çok gördüler… Bir değil iki değil kaç oldu sayısını ha...', ARRAY['Türk Edebiyatı','Şiir','Vedat Akın']::text[], 8.5, '{"poet":"Vedat Akın","poet_slug":"vedat-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/umut-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş, Kıyı Ve Duyabildiklerim', 'gunes-kiyi-ve-duyabildiklerim-i-lhan-ucku-xkcow', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çık biraz dışarıya çocuk

Böyle

Evlerde

Oturmakla olmaz

Çık da gör hayat

Çok değişti

Bildiğin gibi değil

Çık da

Gör

Çiçeklerin

Gene ilkbaharda açması

Yapraklarınsa

Yazsonları sararması

Aldatmasın seni', 'Çık biraz dışarıya çocuk Böyle Evlerde Oturmakla olmaz Çık da gör hayat Çok değişti Bildiğin gibi değil Çık da Gör Çiçeklerin Gene ilkbahard...', ARRAY['Türk Edebiyatı','Şiir','İlhan Uçku']::text[], 8.5, '{"poet":"İlhan Uçku","poet_slug":"i-lhan-ucku","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gunes-kiyi-ve-duyabildiklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resminle Sabah Kadar Ağladım', 'resminle-sabah-kadar-agladim-kadir-eksioglu-qxpd8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakışın konuştu hasretten yana 

Bahçeme vakitsiz geldin sonbahar

Dudağın elveda diyorken bana 

Resminle ağladım sabaha kadar

Elimle topladım gönül yaşımı

Benimle ağ çekip yandı dört duvar

Bıraktım yastığa seven başımı

Resminle ağladım sabaha kadar 

Ben böyle kolayca sarhoş olmazdım

Halimi ben gibi sevenler anlar

Geceleri senin ismini yazdım 

Resminle ağladım sabaha kadar', 'Bakışın konuştu hasretten yana  Bahçeme vakitsiz geldin sonbahar Dudağın elveda diyorken bana  Resminle ağladım sabaha kadar Elimle topladım...', ARRAY['Türk Edebiyatı','Şiir','Kadir Ekşioğlu']::text[], 8.5, '{"poet":"Kadir Ekşioğlu","poet_slug":"kadir-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/resminle-sabah-kadar-agladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-semanur-dilek-2buet', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorgunum! 

Omuzlarımda hasretin ağır yükü

Kollarım, ayaklarım sızlıyor

Arayıp bulamıyorum

Dünkü heyecanımı, umudumu.

Kalbim bile yorgun yorgun çarpıyor.

Vurgunum! 

Hayalimde o eşsiz sevgilinin güzel yüzü.

Gönlüm hala onu deliler gibi seviyor.

Hasrete dayanamıyorum.

Gözlerim her yerde onu arıyor.

İçimde büyük bir boşluk dolduramıyorum.

Bekliyorum! 

Hala bana vaadedilen  vuslatın gerçekleşmesini.

Özlediğim sevgilimin geri gelmesini.

İçim kıpır, kıpır bazen

Genç kız heyecanları yaşıyorum.

Çok uzun süreden beri bekliyorum

Yaşlanıyorum! 

Saçlarımda beyazlar, yüzümde çizgiler.

Düşüyor yavaş, yavaş

İhtiyarlık yaklaşıyor.

Bu ne çelişki Allah’ım anlamıyorum

Bedenim yaşlanıyor ama gönlümde hala taptaze arzular...

Anlamıyorum! 

Nereye kadar sürecek bu bitmeyen bekleyiş.

İstediğim bir umut, bir ışık.

Yoruldum artık eski gücüm yok

Ne sevmek ne beklemek için sabrım yok.

Korkuyorum! 

Yakında vuslat gelecek bile olsa

Benim vuslat için bile gücüm tükenecek.

ALLAH’IM  özlediğim sevgili ne zaman gelecek...', 'Yorgunum!  Omuzlarımda hasretin ağır yükü Kollarım, ayaklarım sızlıyor Arayıp bulamıyorum Dünkü heyecanımı, umudumu. Kalbim bile yorgun yorg...', ARRAY['Türk Edebiyatı','Şiir','Semanur Dilek']::text[], 8.5, '{"poet":"Semanur Dilek","poet_slug":"semanur-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yorgunum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnternetteki Aşk', 'i-nternetteki-ask-kadir-eksioglu-171mu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zorlada olsa ondan 

Bir randevu kapmıştım 

Bir büfede onu bekleyecektim 

Büfeye gittim oturdum 

Onu beklemeye başladım 

Daha onu tanımıyordum bile 

Sadece telofonda konuşmuştuk 

Ben bir gül elimde tutacaktım 

O beni bulacaktı öyle demişti 

Baktım masaya birisi yaklaşıyor 

O gelmeden anlamıştım onun olduğunu 

Ve geldi Kadirmi dedi evet dedim 

Ve masaya oturdu 

Biraz entel gözüküyordu 

Giyinişinden anlamıştım 

İçinden gülüyordu gözlerinden okumuştum 

İki hoş beş konuştuk 

Ve ben onun sadece onun mavi gözlerine 

Bakıyordum oda bana 

Konuşmuyorduk bile sadece bakışıyorduk 

Ben bakışlar yeter diyordum 

Ve ayrıldık bir saat felan kaldık 

Erken çıktık o sinemaya girdi 

Bende eve geliyordum 

Bizim ayrılmamızdan olsa gerek 

Sağnak şeklinde yağmur yağıyordu 

Ve o günden sonra beni hiç aramadı 

Keşke gelmeseydide 

Ben onu rüyalarımda yaşatsaydım 

Benim dünyama girmesiyle çıkması 

Bir oldu evet aynen öyle oldu 

Ama hergün telofoneder diye bekliyorum 

Ama bir gün bile etmedi 

Telofonu açıpta Ayrıldık bile demdi 

Evet bu aşkı internette bulmuştum 

İnternette de arıyordum ama 

Bulamıyordum körebe gibi 

Eğer bu şiirimi okursan 

Bana bir telofon aç be canım 

Sen kendini gayet iyi bilirsin 

Hani ben sana sen sözünü tutarsın 

Diyordum hatırladınmı bu garibi 

Sen arasanda aramasanda 

İnternetteki aşkım olarak kalacaksın 

Ebediyyenbe canım sen unutsanda', 'Zorlada olsa ondan  Bir randevu kapmıştım  Bir büfede onu bekleyecektim  Büfeye gittim oturdum  Onu beklemeye başladım  Daha onu tanımıyordu...', ARRAY['Türk Edebiyatı','Şiir','Kadir Ekşioğlu']::text[], 8.5, '{"poet":"Kadir Ekşioğlu","poet_slug":"kadir-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/internetteki-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değer miydi? ?', 'deger-miydi-sair-desdimona-ia96w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni yaşıyorsun şuan belkide bilmeden

Kaç kez sordum bu soruyu kimbilir kendime? 

Yüzlerce, binlerce kez

Her seferinde sinir oldum yeniden yeniden

Ağladım geceler boyu hıçkıra hıçkıra olmasa da gizlice

Herkesten uzak köşelerde...

Heyyy! Hiç güçsüz olmayı sevmedim ben

Birtek sanaydı güçsüzlüğüm

Senin de birtek bana

Tek gözyaşlarımı sen gördün, acizliğimi, terkedilişimi

Ve yalan değillerdiysede seninkileri de sadece ben...

Peki ya şimdi? 

Kim bu oyunun kazananı? 

Sen mi? 

Yoksa ben mi? 

Susma artık konuş işte! 

Ne çalıyor biliyormusun? 

Bizim şarkımız...

Nekadar komik degilmi? 

Ne bana seni hatırlatıyor şimdi, 

Nede sana beni...

Bu kadar mı kolaydı? 

Hiç bitmeyecek dediğim sevdam bu kadar mı kolay harcanacaktı? 

Şimde sen? 

Zavallı sen ne yapıyorsun? 

Gönül zindanlarımda bile yer açamıyorum sana

Sen! Hey Sen! KÜÇÜK İNSAN! 

Esirliği tutsaklığı bile haketmiyorsun! 

Üç gün üzüldüm senin için

Koskoca upuzun üç gün...

DEGERMİYDİ?', 'Beni yaşıyorsun şuan belkide bilmeden Kaç kez sordum bu soruyu kimbilir kendime?  Yüzlerce, binlerce kez Her seferinde sinir oldum yeniden y...', ARRAY['Türk Edebiyatı','Şiir','Şair Desdimona']::text[], 8.5, '{"poet":"Şair Desdimona","poet_slug":"sair-desdimona","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/deger-miydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sakin-aglama', 'sakin-aglama-mehmet-demirhan-vcfab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer ağlamak istersen sevda, özlem, hasret ve umut        yaşlarını akıt yüreğime 

     Umutsuzluk, mutsuzluk gözyaşları değil.

    Ağlama arkamdan, gittiğim vakit 

    Çünkü senide, yüreğini de götürüyorum yanımda

    Sana söz, bende iyi bakacağım ona 

    Her türlü ihanetten uzak tutacağım kalbini

    Hep senin hayalinle besleyeceğim onu

    Ta ki tekrar kavuşana dek

    Ağlama arkamdan, gittiğim vakit 

    Geleceğim bir gün 

    Döneceğim bir gün 

    Ümidini yitirme sakın

    Ağla arkamdan, eğer geri dönmezsem (ve de yüreğini geri vermezsem

     Bir daha beniSeni göremezsen 

     Ağla o zaman mezarımın başında 

     Bitmeyen, unutulmayan aşkımıza, sevgimize

     Şunu bil ki, yüreğin hep yanımda ocak    benden, bedenimden hiç ama hiç ayrılmayacak 

     Ve sen de bir beden iki yürek olacaksın o zaman

     Tıpkı benim gibi...)', 'Eğer ağlamak istersen sevda, özlem, hasret ve umut        yaşlarını akıt yüreğime       Umutsuzluk, mutsuzluk gözyaşları değil.     Ağlama a...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demirhan']::text[], 8.5, '{"poet":"Mehmet Demirhan","poet_slug":"mehmet-demirhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sakin-aglama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvarlar', 'duvarlar-engin-arapoglu-ha4wf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kıpkırmızı bir gökyüzü; 

üzerinde zifiri bulutlar gezinmekte.

Öldüresiye boğunç bir kıyamet havası esmekte, 

Sonra gece salına salına inmekte, 

Gece değilde sanki; 

Başıma giyotin inmekte! 

Bütün ölüler yeniden dirilip kahkahalarla gülmekte, 

Benim yüreğimi kediler pençelemekte, 

Düşünceler muallakta: ''Acaba neden? '' demekte, 

Şimdi beyinlerimizi fareler kemirmekte! 

Bütün sıkıntılarım taşlaşıp üzerime devrilmekte, 

Acılarım ''ah''laşıp da üstüne titremekte, 

Herşey dönüp-dolaşıp aynı yerde birleşmekte, 

Şimdi kafalarımızı duvarlar beklemekte!', 'Kıpkırmızı bir gökyüzü;  üzerinde zifiri bulutlar gezinmekte. Öldüresiye boğunç bir kıyamet havası esmekte,  Sonra gece salına salına inmekt...', ARRAY['Türk Edebiyatı','Şiir','Engin Arapoğlu']::text[], 8.5, '{"poet":"Engin Arapoğlu","poet_slug":"engin-arapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/duvarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Yoksun', 'ama-yoksun-engin-arapoglu-9pvzt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha sabah olmadı; geceden kork! 

Çünkü geceleri varolurum ben.

Karanlık fobisi benim, 

Nedensiz duyulan korku da ben..

Yanımdasın...

Yoksun ama

Aklımdasın

Olmamalısın zaten, 

Birşeylerin hasretini çekmeliyim

Birşeylerin üzüntüsünü duymalıyım, 

Onun için nöbetindeyim ben yokluğunun

Bana dert gerek anlıyor musun? 

Bana derdin gerek..

Daha incinmedi yürek, 

Sabır uslanmadı daha, 

Çekerim derdini

Çekerim derdimi

Yoksun

Ama olsun

Yine de sesleniyorum sana

''Ne var'' desene........', 'Daha sabah olmadı; geceden kork!  Çünkü geceleri varolurum ben. Karanlık fobisi benim,  Nedensiz duyulan korku da ben.. Yanımdasın... Yoksun...', ARRAY['Türk Edebiyatı','Şiir','Engin Arapoğlu']::text[], 8.5, '{"poet":"Engin Arapoğlu","poet_slug":"engin-arapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ama-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Çocukken', 'kucuk-bir-cocukken-ahmet-kuruoglu-3jrds', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buğulanmış penceremden

Ağlayan çocuklarını emziren

Bulut anneyi izlerdim ben

Şefkati daha küçük bir çocukken 

İşte böyle öğrendim ben

Buğulanmış penceremden

Sararmış yapraklarını döken

Çınar ağacını izlerdim ben

Çaresizliği daha küçük bir çocukken

İşte böyle öğrendim ben

Buğulanmış penceremden

Yıllardır güneşe kavuşmak isteyen

Ay dedeyi izlerdim ben

Aşkı daha küçük bir çocukken

İşte böyle öğrendim ben

Buğulanmış penceremden

Cadde boyu gezen

Kaldırım çiçeklerini izlerdim ben

Günah işlemeyi daha küçük bir çoçukken

İşte böyle öğrendim ben

Buğulanmış penceremden

Kuduran dalgalar arasında seyreden

Gemileri izlerdim ben

Ölümün nefesini daha küçük bir çocukken

İşte böyle öğrendim ben

Buğulanmış penceremden

Ağlarken yada gülerken

Elimi bırakmayan yanlızlığımla tanıştım ben

Dostluğu daha küçük bir çocukken 

İşte böyle öğrendim ben

Buğulanmış penceremden

Su gibi akıp giden

Zamanı izlerdim ben

Hayatı daha küçük bir çocukken

İşte böyle öğrendim ben

Buğulanmış penceremden

Kocaman yanlışları minik bir ana sığdırabilen

Acizleri izlerdim ben

Kendimi daha küçük bir çocukken

İşte böyle tanıdım ben', 'Buğulanmış penceremden Ağlayan çocuklarını emziren Bulut anneyi izlerdim ben Şefkati daha küçük bir çocukken  İşte böyle öğrendim ben Buğula...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kuruoğlu']::text[], 8.5, '{"poet":"Ahmet Kuruoğlu","poet_slug":"ahmet-kuruoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kucuk-bir-cocukken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayvanlar', 'hayvanlar-engin-arapoglu-ciq1n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aya bakma, gitmesin

Güneşe bakma, batmasın

Seslerini kısma.bağırsın kurtlar

Onlar bizi anlarlar

Yeraltı çekmesin suyu, 

Bulutlar inmesin yeryüzüne

Sebep olma, perde düşmesin geceye

Bırak bebekler ağlasınlar

Onlar bizi anlarlar

Üfleme, gitmesin rüzgarlar

Bırak çeksin bizi hortumlar

Yaramı atelleme, aksın kanım

İzin ver, sallansın salıncaklar

Onlar bizi uçuracaklar

Ellerini tutma çocukların, bırak gitsinler

Kuyruklarından asma kedileri, ölmesinler

Yaşadığına yansın kuşlar, dönsünler ormanlarına

Onlar bize doğru çığrışacaklar

Kabuklarını kırma kaplumbağaların

intiharını engelleme yunusların

Kafanı sokup çıkar okyanus diplerine

Gör nasıl yüzdüklerini balıkların

Onlar bizi anlarlar

Ellerini kaldır

Dizlerini yere ver

Umutsuzluk diye birşey yok

Duamız kabul olacaktır

Konuşup durma

Anlarlar diye çabalama boşuna

Onlar bizi anlamıyorlar

Yabani ormanlara sal gitsin onları

Onlar birer hayvanlar', 'Aya bakma, gitmesin Güneşe bakma, batmasın Seslerini kısma.bağırsın kurtlar Onlar bizi anlarlar Yeraltı çekmesin suyu,  Bulutlar inmesin yer...', ARRAY['Türk Edebiyatı','Şiir','Engin Arapoğlu']::text[], 8.5, '{"poet":"Engin Arapoğlu","poet_slug":"engin-arapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hayvanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzdün', 'uzdun-engin-arapoglu-i82i5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarim

Çok mu açtık arayı dersin, 

Yoksa başarıya doyduk mu, 

Bıktık mı? 

Çok muhabbet tez ayrılık getirir diye mi sustuk, 

Körüklesin diye mi yarim, 

Sürüklesin diye mi? 

Benim içindi herşey biliyorum 

Benim içindi ağlayışın, gülüşün

Hedefi vurdun yarim

Beni üzdün

Üzdün....!', 'Yarim Çok mu açtık arayı dersin,  Yoksa başarıya doyduk mu,  Bıktık mı?  Çok muhabbet tez ayrılık getirir diye mi sustuk,  Körüklesin diye m...', ARRAY['Türk Edebiyatı','Şiir','Engin Arapoğlu']::text[], 8.5, '{"poet":"Engin Arapoğlu","poet_slug":"engin-arapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzdun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-veysel-tanriverdi-ttbqx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine, 

Yeni bir doğuş.

Sancılı bir dünya

Hadi

Hemen ağla

Merhaba de acılara

Bil

Seni biz yazdık

Biz çizdik

Açma ellerine boşuna

Ne duruyorsun

Yırt

sök

Bir gün olsun cayma

İçinde umut olana...', 'Yine,  Yeni bir doğuş. Sancılı bir dünya Hadi Hemen ağla Merhaba de acılara Bil Seni biz yazdık Biz çizdik Açma ellerine boşuna Ne duruyorsu...', ARRAY['Türk Edebiyatı','Şiir','Veysel Tanrıverdi']::text[], 8.5, '{"poet":"Veysel Tanrıverdi","poet_slug":"veysel-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/merhaba-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı Meyhanesi', 'balikci-meyhanesi-mustafa-yildiz-demirci-fe1f3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece gene bir balıkçı meyhanesindeyim.

Tek sana içiyor bir sana ağlıyorum.

Ömrümün bu sensiz akşamında, 

Ben sadece gençliğime yanıyorum.

Ne hayattan  memnunum, ne gönlümden

Ne sabahtan umutluyum, ne kendimden, 

Plağın gıcırtılı inleyişinden, 

Ben sadece dertleri bulurum.

İçiyorum bu gecede, 

Ayrılığın ateşini sigaramla yeniden tazeliyorum.

Açılan her kapının ardından, 

Ben yalnızca seni bekliyorum.

Geceler geceler hep gözyaşlarımı gizliyor.

Meyhanenin ışığı yalnızca hayaline yetiyor.

Bu benim sancılı yüreğime, 

Bir kurşun bile yetmiyor.

Bu gece yine seni görmek istiyorum.

Sevdiğin her çiçiğe ismini veriyorum.

Sarhoş meyhanecinin kırık masalarında, 

Özlemini hep kadehlere boşaltıyorum.

Daldıkça dalıyor, aşkından ölüyorum.

Bu hasret testisinden ayrılığın kanını içiyorum.

Ak saçlı ihtiyarın bakışlarında senden kalan eseri; 

Kendimi görüyorum.

Geceler geceler gidin artık dönmeyin, 

Bana sevgilimi getirin.

Meyhanenin bu ıssız köşesinde, 

Ben hep ama hep onu beklerim.....

                                  Mustafa Yıldız Demirci', 'Bu gece gene bir balıkçı meyhanesindeyim. Tek sana içiyor bir sana ağlıyorum. Ömrümün bu sensiz akşamında,  Ben sadece gençliğime yanıyorum....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız Demirci']::text[], 8.5, '{"poet":"Mustafa Yıldız Demirci","poet_slug":"mustafa-yildiz-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/balikci-meyhanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanırsın Ki..', 'sanirsin-ki-serhan-karaduman-5zlh2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sanırsınki eski günler geri döner, 

önceden karşılaştığın yüzler seni hala sever, 

kalbin ürperi werir, 

yarım kalmış arzular, 

bitirilmemiş yazılar gibi, 

tekrar başlama hevesiyle dolar, 

bir hevestir boşa nefes alışlar, 

hep yaşadın sanırsın, 

ne zamanki ölüm seni amansız karşılar', 'sanırsınki eski günler geri döner,  önceden karşılaştığın yüzler seni hala sever,  kalbin ürperi werir,  yarım kalmış arzular,  bitirilmemiş...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sanirsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin', 'gelmedin-ertugrul-bektas-nbg58', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece sabaha kadar

Şehrin ışıklarını seyrettim

Bekledim bir yıldız parlaklığında çıkıp gelmeni, 

Gelmedin.

Dün gece hiçmi hiç uyumadım, 

Sensizliğimle dertleştim.

Sırdaşımdı dün gece şehrin ışıkları, 

Söylerler sana diye; 

Derdimi onlara anlattım, 

Ama gelmedin.

Pırıl pırıl yanan şehrin ışıkları

Derdimi onlarda paylaşamadılar.

Birer birer sakladılar kendilerini, 

Bir daha yanmamacasına.

Sende bırakıp gittin beni, 

Bir daha dönmemecesine.

Dün gece hiç bitmeyecek sandım.

Elim silahımda gözüm şehrin ışıklarında

Bir an işte o an 

Senin hayaline daldım.

Gelirken gördüm seni

En güzel geceliğin üzerinde.

Başka da birşey görmedim.

Bir an işte o an 

Elim silahımda gözüm şehrin ışıklarında

Bir ses duydum sonra...

Başka da bir şey duymadım.

Gözümde şehrin ışıkları, gönlümde sen 

Ve elveda

Gidiyorum ben.

(Önce kurşun girer, sonra sesi duyulur.)', 'Dün gece sabaha kadar Şehrin ışıklarını seyrettim Bekledim bir yıldız parlaklığında çıkıp gelmeni,  Gelmedin. Dün gece hiçmi hiç uyumadım,  ...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Bektaş']::text[], 8.5, '{"poet":"Ertuğrul Bektaş","poet_slug":"ertugrul-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gelmedin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne', 'ne-hakan-yigit-1sjef', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne bir şarkı sözüyüm ne de bir beste

Güller içinde ay gibiyim

Ne denizlere yüz veririm ne sevgiye

Ben gözü gönlü tok bir saray gibiyim...', 'Ne bir şarkı sözüyüm ne de bir beste Güller içinde ay gibiyim Ne denizlere yüz veririm ne sevgiye Ben gözü gönlü tok bir saray gibiyim......', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-memduh-atac-gzv9j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sordum nasıl gidilir? 

Doğru yoldan git dedi, 

Dedim kapı kapalı

Bir elinle it dedi.

Dedim o güneş midir? 

Dokunma yakar dedi

Kirpikleri ok mudur, 

Dikkat et batar dedi.

Dedim yol uzun mudur? 

Uzun ama boş dedi

Acaba varır mıyım? 

Gecikirsen ''Koş'' dedi.', 'Sordum nasıl gidilir?  Doğru yoldan git dedi,  Dedim kapı kapalı Bir elinle it dedi. Dedim o güneş midir?  Dokunma yakar dedi Kirpikleri ok ...', ARRAY['Türk Edebiyatı','Şiir','Memduh Ataç']::text[], 8.5, '{"poet":"Memduh Ataç","poet_slug":"memduh-atac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yol-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandım Kuşların İnce Sesine', 'uyandim-kuslarin-i-nce-sesine-asik-veysel-satiroglu-ypsnd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uyandım kuşların ince sesine

Seherle birlikte iniler durur

Ses verdim sesine bilircesine

Aşıkın derdini yeniler durur.

Baharda çağlayan bulanık sular

Durmadan kendini taşlara çalar

Eşinden ayrılmış bir geyik meler

Dağlar sadâ verir iniler durur

VEYSEL de yaralı geyik gibidir

Kapalı dertlere höyük gibidir

Ne sarhoştur ne de ayık gibidir

Sinesi kös gümüler durur.', 'Uyandım kuşların ince sesine Seherle birlikte iniler durur Ses verdim sesine bilircesine Aşıkın derdini yeniler durur. Baharda çağlayan bula...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uyandim-kuslarin-ince-sesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sözlerin Kaldı', 'bana-sozlerin-kaldi-lusan-bicakci-z43o9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '- Bir annenin sabaha karşı 

  oğlu için söyledikleri

Bana sözlerin kaldı yavrum

Sen değil.

Oysa bir gölgede sakınırdım yüzünü

Saçının her teli benim eserimdi

Boğazından geçirdiğim her lokma

Gider bir yerini iyi ederdi.

Yattığın yerleri ben düzlerdim

Saçlarını okşar gibi.

Bir günden diğerine

Seni özlerken

Yokluğunda yıllar geçti.

Senin yüzün

Benim ellerimin devamıydı

Bütün çizgilerini bilirdim

(Seni bilmediğim insanlar nasıl sevdiler?)

Kopardılar ellerimden

Böldüler denizimi

O günlerden bir kuraklık ellerimde

Bana sözlerin kaldı yavrum

Niçin sen değil?', '- Bir annenin sabaha karşı    oğlu için söyledikleri Bana sözlerin kaldı yavrum Sen değil. Oysa bir gölgede sakınırdım yüzünü Saçının her te...', ARRAY['Türk Edebiyatı','Şiir','Lüsan Bıçakçı']::text[], 8.5, '{"poet":"Lüsan Bıçakçı","poet_slug":"lusan-bicakci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bana-sozlerin-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezelden Ebede', 'ezelden-ebede-sefer-ali-mustu-txjln', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ezelden ebede bahtım yar oldu

Gözüm didar gördü bahtiyar oldu

Yaşamak kâm almak dostum dünyadan

Ömrümde dört mevsim hep bahar oldu

Dağlar çiçek açtı gonca gül açtı

Gölgeler kayboldu gün güneş açtı

Boynuma dolanan o sırma saçtı

Dalga dalga oldu şivekâr oldu

Gençlikte çekilir nazı dilberin

Sevgisi hırçındır bazı dilberin

Boş yere çalıyor sazı ellerim

Zaman geçti güzel cefakâr oldu.

Şair Ali beka Tanrı''ya hastır

İnsanı yaşatan dünyada aşktır

Bütün güzellere gönlümüz köşktür

Şu uslanmaz gönlüm sitemkâr oldu', 'Ezelden ebede bahtım yar oldu Gözüm didar gördü bahtiyar oldu Yaşamak kâm almak dostum dünyadan Ömrümde dört mevsim hep bahar oldu Dağlar çi...', ARRAY['Türk Edebiyatı','Şiir','Sefer Ali Muştu']::text[], 8.5, '{"poet":"Sefer Ali Muştu","poet_slug":"sefer-ali-mustu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ezelden-ebede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Geçilmez', 'canakkale-gecilmez-ali-muzaffer-alyanak-2h3fo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çanakkale de can veren yüz binlerin hatırasına...

Yunus geçer

                    Balık Geçer

                                       Balıkçı geçer

Düşman geçemez

ÇANAKKALE GEÇİLMEZ..', 'Çanakkale de can veren yüz binlerin hatırasına... Yunus geçer                     Balık Geçer                                        Balıkçı...', ARRAY['Türk Edebiyatı','Şiir','Ali Muzaffer Alyanak']::text[], 8.5, '{"poet":"Ali Muzaffer Alyanak","poet_slug":"ali-muzaffer-alyanak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/canakkale-gecilmez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyıda', 'kiyida-yetkin-aroz-y03rj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bunca Kalabalık, bunca gürültü

Vapur düdükleri, tren sesleri

Martıların bitip tükenmez çığlıkları

Ne sevgileri ısıtır ne umutları

Durmadan durmadan büyütür

Bir çığlık gibi

Yalnızlıkları', 'Bunca Kalabalık, bunca gürültü Vapur düdükleri, tren sesleri Martıların bitip tükenmez çığlıkları Ne sevgileri ısıtır ne umutları Durmadan d...', ARRAY['Türk Edebiyatı','Şiir','Yetkin Aröz']::text[], 8.5, '{"poet":"Yetkin Aröz","poet_slug":"yetkin-aroz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kiyida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Dalgaya Tutunmuş', 'yunus-dalgaya-tutunmus-ali-muzaffer-alyanak-2iofc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yunus dalgaya tutunmuş

Midye kayaya.

Acımasız insanoğlu

Vurur Hayvanlara.

Çölde Yılan sürünür, 

Bir eş arar kendisine.

Niye doğurdu seni anan? 

Niye doğurdu seni

Niye doğurdu seni

Niye doğurdu seni anan? 

Ali bir gün sende ölür, 

Toprak olursun.

Toprağına yağmur yağar

Çamur olursun.

Çamurdan bir Adem olur, 

Çamurdan bir İnsan olur.

Diye doğurdu seni anan.

Diye doğurdu seni, 

Diye doğurdu seni, 

Diye doğurdu seni anan.', 'Yunus dalgaya tutunmuş Midye kayaya. Acımasız insanoğlu Vurur Hayvanlara. Çölde Yılan sürünür,  Bir eş arar kendisine. Niye doğurdu seni ana...', ARRAY['Türk Edebiyatı','Şiir','Ali Muzaffer Alyanak']::text[], 8.5, '{"poet":"Ali Muzaffer Alyanak","poet_slug":"ali-muzaffer-alyanak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yunus-dalgaya-tutunmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bİziz Okul', 'bi-ziz-okul-ahmet-mortas-gtd1l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türkü söyler konuşuruz durmadan 

Yıllar yılı mikrfonun PEŞİNDE 

Övünürüz, dövünürüz kırmadan 

Hizmet vardır hepimizin DÜŞÜNDE... 

*** 

Çok severiz güzel duru dilini 

Hep özleriz serin esen yelini 

Köyde-kentte kızı kızan gelini 

Çalışırırz dağlarının BAŞINDA... 

*** 

Türkiye''yi köşe bucak gezeriz 

Halk kültürü deryasında yüzeriz 

Doğruları söyler, güzel yazarız 

TRT.miz otuziki YAŞINDA... 

*** 

Ekrandayız yurdumun her ilinde 

Sesleniriz ovasında belinde 

Kokumuz var çiöeğinde gülünde 

Üzüntümüz, korunmayan KUŞUNDA... 

*** 

Görevimiz bir sevdadır biliriz 

Hizmet aşkıyla severek ölürüz 

Ayrılsakta bir gider bin geliriz 

Tuzumuz var ekmeğinde AŞINDA... 

*** 

Yetmiş dokuz ilimizde yaşarız 

Kameralar elimizde koşarız 

Türkü-mani dilimizde coşarız 

Yurdumuzun toprağında TAŞINDA... 

*** 

Cennet gibi şu yurdumuz ülkemiz 

Ülkemizde bütünlüktür ilkemiz 

Hizmet bekler bizden her bir bölgemiz 

Anadolum baharında KIŞINDA... 

*** 

Biz OKULUZ, yoktur karda gözümüz 

Özümüze hizmet ekmek sözümüz 

Eğitirsek, güler bizim yüzümüz 

Hırsımız yok, Özellerin BEŞİNDE... 

*** 

Morsultan''ım hiç durmadan çalıştık 

Çok diyarlar, çok köyleri dolaştık 

Sitemlere sürgünlere alıştık 

Yinede mutluyuz, herkes İŞİNDE... 

***TRT-PRODUKTÖR 

17-6-1996 Ankara', 'Türkü söyler konuşuruz durmadan  Yıllar yılı mikrfonun PEŞİNDE  Övünürüz, dövünürüz kırmadan  Hizmet vardır hepimizin DÜŞÜNDE...  ***  Çok s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mortaş']::text[], 8.5, '{"poet":"Ahmet Mortaş","poet_slug":"ahmet-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/biziz-okul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.Çocuğum', 'a-cocugum-ahmet-mortas-uzid4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gez yurdunu karış karış demişti, 

Bilim-teknik için yarış demişti, 

Savaş değil hedef barış demişti, 

At hüzünü, O''nu anla çocuğum... 

**** 

Gez yurdunu karış karış demişti, 

Bilim-teknik için yarış demişti, 

Savaş değil hedef barış demişti, 

At hüzünü, O''nu anla çocuğum... 

**** 

Köylümüzü çok yakından izledi, 

Halkcılık''tan yana tutum izledi, 

Hep gençleri çocukları özledi, 

Duy hazını, O''nu anla çocuğum... 

**** 

Geleceği gök yüzünde aradı, 

Gökten indi denileni taradı, 

Eserleri ulusuna yaradı, 

Yaz yazını, O''nu anla çocuğum... 

**** 

Saltanatı temelinden vurmuştu, 

Laikliği tek çıkar yol görmüştü, 

Devrim''ini sabır ile örmüştü, 

Öp yüzünü, O''nu anla çocuğum... 

**** 

Ulusculuk hedefini gösterdi, 

Ekonomik bağımsızlık isterdi, 

Devrimcilik özümüze has derdi, 

Sür izini, O''nu anla çocuğum... 

***** 

Ülkeyi kurtardı kanla, çocuğum, 

Vatanı, Ata''nı anla çocuğum, 

Morsultan''ım beni dinle çocuğum, 

Sev özünü, O''nu anla çocuğum... 

**** 

TRT-Produktör 

1-12-1997 Ankara', 'Gez yurdunu karış karış demişti,  Bilim-teknik için yarış demişti,  Savaş değil hedef barış demişti,  At hüzünü, O''nu anla çocuğum...  **** ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mortaş']::text[], 8.5, '{"poet":"Ahmet Mortaş","poet_slug":"ahmet-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/a-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şatıroğlu beyleri...', 'satiroglu-beyleri-ahmet-mortas-95hm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sivas ile malatya''nın arası 

Dağların dağları, Yamadağları, 

Yüreklerde bir öykünün yarası 

Buna sebeb Şatıroğlu beyleri... 

***** 

Drijan''lar yaylalarda atlıydı 

Alaçayır, Sıçanyurdu otluydu 

Çobanları, sürüleri mutluydu 

Şimdi nerde peynirleri, yağları... 

***** 

Kesilip yenirdi taze etleri 

Boşa havlamazdı itleri 

Dağlarda gezerdi yılkı atları 

Ardından koşardı küçük tayları... 

***** 

Sürüleri yaylaları nerede? 

Pınarlar kurumuş birçok yörede 

Sökülmüş kurumuş her bir derede 

Etekleri üzüm dolu bağları... 

***** 

Fırat''a Hekme''ye gemler vuruldu 

Barajlar üstüne köprü kuruldu 

Bulanıktı sular şimdi duruldu 

Eskiden coşkundu deli çayları... 

***** 

Unutulmaz yaşanılan öyküler 

Ne atları kaldı ne de terkiler 

Söylenmeyi Arguvan''da türküler 

Şehitlere ağlar şimdi dağları... 

***** 

Morsultan''ım acıyı bal eğlersin 

Sevinleri acıları yeğlersin 

Anı yoksa sen dünyayı neylersin? 

Hayal olmuş geçen mutlu çağları... 

TRT.PRODUKTÖRÜ 

1996 Ankara', 'Sivas ile malatya''nın arası  Dağların dağları, Yamadağları,  Yüreklerde bir öykünün yarası  Buna sebeb Şatıroğlu beyleri...  *****  Drijan''l...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mortaş']::text[], 8.5, '{"poet":"Ahmet Mortaş","poet_slug":"ahmet-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/satiroglu-beyleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eosen', 'eosen-bulent-ozcan-bs8ua', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Entelekyam benim kelaynak kuşum

Epigramımı yazan bozguncu tarih

Hiyeroglifimi hizaya soksun

Epikurosçuların şehveti kırbaçlayan o sanal havuzunda

Kösnül yarasaların yüreği dursun

Külün altını örten balinalara inat

Göğün atlasını yorgan yapan yunuslar konuşsun

Endamında boy aynası gezdiren sürahi

Kelebek kanadında kırılsın

Buğulanan buhranını ayır budağından

Ki şiirin yüz iki hörgüçlü görülmemiş buğur senin

Böyle bilinsin

Bereket şiirin aynasını hohlayan hodbinlerden değilsin

Bu kavuran Hitit göğü altında

Hattuşa’nın balkıyan esrikliğisin

Bitir artık bu şiiri dağı yardan uçuran

Söze siyanür katan suyun ömrü vurulsun

Bu son olsun

Olsun

14 Ocak 2001, 

Enfield Island Village, Londra', 'Entelekyam benim kelaynak kuşum Epigramımı yazan bozguncu tarih Hiyeroglifimi hizaya soksun Epikurosçuların şehveti kırbaçlayan o sanal havu...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eosen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Londra Akşamında', 'bir-londra-aksaminda-bulent-ozcan-8c5a5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu hüzündaş Londra akşamında

Bir sensin düşündüğüm

Bir de yoksul, kederli ülkem

Bu hüzündaş Londra akşamında

Bir hıçkırık boğazım düğüm düğüm

Ağlayacağım ama henüz erken

Bu hüzündaş Londra akşamında

Neye baksam bir yalnızlık gördüğüm

Yüreğimi bir şiire gömerken

Bu hüzündaş Londra akşamında, 

Ağlıyorum usul usul kederden...

Temmuz `97, Londra', 'Bu hüzündaş Londra akşamında Bir sensin düşündüğüm Bir de yoksul, kederli ülkem Bu hüzündaş Londra akşamında Bir hıçkırık boğazım düğüm düğü...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-londra-aksaminda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-nilgun-bilgic-610g9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'saçların parlar

güneş kaybolsa da, 

gözlerin ışıl ışıl

yıldızlar olmasa da, 

avuçların yanar 

en soğuk gecelerde, 

çarpar yüreğim her seslenişinde...

gün doğmasa da olur, yaz gelmese de

sussun bütün evren, 

kaybolsun ışıklar

hayat ve sonsuzluk benim, 

YANIMDAYSAN EĞER.....', 'saçların parlar güneş kaybolsa da,  gözlerin ışıl ışıl yıldızlar olmasa da,  avuçların yanar  en soğuk gecelerde,  çarpar yüreğim her seslen...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Bilgiç']::text[], 8.5, '{"poet":"Nilgün Bilgiç","poet_slug":"nilgun-bilgic","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eger-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Desem', 'gel-desem-mustafa-hakan-okur-5c7ol', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğan güneş, çiğ damlası içine

Bir pırıltı gibi, bana gel desem...

Ilık bir meltemsin, esercesine

Bir fısıltı gibi, bana gel desem...

Gökyüzü dopdolu, rahmetle taşkın, 

Sevdiğim, bu mudur kaderi aşkın? 

Kalbe düşen katre, kararma sakın, 

Bir ışıltı gibi, bana gel desem...

Ümidim geceden sonra, doğuşta, 

Sanki tutukluyum ıssız koğuşta, 

Titreyip, kapıya her dokunuşta, 

Bir tıkırtı gibi, bana gel desem...

Güz, kış bekler, aylar geçer aradan

Baharda boy verir ince bir fidan, 

Kalbe doğru, sessiz sessiz damlayan

Bir sızıntı gibi, bana gel desem...

Kalbin bir çiçektir, saf ve nadide 

Öteye açılmış, özü derinde.

Yaşamı sevdiren o gözlerinde

Bir parıltı gibi, bana gel desem...', 'Doğan güneş, çiğ damlası içine Bir pırıltı gibi, bana gel desem... Ilık bir meltemsin, esercesine Bir fısıltı gibi, bana gel desem... Gökyüz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Hakan Okur']::text[], 8.5, '{"poet":"Mustafa Hakan Okur","poet_slug":"mustafa-hakan-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-desem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyeran', 'seyeran-i-dris-sen-art54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'karanlık bir gece 

yalnızım 

sokaklarda tek başıma 

ölümü kolluyorum

sevgiye yer olmayan  bir yere 

kalbime gömdüğüm adını 

haykırmak istediğim acılarımı

yetmeyen hayalleri 

biten dostlukları 

ve içimdeki her şeyi

bırakıyorum 

bir kaldırım kenarı 

küçük bir kovuk  mesken olacak bana

terk edeceğim bu ayyaş hayatı', 'karanlık bir gece  yalnızım  sokaklarda tek başıma  ölümü kolluyorum sevgiye yer olmayan  bir yere  kalbime gömdüğüm adını  haykırmak istedi...', ARRAY['Türk Edebiyatı','Şiir','İdris Şen']::text[], 8.5, '{"poet":"İdris Şen","poet_slug":"i-dris-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seyeran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bis', 'bis-kucuk-i-skender-n80sl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelmeyeceksin..

beklemiyorum da..

telefon etme sakın..

Baskalarını oku..

beni degil..

artık siir yazmıyorum..

Kapıma dayanan postacıları, öldürerek geciriyorum vaktimi', 'Gelmeyeceksin.. beklemiyorum da.. telefon etme sakın.. Baskalarını oku.. beni degil.. artık siir yazmıyorum.. Kapıma dayanan postacıları, öl...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahrem Yürekli', 'mahrem-yurekli-mustafa-i-lhan-bqbr2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öncesinde muazzam bakışların hep kaçış vardı

Yalnızca duygularımız vardı masum kalp atışlarında

Berrak ve ince mahpus edilmiş gözlerimiz ifade etmeye utanıyordu sevdamızı.Hiçbirşey yok gibiydi herşey varken ve en doruklarındayken aslında.

Gözlerimden yaş akmıyordu ama yüreğim gözyaşlarıyla yıkanıyordu her atışında senin için.

Ellerim titremeyi bilmiyordu ilkin ama göğsümde buzları eritecek ateş vardı.uzaktayken ne kadar yakındın bana

Bulut kadar uzaktın ama umuttun bir yağmur bekleyişinde

Yüreğime özlemdin bir cemre düşüşünde.

Bilmiyorum neden o günler geride kaldı...                                   neden bahar gelince soldun sen? .. neden yağıpta üstüme söndürdün ateşimi.biliyorum, biliyorsun bir zamanlar

cevabını söylediğim bu soruların yanıtını.

Demiştim ya sorun benim diye

Hakikaten sebep benim gelişine

ben o kadar yanıp buharlaştımki sen bulut oldun.

O kadar kavruldumki suyunu göğe bağışlamış toprak gibi...

Sen merhamet edip gözyaşlarını bırakınca çatlamış gövdeme

değersiz çamur oldum.ve ben senin için artık hiçbirşey ifade

etmiyorum.çünkü benim sana ihtiyacım yok şimdi.

işin kötüsü; 

yağıp tükendin

ve sende yoksun şimdi...', 'Öncesinde muazzam bakışların hep kaçış vardı Yalnızca duygularımız vardı masum kalp atışlarında Berrak ve ince mahpus edilmiş gözlerimiz ifa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan']::text[], 8.5, '{"poet":"Mustafa İlhan","poet_slug":"mustafa-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mahrem-yurekli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-ahmet-metin-xhisy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah oldu dışardan kuş sesleri geliyor, 

Gözlerimi açtım gönlüm açmak istemiyor.

Sebebini biliyor musun? 

SENSİN.....

İçimde büyük bir sevinç var, 

Kalbimin ta derinlerinden, 

Bir sızı duymaya başladım.

Sebebini biliyor musun? 

SENSİN....

Hani söylemiştim ya sana

‘’Yüksekten çok korkarım’’ diye, 

Ancak oralara çıkıp, gözümün gördüğü

Dağlara, taşlara, ağaçlara, yapraklara bağırmak istiyorum.

Sebebini biliyor musun? 

SENSİN.....

Geceleri uykusuz kalışımın, 

Ancak mutlu oluşumun

Gündüzleri nasıl gezdiğimi bilmeyişimin

Sebebini biliyor musun? 

SENSİN....

Sabah evden çıkınca, 

Acaba bugünde gelir mi? Diye umutla beklediğim

Kimdir biliyor musun? 

SENSİN...

O kadar mutlu ve duyguluyum ki, 

Hayatta hiç tatmamıştım bu lezzeti.

Sebebini kendime soruyorum

Ve CEVABIMI VERİYORUM

      S    E     N     S    İ    N..............

             

                                                                   Ahmet METİN', 'Sabah oldu dışardan kuş sesleri geliyor,  Gözlerimi açtım gönlüm açmak istemiyor. Sebebini biliyor musun?  SENSİN..... İçimde büyük bir sevi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metin']::text[], 8.5, '{"poet":"Ahmet Metin","poet_slug":"ahmet-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sensin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Varsın Bir Yok', 'bir-varsin-bir-yok-sair-asya-ud5tq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir varsın içimde bir yok

sana yaklaştıkça hergün yanında olunca yok...

uzaklaştıkça mesafeler artınca var...

bu ne menem bir çelişki 

tutkular nehirde yönünü şaşırmış dalgalar gibi 

bir akıntıya ters bir düz 

...ışık hüzmeleri gibi 

bir net bir flu 

seninle olabileceğimi anlayınca rahatsız 

olamayacağımı anlayınca sebepsiz rahat 

kollarım sana doğru mutluca kucak açarken 

ayaklarım ters istikamette koşuyor 

anlamıyorum ben seni seviyormuyum?', 'bir varsın içimde bir yok sana yaklaştıkça hergün yanında olunca yok... uzaklaştıkça mesafeler artınca var... bu ne menem bir çelişki  tutku...', ARRAY['Türk Edebiyatı','Şiir','Şair Asya']::text[], 8.5, '{"poet":"Şair Asya","poet_slug":"sair-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-varsin-bir-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güneş Doğdu Biliyormusun', 'bir-gunes-dogdu-biliyormusun-ahmet-metin-up7d8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir güneş doğdu biliyor musun? 

Sıcacık, sımsıcacık bir güneş

Neden gölge etmek zorundasın

Lütfen.Bırak, birazcık ısınayım

Gözleri kapalı bir insanın görmeye başladığı gibi

Annenin evladını hasretle beklediği gibi

Acaba benim de bekleyenim olacak mı

Diye düşündüğüm an.

BİR GÜNEŞ DOĞDU BİLİYORMUSUN', 'Bir güneş doğdu biliyor musun?  Sıcacık, sımsıcacık bir güneş Neden gölge etmek zorundasın Lütfen.Bırak, birazcık ısınayım Gözleri kapalı bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metin']::text[], 8.5, '{"poet":"Ahmet Metin","poet_slug":"ahmet-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-gunes-dogdu-biliyormusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümü Alamıyorum Uzaklardan', 'gozumu-alamiyorum-uzaklardan-ahmet-metin-tmzs1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözümü alamıyorum uzaklardan

Kuşlar uçuyor, ağaçlar sallanıyor

Arabalar geçiyor hiç durmadan

Yerinde duran tek bir şey var

O da benim sana olan sevgim

Haber bekliyorum hiç usanmadan

Bir telefon, bir ses, bir fısıltı

Ayakta geziyorum yerimde hiç durmadan

Yerinde duran tek bir şey var

O da benim sana olan sevgim

İşte hayalin yanımda hiç usanmadan bakıyorum

Ellerin, gözlerin, bakışların ve yüzün

Birden bire üzerime çöktü bir hüzün

Hüzünlenmeyen tek bir şey var

O da benim sana olan sevgim.', 'Gözümü alamıyorum uzaklardan Kuşlar uçuyor, ağaçlar sallanıyor Arabalar geçiyor hiç durmadan Yerinde duran tek bir şey var O da benim sana o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metin']::text[], 8.5, '{"poet":"Ahmet Metin","poet_slug":"ahmet-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozumu-alamiyorum-uzaklardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Görünce Andım', 'seni-gorunce-andim-ahmet-metin-yjxvi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün bayram biliyor musun? Ne bayramı diye sorma

Bugün günlerden Cuma, bir umut bayramı

Yasaklamıştın sen değil mi? Umudu bağlılığı ve sevmeyi

Ne kadar zor sen bilir misin? Umutsuz, bağlanmadan ve sevmeden yaşamak.

Yeni anladım sevmeden yaşanmayacağını

Ben yaşıyor muydum diye soruyorum kendime

Cevap veremiyorum. Çünki; 

Yaşamak kimine göre nefes almak, kimine göre dünyada olmak

İşte ben sadece dünyadaymışım haberim yokmuş

SENİ GÖRÜNCE ANLADIM', 'Bugün bayram biliyor musun? Ne bayramı diye sorma Bugün günlerden Cuma, bir umut bayramı Yasaklamıştın sen değil mi? Umudu bağlılığı ve sevm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metin']::text[], 8.5, '{"poet":"Ahmet Metin","poet_slug":"ahmet-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-gorunce-andim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolik', 'kolik-kadir-koz-l7wdr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben kolik bir insanım

Tütün kolik

Türkü kolik

Yumurta kolik

Hüzün kolik

Keyif kolik

Kavga kolik

Barış kolik

Sevgi kolik

Ve

Alkolik bir insanım

Ve 

Alkolü bıraktım

Hoşçakal alkolik kadir

Hoşgeldin çay kolik kadir', 'Ben kolik bir insanım Tütün kolik Türkü kolik Yumurta kolik Hüzün kolik Keyif kolik Kavga kolik Barış kolik Sevgi kolik Ve Alkolik bir insan...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kolik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Seni Deniz Gözlüm', 'seviyorum-seni-deniz-gozlum-meltem-buhur-5aszr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sakın beni bırakma deniz gözlüm

Bunları sana söyleyemiyorum ama 

İnan seni ilk karşılaştığımız günden beri

Her geçen gün artan bir sevgiyle seviyorum.

Hayallerimde hep sen vardın, 

Rüyalarımda gözlerin, 

Kabusumda ellerini tutan, gözlerine bakan başka bir kız, 

Gözyaşımda seni beklemenin verdiği acı vardı.

Şimdi kavuştum sana.

Ama tamamen benim olmadın daha.

o gün gelene kadar ne olur

Sen başkalarının deniz gözlüsü olma bitanem.

Hep benim kal ve her zaman benimle ol.

Büyük sevgiler için yıllar, yollar, acılar küçüktür, 

Eğer sevgi çok büyükse ÖZLEM de çok büyüktür.

Aşk da büyüktür.

Beni çevrendekilere duyduğun sevgilerin 

En büyüğüyle, 

Aşkların en güzeliyle, 

Özlemlerin en mutlu olanıyla bekle DENİZ GÖZLÜM.

Çünkü; 

Ben seni ilk gördüğüm günden beri böyle bekledim.

şimdi ise herşey daha kolay; 

Beklemek bile... Özlemek bile....

Çünkü UMUDUMUZ ve 

Kocaman bir AŞKIMIZ var.

Artık beraber bekleyeceğiz, 

Hayata dair her duyguyu birlikte yaşayacağız.

                                   (28 Temmuz 2001)', 'Sakın beni bırakma deniz gözlüm Bunları sana söyleyemiyorum ama  İnan seni ilk karşılaştığımız günden beri Her geçen gün artan bir sevgiyle ...', ARRAY['Türk Edebiyatı','Şiir','Meltem Buhur']::text[], 8.5, '{"poet":"Meltem Buhur","poet_slug":"meltem-buhur","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seviyorum-seni-deniz-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle Herşey Daha Güzel', 'senle-hersey-daha-guzel-meltem-buhur-p6iwo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat seninle o kadar güzel ki...

Hayata ait bütün duyguların 

En güzellerini, en büyüklerini sen de yaşadım.

Sevgilerin en gerçeğini sana duydum, 

En acı veren kaygıyı seni sevdiğimi anladığımda hissettim, 

Hüznü dolu dolu sende yaşadım.

Özlemlerin en büyüğü

Kalbimi en çok acıtanı gözlerine, sevgine 

Yani sana duyduğum özlemdi.

En çok sen kızdırdın beni, 

Belki de en çok sen ağlattın

Ama inan(!)  Yine de EN ÇOK 

SENİ SEVİYORUM

DENİZ  GÖZLÜM.....

                                      (28 Temmuz 2001)', 'Hayat seninle o kadar güzel ki... Hayata ait bütün duyguların  En güzellerini, en büyüklerini sen de yaşadım. Sevgilerin en gerçeğini sana d...', ARRAY['Türk Edebiyatı','Şiir','Meltem Buhur']::text[], 8.5, '{"poet":"Meltem Buhur","poet_slug":"meltem-buhur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senle-hersey-daha-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenovaya Cemre Düştü', 'cenovaya-cemre-dustu-kadir-koz-wx6wb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba gece

Merhaba arkadaşım hamam böceği

Merhaba kedi

Merhaba köpek

Bakır fabrikası

Sanada merhaba

Çöptenekesi kusura bakma unuttum

Merhaba dostum

Bu gece biraz dağınığım

Biraz ben değilim

Biraz fazlayım eksik yanımdan

Bağışlayın kardeşlerim

Gecem

Hamam böceğim

Kedim

Köpeğim

Bakır fabrikam

Çöp tenekem

Uzak yoldan geliyorum

Cenovadan geliyorum

Kırılan zincirlerini gördüm

Dünyalı kardeşlerimin

Gördüm

Ve 

Sevindim

Zalim korkabilirmiş mazlumun yumruğundan

Gördüm

Ve 

Üzüldüm

Merminin namertliğine

Kapitalist

Senin bomban

Senin tankın

Senin tüfeğin

Senin paran

Senin orduların

Varsa

Cenovanında

Koreli

Malezyalı

Pakistanlı

Meksikalı

Kübalı

Mazlumları vardır

Kapitalist

Senin cinayetlerin varsa

Cenovanında

Kardeşlik türküleri vardır

Kapitalist

Senin namın dünyayı tutmuşsa

Cenovanında

Ateşi beni tutuşturmuştur

Kusura bakmayın

Biraz ot gibiyim

Biraz samanım bugün

Hepinize selamı var

Dünyalı kardeşlerimin

Bütün mazlumları teker teker

Öpmemi istediler

Teker teker olmasada

Hepinizi öpüyorum

İyi geceler mazlumlar

İyi geceler gece

İyi geceler arkadaşım hamam böceği

İyi geceler kedi

İyi geceler köpek

Bakır fabrikası

Sanada iyi geceler

Çöp tenekesi kusura bakma unuttum

İyi geceler dostum', 'Merhaba gece Merhaba arkadaşım hamam böceği Merhaba kedi Merhaba köpek Bakır fabrikası Sanada merhaba Çöptenekesi kusura bakma unuttum Merha...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/cenovaya-cemre-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Olan Herşeyde Sen Varsın', 'guzel-olan-herseyde-sen-varsin-meltem-buhur-098dy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum.

Arabadayım ve etrafıma bakınıyorum.

Ama öyle bakmak değil bu

Herşeyde seni ararcasına bakıyorum 

Ve güzel olan herşeyde seni bulmam zor olmuyor.

Gökyüzüne bakıyorum.

Bulutlar arasında kalmış maviliklerde 

Bembeyaz tenin arasında kalmış

O harika mavi gözlerini görüyorum.

Bana bakıyorlar gülümser gibi 

Bana ''gitme'' der gibi.

Karşıdaki tepeye bakıyorum.

Yapayalnız kayayı görüyorum.

Ben gittikten sonraki haline benzetiyorum.

Ama üzülme bitanem, 

Belki tek başına kalabilirsin ama 

Yapayalnız kalmayacaksın

Bunu unutma ve bana inan.

Kırmızı bir lalede buluyorum seni.

Nasıl da kızarmış.

Tıpkı seninle ilk karşılaştığımız gün 

Bana gülümseyen, utancından kızarmış

Yüzüne benziyor.

O günü hiç unutmayacağım.

Bir ağaç görüyorum.

Tepenin en büyük, en güzel ağacı

Tıpkı aşkımız gibi.

Alttaki dalda sen, 

Üsttekinde ben

Birer yaprak olmuşuz.

Birleşemiyoruz, bir türlü buluşamıyoruz

Ya anlatamıyoruz derdimizi utancımızdan 

Ya da anlatmaya kelimeler yetmiyor.

Tam sen büyüyorsun, yaklaşıyorsun bana 

Aramıza başka bir dal giriyor.

Tıpkı aramıza giren yollar gibi.

Şimdi bekliyoruz başka baharları

Ilık bir meltem esse de 

Beni senin üzerine düşürse, 

Aşsak aramızdaki dalı 

Ve aretık söylesek birbirimize birbirimizi 

Ne kadar çok sevdiğimizi.

                                          (21 mayıs 2001)', 'Seni düşünüyorum. Arabadayım ve etrafıma bakınıyorum. Ama öyle bakmak değil bu Herşeyde seni ararcasına bakıyorum  Ve güzel olan herşeyde se...', ARRAY['Türk Edebiyatı','Şiir','Meltem Buhur']::text[], 8.5, '{"poet":"Meltem Buhur","poet_slug":"meltem-buhur","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/guzel-olan-herseyde-sen-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Hırsızı', 'gul-hirsizi-kadir-koz-hhnz4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece servisim

Hoşgeldin yalnızlığıma

Hoş

Geldin de

Sefaları getiremedin

Başıma temmuz yağdırıyor

Yağmursuz bulutların

Verici istasyonu gibi

Gözlerini çekiyorum

Dalgaların frekanslarıma karışıyor

Bir sen oluyorum

Bir varoş oluyorum

Bir sana sesleniyorum

Bir açlığa sesleniyorum

Bir aşka kızıyorum

Bir çağıma kızıyorum

Kaçırdığın güllerin yokmu

Kalbimin çeyiz sandığından

Adını gül hırsızı koydum

Mahkemelere vereceğim

Sürüm sürüm süründüreceğim

Ya

Geri ver

Ya 

Geli ver

Şak sanma

Kaka yaptırma kakayı

Yalvartmadan

Ver

Atlattırmadan

Ver

Zırtlattırmadan

Ver

Hadi gül hırsızım

Yapacak başka işlerim var

Hadi kilis biberi

Geri ver güllerini

Sokak beni bekliyor

Kavga beni bekliyor

Bil cümle varoşun çocukları

Mazlumoğlu gariban

Baş örtülü keziban

Kocasından dayak yiyen neriman

İşsiz ve avare faruk

Yolsuz kaluk

Sesi kısık müezzin

Tahtası çürük minber

Boynu bükük minare

Köpek mağduru kedi

Sopa mağduru topal köpek

Şarapçı ersin susamış

Gecelerin kabusu beni bekliyor

Hadi kilis biberim

Hadi antep ceylanım

Hadi karayılan bakışlım

Hadi

Hadi geri ver güllerini', 'Gece servisim Hoşgeldin yalnızlığıma Hoş Geldin de Sefaları getiremedin Başıma temmuz yağdırıyor Yağmursuz bulutların Verici istasyonu gibi ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/gul-hirsizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Sitem', 'sevgiliye-sitem-hayrettin-tarhan-rswd6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEVGİLİYE SİTEM

Sen sevgi nedir bilemezsin, 

Hiç bu kadar çok sevmedin ki.

Her gün büyüyen tertemiz aşkınla, 

İsimler takıp dağlardaki ağaçlara, 

Geceler boyu altında beklemedin ki.

Hasreti yumak yumak umut yaparak, 

Hislerini mısra mısra yazarak, 

Kırmızı bir karanfilde huzuru tatmadın ki.

Kalbin alev alev yanarken

Saatleri dakikaları değil; 

Geçmek bilmeyen saniyeleri saymadın ki.

Gelecek diye beklerken bir anda, 

Hayallerini yok ederek çalan telefonda, 

Yıkılışın ne olduğunu hiç anlamadın ki.

Vefasız bir yâr için çekerken azap

Bir çift gözde gördüğün mutluluk 

Olsa da kızgın çölde bir serap 

Seviyorum diyerek şiirler yazmadın ki.

Gel, dedi diye koşarken şuursuzca ona

Ne kadar büyük bir aşk diye yollara, 

Onu aramak için düşmedin ki.

Gecelerin o onulmaz karanlıklarına, 

Aşklara simge olmuş buse ağaçlarına, 

İsmini kanınla yazmadın ki.

Bir elinde nergis, bir elinde karanfil varken.

Yıllardır aradığın gönül bahçesine girerken, 

Sevdiğin kalpten sürgün edilmedin ki.

Uykusuz geçerken gecelerin sabahlara kadar, 

Aksa çağlasa da göz yaşların azgın nehirler kadar, 

Kimse görmesin diye saklamadın ki.

Her türlü derdine bu sevgiyi derman ederken, 

Dünyadaki tek sevgili oydu derken, 

Bir anda umutların karanlığa gömülmedi ki.

Bütün bunlara rağmen kalbin bir sabır taşı, 

Bir avucunda hasret, diğerinde gözyaşı.

Nefret hançeri ile vurulan kalbin feryadını, 

Hiç ama hiç duymadın ki.

Sen sevgilinin ellerindeki sıcaklığı, 

Sen yâr dilindeki tatlılığı, 

Bilemezsin; yaşamadın böyle bir aşkı

Kendi değerinin bile farkında değilsin ki.

Bilsen de bilmesen de anlamasan da bu aşktan, 

Kurusa da çiçeklerim artık kahrından, 

Ölünce bile karanfil fışkıracak mezarımdan, 

Unut desende seni unutmam mümkün değil ki.', 'SEVGİLİYE SİTEM Sen sevgi nedir bilemezsin,  Hiç bu kadar çok sevmedin ki. Her gün büyüyen tertemiz aşkınla,  İsimler takıp dağlardaki ağaçl...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sevgiliye-sitem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkeme', 'mahkeme-hayrettin-tarhan-vopxw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayallerim, düşlerim 

Sonunda düştüler, mahkemeye.

Hakim sormakta savcı idam istemekte 

Niye bu kadar çok sevdin diye

Söyleyemedim, savunamadım, kendimi 

Yer yokmuş, meğer. 

Aşkın kanununda böyle büyük sevgiye

Bir şahit var dediler. 

Şaşırdım; Çağırıp, dinlediler.

Onlar sordu, susmadı anlattı. 

Bütün her şeyi karanfiller

Suçladılar, beni yine sonunda 

Çok sevmekti, suçum.

Verip de kararı hakimler

Beni gözlerine mahkum ettiler.', 'Hayallerim, düşlerim  Sonunda düştüler, mahkemeye. Hakim sormakta savcı idam istemekte  Niye bu kadar çok sevdin diye Söyleyemedim, savunama...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mahkeme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Çıkar Huy Çıkmaz', 'can-cikar-huy-cikmaz-kadir-koz-5lsld', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğrudur huyumu karadenizden aldığım

Karayel gibi

Karardığım günlerimde oldu

Poyraz gibi 

Esip savurduğum gençlik günlerimde

Süt liman olduğum zamanlarıda biliyorum

Bir akasya altında

Bir dostun sıcak bakışlarında

Bir türkünün kalbinde

Doğrudur huyumu karadenizden aldığım

İçimin kara olduğunu biliyorum

Kara lahana çorbasını

Kara üzümü

Kara kara kızları severim

Siyah pantolon altına

Siyah çorap giydiğim

Siyah gömlek ve siyah ayakkabılarımın

Markası karadenizdir

En sevdiğim şarkı

''Sevemedim kara gözlüm'' şarkısı

Nerede yoksulluk

Nerede imkansızlık

Nerede sömürü

Nerede bir boyacı çocuk görsem 

Gözlerim kararır

Doğrudur huyumu karadenizden aldığım

Pireyi deve iken

Palyaçoyu ağlarken severim

Fındığın zuluflusunu

Kuymağın dibi yanmışını severim

Hamsinin çıtlatmasını

Delikanlının

Akıllısını uslusunu severim

Tabancanın 14'' lüsünü

Yastık altında uyuyanını severim

Köpeklerden kurt köpeğini

Kuşlardan atmacayı

Bitkilerden ısırganı severim

Gecenin sabahçısını

Gündüzün akşamcısını severim

Doğrudur huyumu karadenizden aldığım', 'Doğrudur huyumu karadenizden aldığım Karayel gibi Karardığım günlerimde oldu Poyraz gibi  Esip savurduğum gençlik günlerimde Süt liman olduğ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/can-cikar-huy-cikmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkünün Bekçileri', 'turkunun-bekcileri-kadir-koz-se1rr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biskletli çocuklar

''Kara tren gecikir belki hiç gelmez''

Kuşlastikli çocuklar

''Divane aşık gibi dolanırım yollarda''

Misket gözlü çocuklar

''Cümlece tamahım yoktur bu dünyanın varına''

Çayır sesli çocuklar

''Kanadım kırıldı kaldım burada''

Depremzede çocuklar

''Aşk ile yola geldik yatalım erte gece''

Domates yanaklı çocuklar

''Bir taş attım havaya düştü mapushanaya''

Sarı sidikli çocuklar

''Onbeşinde bir kız bana emmi dedi neyleyim''

Dondurma dilli çocuklar

''Yaramı sarmaya yar kendi gelsin''

Tinerci çocuklar

''Güzeller güleç olur''

Güneş saçlı çocuklar

''Efkarli günlerume geldi çatti ramazan''

Çocuklar yunus yunus

Çocuklar veysel veysel

Çocuklar nesimi nesimi

Çocuklar ruhsati ruhsati

Çocuklar köroğlu köroğlu

Büyüyün

Çalın toprağınıza türkünün mayasını

Olur ya

Tutar birgün

Banada bir kase getirirsiniz', 'Biskletli çocuklar ''Kara tren gecikir belki hiç gelmez'' Kuşlastikli çocuklar ''Divane aşık gibi dolanırım yollarda'' Misket gözlü çocuklar ''Cü...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/turkunun-bekcileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seherde Arafilboy Serpintileri', 'seherde-arafilboy-serpintileri-kadir-koz-u566g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabah yırtmış karanlığını

Gümbür gümbür geliyor

Kuş şarkılarıyla

Kedi ağlamalarıyla

Martılar sabah için 

Kargalarla dövüşüyor

Arabalar uyuyor

Siyah bir köpek sokağı ikiye bölmüş

Yarısı kedilerinse

Yarısıda benim diyor

2 nolu osman kuyusu aralığı bana bakıyor

Ben boztepeye bakınıyorum

Bu yaz gelmedi bülbül

Çok bekledik

Belliki gelmeyecek

Olsun temmuzlar bitmedi ya

Öbür seneside var bu işin

Sabaha

Hayvanların dışında hoşgeldin diyen yok

Boztepenin dibindeyim

Gözü kapalı nasıl çıkılır

Maşatlıktan boztepeye

İyi bilirim

Kaybetsem kendimi yamaçlarında

Akut gelse bulamaz

Karıç karıç karıçlarım boztepeyi

Trabzonu boztepesiz düşünmek

Buna en çok sığırcıklar

Sonbaharda bıldırcınlar güler

Bir fıkra olsaydım temelin yanağında

Ne hoş olurdum

Gülebilirdim belki fadimelere

Ama olamıyorum

Fadimelere gülemiyorum

Gülenleride hiçmi hiç kınamıyorum

Bir fıkra olsaydım temelin yanağında

Ne hoş olurdum', 'Sabah yırtmış karanlığını Gümbür gümbür geliyor Kuş şarkılarıyla Kedi ağlamalarıyla Martılar sabah için  Kargalarla dövüşüyor Arabalar uyuyo...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/seherde-arafilboy-serpintileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahallenin Kuşları', 'mahallenin-kuslari-kadir-koz-unlbw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Annem ve ben

Sabahı beraber karşıladık

O namazını balkonda kıldı

Bense kuşlara dalmışım

Delikanlı serçe televizyon anteninde

Yavuklusu elektrik telinde

Antendeki cik diyor

Cik cik diyor teldeki

Antendeki gel diyor

Geldim geldim diyor teldeki

Antendeki sev diyor

Seviyorum seviyorum diyor teldeki

Antendeki işsizim diyor

Olamaz olamaz diyor teldeki

Antendeki evlen benimle diyor

Evlenemem evlenemem diyor teldeki

Antendeki cik diyor

Cik cik diyor teldeki

Annem namazını balkonda kıldı

Bense kuşlara dalmışım', 'Annem ve ben Sabahı beraber karşıladık O namazını balkonda kıldı Bense kuşlara dalmışım Delikanlı serçe televizyon anteninde Yavuklusu elekt...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mahallenin-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-kadir-koz-2q9h9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşlar

Benimi ötüyorsunuz

Kuşlar

Banamı gülüyorsunuz

Kuşlar

Benimi dövüyorsunuz

Kuşlar

Banamı uçuyorsunuz

Kuşlar

Benimi seviyorsunuz

Kuşlar

Banamı sövüyorsunuz

Kuşlar

Benimi zorluyorsunuz

Kuşlar 

Banamı acıyorsunuz

Kuşlar

Benimi çağırıyorsunuz

Kuşlar

Banamı konuyorsunuz

Kuşlar

Benimi istiyorsunuz

Kuşlar

Banamı susuyorsunuz

Kuşlar

Benimi mezeliyorsunuz

Kuşlar

Banamı ağlıyorsunuz

Kuşlar

Benimi kandırıyorsunuz

Kuşlar

Banamı çoğalıyorsunuz

Ey kuşlar

Ey saka

Ey serçe

Ey florya

Ey atmaca

Ey karga

Ey ismi sayılardan bile çok olan kuşlar

Ben bu dağları aşacağım

Sizden bile yükseklere uçacağım

Hepinizi mekkeye uçuracağım

Uçuracağım kuşlar

Göreceksiniz

Bu dünyanın nabzını müslümanlar tutacak', 'Kuşlar Benimi ötüyorsunuz Kuşlar Banamı gülüyorsunuz Kuşlar Benimi dövüyorsunuz Kuşlar Banamı uçuyorsunuz Kuşlar Benimi seviyorsunuz Kuşlar ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kuslar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Askerin Günlerin', 'bir-askerin-gunlerin-kadir-koz-ge167', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Asıl askerlik ne zaman başlar evlatlarım

Askerden sonra başlar komutanım

Jandarma marşını unutmayın evlatlarım

''Güzel yurdun güvenliği emanettir bizlere''

Unutmayacağız komutanım

Hepinize hayırlı teskereler evlatlarım

Sağolun komutanım

Kısık gözlerinde vatan bakışlı

Mersinli mehmet ast subayım

Beni yine döv

Ama dinle ne olur

Bir maruzatım var

Seni seviyorum komutanım

Öbür komutanlarımı da seviyorum

Mustafa kemal''ide çok seviyorum

Ama komutanım

Ama komutanım

Muhammed''i hepinizden çok seviyorum

Annemden bile çok seviyorum

O benim peygamberim

O benim arkadaşım

O benim kıyam duruşlum

O benim gönül yarem

O benim ciğer parem

O benim türkümün amentüsü

O benim şiirimin ş si

O benim mekke kanatlım

O benim safa ile merve aram

O benim yangın söndürücüm

O benim cihadımın manası

O benim suyumu şerbet yapanım

O benim zalime karşı kalkanım

O benim suskun haykırışım

O benim zehirimin panzehiri

O benim Allah''ımın sevgilisi

Kısacası komutanım

O benim herşeyimin her şeyi

Sizi unutmayacağım komutanım

Hakkınızı helal edin komutanım

Askerlik bitti komutanım

Bundan sonra Muhammed''in askeriyim

Lütfen beni anlayın', 'Asıl askerlik ne zaman başlar evlatlarım Askerden sonra başlar komutanım Jandarma marşını unutmayın evlatlarım ''Güzel yurdun güvenliği emane...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bir-askerin-gunlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanahmet Cezaevi', 'sultanahmet-cezaevi-vedat-turkali-vm3xw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabah serinliği gün ağarıyor

Demir taş küf yosun 

Sen böyle gecenin ortasında 

olan bitenden habersiz 

Uyuyor musun? 

Güvercin sesi çocuk sesi tren sesi 

Parmaklıklara yakışmayan ne varsa 

Duvarlarında 

Güneş bütün gün çağıradursun 

Elden ne gelir 

Yaşamak böyle kanlı akarsa 

Maviliğin dibinde böyle göz yaşları 

Kirli ağır durgun 

Daha bir süre akıp gidecek duvarlarında', 'Sabah serinliği gün ağarıyor Demir taş küf yosun  Sen böyle gecenin ortasında  olan bitenden habersiz  Uyuyor musun?  Güvercin sesi çocuk se...', ARRAY['Türk Edebiyatı','Şiir','Vedat Türkali']::text[], 8.5, '{"poet":"Vedat Türkali","poet_slug":"vedat-turkali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sultanahmet-cezaevi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi bize Bırak', 'bizi-bize-birak-kadir-koz-82vrq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rahat bırakın boztepeyi

Maşatlığın annesini rahat bırakın

Onu ben dün akşam gördüm

Tenha kayalıklarda maşatlığı emziriyordu

Memeleri kuruyordu boztepenin

Maşatlığın sütü kesiliyordu

Rüyamda sakallı çocuklar görüyorum

Belleri iki büklüm

Bastonlu çocuklar

Gördüğüm her çocuğa

Dede diyesim geliyor

Bu bebekler neden büyük doğuyor? 

Bu büyükler neden bebekleşiyor? 

Şu kırkbeşlik adama

Emzik veresim geliyor

Ey kocamış çağ

Erkeksen vur beni

Ama sakat bırakma

Beni vurdun mu

Öldüreceksin

Yaşatırsan

Yaşatmam bilesin

Tırnak makasım grevde

Parmaklarım

Tırnaklarımı büyütüyor

Pamuk prensesin annesi gibiyim

Ey kocamış çağ

Kalbini çıkaracağım

Bilesin

Bana belden aşağıya atma

Kafama kafama at

Bana düşman gibi bak

Münafık gibi bakma

Söveceksen adam gibi söv

Anamdan başla

Sülalemden çık

Çünkü ben bir başlarsam eğer

Ne yedi ceddin kalacak

Ne cinsin

Ne cibilliyetin

Rahat bırak ulan boztepeyi

Maşatlığı rahat bırak

Rahat bırak arafilboyunu

Trabzonu rahat bırak

Rahat bırak temeli

Fadimeyi rahat bırak

Koskoca bir yaz geçti

Bir tek tirsi bile yiyemedim

Annem kahvaltıda soğuk istavrit yemek istiyor

Rahat bırak karadenizi

Gençliğinde 

Denize girermiş çömlekçide

Bütün mahalle

Aynı mahalde yermiş

Aynı mahalde gülermiş

Aynı mahalde ağlarmış

Annem arafilboyunu geri istiyor

Ey kocamış çağ

''Gölge etme başka ihsan istemez''', 'Rahat bırakın boztepeyi Maşatlığın annesini rahat bırakın Onu ben dün akşam gördüm Tenha kayalıklarda maşatlığı emziriyordu Memeleri kuruyor...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/bizi-bize-birak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba', 'acaba-zeki-demir-5g9oo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün sensizliğe, sevgisizliğe alışırsam, 

beni benden çok sevmediğini anlarsam, 

kanayan yarama tuz basarsam, 

Ellerim kırılsın tek kelime yazarsam...

Unuttuğuna, yüreğini avuttuğuna, 

başka kalplere taht kurduğuna, 

bir inanasam mutlu olduğuna, 

Ellerim kırılsın tek kelime yazarsam...

Af dilemiyorum artık, yalvarmakta yok, 

sana yaptıklarım için cehennemde yer çok, 

azrail son sözün derde, yazmamı isterse, 

ne olur kızma seni sevdiğimi yazarsam....', 'Bir gün sensizliğe, sevgisizliğe alışırsam,  beni benden çok sevmediğini anlarsam,  kanayan yarama tuz basarsam,  Ellerim kırılsın tek kelim...', ARRAY['Türk Edebiyatı','Şiir','Zeki Demir']::text[], 8.5, '{"poet":"Zeki Demir","poet_slug":"zeki-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/acaba-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİN KONUŞSUN', 'gozleri-n-konussun-zeki-demir-mr54b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umut yok, ne olacak yarından, ne dünde kalandan, 

Beklemiyorum doğacak güneşi, kurtaramaz karanlıktan.

Bir insan kendi koparsa ondan, bahsedemez mutluluktan, 

Yudum, yudum içerken aşkı, yanlış kelimeler düşerse dudaklardan..

Sanki başka bir şehirdeyim, sesleniyorum mısralardan, 

Korkuyormuyum, utanıyormuyum karşına çıkmaktan.

Kurtulamıyor yüreğim, ne utançtan, ne sevdandan, 

Biliyorum affetmeyeceksin, çıktı söz dudaklardan..

Korkum gözlerinde, bakabilecekmi gözlerime ıslanmadan, 

Dudakların kadar cesurmu, bakabilecekmi bakışlarını kaçırmadan, 

Haykıra bilirmi gözlerin, sert ifadeden, nefretten arınmadan.

Bakarsa söz, onlara saygı duyup vaz geçeceğim bu sevdadan....', 'Umut yok, ne olacak yarından, ne dünde kalandan,  Beklemiyorum doğacak güneşi, kurtaramaz karanlıktan. Bir insan kendi koparsa ondan, bahsed...', ARRAY['Türk Edebiyatı','Şiir','Zeki Demir']::text[], 8.5, '{"poet":"Zeki Demir","poet_slug":"zeki-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerin-konussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan Benle', 'sevdan-benle-zeki-demir-mei03', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Varlığında içimde böylesi yoktun, 

yokluğunda arar oldum seni..

Yazdıklarını ne çabuk unuttun, 

hani ölene dek sevecektin beni.

Benim sevdam bitmedi, yüceldi, 

sensizlik sanki cehennemdi.

Bu aptalsevginin değerini bilmedi, 

oysa sensizlikte bile senleydi.

Hiç kimseyle olamadım sensizlikte, 

sevdan sanki hep nöbette..

Soyunup girmiştim yatağa birlikte, 

geç kalamadım özür dileyip giyinmekte.

Saygı duydu aşkıma o kişi bile, 

ben arayayım konuşayım dedi.

Göz yaşlarım sevgimi getirdi dile, 

yanımdaki lütfen ara dedi.

Ardım defalarca, yoktun iş yerinde, 

cep telin değiş aylar önce.

Aklım aradığımda söylediklerinde, 

sesimi duymak bile istemiyordun bence.

Tek kelimeyle anlatmak isterdim, 

sensiz olamadığımı.

Her şeyi gözlerimle söylerdim, 

az görmüşsündür ağladığımı....', 'Varlığında içimde böylesi yoktun,  yokluğunda arar oldum seni.. Yazdıklarını ne çabuk unuttun,  hani ölene dek sevecektin beni. Benim sevdam...', ARRAY['Türk Edebiyatı','Şiir','Zeki Demir']::text[], 8.5, '{"poet":"Zeki Demir","poet_slug":"zeki-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdan-benle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçilmezimsin', 'vazgecilmezimsin-sevdali-marti-iecli', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşamak gibi tutsak, 

ölüm gibi mecbur olduğumsun

vazgeçilmezimsin

yollar vazgeçiremedi senden beni

ellerimle her metresine

ismini yazdım

dağlar ayıramadı

çorak yüksekliklere

aşkımı kazıdım

ıssız gecelerde adımlarım

sana gelmek için sabırsız

yollarındaydım

yaşamak gibi tutsak, 

ölüm gibi mecbur olduğumsun

vazgeçilmezimsin...

16.10.97 / 19.00', 'yaşamak gibi tutsak,  ölüm gibi mecbur olduğumsun vazgeçilmezimsin yollar vazgeçiremedi senden beni ellerimle her metresine ismini yazdım da...', ARRAY['Türk Edebiyatı','Şiir','Sevdalı Martı']::text[], 8.5, '{"poet":"Sevdalı Martı","poet_slug":"sevdali-marti","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vazgecilmezimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yalnız', 'yalniz-ertan-sezgin-0z8db', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biliyorum

uyuyorsun şu an

başın ak bir yastıkta

ve saçların dağılmış

sanırım

tatlı bir rüya da görüyorsun

güzel gözlerin kapalı

ya ben

gecenin körü

yalnızım 

üşüyorum

yalnız

seni düşünüyorum.

29 temmuz 2001 kdz ereğli', 'biliyorum uyuyorsun şu an başın ak bir yastıkta ve saçların dağılmış sanırım tatlı bir rüya da görüyorsun güzel gözlerin kapalı ya ben gecen...', ARRAY['Türk Edebiyatı','Şiir','Ertan Sezgin']::text[], 8.5, '{"poet":"Ertan Sezgin","poet_slug":"ertan-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalniz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar Meyhanesi, Ben Ve Sen', 'dostlar-meyhanesi-ben-ve-sen-sefa-kaya-l2sx6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dostlar meyhanesinde içiyorum

Delice gülüyorum insanlara.

Kibar ayaklarında da değilim hani, inan

Rakımı isterken getir lan diyorum.

Herşeyi unuturum diye içiyorum.

Alkol komasına girsende unutamazsın diyor

Meyhaneci  sırdaşım osman baba

Şarkılar susuyor ağlıyorum.

Unutmak istiyorum ya oda nafile

Siktir et, gidip eve atayım kafayı bari

Nede olsa unutamıyorum...

Seni özlemelerde sevmeler kadar güzelmiş, 

Hani diyorum ya olmasada olurdu.', 'Dostlar meyhanesinde içiyorum Delice gülüyorum insanlara. Kibar ayaklarında da değilim hani, inan Rakımı isterken getir lan diyorum. Herşeyi...', ARRAY['Türk Edebiyatı','Şiir','Sefa Kaya']::text[], 8.5, '{"poet":"Sefa Kaya","poet_slug":"sefa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dostlar-meyhanesi-ben-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Yakarış', '1-yakaris-arzu-bagriacik-t99du', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kopmalı fırtına

Çiğnenmişlik dünyada.

Çocukluk yok, 

Koşuşturmaca.

Minik el yakarışlarda...

20.07.2001 Ankara', 'Kopmalı fırtına Çiğnenmişlik dünyada. Çocukluk yok,  Koşuşturmaca. Minik el yakarışlarda... 20.07.2001 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/1-yakaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-arzu-bagriacik-etfa5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çaresizlik bizim

Yok olma sakın.

Gece ürpertse de

İnatla git.

Zamanın belirsizliğinde

Ümit bizim.

20.07.2001 Ankara', 'Çaresizlik bizim Yok olma sakın. Gece ürpertse de İnatla git. Zamanın belirsizliğinde Ümit bizim. 20.07.2001 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/umit-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim', 'gidelim-alber-sarapcioglu-49wxi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Som hüzünden süzülmüş

Birkaç damla yanık acı

Sarsak adımlarına dolaşmakta

Ve sarsıla sarsıla ağlamakta koca bir gelecek.

Bu kaçıncı kurban verişin

Kana susamış adak yosmasına...

Düşler pul pul gümüşten bir balık sırtı gibi kaygan

Elle tutmak bir yana

Tenine dokunup kaçmakta...

Oysa gözünün önündeyken arkasını görüyorsun gerçeğin

O kadar şeffaf

Ve yanıltıcı

Ve asla tek değil

Çılgın bir güruh gibi üzerine çullanmakta...

Düşe dokunmak

Gerçeğin öte yanına geçme sanrısı

Ve gerçekte boğulmanın sancısına eşdeğer...

Köstebeğin keskin gözleri, koyunun keskin zekası

Ve bradipusun müthiş kıvraklığında şekillenmiş

Bir adalet buram buram kokmakta...

Ve bala bulanmış yapış yapış bir vicdan

Adı gibi garip sanal gerçekliğin içinde

Gözlerini kırpıştırarak şaşkın şaşkın bakmakta...

Ve delirium tremens son görevini yerine getirir gibi

Yüzüne karşı kahkahalar patlatarak

Ortalıkta dolaşmakta...

Şimdi geleceğe geçme zamanı

Yırtarak şeffaf yüzünü gerçeğin.

Ati-i istikbal ve ömr-ü hayat gibi tuhaf tamlamaların

Üzerinden Sergei Bubka edasıyla aşma zamanı...

Gidelim insan ırkı, yaratıkların soyu

Artık kimsenin seçme şansı yok

Bize verileni alalım ve gidelim

Tohumumuzdaki sadizmi, sonradan öğrendiğimiz kurmaca sevgiyi

Ve üremeye kodlanmış anlamsız varoluşumuzu

Alalım ve gidelim...', 'Som hüzünden süzülmüş Birkaç damla yanık acı Sarsak adımlarına dolaşmakta Ve sarsıla sarsıla ağlamakta koca bir gelecek. Bu kaçıncı kurban v...', ARRAY['Türk Edebiyatı','Şiir','Alber Şarapçıoğlu']::text[], 8.5, '{"poet":"Alber Şarapçıoğlu","poet_slug":"alber-sarapcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gidelim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlük Ağacına Ağıt', 'gunluk-agacina-agit-fatih-soyler-ex1rn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kederliyim

seni bir kez bile görmedim 

fotoğrafların konuştu benimle

çoğu uzak dağların sisli tepelerinde

neredeyse kayıp, 

neredeyse unutulmuş

acıyla kıvranan anaları

ve karınları aç

ve ayakları çıplak çocukları

anımsatmak istercesine

mahzun ve ağlamaklı

kederliyim

eline değmedi elim

mektuplarını okudum durmaksızın

yazılmış gibiydiler yapayalnız bir sahilde

sanki öksüz, yetim, 

lodosa boyun eğmiş bir günlük ağacının

belirsiz geleceğine

ağıt yakıyordu parmakların

öylesine umutsuz, 

o denli kırılgan

ama bilirim ki

her zaman hüzün, 

çoğu zaman gözyaşıyla yıkansa da bedenin

hainlere zılgıt

zalimlere inat

sevda kokusu gelir koynundan

Ankara, Mart,2000', 'kederliyim seni bir kez bile görmedim  fotoğrafların konuştu benimle çoğu uzak dağların sisli tepelerinde neredeyse kayıp,  neredeyse unutul...', ARRAY['Türk Edebiyatı','Şiir','Fatih Söyler']::text[], 8.5, '{"poet":"Fatih Söyler","poet_slug":"fatih-soyler","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gunluk-agacina-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Amak', 'yol-amak-arzu-bagriacik-rva0n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O gemide bende olsaydım, 

Açık denizlere yol alsaydık.

Sadece biz

Ve 

Unutsaydık insanları.

Umursamadan bir bütün olsaydık.

Fırtına kopsa da

Alabora olmadan

Dünyayı son nefese dek

Dolaşsaydık.

Ankara', 'O gemide bende olsaydım,  Açık denizlere yol alsaydık. Sadece biz Ve  Unutsaydık insanları. Umursamadan bir bütün olsaydık. Fırtına kopsa da...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yol-amak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-veysel-tanriverdi-w3qht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık

Seni düşününce üşüyorum

Biliyor musun? 

Habire dökülüyorum

Yaprak yaprak

Karıncalar girmiş yuvalarına

Duvar dipleri çok soğuk

Üşüyorum

Biliyor musun? 

Ayyuka ulaştı titremelerim

Kulaklarım çınlıyor

Anan sen değilsin.

Kuşlar uçalı günler oldu, 

Tohumlar çilerdi

Son yağmurlarla.

Kapısını çoktan kapattı

Elalem.

Ağustos böceği bile görünmüyor

Ortalarda.

Ağlamak mı? 

Ne fayda! 

Saçaklar var ya! 

Eh

Son demdir seni andığım

Artık üşümüyorum

Biliyor musun?', 'Artık Seni düşününce üşüyorum Biliyor musun?  Habire dökülüyorum Yaprak yaprak Karıncalar girmiş yuvalarına Duvar dipleri çok soğuk Üşüyorum...', ARRAY['Türk Edebiyatı','Şiir','Veysel Tanrıverdi']::text[], 8.5, '{"poet":"Veysel Tanrıverdi","poet_slug":"veysel-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/usuyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Seni...', 'yalniz-seni-veysel-tanriverdi-8k68o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni tek başıma sevdim

Ben yalnızdım

Sen değildin.

Ama

Yalnız seni sevdim

Ben hep yalnızdım

Sen değildin.

Yalnız bozuk paralarım vardı yanımda

Seni sevdiğim gecelerde.

Korkmadım

Çünki ben

Yalnızlıktım.

Kimse yoktu yanımda

Ben

Hep yalnızdım

Ve

Yalnız seni sevdim

Yalnız bir tren kalkardı

Bu şehirden

Yalnızdım seni düşünürken

Yapayalnızdım ağlarken...', 'Seni tek başıma sevdim Ben yalnızdım Sen değildin. Ama Yalnız seni sevdim Ben hep yalnızdım Sen değildin. Yalnız bozuk paralarım vardı yanım...', ARRAY['Türk Edebiyatı','Şiir','Veysel Tanrıverdi']::text[], 8.5, '{"poet":"Veysel Tanrıverdi","poet_slug":"veysel-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalniz-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna', 'bosuna-turan-ozden-rqnmd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dost yolları nakışlandı kanımdan 

sevdiklerim vergi keser canımdan

sensizliğe dayanamam gitme yanımdan 

incitip günaha girme boşuna

aşk koymuşlar ızdırabın adını 

alamdım yaşamanın tadını 

yapacaksan eğer bana yardımı

öldür kurtar ilaç verme boşuna', 'dost yolları nakışlandı kanımdan  sevdiklerim vergi keser canımdan sensizliğe dayanamam gitme yanımdan  incitip günaha girme boşuna aşk koym...', ARRAY['Türk Edebiyatı','Şiir','Turan Özden']::text[], 8.5, '{"poet":"Turan Özden","poet_slug":"turan-ozden","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bosuna-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepten Sensiz Kalmak', 'hepten-sensiz-kalmak-arzu-altun-m5532', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben  daha  hiç  sensiz  bir  gün  geçirmedim, 

Sensizlik  nedir  biliyor  musun? 

Seni  düşünmemektir, 

Kanımın  yüreğime  doğru  akmamasıdır, 

Sensizlik, 

Hepten  yok  oluşumdur.

Ben  daha  hiç  sensiz  bir  gün  geçirmedim, 

Sensizlik  nedir  biliyor  musun? 

Kör  olmaktır, 

Elimin,  ayağımın  tutmamasıdır, 

Hepten  ziyan  olmaktır, 

Ben  daha  hiç  sensiz  bir  gün  geçirmedim, 

Sensizlik  nedir  biliyor  musun? 

Yaraya  tuz  basmaktır, 

Ve  sensiz  bir  cennetle  mükafatlandırılmak, 

Hepten  günahkar  olmaktır, 

Ben  daha  hiç  sensiz  bir  gün  geçirmedim, 

Sensizlik  nedir  biliyor  musun? 

Adımı  hatırlamamaktır, 

Aynada  kendimi  tanıyamamak, 

Hepten  kendimi  kaybetmektir, 

Ben  daha  hiç  sensiz  bir  gün  geçirmedim, 

Sensizlik  nedir  biliyor  musun? 

Dikenli  tellerde  yürümek, 

Su  diye  seni  kana  kana  içememektir, 

Hepten  soluksuz  kalmasıdır  ciğerlerimin, 

Ben  daha  hiç  sensiz  bir  gün  geçirmedim, 

Sensizlik  nedir  biliyor  musun? 

Yok  olduğunu  düşünmektir, 

Öleceğini  düşünmektir, 

Hepten  biçare  kalmaktır  sensizlik...

Hepten  sensiz, 

Hepten  bir  hiç  olmaktır.', 'Ben  daha  hiç  sensiz  bir  gün  geçirmedim,  Sensizlik  nedir  biliyor  musun?  Seni  düşünmemektir,  Kanımın  yüreğime  doğru  akmamasıdı...', ARRAY['Türk Edebiyatı','Şiir','Arzu Altun']::text[], 8.5, '{"poet":"Arzu Altun","poet_slug":"arzu-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hepten-sensiz-kalmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karı''m', 'kari-m-veysel-tanriverdi-nmepn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kirli çamaşır

Toprak damım.

Gidemediğim yol

Bir karış menzilim.

Bulutsuz dağım

Suskun çayım

Aylanmış düşüm

Gelmeyen yarınım.

Tuzsuz çorbam

Ela çingenem

Sarı düşüncem.

Ezelim, Ebedim, Tanrım! 

Titreyen her yanım

Kırmızı kupam

Göstergem

Çift jokerim, 

Açmaz elim, 

Gülüm.

Tuzsuz çorbam

Ela çingenem

Sarı düşüncem

Erimeyen eteksiz KAR''ım

Doygunluğum

Zana''m

İnce dalım

Türküm

Kara kalemim

Sığınağım...

Beyaz sinek

Acı kovanım

Mayasız ekmeğim

Beşersiz Kraliçem

Gelmeyen yarınım

Tuzsuz çorbam

Ela düşüncem

Sarı çingenem

KARI''m', 'Kirli çamaşır Toprak damım. Gidemediğim yol Bir karış menzilim. Bulutsuz dağım Suskun çayım Aylanmış düşüm Gelmeyen yarınım. Tuzsuz çorbam E...', ARRAY['Türk Edebiyatı','Şiir','Veysel Tanrıverdi']::text[], 8.5, '{"poet":"Veysel Tanrıverdi","poet_slug":"veysel-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kari-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Akşamında Benim Dağlarım', 'gurbet-aksaminda-benim-daglarim-kazim-yaman-kxtvt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok uzaklardayım memleketimden

Gözümde tütüyor bahçe bağlarım

Neler kaybettim neler kendimden

Aklıma geldikçe yanar ağlarım

Köyümü özledim of aman aman

Gönlümde hüzün var başımda duman

Bilmem kaç yıl oldu bilmem kaç zaman

Gurbet ellerinde yanar ağlarım

Aklıma türlü türlü soru takılır

Düşünür düşünürüm canım sıkılır

Bin kez bina olur bin kez yıkılır

Gurbet akşamında benim dağlarım.', 'Çok uzaklardayım memleketimden Gözümde tütüyor bahçe bağlarım Neler kaybettim neler kendimden Aklıma geldikçe yanar ağlarım Köyümü özledim o...', ARRAY['Türk Edebiyatı','Şiir','Kazım Yaman']::text[], 8.5, '{"poet":"Kazım Yaman","poet_slug":"kazim-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-aksaminda-benim-daglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehir Zemberek Bir Geceydi', 'zehir-zemberek-bir-geceydi-arzu-altun-3dqxe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '*  *  *

Zehir zemberek bir geceydi

Aklımda kalan

Mide bulantılarım

Unutkanlığım

Bir çilingir sofrası düşü

Sonrasında

Başımı alıp gittiğim

Ulaşlı yolu

Bir de etime batan diken misali

Gürültülü yalnızlığım

Kimyası sarhoşluğun

Yalnızlık

Aranan 

Usul usul sevilmek ihtiyacı

Bu zıkkım bile kesmedi

Susamışlığı

Katı kuralı kalabalığın

Zamana hapsetmek

Sevmeyi

Hayvanca kurallar koymak

İnsanca sevmeye

Aradığım

Zamansızlıkta

Aşkı bulmaktı

Yalnızlığımda 

Kalabalığı...', '*  *  * Zehir zemberek bir geceydi Aklımda kalan Mide bulantılarım Unutkanlığım Bir çilingir sofrası düşü Sonrasında Başımı alıp gittiğim Ul...', ARRAY['Türk Edebiyatı','Şiir','Arzu Altun']::text[], 8.5, '{"poet":"Arzu Altun","poet_slug":"arzu-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/zehir-zemberek-bir-geceydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda Özel', 'umuda-ozel-nurullah-aydin-kqa3a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umuda Özel

Bu bambaşka bir gece

Yaşadıklarımdan daha da öte

Karanlıkta duruyorum

Kimse dokunmasın diye yalnızlığıma

Birden sen girdin fikrime

Henüz adını koyamadığım umudum

Gökyüzüne bakıyorum

Yıldızlara ve Ay''a

Seni görme ümidiyle

Kulağımda bir keman ezgisi var

Bana seni anlatan

İçime yeni umutlar saçan

Gitme, 

Yıldızım sönüyor

Işığımı kaybediyorum

Artık umudumu yaşamak istiyorum dilediğimce

Yıldızım olurmusun…? 

Elimden tutabilirmisin karanlıkta…? 

Işığını verirmisin bana…? 

Nurullah AYDIN/01.07.2001', 'Umuda Özel Bu bambaşka bir gece Yaşadıklarımdan daha da öte Karanlıkta duruyorum Kimse dokunmasın diye yalnızlığıma Birden sen girdin fikrim...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/umuda-ozel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Tarifi', 'mutlulugun-tarifi-nurullah-aydin-u021m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluğun Tarifi

Işıklar birer birer sönmüş

Karanlık binmiş heryerine bu şehrin

Kimi derin uykusunda

Kimi ise işyerinde, ekmek parası peşinde

Bense yılların verdiği yorgunluğu atarmışcasına

Balkon sefasındayım

Masamda mum ışığı

Radyoda dinlediğim ince ezgiler

Bir paketin dibinde kalmış bir kaç dal sigara

Biraz kağıt, bir de kalem

Yarenlik ediyor bana

Yazıyorum

Allaha çok şükür mutluyum artık.....

Nurullah AYDIN-19/06/01 00: 47', 'Mutluluğun Tarifi Işıklar birer birer sönmüş Karanlık binmiş heryerine bu şehrin Kimi derin uykusunda Kimi ise işyerinde, ekmek parası peşin...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mutlulugun-tarifi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş - 2', 'bekleyis-2-nurullah-aydin-05vz9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekleyiş-2

Gece yalnızlığını hissettirdiği zaman

Sensizlik doldu birden odama

Bir yanım senden nefret ederken

Bir yanım seni özlüyor

Nasıl bir duyguysa sana duyduğum

Yazdıkça sonu gelmiyor

Gidişinin bu gece 175 nci günü

Anladım ki asla dönmeyeceksin...

Nurullah AYDIN 19/09/01-00: 04', 'Bekleyiş-2 Gece yalnızlığını hissettirdiği zaman Sensizlik doldu birden odama Bir yanım senden nefret ederken Bir yanım seni özlüyor Nasıl b...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bekleyis-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri Bir Rüzgar Eser Ruhumda', 'serseri-bir-ruzgar-eser-ruhumda-arzu-altun-ki16u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Serseri bir rüzgar eser ruhumda

Aradığım özgürlüktür kanımda

Bulanık doğrulardan arınmak

Almak gerçekleri avuçlarıma

Hatırı sayılır bir kahve, köpüğü bolca

Anlatılacak belki kırk yıl sonra

Ta ki uzağında şimdinin

Ta ki uzağında bu yerin

İnleyen bir nağmedir o vakit mazi

Neylersin? 

Koca bir hiç, yaşamak

Onca yıldan sonra elimde kalan

Çok değil; birkaç anı yalnızca', 'Serseri bir rüzgar eser ruhumda Aradığım özgürlüktür kanımda Bulanık doğrulardan arınmak Almak gerçekleri avuçlarıma Hatırı sayılır bir kahv...', ARRAY['Türk Edebiyatı','Şiir','Arzu Altun']::text[], 8.5, '{"poet":"Arzu Altun","poet_slug":"arzu-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/serseri-bir-ruzgar-eser-ruhumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-nurullah-aydin-tjc1r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdalardan geçtim

Zorlu günlerden de

Hiçbiri dokunmamıştı bir yalan kadar

Bir aşk adamı bozmaz belki ama

Bir yalan adamı perişan eder

-19/06/01-01: 05', 'Sevdalardan geçtim Zorlu günlerden de Hiçbiri dokunmamıştı bir yalan kadar Bir aşk adamı bozmaz belki ama Bir yalan adamı perişan eder -19/0...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalan-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-nurullah-aydin-b4pl5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gider bu divane gönül artık buralardan

Gam dolu keder dolu yerlerden uzaklara

Mutluluklar ülkesinde yaşayan

İçi umutlarla dolu insanların diyarına.....

Nurullah AYDIN-10/07/01-15: 15', 'Gider bu divane gönül artık buralardan Gam dolu keder dolu yerlerden uzaklara Mutluluklar ülkesinde yaşayan İçi umutlarla dolu insanların di...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/veda-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-nurullah-aydin-m383e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kocamış bir çınarın gölgesinde

Gördüm bu akşam gençliğimi

Yürüdüm 

Hayaller kurduğum

Acılarımı

Sevinçlerimi 

Yaşadığım İstanbul sokaklarında

Aradım yine her yerde 

Bir türlü bulamadığım duygularımı

Gözlerim az ilerideki banklara ilişti

Oturdum öyle uzun uzun

Gecenin koynuna karşı

Umudumu düşündüm ansızın

Ve tek soru düştü dilimden

Acaba...? 

Nurullah AYDIN-11/07/01-19: 45', 'Kocamış bir çınarın gölgesinde Gördüm bu akşam gençliğimi Yürüdüm  Hayaller kurduğum Acılarımı Sevinçlerimi  Yaşadığım İstanbul sokaklarında...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soru-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müjde', 'mujde-nurullah-aydin-wsupx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecelerle paylaştım yalnızlığımı

Kah yıldızlar dost oldu bana

Kah dolunay

Aşamadım yalnızlık denen duygu duvarını

Yinede umudum hep kalbimde gizli 

Gün ışığını beklercesine

Sökmesede şafaklar

İnadına beklerim 

Her gece

Karanlığın getireceği müjdeyi

Nurullah AYDIN-18/07/2001', 'Gecelerle paylaştım yalnızlığımı Kah yıldızlar dost oldu bana Kah dolunay Aşamadım yalnızlık denen duygu duvarını Yinede umudum hep kalbimde...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mujde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Aşk', 'yasak-ask-nurullah-aydin-9yx0a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yasak diye birşey yok

Bu bizim yalanımız

Sevdaya güvenmekse 

En büyük hayalimiz

Görmüyor muhakkak gözlerimiz

Etrafımızdaki duyguları

Konusulanlarsa aşkın çabaları

Nurullah AYDIN-21/07/2001', 'Yasak diye birşey yok Bu bizim yalanımız Sevdaya güvenmekse  En büyük hayalimiz Görmüyor muhakkak gözlerimiz Etrafımızdaki duyguları Konusul...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasak-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İllede Sen', 'i-llede-sen-nurullah-aydin-56hrw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soğuk rüzgarlar eser yüreğimde

Sen yanımdan gidince

Alaca karanlık başlar dünyamda

Bir kabusa dönüşür

Bir çığlık sesi gelir içimden

Bir ürperti sarar bedenimi

Sensizlik bunun nedeni

Görüyorum, evet görüyorum

Güneş yeniden doğuyor

Karanlığı ezercesine

O sensin yanımdasın

Varlığınla bir tanem canımdasın

Damarlarımda dolaşan kanımdasın

Gözlerim dolu dolu olur

Hiç sorma neden? , kimden? 

Üzülürsün diye anlatamam sana

Beraber olacağımız günleri düşünüp avunuyorum

Onun için sensizliğe sabrediyorum

Sen sorduğunda halimi, söyeleyemiyorum derdimi

Sen yanımda olduğunda tüm kabuslar biter

Sen yanımda ol

Bu bana yeter

Diliyorum Allah''tan

Ömrüm hep seninle geçer

Nurullah AYDIN - 1998/Polatlı', 'Soğuk rüzgarlar eser yüreğimde Sen yanımdan gidince Alaca karanlık başlar dünyamda Bir kabusa dönüşür Bir çığlık sesi gelir içimden Bir ürpe...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/illede-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-adil-ek-rvqcw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ayrılık vardır ki eşten dosttan ve arkadaştan, 

Menzil bilinmez, belki yüksektir arştan.

İnip kalkarken göğüs kafesi, 

Bir bıçak misali kesti ecel son nefesi.

Niye bakıyorsun tavana, ne aramaktasın? 

Düşünsene yakında arş-ı haktasın.

Uzanmış yerde yatmakta ölü, 

Sessiz ve sakin sanki sahra çölü.

Son bir heyecanla çarptı yürekler, 

Gözlerime toptak doldurdu kürekler.

Hoca el açtı benim için dua etti, 

Sonra bütün dostlarım birer birer kabrimi terketti.

Mekanım oldu o topraktan yapı, 

Manevi aleme açıldı saydam bir kapı.', 'Bir ayrılık vardır ki eşten dosttan ve arkadaştan,  Menzil bilinmez, belki yüksektir arştan. İnip kalkarken göğüs kafesi,  Bir bıçak misali ...', ARRAY['Türk Edebiyatı','Şiir','Adil Ek']::text[], 8.5, '{"poet":"Adil Ek","poet_slug":"adil-ek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhül Değilmi', 'mechul-degilmi-i-lhan-yuksel-9ldzs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vardır suçu asın diyen itoğlu 

Devir suçlununda itin değilmi 

Mahkemeye varsın diyen itoğlu 

Hakimim cellada teslim değilmi 

Alınıp Fravnun mumyadan hücre 

Babalık tesbiti yapılmadıkça 

Olsada nüfusu Buca da kaydı 

Celladın piç soyu meçhul değilmi', 'Vardır suçu asın diyen itoğlu  Devir suçlununda itin değilmi  Mahkemeye varsın diyen itoğlu  Hakimim cellada teslim değilmi  Alınıp Fravnun ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mechul-degilmi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diriliş', 'dirilis-aziz-nesin-mt60q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittikçe artıyor yerçekimi

Çek elimden, 

Kurtarsın yerçekiminden

Aşkın çekimi...

Akıyorum aşağılara sızım sızım

Duyuyorum içimdeki derinlikleri

Öpe öpe çek çıkar, 

Soluğunla dirilt beni..

Kumsaldan nasıl sızarsa sular

Çöküyorum dibe azar azar

Dağılıp parçalanıp ayrılıyorum

Topla beni tut beni...

Yağmurca gözyaşlarınca

Aşağı aşağı çizgilerim 

al avuç avuç fırlat gökyüzüne

Yeniden yarat beni...', 'Gittikçe artıyor yerçekimi Çek elimden,  Kurtarsın yerçekiminden Aşkın çekimi... Akıyorum aşağılara sızım sızım Duyuyorum içimdeki derinlikl...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesin']::text[], 8.5, '{"poet":"Aziz Nesin","poet_slug":"aziz-nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dirilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Arzusu', 'gonul-arzusu-cemanur-akkoc-b5ikn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gurbet sen o kadar acı birisin

Ağarttın saçları kuruttun beni

Hainliğin kadar kalleş değilsin

Saz çaldın gönlüme uyuttun beni 

Boyadın gözleri gönül yoruldu

Aç bıraktın bizi toprak darıldı

Benimde güzel yurdum var idi

Saz çalıp gönlüme uyuttun beni

Sağlığımı aldın verdin ızdırap

Sıla hasreti var yolu çok ırak

Gelenden gidenden hatırlar sorar

Teselli arattın avuttun beni', 'Gurbet sen o kadar acı birisin Ağarttın saçları kuruttun beni Hainliğin kadar kalleş değilsin Saz çaldın gönlüme uyuttun beni  Boyadın gözle...', ARRAY['Türk Edebiyatı','Şiir','Cemanur Akkoç']::text[], 8.5, '{"poet":"Cemanur Akkoç","poet_slug":"cemanur-akkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-arzusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Analara', 'butun-analara-cemanur-akkoc-mspii', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şükrederim tanrım sana

Bunca gücü verdin bana

Hakkı ödenmeyen varsa

Oda derim sensin ana 

Anaların hakkı çoktur

Gözü gönlü pekde toktur

Yiyecek ekmeği yoktur

Canından can veren ana

Tariflere sığmaz gücün

Analıktır senin suçun

Baksan nere vardı göçün

Erişilmez sana canım ana

Anaların çoktur yükü

Açtır karnı tokdur gözü

Eğer yeter ise ömrü

Daha neler yapmazki ana', 'Şükrederim tanrım sana Bunca gücü verdin bana Hakkı ödenmeyen varsa Oda derim sensin ana  Anaların hakkı çoktur Gözü gönlü pekde toktur Yiye...', ARRAY['Türk Edebiyatı','Şiir','Cemanur Akkoç']::text[], 8.5, '{"poet":"Cemanur Akkoç","poet_slug":"cemanur-akkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/butun-analara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüklerim', 'gorduklerim-cemanur-akkoc-kbhrc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gençlik perişan cahillik kötü

Almış sigarayı tüttürür gençlik

Anneler babalar çekerler kahrı

Sonunu düşünmez estirir gençlik

Üç beş kuruşunu verirler kursa

Hele birde yüksel caddesine uğrarsa

Çevresine bakıp özenti varsa

O zaman yolunu şaşırır gençlik

Genç yaşta ciğerler dumanla dolar

Aksini düşünmez mutludur onlar

Sağlığı kaybeder çevrede arar

Suçu kendisinde bulamaz geçlik', 'Gençlik perişan cahillik kötü Almış sigarayı tüttürür gençlik Anneler babalar çekerler kahrı Sonunu düşünmez estirir gençlik Üç beş kuruşunu...', ARRAY['Türk Edebiyatı','Şiir','Cemanur Akkoç']::text[], 8.5, '{"poet":"Cemanur Akkoç","poet_slug":"cemanur-akkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gorduklerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Ve Duvar', 'dus-ve-duvar-abaryan-engin-nd9ot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine salına salına geldi o duvar, 

Mahcup bir özlemle çağırırım onu dağıttığım yerlerden, 

43 derecede bile o ilk ağrı, ilk heyecan 

O duvar

Eksik ve yanlışta olsa o ömre dönmek ister, 

Hep susuz bırakılan o eski düşe dönmek ister, 

Kimsesiz bir umutla birlikte.', 'Yine salına salına geldi o duvar,  Mahcup bir özlemle çağırırım onu dağıttığım yerlerden,  43 derecede bile o ilk ağrı, ilk heyecan  O duvar...', ARRAY['Türk Edebiyatı','Şiir','Abaryan Engin']::text[], 8.5, '{"poet":"Abaryan Engin","poet_slug":"abaryan-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dus-ve-duvar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Testi', 'testi-ahmet-muhip-diranas-i4fe0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolu bir testi idim ben, 

Baş aşağı ettiniz beni; 

Eh, boşalıverdim derken...', 'Dolu bir testi idim ben,  Baş aşağı ettiniz beni;  Eh, boşalıverdim derken......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dıranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dıranas","poet_slug":"ahmet-muhip-diranas","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/testi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk', 'yokluk-deniz-faytonu-ys1b3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bugün

bu kentte 

tanınmadık tatlar arasında 

gözlerinin karasını yiyorum

sende göreceksin 

bir baksan 

ben yokum 

bokum

o kum

ben kum', 'bugün bu kentte  tanınmadık tatlar arasında  gözlerinin karasını yiyorum sende göreceksin  bir baksan  ben yokum  bokum o kum ben kum...', ARRAY['Türk Edebiyatı','Şiir','Deniz Faytonu']::text[], 8.5, '{"poet":"Deniz Faytonu","poet_slug":"deniz-faytonu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yokluk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlık', 'varlik-deniz-faytonu-goy1t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bugün

bu kentte 

tanınmadık tatlar arasında 

gözlerinin karasını yiyorum

baksan 

göreceksin sende

ben yokum 

bokum

o kum

ben kum', 'bugün bu kentte  tanınmadık tatlar arasında  gözlerinin karasını yiyorum baksan  göreceksin sende ben yokum  bokum o kum ben kum...', ARRAY['Türk Edebiyatı','Şiir','Deniz Faytonu']::text[], 8.5, '{"poet":"Deniz Faytonu","poet_slug":"deniz-faytonu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/varlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalleri, Aşkı ve Kaçan Tren', 'hayalleri-aski-ve-kacan-tren-mehmet-sercan-tezcanoglu-2e8hy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saat bilmem kaçı gösteriyordu.

Pijamalarını, gömleğini valizine koydu.

Aşkını koydu.

Hediye ettiği kitabı ve içindeki kurumuş çiçeği, 

Nefesini koydu içine çekip de bırakmadığı.

Aslını koydu valize, sahtesini çıkardı attı.

Anılarını, düşlerini, düşüşlerini, yükselişlerini koydu.

Hayallerini, ümitlerini en üste yerleştirdi.

Ceketini giydi üstüne, 

Tren biletini cebine koydu.

Kravatını bağladı, 

İğnesini taktı.

Saatine baktı: 

Saat bilmem kaçı gösteriyordu.

Bavulunu kapattı, 

Aldı eline.

Kapıyı açtı.

Varını dışarı koydu, 

Yoğunu içeri.

Kapıyı kapattı.

Kendini yola koydu.

Düşüncelerini yola dağıttı.

Sonra bir bir topladı.

Yine dağıttı.

Trenin acı ıslığını duydu.

Valizini trene koydu.

Yola çıkıp da düşüncelerini toplamaya başlayınca

Kaçırdı treni.

Hayalleri de umutları da trene binip gitti.

Koştu arkasından koştu.

Çiçek kurusu el salladı.

O düştü.

Dağıldı düşünceleri raylara.

Ayağa kalktı, 

Hepsini bir bir topladı.

Koştu evine.

Açtı kapıyı.

Yokları dışarı kaçtı, 

Varı girdi içeri.

Kapıyı kapattı.

Sahtesini attı camdan dışarı, 

Bir tek aslı kaldı.', 'Saat bilmem kaçı gösteriyordu. Pijamalarını, gömleğini valizine koydu. Aşkını koydu. Hediye ettiği kitabı ve içindeki kurumuş çiçeği,  Nefes...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/hayalleri-aski-ve-kacan-tren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah Senfonisi', 'bir-sabah-senfonisi-mehmet-sercan-tezcanoglu-zqsig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyandım yine uykumda.

Çalar saati fırlattım duvara, 

Bir şey olmadı.

Ben kalktım, 

Ruhum yatakta kaldı.

Buzdolabını açtım.

Su içtim.

Kana kana içtim.

Esnedim, gerildim; 

Ruhum kalkmadı.

Banyoya gittim, 

Gömdüm yüzümü

Küçük bir denize.

Kimseler yoktu.

Döndüm yüzümü aynaya, 

Göz kapaklarım ağırdı.

Çok ağırdı.

Yılların yorgunluğu aynadaydı, 

Bana bakıyorlardı.

Ben de onlara...

Ne kadar yorgundular, 

Onlara acıdım.

Döndüm, 

Suyu çektim aldım yüzümden

Bıraktım havluya.

Havlunun gözleri yaşardı.

Odama döndüm, 

Ruhum kalkmıştı.

Esniyordu hergele

Ne kadar yorgundu.

Acıdım ruhuma, 

Bir el ense patlattım.

Kendine geldi.

Bir de kahkaha patlattım.

Ruhum da güldü.

Üstümü başımı giyindim, 

Ruhum giyinmedi.

Kapıya yöneldim, 

Ruhumun gelmeye hiç niyeti yoktu.

Sensiz ne yaparım ben sokaklarda, dedim.

Geldi, sarıldı boynuma.

Girdi içime, 

Bir daha da çıkmadı.

Kapıyı açtım.

Kapıyı kapattım.

Güneşe çıktım.

Ruhum uyandı.', 'Uyandım yine uykumda. Çalar saati fırlattım duvara,  Bir şey olmadı. Ben kalktım,  Ruhum yatakta kaldı. Buzdolabını açtım. Su içtim. Kana ka...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-sabah-senfonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haftanın Günleri', 'haftanin-gunleri-omer-hayyam-tj2cy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilir misin yüceler yücesi tanrı

Şarap ne zaman coşturur içenleri? 

Pazar, pazartesi, salı, çarşambe, perşembe, 

Bir de cuma, cumartesi günleri....', 'Bilir misin yüceler yücesi tanrı Şarap ne zaman coşturur içenleri?  Pazar, pazartesi, salı, çarşambe, perşembe,  Bir de cuma, cumartesi günl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/haftanin-gunleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çigan Gözler', 'cigan-gozler-umit-yasar-oguzcan-yaxpp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şarkısız ve sensiz kaldığım nice akşamlar

Gözlerin geçer aklımdan özlemler içinde

Gözlerin bir çigan müziği güzelliğinde

Kirpiklerinde keman, bebeklerinde gitar...

İç ürperten sesin her gece odama dolar

Bir buğu yükselircesine göğe kadehten

Nasıl başım döner nasıl mest olurum bilsen

Ağlarım, saçlarında gün doğuncaya kadar...

Mutluluk bir ateştir uzaklarda yaktığın

Ki binlerce ''yay'' çekilircesine derinden

En hazin şarkıları dinlerim gözlerinden

Büyür gitgide hüznü içimde yanlızlığın

Dinlerim o hiç susmak bilmeyen çiganları

Ve bir musiki halinde geçen zamanları...', 'Şarkısız ve sensiz kaldığım nice akşamlar Gözlerin geçer aklımdan özlemler içinde Gözlerin bir çigan müziği güzelliğinde Kirpiklerinde keman...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cigan-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarını Anlatmalısın', 'yarini-anlatmalisin-suat-atar-md9n1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel ceylanim; 

                     Bilinmeyen bir evrene gidelim seninle

                     Agaclari yesil, cicekleri pembe olan

                     Bu dunya kadar cirkin

                     Insanlari kadar kötü olmayan bir evrene

                     Kücük bir kulübemiz olsun orada

                     Fakir bacasinda mutluluk tüten

                     Yanliz ikimiz icin

                     Beni dizlerine yatirmalisin

                     Ellerimi avuclarimin icne alip

                     Dünkü katranli geceleri degil

                     Bana martili ak kanadinca

                     YARINI ANLATMALISIN', 'Gel ceylanim;                       Bilinmeyen bir evrene gidelim seninle                      Agaclari yesil, cicekleri pembe olan         ...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yarini-anlatmalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım', 'alisamadim-suat-atar-zetvk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanmaki unuttum gözlerini

Hasreti yenmeyi basaramadim

Gözlerim her yerde seni ariyor

Yokluguna hala alisamadim

                                 Bilirim mutlusun kendi dunyanda

                                 Bir baska güzel var simdi rüyanda

                                 Gözümden sözümden uzak olsanda

                                 Yokluguna hala alisamadim

Unuttum desemde sözlerim hep yalan

Düslerde yasarim ben seni inan

Ne olur yanimda olsaydin su an

Yokluguna hala alisamadim

                                 Alisamadim gözlerinden uzak durmaya

                                 Alisamadim senden uzakta olmaya

                                 Alisamadim hasretinle yalniz kalmaya

                                 Alisamadim gülüm alisamadim', 'Sanmaki unuttum gözlerini Hasreti yenmeyi basaramadim Gözlerim her yerde seni ariyor Yokluguna hala alisamadim                              ...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alisamadim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim', 'giderim-nurullah-genc-r3339', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde bir acı fırtına kopar

Bulutlarda şimşek çakar giderim

Bitmeyen arzular yolumu kapar

Çılgın bir sel gibi yıkar giderim

Anlarım eşitten farkını farkın

Yıllar süren ömrü biter merakın

Keder uzak olur; mutluluk yakın

Yorgun kafesimden çıkar giderim

O an, zaman durur, mekan silinir

Sonsuzluğa doğru nefes alınır

Ruhum bir damla su, göğe salınır

Süzüle süzüle akar giderim

Çile denizinin görünür dibi

Alır beni yüreğimin sahibi

Geceyi süsleyen yıldızlar gibi

Ben de, bir meş''ale yakar giderim

Birgün utku için, hicran yerine

Dalmak için hülya bahçelerine

Dostların ıslanmış çehrelerine

Son defa, hasretle bakar giderim', 'İçimde bir acı fırtına kopar Bulutlarda şimşek çakar giderim Bitmeyen arzular yolumu kapar Çılgın bir sel gibi yıkar giderim Anlarım eşitten...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/giderim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Dediğin', 'olum-dedigin-bulent-pinarbasi-gk2as', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölürsem, güzel olmalı ölümüm

Sıradan, temiz, aklı başında

Bir şarkı tutmalı herkes son anımda

Sözleri söylendikçe kalmalıyım akılda.

Ölürsem, bir gül gibi olmalı ölümüm

Dökülsem de dizelere yaprak yaprak

Sararsam da solsam da

Parça parça olsam da

Yerleşmeli kokum ruhunuzda

Aniden olmalı olursa ölümüm...

Bir damla yaş süzülmeli dost yanaklardan

Bir kuru söz söylenmeli ardımdan

Matemim, 

Bir günün sınırlarını aşmamalı

İnsanları sıkmamalı ölümüm.

Gümbür gümbür ölmeliyim, ölürsem eğer.

Gazeteler sayfalarca bahsetmeli benden

Ardımdan destanlar yazılmalı, 

Ağıtlar düzülmeli...

Bir anıt yaptırmalı ölürsem.

Bir müzisyenin son bestesi gibi ölmeliyim ya da...

Bir kaç notamı yanlış çalmalı baş kemancı

Seyirci ezgiyi hafiften mırıldanmalı

Son pasaj

Ayakta alkışlanmalı saatlerce

Perdenin indiği gibi ölmeliyim

sessizcebbb', 'Ölürsem, güzel olmalı ölümüm Sıradan, temiz, aklı başında Bir şarkı tutmalı herkes son anımda Sözleri söylendikçe kalmalıyım akılda. Ölürsem...', ARRAY['Türk Edebiyatı','Şiir','Bülent Pınarbaşı']::text[], 8.5, '{"poet":"Bülent Pınarbaşı","poet_slug":"bulent-pinarbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/olum-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlediğim', 'ozledigim-bulent-pinarbasi-lgbw6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşke diyorum kendime

Keşke dönsem çocukluk günlerime

yine öyle saf

Yine sevecen olsam

Beni leylekler getirse evime

Avunduğumu bilmesem sahte sevgilere

Her elma şekerine gelsem

büyükannem götürse akşamları döşeğime

Babam tahin helva getirse işten

Kalorifer olmasaydı acaba yuvamızda

Mısır patlatır mıydık sıcak sobamızda? 

Odun kömür yokluğunda

Sokulur muyduk birbirimize

Isınır mıydık soluğumuzda? 

Yazmıyordu insan kötülüğü

Dünyanın böyle döndüğü

Masallarımızda...', 'Keşke diyorum kendime Keşke dönsem çocukluk günlerime yine öyle saf Yine sevecen olsam Beni leylekler getirse evime Avunduğumu bilmesem saht...', ARRAY['Türk Edebiyatı','Şiir','Bülent Pınarbaşı']::text[], 8.5, '{"poet":"Bülent Pınarbaşı","poet_slug":"bulent-pinarbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozledigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir noel', 'bir-noel-bulent-pinarbasi-3a61i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu noel

Birlikte dans ederken sarmaş dolaş, 

Biliyorum ki benim değil

Bir başkasının boynuna dolanmıştı ellerin.

ama zannediyor musun ki ben seni okşuyordum, 

Zannediyor musun kollarımda sen vardın? 

Hadi; 

Dürüst olalım birbirimize

Ne ben inanırım gözlerinden süzülen yalanlara, 

Ne seni inandırabilirim sözlerime...

     İkimiz de baştan ayağa sevda

     Biz değil onlar utansın

     Üstümüze dalga dalga

     Gelen şu dünya utansın

Bu noel, 

Saçlarına öpücükler kondururken tane tane, 

Göğsüme dayadığın başına

Bir roman yazmalıyım dedim.

Gözlerine şiirler asıp

Okutmalıyım sevdaya susamış dudaklara...

bilemezdim ki o bakışların dokunduğu her dünyada

Binbir destan bıraktığını, 

Bilemezdim hülyanı...

     Sen kaybolmuş zamanların

     Suskun masal kahramanı

     Ben o masalların

     Doymak bilmeyen hayranı

Bu noel, 

Kadehimde rakı değil, ayrılık vardı.

Bu noel bence yalandı.

Biliyorum ki uyandığında

Gözlerinde sadece gecenin yorgunluğu olacak.

dudakların içkiden kurumuş

Parmakların sigaradan sararmış halde

Temizleyip yaşadıklarımızı üzerinden

Hazırlanacaksın yeni güne.

Ben yine bir dost, masum arkadaşı oynayacağım...

     Hayat yine yazacak

     Değişmez yazısını

     Dünya tekrar bulacak

     O eski rotasını.....', 'bu noel Birlikte dans ederken sarmaş dolaş,  Biliyorum ki benim değil Bir başkasının boynuna dolanmıştı ellerin. ama zannediyor musun ki ben...', ARRAY['Türk Edebiyatı','Şiir','Bülent Pınarbaşı']::text[], 8.5, '{"poet":"Bülent Pınarbaşı","poet_slug":"bulent-pinarbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-noel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Adın Sevda Olsun...', 'olum-adin-sevda-olsun-bulent-ozcan-qykk5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm adın sevda olsun, 

Sen kalleş olamazsın...

Ölüm adın canan olsun, 

Sen canım alamazsın...

Canım içre duydum seni, 

Can gözüne koydum seni, 

Sevi ile yudum seni; 

Sen canım alamazsın...

Demiyorum çek git ölüm, 

Canım içre gir yit ölüm, 

Güzel ölüm, yiğit ölüm; 

Sen canım alamazsın...

27/28 Şubat 1993, Gaziantep', 'Ölüm adın sevda olsun,  Sen kalleş olamazsın... Ölüm adın canan olsun,  Sen canım alamazsın... Canım içre duydum seni,  Can gözüne koydum se...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-adin-sevda-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Tende Güz İklimi', 'olum-tende-guz-i-klimi-bulent-ozcan-t3ndg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umut işte, gündönümü, 

Hoyrat rüzgârın ölümü...

Güle verip ben gönlümü, 

Düşünürüm geceleyin...

Geceleyin sevdalanır, 

Geceleyin umutlanır, 

Geceleyin ben uyanır, 

Düşünürüm hep ölümü...

Ölüm tende güz iklimi

Ki bir esrik şarkı gibi

Alır gider beni kimi

Güne boyarım ölümü...

           8 Nisan 1992, Gaziantep', 'Umut işte, gündönümü,  Hoyrat rüzgârın ölümü... Güle verip ben gönlümü,  Düşünürüm geceleyin... Geceleyin sevdalanır,  Geceleyin umutlanır, ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-tende-guz-iklimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye...', 'sevgiliye-zafer-adak-pjhxl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiliye...

bi kapılar bilirim yalnız

öyle böyle değil

ardına kadar açık bırakılmış

bi de bilirim ki

kilidini örümcekler sarmış...

Şimdi 

duyduğunca      

alaca gün ağartısındaki 

bu kimligini unuttuğumuz

kus seslerini, 

bir yalnızlık türküsü yaslanır

yüreğime

dumanları ki hiç tütmez olmustur 

mart ayının 

insan değil mi ki ısıinabilmek için 

gövdem gibi odunlari paralar da 

bosuna boşuna atarmiş sobalara

ama soğuk ama yine buz ayaz...

köşe başlari tutulmus sonra

sokaklarin bir ucu deniz

bir ucu çıkılmaz olmuş

gök kızıl mı kızıl

kurtlar pusuda...

SEN, SEN ki

unuttugumca beyaz

andığımca yine beyaz bir film

gibi geçiyorsun

evimin önünden

yaramaz çocuklar 

oynaşıyor bahçemde 

ve bahçemde gölgesi ağır geliyor

bu baharın                         

bu mısraların.... 

          

15.01.1998/gelibolu', 'Sevgiliye... bi kapılar bilirim yalnız öyle böyle değil ardına kadar açık bırakılmış bi de bilirim ki kilidini örümcekler sarmış... Şimdi  d...', ARRAY['Türk Edebiyatı','Şiir','Zafer Adak']::text[], 8.5, '{"poet":"Zafer Adak","poet_slug":"zafer-adak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sevgiliye-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkların...', 'asklarin-mustafa-dillioglu-6igbk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkların yarım kalmışı olmaz; 

Onların, 

Bir başlamamışları vardır

Bir bitmemişleri...', 'Aşkların yarım kalmışı olmaz;  Onların,  Bir başlamamışları vardır Bir bitmemişleri......', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dillioğlu']::text[], 8.5, '{"poet":"Mustafa Dillioğlu","poet_slug":"mustafa-dillioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asklarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak...', 'birak-mustafa-dillioglu-yjm34', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derin çek sigaranın dumanını

Sonra bırak

Beni bıraktığın gibi

Gör halimi...', 'Derin çek sigaranın dumanını Sonra bırak Beni bıraktığın gibi Gör halimi......', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dillioğlu']::text[], 8.5, '{"poet":"Mustafa Dillioğlu","poet_slug":"mustafa-dillioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/birak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin...', 'gittin-zafer-adak-2d4nz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen, 

sen ki kuytusunda gizinde 

gecenin, 

ve kavgasinda çıktın karşıma

uzak bir köy türküsüydü yüzün

alabildiğince susuz hırçın

görebildiğimce de güzel

ellerin uzandıkça kadehlere sonra

bir tatli-ben sarhoş olmuştum

artık, bi okyanus oluyordu

bi de yakamoza çalıyordu gözlerin

bi türküledin

bi de sustun o gece

bi de sabah ise GİTTİN…', 'sen,  sen ki kuytusunda gizinde  gecenin,  ve kavgasinda çıktın karşıma uzak bir köy türküsüydü yüzün alabildiğince susuz hırçın görebildiği...', ARRAY['Türk Edebiyatı','Şiir','Zafer Adak']::text[], 8.5, '{"poet":"Zafer Adak","poet_slug":"zafer-adak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gittin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ben Sen Kıldım', 'seni-ben-sen-kildim-mustafa-dillioglu-jwwpe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni ben sen kıldım

Yüreğime soktum

Şekil verdim beynimin kıvrımlarında

Seni ben yarattım

Öldüremeyişim bundan...', 'Seni ben sen kıldım Yüreğime soktum Şekil verdim beynimin kıvrımlarında Seni ben yarattım Öldüremeyişim bundan......', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dillioğlu']::text[], 8.5, '{"poet":"Mustafa Dillioğlu","poet_slug":"mustafa-dillioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-ben-sen-kildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Akşamüstlerini Hatırlatır', 'olum-aksamustlerini-hatirlatir-mustafa-dillioglu-b22sn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm, 

Akşamüstlerini hatırlatır bana

Oyunun en güzel saatlerinde, 

Alacakaranlıkta

Sokak lambaları yanar

Annem seslenirdi

Hadi eve...', 'Ölüm,  Akşamüstlerini hatırlatır bana Oyunun en güzel saatlerinde,  Alacakaranlıkta Sokak lambaları yanar Annem seslenirdi Hadi eve......', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dillioğlu']::text[], 8.5, '{"poet":"Mustafa Dillioğlu","poet_slug":"mustafa-dillioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olum-aksamustlerini-hatirlatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaklı Pera', 'yasakli-pera-fatih-soyler-96hi6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'olmayacak işler düşlüyorum	

Pera’da yürüyorum

uzansam dokunacağım bir ses

yüreğimdeki sancı, 

alnımdaki ateş

uzaklardaki hayal

tutup da bırakamadığım nefes

Pera’da yürüyorum

sinmiş duvarlara hüzünlü bir sabah kokusu

göğsümde mengeneler

ruhumda büyük yangınların sorgusu

söylemeye korkuyorum: neler yapabilirdim neler

ah! olmasaydı

suretimizin işlendiği mermerler

Pera’da yürüyorum

iki yanımda taşlaşmış zaman

yorulmuşum, umarsızım hayattan

birden bir yel esiyor

güvercinler uçuşuyor önümde

bir tokat gibi geçmişimi

hain lodos vuruyor yüzüme

bir yağmur damlası düşüyor elime: 

üşüyorum, 

dile geliyor sokaklar: 

yasaklarla yaşıyorum

olmayacak işler düşlüyorum

koluma değiyor kolun

bir yıldırım düşüyor

Pera’da ölüyorum

İstanbul, Aralık,1999', 'olmayacak işler düşlüyorum	 Pera’da yürüyorum uzansam dokunacağım bir ses yüreğimdeki sancı,  alnımdaki ateş uzaklardaki hayal tutup da bıra...', ARRAY['Türk Edebiyatı','Şiir','Fatih Söyler']::text[], 8.5, '{"poet":"Fatih Söyler","poet_slug":"fatih-soyler","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yasakli-pera-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Nokta', 'uc-nokta-i-sa-seker-m6gj1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şarkı söyledim sana, 

Aşk, gurbet, yalnızlıkla.

Hadi ama ağlasana! 

Inga, ınga, ınga.

Fıkralar anlattım gün boyunca; 

İdris, Temel, Nasreddin Hoca.

Gülmekten yıkılmadın hâlâ! 

Hah hah hah ha.

Ve bir söz ver bana, 

Ağlasan da ağlamasan da, 

Gülmekten yıkılmasan da, 

Bu şiir bitmesin burada.

Nokta, nokta ve nokta...', 'Bir şarkı söyledim sana,  Aşk, gurbet, yalnızlıkla. Hadi ama ağlasana!  Inga, ınga, ınga. Fıkralar anlattım gün boyunca;  İdris, Temel, Nasr...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uc-nokta-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşina', 'asina-mustafa-yildiz-demirci-9odqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşinayım ben sendeki arşa değen aşkıma

Rızan için beklerim dönsemde yine şaşkına

Zulmetmesin gözlerin küfretsende ruhuma

Umudumdur belki birgün tutulur sevdan SEVDAMA...', 'Aşinayım ben sendeki arşa değen aşkıma Rızan için beklerim dönsemde yine şaşkına Zulmetmesin gözlerin küfretsende ruhuma Umudumdur belki bir...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız Demirci']::text[], 8.5, '{"poet":"Mustafa Yıldız Demirci","poet_slug":"mustafa-yildiz-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber', 'haber-mustafa-yildiz-demirci-kai72', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne yardan haber var

Ne de Eylül''de bahar

.

Ne bir kapımı çalan var

Ne de günahımı alan! 

Ne de yalandanda olsa bir sevdam! 

Olmaz olsun seni sevmediğim yalan...', 'Ne yardan haber var Ne de Eylül''de bahar . Ne bir kapımı çalan var Ne de günahımı alan!  Ne de yalandanda olsa bir sevdam!  Olmaz olsun seni...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız Demirci']::text[], 8.5, '{"poet":"Mustafa Yıldız Demirci","poet_slug":"mustafa-yildiz-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/haber-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varım Seninle', 'varim-seninle-deniz-yazici-ixtkw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıkar ya sisler

Kimi yağmur üşütür, titretir.kiminde mutluluk dansı yaparsın ya, ıslanırken.

Unutma arkadaşım 

Güneşte yağan yağmurda gökkuşağı çıkacaktır.

Eğer gökkuşağında gördüğün her renkle gözlerin parlıyorsa, 

Gözlerine bakanlar görmek istedikleri tüm renkleri buluyorlarsa.

Boran, fırtına güneş kadar sıcaklık verebiliyorsa bedenine, 

Sen diğerleriyle ve diğerleri de seninle huzurluysa.

Bu hayatta nefes alabilmeye varım seninle.', 'Sıkar ya sisler Kimi yağmur üşütür, titretir.kiminde mutluluk dansı yaparsın ya, ıslanırken. Unutma arkadaşım  Güneşte yağan yağmurda gökkuş...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yazıcı']::text[], 8.5, '{"poet":"Deniz Yazıcı","poet_slug":"deniz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/varim-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-deniz-yazici-huwef', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günler güzel ve geceler ne kadar karanlık olursa olsun.

Her sabaha güneş doğduğuna göre, 

Her gece aydede muhakkak olacaktır.

Bazen bulutların ardında, 

Bazen ışıl ışıl parlak gökmavide...

Bazen denizler dalgalanıp taşsa da, 

Senin dediğin gibi arkadaşım: 

Mutlaka arada sırada sütliman olacaktır.

Kimi gün içini aydınlatır güneş

Kiminde nefesin kadar ruhunu da.', 'Günler güzel ve geceler ne kadar karanlık olursa olsun. Her sabaha güneş doğduğuna göre,  Her gece aydede muhakkak olacaktır. Bazen bulutlar...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yazıcı']::text[], 8.5, '{"poet":"Deniz Yazıcı","poet_slug":"deniz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bazen-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma...', 'kizima-deniz-yazici-ejghv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzel  kızıma 

Günlerin  bahar  meltemleri  gibi 

Ilık  ılık  essin  dilerim.

Günlerinin  rüzgarları  ne  yaksın  kavursun  seni, 

Ne de soğusun  üşütsün.

Günlerin gül demeti

Geleceğin güllerine can veren yağmurun olsun.

Dimağın hep açık olsun.

İyiyide, kötüyüde bilsin.

Ama seçimin hep doğru olsun.

Acılar inciltmesin canını, 

Asıl doğruların kavurmasında içini, 

Çünkü bazen şelaleler doyurmaz bilesin susuzluğunu.

Yaşadıkça hep mutlu olasın.

Ama amacın sade mutluluk olmasın, 

Kendi düzenini kurarken acılarıda göreceksin

Buna temkinli olasın, 

Seni silksin ama devirmesin.

Bunları söylediğime kızma 

Ömür toz pembe değil...

Silkmeler seni yıkmasın açsın gözünü 

Hayata dipdiri bakasın

Gözlerindeki umut ışığı, pırıl pırıl bakışların hiç sönmesin.

Varlığından hep huzur duyasın

Pişmanlıkların ateşe düşen kar taneleri gibi olsun erisin kaybolsun.

Mutluluğun canın gibi tatlı hep sağ ve dimdik olsun

Hiçbir kuvvet bükmesin bileğini, 

Gözlerindeki parıltıyla yak kavur doğru olmayan her şeyi

Gözlerindeki umut ışığın güneş doğursun insanların yüreğine.

Amaçların verimli ağaçlar gibi bol meyveli olsun

Hiçbir meyveni çürütme 

Ömrünce olgunlaştırıp ye

Hep bir çaban olsun 

Tüm insanlar için önder ol 

Hayatta kalıcı birşeyler bırak

Eğer yetiştiremem dediğin umuduna zamanın yetmeyeceğine inanırsan 

Nesline emanet et

Neslini çoğalt senden dileğim.

Benim en verimli ürünüm sensin

Aldığım bir nefesse bu dünyadan bana kalan 

Al senin olsun

Sen Allahın bana bahşettiği en güzel lütufsun.

Sen Yaradandan yana bana en büyük umudumsun.

Herzaman bizden bir adım öne geçebilesin.

Canımdan bir parçasın 

Dilediğince, ömrünce, gönlünce yaşayasın 

Canından bir canın seninde olsun

Onun gururu seni ömrünce güldürsün, 

Annem canım.', 'Güzel  kızıma  Günlerin  bahar  meltemleri  gibi  Ilık  ılık  essin  dilerim. Günlerinin  rüzgarları  ne  yaksın  kavursun  seni,  Ne de soğ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yazıcı']::text[], 8.5, '{"poet":"Deniz Yazıcı","poet_slug":"deniz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kizima-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zor...', 'zor-deniz-yazici-di0x4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben benimle olan mücadelemi bitirebilseydim eğer.

Bitirsem ne farkeder ki 

Hiçbirşey çözüme ulaşmıyor ki.

Kolay mı sanıyorsun.

Saatler dolmaz, günler geçmez mi sanıyorsun.

Hiç güneş sönmez, akşamlar olmaz mı sanıyorsun.

Hiçbir şey eskisi gibi olmaz mı? 

Acıyor içim acıyor.

Zor öyle zor ki. 

Sen, ben, biz, onlar, diğerleri ve diğerleri.....

Acımasız bir dünya bu.hem de çok acımasız.

Ne ben benim diyebilirim, ne sen benimsin.

Söylenecek tek şey zor dostum zor.', 'Ben benimle olan mücadelemi bitirebilseydim eğer. Bitirsem ne farkeder ki  Hiçbirşey çözüme ulaşmıyor ki. Kolay mı sanıyorsun. Saatler dolma...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yazıcı']::text[], 8.5, '{"poet":"Deniz Yazıcı","poet_slug":"deniz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-faik-kivanc-3y1yn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorum, 

Biliyorum birazdan çıkıp gelecek

Gelmese bile telefon edecek

Yok yok 

Telefonla olmaz 

Gelecek, mutlaka gelecek.

''Onu beklediğimi rüzgarın esmesinden bilir, 

Fazla değil, 

On dakika geçmeden gelir...''

Diye diye 

Haftaları kopardım takvimlerden, 

İpekböceğim

Yoksa duymuyor musun sesimi? 

Ellerimi rügara verdim

Hissedebiliyor musun saçlarının arasında? 

Gözlerin hala bir çift yıldız mı gökkubbede? 

Her mehtaplı gecede, 

Kadife yumuşaklığında ışık mı tenin? 

Bir bilsen yalnızlığını şu bedenin, 

Göğü yırtar, 

Bulutlardan vazgeçer, 

Bir gökkuşağı üzerinden, 

Sorgusuz, sualsiz, 

Ve sessiz ve derinden, 

Yıldızları edip yerinden, 

Toprağa karışıp hanımeli''nin köklerinden, 

Süzülüp bana gelirdin! ...

11.TEMMUZ.2001', 'Biliyorum,  Biliyorum birazdan çıkıp gelecek Gelmese bile telefon edecek Yok yok  Telefonla olmaz  Gelecek, mutlaka gelecek. ''Onu beklediğim...', ARRAY['Türk Edebiyatı','Şiir','Faik Kıvanç']::text[], 8.5, '{"poet":"Faik Kıvanç","poet_slug":"faik-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seslenis-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostları İyi Seçebilmeli', 'dostlari-i-yi-secebilmeli-nurullah-aydin-1sxx0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostları İyi Seçebilmeli

Dostlarımız olmalı

Düştüğümüzde kolumuzdan tutabilmeli

Bizimle tünele birlikte girebilmeli 

Sonunda ne olacağını hiç düşünmeden

Dostlarımız olmalı

O''nun için herşeyi göze alabilmeli

Ve hep yüzüne gülümseyebilmeli

Yalansızca, menfaat beklemeden

Dostlarımız olmalı

Tıpkı yıldızlar gibi ışık tutmalı karanlığımıza

Yönümüzü yitirdiğimizde kılavuz olmalı

Ellerimizden tutmalı karşılıksızca

Dostlarımız olmamalı

Bir anda sinirlenip yüzümüze haykıran

Anlaşılmaz bir hal alıp kalp kırabilen

Değersizce dokunmamalı gözleri gözlerimize

Dostlarımız olmamalı

Sadece kendini düşünebilen

Her sözcükte kendini haklı gösterebilen

Vefasız olmamalı düşler gibi....

Nurullah AYDIN- 02.08.2001', 'Dostları İyi Seçebilmeli Dostlarımız olmalı Düştüğümüzde kolumuzdan tutabilmeli Bizimle tünele birlikte girebilmeli  Sonunda ne olacağını hi...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dostlari-iyi-secebilmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-faruk-nafiz-camlibel-zbqfi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gençliğim ardında sürünsün

Aşkına ihanet edersem eğer.

En kalpsiz cellatlar boynu
..........
..........', 'Gençliğim ardında sürünsün Aşkına ihanet edersem eğer. En kalpsiz cellatlar boynu .......... .............', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sana-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-nurullah-aydin-khnpj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki; 

Umutlarım Kaf dağının ardında gizli

Belki de, 

Sevgiyi yaşayamadım inceden inceye

Ya da, 

Yanlış anlaşıldım attığım her adımda

Bir gölge düşürdü gece gönlüme apansızca

Kapadım mı yoksa sevda kapılarımı zamansızca

Anlatamıyorum bir türlü kendimi

Ya duyuluyorum gecelerde

Ya da kahroluyorum yıldızların eşiğinde....

02/08/01', 'Belki;  Umutlarım Kaf dağının ardında gizli Belki de,  Sevgiyi yaşayamadım inceden inceye Ya da,  Yanlış anlaşıldım attığım her adımda Bir g...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/belki-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Rağmen', 'herseye-ragmen-erkan-horoz-j2pby', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '...sahipsiz bir dünyanın çocuğuyum, 

zincirlerini kırmış, duygularını atmış... 

bir dileği vardı belkilerle, 

olmayacağını bile bile, 

kedere yönelikti sanki hayat, 

bahtının kör gözlerine... 

bazen yorulurdu, yenik düşerdi uçsuz duygulara, 

kendini becerircesine bağırırdı, 

bu ruhsuz dünyanın kalbine... 

hatta sonra ağlardı, kalbini yıkan meleğe... 

... 

...sahipsiz bir dünyanın çocuğuyum, 

denizlerse göz yaşım, dağlarsa duygularım... 

yanardağ kör gözlerimin ateşi... 

yıldızlarsa anılara ışık tutan, 

asılı fenerler gibi duruyor yüreğimde... 

herşeye ve herşeye rağmen gözlerimde... 

... 

...(12.03.2001)', '...sahipsiz bir dünyanın çocuğuyum,  zincirlerini kırmış, duygularını atmış...  bir dileği vardı belkilerle,  olmayacağını bile bile,  keder...', ARRAY['Türk Edebiyatı','Şiir','Erkan Horoz']::text[], 8.5, '{"poet":"Erkan Horoz","poet_slug":"erkan-horoz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/herseye-ragmen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Git', 'cek-git-faik-kivanc-p1lft', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çek git güneş

Çek git tepemden...

Saatlerdir sabrımı yoklamaktasın.

Sen yetmezmişsin gibi, 

Kurşun gibi bir haber aldım, 

Kafam darmadağın.

Çek git güneş sınırları zorlamaktasın...

Neymiş efendim? ! 

Bizimkisi ''gelemiyormuş! ! ! ''

İyi halt ediyormuş! ...

11.TEMMUZ.2001', 'Çek git güneş Çek git tepemden... Saatlerdir sabrımı yoklamaktasın. Sen yetmezmişsin gibi,  Kurşun gibi bir haber aldım,  Kafam darmadağın. ...', ARRAY['Türk Edebiyatı','Şiir','Faik Kıvanç']::text[], 8.5, '{"poet":"Faik Kıvanç","poet_slug":"faik-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cek-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli', 'deli-faik-kivanc-680k9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittin gideli, 

çareler arıyor gözlerim dağların ötesinde

bir bekleyiş ki; tükenmiyor, öldüresiye...

ne zormuş; 

yeni filizlenmiş dallarda sonbahar hüznü, 

ve yağmur sıkıntısında bunalmış gökyüzü.

yağmuru beklemek ne zormuş...

aynada tanımadığım bir yabancı, 

açmadan kuruyan güllerdeki sancı, 

ağrısı dinmeyen özlem, 

anlamsız gözlerde nem ne zormuş...

her çiçekte gözlerini aramak

ama senin gibi güleni bulamamak...

nafile arayış ne zormuş, 

bilmezdim...

öğrendim, öğrendim artık.

öğrendim ki hasretindir dayanılmaz, 

ve sokulur yatağıma gizli gizli, uykusuz bir karanlık...

öğrendim ki, gittin gideli, 

ancak vuslattır bu ayrılığın bedeli, 

ve damarlarımda başıboş bir deli, 

dolaşır durur...

savaşır durur...

08.TEMMUZ.2001', 'Gittin gideli,  çareler arıyor gözlerim dağların ötesinde bir bekleyiş ki; tükenmiyor, öldüresiye... ne zormuş;  yeni filizlenmiş dallarda s...', ARRAY['Türk Edebiyatı','Şiir','Faik Kıvanç']::text[], 8.5, '{"poet":"Faik Kıvanç","poet_slug":"faik-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-faik-kivanc-9w1k0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yine olmadı! 

ıslatamadı bile susuzluğumu.

düşüme birkaç yağmur tanesi düştü.

zaten sensiz, 

düşen yağmur taneleri / yağmurun yağması bile

bir düştü...

düşen üç yağmur tanesi değildi.

düşen iki serçenin gözyaşı...

vay be! 

seninle serçelerin ağlaması bile 

gülüştü...

12.TEMMUZ.2001', 'yine olmadı!  ıslatamadı bile susuzluğumu. düşüme birkaç yağmur tanesi düştü. zaten sensiz,  düşen yağmur taneleri / yağmurun yağması bile b...', ARRAY['Türk Edebiyatı','Şiir','Faik Kıvanç']::text[], 8.5, '{"poet":"Faik Kıvanç","poet_slug":"faik-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dus-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Bakışlar', 'gizli-bakislar-faruk-nafiz-camlibel-ah8xg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bakışki açıyor gönül muammasını, 

İki sevdalı kalbin en gizli yarasını, 

Bir bakış ki kudreti hi
..........
..........', 'Bir bakışki açıyor gönül muammasını,  İki sevdalı kalbin en gizli yarasını,  Bir bakış ki kudreti hi .......... .............', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gizli-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''nun Hikayesi', 'o-nun-hikayesi-faik-kivanc-f3qv3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'o, ölümden korkmazdı

yaşı da gençti

ama ölümden korkmazdı işte.

bir ömre çok bulurdu yimibir seneyi

''yirmibir'' derdi, ''çok fazla''

bir el uzanmalı gaipten, 

ansızın çekmeli 

ayaklarının altındaki yirmi santimlik iskemleyi...

''yirmi santim'' derdi, 

''yeter yitirmeye yirmi seneyi''...

''kaybedecek birşeyim yok'' derdi

dünyada adımdan başka.

varsın bir imge de eksik olsun, 

mavi renkli bir imge.

nasıl olsa dünya gökkuşağı renginde...

dünyanın rengarenk olduğunu düşünürdü

ve her rengin de aslında siyah.

beyaz, siyahın gözleri kör haliydi, 

aydınlık, karanlığın kendini saklaması, 

kalabalıklar; 

kalabalıklar, yalnızlıkların biraraya toplanması...

sahte renkler, 

sahte ışıklar, 

sahte beraberlikler, 

sahte dünya...

sahte bulurdu dünyayı, 

bulmak içinde çaba sarfetmemişti zaten...

''şehirler''

insanların kaçışı kendilerinden.

yaşamalar göçebe, 

iğreti

sefil

rezilce...

benliklerdeki saflıktan, 

gözü kapalı bir kaçışvardı sadece...

''erdem'' derdi

hırs balyozuyla tek darbede yıkık...

o şehirde yıkık bir ev vardı, 

içnde susturamadığı bir davet...

parmakuçlarıyla tutardı hayatı.

''bir ipekböceği'' derdi

''sarmalı'' derdiparmaklarımı

''sarmalı, bırakmamak için tutanaklarımı...''

o ölümden korkmazdı.

yaşı henüz yirmibirdi.

ama ölümden korkmazdı işte...

bir ömre çok bulurdu yirmibir seneyi.

''yirmibir'' derdi, 

''çok uzun'' derdi, 

''yaşamak için bunca derdi...''

şimdi ise, 

bir ipekböceği var onunda...

değil parmaklarını, 

tüm bedenini sardı hayata.

cennete döndü, dünya denen bataklık, 

onun da bir ipekböceği var artık...

13.TEMMUZ.2001', 'o, ölümden korkmazdı yaşı da gençti ama ölümden korkmazdı işte. bir ömre çok bulurdu yimibir seneyi ''yirmibir'' derdi, ''çok fazla'' bir el uza...', ARRAY['Türk Edebiyatı','Şiir','Faik Kıvanç']::text[], 8.5, '{"poet":"Faik Kıvanç","poet_slug":"faik-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/o-nun-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum', 'unuttum-cevat-kara-5sftw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalga dalga uzun saçların

Rüzgar ile kırışırdı alnın

Düşerdi de alnına perçem perçem

Tebessümün gülüşün

Saçların ne renkti, unuttum.

Tebessümlerin sarardı içimi

Kahkahalarda neşe, denizde sen

Güneş yakardı da tenini sıcaktan

İşve ile göz eder, sevgi arardın

Bu kadar güzelmiydin, unuttum.

Diz dize oturur

Hayaller kurardık gelecekten

Güzel bir ev göl kıyısında

Çocuklar...tabiat...sevgi derdin

Hayalperestmiy din, unuttum.

Elime bir kalem geçse

Hece hece adını yazar

Sevgi arardım

Yazmaz olunca kalem yıllarca

İsmin neydi, unuttum.', 'Dalga dalga uzun saçların Rüzgar ile kırışırdı alnın Düşerdi de alnına perçem perçem Tebessümün gülüşün Saçların ne renkti, unuttum. Tebessü...', ARRAY['Türk Edebiyatı','Şiir','Cevat Kara']::text[], 8.5, '{"poet":"Cevat Kara","poet_slug":"cevat-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unuttum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine', 'yine-veysel-tanriverdi-75rg2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yöne baktım

Üç duvar

Işıklar titrek

Işıklar garip

Nisan damlaları eşikte.

Sarılan

Aynacı birikintisi

Güneşi doğurdu yaşlı gece.

Saçların kördüğüm.

Mum salınır

Mil yürür

Bir sigara; 

İkli parmak

Bir

Dudak arası.

Yine aydınlanıyor

Gönüller karası.', 'Bir yöne baktım Üç duvar Işıklar titrek Işıklar garip Nisan damlaları eşikte. Sarılan Aynacı birikintisi Güneşi doğurdu yaşlı gece. Saçların...', ARRAY['Türk Edebiyatı','Şiir','Veysel Tanrıverdi']::text[], 8.5, '{"poet":"Veysel Tanrıverdi","poet_slug":"veysel-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yine-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-veysel-tanriverdi-sdok6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''''Günaydın''''

Cimri bakkal.

''''Merhaba''''

Çirkin kız, 

Hem de iki kere.

''''Sağolasın''''

Geç kalan dolmuş

''''Buyur otur''''

Gençliğim.

''''Eyvallah''''

Kalemim.

Hani, sen böyle yazmazdın.

''''Aferin''''

Mürekkep

Sen sen olalı

İçine böyle ''''sevgiler'''' almazdın.', '''''Günaydın'''' Cimri bakkal. ''''Merhaba'''' Çirkin kız,  Hem de iki kere. ''''Sağolasın'''' Geç kalan dolmuş ''''Buyur otur'''' Gençliğim. ''''Eyvallah'''' K...', ARRAY['Türk Edebiyatı','Şiir','Veysel Tanrıverdi']::text[], 8.5, '{"poet":"Veysel Tanrıverdi","poet_slug":"veysel-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunaydin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devir', 'devir-veysel-tanriverdi-5oebx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir devir

Sonsuz sızı.

Kutsanmış

Kılıcın ucundaki

Öteden.

Gözler cümbüş

Körebe yaşam.

Çırpınma tarih, 

Uslanmaz

İçimdeki çocuk.

Yerinde hafif

Hint kumaşı.

Gitmediğim çarşılardan

Bahar terli kızlar.

Kazan içindeki düşlerim

Yüreğin yeditepe

Bilmiyorum hangisinde

Sağır gözüm

Kör yüreğim.', 'Bir devir Sonsuz sızı. Kutsanmış Kılıcın ucundaki Öteden. Gözler cümbüş Körebe yaşam. Çırpınma tarih,  Uslanmaz İçimdeki çocuk. Yerinde hafi...', ARRAY['Türk Edebiyatı','Şiir','Veysel Tanrıverdi']::text[], 8.5, '{"poet":"Veysel Tanrıverdi","poet_slug":"veysel-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/devir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece', 'bu-gece-veysel-tanriverdi-53bt4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yokluğunla söyleştim

Bu gece.

Duvarlar bakıştı

Sudan korktum bu gece

Sokaklar gezdi içimde

Kimsesiz.

Çocuksuz bilyeler vardı

Avuçlarımı gördüm

Okul yolunda.

Aç bir it gibi büzüldüm

Üşüdüm bu gece.

Yere bakarak sevmiştim seni

Sigaraya alıştığım

Küçüğümün elini öptüğüm

Hani

Şu, en sevdiğim yıllardı

Üçyüz doksan iki gün boyunca

Saplandığım bir deyim vardı.

Söyleyemediğim.

Hep, onu söyledim içimden

Sanki dua gibi

Hani sevenler söylerdi ya...

O''nunla eyleştim bu gece.', 'Yokluğunla söyleştim Bu gece. Duvarlar bakıştı Sudan korktum bu gece Sokaklar gezdi içimde Kimsesiz. Çocuksuz bilyeler vardı Avuçlarımı görd...', ARRAY['Türk Edebiyatı','Şiir','Veysel Tanrıverdi']::text[], 8.5, '{"poet":"Veysel Tanrıverdi","poet_slug":"veysel-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bu-gece-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşım', 'arkadasim-nurullah-aydin-85fnr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzünlü gözleriyle dalmış uzaklara 

Kimbilir neler geçiyor fikrinden 

Farketsin istiyorum mutluluğun yolunu 

İnadına hüzne katıyor kendini 

Bir gülüşü var ömür katıyor insana 

Sohbeti desen tatlı dilli, konuşmaya doyamazsın 

Azıcık da kurtulsa düşüncelerinden 

Sarmalara kıyamazsın..... 

-02.08.2001', 'Hüzünlü gözleriyle dalmış uzaklara  Kimbilir neler geçiyor fikrinden  Farketsin istiyorum mutluluğun yolunu  İnadına hüzne katıyor kendini  ...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/arkadasim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demedim mi?', 'demedim-mi-mustafa-kadem-erkan-jl9a0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yar benden gözlerini ayırma demedim mi? 

Gözlerine bakmadan duramam demedim mi? 

Seni görmeden olmaz, saatlerim tükenmez, 

Gözlerini görmeden yapamam demedim mi? 

Elimden ellerini bırakma demedim mi? 

Üşür kurur ellerim sıkı tut demedim mi? 

Bir annenin şefkatli, sıcak hisleri gibi, 

Sen bana dokununca, coşarım demedim mi? 

Güzel gözlüm düşümden, hiç çıkma demedim mi? 

Sen olmayan bir gece, uyunmaz demedim mi? 

Bırakıp ayrılsan da, sabah güneş doğarken, 

Yinede düşlerimde gel bana demedim mi? 

Seni ben ömür boyu, beklerim demedim mi? 

Yıllarca gelmesen de,  unutmam demedim mi? 

Sana olan sevdamı, arama bulamazsın, 

Benim sevdam sınırsız, tükenmez demedim mi? 

..Evet dedim, her şeyi söyledim, ama sen ne kadarını anlayabildin keşke bilebilseydim... keşke...', 'Yar benden gözlerini ayırma demedim mi?  Gözlerine bakmadan duramam demedim mi?  Seni görmeden olmaz, saatlerim tükenmez,  Gözlerini görmede...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kadem Erkan']::text[], 8.5, '{"poet":"Mustafa Kadem Erkan","poet_slug":"mustafa-kadem-erkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/demedim-mi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarim', 'yarim-fidan-aykut-zdhsc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarim, diğer yarım, 

Ne yapsam yarımım sensiz.

Gülsem yarım, ağlasam yarımım, 

Sussam yarım, söylesem yarımım sensiz.

Gözyaşlarım yarım, tebessümüm yarım, 

Hayallerim yarım, umutlarım yarım sensiz.

Şarkılarım yarım, mısralarım yarım, 

Yalnızlığım yarım, sessizliğim bile yarım sensiz.

Yarim, diğer yarım, 

Ne yapsam yarımım sensiz...

7.7.2001-19: 50/ Mersin

Fidan AYKUT', 'Yarim, diğer yarım,  Ne yapsam yarımım sensiz. Gülsem yarım, ağlasam yarımım,  Sussam yarım, söylesem yarımım sensiz. Gözyaşlarım yarım, teb...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yarim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Günden Beri', 'i-lk-gunden-beri-fidan-aykut-2wms0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum kaç gün, ay ya da yıl sonra çıkacaksın karşıma, 

Ne zaman bakacağım gözlerinin derinine, 

Sığınacağım bir liman gibi kollarına.

Yalnız bilki ben seni bilmezden beri varsın hayatımda...

Sevgiyi ilk kez tanımlamaya çalıştığım günden beri, 

Yıllar önce yokluğundan dolayı gözyaşı dökmeye başladığımdan beri, 

Varlığına hasret, dalgalara her kumsalda seni aratmaya başladığımdan beri, 

Issızlığımı kucaklayan her rüzgarı, seni bulması için gönderdiğim günden beri.

Aslında öylesi uzun zamandan beri varsın ki hayatımda, 

Yokluğunu hissettiğim ilk günden beri.....

1.7.2001-20.10/ Mersin

Fidan AYKUT', 'Bilmiyorum kaç gün, ay ya da yıl sonra çıkacaksın karşıma,  Ne zaman bakacağım gözlerinin derinine,  Sığınacağım bir liman gibi kollarına. Y...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilk-gunden-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dosta Söz Verdim', 'bir-dosta-soz-verdim-fidan-aykut-qxvbq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dosta söz verdim; 

Artık hüznü yazmayacağım.

Mısralarıma acıyı koymayacağım, 

Yüreğime yalnızlığı almayacağım, 

Işıl ışıl gözlerimi bir an bile buğulandırmayacağım.

O sözünde durduğu sürece ben hep sözünde duracağım......

30.6.2001-15: 30/Mersin', 'Bir dosta söz verdim;  Artık hüznü yazmayacağım. Mısralarıma acıyı koymayacağım,  Yüreğime yalnızlığı almayacağım,  Işıl ışıl gözlerimi bir ...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-dosta-soz-verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Nedir', 'ask-nedir-ahmet-metin-ktmx0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk nedir diye sorarlardı

Cevabım ‘’saçma’’ olurdu onlara

Merak ediyorum şimdi sorsalar bana

Ve desem ki; 

.......................................

Derler ki bana ‘’ne oldu sana’’

Seni bir görseler, bir tanıslar

İnan hak verirler bana.

Serap görmek çöl ortasında kalmış insana ait

Ancak, ben hayat çölünde bir Serab gördüm ki

O benim kalbime ait

Kimse gelip artık sökemez onu

O benim gönlüme ait sevda yolu

Herkes bir yol tutmuş gidiyormuş hayatta

Ama ben, yaşıyormuşum bir boşlukta.', 'Aşk nedir diye sorarlardı Cevabım ‘’saçma’’ olurdu onlara Merak ediyorum şimdi sorsalar bana Ve desem ki;  ....................................', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metin']::text[], 8.5, '{"poet":"Ahmet Metin","poet_slug":"ahmet-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-nedir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor. Sor Da Birazda Sen Ağla', 'sor-sor-da-birazda-sen-agla-ahmet-metin-6pydo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün beni dinleyecek bir insan için

Neler vermezdim

Neler vermedim ki bugün için.

Gel bana sor.

Sor.Sor da birazda sen ağla

Ağla ama üzülme.

Beni kim anlar diye düşündüğümde

İlk aklıma gelen sendin.

Nedenini gel bana sor.

Sor. Sor da birazda sen ağla

Ağla ama üzülme.

Beni düşündüren tek bir şey

Seni kendime çook yakın bulmam.

Ölümün insana yakınlığı gibi.

Sebebini gel bana sor.

Sor. Sor da birazda sen ağla

Ağla ama üzülme.', 'Bugün beni dinleyecek bir insan için Neler vermezdim Neler vermedim ki bugün için. Gel bana sor. Sor.Sor da birazda sen ağla Ağla ama üzülme...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metin']::text[], 8.5, '{"poet":"Ahmet Metin","poet_slug":"ahmet-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sor-sor-da-birazda-sen-agla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O gözler O Gözler', 'o-gozler-o-gozler-ahmet-metin-kfjjs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim açık hayale daldım

Karşımda duran tıpkı sensin

Bana bağıran sanki senin sesin

Bana uzanan eller inan ki senin

Ve emin olduğum bir şey var ki

O gözler, O gözler.

Yemin ederim senin.

Ne olur elleme hayalin dursun yanımda

O güzel sesin çınlasın kulağımda

Uzatmaya çalıştığın, uzatamadığın

Bakmaya doyamadığım, kıyamadığım

O gözler O gözler

Yemin ederim ki senin', 'Gözlerim açık hayale daldım Karşımda duran tıpkı sensin Bana bağıran sanki senin sesin Bana uzanan eller inan ki senin Ve emin olduğum bir ş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metin']::text[], 8.5, '{"poet":"Ahmet Metin","poet_slug":"ahmet-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/o-gozler-o-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Geldin?', 'niye-geldin-ozlem-malkara-lr1rm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yürümek istedim seninle 

hiç bilmediğimiz bir yerde

yürüyemedik...

yarı yolda kaldım bir başıma 

geriye döndüm, 

ne sen vardın, ne izin 

ne senden bir parça, ne yelin...

üzüldüm belki bir parça 

yo.. yo....bayağıca...

ne sen bildin ne de başkası

sadece ben içtim yalnızlığı 

yudum yudum kadeh kadeh...

günler, aylar hatta yıllar boyu

bir gün çıkageldin! 

dikildin karşıma...

hiçbir şey olmamış gibi

ben şişelerce yalnızlığı devirmemiş gibi

için için güldüm sana 

ne sen gördün ne de bir başkası

kimbilir ya da ağladım senin için 

kendime bile itiraf edemeden 

sessiz, öylesine.. yalnız yapayalnız...

ne değişti sen çıkagelince

geçen zamanı geri getirip avuçlarıma boca edebildin mi? 

''hadi yeniden yine başla'' diyebildin mi? 

yoo..diyemedin ki, 

öyleyse söyle ''NİYE GELDİN? ''', 'yürümek istedim seninle  hiç bilmediğimiz bir yerde yürüyemedik... yarı yolda kaldım bir başıma  geriye döndüm,  ne sen vardın, ne izin  ne ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Malkara']::text[], 8.5, '{"poet":"Özlem Malkara","poet_slug":"ozlem-malkara","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/niye-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına...', 'firtina-ozlem-malkara-txy38', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uzakları yakın kıldım 

hayalleri gerçek...

düşmanları dost

dikenleri çiçek...

bir el uzattım boşluğa

bilinmez yollara vurdum kendimi

bir el uzandı yokluktan varlığa

bir düş görüyorum derken

gerçeğin içinde buldum kendimi

taa derinlerde bir yerde 

fırtına koptu sanki

çok derindeydi yüreğim duyulmaz oldu sesi...', 'uzakları yakın kıldım  hayalleri gerçek... düşmanları dost dikenleri çiçek... bir el uzattım boşluğa bilinmez yollara vurdum kendimi bir el ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Malkara']::text[], 8.5, '{"poet":"Özlem Malkara","poet_slug":"ozlem-malkara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/firtina-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kürek', 'kurek-ozlem-malkara-vp6l8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kürek var elimde

üstüme üstüme akan bir nehirde

çekiyorum küreğimi...

hiçbir ümit kırıntısı kalmasa da içimde

çekiyorum küreğimi...

kıyıya çıkamayacağımı bilsem bile

akıntıya karşı, hayata karşı 

çekiyorum küreğimi...

     ...

bir vazgeçiş yolumdan geri döndürebilir beni

bir anda herşeyi bitirebilirim

ya da bir şey için herşeyimi verebilirim! 

sıpıtıp atabilirim küreğimi

akıntıya boyun eğerek...

ya da serin sulara atlayıp vargücümle yüzebilirim

kulaç atmaktan yorgun düşersem pes edebilirim

ama ne olursa olsun deneyebilirim...

deneyebilirim; 

tek YÜREKTE tek KÜREKLE nehri geçmeyi..', 'bir kürek var elimde üstüme üstüme akan bir nehirde çekiyorum küreğimi... hiçbir ümit kırıntısı kalmasa da içimde çekiyorum küreğimi... kıyı...', ARRAY['Türk Edebiyatı','Şiir','Özlem Malkara']::text[], 8.5, '{"poet":"Özlem Malkara","poet_slug":"ozlem-malkara","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal... Gidiyorum!', 'hoscakal-gidiyorum-ozlem-malkara-06ylt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kumsala ayak izlerimi

dalgalara saçımın tellerini bırakıyorum

hoşçakal... gidiyorum..

cebimde kırık bir midye

genzimde yosun kokusu

gözlerim nemli 

saçlarım tuzlu..

hoşçakal...gidiyorum..

teknemi açıklara 

yüreğimi sana demirledim

ağlarım rıhtımda

alkım sende kaldı

ancak 

hoşçakal...gidiyorum..', 'kumsala ayak izlerimi dalgalara saçımın tellerini bırakıyorum hoşçakal... gidiyorum.. cebimde kırık bir midye genzimde yosun kokusu gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Özlem Malkara']::text[], 8.5, '{"poet":"Özlem Malkara","poet_slug":"ozlem-malkara","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hoscakal-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Sonrası', 'yagmur-sonrasi-ozlem-malkara-kxqv2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yağmur sonrası sessizliğine bürünmüşken şehir

gözyaşlarına boğulmak gelir içimden...

esip giden rüzgardan ne kalmışsa geride 

yok bir fark şu meçhul sevgilerde...

bir kasırga olup döndürseydin başımı

hiç unutmayacaktım yüzünün hatlarını...

bir yağmur olup yağsaydın üstüme

kimse çizgi çekemeyecekti zihnimdeki silüetine..

bir alev olup tutuşsaydın bağrımda

ırmaklara atsam da sönemeyecektim sabaha...

oysa şimdi ne kaldı geride...

yağmur sonrası sessizliğine bürünmüş şehirden

benden gayrı...', 'yağmur sonrası sessizliğine bürünmüşken şehir gözyaşlarına boğulmak gelir içimden... esip giden rüzgardan ne kalmışsa geride  yok bir fark ş...', ARRAY['Türk Edebiyatı','Şiir','Özlem Malkara']::text[], 8.5, '{"poet":"Özlem Malkara","poet_slug":"ozlem-malkara","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yagmur-sonrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Pınarsın İçilen Ama Hiç Kanılmayan', 'bir-pinarsin-i-cilen-ama-hic-kanilmayan-umit-yasar-oguzcan-5nsv9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir pınarsın içilen ama hiç kanılmayan

Seveni yanıltmayan, sevince yanılmayan

Özlenen sen, özleyen sen, özleten sen

Varken doyulmayansın, yokken dayanılmayan', 'Bir pınarsın içilen ama hiç kanılmayan Seveni yanıltmayan, sevince yanılmayan Özlenen sen, özleyen sen, özleten sen Varken doyulmayansın, yo...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-pinarsin-icilen-ama-hic-kanilmayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizi İzlerken', 'denizi-i-zlerken-erdenay-arikan-a4lex', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıyıdan uzaktaki umudu görüyorum

Keşke yüzücü olsam diyorum, 

Derinde bir denıiyıldızı seçiliyor

Keşke dalgıç olsam diyorum, 

Liman buram buram deniz kokuyor

Keşke denizci olsam diyorum, 

Mavilik gözlerimi alıyor benden

Keşke ressam olsam diyorum, 

Saçlarımı okşayan dalga sesleri duyuluyor

Keşke müzisyen olsam diyorum, 

Yakamozlarda mutluluk ateşi seziyorum

Keşke şair olsam diyorum, 

Gözlerimde çiseleyen yağmur, ufka daliyorum

Keşke aşık olsam...', 'Kıyıdan uzaktaki umudu görüyorum Keşke yüzücü olsam diyorum,  Derinde bir denıiyıldızı seçiliyor Keşke dalgıç olsam diyorum,  Liman buram bu...', ARRAY['Türk Edebiyatı','Şiir','Erdenay Arıkan']::text[], 8.5, '{"poet":"Erdenay Arıkan","poet_slug":"erdenay-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/denizi-izlerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'K.', 'k-ahmet-altan-cvvdp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sabah bir baska Joseph K.''nin resimleri var gazetelerde. 

Satonun bulundugu tepenin eteklerindeki küçük köyde yasiyoruz, 

iktidarin asil sahipleri asla gözükmüyor, her sabah kapimizin altindan bir suçlunun resmi atiliyor ve onlarin suçlu olduguna, suçlu olduklari söylendigi için inaniyoruz. Evlerimizden suçluyu parçalamak için çikiyoruz, birbirimize ''Suçluymus'' diyoruz, suçlunun öldürülmesini istiyoruz, efendilerimize suçlunun öldürülmesi için yalvariyoruz. 

cccccc

Kafka''nin yazdigi romanlari okur gibi yasiyoruz. 

Kafka''nin roman kahramani Joseph K. bir sabah uyandiginda evine gelen iki adam onun ''suçlandigini'' söyler ama neyle suçlandigini söylemez. Joseph K.''nin suçlulugu iki adamin onun ''suçlu'' oldugunu söylemesiyle baslar. K.''nin neyle suçlandigi belli degildir ama daha da önemlisi onu kimin suçladigi da belli degildir. 

Bir zamanlar Avrupa''nin bütün simyacilarinin onlara ayrilmis bir mahalledeki birbirine yapismis basik evlerde kükürt dumanlari arasinda bakirdan altin yapmaya çalistigi, çaglar boyu her kösesinde bir baska efsanenin anlatildigi, cinayet hikâyeleriyle, öldürülmüs kadinlarla, basi kesilmis tüccarlarla, hortlaklarla dolu bir geçmise sahiplik eden dar sokaklarla, sivri kuleli evlerle örülmüs, kislari gri bir gökyüzüyle kapli, Ortaçag simyacilarinin kükürt kokularini hisseden bir sehirde, Çek bir babayla Alman Yahudisi bir anneden dogan Kafka, ne tam bir Çek, ne tam bir Alman, ne de tam bir Yahudi olarak, bütün hayati, dogdugu sehir gibi karmakarisik dar sokaklarla ve çikmazlarla dolu görerek yasadi. 

Kafka da, hemen hemen bütün yazarlar gibi, inanilmaz bir vicdan azabi çekiyordu, günlükleri, ''korkunç basagrilari'' ve ''yeteri kadar yazamamanin'' acilariyla doludur; hiçbir yazarin günlügünde bu kadar çok ''basagrisi''ndan yakinildigini, ''Yazmak için isten izin aldim ama üç günü yine yazamadan geçirdim'' türünden sikayetlerin bunca sik tekrarlandigini okumadigimi söyleyebilirim. 

Dagilmaya hazirlanan bir imparatorlugun neredeyse hiç kimsenin sahip olmadigi bir sehrinde, bunaltici bir bürokrasinin çarklari arasinda bir memur olarak yasamak zorunda kalan, kadinlarla iliskilerini tam düzenleyemeyen, genelevin önünden ''sevgilinin evinin önünden'' geçer gibi geçen, çok genç yasta verem olan bir yazarin bize biraktigi romanlar, bugün Kafka''nin yasadigi yerlerden çok uzakta, o kültüre çok yabanci bir kültürde yasayan bizlerin hayatlarini anlatiyor. Kafka iki büyük romaninda, Sato ile Dava''da kahramanina ayni adi vermisti: Joseph K. 

Soyadi bile olmayan bir adam. 

Soyadi hemen silinecek gibi gözüken tek harfe indirilmis bir adam. 

Bu tek harfli insanin maceralarinin anlatildigi romanlari birer karabasana çeviren, bence, bu romanlarda gizli iktidarin sahiplerinin asla görülmemesi, onlara asla ulasilamamasiydi. 

Sato romaninda, bütün köyün efendisi olan kisilerin oturdugu satoya ulasmak, o insanlari görmek mümkün degildir, yalnizca onlari temsilen köyde dolasip herkesi gözetleyen iki adam vardir. Dava''da ise, K.''yi suçlayan asil otorite hiç gözükmez, burada da o otorite adina suçlulugu ilan eden iki kisi görülür. 

Otoritenin ve gücün kaynagi görünmezligindedir. 

Iktidarin gerçek sahipleri her türlü insani iliskinin, elestirinin, suçlanmanin disindadir; onlar istedikleri zaman adamlariyla size ulasabilir, sizi asagilayabilir, sizi suçlayabilir, sizi tutuklatabilir, hatta Dava romaninin sonunda oldugu gibi sizi öldürtebilir ama, siz onlara ulasamazsiniz. 

Iktidarin en korkunç biçimi görünmeyen insanlarin elinde olanidir. 

Onlar sizi görür, siz onlari göremezsiniz. 

Onlar hakkinda fikir yürütmeniz, onlara direnmeniz, baskaldirmaniz mümkün degildir. 

Aynen bizim hayatimizda oldugu gibi, asil efendiler derinlere saklidir, ortada gözükenler onlarin temsilcileri, usaklari, emirberleri, cellatlaridir. Hayatimizi keskin bir inançla korkunç bir süpheciligin üzerine kurmamizdir bu karabasani vareden sir; satodakilerin kudretine, söylediklerinin dogruluguna körü körüne inanir, kendimizden ve satonun disindaki herkesten dehsetle kuskulaniriz. Suçlular görünmeyen iktidar sahipleri tarafindan suçlandiklari için suçludur; suçlu olmak için suçlanmak yeter. 

Birisi suçlandiginda onun suçluluguna hep birlikte inaniriz, hatta suçlanan bile, hiçbir suçu olmadigini düsünse de sonunda kendinden kuskuya düser, agir agir kendi suçluluguna inanir, sonunda bu karabasandan kurtulmak için kendi ölümüne yürür; görünmeyen bir iktidarin tutsakligini kabul edenler için yok olmak belki de tek kurtulus yoludur. 

Iktidarin ortada dolasan adamlari satodakilerin kudretini ve bizim korkumuzu besleyerek büyütür. 

Bizi yok eden satonun gücü degildir; bizi yok eden kendi güçsüzlügümüzdür. 

Hayatimizin üzerine kapanan baskiyi öylesine korkunç kilan, bir karabasana çeviren, bütün kurtulus yollarini kapatan, bizi çaresiz birakan bizim o baskinin bir parçasi olmakta gösterdigimiz ölümcül basegistir. 

Biri suçlandiginda digerlerinin onun suçlu olduguna hemen inanmasidir. Hatta, kendilerine bir suçlu gösterilmesini istekle beklemeleridir. Biri suçlandiginda bütün dostlari, tanidiklari, hatta Dava romaninda oldugu gibi akrabalari hemen suçlayanlarin yaninda yer alir, bu suçlamadan kendilerine bir zarar gelip gelmeyecegini hesap ederler. 

Suçlanan terkedilir. 

Kimse korumaz onu. 

Kimse sahip çikmaz. 

Esas suçlularin satodakiler olabilecegini aklimiza bile getirmeyiz. 

Soyadlarimiz hemen silinebilecek bir tek harfe indirgenmistir. 

Herhangi bir sabah bizim de kapimiz çalinabilir, neyle suçlandigimiz söylenmeden biz de suçlanabiliriz ve biz, bizi suçlayanlara yaranmaya, yok olurken bile onlara kendimizi begendirmeye ugrasiriz. 

Bir suçlu bulunduguna, suçluyu saptama hakkinin da yalnizca iktidarin görünmeyen sahiplerine ait olduguna olan inancimizdir bizi güçsüz kilan. 

Her sabah yeni bir suçluyla uyaniyoruz. 

Her sabah bir baska Joseph K.''nin resimleri var gazetelerde. 

Satonun bulundugu tepenin eteklerindeki küçük köyde yasiyoruz, iktidarin asil sahipleri asla gözükmüyor, her sabah kapimizin altindan bir suçlunun resmi atiliyor ve onlarin suçlu olduguna, suçlu olduklari söylendigi için inaniyoruz. 

Evlerimizden suçluyu parçalamak için çikiyoruz, birbirimize ''Suçluymus'' diyoruz, suçlunun öldürülmesini istiyoruz, efendilerimize suçlunun öldürülmesi için yalvariyoruz. 

Çünkü, suçlular suçlandiklari için suçludur. 

Çünkü biz kaybolmakta olan bir memleketin sahipsiz sehirlerinde eski simyacilarin kükürt kokularini içimize çekerek yasiyor, görünmeyen efendilerin karanlik gücüne boyun egiyoruz. 

Çünkü biz Joseph K.''yiz. 

Soyadlarimiz artik tek bir harf. 

Silinmeye hazir bekliyor.', 'Her sabah bir baska Joseph K.''nin resimleri var gazetelerde.  Satonun bulundugu tepenin eteklerindeki küçük köyde yasiyoruz,  iktidarin asil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altan']::text[], 8.5, '{"poet":"Ahmet Altan","poet_slug":"ahmet-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Gökyüzümsün...', 'sen-benim-gokyuzumsun-bulent-ozcan-blqho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen benim gökyüzümsün, 

Göz açıp gördüğümsün.

Tutkumsun vazgeçilmez, 

Aşkım, özgürlüğümsün...

Usumsun, erincimsin, 

Yaşama sevincimsin...

Sesim, soluğum, sevdam, 

Yazılmadık şiirimsin...

Sen bensin benden öte, 

Canımsın tenden öte...

Şu dünyada ne varsa, 

Yok inan senden öte...

Sen benim gökyüzümsün, 

Göz açıp gördüğümsün.

Tutkumsun vazgeçilmez, 

Aşkım, özgürlüğümsün...', 'Sen benim gökyüzümsün,  Göz açıp gördüğümsün. Tutkumsun vazgeçilmez,  Aşkım, özgürlüğümsün... Usumsun, erincimsin,  Yaşama sevincimsin... Se...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-benim-gokyuzumsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kendini İyi Bilir', 'o-kendini-i-yi-bilir-bulent-ozcan-632jg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hem dinsiz hem kılar namaz

İt oğlu it puşt yobaz

Kendi tilki el oğlu kaz

O kendini iyi bilir.

Yağ yakmaktır tek sanatı

Sözde sever pek sanatı

Kullanır köpek sanatı

O kendini iyi bilir.

Soysuz herif laf anlamaz

Hemen her telden çalar saz

Tükür yüzüne utanmaz

O kendini iyi bilir.

Dil dökmede üstüne yok

Asalak ya hep karnı tok

Ulan deyyus bok oğlu bok

O kendini iyi bilir.

        8 Ekim 1992, Gaziantep', 'Hem dinsiz hem kılar namaz İt oğlu it puşt yobaz Kendi tilki el oğlu kaz O kendini iyi bilir. Yağ yakmaktır tek sanatı Sözde sever pek sanat...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-kendini-iyi-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözüm Meclisten İçeri', 'sozum-meclisten-i-ceri-bulent-ozcan-jii8n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey siz, peşkeş çekilmiş şu zamanın piçleri, 

Ne çabuk unuttunuz sizden öncekileri! ..

              17 Ekim 1991, Gaziantep', 'Ey siz, peşkeş çekilmiş şu zamanın piçleri,  Ne çabuk unuttunuz sizden öncekileri! ..               17 Ekim 1991, Gaziantep...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sozum-meclisten-iceri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Sonsuzluğu...', 'siir-sonsuzlugu-bulent-ozcan-fub2z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanların ötesinde bir zaman

düşleri zamana

zamanı şiire kuruyorum

Şiir sonsuz ey ozan

Yazamazsın! ..

Yazılmayanın şiirini yazmalı

yıldızlar ayakta

yapraklar uykudayken daha...

Şiiri zamana

zamanı rüyaya sığdıramazsın

Şiir sonsuz ey ozan

bir fındık kabuğunda

gökyüzü düşün

Gökyüzünü tutamazsın! ..

        Kasım 1991, Gaziantep', 'Zamanların ötesinde bir zaman düşleri zamana zamanı şiire kuruyorum Şiir sonsuz ey ozan Yazamazsın! .. Yazılmayanın şiirini yazmalı yıldızla...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siir-sonsuzlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Günlerdir', 'son-gunlerdir-sair-hayalperest-q7xqm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son günlerdir çok yalnızım.

Acılar, dertler bitmez oldu, 

Hepsi üstüme bir çığ gibi düştü.

Ne arayanım var ne de soranım, 

Kimseler uğramaz oldu.

Yapayalnız kaldım karanlık sokaklarda, 

Dümeni kırılmış bir gemi misali.

Dalgalar arasında boğuşup, 

Bir o yana bir bu yana savruluyorum,', 'Son günlerdir çok yalnızım. Acılar, dertler bitmez oldu,  Hepsi üstüme bir çığ gibi düştü. Ne arayanım var ne de soranım,  Kimseler uğramaz ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hayalperest']::text[], 8.5, '{"poet":"Şair Hayalperest","poet_slug":"sair-hayalperest","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/son-gunlerdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsizlik', 'sebepsizlik-aysun-elagoz-382x1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sebepsizdi gidişin.......

Veda bile etmedin, 

Yağmur hüznü bıraktın yüreğime, 

Yağmurları severim ben.....

Ardına bakmadın, 

Ardından bakmadım giderken..

Sebepsizdi gidişin

Tıpkı gelişin gibi........', 'Sebepsizdi gidişin....... Veda bile etmedin,  Yağmur hüznü bıraktın yüreğime,  Yağmurları severim ben..... Ardına bakmadın,  Ardından bakmad...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sebepsizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Tiryakisi', 'sevginin-tiryakisi-cemal-kamil-aliimamoglu-qjnzc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizliğin duvarı okadar yüksek ki aşamıyorum.

 Sevginin tiryakisiyim sensiz yapamıyorum.

 Sevginle bütünleşen ruhum yanlız.

 Sensiz olduğum günlerin geceleri, sensizliğinle boğuşuyorum.

 Sen bütün alışkanlıkların bende bıraktığı bir izsin.

  (10.07.1993 Ankara)', 'Sensizliğin duvarı okadar yüksek ki aşamıyorum.  Sevginin tiryakisiyim sensiz yapamıyorum.  Sevginle bütünleşen ruhum yanlız.  Sensiz olduğu...', ARRAY['Türk Edebiyatı','Şiir','Cemal Kamil Aliimamoğlu']::text[], 8.5, '{"poet":"Cemal Kamil Aliimamoğlu","poet_slug":"cemal-kamil-aliimamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevginin-tiryakisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökteki Sevda', 'gokteki-sevda-cem-veysel-gul-hcie1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göğü kucaklayıp getirmek isterim, 

Kucak kucak sevgi, 

Samanyolu çokluğunda gülücük, 

Birde seni seven ben.

Her gece tepende, 

Işık saçan ben, 

Getirmek isterim sana.

Bir hilal, bir dolunay, 

Yada sabaha karşı çobanyılızı, 

Bilemedin küçük bir yıldız, 

Gökyüzünden bir demet papatya gibi, 

Tan ağarmadan henüz, 

Bir demet yıldızla geleceğim.

Sana yüreğimi vermeye, 

Yani sevdamı, dostluğumu, 

Kardeşliğimi getireceğim. 

  Cem Veysel Gül

(İst.03.08.2001.s: 10: 25)', 'Göğü kucaklayıp getirmek isterim,  Kucak kucak sevgi,  Samanyolu çokluğunda gülücük,  Birde seni seven ben. Her gece tepende,  Işık saçan be...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gokteki-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşma', 'bulusma-sabahattin-ozkan-s7ygv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günahın eli sıcak, pişmanlık unutkan, acımasız

İpi kopmuş tutkularımın, boğuk soluyuşlara

Katlanmak mı? Hangi yürekle, neye..  hem neden? 

Huzur damlacıklarıma karıncalar göz dikmişken! 

Bahar dallarından maviliklere baksam, dalsam

Bir göçmen kuş çığlığı duysam da uyansam

Avcumda güneşin gülü gözümde mercan

Bir mercanda yansam, bir goncada: Kansam! 

Yelkeninde nakış olsam, miniminnâ bir leke

Alsa götürse beni yellere verip bir tekne

Ne başımda ağırlıklar kalır ne yüreğimde kül

Dönüş kaygusundan âzatlı, yaşamaya doyumsuz! 

Yorulmak ne, bilmez ufuklara bağır açan

Her masal câna gelir, düşler konar omzuna 

Bir sofrada buluşur Mecnûn, Ferhâd ve Cem

Leylâ azık açar, Şîrin ballanır, can kadehlenir! ..', 'Günahın eli sıcak, pişmanlık unutkan, acımasız İpi kopmuş tutkularımın, boğuk soluyuşlara Katlanmak mı? Hangi yürekle, neye..  hem neden?  H...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Özkan']::text[], 8.5, '{"poet":"Sabahattin Özkan","poet_slug":"sabahattin-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulusma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Masalı', 'zaman-masali-sabahattin-ozkan-orkdt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dost, bir yoldaşım bildim zamanı

Yanımca yürüyen kıldım zamanı

Onsuz olunamaz diye hiçbir an

Beleyip sırtıma aldım zamanı

Bunda yekpârelik olmaz, dediler

Yıllara aylara böldüm zamanı

Tüneline dalıp “Bezm-i Elest”in

“Be-lâ”  bahçesinden yoldum zamanı

Bir adımda geçip gittim yanından

Vardığım mekânda buldum zamanı

Bir gün leke sürdü de gençliğime

Gönül defterimden sildim zamanı

Dervişlere uydum attım abâyı

Pîr kapısı diye çaldım zamanı

Vuslat meleğiyle buluşmak için

Dün O’na haberci saldım zamanı

Kırklar’a karışmak şimdi muradım

Hızır’a bırakıp geldim zamanı', 'Bir dost, bir yoldaşım bildim zamanı Yanımca yürüyen kıldım zamanı Onsuz olunamaz diye hiçbir an Beleyip sırtıma aldım zamanı Bunda yekpârel...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Özkan']::text[], 8.5, '{"poet":"Sabahattin Özkan","poet_slug":"sabahattin-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zaman-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Adında Bir Kadın', 'hayat-adinda-bir-kadin-onder-karadag-w0ruk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir orospunun çığlıksı gülüşümüydü 

ürperten içimi... 

Yoksa, kelepçesi mi bir  güvercinin? .

I.

Kavuşuyoruz  ya  bir Han akşamına

soframızda şiir  mısır ve tütün

ve de ay ışığı; kırpıştıkça gözlerinde

yıldızlar açar tarlalarım.

şımardıkça gülüşünde sesin

mavileşir gökyüzü...

öpmek   istedikçe gözlerini 

kekeler  durur kirpiklerim

ellerimi de  bir  efkar  basar 

utanır en ‘şair yerim’

alır götürür seni gece...

...

II.

Bir Han akşamında; 

soframda şiir, mısır ve tütün

bir de ayrılık...

değemezken   sana ellerim

kırk yıl öncesi çarpar hala

ve de  kekeler durur  kalbim.

dudaklarımda  bir kül kokusu

yüreğimde  yakısı bir  közün.

III.

Şimdi yalnızlık mevsiminde gün 

hep arka sokak, hep eski sabah

özlemler kahırlı, sevmeler illegal 

tutkulu aşklarda hep körebe

gizemli ve kahpe (!) ... 

Hayat adında bir kadın.', 'Bir orospunun çığlıksı gülüşümüydü  ürperten içimi...  Yoksa, kelepçesi mi bir  güvercinin? . I. Kavuşuyoruz  ya  bir Han akşamına soframızd...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hayat-adinda-bir-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Bir Ege Meltemi Tenin', 'mavi-bir-ege-meltemi-tenin-onder-karadag-dowmx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mavi bir Ege meltemi

tenin, okşar ellerimi

öpüşlerin, bir gül ömrü 

tadı, dudağımda şimdi... 

gecikme  telaşında, aşklar

her mevsim, çiçek 

gözlerinde, Ay kavuşumu

yüzünde, esrik gölgesi...

özlemin, şarap kıvamında

tadında nice  yıllar,  gizli 

her  bekleyiş, her akşam üstü 

bir dağbaşı yalnızlığı ateşi şimdi! ...', 'Mavi bir Ege meltemi tenin, okşar ellerimi öpüşlerin, bir gül ömrü  tadı, dudağımda şimdi...  gecikme  telaşında, aşklar her mevsim, çiçek  ...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mavi-bir-ege-meltemi-tenin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hanno', 'hanno-oguz-gemalmaz-ljvjx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Orada tenha olarak yaşadım''

                   Kemalettin Tuğcu

                                                                     

Bir çığ düştü

Uçurumu inleterek düştü bir çığ

Islattı kar, içi miflonlu bir çift postalı

Önce onlar geldi aklıma

Sonra odanda yalnızlığın adımları

Senin gölgenin ağırlığı

Dörtyol-Bahçeli hattı

Çok zaman binemediğin otobüsler

Akan hayatlar

Sana değinmeden yanıbaşından geçen

Sen kimselerin bilemeyeceği sırlarını taşıdın

Yakışıyordu o sırlar yüzüne

Bütün öksüzler gözyaşı döksünler

Hanno öldü

Ölümüne alışmak

Seni sevmekten zor

Kederliyim annesini arayan çocuk gibi

Henüz hazır olmasam da kedere

Evet Hanno, gördüğün gibi

Öksüz bıraktın beni de

Biliyorum seni ıslatan yağmurlar

Şimdi ruhunu yıkamaktadır

Teninden bir yağmur damlıyor üzerime

Gözyaşım sanıyor herkes

Belki de yaşanacak bir anının yok olmasınadır gözyaşları

Yaşam, anıların biriktirilmesidir çünkü

                                                     13.Temmuz.2001 / ANKARA', '''Orada tenha olarak yaşadım''                    Kemalettin Tuğcu                                                                       Bir ç...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Gemalmaz']::text[], 8.5, '{"poet":"Oğuz Gemalmaz","poet_slug":"oguz-gemalmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hanno-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek ve Düş', 'gercek-ve-dus-ozlem-malkara-qqx8i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gerçeklerimin düşleri

düşlerimin gerçekleri vardı

rüyalarımın kanatları

benimse kollarım vardı....

güllerin dikenleri olduğunu zannederdim

hayatın acılarını bilmezken 

ben ne mutluydum çocukken....

aşk uzaklarda bir kent 

keder bilmediğim şehirlerde bir semtti

kahkaham uğrak meyhanem

gözlerim çorak topraklardı

hüzün beni sarmalamamışken

ben ne mutluydum çocukken...', 'gerçeklerimin düşleri düşlerimin gerçekleri vardı rüyalarımın kanatları benimse kollarım vardı.... güllerin dikenleri olduğunu zannederdim h...', ARRAY['Türk Edebiyatı','Şiir','Özlem Malkara']::text[], 8.5, '{"poet":"Özlem Malkara","poet_slug":"ozlem-malkara","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gercek-ve-dus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çapraşık...', 'caprasik-ozlem-malkara-va0v0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kor bir ateş gibi düştü bedenime korkular

alev aldı köşede kalmış umutlar

gökten düşen yalnız damlalar

benim çapraşık dünyam güz akşamları kımıldar...

beni yalnızlığım sarıp sarmalar

içten çökertti masum yalanlar

kinaye bakışlar yüreğimi  yaralar

benim çapraşık dünyam güz akşamları kımıldar..

masalarda sönmüş sefalar

bana yoktur halim soranlar

göçüp gitti ümitsizler kuşlar

benim çapraşık dünyam güz akşamları kımıldar...', 'kor bir ateş gibi düştü bedenime korkular alev aldı köşede kalmış umutlar gökten düşen yalnız damlalar benim çapraşık dünyam güz akşamları k...', ARRAY['Türk Edebiyatı','Şiir','Özlem Malkara']::text[], 8.5, '{"poet":"Özlem Malkara","poet_slug":"ozlem-malkara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/caprasik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
