INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses Veremiyoruz Sesverin', 'ses-veremiyoruz-sesverin-yasemin-yarar-ksy1d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir cesedim

Ruhum kolayca sıyrılıp gitti 

Beton yıkıntılar arasından 

Ben nefes bile alamadım

Etim kemiğim ciğerim ezildi 

Yerim göğüm ağrı oldu

Sesimi duyuramadım. 

Yaşamak ne kadar güzeldi oysa

Kokuştum 

Etim kemiğim dağıldı. 

Ellerimizle yaptığımız makinalar

Aldı savurdu beni çukurlara

Kireçle örtüldüm sonra 

Çiçeklerle selvilerle donatılmıyormuş gömütler

Ömrümüz çimento demir kıymetinde değilmiş

Betonlar, makinalar, karteller, tröstler 

Sürdürecekmiş bu güzel yaşamı

Bizler nasıl olsa ceset kalacakmışız.

Duyan gören ne varsa uzak kalacakmış nefes almaktan

Güneşli bir eylül sabahı 

kurtlanmış enkaz cesetleri 

çiçek açacak baharda 

güzel düşünmek lazım.

Sosyalizm çöktü diyorlar peki depremde çöken neydi.', 'Ben bir cesedim Ruhum kolayca sıyrılıp gitti  Beton yıkıntılar arasından  Ben nefes bile alamadım Etim kemiğim ciğerim ezildi  Yerim göğüm a...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ses-veremiyoruz-sesverin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lut Sodom Gomore17Ağustos99', 'lut-sodom-gomore17agustos99-yasemin-yarar-z09nd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yerin yedi kat derininden cehennem yarıldı çıktı: sen hep 

miraçta turdaydın, sana erişemedi (biz Bodrumda Lut ve 

Sodom-Gomere ileydik.) . Ezilenlerin acının şiddeti nedeniyle 

ilk kez cennete gideceği gündü…', 'Yerin yedi kat derininden cehennem yarıldı çıktı: sen hep  miraçta turdaydın, sana erişemedi (biz Bodrumda Lut ve  Sodom-Gomere ileydik.) . ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/lut-sodom-gomore17agustos99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan kölenin soyluluğudur  F.Nietszche', 'i-syan-kolenin-soylulugudur-f-nietszche-yasemin-yarar-ne1j7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yuvarlak hayatta herşey

Yuvarlak sonsuzluk yuvarlak boşluk

Ama asilik dikine vurmak bize göre..', 'Yuvarlak hayatta herşey Yuvarlak sonsuzluk yuvarlak boşluk Ama asilik dikine vurmak bize göre.....', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/isyan-kolenin-soylulugudur-f-nietszche-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim', 'ellerim-yasemin-yarar-1itwt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '31/12/1999: 

ellerim yürürken boşlukta sallanan

nereye koyacağımı bilemediğim ellerim

tesbihe anahtarlığa sarılan 

iki olmuş ellerim 

bir tane iki tane üç tane..

binlercesi niye olmaz diye düşünen ellerim', '31/12/1999:  ellerim yürürken boşlukta sallanan nereye koyacağımı bilemediğim ellerim tesbihe anahtarlığa sarılan  iki olmuş ellerim  bir ta...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ellerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abim', 'abim-yasemin-yarar-s38nf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umudu kaybetmemek için 

Ümit burnunu keşfetmek için 

Bir hayal gemisi korsanı olmak gerek

Sen mercidabığı görmüşsün Yavuz sultan! (abim Yavuz’a ithaf olunur.)

Abim bir deryaydı: Kaptanı derya; ben içinde bir lahza 

mutlu bir lahza..', 'Umudu kaybetmemek için  Ümit burnunu keşfetmek için  Bir hayal gemisi korsanı olmak gerek Sen mercidabığı görmüşsün Yavuz sultan! (abim Yavu...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/abim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoka Kaç Var', 'yoka-kac-var-yasemin-yarar-89uqd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çırpınmam

Kıvranmam

Bir çarpının kolları

Son nokta bu

Yakında buhar olacak herşey 

Kıyamet midir yokoluş mudur bilmem 

Ama ben yok oluyorum 

Kelimeler siren sesleriyle dolaşıyor beyninimde

Siliniyor her şey bahçeler sesler sular', 'Çırpınmam Kıvranmam Bir çarpının kolları Son nokta bu Yakında buhar olacak herşey  Kıyamet midir yokoluş mudur bilmem  Ama ben yok oluyorum ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yoka-kac-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbrahim Sarıaltın', 'i-brahim-sarialtin-yasemin-yarar-ks6ki', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ibrahim Sarıaltın kızıl ötesi, mor ötesi ışık hızında değdin ya gençliğime kraterler gölet oldu gözlerimde. Çarçabuk vardın oraya, çarçabuk varmak istiyorum yanına. Ibrahim bu en güzel kelime putların, tabuların devriliş sesi gibi. Yanında küçük oldum, yanında dinleyen oldum, bilmeyen oldum. Su sesini dinlemek, yıldızı güneşi görmek oldum. Aksayan atımlarım hızlanırdı hep ama o hıza varmak haddime değildi. Zaman akıyor di’li, miş’li geçmişler arasında bir ışık gibi sızmak en güzeli..

Gençlik imparatorluğumuzun şövalyelerinden birini kaybetmişiz; // acıyorsam sana anam avradım olsun ama aşk olsun sana çocuk aşk olsun! ! ! //.

Omuz omuza olduğumuz arkadaşların her biri tek tek giderken dik yürünmüyor. 

86 yazında sınavı kazandığını söylemen en güzel haberdi; 30.1.2000’de en kötü haberi verdin; 

İbrahim iki kelime; yer kaygan, zaman kaypak İbrahimsizde yaparlar elbet!', 'Ibrahim Sarıaltın kızıl ötesi, mor ötesi ışık hızında değdin ya gençliğime kraterler gölet oldu gözlerimde. Çarçabuk vardın oraya, çarçabuk ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ibrahim-sarialtin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Doğmazmı', 'gunes-dogmazmi-muhammet-karaca-6aau3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmezdim güneşin doğmadığı an yaşayacağımı 

Hayatımın devam edip nefes alacağımı, 

Yaşamak ne olduğunu güneşin batışında öğrendim 

Doğuşunu umut etmeden, yaşamayı güneşsiz 

Bazen güneşin doğduğunu sanıyor pencereye koşuyorum

Çıldırıyorum güneşi göremediğim an pencerede, 

Oysa her taraf aydınlık her taraf cıvıl cıvıl 

Neden ben mutsuz, kapanıyorum odama doğacak güneşi bekliyorum

Güneş doğmayacak mı, diye anlamsız soru geliyor aklıma 

Peki neden ben doğan güneşe çıkamıyorum haykırıyorum 

O anı hatırlamak istemiyorum dışarı çıkmaya yelteniyorum 

Utanıyorum yaptıklarımdan odama koşuyorum 

Tiksiniyorum kendimden, kızıyorum kendime

Oysa sana hiç güneş doğmuyor kıyamet gelmeden, 

Kıyametin koptu aşkım kahrediyorum sensiz yaşanan günlere

İşte AŞKIM benim kıyametim sendin,  yanına gelene dek 

				Arttık güneş haram bana, doğmasın pencereme...

28/11/2000 23: 10', 'Bilmezdim güneşin doğmadığı an yaşayacağımı  Hayatımın devam edip nefes alacağımı,  Yaşamak ne olduğunu güneşin batışında öğrendim  Doğuşunu...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Karaca']::text[], 8.5, '{"poet":"Muhammet Karaca","poet_slug":"muhammet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gunes-dogmazmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavuz Yarar''a(Abime)', 'yavuz-yarar-a-abime-yasemin-yarar-9j7ov', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '26.05.00

yavuzcuğum ömür bitince cendere düşüyor kırılıyor. Balık özgür bir son nefes alıyor. 

Herşey zordu. Seni sevdiğimi söylemeyi öğrenemedim. Herşey çabuk bitti. Işte şimdi tek başına öksürüyorsun tek başına şiş eklemlerine sızısına terine kokusuna dayanıyorsun. Buluşucaz ama hastane eşiklerinde toprakta nefeste terde tende güneşte. 

Hiç düşmedim sendelemedim arkamdaydın. 

Şimdi düşüyor muyum sendeleliyor muyum bilmiyorum. Sen konuşuyorsun gibi söylüyorum dinliyorum kendime.

Dayak yedim güve düştü adımlarıma. 

Dondurma nasıl yenilir, yumurta nasıl pişirilir nasıl kızartılır sucuk neymiş kola ne kadar soğukmuş baktım.

Çocuklar nasıl güler umarsız kollarım sıkıntımı saklamak için başımdayken seyrettim. 

Burnum kanadı yastığıma dayandım. Taş kırdım ellerim şişti. Çapada çavuşlara çıraklık yaptım, kardeşimin pamuk hattına yardım ettim. 

Üç dört yıl kolu paçaları kısalmış pantolon ceket giydim. Başkalarının düzgünce ceketleriyle ankaraya tübitağa gittim. Yılda bir dayak yedim kamburum çıktı dal gibi boyum kısaldı. Ve ilk gençlik yıllarımda arkadaş sıcaklığı çoğu şeyi unutturdu. Beraber yürüyelim dedik. Yürürken bizi aykırı kılan şeylerin sistematize çıkarcıların karşısındaydık. 

Sonra sınavlarla ekmek diledik. Olmadı genel müdürlere el bağladık. Sistem bir ağ oldu. 

Ağda uyuyorlar ama biz uyumuyoruz ağda bir delik bekliyoruz. I

şten işe tekliğe kimsesizliğe arkadaşsızlığa yürüdük. Bükük çocukluğumuzu derleyip kaldırdık zaten hep derli topluydu ve çocuğumuz oldu. Hiç dövmedik. Hep gülsün diye hep gülüyor ya o birşeyler değişecek diyoruz beklemek gerek diyoruz. Hastalık yaşlılık ilgisizlik parasızlık size rağmen bekliyeceğiz.', '26.05.00 yavuzcuğum ömür bitince cendere düşüyor kırılıyor. Balık özgür bir son nefes alıyor.  Herşey zordu. Seni sevdiğimi söylemeyi öğrene...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yavuz-yarar-a-abime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Geceler', 'karanlik-geceler-muhammet-karaca-vjma2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '27/11/2000  06: 10 

Bilmiyorum bazen korku salıyor yüreğim, 

Bazen kaldıramaz oluyor bu sessizliği, 

İçimde, ürkek ceylan ürpertileri, fısıltıları dinliyorum

Derinlerden geliyor  çığlık sesleri ve anlıyorum yalnız değilim 

					Bu karalıkta, buhranda 

Bir gün kurtulacağım diye ümit ediyorum, bazende gözlerim doluyor, 

Bazense hıçkırarak ağlıyorum, isyanım düğümleniyor karanlık sokaklarda 

Haykırmaya korkuyorum, ya ürkek ceylan ürperirde giderse diye 

Aslında benim asıl korkum zaman içinde kayboluşum

					Bir gün unutulacağım korkusu.

Bazen karanlık geceler bana unutturuyor bu yanlızlığı, 

Ben varım dercesine sadık ve dostça, hiç yalnız bırakmamacasına 

Ama bazen oda unutuyor beni karanlık sokaklardan çekiliyor 

Yanlızlıklar arasından, güneşi getiriyor ben bu yanlızlığı paylaşamam 	

					Dermişçesine  insafsızca ve acımasızca 

Umut ediyorum güneş elbette benim içinde doğacak diye 

Umutlarım direncini kaybediyor yeni aydınlanan sokak başlarında

Gören pis dilenci ayyaş diyor, içimdeki fırtınalardan  habersiz 

Daha sokak başında umutlarımı doğan güneşe inat karanlık kuytulara gömüyorum 

					Veda ediyorum güneşe, umutlara uykuya dalıyorum 

27/11/2000  06: 10', '27/11/2000  06: 10  Bilmiyorum bazen korku salıyor yüreğim,  Bazen kaldıramaz oluyor bu sessizliği,  İçimde, ürkek ceylan ürpertileri, fısıl...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Karaca']::text[], 8.5, '{"poet":"Muhammet Karaca","poet_slug":"muhammet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/karanlik-geceler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırpık Kirpi', 'kirpik-kirpi-yasemin-yarar-bnh6j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saçımı kırptım

Bakışımı

Yürüyüşümü 

Gülüşümü kırptım

Gözümün feri söndü

Fenerin yönünü ve pusulamı kaybettim

Öz suyumu budadım

Arkadaşlarım

Dostlarım kalmadı 

Kırpık bir kirpi tekliğiyle 

Korkunun soğuk ve karanlık inindeyim. 

Ibreler sirenler kalk ve yürüde 

Ve sırtındaki bohemlik kamburunu doğrult.

Yasemin yarar', 'Saçımı kırptım Bakışımı Yürüyüşümü  Gülüşümü kırptım Gözümün feri söndü Fenerin yönünü ve pusulamı kaybettim Öz suyumu budadım Arkadaşlarım ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirpik-kirpi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
